CREATE TRIGGER [dbo].[tr_ins_SRM_CLIENT_FILTER_VIEW_ATTRIBUTES] on [dbo].[SRM_CLIENT_FILTER_VIEW_ATTRIBUTES]
for insert
as

declare @SeqId BIGINT


SELECT @SeqId = SEQ_ID FROM INSERTED

UPDATE SRM_CLIENT_FILTER_VIEW_ATTRIBUTES SET SHOW_FIELD='Y',ON_SCREEN_SEARCH_FEILD='N',SEARCH_SCREEN_SEARCH_FEILD='N' WHERE SEQ_ID = @SeqId

UPDATE SRM_CLIENT_FILTER_VIEW_ATTRIBUTES SET ON_SCREEN_SEARCH_FEILD='Y', SEARCH_SCREEN_SEARCH_FEILD='Y' WHERE SEQ_ID = @SeqId AND STANDARD_ATTRIBUTE='Y'



	
;

