CREATE TRIGGER [dbo].[TRIGGER_SYNC_USER_ENTITY] ON [dbo].[SRM_USERS]
FOR INSERT,UPDATE
AS
	DECLARE @USER_ID BIGINT
	DECLARE @USER_DISPLAY_NAME NVARCHAR(100)
	DECLARE @USER_EMAIL NVARCHAR(512)
	DECLARE @USER_PASSWORD NVARCHAR(512)
	DECLARE @DELETED NVARCHAR(1)
	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT
	DECLARE @ACTIVE NVARCHAR(1)

	SELECT @USER_ID=i.SEQ_ID from inserted i;	
	SELECT @USER_DISPLAY_NAME=i.LOGIN_USER_NAME from inserted i;	
	SELECT @USER_EMAIL=i.LOGIN_EMAIL from inserted i;	
	SELECT @USER_PASSWORD=i.LOGIN_PASSWORD from inserted i;	
	SELECT @SRM_CLIENTS_SEQ_ID=i.SRM_CLIENTS_SEQ_ID from inserted i;
	SELECT @DELETED=i.DELETED from inserted i;
	SELECT @ACTIVE=i.ACTIVE from inserted i;
	
	
	EXEC DBO.[GET_SYNC_USER_ENTITY]		
		@USER_DISPLAY_NAME = @USER_DISPLAY_NAME,
		@USER_PASSWORD = @USER_PASSWORD,
		@USER_EMAIL = @USER_EMAIL,			
		@USER_ID = @USER_ID,
		@ACTIVE = @ACTIVE,
		@DELETED = @DELETED,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
					
		
	PRINT 'User Entity Sync-ed  -- After Insert Trigger.';

