CREATE FUNCTION dbo.AddWorkingDays
(
    @StartDate DATE,
    @DaysToAdd INT
)
RETURNS DATE
AS
BEGIN
    DECLARE @ResultDate DATE = @StartDate;
    DECLARE @Counter INT = 0;

    -- If adding negative days, handle backward logic
    IF @DaysToAdd >= 0
    BEGIN
        WHILE @Counter < @DaysToAdd
        BEGIN
            SET @ResultDate = DATEADD(DAY, 1, @ResultDate);
            IF DATENAME(WEEKDAY, @ResultDate) NOT IN ('Saturday', 'Sunday')
                SET @Counter += 1;
        END
    END
    ELSE
    BEGIN
        WHILE @Counter > @DaysToAdd
        BEGIN
            SET @ResultDate = DATEADD(DAY, -1, @ResultDate);
            IF DATENAME(WEEKDAY, @ResultDate) NOT IN ('Saturday', 'Sunday')
                SET @Counter -= 1;
        END
    END

    RETURN @ResultDate;
END
;




CREATE PROCEDURE [dbo].[BATF_SP_CUSTOMER_STATEMENT]
	-- Add the parameters for the stored procedure here
	@Account_Record_ID BIGINT, 
	@Association_Record_ID BIGINT, 
	@Job_ID BIGINT
AS
BEGIN
	
DECLARE @Crd_Seq_ID BIGINT = 0
DECLARE @Total_Credit MONEY = 0
DECLARE @Total_Allocated MONEY = 0
DECLARE @Slh_Seq_ID BIGINT = 0
DECLARE @Receipt_Seq_ID BIGINT = 0
DECLARE @Total_Receipt MONEY = 0
DECLARE @Receipt_Allocated MONEY = 0
DECLARE @SEQ_ID BIGINT
DECLARE @Type BIGINT = 6741

DECLARE cursor_name CURSOR
    FOR SELECT crd.SEQ_ID, SUM(CAST(ct.ATTRIBUTE_032 AS MONEY))
FROM [SRM-CustomEntities_145]..CUS_ENTITY_DATA crd WITH (NOLOCK)
INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES acc WITH (NOLOCK) ON acc.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1401452 AND acc.CUS_ENTITY_DATA_SEQ_ID = crd.SEQ_ID AND acc.ATTRIBUTE_DECIMAL = @Account_Record_ID
INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES crd_wo_inv WITH (NOLOCK) ON crd_wo_inv.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1401542 AND crd_wo_inv.CUS_ENTITY_DATA_SEQ_ID = crd.SEQ_ID AND crd_wo_inv.ATTRIBUTE_BOOLEAN = 'Y'
INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES ctp WITH (NOLOCK) ON ctp.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1401556 AND ctp.ATTRIBUTE_DECIMAL = crd.SEQ_ID
INNER JOIN [SRM-CustomEntities_145]..CUS_ENTITY_DATA ct WITH (NOLOCK) ON ct.SRM_CLIENT_ENTITIES_SEQ_ID = 54441 AND ct.SEQ_ID = ctp.CUS_ENTITY_DATA_SEQ_ID AND ct.DELETED = 'N'
INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES ctp_ass WITH (NOLOCK) ON ctp_ass.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1401619 AND ctp_ass.CUS_ENTITY_DATA_SEQ_ID = ct.SEQ_ID AND ctp_ass.ATTRIBUTE_DECIMAL = @Association_Record_ID
INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES ctp_IT WITH (NOLOCK) ON ctp_IT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1401588 AND ctp_IT.CUS_ENTITY_DATA_SEQ_ID = ct.SEQ_ID AND ctp_IT.ATTRIBUTE_DECIMAL = 0
WHERE crd.SRM_CLIENT_ENTITIES_SEQ_ID = 54440 AND crd.DELETED = 'N'
GROUP BY crd.SEQ_ID
HAVING SUM(CAST(ct.ATTRIBUTE_032 AS MONEY)) > 0

OPEN cursor_name;

FETCH NEXT FROM cursor_name INTO @Crd_Seq_ID, @Total_Credit

While @@FETCH_STATUS = 0
BEGIN

SELECT @Total_Allocated = SUM(CAST(ta.ATTRIBUTE_019 AS MONEY)), @Slh_Seq_ID = slh.SEQ_ID
FROM [SRM-CustomEntities_145]..CUS_ENTITY_DATA crd WITH (NOLOCK)
INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES slhp WITH (NOLOCK) ON slhp.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1411443 AND slhp.ATTRIBUTE_DECIMAL = crd.SEQ_ID
INNER JOIN [SRM-CustomEntities_145]..CUS_ENTITY_DATA slh WITH (NOLOCK) ON slh.SRM_CLIENT_ENTITIES_SEQ_ID = 54811 AND slh.SEQ_ID = slhp.CUS_ENTITY_DATA_SEQ_ID AND slh.DELETED = 'N'
--INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES slh_ass ON slh_ass.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1493095 AND slh_ass.CUS_ENTITY_DATA_SEQ_ID = slh.SEQ_ID and slh_ass.ATTRIBUTE_DECIMAL = @Association_Record_ID
INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES tap WITH (NOLOCK) ON tap.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1411473 AND tap.ATTRIBUTE_DECIMAL = slh.SEQ_ID
INNER JOIN [SRM-CustomEntities_145]..CUS_ENTITY_DATA ta WITH (NOLOCK) ON ta.SRM_CLIENT_ENTITIES_SEQ_ID = 54812 AND ta.SEQ_ID = tap.CUS_ENTITY_DATA_SEQ_ID AND ta.DELETED = 'N'
INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES ta_Ref WITH (NOLOCK) ON ta_ref.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1411470 AND ta_ref.CUS_ENTITY_DATA_SEQ_ID = ta.SEQ_ID AND ta_ref.ATTRIBUTE_DECIMAL = @Type
WHERE crd.SEQ_ID = @Crd_Seq_ID
GROUP BY slh.SEQ_ID

IF @Total_Allocated < @Total_Credit
BEGIN
--PRINT (@Total_Credit - @Total_Allocated)
INSERT INTO [SRM-CustomEntities_145]..CUS_ENTITY_DATA
        ( SRM_CLIENT_ENTITIES_SEQ_ID ,
          ATTRIBUTE_001 ,
          ATTRIBUTE_002 ,
          ATTRIBUTE_003 ,
          ATTRIBUTE_004 ,
          ATTRIBUTE_006 ,
          SRM_CLIENTS_SEQ_ID ,
          DATE_CREATED ,
          CREATED_BY,
		  DELETED
        )
VALUES  ( 
		69631,
		CAST(@Job_ID AS NVARCHAR(MAX)) + CAST(@Crd_Seq_ID AS NVARCHAR(max)),
		@Job_ID,
		@Account_Record_ID,
		@Crd_Seq_ID,
		@Total_Credit - @Total_Allocated,
		145,
		GETDATE(),
		'BATF',
		'N'
        )

		SET @SEQ_ID = SCOPE_IDENTITY()

		EXEC [SRM-DataPivot_145].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
		 -- Add the parameters for the stored procedure here
		 @SRM_CLIENT_ENTITIES_SEQ_ID = null,
		 @CUS_ENTITY_DATA_SEQ_ID = @SEQ_ID,
		 @SRM_CLIENTS_SEQ_ID = 145
END;

SET @Total_Allocated = 0
FETCH NEXT FROM cursor_name INTO @Crd_Seq_ID, @Total_Credit
END

CLOSE cursor_name
DEALLOCATE cursor_name


--Receipts
DECLARE cursor_receipt CURSOR
    FOR SELECT rt.SEQ_ID, CAST(rt.ATTRIBUTE_030 AS MONEY)
	FROM [SRM-CustomEntities_145]..CUS_ENTITY_DATA rt WITH (NOLOCK)
	INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES acc WITH (NOLOCK) ON acc.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1400360 AND acc.CUS_ENTITY_DATA_SEQ_ID = rt.SEQ_ID AND acc.ATTRIBUTE_DECIMAL = @Account_Record_ID
	INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES ass WITH (NOLOCK) ON ass.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1824762 AND ass.CUS_ENTITY_DATA_SEQ_ID = rt.SEQ_ID AND ass.ATTRIBUTE_DECIMAL = @Association_Record_ID
	INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES al WITH (NOLOCK) ON al.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1400415 AND al.CUS_ENTITY_DATA_SEQ_ID = rt.SEQ_ID AND al.ATTRIBUTE_BOOLEAN = 'Y'
	INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES am WITH (NOLOCK) ON am.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1400386 AND am.CUS_ENTITY_DATA_SEQ_ID = rt.SEQ_ID AND am.ATTRIBUTE_DECIMAL > 0
	WHERE rt.SRM_CLIENT_ENTITIES_SEQ_ID = 54415 AND rt.DELETED = 'N'

OPEN cursor_receipt;

FETCH NEXT FROM cursor_receipt INTO @Receipt_Seq_ID, @Total_Receipt

While @@FETCH_STATUS = 0
BEGIN

SELECT @Receipt_Allocated = SUM(CAST(rf.ATTRIBUTE_030 AS MONEY))
FROM [SRM-CustomEntities_145]..CUS_ENTITY_DATA rf WITH (NOLOCK)
INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES am WITH (NOLOCK) ON am.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1401084 AND am.CUS_ENTITY_DATA_SEQ_ID = rf.SEQ_ID AND am.ATTRIBUTE_DECIMAL > 0
INNER JOIN [SRM-DataPivot_145]..CUS_PIVOT_NON_UNIQUE_INDEXES rt WITH (NOLOCK) ON rt.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1401109 AND rt.CUS_ENTITY_DATA_SEQ_ID = rf.SEQ_ID AND rt.ATTRIBUTE_DECIMAL = @Receipt_Seq_ID
WHERE rf.SRM_CLIENT_ENTITIES_SEQ_ID = 54431 AND rf.DELETED = 'N'
GROUP BY rf.ATTRIBUTE_053

IF @Receipt_Allocated < @Total_Receipt
BEGIN
--PRINT (@Total_Receipt - @Receipt_Allocated)
INSERT INTO [SRM-CustomEntities_145]..CUS_ENTITY_DATA
        ( SRM_CLIENT_ENTITIES_SEQ_ID ,
          ATTRIBUTE_001 ,
          ATTRIBUTE_002 ,
          ATTRIBUTE_003 ,
          ATTRIBUTE_005 ,
          ATTRIBUTE_006 ,
          SRM_CLIENTS_SEQ_ID ,
          DATE_CREATED ,
          CREATED_BY,
		  DELETED
        )
VALUES  ( 
		69631,
		CAST(@Job_ID AS NVARCHAR(MAX)) + CAST(@Receipt_Seq_ID AS NVARCHAR(max)),
		@Job_ID,
		@Account_Record_ID,
		@Receipt_Seq_ID,
		@Total_Receipt - @Receipt_Allocated,
		145,
		GETDATE(),
		'BATF',
		'N'
        )

		SET @SEQ_ID = SCOPE_IDENTITY()

		EXEC [SRM-DataPivot_145].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
		 -- Add the parameters for the stored procedure here
		 @SRM_CLIENT_ENTITIES_SEQ_ID = null,
		 @CUS_ENTITY_DATA_SEQ_ID = @SEQ_ID,
		 @SRM_CLIENTS_SEQ_ID = 145
END;

SET @Receipt_Allocated = 0
SET @SEQ_ID = 0

FETCH NEXT FROM cursor_receipt INTO @Receipt_Seq_ID, @Total_Receipt
END

CLOSE cursor_receipt
DEALLOCATE cursor_receipt

END



;




-- =============================================
-- Author:		Faraz Ahmed
-- Create date: 2019-09-23
-- Description:	BIRA service usage part 1
-- =============================================
CREATE PROCEDURE [dbo].[BIRA_POPULATE_SERVICE_USAGE_ALL_ACCOUNTS]
	-- Add the parameters for the stored procedure here
	@CLIENT_ID INT = 143 -- CHANGE THIS UPON GO-LIVE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @ACCID AS BIGINT;
	DECLARE @QUERY AS NVARCHAR(1000);
	DECLARE @CLIENT_ENTITY_ID AS INT;
	DECLARE @CUSTOM_ENTITY_NAME AS NVARCHAR(100);
	DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS INT;

	SELECT TOP 1 @CLIENT_ID = SEQ_ID,@CUSTOM_ENTITY_NAME=INITIAL_CATALOG_CUSTOM_ENTITIES FROM [SRM_CLIENTS] WHERE 
	--CLIENT_NAME LIKE '%BIRA%' --AND IS_LIVE='Y' 
	SEQ_ID = @CLIENT_ID
	ORDER BY SEQ_ID DESC
	
    -- Insert statements for procedure here
	SELECT @CLIENT_ENTITY_ID=SEQ_ID FROM [SRM_CLIENT_ENTITIES] WHERE ENTITY_DISPLAY_NAME='SERVICE_USAGE' AND SRM_CLIENTS_SEQ_ID=@CLIENT_ID
	SELECT @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=SEQ_ID FROM [SRM_CLIENT_ENTITY_ATTRIBUTES] WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@CLIENT_ENTITY_ID AND ATTRIBUTE_DISPLAY_NAME='ACCOUNT'
		
	truncate table [SRM-CUSTOMENTITIES_143].dbo.CUS_ENTITY_DATA_SERVICE_USAGE_RESULT
	
	
print 'Start query: ' +CONVERT(nvarchar,getdate(),121);
DECLARE ER CURSOR FOR
  SELECT distinct USAGE.ATTRIBUTE_003
  FROM [SRM-CUSTOMENTITIES_143].dbo.CUS_ENTITY_DATA USAGE with(nolock)
  WHERE 
    USAGE.SEQ_ID IN (
  select distinct cus_entity_data_seq_id from [SRM-DataPivot_143]..CUS_PIVOT_NON_UNIQUE_INDEXES with(nolock)
  where SRM_CLIENT_ENTITIES_SEQ_ID=@CLIENT_ENTITY_ID and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID and attribute_decimal > 0
  )
  and isnull(USAGE.DELETED,'N') <> 'Y'
OPEN ER;

print 'End query: ' +CONVERT(nvarchar,getdate(),121);

FETCH NEXT FROM ER INTO @ACCID

WHILE @@FETCH_STATUS = 0
  BEGIN

	EXEC [dbo].[BIRA_POPULATE_SERVICE_USAGE_RESULT] @ACCID
	
 	FETCH NEXT FROM ER INTO @ACCID
  END;
  

CLOSE ER;

DEALLOCATE ER;    
	
END



;




-- =============================================
-- Author:		Faraz Ahmed
-- Create date: 2019-09-23
-- Description:	BIRA service usage part 2
-- =============================================
CREATE PROCEDURE [dbo].[BIRA_POPULATE_SERVICE_USAGE_RESULT]
	-- Add the parameters for the stored procedure here
	@ACCOUNT_RECORD_ID BIGINT = 0,
	@CLIENT_ID INT = 143 -- CHANGE THIS UPON GO-LIVE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	
--	declare @ACCOUNT_RECORD_ID  as bigint;
--	declare @CLIENT_ID as bigint;
--set @ACCOUNT_RECORD_ID=1466099
--set @CLIENT_ID = 143

	DECLARE @QUERY AS NVARCHAR(1000);
	DECLARE @CLIENT_ENTITY_ID AS INT;
	DECLARE @LOOKUP_CLIENT_ENTITY_ID AS INT;
	DECLARE @CUSTOM_ENTITY_NAME AS NVARCHAR(100);
	DECLARE @CUSTOM_PIVOT_NAME AS NVARCHAR(100);
	DECLARE @ACCOUNT_ATTRIBUTE_ID as bigint;
  
	
	SELECT TOP 1 @CLIENT_ID = SEQ_ID,@CUSTOM_ENTITY_NAME=INITIAL_CATALOG_CUSTOM_ENTITIES,@CUSTOM_PIVOT_NAME=INITIAL_CATALOG_DATA_PIVOT FROM [SRM_CLIENTS] WHERE 
	--CLIENT_NAME LIKE '%BIRA%' --AND IS_LIVE='Y' 
	SEQ_ID = @CLIENT_ID
	ORDER BY SEQ_ID DESC
	
    -- Insert statements for procedure here
	SELECT @CLIENT_ENTITY_ID=SEQ_ID FROM [SRM_CLIENT_ENTITIES] WHERE ENTITY_DISPLAY_NAME='SERVICE_USAGE' AND SRM_CLIENTS_SEQ_ID=@CLIENT_ID
	SELECT @LOOKUP_CLIENT_ENTITY_ID=SEQ_ID FROM [SRM_CLIENT_ENTITIES] WHERE ENTITY_DISPLAY_NAME='SERVICE_TYPE' AND SRM_CLIENTS_SEQ_ID=@CLIENT_ID
	
	print 'Start: '  +CONVERT(nvarchar,getdate(),121);
	SET @QUERY = 'TRUNCATE TABLE ['+@CUSTOM_ENTITY_NAME+'].dbo.CUS_ENTITY_DATA_SERVICE_USAGE';
	EXEC (@QUERY);
	
	SELECT @CLIENT_ENTITY_ID=SEQ_ID FROM [SRM_CLIENT_ENTITIES] WHERE ENTITY_DISPLAY_NAME='SERVICE_USAGE' AND SRM_CLIENTS_SEQ_ID=@CLIENT_ID
	SELECT @LOOKUP_CLIENT_ENTITY_ID=SEQ_ID FROM [SRM_CLIENT_ENTITIES] WHERE ENTITY_DISPLAY_NAME='SERVICE_TYPE' AND SRM_CLIENTS_SEQ_ID=@CLIENT_ID
	
	print 'Start insert: ' +CONVERT(nvarchar,getdate(),121)
	
	  SELECT @ACCOUNT_ATTRIBUTE_ID=SEQ_ID 
	  FROM [SRM-framework_NEW]..[SRM_CLIENT_ENTITY_ATTRIBUTES] 
	  WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@CLIENT_ENTITY_ID AND ATTRIBUTE_DISPLAY_NAME='ACCOUNT'
  
	
	SET @QUERY = 'INSERT INTO ['+@CUSTOM_ENTITY_NAME+'].dbo.CUS_ENTITY_DATA_SERVICE_USAGE SELECT SU.ATTRIBUTE_003,SU.ATTRIBUTE_010,LOOKUP.ATTRIBUTE_002 ATTRIBUTE_011,SU.ATTRIBUTE_015,SU.ATTRIBUTE_019,SU.ATTRIBUTE_020,SU.ATTRIBUTE_023 FROM ['+@CUSTOM_ENTITY_NAME+'].dbo.CUS_ENTITY_DATA SU JOIN ['+@CUSTOM_ENTITY_NAME+']..CUS_ENTITY_DATA LOOKUP ON LOOKUP.SEQ_ID=SU.ATTRIBUTE_010 WHERE SU.SEQ_ID IN ( (select distinct CUS_ENTITY_DATA_SEQ_ID from ['+@CUSTOM_PIVOT_NAME+']..CUS_PIVOT_NON_UNIQUE_INDEXES
	  where SRM_CLIENT_ENTITIES_SEQ_ID='+CAST(@CLIENT_ENTITY_ID AS NVARCHAR(100))+' and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID='+CAST(@ACCOUNT_ATTRIBUTE_ID AS NVARCHAR(100))+' and attribute_decimal > 0
	  AND ATTRIBUTE_DECIMAL = '+CAST(@ACCOUNT_RECORD_ID AS NVARCHAR(100))+')) AND SU.SRM_CLIENT_ENTITIES_SEQ_ID='+CAST(@CLIENT_ENTITY_ID AS NVARCHAR(100))+' AND LOOKUP.SRM_CLIENT_ENTITIES_SEQ_ID='+CAST(@LOOKUP_CLIENT_ENTITY_ID AS NVARCHAR(100));
	EXEC (@QUERY);

	print 'End insert: ' +CONVERT(nvarchar,getdate(),121)
	
	DECLARE @last12MonthDate as datetime;
	DECLARE @currentDate as datetime;

	DECLARE @DIRECT_SERVICES_USED_IN_LAST_12_MONTHS AS INT;
	DECLARE @DIRECT_SERVICE_LAST_BOUGHT  AS DATETIME;
	DECLARE @NUMBER_OF_OUTSTANDING_LOANS  AS INT;
	DECLARE @USES_GLOBAL_PAYMENT  AS NVARCHAR(1);
	DECLARE @NUMBER_OF_POLICIES  AS INT;
	DECLARE @DIRECT_SERVICES_TURNOVER_IN_LAST_12_MONTHS  AS MONEY;
	DECLARE @DIRECT_SERVICES_AVERAGE_IN_LAST_12_MONTHS  AS DECIMAL(18,2);
	DECLARE @HAS_SAVING_ACCOUNT  AS NVARCHAR(1);
	DECLARE @NUMBER_OF_LEGAL AS INT;
	DECLARE @NUMBER_OF_OTHER_SERVICES AS INT;
	
	DECLARE @serviceTypeDirect as nvarchar(50);
	DECLARE @serviceTypeLoan as nvarchar(50);
	DECLARE @serviceTypeInsurance as nvarchar(50);
	DECLARE @serviceTypeLegal as nvarchar(50);
	DECLARE @serviceTypeDeposit as nvarchar(50);
	DECLARE @serviceTypeGlobal as nvarchar(50);
	
	SET @serviceTypeDirect = 'DIRECTUSE'
	SET @serviceTypeLoan = '1'
	SET @serviceTypeInsurance='TOWINS'
	SET @serviceTypeLegal='bira Legal'
	SET @serviceTypeDeposit='3'
	SET @serviceTypeGlobal='GLOBAL'

	SELECT @currentDate = GETDATE()
	SELECT @last12MonthDate = DATEADD(M,-12,@currentDate)
	
	SET @QUERY = 'SELECT ATTRIBUTE_003,ATTRIBUTE_010,ATTRIBUTE_011,ATTRIBUTE_015,ATTRIBUTE_019,ATTRIBUTE_020,ATTRIBUTE_023 FROM ['+@CUSTOM_ENTITY_NAME+'].dbo.CUS_ENTITY_DATA_SERVICE_USAGE';
	
	CREATE TABLE #TEMP_SERVICE_USAGE(ATTRIBUTE_003 BIGINT,ATTRIBUTE_010 BIGINT,ATTRIBUTE_011 NVARCHAR(100),ATTRIBUTE_015 BIGINT,ATTRIBUTE_019 MONEY,ATTRIBUTE_020 DATETIME,ATTRIBUTE_023 DATETIME)
	INSERT INTO #TEMP_SERVICE_USAGE EXECUTE SP_EXECUTESQL @QUERY
	
	print 'Start calculation: ' +CONVERT(nvarchar,getdate(),121)
	SELECT @DIRECT_SERVICES_USED_IN_LAST_12_MONTHS =COUNT(ROWS) FROM (
	SELECT  
	count(ATTRIBUTE_015) AS 'ROWS' FROM #TEMP_SERVICE_USAGE  with(nolock)
	WHERE ATTRIBUTE_003 = @ACCOUNT_RECORD_ID AND ATTRIBUTE_020 >= @last12MonthDate AND ATTRIBUTE_011 = @serviceTypeDirect
	GROUP BY ATTRIBUTE_015 
	HAVING COUNT(ATTRIBUTE_015) > 0) AS TBL

	SELECT @DIRECT_SERVICE_LAST_BOUGHT = 
	MAX(ATTRIBUTE_020) FROM #TEMP_SERVICE_USAGE  with(nolock)
	WHERE ATTRIBUTE_003 = @ACCOUNT_RECORD_ID  AND ATTRIBUTE_011 = @serviceTypeDirect
	
	SELECT @NUMBER_OF_OUTSTANDING_LOANS = 
	count(ATTRIBUTE_003) FROM #TEMP_SERVICE_USAGE  with(nolock)
	WHERE ATTRIBUTE_003 = @ACCOUNT_RECORD_ID AND ATTRIBUTE_023 >= @currentDate AND ATTRIBUTE_011=@serviceTypeLoan
	
	SELECT @USES_GLOBAL_PAYMENT = 
	CASE count(ATTRIBUTE_003) WHEN 0 THEN 'N' ELSE 'Y' END FROM #TEMP_SERVICE_USAGE  with(nolock)
	WHERE ATTRIBUTE_003 = @ACCOUNT_RECORD_ID AND ATTRIBUTE_023 >= @currentDate AND ATTRIBUTE_011=@serviceTypeGlobal
	
	SELECT @NUMBER_OF_POLICIES = 
	count(ATTRIBUTE_003) FROM #TEMP_SERVICE_USAGE  with(nolock)
	WHERE ATTRIBUTE_003 = @ACCOUNT_RECORD_ID 
	--AND ATTRIBUTE_023 >= @currentDate 
	AND ATTRIBUTE_011=@serviceTypeInsurance
    
	SELECT 
	@DIRECT_SERVICES_TURNOVER_IN_LAST_12_MONTHS = 
	isnull(cast(sum(ATTRIBUTE_019 ) as money),0.00),
	@DIRECT_SERVICES_AVERAGE_IN_LAST_12_MONTHS = 
	round(cast(count(ATTRIBUTE_003)/12.00 as decimal(18, 2)),2) 
	FROM #TEMP_SERVICE_USAGE  with(nolock)
	WHERE ATTRIBUTE_003 = @ACCOUNT_RECORD_ID AND ATTRIBUTE_020 >= @last12MonthDate AND ATTRIBUTE_011 = @serviceTypeDirect
    
	SELECT @HAS_SAVING_ACCOUNT = 
	CASE count(ATTRIBUTE_003) WHEN 0 THEN 'N' ELSE 'Y' END FROM #TEMP_SERVICE_USAGE  with(nolock)
	WHERE ATTRIBUTE_003 = @ACCOUNT_RECORD_ID AND ATTRIBUTE_023 >= @currentDate AND ATTRIBUTE_011=@serviceTypeDeposit
	
	SELECT @NUMBER_OF_LEGAL = 
	count(ATTRIBUTE_003) FROM #TEMP_SERVICE_USAGE  with(nolock)
	WHERE ATTRIBUTE_003 = @ACCOUNT_RECORD_ID AND ATTRIBUTE_023 >= @last12MonthDate AND ATTRIBUTE_011 = @serviceTypeLegal
	
	
	SELECT @NUMBER_OF_OTHER_SERVICES = count(*) FROM (
    SELECT count(*) as 'ROWS' FROM #TEMP_SERVICE_USAGE with(nolock)
	WHERE ATTRIBUTE_003 = @ACCOUNT_RECORD_ID AND ATTRIBUTE_011 not in (@serviceTypeLegal,@serviceTypeDeposit,@serviceTypeDirect,@serviceTypeInsurance,@serviceTypeGlobal,@serviceTypeLoan
	,'501'	,'BB'	,'BAGMA'	,'bhf'	,'biradeshot'	,'BMM'	,'biravoice'	,'Branches'	,'BME'	,'CHA'	,'Clearingda'	,'CHAT'	,'DS'	,'DirectSup'	,'DirectStop'	,'GMPG'	,'Gift'	,'HT'	,'HD'	,'Mailchimp'	,'Mailchimp1'	,'MC'	,'MailMem'	,'Mailchimp2'	,'MIW email'	,'PP'	,'RA'	,'RR'	,'Supplier'	,'Test'	,'Wages')
	group by ATTRIBUTE_011
	) as TBL
	
	
	print @ACCOUNT_RECORD_ID
	print 'End calculation: ' +CONVERT(nvarchar,getdate(),121);
	
	print 'Start posting to result: ' +CONVERT(nvarchar,getdate(),121);
	
	
	If @DIRECT_SERVICE_LAST_BOUGHT is null 
		Begin
		SET @QUERY = 'INSERT INTO ['+@CUSTOM_ENTITY_NAME+'].dbo.CUS_ENTITY_DATA_SERVICE_USAGE_RESULT (ACCOUNT_RECORD_ID,DIRECT_SERVICES_USED_IN_LAST_12_MONTHS,DIRECT_SERVICE_LAST_BOUGHT,NUMBER_OF_OUTSTANDING_LOANS,USES_GLOBAL_PAYMENT,NUMBER_OF_POLICIES,DIRECT_SERVICES_TURNOVER_IN_LAST_12_MONTHS,DIRECT_SERVICES_AVERAGE_IN_LAST_12_MONTHS,HAS_SAVING_ACCOUNT,NUMBER_OF_LEGAL,NUMBER_OF_OTHER_SERVICES) 
		VALUES( '+ CAST(isnull(@ACCOUNT_RECORD_ID,0) AS NVARCHAR(100))+','+ CAST(isnull(@DIRECT_SERVICES_USED_IN_LAST_12_MONTHS,0)  AS NVARCHAR(100))+',NULL,'+CAST(isnull(@NUMBER_OF_OUTSTANDING_LOANS,0) AS NVARCHAR(100))+','''+ISNULL(@USES_GLOBAL_PAYMENT,'N')+''','+CAST(isnull(@NUMBER_OF_POLICIES,0) AS NVARCHAR(100))+','+CAST(isnull(@DIRECT_SERVICES_TURNOVER_IN_LAST_12_MONTHS,0) AS NVARCHAR(100))+','+CAST(isnull(@DIRECT_SERVICES_AVERAGE_IN_LAST_12_MONTHS,0) AS NVARCHAR(100))+','''+ISNULL(@HAS_SAVING_ACCOUNT,'N')+''','+CAST(isnull(@NUMBER_OF_LEGAL,0) AS NVARCHAR(100))+','+CAST(isnull(@NUMBER_OF_OTHER_SERVICES,0) AS NVARCHAR(100)) + ')';
		End
	ELSE
		Begin
		SET @QUERY = 'INSERT INTO ['+@CUSTOM_ENTITY_NAME+'].dbo.CUS_ENTITY_DATA_SERVICE_USAGE_RESULT (ACCOUNT_RECORD_ID,DIRECT_SERVICES_USED_IN_LAST_12_MONTHS,DIRECT_SERVICE_LAST_BOUGHT,NUMBER_OF_OUTSTANDING_LOANS,USES_GLOBAL_PAYMENT,NUMBER_OF_POLICIES,DIRECT_SERVICES_TURNOVER_IN_LAST_12_MONTHS,DIRECT_SERVICES_AVERAGE_IN_LAST_12_MONTHS,HAS_SAVING_ACCOUNT,NUMBER_OF_LEGAL,NUMBER_OF_OTHER_SERVICES) 
		VALUES( '+ CAST(isnull(@ACCOUNT_RECORD_ID,0) AS NVARCHAR(100))+','+ CAST(isnull(@DIRECT_SERVICES_USED_IN_LAST_12_MONTHS,0)  AS NVARCHAR(100))+','''+CONVERT(varchar,@DIRECT_SERVICE_LAST_BOUGHT,121) +''','+CAST(isnull(@NUMBER_OF_OUTSTANDING_LOANS,0) AS NVARCHAR(100))+','''+ISNULL(@USES_GLOBAL_PAYMENT,'N')+''','+CAST(isnull(@NUMBER_OF_POLICIES,0) AS NVARCHAR(100))+','+CAST(isnull(@DIRECT_SERVICES_TURNOVER_IN_LAST_12_MONTHS,0) AS NVARCHAR(100))+','+CAST(isnull(@DIRECT_SERVICES_AVERAGE_IN_LAST_12_MONTHS,0) AS NVARCHAR(100))+','''+ISNULL(@HAS_SAVING_ACCOUNT,'N')+''','+CAST(isnull(@NUMBER_OF_LEGAL,0) AS NVARCHAR(100))+','+CAST(isnull(@NUMBER_OF_OTHER_SERVICES,0) AS NVARCHAR(100)) + ')';
		End
	
	
	exec (@QUERY);

	
	print 'End posting: ' +CONVERT(nvarchar,getdate(),121)

	DROP TABLE #TEMP_SERVICE_USAGE
	
END




;




