	, @MEMBER_OF_PUBLIC_UPDATE_CASE_COUNTER INT = 0, @MAX_CASE_SEQ_ID BIGINT
  
	/*SELECT @MAX_CASE_SEQ_ID=SEQ_ID
	FROM [SRM-CustomEntities_152].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) 	
	WHERE CED.SRM_CLIENT_ENTITIES_SEQ_ID=@EN_CASE AND CED.DELETED='N' 
	AND ISNULL(ATTRIBUTE_012,0) IN (SELECT SEQ_ID FROM [SRM-CustomEntities_152].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE 
