		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_152].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WITH (NOLOCK) 
		WHERE CPNUI.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_CH_CASE AND ATTRIBUTE_DECIMAL=@SEQ_ID
