		PRINT 'MEMBER_OF_PUBLIC DELETE'
		IF EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_152].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_CONTACT AND DELETED='N'
