CREATE PROCEDURE [dbo].[BPA_AUTO_DELETE_CASES_AFTER_3_MONTHS_LIVE]
AS

BEGIN

	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT = 137
	DECLARE @DATA_TO_DELETE TABLE(SEQ_ID BIGINT)

	DECLARE @EN_CASE BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID('CASE',@SRM_CLIENTS_SEQ_ID)
	DECLARE @EN_CASE_TYPE BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID('CASE_TYPE',@SRM_CLIENTS_SEQ_ID)
	DECLARE @EN_COMMUNICATION_HISTORY BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID('COMMUNICATION_HISTORY',@SRM_CLIENTS_SEQ_ID)
	DECLARE @EN_ATTACHMENT BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID('ATTACHMENT',@SRM_CLIENTS_SEQ_ID)
	DECLARE @EN_CONTACT BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID('CONTACT',@SRM_CLIENTS_SEQ_ID)
