			PRINT @MEMBER_OF_PUBLIC_DELETE_COUNTER

			PRINT 'Check if any future case is available of raised by contact then don''t delete'
			IF NOT EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_137].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_CASE AND DELETED='N'
			AND ATTRIBUTE_040=@RAISED_BY_CONTACT AND SEQ_ID>@MAX_CASE_SEQ_ID)
			BEGIN
				PRINT 'Sent for Delete'          
				INSERT INTO [SRM-CustomEntities_137].dbo.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_001,ATTRIBUTE_002,
				SRM_CLIENTS_SEQ_ID,SOURCE_OF_DATA,DATE_CREATED,CREATED_BY,DELETED)
				VALUES(@EN_PERMANENT_DELETE_CONTACT,@GUID,@RAISED_BY_CONTACT,
				@SRM_CLIENTS_SEQ_ID,@GUID,GETDATE(),@CREATED_BY,@DELETED)

				SET @NEW_SEQ_ID = SCOPE_IDENTITY()

				EXEC [SRM-DataPivot_137].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
				@SRM_CLIENT_ENTITIES_SEQ_ID = @EN_PERMANENT_DELETE_CONTACT,
				@CUS_ENTITY_DATA_SEQ_ID = @NEW_SEQ_ID,
				@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
			END
		END     
		
		PRINT 'A WORKFLOW JOB IS CREATED WHICH PICK UP DATA FROM PERMANENT_DELETE_CONTACT ENTITY AND REMOVE THE DATA FROM OOMI' 

		PRINT 'CLEAR DATA FROM CASE'
		IF EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_137].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_CASE AND DELETED='N'
		AND SEQ_ID=@SEQ_ID )
		BEGIN
			PRINT '@MEMBER_OF_PUBLIC: ' + @MEMBER_OF_PUBLIC   
			
			IF @MEMBER_OF_PUBLIC='N'
				SET @MEMBER_OF_PUBLIC_UPDATE_CASE_COUNTER = @MEMBER_OF_PUBLIC_UPDATE_CASE_COUNTER + 1

			PRINT @MEMBER_OF_PUBLIC_UPDATE_CASE_COUNTER 
			
			UPDATE [SRM-CustomEntities_137].dbo.CUS_ENTITY_DATA SET
			ATTRIBUTE_040 = CASE WHEN @MEMBER_OF_PUBLIC = 'Y' THEN NULL ELSE ATTRIBUTE_040 END,
			ATTRIBUTE_041 = CASE WHEN @MEMBER_OF_PUBLIC = 'Y' THEN NULL ELSE ATTRIBUTE_041 END,         
			ATTRIBUTE_044 = CASE WHEN @MEMBER_OF_PUBLIC = 'Y' THEN NULL ELSE ATTRIBUTE_044 END,
			ATTRIBUTE_048 = CASE WHEN @MEMBER_OF_PUBLIC = 'Y' THEN NULL ELSE ATTRIBUTE_048 END,
			ATTRIBUTE_022=NULL,ATTRIBUTE_023=NULL,ATTRIBUTE_024=NULL,ATTRIBUTE_025=NULL,
			ATTRIBUTE_056='Y', -- 'Mark as processed'
			DATE_MODIFIED=GETDATE(),MODIFIED_BY=@CREATED_BY
			WHERE SEQ_ID=@SEQ_ID          

			EXEC [SRM-DataPivot_137].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
			@SRM_CLIENT_ENTITIES_SEQ_ID = @EN_CASE,
			@CUS_ENTITY_DATA_SEQ_ID = @SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		END      

		FETCH NEXT FROM curGeneral INTO @SEQ_ID, @RAISED_BY_CONTACT   
	END    
   
	CLOSE curGeneral                           
	DEALLOCATE curGeneral 

	PRINT 'Remove the information from cases where contacts are deleted'

	DECLARE curDeletedContacts CURSOR LOCAL STATIC FOR 
	SELECT SEQ_ID FROM [SRM-CustomEntities_137].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_CASE AND DELETED='N'
	AND ATTRIBUTE_040 IS NOT NULL 
	
	AND NOT EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_137].dbo.CUS_ENTITY_DATA AS C WITH (NOLOCK) WHERE C.SRM_CLIENT_ENTITIES_SEQ_ID=@EN_CONTACT AND C.DELETED='N'
	AND C.SEQ_ID=CED.ATTRIBUTE_040)

	AND ISNULL(ATTRIBUTE_012,0) IN (SELECT SEQ_ID FROM [SRM-CustomEntities_137].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE 
	SRM_CLIENT_ENTITIES_SEQ_ID=@EN_CASE_STATUS AND DELETED='N' AND ATTRIBUTE_003 IN ('Resolved','Cancelled'))
	AND ATTRIBUTE_008 NOT IN (SELECT SEQ_ID FROM [SRM-CustomEntities_137].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) 
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_CASE_TYPE AND DELETED='N' AND ATTRIBUTE_005='Y')
	--AND DATEDIFF(DAY,CAST(ATTRIBUTE_042 AS DATE),GETDATE()) >= 90
	AND CAST(ATTRIBUTE_042 AS DATE) BETWEEN @DATE_START AND @DATE_END
	
   
	OPEN curDeletedContacts                                                             
	FETCH NEXT FROM curDeletedContacts INTO @CASE_SEQ_ID

	WHILE (@@Fetch_Status = 0)       
	BEGIN        

		UPDATE [SRM-CustomEntities_137].dbo.CUS_ENTITY_DATA SET
		ATTRIBUTE_040 = NULL,
		ATTRIBUTE_041 = NULL,         
		ATTRIBUTE_044 = NULL,
		ATTRIBUTE_048 = NULL,
		ATTRIBUTE_022=NULL,ATTRIBUTE_023=NULL,ATTRIBUTE_024=NULL,ATTRIBUTE_025=NULL,
		ATTRIBUTE_056='Y', -- 'Mark as processed'
		DATE_MODIFIED=GETDATE(),MODIFIED_BY=@CREATED_BY
		WHERE SEQ_ID=@CASE_SEQ_ID          

		EXEC [SRM-DataPivot_137].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
		@SRM_CLIENT_ENTITIES_SEQ_ID = @EN_CASE,
		@CUS_ENTITY_DATA_SEQ_ID = @CASE_SEQ_ID,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

		FETCH NEXT FROM curDeletedContacts INTO @CASE_SEQ_ID    
	END    
   
	CLOSE curDeletedContacts                           
	DEALLOCATE curDeletedContacts  
	 
END;




