--EXEC [dbo].[BPA_REMOVE_CONTACT_EMAIL_AND_FIRST_NAME_FROM_CASE_IF_CONTACT_IS_REMOVED_VIA_GDPR]

CREATE PROCEDURE [dbo].[BPA_REMOVE_CONTACT_EMAIL_AND_FIRST_NAME_FROM_CASE_IF_CONTACT_IS_REMOVED_VIA_GDPR]
AS

BEGIN

	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT = 138


	PRINT 'TEST UPDATE'

	DECLARE @EN_CASE BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID('CASE',@SRM_CLIENTS_SEQ_ID)

	DECLARE @SCEA_CASE_RAISED_BY_CONTACT BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_CASE,'RAISED_BY_CONTACT')
	DECLARE @SCEA_CASE_RAISED_BY_EMAIL BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_CASE,'RAISED_BY_EMAIL')
