	DECLARE @SCEA_CASE_COMPLAINT_SPECIALIST BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_CASE,'COMPLAINT_SPECIALIST')
	DECLARE @SCEA_CASE_COMPLAINT_SPECIALIST_EMAIL BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_CASE,'COMPLAINT_SPECIALIST_EMAIL')
	DECLARE @SCEA_CASE_COMPLAINT_SPECIALIST_FIRST_NAME BIGINT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_CASE,'COMPLAINT_SPECIALIST_FIRST_NAME')


	UPDATE CED SET 
	ATTRIBUTE_047 = NULL
	,ATTRIBUTE_049 = NULL
	FROM [SRM-CustomEntities_138].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_CASE AND DELETED='N'
	AND SEQ_ID IN (
	SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_138].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_CASE_COMPLAINT_SPECIALIST
	AND (ATTRIBUTE_DECIMAL IS NULL OR ATTRIBUTE_DECIMAL = 0)
	UNION
	(
	SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_138].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_CASE_COMPLAINT_SPECIALIST_EMAIL
	AND (ATTRIBUTE_STRING IS NOT NULL AND ATTRIBUTE_STRING != '')
	UNION
	SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_138].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_CASE_COMPLAINT_SPECIALIST_FIRST_NAME
	AND (ATTRIBUTE_STRING IS NOT NULL AND ATTRIBUTE_STRING != '')
	)) AND ISNULL(ATTRIBUTE_045,0) = 0 AND 
	(ISNULL(ATTRIBUTE_047,'' ) != '' OR ISNULL(ATTRIBUTE_049, '') != '')

	EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE @SCEA_CASE_COMPLAINT_SPECIALIST
	EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE @SCEA_CASE_COMPLAINT_SPECIALIST_EMAIL
	EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE @SCEA_CASE_COMPLAINT_SPECIALIST_FIRST_NAME



	PRINT 'LIVE UPDATE'
	SET @SRM_CLIENTS_SEQ_ID = 137

	SET @EN_CASE = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID('CASE',@SRM_CLIENTS_SEQ_ID)

	SET @SCEA_CASE_RAISED_BY_CONTACT = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_CASE,'RAISED_BY_CONTACT')
	SET @SCEA_CASE_RAISED_BY_EMAIL = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_CASE,'RAISED_BY_EMAIL')
	SET @SCEA_CASE_RAISED_BY_CONTACT_FIRST_NAME = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_CASE,'RAISED_BY_CONTACT_FIRST_NAME')


	UPDATE CED SET
	ATTRIBUTE_044 = NULL
	,ATTRIBUTE_048 = NULL
	FROM [SRM-CustomEntities_137].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_CASE AND DELETED='N'
	AND SEQ_ID IN (
