	AND (ATTRIBUTE_STRING IS NOT NULL AND ATTRIBUTE_STRING != '')
	UNION
	SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_137].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_CASE_RAISED_BY_CONTACT_FIRST_NAME
	AND (ATTRIBUTE_STRING IS NOT NULL AND ATTRIBUTE_STRING != '')
	)) AND ISNULL(ATTRIBUTE_040,0) = 0 AND 
