	EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE @SCEA_CASE_RAISED_BY_CONTACT
	EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE @SCEA_CASE_RAISED_BY_EMAIL
	EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE @SCEA_CASE_RAISED_BY_CONTACT_FIRST_NAME

	SET @SCEA_CASE_COMPLAINT_SPECIALIST = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_CASE,'COMPLAINT_SPECIALIST')
