	SET @SCEA_CASE_COMPLAINT_SPECIALIST_FIRST_NAME = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_CASE,'COMPLAINT_SPECIALIST_FIRST_NAME')


