-- =============================================
-- Author:	Muhammad MI. Imran Ali
-- Create date: 02/04/2019
-- Description:	Store necessary data for Customer Statement
-- =============================================
--EXEC [dbo].[BPIF_CUSTOMER_STATEMENT] '12121212121',224465724,222729436

CREATE PROCEDURE [dbo].[BPIF_CUSTOMER_STATEMENT]
-- Add the parameters for the stored procedure here
@Job_Id BIGINT,		--Job Id
@Company BIGINT,	--Customer Statement Options
@Account BIGINT		--Organisation
AS
BEGIN
SET NOCOUNT ON;

	DECLARE @Acc_Dept BIGINT	--Company Look Up
	DECLARE @Company_Type NVARCHAR(10)	--External Reference (On Company Look Up)

--Company Look Up
	SELECT @Acc_Dept = ced.SEQ_ID 
	FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced with (nolock)
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 30945	--ACCOUNTING_DEPARTMENT --Company
	AND ISNULL(DELETED,'N') = 'N'
	--AND ISNULL(ATTRIBUTE_003,'N') = 'Y' 
	AND ced.ATTRIBUTE_499 = @Company

--External Reference (On Company Look Up)
	SELECT @Company_Type = ATTRIBUTE_002 FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced with (nolock) WHERE SEQ_ID = @Company AND DELETED = 'N'

	CREATE TABLE #TempSeqIds(Job_Id BIGINT,Member_Record_Id BIGINT,Invoice_Record_Id BIGINT,Member CHAR(1),Invoice CHAR(1))

	PRINT @Company_Type

	IF(@Company_Type = 'Training')
	BEGIN
	 --select all members having member assigned rates outstanding and company is training
	 --select  outstaaning invoices where invoice transactions have company training
		
		PRINT 'In Training'
		
		INSERT INTO #TempSeqIds
		( Job_Id ,		          Member_Record_Id ,		          Invoice_Record_Id ,		          Member ,		          Invoice)
		SELECT @Job_Id,Mem.SEQ_ID,0,'Y','N' FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS Mem with (nolock)
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS Acc with (nolock) ON Acc.SRM_CLIENT_ENTITIES_SEQ_ID = 30662 AND Mem.ATTRIBUTE_002 = Acc.SEQ_ID AND Acc.SEQ_ID = @Account AND acc.DELETED = 'N'
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS MAR with (nolock) ON MAr.SRM_CLIENT_ENTITIES_SEQ_ID = 30767 AND Mar.ATTRIBUTE_002 = Mem.SEQ_ID AND ISNULL(mar.DELETED,'N') = 'N' 
		WHERE mem.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 AND MAR.SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_95].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS MAR_com with (nolock) 
		WHERE MAR_com.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 759960 AND MAR_com.ATTRIBUTE_DECIMAL = @Acc_Dept
		INTERSECT 
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_95].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS Mar_OS with (nolock) 
		WHERE Mar_os.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 759924 AND Mar_os.ATTRIBUTE_DECIMAL > 0
		) AND Mem.DELETED = 'N' AND ISNULL(mem.ATTRIBUTE_006,'N') = 'N'


		INSERT INTO #TempSeqIds
		( Job_Id ,		          Member_Record_Id ,		          Invoice_Record_Id ,		          Member ,		          Invoice)
		SELECT @Job_Id,0,Inv.SEQ_ID,'N','Y'FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS Inv with (nolock)
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS Acc with (nolock) ON Acc.SRM_CLIENT_ENTITIES_SEQ_ID = 30662 AND inv.ATTRIBUTE_002 = Acc.SEQ_ID AND Acc.SEQ_ID = @Account AND acc.DELETED = 'N'
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS IT with (nolock) ON IT.ATTRIBUTE_002 = Inv.SEQ_ID AND IT.DELETED = 'N'
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS Comp with (nolock) ON Comp.SRM_CLIENT_ENTITIES_SEQ_ID = 30945 AND ISNULL(IT.ATTRIBUTE_081,0) = Comp.Seq_id AND Comp.ATTRIBUTE_002 = @Company_Type
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS TS with (nolock) ON TS.SRM_CLIENT_ENTITIES_SEQ_ID = 30766 AND Inv.ATTRIBUTE_012 = TS.SEQ_ID AND ISNULL(TS.ATTRIBUTE_004,'N') = 'Y' AND ts.DELETED = 'N'
		WHERE Inv.SRM_CLIENT_ENTITIES_SEQ_ID = 30768 AND CAST(Inv.ATTRIBUTE_051 AS MONEY) > 0 AND Inv.DELETED = 'N' AND IT.SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_95].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui with (nolock) 
		WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 760425 AND ATTRIBUTE_DECIMAL = @Acc_Dept
		)

	END
	ELSE IF(@Company_Type = 'BOSS')
	BEGIN
	 --select all members having member assigned rates outstanding and company is training
	 --select  outstaaning invoices where invoice transactions have company training

	 PRINT 'Int BOSS'

		INSERT INTO #TempSeqIds
		( Job_Id ,		          Member_Record_Id ,		          Invoice_Record_Id ,		          Member ,		          Invoice)
		SELECT @Job_Id,Mem.SEQ_ID,0,'Y','N' FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS Mem with (nolock) 
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS Acc with (nolock) ON Acc.SRM_CLIENT_ENTITIES_SEQ_ID = 30662 AND Mem.ATTRIBUTE_002 = Acc.SEQ_ID AND Acc.SEQ_ID = @Account AND acc.DELETED = 'N'
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS MAR with (nolock) ON MAr.SRM_CLIENT_ENTITIES_SEQ_ID = 30767 AND Mar.ATTRIBUTE_002 = Mem.SEQ_ID AND ISNULL(mar.DELETED,'N') = 'N' 
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS NC with (nolock) ON NC.SRM_CLIENT_ENTITIES_SEQ_ID = 30677 AND Mar.ATTRIBUTE_030 = NC.SEQ_ID AND ISNULL(NC.ATTRIBUTE_025,'N') = 'Y' AND NC.DELETED = 'N'
		WHERE mem.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 AND MAR.SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_95].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS Mar_OS with (nolock) 
		WHERE Mar_os.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 759924 AND Mar_os.ATTRIBUTE_DECIMAL > 0
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_95].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS Mar_LA with (nolock) 
		WHERE Mar_LA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 759936 AND Mar_LA.ATTRIBUTE_STRING BETWEEN '4000' AND '4050'
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_95].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS Mar_Dep with (nolock) 
		WHERE Mar_Dep.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 759956 AND Mar_Dep.ATTRIBUTE_STRING  = '7'
		) AND Mem.DELETED = 'N' AND ISNULL(mem.ATTRIBUTE_006,'N') = 'N'


		INSERT INTO #TempSeqIds
		( Job_Id ,		          Member_Record_Id ,		          Invoice_Record_Id ,		          Member ,		          Invoice)
