		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS Acc with (nolock) ON Acc.SRM_CLIENT_ENTITIES_SEQ_ID = 30662 AND inv.ATTRIBUTE_002 = Acc.SEQ_ID AND Acc.SEQ_ID = @Account AND acc.DELETED = 'N'
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS IT with (nolock) ON IT.SRM_CLIENT_ENTITIES_SEQ_ID = 30775 AND IT.ATTRIBUTE_002 = Inv.SEQ_ID AND IT.DELETED = 'N'
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS Comp with (nolock) ON Comp.SRM_CLIENT_ENTITIES_SEQ_ID = 30945 AND ISNULL(IT.ATTRIBUTE_081,0) = Comp.Seq_id AND Comp.ATTRIBUTE_002 = @Company_Type
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS NC with (nolock) ON NC.SRM_CLIENT_ENTITIES_SEQ_ID = 30677 AND IT.ATTRIBUTE_006 = NC.SEQ_ID AND NC.ATTRIBUTE_002 BETWEEN 4000 AND 4050 AND NC.DELETED = 'N'
		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS TS with (nolock) ON TS.SRM_CLIENT_ENTITIES_SEQ_ID = 30766 AND Inv.ATTRIBUTE_012 = TS.SEQ_ID AND ISNULL(TS.ATTRIBUTE_004,'N') = 'Y' AND ts.DELETED = 'N'
