		INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS NC with (nolock) ON NC.SRM_CLIENT_ENTITIES_SEQ_ID = 30677 AND Mar.ATTRIBUTE_030 = NC.SEQ_ID AND NC.ATTRIBUTE_002 NOT BETWEEN 4000 AND 4050 AND NC.DELETED = 'N'
