		INTERSECT 
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_95].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS Mar_OS with (nolock) WHERE Mar_os.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 759924 AND Mar_os.ATTRIBUTE_DECIMAL > 0
		--INTERSECT
		--SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_95].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS Mar_LA with (nolock)
