	SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENTS_SEQ_ID,ATTRIBUTE_001,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_004,ATTRIBUTE_005,DATE_CREATED,CREATED_BY,DELETED)
	SELECT 48188,95,Job_Id,Member_Record_Id,Invoice_Record_Id,Member,Invoice,GETDATE(),'STMT_SP','N' FROM #TempSeqIds 

	--Resultant Data
	--SELECT @Job_Id as JobId
	--SELECT @Company as CustomerStatementOption
	--SELECT @Account as Organisation
	--SELECT @Acc_Dept as Company
	--SELECT @Company_Type as ExternalReference
	SELECT * FROM #TempSeqIds



	DROP TABLE #TempSeqIds

	--Populating Pivot
	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
	DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT
	DECLARE @TOTAL_COUNT BIGINT
	DECLARE @CURRENT_COUNT BIGINT

	PRINT @SRM_CLIENT_ENTITIES_SEQ_ID
	PRINT @SRM_CLIENTS_SEQ_ID 

	DECLARE @FIELD01 NVARCHAR(100)
	DECLARE curGeneral CURSOR LOCAL STATIC FOR 
	SELECT SEQ_ID,SRM_CLIENT_ENTITIES_SEQ_ID,SRM_CLIENTS_SEQ_ID 
	FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) 
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 48188 
	AND ATTRIBUTE_001 = @Job_Id 
	AND DELETED = 'N'

	--WHERE SEQ_ID IN (SELECT SEQ_ID 
	--					FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 with (nolock)
	--					WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 48188 
	--					AND ATTRIBUTE_001 = @Job_Id 
	--					AND DELETED = 'N'
	--					) 

	OPEN curGeneral 
	FETCH NEXT FROM curGeneral INTO @CUS_ENTITY_DATA_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENTS_SEQ_ID

	WHILE (@@Fetch_Status = 0) 
	BEGIN 
	PRINT @CUS_ENTITY_DATA_SEQ_ID
	IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL
		SELECT @SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENTS_SEQ_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-CustomEntities_95].DBO.CUS_ENTITY_DATA with (nolock) WHERE SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID

	EXEC [SRM-DataPivot_95].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
	@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
	@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

	FETCH NEXT FROM curGeneral INTO @CUS_ENTITY_DATA_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENTS_SEQ_ID 
	END 

	CLOSE curGeneral 
	DEALLOCATE curGeneral 

END



;





CREATE PROCEDURE [dbo].[BPIF_GET_Update_Icons]
as

	/*
	UPDATE CED2 SET CED2.ATTRIBUTE_017=CED.ATTRIBUTE_017 FROM [SRM-CustomEntities_91].dbo.CUS_ENTITY_DATA AS ced with (nolock) 
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 with (nolock)  ON CED2.SRM_CLIENT_ENTITIES_SEQ_ID=30669 AND CED2.DELETED='N' AND CED.ATTRIBUTE_001 = CED2.ATTRIBUTE_001
	WHERE CED.SRM_CLIENT_ENTITIES_SEQ_ID=28806 AND CED.DELETED='N' AND CED.ATTRIBUTE_017 IS NOT NULL
	*/


	--##############################Update Member Status color on Members#################################--

	--SELECT ced.ATTRIBUTE_001,ced.COLOR,ced2.ATTRIBUTE_017 FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced with (nolock) 
	--INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 with (nolock)  ON ced2.SRM_CLIENT_ENTITIES_SEQ_ID = 30669 AND ced2.DELETED='N' AND CAST(ced.ATTRIBUTE_021 AS BIGINT) =ced2.SEQ_ID
	--WHERE ced.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 AND ced.SEQ_ID=194485705



	UPDATE ced set ced.COLOR = ced2.ATTRIBUTE_017 FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced with (nolock) 
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 with (nolock)  ON ced2.SRM_CLIENT_ENTITIES_SEQ_ID = 30669 AND ced2.DELETED='N' AND CAST(ced.ATTRIBUTE_021 AS BIGINT) =ced2.SEQ_ID
	WHERE ced.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 
	AND ced.COLOR <> ced2.ATTRIBUTE_017


	--###############################Update Member color on Account Where Accounts have single membership####################################--
	/*
	SELECT ced.COLOR,ced2.COLOR FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced with (nolock) 
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 with (nolock)  ON ced2.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 AND CAST(ced2.ATTRIBUTE_002 AS BIGINT) = ced.SEQ_ID
	AND ced.SEQ_ID IN (
	SELECT CAST(ATTRIBUTE_002 AS BIGINT) FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced with (nolock) 
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 30668
	GROUP BY CAST(ATTRIBUTE_002 AS BIGINT)
	HAVING COUNT(*) = 1 
	) and ced.COLOR  is null
	*/


	UPDATE ced SET ced.COLOR = ced2.COLOR FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced with (nolock) 
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 with (nolock)  ON ced2.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 AND CAST(ced2.ATTRIBUTE_002 AS BIGINT) = ced.SEQ_ID
	AND ced.SEQ_ID IN (
	SELECT CAST(ATTRIBUTE_002 AS BIGINT) FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced with (nolock) 
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 30668
	GROUP BY CAST(ATTRIBUTE_002 AS BIGINT)
	HAVING COUNT(*) = 1 
	) and ced.COLOR  <> ced2.COLOR



	--########################Update Green Member Color on Account where Account have Multiple Memberships an atleast one membership is active#########################
	/*
	SELECT ced.attribute_002,ced.COLOR,ced2.COLOR FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced WITH (NOLOCK) --Account
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 WITH (NOLOCK) ON ced2.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 AND CAST(ced2.ATTRIBUTE_002 AS BIGINT) = ced.SEQ_ID --Member
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced3 WITH (NOLOCK) ON ced3.SRM_CLIENT_ENTITIES_SEQ_ID = 30669 AND cast(ced2.ATTRIBUTE_021 as bigint) = ced3.SEQ_ID AND ISNULL(ced3.ATTRIBUTE_005,'N')  = 'N' --Member_Status
	Where ced.SEQ_ID IN (
	SELECT CAST(ATTRIBUTE_002 AS BIGINT) FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced WITH (NOLOCK)
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 30668
	GROUP BY CAST(ATTRIBUTE_002 AS BIGINT)
	HAVING COUNT(*) > 1 
	) and ced.COLOR  <> ced2.COLOR
	*/


	Update ced set ced.COLOR = ced2.COLOR FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced WITH (NOLOCK) --Account
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 WITH (NOLOCK) ON ced2.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 AND CAST(ced2.ATTRIBUTE_002 AS BIGINT) = ced.SEQ_ID --Member
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced3 WITH (NOLOCK) ON ced3.SRM_CLIENT_ENTITIES_SEQ_ID = 30669 AND cast(ced2.ATTRIBUTE_021 as bigint) = ced3.SEQ_ID AND ISNULL(ced3.ATTRIBUTE_005,'N')  = 'N' --Member_Status
	Where ced.SEQ_ID IN (
	SELECT CAST(ATTRIBUTE_002 AS BIGINT) FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced WITH (NOLOCK)
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 30668
	GROUP BY CAST(ATTRIBUTE_002 AS BIGINT)
	HAVING COUNT(*) > 1 
	) AND ced.COLOR  <> ced2.COLOR



	--############################Update Member banner Color on Account where Account have Multiple Memberships and none of the membership is Active################################
	/*
	SELECT ced.attribute_002,ced.COLOR,ced2.COLOR FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced WITH (NOLOCK)--Account
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 WITH (NOLOCK) ON ced2.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 AND CAST(ced2.ATTRIBUTE_002 AS BIGINT) = ced.SEQ_ID --Member
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced3 WITH (NOLOCK) ON ced3.SRM_CLIENT_ENTITIES_SEQ_ID = 30669 AND cast(ced2.ATTRIBUTE_021 as bigint) = ced3.SEQ_ID AND ISNULL(ced3.ATTRIBUTE_004,'N')  =  'N' --Member_Status
	Where ced.SEQ_ID IN (
	SELECT CAST(ATTRIBUTE_002 AS BIGINT) FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced WITH (NOLOCK)
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 30668
	GROUP BY CAST(ATTRIBUTE_002 AS BIGINT)
	HAVING COUNT(*) > 1 
	) and ced.color is null
	*/


	Update ced set ced.COLOR = ced2.COLOR FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced WITH (NOLOCK) --Account
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 WITH (NOLOCK) ON ced2.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 AND CAST(ced2.ATTRIBUTE_002 AS BIGINT) = ced.SEQ_ID --Member
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced3 WITH (NOLOCK) ON ced3.SRM_CLIENT_ENTITIES_SEQ_ID = 30669 AND cast(ced2.ATTRIBUTE_021 as bigint) = ced3.SEQ_ID AND ISNULL(ced3.ATTRIBUTE_004,'N')  =  'N' --Member_Status
	Where ced.SEQ_ID IN (
	SELECT CAST(ATTRIBUTE_002 AS BIGINT) FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced WITH (NOLOCK)
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 30668
	GROUP BY CAST(ATTRIBUTE_002 AS BIGINT)
	HAVING COUNT(*) > 1 
	) AND ced.color <> ced2.COLOR
	AND ced.SEQ_ID NOT IN
	(
	SELECT ced.seq_id FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced WITH (NOLOCK) --Account
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 WITH (NOLOCK) ON ced2.SRM_CLIENT_ENTITIES_SEQ_ID = 30668 AND CAST(ced2.ATTRIBUTE_002 AS BIGINT) = ced.SEQ_ID --Member
	INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced3 WITH (NOLOCK) ON ced3.SRM_CLIENT_ENTITIES_SEQ_ID = 30669 AND cast(ced2.ATTRIBUTE_021 as bigint) = ced3.SEQ_ID AND ISNULL(ced3.ATTRIBUTE_005,'N')  = 'N' --Member_Status
	WHERE ced.SRM_CLIENT_ENTITIES_SEQ_ID = 30662 AND ced.DELETED = 'N'
	)


	--#########################################Update Account status Color on Account where Account have no membership#######################################

	--Not executed as Color code on Account status is not set.

	--UPDATE CED2 SET 
	--CED2.ATTRIBUTE_006=CED.ATTRIBUTE_006 FROM [SRM-CustomEntities_91].dbo.CUS_ENTITY_DATA AS ced with (nolock) 
	--INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced2 with (nolock)  ON CED2.SRM_CLIENT_ENTITIES_SEQ_ID=30663 AND CED2.DELETED='N' AND CED.ATTRIBUTE_001 = CED2.ATTRIBUTE_001
	--WHERE CED.SRM_CLIENT_ENTITIES_SEQ_ID=28800 AND CED.DELETED='N' AND CED.ATTRIBUTE_006 IS NOT NULL


	--SELECT ced.attribute_002,ced.COLOR,ced3.ATTRIBUTE_006 FROM [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced with (nolock) --Account
	--INNER JOIN [SRM-CustomEntities_95].dbo.CUS_ENTITY_DATA AS ced3 ON ced3.SRM_CLIENT_ENTITIES_SEQ_ID = 30663 AND  ced.ATTRIBUTE_006 = ced3.SEQ_ID --AND ISNULL(ced3.ATTRIBUTE_004,'N')  =  'N' --Account_Status
	--where ced.SRM_CLIENT_ENTITIES_SEQ_ID = 30662 And ced.color is null and ced.ATTRIBUTE_015 is null


