CREATE PROCEDURE [dbo].[CITMA_GET_Paid_BY_MEMBER]
	-- Add the parameters for the stored procedure here
	@OUTPUt_SEQ_ID bigint,
	@ACCOUNT_SEQ_ID BIGINT,
	@API_REQUEST_INVOICE BIGINT = 0
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'start'

	Declare @TotalRecords int
	Declare @Account_SRM_Client_Entity_SEQ_ID bigint
	DECLARE @STR_SQL NVARCHAR(4000)
	DECLARE @Counter int
	DECLARE @MemberId NVARCHAR(15)
	DECLARE @MemberName NVARCHAR(100)
	DECLARE @Total_Os MONEY
	DECLARE @MemberCategory NVARCHAR(100) 
	DECLARE @Total_VAT MONEY 
	DECLARE @MEMBER_IDS NVARCHAR(1000),@PURCHASE_ORDER_NO NVARCHAR(200), @TOTAL_OUTSTANDING NVARCHAR(200), @VAT_AMOUNT NVARCHAR(200)
	DECLARE @MEMBER_SEQ_IDS TABLE(SEQ_ID BIGINT)

	IF @API_REQUEST_INVOICE > 0
	BEGIN
		SELECT @MEMBER_IDS=ATTRIBUTE_017 
		,@PURCHASE_ORDER_NO=ISNULL(ATTRIBUTE_015,'')
		FROM [SRM-CustomEntities_120].dbo.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SEQ_ID=@API_REQUEST_INVOICE

		SET @PURCHASE_ORDER_NO = 'Purchase Order No.: ' + @PURCHASE_ORDER_NO
		
		INSERT INTO @MEMBER_SEQ_IDS(SEQ_ID)
		Select SEQ_ID
		From [SRM-CustomEntities_120]..CUS_ENTITY_DATA WITH (NOLOCK) 
		WHERE SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040444 AND ATTRIBUTE_DECIMAL = @ACCOUNT_SEQ_ID
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040426 AND ATTRIBUTE_BOOLEAN = 'N'
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040464 AND ATTRIBUTE_DECIMAL > 0
		) AND DELETED != 'Y' 
		AND SEQ_ID IN (SELECT value FROM [SRM-Framework_New].dbo.fn_Split(@MEMBER_IDS,','))

		SELECT @TotalRecords = COUNT(SEQ_ID) FROM @MEMBER_SEQ_IDS AS MSI

		SELECT @TOTAL_OUTSTANDING=SUM(CAST(ATTRIBUTE_044 AS MONEY)) FROM [SRM-CustomEntities_120].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) 
		WHERE SEQ_ID IN (SELECT SEQ_ID FROM @MEMBER_SEQ_IDS)

		SELECT @VAT_AMOUNT = SUM(CAST(ATTRIBUTE_017 AS MONEY)) FROM [SRM-CustomEntities_120].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) 
		WHERE SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 967875 
		AND ATTRIBUTE_DECIMAL IN (SELECT SEQ_ID FROM @MEMBER_SEQ_IDS)) AND CED.DELETED='N' AND CAST(ATTRIBUTE_019 AS MONEY) > 0
		
		UPDATE [SRM-Workflow].dbo.WFL_OUTPUT SET ATTRIBUTE_012=@TOTAL_OUTSTANDING,ATTRIBUTE_013=@VAT_AMOUNT,ATTRIBUTE_526=@PURCHASE_ORDER_NO WHERE SEQ_ID=@OUTPUt_SEQ_ID
		
	END
	ELSE
	BEGIN

		Select @TotalRecords = COUNT(SEQ_ID) 
		From [SRM-CustomEntities_120]..CUS_ENTITY_DATA WITH (NOLOCK) 
		WHERE SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040444 AND ATTRIBUTE_DECIMAL = @ACCOUNT_SEQ_ID
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040426 AND ATTRIBUTE_BOOLEAN = 'N'
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040464 AND ATTRIBUTE_DECIMAL > 0
		) AND DELETED != 'Y'
	END

	PRINT 'Total Records End'

	PRINT CAST(@TotalRecords AS NVARCHAR)

	IF @API_REQUEST_INVOICE > 0
	BEGIN
		DECLARE CurMain CURSOR LOCAL STATIC FOR
		
		Select ATTRIBUTE_001 MEMBER_ID,ATTRIBUTE_005 ACCOUNT_NAME,CAST(ATTRIBUTE_044 AS MONEY) TOTAL_OUTSTANDING, ATTRIBUTE_017 Member_Category,
		(
		SELECT SUM(CAST(ATTRIBUTE_017 AS MONEY)) FROM [SRM-CustomEntities_120].dbo.CUS_ENTITY_DATA AS ced WHERE SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1043310 AND ATTRIBUTE_DECIMAL = mem.seq_id
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1043327 AND ATTRIBUTE_DECIMAL > 0
		) AND ced.DELETED != 'Y'
		) VAT_AMOUNT
		From [SRM-CustomEntities_120]..CUS_ENTITY_DATA mem WITH (NOLOCK) 
		WHERE SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040444 AND ATTRIBUTE_DECIMAL = @ACCOUNT_SEQ_ID
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040426 AND ATTRIBUTE_BOOLEAN = 'N'
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040464 AND ATTRIBUTE_DECIMAL > 0
		) AND DELETED != 'Y'
		AND mem.SEQ_ID IN (SELECT value FROM [SRM-Framework_New].dbo.fn_Split(@MEMBER_IDS,','))
	END
	ELSE
	BEGIN
		DECLARE CurMain CURSOR LOCAL STATIC FOR
        
		Select ATTRIBUTE_001 MEMBER_ID,ATTRIBUTE_005 ACCOUNT_NAME,CAST(ATTRIBUTE_044 AS MONEY) TOTAL_OUTSTANDING, ATTRIBUTE_017 Member_Category,
		(
		SELECT SUM(CAST(ATTRIBUTE_017 AS MONEY)) FROM [SRM-CustomEntities_120].dbo.CUS_ENTITY_DATA AS ced WHERE SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1043310 AND ATTRIBUTE_DECIMAL = mem.seq_id
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1043327 AND ATTRIBUTE_DECIMAL > 0
		) AND ced.DELETED != 'Y'
		) VAT_AMOUNT
		From [SRM-CustomEntities_120]..CUS_ENTITY_DATA MEM WITH (NOLOCK) 
		WHERE SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040444 AND ATTRIBUTE_DECIMAL = @ACCOUNT_SEQ_ID
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040426 AND ATTRIBUTE_BOOLEAN = 'N'
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_120].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS cpnui WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1040464 AND ATTRIBUTE_DECIMAL > 0
		) AND DELETED != 'Y'
	END
    
	OPEN CurMain
	FETCH NEXT FROM CurMain INTO @MemberId, @MemberName, @Total_Os,@MemberCategory,@Total_VAT

	Set @Counter = 1

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT @MemberName
		SET @STR_SQL = 'UPDATE [SRM-Workflow].dbo.WFL_OUTPUT SET'
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((2 + @Counter) * 10) + 1 as nvarchar))) + Cast(((2 + @Counter) * 10) + 1 as nvarchar) + ' = ''' + @MemberId + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((2 + @Counter) * 10) + 2 as nvarchar))) + Cast(((2 + @Counter) * 10) + 2 as nvarchar) + '=''' + REPLACE(@MemberName,CHAR(39),CHAR(39)+CHAR(39)) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((2 + @Counter) * 10) + 3 as nvarchar))) + Cast(((2 + @Counter) * 10) + 3 as nvarchar) + '=''' + @MemberCategory + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((2 + @Counter) * 10) + 4 as nvarchar))) + Cast(((2 + @Counter) * 10) + 4 as nvarchar) + '=''' + CAST(ISNULL(@Total_VAT,0.00) AS NVARCHAR) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((2 + @Counter) * 10) + 5 as nvarchar))) + Cast(((2 + @Counter) * 10) + 5 as nvarchar) + ' = ''' + CAST(ISNULL(@Total_Os,0.00) AS NVARCHAR) + ''''
		SET @STR_SQL = @STR_SQL + ' WHERE SEQ_ID = ' + CAST(@OUTPUt_SEQ_ID AS NVARCHAR(20))
	

		PRINT @STR_SQL

		EXEC (@STR_SQL)

		Set @Counter = @Counter + 1

		FETCH NEXT FROM CurMain INTO @MemberId, @MemberName, @Total_Os,@MemberCategory,@Total_VAT

	END
CLOSE CurMain
DEALLOCATE CurMain

END







;




