CREATE PROCEDURE [dbo].[CONTACT_INTEGRATION_WITH_ETARGET]
	 @RECORD_ID BIGINT,
	 @ERROR INT = NULL OUTPUT

AS
BEGIN
PRINT 'HERE'
PRINT @RECORD_ID

DECLARE	
@OOMI_SEQ_ID	BIGINT,@UCN	VARCHAR(MAX),@LAST_NAME	VARCHAR(MAX),@FIRST_NAME	VARCHAR(MAX),@MIDDLE_NAME	VARCHAR(MAX),@PREVIOUS_LAST_NAME	VARCHAR(MAX),
@INITIALS	VARCHAR(MAX),@LABEL_NAME	VARCHAR(MAX),@DESIGNATORY_LETTERS	VARCHAR(MAX),@SALUTATION	VARCHAR(MAX),@DATE_OF_BIRTH	VARCHAR(MAX),@AGE	VARCHAR(MAX),
@LOGIN_USER_NAME	VARCHAR(MAX),@LOGIN_PASSWORD	VARCHAR(MAX),@DATE_CREATED	VARCHAR(MAX),@CREATED_BY	VARCHAR(MAX),@NATIONALITY_NAME	VARCHAR(MAX),
@TITLE_NAME	VARCHAR(MAX),@VIP_LEVEL_NAME	VARCHAR(MAX),@LAST_PAYMENT_DATE	VARCHAR(MAX),@GENDER_DESCRIPTION	VARCHAR(MAX),@THIRD_PARTY_DISCLOSURE_CONSENT_DATE	VARCHAR(MAX),
@THIRD_PARTY_AVAILABILITY_DESCRIPTION	VARCHAR(MAX),@DATA_PROTECTION	VARCHAR(MAX),@ARE_YOU_NI_MEMBER_	VARCHAR(MAX),@MAIN_COUNTRY_NAME	VARCHAR(MAX),
@CRM_TITLES_SEQ_ID BIGINT,@CRM_NATIONALITIES_SEQ_ID BIGINT,@CRM_COUNTRIES_SEQ_ID BIGINT,@CRM_THIRD_PARTY_SEQ_ID BIGINT,@CRM_CONTACT_STATUS_SEQ_ID BIGINT

SELECT				
@OOMI_SEQ_ID=	SEQ_ID	/*	RECORD_ID	*/,
@UCN=	ATTRIBUTE_003	/*	UCN	*/,
@LAST_NAME=	ATTRIBUTE_004	/*	LAST_NAME	*/,
@FIRST_NAME=	ATTRIBUTE_005	/*	FIRST_NAME	*/,
@MIDDLE_NAME=	ATTRIBUTE_006	/*	MIDDLE_NAME	*/,
@PREVIOUS_LAST_NAME=	ATTRIBUTE_007	/*	PREVIOUS_LAST_NAME	*/,
@INITIALS=	ATTRIBUTE_008	/*	INITIALS	*/,
@LABEL_NAME=	ATTRIBUTE_001	/*	LABEL_NAME	*/,
@DESIGNATORY_LETTERS=	ATTRIBUTE_009	/*	DESIGNATORY_LETTERS	*/,
@SALUTATION=	ATTRIBUTE_010	/*	SALUTATION	*/,
@DATE_OF_BIRTH=	ATTRIBUTE_011	/*	DATE_OF_BIRTH	*/,
@AGE=	ATTRIBUTE_012	/*	AGE	*/,
@LOGIN_USER_NAME=	ATTRIBUTE_020	/*	LOGIN_USER_NAME	*/,
@LOGIN_PASSWORD=	ATTRIBUTE_022	/*	LOGIN_PASSWORD	*/,
@DATE_CREATED=	DATE_CREATED	/*	DATE_CREATED	*/,
@CREATED_BY=	CREATED_BY	/*	CREATED_BY	*/,
@NATIONALITY_NAME=	ATTRIBUTE_024	/*	NATIONALITY_NAME	*/,
@TITLE_NAME=	ATTRIBUTE_026	/*	TITLE_NAME	*/,
@VIP_LEVEL_NAME=	ATTRIBUTE_028	/*	VIP_LEVEL_NAME	*/,
@LAST_PAYMENT_DATE=	ATTRIBUTE_090	/*	LAST_PAYMENT_DATE	*/,
@GENDER_DESCRIPTION=	ATTRIBUTE_111	/*	GENDER_DESCRIPTION	*/,
@THIRD_PARTY_DISCLOSURE_CONSENT_DATE=	ATTRIBUTE_126	/*	THIRD_PARTY_DISCLOSURE_CONSENT_DATE	*/,
@THIRD_PARTY_AVAILABILITY_DESCRIPTION=	ATTRIBUTE_128	/*	THIRD_PARTY_AVAILABILITY_DESCRIPTION	*/,
@DATA_PROTECTION=	ATTRIBUTE_146	/*	DATA_PROTECTION	*/,
@ARE_YOU_NI_MEMBER_=	ATTRIBUTE_179	/*	ARE_YOU_NI_MEMBER_	*/,
@MAIN_COUNTRY_NAME=	ATTRIBUTE_185	/*	MAIN_COUNTRY_NAME	*/
--SELECT TOP 10 * 
FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA  WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 9855 AND SEQ_ID = 17053179

IF EXISTS(SELECT SEQ_ID FROM ETARGETNI.DBO.CRM_TITLES WHERE LTRIM(RTRIM(ISNULL(TITLE_DESC,''))) = @TITLE_NAME)--[88.208.248.83].
	PRINT @TITLE_NAME


END



;







-- =============================================
-- Author:  <ASAD>
-- Create date: <14/08/2013,,>
-- Description: <Apply Area of Focus Data to Web service Area of FocusE
-- EXEC [dbo].[COPY_CLIENT_FEATURES] 36,21,8129,65,'' ,'N'
-- =============================================
CREATE PROCEDURE  [dbo].[COPY_CLIENT_FEATURES] 
	 @FROM_SRM_CLIENTS_SEQ_ID BIGINT,
	 @TO_SRM_CLIENTS_SEQ_ID BIGINT,
	 @FROM_ENTITIES_SEQ_ID BIGINT,
	 @TO_ENTITIES_SEQ_ID BIGINT,
	 @FROM_CLIENT_ENTITIES_SEQ_ID BIGINT,
	 @TO_CLIENT_ENTITIES_SEQ_ID BIGINT,
	 @FROM_SRM_USERS_SEQ_ID BIGINT,
	 @TO_SRM_USERS_SEQ_ID BIGINT,
	 @DESCRIPTION NVARCHAR(200) = NULL OUTPUT
 AS 
 BEGIN
  
	SET NOCOUNT ON;
	
	DECLARE @NEW_SRM_ENTITIES_SEQ_ID BIGINT
	DECLARE @NEW_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SRM_ENTITIES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SYSTEM_ENTITY CHAR(1)
	DECLARE @CREATED_BY NVARCHAR(100)
	DECLARE @DATE_CREATED DATETIME
	DECLARE @ATTRIBUTE_DISPLAY_NAME NVARCHAR(200)

	DECLARE @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID BIGINT

	DECLARE @SRM_ENTITY_ATTRIBUTES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT
	DECLARE @NEW_SRM_ENTITY_ATTRIBUTES_SEQ_ID BIGINT

	DECLARE @SRM_CLIENT_FILTER_VIEWS_SEQ_ID BIGINT
	DECLARE @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID BIGINT

	DECLARE @SRM_CLIENT_ENTITY_LOOKUP_FILTERS_SEQ_ID BIGINT
	DECLARE @NEW_SRM_CLIENT_ENTITY_LOOKUP_FILTERS_SEQ_ID BIGINT

	DECLARE @OLD_SRM_CLIENT_ENTITIES_SEQ_ID2  BIGINT
	DECLARE @NEW_SRM_CLIENT_ENTITIES_SEQ_ID2  BIGINT
	DECLARE @SRM_BUTTON_TYPES_SEQ_ID BIGINT 
	DECLARE @ENTITY_DISPLAY_NAME NVARCHAR(200)

	DECLARE @SYSTEM_ATTRIBUTE CHAR(1)

	DECLARE @SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID BIGINT
	DECLARE @NEW_SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID BIGINT
	DECLARE @NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID BIGINT


	DECLARE @TEMP_ENTITY_CLIENT_ENTITY_TABLE TABLE
	(
		SRM_ENTITIES_SEQ_ID BIGINT,
		SRM_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT
	)

	DECLARE @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE TABLE
	(
		SRM_ENTITIES_SEQ_ID BIGINT,
		SRM_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT,
		SRM_ENTITY_ATTRIBUTES_SEQ_ID BIGINT,
		SRM_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT
	)

	DECLARE @TEMP_ENTITY_BUTTONS TABLE
	(		
		SRM_ENTITIES_SEQ_ID BIGINT,
		SRM_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID2 BIGINT
	)

     INSERT INTO @TEMP_ENTITY_CLIENT_ENTITY_TABLE
	 (
			SRM_ENTITIES_SEQ_ID,
			SRM_ENTITIES_SEQ_ID2,
			SRM_CLIENT_ENTITIES_SEQ_ID,
			SRM_CLIENT_ENTITIES_SEQ_ID2
	 )
	 VALUES
	 (
			@FROM_ENTITIES_SEQ_ID,
			@TO_ENTITIES_SEQ_ID,
			@FROM_CLIENT_ENTITIES_SEQ_ID,
			@TO_CLIENT_ENTITIES_SEQ_ID
	 )


DECLARE @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID_1 BIGINT

DECLARE CUR_VIEWS CURSOR FOR 
	SELECT SEQ_ID FROM SRM_CLIENT_FILTER_VIEWS 
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @TO_CLIENT_ENTITIES_SEQ_ID

-- FILTER_VIEW_TYPE_ID = 4 AND SYSTEM_NAME LIKE '%All_Chairmen%' AND SRM_CLIENT_ENTITIES_SEQ_ID IN (SELECT SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)
OPEN CUR_VIEWS

FETCH NEXT FROM CUR_VIEWS INTO @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID_1
WHILE @@FETCH_STATUS = 0
BEGIN
	DELETE FROM SRM_CLIENT_FILTER_VIEW_BUTTONS WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID_1 
	DELETE FROM SRM_CLIENT_FILTER_VIEW_CRITERIA WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID_1 
	DELETE FROM SRM_CLIENT_FILTER_VIEW_DEFAULT WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID_1 
	DELETE FROM SRM_CLIENT_FILTER_VIEW_ATTRIBUTES WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID_1 
	DELETE FROM SRM_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 35 AND OBJECT_ID = @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID_1
	DELETE FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 35 AND OBJECT_ID = @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID_1
	DELETE FROM SRM_CLIENT_FILTER_VIEWS WHERE SEQ_ID = @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID_1

	FETCH NEXT FROM CUR_VIEWS INTO @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID_1
END
CLOSE CUR_VIEWS
DEALLOCATE CUR_VIEWS

DECLARE @NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_1 BIGINT
DECLARE CUR_ATTR_GROUPS CURSOR FOR 
		SELECT SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS 
		WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @TO_CLIENT_ENTITIES_SEQ_ID

	OPEN CUR_ATTR_GROUPS

	FETCH NEXT FROM CUR_ATTR_GROUPS INTO @NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_1
	WHILE @@FETCH_STATUS = 0
	BEGIN
		DELETE FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS WHERE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID = @NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_1 
		DELETE FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SEQ_ID = @NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_1

		FETCH NEXT FROM CUR_ATTR_GROUPS INTO @NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_1
	END
CLOSE CUR_ATTR_GROUPS
DEALLOCATE CUR_ATTR_GROUPS

	DECLARE CUR_ALL_CLIENT_ENTITIES_LISTS CURSOR STATIC FOR
	SELECT SRM_ENTITIES.SEQ_ID, SRM_CLIENT_ENTITIES.SEQ_ID, SYSTEM_ENTITY , SRM_CLIENT_ENTITIES.ENTITY_DISPLAY_NAME FROM SRM_ENTITIES, SRM_CLIENT_ENTITIES WHERE SRM_ENTITIES.SEQ_ID = SRM_CLIENT_ENTITIES.SRM_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID
	OPEN CUR_ALL_CLIENT_ENTITIES_LISTS 
	FETCH NEXT FROM CUR_ALL_CLIENT_ENTITIES_LISTS INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY , @ENTITY_DISPLAY_NAME
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
	SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = SEQ_ID ,@NEW_SRM_ENTITIES_SEQ_ID = SRM_ENTITIES_SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME AND SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID
	INSERT INTO @TEMP_ENTITY_CLIENT_ENTITY_TABLE
		(
			SRM_ENTITIES_SEQ_ID,
			SRM_ENTITIES_SEQ_ID2,
			SRM_CLIENT_ENTITIES_SEQ_ID,
			SRM_CLIENT_ENTITIES_SEQ_ID2
		)
		VALUES
		(
			@SRM_ENTITIES_SEQ_ID,
			@NEW_SRM_ENTITIES_SEQ_ID,
			@SRM_CLIENT_ENTITIES_SEQ_ID,
			@NEW_SRM_CLIENT_ENTITIES_SEQ_ID
		)

		FETCH NEXT FROM CUR_ALL_CLIENT_ENTITIES_LISTS INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY , @ENTITY_DISPLAY_NAME
		END

		CLOSE CUR_ALL_CLIENT_ENTITIES_LISTS 
		DEALLOCATE CUR_ALL_CLIENT_ENTITIES_LISTS



 --	DECLARE CUR_RELATED_LISTS CURSOR STATIC FOR
	--SELECT SRM_CLIENT_ENTITIES_SEQ_ID2 FROM SRM_CLIENT_ENTITY_RELATED_LISTS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @FROM_CLIENT_ENTITIES_SEQ_ID 

	--OPEN CUR_RELATED_LISTS 

	--FETCH NEXT FROM CUR_RELATED_LISTS INTO @OLD_SRM_CLIENT_ENTITIES_SEQ_ID2
	
	--WHILE @@FETCH_STATUS = 0
	--BEGIN
	--	SELECT @ENTITY_DISPLAY_NAME = ENTITY_DISPLAY_NAME FROM SRM_CLIENT_ENTITIES WHERE SEQ_ID = @OLD_SRM_CLIENT_ENTITIES_SEQ_ID2

	--	SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID2 = SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME AND SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID

	--	     INSERT INTO @TEMP_ENTITY_CLIENT_ENTITY_TABLE
	--		 (
	--				SRM_CLIENT_ENTITIES_SEQ_ID,
	--				SRM_CLIENT_ENTITIES_SEQ_ID2
	--		 )
	--		 VALUES
	--		 (
	--				@OLD_SRM_CLIENT_ENTITIES_SEQ_ID2,
	--				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID2
	--		 )

	--	FETCH NEXT FROM CUR_RELATED_LISTS INTO @OLD_SRM_CLIENT_ENTITIES_SEQ_ID2
	--	END

	--	CLOSE CUR_RELATED_LISTS 
	--	DEALLOCATE CUR_RELATED_LISTS


	DECLARE CUR_ENTITIES CURSOR STATIC FOR
	SELECT SRM_ENTITIES.SEQ_ID, SRM_CLIENT_ENTITIES.SEQ_ID, ISNULL(SYSTEM_ENTITY, 'N') FROM SRM_ENTITIES, SRM_CLIENT_ENTITIES WHERE SRM_ENTITIES.SEQ_ID = SRM_CLIENT_ENTITIES.SRM_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITIES.SEQ_ID = @FROM_CLIENT_ENTITIES_SEQ_ID

	OPEN CUR_ENTITIES 

	FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SELECT @NEW_SRM_ENTITIES_SEQ_ID = SRM_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_ENTITIES_SEQ_ID = @SRM_ENTITIES_SEQ_ID
		SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

		DECLARE CUR_ATTRIBUTES CURSOR STATIC FOR
		SELECT SRM_ENTITY_ATTRIBUTES.SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES.SEQ_ID, SYSTEM_ATTRIBUTE ,SRM_CLIENT_ENTITY_ATTRIBUTES.ATTRIBUTE_DISPLAY_NAME  FROM SRM_ENTITY_ATTRIBUTES, SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_ENTITY_ATTRIBUTES.SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_ENTITY_ATTRIBUTES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

		OPEN CUR_ATTRIBUTES 

		FETCH NEXT FROM CUR_ATTRIBUTES INTO @SRM_ENTITY_ATTRIBUTES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @SYSTEM_ATTRIBUTE ,@ATTRIBUTE_DISPLAY_NAME

		WHILE @@FETCH_STATUS = 0
		BEGIN
			IF @SYSTEM_ENTITY = 'Y' AND @SYSTEM_ATTRIBUTE = 'Y'
			BEGIN
				SET @NEW_SRM_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_ENTITY_ATTRIBUTES_SEQ_ID
			END
			ELSE
			BEGIN
			  SELECT @NEW_SRM_ENTITY_ATTRIBUTES_SEQ_ID = SRM_ENTITY_ATTRIBUTES.SEQ_ID,@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SEQ_ID  FROM SRM_ENTITY_ATTRIBUTES, SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_ENTITY_ATTRIBUTES.SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_ENTITY_ATTRIBUTES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_CLIENT_ENTITIES_SEQ_ID = @TO_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES.ATTRIBUTE_DISPLAY_NAME = @ATTRIBUTE_DISPLAY_NAME
			END
			INSERT INTO @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE
				(SRM_ENTITIES_SEQ_ID,
				SRM_ENTITIES_SEQ_ID2,
				SRM_CLIENT_ENTITIES_SEQ_ID,
				SRM_CLIENT_ENTITIES_SEQ_ID2,
				SRM_ENTITY_ATTRIBUTES_SEQ_ID,
				SRM_ENTITY_ATTRIBUTES_SEQ_ID2,
				SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
				SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2
			)
			VALUES
			(
				@FROM_ENTITIES_SEQ_ID,
				@TO_ENTITIES_SEQ_ID,
				@FROM_CLIENT_ENTITIES_SEQ_ID,
				@TO_CLIENT_ENTITIES_SEQ_ID,
				@SRM_ENTITY_ATTRIBUTES_SEQ_ID,
				@NEW_SRM_ENTITY_ATTRIBUTES_SEQ_ID,
				@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
				@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
			)
			FETCH NEXT FROM CUR_ATTRIBUTES INTO @SRM_ENTITY_ATTRIBUTES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @SYSTEM_ATTRIBUTE ,@ATTRIBUTE_DISPLAY_NAME
		END
		CLOSE CUR_ATTRIBUTES 
		DEALLOCATE CUR_ATTRIBUTES


	    DECLARE @CONTENT_SOURCE XML
		DECLARE CUR_CLIENT_ENTITY_BUTTONS CURSOR STATIC FOR
		SELECT SEQ_ID, CONTENT_SOURCE , SRM_BUTTON_TYPES_SEQ_ID FROM SRM_CLIENT_ENTITY_BUTTONS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND (SRM_USERS_SEQ_ID IS NULL OR SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID)
		
		OPEN CUR_CLIENT_ENTITY_BUTTONS 

		FETCH NEXT FROM CUR_CLIENT_ENTITY_BUTTONS INTO @SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID, @CONTENT_SOURCE , @SRM_BUTTON_TYPES_SEQ_ID

		WHILE @@FETCH_STATUS = 0
		BEGIN
			
		SELECT @NEW_SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID = SEQ_ID FROM SRM_CLIENT_ENTITY_BUTTONS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @TO_CLIENT_ENTITIES_SEQ_ID AND (SRM_USERS_SEQ_ID IS NULL OR SRM_USERS_SEQ_ID = @TO_SRM_USERS_SEQ_ID) AND SRM_BUTTON_TYPES_SEQ_ID = @SRM_BUTTON_TYPES_SEQ_ID
		  
			INSERT INTO @TEMP_ENTITY_BUTTONS
			(
				SRM_ENTITIES_SEQ_ID,
				SRM_ENTITIES_SEQ_ID2,
				SRM_CLIENT_ENTITIES_SEQ_ID,
				SRM_CLIENT_ENTITIES_SEQ_ID2,
				SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID,
				SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID2
			)
			VALUES
			(
				@SRM_ENTITIES_SEQ_ID,
				@NEW_SRM_ENTITIES_SEQ_ID,
				@SRM_CLIENT_ENTITIES_SEQ_ID,
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID,
				@SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID,
				@NEW_SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID
			)

			FETCH NEXT FROM CUR_CLIENT_ENTITY_BUTTONS INTO @SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID, @CONTENT_SOURCE , @SRM_BUTTON_TYPES_SEQ_ID
		END

		CLOSE CUR_CLIENT_ENTITY_BUTTONS 
		DEALLOCATE CUR_CLIENT_ENTITY_BUTTONS 

		FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY
		END

		CLOSE CUR_ENTITIES 
		DEALLOCATE CUR_ENTITIES

    -- REST OF THE TABLES

	DECLARE CUR_ENTITIES CURSOR STATIC FOR
	SELECT SRM_ENTITIES.SEQ_ID, SRM_CLIENT_ENTITIES.SEQ_ID, SYSTEM_ENTITY FROM SRM_ENTITIES, SRM_CLIENT_ENTITIES WHERE SRM_ENTITIES.SEQ_ID = SRM_CLIENT_ENTITIES.SRM_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITIES.SEQ_ID = @FROM_CLIENT_ENTITIES_SEQ_ID

	OPEN CUR_ENTITIES 

	FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SELECT @NEW_SRM_ENTITIES_SEQ_ID = SRM_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_ENTITIES_SEQ_ID = @SRM_ENTITIES_SEQ_ID
		SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

		DECLARE CUR_ATTRIBUTE_GROUPS CURSOR STATIC FOR
		SELECT SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS.SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS 
		WHERE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND 
			(SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS.SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID
			OR (SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS.SRM_USERS_SEQ_ID IS NULL 
			AND SRM_CLIENT_ENTITIES_SEQ_ID NOT IN (SELECT SRM_CLIENT_ENTITIES_SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS.SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID)))
		
		OPEN CUR_ATTRIBUTE_GROUPS 

		FETCH NEXT FROM CUR_ATTRIBUTE_GROUPS INTO @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID

		WHILE @@FETCH_STATUS = 0
		BEGIN		
			INSERT INTO SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS
			(
				SRM_CLIENT_ENTITIES_SEQ_ID,
				SRM_USERS_SEQ_ID,
				SYSTEM_NAME,
				GROUP_RANK,
				GROUP_TYPE_ID,
				NAVIGATION_SEQUENCE_ID,
				NUMBER_OF_COLUMNS,
				DISPLAY_ON_EDIT,
				DISPLAY_ON_DETAIL,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID,
				NULL,
				SYSTEM_NAME,
				GROUP_RANK,
				GROUP_TYPE_ID,
				NAVIGATION_SEQUENCE_ID,
				NUMBER_OF_COLUMNS,
				DISPLAY_ON_EDIT,
				DISPLAY_ON_DETAIL,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL
			FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID

			SET @NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID = @@IDENTITY

			INSERT INTO SRM_CLIENT_LANGUAGE_ITEMS
			(
				SRM_LANGUAGES_SEQ_ID,
				SRM_CLIENTS_SEQ_ID,
				OBJECT_ID,
				OBJECT_TYPE,
				SRM_LANGUAGE_TOKENS_SEQ_ID,
				PHRASE,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				SRM_LANGUAGES_SEQ_ID,
				@TO_SRM_CLIENTS_SEQ_ID,
				@NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID,
				OBJECT_TYPE,
				SRM_LANGUAGE_TOKENS_SEQ_ID,
				PHRASE,
				NULL, --SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL			
			FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 11 AND SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND OBJECT_ID = @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID 

			INSERT INTO SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS
			(
