	-- SRM_CLIENT_ENTITY_LOOKUP_FILTERS
DECLARE @TAB NVARCHAR(2), @LF NVARCHAR(2), @CR NVARCHAR(2),@NL VARCHAR(2)
SET @TAB = CHAR(9)
SET @LF = CHAR(10)
SET @CR = CHAR(13)
SET @NL = CHAR(13)+CHAR(10)
DECLARE CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS CURSOR STATIC FOR
SELECT SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID FROM SRM_CLIENT_ENTITY_LOOKUP_FILTERS scelf 
WHERE scelf.SRM_CLIENT_ENTITIES_SEQ_ID = @FROM_CLIENT_ENTITIES_SEQ_ID

OPEN CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS 

FETCH NEXT FROM CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS INTO @SRM_CLIENT_ENTITY_LOOKUP_FILTERS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

WHILE @@FETCH_STATUS = 0
BEGIN

DECLARE @JSONHierarchy JSONHierarchy 
	DECLARE @FILTER_CRITERIA NVARCHAR(max)
	DECLARE @SELECT_FIELDS NVARCHAR(max)
	DECLARE @FILTER_CRITERIA_ATTRIBUTES_LOGIC NVARCHAR(2000)


	SELECT @CREATED_BY = LOGIN_USER_NAME FROM [SRM-Framework_New].dbo.SRM_USERS where SEQ_ID = @TO_SRM_USERS_SEQ_ID
	SET @DATE_CREATED = GETDATE()

	SELECT 
	@FILTER_CRITERIA = FILTER_CRITERIA, 
	@SELECT_FIELDS = SELECT_FIELDS, 
	@FILTER_CRITERIA_ATTRIBUTES_LOGIC = FILTER_CRITERIA_ATTRIBUTES_LOGIC 
	FROM SRM_CLIENT_ENTITY_LOOKUP_FILTERS WHERE SEQ_ID = @SRM_CLIENT_ENTITY_LOOKUP_FILTERS_SEQ_ID 

	-- Update SRM_CLIENT_ENTITIES_SEQ_ID and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID in JSON object of FILTER_CRITERIA
	SET @FILTER_CRITERIA = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@FILTER_CRITERIA)), @TAB,''), @NL,''), @LF,''), @CR,''),' ','')
	DELETE FROM @JSONHierarchy
	INSERT INTO @JSONHierarchy SELECT * FROM dbo.parseJSON(@FILTER_CRITERIA) 
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = h.StringValue AND h.Name = 'entityId'
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = h.StringValue AND h.Name = 'attributeId' AND h.StringValue != 'SEQ_ID'
	SELECT @FILTER_CRITERIA = dbo.ToJSON(@JSONHierarchy)
	SET @FILTER_CRITERIA = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@FILTER_CRITERIA)), @TAB,''), @NL,''), @LF,''), @CR,''),' ','')

	-- Update SRM_CLIENT_ENTITIES_SEQ_ID and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID in JSON object of SELECT_FIELDS
	SET @SELECT_FIELDS = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@SELECT_FIELDS)), @TAB,''), @NL,''), @LF,''), @CR,''),' ','')
	DELETE FROM @JSONHierarchy
	INSERT INTO @JSONHierarchy SELECT * FROM dbo.parseJSON(@SELECT_FIELDS)
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = h.StringValue AND h.Name = 'entityId'
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = h.StringValue AND h.Name = 'attributeId' AND h.StringValue != 'SEQ_ID'
	SELECT @SELECT_FIELDS = dbo.ToJSON(@JSONHierarchy)
	SET @SELECT_FIELDS = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@SELECT_FIELDS)), @TAB,''), @NL,''), @LF,''), @CR,''),' ','')

	-- Update SRM_CLIENT_ENTITIES_SEQ_ID and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID in JSON object of FILTER_CRITERIA_ATTRIBUTES_LOGIC
	SET @FILTER_CRITERIA_ATTRIBUTES_LOGIC = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@FILTER_CRITERIA_ATTRIBUTES_LOGIC)), @TAB,''), @NL,''), @LF,''), @CR,''),' ',''),'AND',' AND '),'OR',' OR ')
	DELETE FROM @JSONHierarchy
	INSERT INTO @JSONHierarchy SELECT * FROM dbo.parseJSON(@FILTER_CRITERIA_ATTRIBUTES_LOGIC)
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = h.StringValue AND h.Name = 'entityId'
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = h.StringValue AND h.Name = 'attributeId' AND h.StringValue != 'SEQ_ID'
	SELECT @FILTER_CRITERIA_ATTRIBUTES_LOGIC = dbo.ToJSON(@JSONHierarchy)
	SET @FILTER_CRITERIA_ATTRIBUTES_LOGIC = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@FILTER_CRITERIA_ATTRIBUTES_LOGIC)), @TAB,''), @NL,''), @LF,''), @CR,''),' ',''),'AND',' AND '),'OR',' OR ')

	INSERT INTO dbo.SRM_CLIENT_ENTITY_LOOKUP_FILTERS
	        ( SYSTEM_NAME ,
	          SRM_CLIENT_ENTITIES_SEQ_ID ,
	          SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID ,
	          RANK ,
	          FILTER_TYPE_ID ,
	          FILTER_HTML ,
	          FILTER_CRITERIA ,
	          SELECT_FIELDS ,
	          FILTER_CRITERIA_ATTRIBUTES_LOGIC ,
	          SOURCE_OF_DATA ,
	          SOURCE_FILE ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  SYSTEM_NAME ,
	        (SELECT SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID) ,
	        (SELECT SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID) ,
	        RANK ,
	        FILTER_TYPE_ID ,
	        FILTER_HTML ,
	        @FILTER_CRITERIA ,
	        @SELECT_FIELDS ,
	        @FILTER_CRITERIA_ATTRIBUTES_LOGIC ,
	        SOURCE_OF_DATA ,
	        SOURCE_FILE ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        @DATE_CREATED ,
	        @CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY FROM dbo.SRM_CLIENT_ENTITY_LOOKUP_FILTERS AS scelf
			WHERE SEQ_ID = @SRM_CLIENT_ENTITY_LOOKUP_FILTERS_SEQ_ID

	FETCH NEXT FROM CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS INTO @SRM_CLIENT_ENTITY_LOOKUP_FILTERS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
END

CLOSE CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS 
DEALLOCATE CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS


SET @DESCRIPTION = 'Features are successfully replicated'
END






;





-- =============================================
-- Author:  <ASAD>
-- Create date: <14/08/2013,,>
-- Description: <Apply Area of Focus Data to Web service Area of FocusE
-- EXEC [dbo].[COPY_SINGLE_WORKFLOW] 36,21,8129,65,'' ,'N'
-- =============================================
CREATE PROCEDURE  [dbo].[COPY_SINGLE_WORKFLOW] 
	 @FROM_SRM_CLIENTS_SEQ_ID BIGINT,
	 @TO_SRM_CLIENTS_SEQ_ID BIGINT,
	 @FROM_WORKFLOW_SEQ_ID BIGINT,
	 @TO_SRM_USERS_SEQ_ID BIGINT,
	 @WORKFLOW_DESCRIPTION NVARCHAR(200) = NULL,
	 @ISNORMALREP NVARCHAR(100),
	 @NEW_WORKFLOW_SEQ_ID BIGINT = NULL OUTPUT
 AS 
 BEGIN
  
	SET NOCOUNT ON;
	
	DECLARE @WFL_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @NEW_WORKFLOWS_SEQ_ID BIGINT 
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
  	DECLARE @NEW_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
	DECLARE @WFL_TASKS_SEQ_ID BIGINT  
	DECLARE @NEW_WFL_TASKS_SEQ_ID BIGINT
	DECLARE @WFL_NEXT_TASK_SEQ_ID BIGINT
	DECLARE @NEW_WFL_NEXT_TASK_SEQ_ID BIGINT  
	DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT 
	DECLARE @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT  
	DECLARE @WFL_VARIABLES_SEQ_ID BIGINT
	DECLARE @WFL_TASK_DETAILS_SEQ_ID BIGINT  
	DECLARE @WFL_TASK_CONDITIONS_SEQ_ID BIGINT  
	DECLARE @NEW_WFL_TASK_CONDITIONS_SEQ_ID BIGINT  
	DECLARE @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID BIGINT
	DECLARE @WFL_MAPPINGS_SEQ_ID BIGINT
	DECLARE @WFL_SCHEDULES_SEQ_ID BIGINT
	DECLARE @WFL_MAILMERGE_TEMPLATES_SEQ_ID BIGINT  	
	DECLARE @TASK_EXPRESSION XML  
	DECLARE @CREATED_BY NVARCHAR(100)
	DECLARE @DATE_CREATED DATETIME

	DECLARE @NEXT_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @NEXT_WORKFLOW_DESCRIPTION NVARCHAR(200)
	DECLARE @GENERATED_NEXT_WORKFLOWS_SEQ_ID BIGINT 
	DECLARE @RE_SEQ_ID BIGINT 


	DECLARE @TEMP_WFL_TASK_CONDITIONS_TABLE TABLE
	(
		WFL_TASK_CONDITIONS_SEQ_ID BIGINT,
		WFL_TASK_CONDITIONS_SEQ_ID2 BIGINT
	)  

	DECLARE @TEMP_WFL_TASKS_TABLE TABLE
	(
		WFL_TASKS_SEQ_ID BIGINT,
		WFL_TASKS_SEQ_ID2 BIGINT
	)

	SET @CREATED_BY = 'Copy-User'
	SELECT @CREATED_BY = LOGIN_USER_NAME FROM [SRM-Framework_New].dbo.SRM_USERS WHERE SEQ_ID = @TO_SRM_USERS_SEQ_ID
	SET @DATE_CREATED = GETDATE()
	
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITY_SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOWS WHERE SEQ_ID = @FROM_WORKFLOW_SEQ_ID

		IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NOT NULL
		BEGIN  
			SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = sec2.SEQ_ID
			FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES sec1, 
			[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES sec2
			where sec1.ENTITY_DISPLAY_NAME = sec2.ENTITY_DISPLAY_NAME AND sec1.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID
			AND sec2.SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID AND sec1.SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
		END 
		ELSE
			SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = NULL  	
			INSERT INTO [SRM-Workflow].dbo.WFL_WORKFLOWS
				( DESCRIPTION ,
					SRM_CLIENT_ENTITY_SEQ_ID ,
					EXPRESSION ,
					REMARKS ,
					SRM_CLIENTS_SEQ_ID ,
					DIAGRAM_XML,
					DIAGRAM_DETAIL,
					SHOW_IN_JOBS,
					OUTPUT_FILENAME,
					DO_NOT_USE_QUOTE,
					IS_ASYNC,
					SHOW_ON_QUERYBUILDER,
					TRACKABLE,
					SHOW_NOTIFICATION,
					SOURCE_OF_DATA ,
					SOURCE_FILE ,
					DATE_MODIFIED ,
					MODIFIED_BY ,
					DATE_CREATED ,
					CREATED_BY ,
					DELETED ,
					DATE_DELETED ,
					DELETED_BY
				)
		SELECT  DESCRIPTION ,
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID ,
				EXPRESSION ,
				REMARKS ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				DIAGRAM_XML,
				DIAGRAM_DETAIL,
				SHOW_IN_JOBS,
				OUTPUT_FILENAME,
				DO_NOT_USE_QUOTE,
				IS_ASYNC,
				SHOW_ON_QUERYBUILDER,
				TRACKABLE,
				SHOW_NOTIFICATION,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_WORKFLOWS	WHERE SEQ_ID = @FROM_WORKFLOW_SEQ_ID
		--SELECT @NEW_WORKFLOWS_SEQ_ID = MAX(SEQ_ID) FROM [SRM-Workflow].dbo.WFL_WORKFLOWS 

		SET @NEW_WORKFLOWS_SEQ_ID = SCOPE_IDENTITY()
	
	-- WFL_WORKFLOW_STARTING_OPTIONS
	DECLARE CUR_WFL_WORKFLOW_STARTING_OPTIONS CURSOR LOCAL FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID
	
	OPEN CUR_WFL_WORKFLOW_STARTING_OPTIONS 

	FETCH NEXT FROM CUR_WFL_WORKFLOW_STARTING_OPTIONS INTO @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS
				( WFL_WORKFLOWS_SEQ_ID ,
				  START_WHEN_ID ,
				  REMARKS ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID ,
				START_WHEN_ID ,
				REMARKS ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				NULL ,
				NULL 
		FROM [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS WHERE SEQ_ID = @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_WORKFLOW_STARTING_OPTIONS INTO @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID
	END

	CLOSE CUR_WFL_WORKFLOW_STARTING_OPTIONS 
	DEALLOCATE CUR_WFL_WORKFLOW_STARTING_OPTIONS


	-- WFL_TASKS
	DECLARE CUR_WFL_TASKS CURSOR LOCAL FOR
	SELECT SEQ_ID, SRM_CLIENT_ENTITY_SEQ_ID, WFL_TASKS_SEQ_ID ,WFL_WORKFLOWS_SEQ_ID2  FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE 
	wt.WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC


	OPEN CUR_WFL_TASKS 

	FETCH NEXT FROM CUR_WFL_TASKS INTO @WFL_TASKS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID ,@NEXT_WORKFLOWS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--Get new client entity ID	
		IF 	@SRM_CLIENT_ENTITIES_SEQ_ID IS NOT NULL
		BEGIN
			SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = sec2.SEQ_ID
			FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES sec1, 
			[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES sec2
			WHERE sec1.ENTITY_DISPLAY_NAME = sec2.ENTITY_DISPLAY_NAME AND sec1.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID
			AND sec2.SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID AND sec1.SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
		END 
		ELSE
			SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = NULL 
		
		IF @NEXT_WORKFLOWS_SEQ_ID IS NOT NULL OR @NEXT_WORKFLOWS_SEQ_ID > 0 AND @ISNORMALREP = 'N'
		BEGIN
			SELECT @NEXT_WORKFLOW_DESCRIPTION = [DESCRIPTION] FROM [SRM-Workflow].dbo.WFL_WORKFLOWS  WHERE SEQ_ID = @NEXT_WORKFLOWS_SEQ_ID
			SELECT @GENERATED_NEXT_WORKFLOWS_SEQ_ID = SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOWS  WHERE [DESCRIPTION] = @NEXT_WORKFLOW_DESCRIPTION AND  SRM_CLIENTS_SEQ_ID= @TO_SRM_CLIENTS_SEQ_ID
			IF @GENERATED_NEXT_WORKFLOWS_SEQ_ID IS NULL OR @GENERATED_NEXT_WORKFLOWS_SEQ_ID <= 0
			BEGIN
				EXEC [dbo].[COPY_SINGLE_WORKFLOW]
							@FROM_SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID,
							@TO_SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID,
							@FROM_WORKFLOW_SEQ_ID= @NEXT_WORKFLOWS_SEQ_ID,
							@TO_SRM_USERS_SEQ_ID = @TO_SRM_USERS_SEQ_ID,
							@WORKFLOW_DESCRIPTION = NULL,
							@ISNORMALREP = @ISNORMALREP,						
							@NEW_WORKFLOW_SEQ_ID = @RE_SEQ_ID OUTPUT	
							
							SET @GENERATED_NEXT_WORKFLOWS_SEQ_ID =@NEW_WORKFLOW_SEQ_ID				
			END
		END 
		ELSE
			SET @GENERATED_NEXT_WORKFLOWS_SEQ_ID = NULL
		
			

		INSERT INTO [SRM-Workflow].dbo.WFL_TASKS
				( WFL_WORKFLOWS_SEQ_ID ,
				  TASK_TYPE_ID ,
				  SRM_CLIENT_ENTITY_SEQ_ID ,
				  WFL_WORKFLOWS_SEQ_ID2 ,
				  WFL_TASKS_SEQ_ID ,
				  STARTING_TASK ,
				  ENDING_TASK ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				  
				)
		SELECT @NEW_WORKFLOWS_SEQ_ID,
				TASK_TYPE_ID ,
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID ,
				@GENERATED_NEXT_WORKFLOWS_SEQ_ID ,
				NULL, --WFL_TASKS_SEQ_ID,
				STARTING_TASK ,
				ENDING_TASK ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				WFL_TASKS_SEQ_ID ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_TASKS wt
		WHERE SEQ_ID = @WFL_TASKS_SEQ_ID
		
		SELECT @NEW_WFL_TASKS_SEQ_ID = MAX(SEQ_ID) FROM [SRM-Workflow].dbo.WFL_TASKS

		INSERT INTO @TEMP_WFL_TASKS_TABLE
		(WFL_TASKS_SEQ_ID, WFL_TASKS_SEQ_ID2)
		VALUES 
		(@WFL_TASKS_SEQ_ID, @NEW_WFL_TASKS_SEQ_ID)

		FETCH NEXT FROM CUR_WFL_TASKS INTO @WFL_TASKS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID , @NEXT_WORKFLOWS_SEQ_ID
	END

	CLOSE CUR_WFL_TASKS 
	DEALLOCATE CUR_WFL_TASKS 
	
	SELECT * FROM @TEMP_WFL_TASKS_TABLE
	-- TASK UPDATER
	DECLARE CUR_WFL_TASKS_UPDATER CURSOR LOCAL FOR
	SELECT SEQ_ID, SOURCE_OF_DATA FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE 
	wt.WFL_WORKFLOWS_SEQ_ID = @NEW_WORKFLOWS_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASKS_UPDATER 

	FETCH NEXT FROM CUR_WFL_TASKS_UPDATER INTO @WFL_TASKS_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF @WFL_NEXT_TASK_SEQ_ID IS NOT NULL
			SET @NEW_WFL_NEXT_TASK_SEQ_ID = (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = @WFL_NEXT_TASK_SEQ_ID)
		ELSE
			SET @NEW_WFL_NEXT_TASK_SEQ_ID = NULL 

		UPDATE [SRM-Workflow].dbo.WFL_TASKS
		SET WFL_TASKS_SEQ_ID = @NEW_WFL_NEXT_TASK_SEQ_ID
		WHERE SEQ_ID = @WFL_TASKS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_TASKS_UPDATER INTO @WFL_TASKS_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID
	END

	CLOSE CUR_WFL_TASKS_UPDATER 
	DEALLOCATE CUR_WFL_TASKS_UPDATER 

		-- WFL_VARIABLES
	DECLARE CUR_WFL_VARIABLES CURSOR LOCAL FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_VARIABLES AS wv 
	WHERE wv.WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_VARIABLES 

	FETCH NEXT FROM CUR_WFL_VARIABLES INTO @WFL_VARIABLES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_VARIABLES
				( WFL_WORKFLOWS_SEQ_ID ,
				  VARIABLE_NAME ,
				  VARIABLE_TYPE_ID ,
				  EXPRESSION ,
				  REMARKS ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID,
				VARIABLE_NAME ,
				VARIABLE_TYPE_ID ,
				EXPRESSION ,
				REMARKS ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_VARIABLES AS wv
		WHERE SEQ_ID = @WFL_VARIABLES_SEQ_ID

		FETCH NEXT FROM CUR_WFL_VARIABLES INTO @WFL_VARIABLES_SEQ_ID
	END

	CLOSE CUR_WFL_VARIABLES 
	DEALLOCATE CUR_WFL_VARIABLES


	--WFL_TASK_CONDITIONS
	DECLARE CUR_WFL_TASK_CONDITIONS CURSOR LOCAL FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS WHERE 
	WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID) ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASK_CONDITIONS 

	FETCH NEXT FROM CUR_WFL_TASK_CONDITIONS INTO @WFL_TASK_CONDITIONS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_TASK_CONDITIONS
				( WFL_TASKS_SEQ_ID ,
				  WFL_TASKS_SEQ_ID2 ,
				  RANK ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtc.WFL_TASKS_SEQ_ID) ,
				(SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtc.WFL_TASKS_SEQ_ID2) ,
				RANK ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS wtc
		WHERE SEQ_ID = @WFL_TASK_CONDITIONS_SEQ_ID

		SELECT @NEW_WFL_TASK_CONDITIONS_SEQ_ID = MAX(SEQ_ID) FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS


		INSERT INTO @TEMP_WFL_TASK_CONDITIONS_TABLE
		(WFL_TASK_CONDITIONS_SEQ_ID, WFL_TASK_CONDITIONS_SEQ_ID2)
		VALUES
		(@WFL_TASK_CONDITIONS_SEQ_ID, @NEW_WFL_TASK_CONDITIONS_SEQ_ID)  

		FETCH NEXT FROM CUR_WFL_TASK_CONDITIONS INTO @WFL_TASK_CONDITIONS_SEQ_ID
	END

	CLOSE CUR_WFL_TASK_CONDITIONS 
	DEALLOCATE CUR_WFL_TASK_CONDITIONS



	-- WFL_TASK_DETAILS
	DECLARE @Node BIGINT
	DECLARE @ATTRIB_COUNTER BIGINT

	DECLARE CUR_WFL_TASK_DETAILS CURSOR LOCAL FOR
	SELECT wtd.SEQ_ID, EXPRESSION, wt.SRM_CLIENT_ENTITY_SEQ_ID 
	FROM [SRM-Workflow].dbo.WFL_TASK_DETAILS AS wtd 
	INNER JOIN [SRM-Workflow].dbo.WFL_TASKS wt ON wtd.WFL_TASKS_SEQ_ID = wt.SEQ_ID
	WHERE wtd.WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID) ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASK_DETAILS 

	FETCH NEXT FROM CUR_WFL_TASK_DETAILS INTO @WFL_TASK_DETAILS_SEQ_ID, @TASK_EXPRESSION, @SRM_CLIENT_ENTITIES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Node = 1
		SET @ATTRIB_COUNTER = (SELECT COUNT(attrib.value('(SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID)[1]', 'bigint')) FROM @TASK_EXPRESSION.nodes('/QUERY/CRITERIA_ATTRIBUTES') as EMP(attrib))

		WHILE @Node <= @ATTRIB_COUNTER
		BEGIN
			SET @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0
			SET @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = (SELECT @TASK_EXPRESSION.value('(//QUERY/CRITERIA_ATTRIBUTES[sql:variable("@Node")]/SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID/node())[1]', 'varchar(max)')) 

			SELECT @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = sea2.SEQ_ID
			FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES sec1, 
			[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES sec2, 
			[SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES sea1, 
			[SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES sea2
			where sec1.ENTITY_DISPLAY_NAME = sec2.ENTITY_DISPLAY_NAME AND sec1.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID
			AND sec2.SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID AND sec1.SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
			AND sec1.SEQ_ID = sea1.SRM_CLIENT_ENTITIES_SEQ_ID AND sec2.SEQ_ID = sea2.SRM_CLIENT_ENTITIES_SEQ_ID 
			AND sea1.ATTRIBUTE_DISPLAY_NAME = sea2.ATTRIBUTE_DISPLAY_NAME AND sea1.SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

			IF(@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID != '' AND @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID > 0)
			BEGIN
				SET @TASK_EXPRESSION.modify('replace value of (//QUERY/CRITERIA_ATTRIBUTES[sql:variable("@Node")]/SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID/text())[1] with sql:variable("@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID")') 
			END

			SET @Node = @Node + 1
		END
IF (@TASK_EXPRESSION.exist('//QUERY/EMAIL_DETAILS') = 1)
	BEGIN
		SET @TASK_EXPRESSION.modify('replace value of (//QUERY/EMAIL_DETAILS/TO_ADDRESS/SOURCE_PROPERTY_VALUE/text())[1] with "stargetsupport@centrepoint.uk.com"')
		SET @TASK_EXPRESSION.modify('replace value of (//QUERY/EMAIL_DETAILS/CC_ADDRESS/SOURCE_PROPERTY_VALUE/text())[1] with ""')
		SET @TASK_EXPRESSION.modify('replace value of (//QUERY/EMAIL_DETAILS/BCC_ADDRESS/SOURCE_PROPERTY_VALUE/text())[1] with ""')

		SET @TASK_EXPRESSION.modify('replace value of (//QUERY/EMAIL_DETAILS/EMAIL_SUBJECT/SOURCE_PROPERTY_VALUE/text())[1] with ""') 
	END

INSERT INTO [SRM-Workflow].dbo.WFL_TASK_DETAILS
				( WFL_TASKS_SEQ_ID ,
				  WFL_TASK_CONDITIONS_SEQ_ID ,
				  DETAILS_TYPE_ID ,
				  EXPRESSION ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtd.WFL_TASKS_SEQ_ID) ,
				(SELECT WFL_TASK_CONDITIONS_SEQ_ID2 FROM @TEMP_WFL_TASK_CONDITIONS_TABLE WHERE WFL_TASK_CONDITIONS_SEQ_ID = wtd.WFL_TASK_CONDITIONS_SEQ_ID) ,
				DETAILS_TYPE_ID ,
				CONVERT(NVARCHAR(max), @TASK_EXPRESSION) ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_TASK_DETAILS wtd
		WHERE wtd.SEQ_ID = @WFL_TASK_DETAILS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_TASK_DETAILS INTO @WFL_TASK_DETAILS_SEQ_ID, @TASK_EXPRESSION, @SRM_CLIENT_ENTITIES_SEQ_ID
	END

	CLOSE CUR_WFL_TASK_DETAILS 
	DEALLOCATE CUR_WFL_TASK_DETAILS 

	-- WFL_MAILMERGE_TEMPLATES
	DECLARE CUR_WFL_MAILMERGE_TEMPLATES CURSOR LOCAL FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES AS wmt 
	WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_MAILMERGE_TEMPLATES 

	FETCH NEXT FROM CUR_WFL_MAILMERGE_TEMPLATES INTO @WFL_MAILMERGE_TEMPLATES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES
				( WFL_WORKFLOWS_SEQ_ID ,
				  TEMPLATE_TITLE ,
				  ATTACHMENT_URL ,
				  REMARKS ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID,
				TEMPLATE_TITLE ,
				ATTACHMENT_URL ,
				REMARKS ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES wmt
		WHERE SEQ_ID = @WFL_MAILMERGE_TEMPLATES_SEQ_ID

		FETCH NEXT FROM CUR_WFL_MAILMERGE_TEMPLATES INTO @WFL_MAILMERGE_TEMPLATES_SEQ_ID
	END

	CLOSE CUR_WFL_MAILMERGE_TEMPLATES 
	DEALLOCATE CUR_WFL_MAILMERGE_TEMPLATES


	-- WFL_MAPPINGS
	DECLARE CUR_WFL_MAPPINGS CURSOR LOCAL FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_MAPPINGS AS wm WHERE 
	WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_MAPPINGS 

	FETCH NEXT FROM CUR_WFL_MAPPINGS INTO @WFL_MAPPINGS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_MAPPINGS
				( WFL_WORKFLOWS_SEQ_ID ,
				  ATTRIBUTE_SYSTEM_NAME ,
				  ATTRIBUTE_DESCRIPTION ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID,
				ATTRIBUTE_SYSTEM_NAME ,
				ATTRIBUTE_DESCRIPTION ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_MAPPINGS AS wm
		WHERE SEQ_ID = @WFL_MAPPINGS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_MAPPINGS INTO @WFL_MAPPINGS_SEQ_ID
	END

	CLOSE CUR_WFL_MAPPINGS 
	DEALLOCATE CUR_WFL_MAPPINGS 


	-- WFL_SCHEDULES
	DECLARE CUR_WFL_SCHEDULES CURSOR LOCAL FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_SCHEDULES ws
	WHERE ws.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID

	OPEN CUR_WFL_SCHEDULES 

	FETCH NEXT FROM CUR_WFL_SCHEDULES INTO @WFL_SCHEDULES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_SCHEDULES
				( WFL_WORKFLOWS_SEQ_ID ,
				  SCHEDULE_START_DATE ,
				  SCHEDULE_NAME ,
				  SCHEDULE_TYPE_ID ,
				  INTERVAL_IN_DAYS ,
				  FREQUENCY_ID ,
				  FREQUENCY_COUNTER ,
				  TIME_OF_DAY ,
				  DAY_OF_MONTH ,
				  START_DATE ,
				  END_DATE ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID,
				SCHEDULE_START_DATE ,
				SCHEDULE_NAME ,
				SCHEDULE_TYPE_ID ,
				INTERVAL_IN_DAYS ,
				FREQUENCY_ID ,
				FREQUENCY_COUNTER ,
				TIME_OF_DAY ,
				DAY_OF_MONTH ,
				START_DATE ,
				END_DATE ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_SCHEDULES AS ws
		WHERE SEQ_ID = @WFL_SCHEDULES_SEQ_ID

		FETCH NEXT FROM CUR_WFL_SCHEDULES INTO @WFL_SCHEDULES_SEQ_ID
	END

	CLOSE CUR_WFL_SCHEDULES 
	DEALLOCATE CUR_WFL_SCHEDULES 

	
	SET @NEW_WORKFLOW_SEQ_ID = @NEW_WORKFLOWS_SEQ_ID 
END






;

