ww.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND
ww.SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE)

