CREATE PROCEDURE [dbo].[CREATE_DATABASE_FROM_LOG] 
-- Add the parameters for the stored procedure here	

AS
BEGIN
-- SET NOCOUNT ON added to prevent extra result sets from
-- interfering with SELECT statements.
SET NOCOUNT ON;

DECLARE @ClientId as bigint;
DECLARE @UserId as bigint;
DECLARE @SignupId as bigint;

--Sending email to user....
DECLARE @FromAddress AS VARCHAR(100);
DECLARE @ToAddress AS VARCHAR(100);
DECLARE @EmailSubject AS VARCHAR(500);
DECLARE @EmailBody AS VARCHAR(4000);
DECLARE @CustomerName AS VARCHAR(100);

SELECT TOP 1 @ClientId = SRM_CLIENT_SEQ_ID, @UserId = SRM_USER_SEQ_ID FROM SRM_SIGNUP_LOG WHERE STATUS = 'QUE'

IF(@ClientId> 0 AND @UserId > 0)
		BEGIN
				BEGIN TRY			

							UPDATE SRM_SIGNUP_LOG SET STATUS = 'WIP' WHERE SRM_CLIENT_SEQ_ID = @ClientId AND SRM_USER_SEQ_ID = @UserId 
							EXEC CREATE_NEW_CLIENT 72, @ClientId, 6114,  @UserId

							--EXEC CREATEDATAPIVOTFORNEWCLIENT @ClientId, '67', 'E:\Live-DB-SRM\', 'F:\Live-DB-SRM\'

							--SELECT @SignupId = CRM_CUSTOMERS_SEQ_ID FROM SRM_USERS WHERE SEQ_ID = @UserId

							--DECLARE @ModuleId VARCHAR(5)

							----------------------------------------------------------
							--					DECLARE @MyCursor CURSOR
							--					SET @MyCursor = CURSOR FAST_FORWARD
							--					FOR
							--					SELECT MODULE_ID FROM SRM_SYSTEM_MODULES WHERE SEQ_ID NOT IN (SELECT SEQ_ID FROM SRM_SIGNUP_SYSTEM_MODULES WHERE SRM_SIGNUPS_SEQ_ID =  @SignupId)
							--					OPEN @MyCursor
							--					FETCH NEXT FROM @MyCursor INTO @ModuleId
							--					WHILE @@FETCH_STATUS = 0
							--					BEGIN
							--					EXEC GET_HIDE_MODULE @ClientId, @ModuleId
 
							--					FETCH NEXT FROM @MyCursor INTO @ModuleId 
							--					END
							--					CLOSE @MyCursor
							--					DEALLOCATE @MyCursor

							--EXEC GET_SHOW_MODULE

							SELECT @ToAddress = LOGIN_EMAIL, @CustomerName = FIRST_NAME FROM SRM_USERS WHERE SEQ_ID = @UserId

							SELECT @EmailSubject = EMAIL_SUBJECT, @EmailBody = REPLACE(EMAIL_BODY, '##CUSTOMER_NAME##', @CustomerName) FROM  [SRM-OomiGoAdmin]..SRM_SYSTEM_EMAIL_TEMPLATES WHERE SEQ_ID = 4;
							EXEC INSERT_JAM_EMAIL 'noreply@oomi.co.uk', @ToAddress, @EmailBody, @EmailSubject, 1, 'NST';

							UPDATE SRM_SIGNUP_LOG SET STATUS = 'COMPL' WHERE SRM_CLIENT_SEQ_ID = @ClientId AND SRM_USER_SEQ_ID = @UserId
							UPDATE dbo.SRM_USERS SET SUPER_ADMIN = 'N' WHERE SRM_CLIENTS_SEQ_ID = @ClientId AND SEQ_ID = @UserId
				
					END TRY  
					BEGIN CATCH
					SET @EmailBody =  'There is an error in creation of client: ' + CAST(@ClientId as varchar(5)); 
					EXEC INSERT_JAM_EMAIL 'noreply@oomi.co.uk', 'zafar.mahmood@target.com.pk', @EmailBody , 'New client creation error', 1, 'NST';
					UPDATE SRM_SIGNUP_LOG SET STATUS = 'ERR' WHERE SRM_CLIENT_SEQ_ID = @ClientId AND SRM_USER_SEQ_ID = @UserId
					END CATCH
		END
END



;






-- EXEC [dbo].[CREATE_INVOICE_EXPORT_FILE_40]   

CREATE PROCEDURE [dbo].[CREATE_INVOICE_EXPORT_FILE_40]
@_JOB_ID BIGINT = 0
AS

--- RG_2020029_RG_Start Disabled on request of NI-10794
	Return
--- RG_2020029_RG_End

   DECLARE @Command NVARCHAR(1000)
   DECLARE @FileName As NVARCHAR(1000)
   DECLARE @ExternalRef NVARCHAR(50)
   DECLARE @InvoiceNo	NVARCHAR(50)
   DECLARE @DataLoadID	int
   DECLARE @m_DATA_LOAD_ID NVARCHAR(100)
   DECLARE @Total_tran int
   DECLARE @iCount int
   DECLARE @ItemLineRef VARCHAR(50)

   DECLARE @ERROR SMALLINT = NULL
   DECLARE @ERROR_DESCRIPTION NVARCHAR(200)


   DECLARE @SRM_CLIENTS_SEQ_ID BIGINT = 40
   DECLARE @EN_INVOICE BIGINT
   DECLARE @EN_INVOICE_DETAIL BIGINT
   DECLARE @EN_CONTACT BIGINT 
   DECLARE @EN_ACCOUNT BIGINT 
   DECLARE @EN_VAT_RATE BIGINT
   DECLARE @EN_PRODUCT BIGINT 
   DECLARE @EN_FINANCE_TRANSACTION_STATUS BIGINT
   DECLARE @EN_TRANSACTION_TYPE BIGINT 
   DECLARE @SCEA_PRODUCT_TYPE_NAME BIGINT
   DECLARE @SCEA_FINANCE_TRANSACTION BIGINT
   DECLARE @SCEA_EMAIL_SENT_DATE BIGINT 
   DECLARE @SCEA_EMAIL_SENT_TO_DISTRIBUTOR BIGINT
   DECLARE @UPDATED_STATUS_SEQ_ID BIGINT
   DECLARE @INVOICE_TRANSACTION_SEQ_ID BIGINT 
   
   SELECT @EN_INVOICE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=@SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME='FINANCE_TRANSACTION'
   SELECT @EN_INVOICE_DETAIL = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=@SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME='FINANCE_TRANSACTION_DETAIL'
   SELECT @EN_CONTACT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=@SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME='CONTACT'
   SELECT @EN_ACCOUNT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=@SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME='ACCOUNT'
   SELECT @EN_VAT_RATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=@SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME='VAT_RATE'
   SELECT @EN_PRODUCT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=@SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME='PRODUCT'
   SELECT @EN_FINANCE_TRANSACTION_STATUS = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=@SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME='FINANCE_TRANSACTION_STATUS'
   SELECT @EN_TRANSACTION_TYPE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=@SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME='TRANSACTION_TYPE'
   SELECT @SCEA_PRODUCT_TYPE_NAME = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_PRODUCT AND ATTRIBUTE_DISPLAY_NAME='PRODUCT_TYPE_DESCRIPTION'
   SELECT @SCEA_FINANCE_TRANSACTION = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE_DETAIL AND ATTRIBUTE_DISPLAY_NAME='FINANCE_TRANSACTION'
   SELECT @SCEA_EMAIL_SENT_DATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE AND ATTRIBUTE_DISPLAY_NAME='EMAIL_SENT_DATE'
   SELECT @SCEA_EMAIL_SENT_TO_DISTRIBUTOR = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE AND ATTRIBUTE_DISPLAY_NAME='EMAIL_SENT_TO_DISTRIBUTOR'

   
   SELECT @UPDATED_STATUS_SEQ_ID = SEQ_ID FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_FINANCE_TRANSACTION_STATUS AND DELETED='N' AND ATTRIBUTE_008='Y'
   SELECT @INVOICE_TRANSACTION_SEQ_ID = SEQ_ID FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_TRANSACTION_TYPE AND DELETED='N' AND ATTRIBUTE_006='Y'
      
	   
	UPDATE CUS_ENTITY_DATA SET 
		ATTRIBUTE_092 = convert(nvarchar(MAX), DATEADD(HH, 0, GETDATE()), 20), 
		DATE_MODIFIED = GETDATE(),
		MODIFIED_BY = 'Nautical Institute DP'
	FROM [SRM-CustomEntities_40]..CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @EN_INVOICE AND ATTRIBUTE_071 = 'Y' 
	AND ATTRIBUTE_092 IS NULL AND (DELETED = 'N' OR DELETED IS NULL)
	AND ATTRIBUTE_042 IN (SELECT SEQ_ID FROM [SRM-CustomEntities_40]..CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @EN_FINANCE_TRANSACTION_STATUS AND ATTRIBUTE_008 = 'Y')

	UPDATE CUS_ENTITY_DATA SET 
		ATTRIBUTE_092 = left(ATTRIBUTE_092, 10) + ' ' + left(ATTRIBUTE_093, 8) + '.000', 
		DATE_MODIFIED = GETDATE(),
		MODIFIED_BY = 'Nautical Institute DP'
	FROM [SRM-CustomEntities_40]..CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @EN_INVOICE AND ATTRIBUTE_071 = 'Y' 
	AND DATEPART(HOUR, ATTRIBUTE_092) = 0 AND DATEPART(MINUTE, ATTRIBUTE_092) = 0
	AND ATTRIBUTE_042 IN (SELECT SEQ_ID FROM [SRM-CustomEntities_40]..CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @EN_FINANCE_TRANSACTION_STATUS AND ATTRIBUTE_008 = 'Y')
	AND DATEDIFF(DAY, ATTRIBUTE_092, GETDATE()) <= 2

	UPDATE CUS_ENTITY_DATA SET 
		ATTRIBUTE_092 = convert(nvarchar(MAX), DATEADD(HH, 0, GETDATE()), 20), 
		DATE_MODIFIED = GETDATE(),
		MODIFIED_BY = 'Nautical Institute DP'
	FROM [SRM-CustomEntities_40]..CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @EN_INVOICE AND ATTRIBUTE_071 = 'Y' 
	AND DATEDIFF(HOUR, ATTRIBUTE_092, GetDate()) > 24 
	AND cast(ATTRIBUTE_010 as Datetime) >=  '2019-07-22 18:15:00.000'
	AND '"' + ATTRIBUTE_001 + '"' collate Latin1_General_100_CI_AS not in (select InvoiceNo from [SRM-Framework_new]..NI_INV_OUTPUT_FILE_LOG)
	AND (DELETED = 'N' OR DELETED IS NULL)
	AND ATTRIBUTE_042 IN (SELECT SEQ_ID FROM [SRM-CustomEntities_40]..CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @EN_FINANCE_TRANSACTION_STATUS AND ATTRIBUTE_008 = 'Y')
	
	EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE
		@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SCEA_EMAIL_SENT_DATE


	
   --MQ kayako TASK ID : 9350 --Product 0333 - Work of the Harbour Master book and scheme
   DECLARE @DO_NOT_SEND_INVOICES_EMAIL_TO_DISTRIBUTOR TABLE (SEQ_ID BIGINT)
   INSERT INTO @DO_NOT_SEND_INVOICES_EMAIL_TO_DISTRIBUTOR
   SELECT CAST(ATTRIBUTE_002 AS BIGINT)
   FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS FTD WITH (NOLOCK) 
   WHERE SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID 
                   FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
				   WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 215833 --PRODUCT SEQ_ID
				   AND ATTRIBUTE_DECIMAL IN(SELECT CUS_ENTITY_DATA_SEQ_ID
											FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
											WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1340780 --DO_NOT_SEND_AUTO_EMAIL_TO_DISTRIBUTOR
											AND ISNULL(ATTRIBUTE_BOOLEAN,'N')='Y'
				                           )
				   )
   
   AND CREATED_BY='WEB'
   AND CAST(ATTRIBUTE_092 AS DATETIME)	>= DATEADD(MINUTE,15, DATEADD(HH,18,CONVERT(VARCHAR(10),GETDATE()- 1,110)))

   UPDATE X SET ATTRIBUTE_091='N' --EMAIL_SENT_TO_DISTRIBUTOR
   FROM [SRM-CustomEntities_40]..CUS_ENTITY_DATA X WITH(NOLOCK)
   WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE --9989	--FINANCE_TRANSACTION
   AND SEQ_ID IN(SELECT SEQ_ID FROM @DO_NOT_SEND_INVOICES_EMAIL_TO_DISTRIBUTOR)

   EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE
		@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SCEA_EMAIL_SENT_TO_DISTRIBUTOR --571559	--EMAIL_SENT_TO_DISTRIBUTOR


   DECLARE @EN_POSTAGE_PRODUCT_TABLE TABLE (SEQ_ID BIGINT)
   INSERT INTO @EN_POSTAGE_PRODUCT_TABLE
   SELECT SEQ_ID FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_PRODUCT AND DELETED='N' AND SEQ_ID IN (
   SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_PRODUCT_TYPE_NAME AND ATTRIBUTE_STRING='POSTAGE')

   --ALTER TABLE NI_INV_OUTPUT_FILE ADD Department NVARCHAR(200)
     
	TRUNCATE TABLE NI_INV_OUTPUT_FILE
	
	INSERT INTO NI_INV_OUTPUT_FILE VALUES (
	'"Data Load ID"',
