	)
	

	SET @FileName = 'NI-'+Replace(replace(REPLACE( CONVERT(varchar(19),GETDATE(),121),'-',''),':',''),' ','')+'.csv' 
		

	Insert Into NI_INV_OUTPUT_FILE

	SELECT '"' + 'NI000000001' +  + '"' 'Data Load ID', 
	'"' + ISNULL(IIBD.ATTRIBUTE_001, '')  + '"' 'External Ref', 
	'"' + ISNULL(IIBD.ATTRIBUTE_012, '')  + '"' 'Customer Order No',
	'"' + CAST(ISNULL(CASE WHEN ISNULL(IIBD.ATTRIBUTE_006, '') = '' THEN CO.ATTRIBUTE_003 ELSE CP.ATTRIBUTE_003 END, '') AS VARCHAR(50))  + '"' 'Cust Account',
	'"' + dbo.GetStringDateUK(IIBD.ATTRIBUTE_010)  + '"' 'Invoice Date', 
