	'"' + ISNULL(CASE WHEN ISNULL(IIBD.ATTRIBUTE_067, '') <> '' THEN '15 Days' WHEN ISNULL(IIBD.ATTRIBUTE_006, '') = '' THEN CO.ATTRIBUTE_060 ELSE  CP.ATTRIBUTE_084 END, '')  + '"' 'Settlement Terms',
	'""' 'Delivery Via', 
