	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_029 , '') AS VARCHAR(500))  + '"' 'InvoiceAccountStreet2',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_030, '') AS VARCHAR(500))   + '"' 'InvoiceAccountStreet3',
	'""' 'InvoiceAccountStreet4',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_031, '') AS VARCHAR(50))   + '"' 'InvoiceAccountCity',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_034, '') AS VARCHAR(50))   + '"' 'InvoiceAccountCounty',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_032, '') AS VARCHAR(50))   + '"' 'InvoiceAccountPostcode',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_036, '') AS VARCHAR(50))    + '"' 'InvoiceAccountCountry',
