	'""' 'DeliveryContactLastName',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_015, '') AS VARCHAR(50))   + '"' 'DeliveryCompanyName',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_016, '') AS VARCHAR(500))   + '"' 'DeliveryAddressStreet1',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_017, '') AS VARCHAR(500))   + '"' 'DeliveryAddressStreet2',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_018, '') AS VARCHAR(500))   + '"' 'DeliveryAddressStreet3',
	'""' 'DeliveryAddressStreet4',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_019, '') AS VARCHAR(50))   + '"' 'DeliveryAddressCity',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_022, '') AS VARCHAR(50))   + '"' 'DeliveryAddressCounty',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_020, '') AS VARCHAR(50))   + '"' 'DeliveryAddressPostcode',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_024, '') AS VARCHAR(50))   + '"' 'DeliveryAddressCountry',
	'"' + CAST(ISNULL(CASE WHEN CP.SEQ_ID IS Null THEN CO.ATTRIBUTE_045 ELSE CP.ATTRIBUTE_056 END, '') AS VARCHAR(50))   + '"' 'Email Address',
	'"' + CAST(ISNULL(CASE WHEN CP.SEQ_ID IS Null THEN CO.ATTRIBUTE_043 ELSE CP.ATTRIBUTE_053 END, '') AS VARCHAR(50))   + '"' 'Telephone',

	'"' + CAST(ISNULL((	
	Select sum(CAST(ATTRIBUTE_018 AS MONEY)) FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA ID WITH (NOLOCK) WHERE ID.SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE_DETAIL
	AND SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_FINANCE_TRANSACTION AND 
	ATTRIBUTE_DECIMAL = IIBD.SEQ_ID) AND ID.DELETED='N' AND ATTRIBUTE_022 NOT IN (SELECT SEQ_ID FROM @EN_POSTAGE_PRODUCT_TABLE)
	), 0.00) AS VARCHAR(50))  + '"' 'SubTotal',

	'"' + CAST(ISNULL((	
	Select sum(CAST(ATTRIBUTE_018 AS MONEY)+CAST(ATTRIBUTE_019 AS MONEY)) FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA ID WITH (NOLOCK) WHERE ID.SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE_DETAIL
	AND SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_FINANCE_TRANSACTION AND 
	ATTRIBUTE_DECIMAL = IIBD.SEQ_ID) AND ID.DELETED='N' AND ATTRIBUTE_022 IN (SELECT SEQ_ID FROM @EN_POSTAGE_PRODUCT_TABLE)
	
	), 0.00) AS VARCHAR(50))  + '"' 'Carriage',
	
	'"0.00"' 'Packing',

	'"' + CAST(ISNULL((	Select sum(CAST(ATTRIBUTE_019 AS MONEY)) FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA ID WITH (NOLOCK) WHERE ID.SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE_DETAIL
	AND SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_FINANCE_TRANSACTION AND 
	ATTRIBUTE_DECIMAL = IIBD.SEQ_ID) AND ID.DELETED='N' AND ATTRIBUTE_022 NOT IN (SELECT SEQ_ID FROM @EN_POSTAGE_PRODUCT_TABLE)), 0.00) AS VARCHAR(50))  + '"' 'VAT',
	
	'"' + CAST(ISNULL((Select sum(CAST(ATTRIBUTE_020 AS MONEY)) FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA ID WITH (NOLOCK) WHERE ID.SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE_DETAIL
	AND SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_FINANCE_TRANSACTION AND 
	ATTRIBUTE_DECIMAL = IIBD.SEQ_ID) AND ID.DELETED='N'), 0.00) AS VARCHAR(50))   + '"' 'Total',
	
	'"' + CAST(CASE WHEN ISNULL(IIBD.ATTRIBUTE_083, '') = 'Post' then 'Mail' ELSE ISNULL(IIBD.ATTRIBUTE_083, '') END AS VARCHAR(250))   + '"' 'Delivery Method',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_088, '') AS VARCHAR(250))   + '"' 'Delivery Ins',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_001, '') AS VARCHAR(50))   + '"' 'Item Line Ref',
	'"' + CAST(ISNULL(IP.ATTRIBUTE_001, '') AS VARCHAR(50))   + '"' 'Item',
	'"' + CAST(ISNULL(IIBT.ATTRIBUTE_023, '') AS VARCHAR(250))   + '"' 'Description',
	'"' + CAST(ISNULL(IIBT.ATTRIBUTE_014, 0) AS VARCHAR(50))  + '"' 'QUANTITY',
	'"' + CAST(ISNULL(VR.ATTRIBUTE_008, '') AS VARCHAR(50))   + '"' 'VAT Code',
	'"' + CAST(ISNULL(IIBT.ATTRIBUTE_013, 0.00) AS VARCHAR(50))  + '"' 'Unit Price',
	'"' + CAST(ISNULL(IIBT.ATTRIBUTE_016, 0.00) AS VARCHAR(50))  + '"' 'Discount',
	'"' + CAST(ISNULL(IIBT.ATTRIBUTE_018, 0.00) AS VARCHAR(50))  + '"' 'Net Amount',
	'"' + CAST(ISNULL(dbo.[fn_GetInvoiceDepartment_40](IIBD.SEQ_ID), '') AS VARCHAR(50))  + '"' 'Department'
	FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS IIBD WITH (NOLOCK) 
	LEFT OUTER JOIN [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CP ON CP.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_CONTACT AND CP.SEQ_ID = IIBD.ATTRIBUTE_006 AND CP.DELETED='N'
	LEFT OUTER JOIN [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CO ON CO.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_ACCOUNT AND CO.SEQ_ID = IIBD.ATTRIBUTE_004 AND CO.DELETED='N'
	INNER JOIN [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI ON SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_FINANCE_TRANSACTION AND ATTRIBUTE_DECIMAL=IIBD.SEQ_ID
	INNER JOIN [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA IIBT ON IIBT.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_INVOICE_DETAIL AND CPNUI.CUS_ENTITY_DATA_SEQ_ID = IIBT.SEQ_ID AND 
	IIBT.DELETED='N' AND IIBT.ATTRIBUTE_022 NOT IN (SELECT SEQ_ID FROM @EN_POSTAGE_PRODUCT_TABLE)
	LEFT OUTER JOIN [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA VR ON VR.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_VAT_RATE AND IIBT.ATTRIBUTE_010 = VR.SEQ_ID AND VR.DELETED='N'
	LEFT OUTER JOIN [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA IP ON IP.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_PRODUCT AND IIBT.ATTRIBUTE_022 = IP.SEQ_ID AND IP.DELETED='N'
	WHERE 
	-- adding 18hrs and 15 min. 
	(IIBD.SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID 
					 FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI 
					 WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_EMAIL_SENT_DATE
					 AND ATTRIBUTE_DATETIME	>= DATEADD(MINUTE,15, DATEADD(HH,18,CONVERT(VARCHAR(10),GETDATE()- 1,110)))
					)
	)

	AND IIBD.SEQ_ID NOT IN(SELECT SEQ_ID FROM @DO_NOT_SEND_INVOICES_EMAIL_TO_DISTRIBUTOR)

	--CAST(IIBD.ATTRIBUTE_092 AS DATE) >= '2017-11-06' AND CAST(IIBD.ATTRIBUTE_092 AS DATETIME) < '2017-11-20 18:15' AND IIBD.ATTRIBUTE_083 = 'POST'
	AND IIBD.DELETED='N'
	AND IIBD.ATTRIBUTE_054 = @INVOICE_TRANSACTION_SEQ_ID
	AND IIBD.ATTRIBUTE_071 = 'Y' AND IIBD.ATTRIBUTE_001 <> '56669'
	AND IIBD.ATTRIBUTE_042 = @UPDATED_STATUS_SEQ_ID
	AND DATEDIFF(mm, IIBD.ATTRIBUTE_010, GETDATE()) <= 6
	ORDER BY IIBD.ATTRIBUTE_012 
	--cast(CP.ATTRIBUTE_003 as bigint), cast(CO.ATTRIBUTE_003 as bigint), cast(IIBD.ATTRIBUTE_001 as bigint)

	
	print 'before cursor'	
	DECLARE curInvoices CURSOR FOR
	SELECT ExternalRef, count(*) Total_tran FROM NI_INV_OUTPUT_FILE where ExternalRef <> 'External Ref' group by ExternalRef ORDER By ExternalRef
	
	OPEN curInvoices
	SET @DataLoadID = 0
	SET @InvoiceNo = ''
	FETCH NEXT FROM curInvoices INTO @ExternalRef, @Total_tran
	WHILE (@@FETCH_STATUS = 0)
	BEGIN	
		
		print 'in the start of cursor'	
		EXECUTE [dbo].[GET_PIVOT_NEXT_ID] 
		@UNIQUE_INDEX_ID = 99,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@PIVOT_NEXT_ID = @m_DATA_LOAD_ID OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
		 
		UPDATE NI_INV_OUTPUT_FILE 
		SET DataLoadID = '"' + 'NI' + RIGHT ('00000000' + LTRIM(STR(@m_DATA_LOAD_ID)),8) + '"'
		WHERE ExternalRef = @ExternalRef
				
		SET @iCount = 0
		
		DECLARE curUpdateCursor CURSOR FOR
		SELECT ItemLineRef FROM NI_INV_OUTPUT_FILE where ExternalRef = @ExternalRef FOR UPDATE OF ItemLineRef
	
		OPEN curUpdateCursor
		FETCH NEXT FROM curUpdateCursor INTO  @ItemLineRef
		WHILE (@@FETCH_STATUS = 0)
		BEGIN
			SET @iCount = @iCount + 1
			UPDATE NI_INV_OUTPUT_FILE SET ItemLineRef = '"' + SUBSTRING(@ExternalRef, 2, LEN(@ExternalRef)-2) + '-' + RIGHT ('000' + LTRIM(STR(@iCount)),3) + '"' WHERE CURRENT OF curUpdateCursor			
			FETCH NEXT FROM curUpdateCursor INTO @ItemLineRef
		END
		CLOSE curUpdateCursor
		DEALLOCATE curUpdateCursor	
		
		FETCH NEXT FROM curInvoices INTO @ExternalRef, @Total_tran
	END
	CLOSE curInvoices
	DEALLOCATE curInvoices	
	   	
	select @Command = 'bcp [' + db_name() + ']..NI_INV_OUTPUT_FILE out C:\ClientData\NI-Invoices\' + @FileName + ' -c -t, -T -S '+ @@servername

	exec xp_CmdShell @Command


	-- maintain log
	insert into NI_INV_OUTPUT_FILE_LOG
	(
		DataLoadID,
		ExternalRef,
		CustomerOrderNo,
		CustAccount,
		InvoiceDate,
		InvoiceNo,
		CompanyVATNo,
		CreditNote,
		CustomerCourierAcc,
		SettlementTerms,
		DeliveryVia,
		InvoiceAccountSocalTitle,
		InvoiceAccountFirstName,
		InvoiceAccountLastName,
		CompanyName,
		InvoiceAccountStreet1,
		InvoiceAccountStreet2,
		InvoiceAccountStreet3,
		InvoiceAccountStreet4,
		InvoiceAccountCity,
		InvoiceAccountCounty,
		InvoiceAccountPostcode,
		InvoiceAccountCountry,
		DeliveryContactSocalTitle,
		DeliveryContactFirstName,
		DeliveryContactLastName,
		DeliveryCompanyName,
		DeliveryAddressStreet1,
		DeliveryAddressStreet2,
		DeliveryAddressStreet3,
		DeliveryAddressStreet4,
		DeliveryAddressCity,
		DeliveryAddressCounty,
		DeliveryAddressPostcode,
		DeliveryAddressCountry,
		EmailAddress,
		Telephone,
		SubTotal,
		Carriage,
		Packing,
		VAT,
		Total,
		DeliveryMethod,
		DeliveryIns,
		ItemLineRef,
		Item,
		Description,
		Quantity,
		VATCode,
		UnitPrice,
		Discount,
		NetAmount,
		Department,
		DateSent
	)
	select 
		DataLoadID,
		ExternalRef,
		CustomerOrderNo,
		CustAccount,
		InvoiceDate,
		InvoiceNo,
		CompanyVATNo,
		CreditNote,
		CustomerCourierAcc,
		SettlementTerms,
		DeliveryVia,
		InvoiceAccountSocalTitle,
		InvoiceAccountFirstName,
		InvoiceAccountLastName,
		CompanyName,
		InvoiceAccountStreet1,
		InvoiceAccountStreet2,
		InvoiceAccountStreet3,
		InvoiceAccountStreet4,
		InvoiceAccountCity,
		InvoiceAccountCounty,
		InvoiceAccountPostcode,
		InvoiceAccountCountry,
		DeliveryContactSocalTitle,
		DeliveryContactFirstName,
		DeliveryContactLastName,
		DeliveryCompanyName,
		DeliveryAddressStreet1,
		DeliveryAddressStreet2,
		DeliveryAddressStreet3,
		DeliveryAddressStreet4,
		DeliveryAddressCity,
		DeliveryAddressCounty,
		DeliveryAddressPostcode,
		DeliveryAddressCountry,
		EmailAddress,
		Telephone,
		SubTotal,
		Carriage,
		Packing,
		VAT,
		Total,
		DeliveryMethod,
		DeliveryIns,
		ItemLineRef,
		Item,
		Description,
