	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_017, '') AS VARCHAR(500))   + '"' 'DeliveryAddressStreet2',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_018, '') AS VARCHAR(500))   + '"' 'DeliveryAddressStreet3',
	'""' 'DeliveryAddressStreet4',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_019, '') AS VARCHAR(50))   + '"' 'DeliveryAddressCity',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_022, '') AS VARCHAR(50))   + '"' 'DeliveryAddressCounty',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_020, '') AS VARCHAR(50))   + '"' 'DeliveryAddressPostcode',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_024, '') AS VARCHAR(50))   + '"' 'DeliveryAddressCountry',
