	AND SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_FINANCE_TRANSACTION AND 
	ATTRIBUTE_DECIMAL = IIBD.SEQ_ID) AND ID.DELETED='N' AND ATTRIBUTE_022 IN (SELECT SEQ_ID FROM @EN_POSTAGE_PRODUCT_TABLE)
	
	), 0.00) AS VARCHAR(50))  + '"' 'Carriage',
	
	'"0.00"' 'Packing',

	'"' + CAST(ISNULL((	Select sum(CAST(ATTRIBUTE_019 AS MONEY)) FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA ID WITH (NOLOCK) WHERE ID.SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE_DETAIL
	AND SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_FINANCE_TRANSACTION AND 
	ATTRIBUTE_DECIMAL = IIBD.SEQ_ID) AND ID.DELETED='N' AND ATTRIBUTE_022 NOT IN (SELECT SEQ_ID FROM @EN_POSTAGE_PRODUCT_TABLE)), 0.00) AS VARCHAR(50))  + '"' 'VAT',
	
	'"' + CAST(ISNULL((Select sum(CAST(ATTRIBUTE_020 AS MONEY)) FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA ID WITH (NOLOCK) WHERE ID.SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE_DETAIL
	AND SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_FINANCE_TRANSACTION AND 
	ATTRIBUTE_DECIMAL = IIBD.SEQ_ID) AND ID.DELETED='N'), 0.00) AS VARCHAR(50))   + '"' 'Total',
	
	'"' + CAST(CASE WHEN ISNULL(IIBD.ATTRIBUTE_083, '') = 'Post' then 'Mail' ELSE ISNULL(IIBD.ATTRIBUTE_083, '') END AS VARCHAR(250))   + '"' 'Delivery Method',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_088, '') AS VARCHAR(250))   + '"' 'Delivery Ins',
	'"' + CAST(ISNULL(IIBD.ATTRIBUTE_001, '') AS VARCHAR(50))   + '"' 'Item Line Ref',
	'"' + CAST(ISNULL(IP.ATTRIBUTE_001, '') AS VARCHAR(50))   + '"' 'Item',
	'"' + CAST(ISNULL(IIBT.ATTRIBUTE_023, '') AS VARCHAR(250))   + '"' 'Description',
	'"' + CAST(ISNULL(IIBT.ATTRIBUTE_014, 0) AS VARCHAR(50))  + '"' 'QUANTITY',
	'"' + CAST(ISNULL(VR.ATTRIBUTE_008, '') AS VARCHAR(50))   + '"' 'VAT Code',
	'"' + CAST(ISNULL(IIBT.ATTRIBUTE_013, 0.00) AS VARCHAR(50))  + '"' 'Unit Price',
	--'"' + CAST(CAST(ISNULL(IIBT.ATTRIBUTE_017, 0.00) AS MONEY)/CAST(ISNULL(IIBT.ATTRIBUTE_014, 1) AS MONEY) AS VARCHAR(50))  + '"' 'Discount',
	'"' + CAST((CAST(ISNULL(IIBT.ATTRIBUTE_015, 0.00) AS MONEY)-CAST(ISNULL(IIBT.ATTRIBUTE_018, 1) AS MONEY))/CAST(ISNULL(IIBT.ATTRIBUTE_014, 1) AS MONEY) AS VARCHAR(50))  + '"' 'Discount',
	'"' + CAST(ISNULL(IIBT.ATTRIBUTE_018, 0.00) AS VARCHAR(50))  + '"' 'Net Amount',
	'"' + CAST(ISNULL(dbo.[fn_GetInvoiceDepartment_40](IIBD.SEQ_ID), '') AS VARCHAR(50))  + '"' 'Department'

	FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS IIBD WITH (NOLOCK) 
	LEFT OUTER JOIN [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CP ON CP.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_CONTACT AND CP.SEQ_ID = IIBD.ATTRIBUTE_006 AND CP.DELETED='N'
	LEFT OUTER JOIN [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CO ON CO.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_ACCOUNT AND CO.SEQ_ID = IIBD.ATTRIBUTE_004 AND CO.DELETED='N'
	INNER JOIN [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI ON SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_FINANCE_TRANSACTION AND ATTRIBUTE_DECIMAL=IIBD.SEQ_ID
	INNER JOIN [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA IIBT ON IIBT.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_INVOICE_DETAIL AND CPNUI.CUS_ENTITY_DATA_SEQ_ID = IIBT.SEQ_ID AND 
	IIBT.DELETED='N' AND ( IIBT.ATTRIBUTE_022 NOT IN (SELECT SEQ_ID FROM @EN_POSTAGE_PRODUCT_TABLE)
						   OR
				           IIBT.ATTRIBUTE_022 IN (SELECT SEQ_ID FROM @EN_DP_PRODUCT_TABLE)           
						 )
	LEFT OUTER JOIN [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA VR ON VR.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_VAT_RATE AND  VR.DELETED='N' --AND IIBT.ATTRIBUTE_010=VR.SEQ_ID 
																				AND (CASE WHEN CAST(IIBT.ATTRIBUTE_019 AS MONEY)>0 THEN CAST(IIBT.ATTRIBUTE_010 AS BIGINT) ELSE 190923356 END = VR.SEQ_ID)
	LEFT OUTER JOIN [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA IP ON IP.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_PRODUCT AND IIBT.ATTRIBUTE_022 = IP.SEQ_ID AND IP.DELETED='N'
	WHERE 
	-- adding 18hrs and 15 min. 
	(IIBD.SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID 
					 FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI 
					 WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_EMAIL_SENT_DATE
					 AND ATTRIBUTE_DATETIME	>= DATEADD(MINUTE,15, DATEADD(HH,18,CONVERT(VARCHAR(10),GETDATE()- 1,110)))
					)
	)

	AND IIBD.SEQ_ID NOT IN(SELECT SEQ_ID FROM @DO_NOT_SEND_INVOICES_EMAIL_TO_DISTRIBUTOR)
	--AND IIBD.ATTRIBUTE_001 not in (select InvoiceNo from [SRM-Framework_new]..NI_INV_OUTPUT_FILE_DT_LOG)
	AND '"' + IIBD.ATTRIBUTE_001 + '"' collate Latin1_General_100_CI_AS not in (select InvoiceNo from [SRM-Framework_new]..NI_INV_OUTPUT_FILE_DT_LOG)
	--CAST(IIBD.ATTRIBUTE_092 AS DATE) >= '2017-11-06' AND CAST(IIBD.ATTRIBUTE_092 AS DATETIME) < '2017-11-20 18:15' AND IIBD.ATTRIBUTE_083 = 'POST'
	AND IIBD.DELETED='N'
	AND IIBD.ATTRIBUTE_054 = @INVOICE_TRANSACTION_SEQ_ID
	AND IIBD.ATTRIBUTE_071 = 'Y' 
	AND IIBD.ATTRIBUTE_001 <> '56669'
	AND IIBD.ATTRIBUTE_042 = @UPDATED_STATUS_SEQ_ID
	--AND DATEDIFF(mm, IIBD.ATTRIBUTE_010, GETDATE()) <= 6
	ORDER BY IIBD.ATTRIBUTE_012 
	--cast(CP.ATTRIBUTE_003 as bigint), cast(CO.ATTRIBUTE_003 as bigint), cast(IIBD.ATTRIBUTE_001 as bigint)


	print 'before cursor'	
	DECLARE curInvoices CURSOR FOR
	SELECT ExternalRef, count(*) Total_tran FROM NI_INV_OUTPUT_FILE_DT where ExternalRef <> 'External Ref' group by ExternalRef ORDER By ExternalRef
	
	OPEN curInvoices
	SET @DataLoadID = 0
	SET @InvoiceNo = ''
	FETCH NEXT FROM curInvoices INTO @ExternalRef, @Total_tran
	WHILE (@@FETCH_STATUS = 0)
	BEGIN	
		
		print 'in the start of cursor'	
		EXECUTE [dbo].[GET_PIVOT_NEXT_ID] 
		@UNIQUE_INDEX_ID = 99,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@PIVOT_NEXT_ID = @m_DATA_LOAD_ID OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
		 
		UPDATE NI_INV_OUTPUT_FILE_DT 
		SET DataLoadID = '"' + 'NI' + RIGHT ('00000000' + LTRIM(STR(@m_DATA_LOAD_ID)),8) + '"'
		WHERE ExternalRef = @ExternalRef
				
		SET @iCount = 0
		
		DECLARE curUpdateCursor CURSOR FOR
		SELECT ItemLineRef FROM NI_INV_OUTPUT_FILE_DT where ExternalRef = @ExternalRef FOR UPDATE OF ItemLineRef
	
		OPEN curUpdateCursor
		FETCH NEXT FROM curUpdateCursor INTO  @ItemLineRef
		WHILE (@@FETCH_STATUS = 0)
		BEGIN
			SET @iCount = @iCount + 1
			UPDATE NI_INV_OUTPUT_FILE_DT SET ItemLineRef = '"' + SUBSTRING(@ExternalRef, 2, LEN(@ExternalRef)-2) + '-' + RIGHT ('000' + LTRIM(STR(@iCount)),3) + '"' WHERE CURRENT OF curUpdateCursor			
			FETCH NEXT FROM curUpdateCursor INTO @ItemLineRef
		END
		CLOSE curUpdateCursor
		DEALLOCATE curUpdateCursor	
		
		FETCH NEXT FROM curInvoices INTO @ExternalRef, @Total_tran
	END
	CLOSE curInvoices
	DEALLOCATE curInvoices	

	---------------------------------------------------------------------------------------------
	--	START				CHUNK FOR GROUP PRODUCTS
	---------------------------------------------------------------------------------------------
	print 'before cursor GROUP PRODUCTS'
	---------------------------------------------------------------------------------------------

	DECLARE @GROUP_PRODUCTS TABLE (GROUP_PRODUCT_ID VARCHAR(50)  , PRODUCT_ID VARCHAR(50) , PRODUCT_DESCRIPTION NVARCHAR(500))
	INSERT INTO @GROUP_PRODUCTS (GROUP_PRODUCT_ID, PRODUCT_ID , PRODUCT_DESCRIPTION) 
	SELECT P.ATTRIBUTE_001  GROUP_PRODUCT_ID , GPD.ATTRIBUTE_001 PRODUCT_ID , GPD.ATTRIBUTE_002
	FROM [SRM-CustomEntities_40]..CUS_ENTITY_DATA GP WITH(NOLOCK)
	INNER JOIN [SRM-CustomEntities_40]..CUS_ENTITY_DATA P WITH(NOLOCK) ON P.SRM_CLIENT_ENTITIES_SEQ_ID=9894 AND ISNULL(P.DELETED,'N')='N' AND P.SEQ_ID = GP.ATTRIBUTE_004
	INNER JOIN [SRM-CustomEntities_40]..CUS_ENTITY_DATA GPD WITH(NOLOCK) ON GPD.SRM_CLIENT_ENTITIES_SEQ_ID=9894 AND ISNULL(GPD.DELETED,'N')='N' AND GPD.SEQ_ID = GP.ATTRIBUTE_002
	WHERE GP.SRM_CLIENT_ENTITIES_SEQ_ID=58240
	AND ISNULL(GP.DELETED,'N')='N'

	DECLARE @COUNT_GROUP_PRODUCTS BIGINT
	DECLARE @gp_CountRowsFrom_OUTPUT_FILE_DT BIGINT
    DECLARE @gp_INVOICE_NO VARCHAR(50)

	DECLARE curGroupProducts CURSOR FOR
	SELECT ExternalRef
	FROM NI_INV_OUTPUT_FILE_DT 
	WHERE ExternalRef <> 'External Ref'
	AND item in (SELECT '"' + GROUP_PRODUCT_ID + '"'  from @GROUP_PRODUCTS )
	GROUP BY ExternalRef 
	ORDER By ExternalRef
	
	OPEN curGroupProducts
	FETCH NEXT FROM curGroupProducts INTO @gp_INVOICE_NO
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
  
		SELECT @gp_CountRowsFrom_OUTPUT_FILE_DT = COUNT(*) FROM NI_INV_OUTPUT_FILE_DT WHERE ExternalRef=@gp_INVOICE_NO
    
	    print 'before cursor GROUP PRODUCTS transactions'  

		DECLARE @gpt_ExternalRef VARCHAR(50)
		DECLARE @gpt_ItemLineRef VARCHAR(50)
		DECLARE @gpt_Item VARCHAR(50)
		DECLARE @gpt_UnitPrice VARCHAR(50)
		DECLARE @gpt_Discount VARCHAR(50)

		DECLARE @gpt_NewPrice MONEY
		DECLARE @gpt_NewDiscount MONEY  

        DECLARE @GP_PRODUCT_ID VARCHAR(50)
		DECLARE @GP_PRODUCT_DESCRIPTION VARCHAR(500)
		DECLARE @gpt_MaxItemLineRef VARCHAR(50)

		DECLARE curGroupProductsTransactions CURSOR FOR      
		SELECT ExternalRef, ItemLineRef , Item , UnitPrice ,Discount
		FROM NI_INV_OUTPUT_FILE_DT 
		WHERE ExternalRef = @gp_INVOICE_NO 
		AND Item IN (SELECT '"' + GROUP_PRODUCT_ID + '"' FROM @GROUP_PRODUCTS)
		ORDER By ItemLineRef


		OPEN curGroupProductsTransactions
		FETCH NEXT FROM curGroupProductsTransactions INTO @gpt_ExternalRef, @gpt_ItemLineRef,@gpt_Item,@gpt_UnitPrice , @gpt_Discount
		WHILE (@@FETCH_STATUS = 0)
		BEGIN
				SELECT @COUNT_GROUP_PRODUCTS = COUNT(*)  FROM @GROUP_PRODUCTS WHERE GROUP_PRODUCT_ID=REPLACE(@gpt_Item,'"','')
				SELECT TOP 1 @GP_PRODUCT_ID =PRODUCT_ID , @GP_PRODUCT_DESCRIPTION = PRODUCT_DESCRIPTION FROM @GROUP_PRODUCTS WHERE GROUP_PRODUCT_ID=REPLACE(@gpt_Item,'"','') ORDER BY PRODUCT_ID
				SELECT @gpt_NewPrice = CAST(REPLACE(@gpt_UnitPrice,'"','') AS MONEY) / CAST(@COUNT_GROUP_PRODUCTS AS MONEY)
				SELECT @gpt_NewDiscount = CAST(REPLACE(@gpt_Discount,'"','') AS MONEY) / CAST(@COUNT_GROUP_PRODUCTS AS MONEY)
				SELECT @gpt_MaxItemLineRef = MAX(ITEMLINEREF) FROM NI_INV_OUTPUT_FILE_DT WHERE ExternalRef=@gpt_ExternalRef

				IF @COUNT_GROUP_PRODUCTS>0
				BEGIN
					PRINT '--------------------GROUP PRODUCT'

					
					INSERT INTO NI_INV_OUTPUT_FILE_DT (DataLoadID,ExternalRef,CustomerOrderNo,CustAccount,InvoiceDate,InvoiceNo,CompanyVATNo,CreditNote,CustomerCourierAcc,SettlementTerms,DeliveryVia,InvoiceAccountSocalTitle,InvoiceAccountFirstName,InvoiceAccountLastName,CompanyName,InvoiceAccountStreet1,InvoiceAccountStreet2,InvoiceAccountStreet3,InvoiceAccountStreet4,InvoiceAccountCity,InvoiceAccountCounty,InvoiceAccountPostcode,InvoiceAccountCountry,DeliveryContactSocalTitle,DeliveryContactFirstName,DeliveryContactLastName,DeliveryCompanyName,DeliveryAddressStreet1,DeliveryAddressStreet2,DeliveryAddressStreet3,DeliveryAddressStreet4,DeliveryAddressCity,DeliveryAddressCounty,DeliveryAddressPostcode,DeliveryAddressCountry,EmailAddress,Telephone,SubTotal,Carriage,Packing,VAT,Total,DeliveryMethod,DeliveryIns
					                                  ,ItemLineRef,Item,Description,Quantity,VATCode,UnitPrice,Discount,NetAmount,Department)
					SELECT
					 X.DataLoadID,X.ExternalRef,X.CustomerOrderNo,X.CustAccount,X.InvoiceDate,X.InvoiceNo,X.CompanyVATNo,X.CreditNote,X.CustomerCourierAcc,X.SettlementTerms,X.DeliveryVia,X.InvoiceAccountSocalTitle,X.InvoiceAccountFirstName,X.InvoiceAccountLastName,X.CompanyName,X.InvoiceAccountStreet1,X.InvoiceAccountStreet2,X.InvoiceAccountStreet3,X.InvoiceAccountStreet4,X.InvoiceAccountCity,X.InvoiceAccountCounty,X.InvoiceAccountPostcode,X.InvoiceAccountCountry,X.DeliveryContactSocalTitle,X.DeliveryContactFirstName,X.DeliveryContactLastName,X.DeliveryCompanyName,X.DeliveryAddressStreet1,X.DeliveryAddressStreet2,X.DeliveryAddressStreet3,X.DeliveryAddressStreet4,X.DeliveryAddressCity,X.DeliveryAddressCounty,X.DeliveryAddressPostcode,X.DeliveryAddressCountry,X.EmailAddress,X.Telephone,X.SubTotal,X.Carriage,X.Packing,X.VAT,X.Total,X.DeliveryMethod,X.DeliveryIns
					, X.ItemLineRef
					,'"' + GP.PRODUCT_ID + '"' Item, '"' + GP.PRODUCT_DESCRIPTION + '"' Description,X.Quantity,X.VATCode,'"' + CAST(@gpt_NewPrice AS VARCHAR(50)) + '"' UnitPrice,'"' + CAST(@gpt_NewDiscount AS VARCHAR(50)) + '"' Discount,X.NetAmount,X.Department

					FROM NI_INV_OUTPUT_FILE_DT x
					INNER JOIN  @GROUP_PRODUCTS gp ON '"' + gp.GROUP_PRODUCT_ID + '"' = @gpt_Item AND GP.PRODUCT_ID!=@GP_PRODUCT_ID
					WHERE x.ExternalRef = @gp_INVOICE_NO
					AND x.Item=@gpt_Item
					
					UPDATE NI_INV_OUTPUT_FILE_DT SET Item = '"' + @GP_PRODUCT_ID + '"', Description= '"' + @GP_PRODUCT_DESCRIPTION + '"', UnitPrice = '"' + CAST(@gpt_NewPrice AS VARCHAR(50)) + '"', Discount = '"' + CAST(@gpt_NewDiscount AS VARCHAR(50)) + '"'
					WHERE ExternalRef = @gpt_ExternalRef AND ItemLineRef = @gpt_ItemLineRef AND Item=@gpt_Item
				END
  
		FETCH NEXT FROM curGroupProductsTransactions INTO @gpt_ExternalRef, @gpt_ItemLineRef,@gpt_Item,@gpt_UnitPrice,@gpt_Discount
		END
		CLOSE curGroupProductsTransactions
	    DEALLOCATE curGroupProductsTransactions

		DECLARE @iKount INT
		DECLARE @ItemLineRef2 VARCHAR(50)
		SET @iKount = 0
		DECLARE curResetLineItemRef CURSOR FOR
		SELECT ItemLineRef FROM NI_INV_OUTPUT_FILE_DT where ExternalRef = @gp_INVOICE_NO FOR UPDATE OF ItemLineRef
	
		OPEN curResetLineItemRef
		FETCH NEXT FROM curResetLineItemRef INTO  @ItemLineRef2
		WHILE (@@FETCH_STATUS = 0)
		BEGIN
			SET @iKount = @iKount + 1
			UPDATE NI_INV_OUTPUT_FILE_DT SET ItemLineRef = '"' + SUBSTRING(@gp_INVOICE_NO, 2, LEN(@gp_INVOICE_NO)-2) + '-' + RIGHT ('000' + LTRIM(STR(@iKount)),3) + '"' WHERE CURRENT OF curResetLineItemRef
			FETCH NEXT FROM curResetLineItemRef INTO @ItemLineRef2
		END
		CLOSE curResetLineItemRef
		DEALLOCATE curResetLineItemRef	


	FETCH NEXT FROM curGroupProducts INTO @gp_INVOICE_NO
	END
	CLOSE curGroupProducts
	DEALLOCATE curGroupProducts	

	---------------------------------------------------------------------------------------------
	--	END				CHUNK FOR GROUP PRODUCTS
	---------------------------------------------------------------------------------------------
--
