				 +','  + dbo.CheckSingleQuote(Carriage)
				 +','  + dbo.CheckSingleQuote(SettlementTerms)
				 + '', GETDATE()

				 FROM NI_INV_OUTPUT_FILE_DT
				 left OUTER JOIN [SRM-CustomEntities_40]..CUS_ENTITY_DATA DT WITH(NOLOCK) ON DT.SRM_CLIENT_ENTITIES_SEQ_ID=9877
				 AND REPLACE(NI_INV_OUTPUT_FILE_DT.DeliveryAddressCountry,'"','') collate SQL_Latin1_General_CP1_CI_AS =   DT.ATTRIBUTE_001

				 left OUTER JOIN [SRM-CustomEntities_40]..CUS_ENTITY_DATA DTT WITH(NOLOCK) ON DTT.SRM_CLIENT_ENTITIES_SEQ_ID=9877
				 and REPLACE(NI_INV_OUTPUT_FILE_DT.InvoiceAccountCountry,'"','') collate SQL_Latin1_General_CP1_CI_AS =   DTT.ATTRIBUTE_001
