					+ ',' + dbo.CheckSingleQuote(item)
					+ ',' + dbo.CheckSingleQuote(Quantity) 
					+ ',' + dbo.CheckSingleQuote(UnitPrice)
					+ ',"'+ CAST(CAST(REPLACE(UnitPrice,'"','') AS MONEY) - CAST(REPLACE(discount,'"','') AS MONEY) AS NVARCHAR(max)) + '"'
					+','  + dbo.CheckSingleQuote(VATCode)
					+ '' ,
					GETDATE()
					FROM NI_INV_OUTPUT_FILE_DT
					WHERE ItemLineRef=@ITEM_LINE_REF
				
			END
