		SRM_ENTITIES_SEQ_ID BIGINT,
		SRM_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT
	)

	DECLARE @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE TABLE
	(
		SRM_ENTITIES_SEQ_ID BIGINT,
		SRM_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT,
		SRM_ENTITY_ATTRIBUTES_SEQ_ID BIGINT,
		SRM_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT
	)

	DECLARE @TEMP_ENTITY_BUTTONS TABLE
	(		
		SRM_ENTITIES_SEQ_ID BIGINT,
		SRM_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID2 BIGINT
	)

	IF EXISTS(SELECT SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID)
	BEGIN
		PRINT 'THIS CLIENT''S DATA ALREADY EXISTS, SO CAN''T CONTINUE'
		RETURN
	END
  
	SET @TEMP_TABLE_NAME_POSTFIX = CONVERT(VARCHAR,@FROM_SRM_CLIENTS_SEQ_ID)+'_'+CONVERT(VARCHAR,@TO_SRM_CLIENTS_SEQ_ID)+'_'+CONVERT(VARCHAR,YEAR(GETDATE())) + CONVERT(VARCHAR,MONTH(GETDATE())) + CONVERT(VARCHAR,DAY(GETDATE()))  

	--BEGIN TRAN

	SELECT @CREATED_BY = LOGIN_USER_NAME FROM [SRM-Framework_New].dbo.SRM_USERS where SEQ_ID = @TO_SRM_USERS_SEQ_ID
	SET @DATE_CREATED = GETDATE()

	-- LANGUAGE
	INSERT INTO SRM_CLIENT_LANGUAGES
	(
		SRM_LANGUAGES_SEQ_ID,
		SRM_CLIENTS_SEQ_ID,
		SOURCE_OF_DATA,
		SOURCE_FILE,
		DATE_MODIFIED,
		MODIFIED_BY,
		DATE_CREATED,
		CREATED_BY,
		DELETED,
		DATE_DELETED,
		DELETED_BY
	)
	SELECT 	
		SRM_LANGUAGES_SEQ_ID,
		@TO_SRM_CLIENTS_SEQ_ID,
		SOURCE_OF_DATA,
		SOURCE_FILE,
		DATE_MODIFIED,
		MODIFIED_BY,
		DATE_CREATED,
		CREATED_BY,
		DELETED,
		DATE_DELETED,
		DELETED_BY
	FROM SRM_CLIENT_LANGUAGES
	WHERE SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID

	DECLARE CUR_ENTITIES CURSOR STATIC FOR
	SELECT SRM_ENTITIES.SEQ_ID, SRM_CLIENT_ENTITIES.SEQ_ID, SYSTEM_ENTITY FROM SRM_ENTITIES, SRM_CLIENT_ENTITIES WHERE SRM_ENTITIES.SEQ_ID = SRM_CLIENT_ENTITIES.SRM_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID

	OPEN CUR_ENTITIES 

	FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF @SYSTEM_ENTITY = 'Y'
		BEGIN
			SET @NEW_SRM_ENTITIES_SEQ_ID = @SRM_ENTITIES_SEQ_ID
		END
		ELSE
		BEGIN
			INSERT INTO SRM_ENTITIES
			(
				SYSTEM_NAME,
				DATABASE_SYSTEM_NAME,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				SYSTEM_NAME,
				DATABASE_SYSTEM_NAME,
				NULL, --SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL			
			FROM SRM_ENTITIES WHERE SEQ_ID = @SRM_ENTITIES_SEQ_ID

			SET @NEW_SRM_ENTITIES_SEQ_ID = @@IDENTITY
			
			--Moved SRM_CLIENT_LANGUAGE_ITEMS outside from else condition
		END
		INSERT INTO SRM_CLIENT_LANGUAGE_ITEMS
		(
			SRM_LANGUAGES_SEQ_ID,
			SRM_CLIENTS_SEQ_ID,
			OBJECT_ID,
			OBJECT_TYPE,
			SRM_LANGUAGE_TOKENS_SEQ_ID,
			PHRASE,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT 
			SRM_LANGUAGES_SEQ_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			@NEW_SRM_ENTITIES_SEQ_ID,
			OBJECT_TYPE,
			SRM_LANGUAGE_TOKENS_SEQ_ID,
			PHRASE,
			NULL, --SOURCE_OF_DATA
			NULL,
			NULL,
			NULL,
			@DATE_CREATED,
			@CREATED_BY,
			'N',
			NULL,
			NULL			
		FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 25 AND SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND OBJECT_ID = @SRM_ENTITIES_SEQ_ID      
		INSERT INTO SRM_CLIENT_ENTITIES
		(
			SRM_ENTITIES_SEQ_ID,
			SRM_CLIENTS_SEQ_ID,
			ENTITY_DISPLAY_NAME,
			SYSTEM_ENTITY,
			SERVICE_ID,
			PICK_LIST,
			CUSTOMISABLE,
			STARTS_WITH_VOWEL_SOUND,
			ALLOW_ACTIVITIES,
			TRACK_FIELD_HISTORY,
			DEPLOYMENT_STATUS,
			ENTITY_LINK,
			SHOW_IN_QUERYBUILDER,
			ADD_NOTES,
			ADD_ATTACHMENTS,
			VISIBLE,
			MERGE_ACTION_ID,
			SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
			INCLUDE_IN_RECENT_ITEMS,
			CLIENT_ENTITY_ICON_URL,
			HAS_SYNC_WF,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY,
			CLIENT_ENTITY_LARGE_ICON_URL,
			READ_ONLY ,
			SHOW_IN_RECYCLE_BIN ,
			ACTIVE_ATTRIBUTE,
			IS_LOOKUP,
			PAGE_SIZE,
			SYSTEM_MODULE
		)
		SELECT 
			@NEW_SRM_ENTITIES_SEQ_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			ENTITY_DISPLAY_NAME,
			SYSTEM_ENTITY,
			SERVICE_ID,
			PICK_LIST,
			CUSTOMISABLE,
			STARTS_WITH_VOWEL_SOUND,
			ALLOW_ACTIVITIES,
			TRACK_FIELD_HISTORY,
			DEPLOYMENT_STATUS,
			ENTITY_LINK,
			SHOW_IN_QUERYBUILDER,
			ADD_NOTES,
			ADD_ATTACHMENTS,
			VISIBLE,
			MERGE_ACTION_ID,
			CASE WHEN SRM_CLIENT_ENTITIES.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IS NOT NULL AND SRM_CLIENT_ENTITIES.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID != 0 THEN (SELECT SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITIES.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID) ELSE SRM_CLIENT_ENTITIES.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID END,
			INCLUDE_IN_RECENT_ITEMS,
			CLIENT_ENTITY_ICON_URL,
			HAS_SYNC_WF,
			NULL,
			NULL,
			NULL,
			NULL,
			@DATE_CREATED,
			@CREATED_BY,
			'N',
			NULL,
			NULL,
			CLIENT_ENTITY_LARGE_ICON_URL,
			READ_ONLY ,
			SHOW_IN_RECYCLE_BIN ,
			ACTIVE_ATTRIBUTE,
			IS_LOOKUP,
			PAGE_SIZE,
			SYSTEM_MODULE			
		FROM SRM_CLIENT_ENTITIES WHERE SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
		SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = @@IDENTITY

		INSERT INTO @TEMP_ENTITY_CLIENT_ENTITY_TABLE
		(
			SRM_ENTITIES_SEQ_ID,
			SRM_ENTITIES_SEQ_ID2,
			SRM_CLIENT_ENTITIES_SEQ_ID,
			SRM_CLIENT_ENTITIES_SEQ_ID2
		)
		VALUES
		(
			@SRM_ENTITIES_SEQ_ID,
			@NEW_SRM_ENTITIES_SEQ_ID,
			@SRM_CLIENT_ENTITIES_SEQ_ID,
			@NEW_SRM_CLIENT_ENTITIES_SEQ_ID
		)

		FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY
	END

	CLOSE CUR_ENTITIES 
	DEALLOCATE CUR_ENTITIES 


	
-------------------------------------------- [SRM-Workflow].dbo.WFL_WORKFLOWS -------------------------------------------------------


DECLARE CUR_WFL_WORKFLOWS CURSOR STATIC FOR
SELECT SEQ_ID, SRM_CLIENT_ENTITY_SEQ_ID, EXPRESSION FROM [SRM-Workflow].dbo.WFL_WORKFLOWS w
WHERE w.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID

OPEN CUR_WFL_WORKFLOWS 

FETCH NEXT FROM CUR_WFL_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @XML_EXPRESSION

WHILE @@FETCH_STATUS = 0
BEGIN

	
	

	IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NOT NULL AND @SRM_CLIENT_ENTITIES_SEQ_ID > 0
    BEGIN  
		SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = t.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM  @TEMP_ENTITY_CLIENT_ENTITY_TABLE t 
		WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
	END 
	ELSE
	BEGIN
  		SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = NULL
	END 
	
	IF (@XML_EXPRESSION.exist('//CLIENT_ENTITY_ID') = 1)
	BEGIN
		SET @I = 0
		SET @I = @XML_EXPRESSION.value('count(//CLIENT_ENTITY_ID)', 'VARCHAR(10)')
		WHILE @I > 0	
		BEGIN
			SET @SRM_CLIENT_ENTITY_SEQ_ID_NEW = 0
			SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD = 0

			SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD =  RTRIM(LTRIM(REPLACE(REPLACE((@XML_EXPRESSION.value('((//CLIENT_ENTITY_ID)[sql:variable("@I")]/node())[1]', 'VARCHAR(10)')), CHAR(10), ''), CHAR(13), '')))

			IF (@SRM_CLIENT_ENTITY_SEQ_ID_OLD > 0)
			BEGIN
				SELECT @SRM_CLIENT_ENTITY_SEQ_ID_NEW = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID_OLD

				IF (@SRM_CLIENT_ENTITY_SEQ_ID_NEW > 0)
				BEGIN
					SET @XML_EXPRESSION.modify('replace value of ((//CLIENT_ENTITY_ID)[sql:variable("@I")]/text())[1] with sql:variable("@SRM_CLIENT_ENTITY_SEQ_ID_NEW")')
				END 
			END
			SET @I = @I - 1
		END
	END 
	
	INSERT INTO [SRM-Workflow].dbo.WFL_WORKFLOWS
	        ( DESCRIPTION ,
				SRM_CLIENT_ENTITY_SEQ_ID ,
				EXPRESSION ,
				REMARKS ,
				SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DIAGRAM_XML ,
				DIAGRAM_DETAIL ,
				SHOW_IN_JOBS ,
				OUTPUT_FILENAME ,
				DO_NOT_USE_QUOTE ,
				IS_ASYNC ,
				REQUIRE_MANUAL_INPUT ,
				ALWAYS_TRIGGER ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				DATE_CREATED ,
				CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY ,
				SHOW_ON_QUERYBUILDER ,
				TRACKABLE ,
				SHOW_NOTIFICATION ,
				INPUT_HEADING ,
				INPUT_BUTTON_TEXT ,
				INPUT_SUCCESS_MESSAGE ,
				INPUT_FAILURE_MESSAGE ,
				EXPORT_WITHOUT_HEADING ,
				AVAILABLE_FOR_TEMPLATES ,
				SRM_WORKFLOWS_SEQ_ID ,
				REQUIRE_TEMPLATE_INPUT
	        )
	SELECT  DESCRIPTION ,
			@NEW_SRM_CLIENT_ENTITIES_SEQ_ID ,
			CONVERT(NVARCHAR(MAX),@XML_EXPRESSION) ,
			REMARKS ,
			@TO_SRM_CLIENTS_SEQ_ID ,
			SOURCE_OF_DATA ,
			SOURCE_FILE ,
			DIAGRAM_XML ,
			DIAGRAM_DETAIL ,
			SHOW_IN_JOBS ,
			OUTPUT_FILENAME ,
			DO_NOT_USE_QUOTE ,
			IS_ASYNC ,
			REQUIRE_MANUAL_INPUT ,
			ALWAYS_TRIGGER ,
			DATE_MODIFIED ,
			MODIFIED_BY ,
			@DATE_CREATED ,
			@CREATED_BY ,
			DELETED ,
			DATE_DELETED ,
			DELETED_BY ,
			SHOW_ON_QUERYBUILDER ,
			TRACKABLE ,
			SHOW_NOTIFICATION ,
			INPUT_HEADING ,
			INPUT_BUTTON_TEXT ,
			INPUT_SUCCESS_MESSAGE ,
			INPUT_FAILURE_MESSAGE ,
			EXPORT_WITHOUT_HEADING ,
			AVAILABLE_FOR_TEMPLATES ,
			SRM_WORKFLOWS_SEQ_ID ,
			REQUIRE_TEMPLATE_INPUT 
	FROM [SRM-Workflow].dbo.WFL_WORKFLOWS AS ww
	WHERE SEQ_ID = @WFL_WORKFLOWS_SEQ_ID

	SET @NEW_WORKFLOWS_SEQ_ID = @@IDENTITY

	--------------------------------------- INSERT [SRM-Workflow].dbo.WFL_DESIGNER_TASK_DETAILS ---------------------------------------

	PRINT 'Add WFL_DESIGNER_TASK_DETAILS'
	INSERT INTO [SRM-Workflow].dbo.WFL_DESIGNER_TASK_DETAILS
	        ( DESIGNER_TASK_ID ,
	          WFL_WORKFLOWS_SEQ_ID ,
	          TASK_NAME ,
	          TASK_DETAIL ,
	          TASK_TYPE_ID ,
	          TASK_VARIABLES ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  DESIGNER_TASK_ID ,
	        @NEW_WORKFLOWS_SEQ_ID ,
	        TASK_NAME ,
	        TASK_DETAIL ,
	        TASK_TYPE_ID ,
	        TASK_VARIABLES ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        GETDATE() ,
			'RHA' ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd 
	WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID

	PRINT 'Add WFL_DESIGNER_VARIABLES'
	INSERT INTO [SRM-Workflow].dbo.WFL_DESIGNER_VARIABLES
	        ( WFL_WORKFLOW_SEQ_ID ,
	          TASK_ID ,
	          VARIABLE_NAME ,
	          VARIABLE_DETAIL ,
	          VARIABLE_TYPE ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  @NEW_WORKFLOWS_SEQ_ID ,
	        TASK_ID ,
	        VARIABLE_NAME ,
	        VARIABLE_DETAIL ,
	        VARIABLE_TYPE ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        GETDATE() ,
			'RHA' ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-Workflow].dbo.WFL_DESIGNER_VARIABLES wdv
	WHERE wdv.WFL_WORKFLOW_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID

	PRINT 'Add WFL_DESIGNER_CONNECTIONS'
	INSERT INTO [SRM-Workflow].dbo.WFL_DESIGNER_CONNECTIONS
	        ( WFL_WORKFLOW_SEQ_ID ,
	          CONNECTION_DETAIL ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  @NEW_WORKFLOWS_SEQ_ID ,
	        CONNECTION_DETAIL ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        GETDATE() ,
			'RHA' ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-Workflow].dbo.WFL_DESIGNER_CONNECTIONS AS wdc 
	WHERE WFL_WORKFLOW_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID

	--------------------------------------- INSERT [SRM-Workflow].dbo.WFL_DESIGNER_TASK_DETAILS ---------------------------------------

	INSERT INTO @TEMP_WFL_WORKFLOWS_TABLE
	(
		WFL_WORKFLOWS_SEQ_ID,
		WFL_WORKFLOWS_SEQ_ID2
	)
	VALUES
	(
		@WFL_WORKFLOWS_SEQ_ID,
		@NEW_WORKFLOWS_SEQ_ID
	)	


FETCH NEXT FROM CUR_WFL_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @XML_EXPRESSION
END

CLOSE CUR_WFL_WORKFLOWS 
DEALLOCATE CUR_WFL_WORKFLOWS

--Create Temp Workflows Table
