--EXECUTE(@TEMP_TABLE_QUERY)

IF (EXISTS (SELECT * FROM [SRM-ClientCopyLog].INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = 'dbo' AND  TABLE_NAME = 'TEMP_WFL_WORKFLOWS_TABLE'))
BEGIN
	DROP TABLE [SRM-ClientCopyLog].dbo.TEMP_WFL_WORKFLOWS_TABLE
END
