INSERT INTO [SRM-ClientCopyLog].[dbo].[SRM_CLIENT_WORKFLOW_COPY_LOG] (LOG_TYPE_ID,LOG_TYPE_DESCRIPTION,WFL_WORKFLOWS_SEQ_ID_OLD,
WFL_WORKFLOWS_SEQ_ID_NEW,SRM_CLIENTS_SEQ_ID_OLD,SRM_CLIENTS_SEQ_ID_NEW,SRM_USERS_SEQ_ID_OLD,SRM_USERS_SEQ_ID_NEW)
SELECT 4,'WORKFLOW MAPPING', WFL_WORKFLOWS_SEQ_ID, WFL_WORKFLOWS_SEQ_ID2, @FROM_SRM_CLIENTS_SEQ_ID,
