-------------------------------------------- [SRM-Workflow].dbo.WFL_WORKFLOWS ------------------------------------------------------


---------------------------------------- UPDATE [SRM-Workflow].WFL_DESIGNER_TASK_DETAILS --------------------------------------------------

		DECLARE CUR_WFL_DESIGNER_TASK_DETAILS CURSOR STATIC FOR 
		SELECT WFL_DESIGNER_TASK_DETAIL_SEQ_ID, DESIGNER_TASK_ID, TASK_DETAIL, WFL_WORKFLOWS_SEQ_ID, TASK_TYPE_ID
		FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd 
		WHERE WFL_WORKFLOWS_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)

		OPEN CUR_WFL_DESIGNER_TASK_DETAILS 

		FETCH NEXT FROM CUR_WFL_DESIGNER_TASK_DETAILS INTO @WFL_DESIGNER_TASK_DETAIL_SEQ_ID, @OLD_DESIGNER_TASK_ID, @OLD_TASK_DETAIL, @WORKFLOWS_SEQ_ID, @TASK_TYPE_ID

		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @OLD_DESIGNER_TASK_ID = '00000000-0000-0000-0000-000000000000'
			BEGIN
				SET @NEW_DESIGNER_TASK_ID = @OLD_DESIGNER_TASK_ID
			END 
			ELSE
			BEGIN
				SET @NEW_DESIGNER_TASK_ID = NEWID()
			END

			SET @OLD_TASK_DETAIL = REPLACE(@OLD_TASK_DETAIL, @OLD_DESIGNER_TASK_ID, @NEW_DESIGNER_TASK_ID)
    
			SET @NEW_TASK_DETAIL_XML = CONVERT(XML, @OLD_TASK_DETAIL)
  
			IF (@NEW_TASK_DETAIL_XML.exist('//EntityId') = 1)
			BEGIN
				SET @I = 0
				SET @I = @NEW_TASK_DETAIL_XML.value('count(//EntityId)', 'INT')
				WHILE @I > 0	
				BEGIN
					SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = 0
					SET @SRM_CLIENT_ENTITIES_SEQ_ID = 0

					SET @SRM_CLIENT_ENTITIES_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//EntityId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

					IF (@SRM_CLIENT_ENTITIES_SEQ_ID > 0)
					BEGIN
						SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

						IF (@NEW_SRM_CLIENT_ENTITIES_SEQ_ID > 0)
						BEGIN
							SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//EntityId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_SRM_CLIENT_ENTITIES_SEQ_ID")')
						END 
					END
					SET @I = @I - 1
				END
			END      
  
			IF (@NEW_TASK_DETAIL_XML.exist('//WorkflowId') = 1)
			BEGIN
				SET @I = 0
				SET @I = @NEW_TASK_DETAIL_XML.value('count(//WorkflowId)', 'INT')
				WHILE @I > 0	
				BEGIN
					SET @NEW_WORKFLOWS_SEQ_ID = 0
					SET @OLD_WORKFLOWS_SEQ_ID = 0

					SET @OLD_WORKFLOWS_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//WorkflowId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

					IF (@OLD_WORKFLOWS_SEQ_ID > 0)
					BEGIN
						SET @NEW_WORKFLOWS_SEQ_ID = (SELECT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @OLD_WORKFLOWS_SEQ_ID)

						IF (@NEW_WORKFLOWS_SEQ_ID > 0)
						BEGIN
							SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//WorkflowId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_WORKFLOWS_SEQ_ID")')
						END 
					END
					SET @I = @I - 1
				END
			END 
  
			IF (@NEW_TASK_DETAIL_XML.exist('//SubworkflowId') = 1)
			BEGIN
				SET @I = 0
				SET @I = @NEW_TASK_DETAIL_XML.value('count(//SubworkflowId)', 'INT')
				WHILE @I > 0	
				BEGIN
					SET @NEW_WORKFLOWS_SEQ_ID = 0
					SET @OLD_WORKFLOWS_SEQ_ID = 0

					SET @OLD_WORKFLOWS_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//SubworkflowId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

					IF (@OLD_WORKFLOWS_SEQ_ID > 0)
					BEGIN
