		--SET @TEMP_TABLE_QUERY = 'SELECT * INTO [SRM-WorkFlow].dbo.TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE_'+ @TEMP_TABLE_NAME_POSTFIX +' FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE'
		--EXECUTE(@TEMP_TABLE_QUERY)

		IF (EXISTS (SELECT * FROM [SRM-ClientCopyLog].INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = 'dbo' AND  TABLE_NAME = 'TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE'))
		BEGIN
			DROP TABLE [SRM-ClientCopyLog].dbo.TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE
		END
		SELECT * INTO [SRM-ClientCopyLog].dbo.TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE

		------------------------For Update WFL_DESIGNER_TASK_DETAILS------------------------

		DECLARE @OLD_TASK_ID VARCHAR(100)
		DECLARE @NEW_TASK_ID VARCHAR(100)

		DECLARE CUR_WFL_DESIGNER_TASK_DETAILS_2 CURSOR STATIC FOR 
		SELECT WFL_DESIGNER_TASK_DETAIL_SEQ_ID, DESIGNER_TASK_ID, TASK_DETAIL, WFL_WORKFLOWS_SEQ_ID
		FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd 
		WHERE WFL_WORKFLOWS_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)
		AND TASK_TYPE_ID = 4

		OPEN CUR_WFL_DESIGNER_TASK_DETAILS_2 

		FETCH NEXT FROM CUR_WFL_DESIGNER_TASK_DETAILS_2 INTO @WFL_DESIGNER_TASK_DETAIL_SEQ_ID, @OLD_DESIGNER_TASK_ID, @OLD_TASK_DETAIL, @WORKFLOWS_SEQ_ID

		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @NEW_TASK_DETAIL_XML = CONVERT(XML,@OLD_TASK_DETAIL)

			IF (@NEW_TASK_DETAIL_XML.exist('//ConditionalMappingsModel/TaskId') = 1)
				BEGIN
					SET @I = 0
					SET @I = @NEW_TASK_DETAIL_XML.value('count(//ConditionalMappingsModel/TaskId)', 'INT')
					WHILE @I > 0	
					BEGIN
						SET @OLD_TASK_ID = (@NEW_TASK_DETAIL_XML.value('((//ConditionalMappingsModel)[sql:variable("@I")]/TaskId/node())[1]', 'VARCHAR(MAX)'))
						SET @NEW_TASK_ID = (SELECT TOP 1 NEW_DESIGNER_TASK_ID FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE WHERE OLD_DESIGNER_TASK_ID = @OLD_TASK_ID)

						IF @NEW_TASK_ID != ''
						BEGIN
					
							SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//ConditionalMappingsModel)[sql:variable("@I")]/TaskId/text())[1] with sql:variable("@NEW_TASK_ID")')

							UPDATE [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS
							SET TASK_DETAIL = CONVERT(NVARCHAR(max),@NEW_TASK_DETAIL_XML)
							WHERE WFL_DESIGNER_TASK_DETAIL_SEQ_ID = @WFL_DESIGNER_TASK_DETAIL_SEQ_ID

						END 

						SET @I = @I - 1
					END
				END 

			FETCH NEXT FROM CUR_WFL_DESIGNER_TASK_DETAILS_2 INTO @WFL_DESIGNER_TASK_DETAIL_SEQ_ID, @OLD_DESIGNER_TASK_ID, @OLD_TASK_DETAIL, @WORKFLOWS_SEQ_ID
		END

		CLOSE CUR_WFL_DESIGNER_TASK_DETAILS_2 
		DEALLOCATE CUR_WFL_DESIGNER_TASK_DETAILS_2  

		------------------------For Update WFL_DESIGNER_TASK_DETAILS------------------------

		---------------------------------------- UPDATE [SRM-Workflow].WFL_DESIGNER_TASK_DETAILS --------------------------------------------------


		---- Update DIAGRAM_DETAIL, DIAGRAM_XML in WFL_WORKFLOWS ---------

		DECLARE @DIAGRAM_DETAIL NVARCHAR(MAX)
		DECLARE @DIAGRAM_XML NVARCHAR(MAX)

		PRINT 'Update TaskId in DIAGRAM_DETAIL, DIAGRAM_XML in [SRM-WorkFlow].dbo.WFL_WORKFLOWS'

		DECLARE CUR_WFL_WORKFLOWS CURSOR STATIC FOR
		SELECT SEQ_ID, DIAGRAM_DETAIL, DIAGRAM_XML FROM [SRM-WorkFlow].dbo.WFL_WORKFLOWS AS ww WHERE SEQ_ID IN
		(SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)
		AND (DIAGRAM_DETAIL IS NOT NULL OR DIAGRAM_XML IS NOT NULL)

		OPEN CUR_WFL_WORKFLOWS 

		FETCH NEXT FROM CUR_WFL_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID, @DIAGRAM_DETAIL, @DIAGRAM_XML

		WHILE @@FETCH_STATUS = 0
		BEGIN
				--------------------------------

				DECLARE CUR_DESIGNER_TASK CURSOR STATIC FOR
				SELECT DESIGNER_TASK_ID FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd
				WHERE WFL_WORKFLOWS_SEQ_ID = (SELECT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE 
				WHERE WFL_WORKFLOWS_SEQ_ID2 = @WFL_WORKFLOWS_SEQ_ID)

				OPEN CUR_DESIGNER_TASK 

				FETCH NEXT FROM CUR_DESIGNER_TASK INTO @OLD_TASK_ID

				WHILE @@FETCH_STATUS = 0
				BEGIN

					SET @NEW_TASK_ID = (SELECT TOP 1 NEW_DESIGNER_TASK_ID FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE WHERE OLD_DESIGNER_TASK_ID = @OLD_TASK_ID)

					IF @NEW_TASK_ID != '' 
					BEGIN
						SET @DIAGRAM_DETAIL = REPLACE(@DIAGRAM_DETAIL, @OLD_TASK_ID, @NEW_TASK_ID)
						SET @DIAGRAM_XML = REPLACE(@DIAGRAM_XML, @OLD_TASK_ID, @NEW_TASK_ID)
					END
				

				FETCH NEXT FROM CUR_DESIGNER_TASK INTO @OLD_TASK_ID
				END

				CLOSE CUR_DESIGNER_TASK 
				DEALLOCATE CUR_DESIGNER_TASK

				--------------------------------

				UPDATE [SRM-Workflow].dbo.WFL_WORKFLOWS
				SET DIAGRAM_DETAIL = @DIAGRAM_DETAIL, DIAGRAM_XML = @DIAGRAM_XML
				WHERE SEQ_ID = @WFL_WORKFLOWS_SEQ_ID
	

		FETCH NEXT FROM CUR_WFL_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID, @DIAGRAM_DETAIL, @DIAGRAM_XML
		END

		CLOSE CUR_WFL_WORKFLOWS 
		DEALLOCATE CUR_WFL_WORKFLOWS

		---- Update DIAGRAM_DETAIL, DIAGRAM_XML in WFL_WORKFLOWS ---------

		


		---- Replace WFL_DESIGNER_VARIABLES ------

		PRINT 'Replace VariableId/TaskId/WorkflowId in WFL_DESIGNER_VARIABLES'

		DECLARE @WFL_DESIGNER_VARIABLES_SEQ_ID BIGINT
		DECLARE @VARIABLE_DETAIL NVARCHAR(MAX)
		DECLARE @NEW_SEQ_ID BIGINT

		DECLARE CUR_WFL_DESIGNER_VARIABLES CURSOR STATIC FOR
		SELECT SEQ_ID, TASK_ID, VARIABLE_DETAIL FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_VARIABLES AS ww 
		WHERE WFL_WORKFLOW_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)

		OPEN CUR_WFL_DESIGNER_VARIABLES 

		FETCH NEXT FROM CUR_WFL_DESIGNER_VARIABLES INTO @WFL_DESIGNER_VARIABLES_SEQ_ID, @OLD_TASK_ID, @VARIABLE_DETAIL

		WHILE @@FETCH_STATUS = 0
		BEGIN

				SET @NEW_TASK_ID = (SELECT TOP 1 NEW_DESIGNER_TASK_ID FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE WHERE OLD_DESIGNER_TASK_ID = @OLD_TASK_ID)

				SET @NEW_TASK_DETAIL_XML = CONVERT(XML,@VARIABLE_DETAIL)

				IF (@NEW_TASK_DETAIL_XML.exist('//VariableId') = 1)
				BEGIN
					SET @I = 0
					SET @I = @NEW_TASK_DETAIL_XML.value('count(//VariableId)', 'BIGINT')
					WHILE @I > 0	
					BEGIN
  
						SET @NEW_SEQ_ID = @WFL_DESIGNER_VARIABLES_SEQ_ID          
						SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//VariableId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_SEQ_ID")')
						SET @I = @I - 1

					END
				END 

				IF (@NEW_TASK_DETAIL_XML.exist('//TaskId') = 1)
				BEGIN
					SET @I = 0
					SET @I = @NEW_TASK_DETAIL_XML.value('count(//TaskId)', 'INT')
					WHILE @I > 0	
					BEGIN
						SET @OLD_TASK_ID = (@NEW_TASK_DETAIL_XML.value('((//TaskId)[sql:variable("@I")]/node())[1]', 'VARCHAR(MAX)'))
						SET @NEW_TASK_ID = (SELECT TOP 1 NEW_DESIGNER_TASK_ID FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE WHERE OLD_DESIGNER_TASK_ID = @OLD_TASK_ID)

						IF @NEW_TASK_ID != ''
						BEGIN
							SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//TaskId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_TASK_ID")')
						END 

						SET @I = @I - 1
					END
				END
		
				IF (@NEW_TASK_DETAIL_XML.exist('//WorkflowId') = 1)
				BEGIN
					SET @I = 0
					SET @I = @NEW_TASK_DETAIL_XML.value('count(//WorkflowId)', 'INT')
					WHILE @I > 0	
					BEGIN
						SET @NEW_WORKFLOWS_SEQ_ID = 0
						SET @OLD_WORKFLOWS_SEQ_ID = 0

						SET @OLD_WORKFLOWS_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//WorkflowId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

						IF (@OLD_WORKFLOWS_SEQ_ID > 0)
						BEGIN
							SET @NEW_WORKFLOWS_SEQ_ID = (SELECT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @OLD_WORKFLOWS_SEQ_ID)

							IF (@NEW_WORKFLOWS_SEQ_ID > 0)
							BEGIN
								SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//WorkflowId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_WORKFLOWS_SEQ_ID")')
							END 
						END
						SET @I = @I - 1
					END
				END  

				UPDATE [SRM-Workflow].dbo.WFL_DESIGNER_VARIABLES
				SET TASK_ID = @NEW_TASK_ID, VARIABLE_DETAIL = CONVERT(NVARCHAR(MAX),@NEW_TASK_DETAIL_XML)
				WHERE SEQ_ID = @WFL_DESIGNER_VARIABLES_SEQ_ID

		FETCH NEXT FROM CUR_WFL_DESIGNER_VARIABLES INTO @WFL_DESIGNER_VARIABLES_SEQ_ID, @OLD_TASK_ID, @VARIABLE_DETAIL
		END

		CLOSE CUR_WFL_DESIGNER_VARIABLES 
		DEALLOCATE CUR_WFL_DESIGNER_VARIABLES


		---- Replace WFL_DESIGNER_VARIABLES ------

		DECLARE @WFL_DESIGNER_CONNECTIONS_SEQ_ID BIGINT
		DECLARE @CONNECTION_DETAIL NVARCHAR(MAX)


		---- Update CONNECTION_DETAIL in WFL_DESIGNER_CONNECTIONS ---------

		PRINT 'Replace TaskId in WFL_DESIGNER_CONNECTIONS'

		DECLARE CUR_WFL_DESIGNER_CONNECTIONS CURSOR STATIC FOR
		SELECT SEQ_ID, WFL_WORKFLOW_SEQ_ID, CONNECTION_DETAIL FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_CONNECTIONS AS ww 
		WHERE WFL_WORKFLOW_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)

		OPEN CUR_WFL_DESIGNER_CONNECTIONS 

		FETCH NEXT FROM CUR_WFL_DESIGNER_CONNECTIONS INTO @WFL_DESIGNER_CONNECTIONS_SEQ_ID, @WFL_WORKFLOWS_SEQ_ID, @CONNECTION_DETAIL

		WHILE @@FETCH_STATUS = 0
		BEGIN

				--------------------------------

				DECLARE CUR_DESIGNER_TASK CURSOR STATIC FOR
				SELECT DESIGNER_TASK_ID FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd
				WHERE WFL_WORKFLOWS_SEQ_ID = (SELECT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE 
				WHERE WFL_WORKFLOWS_SEQ_ID2 = @WFL_WORKFLOWS_SEQ_ID)

				OPEN CUR_DESIGNER_TASK 

				FETCH NEXT FROM CUR_DESIGNER_TASK INTO @OLD_TASK_ID

				WHILE @@FETCH_STATUS = 0
				BEGIN

					SET @NEW_TASK_ID = (SELECT TOP 1 NEW_DESIGNER_TASK_ID FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE WHERE OLD_DESIGNER_TASK_ID = @OLD_TASK_ID)

					IF @NEW_TASK_ID != '' 
					BEGIN
						SET @CONNECTION_DETAIL = REPLACE(@CONNECTION_DETAIL, @OLD_TASK_ID, @NEW_TASK_ID)
					END

				FETCH NEXT FROM CUR_DESIGNER_TASK INTO @OLD_TASK_ID
				END

				CLOSE CUR_DESIGNER_TASK 
				DEALLOCATE CUR_DESIGNER_TASK

				--------------------------------

		UPDATE [SRM-Workflow].dbo.WFL_DESIGNER_CONNECTIONS
		SET CONNECTION_DETAIL = @CONNECTION_DETAIL
		WHERE SEQ_ID = @WFL_DESIGNER_CONNECTIONS_SEQ_ID
	

	FETCH NEXT FROM CUR_WFL_DESIGNER_CONNECTIONS INTO @WFL_DESIGNER_CONNECTIONS_SEQ_ID, @WFL_WORKFLOWS_SEQ_ID, @CONNECTION_DETAIL
	END

	CLOSE CUR_WFL_DESIGNER_CONNECTIONS 
	DEALLOCATE CUR_WFL_DESIGNER_CONNECTIONS


	---- Update CONNECTION_DETAIL in WFL_DESIGNER_CONNECTIONS ---------


	-- ATTRIBUTES

	DECLARE CUR_ENTITIES CURSOR STATIC FOR
	SELECT SRM_ENTITIES.SEQ_ID, SRM_CLIENT_ENTITIES.SEQ_ID, ISNULL(SYSTEM_ENTITY, 'N') FROM SRM_ENTITIES, SRM_CLIENT_ENTITIES 
	WHERE SRM_ENTITIES.SEQ_ID = SRM_CLIENT_ENTITIES.SRM_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID

	OPEN CUR_ENTITIES 

	FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SELECT @NEW_SRM_ENTITIES_SEQ_ID = SRM_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_ENTITIES_SEQ_ID = @SRM_ENTITIES_SEQ_ID
		SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

		DECLARE CUR_ATTRIBUTES CURSOR STATIC FOR
		SELECT SRM_ENTITY_ATTRIBUTES.SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES.SEQ_ID, SYSTEM_ATTRIBUTE FROM SRM_ENTITY_ATTRIBUTES, SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_ENTITY_ATTRIBUTES.SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_ENTITY_ATTRIBUTES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

		OPEN CUR_ATTRIBUTES 

		FETCH NEXT FROM CUR_ATTRIBUTES INTO @SRM_ENTITY_ATTRIBUTES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @SYSTEM_ATTRIBUTE

		WHILE @@FETCH_STATUS = 0
		BEGIN
			IF @SYSTEM_ENTITY = 'Y' AND @SYSTEM_ATTRIBUTE = 'Y'
			BEGIN
				SET @NEW_SRM_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_ENTITY_ATTRIBUTES_SEQ_ID
			END
			ELSE
			BEGIN
				INSERT INTO SRM_ENTITY_ATTRIBUTES
				(
					SRM_ENTITIES_SEQ_ID,
					SYSTEM_NAME,
					PROPERTY_NAME,
					SOURCE_OF_DATA,
					SOURCE_FILE,
					DATE_MODIFIED,
					MODIFIED_BY,
					DATE_CREATED,
					CREATED_BY,
					DELETED,
					DATE_DELETED,
					DELETED_BY
				)
				SELECT 
					@NEW_SRM_ENTITIES_SEQ_ID,
					SYSTEM_NAME,
					PROPERTY_NAME,
					NULL,
					NULL,
					NULL,
					NULL,
					@DATE_CREATED,
					@CREATED_BY,
					'N',
					NULL,
					NULL			
				FROM SRM_ENTITY_ATTRIBUTES WHERE SRM_ENTITY_ATTRIBUTES.SEQ_ID = @SRM_ENTITY_ATTRIBUTES_SEQ_ID

				SET @NEW_SRM_ENTITY_ATTRIBUTES_SEQ_ID = @@IDENTITY

				INSERT INTO SRM_CLIENT_LANGUAGE_ITEMS
				(
					SRM_LANGUAGES_SEQ_ID,
					SRM_CLIENTS_SEQ_ID,
					OBJECT_ID,
					OBJECT_TYPE,
					SRM_LANGUAGE_TOKENS_SEQ_ID,
					PHRASE,
					SOURCE_OF_DATA,
					SOURCE_FILE,
					DATE_MODIFIED,
					MODIFIED_BY,
					DATE_CREATED,
					CREATED_BY,
					DELETED,
					DATE_DELETED,
					DELETED_BY
				)
				SELECT 
					SRM_LANGUAGES_SEQ_ID,
					@TO_SRM_CLIENTS_SEQ_ID,
					@NEW_SRM_ENTITY_ATTRIBUTES_SEQ_ID,
					OBJECT_TYPE,
					SRM_LANGUAGE_TOKENS_SEQ_ID,
					PHRASE,
					NULL, --SOURCE_OF_DATA
					NULL,
					NULL,
					NULL,
					@DATE_CREATED,
					@CREATED_BY,
					'N',
					NULL,
					NULL			
				FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 3 AND SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND OBJECT_ID = @SRM_ENTITY_ATTRIBUTES_SEQ_ID
			END
			INSERT INTO SRM_CLIENT_ENTITY_ATTRIBUTES
			(
				SRM_CLIENT_ENTITIES_SEQ_ID,
				SRM_CLIENT_ENTITIES_SEQ_ID2,
				SRM_ENTITY_ATTRIBUTES_SEQ_ID,
				SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
				SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID,
				ATTRIBUTE_DISPLAY_NAME,
				REFERENCED_SERVICE_ID,
				SYSTEM_ATTRIBUTE,
				STANDARD_ATTRIBUTE,
				DISPLAY_ATTRIBUTE,
				DEFAULT_VALUE,
				MAX_LENGTH,
				DECIMAL_PLACES,
				VISIBLE_LINES,
				DISPLAY_FORMAT,
				STARTING_NUMBER,
				MANDATORY,
				GENERATE_AUTO_NUMBER_FOR_EXISTING_RECORDS,
				DISTINCTIVE,
				DISTINCTIVE_CASE_SENSITIVE,
				SORT_VALUE,
				MASK_CHARACTER,
				STARTS_WITH_VOWEL_SOUND,
				ALLOW_ACTIVITIES,
				TRACK_FIELD_HISTORY,
				READ_ONLY,
				DELETE_ACTION_ID,
				DO_NOT_SHOW_ON_EDIT,
				LOOKUP_PICKLIST_NAME,
				SERViCE_SYSTEM_NAME,
				ATTRIBUTE_TYPE_ID,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY,
				ATTRIBUTE_ICON_URL,
				READ_ONLY_ON_EDIT,
				ATTRIBUTE_TYPE_GROUP_SEQ_ID,
				MERGE_ACTION_ID,
				DO_NOT_SHOW_IN_GLOBAL_UPDATE,
				SYSTEM_MODULE
			)
			SELECT
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID,
				(SELECT TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_CLIENT_ENTITIES_SEQ_ID2),
				--NULL,
				@NEW_SRM_ENTITY_ATTRIBUTES_SEQ_ID,
				NULL, -- UPDATED SEPERATELY BELOW
				SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID,
				ATTRIBUTE_DISPLAY_NAME,
				REFERENCED_SERVICE_ID,
				SYSTEM_ATTRIBUTE,
				STANDARD_ATTRIBUTE,
				DISPLAY_ATTRIBUTE,
				DEFAULT_VALUE,
				MAX_LENGTH,
				DECIMAL_PLACES,
				VISIBLE_LINES,
				DISPLAY_FORMAT,
				STARTING_NUMBER,
				MANDATORY,
				GENERATE_AUTO_NUMBER_FOR_EXISTING_RECORDS,
				DISTINCTIVE,
				DISTINCTIVE_CASE_SENSITIVE,
				SORT_VALUE,
				MASK_CHARACTER,
				STARTS_WITH_VOWEL_SOUND,
				ALLOW_ACTIVITIES,
				TRACK_FIELD_HISTORY,
				READ_ONLY,
				DELETE_ACTION_ID,
				DO_NOT_SHOW_ON_EDIT,
				LOOKUP_PICKLIST_NAME,
				SERViCE_SYSTEM_NAME,
				ATTRIBUTE_TYPE_ID,
				NULL,
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL,
				ATTRIBUTE_ICON_URL,
				READ_ONLY_ON_EDIT,
				ATTRIBUTE_TYPE_GROUP_SEQ_ID,
				MERGE_ACTION_ID,
				DO_NOT_SHOW_IN_GLOBAL_UPDATE,
				SYSTEM_MODULE			
			FROM SRM_CLIENT_ENTITY_ATTRIBUTES
			WHERE SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
				
			SET @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @@IDENTITY

			INSERT INTO @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE
				(SRM_ENTITIES_SEQ_ID,
				SRM_ENTITIES_SEQ_ID2,
				SRM_CLIENT_ENTITIES_SEQ_ID,
				SRM_CLIENT_ENTITIES_SEQ_ID2,
				SRM_ENTITY_ATTRIBUTES_SEQ_ID,
				SRM_ENTITY_ATTRIBUTES_SEQ_ID2,
				SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
				SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2
			)
			VALUES
			(
				@SRM_ENTITIES_SEQ_ID,
				@NEW_SRM_ENTITIES_SEQ_ID,
				@SRM_CLIENT_ENTITIES_SEQ_ID,
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID,
				@SRM_ENTITY_ATTRIBUTES_SEQ_ID,
				@NEW_SRM_ENTITY_ATTRIBUTES_SEQ_ID,
				@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
				@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
			)

			--------------------------------SRM_CLIENT_ENTITY_ATTRIBUTES_GROUP_DEFINATION-----------------------------

			INSERT INTO dbo.SRM_CLIENT_ENTITY_ATTRIBUTES_GROUP_DEFINATION
			( SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, SYSTEM_NAME, RANK, IS_DEFAULT, URL )
			SELECT @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, SYSTEM_NAME, RANK, IS_DEFAULT, URL
			FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTES_GROUP_DEFINATION AS sceagd
			WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

			--------------------------------SRM_CLIENT_ENTITY_ATTRIBUTES_GROUP_DEFINATION-----------------------------

			FETCH NEXT FROM CUR_ATTRIBUTES INTO @SRM_ENTITY_ATTRIBUTES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @SYSTEM_ATTRIBUTE
		END
		CLOSE CUR_ATTRIBUTES 
		DEALLOCATE CUR_ATTRIBUTES 

		-- SRM_CLIENT_ENTITY_BUTTONS
		DECLARE @CONTENT_SOURCE XML
		DECLARE @MAPPING XML      

		DECLARE CUR_CLIENT_ENTITY_BUTTONS CURSOR STATIC FOR
		SELECT SEQ_ID, CONTENT_SOURCE, MAPPING FROM SRM_CLIENT_ENTITY_BUTTONS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND (SRM_USERS_SEQ_ID IS NULL OR SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID)
		
		OPEN CUR_CLIENT_ENTITY_BUTTONS 

		FETCH NEXT FROM CUR_CLIENT_ENTITY_BUTTONS INTO @SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID, @CONTENT_SOURCE,@MAPPING

		WHILE @@FETCH_STATUS = 0
		BEGIN
  
			IF @MAPPING IS NOT NULL AND @MAPPING.exist('//EXPRESSION_DETAIL/UPDATE_TRANSECTION_WORK_FLOW_DETAILS/WORKFLOW_ID') = 1
			BEGIN
				SET @OLD_WORKFLOWS_SEQ_ID = (SELECT @MAPPING.value('(//EXPRESSION_DETAIL/UPDATE_TRANSECTION_WORK_FLOW_DETAILS/WORKFLOW_ID/node())[1]', 'VARCHAR(MAX)')) 
				SELECT @NEW_WORKFLOWS_SEQ_ID = WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @OLD_WORKFLOWS_SEQ_ID
				SET @MAPPING.modify('replace value of (//EXPRESSION_DETAIL/UPDATE_TRANSECTION_WORK_FLOW_DETAILS/WORKFLOW_ID/text())[1] with sql:variable("@NEW_WORKFLOWS_SEQ_ID")')
			END       
  
			IF @CONTENT_SOURCE IS NOT NULL AND @CONTENT_SOURCE.exist('//EXPRESSION/WORKFLOW/VALUE') = 1
			BEGIN
				SET @OLD_WORKFLOWS_SEQ_ID = (SELECT @CONTENT_SOURCE.value('(//EXPRESSION/WORKFLOW/VALUE/node())[1]', 'VARCHAR(MAX)')) 
				SELECT @NEW_WORKFLOWS_SEQ_ID = WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @OLD_WORKFLOWS_SEQ_ID
				SET @CONTENT_SOURCE.modify('replace value of (//EXPRESSION/WORKFLOW/VALUE/text())[1] with sql:variable("@NEW_WORKFLOWS_SEQ_ID")')
			END 
			
			IF (@CONTENT_SOURCE.exist('//CLIENT_ENTITY_ID') = 1)
			BEGIN
				SET @I = 0
				SET @I = @CONTENT_SOURCE.value('count(//CLIENT_ENTITY_ID)', 'VARCHAR(10)')
				WHILE @I > 0	
				BEGIN
					SET @SRM_CLIENT_ENTITY_SEQ_ID_NEW = 0
					SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD = 0

					SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD =  RTRIM(LTRIM(REPLACE(REPLACE((@CONTENT_SOURCE.value('((//CLIENT_ENTITY_ID)[sql:variable("@I")]/node())[1]', 'VARCHAR(10)')), CHAR(10), ''), CHAR(13), '')))

					IF (@SRM_CLIENT_ENTITY_SEQ_ID_OLD > 0)
					BEGIN
						SELECT @SRM_CLIENT_ENTITY_SEQ_ID_NEW = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID_OLD

						IF (@SRM_CLIENT_ENTITY_SEQ_ID_NEW > 0)
						BEGIN
							SET @CONTENT_SOURCE.modify('replace value of ((//CLIENT_ENTITY_ID)[sql:variable("@I")]/text())[1] with sql:variable("@SRM_CLIENT_ENTITY_SEQ_ID_NEW")')
						END 
					END
					SET @I = @I - 1
				END
			END
  
			IF @CONTENT_SOURCE IS NOT NULL AND @CONTENT_SOURCE.exist('//EXPRESSION/CLIENT_ENTITY_ID/VALUE') = 1
			BEGIN
				SET @SRM_CLIENT_ENTITY_SEQ_ID_NEW = 0
				SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD = 0
				SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD = (SELECT @CONTENT_SOURCE.value('(//EXPRESSION/CLIENT_ENTITY_ID/VALUE/node())[1]', 'VARCHAR(MAX)')) 

				SELECT @SRM_CLIENT_ENTITY_SEQ_ID_NEW = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID_OLD

				SET @CONTENT_SOURCE.modify('replace value of (//EXPRESSION/CLIENT_ENTITY_ID/VALUE/text())[1] with sql:variable("@SRM_CLIENT_ENTITY_SEQ_ID_NEW")')
			END
	
			IF (@CONTENT_SOURCE.exist('//USER_DETAILS/@CLIENT_ENTITY_ID') = 1)
			BEGIN
				SET @I = 0
				SET @I = @CONTENT_SOURCE.value('count(//USER_DETAILS/@CLIENT_ENTITY_ID)', 'VARCHAR(10)')
				WHILE @I > 0	
				BEGIN
					SET @SRM_CLIENT_ENTITY_SEQ_ID_NEW = 0
					SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD = 0

					SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD =  RTRIM(LTRIM(REPLACE(REPLACE((@CONTENT_SOURCE.value('((//USER_DETAILS/@CLIENT_ENTITY_ID)[sql:variable("@I")])[1]', 'VARCHAR(10)')), CHAR(10), ''), CHAR(13), '')))

					IF (@SRM_CLIENT_ENTITY_SEQ_ID_OLD > 0)
					BEGIN
						SELECT @SRM_CLIENT_ENTITY_SEQ_ID_NEW = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID_OLD

						IF (@SRM_CLIENT_ENTITY_SEQ_ID_NEW > 0)
						BEGIN
							SET @CONTENT_SOURCE.modify('replace value of ((//USER_DETAILS/@CLIENT_ENTITY_ID)[sql:variable("@I")])[1] with sql:variable("@SRM_CLIENT_ENTITY_SEQ_ID_NEW")')
						END 
					END
					SET @I = @I - 1
				END
			END  
        
			INSERT INTO SRM_CLIENT_ENTITY_BUTTONS
			(
				SRM_BUTTON_TYPES_SEQ_ID,
				SRM_CLIENT_ENTITIES_SEQ_ID,
				SRM_USERS_SEQ_ID,
				VISIBLE,
				BUTTON_ACTION,
				BEHAVIOUR_ID,
				APPLICABLE_TO_ID,
				CONTENT_SOURCE,
				MAPPING,
				BUTTON_ICON_COORDINATES,
				BUTTON_HOVER_ICON_COORDINATES,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				SRM_BUTTON_TYPES_SEQ_ID,
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID,
				CASE WHEN SRM_USERS_SEQ_ID IS NULL THEN NULL ELSE @TO_SRM_USERS_SEQ_ID END SRM_USERS_SEQ_ID,
				VISIBLE,
				BUTTON_ACTION,
				BEHAVIOUR_ID,
				APPLICABLE_TO_ID,
				CONVERT(NVARCHAR(MAX),@CONTENT_SOURCE),
				CONVERT(NVARCHAR(MAX),@MAPPING),
				BUTTON_ICON_COORDINATES,
				BUTTON_HOVER_ICON_COORDINATES,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL
			FROM SRM_CLIENT_ENTITY_BUTTONS WHERE SEQ_ID = @SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID

			SET @NEW_SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID = @@IDENTITY

			INSERT INTO @TEMP_ENTITY_BUTTONS
			(
				SRM_ENTITIES_SEQ_ID,
				SRM_ENTITIES_SEQ_ID2,
				SRM_CLIENT_ENTITIES_SEQ_ID,
				SRM_CLIENT_ENTITIES_SEQ_ID2,
				SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID,
				SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID2
			)
			VALUES
			(
				@SRM_ENTITIES_SEQ_ID,
				@NEW_SRM_ENTITIES_SEQ_ID,
				@SRM_CLIENT_ENTITIES_SEQ_ID,
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID,
				@SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID,
				@NEW_SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID
			)

			FETCH NEXT FROM CUR_CLIENT_ENTITY_BUTTONS INTO @SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID, @CONTENT_SOURCE, @MAPPING
		END

		CLOSE CUR_CLIENT_ENTITY_BUTTONS 
		DEALLOCATE CUR_CLIENT_ENTITY_BUTTONS 


		FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY
	END

	CLOSE CUR_ENTITIES 
	DEALLOCATE CUR_ENTITIES

	-- UPDATE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IN SRM_CLIENT_ENTITY_ATTRIBUTES TABLE
	DECLARE CUR_ATTRIBUTES CURSOR STATIC FOR
	SELECT SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IS NOT NULL

	OPEN CUR_ATTRIBUTES 

	FETCH NEXT FROM CUR_ATTRIBUTES INTO @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @REFERENCED_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SELECT @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
		SELECT @NEW_REFERENCED_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @REFERENCED_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

		UPDATE SRM_CLIENT_ENTITY_ATTRIBUTES
		SET SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @NEW_REFERENCED_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
		WHERE SEQ_ID = @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

		FETCH NEXT FROM CUR_ATTRIBUTES INTO @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @REFERENCED_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
	END

	CLOSE CUR_ATTRIBUTES 
	DEALLOCATE CUR_ATTRIBUTES 

	--REST OF THE TABLES
	ALTER TABLE SRM_CLIENT_FILTER_VIEW_ATTRIBUTES DISABLE TRIGGER ALL

	DECLARE CUR_ENTITIES CURSOR STATIC FOR
	SELECT SRM_ENTITIES.SEQ_ID, SRM_CLIENT_ENTITIES.SEQ_ID, SYSTEM_ENTITY FROM SRM_ENTITIES, SRM_CLIENT_ENTITIES WHERE SRM_ENTITIES.SEQ_ID = SRM_CLIENT_ENTITIES.SRM_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID

	OPEN CUR_ENTITIES 

	FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SELECT @NEW_SRM_ENTITIES_SEQ_ID = SRM_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_ENTITIES_SEQ_ID = @SRM_ENTITIES_SEQ_ID
		SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

		DECLARE CUR_ATTRIBUTE_GROUPS CURSOR STATIC FOR
		SELECT SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS.SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS 
		WHERE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND 
			(SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS.SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID
			OR (SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS.SRM_USERS_SEQ_ID IS NULL 
			AND SRM_CLIENT_ENTITIES_SEQ_ID NOT IN (SELECT SRM_CLIENT_ENTITIES_SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS.SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID)))
		
		OPEN CUR_ATTRIBUTE_GROUPS 

		FETCH NEXT FROM CUR_ATTRIBUTE_GROUPS INTO @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID

		WHILE @@FETCH_STATUS = 0
		BEGIN
			
			INSERT INTO SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS
			(
				SRM_CLIENT_ENTITIES_SEQ_ID,
				SRM_USERS_SEQ_ID,
				SYSTEM_NAME,
				GROUP_RANK,
				GROUP_TYPE_ID,
				NAVIGATION_SEQUENCE_ID,
				NUMBER_OF_COLUMNS,
				DISPLAY_ON_EDIT,
				DISPLAY_ON_DETAIL,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID,
				NULL,
				SYSTEM_NAME,
				GROUP_RANK,
				GROUP_TYPE_ID,
				NAVIGATION_SEQUENCE_ID,
				NUMBER_OF_COLUMNS,
				DISPLAY_ON_EDIT,
				DISPLAY_ON_DETAIL,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL
			FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID

			SET @NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID = @@IDENTITY

			INSERT INTO SRM_CLIENT_LANGUAGE_ITEMS
			(
				SRM_LANGUAGES_SEQ_ID,
				SRM_CLIENTS_SEQ_ID,
				OBJECT_ID,
				OBJECT_TYPE,
				SRM_LANGUAGE_TOKENS_SEQ_ID,
				PHRASE,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				SRM_LANGUAGES_SEQ_ID,
				@TO_SRM_CLIENTS_SEQ_ID,
				@NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID,
				OBJECT_TYPE,
				SRM_LANGUAGE_TOKENS_SEQ_ID,
				PHRASE,
				NULL, --SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL			
			FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 11 AND SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND OBJECT_ID = @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID 

			INSERT INTO SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS
			(
				SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID,
				SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
				SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID,
				ROW_INDEX,
				COLUMN_INDEX,
				DISPLAY_ONLY,
				DISPLAY_ONLY_ON_EDIT,
				MANDATORY,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				@NEW_SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID,
				TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2,
				NULL,
				ROW_INDEX,
				COLUMN_INDEX,
				DISPLAY_ONLY,
				DISPLAY_ONLY_ON_EDIT,
				MANDATORY,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL
			FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE
			WHERE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
				AND SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID 

			FETCH NEXT FROM CUR_ATTRIBUTE_GROUPS INTO @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID
		END

		CLOSE CUR_ATTRIBUTE_GROUPS 
		DEALLOCATE CUR_ATTRIBUTE_GROUPS 	

		--SRM_CLIENT_ENTITY_RELATED_LISTS WHERE USER ID IS NULL
		INSERT INTO SRM_CLIENT_ENTITY_RELATED_LISTS
		(
			SRM_CLIENT_ENTITIES_SEQ_ID,
			SRM_CLIENT_ENTITIES_SEQ_ID2,
			SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
			SRM_USERS_SEQ_ID,
			VISIBLE,
			RANK,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT 
			@NEW_SRM_CLIENT_ENTITIES_SEQ_ID,
			TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_CLIENT_ENTITIES_SEQ_ID2,
			CASE WHEN SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IS NOT NULL AND SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID != 0 THEN (SELECT SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID) ELSE SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID END,
			NULL,
			VISIBLE,
			RANK,
			NULL, -- SOURCE_OF_DATA
			NULL,
			NULL,
			NULL,
			@DATE_CREATED,
			@CREATED_BY,
			'N',
			NULL,
			NULL
		FROM SRM_CLIENT_ENTITY_RELATED_LISTS, @TEMP_ENTITY_CLIENT_ENTITY_TABLE TEMP_ENTITY_CLIENT_ENTITY_TABLE
		WHERE 
			SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
			AND SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITIES_SEQ_ID2 = TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_CLIENT_ENTITIES_SEQ_ID
			AND SRM_USERS_SEQ_ID IS NULL

		--SRM_CLIENT_ENTITY_RELATED_LISTS
		INSERT INTO SRM_CLIENT_ENTITY_RELATED_LISTS
		(
			SRM_CLIENT_ENTITIES_SEQ_ID,
			SRM_CLIENT_ENTITIES_SEQ_ID2,
			SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
			SRM_USERS_SEQ_ID,
			VISIBLE,
			RANK,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT 
			@NEW_SRM_CLIENT_ENTITIES_SEQ_ID,
			TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_CLIENT_ENTITIES_SEQ_ID2,
			CASE WHEN SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IS NOT NULL AND SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID != 0 THEN (SELECT SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID) ELSE SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID END,
			@TO_SRM_USERS_SEQ_ID,
			VISIBLE,
			RANK,
			NULL, -- SOURCE_OF_DATA
			NULL,
			NULL,
			NULL,
			@DATE_CREATED,
			@CREATED_BY,
			'N',
			NULL,
			NULL
		FROM SRM_CLIENT_ENTITY_RELATED_LISTS, @TEMP_ENTITY_CLIENT_ENTITY_TABLE TEMP_ENTITY_CLIENT_ENTITY_TABLE
		WHERE 
			SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID
			AND SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
			AND SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITIES_SEQ_ID2 = TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_CLIENT_ENTITIES_SEQ_ID
			AND SRM_USERS_SEQ_ID IS NOT NULL

		DECLARE CUR_FILTER_VIEWS CURSOR STATIC FOR
		SELECT scfv.SEQ_ID FROM dbo.SRM_CLIENT_FILTER_VIEWS AS scfv,dbo.SRM_CLIENT_ENTITIES AS sce
			WHERE sce.SEQ_ID = scfv.SRM_CLIENT_ENTITIES_SEQ_ID AND scfv.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND (sce.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND scfv.FILTER_VIEW_TYPE_ID != 4) AND (SRM_USERS_SEQ_ID IS NULL OR SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID)
		UNION
		SELECT scfv.SEQ_ID FROM dbo.SRM_CLIENT_FILTER_VIEWS AS scfv,dbo.SRM_CLIENT_ENTITIES AS sce
			WHERE sce.SEQ_ID = scfv.SRM_CLIENT_ENTITIES_SEQ_ID AND scfv.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND (sce.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND scfv.FILTER_VIEW_TYPE_ID = 4 AND (SRM_USERS_SEQ_ID IS NULL OR SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID) 
			AND scfv.SEQ_ID IN (SELECT MIN(scfv_internal.SEQ_ID) FROM dbo.SRM_CLIENT_FILTER_VIEWS AS scfv_internal,dbo.SRM_CLIENT_ENTITIES AS sce
				WHERE sce.SEQ_ID = scfv_internal.SRM_CLIENT_ENTITIES_SEQ_ID AND scfv_internal.FILTER_VIEW_TYPE_ID = 4 AND sce.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID
				GROUP BY scfv_internal.SRM_CLIENT_ENTITIES_SEQ_ID
			))

		OPEN CUR_FILTER_VIEWS 

		FETCH NEXT FROM CUR_FILTER_VIEWS INTO @SRM_CLIENT_FILTER_VIEWS_SEQ_ID

		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO SRM_CLIENT_FILTER_VIEWS
			(
				SYSTEM_NAME,
				SRM_USERS_SEQ_ID,
				SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
				SRM_CLIENT_ENTITIES_SEQ_ID,
				SRM_CLIENT_ENTITIES_SEQ_ID2,
				SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
				FILTER_VIEW_TYPE_ID,
				FILTER_LOGIC,
				VISIBLE_LINES,
				PAGE_SIZE,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				SYSTEM_NAME,
				NULL,
				NULL, ---- SRM_CLIENT_FILTER_VIEWS_SEQ_ID, ---NEED TO CHECK---
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID,
				(SELECT TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_FILTER_VIEWS.SRM_CLIENT_ENTITIES_SEQ_ID2),
				CASE WHEN SRM_CLIENT_FILTER_VIEWS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IS NOT NULL AND SRM_CLIENT_FILTER_VIEWS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID != 0 THEN (SELECT SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_FILTER_VIEWS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID) ELSE SRM_CLIENT_FILTER_VIEWS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID END,
				FILTER_VIEW_TYPE_ID,
				FILTER_LOGIC,
				VISIBLE_LINES,
				PAGE_SIZE,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL
			FROM SRM_CLIENT_FILTER_VIEWS
			WHERE SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID

			SET @NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @@IDENTITY

			INSERT INTO SRM_CLIENT_LANGUAGE_ITEMS
			(
				SRM_LANGUAGES_SEQ_ID,
				SRM_CLIENTS_SEQ_ID,
				OBJECT_ID,
				OBJECT_TYPE,
				SRM_LANGUAGE_TOKENS_SEQ_ID,
				PHRASE,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				SRM_LANGUAGES_SEQ_ID,
				@TO_SRM_CLIENTS_SEQ_ID,
				@NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
				OBJECT_TYPE,
				SRM_LANGUAGE_TOKENS_SEQ_ID,
				PHRASE,
				NULL, --SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL			
			FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 35 AND SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND OBJECT_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID

			INSERT INTO SRM_CLIENT_FILTER_VIEW_ATTRIBUTES
			(
				SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
				SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
				RANK,
				STANDARD_ATTRIBUTE,
				INTERNAL_ATTRIBUTE,
				SORT_RANK,
				SORT_DESCENDING,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY ,
				SHOW_FIELD,
				ON_SCREEN_SEARCH_FEILD,
				SEARCH_SCREEN_SEARCH_FEILD
			)
			SELECT 
				@NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
				TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2,
				RANK,
				STANDARD_ATTRIBUTE,
				INTERNAL_ATTRIBUTE,
				SORT_RANK,
				SORT_DESCENDING,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL,
				SHOW_FIELD,
				ON_SCREEN_SEARCH_FEILD,
				SEARCH_SCREEN_SEARCH_FEILD
			FROM SRM_CLIENT_FILTER_VIEW_ATTRIBUTES, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE
			WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID
				AND SRM_CLIENT_FILTER_VIEW_ATTRIBUTES.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
			
			INSERT INTO SRM_CLIENT_FILTER_VIEW_BUTTONS
			(
				SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
				SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID,
				RANK,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				@NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
				TEMP_ENTITY_BUTTONS.SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID2,
				RANK,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL
			FROM SRM_CLIENT_FILTER_VIEW_BUTTONS, @TEMP_ENTITY_BUTTONS TEMP_ENTITY_BUTTONS
			WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID
				AND SRM_CLIENT_FILTER_VIEW_BUTTONS.SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID = TEMP_ENTITY_BUTTONS.SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID

			INSERT INTO SRM_CLIENT_FILTER_VIEW_CRITERIA
			(
				SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
				SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
				RANK,
				OPERATOR_ID,
				CRITERIA_VALUE,
				FILTERED,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				@NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
				TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2,
				RANK,
				OPERATOR_ID,
				CRITERIA_VALUE,
				FILTERED,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL
			FROM SRM_CLIENT_FILTER_VIEW_CRITERIA, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE
			WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID
			AND SRM_CLIENT_FILTER_VIEW_CRITERIA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =  TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

			INSERT INTO SRM_CLIENT_FILTER_VIEW_DEFAULT
			(
				SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
				SRM_CLIENTS_SEQ_ID,
				SRM_USERS_SEQ_ID,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				@NEW_SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
				@TO_SRM_CLIENTS_SEQ_ID,
				NULL,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL
			FROM SRM_CLIENT_FILTER_VIEW_DEFAULT WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID AND SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID
	
			FETCH NEXT FROM CUR_FILTER_VIEWS INTO @SRM_CLIENT_FILTER_VIEWS_SEQ_ID
		END

		CLOSE CUR_FILTER_VIEWS 
		DEALLOCATE CUR_FILTER_VIEWS 

		FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SYSTEM_ENTITY
	END

	CLOSE CUR_ENTITIES 
	DEALLOCATE CUR_ENTITIES 

	ALTER TABLE SRM_CLIENT_FILTER_VIEW_ATTRIBUTES ENABLE TRIGGER ALL
	--MENUS

	DECLARE CUR_MENU_ITEMS CURSOR STATIC FOR
	SELECT SRM_CLIENT_MENU_ITEMS.SEQ_ID, SRM_MENU_ITEMS.SEQ_ID, MENU_TYPE_ID FROM SRM_CLIENT_MENU_ITEMS, SRM_MENU_ITEMS WHERE SRM_CLIENT_MENU_ITEMS.SRM_MENU_ITEMS_SEQ_ID = SRM_MENU_ITEMS.SEQ_ID AND SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID

	OPEN CUR_MENU_ITEMS 

	FETCH NEXT FROM CUR_MENU_ITEMS INTO @SRM_CLIENT_MENU_ITEMS_SEQ_ID, @SRM_MENU_ITEMS_SEQ_ID, @MENU_TYPE_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF @MENU_TYPE_ID = 1
		BEGIN
			INSERT INTO SRM_MENU_ITEMS
			(
				SRM_ENTITIES_SEQ_ID,
				COLOUR_ID,
				IMAGE_ID,
				MENU_TYPE_ID,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_ENTITIES_SEQ_ID2,
				COLOUR_ID,
				IMAGE_ID,
				MENU_TYPE_ID,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL
			FROM SRM_MENU_ITEMS, @TEMP_ENTITY_CLIENT_ENTITY_TABLE TEMP_ENTITY_CLIENT_ENTITY_TABLE
			WHERE SEQ_ID = @SRM_MENU_ITEMS_SEQ_ID
			AND SRM_MENU_ITEMS.SRM_ENTITIES_SEQ_ID = TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_ENTITIES_SEQ_ID
		END
		ELSE
		BEGIN
			INSERT INTO SRM_MENU_ITEMS
			(
				SRM_ENTITIES_SEQ_ID,
				COLOUR_ID,
				IMAGE_ID,
				MENU_TYPE_ID,
				SOURCE_OF_DATA,
				SOURCE_FILE,
				DATE_MODIFIED,
				MODIFIED_BY,
				DATE_CREATED,
				CREATED_BY,
				DELETED,
				DATE_DELETED,
				DELETED_BY
			)
			SELECT 
				NULL,
				COLOUR_ID,
				IMAGE_ID,
				MENU_TYPE_ID,
				NULL, -- SOURCE_OF_DATA
				NULL,
				NULL,
				NULL,
				@DATE_CREATED,
				@CREATED_BY,
				'N',
				NULL,
				NULL
			FROM SRM_MENU_ITEMS
			WHERE SEQ_ID = @SRM_MENU_ITEMS_SEQ_ID
		END
		
		SET @NEW_SRM_MENU_ITEMS_SEQ_ID = @@IDENTITY

		INSERT INTO SRM_MODULE_MENU_ITEMS
		(
			SRM_MENU_ITEMS_SEQ_ID,
			SRM_SYSTEM_MODULES_SEQ_ID,
			RANK,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT 
			@NEW_SRM_MENU_ITEMS_SEQ_ID,
			SRM_SYSTEM_MODULES_SEQ_ID,
			RANK,
			NULL, -- SOURCE_OF_DATA
			NULL,
			NULL,
			NULL,
			@DATE_CREATED,
			@CREATED_BY,
			'N',
			NULL,
			NULL
		FROM SRM_MODULE_MENU_ITEMS
		WHERE SRM_MENU_ITEMS_SEQ_ID = @SRM_MENU_ITEMS_SEQ_ID

		INSERT INTO SRM_CLIENT_MENU_ITEMS
		(
			SRM_MENU_ITEMS_SEQ_ID,
			SRM_CLIENTS_SEQ_ID,
			COLOUR_ID,
			IMAGE_ID,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT 
			@NEW_SRM_MENU_ITEMS_SEQ_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			COLOUR_ID,
			IMAGE_ID,
			NULL, -- SOURCE_OF_DATA
			NULL,
			NULL,
			NULL,
			@DATE_CREATED,
			@CREATED_BY,
			'N',
			NULL,
			NULL
		FROM SRM_CLIENT_MENU_ITEMS
		WHERE SEQ_ID = @SRM_CLIENT_MENU_ITEMS_SEQ_ID

		SET @NEW_SRM_CLIENT_MENU_ITEMS_SEQ_ID = @@IDENTITY

		INSERT INTO SRM_CLIENT_MODULE_MENU_ITEMS
		(
			SRM_CLIENT_MENU_ITEMS_SEQ_ID,
			SRM_SYSTEM_MODULES_SEQ_ID,
			SRM_USERS_SEQ_ID,
			VISIBLE,
			RANK,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT 
			@NEW_SRM_CLIENT_MENU_ITEMS_SEQ_ID,
			SRM_SYSTEM_MODULES_SEQ_ID,
			NULL,
			VISIBLE,
			RANK,
			NULL, -- SOURCE_OF_DATA
			NULL,
			NULL,
			NULL,
			@DATE_CREATED,
			@CREATED_BY,
			'N',
			NULL,
			NULL
		FROM SRM_CLIENT_MODULE_MENU_ITEMS
		WHERE SRM_CLIENT_MENU_ITEMS_SEQ_ID = @SRM_CLIENT_MENU_ITEMS_SEQ_ID -- AND SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID
		
		FETCH NEXT FROM CUR_MENU_ITEMS INTO @SRM_CLIENT_MENU_ITEMS_SEQ_ID, @SRM_MENU_ITEMS_SEQ_ID, @MENU_TYPE_ID
	END

	CLOSE CUR_MENU_ITEMS 
	DEALLOCATE CUR_MENU_ITEMS 

	-- PAGE SECTIONS AND COMPONENTS

	INSERT INTO SRM_CLIENT_COMPONENTS
	(	
		SRM_COMPONENTS_SEQ_ID,
		SRM_CLIENTS_SEQ_ID,
		SOURCE_OF_DATA,
		SOURCE_FILE,
		DATE_MODIFIED,
		MODIFIED_BY,
		DATE_CREATED,
		CREATED_BY,
		DELETED,
		DATE_DELETED,
		DELETED_BY
	)
	SELECT 
		SRM_COMPONENTS_SEQ_ID,
		@TO_SRM_CLIENTS_SEQ_ID,
		SOURCE_OF_DATA,
		SOURCE_FILE,
		DATE_MODIFIED,
		MODIFIED_BY,
		DATE_CREATED,
		CREATED_BY,
		DELETED,
		DATE_DELETED,
		DELETED_BY
	FROM SRM_CLIENT_COMPONENTS
	WHERE 
		SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID

	INSERT INTO SRM_ENTITY_COMPONENTS
	(
		SRM_COMPONENTS_SEQ_ID,
		SRM_ENTITIES_SEQ_ID,
		DISABLED,
		SOURCE_OF_DATA,
		SOURCE_FILE,
		DATE_MODIFIED,
		MODIFIED_BY,
		DATE_CREATED,
		CREATED_BY,
		DELETED,
		DATE_DELETED,
		DELETED_BY
	)
	SELECT DISTINCT
		SRM_ENTITY_COMPONENTS.SRM_COMPONENTS_SEQ_ID,
		TEMP_ENTITY.SRM_ENTITIES_SEQ_ID2,
		SRM_ENTITY_COMPONENTS.DISABLED,
		SRM_ENTITY_COMPONENTS.SOURCE_OF_DATA,
		SRM_ENTITY_COMPONENTS.SOURCE_FILE,
		SRM_ENTITY_COMPONENTS.DATE_MODIFIED,
		SRM_ENTITY_COMPONENTS.MODIFIED_BY,
		SRM_ENTITY_COMPONENTS.DATE_CREATED,
		SRM_ENTITY_COMPONENTS.CREATED_BY,
		SRM_ENTITY_COMPONENTS.DELETED,
		SRM_ENTITY_COMPONENTS.DATE_DELETED,
		SRM_ENTITY_COMPONENTS.DELETED_BY
	FROM SRM_ENTITY_COMPONENTS
	INNER JOIN @TEMP_ENTITY_CLIENT_ENTITY_TABLE TEMP_ENTITY ON SRM_ENTITY_COMPONENTS.SRM_ENTITIES_SEQ_ID = TEMP_ENTITY.SRM_ENTITIES_SEQ_ID

	-- needs to be fixed pick all sections where user exist and also the sections which do not exits for the user

	DECLARE CUR_PAGE_SECTIONS CURSOR STATIC FOR
	SELECT SEQ_ID FROM SRM_CLIENT_PAGE_SECTIONS WHERE (SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID) AND (SRM_USERS_SEQ_ID = @FROM_SRM_USERS_SEQ_ID
	OR (SRM_USERS_SEQ_ID IS NULL AND CAST(SRM_PAGES_SEQ_ID AS NVARCHAR) + '#' + CAST(SRM_PAGE_SECTION_TYPES_SEQ_ID AS NVARCHAR) NOT IN (SELECT CAST(SRM_PAGES_SEQ_ID AS NVARCHAR) + '#' + CAST(SRM_PAGE_SECTION_TYPES_SEQ_ID AS NVARCHAR) FROM SRM_CLIENT_PAGE_SECTIONS WHERE SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND SRM_USERS_SEQ_ID <> @FROM_SRM_USERS_SEQ_ID)))

	OPEN CUR_PAGE_SECTIONS 

	FETCH NEXT FROM CUR_PAGE_SECTIONS INTO @SRM_CLIENT_PAGE_SECTIONS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO SRM_CLIENT_PAGE_SECTIONS
		(
			SRM_CLIENTS_SEQ_ID,
			SRM_USERS_SEQ_ID,
			SRM_PAGES_SEQ_ID,
			SRM_PAGE_SECTION_TYPES_SEQ_ID,
			COLUMN_INDEX,
			ROW_INDEX,
			WIDTH,
			HEIGHT,
			VISIBLE,
			SETTINGS,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT
			@TO_SRM_CLIENTS_SEQ_ID,
			NULL,
			SRM_PAGES_SEQ_ID,
			SRM_PAGE_SECTION_TYPES_SEQ_ID,
			COLUMN_INDEX,
			ROW_INDEX,
			WIDTH,
			HEIGHT,
			VISIBLE,
			SETTINGS,
			NULL, -- SOURCE_OF_DATA
			NULL,
			NULL,
			NULL,
			@DATE_CREATED,
			@CREATED_BY,
			'N',
			NULL,
			NULL
		FROM SRM_CLIENT_PAGE_SECTIONS
		WHERE SEQ_ID = @SRM_CLIENT_PAGE_SECTIONS_SEQ_ID

		SET @NEW_SRM_CLIENT_PAGE_SECTIONS_SEQ_ID = @@IDENTITY

		INSERT INTO SRM_CLIENT_PAGE_COMPONENTS
		(
			SRM_COMPONENTS_SEQ_ID,
			SRM_CLIENT_PAGE_SECTIONS_SEQ_ID,
			SRM_USERS_SEQ_ID,
			SRM_CLIENT_ENTITIES_SEQ_ID,
			SETTINGS,
			RANK,
			DISABLED,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY		
		)

		SELECT
			SRM_COMPONENTS_SEQ_ID,
			@NEW_SRM_CLIENT_PAGE_SECTIONS_SEQ_ID,
			@TO_SRM_USERS_SEQ_ID,
			(SELECT TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE TEMP_ENTITY_CLIENT_ENTITY_TABLE.SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_PAGE_COMPONENTS.SRM_CLIENT_ENTITIES_SEQ_ID),
			SETTINGS,
			RANK,
			DISABLED,
			NULL, -- SOURCE_OF_DATA
			NULL,
			NULL,
			NULL,
			@DATE_CREATED,
			@CREATED_BY,
			'N',
			NULL,
			NULL
		FROM SRM_CLIENT_PAGE_COMPONENTS
		WHERE SRM_CLIENT_PAGE_SECTIONS_SEQ_ID = @SRM_CLIENT_PAGE_SECTIONS_SEQ_ID

		FETCH NEXT FROM CUR_PAGE_SECTIONS INTO @SRM_CLIENT_PAGE_SECTIONS_SEQ_ID
	END

	CLOSE CUR_PAGE_SECTIONS 
	DEALLOCATE CUR_PAGE_SECTIONS 

	-- SRM_CLIENT_SETTINGS

	INSERT INTO SRM_CLIENT_SETTINGS
	(
		SRM_CLIENTS_SEQ_ID,
		SRM_SETTINGS_SEQ_ID,
		SETTING_VALUE,
		SOURCE_OF_DATA,
