		NULL
	FROM SRM_CLIENT_SETTINGS WHERE SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID

	-- SRM_CLIENT_SYSTEM_MODULES
	
	INSERT INTO SRM_CLIENT_SYSTEM_MODULES
	(
