-- SRM_CLIENT_ENTITY_LOOKUP_FILTERS
DECLARE @TAB NVARCHAR(2), @LF NVARCHAR(2), @CR NVARCHAR(2),@NL VARCHAR(2)
SET @TAB = CHAR(9)
SET @LF = CHAR(10)
SET @CR = CHAR(13)
SET @NL = CHAR(13)+CHAR(10)
DECLARE CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS CURSOR STATIC FOR
SELECT SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID FROM SRM_CLIENT_ENTITY_LOOKUP_FILTERS scelf 
WHERE scelf.SRM_CLIENT_ENTITIES_SEQ_ID IN 
(SELECT SRM_CLIENT_ENTITIES_SEQ_ID FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE tecet)

OPEN CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS 

FETCH NEXT FROM CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS INTO @SRM_CLIENT_ENTITY_LOOKUP_FILTERS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

WHILE @@FETCH_STATUS = 0
BEGIN

	
	

	SELECT 
	@FILTER_CRITERIA = FILTER_CRITERIA, 
	@SELECT_FIELDS = SELECT_FIELDS, 
	@FILTER_CRITERIA_ATTRIBUTES_LOGIC = FILTER_CRITERIA_ATTRIBUTES_LOGIC 
	FROM SRM_CLIENT_ENTITY_LOOKUP_FILTERS WHERE SEQ_ID = @SRM_CLIENT_ENTITY_LOOKUP_FILTERS_SEQ_ID 

	-- Update SRM_CLIENT_ENTITIES_SEQ_ID and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID in JSON object of FILTER_CRITERIA
	SET @FILTER_CRITERIA = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@FILTER_CRITERIA)), @TAB,''), @NL,''), @LF,''), @CR,''),' ','')
	DELETE FROM @JSONHierarchy
	INSERT INTO @JSONHierarchy SELECT * FROM dbo.parseJSON(@FILTER_CRITERIA) 
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = h.StringValue AND h.Name = 'entityId'
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = h.StringValue AND h.Name = 'attributeId' AND h.StringValue != 'SEQ_ID'
	SELECT @FILTER_CRITERIA = dbo.ToJSON(@JSONHierarchy)
	SET @FILTER_CRITERIA = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@FILTER_CRITERIA)), @TAB,''), @NL,''), @LF,''), @CR,''),' ','')

	-- Update SRM_CLIENT_ENTITIES_SEQ_ID and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID in JSON object of SELECT_FIELDS
	SET @SELECT_FIELDS = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@SELECT_FIELDS)), @TAB,''), @NL,''), @LF,''), @CR,''),' ','')
	DELETE FROM @JSONHierarchy
	INSERT INTO @JSONHierarchy SELECT * FROM dbo.parseJSON(@SELECT_FIELDS)
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = h.StringValue AND h.Name = 'entityId'
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = h.StringValue AND h.Name = 'attributeId' AND h.StringValue != 'SEQ_ID'
	SELECT @SELECT_FIELDS = dbo.ToJSON(@JSONHierarchy)
	SET @SELECT_FIELDS = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@SELECT_FIELDS)), @TAB,''), @NL,''), @LF,''), @CR,''),' ','')

	-- Update SRM_CLIENT_ENTITIES_SEQ_ID and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID in JSON object of FILTER_CRITERIA_ATTRIBUTES_LOGIC
	SET @FILTER_CRITERIA_ATTRIBUTES_LOGIC = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@FILTER_CRITERIA_ATTRIBUTES_LOGIC)), @TAB,''), @NL,''), @LF,''), @CR,''),' ',''),'AND',' AND '),'OR',' OR ')
	DELETE FROM @JSONHierarchy
	INSERT INTO @JSONHierarchy SELECT * FROM dbo.parseJSON(@FILTER_CRITERIA_ATTRIBUTES_LOGIC)
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = h.StringValue AND h.Name = 'entityId'
	UPDATE @JSONHierarchy SET StringValue = t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @JSONHierarchy h, @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t WHERE t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = h.StringValue AND h.Name = 'attributeId' AND h.StringValue != 'SEQ_ID'
	SELECT @FILTER_CRITERIA_ATTRIBUTES_LOGIC = dbo.ToJSON(@JSONHierarchy)
	SET @FILTER_CRITERIA_ATTRIBUTES_LOGIC = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@FILTER_CRITERIA_ATTRIBUTES_LOGIC)), @TAB,''), @NL,''), @LF,''), @CR,''),' ',''),'AND',' AND '),'OR',' OR ')

	INSERT INTO dbo.SRM_CLIENT_ENTITY_LOOKUP_FILTERS
	        ( SYSTEM_NAME ,
	          SRM_CLIENT_ENTITIES_SEQ_ID ,
	          SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID ,
	          RANK ,
	          FILTER_TYPE_ID ,
	          FILTER_HTML ,
	          FILTER_CRITERIA ,
	          SELECT_FIELDS ,
	          FILTER_CRITERIA_ATTRIBUTES_LOGIC ,
	          SOURCE_OF_DATA ,
	          SOURCE_FILE ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  SYSTEM_NAME ,
	        (SELECT SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID) ,
	        (SELECT SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID) ,
	        RANK ,
	        FILTER_TYPE_ID ,
	        FILTER_HTML ,
	        @FILTER_CRITERIA ,
	        @SELECT_FIELDS ,
	        @FILTER_CRITERIA_ATTRIBUTES_LOGIC ,
	        SOURCE_OF_DATA ,
	        SOURCE_FILE ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        @DATE_CREATED ,
	        @CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY FROM dbo.SRM_CLIENT_ENTITY_LOOKUP_FILTERS AS scelf
			WHERE SEQ_ID = @SRM_CLIENT_ENTITY_LOOKUP_FILTERS_SEQ_ID

	FETCH NEXT FROM CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS INTO @SRM_CLIENT_ENTITY_LOOKUP_FILTERS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
END

CLOSE CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS 
DEALLOCATE CUR_SRM_CLIENT_ENTITY_LOOKUP_FILTERS




