-- SRM_CLIENT_ENTITY_RULES
DECLARE CUR_SRM_CLIENT_ENTITY_RULES CURSOR STATIC FOR
SELECT SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, REPLACE(RULE_EXPRESSION,'&','and'), REPLACE(SYSTEM_EXPRESSION,'&','and'), RULE_TYPE_ID 
,MAPPING
FROM SRM_CLIENT_ENTITY_RULES r
WHERE r.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID

OPEN CUR_SRM_CLIENT_ENTITY_RULES 

FETCH NEXT FROM CUR_SRM_CLIENT_ENTITY_RULES INTO @SRM_CLIENT_ENTITY_RULES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @RULE_EXPRESSION, @SYSTEM_EXPRESSION, @RULE_TYPE_ID, @RULE_MAPPING

WHILE @@FETCH_STATUS = 0
BEGIN

	SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = NULL
	SET @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = NULL  

	IF @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IS NOT NULL
	BEGIN
		SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = t.SRM_CLIENT_ENTITIES_SEQ_ID2,
		@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 
		FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE t 
		WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND t.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
	END  
	ELSE
	BEGIN
		SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = t.SRM_CLIENT_ENTITIES_SEQ_ID2
		FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE t WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
	END  

	
	SET @OLD_ENTITIES_SEQ_ID = 0
    SET @NEW_ENTITIES_SEQ_ID = 0
	SET @OLD_CLIENT_ENTITIES_SEQ_ID = 0
    SET @NEW_CLIENT_ENTITIES_SEQ_ID = 0

	IF @RULE_TYPE_ID = 10 OR @RULE_TYPE_ID = 13
	BEGIN
		IF @RULE_MAPPING IS NOT NULL AND @RULE_MAPPING.exist('//EXPRESSION_DETAIL/WINDOW_PROPERTIES/ENTITY_ID') = 1
			BEGIN				     
				SELECT @OLD_ENTITIES_SEQ_ID = RTRIM(LTRIM(REPLACE(REPLACE((@RULE_MAPPING.value('((//EXPRESSION_DETAIL/WINDOW_PROPERTIES/ENTITY_ID)/node())[1]', 'NVARCHAR(MAX)')), CHAR(10), ''), CHAR(13), '')))
				SELECT @NEW_ENTITIES_SEQ_ID = SRM_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_ENTITIES_SEQ_ID = @OLD_ENTITIES_SEQ_ID
				SET @RULE_MAPPING.modify('replace value of (//EXPRESSION_DETAIL/WINDOW_PROPERTIES/ENTITY_ID/text())[1] with sql:variable("@NEW_ENTITIES_SEQ_ID")')
			END   
		IF @RULE_MAPPING IS NOT NULL AND @RULE_MAPPING.exist('//EXPRESSION_DETAIL/WINDOW_PROPERTIES/CLIENT_ENTITY_ID') = 1
			BEGIN
				SET @OLD_CLIENT_ENTITIES_SEQ_ID = RTRIM(LTRIM(REPLACE(REPLACE((SELECT @RULE_MAPPING.value('(//EXPRESSION_DETAIL/WINDOW_PROPERTIES/CLIENT_ENTITY_ID/node())[1]', 'VARCHAR(MAX)')), CHAR(10), ''), CHAR(13), '')))
				SELECT @NEW_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @OLD_CLIENT_ENTITIES_SEQ_ID
				SET @RULE_MAPPING.modify('replace value of (//EXPRESSION_DETAIL/WINDOW_PROPERTIES/CLIENT_ENTITY_ID/text())[1] with sql:variable("@NEW_CLIENT_ENTITIES_SEQ_ID")')
			END         
    
		IF @RULE_EXPRESSION IS NOT NULL
		BEGIN
			SET @OLD_WORKFLOWS_SEQ_ID = (SELECT @RULE_EXPRESSION.value('(//EXPRESSION_DETAIL/WORKFLOW/ID/node())[1]', 'varchar(max)')) 
			SELECT @NEW_WORKFLOWS_SEQ_ID = WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @OLD_WORKFLOWS_SEQ_ID
			SET @RULE_EXPRESSION.modify('replace value of (//EXPRESSION_DETAIL/WORKFLOW/ID/text())[1] with sql:variable("@NEW_WORKFLOWS_SEQ_ID")') 
		END

		IF @SYSTEM_EXPRESSION IS NOT NULL
		BEGIN
			SET @OLD_WORKFLOWS_SEQ_ID = (SELECT @SYSTEM_EXPRESSION.value('(//EXPRESSION_DETAIL/WORKFLOW/ID/node())[1]', 'varchar(max)')) 
			SELECT @NEW_WORKFLOWS_SEQ_ID = WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @OLD_WORKFLOWS_SEQ_ID
			SET @SYSTEM_EXPRESSION.modify('replace value of (//EXPRESSION_DETAIL/WORKFLOW/ID/text())[1] with sql:variable("@NEW_WORKFLOWS_SEQ_ID")')    
		END
	END

	INSERT INTO dbo.SRM_CLIENT_ENTITY_RULES
	        ( SRM_CLIENT_ENTITIES_SEQ_ID ,
	          SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID ,
	          SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 ,
	          RULE_TYPE_ID ,
	          RULE_NAME ,
	          RULE_EXPRESSION ,
