-- WFL_TASKS
DECLARE CUR_WFL_TASKS CURSOR STATIC FOR
SELECT SEQ_ID, WFL_WORKFLOWS_SEQ_ID2, SRM_CLIENT_ENTITY_SEQ_ID, WFL_TASKS_SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE 
wt.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID ORDER BY SEQ_ID ASC

OPEN CUR_WFL_TASKS 

FETCH NEXT FROM CUR_WFL_TASKS INTO @WFL_TASKS_SEQ_ID, @WFL_WORKFLOWS_SEQ_ID2, @SRM_CLIENT_ENTITIES_SEQ_ID, @WFL_SUB_TASKS_SEQ_ID

WHILE @@FETCH_STATUS = 0
BEGIN

	--Get new workflow ID 
	IF @WFL_WORKFLOWS_SEQ_ID2 IS NOT NULL
		BEGIN
			SELECT @NEW_WFL_WORKFLOWS_SEQ_ID2 = WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID2
		END  
	ELSE
		BEGIN
			SET @NEW_WFL_WORKFLOWS_SEQ_ID2 = NULL
		END 
	
	--Get new client entity ID	
	IF 	@SRM_CLIENT_ENTITIES_SEQ_ID IS NOT NULL
		BEGIN
			SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

			/*
			SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = sccl.SRM_CLIENT_ENTITIES_SEQ_ID_NEW FROM [SRM-ClientCopyLog].dbo.SRM_CLIENT_COPY_LOG AS sccl
			WHERE sccl.SRM_CLIENTS_SEQ_ID_OLD = @FROM_SRM_CLIENTS_SEQ_ID AND sccl.SRM_CLIENTS_SEQ_ID_NEW = @TO_SRM_CLIENTS_SEQ_ID
			AND sccl.SRM_USERS_SEQ_ID_OLD = @FROM_SRM_USERS_SEQ_ID AND sccl.SRM_USERS_SEQ_ID_NEW = @TO_SRM_USERS_SEQ_ID
			AND sccl.ATTRIBUTE_01 IS NULL AND sccl.ATTRIBUTE_02 IS NULL AND sccl.ATTRIBUTE_03 IS NULL AND sccl.ATTRIBUTE_04 IS NULL AND
			sccl.SRM_CLIENT_ENTITIES_SEQ_ID_OLD = @SRM_CLIENT_ENTITIES_SEQ_ID
			*/
		END 
	ELSE
		BEGIN
			SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = NULL
		END  
	
	--Get new sub task ID
	IF @WFL_SUB_TASKS_SEQ_ID IS NOT NULL
		BEGIN
			SELECT @NEW_WFL_SUB_TASKS_SEQ_ID = WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = @WFL_SUB_TASKS_SEQ_ID
		END  
	ELSE
		BEGIN
			SET @NEW_WFL_SUB_TASKS_SEQ_ID = NULL
		END 
		
	
		 

	INSERT INTO [SRM-Workflow].dbo.WFL_TASKS
	        ( WFL_WORKFLOWS_SEQ_ID ,
	          TASK_TYPE_ID ,
	          SRM_CLIENT_ENTITY_SEQ_ID ,
	          WFL_WORKFLOWS_SEQ_ID2 ,
	          WFL_TASKS_SEQ_ID ,
	          STARTING_TASK ,
	          ENDING_TASK ,
	          SRM_CLIENTS_SEQ_ID ,
	          SOURCE_OF_DATA ,
	          SOURCE_FILE ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT (SELECT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = wt.WFL_WORKFLOWS_SEQ_ID) ,
	        TASK_TYPE_ID ,
	        @NEW_SRM_CLIENT_ENTITIES_SEQ_ID ,
	        @NEW_WFL_WORKFLOWS_SEQ_ID2 ,
	        WFL_TASKS_SEQ_ID, --REPLACED IN NEXT CURSOR
	        STARTING_TASK ,
	        ENDING_TASK ,
	        @TO_SRM_CLIENTS_SEQ_ID ,
	        SOURCE_OF_DATA ,
	        SOURCE_FILE ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        @DATE_CREATED ,
	        @CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-Workflow].dbo.WFL_TASKS wt
	WHERE SEQ_ID = @WFL_TASKS_SEQ_ID

	SET @NEW_WFL_TASKS_SEQ_ID = @@IDENTITY

	INSERT INTO @TEMP_WFL_TASKS_TABLE
	(WFL_TASKS_SEQ_ID, WFL_TASKS_SEQ_ID2)
	VALUES 
	(@WFL_TASKS_SEQ_ID, @NEW_WFL_TASKS_SEQ_ID)

	FETCH NEXT FROM CUR_WFL_TASKS INTO @WFL_TASKS_SEQ_ID, @WFL_WORKFLOWS_SEQ_ID2, @SRM_CLIENT_ENTITIES_SEQ_ID, @WFL_SUB_TASKS_SEQ_ID
END

CLOSE CUR_WFL_TASKS 
DEALLOCATE CUR_WFL_TASKS 

