SELECT SEQ_ID, WFL_TASKS_SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE 
wt.SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID ORDER BY SEQ_ID ASC

OPEN CUR_WFL_TASKS_UPDATER 

