	          DELETED_BY
	        )
	SELECT  (SELECT SRM_DASHBOARDS_SEQ_ID2 FROM @TEMP_SRM_DASHBOARDS_TABLE WHERE SRM_DASHBOARDS_SEQ_ID = sdud.SRM_DASHBOARD_SEQ_ID)  ,
	        @SRM_USERS_SEQ_ID ,
	        SOURCE_OF_DATA ,
	        SOURCE_FILE ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        @DATE_CREATED ,
	        @CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY
	FROM dbo.SRM_DASHBOARD_USER_DEFAULTS AS sdud
	WHERE SEQ_ID = @SRM_DASHBOARD_USER_DEFAULTS_SEQ_ID

	FETCH NEXT FROM CUR_SRM_DASHBOARD_USER_DEFAULTS INTO @SRM_DASHBOARD_USER_DEFAULTS_SEQ_ID, @SRM_USERS_SEQ_ID
END

CLOSE CUR_SRM_DASHBOARD_USER_DEFAULTS 
DEALLOCATE CUR_SRM_DASHBOARD_USER_DEFAULTS

-------------------------------------INSERT CLIENT LANGUAGE ITEMS FOR SYSTEM ATTRIBUTES-------------------------------

	INSERT INTO SRM_CLIENT_LANGUAGE_ITEMS
	(SRM_LANGUAGES_SEQ_ID,
	SRM_CLIENTS_SEQ_ID,
	OBJECT_ID,
	OBJECT_TYPE,
	SRM_LANGUAGE_TOKENS_SEQ_ID,
	PHRASE,
	SOURCE_OF_DATA,
	SOURCE_FILE,
	DATE_MODIFIED,
	MODIFIED_BY,
	DATE_CREATED,
	CREATED_BY,
	DELETED,
	DATE_DELETED,
	DELETED_BY)
	SELECT SRM_LANGUAGES_SEQ_ID,
	@TO_SRM_CLIENTS_SEQ_ID,
	OBJECT_ID,
	OBJECT_TYPE,
	SRM_LANGUAGE_TOKENS_SEQ_ID,
	PHRASE,
	SOURCE_OF_DATA,
	SOURCE_FILE,
	DATE_MODIFIED,
	MODIFIED_BY,
	GETDATE(),
	CREATED_BY,
	DELETED,
	DATE_DELETED,
	DELETED_BY 
	FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE  
	OBJECT_TYPE = 3 AND SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND OBJECT_ID IN 
	(SELECT SRM_ENTITY_ATTRIBUTES_SEQ_ID FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID IN 
	(SELECT SEQ_ID FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID) AND SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_ENTITY_ATTRIBUTES_SEQ_ID IN 
	(SELECT SRM_ENTITY_ATTRIBUTES_SEQ_ID FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID IN 
	(SELECT SEQ_ID FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID))
	AND SRM_ENTITY_ATTRIBUTES_SEQ_ID NOT IN (SELECT OBJECT_ID FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE  OBJECT_TYPE = 3 AND SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID))

