	/***************************INSERT SEC_OPTIONS AND SEC_GROUP_OPTIONS (RG)*******************************/

	INSERT INTO [SRM-FRAMEWORK_NEW].DBO.SEC_OPTIONS 
	(
		SRM_CLIENTS_SEQ_ID,
		ITEM_TYPE,
		SYSTEM_NAME,
		ITEM_NAME,
		DATE_CREATED,
		CREATED_BY,
		DELETED
	)

	SELECT 
		DISTINCT @TO_SRM_CLIENTS_SEQ_ID,
		ITEM_TYPE,
		SYSTEM_NAME,
		ITEM_NAME,
		GETDATE(),
		'SYSTEM',
		'N'
	FROM [SRM-FRAMEWORK_NEW].DBO.SEC_OPTIONS SEC_OPTIONS WHERE SYSTEM_NAME NOT IN (SELECT SYSTEM_NAME FROM [SRM-FRAMEWORK_NEW].DBO.SEC_OPTIONS SEC_OPTIONS WHERE SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID)

	INSERT INTO [SRM-FRAMEWORK_NEW].DBO.SEC_GROUP_OPTIONS
	(
		SEC_GROUPS_SEQ_ID,
		SEC_OPTIONS_SEQ_ID,
		ENABLE,
		DATE_CREATED,
		CREATED_BY,
		DELETED
	)

	SELECT 
		SEC_GROUPS.SEQ_ID,
		SEC_OPTIONS.SEQ_ID,
		'Y',
		GETDATE(),
		'SYSTEM',
		'N'
	FROM [SRM-FRAMEWORK_NEW].DBO.SEC_OPTIONS SEC_OPTIONS, [SRM-FRAMEWORK_NEW].DBO.SEC_GROUPS SEC_GROUPS
	WHERE SEC_OPTIONS.SRM_CLIENTS_SEQ_ID = SEC_GROUPS.SRM_CLIENTS_SEQ_ID
	AND SEC_OPTIONS.SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID
	AND NOT EXISTS(SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SEC_GROUP_OPTIONS SEC_GROUP_OPTIONS WHERE SEC_GROUP_OPTIONS.SEC_GROUPS_SEQ_ID = SEC_GROUPS.SEQ_ID AND SEC_GROUP_OPTIONS.SEC_OPTIONS_SEQ_ID = SEC_OPTIONS.SEQ_ID)

