	/********************************COPY LOOKUPS DATA IN NEW CLIENT (RM)***********************************/

	DECLARE @OLD_CUS_ENTITY_DATA_SEQ_ID BIGINT
	DECLARE @NEW_CUS_ENTITY_DATA_SEQ_ID BIGINT

	DECLARE @OLD_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @CUS_ENTITY_DATA_ATTRIBUTE NVARCHAR(100)
  
	DECLARE @OLD_CUS_ENTITY_DATA_ATTRIBUTE_VALUE NVARCHAR(100)
	DECLARE @NEW_CUS_ENTITY_DATA_ATTRIBUTE_VALUE NVARCHAR(100)
	 
	DECLARE @TEMP_ATTRIBUTES_DATA_TABLE TABLE
	(
		OLD_CUS_ENTITY_DATA_ATTRIBUTE_VALUE BIGINT
	)   

	DECLARE CUR_COPY_CUS_ENTITY_DATA CURSOR STATIC FOR
	SELECT ced.SEQ_ID, ced.SRM_CLIENT_ENTITIES_SEQ_ID FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA AS ced
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES ENTITIES ON ENTITIES.SEQ_ID = ced.SRM_CLIENT_ENTITIES_SEQ_ID and ENTITIES.DELETED = 'N'
	INNER JOIN [SRM-Framework_New]..[SRM_CLIENT_COPY_LOOKUPS] COPY_ENT ON COPY_ENT.ENTITY_DISPLAY_NAME = ENTITIES.ENTITY_DISPLAY_NAME and COPY_ENT.DELETED = 'N'
	WHERE ced.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND CED.DELETED='N' AND SRM_CLIENT_ENTITIES_SEQ_ID IS NOT NULL AND SRM_CLIENT_ENTITIES_SEQ_ID > 0

	OPEN CUR_COPY_CUS_ENTITY_DATA 

	FETCH NEXT FROM CUR_COPY_CUS_ENTITY_DATA INTO @OLD_CUS_ENTITY_DATA_SEQ_ID, @OLD_SRM_CLIENT_ENTITIES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
  
		SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = 0  
  
		SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = sce_new.SEQ_ID FROM 
		[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS sce_old WITH(NOLOCK), 
		[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS sce_new WITH(NOLOCK) 
		WHERE 
		sce_old.ENTITY_DISPLAY_NAME = sce_new.ENTITY_DISPLAY_NAME AND
		sce_old.SEQ_ID = @OLD_SRM_CLIENT_ENTITIES_SEQ_ID AND
		sce_new.SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID      

