		-------------------------------------------------------------
			INSERT INTO [SRM-ClientCopyLog].dbo.SRM_CLIENT_DATA_COPY_LOG
					( LOG_TYPE_ID ,
						LOG_TYPE_DESCRIPTION ,
						SRM_CLIENTS_SEQ_ID_OLD ,
						SRM_CLIENTS_SEQ_ID_NEW ,
						SRM_CLIENT_ENTITIES_SEQ_ID_OLD ,
						SRM_CLIENT_ENTITIES_SEQ_ID_NEW ,
						CUS_ENTITY_DATA_SEQ_ID_OLD ,
						CUS_ENTITY_DATA_SEQ_ID_NEW
					)
			VALUES  ( 1 , 
						'Client Entity Data' , 
						@FROM_SRM_CLIENTS_SEQ_ID , 
						@TO_SRM_CLIENTS_SEQ_ID , 
						@OLD_SRM_CLIENT_ENTITIES_SEQ_ID , 
						@NEW_SRM_CLIENT_ENTITIES_SEQ_ID , 
						@OLD_CUS_ENTITY_DATA_SEQ_ID , 
						@NEW_CUS_ENTITY_DATA_SEQ_ID  
					)

			IF (SELECT ENTITY_DISPLAY_NAME FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SEQ_ID = @NEW_SRM_CLIENT_ENTITIES_SEQ_ID) = 'CLIENT_SETTING'
				UPDATE [SRM-CustomEntities].dbo.CUS_ENTITY_DATA SET ATTRIBUTE_001 = @CLIENT_NAME, ATTRIBUTE_002 = @CLIENT_NAME WHERE SEQ_ID = @NEW_CUS_ENTITY_DATA_SEQ_ID
		END
