    SET @ATTACHMENT_CLIENT_ENTITY_ID = (SELECT TOP 1 SEQ_ID FROM dbo.SRM_CLIENT_ENTITIES AS sce 
	WHERE ENTITY_DISPLAY_NAME = 'ATTACHMENT' AND SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID)  

