		INSERT INTO [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_DETAILS
		        ( SRM_CLIENT_ENTITIES_SEQ_ID ,
		          SRM_CLIENTS_SEQ_ID ,
		          ATTRIBUTE_MAPPING ,
		          SOURCE_OF_DATA ,
		          SOURCE_FILE ,
		          DATE_MODIFIED ,
		          MODIFIED_BY ,
		          DATE_CREATED ,
		          CREATED_BY ,
		          DELETED ,
		          DATE_DELETED ,
		          DELETED_BY
		        )
		SELECT TOP 1  
				@ATTACHMENT_CLIENT_ENTITY_ID ,
		        @TO_SRM_CLIENTS_SEQ_ID ,
		        ATTRIBUTE_MAPPING ,
		        SOURCE_OF_DATA ,
		        SOURCE_FILE ,
		        DATE_MODIFIED ,
		        MODIFIED_BY ,
		        GETDATE() ,
		        @CREATED_BY ,
		        DELETED ,
		        DATE_DELETED ,
		        DELETED_BY 
		FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_DETAILS AS sced
		WHERE SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID
	END   

	/******************************** COPY SRM_CLIENT_ENTITY_DETAILS ENDS ***********************************/
	
	--ROLLBACK TRAN
	--COMMIT TRAN

	/******************************** CREATE MERGE SP COPY STARTS ***********************************/
	EXEC [SRM-Framework_New].dbo.[CREATE_MERGE_SCRIPT_FOR_NEW_CLIENT]
	@OLD_CLIENT_ID = @FROM_SRM_CLIENTS_SEQ_ID,
	@NEW_CLIENT_ID = @TO_SRM_CLIENTS_SEQ_ID
	/******************************** CREATE MERGE SP COPY ENDS ***********************************/


END



;





CREATE PROCEDURE [dbo].[CREATE_NOTE]
@SEQ_ID BigInt,
@NOTE_TYPE_DESCRIPTION NVARCHAR(100),
@NOTES NVARCHAR(MAX)
AS
BEGIN

	IF ISNULL(@NOTES, '') = ''
		RETURN

	DECLARE @NOTE_TYPE_SEQ_ID BigInt


	SELECT @NOTE_TYPE_SEQ_ID = SEQ_ID FROM [SRM-CustomENtities].dbo.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 10710 AND ATTRIBUTE_001 = @NOTE_TYPE_DESCRIPTION

 	INSERT INTO [SRM-CustomENtities].dbo.CUS_ENTITY_DATA
			(
			SRM_CLIENT_ENTITIES_SEQ_ID,
			ATTRIBUTE_001,
			ATTRIBUTE_003,
			ATTRIBUTE_004,
			ATTRIBUTE_499,
			SRM_CLIENTS_SEQ_ID,
			CREATED_BY,
			DATE_CREATED
			)
			VALUES
			(
			10551,
			@NOTES,
			@NOTE_TYPE_SEQ_ID,
			@NOTE_TYPE_DESCRIPTION,
			@SEQ_ID,
			42,
			'CCS',
			GETDATE()
			)

END



;





CREATE PROCEDURE [dbo].[CREATE_RELATED_LIST]
@SRM_CLIENTS_SEQ_ID_OLD BIGINT = 0,
@SRM_CLIENTS_SEQ_ID BIGINT = 0,
@SRM_USERS_SEQ_ID_OLD BIGINT = 0,
@SRM_USERS_SEQ_ID BIGINT = 0,
@ENTITY_DISPLAY_NAME NVARCHAR(100) = '',
@ENTITY_DISPLAY_NAME2 NVARCHAR(100) = '', 
@FOREIGN_KEY_ATTRIBUTE_NAME NVARCHAR(100) = '', 
@RELATED_LIST_ATTRIBUTES NVARCHAR(4000) = ''
AS

DECLARE @CLIENT_ENTITY_SEQ_ID BIGINT
DECLARE @CLIENT_ENTITY_SEQ_ID2 BIGINT
DECLARE @CLIENT_ENTITY_SEQ_ID_OLD BIGINT
DECLARE @CLIENT_ENTITY_SEQ_ID2_OLD BIGINT
DECLARE @FILTER_VIEW_SEQ_ID BIGINT
DECLARE @LANGUAGE_SEQ_ID BIGINT
DECLARE @SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID BIGINT
DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT
DECLARE @TODAY DATETIME
DECLARE @USER NVARCHAR(100)
DECLARE @RANK INT = 1

------------ **************************

SELECT @CLIENT_ENTITY_SEQ_ID = SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME
SELECT @CLIENT_ENTITY_SEQ_ID2 = SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME2
SELECT @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID2 AND ATTRIBUTE_DISPLAY_NAME = @FOREIGN_KEY_ATTRIBUTE_NAME

IF @SRM_CLIENTS_SEQ_ID_OLD > 0
BEGIN
	SET @RANK = 99
	SELECT @CLIENT_ENTITY_SEQ_ID_OLD = SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID_OLD AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME
	SELECT @CLIENT_ENTITY_SEQ_ID2_OLD = SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID_OLD AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME2
	SELECT @RANK = RANK FROM dbo.SRM_CLIENT_ENTITY_RELATED_LISTS AS SCERL WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@CLIENT_ENTITY_SEQ_ID_OLD AND SRM_CLIENT_ENTITIES_SEQ_ID2=@CLIENT_ENTITY_SEQ_ID2_OLD
	AND SRM_USERS_SEQ_ID=@SRM_USERS_SEQ_ID_OLD
END

PRINT @CLIENT_ENTITY_SEQ_ID
PRINT @CLIENT_ENTITY_SEQ_ID2
PRINT @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

IF (@CLIENT_ENTITY_SEQ_ID IS NULL OR @CLIENT_ENTITY_SEQ_ID2 IS NULL OR @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IS NULL)
BEGIN
	PRINT 'ERROR SELECTING CLIENT ENTITIES OR FOREIGN KEY ATTRIBUTE'
	RETURN
END

SET @FILTER_VIEW_SEQ_ID = 0
SET @TODAY = GETDATE()
SET @USER = 'dbuser'

--- DELETE EXISTING DATA
IF EXISTS (SELECT * FROM SRM_CLIENT_ENTITY_RELATED_LISTS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID2)
BEGIN
	SELECT @FILTER_VIEW_SEQ_ID = SEQ_ID FROM SRM_CLIENT_FILTER_VIEWS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID2 AND SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID
	IF @FILTER_VIEW_SEQ_ID > 0
	BEGIN
		DELETE FROM SRM_CLIENT_FILTER_VIEW_ATTRIBUTES WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @FILTER_VIEW_SEQ_ID
		DELETE FROM SRM_CLIENT_FILTER_VIEW_CRITERIA WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @FILTER_VIEW_SEQ_ID
		DELETE FROM SRM_CLIENT_FILTER_VIEW_BUTTONS WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @FILTER_VIEW_SEQ_ID
		DELETE FROM SRM_CLIENT_FILTER_VIEW_DEFAULT WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @FILTER_VIEW_SEQ_ID
		DELETE FROM SRM_CLIENT_FILTER_VIEWS WHERE SEQ_ID = @FILTER_VIEW_SEQ_ID
	END
	DELETE FROM SRM_CLIENT_ENTITY_RELATED_LISTS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID2
END


-- CLIENT ENTITY RELATED LIST
INSERT INTO [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_RELATED_LISTS
(SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID2, SRM_USERS_SEQ_ID, VISIBLE, RANK, DATE_CREATED, CREATED_BY, DELETED)
SELECT @CLIENT_ENTITY_SEQ_ID, @CLIENT_ENTITY_SEQ_ID2, NULL, 'Y', @RANK, @TODAY, @USER, 'N'

-- CLIENT ENTITY RELATED LIST FOR USER AND MAKE IS VISIBLE
INSERT INTO [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_RELATED_LISTS
(SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID2, SRM_USERS_SEQ_ID, VISIBLE,RANK, DATE_CREATED, CREATED_BY, DELETED)
SELECT @CLIENT_ENTITY_SEQ_ID, @CLIENT_ENTITY_SEQ_ID2, @SRM_USERS_SEQ_ID, 'Y',@RANK, @TODAY, @USER, 'N'

-- FILTER VIEW - VIEWS
INSERT INTO [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEWS
(SYSTEM_NAME, SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID2, FILTER_VIEW_TYPE_ID, VISIBLE_LINES, PAGE_SIZE, DATE_CREATED, CREATED_BY, DELETED)
SELECT 'RELATED_LIST', @CLIENT_ENTITY_SEQ_ID2, @CLIENT_ENTITY_SEQ_ID, 1, 3, 1000, @TODAY, @USER, 'N'

SET @FILTER_VIEW_SEQ_ID = @@IDENTITY

-- FILTER VIEW ATTRIBTUES - VIEWS (SEQ_ID ONLY)
INSERT INTO [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEW_ATTRIBUTES
(SRM_CLIENT_FILTER_VIEWS_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, RANK, STANDARD_ATTRIBUTE, INTERNAL_ATTRIBUTE, DATE_CREATED, CREATED_BY, DELETED)
SELECT @FILTER_VIEW_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES.SEQ_ID, 1, SRM_CLIENT_ENTITY_ATTRIBUTES.STANDARD_ATTRIBUTE, 'N', @TODAY, @USER, 'N'
FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES SRM_CLIENT_ENTITY_ATTRIBUTES, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES SRM_ENTITY_ATTRIBUTES
WHERE SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID2
AND SRM_ENTITY_ATTRIBUTES.SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_ENTITY_ATTRIBUTES_SEQ_ID
AND SRM_ENTITY_ATTRIBUTES.SYSTEM_NAME IN (SELECT VALUE FROM [SRM-FRAMEWORK_NEW].DBO.SPLIT('SEQ_ID', ','))

-- FILTER VIEW ATTRIBTUES - VIEWS
INSERT INTO [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEW_ATTRIBUTES
(SRM_CLIENT_FILTER_VIEWS_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, RANK, STANDARD_ATTRIBUTE, INTERNAL_ATTRIBUTE, DATE_CREATED, CREATED_BY, DELETED)
SELECT @FILTER_VIEW_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES.SEQ_ID, (ROW_NUMBER() OVER (ORDER BY SRM_ENTITIES_SEQ_ID)) + 1, SRM_CLIENT_ENTITY_ATTRIBUTES.STANDARD_ATTRIBUTE, 'N', @TODAY, @USER, 'N'
FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES SRM_CLIENT_ENTITY_ATTRIBUTES, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES SRM_ENTITY_ATTRIBUTES
WHERE SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID2
AND SRM_ENTITY_ATTRIBUTES.SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_ENTITY_ATTRIBUTES_SEQ_ID
AND SRM_ENTITY_ATTRIBUTES.SYSTEM_NAME IN (SELECT VALUE FROM [SRM-FRAMEWORK_NEW].DBO.SPLIT(@RELATED_LIST_ATTRIBUTES, ',') WHERE VALUE <> 'SEQ_ID')

UPDATE SRM_CLIENT_FILTER_VIEW_ATTRIBUTES SET INTERNAL_ATTRIBUTE = 'Y' WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @FILTER_VIEW_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IN 
(SELECT SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID2 AND ATTRIBUTE_DISPLAY_NAME = 'RECORD_ID')

-- FILTER VIEW ATTRIBTUES - VIEWS
INSERT INTO [SRM-FRAMEWORK_NEW].DBO.SRM_LANGUAGE_ITEMS
(SRM_LANGUAGES_SEQ_ID, OBJECT_ID, OBJECT_TYPE, SRM_LANGUAGE_TOKENS_SEQ_ID, PHRASE, DATE_CREATED, CREATED_BY, DELETED)
SELECT @LANGUAGE_SEQ_ID, @FILTER_VIEW_SEQ_ID, 35, 1, 'ALL', @TODAY, @USER, 'N'

-- FILTER VIEW BUTTONS
SELECT @SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID = SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_BUTTONS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID AND APPLICABLE_TO_ID = 1
AND SRM_BUTTON_TYPES_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_BUTTON_TYPES WHERE SYSTEM_NAME = 'btnNew')

INSERT INTO [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEW_BUTTONS
(SRM_CLIENT_FILTER_VIEWS_SEQ_ID, SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID, RANK, DATE_CREATED, CREATED_BY, DELETED)
SELECT @FILTER_VIEW_SEQ_ID, @SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID, 1, @TODAY, @USER, 'N'

--SRM_CLIENT_FILTER_VIEW_CRITERIA
INSERT INTO [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEW_CRITERIA
(SRM_CLIENT_FILTER_VIEWS_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, RANK, OPERATOR_ID, DATE_CREATED, CREATED_BY, DELETED)
SELECT @FILTER_VIEW_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, 1, 3, @TODAY, @USER, 'N'





;






CREATE PROCEDURE [dbo].[CREATE_REPLICATION_DATA_FOR_NEW_CLIENT]
@ClientId int = 0 -- DO NOT RUN THIS SCRIPT FOR CLIENT 17 (d&t) AS THERE IS CUSTOM MAPPING

AS

--BEGIN
	IF @ClientId=0
	RETURN;

	-- DELETE EXISTING RECORDS FOR SPECIFIED USER.
	DELETE FROM  SRM_REPLICATION_ATTRIBUTE_MAPPINGS WHERE [SRM_REPLICATION_RECEIVERS_SEQ_ID]
	IN (SELECT SEQ_ID FROM SRM_REPLICATION_RECEIVERS WHERE [SRM_CLIENTS_SEQ_ID] = @ClientId);
	DELETE FROM SRM_REPLICATION_RECEIVERS WHERE [SRM_CLIENTS_SEQ_ID] = @ClientId;
	DELETE FROM SRM_REPLICATION_SENDERS WHERE [SRM_CLIENTS_SEQ_ID] = @ClientId;

	-- ------------------------------------------------------------------------------------
	Declare @ServiceId INT = 12;
	INSERT INTO SRM_REPLICATION_RECEIVERS
	([SRM_CLIENTS_SEQ_ID]
			   ,[SRM_ENTITIES_SEQ_ID]
			   ,[SENDER_ENTITY_SYSTEM_NAME]
			   ,[SRM_ENTITIES_SEQ_ID2]
			   ,[RECEIVER_ENTITY_SYSTEM_NAME]
			   ,[SRM_ENTITY_ATTRIBUTES_SEQ_ID]
			   ,[RECEIVER_FOREIGN_ATTRIBUTE_SEQ_ID]
			   ,[RECEIVER_FOREIGN_ATTRIBUTE_SYSTEM_NAME]
			   ,[SERVICE_ID]
			   ,[CREATED_BY])

	--ALTER TABLE SRM_REPLICATION_RECEIVERS ADD RECEIVER_FOREIGN_ATTRIBUTE_SEQ_ID BIGINT
	SELECT DISTINCT
	R.SRM_CLIENTS_SEQ_ID, 
	S.SEQ_ID,-- S.SRM_ENTITIES_SEQ_ID,   -- SENDER
	EN.SYSTEM_NAME AS SENDER_ENTITY_SYSTEM_NAME,
	R.SEQ_ID  AS SRM_ENTITIES_SEQ_ID1,--R.SRM_ENTITIES_SEQ_ID AS SRM_ENTITIES_SEQ_ID1,  -- RECEIVER
	'CUS_ENTITY_DATA' AS RECEIVER_ENTITY_SYSTEM_NAME,
	(SELECT SEQ_ID FROM SRM_ENTITY_ATTRIBUTES WHERE SRM_ENTITIES_SEQ_ID = S.SRM_ENTITIES_SEQ_ID 
	AND SYSTEM_NAME = 'SEQ_ID' ) as ENTITY_ATTRIBUTE_SEQ_ID, 
	A.SEQ_ID AS RECEIVER_FOREIGN_ATTRIBUTE_SEQ_ID,
	(SELECT T.SYSTEM_NAME FROM SRM_ENTITY_ATTRIBUTES AS T WHERE
	T.SEQ_ID = A.SRM_ENTITY_ATTRIBUTES_SEQ_ID) AS RECEIVER_FOREIGN_ATTRIBUTE_SYSTEM_NAME ,
	@ServiceId AS SERVICE_ID,--MUSAWAR --UNCOMMENT IT
	'dbscript' as CREATED_BY
	FROM  
	SRM_CLIENT_ENTITY_ATTRIBUTES AS A 
	INNER JOIN SRM_CLIENT_ENTITIES AS R  ON A.SRM_CLIENT_ENTITIES_SEQ_ID = R.SEQ_ID AND R.SRM_CLIENTS_SEQ_ID = @ClientId
	INNER JOIN SRM_CLIENT_ENTITIES AS S  ON A.SRM_CLIENT_ENTITIES_SEQ_ID2 = S.SEQ_ID
	INNER JOIN SRM_ENTITIES AS EN ON S.SRM_ENTITIES_SEQ_ID = EN.SEQ_ID
	WHERE R.SRM_CLIENTS_SEQ_ID = @ClientId
	AND A.SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (11,19) 
	AND A.SRM_CLIENT_ENTITIES_SEQ_ID2 IS NOT NULL
	ORDER BY S.SEQ_ID

	-- ------------------------------------------------------------------------------------

	INSERT INTO [SRM_REPLICATION_SENDERS]
			   ([SRM_CLIENTS_SEQ_ID]
			   ,[SRM_ENTITIES_SEQ_ID]
			   ,[ENTITY_SYSTEM_NAME]
			   ,[SRM_ENTITY_ATTRIBUTES_SEQ_ID]
			   ,[CREATED_BY])
           
		SELECT DISTINCT SRM_CLIENTS_SEQ_ID, 
		SRM_ENTITIES_SEQ_ID, 
		SENDER_ENTITY_SYSTEM_NAME, 
		SRM_ENTITY_ATTRIBUTES_SEQ_ID,
		'dbscript' FROM SRM_REPLICATION_RECEIVERS 
		WHERE SRM_CLIENTS_SEQ_ID = @ClientId
    

	-- ------------------------------------------------------------------------------------
	PRINT ' SRM_REPLICATION_ATTRIBUTE_MAPPINGS'

	DECLARE @senderClientEntity INT;
	DECLARE @receiverClientEntity INT;
	DECLARE @replicationId INT;
	DECLARE @receiverFkAttr nvarchar(50);

	DECLARE @mappingCursor CURSOR 
	SET @mappingCursor = CURSOR STATIC LOCAL FOR
	SELECT R.SEQ_ID, SENDER.SEQ_ID, RECEIVER.SEQ_ID, R.RECEIVER_FOREIGN_ATTRIBUTE_SYSTEM_NAME 
	FROM SRM_REPLICATION_RECEIVERS AS R
	INNER JOIN SRM_CLIENT_ENTITIES AS SENDER ON  SENDER.SRM_CLIENTS_SEQ_ID = R.SRM_CLIENTS_SEQ_ID AND SENDER.SEQ_ID = R.SRM_ENTITIES_SEQ_ID
	INNER JOIN SRM_CLIENT_ENTITIES AS RECEIVER ON  RECEIVER.SRM_CLIENTS_SEQ_ID = R.SRM_CLIENTS_SEQ_ID AND RECEIVER.SEQ_ID = R.SRM_ENTITIES_SEQ_ID2
	--INNER JOIN SRM_CLIENT_ENTITIES AS SENDER ON  SENDER.SRM_CLIENTS_SEQ_ID = R.SRM_CLIENTS_SEQ_ID AND SENDER.SRM_ENTITIES_SEQ_ID = R.SRM_ENTITIES_SEQ_ID
	--INNER JOIN SRM_CLIENT_ENTITIES AS RECEIVER ON  RECEIVER.SRM_CLIENTS_SEQ_ID = R.SRM_CLIENTS_SEQ_ID AND RECEIVER.SRM_ENTITIES_SEQ_ID = R.SRM_ENTITIES_SEQ_ID2
	AND R.SRM_CLIENTS_SEQ_ID =  @ClientId;


	OPEN @mappingCursor
	FETCH NEXT
	FROM @mappingCursor INTO @replicationId, @senderClientEntity, @receiverClientEntity, @receiverFkAttr
	WHILE @@FETCH_STATUS = 0
	BEGIN

	PRINT @replicationId
	INSERT INTO [SRM_REPLICATION_ATTRIBUTE_MAPPINGS]
			   ([SRM_REPLICATION_RECEIVERS_SEQ_ID]
			   ,[SRM_ENTITY_ATTRIBUTES_SEQ_ID]
			   ,[SENDER_ATTRIBUTE_SYSTEM_NAME]
			   ,[SRM_ENTITY_ATTRIBUTES_SEQ_ID2]
			   ,[RECEIVER_ATTRIBUTE_SYSTEM_NAME]
			   ,[CREATED_BY])
           
	SELECT DISTINCT
	 @replicationId, 
	(SELECT E.SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTES AS TA 
	INNER JOIN SRM_ENTITY_ATTRIBUTES AS E ON
	TA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = E.SEQ_ID
	WHERE TA.SRM_CLIENT_ENTITIES_SEQ_ID = A.SRM_CLIENT_ENTITIES_SEQ_ID2 AND STANDARD_ATTRIBUTE = 'Y' )
	 AS SENDER_ENTITY_ATTRIBUTE_SEQ_ID, 
 
	 (SELECT E.SYSTEM_NAME FROM SRM_CLIENT_ENTITY_ATTRIBUTES AS TA 
	INNER JOIN SRM_ENTITY_ATTRIBUTES AS E ON
	TA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = E.SEQ_ID
	WHERE TA.SRM_CLIENT_ENTITIES_SEQ_ID = A.SRM_CLIENT_ENTITIES_SEQ_ID2 AND STANDARD_ATTRIBUTE = 'Y' ) 
	AS SENDER_ENTITY_ATTRIBUTE_SYSTEM_NAME, 
 
 
	(SELECT T.SEQ_ID FROM SRM_ENTITY_ATTRIBUTES AS T WHERE
	T.SEQ_ID = B.SRM_ENTITY_ATTRIBUTES_SEQ_ID

	) AS RECEIVER_ENTITY_ATTRIBUTE_SEQ_ID ,

	(SELECT T.SYSTEM_NAME FROM SRM_ENTITY_ATTRIBUTES AS T WHERE
	T.SEQ_ID = B.SRM_ENTITY_ATTRIBUTES_SEQ_ID

	) AS RECEIVER_ENTITY_ATTRIBUTE_SYSTEM_NAME  ,
	'dbscript' 
   
	FROM  
	SRM_CLIENT_ENTITY_ATTRIBUTES AS A 
	LEFT JOIN SRM_CLIENT_ENTITY_ATTRIBUTES AS B ON A.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = B.SEQ_ID
	WHERE 
	A.SRM_CLIENT_ENTITIES_SEQ_ID2 = @senderClientEntity AND
	A.SRM_CLIENT_ENTITIES_SEQ_ID = @receiverClientEntity AND

	 A.SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN ( 11,19) 
	AND A.SRM_CLIENT_ENTITIES_SEQ_ID2 IS NOT NULL
	AND (SELECT T.SYSTEM_NAME FROM SRM_ENTITY_ATTRIBUTES AS T WHERE
	T.SEQ_ID = A.SRM_ENTITY_ATTRIBUTES_SEQ_ID) = @receiverFkAttr;

	FETCH NEXT
	FROM @mappingCursor INTO @replicationId, @senderClientEntity, @receiverClientEntity, @receiverFkAttr
	END
	CLOSE @mappingCursor;
	DEALLOCATE @mappingCursor ; 


	-- ------------------------------------------------------------------------------------
--END



;





