CREATE PROCEDURE [dbo].[CREATE_SINGLE_ATTRIBUTE_IN_AN_ENTITY]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENTS_SEQ_ID BIGINT,
	@CLIENT_ENTITY_NAME NVARCHAR(200),
	@ATTRIBUTE_DISPLAY_NAME NVARCHAR(200),
	@SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID BIGINT,
	@MAX_LENGTH INT,
	@DECIMAL_PLACES INT=0,
	@ADD_TO_FORM CHAR(1) = 'N',
	@SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID BIGINT = 0,
	@GROUP_NAME NVARCHAR(200) = NULL,
	@ROW_INDEX INT = 0,
	@COLUMN_INDEX INT = 0,
	@MANDATORY CHAR(1) = 'N',
	@READ_ONLY_ON_ADD CHAR(1) = 'N',
	@READ_ONLY_ON_EDIT CHAR(1) = 'N',
	@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID3 BIGINT = 0 OUTPUT,
	@ERROR SMALLINT = 0 OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = '' OUTPUT
AS
BEGIN
	DECLARE @PHRASE NVARCHAR(200) = REPLACE(dbo.ProperCase(@ATTRIBUTE_DISPLAY_NAME),'_',' ')

	SET @ATTRIBUTE_DISPLAY_NAME = UPPER(@ATTRIBUTE_DISPLAY_NAME)
	SET @ATTRIBUTE_DISPLAY_NAME = REPLACE(@ATTRIBUTE_DISPLAY_NAME,' ','_')
	SET @ATTRIBUTE_DISPLAY_NAME = REPLACE(@ATTRIBUTE_DISPLAY_NAME,'(','_')
	SET @ATTRIBUTE_DISPLAY_NAME = REPLACE(@ATTRIBUTE_DISPLAY_NAME,')','_')
	SET @ATTRIBUTE_DISPLAY_NAME = REPLACE(@ATTRIBUTE_DISPLAY_NAME,'/','_')
	SET @ATTRIBUTE_DISPLAY_NAME = REPLACE(@ATTRIBUTE_DISPLAY_NAME,'-','_')

	PRINT @GROUP_NAME
	PRINT @ATTRIBUTE_DISPLAY_NAME

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = 0, @SRM_ENTITIES_SEQ_ID BIGINT = 0
	DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT = 0, @SRM_ENTITY_ATTRIBUTES_SEQ_ID BIGINT = 0
	DECLARE @MAX_ATTRIBUTE_ID INT, @NEXT_ATTRIBUTE_ID INT, @SYSTEM_NAME NVARCHAR(20), @PROPERTY_NAME NVARCHAR(20)
	DECLARE @ATTRIBUTE_API_CAPTION NVARCHAR(200) = REPLACE(dbo.ProperCase(@ATTRIBUTE_DISPLAY_NAME),'_','')
	DECLARE @MAX_ROW_INDEX INT = 0, @MAX_COLUMN_INDEX INT = 0, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT = 0
	DECLARE @GROUP_RANK INT = 0
	
	DECLARE @DATE_CREATED DATETIME = GETDATE(), @DELETED CHAR(1) = 'N'
	DECLARE @CREATED_BY NVARCHAR(50) = (SELECT TOP 1 LOGIN_USER_NAME FROM SRM_USERS WHERE SRM_CLIENTS_SEQ_ID=@SRM_CLIENTS_SEQ_ID AND SUPER_ADMIN='Y')

	IF @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID NOT IN (3,4,8,5,13,23,24)
	BEGIN
		SET @ERROR = 1
		SET @ERROR_DESCRIPTION = 'This stored procedure can only be used to create text field, date field, file, radio button or checkbox.' 
		RETURN  
	END  

	IF @SRM_CLIENTS_SEQ_ID = 0 OR @CLIENT_ENTITY_NAME = '' OR @ATTRIBUTE_DISPLAY_NAME = '' OR @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID=0 OR @MAX_LENGTH=0
	BEGIN
		SET @ERROR = 1
		SET @ERROR_DESCRIPTION = 'Expected parameter values in mandatory first 5 fields.' 
		RETURN  
	END  

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID = SEQ_ID,@SRM_ENTITIES_SEQ_ID=SRM_ENTITIES_SEQ_ID FROM dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=@SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME=@CLIENT_ENTITY_NAME

	IF @SRM_CLIENT_ENTITIES_SEQ_ID = 0
	BEGIN
		SET @ERROR = 1
		SET @ERROR_DESCRIPTION = 'Entity does not exist in oomi against this client.' 
		RETURN
	END   

	SELECT @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID 
	AND ATTRIBUTE_DISPLAY_NAME=@ATTRIBUTE_DISPLAY_NAME

	IF @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID > 0
	BEGIN
		SET @ERROR = 1
		SET @ERROR_DESCRIPTION = 'Attribute already exists against this entity.' 
		RETURN
	END   

	IF @ADD_TO_FORM = 'Y'
	BEGIN
		IF @COLUMN_INDEX > 2
		BEGIN
			SET @ERROR = 1
			SET @ERROR_DESCRIPTION = 'Column Index can''t be greater than 2.' 
			RETURN      			      
		END  
    
		IF @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID=0 AND ISNULL(@GROUP_NAME,'') != ''
		BEGIN
			SELECT @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID=SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS AS SCEAG WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID
			AND SYSTEM_NAME=@GROUP_NAME
		      
    
			--IF NOT EXISTS(SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS AS SCEAG WHERE 
			--SEQ_ID=@SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID  AND SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID)
			--BEGIN
			--	SET @ERROR = 1
			--	SET @ERROR_DESCRIPTION = 'Group is not available against this entity.' 
			--	RETURN      			      
			--END  
		
			IF (@ROW_INDEX > 0 AND @COLUMN_INDEX > 0 AND @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID > 0
			AND EXISTS (SELECT * FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS AS SCEAGD 
			WHERE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID=@SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID
			AND ROW_INDEX=@ROW_INDEX AND COLUMN_INDEX=@COLUMN_INDEX))
			BEGIN
				SET @ERROR = 1
				SET @ERROR_DESCRIPTION = 'Field is already available at provided co-ordinates.' 
				RETURN      			      
			END  
		END
	END  


	SELECT TOP 1 @MAX_ATTRIBUTE_ID=CAST(REPLACE(SYSTEM_NAME,'ATTRIBUTE_','') AS INT) FROM dbo.SRM_ENTITY_ATTRIBUTES AS SEA WHERE SRM_ENTITIES_SEQ_ID=@SRM_ENTITIES_SEQ_ID AND SYSTEM_NAME LIKE 'ATTRIBUTE%'
	ORDER BY CAST(REPLACE(SYSTEM_NAME,'ATTRIBUTE_','') AS INT) DESC

	SET @NEXT_ATTRIBUTE_ID = @MAX_ATTRIBUTE_ID + 1
	
	SET @SYSTEM_NAME = 'ATTRIBUTE_' + RIGHT('00' + CAST(@NEXT_ATTRIBUTE_ID AS NVARCHAR),3)
	SET @PROPERTY_NAME = 'Attribute' + RIGHT('00' + CAST(@NEXT_ATTRIBUTE_ID AS NVARCHAR(3)),3)

	INSERT INTO SRM_ENTITY_ATTRIBUTES(SRM_ENTITIES_SEQ_ID,SYSTEM_NAME,PROPERTY_NAME,DATE_CREATED,CREATED_BY,DELETED)
	SELECT @SRM_ENTITIES_SEQ_ID, @SYSTEM_NAME, @PROPERTY_NAME, @DATE_CREATED, @CREATED_BY, @DELETED
	SET @SRM_ENTITY_ATTRIBUTES_SEQ_ID = SCOPE_IDENTITY()

	INSERT INTO dbo.SRM_CLIENT_ENTITY_ATTRIBUTES(
	SRM_CLIENT_ENTITIES_SEQ_ID,SRM_ENTITY_ATTRIBUTES_SEQ_ID,SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID,ATTRIBUTE_DISPLAY_NAME,
	REFERENCED_SERVICE_ID,SYSTEM_ATTRIBUTE,STANDARD_ATTRIBUTE,DISPLAY_ATTRIBUTE,MAX_LENGTH,DECIMAL_PLACES,STARTING_NUMBER,TRACK_FIELD_HISTORY,
	DATE_CREATED,CREATED_BY,DELETED,ATTRIBUTE_API_CAPTION)
	SELECT TOP 1 SRM_CLIENT_ENTITIES_SEQ_ID,@SRM_ENTITY_ATTRIBUTES_SEQ_ID SRM_ENTITY_ATTRIBUTES_SEQ_ID,
	@SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID,@ATTRIBUTE_DISPLAY_NAME ATTRIBUTE_DISPLAY_NAME,
	REFERENCED_SERVICE_ID,'N' SYSTEM_ATTRIBUTE,'N' STANDARD_ATTRIBUTE,DISPLAY_ATTRIBUTE,@MAX_LENGTH MAX_LENGTH,@DECIMAL_PLACES,STARTING_NUMBER,TRACK_FIELD_HISTORY,
	@DATE_CREATED DATE_CREATED,@CREATED_BY CREATED_BY,@DELETED DELETED,@ATTRIBUTE_API_CAPTION ATTRIBUTE_API_CAPTION
	FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND STANDARD_ATTRIBUTE='Y'
	SET @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCOPE_IDENTITY()
	SET @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID3=@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2

	INSERT INTO dbo.SRM_CLIENT_LANGUAGE_ITEMS(SRM_LANGUAGES_SEQ_ID,SRM_CLIENTS_SEQ_ID,OBJECT_ID,OBJECT_TYPE,SRM_LANGUAGE_TOKENS_SEQ_ID,PHRASE,
	DATE_CREATED,CREATED_BY,DELETED)
	SELECT 2,@SRM_CLIENTS_SEQ_ID,@SRM_ENTITY_ATTRIBUTES_SEQ_ID,3,1,@PHRASE,@DATE_CREATED,@CREATED_BY,@DELETED

	IF @ADD_TO_FORM = 'Y'
	BEGIN
		IF @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID = 0
		BEGIN
			SELECT @GROUP_RANK=MAX(GROUP_RANK) + 1 FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID

			INSERT INTO dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS(
			SRM_CLIENT_ENTITIES_SEQ_ID,SYSTEM_NAME,GROUP_RANK,GROUP_TYPE_ID,NAVIGATION_SEQUENCE_ID,NUMBER_OF_COLUMNS,DISPLAY_ON_EDIT,DISPLAY_ON_DETAIL,
			DATE_CREATED,CREATED_BY,DELETED,
			DISPLAY_ON_ADD,DISPLAY_ON_ADD_MOBILE,DISPLAY_ON_EDIT_MOBILE,DISPLAY_ON_DETAIL_MOBILE,UNIQUE_ID,CONDITION_GROUP)

			SELECT @SRM_CLIENT_ENTITIES_SEQ_ID,@GROUP_NAME SYSTEM_NAME,@GROUP_RANK GROUP_RANK,GROUP_TYPE_ID,NAVIGATION_SEQUENCE_ID,NUMBER_OF_COLUMNS,
			DISPLAY_ON_EDIT,DISPLAY_ON_DETAIL,
			@DATE_CREATED DATE_CREATED,@CREATED_BY CREATED_BY,@DELETED DELETED,
			DISPLAY_ON_ADD,DISPLAY_ON_ADD_MOBILE,DISPLAY_ON_EDIT_MOBILE,DISPLAY_ON_DETAIL_MOBILE, UPPER(@CLIENT_ENTITY_NAME + '_' + REPLACE(@GROUP_NAME,' ','_')) UNIQUE_ID,CONDITION_GROUP
			FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS AS SCEAG WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND SYSTEM_NAME='General'
			
			SET @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID = SCOPE_IDENTITY()

			INSERT INTO dbo.SRM_CLIENT_LANGUAGE_ITEMS(SRM_LANGUAGES_SEQ_ID,SRM_CLIENTS_SEQ_ID,OBJECT_ID,OBJECT_TYPE,SRM_LANGUAGE_TOKENS_SEQ_ID,PHRASE,
			DATE_CREATED,CREATED_BY,DELETED)
			SELECT 2,@SRM_CLIENTS_SEQ_ID,@SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID,11,1,@GROUP_NAME,@DATE_CREATED,@CREATED_BY,@DELETED
		END      
		
		SET @MAX_ROW_INDEX = 0
		SET @MAX_COLUMN_INDEX = 0

		IF @ROW_INDEX= 0 OR @COLUMN_INDEX=0
		BEGIN
			SELECT TOP 1 @MAX_ROW_INDEX = ROW_INDEX, @MAX_COLUMN_INDEX = COLUMN_INDEX
			FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS AS SCEAGD 
			WHERE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID=@SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID
			ORDER BY SEQ_ID DESC

			IF @MAX_ROW_INDEX=0 AND @MAX_COLUMN_INDEX=0
			BEGIN
				SET @ROW_INDEX = 1
				SET @COLUMN_INDEX = 1
			END          
			ELSE
			BEGIN          
				IF @MAX_COLUMN_INDEX = 1
				BEGIN
					SET @ROW_INDEX = @MAX_ROW_INDEX
					SET @COLUMN_INDEX = @MAX_COLUMN_INDEX + 1
				END
				ELSE IF @MAX_COLUMN_INDEX = 2
				BEGIN
					SET @ROW_INDEX = @MAX_ROW_INDEX + 1
					SET @COLUMN_INDEX = 1
				END  
			END       
		END      
	END 
	
	IF @ROW_INDEX=0 AND @COLUMN_INDEX=0
	BEGIN
		SET @ROW_INDEX = 1
		SET @COLUMN_INDEX = 1  
	END  

	INSERT INTO dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS
	(SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID,SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,
	 ROW_INDEX,COLUMN_INDEX,DISPLAY_ONLY,DISPLAY_ONLY_ON_EDIT,MANDATORY,DATE_CREATED,CREATED_BY,DELETED)
	SELECT @SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID,@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2,@ROW_INDEX,@COLUMN_INDEX,
	@READ_ONLY_ON_ADD, @READ_ONLY_ON_EDIT,@MANDATORY,
	@DATE_CREATED,@CREATED_BY,@DELETED
END




;





-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[CREATE_WORKFLOW_COPY_FOR_DIFFERENT_CLIENT]
	-- Add the parameters for the stored procedure here
	@FROM_SRM_CLIENTS_SEQ_ID BIGINT = 0,
	@TO_SRM_CLIENTS_SEQ_ID BIGINT = 0,
	@FROM_SRM_USERS_SEQ_ID BIGINT = 0,	
	@FROM_WFL_WORKFLOWS_SEQ_ID BIGINT = 0,
	@ERROR NVARCHAR(1) OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(500) OUTPUT
AS

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 'N'
	SET @ERROR_DESCRIPTION = 'NO ERROR'

	DECLARE @CREATE_COPY_WORKFLOW_LOG_SEQ_ID BIGINT = 0
	DECLARE @SAME_CLIENT CHAR(1)

	SET @SAME_CLIENT = 'N'

	INSERT INTO [SRM-Workflow].dbo.CREATE_COPY_WORKFLOW_LOG(FROM_SRM_CLIENTS_SEQ_ID, TO_SRM_CLIENTS_SEQ_ID, FROM_SRM_USERS_SEQ_ID, FROM_WFL_WORKFLOWS_SEQ_ID,DATE_CREATED)
	SELECT @FROM_SRM_CLIENTS_SEQ_ID, @TO_SRM_CLIENTS_SEQ_ID, @FROM_SRM_USERS_SEQ_ID, @FROM_WFL_WORKFLOWS_SEQ_ID, GETDATE()

	SET @CREATE_COPY_WORKFLOW_LOG_SEQ_ID = @@IDENTITY

	IF (ISNULL(@FROM_WFL_WORKFLOWS_SEQ_ID,0) = 0)
	BEGIN
		SET @ERROR = 'Y'  
		SET @ERROR_DESCRIPTION = 'Workflow id is blank. Please refresh screen and try again.'

		UPDATE [SRM-Workflow].dbo.CREATE_COPY_WORKFLOW_LOG SET ERROR=@ERROR, ERROR_DESCRIPTION=@ERROR_DESCRIPTION WHERE SEQ_ID=@CREATE_COPY_WORKFLOW_LOG_SEQ_ID
		RETURN;
	END 
	ELSE IF (ISNULL(@TO_SRM_CLIENTS_SEQ_ID,0) = 0)
	BEGIN
		SET @ERROR = 'Y'  
		SET @ERROR_DESCRIPTION = 'Please select a client to continue.'

		UPDATE [SRM-Workflow].dbo.CREATE_COPY_WORKFLOW_LOG SET ERROR=@ERROR, ERROR_DESCRIPTION=@ERROR_DESCRIPTION WHERE SEQ_ID=@CREATE_COPY_WORKFLOW_LOG_SEQ_ID
		RETURN;
	END 
	ELSE IF (ISNULL(@FROM_SRM_CLIENTS_SEQ_ID,0) = 0)
	BEGIN
		SELECT @FROM_SRM_CLIENTS_SEQ_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOWS WHERE SEQ_ID = @FROM_WFL_WORKFLOWS_SEQ_ID  
		IF (ISNULL(@FROM_SRM_CLIENTS_SEQ_ID,0) = 0)
		BEGIN
			SET @ERROR = 'Y'  
			SET @ERROR_DESCRIPTION = 'Client id is missing of the Source workflow.'

			UPDATE [SRM-Workflow].dbo.CREATE_COPY_WORKFLOW_LOG SET ERROR=@ERROR, ERROR_DESCRIPTION=@ERROR_DESCRIPTION WHERE SEQ_ID=@CREATE_COPY_WORKFLOW_LOG_SEQ_ID
			RETURN;			
		END
	END 
	ELSE IF (ISNULL(@FROM_SRM_USERS_SEQ_ID,0) = 0)
	BEGIN
		SELECT @FROM_SRM_USERS_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_USERS WHERE SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND ISNULL(SUPER_ADMIN,'N') = 'Y' ORDER BY SEQ_ID
		IF (ISNULL(@FROM_SRM_USERS_SEQ_ID,0) = 0)
		BEGIN
			SET @ERROR = 'Y'  
			SET @ERROR_DESCRIPTION = 'Source User id is missing.'

			UPDATE [SRM-Workflow].dbo.CREATE_COPY_WORKFLOW_LOG SET ERROR=@ERROR, ERROR_DESCRIPTION=@ERROR_DESCRIPTION WHERE SEQ_ID=@CREATE_COPY_WORKFLOW_LOG_SEQ_ID
			RETURN;			
		END
	END 


	--RETURN;

	DECLARE @TO_SRM_USERS_SEQ_ID BIGINT = 0
	DECLARE @CREATED_BY NVARCHAR(100) 
	SELECT TOP 1 @TO_SRM_USERS_SEQ_ID = SEQ_ID, @CREATED_BY = LOGIN_USER_NAME FROM [SRM-Framework_New].dbo.SRM_USERS WHERE SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID AND ISNULL(SUPER_ADMIN,'N') = 'Y' ORDER BY SEQ_ID

	
	PRINT @TO_SRM_USERS_SEQ_ID
	PRINT @CREATED_BY

	DECLARE @WFL_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @MAIN_NEW_WFL_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
	DECLARE @XML_EXPRESSION XML 
	DECLARE @NEW_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @I BIGINT  
	DECLARE @SRM_CLIENT_ENTITY_SEQ_ID_NEW BIGINT
	DECLARE @SRM_CLIENT_ENTITY_SEQ_ID_OLD BIGINT  
  	DECLARE @DATE_CREATED DATETIME
	SET @DATE_CREATED = GETDATE()  

	DECLARE @SRM_USERS_SEQ_ID BIGINT
	DECLARE @NEW_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @OLD_WORKFLOWS_SEQ_ID BIGINT   
	DECLARE @WFL_DESIGNER_TASK_DETAIL_SEQ_ID BIGINT  
	DECLARE @OLD_DESIGNER_TASK_ID NVARCHAR(255)
	DECLARE @NEW_DESIGNER_TASK_ID NVARCHAR(255)
	DECLARE @OLD_TASK_DETAIL NVARCHAR(MAX)
	DECLARE @NEW_TASK_DETAIL_XML XML
	DECLARE @WORKFLOWS_SEQ_ID BIGINT
	DECLARE @TASK_DETAIL XML
	DECLARE @TASK_TYPE_ID SMALLINT
  	DECLARE @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID BIGINT
  	DECLARE @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT
	DECLARE @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT  
  
  
	DECLARE @WFL_TASKS_SEQ_ID BIGINT 
	DECLARE @WFL_SUB_TASKS_SEQ_ID BIGINT 
	DECLARE @NEW_WFL_SUB_TASKS_SEQ_ID BIGINT
	DECLARE @NEW_WFL_TASKS_SEQ_ID BIGINT  

	DECLARE @WFL_WORKFLOWS_SEBIGINTBIGINT BIGINT
	DECLARE @NEW_WFL_WORKFLOWS_SEQ_ID2 BIGINT
	DECLARE @WFL_WORKFLOWS_SEQ_ID2 BIGINT 
	DECLARE @OLD_WFL_WORKFLOWS_SEQ_ID BIGINT
	
	DECLARE @WFL_VARIABLES_SEQ_ID BIGINT
	DECLARE @WFL_TASK_CONDITIONS_SEQ_ID  BIGINT
	DECLARE @NEW_WFL_TASK_CONDITIONS_SEQ_ID BIGINT  
	DECLARE @WFL_TASK_DETAILS_SEQ_ID BIGINT

	DECLARE @WFL_MAILMERGE_TEMPLATES_SEQ_ID BIGINT
  
	DECLARE @WFL_MAPPINGS_SEQ_ID BIGINT    
	DECLARE @NEW_SRM_ENTITIES_SEQ_ID BIGINT
    DECLARE @SRM_ENTITIES_SEQ_ID BIGINT
	DECLARE @Id INT
  
      

  	DECLARE @TEMP_WFL_WORKFLOWS TABLE
	(
		SEQ_ID BIGINT,
		PROCESSED CHAR(1)
    )  

	IF (ISNULL(@FROM_SRM_CLIENTS_SEQ_ID,0) = ISNULL(@TO_SRM_CLIENTS_SEQ_ID,0)) -- FOR SAME CLIENT
	BEGIN
		SET @SAME_CLIENT = 'Y'  
		INSERT INTO @TEMP_WFL_WORKFLOWS( SEQ_ID, PROCESSED ) SELECT @FROM_WFL_WORKFLOWS_SEQ_ID, 'Y'
	END
	ELSE   
	BEGIN
	--------POPULATE WORKFLOW AND ALL SUB WORKFLOWS (NESTED) START-----------------------
		INSERT INTO @TEMP_WFL_WORKFLOWS( SEQ_ID, PROCESSED )
		SELECT SEQ_ID, 'Y' FROM [SRM-Workflow].dbo.WFL_WORKFLOWS WHERE SEQ_ID=@FROM_WFL_WORKFLOWS_SEQ_ID UNION
		SELECT WFL_WORKFLOWS_SEQ_ID2, 'N' FROM [SRM-Workflow].dbo.WFL_TASKS WHERE TASK_TYPE_ID=1 AND WFL_WORKFLOWS_SEQ_ID2 IS NOT NULL AND WFL_WORKFLOWS_SEQ_ID=@FROM_WFL_WORKFLOWS_SEQ_ID 

		DECLARE curGeneral CURSOR FOR 
		SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS WHERE PROCESSED = 'N'
   
		OPEN curGeneral                                                             
		FETCH NEXT FROM curGeneral INTO @Id    

		WHILE (@@Fetch_Status = 0)       
		BEGIN        

			INSERT INTO @TEMP_WFL_WORKFLOWS( SEQ_ID, PROCESSED )
			SELECT WFL_WORKFLOWS_SEQ_ID2, 'N' FROM [SRM-Workflow].dbo.WFL_TASKS WHERE TASK_TYPE_ID=1 AND WFL_WORKFLOWS_SEQ_ID2 IS NOT NULL AND WFL_WORKFLOWS_SEQ_ID=@Id AND
			WFL_WORKFLOWS_SEQ_ID2 NOT IN (SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS)

			UPDATE @TEMP_WFL_WORKFLOWS SET PROCESSED='Y' WHERE SEQ_ID=@Id    

			FETCH NEXT FROM curGeneral INTO @Id    
		END    
   
		CLOSE curGeneral                           
		DEALLOCATE curGeneral  
	END 
    --------POPULATE WORKFLOW AND ALL SUB WORKFLOWS (NESTED) END-----------------------
	PRINT '@SAME_CLIENT: ' + @SAME_CLIENT 
   	DECLARE @TEMP_WFL_WORKFLOWS_TABLE TABLE
	(
		WFL_WORKFLOWS_SEQ_ID BIGINT,
		WFL_WORKFLOWS_SEQ_ID2 BIGINT
	)  

	DECLARE @TEMP_ENTITY_CLIENT_ENTITY_TABLE TABLE
	(
		SRM_ENTITIES_SEQ_ID BIGINT,
		SRM_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT
	)

	DECLARE @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE TABLE
	(
		OLD_WORKFLOWS_SEQ_ID BIGINT,
		NEW_WORKFLOWS_SEQ_ID BIGINT,
		OLD_DESIGNER_TASK_ID VARCHAR(100),
		NEW_DESIGNER_TASK_ID VARCHAR(100)
	)   

	DECLARE @TEMP_WFL_TASKS_TABLE TABLE
	(
		WFL_TASKS_SEQ_ID BIGINT,
		WFL_TASKS_SEQ_ID2 BIGINT
	)

	DECLARE @TEMP_WFL_TASK_CONDITIONS_TABLE TABLE
	(
		WFL_TASK_CONDITIONS_SEQ_ID BIGINT,
		WFL_TASK_CONDITIONS_SEQ_ID2 BIGINT
	)  

	DECLARE @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE TABLE
	(
		SRM_ENTITIES_SEQ_ID BIGINT,
		SRM_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT,
		SRM_ENTITY_ATTRIBUTES_SEQ_ID BIGINT,
		SRM_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT
	)


	--POPULATE TEMP TABLES
	INSERT INTO @TEMP_ENTITY_CLIENT_ENTITY_TABLE
	        ( SRM_ENTITIES_SEQ_ID ,
	          SRM_ENTITIES_SEQ_ID2 ,
	          SRM_CLIENT_ENTITIES_SEQ_ID ,
	          SRM_CLIENT_ENTITIES_SEQ_ID2
	        )
	SELECT OLD.SRM_ENTITIES_SEQ_ID, NEW.SRM_ENTITIES_SEQ_ID, OLD.SEQ_ID, NEW.SEQ_ID
	FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES OLD 
	LEFT OUTER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES NEW ON NEW.SRM_CLIENTS_SEQ_ID=@TO_SRM_CLIENTS_SEQ_ID AND OLD.ENTITY_DISPLAY_NAME=NEW.ENTITY_DISPLAY_NAME
	WHERE OLD.SEQ_ID IN 
	(SELECT SRM_CLIENT_ENTITY_SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOWS WHERE SEQ_ID IN (SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS) AND ISNULL(SRM_CLIENT_ENTITY_SEQ_ID,0) > 0 UNION
	SELECT SRM_CLIENT_ENTITY_SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID IN (SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS) AND ISNULL(SRM_CLIENT_ENTITY_SEQ_ID,0) > 0)

	DELETE FROM @TEMP_WFL_WORKFLOWS WHERE SEQ_ID=0

	--SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS
	--SELECT * FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE

	--RETURN;
	-------------------------------------------- [SRM-Workflow].dbo.WFL_WORKFLOWS -------------------------------------------------------

--BEGIN TRANSACTION

DECLARE CUR_WFL_WORKFLOWS CURSOR STATIC FOR
SELECT SEQ_ID, SRM_CLIENT_ENTITY_SEQ_ID, EXPRESSION FROM [SRM-Workflow].dbo.WFL_WORKFLOWS w
WHERE w.SEQ_ID IN (SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS)

OPEN CUR_WFL_WORKFLOWS 

FETCH NEXT FROM CUR_WFL_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @XML_EXPRESSION

WHILE @@FETCH_STATUS = 0
BEGIN

	
	

	IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NOT NULL AND @SRM_CLIENT_ENTITIES_SEQ_ID > 0
    BEGIN  
		SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = t.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM  @TEMP_ENTITY_CLIENT_ENTITY_TABLE t 
		WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
	END 
	ELSE
	BEGIN
  		SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = NULL
	END 
	
	IF (@XML_EXPRESSION.exist('//CLIENT_ENTITY_ID') = 1)
	BEGIN
		SET @I = 0
		SET @I = @XML_EXPRESSION.value('count(//CLIENT_ENTITY_ID)', 'VARCHAR(10)')
		WHILE @I > 0	
		BEGIN
			SET @SRM_CLIENT_ENTITY_SEQ_ID_NEW = 0
			SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD = 0

			SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD =  RTRIM(LTRIM(REPLACE(REPLACE((@XML_EXPRESSION.value('((//CLIENT_ENTITY_ID)[sql:variable("@I")]/node())[1]', 'VARCHAR(10)')), CHAR(10), ''), CHAR(13), '')))

			IF (@SRM_CLIENT_ENTITY_SEQ_ID_OLD > 0)
			BEGIN
				SELECT @SRM_CLIENT_ENTITY_SEQ_ID_NEW = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID_OLD

				IF (@SRM_CLIENT_ENTITY_SEQ_ID_NEW > 0)
				BEGIN
					SET @XML_EXPRESSION.modify('replace value of ((//CLIENT_ENTITY_ID)[sql:variable("@I")]/text())[1] with sql:variable("@SRM_CLIENT_ENTITY_SEQ_ID_NEW")')
				END 
			END
			SET @I = @I - 1
		END
	END 
	
	INSERT INTO [SRM-Workflow].dbo.WFL_WORKFLOWS
	        ( DESCRIPTION ,
				SRM_CLIENT_ENTITY_SEQ_ID ,
				EXPRESSION ,
				REMARKS ,
