---------------------------------------- UPDATE [SRM-Workflow].WFL_DESIGNER_TASK_DETAILS --------------------------------------------------

		DECLARE CUR_WFL_DESIGNER_TASK_DETAILS CURSOR STATIC FOR 
		SELECT WFL_DESIGNER_TASK_DETAIL_SEQ_ID, DESIGNER_TASK_ID, TASK_DETAIL, WFL_WORKFLOWS_SEQ_ID, TASK_TYPE_ID
		FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd 
		WHERE WFL_WORKFLOWS_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)

		OPEN CUR_WFL_DESIGNER_TASK_DETAILS 

		FETCH NEXT FROM CUR_WFL_DESIGNER_TASK_DETAILS INTO @WFL_DESIGNER_TASK_DETAIL_SEQ_ID, @OLD_DESIGNER_TASK_ID, @OLD_TASK_DETAIL, @WORKFLOWS_SEQ_ID, @TASK_TYPE_ID

		WHILE @@FETCH_STATUS = 0
		BEGIN

			IF @OLD_DESIGNER_TASK_ID = '00000000-0000-0000-0000-000000000000'
			BEGIN
				SET @NEW_DESIGNER_TASK_ID = @OLD_DESIGNER_TASK_ID
			END 
			ELSE
			BEGIN
				SET @NEW_DESIGNER_TASK_ID = NEWID()
			END

			SET @OLD_TASK_DETAIL = REPLACE(@OLD_TASK_DETAIL, @OLD_DESIGNER_TASK_ID, @NEW_DESIGNER_TASK_ID)
    
			SET @NEW_TASK_DETAIL_XML = CONVERT(XML, @OLD_TASK_DETAIL)
  
			IF (@NEW_TASK_DETAIL_XML.exist('//EntityId') = 1)
			BEGIN
				SET @I = 0
				SET @I = @NEW_TASK_DETAIL_XML.value('count(//EntityId)', 'INT')
				WHILE @I > 0	
				BEGIN
					SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = 0
					SET @SRM_CLIENT_ENTITIES_SEQ_ID = 0

					SET @SRM_CLIENT_ENTITIES_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//EntityId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

					IF (@SRM_CLIENT_ENTITIES_SEQ_ID > 0)
					BEGIN
						SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

						IF (@NEW_SRM_CLIENT_ENTITIES_SEQ_ID > 0)
						BEGIN
							SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//EntityId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_SRM_CLIENT_ENTITIES_SEQ_ID")')
						END 
					END
					SET @I = @I - 1
				END
			END      
  
			IF (@NEW_TASK_DETAIL_XML.exist('//WorkflowId') = 1)
			BEGIN
				SET @I = 0
				SET @I = @NEW_TASK_DETAIL_XML.value('count(//WorkflowId)', 'INT')
				WHILE @I > 0	
				BEGIN
					SET @NEW_WORKFLOWS_SEQ_ID = 0
					SET @OLD_WORKFLOWS_SEQ_ID = 0

					SET @OLD_WORKFLOWS_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//WorkflowId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

					IF (@OLD_WORKFLOWS_SEQ_ID > 0)
					BEGIN
						SET @NEW_WORKFLOWS_SEQ_ID = (SELECT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @OLD_WORKFLOWS_SEQ_ID)

						IF (@NEW_WORKFLOWS_SEQ_ID > 0)
						BEGIN
							SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//WorkflowId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_WORKFLOWS_SEQ_ID")')
						END 
					END
					SET @I = @I - 1
				END
			END 
  
			IF (@NEW_TASK_DETAIL_XML.exist('//SubworkflowId') = 1)
			BEGIN
				SET @I = 0
				SET @I = @NEW_TASK_DETAIL_XML.value('count(//SubworkflowId)', 'INT')
				WHILE @I > 0	
				BEGIN
					SET @NEW_WORKFLOWS_SEQ_ID = 0
					SET @OLD_WORKFLOWS_SEQ_ID = 0

					SET @OLD_WORKFLOWS_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//SubworkflowId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

					IF (@OLD_WORKFLOWS_SEQ_ID > 0)
					BEGIN
						SET @NEW_WORKFLOWS_SEQ_ID = (SELECT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @OLD_WORKFLOWS_SEQ_ID)

						IF (@NEW_WORKFLOWS_SEQ_ID > 0)
						BEGIN
							SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//SubworkflowId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_WORKFLOWS_SEQ_ID")')
						END 
					END
					SET @I = @I - 1
				END
			END
		
			IF (@NEW_TASK_DETAIL_XML.exist('//SubworkflowId') = 1)
			BEGIN
				SET @I = 0
				SET @I = @NEW_TASK_DETAIL_XML.value('count(//SubworkflowId)', 'INT')
				WHILE @I > 0	
				BEGIN
					SET @NEW_WORKFLOWS_SEQ_ID = 0
					SET @OLD_WORKFLOWS_SEQ_ID = 0

					SET @OLD_WORKFLOWS_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//SubworkflowId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

					IF (@OLD_WORKFLOWS_SEQ_ID > 0)
					BEGIN
						SET @NEW_WORKFLOWS_SEQ_ID = (SELECT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @OLD_WORKFLOWS_SEQ_ID)

						IF (@NEW_WORKFLOWS_SEQ_ID > 0)
						BEGIN
							SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//SubworkflowId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_WORKFLOWS_SEQ_ID")')
						END 
					END
					SET @I = @I - 1
				END
			END      

			UPDATE [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS SET 
			DESIGNER_TASK_ID = @NEW_DESIGNER_TASK_ID,
			TASK_DETAIL = CONVERT(NVARCHAR(max),@NEW_TASK_DETAIL_XML)
			WHERE WFL_DESIGNER_TASK_DETAIL_SEQ_ID = @WFL_DESIGNER_TASK_DETAIL_SEQ_ID

			INSERT INTO @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE
			(
				OLD_WORKFLOWS_SEQ_ID,
				NEW_WORKFLOWS_SEQ_ID,
				OLD_DESIGNER_TASK_ID,
				NEW_DESIGNER_TASK_ID
			)
			VALUES
			(
				(SELECT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID2 = @WORKFLOWS_SEQ_ID),
				@WORKFLOWS_SEQ_ID,
				@OLD_DESIGNER_TASK_ID,
				@NEW_DESIGNER_TASK_ID
			)

			FETCH NEXT FROM CUR_WFL_DESIGNER_TASK_DETAILS INTO @WFL_DESIGNER_TASK_DETAIL_SEQ_ID, @OLD_DESIGNER_TASK_ID, @OLD_TASK_DETAIL, @WORKFLOWS_SEQ_ID, @TASK_TYPE_ID
		END

		CLOSE CUR_WFL_DESIGNER_TASK_DETAILS 
		DEALLOCATE CUR_WFL_DESIGNER_TASK_DETAILS


		------------------------For Update WFL_DESIGNER_TASK_DETAILS------------------------

		DECLARE @OLD_TASK_ID VARCHAR(100)
		DECLARE @NEW_TASK_ID VARCHAR(100)

		DECLARE CUR_WFL_DESIGNER_TASK_DETAILS_2 CURSOR STATIC FOR 
		SELECT WFL_DESIGNER_TASK_DETAIL_SEQ_ID, DESIGNER_TASK_ID, TASK_DETAIL, WFL_WORKFLOWS_SEQ_ID
		FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd 
		WHERE WFL_WORKFLOWS_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)
		AND TASK_TYPE_ID = 4

		OPEN CUR_WFL_DESIGNER_TASK_DETAILS_2 

		FETCH NEXT FROM CUR_WFL_DESIGNER_TASK_DETAILS_2 INTO @WFL_DESIGNER_TASK_DETAIL_SEQ_ID, @OLD_DESIGNER_TASK_ID, @OLD_TASK_DETAIL, @WORKFLOWS_SEQ_ID

		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @NEW_TASK_DETAIL_XML = CONVERT(XML,@OLD_TASK_DETAIL)

			IF (@NEW_TASK_DETAIL_XML.exist('//ConditionalMappingsModel/TaskId') = 1)
				BEGIN
					SET @I = 0
					SET @I = @NEW_TASK_DETAIL_XML.value('count(//ConditionalMappingsModel/TaskId)', 'INT')
					WHILE @I > 0	
					BEGIN
						SET @OLD_TASK_ID = (@NEW_TASK_DETAIL_XML.value('((//ConditionalMappingsModel)[sql:variable("@I")]/TaskId/node())[1]', 'VARCHAR(MAX)'))
						SET @NEW_TASK_ID = (SELECT TOP 1 NEW_DESIGNER_TASK_ID FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE WHERE OLD_DESIGNER_TASK_ID = @OLD_TASK_ID)

						IF @NEW_TASK_ID != ''
						BEGIN
					
							SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//ConditionalMappingsModel)[sql:variable("@I")]/TaskId/text())[1] with sql:variable("@NEW_TASK_ID")')

							UPDATE [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS
							SET TASK_DETAIL = CONVERT(NVARCHAR(max),@NEW_TASK_DETAIL_XML)
							WHERE WFL_DESIGNER_TASK_DETAIL_SEQ_ID = @WFL_DESIGNER_TASK_DETAIL_SEQ_ID

						END 

						SET @I = @I - 1
					END
				END 

			FETCH NEXT FROM CUR_WFL_DESIGNER_TASK_DETAILS_2 INTO @WFL_DESIGNER_TASK_DETAIL_SEQ_ID, @OLD_DESIGNER_TASK_ID, @OLD_TASK_DETAIL, @WORKFLOWS_SEQ_ID
		END

		CLOSE CUR_WFL_DESIGNER_TASK_DETAILS_2 
		DEALLOCATE CUR_WFL_DESIGNER_TASK_DETAILS_2  

		------------------------For Update WFL_DESIGNER_TASK_DETAILS------------------------

		---------------------------------------- UPDATE [SRM-Workflow].WFL_DESIGNER_TASK_DETAILS --------------------------------------------------


		---- Update DIAGRAM_DETAIL, DIAGRAM_XML in WFL_WORKFLOWS ---------

		DECLARE @DIAGRAM_DETAIL NVARCHAR(MAX)
		DECLARE @DIAGRAM_XML NVARCHAR(MAX)

		PRINT 'Update TaskId in DIAGRAM_DETAIL, DIAGRAM_XML in [SRM-WorkFlow].dbo.WFL_WORKFLOWS'

		DECLARE CUR_WFL_WORKFLOWS CURSOR STATIC FOR
		SELECT SEQ_ID, DIAGRAM_DETAIL, DIAGRAM_XML FROM [SRM-WorkFlow].dbo.WFL_WORKFLOWS AS ww WHERE SEQ_ID IN
		(SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)
		AND (DIAGRAM_DETAIL IS NOT NULL OR DIAGRAM_XML IS NOT NULL)

		OPEN CUR_WFL_WORKFLOWS 

		FETCH NEXT FROM CUR_WFL_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID, @DIAGRAM_DETAIL, @DIAGRAM_XML

		WHILE @@FETCH_STATUS = 0
		BEGIN
				--------------------------------

				DECLARE CUR_DESIGNER_TASK CURSOR STATIC FOR
				SELECT DESIGNER_TASK_ID FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd
				WHERE WFL_WORKFLOWS_SEQ_ID = (SELECT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE 
				WHERE WFL_WORKFLOWS_SEQ_ID2 = @WFL_WORKFLOWS_SEQ_ID)

				OPEN CUR_DESIGNER_TASK 

				FETCH NEXT FROM CUR_DESIGNER_TASK INTO @OLD_TASK_ID

				WHILE @@FETCH_STATUS = 0
				BEGIN

					SET @NEW_TASK_ID = (SELECT TOP 1 NEW_DESIGNER_TASK_ID FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE WHERE OLD_DESIGNER_TASK_ID = @OLD_TASK_ID)

					IF @NEW_TASK_ID != '' 
					BEGIN
						SET @DIAGRAM_DETAIL = REPLACE(@DIAGRAM_DETAIL, @OLD_TASK_ID, @NEW_TASK_ID)
						SET @DIAGRAM_XML = REPLACE(@DIAGRAM_XML, @OLD_TASK_ID, @NEW_TASK_ID)
					END
				

				FETCH NEXT FROM CUR_DESIGNER_TASK INTO @OLD_TASK_ID
				END

				CLOSE CUR_DESIGNER_TASK 
				DEALLOCATE CUR_DESIGNER_TASK

				--------------------------------

				UPDATE [SRM-Workflow].dbo.WFL_WORKFLOWS
				SET DIAGRAM_DETAIL = @DIAGRAM_DETAIL, DIAGRAM_XML = @DIAGRAM_XML
				WHERE SEQ_ID = @WFL_WORKFLOWS_SEQ_ID
	

		FETCH NEXT FROM CUR_WFL_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID, @DIAGRAM_DETAIL, @DIAGRAM_XML
		END

		CLOSE CUR_WFL_WORKFLOWS 
		DEALLOCATE CUR_WFL_WORKFLOWS

		---- Update DIAGRAM_DETAIL, DIAGRAM_XML in WFL_WORKFLOWS ---------

		


		---- Replace WFL_DESIGNER_VARIABLES ------

		PRINT 'Replace VariableId/TaskId/WorkflowId in WFL_DESIGNER_VARIABLES'

		DECLARE @WFL_DESIGNER_VARIABLES_SEQ_ID BIGINT
		DECLARE @VARIABLE_DETAIL NVARCHAR(MAX)
		DECLARE @NEW_SEQ_ID BIGINT

		DECLARE CUR_WFL_DESIGNER_VARIABLES CURSOR STATIC FOR
		SELECT SEQ_ID, TASK_ID, VARIABLE_DETAIL FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_VARIABLES AS ww 
		WHERE WFL_WORKFLOW_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)

		OPEN CUR_WFL_DESIGNER_VARIABLES 

		FETCH NEXT FROM CUR_WFL_DESIGNER_VARIABLES INTO @WFL_DESIGNER_VARIABLES_SEQ_ID, @OLD_TASK_ID, @VARIABLE_DETAIL

		WHILE @@FETCH_STATUS = 0
		BEGIN

				SET @NEW_TASK_ID = (SELECT TOP 1 NEW_DESIGNER_TASK_ID FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE WHERE OLD_DESIGNER_TASK_ID = @OLD_TASK_ID)

				SET @NEW_TASK_DETAIL_XML = CONVERT(XML,@VARIABLE_DETAIL)

				IF (@NEW_TASK_DETAIL_XML.exist('//VariableId') = 1)
				BEGIN
					SET @I = 0
					SET @I = @NEW_TASK_DETAIL_XML.value('count(//VariableId)', 'BIGINT')
					WHILE @I > 0	
					BEGIN
  
						SET @NEW_SEQ_ID = @WFL_DESIGNER_VARIABLES_SEQ_ID          
						SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//VariableId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_SEQ_ID")')
						SET @I = @I - 1

					END
				END 

				IF (@NEW_TASK_DETAIL_XML.exist('//TaskId') = 1)
				BEGIN
					SET @I = 0
					SET @I = @NEW_TASK_DETAIL_XML.value('count(//TaskId)', 'INT')
					WHILE @I > 0	
					BEGIN
						SET @OLD_TASK_ID = (@NEW_TASK_DETAIL_XML.value('((//TaskId)[sql:variable("@I")]/node())[1]', 'VARCHAR(MAX)'))
						SET @NEW_TASK_ID = (SELECT TOP 1 NEW_DESIGNER_TASK_ID FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE WHERE OLD_DESIGNER_TASK_ID = @OLD_TASK_ID)

						IF @NEW_TASK_ID != ''
						BEGIN
							SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//TaskId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_TASK_ID")')
						END 

						SET @I = @I - 1
					END
				END
		
				IF (@NEW_TASK_DETAIL_XML.exist('//WorkflowId') = 1)
				BEGIN
					SET @I = 0
					SET @I = @NEW_TASK_DETAIL_XML.value('count(//WorkflowId)', 'INT')
					WHILE @I > 0	
					BEGIN
						SET @NEW_WORKFLOWS_SEQ_ID = 0
						SET @OLD_WORKFLOWS_SEQ_ID = 0

						SET @OLD_WORKFLOWS_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//WorkflowId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

						IF (@OLD_WORKFLOWS_SEQ_ID > 0)
						BEGIN
							SET @NEW_WORKFLOWS_SEQ_ID = (SELECT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = @OLD_WORKFLOWS_SEQ_ID)

							IF (@NEW_WORKFLOWS_SEQ_ID > 0)
							BEGIN
								SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//WorkflowId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_WORKFLOWS_SEQ_ID")')
							END 
						END
						SET @I = @I - 1
					END
				END  

				UPDATE [SRM-Workflow].dbo.WFL_DESIGNER_VARIABLES
				SET TASK_ID = @NEW_TASK_ID, VARIABLE_DETAIL = CONVERT(NVARCHAR(MAX),@NEW_TASK_DETAIL_XML)
				WHERE SEQ_ID = @WFL_DESIGNER_VARIABLES_SEQ_ID

		FETCH NEXT FROM CUR_WFL_DESIGNER_VARIABLES INTO @WFL_DESIGNER_VARIABLES_SEQ_ID, @OLD_TASK_ID, @VARIABLE_DETAIL
		END

		CLOSE CUR_WFL_DESIGNER_VARIABLES 
		DEALLOCATE CUR_WFL_DESIGNER_VARIABLES


		---- Replace WFL_DESIGNER_VARIABLES ------

		DECLARE @WFL_DESIGNER_CONNECTIONS_SEQ_ID BIGINT
		DECLARE @CONNECTION_DETAIL NVARCHAR(MAX)


		---- Update CONNECTION_DETAIL in WFL_DESIGNER_CONNECTIONS ---------

		PRINT 'Replace TaskId in WFL_DESIGNER_CONNECTIONS'

		DECLARE CUR_WFL_DESIGNER_CONNECTIONS CURSOR STATIC FOR
		SELECT SEQ_ID, WFL_WORKFLOW_SEQ_ID, CONNECTION_DETAIL FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_CONNECTIONS AS ww 
		WHERE WFL_WORKFLOW_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)

		OPEN CUR_WFL_DESIGNER_CONNECTIONS 

		FETCH NEXT FROM CUR_WFL_DESIGNER_CONNECTIONS INTO @WFL_DESIGNER_CONNECTIONS_SEQ_ID, @WFL_WORKFLOWS_SEQ_ID, @CONNECTION_DETAIL

		WHILE @@FETCH_STATUS = 0
		BEGIN

				--------------------------------

				DECLARE CUR_DESIGNER_TASK CURSOR STATIC FOR
				SELECT DESIGNER_TASK_ID FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd
				WHERE WFL_WORKFLOWS_SEQ_ID = (SELECT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE 
				WHERE WFL_WORKFLOWS_SEQ_ID2 = @WFL_WORKFLOWS_SEQ_ID)

				OPEN CUR_DESIGNER_TASK 

				FETCH NEXT FROM CUR_DESIGNER_TASK INTO @OLD_TASK_ID

				WHILE @@FETCH_STATUS = 0
				BEGIN

					SET @NEW_TASK_ID = (SELECT TOP 1 NEW_DESIGNER_TASK_ID FROM @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE WHERE OLD_DESIGNER_TASK_ID = @OLD_TASK_ID)

					IF @NEW_TASK_ID != '' 
					BEGIN
						SET @CONNECTION_DETAIL = REPLACE(@CONNECTION_DETAIL, @OLD_TASK_ID, @NEW_TASK_ID)
					END

				FETCH NEXT FROM CUR_DESIGNER_TASK INTO @OLD_TASK_ID
				END

				CLOSE CUR_DESIGNER_TASK 
				DEALLOCATE CUR_DESIGNER_TASK

				--------------------------------

		UPDATE [SRM-Workflow].dbo.WFL_DESIGNER_CONNECTIONS
		SET CONNECTION_DETAIL = @CONNECTION_DETAIL
		WHERE SEQ_ID = @WFL_DESIGNER_CONNECTIONS_SEQ_ID
	

	FETCH NEXT FROM CUR_WFL_DESIGNER_CONNECTIONS INTO @WFL_DESIGNER_CONNECTIONS_SEQ_ID, @WFL_WORKFLOWS_SEQ_ID, @CONNECTION_DETAIL
	END

	CLOSE CUR_WFL_DESIGNER_CONNECTIONS 
	DEALLOCATE CUR_WFL_DESIGNER_CONNECTIONS


	---- Update CONNECTION_DETAIL in WFL_DESIGNER_CONNECTIONS ---------



	-- WFL_WORKFLOW_STARTING_OPTIONS
DECLARE CUR_WFL_WORKFLOW_STARTING_OPTIONS CURSOR STATIC FOR
SELECT SEQ_ID, WFL_WORKFLOWS_SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS 
WHERE WFL_WORKFLOWS_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE)


OPEN CUR_WFL_WORKFLOW_STARTING_OPTIONS 

FETCH NEXT FROM CUR_WFL_WORKFLOW_STARTING_OPTIONS INTO @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID, @OLD_WORKFLOWS_SEQ_ID

WHILE @@FETCH_STATUS = 0
BEGIN

	
	

