DECLARE CUR_WFL_WORKFLOWS CURSOR STATIC FOR
SELECT SEQ_ID, SRM_CLIENT_ENTITY_SEQ_ID, EXPRESSION FROM [SRM-Workflow].dbo.WFL_WORKFLOWS w
WHERE w.SEQ_ID IN (SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS)

