				MODIFIED_BY ,
				DATE_CREATED ,
				CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY ,
				SHOW_ON_QUERYBUILDER ,
				TRACKABLE ,
				SHOW_NOTIFICATION ,
				INPUT_HEADING ,
				INPUT_BUTTON_TEXT ,
				INPUT_SUCCESS_MESSAGE ,
