IF EXISTS(SELECT * FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE ISNULL(SRM_CLIENT_ENTITIES_SEQ_ID2,0) = 0)
	SET @ERROR_DESCRIPTION = 'Client Entity(ies) are missing while creating Workflow copy. New Workflow Id is ' + CAST(@MAIN_NEW_WFL_WORKFLOWS_SEQ_ID AS NVARCHAR(100))
ELSE
