--WFL_TASK_CONDITIONS

DECLARE CUR_WFL_TASK_CONDITIONS CURSOR STATIC FOR
SELECT DISTINCT wtc.SEQ_ID FROM 
[SRM-Workflow].dbo.WFL_WORKFLOWS AS ww, 
[SRM-Workflow].dbo.WFL_TASKS AS wt,
[SRM-Workflow].dbo.WFL_TASK_CONDITIONS AS wtc
WHERE (ww.SEQ_ID = wt.WFL_WORKFLOWS_SEQ_ID OR ww.SEQ_ID = wt.WFL_WORKFLOWS_SEQ_ID2) AND
(wt.SEQ_ID = wtc.WFL_TASKS_SEQ_ID OR wt.SEQ_ID = wtc.WFL_TASKS_SEQ_ID2) AND
ww.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND
ww.SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE)

OPEN CUR_WFL_TASK_CONDITIONS 

FETCH NEXT FROM CUR_WFL_TASK_CONDITIONS INTO @WFL_TASK_CONDITIONS_SEQ_ID

WHILE @@FETCH_STATUS = 0
BEGIN

	
	

	INSERT INTO [SRM-Workflow].dbo.WFL_TASK_CONDITIONS
	        ( WFL_TASKS_SEQ_ID ,
	          WFL_TASKS_SEQ_ID2 ,
	          RANK ,
	          SRM_CLIENTS_SEQ_ID ,
	          SOURCE_OF_DATA ,
	          SOURCE_FILE ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtc.WFL_TASKS_SEQ_ID) ,
	        (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtc.WFL_TASKS_SEQ_ID2) ,
	        RANK ,
	        @TO_SRM_CLIENTS_SEQ_ID ,
	        SOURCE_OF_DATA ,
	        SOURCE_FILE ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        @DATE_CREATED ,
	        @CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS wtc
	WHERE SEQ_ID = @WFL_TASK_CONDITIONS_SEQ_ID

	SET @NEW_WFL_TASK_CONDITIONS_SEQ_ID = @@IDENTITY

	INSERT INTO @TEMP_WFL_TASK_CONDITIONS_TABLE
	(WFL_TASK_CONDITIONS_SEQ_ID, WFL_TASK_CONDITIONS_SEQ_ID2)
	VALUES
	(@WFL_TASK_CONDITIONS_SEQ_ID, @NEW_WFL_TASK_CONDITIONS_SEQ_ID)  

	FETCH NEXT FROM CUR_WFL_TASK_CONDITIONS INTO @WFL_TASK_CONDITIONS_SEQ_ID
END

CLOSE CUR_WFL_TASK_CONDITIONS 
DEALLOCATE CUR_WFL_TASK_CONDITIONS


-- WFL_TASK_DETAILS

DECLARE @WFL_TASK_DETAILS_EXPRESSION XML
DECLARE @SP_NAME VARCHAR(1000)

DECLARE CUR_WFL_TASK_DETAILS CURSOR STATIC FOR
SELECT SEQ_ID, ISNULL(EXPRESSION,'') FROM [SRM-Workflow].dbo.WFL_TASK_DETAILS AS wtd WHERE 
SRM_CLIENTS_SEQ_ID =  @FROM_SRM_CLIENTS_SEQ_ID AND WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM
[SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE))

OPEN CUR_WFL_TASK_DETAILS 

FETCH NEXT FROM CUR_WFL_TASK_DETAILS INTO @WFL_TASK_DETAILS_SEQ_ID, @WFL_TASK_DETAILS_EXPRESSION

WHILE @@FETCH_STATUS = 0
BEGIN

	
	

	IF (@WFL_TASK_DETAILS_EXPRESSION.exist('//QUERY/CRITERIA_ATTRIBUTES/SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID') = 1)
	BEGIN
		SET @I = 0
		SET @I = (@WFL_TASK_DETAILS_EXPRESSION.value('count(//QUERY/CRITERIA_ATTRIBUTES/SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID)', 'INT'))
		WHILE @I > 0 
		BEGIN
			SET @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0
			SET @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0

			SET @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = (@WFL_TASK_DETAILS_EXPRESSION.value('(//QUERY/CRITERIA_ATTRIBUTES[sql:variable("@I")]/SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID/node())[1]', 'varchar(max)'))

			IF (@OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID > 0)
			BEGIN
				--SELECT @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
				SELECT TOP 1 
				@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = scea_new.SEQ_ID				
				FROM 
				dbo.SRM_CLIENT_ENTITIES AS sce_old,
				dbo.SRM_CLIENT_ENTITIES AS sce_new,
				dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS scea_old,
				dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS scea_new
				WHERE 
				sce_old.ENTITY_DISPLAY_NAME = sce_new.ENTITY_DISPLAY_NAME AND
				scea_old.ATTRIBUTE_DISPLAY_NAME = scea_new.ATTRIBUTE_DISPLAY_NAME AND
				scea_old.SRM_CLIENT_ENTITIES_SEQ_ID = sce_old.SEQ_ID AND
				scea_new.SRM_CLIENT_ENTITIES_SEQ_ID = sce_new.SEQ_ID AND
				sce_old.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND --OLD CLIENT ID
				sce_new.SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID--NEW CLIENT ID
				AND scea_old.SEQ_ID = @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

				IF (@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID > 0)
				BEGIN
					SET @WFL_TASK_DETAILS_EXPRESSION.modify('replace value of (//QUERY/CRITERIA_ATTRIBUTES[sql:variable("@I")]/SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID/text())[1] with sql:variable("@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID")')
				END 
			END
			SET @I = @I - 1
		END
	END	  

	IF (@WFL_TASK_DETAILS_EXPRESSION.exist('//QUERY/EMAIL_DETAILS') = 1)
	BEGIN
		SET @WFL_TASK_DETAILS_EXPRESSION.modify('replace value of (//QUERY/EMAIL_DETAILS/TO_ADDRESS/SOURCE_PROPERTY_VALUE/text())[1] with "stargetsupport@centrepoint.uk.com"')
		SET @WFL_TASK_DETAILS_EXPRESSION.modify('replace value of (//QUERY/EMAIL_DETAILS/CC_ADDRESS/SOURCE_PROPERTY_VALUE/text())[1] with ""')
		SET @WFL_TASK_DETAILS_EXPRESSION.modify('replace value of (//QUERY/EMAIL_DETAILS/BCC_ADDRESS/SOURCE_PROPERTY_VALUE/text())[1] with ""')

		SET @WFL_TASK_DETAILS_EXPRESSION.modify('replace value of (//QUERY/EMAIL_DETAILS/EMAIL_SUBJECT/SOURCE_PROPERTY_VALUE/text())[1] with ""') 
	END

	IF (@WFL_TASK_DETAILS_EXPRESSION.value('(//QUERY/ADDITIONAL_INFO/METHOD_NAME/node())[1]', 'varchar(max)') = 'ExecuteStoredProcedure')
	BEGIN
		SET @SP_NAME = RTRIM(LTRIM(@WFL_TASK_DETAILS_EXPRESSION.value('(//QUERY/ADDITIONAL_INFO/OUTPUT_PARAMETER_NAME/node())[1]', 'varchar(max)')))

		IF (SUBSTRING(@SP_NAME,LEN(@SP_NAME),1) = ']')
			BEGIN
				SET @SP_NAME = SUBSTRING(@SP_NAME,1,LEN(@SP_NAME)-1) + '_TO_BE_CHANGED' + SUBSTRING(@SP_NAME,LEN(@SP_NAME),1)
			END
		ELSE
			BEGIN
				SET @SP_NAME = (@SP_NAME + '_TO_BE_CHANGED')
			END      

		SET @WFL_TASK_DETAILS_EXPRESSION.modify('replace value of (//QUERY/ADDITIONAL_INFO/OUTPUT_PARAMETER_NAME/text())[1] with sql:variable("@SP_NAME")')
	END
  
	IF (@WFL_TASK_DETAILS_EXPRESSION.exist('//CLIENT_ENTITY_ID') = 1)
	BEGIN
		SET @SRM_CLIENT_ENTITY_SEQ_ID_NEW = 0
		SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD = 0

		SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD =  RTRIM(LTRIM(REPLACE(REPLACE((@WFL_TASK_DETAILS_EXPRESSION.value('((//CLIENT_ENTITY_ID/SOURCE_PROPERTY_VALUE)/node())[1]', 'VARCHAR(10)')), CHAR(10), ''), CHAR(13), '')))
		IF (@SRM_CLIENT_ENTITY_SEQ_ID_OLD > 0)
		BEGIN
			SELECT @SRM_CLIENT_ENTITY_SEQ_ID_NEW = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID_OLD
			IF (@SRM_CLIENT_ENTITY_SEQ_ID_NEW > 0)
			BEGIN
				SET @WFL_TASK_DETAILS_EXPRESSION.modify('replace value of ((//CLIENT_ENTITY_ID/SOURCE_PROPERTY_VALUE)/text())[1] with sql:variable("@SRM_CLIENT_ENTITY_SEQ_ID_NEW")')
			END 
		END
	END
  
	IF (@WFL_TASK_DETAILS_EXPRESSION.exist('//ENTITY_ID') = 1)
	BEGIN
		SET @NEW_SRM_ENTITIES_SEQ_ID = 0
		SET @SRM_ENTITIES_SEQ_ID = 0

		SET @SRM_ENTITIES_SEQ_ID =  RTRIM(LTRIM(REPLACE(REPLACE((@WFL_TASK_DETAILS_EXPRESSION.value('((//ENTITY_ID/SOURCE_PROPERTY_VALUE)/node())[1]', 'VARCHAR(10)')), CHAR(10), ''), CHAR(13), '')))
		IF (@SRM_ENTITIES_SEQ_ID > 0)
		BEGIN
			SELECT @NEW_SRM_ENTITIES_SEQ_ID = SRM_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_ENTITIES_SEQ_ID = @SRM_ENTITIES_SEQ_ID
			IF (@NEW_SRM_ENTITIES_SEQ_ID > 0)
			BEGIN
				SET @WFL_TASK_DETAILS_EXPRESSION.modify('replace value of ((//ENTITY_ID/SOURCE_PROPERTY_VALUE)/text())[1] with sql:variable("@NEW_SRM_ENTITIES_SEQ_ID")')
			END 
		END
	END 
	
	IF (@WFL_TASK_DETAILS_EXPRESSION.exist('//CLIENT_ID') = 1)
	BEGIN
		SET @WFL_TASK_DETAILS_EXPRESSION.modify('replace value of ((//CLIENT_ID/SOURCE_PROPERTY_VALUE)/text())[1] with sql:variable("@TO_SRM_CLIENTS_SEQ_ID")')
	END

	INSERT INTO [SRM-Workflow].dbo.WFL_TASK_DETAILS
	        ( WFL_TASKS_SEQ_ID ,
	          WFL_TASK_CONDITIONS_SEQ_ID ,
	          DETAILS_TYPE_ID ,
	          EXPRESSION ,
	          SRM_CLIENTS_SEQ_ID ,
	          SOURCE_OF_DATA ,
	          SOURCE_FILE ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtd.WFL_TASKS_SEQ_ID) ,
	        (SELECT WFL_TASK_CONDITIONS_SEQ_ID2 FROM @TEMP_WFL_TASK_CONDITIONS_TABLE WHERE WFL_TASK_CONDITIONS_SEQ_ID = wtd.WFL_TASK_CONDITIONS_SEQ_ID) ,
	        DETAILS_TYPE_ID ,
	        CONVERT(NVARCHAR(MAX), @WFL_TASK_DETAILS_EXPRESSION) ,
	        @TO_SRM_CLIENTS_SEQ_ID ,
	        SOURCE_OF_DATA ,
	        SOURCE_FILE ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        @DATE_CREATED ,
	        @CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-Workflow].dbo.WFL_TASK_DETAILS wtd
	WHERE wtd.SEQ_ID = @WFL_TASK_DETAILS_SEQ_ID

	FETCH NEXT FROM CUR_WFL_TASK_DETAILS INTO @WFL_TASK_DETAILS_SEQ_ID, @WFL_TASK_DETAILS_EXPRESSION
END

CLOSE CUR_WFL_TASK_DETAILS 
DEALLOCATE CUR_WFL_TASK_DETAILS 


-- WFL_MAILMERGE_TEMPLATES

DECLARE CUR_WFL_MAILMERGE_TEMPLATES CURSOR STATIC FOR
SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES AS wmt 
WHERE SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND
WFL_WORKFLOWS_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE)

OPEN CUR_WFL_MAILMERGE_TEMPLATES 

FETCH NEXT FROM CUR_WFL_MAILMERGE_TEMPLATES INTO @WFL_MAILMERGE_TEMPLATES_SEQ_ID

WHILE @@FETCH_STATUS = 0
BEGIN

	
	
	
	INSERT INTO [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES
	        ( WFL_WORKFLOWS_SEQ_ID ,
	          TEMPLATE_TITLE ,
	          ATTACHMENT_URL ,
	          REMARKS ,
	          SRM_CLIENTS_SEQ_ID ,
	          SOURCE_OF_DATA ,
	          SOURCE_FILE ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  (SELECT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = wmt.WFL_WORKFLOWS_SEQ_ID) ,
	        TEMPLATE_TITLE ,
	        ATTACHMENT_URL ,
	        REMARKS ,
	        @TO_SRM_CLIENTS_SEQ_ID ,
	        SOURCE_OF_DATA ,
	        SOURCE_FILE ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        @DATE_CREATED ,
	        @CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES wmt
	WHERE SEQ_ID = @WFL_MAILMERGE_TEMPLATES_SEQ_ID

	FETCH NEXT FROM CUR_WFL_MAILMERGE_TEMPLATES INTO @WFL_MAILMERGE_TEMPLATES_SEQ_ID
END

CLOSE CUR_WFL_MAILMERGE_TEMPLATES 
DEALLOCATE CUR_WFL_MAILMERGE_TEMPLATES


-- WFL_MAPPINGS

DECLARE CUR_WFL_MAPPINGS CURSOR STATIC FOR
SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_MAPPINGS AS wm WHERE 
SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND
WFL_WORKFLOWS_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE)

OPEN CUR_WFL_MAPPINGS 

FETCH NEXT FROM CUR_WFL_MAPPINGS INTO @WFL_MAPPINGS_SEQ_ID

WHILE @@FETCH_STATUS = 0
BEGIN

	
	

	INSERT INTO [SRM-Workflow].dbo.WFL_MAPPINGS
	        ( WFL_WORKFLOWS_SEQ_ID ,
	          ATTRIBUTE_SYSTEM_NAME ,
	          ATTRIBUTE_DESCRIPTION ,
	          SRM_CLIENTS_SEQ_ID ,
	          SOURCE_OF_DATA ,
	          SOURCE_FILE ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  (SELECT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE WHERE WFL_WORKFLOWS_SEQ_ID = wm.WFL_WORKFLOWS_SEQ_ID) ,
	        ATTRIBUTE_SYSTEM_NAME ,
	        ATTRIBUTE_DESCRIPTION ,
	        @TO_SRM_CLIENTS_SEQ_ID ,
	        SOURCE_OF_DATA ,
	        SOURCE_FILE ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        @DATE_CREATED ,
	        @CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-Workflow].dbo.WFL_MAPPINGS AS wm
	WHERE SEQ_ID = @WFL_MAPPINGS_SEQ_ID

	FETCH NEXT FROM CUR_WFL_MAPPINGS INTO @WFL_MAPPINGS_SEQ_ID
END

CLOSE CUR_WFL_MAPPINGS 
DEALLOCATE CUR_WFL_MAPPINGS 


---------------------------------------- ADDITIONAL UPDATE [SRM-Workflow].WFL_DESIGNER_TASK_DETAILS --------------------------------------------------

DECLARE CUR_WFL_DESIGNER_TASK_DETAILS_ADDITIONAL CURSOR STATIC FOR 
SELECT WFL_DESIGNER_TASK_DETAIL_SEQ_ID, TASK_DETAIL
FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd 
WHERE WFL_WORKFLOWS_SEQ_ID IN (SELECT DISTINCT WFL_WORKFLOWS_SEQ_ID2 FROM @TEMP_WFL_WORKFLOWS_TABLE)

OPEN CUR_WFL_DESIGNER_TASK_DETAILS_ADDITIONAL 

FETCH NEXT FROM CUR_WFL_DESIGNER_TASK_DETAILS_ADDITIONAL INTO @WFL_DESIGNER_TASK_DETAIL_SEQ_ID, @OLD_TASK_DETAIL

WHILE @@FETCH_STATUS = 0
BEGIN

	SET @NEW_TASK_DETAIL_XML = CONVERT(XML, @OLD_TASK_DETAIL)
  
	IF (@NEW_TASK_DETAIL_XML.exist('//ClientEntityAttributeId') = 1)
	BEGIN
		SET @I = 0
		SET @I = @NEW_TASK_DETAIL_XML.value('count(//ClientEntityAttributeId)', 'INT')
		WHILE @I > 0	
		BEGIN
			SET @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0
			SET @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0

			SET @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//ClientEntityAttributeId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

			IF (@OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID > 0)
			BEGIN
				SELECT TOP 1 
				@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = scea_new.SEQ_ID				
				FROM 
				dbo.SRM_CLIENT_ENTITIES AS sce_old,
				dbo.SRM_CLIENT_ENTITIES AS sce_new,
				dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS scea_old,
				dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS scea_new
				WHERE 
				sce_old.ENTITY_DISPLAY_NAME = sce_new.ENTITY_DISPLAY_NAME AND
				scea_old.ATTRIBUTE_DISPLAY_NAME = scea_new.ATTRIBUTE_DISPLAY_NAME AND
				scea_old.SRM_CLIENT_ENTITIES_SEQ_ID = sce_old.SEQ_ID AND
				scea_new.SRM_CLIENT_ENTITIES_SEQ_ID = sce_new.SEQ_ID AND
				sce_old.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND --OLD CLIENT ID
				sce_new.SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID--NEW CLIENT ID
				AND scea_old.SEQ_ID = @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

				--PRINT 'WFL_DESIGNER_TASK_DETAILS_ATTRIBUTE NEW ATTR' + CAST(@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS VARCHAR) 
				IF (@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID > 0)
				BEGIN
					SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//ClientEntityAttributeId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID")')
				END 
			END
			SET @I = @I - 1
		END
	END
  
	IF (@NEW_TASK_DETAIL_XML.exist('//SrmClientEntityAttributeId') = 1)
	BEGIN
		SET @I = 0
		SET @I = @NEW_TASK_DETAIL_XML.value('count(//SrmClientEntityAttributeId)', 'INT')
		WHILE @I > 0	
		BEGIN
			SET @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0
			SET @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0

			SET @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = (@NEW_TASK_DETAIL_XML.value('((//SrmClientEntityAttributeId)[sql:variable("@I")]/node())[1]', 'BIGINT'))

			--PRINT 'WFL_DESIGNER_TASK_DETAILS_ATTRIBUTE OLD ATTR' + CAST(@OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS VARCHAR) 
			IF (@OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID > 0)
			BEGIN
				--SELECT @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID--@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
				SELECT TOP 1 
				@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = scea_new.SEQ_ID				
				FROM 
				dbo.SRM_CLIENT_ENTITIES AS sce_old,
				dbo.SRM_CLIENT_ENTITIES AS sce_new,
				dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS scea_old,
				dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS scea_new
				WHERE 
				sce_old.ENTITY_DISPLAY_NAME = sce_new.ENTITY_DISPLAY_NAME AND
				scea_old.ATTRIBUTE_DISPLAY_NAME = scea_new.ATTRIBUTE_DISPLAY_NAME AND
				scea_old.SRM_CLIENT_ENTITIES_SEQ_ID = sce_old.SEQ_ID AND
				scea_new.SRM_CLIENT_ENTITIES_SEQ_ID = sce_new.SEQ_ID AND
				sce_old.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND --OLD CLIENT ID
				sce_new.SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID--NEW CLIENT ID
				AND scea_old.SEQ_ID = @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

				--PRINT 'WFL_DESIGNER_TASK_DETAILS_ATTRIBUTE NEW ATTR' + CAST(@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS VARCHAR) 
				IF (@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID > 0)
				BEGIN
					SET @NEW_TASK_DETAIL_XML.modify('replace value of ((//SrmClientEntityAttributeId)[sql:variable("@I")]/text())[1] with sql:variable("@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID")')
				END 
			END
			SET @I = @I - 1
		END
	END
	
	--PRINT 'WFL_DESIGNER_TASK_DETAILS with WFL_DESIGNER_TASK_DETAIL_SEQ_ID ' + CAST(@WFL_DESIGNER_TASK_DETAIL_SEQ_ID AS VARCHAR) 	
	UPDATE [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS SET 
	TASK_DETAIL = CONVERT(NVARCHAR(max),@NEW_TASK_DETAIL_XML)
	WHERE WFL_DESIGNER_TASK_DETAIL_SEQ_ID = @WFL_DESIGNER_TASK_DETAIL_SEQ_ID

	FETCH NEXT FROM CUR_WFL_DESIGNER_TASK_DETAILS_ADDITIONAL INTO @WFL_DESIGNER_TASK_DETAIL_SEQ_ID, @OLD_TASK_DETAIL
END

CLOSE CUR_WFL_DESIGNER_TASK_DETAILS_ADDITIONAL 
DEALLOCATE CUR_WFL_DESIGNER_TASK_DETAILS_ADDITIONAL

---------------------------------------- ADDITIONAL UPDATE [SRM-Workflow].WFL_DESIGNER_TASK_DETAILS --------------------------------------------------


