-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[CREATE_WORKFLOW_COPY_FOR_DIFFERENT_CLIENT_NI_eTargetLive]
	-- Add the parameters for the stored procedure here
	@FROM_SRM_CLIENTS_SEQ_ID BIGINT = 82,
	@TO_SRM_CLIENTS_SEQ_ID BIGINT = 40,
	@FROM_SRM_USERS_SEQ_ID BIGINT = 0,	
	@FROM_WFL_WORKFLOWS_SEQ_ID BIGINT = 0,
	@NEW_WFL_WORKFLOWS_SEQ_ID BIGINT OUTPUT,
	@ERROR NVARCHAR(1) OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(500) OUTPUT
AS

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 'N'
	SET @ERROR_DESCRIPTION = 'NO ERROR'

	DECLARE @CREATE_COPY_WORKFLOW_LOG_SEQ_ID BIGINT = 0
	DECLARE @SAME_CLIENT CHAR(1)

	SET @SAME_CLIENT = 'N'

	INSERT INTO [SRM-Workflow].dbo.CREATE_COPY_WORKFLOW_LOG(FROM_SRM_CLIENTS_SEQ_ID, TO_SRM_CLIENTS_SEQ_ID, FROM_SRM_USERS_SEQ_ID, FROM_WFL_WORKFLOWS_SEQ_ID,DATE_CREATED)
	SELECT @FROM_SRM_CLIENTS_SEQ_ID, @TO_SRM_CLIENTS_SEQ_ID, @FROM_SRM_USERS_SEQ_ID, @FROM_WFL_WORKFLOWS_SEQ_ID, GETDATE()

	SET @CREATE_COPY_WORKFLOW_LOG_SEQ_ID = @@IDENTITY

	IF (ISNULL(@FROM_WFL_WORKFLOWS_SEQ_ID,0) = 0)
	BEGIN
		SET @ERROR = 'Y'  
		SET @ERROR_DESCRIPTION = 'Workflow id is blank. Please refresh screen and try again.'

		UPDATE [SRM-Workflow].dbo.CREATE_COPY_WORKFLOW_LOG SET ERROR=@ERROR, ERROR_DESCRIPTION=@ERROR_DESCRIPTION WHERE SEQ_ID=@CREATE_COPY_WORKFLOW_LOG_SEQ_ID
		RETURN;
	END 
	ELSE IF (ISNULL(@TO_SRM_CLIENTS_SEQ_ID,0) = 0)
	BEGIN
		SET @ERROR = 'Y'  
		SET @ERROR_DESCRIPTION = 'Please select a client to continue.'

		UPDATE [SRM-Workflow].dbo.CREATE_COPY_WORKFLOW_LOG SET ERROR=@ERROR, ERROR_DESCRIPTION=@ERROR_DESCRIPTION WHERE SEQ_ID=@CREATE_COPY_WORKFLOW_LOG_SEQ_ID
		RETURN;
	END 
	ELSE IF (ISNULL(@FROM_SRM_CLIENTS_SEQ_ID,0) = 0)
	BEGIN
		SELECT @FROM_SRM_CLIENTS_SEQ_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOWS WHERE SEQ_ID = @FROM_WFL_WORKFLOWS_SEQ_ID  
		IF (ISNULL(@FROM_SRM_CLIENTS_SEQ_ID,0) = 0)
		BEGIN
			SET @ERROR = 'Y'  
			SET @ERROR_DESCRIPTION = 'Client id is missing of the Source workflow.'

			UPDATE [SRM-Workflow].dbo.CREATE_COPY_WORKFLOW_LOG SET ERROR=@ERROR, ERROR_DESCRIPTION=@ERROR_DESCRIPTION WHERE SEQ_ID=@CREATE_COPY_WORKFLOW_LOG_SEQ_ID
			RETURN;			
		END
	END 
	ELSE IF (ISNULL(@FROM_SRM_USERS_SEQ_ID,0) = 0)
	BEGIN
		SELECT @FROM_SRM_USERS_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_USERS WHERE SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID AND ISNULL(SUPER_ADMIN,'N') = 'Y' ORDER BY SEQ_ID
		IF (ISNULL(@FROM_SRM_USERS_SEQ_ID,0) = 0)
		BEGIN
			SET @ERROR = 'Y'  
			SET @ERROR_DESCRIPTION = 'Source User id is missing.'

			UPDATE [SRM-Workflow].dbo.CREATE_COPY_WORKFLOW_LOG SET ERROR=@ERROR, ERROR_DESCRIPTION=@ERROR_DESCRIPTION WHERE SEQ_ID=@CREATE_COPY_WORKFLOW_LOG_SEQ_ID
			RETURN;			
		END
	END 


	--RETURN;

	DECLARE @TO_SRM_USERS_SEQ_ID BIGINT = 0
	DECLARE @CREATED_BY NVARCHAR(100) 
	SELECT TOP 1 @TO_SRM_USERS_SEQ_ID = SEQ_ID, @CREATED_BY = LOGIN_USER_NAME FROM [SRM-Framework_New].dbo.SRM_USERS WHERE SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID AND ISNULL(SUPER_ADMIN,'N') = 'Y' ORDER BY SEQ_ID

	
	PRINT @TO_SRM_USERS_SEQ_ID
	PRINT @CREATED_BY

	DECLARE @WFL_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @MAIN_NEW_WFL_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
	DECLARE @XML_EXPRESSION XML 
	DECLARE @NEW_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @I BIGINT  
	DECLARE @SRM_CLIENT_ENTITY_SEQ_ID_NEW BIGINT
	DECLARE @SRM_CLIENT_ENTITY_SEQ_ID_OLD BIGINT  
  	DECLARE @DATE_CREATED DATETIME
	SET @DATE_CREATED = GETDATE()  

	DECLARE @SRM_USERS_SEQ_ID BIGINT
	DECLARE @NEW_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @OLD_WORKFLOWS_SEQ_ID BIGINT   
	DECLARE @WFL_DESIGNER_TASK_DETAIL_SEQ_ID BIGINT  
	DECLARE @OLD_DESIGNER_TASK_ID NVARCHAR(255)
	DECLARE @NEW_DESIGNER_TASK_ID NVARCHAR(255)
	DECLARE @OLD_TASK_DETAIL NVARCHAR(MAX)
	DECLARE @NEW_TASK_DETAIL_XML XML
	DECLARE @WORKFLOWS_SEQ_ID BIGINT
	DECLARE @TASK_DETAIL XML
	DECLARE @TASK_TYPE_ID SMALLINT
  	DECLARE @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID BIGINT
  	DECLARE @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT
	DECLARE @OLD_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT  
  
  
	DECLARE @WFL_TASKS_SEQ_ID BIGINT 
	DECLARE @WFL_SUB_TASKS_SEQ_ID BIGINT 
	DECLARE @NEW_WFL_SUB_TASKS_SEQ_ID BIGINT
	DECLARE @NEW_WFL_TASKS_SEQ_ID BIGINT  

	DECLARE @WFL_WORKFLOWS_SEBIGINTBIGINT BIGINT
	DECLARE @NEW_WFL_WORKFLOWS_SEQ_ID2 BIGINT
	DECLARE @WFL_WORKFLOWS_SEQ_ID2 BIGINT 
	DECLARE @OLD_WFL_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @TEMP_WFL_WORKFLOWS_SEQ_ID BIGINT
	
	DECLARE @WFL_VARIABLES_SEQ_ID BIGINT
	DECLARE @WFL_TASK_CONDITIONS_SEQ_ID  BIGINT
	DECLARE @NEW_WFL_TASK_CONDITIONS_SEQ_ID BIGINT  
	DECLARE @WFL_TASK_DETAILS_SEQ_ID BIGINT

	DECLARE @WFL_MAILMERGE_TEMPLATES_SEQ_ID BIGINT
  
	DECLARE @WFL_MAPPINGS_SEQ_ID BIGINT    
	DECLARE @NEW_SRM_ENTITIES_SEQ_ID BIGINT
    DECLARE @SRM_ENTITIES_SEQ_ID BIGINT
	DECLARE @Id INT
  
      

  	DECLARE @TEMP_WFL_WORKFLOWS TABLE
	(
		SEQ_ID BIGINT,
		PROCESSED CHAR(1)
    )  

	IF (ISNULL(@FROM_SRM_CLIENTS_SEQ_ID,0) = ISNULL(@TO_SRM_CLIENTS_SEQ_ID,0)) -- FOR SAME CLIENT
	BEGIN
		SET @SAME_CLIENT = 'Y'  
		INSERT INTO @TEMP_WFL_WORKFLOWS( SEQ_ID, PROCESSED ) SELECT @FROM_WFL_WORKFLOWS_SEQ_ID, 'Y'
	END
	ELSE   
	BEGIN
	--------POPULATE WORKFLOW AND ALL SUB WORKFLOWS (NESTED) START-----------------------
		INSERT INTO @TEMP_WFL_WORKFLOWS( SEQ_ID, PROCESSED )
		SELECT SEQ_ID, 'Y' FROM [SRM-Workflow].dbo.WFL_WORKFLOWS WHERE SEQ_ID=@FROM_WFL_WORKFLOWS_SEQ_ID 
		--commented below script because we dont need to create subworkflow
		--UNION SELECT WFL_WORKFLOWS_SEQ_ID2, 'N' FROM [SRM-Workflow].dbo.WFL_TASKS WHERE TASK_TYPE_ID=1 AND WFL_WORKFLOWS_SEQ_ID2 IS NOT NULL AND WFL_WORKFLOWS_SEQ_ID=@FROM_WFL_WORKFLOWS_SEQ_ID 

	--	DECLARE curGeneral CURSOR FOR 
	--	SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS WHERE PROCESSED = 'N'
   
	--	OPEN curGeneral                                                             
	--	FETCH NEXT FROM curGeneral INTO @Id    

	--	WHILE (@@Fetch_Status = 0)       
	--	BEGIN        

	--		INSERT INTO @TEMP_WFL_WORKFLOWS( SEQ_ID, PROCESSED )
	--		SELECT WFL_WORKFLOWS_SEQ_ID2, 'N' FROM [SRM-Workflow].dbo.WFL_TASKS WHERE TASK_TYPE_ID=1 AND WFL_WORKFLOWS_SEQ_ID2 IS NOT NULL AND WFL_WORKFLOWS_SEQ_ID=@Id AND
	--		WFL_WORKFLOWS_SEQ_ID2 NOT IN (SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS)

	--		UPDATE @TEMP_WFL_WORKFLOWS SET PROCESSED='Y' WHERE SEQ_ID=@Id    

	--		FETCH NEXT FROM curGeneral INTO @Id    
	--	END    
   
	--	CLOSE curGeneral                           
	--	DEALLOCATE curGeneral  
	END 
    --------POPULATE WORKFLOW AND ALL SUB WORKFLOWS (NESTED) END-----------------------
	PRINT '@SAME_CLIENT: ' + @SAME_CLIENT 
   	DECLARE @TEMP_WFL_WORKFLOWS_TABLE TABLE
	(
		WFL_WORKFLOWS_SEQ_ID BIGINT,
		WFL_WORKFLOWS_SEQ_ID2 BIGINT
	)  

	DECLARE @TEMP_ENTITY_CLIENT_ENTITY_TABLE TABLE
	(
		SRM_ENTITIES_SEQ_ID BIGINT,
		SRM_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT
	)

	DECLARE @TEMP_WFL_DESIGNER_TASK_DETAILS_TABLE TABLE
	(
		OLD_WORKFLOWS_SEQ_ID BIGINT,
		NEW_WORKFLOWS_SEQ_ID BIGINT,
		OLD_DESIGNER_TASK_ID VARCHAR(100),
		NEW_DESIGNER_TASK_ID VARCHAR(100)
	)   

	DECLARE @TEMP_WFL_TASKS_TABLE TABLE
	(
		WFL_TASKS_SEQ_ID BIGINT,
		WFL_TASKS_SEQ_ID2 BIGINT
	)

	DECLARE @TEMP_WFL_TASK_CONDITIONS_TABLE TABLE
	(
		WFL_TASK_CONDITIONS_SEQ_ID BIGINT,
		WFL_TASK_CONDITIONS_SEQ_ID2 BIGINT
	)  

	DECLARE @TEMP_ENTITY_CLIENT_ENTITY_ATTRIBUTES_TABLE TABLE
	(
		SRM_ENTITIES_SEQ_ID BIGINT,
		SRM_ENTITIES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT,
		SRM_ENTITY_ATTRIBUTES_SEQ_ID BIGINT,
		SRM_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT,
		SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT,
		SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT
	)


	--POPULATE TEMP TABLES
	INSERT INTO @TEMP_ENTITY_CLIENT_ENTITY_TABLE
	        ( SRM_ENTITIES_SEQ_ID ,
	          SRM_ENTITIES_SEQ_ID2 ,
	          SRM_CLIENT_ENTITIES_SEQ_ID ,
	          SRM_CLIENT_ENTITIES_SEQ_ID2
	        )
	SELECT OLD.SRM_ENTITIES_SEQ_ID, NEW.SRM_ENTITIES_SEQ_ID, OLD.SEQ_ID, NEW.SEQ_ID
	FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES OLD 
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES NEW ON NEW.SRM_CLIENTS_SEQ_ID=@TO_SRM_CLIENTS_SEQ_ID AND OLD.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID
	AND OLD.ENTITY_DISPLAY_NAME=NEW.ENTITY_DISPLAY_NAME
	WHERE OLD.SEQ_ID IN 
	(SELECT SRM_CLIENT_ENTITY_SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOWS WHERE SEQ_ID IN (SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS) AND ISNULL(SRM_CLIENT_ENTITY_SEQ_ID,0) > 0 UNION
	SELECT SRM_CLIENT_ENTITY_SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID IN (SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS) AND ISNULL(SRM_CLIENT_ENTITY_SEQ_ID,0) > 0)

	DELETE FROM @TEMP_WFL_WORKFLOWS WHERE SEQ_ID=0

	-------------------------------------------- [SRM-Workflow].dbo.WFL_WORKFLOWS -------------------------------------------------------



DECLARE CUR_WFL_WORKFLOWS CURSOR STATIC FOR
SELECT SEQ_ID, SRM_CLIENT_ENTITY_SEQ_ID, EXPRESSION FROM [SRM-Workflow].dbo.WFL_WORKFLOWS w
WHERE w.SEQ_ID IN (SELECT SEQ_ID FROM @TEMP_WFL_WORKFLOWS)

OPEN CUR_WFL_WORKFLOWS 

FETCH NEXT FROM CUR_WFL_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @XML_EXPRESSION

WHILE @@FETCH_STATUS = 0
BEGIN

	
	

	IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NOT NULL AND @SRM_CLIENT_ENTITIES_SEQ_ID > 0
    BEGIN  
		SELECT @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = t.SRM_CLIENT_ENTITIES_SEQ_ID2 FROM  @TEMP_ENTITY_CLIENT_ENTITY_TABLE t 
		WHERE t.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
	END 
	ELSE
	BEGIN
  		SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = NULL
	END 
	
	IF (@XML_EXPRESSION.exist('//CLIENT_ENTITY_ID') = 1)
	BEGIN
		SET @I = 0
		SET @I = @XML_EXPRESSION.value('count(//CLIENT_ENTITY_ID)', 'VARCHAR(10)')
		WHILE @I > 0	
		BEGIN
			SET @SRM_CLIENT_ENTITY_SEQ_ID_NEW = 0
			SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD = 0

			SET @SRM_CLIENT_ENTITY_SEQ_ID_OLD =  RTRIM(LTRIM(REPLACE(REPLACE((@XML_EXPRESSION.value('((//CLIENT_ENTITY_ID)[sql:variable("@I")]/node())[1]', 'VARCHAR(10)')), CHAR(10), ''), CHAR(13), '')))

			IF (@SRM_CLIENT_ENTITY_SEQ_ID_OLD > 0)
			BEGIN
				SELECT @SRM_CLIENT_ENTITY_SEQ_ID_NEW = SRM_CLIENT_ENTITIES_SEQ_ID2 FROM @TEMP_ENTITY_CLIENT_ENTITY_TABLE WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID_OLD

				IF (@SRM_CLIENT_ENTITY_SEQ_ID_NEW > 0)
				BEGIN
					SET @XML_EXPRESSION.modify('replace value of ((//CLIENT_ENTITY_ID)[sql:variable("@I")]/text())[1] with sql:variable("@SRM_CLIENT_ENTITY_SEQ_ID_NEW")')
				END 
			END
			SET @I = @I - 1
		END
	END 
	
	INSERT INTO [SRM-Workflow].dbo.WFL_WORKFLOWS
	        ( DESCRIPTION ,
				SRM_CLIENT_ENTITY_SEQ_ID ,
				EXPRESSION ,
				REMARKS ,
				SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DIAGRAM_XML ,
				DIAGRAM_DETAIL ,
				SHOW_IN_JOBS ,
				OUTPUT_FILENAME ,
				DO_NOT_USE_QUOTE ,
				IS_ASYNC ,
				REQUIRE_MANUAL_INPUT ,
				ALWAYS_TRIGGER ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				DATE_CREATED ,
				CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY ,
				SHOW_ON_QUERYBUILDER ,
				TRACKABLE ,
				SHOW_NOTIFICATION ,
				INPUT_HEADING ,
				INPUT_BUTTON_TEXT ,
				INPUT_SUCCESS_MESSAGE ,
				INPUT_FAILURE_MESSAGE ,
				EXPORT_WITHOUT_HEADING ,
				AVAILABLE_FOR_TEMPLATES ,
				SRM_WORKFLOWS_SEQ_ID ,
				REQUIRE_TEMPLATE_INPUT
	        )
	SELECT  DESCRIPTION ,
			@NEW_SRM_CLIENT_ENTITIES_SEQ_ID ,
			CONVERT(NVARCHAR(MAX),@XML_EXPRESSION) ,
			REMARKS ,
			@TO_SRM_CLIENTS_SEQ_ID ,
			SOURCE_OF_DATA ,
			SOURCE_FILE ,
			DIAGRAM_XML ,
			DIAGRAM_DETAIL ,
			SHOW_IN_JOBS ,
			OUTPUT_FILENAME ,
			DO_NOT_USE_QUOTE ,
			IS_ASYNC ,
			REQUIRE_MANUAL_INPUT ,
			ALWAYS_TRIGGER ,
			DATE_MODIFIED ,
			MODIFIED_BY ,
			@DATE_CREATED ,
			@CREATED_BY ,
			DELETED ,
			DATE_DELETED ,
			DELETED_BY ,
			SHOW_ON_QUERYBUILDER ,
			TRACKABLE ,
			SHOW_NOTIFICATION ,
			INPUT_HEADING ,
			INPUT_BUTTON_TEXT ,
			INPUT_SUCCESS_MESSAGE ,
			INPUT_FAILURE_MESSAGE ,
			EXPORT_WITHOUT_HEADING ,
			AVAILABLE_FOR_TEMPLATES ,
			SRM_WORKFLOWS_SEQ_ID ,
			REQUIRE_TEMPLATE_INPUT 
	FROM [SRM-Workflow].dbo.WFL_WORKFLOWS AS ww
	WHERE SEQ_ID = @WFL_WORKFLOWS_SEQ_ID

	SET @NEW_WORKFLOWS_SEQ_ID = @@IDENTITY
	PRINT '@NEW_WORKFLOWS_SEQ_ID: ' + CAST(@NEW_WORKFLOWS_SEQ_ID AS NVARCHAR(100))
	--------------------------------------- INSERT [SRM-Workflow].dbo.WFL_DESIGNER_TASK_DETAILS ---------------------------------------

	PRINT 'Add WFL_DESIGNER_TASK_DETAILS'
	INSERT INTO [SRM-Workflow].dbo.WFL_DESIGNER_TASK_DETAILS
	        ( DESIGNER_TASK_ID ,
	          WFL_WORKFLOWS_SEQ_ID ,
	          TASK_NAME ,
	          TASK_DETAIL ,
	          TASK_TYPE_ID ,
	          TASK_VARIABLES ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  DESIGNER_TASK_ID ,
	        @NEW_WORKFLOWS_SEQ_ID ,
	        TASK_NAME ,
	        TASK_DETAIL ,
	        TASK_TYPE_ID ,
	        TASK_VARIABLES ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        GETDATE() ,
			@CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-WorkFlow].dbo.WFL_DESIGNER_TASK_DETAILS AS wdtd 
	WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID

	PRINT 'Add WFL_DESIGNER_VARIABLES'
	INSERT INTO [SRM-Workflow].dbo.WFL_DESIGNER_VARIABLES
	        ( WFL_WORKFLOW_SEQ_ID ,
	          TASK_ID ,
	          VARIABLE_NAME ,
	          VARIABLE_DETAIL ,
	          VARIABLE_TYPE ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  @NEW_WORKFLOWS_SEQ_ID ,
	        TASK_ID ,
	        VARIABLE_NAME ,
	        VARIABLE_DETAIL ,
	        VARIABLE_TYPE ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        GETDATE() ,
			@CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-Workflow].dbo.WFL_DESIGNER_VARIABLES wdv
	WHERE wdv.WFL_WORKFLOW_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID

	PRINT 'Add WFL_DESIGNER_CONNECTIONS'
	INSERT INTO [SRM-Workflow].dbo.WFL_DESIGNER_CONNECTIONS
	        ( WFL_WORKFLOW_SEQ_ID ,
	          CONNECTION_DETAIL ,
	          DATE_MODIFIED ,
	          MODIFIED_BY ,
	          DATE_CREATED ,
	          CREATED_BY ,
	          DELETED ,
	          DATE_DELETED ,
	          DELETED_BY
	        )
	SELECT  @NEW_WORKFLOWS_SEQ_ID ,
	        CONNECTION_DETAIL ,
	        DATE_MODIFIED ,
	        MODIFIED_BY ,
	        GETDATE() ,
			@CREATED_BY ,
	        DELETED ,
	        DATE_DELETED ,
	        DELETED_BY 
	FROM [SRM-Workflow].dbo.WFL_DESIGNER_CONNECTIONS AS wdc 
	WHERE WFL_WORKFLOW_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID

	--------------------------------------- INSERT [SRM-Workflow].dbo.WFL_DESIGNER_TASK_DETAILS ---------------------------------------

	INSERT INTO @TEMP_WFL_WORKFLOWS_TABLE
	(
		WFL_WORKFLOWS_SEQ_ID,
		WFL_WORKFLOWS_SEQ_ID2
	)
	VALUES
	(
		@WFL_WORKFLOWS_SEQ_ID,
		@NEW_WORKFLOWS_SEQ_ID
	)	

	INSERT INTO [SRM-ClientCopyLog].dbo.NI_WORKFLOW_COPY_LOG
	SELECT @WFL_WORKFLOWS_SEQ_ID, @NEW_WORKFLOWS_SEQ_ID

FETCH NEXT FROM CUR_WFL_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @XML_EXPRESSION
END

CLOSE CUR_WFL_WORKFLOWS 
