	AND WFL_WORKFLOWS_SEQ_ID=@FROM_WFL_WORKFLOWS_SEQ_ID AND WFL_WORKFLOWS_SEQ_ID2 NOT IN (SELECT WFL_WORKFLOWS_SEQ_ID FROM @TEMP_WFL_WORKFLOWS_TABLE)
END


