CREATE PROCEDURE [dbo].[Copy_SPs_Source_DataPivot_To_New_DataPivot]
@OLD_CLIENT_ID NVARCHAR(20),
@NEW_CLIENT_ID NVARCHAR(20)

AS

BEGIN

	SET @OLD_CLIENT_ID='[SRM-DATAPIVOT_' + @OLD_CLIENT_ID + ']'
	SET @NEW_CLIENT_ID='[SRM-DATAPIVOT_' + @NEW_CLIENT_ID + ']'
	PRINT @OLD_CLIENT_ID
	PRINT @NEW_CLIENT_ID

	DECLARE @SQL NVARCHAR(MAX) 
	DECLARE @NEW_SP_NAME NVARCHAR(500)
	DECLARE @sqlstr1 NVARCHAR(500)
	DECLARE @NAME VARCHAR(100)='SRM-DATAPIVOT'+@NEW_CLIENT_ID 
	--PRINT @NAME

	DECLARE @SP_NAME nvarchar(200)
	DECLARE @KillCommand nvarchar(200)


	DECLARE @selectCursor NVARCHAR(2000) 
    DECLARE @sp_names TABLE (sp_name NVARCHAR(2000))

   SET @selectCursor = 'USE ' + @OLD_CLIENT_ID + '; SELECT name FROM sysobjects where type = ''P'''
   PRINT @selectCursor
   INSERT INTO @sp_names
   EXECUTE (@selectCursor)

	DECLARE @getSPID CURSOR 
	SET @getSPID = CURSOR LOCAL FOR
		SELECT * FROM @sp_names
	OPEN @getSPID 
	FETCH NEXT
	FROM @getSPID INTO @SP_NAME
	WHILE @@FETCH_STATUS = 0
	BEGIN

		SET @NEW_SP_NAME = @NEW_CLIENT_ID + '.dbo.' + @SP_NAME
		--PRINT @NEW_SP_NAME

	

		SET @SQL =''

		SELECT @SQL = replace(definition, @OLD_CLIENT_ID , @NEW_CLIENT_ID)
			FROM [SRM-DataPivot_75].SYS.PROCEDURES PR 
			INNER JOIN [SRM-DataPivot_75].SYS.SQL_MODULES MOD ON PR.OBJECT_ID = MOD.OBJECT_ID 
			WHERE PR.IS_MS_SHIPPED = 0 AND 
			PR.NAME =  @SP_NAME
	
			IF @SQL != ''
			BEGIN	
				SET @SQL = REPLACE(@SQL,'''','''''') 
				SET @SQL = 'USE ' + @NEW_CLIENT_ID + '; EXEC(''' + @SQL + ''')' 
 
				EXEC [SRM-Framework_New].dbo.GET_PRINT @SQL
				EXEC(@SQL) 

				IF @@ERROR <> 0 
					PRINT 'Error in creating procedure ' + @SP_NAME + '.'  
				ELSE
					PRINT @SP_NAME + ' created successfully.'  
			END
			ELSE
				PRINT 'SP ' + @SP_NAME + ' now found in ' +REPLACE(@OLD_CLIENT_ID,']','') + ' .'   

	

	FETCH NEXT
	FROM @getSPID INTO @SP_NAME
	END
	CLOSE @getSPID
	DEALLOCATE @getSPID
END
	


;




