CREATE PROCEDURE [dbo].[DATA_RETURN_BASIC_CATEGORIES]
AS

BEGIN
	SELECT ATTRIBUTE_001 FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2544 AND DELETED='N'
	AND ATTRIBUTE_003='Y' AND ISNULL(ATTRIBUTE_025,'N')='Y'
END


;





CREATE PROCEDURE [dbo].[DELETE_CONTACT_EMAIL_FROM_PIVOT]
	-- Add the parameters for the stored procedure here
	@Email_Address NVARCHAR(MAX)
AS
BEGIN

--Delete API_Contact_Registration records
UPDATE [SRM-CustomEntities]..CUS_ENTITY_DATA SET
DELETED = 'Y',
DATE_DELETED = GETDATE(),
DELETED_BY = 'EI'
WHERE
--SEQ_ID = @Api_Seq_ID
SEQ_ID IN 
(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_77]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 544570 AND ATTRIBUTE_STRING = @Email_Address)


--Delete unique index
DELETE FROM [SRM-DataPivot_77]..CUS_PIVOT_UNIQUE_INDEXES WHERE UNIQUE_INDEX_ID = 84 AND ATTRIBUTE_STRING = @Email_Address
end


;





CREATE PROCEDURE [dbo].[DELETE_INVALID_DATA_FROM_PIVOT_UNIQUE_INDEX]
AS

DECLARE @SRM_CLIENTS_SEQ_ID NVARCHAR(10)
DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_SEQ_ID NVARCHAR(10)
DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID NVARCHAR(10)
DECLARE @UNIQUE_INDEX_ID NVARCHAR(10)
DECLARE @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID NVARCHAR(10)
DECLARE @PIVOT_DATABASENAME NVARCHAR(100)
DECLARE @SQL NVARCHAR(4000)

DECLARE curGeneral CURSOR LOCAL STATIC FOR 
SELECT TOP 100 SCER.SRM_CLIENTS_SEQ_ID, SCER.SRM_CLIENT_ENTITIES_SEQ_ID, SCER.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, SCER.UNIQUE_INDEX_ID,
SCEA.SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID
FROM dbo.SRM_CLIENT_ENTITY_RULES AS SCER 
INNER JOIN dbo.SRM_CLIENTS AS SC ON SCER.SRM_CLIENTS_SEQ_ID = sc.SEQ_ID AND sc.DELETED='N'
INNER JOIN dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA ON SCER.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SCEA.SEQ_ID
WHERE SCER.RULE_TYPE_ID=4 AND SCER.SRM_CLIENT_ENTITIES_SEQ_ID IS NOT NULL AND SCER.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IS NOT NULL 
AND SCER.UNIQUE_INDEX_ID IS NOT NULL AND SCER.UNIQUE_INDEX_ID > 0 --AND SC.SEQ_ID=52 

   
OPEN curGeneral                                                             
FETCH NEXT FROM curGeneral INTO @SRM_CLIENTS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @UNIQUE_INDEX_ID, @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID

WHILE (@@Fetch_Status = 0)       
BEGIN
	PRINT @SRM_CLIENT_ENTITIES_SEQ_ID_SEQ_ID
	SELECT @PIVOT_DATABASENAME = [dbo].[GetClientPivotdatabase](@SRM_CLIENTS_SEQ_ID)

	SET @SQL = 'DELETE FROM ' + @PIVOT_DATABASENAME + '.dbo.CUS_PIVOT_UNIQUE_INDEXES WHERE SEQ_ID IN (
	SELECT SEQ_ID FROM ' + @PIVOT_DATABASENAME + '.dbo.CUS_PIVOT_UNIQUE_INDEXES AS CPUI WHERE 
	CPUI.SRM_CLIENTS_SEQ_ID= ' + @SRM_CLIENTS_SEQ_ID  + ' AND UNIQUE_INDEX_ID=' + @UNIQUE_INDEX_ID + ' AND ATTRIBUTE_STRING IS NOT NULL 
	AND ISNULL(ATTRIBUTE_STRING, '''') NOT IN (
	SELECT ISNULL(ATTRIBUTE_STRING, '''') FROM ' + @PIVOT_DATABASENAME + '.dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WHERE 
	SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=' + @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID + ')) '

	--PRINT @SQL
	EXEC (@SQL)

	FETCH NEXT FROM curGeneral INTO @SRM_CLIENTS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @UNIQUE_INDEX_ID, @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID    
END    
   
CLOSE curGeneral                           
DEALLOCATE curGeneral  




;




-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <18 Feb 2022>
-- Description:	<To delete unwanted record from reporting audit>
-- =============================================
CREATE PROCEDURE [dbo].[DELETE_UNWANTED_RECORDS_FROM_REPORTING_AUDIT] 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @FIRST_TIME CHAR(1)
	
	SET @FIRST_TIME = 'Y'
	
	WHILE (@FIRST_TIME = 'Y' OR @@ROWCOUNT > 0)
	BEGIN
		SET @FIRST_TIME = 'N'
		DELETE FROM [SRM-ReportingAudit].dbo.SRM_DATA_SYNCRONISATION_AUDITS
		WHERE SEQ_ID IN (SELECT TOP 50000 SEQ_ID FROM [SRM-ReportingAudit].dbo.SRM_DATA_SYNCRONISATION_AUDITS WITH (NOLOCK)
					WHERE (ACTION_TYPE_ID in (2, 3) and DATA_STATUS_ID = 3))	
	END
END



;





CREATE PROC [dbo].[DESIGNTECHNOLOGY_JOB_SET_TOTAL_BOOKING_FOR_EVENT_SESSION]
AS
BEGIN TRY
	DROP TABLE #TEMP
END TRY
BEGIN CATCH
	DECLARE @X BIT
END CATCH

SELECT EVE_SESSION.ATTRIBUTE_001 SESSION_ID, 
	   EVE_SESSION.SEQ_ID SESSION_SEQ_ID,
	   EVE_SESSION.ATTRIBUTE_015 TOTAL_BOOKINGS,
	   SUM(CAST(ISNULL(SESSION_REG.ATTRIBUTE_008,0) AS BIGINT)) SESSION_REGISTRATION_COUNT
INTO #TEMP
FROM [SRM-CUSTOMENTITIES]..CUS_ENTITY_DATA EVE_SESSION WITH(NOLOCK) 
INNER JOIN  [SRM-CUSTOMENTITIES]..CUS_ENTITY_DATA SESSION_REG WITH(NOLOCK) ON SESSION_REG.SRM_CLIENT_ENTITIES_SEQ_ID = 2654 AND SESSION_REG.ATTRIBUTE_002=EVE_SESSION.SEQ_ID AND ISNULL(SESSION_REG.DELETED,'N')='N'
WHERE EVE_SESSION.SRM_CLIENT_ENTITIES_SEQ_ID=2646
--AND EVE_SESSION.ATTRIBUTE_001='D2AM3'
AND ISNULL(EVE_SESSION.DELETED,'N')='N'
GROUP BY EVE_SESSION.ATTRIBUTE_001,EVE_SESSION.SEQ_ID , EVE_SESSION.ATTRIBUTE_015
HAVING ISNULL(EVE_SESSION.ATTRIBUTE_015,0)>SUM(CAST(ISNULL(SESSION_REG.ATTRIBUTE_008,0) AS BIGINT))
ORDER BY EVE_SESSION.ATTRIBUTE_015

IF (SELECT COUNT(*) FROM #TEMP)>0
BEGIN
			UPDATE EVE_SESSION SET 

			EVE_SESSION.ATTRIBUTE_015 = (SELECT SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT)) 
										  FROM [SRM-CUSTOMENTITIES]..CUS_ENTITY_DATA 
										  WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2654 
										  AND ATTRIBUTE_002=EVE_SESSION.SEQ_ID 
										  AND ISNULL(DELETED,'N')='N'
										  AND ATTRIBUTE_005='CONFIRMED'
										 )

			FROM [SRM-CUSTOMENTITIES]..CUS_ENTITY_DATA EVE_SESSION WITH(NOLOCK) 
			WHERE EVE_SESSION.SRM_CLIENT_ENTITIES_SEQ_ID=2646
			AND ISNULL(EVE_SESSION.DELETED,'N')='N'
			AND EVE_SESSION.SEQ_ID IN(SELECT SESSION_SEQ_ID FROM #TEMP)
			

			UPDATE EVE_SESSION SET 

			ATTRIBUTE_016=CAST(ATTRIBUTE_014 AS BIGINT)- CAST(ATTRIBUTE_015 AS BIGINT)

			FROM [SRM-CUSTOMENTITIES]..CUS_ENTITY_DATA EVE_SESSION WITH(NOLOCK) 
			WHERE EVE_SESSION.SRM_CLIENT_ENTITIES_SEQ_ID=2646
			AND ISNULL(EVE_SESSION.DELETED,'N')='N'
			AND EVE_SESSION.SEQ_ID IN(SELECT SESSION_SEQ_ID FROM #TEMP)


			  DECLARE 
			   @CLIENT_SEQ_ID BIGINT      
			  ,@EVENT_SEQ_ID BIGINT     
			  ,@CUS_ENTITY_DATA_SEQ_ID BIGINT     
			  ,@ERR SMALLINT      
			  ,@ERR_DESC NVARCHAR(200)    


			DECLARE CUR  CURSOR STATIC LOCAL FOR   
			SELECT SEQ_ID, ATTRIBUTE_002 FROM [SRM-CUSTOMENTITIES]..CUS_ENTITY_DATA EVE_SESSION WITH(NOLOCK) 
			WHERE EVE_SESSION.SRM_CLIENT_ENTITIES_SEQ_ID=2646
			AND ISNULL(EVE_SESSION.DELETED,'N')='N'
			AND EVE_SESSION.SEQ_ID IN(SELECT SESSION_SEQ_ID FROM #TEMP)


			 OPEN CUR  
			 FETCH NEXT FROM CUR INTO @CUS_ENTITY_DATA_SEQ_ID, @EVENT_SEQ_ID
 
			 WHILE @@FETCH_STATUS = 0  
			 BEGIN  

			  EXEC [SRM-FRAMEWORK_NEW].[DBO].[GET_APPLY_EVENT_SESSIONS_DATA_TO_API]
			  @M_CLIENT_SEQ_ID =17,      
			  @M_EVENT_SEQ_ID = @EVENT_SEQ_ID,      
			  @M_CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,      
			  @ERROR  = @ERR OUTPUT,      
			  @ERROR_DESCRIPTION = @ERR_DESC OUTPUT
  
				EXEC [SRM-FRAMEWORK_NEW].[DBO].[GET_POPULATE_PIVOT_TABLE]
				-- ADD THE PARAMETERS FOR THE STORED PROCEDURE HERE
				@SRM_CLIENT_ENTITIES_SEQ_ID = 2646,
				@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
				@SRM_CLIENTS_SEQ_ID = 17

			  FETCH NEXT FROM CUR INTO @CUS_ENTITY_DATA_SEQ_ID, @EVENT_SEQ_ID
			  END    

			 CLOSE CUR  
			 DEALLOCATE CUR   


			 BEGIN TRY 
					 SELECT 
							IDENTITY(BIGINT, 1,1) AS SEQ_ID ,
							CAST(SESSION_ID AS BIGINT) AS SESSION_ID, 
							SESSION_SEQ_ID,
							CAST(TOTAL_BOOKINGS AS INT) AS TOTAL_BOOKINGS,
							SESSION_REGISTRATION_COUNT,
							GETDATE() AS DATE_CREATED
					 INTO [SRM-oomiTemp].DBO.DESIGNTECHNOLOGY_JOB_SET_TOTAL_BOOKING_FOR_EVENT_SESSION
					 FROM #TEMP
			END TRY
			BEGIN CATCH
						INSERT INTO [SRM-oomiTemp].DBO.DESIGNTECHNOLOGY_JOB_SET_TOTAL_BOOKING_FOR_EVENT_SESSION (SESSION_ID,SESSION_SEQ_ID,TOTAL_BOOKINGS,SESSION_REGISTRATION_COUNT,DATE_CREATED)
						SELECT SESSION_ID,SESSION_SEQ_ID,TOTAL_BOOKINGS,SESSION_REGISTRATION_COUNT,GETDATE()
						FROM #TEMP
			END CATCH

END



;


CREATE function [dbo].[DataType](@DataType as varchar(100))
returns bigint
as
begin
	declare @Ret bigint;
 
	if @DataType = 'bigint'
		set @Ret = 8
	else if @DataType = 'nvarchar'
		set @Ret = 13
	else if @DataType = 'char'
		set @Ret = 13
	else if @DataType = 'datetime'
		set @Ret = 6
	else if @DataType = 'date'
		set @Ret = 5
	else if @DataType = 'int'
		set @Ret = 8		
	else if @DataType = 'nchar'
		set @Ret = 13	
	else if @DataType = 'smallint'
		set @Ret = 8
	else if @DataType = 'varbinary'
		set @Ret = 15
	else
		set @Ret = 13
			
   return @Ret
end
;






