				update [SRM-CustomEntities].dbo.CUS_ENTITY_DATA
				set DELETED = 'Y',DATE_MODIFIED=@TODAY, SOURCE_OF_DATA=SEQ_ID
				where SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_MARKETING_SOURCE_API and ltrim(rtrim(ATTRIBUTE_001))=@Des 
			else if(@Web = 'Y')
				update [SRM-CustomEntities].dbo.CUS_ENTITY_DATA
				set DELETED = 'N',DATE_MODIFIED=@TODAY, SOURCE_OF_DATA=SEQ_ID
				where SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_MARKETING_SOURCE_API and ltrim(rtrim(ATTRIBUTE_001))=@Des


		end
		else
		begin
			if(@Web = 'Y')
				insert [SRM-CustomEntities].dbo.CUS_ENTITY_DATA (ATTRIBUTE_001,SRM_CLIENT_ENTITIES_SEQ_ID,SRM_CLIENTS_SEQ_ID,DATE_CREATED)
				values(@Des,@SRM_CLIENT_ENTITIES_SEQ_ID_MARKETING_SOURCE_API, @SRM_CLIENTS_SEQ_ID,@TODAY)

		end


		FETCH NEXT FROM CUR_RECORDS INTO @Des,@Del,@Web
end

	CLOSE CUR_RECORDS
	DEALLOCATE CUR_RECORDS

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
	end






;






-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
--  exec [dbo].[EXPORT_TITLE_DATA_TO_API]  16
-- =============================================
CREATE PROCEDURE [dbo].[EXPORT_TITLE_DATA_TO_API] 
	-- Add the parameters for the stored procedure here
	@m_CLIENT_SEQ_ID BIGINT,
	 @m_CUS_ENTITY_DATA_SEQ_ID BIGINT = null,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN


	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	
	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)
	
	DECLARE @TITLE NVARCHAR(200)
	DECLARE @Des NVARCHAR(200)
	DECLARE @Del NVARCHAR(200)
	DECLARE @Web NVARCHAR(200)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_TITLE_API BIGINT
	set @SRM_CLIENT_ENTITIES_SEQ_ID_TITLE_API = 6820
	
	DECLARE @SRM_CLIENTS_SEQ_ID int
	set @SRM_CLIENTS_SEQ_ID =16
	
	
	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_EVENT_DATA_TO_API]'

    -- Insert statements for procedure here
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID  
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'TITLE'
	
	--print @SRM_CLIENT_ENTITIES_SEQ_ID
	
	
	DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR 
	
	select ltrim(rtrim(ATTRIBUTE_001)), DELETED,ATTRIBUTE_003 from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA where SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID AND ATTRIBUTE_003 = 'Y'
	
	
	OPEN CUR_RECORDS
	FETCH NEXT FROM CUR_RECORDS INTO @Des,@Del,@Web
	
	DELETE FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA where SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_TITLE_API
	
	WHILE @@FETCH_STATUS = 0
	BEGIN

		insert [SRM-CustomEntities].dbo.CUS_ENTITY_DATA (ATTRIBUTE_001,SRM_CLIENT_ENTITIES_SEQ_ID,SRM_CLIENTS_SEQ_ID,DATE_CREATED)
		values(@Des,@SRM_CLIENT_ENTITIES_SEQ_ID_TITLE_API,@SRM_CLIENTS_SEQ_ID,@TODAY)
		

		FETCH NEXT FROM CUR_RECORDS INTO @Des,@Del,@Web
	end

	CLOSE CUR_RECORDS
	DEALLOCATE CUR_RECORDS

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
end






;


create FUNCTION [dbo].[Func_UK_All_PostCode] 
(
	@Radius int,
	@givenPostcode varchar(20)
)
RETURNS @result TABLE
(
	postcode varchar(20),
	distance float
)
AS
BEGIN
declare @lat float
declare @lng float
declare @firstPart varchar(10)
declare @secondPart varchar(10)
declare @correctPostCode varchar(20)

set @firstPart = ltrim(rtrim(dbo.fn_leanUtil_PostCodePart(@givenPostcode,1)));
set @secondPart  = ltrim(rtrim(dbo.fn_leanUtil_PostCodePart(@givenPostcode,2)));
set @correctPostCode = @firstPart + ' ' + @secondPart;

SELECT @lng = longitude, @lat = latitude FROM UK_POSTCODES where postcode = @correctPostCode;


INSERT INTO @result 
--SELECT distinct postcode FROM (
--SELECT id,postcode, latitude, longitude, 
-- ( 3959 * acos( cos( radians(@lat) ) * cos( radians( latitude ) ) * cos( radians( longitude ) - radians(@lng) ) + sin( radians(@lat) ) * sin( radians( latitude ) ) ) ) AS distance 
--FROM UK_POSTCODES) as tblPostcode
--where distance <= @Radius + 1 ; 

SELECT distinct postcode,distance FROM (
SELECT id,postcode, latitude, longitude, 
 ( 3959 * acos(CASE WHEN ABS( cos( radians(convert(float, @lat)) ) * cos( radians( convert(float, latitude) ) ) * cos( radians( convert(float, longitude) ) - radians(convert(float, @lng)) ) + sin( radians(convert(float, @lat)) ) 
 * sin( radians( convert(float, latitude) ) ) ) > 1 THEN SIGN(
 
 cos( radians(convert(float, @lat)) ) * cos( radians( convert(float, latitude) ) ) * cos( radians( convert(float, longitude) ) - radians(convert(float, @lng)) ) + sin( radians(convert(float, @lat)) ) 
 * sin( radians( convert(float, latitude) ) )
 
 
 
 )*1 ELSE 
 
 cos( radians(convert(float, @lat)) ) * cos( radians( convert(float, latitude) ) ) * cos( radians( convert(float, longitude) ) - radians(convert(float, @lng)) ) + sin( radians(convert(float, @lat)) ) 
 * sin( radians( convert(float, latitude) ) )
 
 
 END)
 
 
 
 )  AS distance 
 
FROM UK_POSTCODES
) as tblPostcode
where distance <= @Radius + 1
order by distance asc;   
   
	RETURN 
END
;


CREATE FUNCTION [dbo].[FuzzyMatchString] (@s1 varchar(100), @s2 varchar(100))
RETURNS int
AS
BEGIN
    -- written by William Talada for SqlServerCentral
    DECLARE @i int, @j int;

    SET @i = 1;
    SET @j = 0;

    WHILE @i < LEN(@s1)
    BEGIN
        IF CHARINDEX(SUBSTRING(@s1,@i,2), @s2) > 0 SET @j=@j+1;
        SET @i=@i+1;
    END

    RETURN @j;
END

;




