CREATE PROCEDURE [dbo].[GET_ADD_MISSING_RATES]
AS

BEGIN

	--DECLARE @TABLE TABLE (
	--MEMBER BIGINT,
	--MEMBER_RATE BIGINT
	--)
	--CREATE TABLE DBO.TMP_MEMBERS_WITH_MISSING_RATES (
	--MEMBER BIGINT,
	--MEMBER_RATE BIGINT
	--)
 
	DECLARE @MEMBER BIGINT
	DECLARE @MEMBER_CATEGORY NVARCHAR(200)


	DECLARE curMember CURSOR LOCAL STATIC FOR 
	SELECT SEQ_ID, ATTRIBUTE_013 MEMBER_CATEGORY FROM [srm-customentities].dbo.cus_entity_data M with (nolock) 
	WHERE M.SRM_CLIENT_ENTITIES_SEQ_ID=2541 AND ISNULL(M.DELETED,'N') = 'N' AND ISNULL(M.ATTRIBUTE_031, 'N') = 'N'
	AND M.SEQ_ID NOT IN (SELECT MEMBER FROM DBO.TMP_MEMBERS_WITH_MISSING_RATES)
	AND M.ATTRIBUTE_013 IN (select ATTRIBUTE_004 from [srm-customentities].dbo.cus_entity_data with (nolock) where srm_client_entities_seq_id = 2545 and deleted = 'N' and 
	ATTRIBUTE_002 IN (5208170,4791084,4701484,5176424))
	ORDER BY M.SEQ_ID
   
	OPEN curMember 
	FETCH NEXT FROM curMember INTO @MEMBER, @MEMBER_CATEGORY

	WHILE (@@Fetch_Status = 0)       
	BEGIN        
		
		INSERT INTO [SRM-FRAMEWORK_NEW].DBO.TMP_MEMBERS_WITH_MISSING_RATES
		SELECT @MEMBER, SEQ_ID FROM [srm-customentities].dbo.cus_entity_data with (nolock) where srm_client_entities_seq_id = 2545 and deleted = 'N' AND
		ATTRIBUTE_004 = @MEMBER_CATEGORY AND ATTRIBUTE_002 IN (5208170,4791084,4701484,5176424) AND
		ATTRIBUTE_002 NOT IN (SELECT ATTRIBUTE_008 FROM [srm-customentities].dbo.cus_entity_data with (nolock) where srm_client_entities_seq_id = 2547 AND DELETED = 'N'
		AND ATTRIBUTE_002 = @MEMBER)
		

		FETCH NEXT FROM curMember INTO @MEMBER, @MEMBER_CATEGORY
	END    
   
	CLOSE curMember                           
	DEALLOCATE curMember  

END

--SELECT * FROM [SRM-FRAMEWORK_NEW].DBO.TMP_MEMBERS_WITH_MISSING_RATES TEMP

SELECT M.ATTRIBUTE_001 MEMBER_ID, 
MR.ATTRIBUTE_003 RATE_TYPE_NAME,MR.ATTRIBUTE_005 MEMBER_CATEGORY_NAME,MR.ATTRIBUTE_007 RATE_AMOUNT
FROM [SRM-FRAMEWORK_NEW].DBO.TMP_MEMBERS_WITH_MISSING_RATES TEMP
INNER JOIN [srm-customentities].dbo.cus_entity_data M with (nolock) ON M.SRM_CLIENT_ENTITIES_SEQ_ID=2541 AND TEMP.MEMBER = M.SEQ_ID
INNER JOIN [srm-customentities].dbo.cus_entity_data MR with (nolock) ON MR.SRM_CLIENT_ENTITIES_SEQ_ID=2545 AND TEMP.MEMBER_RATE = MR.SEQ_ID



;





