CREATE PROCEDURE [dbo].[GET_APPLY_ADDITIONAL_SUBSCRIPTIONS]
@m_RENEWAL_DATE DATETIME
AS



DECLARE @MEMBER_SEQ_ID BigInt
DECLARE @MEMBER_NAME NVARCHAR(100)
DECLARE @RATE_TYPE_SEQ_ID BigInt
DECLARE @RATE_TYPE_NAME NVARCHAR(100)
DECLARE @TOTAL_RATE_AMOUNT Money
DECLARE @RATE_AMOUNT Money
DECLARE @QTY Decimal
DECLARE @CURRENT_DATE NVARCHAR(25)
DECLARE @NEW_SEQ_ID Bigint
DECLARE @NEXT_RENEWAL_DATE DateTime
DECLARE @JOIN_DATE DateTime
DECLARE @STARING_FISCAL_PERIOD NVARCHAR(6)
DECLARE @ENDING_FISCAL_PERIOD NVARCHAR(6)
DECLARE @FISCAL_PERIOD NVARCHAR(7)
DECLARE @FISCAL_PERIOD_LZ NVARCHAR(7)
DECLARE @MODIFIED_BY NVARCHAR(100)
DECLARE @NUMBER_OF_MONTHS BIGINT


-- BEGIN TRAN

/*SET @CURRENT_DATE = CONVERT(nvarchar(25), GETDATE(), 121)
SET @NEXT_RENEWAL_DATE = DATEADD(YEAR, 1, @m_RENEWAL_DATE)
SET @JOIN_DATE = DATEADD(MONTH, -1, @m_RENEWAL_DATE)
SET @STARING_FISCAL_PERIOD = CAST(YEAR(@JOIN_DATE) - 1 AS NVARCHAR(4)) + RIGHT('0' + CAST(MONTH(@JOIN_DATE) AS NVARCHAR(2)), 2)
SET @ENDING_FISCAL_PERIOD = CAST(YEAR(@JOIN_DATE) AS NVARCHAR(4)) + RIGHT('0' + CAST(MONTH(@JOIN_DATE) AS NVARCHAR(2)), 2)

SET @FISCAL_PERIOD = CAST(MONTH(@m_RENEWAL_DATE) AS NVARCHAR(2)) + '/' + CAST(YEAR(@m_RENEWAL_DATE) AS NVARCHAR(4))
SET @FISCAL_PERIOD_LZ = RIGHT('0' + CAST(MONTH(@m_RENEWAL_DATE) AS NVARCHAR(2)), 2) + '/' + CAST(YEAR(@m_RENEWAL_DATE) AS NVARCHAR(4))*/

--CHANGES MADE BY NJ AS PART OF OSDCCR-527
SET @CURRENT_DATE = CONVERT(nvarchar(25), GETDATE(), 121)
--SET @NEXT_RENEWAL_DATE = DATEADD(YEAR, 1, @m_RENEWAL_DATE)
SET @JOIN_DATE = DATEADD(MONTH, -1, @m_RENEWAL_DATE)

--SET @STARING_FISCAL_PERIOD = CAST(YEAR(@JOIN_DATE) - 1 AS NVARCHAR(4)) + RIGHT('0' + CAST(MONTH(@JOIN_DATE) AS NVARCHAR(2)), 2)
--SET @ENDING_FISCAL_PERIOD = CAST(YEAR(@JOIN_DATE) AS NVARCHAR(4)) + RIGHT('0' + CAST(MONTH(@JOIN_DATE) AS NVARCHAR(2)), 2)

SET @FISCAL_PERIOD = CAST(MONTH(@m_RENEWAL_DATE) AS NVARCHAR(2)) + '/' + CAST(YEAR(@m_RENEWAL_DATE) AS NVARCHAR(4))
SET @FISCAL_PERIOD_LZ = RIGHT('0' + CAST(MONTH(@m_RENEWAL_DATE) AS NVARCHAR(2)), 2) + '/' + CAST(YEAR(@m_RENEWAL_DATE) AS NVARCHAR(4))

PRINT @CURRENT_DATE
PRINT @NEXT_RENEWAL_DATE
PRINT @JOIN_DATE
PRINT @STARING_FISCAL_PERIOD
PRINT @ENDING_FISCAL_PERIOD
PRINT @FISCAL_PERIOD
PRINT @FISCAL_PERIOD_LZ


PRINT '***********'

--***********************OUTER CURSOR FOR MEMBERS (START) ***********************
DECLARE curMembersRenewal_sp_Get_Apply_Additional_Subscriptions CURSOR FOR

/*SELECT SEQ_ID, ATTRIBUTE_001, @MODIFIED_BY 
FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)
WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2541 
AND CAST(ATTRIBUTE_005 AS DATE) = @NEXT_RENEWAL_DATE 
AND ISNULL(ATTRIBUTE_031, 'N') = 'N' 
AND CAST(ATTRIBUTE_002 AS DATE) < @JOIN_DATE
--AND SEQ_ID = 7212642 -- FOR TESTING ONLY  */

SELECT SEQ_ID, ATTRIBUTE_001,ATTRIBUTE_077, MODIFIED_BY 
FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)
WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2541  
AND CAST(ATTRIBUTE_070 AS DATE) = @m_RENEWAL_DATE 
AND ISNULL(ATTRIBUTE_031, 'N') = 'N' 
AND CAST(ATTRIBUTE_002 AS DATE) < @JOIN_DATE

OPEN curMembersRenewal_sp_Get_Apply_Additional_Subscriptions

FETCH NEXT FROM curMembersRenewal_sp_Get_Apply_Additional_Subscriptions INTO @MEMBER_SEQ_ID, @MEMBER_NAME , @NUMBER_OF_MONTHS, @MODIFIED_BY

WHILE (@@FETCH_STATUS = 0)
BEGIN
	PRINT @MEMBER_SEQ_ID
	PRINT @MEMBER_NAME

--***********************INNER CURSOR FOR NON MSUB RATES (START) ***********************

--CHANGES MADE BY NJ AS PART OF OSDCCR-527 START

SET @STARING_FISCAL_PERIOD=CAST(YEAR(DATEADD(MONTH,-@NUMBER_OF_MONTHS,@m_RENEWAL_DATE)) AS NVARCHAR(4))+RIGHT('0'+CAST(MONTH(DATEADD(MONTH,-@NUMBER_OF_MONTHS,@m_RENEWAL_DATE)) AS NVARCHAR(2)),2)
SET @ENDING_FISCAL_PERIOD=CAST(YEAR(DATEADD(MONTH,-@NUMBER_OF_MONTHS,@m_RENEWAL_DATE))+1 AS NVARCHAR(4))+RIGHT('0'+CAST(MONTH(DATEADD(MONTH,-@NUMBER_OF_MONTHS,@m_RENEWAL_DATE)) AS NVARCHAR(2)),2)

--CHANGES MADE BY NJ AS PART OF OSDCCR-527 END

	DECLARE curRatesRenewal_sp_Get_Apply_Additional_Subscriptions CURSOR LOCAL FOR
	SELECT 
			MEMBER_ASSIGNED_RATE.ATTRIBUTE_008
		  , MEMBER_ASSIGNED_RATE.ATTRIBUTE_009
		  , SUM(CAST(ISNULL(MEMBER_ASSIGNED_RATE.ATTRIBUTE_014, 1) AS Decimal))

	FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA MEMBER_ASSIGNED_RATE WITH(NOLOCK)
	INNER JOIN [SRM-CustomEntities].dbo.CUS_ENTITY_DATA MEMBER_RATE_TYPE WITH(NOLOCK) ON MEMBER_ASSIGNED_RATE.ATTRIBUTE_008 = MEMBER_RATE_TYPE.SEQ_ID
	WHERE MEMBER_ASSIGNED_RATE.SRM_CLIENT_ENTITIES_SEQ_ID = 2547
	AND ISNULL(MEMBER_ASSIGNED_RATE.DELETED, 'N') = 'N'
	AND MEMBER_ASSIGNED_RATE.ATTRIBUTE_002 = @MEMBER_SEQ_ID
	AND ISNULL(MEMBER_ASSIGNED_RATE.ATTRIBUTE_020, 'N') = 'N'
	AND CAST(ISNULL(MEMBER_ASSIGNED_RATE.ATTRIBUTE_007, 0.00) AS Decimal) > 0.00
	AND ISNULL(MEMBER_RATE_TYPE.ATTRIBUTE_008, 'N') = 'N' 
	AND RIGHT(ISNULL(MEMBER_ASSIGNED_RATE.ATTRIBUTE_004, '00/0000'), 4) + LEFT(RIGHT('0' + ISNULL(MEMBER_ASSIGNED_RATE.ATTRIBUTE_004, '00/0000'), 7), 2) BETWEEN @STARING_FISCAL_PERIOD AND @ENDING_FISCAL_PERIOD
	AND NOT EXISTS (SELECT SEQ_ID 
					FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)
					WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2547 
					AND ISNULL(DELETED, 'N') = 'N'
					AND ATTRIBUTE_002 = MEMBER_ASSIGNED_RATE.ATTRIBUTE_002 
					AND CAST(ISNULL(ATTRIBUTE_007, 0.00) AS Decimal) > 0.00
					AND ATTRIBUTE_008 = MEMBER_ASSIGNED_RATE.ATTRIBUTE_008 
					AND ATTRIBUTE_004 IN (@FISCAL_PERIOD, @FISCAL_PERIOD_LZ)
					)
	GROUP BY MEMBER_ASSIGNED_RATE.ATTRIBUTE_008, MEMBER_ASSIGNED_RATE.ATTRIBUTE_009
		
	OPEN curRatesRenewal_sp_Get_Apply_Additional_Subscriptions
	
	FETCH NEXT FROM curRatesRenewal_sp_Get_Apply_Additional_Subscriptions INTO @RATE_TYPE_SEQ_ID, @RATE_TYPE_NAME, @QTY
	
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		SET @RATE_AMOUNT = 0
		
		SELECT @RATE_AMOUNT = ATTRIBUTE_007
		FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA MEMBER_RATE
		WHERE MEMBER_RATE.SRM_CLIENT_ENTITIES_SEQ_ID = 2545 AND ATTRIBUTE_002 = @RATE_TYPE_SEQ_ID AND ISNULL(ATTRIBUTE_004, 0) = 0
		
		IF @RATE_AMOUNT = 0 
			PRINT CAST(@RATE_TYPE_SEQ_ID AS NVARCHAR(100)) + '....Rate not found'
		ELSE
		BEGIN
			PRINT CAST(@RATE_TYPE_SEQ_ID AS NVARCHAR(100)) + '....Rate found'
			PRINT 'APPLYING RATE FOR MEMBER ' + CAST(@MEMBER_SEQ_ID AS NVARCHAR)
			SET @RATE_AMOUNT = ROUND(@RATE_AMOUNT, 2)
			SET @TOTAL_RATE_AMOUNT = @RATE_AMOUNT * @QTY

--***********************ADDING MEMBER ASSIGNED RATE FOR EACH RATE TYPE***********************			
			INSERT INTO [SRM-CustomEntities].dbo.CUS_ENTITY_DATA (
			SRM_CLIENT_ENTITIES_SEQ_ID,		
			ATTRIBUTE_001,	--RATE_NAME
			SRM_CLIENTS_SEQ_ID, --CLIENT_ID
			DATE_CREATED, --DATE_CREATED
			CREATED_BY, --CREATED_BY
			ATTRIBUTE_002, --MEMBER_ID
			ATTRIBUTE_003, --MEMBER_ID_NAME
			ATTRIBUTE_004, --FISCAL_PERIOD
			ATTRIBUTE_005, --NET_AMOUNT
			ATTRIBUTE_006, --VAT_AMOUNT
			ATTRIBUTE_007, --GROSS_AMOUNT
			ATTRIBUTE_008, --RATE_TYPE
			ATTRIBUTE_009, --RATE_TYPE_NAME
			ATTRIBUTE_010, --TOTAL_OUTSTANDING
			ATTRIBUTE_011, --RATE_AMOUNT
			ATTRIBUTE_012, --DISCOUNT
			ATTRIBUTE_013, --SURCHARGE
			ATTRIBUTE_014, --QUANTITY
			ATTRIBUTE_015, --VAT_PERCENTAGE
			ATTRIBUTE_016, --ACTUAL_RATE_AMOUNT
			ATTRIBUTE_017, --NEXT_RENEWAL_DATE
			ATTRIBUTE_018, --PAYMENT_METHOD
			ATTRIBUTE_019, --PAYMENT_METHOD_DESCRIPTION
			ATTRIBUTE_020, --DO_NOT_RENEW
			ATTRIBUTE_021, --VAT_RATE
			ATTRIBUTE_022)  --VAT_RATE_NAME
			VALUES (
			2547,
			@RATE_TYPE_NAME,			
			17,
			@CURRENT_DATE,
			@MODIFIED_BY,
			@MEMBER_SEQ_ID, 
			@MEMBER_NAME,
			@FISCAL_PERIOD_LZ,
			@TOTAL_RATE_AMOUNT,
			0,
			@TOTAL_RATE_AMOUNT,
			@RATE_TYPE_SEQ_ID, 
			@RATE_TYPE_NAME, 
			@TOTAL_RATE_AMOUNT,
			@RATE_AMOUNT,
			0,
			0,
			@QTY,
			0,
			@RATE_AMOUNT,
			NULL,
			NULL,
			NULL,
			'N',
			0,
			NULL)
			
			SET @New_SEQ_ID = SCOPE_IDENTITY()
			
			EXEC [SRM-Framework_New].[dbo].[GET_POPULATE_PIVOT_TABLE]
			-- Add the parameters for the stored procedure here
			@SRM_CLIENT_ENTITIES_SEQ_ID = 2547,
			@CUS_ENTITY_DATA_SEQ_ID = @New_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = 17

--***********************ADDING MEMBER LEDGER FOR ADDED RATE***********************		
			INSERT INTO [SRM-CustomEntities].dbo.CUS_ENTITY_DATA (
			SRM_CLIENT_ENTITIES_SEQ_ID,		
			ATTRIBUTE_001, --REMARKS
			SRM_CLIENTS_SEQ_ID, --CLIENT_ID
			DATE_CREATED, --DATE_CREATED
			CREATED_BY, --CREATED_BY
			ATTRIBUTE_002, --TRANSACTION_TYPE
			ATTRIBUTE_003, --RATE_TYPE
			ATTRIBUTE_004, --FISCAL_PERIOD
			ATTRIBUTE_005, --TRANSACTION_DATE
			ATTRIBUTE_006, --TRANSACTION_METHOD
			ATTRIBUTE_007, --DEBIT_AMOUNT
			ATTRIBUTE_008, --CREDIT_AMOUNT
			ATTRIBUTE_009, --BATCH_ID
			ATTRIBUTE_010, --MEMBER
			ATTRIBUTE_011 --MEMBER_NAME
			)
			VALUES 
			(
			2579,						
			NULL,
			17,
			@CURRENT_DATE,
			@MODIFIED_BY,
			'New',
			@RATE_TYPE_NAME,
			@FISCAL_PERIOD_LZ,
			@CURRENT_DATE,
			NULL,
			@TOTAL_RATE_AMOUNT,
			'0.00',
			NULL,
			@MEMBER_SEQ_ID, 
			@MEMBER_NAME)
			
			SET @New_SEQ_ID = SCOPE_IDENTITY()
			
			EXEC [SRM-Framework_New].[dbo].[GET_POPULATE_PIVOT_TABLE]
			-- Add the parameters for the stored procedure here
			@SRM_CLIENT_ENTITIES_SEQ_ID = 2579,
			@CUS_ENTITY_DATA_SEQ_ID = @New_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = 17
			
--***********************UPDATING TOTAL RATE AMOUNT ON MEMBERS***********************	
			UPDATE [SRM-CustomEntities].dbo.CUS_ENTITY_DATA
			SET ATTRIBUTE_028 = ROUND(CAST(ISNULL(ATTRIBUTE_028, 0.00) AS Money) + @TOTAL_RATE_AMOUNT, 2),
			MODIFIED_BY = @MODIFIED_BY,
			DATE_MODIFIED = @CURRENT_DATE
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2541 AND SEQ_ID = @MEMBER_SEQ_ID
			
			EXEC [SRM-Framework_New].[dbo].[GET_POPULATE_PIVOT_TABLE]
			-- Add the parameters for the stored procedure here
			@SRM_CLIENT_ENTITIES_SEQ_ID = 2541,
			@CUS_ENTITY_DATA_SEQ_ID = @MEMBER_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = 17
			
		END

		FETCH NEXT FROM curRatesRenewal_sp_Get_Apply_Additional_Subscriptions INTO @RATE_TYPE_SEQ_ID, @RATE_TYPE_NAME, @QTY
	
	END
	CLOSE curRatesRenewal_sp_Get_Apply_Additional_Subscriptions
	DEALLOCATE curRatesRenewal_sp_Get_Apply_Additional_Subscriptions

--***********************INNER CURSOR FOR NON MSUB RATES (ENDING) ***********************

--***********************INNER CURSOR FOR EXTRA LOGIN RATES (START) ***********************
	PRINT 'BEFORE APPLYING EXTRA LOGIN'


	DECLARE OtherRatesToInclude CURSOR FOR
	SELECT SEQ_ID , Attribute_001 
	FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK) 
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2546   --  RATE TYPE
	AND ISNULL(DELETED,'N')='N'
	AND ISNULL(ATTRIBUTE_006,'N') = 'Y'	--ACTIVE
	AND ( ISNULL(ATTRIBUTE_015,'N') = 'Y'	--EXTRA LOGIN FLAG
		  --OR SEQ_ID IN() RATE TYPE SEQ-ID  -- FOR FUTURE IF ANY ORTHER RATE TO INCLUDE IN RENEWAL
	    )

	OPEN OtherRatesToInclude

	FETCH NEXT FROM OtherRatesToInclude INTO @RATE_TYPE_SEQ_ID , @RATE_TYPE_NAME

	WHILE (@@FETCH_STATUS = 0)
	BEGIN 
			PRINT 'CHECKING EXTRA LOGIN FOR MEMBER ' + CAST(@MEMBER_SEQ_ID AS NVARCHAR)
			PRINT @MEMBER_SEQ_ID
			PRINT @RATE_TYPE_SEQ_ID
			PRINT @FISCAL_PERIOD
			
			IF NOT EXISTS(	SELECT SEQ_ID 
							FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)
							WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2547 
							AND ISNULL(DELETED, 'N') = 'N'
							AND ATTRIBUTE_002 = @MEMBER_SEQ_ID
							AND ATTRIBUTE_008 =@RATE_TYPE_SEQ_ID
							AND ATTRIBUTE_004 IN (@FISCAL_PERIOD, @FISCAL_PERIOD_LZ)
							AND CAST(DATE_CREATED AS DATE)=CAST(GETDATE() AS DATE)
						)
			BEGIN
  
				PRINT 'CHECKING PREVIOUS AMOUNT EXTRA LOGIN FOR MEMBER ' + CAST(@MEMBER_SEQ_ID AS NVARCHAR)

				SET @RATE_AMOUNT = 0

				SELECT @RATE_AMOUNT = ATTRIBUTE_011 , @QTY=ATTRIBUTE_014
				FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)
				WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2547		-- MEMBER RATE
				AND ISNULL(DELETED, 'N') = 'N'
				AND ATTRIBUTE_002 = @MEMBER_SEQ_ID
				AND ATTRIBUTE_008 = @RATE_TYPE_SEQ_ID
				AND RIGHT(ISNULL(ATTRIBUTE_004, '00/0000'), 4) + LEFT(RIGHT('0' + ISNULL(ATTRIBUTE_004, '00/0000'), 7), 2) BETWEEN @STARING_FISCAL_PERIOD AND @ENDING_FISCAL_PERIOD

				--SELECT @RATE_AMOUNT = ATTRIBUTE_017 , @QTY=ATTRIBUTE_014
				--FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)
				--WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2547		-- MEMBER RATE
				--AND ISNULL(DELETED, 'N') = 'N'
				--AND ATTRIBUTE_002 = @RATE_TYPE_SEQ_ID
				--AND ISNULL(ATTRIBUTE_004, 0) = 0

				SET @RATE_AMOUNT = ROUND(@RATE_AMOUNT, 2)
				SET @TOTAL_RATE_AMOUNT = @RATE_AMOUNT * @QTY
				IF ISNULL(@RATE_AMOUNT, 0) > 0
				BEGIN
					PRINT 'APPLYING EXTRA LOGIN FOR MEMBER ' + CAST(@MEMBER_SEQ_ID AS NVARCHAR)
					PRINT @RATE_AMOUNT
					PRINT @TOTAL_RATE_AMOUNT
					PRINT @QTY

					INSERT INTO [SRM-CustomEntities].dbo.CUS_ENTITY_DATA (
					SRM_CLIENT_ENTITIES_SEQ_ID,		
					ATTRIBUTE_001,	--RATE_NAME
					SRM_CLIENTS_SEQ_ID, --CLIENT_ID
					DATE_CREATED, --DATE_CREATED
					CREATED_BY, --CREATED_BY
					ATTRIBUTE_002, --MEMBER_ID
					ATTRIBUTE_003, --MEMBER_ID_NAME
					ATTRIBUTE_004, --FISCAL_PERIOD
					ATTRIBUTE_005, --NET_AMOUNT
					ATTRIBUTE_006, --VAT_AMOUNT
					ATTRIBUTE_007, --GROSS_AMOUNT
					ATTRIBUTE_008, --RATE_TYPE
					ATTRIBUTE_009, --RATE_TYPE_NAME
					ATTRIBUTE_010, --TOTAL_OUTSTANDING
					ATTRIBUTE_011, --RATE_AMOUNT
					ATTRIBUTE_012, --DISCOUNT
					ATTRIBUTE_013, --SURCHARGE
					ATTRIBUTE_014, --QUANTITY
					ATTRIBUTE_015, --VAT_PERCENTAGE
					ATTRIBUTE_016, --ACTUAL_RATE_AMOUNT
					ATTRIBUTE_017, --NEXT_RENEWAL_DATE
					ATTRIBUTE_018, --PAYMENT_METHOD
					ATTRIBUTE_019, --PAYMENT_METHOD_DESCRIPTION
					ATTRIBUTE_020, --DO_NOT_RENEW
					ATTRIBUTE_021, --VAT_RATE
					ATTRIBUTE_022)  --VAT_RATE_NAME
					VALUES (
					2547,
					@RATE_TYPE_NAME,			
					17,
					@CURRENT_DATE,
					@MODIFIED_BY,
					@MEMBER_SEQ_ID, 
					@MEMBER_NAME,
					@FISCAL_PERIOD_LZ,
					@TOTAL_RATE_AMOUNT,
					0,
					@TOTAL_RATE_AMOUNT,
					@RATE_TYPE_SEQ_ID, 
					@RATE_TYPE_NAME, 
					@TOTAL_RATE_AMOUNT,
					@RATE_AMOUNT,
					0,
					0,
					@QTY,
					0,
					@RATE_AMOUNT,
					NULL,
					NULL,
					NULL,
					'N',
					0,
					NULL)
			
					SET @New_SEQ_ID = SCOPE_IDENTITY()
	
					EXEC [SRM-Framework_New].[dbo].[GET_POPULATE_PIVOT_TABLE]
					-- Add the parameters for the stored procedure here
					@SRM_CLIENT_ENTITIES_SEQ_ID = 2547,
					@CUS_ENTITY_DATA_SEQ_ID = @New_SEQ_ID,
					@SRM_CLIENTS_SEQ_ID = 17	 

					UPDATE [SRM-CustomEntities].dbo.CUS_ENTITY_DATA
					SET ATTRIBUTE_028 = ROUND(CAST(ISNULL(ATTRIBUTE_028, 0.00) AS Money) + @TOTAL_RATE_AMOUNT, 2), 
					ATTRIBUTE_044 = CAST(ISNULL(ATTRIBUTE_044,'0') AS BIGINT) + @QTY,
					MODIFIED_BY = @MODIFIED_BY,
					DATE_MODIFIED = @CURRENT_DATE
					WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2541 AND SEQ_ID = @MEMBER_SEQ_ID
			
					EXEC [SRM-Framework_New].[dbo].[GET_POPULATE_PIVOT_TABLE]
					-- Add the parameters for the stored procedure here
					@SRM_CLIENT_ENTITIES_SEQ_ID = 2541,
					@CUS_ENTITY_DATA_SEQ_ID = @MEMBER_SEQ_ID,
					@SRM_CLIENTS_SEQ_ID = 17
					     
				END
			END 

			FETCH NEXT FROM OtherRatesToInclude INTO @RATE_TYPE_SEQ_ID , @RATE_TYPE_NAME
	
		END
		CLOSE OtherRatesToInclude
		DEALLOCATE OtherRatesToInclude	      
--***********************INNER CURSOR FOR EXTRA LOGIN RATES (ENDING) ***********************	 

	FETCH NEXT FROM curMembersRenewal_sp_Get_Apply_Additional_Subscriptions INTO  @MEMBER_SEQ_ID, @MEMBER_NAME , @NUMBER_OF_MONTHS, @MODIFIED_BY

	END
	CLOSE curMembersRenewal_sp_Get_Apply_Additional_Subscriptions
	DEALLOCATE curMembersRenewal_sp_Get_Apply_Additional_Subscriptions
--***********************OUTER CURSOR FOR MEMBERS (ENDING) ***********************
--	COMMIT TRAN





--Internal Testing by MN 
/*
DECLARE @m_RENEWAL_DATE DATETIME
