PRINT 'STARING_FISCAL_PERIOD = ' PRINT  @STARING_FISCAL_PERIOD
PRINT 'ENDING_FISCAL_PERIOD = ' PRINT  @ENDING_FISCAL_PERIOD
PRINT 'FISCAL_PERIOD = ' PRINT  @FISCAL_PERIOD
PRINT 'FISCAL_PERIOD_LZ = ' PRINT  @FISCAL_PERIOD_LZ

SELECT 
			MEMBER_ASSIGNED_RATE.ATTRIBUTE_008
		  , MEMBER_ASSIGNED_RATE.ATTRIBUTE_009
		  , SUM(CAST(ISNULL(MEMBER_ASSIGNED_RATE.ATTRIBUTE_014, 1) AS Decimal))

	FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA MEMBER_ASSIGNED_RATE WITH(NOLOCK)
	INNER JOIN [SRM-CustomEntities].dbo.CUS_ENTITY_DATA MEMBER_RATE_TYPE WITH(NOLOCK) ON MEMBER_ASSIGNED_RATE.ATTRIBUTE_008 = MEMBER_RATE_TYPE.SEQ_ID
	WHERE MEMBER_ASSIGNED_RATE.SRM_CLIENT_ENTITIES_SEQ_ID = 2547
	AND MEMBER_RATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = 2546
	AND ISNULL(MEMBER_ASSIGNED_RATE.DELETED, 'N') = 'N'
	AND MEMBER_ASSIGNED_RATE.ATTRIBUTE_002 = 4800420
	AND ISNULL(MEMBER_ASSIGNED_RATE.ATTRIBUTE_020, 'N') = 'N'
	AND CAST(ISNULL(MEMBER_ASSIGNED_RATE.ATTRIBUTE_007, 0.00) AS Decimal) > 0.00
	AND ISNULL(MEMBER_RATE_TYPE.ATTRIBUTE_008, 'N') = 'N' 
	AND RIGHT(ISNULL(MEMBER_ASSIGNED_RATE.ATTRIBUTE_004, '00/0000'), 4) + LEFT(RIGHT('0' + ISNULL(MEMBER_ASSIGNED_RATE.ATTRIBUTE_004, '00/0000'), 7), 2) BETWEEN @STARING_FISCAL_PERIOD AND @ENDING_FISCAL_PERIOD
	AND NOT EXISTS (SELECT SEQ_ID 
					FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)
					WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2547 
					AND ISNULL(DELETED, 'N') = 'N'
					AND ATTRIBUTE_002 = MEMBER_ASSIGNED_RATE.ATTRIBUTE_002 
					AND CAST(ISNULL(ATTRIBUTE_007, 0.00) AS Decimal) > 0.00
					AND ATTRIBUTE_008 = MEMBER_ASSIGNED_RATE.ATTRIBUTE_008 
					AND ATTRIBUTE_004 IN (@FISCAL_PERIOD, @FISCAL_PERIOD_LZ)
					)
	GROUP BY MEMBER_ASSIGNED_RATE.ATTRIBUTE_008, MEMBER_ASSIGNED_RATE.ATTRIBUTE_009

	SELECT 
	ATTRIBUTE_020,
	RIGHT(ISNULL(ATTRIBUTE_004, '00/0000'), 4),
	LEFT(RIGHT('0' + ISNULL(ATTRIBUTE_004, '00/0000'), 7), 2),
	RIGHT(ISNULL(ATTRIBUTE_004, '00/0000'), 4) + LEFT(RIGHT('0' + ISNULL(ATTRIBUTE_004, '00/0000'), 7), 2),
	*
	FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2547
	AND ATTRIBUTE_002 = 4800420
	AND ISNULL(ATTRIBUTE_020, 'N') = 'N'
	AND ISNULL(DELETED, 'N') = 'N'
	AND ATTRIBUTE_001 IN ('Designing magazine (2 copies)')
	--AND CAST(ISNULL(ATTRIBUTE_007, 0.00) AS Decimal) > 0.00
	AND RIGHT(ISNULL(ATTRIBUTE_004, '00/0000'), 4) + LEFT(RIGHT('0' + ISNULL(ATTRIBUTE_004, '00/0000'), 7), 2) BETWEEN 202010 AND 202210




	SELECT
	*
	FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2544	--MEMBER_CATEGORY
	AND SEQ_ID IN (244732807,4701381)
*/
;





-- Stored Procedure  
  
-- =============================================  
-- Author:  <Adeel Hassan>  
-- Create date: <01/09/2013>  
-- Description: <Apply Event Booking Data to sTarget>  
-- =============================================  
CREATE PROCEDURE [dbo].[GET_APPLY_EVENT_BOOKING_DATA_TO_STARGET]  
 -- Add the parameters for the stored procedure here  
 @WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID BIGINT = NULL,  
 @ERROR SMALLINT = NULL OUTPUT,  
 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT  
AS  
BEGIN  
 -- SET NOCOUNT ON added to prevent extra result sets from  
 -- interfering with SELECT statements.  
 SET NOCOUNT ON;  
  
 SET @ERROR = 1  
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_EVENT_BOOKING_DATA_TO_STARGET]'  
  
 DECLARE @TODAY NVARCHAR(30)  
 SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)  
  
 DECLARE @BOOKING_ID NVARCHAR(100)  
 DECLARE @USER_NAME NVARCHAR(100)  
  
 DECLARE @SRM_CLIENTS_SEQ_ID BIGINT  
 DECLARE @USER NVARCHAR(100)  
 DECLARE @CONTACT_SEQ_ID BIGINT  
 DECLARE @ACCOUNT_SEQ_ID BIGINT  
 DECLARE @EVENT_REGISTRATION_SEQ_ID BIGINT  
 DECLARE @REGISTRATION_ID NVARCHAR(100)  
 DECLARE @INVOICE_TRANSACTION_SEQ_ID BIGINT  
 DECLARE @DELEGATE_CONTACT_SEQ_ID BIGINT  
 DECLARE @DELEGATE_ACCOUNT_SEQ_ID BIGINT  
  
 DECLARE @PIVOT_RETURN_VALUE NVARCHAR(MAX)  
 DECLARE @MODULE BIGINT  
 DECLARE @MODULE_DESCRIPTION NVARCHAR(100)  
 DECLARE @FINANCE_TRANSACTION_SEQ_ID BIGINT  
 DECLARE @PAYMENT_BATCH_TRANSACTION_SEQ_ID BIGINT  
  
 DECLARE @LABEL_NAME NVARCHAR(100)  
 DECLARE @WEB_SERVICE_EVENT_BOOKING_DETAIL_SEQ_ID BIGINT  
  
 -- EVENT REGISTRATION DETAIL  
 DECLARE @DELEGATE_TYPE BIGINT  
 DECLARE @EVENT_ID NVARCHAR(100)  
 DECLARE @PAY_BY_INVOICE NVARCHAR(1)  
 DECLARE @PURCHASE_ORDER_NUMBER NVARCHAR(100)  
 DECLARE @ATTENDING_IN_PERSON NVARCHAR(1)  
 DECLARE @DISCOUNT_CODE NVARCHAR(20)  
 DECLARE @PAYMENT_AMOUNT_NET MONEY  
 DECLARE @PAYMENT_AMOUNT_VAT MONEY  
 
 
 DECLARE @PRIVACY_POLICY_AGREEMENT NVarchar(1) --ATTRIBUTE_068
 DECLARE @PRIVACY_POLICY_AGREEMENT_DATE NVarchar(100) --ATTRIBUTE_069
 DECLARE @TS_CS_AGREEMENT NVarchar(1) --ATTRIBUTE_070
 DECLARE @TS_CS_AGREEMENT_DATE NVarchar(100) --ATTRIBUTE_071
 

 DECLARE @ATTRIBUTE_002_PRODUCT NVARCHAR(200)  
 DECLARE @ATTRIBUTE_005_PRODUCT NVARCHAR(20)  
 DECLARE @ATTRIBUTE_006_PRODUCT NVARCHAR(100)  
 DECLARE @ATTRIBUTE_007_PRODUCT NVARCHAR(20)  
 DECLARE @ATTRIBUTE_008_PRODUCT NVARCHAR(100)  
 --  
  
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM BIGINT  
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBD BIGINT  
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT BIGINT  
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT BIGINT  
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_IT BIGINT  
  
 DECLARE @ENTITY_DISPLAY_NAME_WSEBM NVARCHAR(100)  
 DECLARE @ENTITY_DISPLAY_NAME_WSEBD NVARCHAR(100)  
 DECLARE @ENTITY_DISPLAY_NAME_CONTACT NVARCHAR(100)  
 DECLARE @ENTITY_DISPLAY_NAME_EVENT NVARCHAR(100)  
 DECLARE @ENTITY_DISPLAY_NAME_IT NVARCHAR(100)  
 DECLARE @PAYMENT_AMOUNT MONEY  
 DECLARE @EVENT_SEQ_ID BIGINT  
  
 DECLARE @BOOKER_FIRST_NAME NVARCHAR(200)  
 DECLARE @BOOKER_LAST_NAME NVARCHAR(200)  
 DECLARE @DELEGATE_FIRST_NAME NVARCHAR(200)  
 DECLARE @DELEGATE_LAST_NAME NVARCHAR(200)  
  
 SET @USER = 'WEB'  
  
 SET @SRM_CLIENTS_SEQ_ID = 17  
 SET @ENTITY_DISPLAY_NAME_WSEBM = 'WEB_SERVICE_EVENT_BOOKING_MASTER'  
 SET @ENTITY_DISPLAY_NAME_WSEBD = 'WEB_SERVICE_EVENT_BOOKING_DETAIL'  
 SET @ENTITY_DISPLAY_NAME_CONTACT = 'CONTACT'  
 SET @ENTITY_DISPLAY_NAME_EVENT = 'EVENT'  
 SET @ENTITY_DISPLAY_NAME_IT = 'INVOICE_TRANSACTION'  
  
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSEBM   
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBD = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSEBD  
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_CONTACT  
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EVENT  
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_IT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_IT  
  
 -- GET MODULE  
 EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MODULE', @ATTRIBUTE_DISPLAY_NAME = 'EVENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MODULE OUTPUT, @DESCRIPTION = @MODULE_DESCRIPTION OUTPUT  
  
 SELECT 
     @BOOKING_ID = ATTRIBUTE_035
   , @USER_NAME = ATTRIBUTE_001
   , @PAYMENT_AMOUNT = ATTRIBUTE_017
   , @DELEGATE_TYPE = ATTRIBUTE_016
   , @EVENT_ID = ATTRIBUTE_018
   , @PAY_BY_INVOICE = ATTRIBUTE_032
   , @PURCHASE_ORDER_NUMBER = ATTRIBUTE_033
   , @ATTENDING_IN_PERSON = ATTRIBUTE_034
   , @DISCOUNT_CODE = ATTRIBUTE_037
   , @PAYMENT_AMOUNT_NET = ATTRIBUTE_038
   , @PAYMENT_AMOUNT_VAT = ATTRIBUTE_039
   , @BOOKER_FIRST_NAME = ISNULL(ATTRIBUTE_003,'')
   , @BOOKER_LAST_NAME = ISNULL(ATTRIBUTE_004,'') 

   , @PRIVACY_POLICY_AGREEMENT =CASE WHEN ATTRIBUTE_068 IN ('Y' , 'Yes' , 'True') THEN  'Y' ELSE 'N' END
   , @PRIVACY_POLICY_AGREEMENT_DATE = ATTRIBUTE_069
   , @TS_CS_AGREEMENT =CASE WHEN ATTRIBUTE_070 IN ('Y' , 'Yes' , 'True') THEN  'Y' ELSE 'N' END
   , @TS_CS_AGREEMENT_DATE =ATTRIBUTE_071

 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
 AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM 
 AND SEQ_ID = @WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID  
  
 IF ISNULL(@BOOKING_ID, '') = ''  
 BEGIN  
	SET @ERROR = 0  
	SET @ERROR_DESCRIPTION = 'THIS ORDER CANNOT BE PROCESSED. NO BOOKING ID HAS BEEN PROVIDED'  
	RETURN
 END  
  
 -- UPDATE Net Amount as Gross Amount if Net Amount is zero  
 IF ISNULL(@PAYMENT_AMOUNT_NET,0) = 0  
 BEGIN  
		  UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA   
		  SET ATTRIBUTE_038 = ATTRIBUTE_017  
		  WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		  AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM 
		  AND SEQ_ID = @WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID  
 END  
  
 SET @CONTACT_SEQ_ID = NULL  
 PRINT '@USER_NAME ' + @USER_NAME  
 IF ISNULL(@USER_NAME, '') <> ''   
 BEGIN  
  SET @PIVOT_RETURN_VALUE = NULL  
  
  EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT, @ATTRIBUTE_DISPLAY_NAME = 'LOGIN_USER_NAME', @OPERATOR_ID = 3, @SEARCH_VALUE = @USER_NAME, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT  
  
  IF ISNULL(@PIVOT_RETURN_VALUE, '') <> ''  
  BEGIN  
   SELECT @CONTACT_SEQ_ID = DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ',')  
   PRINT '@CONTACT_SEQ_ID ' + CAST(@CONTACT_SEQ_ID AS NVARCHAR(100))  
  END  
  
 END  
  
 IF ISNULL(@CONTACT_SEQ_ID, 0) = 0 -- CREATE A NEW CONTACT  
 BEGIN  
  EXEC [dbo].[GET_CREATE_ACCOUNT_CONTACT_EVENT_IMPORT]  
   @EXTERNAL_ID = @BOOKING_ID,  
   @USER = @USER,  
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
   @CONTACT = @CONTACT_SEQ_ID OUTPUT,  
   @ACCOUNT = @ACCOUNT_SEQ_ID OUTPUT,  
   @ERROR = @ERROR OUTPUT,  
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
 END  
  
 IF ISNULL(@CONTACT_SEQ_ID, 0) = 0  
 BEGIN  
  PRINT 'ERROR ----- CONTACT NOT FOUND, CANNOT CONTINUE'  
  SET @ERROR = 1  
  SET @ERROR_DESCRIPTION = 'ERROR ----- CONTACT NOT FOUND, CANNOT CONTINUE'  
  RETURN  
 END  
  
 -- GET CONTACT NAME  
 SELECT @LABEL_NAME = ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA   
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID  
  AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT  
  AND SEQ_ID = @CONTACT_SEQ_ID  

  --GDPR MQ 
  IF ISNULL(@CONTACT_SEQ_ID,0)>0
  BEGIN
		UPDATE DATAProtectionFields SET 
		ATTRIBUTE_190 = ISNULL(@PRIVACY_POLICY_AGREEMENT ,DATAProtectionFields.ATTRIBUTE_190)
		,ATTRIBUTE_191 = ISNULL(@PRIVACY_POLICY_AGREEMENT_DATE , DATAProtectionFields.ATTRIBUTE_191)
		,ATTRIBUTE_192 = ISNULL(@TS_CS_AGREEMENT , DATAProtectionFields.ATTRIBUTE_192)
		,ATTRIBUTE_193 = ISNULL(@TS_CS_AGREEMENT_DATE , DATAProtectionFields.ATTRIBUTE_193)
		FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA DATAProtectionFields WITH(NOLOCK)
		WHERE SEQ_ID = @CONTACT_SEQ_ID

		EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT,
		@CUS_ENTITY_DATA_SEQ_ID = @CONTACT_SEQ_ID,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
  END



 -- ADD DATA IN EVENT BOOKING  
 EXEC [dbo].[GET_CREATE_EVENT_REGISTRATION_IMPORT]  
  @WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID = @WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID,  
  @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT,  
  @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM = @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM,  
  @EXTERNAL_ID = @BOOKING_ID,  
  @CONTACT_SEQ_ID = @CONTACT_SEQ_ID,  
  @USER = @USER,  
  @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
  @EVENT_REGISTRATION_SEQ_ID = @EVENT_REGISTRATION_SEQ_ID OUTPUT,    
  @REGISTRATION_ID = @REGISTRATION_ID OUTPUT,  
  @ERROR = @ERROR OUTPUT,  
  @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
  
 -- POPULATE EVENT_REGISTRATION IN WEB_SERVICE_EVENT_BOOKING_MASTER
	UPDATE [SRM-CustomEntities].dbo.CUS_ENTITY_DATA SET ATTRIBUTE_072=@EVENT_REGISTRATION_SEQ_ID,
	ATTRIBUTE_073=@REGISTRATION_ID WHERE SEQ_ID=@WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID
  
 -- **************************************************************************************************************************  
 -- ADD DETAILS FROM WEB_SERVICE_EVENT_BOOKING_DETAIL INTO EVENT_DELEGATE, EVENT_REGISTRATION_CHARGES & INVOICE_TRANSACTION  
 -- **************************************************************************************************************************  
 SET @USER_NAME = NULL  
 SET @PAYMENT_AMOUNT_NET = 0  
  
 DECLARE CUS_ADDITIONAL_DELEGATE CURSOR STATIC LOCAL FOR   
 SELECT  SEQ_ID, ATTRIBUTE_001, ATTRIBUTE_033, ISNULL(ATTRIBUTE_002,''), ISNULL(ATTRIBUTE_003,'') 
 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
 AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBD 
 --AND ATTRIBUTE_027 = @BOOKING_ID
 AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBD AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56716 AND ISNULL(ATTRIBUTE_STRING,'')=@BOOKING_ID)
 
 OPEN CUS_ADDITIONAL_DELEGATE  
 FETCH NEXT FROM CUS_ADDITIONAL_DELEGATE INTO @WEB_SERVICE_EVENT_BOOKING_DETAIL_SEQ_ID, @USER_NAME, @PAYMENT_AMOUNT_NET, @DELEGATE_FIRST_NAME, @DELEGATE_LAST_NAME  
  
 WHILE @@FETCH_STATUS = 0  
 BEGIN  
  PRINT 'IN DELEGATE LOOP ...'  
  
  -- UPDATE Net Amount as Gross Amount if Net Amount is zero  
  IF ISNULL(@PAYMENT_AMOUNT_NET,0) = 0  
  BEGIN  
   UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA   
   SET ATTRIBUTE_033 = ATTRIBUTE_032  
   WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
   AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBD 
   AND SEQ_ID = @WEB_SERVICE_EVENT_BOOKING_DETAIL_SEQ_ID  
  END  
  
  SET @DELEGATE_CONTACT_SEQ_ID = NULL    
  SET @DELEGATE_ACCOUNT_SEQ_ID = 0  
  
  IF ISNULL(@USER_NAME, '') <> ''   
  BEGIN  
   SET @PIVOT_RETURN_VALUE = NULL  
  
   EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT, @ATTRIBUTE_DISPLAY_NAME = 'LOGIN_USER_NAME', @OPERATOR_ID = 3, @SEARCH_VALUE = @USER_NAME, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT  
  
   IF ISNULL(@PIVOT_RETURN_VALUE, '') <> ''  
   BEGIN  
    SELECT @DELEGATE_CONTACT_SEQ_ID = DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ',')  
   END  
  
  END  
  
  -- Check if the Delegate is same as the Booker of this Booking  
  IF LTRIM(RTRIM(@BOOKER_FIRST_NAME)) = LTRIM(RTRIM(@DELEGATE_FIRST_NAME)) AND  LTRIM(RTRIM(@BOOKER_LAST_NAME)) = LTRIM(RTRIM(@DELEGATE_LAST_NAME))  
   SET @DELEGATE_CONTACT_SEQ_ID = @CONTACT_SEQ_ID  
  ELSE IF ISNULL(@DELEGATE_CONTACT_SEQ_ID, 0) = 0 -- CREATE A NEW CONTACT  
  BEGIN  
   EXEC [dbo].[GET_CREATE_ACCOUNT_CONTACT_EVENT_DELEGATE_IMPORT]  
    @EXTERNAL_ID = @BOOKING_ID,  
    @WEB_SERVICE_EVENT_BOOKING_DETAIL_SEQ_ID = @WEB_SERVICE_EVENT_BOOKING_DETAIL_SEQ_ID,  
    @USER = @USER,  
    @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
    @CONTACT = @DELEGATE_CONTACT_SEQ_ID OUTPUT,  
    @ACCOUNT = @DELEGATE_ACCOUNT_SEQ_ID OUTPUT,  
    @ERROR = @ERROR OUTPUT,  
    @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
  END  
  PRINT 'BEFORE DELEGATE ADD'  
  -- ADD DATA IN EVENT DELEGATE & REGISTRATION CHARGES  
  EXEC [dbo].[GET_CREATE_EVENT_DELEGATE_REGISTRATION_CHARGES]  
   @WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID = @WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID,  
   @WEB_SERVICE_EVENT_BOOKING_DETAIL_SEQ_ID = @WEB_SERVICE_EVENT_BOOKING_DETAIL_SEQ_ID,  
   @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT,  
   @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM = @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM,  
   @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBD = @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBD,  
   @EXTERNAL_ID = @BOOKING_ID,  
   @CONTACT_SEQ_ID = @DELEGATE_CONTACT_SEQ_ID,  
   @EVENT_REGISTRATION_SEQ_ID = @EVENT_REGISTRATION_SEQ_ID,    
   @REGISTRATION_ID = @REGISTRATION_ID,  
   @USER = @USER,  
   @DISCOUNT_CODE = @DISCOUNT_CODE,  
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
   @ERROR = @ERROR OUTPUT,  
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
  PRINT 'AFTER DELEGATE ADD'  
  
    IF @DELEGATE_CONTACT_SEQ_ID>0
  BEGIN
		  EXEC [dbo].[GET_CREATE_EVENT_SESSION_REGISTRATION]
		   @BOOKING_ID = @BOOKING_ID,
		   @DELEGATE_CONTACT_SEQ_ID = @DELEGATE_CONTACT_SEQ_ID , 
		   @DELEGATE_FIRST_NAME = @DELEGATE_FIRST_NAME,
		   @DELEGATE_LAST_NAME  = @DELEGATE_LAST_NAME,
		   @EVENT_REGISTRATION_SEQ_ID = @EVENT_REGISTRATION_SEQ_ID,
		   @USER = @USER ,   
		   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
		   @ERROR = @ERROR OUTPUT,  
		   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
   END
  
  FETCH NEXT FROM CUS_ADDITIONAL_DELEGATE INTO @WEB_SERVICE_EVENT_BOOKING_DETAIL_SEQ_ID, @USER_NAME, @PAYMENT_AMOUNT_NET, @DELEGATE_FIRST_NAME, @DELEGATE_LAST_NAME  
 END  
  
 CLOSE CUS_ADDITIONAL_DELEGATE  
 DEALLOCATE CUS_ADDITIONAL_DELEGATE  
 PRINT 'OUT OF DELEGATE LOOP ...'  
 -- **************************************************************************************************************************  
 -- END:   
 -- **************************************************************************************************************************  
  
  
 EXEC [dbo].[GET_CREATE_FINANCE_BATCH_EVENT]  
  @EXTERNAL_ID = @BOOKING_ID,  
  @ACCOUNT = NULL,  
  @ACCOUNT_NAME = NULL,  
  @CONTACT = @CONTACT_SEQ_ID,  
  @CONTACT_NAME = @LABEL_NAME,  
  @EVENT_REGISTRATION = @EVENT_REGISTRATION_SEQ_ID,  
  @EVENT_REGISTRATION_NAME = @REGISTRATION_ID,  
  @USER = @USER,  
  @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
  @FINANCE_TRANSACTION_SEQ_ID = @FINANCE_TRANSACTION_SEQ_ID OUTPUT,  
  @ERROR = @ERROR OUTPUT,  
  @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
  
 IF ISNULL(@PAY_BY_INVOICE,'N') <> 'Y' AND ISNULL(@PAYMENT_AMOUNT,0) > 0  
 BEGIN  
  EXEC [dbo].[GET_CREATE_RECEIPT_BATCH_EVENT]  
   @EXTERNAL_ID = @BOOKING_ID,  
   @ACCOUNT = NULL,  
   @ACCOUNT_NAME = NULL,  
   @CONTACT = @CONTACT_SEQ_ID,  
   @CONTACT_NAME = @LABEL_NAME,  
   @FINANCE_TRANSACTION_SEQ_ID = @FINANCE_TRANSACTION_SEQ_ID,  
   @USER = @USER,  
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
   @PAYMENT_BATCH_TRANSACTION_SEQ_ID = @PAYMENT_BATCH_TRANSACTION_SEQ_ID OUTPUT,  
   @ERROR = @ERROR OUTPUT,  
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
 END  
  
 SELECT @EVENT_SEQ_ID = SEQ_ID 
 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA   
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
 AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT 
 --AND ATTRIBUTE_002 = @EVENT_ID  
 AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52318 AND ISNULL(ATTRIBUTE_STRING,'')=@EVENT_ID)
 
 
 DECLARE @TOTAL_BOOKINGS INT    
 
 SELECT @TOTAL_BOOKINGS = ISNULL(COUNT(SEQ_ID),0)
 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID  
 AND SRM_CLIENT_ENTITIES_SEQ_ID = 2560 
 --AND ATTRIBUTE_032 DEFAULT_EVENT
 AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT TEMP2.CUS_ENTITY_DATA_SEQ_ID 
								FROM (SELECT CUS_ENTITY_DATA_SEQ_ID 
										FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
										WHERE SRM_CLIENT_ENTITIES_SEQ_ID =2560 
										AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57206  --AND ATTRIBUTE_032 DEFAULT_EVENT
										AND ISNULL(ATTRIBUTE_DECIMAL,0)=@EVENT_SEQ_ID
									 )TEMP1
								INNER JOIN 	[SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH(NOLOCK)
								ON TEMP2.CUS_ENTITY_DATA_SEQ_ID = TEMP1.CUS_ENTITY_DATA_SEQ_ID
								WHERE TEMP2.SRM_CLIENT_ENTITIES_SEQ_ID =2560
								AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52438
								AND ISNULL(ATTRIBUTE_STRING,'')='CONFIRMED'
								)
 
 UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
 SET ATTRIBUTE_032 = @TOTAL_BOOKINGS,
  DATE_MODIFIED = @TODAY,    
  MODIFIED_BY = @USER    
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT AND SEQ_ID = @EVENT_SEQ_ID    
    
 EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
  @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT,    
  @CUS_ENTITY_DATA_SEQ_ID = @EVENT_SEQ_ID,    
  @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
  @ERROR = @ERROR OUTPUT,    
  @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT 



 PRINT '@EVENT_SEQ_ID ' + CAST(@EVENT_SEQ_ID AS NVARCHAR(100))  
 EXEC [dbo].[GET_APPLY_EVENT_DATA_TO_API]   
   @m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
   @m_CUS_ENTITY_DATA_SEQ_ID = @EVENT_SEQ_ID,  
   @ERROR = @ERROR OUTPUT,  
   @ERROR_DESCRIPTION  = @ERROR_DESCRIPTION OUTPUT  
  
 SET @ERROR = 0  
 SET @ERROR_DESCRIPTION = 'Process completed successfully'  
  
 SELECT @ERROR AS ERROR, @ERROR_DESCRIPTION AS ERROR_DESCRIPTION   
END



;







-- =============================================
-- Author:  <Mazhar>
-- Create date: <14/08/2013,,>
-- Description: <Apply Area of Focus Data to Web service Area of Focus>
-- =============================================
CREATE PROCEDURE [dbo].[GET_APPLY_EVENT_DATA_TO_API] 
	 @m_CLIENT_SEQ_ID BIGINT,
	 @m_CUS_ENTITY_DATA_SEQ_ID BIGINT,
	 @m_EVENT_SESSION_SEQ_ID BIGINT=0,
	 @ERROR SMALLINT = 0 OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
 AS 
 BEGIN
  
	SET NOCOUNT ON;
	
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @DEL_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @NEW_SEQ_ID BIGINT
	DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)
	DECLARE @EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @MEM_LEDGER_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @ATTACHMENT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SIMILAR_EVENT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	
	DECLARE @EVENT_NAME NVARCHAR(200)
	DECLARE @EVENT_CATEGORY NVARCHAR(500)
	DECLARE @INTRODUCTION NVARCHAR(MAX)
	DECLARE @VENUE_ADDRESS_1 NVARCHAR(100)
	DECLARE @VENUE_ADDRESS_2 NVARCHAR(100)
	DECLARE @VENUE_ADDRESS_3 NVARCHAR(100)
	DECLARE @VENUE_ADDRESS_4 NVARCHAR(100)
	DECLARE @VENUE_ADDRESS_5 NVARCHAR(100)
	DECLARE @VENUE_POSTCODE NVARCHAR(100)
	DECLARE @VENUE_COUNTY NVARCHAR(100)
	DECLARE @VENUE_COUNTRY NVARCHAR(100)
	DECLARE @START_TIME NVARCHAR(100)
	DECLARE @END_TIME NVARCHAR(100)
	DECLARE @INFORMATION_ABOUT_THE_EVENT NVARCHAR(100)
	DECLARE @CONTACT_EMAIL NVARCHAR(100)
	DECLARE @CONTACT_TELEPHONE NVARCHAR(100)
	DECLARE @START_DATE NVARCHAR(100)
	DECLARE @TOTAL_SPACE NVARCHAR(100)
	DECLARE @AVAILABLE_SPACE NVARCHAR(100)
	DECLARE @EVENT_ID NVARCHAR(100)
	DECLARE @MEM_RATE NVARCHAR(100)
	DECLARE @NON_MEM_RATE NVARCHAR(100)
	DECLARE @PRIMARY NVARCHAR(200)
	DECLARE @SECONDARY NVARCHAR(200)
	DECLARE @SEN NVARCHAR(200)
	DECLARE @LOCAL_BRANCHES NVARCHAR(200)
	DECLARE @WORK_GROUP NVARCHAR(200)
	DECLARE @EVENTS NVARCHAR(200)
	DECLARE @CONSUTANTS NVARCHAR(200)
	DECLARE @CURRICULUM NVARCHAR(200)
	DECLARE @SEARCH NVARCHAR(200)
	DECLARE @HEALTHSAFETY NVARCHAR(200)
	DECLARE @REGISTRATION_TIME NVARCHAR(200)
	DECLARE @PRE_READINGS NVARCHAR(500)
	DECLARE @ASSOCITED_PRODUCTS NVARCHAR(500)
	DECLARE @ACCREDITION_POINTS NVARCHAR(500)
	DECLARE @BOOKING_DEADLINE NVARCHAR(500)
	DECLARE @PRESENTER_INFO NVARCHAR(500)
	DECLARE @PRESENTER_NAME NVARCHAR(500)
	DECLARE @SIMILAR_EVENT_IDS NVARCHAR(500)
	DECLARE @BOOK_NOW_OVERRIDE NVARCHAR(1)
	DECLARE @BOOK_NOW_OVERRIDE_DETAILS NVARCHAR(MAX)
		
	DECLARE @IMAGE_URL NVARCHAR(200)
	DECLARE @MEM_NET_AMOUNT NVARCHAR(200)
	DECLARE @MEM_VAT_AMOUNT NVARCHAR(200)
	DECLARE @MEM_GROSS_AMOUNT NVARCHAR(200)
	DECLARE @NON_MEM_NET_AMOUNT NVARCHAR(200)
	DECLARE @NON_MEM_VAT_AMOUNT NVARCHAR(200)
	DECLARE @NON_MEM_GROSS_AMOUNT NVARCHAR(200)
	DECLARE @MEM_VAT_INCLUSIVE NVARCHAR(200)
	DECLARE @NON_VAT_INCLUSIVE NVARCHAR(200)
	
	DECLARE @MEM_VAT_RATE NVARCHAR(200)
	DECLARE @NON_VAT_RATE NVARCHAR(200)
	DECLARE @DATEMODIFIED DATETIME
	DECLARE @MODIFIEDBY NVARCHAR(200)
	DECLARE @DATECREATED DATETIME
	DECLARE @CREATEDBY NVARCHAR(200)
	DECLARE @WEB NVARCHAR(5) 
	DECLARE @DELETED NVARCHAR(5) 
	DECLARE @VAT_RATE BIGINT 
	DECLARE @VAT_PERC MONEY
	DECLARE @ENTITY_DISPLAY_NAME_VAT_RATE NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE BIGINT
	DECLARE @EVENT_REMARKS NVARCHAR(500)
	DECLARE @SRM_EVENT_WAITING_LIST NVARCHAR(5)
	DECLARE @EVENT_TAGS NVARCHAR(1000)
	DECLARE @END_DATE NVARCHAR(100)
	DECLARE @FEATURED_EVENT NVARCHAR(1)
	DECLARE @EVENT_ID_THINKIFIC NVARCHAR(100)
	
	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_EVENT_DATA_TO_API]'
	
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_EVENT_LISTING'

	SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT'

	SELECT @CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'CONTACT'
	
	SELECT @ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'ACCOUNT'

	SELECT @DEL_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'DELEGATE_TYPE'


	SELECT @EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID 
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT_RATE'

	SELECT @ATTACHMENT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'ATTACHMENT'
	
	SELECT @PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT_ASSOCIATED_PRODUCT'

	SELECT @SIMILAR_EVENT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'SIMILAR_EVENT'
	
	SET @ENTITY_DISPLAY_NAME_VAT_RATE = 'VAT_RATE'
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_VAT_RATE
	

	DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR 
		SELECT  
			EVE.ATTRIBUTE_001 AS EVENT_NAME,
			EVE.ATTRIBUTE_048 AS INTRODUCTION,
			--VENUE.ATTRIBUTE_024 AS VENUE_ADDRESS_1,
			--VENUE.ATTRIBUTE_025 AS VENUE_ADDRESS_2,
			--VENUE.ATTRIBUTE_026 AS VENUE_ADDRESS_3,
			--VENUE.ATTRIBUTE_105 AS VENUE_ADDRESS_4,
			--VENUE.ATTRIBUTE_027 AS VENUE_ADDRESS_5,
			--VENUE.ATTRIBUTE_028 AS VENUE_POSTCODE,
			--VENUE.ATTRIBUTE_030 AS VENUE_COUNTY,
			--VENUE.ATTRIBUTE_032 AS VENUE_COUNTRY,
			case when ISNULL(VENUE.ATTRIBUTE_108,'') = 'Alternate Business' then ISNULL(VENUE.ATTRIBUTE_001, '') + ', ' + ISNULL(VENUE.ATTRIBUTE_033, '') else ISNULL(VENUE.ATTRIBUTE_001, '') + ', ' + ISNULL(VENUE.ATTRIBUTE_024, '') end as VENUE_ADDRESS_1,
			case when ISNULL(VENUE.ATTRIBUTE_108,'') = 'Alternate Business' then VENUE.ATTRIBUTE_034 else VENUE.ATTRIBUTE_025 end as VENUE_ADDRESS_2,
			case when ISNULL(VENUE.ATTRIBUTE_108,'') = 'Alternate Business' then VENUE.ATTRIBUTE_035 else VENUE.ATTRIBUTE_026 end as VENUE_ADDRESS_3,
			case when ISNULL(VENUE.ATTRIBUTE_108,'') = 'Alternate Business' then VENUE.ATTRIBUTE_104 else VENUE.ATTRIBUTE_105 end as VENUE_ADDRESS_4,
			case when ISNULL(VENUE.ATTRIBUTE_108,'') = 'Alternate Business' then VENUE.ATTRIBUTE_036 else VENUE.ATTRIBUTE_027 end as VENUE_ADDRESS_5,
			case when ISNULL(VENUE.ATTRIBUTE_108,'') = 'Alternate Business' then VENUE.ATTRIBUTE_038 else VENUE.ATTRIBUTE_028 end as VENUE_POSTCODE,
			case when ISNULL(VENUE.ATTRIBUTE_108,'') = 'Alternate Business' then VENUE.ATTRIBUTE_040 else VENUE.ATTRIBUTE_030 end as VENUE_COUNTY,
			case when ISNULL(VENUE.ATTRIBUTE_108,'') = 'Alternate Business' then VENUE.ATTRIBUTE_042 else VENUE.ATTRIBUTE_032 end as VENUE_COUNTRY,
			EVE.ATTRIBUTE_028 AS [START_TIME],
			EVE.ATTRIBUTE_029 AS [END_TIME],
			EVE.ATTRIBUTE_052 AS INFORMATION_ABOUT_THE_EVENT,
			EVE_CONTACT.ATTRIBUTE_056 AS CONTACT_EMAIL,
			EVE_CONTACT.ATTRIBUTE_054 AS CONTACT_TELEPHONE,
			CONVERT(NVARCHAR, EVE.ATTRIBUTE_004,121)  AS [START_DATE],
			EVE.ATTRIBUTE_030 AS TOTAL_SPACE,
			EVE.ATTRIBUTE_034 AS AVAILABLE_SPACE,
			--EVE.ATTRIBUTE_034 AS AVAILABLE_SPACE,
			EVE.ATTRIBUTE_002 AS EVENT_ID,
			EVE.ATTRIBUTE_054 AS [PRIMARY],
			EVE.ATTRIBUTE_055 AS SECONDARY,
			EVE.ATTRIBUTE_056 AS SEN,
			EVE.ATTRIBUTE_057 AS LOCAL_BRANCHES,
			EVE.ATTRIBUTE_058 AS WORK_GROUP,
			EVE.ATTRIBUTE_059 AS [EVENTS],
			EVE.ATTRIBUTE_060 AS CONSUTANTS,
			EVE.ATTRIBUTE_061 AS CURRICULUM ,
			EVE.ATTRIBUTE_062 AS SEARCH ,
			EVE.ATTRIBUTE_063 AS HEALTH_AND_SAFETY,
			EVE.ATTRIBUTE_064 AS REGISTRATION_TIME,
			EVE.ATTRIBUTE_069 AS ACCREDITION,
			EVE.ATTRIBUTE_068 AS BOOKING_DEADLINE,
			EVE.ATTRIBUTE_067 AS PRESENTER_INFO,
			EVE.ATTRIBUTE_066 AS PRESENTER_NAME,
			EVE.ATTRIBUTE_072 As EVENT_CATEGORY,
			EVE.DATE_CREATED,EVE.CREATED_BY,EVE.DATE_MODIFIED,EVE.MODIFIED_BY,
			EVE.ATTRIBUTE_045 AS WEB,
			EVE.DELETED AS DELETED,
			EVE.ATTRIBUTE_016 AS VAT_RATE,
			EVE.ATTRIBUTE_040 AS EVT_REMARKS,
			case when isnull(EVE.ATTRIBUTE_037,0) > 0 then 'Y' else 'N' end AS WAITING_LIST,
			EVE.ATTRIBUTE_073 AS BOOK_NOW_OVERRIDE,
			EVE.ATTRIBUTE_074 AS BOOK_NOW_OVERRIDE_DETAILS,
			EVE.ATTRIBUTE_075 AS EVENT_TAGS,
			EVE.ATTRIBUTE_005 AS END_DATE,
			EVE.ATTRIBUTE_076 AS FEATURED_EVENT,
			EVE.ATTRIBUTE_082 as EVENT_ID_THINKIFIC

		FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVE WITH(NOLOCK)
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA VENUE WITH(NOLOCK) ON VENUE.SRM_CLIENT_ENTITIES_SEQ_ID=@ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID AND VENUE.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0) FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND CUS_ENTITY_DATA_SEQ_ID = EVE.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52328) --=EVE.ATTRIBUTE_020  --ACCOUNT
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVE_CONTACT WITH(NOLOCK) ON EVE_CONTACT.SRM_CLIENT_ENTITIES_SEQ_ID=@CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID AND EVE_CONTACT.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0) FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND CUS_ENTITY_DATA_SEQ_ID = EVE.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52350)  --EVE.ATTRIBUTE_042 --CONTACT
		WHERE EVE.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID
		AND EVE.SEQ_ID=@m_CUS_ENTITY_DATA_SEQ_ID 
		
		OPEN CUR_RECORDS
		FETCH NEXT FROM CUR_RECORDS INTO   @EVENT_NAME,@INTRODUCTION,@VENUE_ADDRESS_1,@VENUE_ADDRESS_2,@VENUE_ADDRESS_3,@VENUE_ADDRESS_4,@VENUE_ADDRESS_5,@VENUE_POSTCODE,
										@VENUE_COUNTY,@VENUE_COUNTRY,@START_TIME,@END_TIME,@INFORMATION_ABOUT_THE_EVENT,@CONTACT_EMAIL,@CONTACT_TELEPHONE,@START_DATE,@TOTAL_SPACE,
										@AVAILABLE_SPACE,@EVENT_ID,@PRIMARY,@SECONDARY,@SEN,@LOCAL_BRANCHES,@WORK_GROUP,@EVENTS,@CONSUTANTS,@CURRICULUM,@SEARCH,@HEALTHSAFETY,
										@REGISTRATION_TIME,@ACCREDITION_POINTS,@BOOKING_DEADLINE,@PRESENTER_INFO,@PRESENTER_NAME,@EVENT_CATEGORY,@DATECREATED, @CREATEDBY , @DATEMODIFIED , 
										@MODIFIEDBY , @WEB, @DELETED, @VAT_RATE,@EVENT_REMARKS,@SRM_EVENT_WAITING_LIST, @BOOK_NOW_OVERRIDE, @BOOK_NOW_OVERRIDE_DETAILS, @EVENT_TAGS, @END_DATE, @FEATURED_EVENT, @EVENT_ID_THINKIFIC
	WHILE @@FETCH_STATUS = 0
	BEGIN
		--DELETE IF ALREADY EXITS MEMBER DATA
		DECLARE @WEB_SERVICE_EVENT_SEQ_ID BIGINT
		SELECT @WEB_SERVICE_EVENT_SEQ_ID = SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH(NOLOCK) 
		WHERE SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID 
		AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=56225 AND ISNULL(ATTRIBUTE_STRING,'') = @EVENT_ID )  ---ATTRIBUTE_028=@EVENT_ID

		--IF (EXISTS(SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=56225 AND ATTRIBUTE_STRING = @EVENT_ID ) ---ATTRIBUTE_028=@EVENT_ID))
		IF ISNULL(@WEB_SERVICE_EVENT_SEQ_ID,0)>0
		BEGIN
			DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID AND SEQ_ID IN (SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=56225 AND ISNULL(ATTRIBUTE_STRING,'') = @EVENT_ID )) --= @WEB_SERVICE_EVENT_SEQ_ID  --ATTRIBUTE_028=@EVENT_ID AND 
			DELETE FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE CUS_ENTITY_DATA_SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=56225 AND ISNULL(ATTRIBUTE_STRING,'') = @EVENT_ID )-- @WEB_SERVICE_EVENT_SEQ_ID --IN (SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_028=@EVENT_ID AND SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID)
			
		END
		--SYNCH MEMBERSHIP RECORD
		if(ISNULL(@WEB, 'N') = 'Y' AND ISNULL(@DELETED, 'N') = 'N')
		begin
			SELECT @VAT_PERC = ATTRIBUTE_006 FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE AND SEQ_ID = @VAT_RATE
			PRINT '@VAT_PERC '+ CAST(@VAT_PERC AS NVARCHAR)
			--GETING SIMILAR EVENTS
			SET @SIMILAR_EVENT_IDS =(SELECT TOP 1 STUFF((SELECT ',' + E.ATTRIBUTE_002 
											 FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SIM_EVE WITH(NOLOCK)
											 INNER JOIN  [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA E WITH(NOLOCK)
											 ON E.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID
											 AND E.SEQ_ID=SIM_EVE.ATTRIBUTE_004 --SIM_EVE.ATTRIBUTE_004
											 WHERE SIM_EVE.SRM_CLIENT_ENTITIES_SEQ_ID=@SIMILAR_EVENT_SRM_CLIENT_ENTITIES_SEQ_ID
											 AND SIM_EVE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SIMILAR_EVENT_SRM_CLIENT_ENTITIES_SEQ_ID AND CUS_ENTITY_DATA_SEQ_ID=SIM_EVE.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57771  AND ISNULL(ATTRIBUTE_DECIMAL,0)=@m_CUS_ENTITY_DATA_SEQ_ID)  --ATTRIBUTE_002=@m_CUS_ENTITY_DATA_SEQ_ID
											 AND ISNULL(SIM_EVE.DELETED,'N')='N'
                                             FOR XML PATH('')),1,1,''))

			--GET PRE READINGS AND ASSOCIATED PRODUCTS 
			
			SET @PRE_READINGS = (SELECT TOP 1 STUFF((SELECT ',' + PRE_READINGS.ATTRIBUTE_003 
                                         FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA PRE_READINGS WITH(NOLOCK)
                                         WHERE PRE_READINGS.SRM_CLIENT_ENTITIES_SEQ_ID=@PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID 
                                         AND PRE_READINGS.SEQ_ID IN(SELECT TEMP2.CUS_ENTITY_DATA_SEQ_ID 
																	FROM(SELECT CUS_ENTITY_DATA_SEQ_ID  
																		 FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) 
																		 WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID 
																		 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57757  
																		 AND ISNULL(ATTRIBUTE_DECIMAL,0)=@m_CUS_ENTITY_DATA_SEQ_ID  --PRE_READINGS.ATTRIBUTE_006=@m_CUS_ENTITY_DATA_SEQ_ID
																		 ) AS TEMP1 
																	 INNER JOIN [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH(NOLOCK) ON  TEMP2.CUS_ENTITY_DATA_SEQ_ID = TEMP1.CUS_ENTITY_DATA_SEQ_ID
																	 WHERE TEMP2.SRM_CLIENT_ENTITIES_SEQ_ID=@PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID 
																	 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57754
																	 AND ISNULL(TEMP2.ATTRIBUTE_BOOLEAN,'N')='Y'
																	 )
                                         --AND PRE_READINGS.ATTRIBUTE_005='Y' 
                                         AND ISNULL(PRE_READINGS.DELETED,'N')='N' 
                                         FOR XML PATH('')),1,1,''))
			
SET @ASSOCITED_PRODUCTS = (SELECT TOP 1 STUFF((SELECT ',' + PRE_READINGS.ATTRIBUTE_003 
											   FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA PRE_READINGS WITH(NOLOCK)
											   WHERE PRE_READINGS.SRM_CLIENT_ENTITIES_SEQ_ID=@PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID
	                                            AND PRE_READINGS.SEQ_ID IN(SELECT TEMP2.CUS_ENTITY_DATA_SEQ_ID 
																	      FROM(SELECT CUS_ENTITY_DATA_SEQ_ID
																	           FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) 
																				 WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID 
																				 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57757  
																				 AND ISNULL(ATTRIBUTE_DECIMAL,0)=@m_CUS_ENTITY_DATA_SEQ_ID  --PRE_READINGS.ATTRIBUTE_006=@m_CUS_ENTITY_DATA_SEQ_ID
																		 ) AS TEMP1 
																	 INNER JOIN [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH(NOLOCK) ON  TEMP2.CUS_ENTITY_DATA_SEQ_ID = TEMP1.CUS_ENTITY_DATA_SEQ_ID
																	 WHERE TEMP2.SRM_CLIENT_ENTITIES_SEQ_ID=@PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID 
																	 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57753
																	 AND ISNULL(TEMP2.ATTRIBUTE_BOOLEAN,'N')='Y'
																	 )

											   --AND PRE_READINGS.ATTRIBUTE_004='Y' 
											   AND ISNULL(PRE_READINGS.DELETED,'N')='N' 
											   FOR XML PATH('')),1,1,''))
		
		
		
			--GET ATTACHMENT
				SELECT TOP 1  @IMAGE_URL=ATTRIBUTE_002 
				FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA ATTACHMENT WITH(NOLOCK)
				WHERE ATTACHMENT.SRM_CLIENT_ENTITIES_SEQ_ID=@ATTACHMENT_SRM_CLIENT_ENTITIES_SEQ_ID 
				AND ATTACHMENT.SEQ_ID IN(SELECT TEMP2.CUS_ENTITY_DATA_SEQ_ID 
									 FROM(SELECT CUS_ENTITY_DATA_SEQ_ID  
										   FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) 
										   WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@ATTACHMENT_SRM_CLIENT_ENTITIES_SEQ_ID 
										   AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 51837  
										   AND ISNULL(ATTRIBUTE_DECIMAL,0)=@m_CUS_ENTITY_DATA_SEQ_ID  --ATTACHMENT.ATTRIBUTE_499=@M_CUS_ENTITY_DATA_SEQ_ID 
										   ) AS TEMP1 
										   INNER JOIN [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH(NOLOCK) ON  TEMP2.CUS_ENTITY_DATA_SEQ_ID = TEMP1.CUS_ENTITY_DATA_SEQ_ID
										   WHERE TEMP2.SRM_CLIENT_ENTITIES_SEQ_ID=@ATTACHMENT_SRM_CLIENT_ENTITIES_SEQ_ID 
										   AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 51855
										   AND ISNULL(TEMP2.ATTRIBUTE_STRING,'')='IMAGE FOR WEB'
										)  
				--AND ATTACHMENT.ATTRIBUTE_008 = 'IMAGE FOR WEB'
				AND ISNULL(ATTACHMENT.DELETED,'N')='N'		
				
			--GETTING MEM RATE
			SELECT TOP 1 
			@MEM_RATE = ISNULL(EVNT_RATE.ATTRIBUTE_008,'0'),
			@MEM_VAT_RATE=ISNULL(EVNT_RATE.ATTRIBUTE_015,'0'),
			@MEM_VAT_INCLUSIVE=EVNT_RATE.ATTRIBUTE_010
			FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVNT_RATE WITH(NOLOCK)
			INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA DELEGATE_TYPE WITH(NOLOCK)
					ON DELEGATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = @DEL_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID 
					AND DELEGATE_TYPE.SEQ_ID IN(SELECT Temp2.CUS_ENTITY_DATA_SEQ_ID
												FROM (SELECT ISNULL(ATTRIBUTE_DECIMAL,0) AS DELEGATE_TYPE_SEQ_ID
														 FROM  [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
														 WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID
														 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=54234 
														 AND CUS_ENTITY_DATA_SEQ_ID=EVNT_RATE.SEQ_ID
												      ) TEMP1
														INNER JOIN [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH(NOLOCK) ON TEMP2.CUS_ENTITY_DATA_SEQ_ID = TEMP1.DELEGATE_TYPE_SEQ_ID
													    WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@DEL_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID
													    AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52381
													    AND ISNULL(ATTRIBUTE_STRING,'') = 'MEM'
												)
			WHERE EVNT_RATE.SRM_CLIENT_ENTITIES_SEQ_ID=@EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID
			AND EVNT_RATE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=54230 AND ISNULL(ATTRIBUTE_DECIMAL,0)=@m_CUS_ENTITY_DATA_SEQ_ID) --ATTRIBUTE_002 =@m_CUS_ENTITY_DATA_SEQ_ID
			AND ISNULL(EVNT_RATE.DELETED,'N') = 'N'

		
			IF(@MEM_VAT_INCLUSIVE='Y')
			BEGIN
				--Net=(Gross*100)/(100+vat rate)
				SET @MEM_NET_AMOUNT = (CAST(ISNULL(@MEM_RATE, '0.00') AS MONEY)*100.00)/(100.00+ CAST(@VAT_PERC AS MONEY))
				SET @MEM_NET_AMOUNT = ROUND(CAST(ISNULL(@MEM_NET_AMOUNT , '0.00') AS MONEY), 2)
				SET @MEM_GROSS_AMOUNT = @MEM_RATE
				SET @MEM_VAT_AMOUNT = CAST(ISNULL(@MEM_GROSS_AMOUNT, '0.00') AS MONEY)-CAST(ISNULL(@MEM_NET_AMOUNT, '0.00') AS MONEY)
				SET @MEM_VAT_RATE = @MEM_VAT_AMOUNT
			END
			ELSE
			BEGIN
				SET @MEM_NET_AMOUNT = ISNULL(@MEM_RATE, '0.00')
				SET @MEM_VAT_RATE = CAST(ISNULL(@MEM_RATE, '0.00') AS MONEY) * CAST(ISNULL(@VAT_PERC, '0.00') AS MONEY) / 100
				--SET @MEM_GROSS_AMOUNT = CAST(@MEM_NET_AMOUNT AS MONEY)*((100 + CAST(@MEM_VAT_RATE AS MONEY))/100.00)
				SET @MEM_GROSS_AMOUNT = CAST(ISNULL(@MEM_NET_AMOUNT, '0.00') AS MONEY) + CAST(ISNULL(@MEM_VAT_RATE, '0.00') AS MONEY)
				--SET @MEM_VAT_AMOUNT = CAST(@MEM_GROSS_AMOUNT AS MONEY)-CAST(@MEM_NET_AMOUNT AS MONEY)
			END

			--GETTING NON MEM RATE
			
			SELECT TOP 1 
			@NON_MEM_RATE = ISNULL(EVNT_RATE.ATTRIBUTE_008,'0'),
			@NON_VAT_RATE=ISNULL(EVNT_RATE.ATTRIBUTE_015,'0') ,
			@NON_VAT_INCLUSIVE=EVNT_RATE.ATTRIBUTE_010
			FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVNT_RATE WITH(NOLOCK)
			INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA DELEGATE_TYPE WITH(NOLOCK)
					ON DELEGATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = @DEL_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID 
					AND DELEGATE_TYPE.SEQ_ID IN(SELECT Temp2.CUS_ENTITY_DATA_SEQ_ID
												FROM (SELECT ISNULL(ATTRIBUTE_DECIMAL,0) AS DELEGATE_TYPE_SEQ_ID
														 FROM  [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
														 WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID
														 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=54234 
														 AND CUS_ENTITY_DATA_SEQ_ID=EVNT_RATE.SEQ_ID
												      ) TEMP1
														INNER JOIN [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH(NOLOCK) ON TEMP2.CUS_ENTITY_DATA_SEQ_ID = TEMP1.DELEGATE_TYPE_SEQ_ID
													    WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@DEL_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID
													    AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52381
													    AND ISNULL(ATTRIBUTE_STRING,'') = 'NON'
												)
			--AND DELEGATE_TYPE.ATTRIBUTE_009='NON'
			WHERE EVNT_RATE.SRM_CLIENT_ENTITIES_SEQ_ID=@EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID
			AND EVNT_RATE.ATTRIBUTE_002 = CAST(@m_CUS_ENTITY_DATA_SEQ_ID AS VARCHAR )  
			AND ISNULL(EVNT_RATE.DELETED,'N') = 'N'
			
			IF(@NON_VAT_INCLUSIVE='Y')
			BEGIN
				--Net=(Gross*100)/(100+vat rate)
				--SET @NON_MEM_NET_AMOUNT = (CAST(@NON_MEM_RATE AS MONEY)*100.00)/(100.00+ CAST(@NON_VAT_RATE AS MONEY))
				SET @NON_MEM_NET_AMOUNT = (CAST(ISNULL(@NON_MEM_RATE, '0.00') AS MONEY)*100.00)/(100.00+ CAST(ISNULL(@VAT_PERC, '0.00') AS MONEY))
				SET @NON_MEM_NET_AMOUNT = ROUND(CAST(ISNULL(@NON_MEM_NET_AMOUNT, '0.00') AS MONEY), 2)
				PRINT '@NON_MEM_NET_AMOUNT = ' + @NON_MEM_NET_AMOUNT
				SET @NON_MEM_GROSS_AMOUNT = CAST(ISNULL(@NON_MEM_RATE, '0.00') AS MONEY)
				SET @NON_MEM_VAT_AMOUNT = CAST(ISNULL(@NON_MEM_GROSS_AMOUNT, '0.00') AS MONEY)-CAST(ISNULL(@NON_MEM_NET_AMOUNT, '0.00') AS MONEY)			
				SET @NON_VAT_RATE = @NON_MEM_VAT_AMOUNT
			END
			ELSE
			BEGIN
				SET @NON_MEM_NET_AMOUNT = ISNULL(@NON_MEM_RATE, '0.00')
				SET @NON_VAT_RATE = CAST(ISNULL(@NON_MEM_RATE, '0.00') AS MONEY) * CAST(ISNULL(@VAT_PERC, '0.00') AS MONEY) / 100
				SET @NON_MEM_GROSS_AMOUNT = CAST(ISNULL(@NON_MEM_NET_AMOUNT, '0.00') AS MONEY) + CAST(ISNULL(@NON_VAT_RATE, '0.00') AS MONEY)
				--SET @NON_MEM_GROSS_AMOUNT = CAST(@NON_MEM_NET_AMOUNT AS MONEY)*((100 + CAST(@NON_VAT_RATE AS MONEY))/100.00)
				--SET @NON_MEM_VAT_AMOUNT = CAST(@NON_MEM_GROSS_AMOUNT AS MONEY)-CAST(@NON_MEM_NET_AMOUNT AS MONEY)
			END

			EXEC  [DBO].[GET_INSERT_CUS_ENTITY_DATA]
			@SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID,
			@ATTRIBUTE_001=@EVENT_NAME,
			@ATTRIBUTE_002=@INTRODUCTION,
			@ATTRIBUTE_003=@VENUE_ADDRESS_1,
			@ATTRIBUTE_004=@VENUE_ADDRESS_2,
			@ATTRIBUTE_005=@VENUE_ADDRESS_3,
			@ATTRIBUTE_006=@VENUE_ADDRESS_4,
			@ATTRIBUTE_007=@VENUE_ADDRESS_5,
			@ATTRIBUTE_008=@VENUE_POSTCODE,
			@ATTRIBUTE_009=@VENUE_COUNTY,
			@ATTRIBUTE_011=@START_TIME,
			@ATTRIBUTE_012=@END_TIME,
			--@ATTRIBUTE_013=@INFORMATION_ABOUT_THE_EVENT,
			--@ATTRIBUTE_014=@EVENT_REMARKS,
			@ATTRIBUTE_015=@CONTACT_EMAIL,
			@ATTRIBUTE_016=@CONTACT_TELEPHONE,
			@ATTRIBUTE_020=@START_DATE,
			@ATTRIBUTE_022=@TOTAL_SPACE,
			@ATTRIBUTE_023=@AVAILABLE_SPACE,
			@ATTRIBUTE_024= @SRM_EVENT_WAITING_LIST, 
			@ATTRIBUTE_028=@EVENT_ID,
			@ATTRIBUTE_031=@MEM_NET_AMOUNT,
			@ATTRIBUTE_032=@MEM_VAT_RATE,
			@ATTRIBUTE_029=@MEM_GROSS_AMOUNT,
			@ATTRIBUTE_033=@NON_MEM_NET_AMOUNT,
			@ATTRIBUTE_034=@NON_VAT_RATE,
			@ATTRIBUTE_030=@NON_MEM_GROSS_AMOUNT,
			@ATTRIBUTE_037=@PRIMARY,
			@ATTRIBUTE_038=@SECONDARY,
			@ATTRIBUTE_039=@SEN,
			@ATTRIBUTE_040=@LOCAL_BRANCHES,
			@ATTRIBUTE_041=@WORK_GROUP,
			@ATTRIBUTE_042=@EVENTS,
			@ATTRIBUTE_043=@CONSUTANTS,
			@ATTRIBUTE_044=@CURRICULUM,
			@ATTRIBUTE_045=@SEARCH,
			@ATTRIBUTE_046=@HEALTHSAFETY,
			@ATTRIBUTE_047=@EVENT_CATEGORY,
			@ATTRIBUTE_010=@REGISTRATION_TIME,
			@ATTRIBUTE_035=@IMAGE_URL,
			@ATTRIBUTE_017=@PRE_READINGS,
			@ATTRIBUTE_036=@ASSOCITED_PRODUCTS,
			@ATTRIBUTE_026=@ACCREDITION_POINTS,
			@ATTRIBUTE_021=@BOOKING_DEADLINE,
			--@ATTRIBUTE_018=@PRESENTER_INFO,
			--@ATTRIBUTE_019=@PRESENTER_NAME,
			@ATTRIBUTE_018=@PRESENTER_NAME,
			@ATTRIBUTE_019=@PRESENTER_INFO,
			@ATTRIBUTE_027=@SIMILAR_EVENT_IDS,
			@ATTRIBUTE_048 = @BOOK_NOW_OVERRIDE,
			@ATTRIBUTE_049 = @BOOK_NOW_OVERRIDE_DETAILS,
			@ATTRIBUTE_050 = @EVENT_TAGS,
			@ATTRIBUTE_051 = @END_DATE,
			@ATTRIBUTE_052  = @FEATURED_EVENT, 
			@ATTRIBUTE_053 = @EVENT_ID_THINKIFIC,
			@SRM_CLIENTS_SEQ_ID=@M_CLIENT_SEQ_ID,
			@DATE_CREATED=@DATECREATED,
			@CREATED_BY=@CREATEDBY,
			@DATE_MODIFIED=@DATEMODIFIED,
			@MODIFIED_BY=@MODIFIEDBY,
		
			@RETURN_SEQ_ID=@NEW_SEQ_ID OUTPUT,
			@ERROR=@ERROR OUTPUT,
			@ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT				
			
			
			--EXEC [dbo].[GET_APPLY_EVENT_SESSIONS_DATA_TO_API] 
			--@m_CLIENT_SEQ_ID = @m_CLIENT_SEQ_ID,
			--@m_EVENT_SEQ_ID = @m_CUS_ENTITY_DATA_SEQ_ID,
			--@m_CUS_ENTITY_DATA_SEQ_ID = @m_EVENT_SESSION_SEQ_ID,
			--@ERROR  = @ERROR OUTPUT,
			--@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
			
			
		END

		FETCH NEXT FROM CUR_RECORDS INTO   @EVENT_NAME,@INTRODUCTION,@VENUE_ADDRESS_1,@VENUE_ADDRESS_2,@VENUE_ADDRESS_3,@VENUE_ADDRESS_4,@VENUE_ADDRESS_5,@VENUE_POSTCODE,
										@VENUE_COUNTY,@VENUE_COUNTRY,@START_TIME,@END_TIME,@INFORMATION_ABOUT_THE_EVENT,@CONTACT_EMAIL,@CONTACT_TELEPHONE,@START_DATE,@TOTAL_SPACE,
										@AVAILABLE_SPACE,@EVENT_ID,@PRIMARY,@SECONDARY,@SEN,@LOCAL_BRANCHES,@WORK_GROUP,@EVENTS,@CONSUTANTS,@CURRICULUM,@SEARCH,@HEALTHSAFETY,
										@REGISTRATION_TIME,@ACCREDITION_POINTS,@BOOKING_DEADLINE,@PRESENTER_INFO,@PRESENTER_NAME,@EVENT_CATEGORY,@DATECREATED, @CREATEDBY , @DATEMODIFIED , 
										@MODIFIEDBY , @WEB, @DELETED, @VAT_RATE,@EVENT_REMARKS,@SRM_EVENT_WAITING_LIST,@BOOK_NOW_OVERRIDE, @BOOK_NOW_OVERRIDE_DETAILS, @EVENT_TAGS, @END_DATE , @FEATURED_EVENT, @EVENT_ID_THINKIFIC

		--FETCH NEXT FROM CUR_RECORDS INTO    @EVENT_NAME,@INTRODUCTION,@VENUE_ADDRESS_1,@VENUE_ADDRESS_2,@VENUE_ADDRESS_3,@VENUE_ADDRESS_4,@VENUE_POSTCODE,
		--										@VENUE_COUNTY,@VENUE_COUNTRY,@START_TIME,@END_TIME,@INFORMATION_ABOUT_THE_EVENT,@CONTACT_EMAIL,@CONTACT_TELEPHONE,
		--										@START_DATE,@TOTAL_SPACE,@AVAILABLE_SPACE,@EVENT_ID,@PRIMARY,@SECONDARY,@SEN,@LOCAL_BRANCHES,
		--										@WORK_GROUP,@EVENTS,@CONSUTANTS,@CURRICULUM,@SEARCH,@HEALTHSAFETY,@REGISTRATION_TIME,@ACCREDITION_POINTS,@BOOKING_DEADLINE,@PRESENTER_INFO,@PRESENTER_NAME,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY, @WEB, @VAT_RATE 
	
	end

	CLOSE CUR_RECORDS
	DEALLOCATE CUR_RECORDS



	  IF ISNULL(@m_EVENT_SESSION_SEQ_ID,0)>0
		BEGIN
			  DECLARE CUR_SESSION_RECORDS CURSOR LOCAL STATIC  FOR   
			  SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVE_SESSIONS WITH(NOLOCK)
			  WHERE SEQ_ID= @M_EVENT_SESSION_SEQ_ID
			  AND EVE_SESSIONS.SRM_CLIENT_ENTITIES_SEQ_ID=2646  -- EVENT_SESSION
			  AND EVE_SESSIONS.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID 
										  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)  
										  WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2646 
										  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=54140 
										  AND ISNULL(ATTRIBUTE_DECIMAL,0)=@M_CUS_ENTITY_DATA_SEQ_ID
										  ) --ATTRIBUTE_002=@M_CUS_ENTITY_DATA_SEQ_ID 
			  --AND ISNULL(DELETED,'N')='N'
	   END 
	  ELSE
  		BEGIN
  			  DECLARE CUR_SESSION_RECORDS CURSOR LOCAL STATIC  FOR   
			  SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVE_SESSIONS WITH(NOLOCK)
			  WHERE EVE_SESSIONS.SRM_CLIENT_ENTITIES_SEQ_ID=2646 -- EVENT_SESSION
			  AND EVE_SESSIONS.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID 
										 FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
										 WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2646
										 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=54140 
										 AND ISNULL(ATTRIBUTE_DECIMAL,0)=@M_CUS_ENTITY_DATA_SEQ_ID) --ATTRIBUTE_002=@M_CUS_ENTITY_DATA_SEQ_ID
			  --AND ISNULL(DELETED,'N')='N'
		END 
		
	  OPEN CUR_SESSION_RECORDS  
	  FETCH NEXT FROM CUR_SESSION_RECORDS INTO   @m_EVENT_SESSION_SEQ_ID
	  
	   WHILE @@FETCH_STATUS = 0  
	   BEGIN  
					 EXEC [dbo].[GET_APPLY_EVENT_SESSIONS_DATA_TO_API]   
					   @m_CLIENT_SEQ_ID = @m_CLIENT_SEQ_ID,  
					   @m_EVENT_SEQ_ID = @m_CUS_ENTITY_DATA_SEQ_ID,  
					   @m_CUS_ENTITY_DATA_SEQ_ID = @m_EVENT_SESSION_SEQ_ID,  
					   @ERROR  = @ERROR OUTPUT,  
					   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
		
			FETCH NEXT FROM CUR_SESSION_RECORDS INTO   @m_EVENT_SESSION_SEQ_ID   
	   END
	   
	   CLOSE CUR_SESSION_RECORDS  
	   DEALLOCATE CUR_SESSION_RECORDS  



	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END




;






-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_APPLY_EVENT_DATA_TO_API_ALL_EVENTS]
	-- Add the parameters for the stored procedure here
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_EVENT_DATA_TO_API_ALL_EVENTS]'
	
	SET ANSI_NULLS ON
	SET QUOTED_IDENTIFIER ON
	--SET NOCOUNT ON;

	DECLARE @EVENT_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT

	SET @SRM_CLIENTS_SEQ_ID = 17
	SET @SRM_CLIENT_ENTITIES_SEQ_ID = 2556

	DELETE FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID  =  @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 2741
	--AND ATTRIBUTE_028 NOT IN (SELECT ATTRIBUTE_002 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE DELETED = 'N' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 2556)
	AND CUS_ENTITY_DATA.SEQ_ID IN  (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
								  WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2741 
								  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56225 
								  AND ISNULL(ATTRIBUTE_STRING,'') COLLATE SQL_Latin1_General_CP1_CI_AS NOT IN (SELECT ATTRIBUTE_002 
																	  FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
																	  WHERE DELETED = 'N' AND SRM_CLIENTS_SEQ_ID =@SRM_CLIENTS_SEQ_ID 
																	  AND SRM_CLIENT_ENTITIES_SEQ_ID = 2556
																	  )
								)
	
	DECLARE CUR_EVENT CURSOR FOR
		SELECT SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

	OPEN CUR_EVENT 

	FETCH NEXT FROM CUR_EVENT INTO @EVENT_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT 'REPLICATING EVENT ' + CAST(@EVENT_SEQ_ID AS NVARCHAR)

		EXEC [SRM-Framework_New].[dbo].[GET_APPLY_EVENT_DATA_TO_API]  
			@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@m_CUS_ENTITY_DATA_SEQ_ID = @EVENT_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		FETCH NEXT FROM CUR_EVENT INTO @EVENT_SEQ_ID
	END

	CLOSE CUR_EVENT
	DEALLOCATE CUR_EVENT

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''

	--PRINT 'END POPULATE PIVOT _____________________________'
END
	





;





     
      
-- =============================================      
-- Author:  <MQ>      
-- Create date: <14/08/2013,,>      
-- Description: <Apply Event Sessions Data to Web service Event Session>      
-- =============================================      
CREATE PROCEDURE [dbo].[GET_APPLY_EVENT_SESSIONS_DATA_TO_API]      
  @m_CLIENT_SEQ_ID BIGINT,      
  @m_EVENT_SEQ_ID BIGINT,      
  @m_CUS_ENTITY_DATA_SEQ_ID BIGINT = NULL,      
  @ERROR SMALLINT = 0 OUTPUT,      
  @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT      
 AS       
 BEGIN      
        
         
 SET NOCOUNT ON;      
       
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
 DECLARE @WEB_SERVICE_EVENT_SESSIONS BIGINT      
 DECLARE @EVENT_SETUP_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
      
 DECLARE @NEW_SEQ_ID BIGINT      
 DECLARE @SRM_ENTITY_NAME NVARCHAR(200)      
 DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)      
 DECLARE @EVENT_SETUP_SRM_ENTITY_NAME NVARCHAR(200)      
       
       
 DECLARE @EVENT_NAME NVARCHAR(100)      
 DECLARE @EVENT_ID NVARCHAR(100)      
 DECLARE @WEB NVARCHAR(5)       
 DECLARE @EVENT_DELETED NVARCHAR(5)       
 DECLARE @EVENT_DATEDELETED DATETIME      
 DECLARE @EVENT_DELETEDBY NVARCHAR(200)      
 DECLARE @EVENT_DATEMODIFIED DATETIME      
 DECLARE @EVENT_MODIFIEDBY NVARCHAR(200)      
 DECLARE @EVENT_DATECREATED DATETIME      
 DECLARE @EVENT_CREATEDBY NVARCHAR(200)      
       
 DECLARE @SESSION_SEQ_ID BIGINT      
 DECLARE @SESSION_ID NVARCHAR(100)      
 DECLARE @SESSION_CLIENT_ID BIGINT      
 DECLARE @SESSION_DATE_MODIFIED DATETIME      
 DECLARE @SESSION_MODIFIED_BY NVARCHAR(100)      
 DECLARE @SESSION_DATE_CREATED DATETIME      
 DECLARE @SESSION_CREATED_BY NVARCHAR(100)      
 DECLARE @SESSION_DELETED NVARCHAR      
 DECLARE @SESSION_DATE_DELETED DATETIME      
 DECLARE @SESSION_DELETED_BY NVARCHAR(100)      
 DECLARE @SESSION_EVENT BIGINT      
 DECLARE @SESSION_EVENT_NAME NVARCHAR(100)      
 DECLARE @SESSION_EVENT_STATUS BIGINT      
 DECLARE @SESSION_EVENT_STATUS_DESCRIPTION NVARCHAR(100)      
 DECLARE @SESSION_TYPE BIGINT      
 DECLARE @SESSION_TYPE_NAME NVARCHAR(100)      
 DECLARE @SESSION_DESCRIPTION NVARCHAR(200)      
 DECLARE @SESSION_FORMAL_TITLE NVARCHAR(250)      
 DECLARE @SESSION_START_DATE DATE      
 DECLARE @SESSION_END_DATE DATE      
 DECLARE @SESSION_START_TIME NVARCHAR(16)      
 DECLARE @SESSION_END_TIME NVARCHAR(16)      
 DECLARE @SESSION_MAXIMUM_SEATS_AVAILABLE BIGINT      
 DECLARE @SESSION_TOTAL_BOOKINGS BIGINT      
 DECLARE @SESSION_SEATS_AVAILABLE BIGINT      
 DECLARE @SESSION_CPD_POINTS BIGINT      
 DECLARE @SESSION_REMARKS NVARCHAR(500)      
 DECLARE @SESSION_LOCATION NVARCHAR(200)      
 DECLARE @SESSION_NO_OF_WAITING BIGINT      
 DECLARE @SESSION_WAITING_LIMIT_PERCENTAGE BIGINT      
 DECLARE @SESSION_WAITING_LIMIT_NUMBER BIGINT      
 DECLARE @SESSION_RATE_TYPE BIGINT      
 DECLARE @SESSION_RATE_TYPE_NAME NVARCHAR(100)      
 DECLARE @SESSION_SPEAKER_TUTOR BIGINT      
 DECLARE @SESSION_SPEAKER_TUTOR_NAME NVARCHAR(100)      

--drop table Temp_Event_Sessions
--select identity(bigint,1,1) as row_id , cast(1 as bigint) as event_seq_id , cast(1 as bigint) as session_seq_id into Temp_Event_Sessions from [SRM-CustomEntities]..CUS_ENTITY_DATA where seq_id =0  
--insert into  Temp_Event_Sessions(event_seq_id,session_seq_id) values(@m_EVENT_SEQ_ID,@m_CUS_ENTITY_DATA_SEQ_ID)
--select * from Temp_Event_Sessions
 
 
       
 SET @ERROR = 1      
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_EVENT_SESSIONS_DATA_TO_API]'      
       
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT_SESSION'      
      
 SELECT @WEB_SERVICE_EVENT_SESSIONS= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_EVENT_SESSIONS'      
       
 SELECT @EVENT_SETUP_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@EVENT_SETUP_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT'      
       
 SELECT        
   @EVENT_NAME   = EVE.ATTRIBUTE_001,      
   @EVENT_ID   = EVE.ATTRIBUTE_002,      
   @WEB    = EVE.ATTRIBUTE_045,      
   @EVENT_DELETED  = EVE.DELETED,      
   @EVENT_DATEDELETED = EVE.DATE_DELETED,      
   @EVENT_DELETEDBY = EVE.DELETED_BY,      
   @EVENT_DATEMODIFIED = EVE.DATE_MODIFIED,      
   @EVENT_MODIFIEDBY = EVE.MODIFIED_BY,      
   @EVENT_DATECREATED = EVE.DATE_CREATED,      
   @EVENT_CREATEDBY = EVE.CREATED_BY      
         
 FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVE WITH(NOLOCK)
 WHERE EVE.SRM_CLIENT_ENTITIES_SEQ_ID=@EVENT_SETUP_SRM_CLIENT_ENTITIES_SEQ_ID      
 AND SEQ_ID = @m_EVENT_SEQ_ID      
       
 IF @WEB='N' OR @EVENT_DELETED='Y'
 BEGIN      
     
   --SELECT SEQ_ID INTO #TEMP_EVENT_SESSIONS FROM  [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA    
   --WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @WEB_SERVICE_EVENT_SESSIONS       
   --AND ATTRIBUTE_002 = @m_EVENT_SEQ_ID      
     
   DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA  
   WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @WEB_SERVICE_EVENT_SESSIONS       
   AND SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID 
				  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
				  WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @WEB_SERVICE_EVENT_SESSIONS
				  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 287194
				  AND ISNULL(ATTRIBUTE_DECIMAL,0)=@m_CUS_ENTITY_DATA_SEQ_ID
				 ) --ATTRIBUTE_028 = @m_CUS_ENTITY_DATA_SEQ_ID      
    
   DELETE FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES     
   WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @WEB_SERVICE_EVENT_SESSIONS
   AND CUS_ENTITY_DATA_SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID 
				  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
				  WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @WEB_SERVICE_EVENT_SESSIONS
				  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 287194
				  AND ISNULL(ATTRIBUTE_DECIMAL,0)=@m_CUS_ENTITY_DATA_SEQ_ID
				 )       --=@m_CUS_ENTITY_DATA_SEQ_ID  --IN(SELECT SEQ_ID FROM #TEMP_EVENT_SESSIONS)    
       
 END      
 ELSE      
 BEGIN      
   IF ISNULL(@m_CUS_ENTITY_DATA_SEQ_ID,0)<=0 RETURN      
   
   
   --DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR       
   SELECT        
    @SESSION_SEQ_ID   = SEQ_ID,      
    @SESSION_ID    = ATTRIBUTE_001,      
    @SESSION_DATE_MODIFIED = DATE_MODIFIED,      
    @SESSION_MODIFIED_BY = MODIFIED_BY,      
    @SESSION_DATE_CREATED = DATE_CREATED,      
    @SESSION_CREATED_BY  = CREATED_BY,      
    @SESSION_DELETED  = DELETED,      
    @SESSION_DATE_DELETED = DATE_DELETED,      
    @SESSION_DELETED_BY  = DELETED_BY,      
    @SESSION_EVENT   = ATTRIBUTE_002,      
    @SESSION_EVENT_NAME  = ATTRIBUTE_003,      
    @SESSION_EVENT_STATUS = ATTRIBUTE_004,      
    @SESSION_EVENT_STATUS_DESCRIPTION = ATTRIBUTE_005,      
    @SESSION_TYPE   = ATTRIBUTE_006,      
    @SESSION_TYPE_NAME  = ATTRIBUTE_007,      
    @SESSION_DESCRIPTION = ATTRIBUTE_008,      
    @SESSION_FORMAL_TITLE = ATTRIBUTE_009,      
    @SESSION_START_DATE  = ATTRIBUTE_010,      
    @SESSION_END_DATE  = ATTRIBUTE_011,      
    @SESSION_START_TIME  = ATTRIBUTE_012,      
    @SESSION_END_TIME  = ATTRIBUTE_013,      
    @SESSION_MAXIMUM_SEATS_AVAILABLE = ATTRIBUTE_014,      
    @SESSION_TOTAL_BOOKINGS   = ATTRIBUTE_015,      
    @SESSION_SEATS_AVAILABLE  = ATTRIBUTE_016,      
    @SESSION_CPD_POINTS    = ATTRIBUTE_017,      
    @SESSION_REMARKS    = ATTRIBUTE_018,      
    @SESSION_LOCATION    = ATTRIBUTE_019,      
    @SESSION_NO_OF_WAITING   = ATTRIBUTE_020,      
    @SESSION_WAITING_LIMIT_PERCENTAGE = ATTRIBUTE_021,      
    @SESSION_WAITING_LIMIT_NUMBER = ATTRIBUTE_022,      
    @SESSION_RATE_TYPE    = ATTRIBUTE_023,      
    @SESSION_RATE_TYPE_NAME   = ATTRIBUTE_024,      
    @SESSION_SPEAKER_TUTOR   = ATTRIBUTE_025,      
    @SESSION_SPEAKER_TUTOR_NAME  = ATTRIBUTE_026      
      
   FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
   WHERE SEQ_ID = @m_CUS_ENTITY_DATA_SEQ_ID      
      AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
      --AND ISNULL(DELETED,'N')='N'
      
   Print 'here'
  
   IF EXISTS(SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
    WHERE SRM_CLIENT_ENTITIES_SEQ_ID =@WEB_SERVICE_EVENT_SESSIONS   
    AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID  
             FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)  
             WHERE SRM_CLIENT_ENTITIES_SEQ_ID =@WEB_SERVICE_EVENT_SESSIONS  
             AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =  287194  
             AND ISNULL(ATTRIBUTE_DECIMAL,0)=@m_CUS_ENTITY_DATA_SEQ_ID  
             )--ATTRIBUTE_028 = cast(@m_CUS_ENTITY_DATA_SEQ_ID as nvarchar(20))
     AND ISNULL(DELETED,'N')='N'  
   )      
   BEGIN      
          
    Print 'Update'      
          
    UPDATE [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SET      
     ATTRIBUTE_001=@SESSION_ID,      
     ATTRIBUTE_002=@SESSION_EVENT,      
     ATTRIBUTE_003=@SESSION_EVENT_NAME,      
     ATTRIBUTE_004=@SESSION_EVENT_STATUS,      
     ATTRIBUTE_005=@SESSION_EVENT_STATUS_DESCRIPTION,      
     ATTRIBUTE_006=@SESSION_TYPE,      
     ATTRIBUTE_007=@SESSION_TYPE_NAME,      
     ATTRIBUTE_008=@SESSION_DESCRIPTION,      
     ATTRIBUTE_009=@SESSION_FORMAL_TITLE,      
     ATTRIBUTE_010=@SESSION_START_DATE,      
     ATTRIBUTE_011=@SESSION_END_DATE,      
     ATTRIBUTE_012=@SESSION_START_TIME,      
     ATTRIBUTE_013=@SESSION_END_TIME,      
     ATTRIBUTE_014=@SESSION_MAXIMUM_SEATS_AVAILABLE,      
     ATTRIBUTE_015=@SESSION_TOTAL_BOOKINGS,      
     ATTRIBUTE_016=@SESSION_SEATS_AVAILABLE,      
     ATTRIBUTE_017=@SESSION_CPD_POINTS,      
     ATTRIBUTE_018=@SESSION_REMARKS,      
     ATTRIBUTE_019=@SESSION_LOCATION,      
     ATTRIBUTE_020=@SESSION_NO_OF_WAITING,      
     ATTRIBUTE_021=@SESSION_WAITING_LIMIT_PERCENTAGE,      
     ATTRIBUTE_022=@SESSION_WAITING_LIMIT_NUMBER,      
     ATTRIBUTE_023=@SESSION_RATE_TYPE,      
     ATTRIBUTE_024=@SESSION_RATE_TYPE_NAME,       
     ATTRIBUTE_025=@SESSION_SPEAKER_TUTOR,      
     ATTRIBUTE_026=@SESSION_SPEAKER_TUTOR_NAME,      
     ATTRIBUTE_027=@EVENT_ID,      
     --ATTRIBUTE_028=@m_CUS_ENTITY_DATA_SEQ_ID,      
     SRM_CLIENTS_SEQ_ID=@m_CLIENT_SEQ_ID,      
     --DATE_CREATED=@SESSION_DATE_CREATED,      
     --CREATED_BY=@SESSION_CREATED_BY,      
     DATE_MODIFIED=@SESSION_DATE_MODIFIED,      
     MODIFIED_BY=@SESSION_MODIFIED_BY,      
     DELETED = @SESSION_DELETED,      
     DATE_DELETED = @SESSION_DATE_DELETED,      
     DELETED_BY = @SESSION_DELETED_BY      
    WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @WEB_SERVICE_EVENT_SESSIONS       
    AND SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID 
				  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
				  WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @WEB_SERVICE_EVENT_SESSIONS
				  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 287194
				  AND ISNULL(ATTRIBUTE_DECIMAL,0)=@m_CUS_ENTITY_DATA_SEQ_ID
				 ) --ATTRIBUTE_028 = @m_CUS_ENTITY_DATA_SEQ_ID      
	--AND ISNULL(DELETED,'N')='N' 
   END      
   ELSE      
    BEGIN  
    
    --if deleted from oomi
    IF ISNULL(@SESSION_DELETED,'N')='Y' RETURN
        
     Print 'INSERT'      
     EXEC  [DBO].[GET_INSERT_CUS_ENTITY_DATA]      
     @SRM_CLIENT_ENTITIES_SEQ_ID=@WEB_SERVICE_EVENT_SESSIONS,      
     @ATTRIBUTE_001=@SESSION_ID,      
     @ATTRIBUTE_002=@SESSION_EVENT,      
     @ATTRIBUTE_003=@SESSION_EVENT_NAME,      
     @ATTRIBUTE_004=@SESSION_EVENT_STATUS,      
     @ATTRIBUTE_005=@SESSION_EVENT_STATUS_DESCRIPTION,      
     @ATTRIBUTE_006=@SESSION_TYPE,      
     @ATTRIBUTE_007=@SESSION_TYPE_NAME,      
     @ATTRIBUTE_008=@SESSION_DESCRIPTION,      
     @ATTRIBUTE_009=@SESSION_FORMAL_TITLE,      
     @ATTRIBUTE_010=@SESSION_START_DATE,      
     @ATTRIBUTE_011=@SESSION_END_DATE,      
     @ATTRIBUTE_012=@SESSION_START_TIME,      
     @ATTRIBUTE_013=@SESSION_END_TIME,      
     @ATTRIBUTE_014=@SESSION_MAXIMUM_SEATS_AVAILABLE,      
     @ATTRIBUTE_015=@SESSION_TOTAL_BOOKINGS,      
     @ATTRIBUTE_016=@SESSION_SEATS_AVAILABLE,      
     @ATTRIBUTE_017=@SESSION_CPD_POINTS,      
     @ATTRIBUTE_018=@SESSION_REMARKS,      
     @ATTRIBUTE_019=@SESSION_LOCATION,      
     @ATTRIBUTE_020=@SESSION_NO_OF_WAITING,      
     @ATTRIBUTE_021=@SESSION_WAITING_LIMIT_PERCENTAGE,      
	 @ATTRIBUTE_022=@SESSION_WAITING_LIMIT_NUMBER,      
     @ATTRIBUTE_023=@SESSION_RATE_TYPE,      
     @ATTRIBUTE_024=@SESSION_RATE_TYPE_NAME,       
     @ATTRIBUTE_025=@SESSION_SPEAKER_TUTOR,      
     @ATTRIBUTE_026=@SESSION_SPEAKER_TUTOR_NAME,      
     @ATTRIBUTE_027=@EVENT_ID,      
     @ATTRIBUTE_028=@m_CUS_ENTITY_DATA_SEQ_ID,      
     @SRM_CLIENTS_SEQ_ID=@m_CLIENT_SEQ_ID,      
     @DATE_CREATED=@SESSION_DATE_CREATED,      
     @CREATED_BY=@SESSION_CREATED_BY,      
     @DATE_MODIFIED=@SESSION_DATE_MODIFIED,      
     @MODIFIED_BY=@SESSION_MODIFIED_BY,      
      
     @RETURN_SEQ_ID=@NEW_SEQ_ID OUTPUT,      
     @ERROR=@ERROR OUTPUT,      
     @ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT       
    END      
 END      
 SET @ERROR = 0      
 SET @ERROR_DESCRIPTION = ''      
END



;






/*
exec  [dbo].[GET_APPLY_MEMBERSHIP_DATA_TO_API]
	@SRM_CLIENTS_SEQ_ID = 17
*/
-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_APPLY_MEMBERSHIP_DATA_TO_API]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_MEMBERSHIP_DATA_TO_API]'

	EXEC [DBO].[GET_POPULATE_MEMBERSHIP_MASTER_CATEGORY]
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION
	
	EXEC [DBO].[GET_POPULATE_MEMBERSHIP_CATEGORY]
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION
		
	EXEC [DBO].[GET_POPULATE_MEMBERSHIP_CATEGORY_DETAIL]
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION

	EXEC [DBO].[GET_POPULATE_COUNTY]
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION
					
	EXEC [DBO].[GET_POPULATE_COUNTRY]
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION

	EXEC [dbo].[GET_POPULATE_JOB_CATEGORY] 
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION

	EXEC [dbo].[GET_POPULATE_DISCOUNT_CODE] 
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION	 

	EXEC [dbo].[GET_POPULATE_MARKETING_SOURCE] 
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION	 

	EXEC [dbo].[GET_POPULATE_ORGANISATION_TYPE] 
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION	 

	EXEC [dbo].[GET_POPULATE_TITLE] 
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION	 

	EXEC [dbo].[GET_POPULATE_AREA_OF_FOCUS] 
		@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION	
		
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
	
END





;





