CREATE PROCEDURE [dbo].[GET_APPLY_MEMBERSHIP_DATA_TO_STARGET]    
 -- Add the parameters for the stored procedure here    
 @EXTERNAL_RECORD_ID BIGINT = NULL,    
 @EXTERNAL_ID NVARCHAR(100) = NULL,    
 @USER NVARCHAR(100) = NULL,    
 @SRM_CLIENTS_SEQ_ID BIGINT = NULL,    
 @ERROR SMALLINT = NULL OUTPUT,    
 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT,
 @OUPUT_MEMBER_ID BIGINT = NULL OUTPUT ,
 @OUTPUT_PAYMENTBATCH_TRANSACTION_SEQ_ID BIGINT = NULL OUTPUT
AS    
BEGIN    
 -- SET NOCOUNT ON added to prevent extra result sets from    
 -- interfering with SELECT statements.    
 SET NOCOUNT ON; 
    
SET @ERROR = 0
SET @OUPUT_MEMBER_ID = 0
SET @OUTPUT_PAYMENTBATCH_TRANSACTION_SEQ_ID = 0 

 IF ISNULL(@EXTERNAL_RECORD_ID, 0) = 0 RETURN 
     
 PRINT 'I AM IN [dbo].[GET_APPLY_MEMBERSHIP_DATA_TO_STARGET]'    
    
 SET @ERROR = 1    
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_MEMBERSHIP_DATA_TO_STARGET]'    
    
 DECLARE @TODAY NVARCHAR(30)    
 SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)
    
 DECLARE @OLD_MEMBER_CATEGORY NVARCHAR(100)    
