 DECLARE @BANK_NAME NVARCHAR(100)    
 DECLARE @BANK_BRANCH NVARCHAR(100)    
 DECLARE @BANK_BRANCH_NAME NVARCHAR(100)    
 DECLARE @DIRECT_DEBIT_PAYMENT_FREQUENCY NVARCHAR(1)    
 DECLARE @CATEGORY_DATE NVARCHAR(100)    
 DECLARE @STATUS NVARCHAR(100)    
 DECLARE @STATUS_DESCRIPTION NVARCHAR(100)    
 DECLARE @STATUS_DATE NVARCHAR(100)    
