 DECLARE @DISCOUNT_CODE NVARCHAR(100)    
 DECLARE @DISCOUNT_CODE_NAME NVARCHAR(100)    
 DECLARE @NUMBER_OF_LOGINS NVARCHAR(100)    
 DECLARE @MEMBERSHIP_PACK_SENT NVARCHAR(100)    
 DECLARE @PACK_SENT_DATE NVARCHAR(100)    
 DECLARE @BRANCH_SORT_CODE NVARCHAR(50)    
