 DECLARE @ORGANISATION_ID NVARCHAR(100)    
 DECLARE @END_OF_FIRST_YEAR_DATE NVARCHAR(100)    
 DECLARE @SALE_ID NVARCHAR(100)    
 DECLARE @USER_NAME NVARCHAR(100)    
 DECLARE @PIVOT_RETURN_VALUE NVARCHAR(100)    
 DECLARE @ADDITIONAL_RATE_SEQ_ID BIGINT    
 DECLARE @PAYMENT_TYPE NVARCHAR(2) --ADDED BY ASAD    
    
 DECLARE @ADDITIONAL_PAYMENT_AMOUNT_NET MONEY    
 DECLARE @ADDITIONAL_PAYMENT_AMOUNT_VAT MONEY    
 DECLARE @ADDITIONAL_PAYMENT_AMOUNT_GROSS MONEY    
 DECLARE @OLD_STATUS_ARCHIVE CHAR(1)    
 DECLARE @NEW_STATUS_ARCHIVE CHAR(1)    
    
 DECLARE @IS_NEW_MEMBER CHAR(1)    
    
 DECLARE @ENTITY_DISPLAY_NAME_WSMAR NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR BIGINT    
 SET @ENTITY_DISPLAY_NAME_WSMAR = 'WEB_SERVICE_MEMBERSHIP_ADDITIONAL_RATE'    
    
 DECLARE @ENTITY_DISPLAY_NAME_MEMBER NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER BIGINT    
 SET @ENTITY_DISPLAY_NAME_MEMBER = 'MEMBER'    
    
 DECLARE @ENTITY_DISPLAY_NAME_ACCOUNT NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT BIGINT    
 SET @ENTITY_DISPLAY_NAME_ACCOUNT = 'ACCOUNT'    
    
 DECLARE @ENTITY_DISPLAY_NAME_CONTACT NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT BIGINT    
 SET @ENTITY_DISPLAY_NAME_CONTACT = 'CONTACT'    
     
 DECLARE @ENTITY_DISPLAY_NAME_WSM NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSM BIGINT    
 SET @ENTITY_DISPLAY_NAME_WSM = 'WEB_SERVICE_MEMBERSHIP'    
    
 DECLARE @ENTITY_DISPLAY_NAME_WSMH NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSMH BIGINT    
 SET @ENTITY_DISPLAY_NAME_WSMH = 'WEB_SERVICE_MEMBERSHIP_HISTORY'    
    
 DECLARE @ENTITY_DISPLAY_NAME_WSMC NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSMC BIGINT    
 SET @ENTITY_DISPLAY_NAME_WSMC = 'WEB_SERVICE_MEMBERSHIP_CATEGORY'    
    
 DECLARE @ENTITY_DISPLAY_NAME_MC NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MC BIGINT    
 SET @ENTITY_DISPLAY_NAME_MC = 'MEMBER_CATEGORY'    
    
 DECLARE @ENTITY_DISPLAY_NAME_MBH NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MBH BIGINT    
 SET @ENTITY_DISPLAY_NAME_MBH = 'MEMBER_BANK_HISTORY'    
    
 DECLARE @ENTITY_DISPLAY_NAME_BANK NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_BANK BIGINT    
 SET @ENTITY_DISPLAY_NAME_BANK = 'BANK'    
    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSM = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSM     
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSMH = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSMH     
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MEMBER    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_ACCOUNT    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_CONTACT    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSMC = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSMC    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSMAR    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MC = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MC    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MBH = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MBH    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_BANK = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_BANK    
     
 EXEC [DBO].[GET_CREATE_ENTITY_DATA_HISTORY]    
  @MAIN_ENTITY_RECORD_ID = @EXTERNAL_RECORD_ID,    
  @SRM_CLIENT_ENTITIES_SEQ_ID_MAIN_ENTITY = @SRM_CLIENT_ENTITIES_SEQ_ID_WSM,    
  @SRM_CLIENT_ENTITIES_SEQ_ID_HISTORY_ENTITY = @SRM_CLIENT_ENTITIES_SEQ_ID_WSMH,    
  @USER = @USER,    
  @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
  @ERROR = @ERROR OUTPUT,    
  @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
     
 IF EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK) WHERE SEQ_ID = @EXTERNAL_RECORD_ID AND ATTRIBUTE_019='GB')
 BEGIN
	UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA SET ATTRIBUTE_019='United Kingdom' WHERE SEQ_ID = @EXTERNAL_RECORD_ID

	UPDATE [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES SET ATTRIBUTE_STRING='United Kingdom' WHERE CUS_ENTITY_DATA_SEQ_ID=@EXTERNAL_RECORD_ID AND
	SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=55301 
 END
     
 SET @IS_NEW_MEMBER = 'N'    
      
 SELECT     
  @USER_NAME = ATTRIBUTE_041,    
  @PAY_BY_INVOICE = CASE WHEN ATTRIBUTE_009 IN ('Y', 'Yes', 'True') THEN 'Y' ELSE 'N' END,    
  @DIRECT_DEBIT = CASE WHEN ATTRIBUTE_064 IN ('Y', 'Yes', 'True') THEN 'Y' ELSE 'N' END,    
  @MEMBER_CATEGORY_NAME = ltrim(ATTRIBUTE_042),    
  @PAYMENT_AMOUNT = ATTRIBUTE_044,    
  @MEMBER_ID = ATTRIBUTE_045,    
  @DEPARTMENTAL_MEMBER_ID = ATTRIBUTE_046,    
  @TRANSACTION_TYPE = ATTRIBUTE_053,    
  @PURCHASE_ORDER_NUMBER = ATTRIBUTE_054,    
  @DISCOUNT_CODE_NAME = ATTRIBUTE_055,    
  @PAYMENT_AMOUNT_NET = ATTRIBUTE_056,    
  @PAYMENT_AMOUNT_VAT = ATTRIBUTE_057,    
  @COURSE_END_DATE = ATTRIBUTE_059,    
  @END_OF_FIRST_YEAR_DATE = ATTRIBUTE_060,    
  @SALE_ID = ATTRIBUTE_061,
  @CREDIT_CARD = ATTRIBUTE_069,    
  @BRANCH_SORT_CODE = ATTRIBUTE_070,    
  @BANK_BUILDING_SOCIETY_ACCOUNT_NUMBER = ATTRIBUTE_071,    
  @NAME_OF_ACCOUNT_HOLDER = ATTRIBUTE_072,    
  @I_AM_ACCOUNT_HOLDER = ATTRIBUTE_073,    
  @DIRECT_DEBIT_PAYMENT_FREQUENCY = ATTRIBUTE_074,    
  @PAYMENT_TYPE = ATTRIBUTE_076, --ADDED BY ASAD    
  @HAS_MEMBERSHIP_TAGS = CASE WHEN ATTRIBUTE_077 IN ('Y', 'Yes', 'True') THEN 'Y' ELSE 'N' END,    
  @MEMBERSHIP_TAGS = ATTRIBUTE_075,
  @MEMBERSHIP_STATUS = ATTRIBUTE_068

 ,@PRIVACY_POLICY_AGREEMENT = CASE WHEN ATTRIBUTE_080 IN('Y','Yes','True') THEN 'Y' ELSE 'N' END
 ,@PRIVACY_POLICY_AGREEMENT_DATE = ATTRIBUTE_081
 ,@TS_CS_AGREEMENT =CASE WHEN ATTRIBUTE_082 IN('Y','Yes','True') THEN 'Y' ELSE 'N' END
 ,@TS_CS_AGREEMENT_DATE =ATTRIBUTE_083

 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
 AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSM 
 AND SEQ_ID = @EXTERNAL_RECORD_ID    
 

 IF ISNULL(@MEMBER_ID,'')<>''
 BEGIN
	SET @OUPUT_MEMBER_ID = @MEMBER_ID
 END 



 IF ISNULL(@PAYMENT_AMOUNT_NET,0) = 0    
 BEGIN    
  SET @PAYMENT_AMOUNT_NET = @PAYMENT_AMOUNT    
    
  UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
  SET ATTRIBUTE_056 = @PAYMENT_AMOUNT    
  WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
  AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSM 
  AND SEQ_ID = @EXTERNAL_RECORD_ID    
 END    
    
 EXEC [dbo].[GET_CREATE_UPDATE_ACCOUNT_CONTACT_MEMBERSHIP_IMPORT]    
  @EXTERNAL_RECORD_ID = @EXTERNAL_RECORD_ID,    
  @EXTERNAL_ID = @SALE_ID,    
  @USER = @USER,    
  @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
  @CONTACT = @CONTACT OUTPUT,    
  @ACCOUNT = @ACCOUNT OUTPUT,    
  @ERROR = @ERROR OUTPUT,    
  @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
    
 SET @ORGANISATION_ID = CAST(@ACCOUNT AS NVARCHAR(20))    

--AS CHANGE START MOVE FROM BELOW
    -- ACCOUNT    
  SELECT @ACCOUNT_NAME = ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT AND SEQ_ID = @ACCOUNT    
  -- CONTACT    
  SELECT @CONTACT_NAME = ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT AND SEQ_ID = @CONTACT    
--AS CHANGE END
    
 PRINT 'I AM BACK IN [dbo].[GET_APPLY_MEMBERSHIP_DATA_TO_STARGET]'    
     
 IF ISNULL(@MEMBER_ID, '') = '' -- NEW MEMBER    
 BEGIN    
  SET @IS_NEW_MEMBER = 'Y'    
  PRINT 'MEMBER ID IS BLANK'    
    
  EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 4, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @MEMBER_ID OUTPUT    
  SET @JOIN_DATE = @TODAY    
      
  -- GET PAYMENT METHOD    
  IF ISNULL(@DIRECT_DEBIT, 'N') = 'Y'    
   EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_METHOD', @ATTRIBUTE_DISPLAY_NAME = 'DIRECT_DEBIT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_METHOD OUTPUT, @DESCRIPTION = @PAYMENT_METHOD_NAME OUTPUT     
  ELSE IF ISNULL(@PAY_BY_INVOICE, 'N') = 'Y'     
   EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_METHOD', @ATTRIBUTE_DISPLAY_NAME = 'DEFAULT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_METHOD OUTPUT, @DESCRIPTION = @PAYMENT_METHOD_NAME OUTPUT    
  ELSE IF ISNULL(@CREDIT_CARD, 0) = 1    
   EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_METHOD', @ATTRIBUTE_DISPLAY_NAME = 'PAYPAL_CREDIT_CARD', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_METHOD OUTPUT, @DESCRIPTION
= @PAYMENT_METHOD_NAME OUTPUT    
  ELSE IF ISNULL(@CREDIT_CARD, 0) = 2    
   EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_METHOD', @ATTRIBUTE_DISPLAY_NAME = 'SAGEPAY_CREDIT_CARD', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_METHOD OUTPUT, @DESCRIPTION = @PAYMENT_METHOD_NAME OUTPUT    
  ELSE    
   EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_METHOD', @ATTRIBUTE_DISPLAY_NAME = 'ONLINE', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_METHOD OUTPUT, @DESCRIPTION = @PAYMENT_METHOD_NAME OUTPUT    
    
  -- GET STATUS    
  EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MEMBER_STATUS_TYPE', @ATTRIBUTE_DISPLAY_NAME = 'CURRENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @STATUS OUTPUT, @DESCRIPTION = @STATUS_DESCRIPTION OUTPUT     
  SET @STATUS_DATE = @TODAY    
     
  -- GET FREQUENCY    
  IF @DIRECT_DEBIT_PAYMENT_FREQUENCY = 'M'    
  BEGIN    
   EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_FREQUENCY', @ATTRIBUTE_DISPLAY_NAME = 'INCREMENT_MONTH', @OPERATOR_ID = 3, @SEARCH_VALUE = '1', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_FREQUENCY OUTPUT, @DESCRIPTION = @PAYMENT_FREQUENCY_DESCRIPTION OUTPUT    
   SET @TOTAL_INSTALLMENTS = 12    
  END    
  ELSE IF @DIRECT_DEBIT_PAYMENT_FREQUENCY = 'Y'     
  BEGIN    
   EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_FREQUENCY', @ATTRIBUTE_DISPLAY_NAME = 'INCREMENT_MONTH', @OPERATOR_ID = 3, @SEARCH_VALUE = '12', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_FREQUENCY OUTPUT, @DESCRIPTION = @PAYMENT_FREQUENCY_DESCRIPTION OUTPUT    
   SET @TOTAL_INSTALLMENTS = 1    
  END    
  ELSE    
  BEGIN    
   EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_FREQUENCY', @ATTRIBUTE_DISPLAY_NAME = 'DEFAULT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_FREQUENCY OUTPUT, @DESCRIPTION = @PAYMENT_FREQUENCY_DESCRIPTION OUTPUT    
   SET @TOTAL_INSTALLMENTS = 1    
