			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
			@ERROR = @ERROR OUTPUT,    
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT      
    END
     
  END    
    
  DECLARE CUR_ADDITIONAL_RATES CURSOR LOCAL STATIC FOR    
   SELECT SEQ_ID 
   FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
   WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
   AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR
   --AND ATTRIBUTE_002 = @SALE_ID    
   AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57036 AND ISNULL(ATTRIBUTE_STRING,'')=@SALE_ID)
   
  OPEN CUR_ADDITIONAL_RATES    
    
  FETCH NEXT FROM CUR_ADDITIONAL_RATES INTO @ADDITIONAL_RATE_SEQ_ID    
    
  WHILE @@FETCH_STATUS = 0    
  BEGIN    
   UPDATE CUS_ENTITY_DATA SET ATTRIBUTE_004 = ISNULL(ATTRIBUTE_004, '0.00'), ATTRIBUTE_003 = CASE WHEN CAST(ISNULL(ATTRIBUTE_003, '0.00') AS Money) = 0 THEN ATTRIBUTE_005 ELSE ATTRIBUTE_003 END    
   FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR AND SEQ_ID = @ADDITIONAL_RATE_SEQ_ID    
       
   EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
    @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR,    
    @CUS_ENTITY_DATA_SEQ_ID = @ADDITIONAL_RATE_SEQ_ID,    
    @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
    @ERROR = @ERROR OUTPUT,    
    @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
    
   FETCH NEXT FROM CUR_ADDITIONAL_RATES INTO @ADDITIONAL_RATE_SEQ_ID    
  END    
    
  CLOSE CUR_ADDITIONAL_RATES    
  DEALLOCATE CUR_ADDITIONAL_RATES    
     
  SET @TOTAL_OUTSTANDING = ISNULL(@PAYMENT_AMOUNT_NET, 0) + ISNULL(@PAYMENT_AMOUNT_VAT, 0)     
