  --IF @ADDITIONAL_PAYMENT_AMOUNT_GROSS > 0    
  --BEGIN    
  -- SET @TOTAL_OUTSTANDING = CAST(@TOTAL_OUTSTANDING AS MONEY) + @ADDITIONAL_PAYMENT_AMOUNT_GROSS    
  -- SET @PAYMENT_AMOUNT = @PAYMENT_AMOUNT + @ADDITIONAL_PAYMENT_AMOUNT_GROSS    
  --END    
    
