  SET @NEXT_RENEWAL_DATE = CONVERT(VARCHAR(10), DATEADD(yy, 1, DATEADD(dd,-(DAY(DATEADD(mm,1,GETDATE()))-1),DATEADD(mm,1,GETDATE()))),121) 
  
