    @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
       
   --IF ISNULL(@PAY_BY_INVOICE, 'N') = 'N' AND ISNULL(@DIRECT_DEBIT, 'N') = 'N'    
