    @ATTRIBUTE_018 = @CONTACT_NAME_TEMP,    
    @ATTRIBUTE_019 = NULL,  -- BANK   
    @ATTRIBUTE_020 = NULL,  -- BANK NAME  
    @ATTRIBUTE_021 = @CATEGORY_DATE,    
    @ATTRIBUTE_022 = @STATUS,    
    @ATTRIBUTE_023 = @STATUS_DESCRIPTION,    
    @ATTRIBUTE_024 = @STATUS_DATE,    
    @ATTRIBUTE_025 = @PAYMENT_FREQUENCY,    
    @ATTRIBUTE_026 = @PAYMENT_FREQUENCY_DESCRIPTION,    
    @ATTRIBUTE_027 = @DD_FLAG,    
    @ATTRIBUTE_028 = '0.00', -- @TOTAL_OUTSTANDING,    
    @ATTRIBUTE_029 = @ACCOUNT, --@PAID_BY,     
    @ATTRIBUTE_030 = @ACCOUNT_NAME, -- @PAID_BY_NAME,     
    @ATTRIBUTE_031 = @ARCHIVE,    
    @ATTRIBUTE_032 = @LAST_DD_RUN,    
    @ATTRIBUTE_033 = @NEXT_RENEWAL_CATEGORY,    
    @ATTRIBUTE_034 = @NEXT_RENEWAL_CATEGORY_NAME,    
    @ATTRIBUTE_035 = '0.00', -- @CURRICULUM_CREDITS,    
    @ATTRIBUTE_038 = @MARKETING_CAMPAIGN,    
    @ATTRIBUTE_039 = @PURCHASE_ORDER_NUMBER,    
    @ATTRIBUTE_040 = @COURSE_END_DATE,    
    @ATTRIBUTE_041 = @MARKETING_CAMPAIGN_NAME,    
    @ATTRIBUTE_042 = @DISCOUNT_CODE,    
    @ATTRIBUTE_043 = @DISCOUNT_CODE_NAME,    
    @ATTRIBUTE_044 = NULL, -- @NUMBER_OF_LOGINS,    
    @ATTRIBUTE_045 = @MEMBERSHIP_PACK_SENT,    
    @ATTRIBUTE_046 = @PACK_SENT_DATE,    
    -- added Sale ID, Pay By Invoice and Pay by DD fields - Start    
    @ATTRIBUTE_047 = @SALE_ID,    
    @ATTRIBUTE_048 = @PAY_BY_INVOICE,    
    @ATTRIBUTE_049 = @DIRECT_DEBIT,    
    -- added Sale ID, Pay By Invoice and Pay by DD fields - End    
	@ATTRIBUTE_067 = 0, --MONTHS_OF_MEMBERSHIP
    @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER,    
    @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
    @DATE_CREATED = NULL,    
    @CREATED_BY = @USER,    
    @RETURN_SEQ_ID = @CONTACT_MEMBER OUTPUT,    
    @ERROR = @ERROR OUTPUT,    
    @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
        
		
		--SET @OUPUT_MEMBER_ID = @CONTACT_MEMBER_ID

    --Setting the member status of contact    
        
    UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
    SET ATTRIBUTE_144 = @STATUS,    
    ATTRIBUTE_145 = @STATUS_DESCRIPTION    
    WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT AND SEQ_ID = @CONTACT_TEMP    
    
   EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
    @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT,    
    @CUS_ENTITY_DATA_SEQ_ID = @CONTACT_TEMP,    
    @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
    @ERROR = @ERROR OUTPUT,    
    @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
        
   IF ISNULL(@CONTACT_MEMBER, 0) > 0    
   BEGIN    
    EXEC [dbo].[GET_POPULATE_MEMBERSHIP]     
     @CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
     @CUS_ENTITY_DATA_SEQ_ID = @CONTACT_MEMBER,    
     @ERROR = @ERROR OUTPUT,    
     @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
   END        
        
  END    
      
 END    
 ELSE    
 BEGIN    
  PRINT 'MEMBER ID IS NOT BLANK'    
  EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER, @ATTRIBUTE_DISPLAY_NAME = 'MEMBER_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @MEMBER_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MEMBER OUTPUT, @DESCRIPTION = @MEMBER_ID OUTPUT    
      
  SELECT @OLD_MEMBER_CATEGORY = ATTRIBUTE_013,     
  @OLD_MEMBER_CATEGORY_NAME = ATTRIBUTE_014,    
  @OLD_STATUS = ATTRIBUTE_022,     
  @OLD_STATUS_DESCRIPTION = ATTRIBUTE_023,    
  @OLD_STATUS_DATE = ATTRIBUTE_024,    
  @ARCHIVE = ATTRIBUTE_031,    
  @END_DATE = ATTRIBUTE_003,    
  @REINSTATE_DATE = ATTRIBUTE_004,    
  @CONTACT = ATTRIBUTE_017,    
  @ACCOUNT = ATTRIBUTE_015,
  --AS CHANGE START
  @OLD_PAYMENT_METHOD = ATTRIBUTE_009,
  @OLD_BANK = ATTRIBUTE_019,
  @OLD_PAYMENT_FREQUENCY = ATTRIBUTE_025,
  @OLD_NEXT_RENEWAL_DATE =  CONVERT(VARCHAR(10), ATTRIBUTE_005,121)
  --AS CHANGE END    
  FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA
  WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
  AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
  AND SEQ_ID = @MEMBER    

  --MQ GDPR
  IF ISNULL(@CONTACT,0)>0
  BEGIN
		UPDATE DATAProtectionFields SET 
		ATTRIBUTE_190 = ISNULL(@PRIVACY_POLICY_AGREEMENT ,DATAProtectionFields.ATTRIBUTE_190)
		,ATTRIBUTE_191 = ISNULL(@PRIVACY_POLICY_AGREEMENT_DATE , DATAProtectionFields.ATTRIBUTE_191)
		,ATTRIBUTE_192 = ISNULL(@TS_CS_AGREEMENT , DATAProtectionFields.ATTRIBUTE_192)
		,ATTRIBUTE_193 = ISNULL(@TS_CS_AGREEMENT_DATE , DATAProtectionFields.ATTRIBUTE_193)
		FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA DATAProtectionFields WITH(NOLOCK)
		WHERE SEQ_ID = @CONTACT

		EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT,
		@CUS_ENTITY_DATA_SEQ_ID = @CONTACT,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
  END

  


  --SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MST = SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = 'MEMBER_STATUS_TYPE'    
      
  --Get Status information    
  IF ISNULL(@MEMBERSHIP_STATUS, '') <> ''
  BEGIN    
   EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MEMBER_STATUS_TYPE', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @MEMBERSHIP_STATUS, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @STATUS OUTPUT, @DESCRIPTION = @STATUS_DESCRIPTION OUTPUT    
   SET @STATUS_DATE = @TODAY    
       
   SELECT @OLD_STATUS_ARCHIVE = ATTRIBUTE_008    
   FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA
   WHERE SEQ_ID = @OLD_STATUS    
      
   SELECT  @NEW_STATUS_ARCHIVE = ATTRIBUTE_008    
   FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA
   WHERE SEQ_ID = @STATUS    
       
   PRINT 'Malhan...'    
   PRINT @OLD_STATUS    
   PRINT @MEMBERSHIP_STATUS    
   PRINT @OLD_STATUS_ARCHIVE    
   PRINT @NEW_STATUS_ARCHIVE    
      
   IF ISNULL(@OLD_STATUS_ARCHIVE, 'N') = 'N' AND ISNULL(@NEW_STATUS_ARCHIVE, 'N') = 'Y'    
   BEGIN       
    SET @END_DATE = GETDATE()    
    SET @ARCHIVE = 'Y'    
   END    
   ELSE IF ISNULL(@OLD_STATUS_ARCHIVE, 'N') = 'Y' AND ISNULL(@NEW_STATUS_ARCHIVE, 'N') = 'N'    
   BEGIN       
    SET @REINSTATE_DATE = GETDATE()    
    SET @ARCHIVE = 'N'    
   END    
  END    
  ELSE    
  BEGIN    
   SET @STATUS = @OLD_STATUS    
   SET @STATUS_DESCRIPTION = @OLD_STATUS_DESCRIPTION    
   SET @STATUS_DATE = @OLD_STATUS_DATE    
  END      
      
  --Get Category information    
  IF ISNULL(@MEMBER_CATEGORY_NAME, '') <> ''     
   EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MEMBER_CATEGORY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @MEMBER_CATEGORY_NAME, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @NEW_MEMBER_CATEGORY OUTPUT, @DESCRIPTION = @NEW_MEMBER_CATEGORY_NAME OUTPUT    
      
  PRINT 'Hi'    
  PRINT @MEMBER_CATEGORY_NAME    
  PRINT @OLD_MEMBER_CATEGORY    
  PRINT @NEW_MEMBER_CATEGORY    
      
  IF @OLD_MEMBER_CATEGORY <> @NEW_MEMBER_CATEGORY    
  BEGIN    
   SET @MEMBER_CATEGORY = @NEW_MEMBER_CATEGORY    
   SET @MEMBER_CATEGORY_NAME = @NEW_MEMBER_CATEGORY_NAME    
  END    
  ELSE    
  BEGIN    
   SET @MEMBER_CATEGORY = @OLD_MEMBER_CATEGORY    
   SET @MEMBER_CATEGORY_NAME = @OLD_MEMBER_CATEGORY_NAME    
  END    

    PRINT 'DD CHANGES ON UPDATE MEMBER STARTS'
	
--AS CHANGE START
  IF (ISNULL(@DIRECT_DEBIT, 'N') = 'Y' OR @DIRECT_DEBIT = 'True')
  BEGIN  
	
	IF ISNULL(@BANK_BUILDING_SOCIETY_ACCOUNT_NUMBER,'') != '' AND ISNULL(@BRANCH_SORT_CODE,'') != '' AND ISNULL(@NAME_OF_ACCOUNT_HOLDER,'') != ''
		SET @DD_WITH_BANK_DEATIL = 'Y'

	IF @DD_WITH_BANK_DEATIL = 'Y'
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_METHOD', @ATTRIBUTE_DISPLAY_NAME = 'DIRECT_DEBIT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_METHOD OUTPUT, @DESCRIPTION = @PAYMENT_METHOD_NAME OUTPUT     


			--GET OR CREATE BANK
			EXEC [srm-framework_new].[dbo].[GET_CHECK_ACOUNT_CONTACT_BANK]
			@OLD_BANK = @OLD_BANK,
			@CONTACT = @CONTACT,
			@CONTACT_NAME = @CONTACT_NAME,
			@ACCOUNT = @ACCOUNT,
			@ACCOUNT_NAME = @ACCOUNT_NAME,
			@ACCOUNT_NUMBER=@BANK_BUILDING_SOCIETY_ACCOUNT_NUMBER,
			@SORT_CODE=@BRANCH_SORT_CODE,
			@ACCOUNT_TITLE = @NAME_OF_ACCOUNT_HOLDER,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@NEW_BANK = @BANK OUTPUT,
			@NEW_BANK_NAME = @BANK_NAME OUTPUT,
			@ERROR = @ERROR OUTPUT,    
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT 

			PRINT '@BANK: ' + CAST(@BANK AS NVARCHAR(100))
	

			IF @DIRECT_DEBIT_PAYMENT_FREQUENCY = 'M'    
			BEGIN    
				EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_FREQUENCY', @ATTRIBUTE_DISPLAY_NAME = 'INCREMENT_MONTH', @OPERATOR_ID = 3, @SEARCH_VALUE = '1', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_FREQUENCY OUTPUT, @DESCRIPTION = @PAYMENT_FREQUENCY_DESCRIPTION OUTPUT    
				SET @TOTAL_INSTALLMENTS = 12    
			END    
			ELSE IF @DIRECT_DEBIT_PAYMENT_FREQUENCY = 'Y'     
			BEGIN    
				EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_FREQUENCY', @ATTRIBUTE_DISPLAY_NAME = 'INCREMENT_MONTH', @OPERATOR_ID = 3, @SEARCH_VALUE = '12', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_FREQUENCY OUTPUT, @DESCRIPTION = @PAYMENT_FREQUENCY_DESCRIPTION OUTPUT    
				SET @TOTAL_INSTALLMENTS = 1    
			END    
			ELSE    
			BEGIN    
				EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_FREQUENCY', @ATTRIBUTE_DISPLAY_NAME = 'DEFAULT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_FREQUENCY OUTPUT, @DESCRIPTION = @PAYMENT_FREQUENCY_DESCRIPTION OUTPUT    
				SET @TOTAL_INSTALLMENTS = 1    
			END 

			SET @INSTALLMENTS_PAID = 0  

			-- DD DATES FOR MEMBER ENTITY    
			SET @MANDATE_ON_DATE = CONVERT(NVARCHAR(10), GETDATE(), 121)

			IF DAY(GETDATE()) <= 19    
				SET @FIRST_COLLECTION_DATE = CONVERT(NVARCHAR(10), DATEADD(MONTH, DATEDIFF(MONTH, 0, GETDATE()) + 1, 0), 121) -- 1ST OF NEXT MONTH   
			ELSE    
				SET @FIRST_COLLECTION_DATE = CONVERT(NVARCHAR(10), DATEADD(MONTH, DATEDIFF(MONTH, 0, GETDATE()) + 2, 0), 121) -- 1ST OF A MONTH AHEAD
    
	
    
			IF @DIRECT_DEBIT_PAYMENT_FREQUENCY = 'M'    
				SET @REGULAR_COLLECTION_DAY = CONVERT(NVARCHAR(10), DATEADD(MONTH, 1, @FIRST_COLLECTION_DATE), 121)
			ELSE    
				SET @REGULAR_COLLECTION_DAY = CONVERT(NVARCHAR(10), @OLD_NEXT_RENEWAL_DATE, 121) 
			-- END DD DATES FOR MEMBER ENTITY    
	END 

  END

  PRINT 'DD CHANGES ON UPDATE MEMBER STARTS'   
--AS CHANGE END
      
  PRINT 'before updaing member'    
  PRINT @MEMBER_CATEGORY_NAME    
  
  UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
  SET ATTRIBUTE_013 = @MEMBER_CATEGORY,    
   ATTRIBUTE_014 = @MEMBER_CATEGORY_NAME,    
   ATTRIBUTE_022 = @STATUS,    
   ATTRIBUTE_023 = @STATUS_DESCRIPTION,    
   ATTRIBUTE_024 = @STATUS_DATE,    
   ATTRIBUTE_053 = @HAS_MEMBERSHIP_TAGS,    
   ATTRIBUTE_057 = @MEMBERSHIP_TAGS,    
   ATTRIBUTE_031 = @ARCHIVE,    
   ATTRIBUTE_003 = @END_DATE,    
   ATTRIBUTE_004 = @REINSTATE_DATE,    
   --AS CHANGE START   
   ATTRIBUTE_049 = @DIRECT_DEBIT, 
   ATTRIBUTE_006 = CASE @DD_WITH_BANK_DEATIL WHEN 'Y' THEN @TOTAL_INSTALLMENTS ELSE ATTRIBUTE_006 END,
   ATTRIBUTE_009 = CASE @DD_WITH_BANK_DEATIL WHEN 'Y' THEN @PAYMENT_METHOD ELSE ATTRIBUTE_009 END,
   ATTRIBUTE_010 = CASE @DD_WITH_BANK_DEATIL WHEN 'Y' THEN @PAYMENT_METHOD_NAME ELSE ATTRIBUTE_010 END,
   ATTRIBUTE_019 = CASE @DD_WITH_BANK_DEATIL WHEN 'Y' THEN @BANK ELSE ATTRIBUTE_019 END,
   ATTRIBUTE_020 = CASE @DD_WITH_BANK_DEATIL WHEN 'Y' THEN @BANK_NAME ELSE ATTRIBUTE_020 END,
   ATTRIBUTE_025 = CASE @DD_WITH_BANK_DEATIL WHEN 'Y' THEN @PAYMENT_FREQUENCY ELSE ATTRIBUTE_025 END,    
   ATTRIBUTE_026 = CASE @DD_WITH_BANK_DEATIL WHEN 'Y' THEN @PAYMENT_FREQUENCY_DESCRIPTION ELSE ATTRIBUTE_026 END,
   ATTRIBUTE_050 = CASE @DD_WITH_BANK_DEATIL WHEN 'Y' THEN @MANDATE_ON_DATE ELSE ATTRIBUTE_050 END,
   ATTRIBUTE_051 = CASE @DD_WITH_BANK_DEATIL WHEN 'Y' THEN @FIRST_COLLECTION_DATE ELSE ATTRIBUTE_051 END,
   ATTRIBUTE_052 = CASE @DD_WITH_BANK_DEATIL WHEN 'Y' THEN @REGULAR_COLLECTION_DAY ELSE ATTRIBUTE_052 END,
   --AS CHANGE END
   MODIFIED_BY = @USER,    
   DATE_MODIFIED = GETDATE()    
   WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND SEQ_ID = @MEMBER    
      
  PRINT 'after updaing member'    
  PRINT @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT    
  PRINT @ACCOUNT    
  PRINT @CONTACT    
      
  EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
   @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER,    
   @CUS_ENTITY_DATA_SEQ_ID = @MEMBER,    
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
   @ERROR = @ERROR OUTPUT,    
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    

      --AS CHANGE START
	IF ISNULL(@OLD_BANK,0) != ISNULL(@BANK, 0) AND @DD_WITH_BANK_DEATIL = 'Y'-- IF BANK IS CHANGED AND BANK INFORMATION IS PROVIDED = 'Y'
	BEGIN	  
		  --START MEMBER_BANK_HISTORY
			SELECT @BANK_BRANCH = SEQ_ID, @BANK_BRANCH_NAME = ATTRIBUTE_002 
			FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
			WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
			AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_BANK
			AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_BANK AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52768 AND ISNULL(ATTRIBUTE_STRING,'')=@BRANCH_SORT_CODE)

		   EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]    
			@ATTRIBUTE_001 = NULL, --REMARKS    
			@ATTRIBUTE_002 = @BANK, --ACCOUNT_CONTACT_BANK    
			@ATTRIBUTE_003 = @BANK_NAME, --ACCOUNT_CONTACT_BANK_NAME    
			@ATTRIBUTE_004 = @BANK_BUILDING_SOCIETY_ACCOUNT_NUMBER, --ACCOUNT_NUMBER    
			@ATTRIBUTE_005 = @NAME_OF_ACCOUNT_HOLDER, --ACCOUNT_NAME    
			@ATTRIBUTE_006 = @NAME_OF_ACCOUNT_HOLDER, --ACCOUNT_TITLE    
			@ATTRIBUTE_007 = @BRANCH_SORT_CODE, --SORT_CODE    
			@ATTRIBUTE_008 = @BANK_BRANCH, --BANK    
			@ATTRIBUTE_009 = @BANK_BRANCH_NAME, --BANK_NAME    
			@ATTRIBUTE_010 = 'N', --EXPORTED    
			@ATTRIBUTE_011 = 'N', --REMOVED    
			@ATTRIBUTE_012 = NULL, --DATE_EXPORTED    
			@ATTRIBUTE_013 = @MEMBER, --MEMBER    
			@ATTRIBUTE_014 = @MEMBER_ID, --MEMBER_NAME    
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MBH,    
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
			@DATE_CREATED = NULL,    
			@CREATED_BY = @USER,    
			@RETURN_SEQ_ID = @MEMBER_BANK_HISTORY OUTPUT,    
			@ERROR = @ERROR OUTPUT,    
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
		  --END MEMBER_BANK_HISTORY
	END
    --AS CHANGE END   
       
  IF ISNULL(@STATUS, 0) != ISNULL(@OLD_STATUS, 0)    
  BEGIN    
   IF ISNULL(@CONTACT, 0) != 0    
   BEGIN    
    UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA    
    SET ATTRIBUTE_144 = @STATUS,    
    ATTRIBUTE_145 = @STATUS_DESCRIPTION,    
    MODIFIED_BY = @USER,    
    DATE_MODIFIED = GETDATE()    
    WHERE SEQ_ID = @CONTACT    
        
    EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
     @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT,    
     @CUS_ENTITY_DATA_SEQ_ID = @CONTACT,    
     @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
     @ERROR = @ERROR OUTPUT,    
     @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
   END    
   ELSE    
   BEGIN    
    UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA    
    SET ATTRIBUTE_110 = @STATUS,    
    ATTRIBUTE_111 = @STATUS_DESCRIPTION,    
    MODIFIED_BY = @USER,    
    DATE_MODIFIED = GETDATE()    
    WHERE SEQ_ID = @ACCOUNT    
        
    EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
     @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT,    
     @CUS_ENTITY_DATA_SEQ_ID = @ACCOUNT,    
     @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
     @ERROR = @ERROR OUTPUT,    
     @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
   END    
  END    
         
  --ADDED BY ASAD    
  IF (ISNULL(@PAYMENT_TYPE ,'N') = 'R' AND ISNULL(@PAYMENT_AMOUNT, 0) > 0)    
  BEGIN    
   EXEC [dbo].[GET_CREATE_RECEIPT_BATCH_MEMBERSHIP]    
    @EXTERNAL_RECORD_ID = @EXTERNAL_RECORD_ID,    
    @MEMBER = @MEMBER,    
    @PAYMENT_AMOUNT = @PAYMENT_AMOUNT,    
    @PAYMENT_METHOD = @PAYMENT_METHOD,    
    @PAYMENT_METHOD_NAME = @PAYMENT_METHOD_NAME,    
    @USER = @USER,    
    @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
    @ERROR = @ERROR OUTPUT,    
    @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT,
	@PAYMENT_BATCH_TRANSACTION_SEQ_ID = @OUTPUT_PAYMENTBATCH_TRANSACTION_SEQ_ID OUTPUT
  END       
  -------------------------------------------------------------------    
 END    
    
 IF @PAYMENT_TYPE IS NOT NULL    
 BEGIN    
  UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
   SET ATTRIBUTE_076 = NULL    
  WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSM AND SEQ_ID = @EXTERNAL_RECORD_ID    
       
  EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
   @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSM,    
   @CUS_ENTITY_DATA_SEQ_ID = @EXTERNAL_RECORD_ID,    
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
   @ERROR = @ERROR OUTPUT,    
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
    
  IF ISNULL(@CONTACT_MEMBER_ID, 0) > 0    
  BEGIN    
   EXEC [dbo].[GET_POPULATE_MEMBERSHIP]     
    @CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
    @CUS_ENTITY_DATA_SEQ_ID = @CONTACT_MEMBER_ID,    
    @ERROR = @ERROR OUTPUT,    
    @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
  END    
 END    
    
 -- insert into CUSTOMER_HISTORY    
 IF @IS_NEW_MEMBER = 'Y'    
 BEGIN    
  INSERT [SRM-CustomEntities].dbo.CUS_ENTITY_DATA    
  (    
   SRM_CLIENT_ENTITIES_SEQ_ID,    
   ATTRIBUTE_002,    
   ATTRIBUTE_003,    
   ATTRIBUTE_004,    
   ATTRIBUTE_005, --  ACCOUNT_NAME    
   ATTRIBUTE_006, --  LAST_NAME    
   ATTRIBUTE_007, --  FIRST_NAME    
   ATTRIBUTE_008, --  SORT_CODE    
   ATTRIBUTE_009, --  ACCOUNT_NUMBER    
   ATTRIBUTE_010, --  ADDRESS_LINE_1    
   ATTRIBUTE_011, --  ADDRESS_LINE_2    
   ATTRIBUTE_012, --  ADDRESS_LINE_3    
