   ATTRIBUTE_014, --  COUNTY_DESCRIPTION    
   ATTRIBUTE_015, --  POSTCODE    
   ATTRIBUTE_016, --  TEL    
   ATTRIBUTE_017, --  EMAIL    
   ATTRIBUTE_018, --  EMAIL_1    
   ATTRIBUTE_019, --  EXPORTED    
   ATTRIBUTE_020, --  DATE_EXPORTED    
   ATTRIBUTE_021, --  TITLE_NAME    
   SRM_CLIENTS_SEQ_ID,    
   CREATED_BY,    
   DATE_CREATED    
  )    
  SELECT     
   5524,     
   ACCOUNT.SEQ_ID,    
   CONTACT.SEQ_ID,    
   MEM.ATTRIBUTE_001 MEMBER_ID,    
   ACCOUNT.ATTRIBUTE_001 ACCOUNT_NAME,    
   CONTACT.ATTRIBUTE_004 LAST_NAME,    
   CONTACT.ATTRIBUTE_005 FIRST_NAME,    
   ACB.ATTRIBUTE_001 SORT_CODE,     
   ACB.ATTRIBUTE_002 ACCOUNT_NUMBER,     
   ADDRESS_LINE_1 = CASE WHEN ACCOUNT.SEQ_ID IS NOT NULL THEN ACCOUNT.ATTRIBUTE_114 ELSE CONTACT.ATTRIBUTE_149 END,    
   ADDRESS_LINE_2 = CASE WHEN ACCOUNT.SEQ_ID IS NOT NULL THEN ACCOUNT.ATTRIBUTE_115 ELSE CONTACT.ATTRIBUTE_150 END,    
   ADDRESS_LINE_3 = CASE WHEN ACCOUNT.SEQ_ID IS NOT NULL THEN ACCOUNT.ATTRIBUTE_116 ELSE CONTACT.ATTRIBUTE_151 END,    
   TOWN = CASE WHEN ACCOUNT.SEQ_ID IS NOT NULL THEN ACCOUNT.ATTRIBUTE_118 ELSE CONTACT.ATTRIBUTE_153 END,    
   COUNTY_DESCRIPTION = CASE WHEN ACCOUNT.SEQ_ID IS NOT NULL THEN ACCOUNT.ATTRIBUTE_121 ELSE CONTACT.ATTRIBUTE_156 END,    
   POSTCODE = CASE WHEN ACCOUNT.SEQ_ID IS NOT NULL THEN ACCOUNT.ATTRIBUTE_119 ELSE CONTACT.ATTRIBUTE_154 END,    
   TEL = CASE WHEN ACCOUNT.SEQ_ID IS NOT NULL THEN ACCOUNT.ATTRIBUTE_043 ELSE CONTACT.ATTRIBUTE_053 END,    
   EMAIL = CASE WHEN ACCOUNT.SEQ_ID IS NOT NULL THEN ACCOUNT.ATTRIBUTE_045 ELSE CONTACT.ATTRIBUTE_056 END,    
   EMAIL_1 = CASE WHEN ACCOUNT.SEQ_ID IS NOT NULL THEN NULL ELSE CONTACT.ATTRIBUTE_057 END,    
   'N' EXPORTED,     
   NULL DATE_EXPORTED,    
   CONTACT.ATTRIBUTE_026 TITLE_NAME,    
   @SRM_CLIENTS_SEQ_ID, @USER, @TODAY      
  FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA MEM WITH (NOLOCK)    
	   INNER JOIN [SRM-CustomEntities].dbo.CUS_ENTITY_DATA ACB WITH (NOLOCK) ON ACB.SRM_CLIENT_ENTITIES_SEQ_ID = 2576 AND ACB.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0) FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2541 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52015 AND CUS_ENTITY_DATA_SEQ_ID = MEM.SEQ_ID AND ISNULL(ATTRIBUTE_DECIMAL,0)=MEM.ATTRIBUTE_019 )   --= ISNULL(MEM.ATTRIBUTE_019, '0')  
	   LEFT OUTER JOIN [SRM-CustomEntities].dbo.CUS_ENTITY_DATA ACCOUNT WITH (NOLOCK) ON ACCOUNT.SRM_CLIENT_ENTITIES_SEQ_ID = 2525 AND ACCOUNT.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0) FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2541 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52011 AND CUS_ENTITY_DATA_SEQ_ID = MEM.SEQ_ID AND ISNULL(ATTRIBUTE_DECIMAL,0)=MEM.ATTRIBUTE_015 ) --= MEM.ATTRIBUTE_015
	   LEFT OUTER JOIN [SRM-CustomEntities].dbo.CUS_ENTITY_DATA CONTACT WITH (NOLOCK) ON CONTACT.SRM_CLIENT_ENTITIES_SEQ_ID = 2524 AND CONTACT.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0) FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2541 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52013 AND CUS_ENTITY_DATA_SEQ_ID = MEM.SEQ_ID AND ISNULL(ATTRIBUTE_DECIMAL,0)=MEM.ATTRIBUTE_017 )--= MEM.ATTRIBUTE_017
	   LEFT OUTER JOIN [SRM-CustomEntities].dbo.CUS_ENTITY_DATA BANK WITH (NOLOCK) ON BANK.SRM_CLIENT_ENTITIES_SEQ_ID =2575 AND BANK.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0) FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2576 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52794 AND CUS_ENTITY_DATA_SEQ_ID = MEM.SEQ_ID AND ISNULL(ATTRIBUTE_DECIMAL,0)=ACB.ATTRIBUTE_003 ) --= ACB.ATTRIBUTE_003
  WHERE MEM.SRM_CLIENT_ENTITIES_SEQ_ID = 2541
  AND MEM.SEQ_ID = @MEMBER
  AND ISNULL(MEM.DELETED, 'N') = 'N' 
  AND ISNULL(MEM.ATTRIBUTE_031, 'N') = 'N'  
    
  SET @CUSTOMER_HISTORY = @@IDENTITY    
    
  EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
   @SRM_CLIENT_ENTITIES_SEQ_ID = 5524,    
   @CUS_ENTITY_DATA_SEQ_ID = @CUSTOMER_HISTORY,    
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
   @ERROR = @ERROR OUTPUT,    
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
     
 END    
 
  print 'before Membership Tag  @MEMBERSHIP_TAGS = ' + @MEMBERSHIP_TAGS + ' , @MEMBER = ' + isnull(cast(@MEMBER as varchar(50)),0)
 
 SET @MEMBERSHIP_TAGS = LTRIM(RTRIM(@MEMBERSHIP_TAGS))
 IF LEN(@MEMBERSHIP_TAGS)>0 AND @MEMBER>0 
 BEGIN
			
	DECLARE @ENTITY_DISPLAY_NAME_PROFILE NVARCHAR(100)    
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE BIGINT    
	SET @ENTITY_DISPLAY_NAME_PROFILE = 'PROFILE'    
	
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PROFILE    

	DECLARE @ENTITY_DISPLAY_NAME_PROFILE_PICKLIST NVARCHAR(100)    
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE_PICKLIST BIGINT    
	SET @ENTITY_DISPLAY_NAME_PROFILE_PICKLIST = 'PROFILE_PICKLIST'    
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE_PICKLIST = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PROFILE_PICKLIST    
		
	DECLARE @DATE_OF_CREATION NVARCHAR(30)
	SELECT @DATE_OF_CREATION = CONVERT(NVARCHAR,Cast(GetDate() as Date), 121)
	
	DECLARE @CommaSepareated_TagsVALUE NVARCHAR(5)
	DECLARE @PROFILE_PICKLIST_SEQ_ID BIGINT
	DECLARE @PROFILE_PICKLIST_ATTRIBUTE_001 NVARCHAR(50)
	DECLARE @PROFILE_PICKLIST_ATTRIBUTE_004 NVARCHAR(50)
	DECLARE @PROFILE_SEQ_ID BIGINT
	DECLARE @PROFILE_DELETED VARCHAR(1)
	DECLARE @ACTION VARCHAR(10)
	
	--Drop Table TempMQ
	--select Identity(Bigint,1,1) as RowID , Cast('' as varchar(500)) as LogDesc Into TempMQ from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA where seq_id = 0
	--select * from TempMQ
	
	--set @MEMBERSHIP_TAGS = replace(@MEMBERSHIP_TAGS,'-','–')
	
	DECLARE MEMBERSHIP_TAGS CURSOR LOCAL STATIC FOR
		WITH TEMP_REC AS (
		SELECT CommaSepareated_Tags.VALUE,
			iPROFILE_PICKLIST.SEQ_ID AS OUTER_iPROFILE_PICKLIST_SEQ_ID,
			iPROFILE_PICKLIST.ATTRIBUTE_001 AS OUTER_iPROFILE_PICKLIST_DESCRIPTION,
			CASE
			WHEN LTRIM(RTRIM(CommaSepareated_Tags.VALUE)) IS NULL AND ISNULL(iPROFILE_SEQ_ID,0)>0 AND ISNULL(PROFILE_ASSIGNED.DELETED,'N')!='Y' THEN 'DELETE'
			WHEN LTRIM(RTRIM(CommaSepareated_Tags.VALUE)) IS NULL AND ISNULL(iPROFILE_SEQ_ID,0)>0 AND ISNULL(PROFILE_ASSIGNED.DELETED,'N')='Y' THEN 'NOACTION'
			WHEN LTRIM(RTRIM(CommaSepareated_Tags.VALUE)) IS NOT NULL AND ISNULL(iPROFILE_SEQ_ID,0)>0 AND ISNULL(PROFILE_ASSIGNED.DELETED,'N')='N'THEN 'NOACTION'
			WHEN LTRIM(RTRIM(CommaSepareated_Tags.VALUE)) IS NOT NULL AND ISNULL(iPROFILE_SEQ_ID,0)>0 AND ISNULL(PROFILE_ASSIGNED.DELETED,'N')='Y'THEN 'UPDATE'
			WHEN LTRIM(RTRIM(CommaSepareated_Tags.VALUE)) IS NOT NULL AND ISNULL(iPROFILE_SEQ_ID,0)=0 THEN 'INSERT'
			END as ACTION,
			PROFILE_ASSIGNED.iPROFILE_PICKLIST_ATTRIBUTE_004,
			PROFILE_ASSIGNED.iPROFILE_SEQ_ID,
			PROFILE_ASSIGNED.DELETED
		FROM (	SELECT 
					   iPROFILE_PICKLIST.ATTRIBUTE_004 AS iPROFILE_PICKLIST_ATTRIBUTE_004,
					   iPROFILE.SEQ_ID as iPROFILE_SEQ_ID,
					   iPROFILE.DELETED,
					   iPROFILE_PICKLIST.SEQ_ID AS iPROFILE_PICKLIST_SEQ_ID,
					   iPROFILE_PICKLIST.ATTRIBUTE_001
				FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA iPROFILE_PICKLIST WITH(NOLOCK)
						RIGHT JOIN [SRM-CustomEntities].dbo.CUS_ENTITY_DATA iPROFILE WITH(NOLOCK) 
						ON iPROFILE.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE
						AND iPROFILE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)  WHERE SRM_CLIENT_ENTITIES_SEQ_ID =@SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =52258 AND ISNULL(ATTRIBUTE_DECIMAL,0)=iPROFILE_PICKLIST.SEQ_ID)   --ISNULL(iPROFILE.ATTRIBUTE_002,0) = iPROFILE_PICKLIST.SEQ_ID
						AND iPROFILE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)  WHERE SRM_CLIENT_ENTITIES_SEQ_ID =@SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =52257 AND ISNULL(ATTRIBUTE_DECIMAL,0)=@MEMBER) --ATTRIBUTE_499=@MEMBER
						WHERE iPROFILE_PICKLIST.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE_PICKLIST 
			  ) AS PROFILE_ASSIGNED 
			  
		RIGHT JOIN [SRM-CustomEntities].dbo.CUS_ENTITY_DATA iPROFILE_PICKLIST WITH(NOLOCK)
			  ON iPROFILE_PICKLIST.SEQ_ID = PROFILE_ASSIGNED.iPROFILE_PICKLIST_SEQ_ID 
		FULL OUTER JOIN [SRM-Framework_New].DBO.FN_SPLIT(@MEMBERSHIP_TAGS,',') As CommaSepareated_Tags
			  ON LTRIM(RTRIM(CommaSepareated_Tags.VALUE)) COLLATE  SQL_Latin1_General_CP1_CI_AS= ISNULL(iPROFILE_PICKLIST.ATTRIBUTE_005,0) --ISNULL(iPROFILE_PICKLIST.ATTRIBUTE_004,0)
		WHERE iPROFILE_PICKLIST.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE_PICKLIST
		) SELECT * FROM TEMP_REC WHERE ACTION IS NOT NULL
		--ORDER BY CommaSepareated_Tags.VALUE
		ORDER BY VALUE
	

	
	
    OPEN MEMBERSHIP_TAGS
    
    FETCH NEXT FROM MEMBERSHIP_TAGS INTO   	
    @CommaSepareated_TagsVALUE,
	@PROFILE_PICKLIST_SEQ_ID,
	@PROFILE_PICKLIST_ATTRIBUTE_001,
	@ACTION,
	@PROFILE_PICKLIST_ATTRIBUTE_004,
	@PROFILE_SEQ_ID,
	@PROFILE_DELETED
	
  WHILE @@FETCH_STATUS = 0    
  BEGIN 
		       
		IF @ACTION='INSERT'
		BEGIN 	 
				   
		   EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_001 = @PROFILE_PICKLIST_ATTRIBUTE_001,    
				@ATTRIBUTE_002 = @PROFILE_PICKLIST_SEQ_ID , 
				@ATTRIBUTE_005 = @DATE_OF_CREATION,
				@ATTRIBUTE_498 = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER,
				@ATTRIBUTE_499 = @MEMBER,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE,    
				@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,       
				@CREATED_BY = @USER,    
				@RETURN_SEQ_ID = @PROFILE_SEQ_ID OUTPUT,    
				@ERROR = @ERROR OUTPUT,    
				@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
				
		END 
		
		IF @ACTION='DELETE'
		BEGIN
				UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
				SET DELETED='Y', DATE_DELETED = GETDATE() , DELETED_BY=@USER
				WHERE SEQ_ID = @PROFILE_SEQ_ID
		END 
		
		IF @ACTION='UPDATE'
		BEGIN
				UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
				SET DELETED='N', DATE_MODIFIED = GETDATE() , MODIFIED_BY=@USER
				WHERE SEQ_ID = @PROFILE_SEQ_ID
		END 

	IF  @ACTION IN('UPDATE','DELETE')
	BEGIN
			EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
		   @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PROFILE,    
		   @CUS_ENTITY_DATA_SEQ_ID = @PROFILE_SEQ_ID,    
		   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
		   @ERROR = @ERROR OUTPUT,    
		   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
	END 
	
    FETCH NEXT FROM MEMBERSHIP_TAGS INTO   	
    @CommaSepareated_TagsVALUE,
	@PROFILE_PICKLIST_SEQ_ID,
	@PROFILE_PICKLIST_ATTRIBUTE_001,
	@ACTION,
	@PROFILE_PICKLIST_ATTRIBUTE_004,
	@PROFILE_SEQ_ID,
	@PROFILE_DELETED
	
  END    
    
  CLOSE MEMBERSHIP_TAGS
  DEALLOCATE MEMBERSHIP_TAGS						
  
END 
 
 SET @ERROR = 0    
 SET @ERROR_DESCRIPTION = ''    
END    



;






-- =============================================
-- Author:		<Rauf Gill>
-- Modifications By:		<Sohail Raza>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_APPLY_MEMBERSHIP_MEMBERS_DATA_TO_API]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
	
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_MEMBERSHIP_MEMBERS_DATA_TO_API]'

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER  BIGINT
	DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER = SEQ_ID 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME LIKE 'MEMBER'

	DECLARE CUR_MEMBERS CURSOR LOCAL STATIC FOR
		SELECT SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER -- AND ISNULL(ATTRIBUTE_031, 'N')  ='N'
		--AND SEQ_ID > 4161567
		ORDER BY SEQ_ID

	-- Only get those where 'Membership Pay By' is null. case handled in [GET_POPULATE_MEMBERSHIP]	
	-- RG_2013102 Commented following line as system does not sync. data if record if pay by member is saved.
	 --AND ATTRIBUTE_029 IS NULL

	OPEN CUR_MEMBERS
	FETCH NEXT FROM CUR_MEMBERS INTO @CUS_ENTITY_DATA_SEQ_ID
	WHILE @@FETCH_STATUS = 0 
	BEGIN
		PRINT 'PROCESSING MEMBER CUS_ENTITY_DATA_SEQ_ID = ' +  CAST(@CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR(20))

		EXEC [dbo].[GET_POPULATE_MEMBERSHIP] 
			@CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
		
		FETCH NEXT FROM CUR_MEMBERS INTO @CUS_ENTITY_DATA_SEQ_ID
	END
	CLOSE CUR_MEMBERS
	DEALLOCATE CUR_MEMBERS


					
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END






;






-- EXEC [dbo].[GET_APPLY_MEMBERSHIP_MEMBERS_DATA_TO_API_MISSING_RECORDS] @SRM_CLIENTS_SEQ_ID = 17

-- =============================================
-- Author:		<Rauf Gill>
-- Modifications By:		<Sohail Raza>
