-- =============================================
CREATE PROCEDURE [dbo].[GET_APPLY_MEMBERSHIP_MEMBERS_DATA_TO_API_MISSING_RECORDS]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_MEMBERSHIP_MEMBERS_DATA_TO_API_MISSING_RECORDS]'

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER  BIGINT
	DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER = SEQ_ID 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME LIKE 'MEMBER'

	DECLARE CUR_MEMBERS CURSOR LOCAL STATIC FOR
		SELECT SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND (ATTRIBUTE_031 IS NULL OR ATTRIBUTE_031 ='N')
		AND ATTRIBUTE_001 NOT IN (SELECT ATTRIBUTE_045 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 2696 AND ATTRIBUTE_045 IS NOT NULL)
		ORDER BY SEQ_ID

	-- Only get those where 'Membership Pay By' is null. case handled in [GET_POPULATE_MEMBERSHIP]	
	-- RG_2013102 Commented following line as system does not sync. data if record if pay by member is saved.
	 --AND ATTRIBUTE_029 IS NULL

	OPEN CUR_MEMBERS
	FETCH NEXT FROM CUR_MEMBERS INTO @CUS_ENTITY_DATA_SEQ_ID
	WHILE @@FETCH_STATUS = 0 
	BEGIN
		PRINT 'PROCESSING MEMBER CUS_ENTITY_DATA_SEQ_ID = ' +  CAST(@CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR(20))

		EXEC [dbo].[GET_POPULATE_MEMBERSHIP] 
			@CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
		
		FETCH NEXT FROM CUR_MEMBERS INTO @CUS_ENTITY_DATA_SEQ_ID
	END
	CLOSE CUR_MEMBERS
	DEALLOCATE CUR_MEMBERS


					
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END






;






-- EXEC [dbo].[GET_APPLY_MEMBERSHIP_MEMBERS_DATA_TO_API_MODIFIED_RECORDS] @SRM_CLIENTS_SEQ_ID = 17

-- =============================================
-- Author:		<Rauf Gill>
-- Modifications By:		<Sohail Raza>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_APPLY_MEMBERSHIP_MEMBERS_DATA_TO_API_MODIFIED_RECORDS]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_MEMBERSHIP_MEMBERS_DATA_TO_API_MODIFIED_RECORDS]'

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER  BIGINT
	DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER = SEQ_ID 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME LIKE 'MEMBER'

	DECLARE CUR_MEMBERS CURSOR LOCAL STATIC FOR
		SELECT SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
			--AND (ATTRIBUTE_031 IS NULL OR ATTRIBUTE_031 ='N')
			AND DATE_MODIFIED >= DATEADD(D, -1, GETDATE())
		ORDER BY SEQ_ID

	-- Only get those where 'Membership Pay By' is null. case handled in [GET_POPULATE_MEMBERSHIP]	
	-- RG_2013102 Commented following line as system does not sync. data if record if pay by member is saved.
	 --AND ATTRIBUTE_029 IS NULL

	OPEN CUR_MEMBERS
	FETCH NEXT FROM CUR_MEMBERS INTO @CUS_ENTITY_DATA_SEQ_ID
	WHILE @@FETCH_STATUS = 0 
	BEGIN
		PRINT 'PROCESSING MEMBER CUS_ENTITY_DATA_SEQ_ID = ' +  CAST(@CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR(20))

		EXEC [dbo].[GET_POPULATE_MEMBERSHIP] 
			@CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
		
		FETCH NEXT FROM CUR_MEMBERS INTO @CUS_ENTITY_DATA_SEQ_ID
	END
	CLOSE CUR_MEMBERS
	DEALLOCATE CUR_MEMBERS

	DECLARE CUR_MEMBERS CURSOR LOCAL STATIC FOR
		SELECT SEQ_ID 
		FROM [SRM-CUSTOMENTITIES]..CUS_ENTITY_DATA WITH(NOLOCK) 
		WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER	--MEMBER CUSTOM ENTITIES
		AND ISNULL(DELETED,'N')='N' 
		AND SEQ_ID IN( 
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17 ]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52027 AND ATTRIBUTE_BOOLEAN IS NOT NULL AND ATTRIBUTE_BOOLEAN='Y'
		INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17 ]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
		AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=51987 
		AND ATTRIBUTE_STRING IN(
		SELECT ATTRIBUTE_STRING FROM [SRM-DataPivot_17 ]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2696 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=55327 AND ATTRIBUTE_STRING IS NOT NULL 
		)) ORDER BY SEQ_ID

	-- Only get those where 'Membership Pay By' is null. case handled in [GET_POPULATE_MEMBERSHIP]	
	-- RG_2013102 Commented following line as system does not sync. data if record if pay by member is saved.
	 --AND ATTRIBUTE_029 IS NULL

	OPEN CUR_MEMBERS
	FETCH NEXT FROM CUR_MEMBERS INTO @CUS_ENTITY_DATA_SEQ_ID
	WHILE @@FETCH_STATUS = 0 
	BEGIN
		PRINT 'PROCESSING MEMBER CUS_ENTITY_DATA_SEQ_ID = ' +  CAST(@CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR(20))

		EXEC [dbo].[GET_POPULATE_MEMBERSHIP] 
			@CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
		
		FETCH NEXT FROM CUR_MEMBERS INTO @CUS_ENTITY_DATA_SEQ_ID
	END
	CLOSE CUR_MEMBERS
	DEALLOCATE CUR_MEMBERS
					
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END






;




-- ===================================================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- ===================================================================

CREATE PROCEDURE [dbo].[GET_APPLY_PRODUCT_SALES_DATA_TO_STARGET]
	-- Add the parameters for the stored procedure here
	@WEB_SERVICE_PRODUCT_SALE_MASTER_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_PRODUCT_SALES_DATA_TO_STARGET]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @ATTRIBUTE_001_SLAE_ID NVARCHAR(100)
	DECLARE @ATTRIBUTE_002_USER_NAME NVARCHAR(100)
	DECLARE @ATTRIBUTE_026_CURRICULUM_CREDITS_USED NVARCHAR(1)

	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT
	DECLARE @USER NVARCHAR(100)
	DECLARE @CONTACT_SEQ_ID BIGINT
	DECLARE @ACCOUNT_SEQ_ID BIGINT
	DECLARE @PRODUCT_SALE_SEQ_ID BIGINT
	DECLARE @INVOICE_TRANSACTION_SEQ_ID BIGINT

	DECLARE @PIVOT_RETURN_VALUE NVARCHAR(MAX)
	DECLARE @MODULE BIGINT
	DECLARE @MODULE_DESCRIPTION NVARCHAR(100)
	DECLARE @FINANCE_TRANSACTION_SEQ_ID BIGINT
	DECLARE @PAYMENT_BATCH_TRANSACTION_SEQ_ID BIGINT

	DECLARE @ATTRIBUTE_001_LABEL_NAME NVARCHAR(100)

		
	---- CONTACT VARIABLES
	--DECLARE @ATTRIBUTE_004_LAST_NAME NVARCHAR(100)
	--DECLARE @ATTRIBUTE_005_FIRST_NAME NVARCHAR(100)
	--DECLARE @ATTRIBUTE_003_UCN NVARCHAR(100)
	--DECLARE @ATTRIBUTE_132_AREA_OF_FOCUS BIGINT
	--DECLARE @ATTRIBUTE_133_AREA_OF_FOCUS_DESCRIPTION NVARCHAR(100)
	--DECLARE @ATTRIBUTE_020_LOGIN_USER_NAME NVARCHAR(100)
	--DECLARE @ATTRIBUTE_022_LOGIN_PASSWORD NVARCHAR(100)
	---- END CONTACT VARIABLES

	-- PRODUCT SALE DETAIL
	DECLARE @ATTRIBUTE_005_UNIT_PRICE MONEY
	DECLARE @ATTRIBUTE_006_QUANTITY SMALLINT
	DECLARE @ATTRIBUTE_007_TOTAL_PRICE MONEY
	DECLARE @ATTRIBUTE_008_DISCOUNT_PERCENTAGE MONEY
	DECLARE @ATTRIBUTE_009_DISCOUNT_AMOUNT MONEY
	DECLARE @ATTRIBUTE_010_VAT_PERCENTAGE MONEY
	DECLARE @ATTRIBUTE_011_VAT_AMOUNT MONEY
	DECLARE @ATTRIBUTE_012_NET_AMOUNT MONEY
	DECLARE @ATTRIBUTE_013_GROSS_AMOUNT MONEY
	DECLARE @ATTRIBUTE_015_PRODUCT_ID NVARCHAR(100)
	DECLARE @PRODUCT_SEQ_ID BIGINT

	DECLARE @ATTRIBUTE_002_PRODUCT NVARCHAR(200)
	DECLARE @ATTRIBUTE_005_PRODUCT NVARCHAR(20)
	DECLARE @ATTRIBUTE_006_PRODUCT NVARCHAR(100)
	DECLARE @ATTRIBUTE_007_PRODUCT NVARCHAR(20)
	DECLARE @ATTRIBUTE_008_PRODUCT NVARCHAR(100)


	DECLARE @DISCOUNT_CODE_SEQ_ID BIGINT
	DECLARE @DISCOUNT_PERC BIGINT
	DECLARE @DISCOUNT_CODE NVARCHAR(100)
	DECLARE @TOTAL_AMOUNT MONEY
	DECLARE @VAT_PERCENTAGE MONEY
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_DISCOUNT_CODE NVARCHAR(200)


	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_AOF BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PS BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_IT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PR BIGINT

	DECLARE @ENTITY_DISPLAY_NAME_WSPSM NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_WSPSD NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_AOF NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_CONTACT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_PRODUCT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_PS NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_IT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_PR NVARCHAR(100)
	DECLARE @PAYMENT_AMOUNT MONEY

	DECLARE @PRODUCT_SALE_DETAILS_SEQ_ID BIGINT
	DECLARE @PRODUCT_ID NVARCHAR(100)
	DECLARE @GROSS_AMOUNT MONEY
	DECLARE @NET_AMOUNT MONEY
	DECLARE @VAT_AMOUNT MONEY
	DECLARE @UNIT_PRICE MONEY
	DECLARE @QUANTITY BIGINT
	DECLARE @PRODUCT_NET_AMOUNT MONEY
	DECLARE @PRODUCT_VAT_AMOUNT MONEY
	DECLARE @PRODUCT_SALE_MASTER_NET_AMOUNT MONEY
	DECLARE @PRODUCT_SALE_MASTER_VAT_AMOUNT MONEY
	DECLARE @VAT_RATE NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_VAT_RATE NVARCHAR(100)

	DECLARE @ENTITY_DISPLAY_NAME_MEMBER NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER BIGINT	
	DECLARE @MEMBER_SEQ_ID BIGINT
	DECLARE @MEMBER_CURRICULUM_CREDITS MONEY
	DECLARE @PAY_BY_INVOICE NVARCHAR(1)

	DECLARE @PRIVACY_POLICY_AGREEMENT NVarchar(1) --ATTRIBUTE_070 
	DECLARE @PRIVACY_POLICY_AGREEMENT_DATE NVarchar(100) --ATTRIBUTE_071
	DECLARE @TS_CS_AGREEMENT NVarchar(1) --ATTRIBUTE_072 
	DECLARE @TS_CS_AGREEMENT_DATE NVarchar(100) --ATTRIBUTE_073


	SET @USER = 'WEB'

	SET @SRM_CLIENTS_SEQ_ID = 17
	SET @ENTITY_DISPLAY_NAME_WSPSM = 'WEB_SERVICE_PRODUCT_SALE_MASTER'
	SET @ENTITY_DISPLAY_NAME_WSPSD = 'WEB_SERVICE_PRODUCT_SALE_DETAIL'
	SET @ENTITY_DISPLAY_NAME_AOF = 'AREA_OF_FOCUS'
	SET @ENTITY_DISPLAY_NAME_CONTACT = 'CONTACT'
	SET @ENTITY_DISPLAY_NAME_PRODUCT = 'PRODUCT'
	SET @ENTITY_DISPLAY_NAME_PS = 'PRODUCT_SALE'
	SET @ENTITY_DISPLAY_NAME_IT = 'INVOICE_TRANSACTION'
	SET @ENTITY_DISPLAY_NAME_PR = 'PRODUCT_PRICING'
	SET @ENTITY_DISPLAY_NAME_VAT_RATE = 'VAT_RATE'
	SET @ENTITY_DISPLAY_NAME_MEMBER = 'MEMBER'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSPSM 
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSPSD
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_AOF = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_AOF 
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_CONTACT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PRODUCT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PS = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PS
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_IT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_IT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PR = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PR
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_VAT_RATE
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MEMBER
	
	-- GET MODULE
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MODULE', @ATTRIBUTE_DISPLAY_NAME = 'PRODUCT_SALE', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MODULE OUTPUT, @DESCRIPTION = @MODULE_DESCRIPTION OUTPUT

	SELECT 
		@ATTRIBUTE_001_SLAE_ID = ATTRIBUTE_001, 
		@ATTRIBUTE_002_USER_NAME = ATTRIBUTE_002, 
		@ATTRIBUTE_026_CURRICULUM_CREDITS_USED = ISNULL(ATTRIBUTE_026, 'N'), 
		@PAYMENT_AMOUNT = ATTRIBUTE_025, 
		@PRODUCT_SALE_MASTER_NET_AMOUNT = ISNULL(ATTRIBUTE_038, 0), 
		@DISCOUNT_CODE = ATTRIBUTE_031, 
		@PAY_BY_INVOICE = ATTRIBUTE_029

	   ,@PRIVACY_POLICY_AGREEMENT =CASE WHEN ATTRIBUTE_070 IN ('Y' , 'Yes' , 'True') THEN  'Y' ELSE 'N' END 
	   ,@PRIVACY_POLICY_AGREEMENT_DATE = ATTRIBUTE_071
	   ,@TS_CS_AGREEMENT =CASE WHEN ATTRIBUTE_072 IN ('Y' , 'Yes' , 'True') THEN  'Y' ELSE 'N' END 
	   ,@TS_CS_AGREEMENT_DATE =ATTRIBUTE_073

	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM 
	AND SEQ_ID = @WEB_SERVICE_PRODUCT_SALE_MASTER_SEQ_ID


	IF ISNULL(@ATTRIBUTE_001_SLAE_ID, '') = ''
	BEGIN
		SET @ERROR = 0
		SET @ERROR_DESCRIPTION = 'THIS ORDER CANNOT BE PROCESSED. NO SALE ID HAS BEEN PROVIDED'
		RETURN
	END

	-- *********************************************************************************
	-- Start - Populate Net Amount & VAT amount for Product Sale Detail & Product Sale Master
	-- *********************************************************************************
	SET @NET_AMOUNT = 0
	SET @PRODUCT_SEQ_ID = 0

	DECLARE CUR_PRODUCT_SALE_DETAIL CURSOR STATIC FOR
	SELECT  SEQ_ID, ISNULL(ATTRIBUTE_012,0),  ATTRIBUTE_011, ATTRIBUTE_013, ATTRIBUTE_015 , ATTRIBUTE_005, ATTRIBUTE_006
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD 
	--ATTRIBUTE_001 = @ATTRIBUTE_001_SLAE_ID
	AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 55954 AND ISNULL(ATTRIBUTE_STRING,'') = @ATTRIBUTE_001_SLAE_ID)
		
	OPEN CUR_PRODUCT_SALE_DETAIL
	FETCH NEXT FROM CUR_PRODUCT_SALE_DETAIL INTO @PRODUCT_SALE_DETAILS_SEQ_ID, @NET_AMOUNT, @VAT_AMOUNT, @GROSS_AMOUNT, @PRODUCT_ID, @UNIT_PRICE, @QUANTITY

	WHILE (@@FETCH_STATUS = 0)
	BEGIN
	
		SET @QUANTITY = ISNULL(@QUANTITY, 1)
		
		IF @QUANTITY<=0
		 SET  @QUANTITY=1

		IF ISNULL(@NET_AMOUNT, 0) = 0
		BEGIN
			SELECT @PRODUCT_SEQ_ID = SEQ_ID 
			FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT
			--AND ATTRIBUTE_001 = @PRODUCT_ID
			AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52591 AND ISNULL(ATTRIBUTE_STRING,'') = @PRODUCT_ID)

			SET @PRODUCT_NET_AMOUNT = 0
			SET @PRODUCT_VAT_AMOUNT = 0
			SET @GROSS_AMOUNT = 0

			SELECT @PRODUCT_NET_AMOUNT = ATTRIBUTE_006, @PRODUCT_VAT_AMOUNT = ATTRIBUTE_007 
			FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PR
			--ATTRIBUTE_002 = @PRODUCT_SEQ_ID 
			AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID 
										  FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) 
										  WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PR 
										  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 54177 
										  AND ISNULL(ATTRIBUTE_DECIMAL,0) = @PRODUCT_SEQ_ID
										 )
			AND CAST(ATTRIBUTE_006 AS MONEY) + CAST(ATTRIBUTE_007 AS MONEY) = @UNIT_PRICE

			SET @PRODUCT_NET_AMOUNT = ISNULL(@PRODUCT_NET_AMOUNT, 0) * @QUANTITY
			SET @PRODUCT_VAT_AMOUNT = ISNULL(@PRODUCT_VAT_AMOUNT, 0) * @QUANTITY
			
			SET @GROSS_AMOUNT = @PRODUCT_NET_AMOUNT + @PRODUCT_VAT_AMOUNT

			UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
			SET ATTRIBUTE_012 = @PRODUCT_NET_AMOUNT, ATTRIBUTE_011 = @PRODUCT_VAT_AMOUNT, ATTRIBUTE_013 = @GROSS_AMOUNT
			WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
			AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD 
			AND SEQ_ID = @PRODUCT_SALE_DETAILS_SEQ_ID
		END
		
		SET @NET_AMOUNT = 0
		FETCH NEXT FROM CUR_PRODUCT_SALE_DETAIL INTO @PRODUCT_SALE_DETAILS_SEQ_ID, @NET_AMOUNT, @VAT_AMOUNT, @GROSS_AMOUNT, @PRODUCT_ID, @UNIT_PRICE, @QUANTITY
	END
	CLOSE CUR_PRODUCT_SALE_DETAIL
	DEALLOCATE CUR_PRODUCT_SALE_DETAIL
	

	SELECT 
		@PRODUCT_SALE_MASTER_NET_AMOUNT = SUM(ISNULL(CAST(ATTRIBUTE_012 AS MONEY), 0)), 
		@PRODUCT_SALE_MASTER_VAT_AMOUNT = SUM(ISNULL(CAST(ATTRIBUTE_011 AS MONEY), 0))
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD 
	--AND ATTRIBUTE_001 = @ATTRIBUTE_001_SLAE_ID
	AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 55954 AND ISNULL(ATTRIBUTE_STRING,'') = @ATTRIBUTE_001_SLAE_ID)
		
	UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA SET ATTRIBUTE_038 = @PRODUCT_SALE_MASTER_NET_AMOUNT, ATTRIBUTE_039 = @PRODUCT_SALE_MASTER_VAT_AMOUNT
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM 
	AND SEQ_ID = @WEB_SERVICE_PRODUCT_SALE_MASTER_SEQ_ID

	-- *********************************************************************************
	-- End - Populate Net Amount & VAT amount for Product Sale Detail & Product Sale Master
	-- *********************************************************************************



	SET @CONTACT_SEQ_ID = NULL

	IF ISNULL(@ATTRIBUTE_002_USER_NAME, '') <> '' 
	BEGIN
		SET @PIVOT_RETURN_VALUE = NULL

		EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT, @ATTRIBUTE_DISPLAY_NAME = 'LOGIN_USER_NAME', @OPERATOR_ID = 3, @SEARCH_VALUE = @ATTRIBUTE_002_USER_NAME, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT

		IF ISNULL(@PIVOT_RETURN_VALUE, '') <> ''
		BEGIN
			SELECT @CONTACT_SEQ_ID = DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ',')
		END
			
	END

	IF ISNULL(@CONTACT_SEQ_ID, 0) = 0 -- CREATE A NEW CONTACT
	BEGIN
		EXEC [dbo].[GET_CREATE_ACCOUNT_CONTACT_PS_IMPORT]
			@EXTERNAL_ID = @ATTRIBUTE_001_SLAE_ID,
			@USER = @USER,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@CONTACT = @CONTACT_SEQ_ID OUTPUT,
			@ACCOUNT = @ACCOUNT_SEQ_ID OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END

	IF ISNULL(@CONTACT_SEQ_ID, 0) = 0
	BEGIN
		PRINT 'ERROR ----- CONTACT NOT FOUND, CANNOT CONTINUE'
		SET @ERROR = 1
		SET @ERROR_DESCRIPTION = 'ERROR ----- CONTACT NOT FOUND, CANNOT CONTINUE'
		RETURN
	END

	-- GET CONTACT NAME
	SELECT @ATTRIBUTE_001_LABEL_NAME = ATTRIBUTE_001 
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT
	AND SEQ_ID = @CONTACT_SEQ_ID


	UPDATE DATAProtectionFields SET 
	 ATTRIBUTE_190 = ISNULL(@PRIVACY_POLICY_AGREEMENT ,DATAProtectionFields.ATTRIBUTE_190)
	,ATTRIBUTE_191 = ISNULL(@PRIVACY_POLICY_AGREEMENT_DATE , DATAProtectionFields.ATTRIBUTE_191)
	,ATTRIBUTE_192 = ISNULL(@TS_CS_AGREEMENT , DATAProtectionFields.ATTRIBUTE_192)
	,ATTRIBUTE_193 = ISNULL(@TS_CS_AGREEMENT_DATE , DATAProtectionFields.ATTRIBUTE_193)
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA DATAProtectionFields WITH(NOLOCK)
	WHERE SEQ_ID = @CONTACT_SEQ_ID

    EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
	@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT,
	@CUS_ENTITY_DATA_SEQ_ID = @CONTACT_SEQ_ID,
	@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
	@ERROR = @ERROR OUTPUT,
	@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT


	-- ADD PRODUCT_SALE AND INVOICE_TRANSACTION
	EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD, @ATTRIBUTE_DISPLAY_NAME = 'SALE_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @ATTRIBUTE_001_SLAE_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT
	
	Print 'GETTING PRODUCT DETAIL IN CURSOR  : START : ' +  convert(varchar, getdate(), 113)
	DECLARE CUS_SALES CURSOR STATIC LOCAL FOR 
	SELECT ATTRIBUTE_005,
		ATTRIBUTE_006,
		ATTRIBUTE_007,
		ATTRIBUTE_008,
		ATTRIBUTE_009,
		ATTRIBUTE_010,
		ATTRIBUTE_011,
		ATTRIBUTE_012,
		ATTRIBUTE_013,
		ATTRIBUTE_015
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD
		AND SEQ_ID IN (SELECT DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ','))

	OPEN CUS_SALES
	Print 'GETTING PRODUCT DETAIL IN CURSOR  : END : ' +  convert(varchar, getdate(), 113)
	
	FETCH NEXT FROM CUS_SALES INTO 
		@ATTRIBUTE_005_UNIT_PRICE,
		@ATTRIBUTE_006_QUANTITY, 
		@ATTRIBUTE_007_TOTAL_PRICE,
		@ATTRIBUTE_008_DISCOUNT_PERCENTAGE,
		@ATTRIBUTE_009_DISCOUNT_AMOUNT,
		@ATTRIBUTE_010_VAT_PERCENTAGE,
		@ATTRIBUTE_011_VAT_AMOUNT,
		@ATTRIBUTE_012_NET_AMOUNT,
		@ATTRIBUTE_013_GROSS_AMOUNT,
		@ATTRIBUTE_015_PRODUCT_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		Print '------------------------------FETCHING NEXT RECORD END : ' +  convert(varchar, getdate(), 113)
		--EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT, @ATTRIBUTE_DISPLAY_NAME = 'PRODUCT_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @ATTRIBUTE_015_PRODUCT_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT
		--SELECT @PRODUCT_SEQ_ID = DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ',')
		--print '@DISCOUNT_CODE ' + @DISCOUNT_CODE
