			@ATTRIBUTE_008_PRODUCT = ATTRIBUTE_008
		FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
		WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT
