		AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52591 AND ISNULL(ATTRIBUTE_STRING,'') = @ATTRIBUTE_015_PRODUCT_ID)
			
