	EXEC [dbo].[GET_CREATE_FINANCE_BATCH]
		@EXTERNAL_ID = @ATTRIBUTE_001_SLAE_ID,
		@ACCOUNT = NULL,
		@ACCOUNT_NAME = NULL,
		@CONTACT = @CONTACT_SEQ_ID,
		@CONTACT_NAME = @ATTRIBUTE_001_LABEL_NAME,
		@USER = @USER,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@FINANCE_TRANSACTION_SEQ_ID = @FINANCE_TRANSACTION_SEQ_ID OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		Print 'CURRICULUM CREDIT :  ' +  convert(varchar, getdate(), 113)
		-- Decrement Curriculum Credits from Member Account
		DECLARE @ATTRIBUTE_029_PAID_BY BIGINT
		DECLARE @GROSS_AMOUNT_FTD MONEY
		
		
		IF @ATTRIBUTE_026_CURRICULUM_CREDITS_USED = 'Y'
		BEGIN
		
			SELECT @MEMBER_SEQ_ID = SEQ_ID,  @MEMBER_CURRICULUM_CREDITS = ISNULL(ATTRIBUTE_035,0) , @ATTRIBUTE_029_PAID_BY=ISNULL(ATTRIBUTE_029,0)
			FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
			WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
			AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
			--AND ATTRIBUTE_017 = @CONTACT_SEQ_ID
			AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52013 AND ISNULL(ATTRIBUTE_DECIMAL,0) = @CONTACT_SEQ_ID)
			ORDER BY  ISNULL(ATTRIBUTE_031,'N') DESC
            
			SELECT @GROSS_AMOUNT_FTD=SUM(CAST(ISNULL(ATTRIBUTE_020,'0') AS MONEY))
			FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2669
			AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2669 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 54709 AND ISNULL(ATTRIBUTE_DECIMAL,0)=@FINANCE_TRANSACTION_SEQ_ID)
			
			PRINT '@MEMBER_CURRICULUM_CREDITS ' + CAST(@MEMBER_CURRICULUM_CREDITS AS NVARCHAR(100)) 
			PRINT '@ATTRIBUTE_013_GROSS_AMOUNT ' + CAST(@GROSS_AMOUNT_FTD AS NVARCHAR(100))
			
			IF ISNULL(@ATTRIBUTE_029_PAID_BY,0)=0
			BEGIN
					IF @MEMBER_CURRICULUM_CREDITS>0
					BEGIN
						Print '------------------------------UPDATING CURRICULUM CREDIT : UPDATE START ' +  convert(varchar, getdate(), 113)
						UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
						SET ATTRIBUTE_035 = ATTRIBUTE_035 - @GROSS_AMOUNT_FTD
						WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
						--AND ATTRIBUTE_017 = @CONTACT_SEQ_ID
						--AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52013 AND ISNULL(ATTRIBUTE_DECIMAL,0) = @CONTACT_SEQ_ID)
						AND SEQ_ID = @MEMBER_SEQ_ID

						Print '------------------------------UPDATING CURRICULUM CREDIT 1 : POPULATE PIVOT START : ' +  convert(varchar, getdate(), 113)
						EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
							@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER,
							@CUS_ENTITY_DATA_SEQ_ID = @MEMBER_SEQ_ID,
							@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
							@ERROR = @ERROR OUTPUT,
							@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
						Print '------------------------------UPDATING CURRICULUM CREDIT 1 : POPULATE PIVOT END : ' +  convert(varchar, getdate(), 113)
					END
			END
			ELSE IF @ATTRIBUTE_029_PAID_BY>0
			BEGIN
					SELECT @MEMBER_SEQ_ID = SEQ_ID,  @MEMBER_CURRICULUM_CREDITS = ISNULL(ATTRIBUTE_035,0)
					FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
					WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
					AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
					--AND ATTRIBUTE_015 = @ATTRIBUTE_029_PAID_BY
					AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52011 AND ISNULL(ATTRIBUTE_DECIMAL,0) = @ATTRIBUTE_029_PAID_BY)
					ORDER BY  ISNULL(ATTRIBUTE_031,'N') DESC
                    
					IF @MEMBER_CURRICULUM_CREDITS>0
					BEGIN
						Print '------------------------------UPDATING CURRICULUM CREDIT2 : UPDATE START ' +  convert(varchar, getdate(), 113)
						UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
						SET ATTRIBUTE_035 = ATTRIBUTE_035 - @GROSS_AMOUNT_FTD
						WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
						AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
						--AND ATTRIBUTE_015 = @ATTRIBUTE_029_PAID_BY
						AND SEQ_ID = @MEMBER_SEQ_ID
						
						Print '------------------------------UPDATING CURRICULUM CREDIT 2 : POPULATE PIVOT START : ' +  convert(varchar, getdate(), 113)
						EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
							@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER,
							@CUS_ENTITY_DATA_SEQ_ID = @MEMBER_SEQ_ID,
							@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
							@ERROR = @ERROR OUTPUT,
							@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
						Print '------------------------------UPDATING CURRICULUM CREDIT 2 : POPULATE PIVOT END : ' +  convert(varchar, getdate(), 113)
					END
			END
				
		END



		/*
		--Print '------------------------------UPDATING CURRICULUM CREDIT 2 : POPULATE_MEMBERSHIP START : ' +  convert(varchar, getdate(), 113)
		--IF @ATTRIBUTE_026_CURRICULUM_CREDITS_USED = 'Y' AND @ATTRIBUTE_029_PAID_BY>0
		--BEGIN
		--			SELECT @MEMBER_SEQ_ID = SEQ_ID,  @MEMBER_CURRICULUM_CREDITS = ISNULL(ATTRIBUTE_035,0)
		--			FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
		--			WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		--			AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
		--			--AND ATTRIBUTE_015 = @ATTRIBUTE_029_PAID_BY
		--			AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52011 AND ISNULL(ATTRIBUTE_DECIMAL,0) = @ATTRIBUTE_029_PAID_BY)
					
		--			EXEC [dbo].[GET_POPULATE_MEMBERSHIP] 
		--				@CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		--				@CUS_ENTITY_DATA_SEQ_ID = @MEMBER_SEQ_ID,
		--				@ERROR = @ERROR OUTPUT,
		--				@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
		--END 
		--Print '------------------------------UPDATING CURRICULUM CREDIT 2 : POPULATE_MEMBERSHIP END : ' +  convert(varchar, getdate(), 113)
		*/

	IF ISNULL(@PAY_BY_INVOICE, 'N')  = 'N' AND @PAYMENT_AMOUNT > 0 AND ISNULL(@ATTRIBUTE_026_CURRICULUM_CREDITS_USED, 'N') = 'N'
	BEGIN
		EXEC [dbo].[GET_CREATE_RECEIPT_BATCH]
			@EXTERNAL_ID = @WEB_SERVICE_PRODUCT_SALE_MASTER_SEQ_ID,
			@ACCOUNT = NULL,
			@ACCOUNT_NAME = NULL,
			@CONTACT = @CONTACT_SEQ_ID,
			@CONTACT_NAME = @ATTRIBUTE_001_LABEL_NAME,
			@PAYMENT_AMOUNT = @PAYMENT_AMOUNT,
			@FINANCE_TRANSACTION_SEQ_ID = @FINANCE_TRANSACTION_SEQ_ID,
			@USER = @USER,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@PAYMENT_BATCH_TRANSACTION_SEQ_ID = @PAYMENT_BATCH_TRANSACTION_SEQ_ID OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = 'Process completed successfully'
  
	SELECT @ERROR AS ERROR, @ERROR_DESCRIPTION AS ERROR_DESCRIPTION 
END







;







/*
	exec [dbo].[GET_APPLY_PRODUCT_SALES_DATA_TO_STARGET]
		@WEB_SERVICE_PRODUCT_SALE_MASTER_SEQ_ID = 5213351
*/
-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_APPLY_PRODUCT_SALES_DATA_TO_STARGET_TEST]
	-- Add the parameters for the stored procedure here
	@WEB_SERVICE_PRODUCT_SALE_MASTER_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_PRODUCT_SALES_DATA_TO_STARGET]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @ATTRIBUTE_001_SLAE_ID NVARCHAR(100)
	DECLARE @ATTRIBUTE_002_USER_NAME NVARCHAR(100)
	DECLARE @ATTRIBUTE_026_CURRICULUM_CREDITS_USED NVARCHAR(1)

	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT
	DECLARE @USER NVARCHAR(100)
	DECLARE @CONTACT_SEQ_ID BIGINT
	DECLARE @ACCOUNT_SEQ_ID BIGINT
	DECLARE @PRODUCT_SALE_SEQ_ID BIGINT
	DECLARE @INVOICE_TRANSACTION_SEQ_ID BIGINT

	DECLARE @PIVOT_RETURN_VALUE NVARCHAR(MAX)
	DECLARE @MODULE BIGINT
	DECLARE @MODULE_DESCRIPTION NVARCHAR(100)
	DECLARE @FINANCE_TRANSACTION_SEQ_ID BIGINT
	DECLARE @PAYMENT_BATCH_TRANSACTION_SEQ_ID BIGINT

	DECLARE @ATTRIBUTE_001_LABEL_NAME NVARCHAR(100)

		
	---- CONTACT VARIABLES
	--DECLARE @ATTRIBUTE_004_LAST_NAME NVARCHAR(100)
	--DECLARE @ATTRIBUTE_005_FIRST_NAME NVARCHAR(100)
	--DECLARE @ATTRIBUTE_003_UCN NVARCHAR(100)
	--DECLARE @ATTRIBUTE_132_AREA_OF_FOCUS BIGINT
	--DECLARE @ATTRIBUTE_133_AREA_OF_FOCUS_DESCRIPTION NVARCHAR(100)
	--DECLARE @ATTRIBUTE_020_LOGIN_USER_NAME NVARCHAR(100)
	--DECLARE @ATTRIBUTE_022_LOGIN_PASSWORD NVARCHAR(100)
	---- END CONTACT VARIABLES

	-- PRODUCT SALE DETAIL
	DECLARE @ATTRIBUTE_005_UNIT_PRICE MONEY
	DECLARE @ATTRIBUTE_006_QUANTITY SMALLINT
	DECLARE @ATTRIBUTE_007_TOTAL_PRICE MONEY
	DECLARE @ATTRIBUTE_008_DISCOUNT_PERCENTAGE MONEY
	DECLARE @ATTRIBUTE_009_DISCOUNT_AMOUNT MONEY
	DECLARE @ATTRIBUTE_010_VAT_PERCENTAGE MONEY
	DECLARE @ATTRIBUTE_011_VAT_AMOUNT MONEY
	DECLARE @ATTRIBUTE_012_NET_AMOUNT MONEY
	DECLARE @ATTRIBUTE_013_GROSS_AMOUNT MONEY
	DECLARE @ATTRIBUTE_015_PRODUCT_ID NVARCHAR(100)
	DECLARE @PRODUCT_SEQ_ID BIGINT

	DECLARE @ATTRIBUTE_002_PRODUCT NVARCHAR(200)
	DECLARE @ATTRIBUTE_005_PRODUCT NVARCHAR(20)
	DECLARE @ATTRIBUTE_006_PRODUCT NVARCHAR(100)
	DECLARE @ATTRIBUTE_007_PRODUCT NVARCHAR(20)
	DECLARE @ATTRIBUTE_008_PRODUCT NVARCHAR(100)


	DECLARE @DISCOUNT_CODE_SEQ_ID BIGINT
	DECLARE @DISCOUNT_PERC BIGINT
	DECLARE @DISCOUNT_CODE NVARCHAR(100)
	DECLARE @TOTAL_AMOUNT MONEY
	DECLARE @VAT_PERCENTAGE MONEY
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_DISCOUNT_CODE NVARCHAR(200)


	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_AOF BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PS BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_IT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PR BIGINT

	DECLARE @ENTITY_DISPLAY_NAME_WSPSM NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_WSPSD NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_AOF NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_CONTACT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_PRODUCT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_PS NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_IT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_PR NVARCHAR(100)
	DECLARE @PAYMENT_AMOUNT MONEY

	DECLARE @PRODUCT_SALE_DETAILS_SEQ_ID BIGINT
	DECLARE @PRODUCT_ID NVARCHAR(100)
	DECLARE @GROSS_AMOUNT MONEY
	DECLARE @NET_AMOUNT MONEY
	DECLARE @VAT_AMOUNT MONEY
	DECLARE @UNIT_PRICE MONEY
	DECLARE @QUANTITY BIGINT
	DECLARE @PRODUCT_NET_AMOUNT MONEY
	DECLARE @PRODUCT_VAT_AMOUNT MONEY
	DECLARE @PRODUCT_SALE_MASTER_NET_AMOUNT MONEY
	DECLARE @PRODUCT_SALE_MASTER_VAT_AMOUNT MONEY
	DECLARE @VAT_RATE NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_VAT_RATE NVARCHAR(100)

	DECLARE @ENTITY_DISPLAY_NAME_MEMBER NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER BIGINT	
	DECLARE @MEMBER_SEQ_ID BIGINT
	DECLARE @MEMBER_CURRICULUM_CREDITS MONEY
	DECLARE @PAY_BY_INVOICE NVARCHAR(1)

	SET @USER = 'WEB'

	SET @SRM_CLIENTS_SEQ_ID = 17
	SET @ENTITY_DISPLAY_NAME_WSPSM = 'WEB_SERVICE_PRODUCT_SALE_MASTER'
	SET @ENTITY_DISPLAY_NAME_WSPSD = 'WEB_SERVICE_PRODUCT_SALE_DETAIL'
	SET @ENTITY_DISPLAY_NAME_AOF = 'AREA_OF_FOCUS'
	SET @ENTITY_DISPLAY_NAME_CONTACT = 'CONTACT'
	SET @ENTITY_DISPLAY_NAME_PRODUCT = 'PRODUCT'
	SET @ENTITY_DISPLAY_NAME_PS = 'PRODUCT_SALE'
	SET @ENTITY_DISPLAY_NAME_IT = 'INVOICE_TRANSACTION'
	SET @ENTITY_DISPLAY_NAME_PR = 'PRODUCT_PRICING'
	SET @ENTITY_DISPLAY_NAME_VAT_RATE = 'VAT_RATE'
	SET @ENTITY_DISPLAY_NAME_MEMBER = 'MEMBER'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSPSM 
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSPSD
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_AOF = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_AOF 
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_CONTACT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PRODUCT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PS = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PS
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_IT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_IT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PR = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PR
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_VAT_RATE
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MEMBER
	
	-- GET MODULE
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MODULE', @ATTRIBUTE_DISPLAY_NAME = 'PRODUCT_SALE', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MODULE OUTPUT, @DESCRIPTION = @MODULE_DESCRIPTION OUTPUT

	SELECT 
		@ATTRIBUTE_001_SLAE_ID = ATTRIBUTE_001, 
		@ATTRIBUTE_002_USER_NAME = ATTRIBUTE_002, 
		@ATTRIBUTE_026_CURRICULUM_CREDITS_USED = ISNULL(ATTRIBUTE_026, 'N'), 
		@PAYMENT_AMOUNT = ATTRIBUTE_025, 
		@PRODUCT_SALE_MASTER_NET_AMOUNT = ISNULL(ATTRIBUTE_038, 0), 
		@DISCOUNT_CODE = ATTRIBUTE_031, 
		@PAY_BY_INVOICE = ATTRIBUTE_029
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM AND SEQ_ID = @WEB_SERVICE_PRODUCT_SALE_MASTER_SEQ_ID


	IF ISNULL(@ATTRIBUTE_001_SLAE_ID, '') = ''
	BEGIN
		SET @ERROR = 0
		SET @ERROR_DESCRIPTION = 'THIS ORDER CANNOT BE PROCESSED. NO SALE ID HAS BEEN PROVIDED'
		RETURN
	END

	-- *********************************************************************************
	-- Start - Populate Net Amount & VAT amount for Product Sale Detail & Product Sale Master
	-- *********************************************************************************
	SET @NET_AMOUNT = 0
	SET @PRODUCT_SEQ_ID = 0

	DECLARE CUR_PRODUCT_SALE_DETAIL CURSOR STATIC FOR
	SELECT  SEQ_ID, ISNULL(ATTRIBUTE_012,0),  ATTRIBUTE_011, ATTRIBUTE_013, ATTRIBUTE_015 , ATTRIBUTE_005, ATTRIBUTE_006
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD AND ATTRIBUTE_001 = @ATTRIBUTE_001_SLAE_ID
	
	OPEN CUR_PRODUCT_SALE_DETAIL
	FETCH NEXT FROM CUR_PRODUCT_SALE_DETAIL INTO @PRODUCT_SALE_DETAILS_SEQ_ID, @NET_AMOUNT, @VAT_AMOUNT, @GROSS_AMOUNT, @PRODUCT_ID, @UNIT_PRICE, @QUANTITY

	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		SET @QUANTITY = ISNULL(@QUANTITY, 1)

		IF ISNULL(@NET_AMOUNT, 0) = 0
		BEGIN
			SELECT @PRODUCT_SEQ_ID = SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT
			AND ATTRIBUTE_001 = @PRODUCT_ID

			SET @PRODUCT_NET_AMOUNT = 0
			SET @PRODUCT_VAT_AMOUNT = 0
			SET @GROSS_AMOUNT = 0

			SELECT @PRODUCT_NET_AMOUNT = ATTRIBUTE_006, @PRODUCT_VAT_AMOUNT = ATTRIBUTE_007 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PR
			AND ATTRIBUTE_002 = @PRODUCT_SEQ_ID AND CAST(ATTRIBUTE_006 AS MONEY) + CAST(ATTRIBUTE_007 AS MONEY) = @UNIT_PRICE

			SET @PRODUCT_NET_AMOUNT = ISNULL(@PRODUCT_NET_AMOUNT, 0) * @QUANTITY
			SET @PRODUCT_VAT_AMOUNT = ISNULL(@PRODUCT_VAT_AMOUNT, 0) * @QUANTITY
			
			SET @GROSS_AMOUNT = @PRODUCT_NET_AMOUNT + @PRODUCT_VAT_AMOUNT

			UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
			SET ATTRIBUTE_012 = @PRODUCT_NET_AMOUNT, ATTRIBUTE_011 = @PRODUCT_VAT_AMOUNT, ATTRIBUTE_013 = @GROSS_AMOUNT
			WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD AND SEQ_ID = @PRODUCT_SALE_DETAILS_SEQ_ID
		END
		
		SET @NET_AMOUNT = 0
		FETCH NEXT FROM CUR_PRODUCT_SALE_DETAIL INTO @PRODUCT_SALE_DETAILS_SEQ_ID, @NET_AMOUNT, @VAT_AMOUNT, @GROSS_AMOUNT, @PRODUCT_ID, @UNIT_PRICE, @QUANTITY
	END
	CLOSE CUR_PRODUCT_SALE_DETAIL
	DEALLOCATE CUR_PRODUCT_SALE_DETAIL
	

	SELECT @PRODUCT_SALE_MASTER_NET_AMOUNT = SUM(ISNULL(CAST(ATTRIBUTE_012 AS MONEY), 0)), @PRODUCT_SALE_MASTER_VAT_AMOUNT = SUM(ISNULL(CAST(ATTRIBUTE_011 AS MONEY), 0))
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD AND ATTRIBUTE_001 = @ATTRIBUTE_001_SLAE_ID
		
	UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA SET ATTRIBUTE_038 = @PRODUCT_SALE_MASTER_NET_AMOUNT, ATTRIBUTE_039 = @PRODUCT_SALE_MASTER_VAT_AMOUNT
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM AND SEQ_ID = @WEB_SERVICE_PRODUCT_SALE_MASTER_SEQ_ID

	-- *********************************************************************************
	-- End - Populate Net Amount & VAT amount for Product Sale Detail & Product Sale Master
	-- *********************************************************************************



	SET @CONTACT_SEQ_ID = NULL

	IF ISNULL(@ATTRIBUTE_002_USER_NAME, '') <> '' 
	BEGIN
		SET @PIVOT_RETURN_VALUE = NULL

		EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT, @ATTRIBUTE_DISPLAY_NAME = 'LOGIN_USER_NAME', @OPERATOR_ID = 3, @SEARCH_VALUE = @ATTRIBUTE_002_USER_NAME, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT

		IF ISNULL(@PIVOT_RETURN_VALUE, '') <> ''
		BEGIN
			SELECT @CONTACT_SEQ_ID = DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ',')
		END
			
	END

	PRINT 'Helloooo 1'
	PRINT @CONTACT_SEQ_ID

	IF ISNULL(@CONTACT_SEQ_ID, 0) = 0 -- CREATE A NEW CONTACT
	BEGIN
		EXEC [dbo].[GET_CREATE_ACCOUNT_CONTACT_PS_IMPORT]
			@EXTERNAL_ID = @ATTRIBUTE_001_SLAE_ID,
			@USER = @USER,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@CONTACT = @CONTACT_SEQ_ID OUTPUT,
			@ACCOUNT = @ACCOUNT_SEQ_ID OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END

	IF ISNULL(@CONTACT_SEQ_ID, 0) = 0
	BEGIN
		PRINT 'ERROR ----- CONTACT NOT FOUND, CANNOT CONTINUE'
		SET @ERROR = 1
		SET @ERROR_DESCRIPTION = 'ERROR ----- CONTACT NOT FOUND, CANNOT CONTINUE'
		RETURN
	END

	-- GET CONTACT NAME
	SELECT @ATTRIBUTE_001_LABEL_NAME = ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT
		AND SEQ_ID = @CONTACT_SEQ_ID

	PRINT 'Hellooooo 2' 
	PRINT @ATTRIBUTE_001_LABEL_NAME

	-- ADD PRODUCT_SALE AND INVOICE_TRANSACTION
	EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD, @ATTRIBUTE_DISPLAY_NAME = 'SALE_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @ATTRIBUTE_001_SLAE_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT

	
	DECLARE CUS_SALES CURSOR STATIC LOCAL FOR 
	SELECT ATTRIBUTE_005,
		ATTRIBUTE_006,
		ATTRIBUTE_007,
		ATTRIBUTE_008,
		ATTRIBUTE_009,
		ATTRIBUTE_010,
		ATTRIBUTE_011,
		ATTRIBUTE_012,
		ATTRIBUTE_013,
		ATTRIBUTE_015
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSD
		AND SEQ_ID IN (SELECT DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ','))

	OPEN CUS_SALES

	FETCH NEXT FROM CUS_SALES INTO 
		@ATTRIBUTE_005_UNIT_PRICE,
		@ATTRIBUTE_006_QUANTITY, 
		@ATTRIBUTE_007_TOTAL_PRICE,
		@ATTRIBUTE_008_DISCOUNT_PERCENTAGE,
		@ATTRIBUTE_009_DISCOUNT_AMOUNT,
		@ATTRIBUTE_010_VAT_PERCENTAGE,
		@ATTRIBUTE_011_VAT_AMOUNT,
		@ATTRIBUTE_012_NET_AMOUNT,
		@ATTRIBUTE_013_GROSS_AMOUNT,
		@ATTRIBUTE_015_PRODUCT_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
	
		--EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT, @ATTRIBUTE_DISPLAY_NAME = 'PRODUCT_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @ATTRIBUTE_015_PRODUCT_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT
		--SELECT @PRODUCT_SEQ_ID = DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ',')
		--print '@DISCOUNT_CODE ' + @DISCOUNT_CODE
		--EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT, @ATTRIBUTE_DISPLAY_NAME = 'PRODUCT_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @ATTRIBUTE_015_PRODUCT_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PRODUCT_SEQ_ID OUTPUT, @DESCRIPTION = @ATTRIBUTE_015_PRODUCT_ID OUTPUT

		SELECT 
			@PRODUCT_SEQ_ID = SEQ_ID,
			@ATTRIBUTE_002_PRODUCT = ATTRIBUTE_002,
			@ATTRIBUTE_005_PRODUCT = ATTRIBUTE_005,
			@ATTRIBUTE_006_PRODUCT = ATTRIBUTE_006,
			@ATTRIBUTE_007_PRODUCT = ATTRIBUTE_007,
			@ATTRIBUTE_008_PRODUCT = ATTRIBUTE_008
		FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
		WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
			AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT
			AND ATTRIBUTE_001 = @ATTRIBUTE_015_PRODUCT_ID

		IF ISNULL(@ATTRIBUTE_010_VAT_PERCENTAGE, 0.00) = 0.00 AND ISNULL(@ATTRIBUTE_011_VAT_AMOUNT, 0.00) > 0.00
			SELECT  @ATTRIBUTE_010_VAT_PERCENTAGE = ATTRIBUTE_006 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SEQ_ID = @ATTRIBUTE_005_PRODUCT
			
		-- UPDATE QUANTITY IN HAND 
		PRINT 'Helllooooo 3'
		PRINT @PRODUCT_SEQ_ID
		PRINT @ATTRIBUTE_006_QUANTITY

		EXEC [dbo].[GET_UPDATE_QUANTITY_IN_HAND_PS]
			@PRODUCT_SEQ_ID = @PRODUCT_SEQ_ID,
			@QUANTITY_SOLD = @ATTRIBUTE_006_QUANTITY,
			@USER = @USER,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		IF ISNULL(@ATTRIBUTE_005_UNIT_PRICE, 0) = 0
		BEGIN
			SET @ATTRIBUTE_005_UNIT_PRICE = @ATTRIBUTE_007_TOTAL_PRICE / @ATTRIBUTE_006_QUANTITY
		END
		
		
		IF ISNULL(@DISCOUNT_CODE,'') <> ''
		BEGIN
			SET @DISCOUNT_PERC = 0

			-- VAT RATE For given Product
			SET @VAT_PERCENTAGE = 0
			SELECT @VAT_RATE = ATTRIBUTE_005 FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT AND ATTRIBUTE_001 = @ATTRIBUTE_015_PRODUCT_ID
			IF ISNULL(@VAT_RATE, '') <> ''
			BEGIN
				SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_VAT_RATE
				SELECT @VAT_PERCENTAGE = ATTRIBUTE_006 FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE AND SEQ_ID = @VAT_RATE
				PRINT '@VAT_PERCENTAGE ' + CAST(@VAT_PERCENTAGE AS NVARCHAR(100))
			END

			SET @ENTITY_DISPLAY_NAME_DISCOUNT_CODE = 'DISCOUNT_CODE'
			SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_DISCOUNT_CODE
	
			SELECT @DISCOUNT_PERC = ATTRIBUTE_004 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
			AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE AND ATTRIBUTE_001 = @DISCOUNT_CODE

			IF ISNULL(@DISCOUNT_PERC,0) > 0
			BEGIN
				PRINT '@DISCOUNT_PERC ' + CAST(@DISCOUNT_PERC AS NVARCHAR)
				PRINT '@ATTRIBUTE_012_NET_AMOUNT ' + ISNULL(CAST(@ATTRIBUTE_012_NET_AMOUNT AS NVARCHAR(100)), 'NULL')
				PRINT '@ATTRIBUTE_011_VAT_AMOUNT ' + ISNULL(CAST(@ATTRIBUTE_011_VAT_AMOUNT AS NVARCHAR(100)), 'NULL')

				SET @TOTAL_AMOUNT = @ATTRIBUTE_012_NET_AMOUNT / (1.00 - ROUND(@DISCOUNT_PERC/100.00,2))			
				PRINT '@TOTAL_AMOUNT before condition ' + CAST(@TOTAL_AMOUNT AS NVARCHAR(100))						
				IF @PAYMENT_AMOUNT = @ATTRIBUTE_012_NET_AMOUNT
				BEGIN
					PRINT '1st Case'
					SET @ATTRIBUTE_012_NET_AMOUNT = @TOTAL_AMOUNT
					SET @ATTRIBUTE_013_GROSS_AMOUNT = @TOTAL_AMOUNT		
					IF @ATTRIBUTE_011_VAT_AMOUNT > 0
						SET @ATTRIBUTE_011_VAT_AMOUNT = ROUND(@TOTAL_AMOUNT * @VAT_PERCENTAGE / 100, 2)
				END
				ELSE IF @PAYMENT_AMOUNT = @ATTRIBUTE_012_NET_AMOUNT + @ATTRIBUTE_011_VAT_AMOUNT
				BEGIN
					PRINT '2nd Case'
					SET @ATTRIBUTE_012_NET_AMOUNT = @TOTAL_AMOUNT
					IF @ATTRIBUTE_011_VAT_AMOUNT > 0
						SET @ATTRIBUTE_011_VAT_AMOUNT = ROUND(@TOTAL_AMOUNT * @VAT_PERCENTAGE / 100, 2)
					SET @ATTRIBUTE_013_GROSS_AMOUNT = @ATTRIBUTE_012_NET_AMOUNT + @ATTRIBUTE_011_VAT_AMOUNT
					PRINT '2nd case end'
				END
				PRINT '@TOTAL_AMOUNT ' + CAST(@TOTAL_AMOUNT AS NVARCHAR(100))
				PRINT '@ATTRIBUTE_012_NET_AMOUNT ' + CAST(@ATTRIBUTE_012_NET_AMOUNT AS NVARCHAR(100))
				PRINT '@ATTRIBUTE_011_VAT_AMOUNT ' + CAST(@ATTRIBUTE_011_VAT_AMOUNT AS NVARCHAR(100))
				PRINT '@ATTRIBUTE_013_GROSS_AMOUNT ' + CAST(@ATTRIBUTE_013_GROSS_AMOUNT AS NVARCHAR(100))
			END
		END

		PRINT 'CURRICULUM CREDIT ....'
		-- Decrement Curriculum Credits from Member Account
		DECLARE @ATTRIBUTE_029_PAID_BY BIGINT
		
		IF @ATTRIBUTE_026_CURRICULUM_CREDITS_USED = 'Y'
		BEGIN
			SELECT @MEMBER_SEQ_ID = SEQ_ID,  @MEMBER_CURRICULUM_CREDITS = ISNULL(ATTRIBUTE_035,0) , @ATTRIBUTE_029_PAID_BY=ISNULL(ATTRIBUTE_029,0)
			FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND ATTRIBUTE_017 = @CONTACT_SEQ_ID
			
			PRINT '@MEMBER_CURRICULUM_CREDITS ' + CAST(@MEMBER_CURRICULUM_CREDITS AS NVARCHAR(100)) 
			PRINT '@ATTRIBUTE_013_GROSS_AMOUNT ' + CAST(@ATTRIBUTE_013_GROSS_AMOUNT AS NVARCHAR(100))
			
			IF ISNULL(@ATTRIBUTE_029_PAID_BY,0)=0
			BEGIN
					IF @MEMBER_CURRICULUM_CREDITS>0
					BEGIN
						UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
						SET ATTRIBUTE_035 = ATTRIBUTE_035 - @ATTRIBUTE_013_GROSS_AMOUNT
						WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND ATTRIBUTE_017 = @CONTACT_SEQ_ID
						
						EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
							@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER,
							@CUS_ENTITY_DATA_SEQ_ID = @MEMBER_SEQ_ID,
							@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
							@ERROR = @ERROR OUTPUT,
							@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
					END
			END
			ELSE IF @ATTRIBUTE_029_PAID_BY>0
			BEGIN
					SELECT @MEMBER_SEQ_ID = SEQ_ID,  @MEMBER_CURRICULUM_CREDITS = ISNULL(ATTRIBUTE_035,0)
					FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND ATTRIBUTE_015 = @ATTRIBUTE_029_PAID_BY
					
					IF @MEMBER_CURRICULUM_CREDITS>0
					BEGIN
						UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
						SET ATTRIBUTE_035 = ATTRIBUTE_035 - @ATTRIBUTE_013_GROSS_AMOUNT
						WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND ATTRIBUTE_015 = @ATTRIBUTE_029_PAID_BY
						
						
						EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
							@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER,
							@CUS_ENTITY_DATA_SEQ_ID = @MEMBER_SEQ_ID,
							@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
							@ERROR = @ERROR OUTPUT,
							@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
						
						EXEC [dbo].[GET_POPULATE_MEMBERSHIP] 
							@CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
							@CUS_ENTITY_DATA_SEQ_ID = @MEMBER_SEQ_ID,
							@ERROR = @ERROR OUTPUT,
							@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
					END
			END
				
		END
	
		-- ADD DATA IN PRODUCT_SALES
		EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
			@ATTRIBUTE_004 = @CONTACT_SEQ_ID, --CONTACT
			@ATTRIBUTE_005 = @ATTRIBUTE_001_LABEL_NAME, --CONTACT_NAME
			@ATTRIBUTE_006 = @PRODUCT_SEQ_ID, --PRODUCT
			@ATTRIBUTE_007 = @ATTRIBUTE_002_PRODUCT, --PRODUCT_NAME
			@ATTRIBUTE_008 = @TODAY, --TRANSACTION_DATE
			@ATTRIBUTE_009 = @ATTRIBUTE_007_PRODUCT, --LEDGER_ACCOUNT
			@ATTRIBUTE_010 = @ATTRIBUTE_008_PRODUCT, --LEDGER_ACCOUNT_NAME
			@ATTRIBUTE_011 = @ATTRIBUTE_005_PRODUCT, --VAT_RATE
			@ATTRIBUTE_012 = @ATTRIBUTE_006_PRODUCT, --VAT_RATE_NAME
			@ATTRIBUTE_013 = @ATTRIBUTE_010_VAT_PERCENTAGE, --VAT_PERCENTAGE
			@ATTRIBUTE_014 = @ATTRIBUTE_005_UNIT_PRICE, --UNIT_PRICE
			@ATTRIBUTE_015 = @ATTRIBUTE_008_DISCOUNT_PERCENTAGE, --DISCOUNT_PERCENTAGE
			@ATTRIBUTE_016 = @ATTRIBUTE_009_DISCOUNT_AMOUNT, --DISCOUNT_AMOUNT
			@ATTRIBUTE_017 = @ATTRIBUTE_012_NET_AMOUNT, --NET_AMOUNT
			@ATTRIBUTE_018 = @ATTRIBUTE_011_VAT_AMOUNT, --VAT_AMOUNT
			@ATTRIBUTE_019 = @ATTRIBUTE_013_GROSS_AMOUNT, --GROSS_AMOUNT
			@ATTRIBUTE_020 = @ATTRIBUTE_006_QUANTITY, --QUANTITY
			@ATTRIBUTE_021 = @ATTRIBUTE_007_TOTAL_PRICE, --TOTAL_PRICE
			@ATTRIBUTE_025 = @ATTRIBUTE_026_CURRICULUM_CREDITS_USED, --SOLD_AGAINST_CURRICULUM_CREDITS
			@ATTRIBUTE_032 = @ATTRIBUTE_001_SLAE_ID, --EXTERNAL_ID
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PS,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@DATE_CREATED = NULL,
			@CREATED_BY = @USER,
			@RETURN_SEQ_ID = @PRODUCT_SALE_SEQ_ID OUTPUT

			-- ADD DATA IN INVOICE_TRANSACTION
			EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_001 = @ATTRIBUTE_002_PRODUCT, --PRODUCT_NAME
				@ATTRIBUTE_002 = @MODULE, --MODULE
				@ATTRIBUTE_003 = @MODULE_DESCRIPTION, --MODULE_DESCRIPTION
				@ATTRIBUTE_004 = @PRODUCT_SALE_SEQ_ID, --PARENT_ID
				@ATTRIBUTE_005 = @PRODUCT_SEQ_ID, --PRODUCT
				@ATTRIBUTE_008 = @CONTACT_SEQ_ID, --CONTACT
				@ATTRIBUTE_009 = @ATTRIBUTE_001_LABEL_NAME, --CONTACT_NAME
				@ATTRIBUTE_011 = @TODAY,
				@ATTRIBUTE_012 = @ATTRIBUTE_007_PRODUCT, --LEDGER_ACCOUNT
				@ATTRIBUTE_013 = @ATTRIBUTE_008_PRODUCT, --LEDGER_ACCOUNT_NAME
				@ATTRIBUTE_014 = @ATTRIBUTE_005_PRODUCT, --VAT_RATE
				@ATTRIBUTE_015 = @ATTRIBUTE_006_PRODUCT, --VAT_RATE_NAME
				@ATTRIBUTE_016 = @ATTRIBUTE_010_VAT_PERCENTAGE, --VAT_PERCENTAGE
				@ATTRIBUTE_017 = @ATTRIBUTE_005_UNIT_PRICE, --UNIT_PRICE
				@ATTRIBUTE_018 = @ATTRIBUTE_006_QUANTITY, --QUANTITY
				@ATTRIBUTE_019 = @ATTRIBUTE_007_TOTAL_PRICE, --TOTAL_PRICE
				@ATTRIBUTE_020 = @ATTRIBUTE_008_DISCOUNT_PERCENTAGE, --DISCOUNT_PERCENTAGE
				@ATTRIBUTE_021 = @ATTRIBUTE_009_DISCOUNT_AMOUNT, --DISCOUNT_AMOUNT
				@ATTRIBUTE_022 = @ATTRIBUTE_012_NET_AMOUNT, --NET_AMOUNT
				@ATTRIBUTE_023 = @ATTRIBUTE_011_VAT_AMOUNT, --VAT_AMOUNT
				@ATTRIBUTE_024 = @ATTRIBUTE_013_GROSS_AMOUNT, --GROSS_AMOUNT
				@ATTRIBUTE_030 = @ATTRIBUTE_001_SLAE_ID, --EXTERNAL_ID
				@ATTRIBUTE_031 = @ATTRIBUTE_026_CURRICULUM_CREDITS_USED, --SOLD_AGAINST_CURRICULUM_CREDITS
				@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_IT,
				@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
				@DATE_CREATED = NULL,
				@CREATED_BY = @USER,
				@RETURN_SEQ_ID = @INVOICE_TRANSACTION_SEQ_ID OUTPUT


		FETCH NEXT FROM CUS_SALES INTO 
			@ATTRIBUTE_005_UNIT_PRICE,
			@ATTRIBUTE_006_QUANTITY,
			@ATTRIBUTE_007_TOTAL_PRICE,
			@ATTRIBUTE_008_DISCOUNT_PERCENTAGE,
			@ATTRIBUTE_009_DISCOUNT_AMOUNT,
			@ATTRIBUTE_010_VAT_PERCENTAGE,
			@ATTRIBUTE_011_VAT_AMOUNT,
			@ATTRIBUTE_012_NET_AMOUNT,
			@ATTRIBUTE_013_GROSS_AMOUNT,
			@ATTRIBUTE_015_PRODUCT_ID
	END
	CLOSE CUS_SALES
	DEALLOCATE CUS_SALES

	EXEC [dbo].[GET_CREATE_FINANCE_BATCH]
		@EXTERNAL_ID = @ATTRIBUTE_001_SLAE_ID,
		@ACCOUNT = NULL,
		@ACCOUNT_NAME = NULL,
		@CONTACT = @CONTACT_SEQ_ID,
		@CONTACT_NAME = @ATTRIBUTE_001_LABEL_NAME,
		@USER = @USER,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@FINANCE_TRANSACTION_SEQ_ID = @FINANCE_TRANSACTION_SEQ_ID OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT


	IF ISNULL(@PAY_BY_INVOICE, 'N')  = 'N' AND @PAYMENT_AMOUNT > 0 AND ISNULL(@ATTRIBUTE_026_CURRICULUM_CREDITS_USED, 'N') = 'N'
	BEGIN
		EXEC [dbo].[GET_CREATE_RECEIPT_BATCH]
			@EXTERNAL_ID = @WEB_SERVICE_PRODUCT_SALE_MASTER_SEQ_ID,
			@ACCOUNT = NULL,
			@ACCOUNT_NAME = NULL,
			@CONTACT = @CONTACT_SEQ_ID,
			@CONTACT_NAME = @ATTRIBUTE_001_LABEL_NAME,
			@PAYMENT_AMOUNT = @PAYMENT_AMOUNT,
			@FINANCE_TRANSACTION_SEQ_ID = @FINANCE_TRANSACTION_SEQ_ID,
			@USER = @USER,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@PAYMENT_BATCH_TRANSACTION_SEQ_ID = @PAYMENT_BATCH_TRANSACTION_SEQ_ID OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = 'Process completed successfully'
  
	SELECT @ERROR AS ERROR, @ERROR_DESCRIPTION AS ERROR_DESCRIPTION 
END








;






--EXEC [DBO].GET_APPLY_PS_DATA_TO_API

-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_APPLY_PS_DATA_TO_API]
	-- Add the parameters for the stored procedure here
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_PS_DATA_TO_API]'
	
	SET ANSI_NULLS ON
	SET QUOTED_IDENTIFIER ON
	--SET NOCOUNT ON;

	DECLARE @PRODUCT_ID NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT

	SET @SRM_CLIENTS_SEQ_ID = 17
	SET @SRM_CLIENT_ENTITIES_SEQ_ID = 2568

	DECLARE CUR_PRODUCT CURSOR FOR
		SELECT ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

	OPEN CUR_PRODUCT 

	FETCH NEXT FROM CUR_PRODUCT INTO @PRODUCT_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT 'REPLICATING PRODUCT ' + CAST(@PRODUCT_ID AS NVARCHAR)

		exec  [SRM-Framework_New].[dbo].[GET_SYNCH_PRODUCTS]  
			@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@m_PRODUCT_ID =  @PRODUCT_ID

		FETCH NEXT FROM CUR_PRODUCT INTO @PRODUCT_ID
	END

	CLOSE CUR_PRODUCT
	DEALLOCATE CUR_PRODUCT

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''

	--PRINT 'END POPULATE PIVOT _____________________________'
END
	





;






--EXEC [DBO].GET_APPLY_PS_DATA_TO_API_MISSING_PRODUCTS

-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_APPLY_PS_DATA_TO_API_ALL_PRODUCTS]
	-- Add the parameters for the stored procedure here
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_PS_DATA_TO_API_MISSING_PRODUCTS]'
	
	SET ANSI_NULLS ON
	SET QUOTED_IDENTIFIER ON
	--SET NOCOUNT ON;

	DECLARE @PRODUCT_ID NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSP BIGINT

	SET @SRM_CLIENTS_SEQ_ID = 17
	SET @SRM_CLIENT_ENTITIES_SEQ_ID = 2568
	SET @SRM_CLIENT_ENTITIES_SEQ_ID_WSP = 2724

	DECLARE CUR_PRODUCT CURSOR FOR
		SELECT ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE DELETED = 'N' AND ISNULL(ATTRIBUTE_039, 'N') = 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
		--AND ATTRIBUTE_001 NOT IN (SELECT ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSP)

	OPEN CUR_PRODUCT 

	FETCH NEXT FROM CUR_PRODUCT INTO @PRODUCT_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT 'REPLICATING PRODUCT ' + CAST(@PRODUCT_ID AS NVARCHAR)

		exec  [SRM-Framework_New].[dbo].[GET_SYNCH_PRODUCTS]  
			@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@m_PRODUCT_ID =  @PRODUCT_ID

		FETCH NEXT FROM CUR_PRODUCT INTO @PRODUCT_ID
	END

	CLOSE CUR_PRODUCT
	DEALLOCATE CUR_PRODUCT

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''

	--PRINT 'END POPULATE PIVOT _____________________________'
END
	





;






--EXEC [DBO].GET_APPLY_PS_DATA_TO_API_MISSING_PRODUCTS

-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_APPLY_PS_DATA_TO_API_MISSING_PRODUCTS]
	-- Add the parameters for the stored procedure here
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_PS_DATA_TO_API_MISSING_PRODUCTS]'
	
	SET ANSI_NULLS ON
	SET QUOTED_IDENTIFIER ON
	--SET NOCOUNT ON;

	DECLARE @PRODUCT_ID NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSP BIGINT

	SET @SRM_CLIENTS_SEQ_ID = 17
	SET @SRM_CLIENT_ENTITIES_SEQ_ID = 2568
	SET @SRM_CLIENT_ENTITIES_SEQ_ID_WSP = 2724

	DECLARE CUR_PRODUCT CURSOR FOR
		SELECT ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE DELETED = 'N' AND ISNULL(ATTRIBUTE_039, 'N') = 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
		AND ATTRIBUTE_001 NOT IN (SELECT ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSP)

	OPEN CUR_PRODUCT 

	FETCH NEXT FROM CUR_PRODUCT INTO @PRODUCT_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT 'REPLICATING PRODUCT ' + CAST(@PRODUCT_ID AS NVARCHAR)

		exec  [SRM-Framework_New].[dbo].[GET_SYNCH_PRODUCTS]  
			@m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@m_PRODUCT_ID =  @PRODUCT_ID

		FETCH NEXT FROM CUR_PRODUCT INTO @PRODUCT_ID
	END

	CLOSE CUR_PRODUCT
	DEALLOCATE CUR_PRODUCT

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''

	--PRINT 'END POPULATE PIVOT _____________________________'
END
	





;







-- =============================================
-- Author:		<Asif Shehzad>
-- Create date: <07/06/2016,,>
-- Description:	<Get or create account contact bank,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_CHECK_ACOUNT_CONTACT_BANK]
	-- Add the parameters for the stored procedure here
	@OLD_BANK BIGINT = NULL,
	@CONTACT BIGINT = 0,
	@CONTACT_NAME NVARCHAR(100) = NULL,
	@ACCOUNT BIGINT = 0,
	@ACCOUNT_NAME NVARCHAR(100) = NULL,
	@ACCOUNT_NUMBER NVARCHAR(30) = NULL,
	@SORT_CODE NVARCHAR(100) = NULL,
	@ACCOUNT_TITLE NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@USER NVARCHAR(100) = NULL,
	@NEW_BANK BIGINT = 0 OUTPUT,
	@NEW_BANK_NAME NVARCHAR(100) = NULL OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[GET_CHECK_ACOUNT_CONTACT_BANK]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CHECK_ACOUNT_CONTACT_BANK]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @OLD_ACCOUNT_NUMBER NVARCHAR(30) = NULL
	DECLARE @OLD_SORT_CODE NVARCHAR(100) = NULL
	DECLARE @OLD_ACCOUNT_TITLE NVARCHAR(100) = NULL
	DECLARE @OLD_CONTACT BIGINT = 0
	DECLARE @OLD_ACCOUNT BIGINT = 0

	SELECT 
	@OLD_SORT_CODE = ATTRIBUTE_001,
	@OLD_ACCOUNT_NUMBER = ATTRIBUTE_002,
	@OLD_ACCOUNT_TITLE = ATTRIBUTE_009,
	@OLD_CONTACT = ISNULL(ATTRIBUTE_005, 0),
	@OLD_ACCOUNT = ISNULL(ATTRIBUTE_007, 0)
	FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SEQ_ID=@OLD_BANK AND SRM_CLIENT_ENTITIES_SEQ_ID=2576 AND DELETED='N'
	
	PRINT @OLD_ACCOUNT + @ACCOUNT
	
	IF (@OLD_SORT_CODE = @SORT_CODE AND @OLD_ACCOUNT_NUMBER = @ACCOUNT_NUMBER AND @OLD_ACCOUNT_TITLE = @ACCOUNT_TITLE AND
		@OLD_CONTACT = ISNULL(@CONTACT, 0) AND @OLD_ACCOUNT = ISNULL(@ACCOUNT,0))
	BEGIN
		PRINT 'BANK IS SAME'
		SET @NEW_BANK = @OLD_BANK
		SET @NEW_BANK_NAME = @OLD_ACCOUNT_NUMBER
	END
	ELSE -- NEW DETAIL ALREADY LINKED TO CONTACT/ACCOUNT
	BEGIN
		SET @NEW_BANK = 0

		SELECT TOP 1
		@NEW_BANK = SEQ_ID,
		@NEW_BANK_NAME = ATTRIBUTE_002
		FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SEQ_ID!=ISNULL(@OLD_BANK,0) AND SRM_CLIENT_ENTITIES_SEQ_ID=2576 AND DELETED='N' AND SEQ_ID IN 

		(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52796 AND ATTRIBUTE_DECIMAL=ISNULL(@CONTACT,0) INTERSECT
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52798 AND ATTRIBUTE_DECIMAL=ISNULL(@ACCOUNT,0))

		AND @SORT_CODE = ATTRIBUTE_001 AND @ACCOUNT_NUMBER = ATTRIBUTE_002 AND @ACCOUNT_TITLE = ATTRIBUTE_009 

		ORDER BY SEQ_ID

		PRINT @NEW_BANK

		IF @NEW_BANK = 0
		BEGIN
			EXEC [dbo].[GET_CREATE_ACCOUNT_CONTACT_BANK]    
			@ACCOUNT = @ACCOUNT,    
			@ACCOUNT_NAME = @ACCOUNT_NAME,    
			@CONTACT = @CONTACT,    
			@CONTACT_NAME = @CONTACT_NAME,    
			@BRANCH_SORT_CODE = @SORT_CODE,    
			@BANK_BUILDING_SOCIETY_ACCOUNT_NUMBER = @ACCOUNT_NUMBER,    
			@NAME_OF_ACCOUNT_HOLDER = @ACCOUNT_TITLE,    
			@I_AM_ACCOUNT_HOLDER = NULL,    
			@USER = @USER,    
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
			@BANK = @NEW_BANK OUTPUT,    
			@BANK_NAME = @NEW_BANK_NAME OUTPUT,    
			@ERROR = @ERROR OUTPUT,    
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
		END
	END
		



	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
	
END








;

-- =============================================  
-- Author:  <Rauf Gill>  
-- Create date: <27/08/2024>  
-- Description: <Returns Configuration Value>  
-- =============================================  
/*  
SELECT * FROM CFG_CLIENT_SETTINGS WHERE CFG_SETTINGS_SEQ_ID  = 11  
SELECT * FROM CFG_SETTING_VALUES WHERE CFG_SETTINGS_SEQ_ID  = 11  
UPDATE CFG_SETTING_VALUES SET [DEFAULT] = 'Y' WHERE SEQ_ID = 26  
SELECT * FROM SRM_USERS WHERE SRM_CLIENTS_SEQ_ID  =500  
  
DECLARE @p_CONFIGURATION_ID BIGINT          -- SEQ_ID OF CONFIGURATION  
DECLARE @p_CLIENT_ID BIGINT                 -- SEQ_ID OF CLIENT  
DECLARE @p_USER_ID BIGINT  -- SEQ_ID OF USER  
DECLARE @p_USER_EMAIL NVARCHAR(100)  
DECLARE @p_CONFIGURATION_VALUE NVARCHAR(10) -- OUTPUT PARAMETER CONFIGURATION VALUE  
DECLARE @p_SUCCESS NVARCHAR(1)              -- OUTPUT PARAMETER  
  
SET @p_CONFIGURATION_ID = 41  
SET @p_CLIENT_ID = 500  
--SET @p_USER_ID = 9977  
SET @p_USER_EMAIL = 'smart@oomi.co.uk'  
  
EXEC [SRM-Framework_new].dbo.[GET_CLIENT_CONFIGURATION]  
 @p_CONFIGURATION_ID = @p_CONFIGURATION_ID,  
 --@p_CLIENT_ID = @p_CLIENT_ID,  
 --@p_USER_ID = @p_USER_ID,  
 @p_USER_EMAIL = @p_USER_EMAIL,  
 @p_CONFIGURATION_VALUE = @p_CONFIGURATION_VALUE OUTPUT,  
 @p_SUCCESS = @p_SUCCESS OUTPUT  
  
  
PRINT @p_SUCCESS  
PRINT @p_CONFIGURATION_VALUE  
*/  
  
CREATE PROCEDURE [dbo].[GET_CLIENT_CONFIGURATION]  
 -- Add the parameters for the stored procedure here  
 @p_CONFIGURATION_ID BIGINT = NULL,    -- SEQ_ID OF CONFIGURATION  
 @p_CLIENT_ID BIGINT = NULL,      -- SEQ_ID OF CLIENT  
 @p_USER_ID BIGINT = NULL,      -- SEQ_ID OF USER  
 @p_USER_EMAIL NVARCHAR(200) = NULL,    -- EMAIL OF USER  
 @p_CONFIGURATION_VALUE NVARCHAR(10) OUTPUT,  -- OUTPUT PARAMETER RETURNS CONFIGURATION VALUE  
 @p_SUCCESS CHAR(1) OUTPUT      -- OUTPUT PARAMETER RETURNS Y/N  
AS  
BEGIN  
 -- SET NOCOUNT ON added to prevent extra result sets from  
 -- interfering with SELECT statements.  
 SET NOCOUNT ON;  
  
 SET @p_CONFIGURATION_VALUE = NULL  
  
 SET @p_SUCCESS = 'Y'  
  
 IF (ISNULL(@p_CLIENT_ID , 0) = 0 AND ISNULL(@p_USER_ID , 0) = 0 AND ISNULL(@p_USER_EMAIL, '') = '') OR ISNULL(@p_CONFIGURATION_ID, 0) = 0  
 BEGIN  
  PRINT 'MISSING REQUIRED PARAMETER'  
  SET @p_SUCCESS = 'N'  
  RETURN  
 END  
  
 IF ISNULL(@p_CLIENT_ID , 0) <> 0  
 BEGIN  
  SET @p_CLIENT_ID = @p_CLIENT_ID  
 END  
 ELSE IF ISNULL(@p_CLIENT_ID , 0) = 0 AND ISNULL(@p_USER_ID , 0) <> 0  -- CLIENT NOT AVAILABLE BUT USER ID AVAILABLE  
 BEGIN  
  SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM dbO.SRM_USERS WHERE SEQ_ID = @p_USER_ID    
 END  
 ELSE IF ISNULL(@p_USER_EMAIL, '') <> '' -- CLIENT AND USER ID NOT AVAILABLE BUT USER EMAIL AVAILABLE  
 BEGIN  
   SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM dbO.SRM_USERS WHERE LOGIN_EMAIL = @p_USER_EMAIL  
 END  
  
 -- GET VALUE SETUP FOR THE CLIENT  
 SELECT TOP 1 @p_CONFIGURATION_VALUE = SETTING_VALUE FROM CFG_CLIENT_SETTINGS WHERE SRM_CLIENTS_SEQ_ID = @p_CLIENT_ID AND CFG_SETTINGS_SEQ_ID = @p_CONFIGURATION_ID AND (DELETED IS NULL OR DELETED = 'N') 
  
 -- GET DEFAULT VALUE WHEN CLIENT VALUE IS NOT FOUND  
 
 IF @p_CONFIGURATION_VALUE IS NULL OR @p_CONFIGURATION_VALUE = ''  
 BEGIN  
  SELECT TOP 1 @p_CONFIGURATION_VALUE = SETTING_VALUE FROM dbo.CFG_SETTING_VALUES WHERE CFG_SETTINGS_SEQ_ID = @p_CONFIGURATION_ID AND [DEFAULT] = 'Y' AND (DELETED IS NULL OR DELETED = 'N')  
 
 END  
 

 IF @p_CONFIGURATION_VALUE IS NULL OR @p_CONFIGURATION_VALUE = ''  
 BEGIN   
  SET @p_CONFIGURATION_VALUE = 0  
  SET @p_SUCCESS = 'N'  
 END  
  
    
END  

;



-- *****************************************************************************************************************
-- Created By: Adeel Hassan
-- Date Created: 08/09/2026
-- Summary: A process to return concatenated values of Assigned Add-ons
--******************************************************************************************************************

CREATE PROCEDURE [dbo].[GET_CONCATENATED_ASSIGNED_ADD_ONS]
	@p_MEMBER_SEQ_ID NVARCHAR(200),
	@p_USER_EMAIL NVARCHAR(200)
AS
BEGIN
	DECLARE @CLIENT_ID BIGINT
    DECLARE @strSQL NVARCHAR(1000)
    DECLARE @strSQL2 NVARCHAR(1000)
	DECLARE @ASSIGNED_ADD_ON_ENTITY_SEQ_ID BIGINT = 112808
	DECLARE @MEMBER_ENTITY_SEQ_ID BIGINT = 112782
	DECLARE @MEMBER_ATTRIBUTE_SEQ_ID BIGINT = 3062161
	DECLARE @ARCHIVED_ATTRIBUTE_SEQ_ID BIGINT = 3062170
	
	DECLARE @p_ASSIGNED_ADD_ONS_NAME NVARCHAR(1000)

		-- Get Client ID on the basis of User Email
	SELECT @CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USER_EMAIL

SET @strSQL = 'SELECT @p_ASSIGNED_ADD_ONS_NAME = STRING_AGG(CAST(C.ATTRIBUTE_001 AS NVARCHAR(100)), '' | '')
    FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10)) + '].dbo.CUS_ENTITY_DATA C
    INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10)) + '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I ON C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID
    INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10)) + '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I2 ON C.SEQ_ID = I2.CUS_ENTITY_DATA_SEQ_ID
    WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' 
    AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@ASSIGNED_ADD_ON_ENTITY_SEQ_ID AS NVARCHAR(100)) + '
    AND C.SRM_CLIENTS_SEQ_ID = ' + CAST(@CLIENT_ID AS NVARCHAR(100)) + '
    AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@MEMBER_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + '
    AND I.ATTRIBUTE_DECIMAL = ' + CAST(@p_MEMBER_SEQ_ID AS NVARCHAR(100)) + '
	AND I2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@ARCHIVED_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + '
    AND I2.ATTRIBUTE_BOOLEAN != ''Y''';
	
    EXEC sp_executesql @strSQL, 
						N'@p_ASSIGNED_ADD_ONS_NAME NVARCHAR(1000) OUTPUT, @CLIENT_ID BIGINT, @ASSIGNED_ADD_ON_ENTITY_SEQ_ID BIGINT, 
						@MEMBER_ATTRIBUTE_SEQ_ID BIGINT, @p_MEMBER_SEQ_ID BIGINT', 
						@p_ASSIGNED_ADD_ONS_NAME  OUTPUT, @CLIENT_ID, 
						@ASSIGNED_ADD_ON_ENTITY_SEQ_ID, @MEMBER_ATTRIBUTE_SEQ_ID, @p_MEMBER_SEQ_ID
	PRINT @strSQL
	
	PRINT @p_ASSIGNED_ADD_ONS_NAME

	SET @strSQL2 = 'UPDATE A
	set A.ATTRIBUTE_130 = @p_ASSIGNED_ADD_ONS_NAME
	FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10)) + '].dbo.CUS_ENTITY_DATA A
	WHERE SEQ_ID = '+ CAST(@p_MEMBER_SEQ_ID AS NVARCHAR(100))
	
	PRINT @strSQL2

    EXEC sp_executesql @strSQL2, 
						N'@CLIENT_ID BIGINT, @p_MEMBER_SEQ_ID BIGINT, @p_ASSIGNED_ADD_ONS_NAME NVARCHAR(1000)', 
						@CLIENT_ID,@p_MEMBER_SEQ_ID,  @p_ASSIGNED_ADD_ONS_NAME

	SET @strSQL2 = 'EXEC [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10)) + '].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
		 @SRM_CLIENT_ENTITIES_SEQ_ID = '+ CAST(@MEMBER_ENTITY_SEQ_ID AS NVARCHAR(100)) + ',
		 @CUS_ENTITY_DATA_SEQ_ID = '+ CAST(@p_MEMBER_SEQ_ID AS NVARCHAR(100)) + ',
		 @SRM_CLIENTS_SEQ_ID = '+ CAST(@CLIENT_ID AS NVARCHAR(100)) 
		 
	PRINT @strSQL2
END
;


-- *****************************************************************************************************************
-- Created By: Adeel Hassan
-- Date Created: 11/03/2025
-- Summary: A dynamic process to return concatenated values of a field based on given criterion
--******************************************************************************************************************

CREATE PROCEDURE GET_CONCATENATED_FIELD_VALUES
    @p_ENTITY_NAME NVARCHAR(200),
    @p_SELECT_FIELD_NAME NVARCHAR(200),
    @p_WHERE_FIELD_NAME NVARCHAR(200),
	@p_WHERE_FIELD_VALUE NVARCHAR(200),
	@p_USER_EMAIL NVARCHAR(200),
	@p_RETURN_VALUE NVARCHAR(1000) OUTPUT
AS
BEGIN
	DECLARE @CLIENT_ID BIGINT
    DECLARE @strSQL NVARCHAR(1000)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SELECT_FIELD_SYSTEM_NAME NVARCHAR(200)
	DECLARE @WHERE_FIELD_ATTRIBUTE_SEQ_ID BIGINT

		-- Get Client ID on the basis of User Email
	SELECT @CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USER_EMAIL

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITIES WHERE ENTITY_DISPLAY_NAME = @p_ENTITY_NAME AND SRM_CLIENTS_SEQ_ID = 500

	SELECT @SELECT_FIELD_SYSTEM_NAME = SCA.SYSTEM_NAME
	FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA, [SRM-Framework_New].DBO.SRM_ENTITY_ATTRIBUTES SCA WHERE SCA.SEQ_ID = SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND SCEA.ATTRIBUTE_DISPLAY_NAME = @p_SELECT_FIELD_NAME AND SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

	SELECT @WHERE_FIELD_ATTRIBUTE_SEQ_ID = SCEA.SEQ_ID
	FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA 
	WHERE SCEA.ATTRIBUTE_DISPLAY_NAME = @p_WHERE_FIELD_NAME AND SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

	SET @strSQL = 'SELECT @p_RETURN_VALUE = STRING_AGG(CAST(C.' + QUOTENAME(@SELECT_FIELD_SYSTEM_NAME) + ' AS NVARCHAR(100)), '','') 
                   FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C, 
							 [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I 
                   WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' AND C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID 
						 AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS NVARCHAR(100)) + 
						 ' AND C.SRM_CLIENTS_SEQ_ID = ' + CAST(@CLIENT_ID AS NVARCHAR(100)) +
						 ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =  ' + CAST(@WHERE_FIELD_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) +
						 ' AND I.ATTRIBUTE_DECIMAL = ' + CAST(@p_WHERE_FIELD_VALUE AS NVARCHAR(100))

	PRINT @strSQL
    EXEC sp_executesql @strSQL, 
						N'@p_RETURN_VALUE NVARCHAR(1000) OUTPUT, @SELECT_FIELD_SYSTEM_NAME NVARCHAR(200), @CLIENT_ID BIGINT, @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT, 
						@WHERE_FIELD_ATTRIBUTE_SEQ_ID BIGINT, @p_WHERE_FIELD_VALUE BIGINT', 
						@p_RETURN_VALUE OUTPUT, @SELECT_FIELD_SYSTEM_NAME, @CLIENT_ID, 
						@SRM_CLIENT_ENTITIES_SEQ_ID, @WHERE_FIELD_ATTRIBUTE_SEQ_ID, @p_WHERE_FIELD_VALUE
	
	PRINT @p_RETURN_VALUE

END;



-- *****************************************************************************************************************
-- Created By: Adeel Hassan
-- Date Created: 11/03/2025
-- Summary: A process to return concatenated values of a Group field
--******************************************************************************************************************

CREATE PROCEDURE [dbo].[GET_CONCATENATED_GROUP_FIELD_VALUES]
	@p_CONTACT_SEQ_ID NVARCHAR(200),
	@p_USER_EMAIL NVARCHAR(200),
	@p_GROUPS_NAME NVARCHAR(1000) OUTPUT,
	@p_GROUP_ROLES_NAME NVARCHAR(1000) OUTPUT
AS
BEGIN
	DECLARE @CLIENT_ID BIGINT
    DECLARE @strSQL NVARCHAR(1000)
	DECLARE @GROUP_MEMBER_ENTITY_SEQ_ID BIGINT = 113002
	DECLARE @CONTACT_ATTRIBUTE_SEQ_ID BIGINT = 3067813
	DECLARE @ACTIVE_ATTRIBUTE_SEQ_ID BIGINT = 3067820

		-- Get Client ID on the basis of User Email
	SELECT @CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USER_EMAIL

SET @strSQL = 'SELECT 
    @p_GROUPS_NAME = STRING_AGG(CAST(C.ATTRIBUTE_003 AS NVARCHAR(100)), '' | ''),
    @p_GROUP_ROLES_NAME = STRING_AGG(CAST(C.ATTRIBUTE_003 AS NVARCHAR(100)) + '', '' + CAST(C.ATTRIBUTE_007 AS NVARCHAR(100)),'' | '')
    FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10)) + '].dbo.CUS_ENTITY_DATA C
    INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10)) + '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I ON C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID
    INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10)) + '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I2 ON C.SEQ_ID = I2.CUS_ENTITY_DATA_SEQ_ID
    WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' 
    AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@GROUP_MEMBER_ENTITY_SEQ_ID AS NVARCHAR(100)) + '
    AND C.SRM_CLIENTS_SEQ_ID = ' + CAST(@CLIENT_ID AS NVARCHAR(100)) + '
    AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@CONTACT_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + '
    AND I.ATTRIBUTE_DECIMAL = ' + CAST(@p_CONTACT_SEQ_ID AS NVARCHAR(100)) + '
	AND I2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@ACTIVE_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + '
    AND I2.ATTRIBUTE_BOOLEAN = ''Y''';

	PRINT @strSQL
    EXEC sp_executesql @strSQL, 
						N'@p_GROUPS_NAME NVARCHAR(1000) OUTPUT, @p_GROUP_ROLES_NAME NVARCHAR(1000) OUTPUT, @CLIENT_ID BIGINT, @GROUP_MEMBER_ENTITY_SEQ_ID BIGINT, 
						@CONTACT_ATTRIBUTE_SEQ_ID BIGINT, @p_CONTACT_SEQ_ID BIGINT', 
						@p_GROUPS_NAME OUTPUT, @p_GROUP_ROLES_NAME OUTPUT, @CLIENT_ID, 
						@GROUP_MEMBER_ENTITY_SEQ_ID, @CONTACT_ATTRIBUTE_SEQ_ID, @p_CONTACT_SEQ_ID
	
	PRINT @p_GROUPS_NAME

END
;







