	declare @teaching_level_name nvarchar(200)
	DECLARE @LAST_PAYMENT_AMOUNT  nvarchar(200)
	DECLARE @LAST_PAYMENT_DATE nvarchar(200)
	DECLARE @LAST_SALE_AMOUNT nvarchar(200)
	DECLARE @LAST_SALE_DATE nvarchar(200)
	DECLARE @SALE_AMOUNT_LAST_YEARS nvarchar(200)
	DECLARE @SALE_AMOUNT_MONTH_TO_DATE nvarchar(200)
	DECLARE @SALE_AMOUNT_YEAR_TO_DATE nvarchar(200)
	DECLARE @Salutation nvarchar(200)
	DECLARE @DateCreated datetime
	DECLARE @CreatedBy nvarchar(200)

	DECLARE @USERNAME nvarchar(200)
	DECLARE @PASSWORD nvarchar(200)
	DECLARE @COUNTER BIGINT

	SET NOCOUNT ON;

	--BEGIN TRANSACTION 

	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'CONTACT'

		DECLARE Cur_records CURSOR  LOCAL STATIC FOR 
					
					SELECT PERS.SEQ_ID,  PERS.AGE, PART.BADGE_1,PART.BADGE_2,PART.BADGE_3,PART.BADGE_4,
					DESG_LETTS,PERS.UCN,PERS.LAST_NAME,PERS.FIRST_NAME,PERS.MIDDLE_NAME,PERS.INITIALS,PERS.LABEL_NAME,
					PERs.TAX_PAYER,PERS.IS_VIP,
					CONVERT(NVARCHAR, PERS.DATE_OF_BIRTH, 121) DATE_OF_BIRTH,PERS.GAD_GIVEN,PERS.GAD_REFUSED,
					case when PERS.sex = 'M' then 2545335  when PERS.sex='F' then 2545336 end as SEX,--for client 17
					case when sex = 'M' then 'Male'  when sex='F' then 'Female' end sex_desc,--for client 17
					SRM_TITLE.SEQ_ID TITLE,SRM_TITLE.ATTRIBUTE_001 TITLE_NAME,
					SRM_CONTACT_STATUS.SEQ_ID CONTACT_STATUS,SRM_CONTACT_STATUS.ATTRIBUTE_001 CONTACT_STATUS_NAME,
					SRM_BRANCH1.SEQ_ID AS BRANCH_1,SRM_BRANCH1.ATTRIBUTE_001 AS BRANCH_1_NAME,
					SRM_BRANCH2.SEQ_ID AS BRANCH_2,SRM_BRANCH2.ATTRIBUTE_001 AS BRANCH_2_NAME,
					SRM_BRANCH3.SEQ_ID AS BRANCH_3,SRM_BRANCH3.ATTRIBUTE_001 AS BRANCH_3_NAME,
					SRM_MARKETING_SOURCE.SEQ_ID AS FROM_WHERE_YOU_HEAR_ABOUT_US,SRM_MARKETING_SOURCE.ATTRIBUTE_001 AS FROM_WHERE_YOU_HEAR_ABOUT_US_NAME,
					SRM_TEACHING_LEVEL.SEQ_ID AS TEACHING_LEVEL,SRM_TEACHING_LEVEL.ATTRIBUTE_001 AS TEACHING_LEVEL_DESCRIPTION,
					  CUST.LAST_PAYMENT_AMOUNT, 
					  CONVERT(NVARCHAR, CUST.LAST_PAYMENT_DATE, 121) LAST_PAYMENT_DATE ,
					  CUST.LAST_SALE_AMOUNT ,
					  CONVERT(NVARCHAR, CUST.LAST_SALE_DATE, 121) LAST_SALE_DATE , 
					  CUST.SALE_AMOUNT_LAST_YEARS , 
					  CUST.SALE_AMOUNT_MONTH_TO_DATE,  
					  CUST.SALE_AMOUNT_YEAR_TO_DATE,
					  pers.SALUTATION,
					  WA.[USER_NAME],
					  WA.[PASSWORD],
					  CONVERT(NVARCHAR, pers.DATE_CREATED, 121) DATE_CREATED,
					  pers.created_by,
					  CONVERT(NVARCHAR, pers.date_modified, 121) date_modified,
					  pers.modified_by
				

					 FROM ETARGETDATA.DBO.CRM_PERSONS PERS
					LEFT OUTER JOIN ETARGETDATA.DBO.EV_PARTICIPANTS PART ON PERS.SEQ_ID=PART.CRM_PERSONS_SEQ_ID
					LEFT OUTER JOIN ETARGETDATA.DBO.ISC_CUSTOMERS CUST ON PERS.SEQ_ID=CUST.CRM_PERSONS_SEQ_ID
					LEFT OUTER JOIN ETARGETDATA.DBO.CRM_WEB_ACCESS wa ON PERS.SEQ_ID=wa.CRM_PERSONS_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_TITLE ON LOG_TITLE.ETARGET_SEQ_ID=PERS.CRM_TITLES_SEQ_ID AND LOG_TITLE.ETARGET_TABLE_NAME='CRM_TITLES' and LOG_TITLE.STARGET_CLIENT_ENTITIES_SEQ_ID= 2529
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_TITLE ON SRM_TITLE.SEQ_ID=LOG_TITLE.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT_STATUS ON LOG_CONTACT_STATUS.ETARGET_SEQ_ID=PERS.CRM_CONTACT_STATUS_SEQ_ID AND LOG_CONTACT_STATUS.ETARGET_TABLE_NAME='CRM_CONTACT_STATUS' and LOG_CONTACT_STATUS.STARGET_CLIENT_ENTITIES_SEQ_ID= 2538
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT_STATUS ON SRM_CONTACT_STATUS.SEQ_ID=LOG_CONTACT_STATUS.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BRANCH1 ON LOG_BRANCH1.ETARGET_SEQ_ID=PERS.CRM_AREAS_SEQ_ID AND LOG_BRANCH1.ETARGET_TABLE_NAME='CRM_AREAS' and LOG_BRANCH1.STARGET_CLIENT_ENTITIES_SEQ_ID= 2678
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BRANCH1 ON SRM_BRANCH1.SEQ_ID=LOG_BRANCH1.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BRANCH2 ON LOG_BRANCH2.ETARGET_SEQ_ID=PERS.CRM_AREAS_SEC_SEQ_ID AND LOG_BRANCH2.ETARGET_TABLE_NAME='CRM_AREAS'and LOG_BRANCH2.STARGET_CLIENT_ENTITIES_SEQ_ID= 2678
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BRANCH2 ON SRM_BRANCH2.SEQ_ID=LOG_BRANCH2.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BRANCH3 ON LOG_BRANCH3.ETARGET_SEQ_ID=PERS.CRM_AREAS_TRD_SEQ_ID AND LOG_BRANCH3.ETARGET_TABLE_NAME='CRM_AREAS'and LOG_BRANCH3.STARGET_CLIENT_ENTITIES_SEQ_ID= 2678
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BRANCH3 ON SRM_BRANCH3.SEQ_ID=LOG_BRANCH3.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_MARKETING_SOURCE ON LOG_MARKETING_SOURCE.ETARGET_SEQ_ID=PERS.CRM_MARKETING_SOURCES_SEQ_ID AND LOG_MARKETING_SOURCE.ETARGET_TABLE_NAME='CRM_MARKETING_SOURCES' and LOG_MARKETING_SOURCE.STARGET_CLIENT_ENTITIES_SEQ_ID= 2536
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_MARKETING_SOURCE ON SRM_MARKETING_SOURCE.SEQ_ID=LOG_MARKETING_SOURCE.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_TEACHING_LEVEL ON LOG_TEACHING_LEVEL.ETARGET_SEQ_ID=PERS.CRM_MARKETING_SOURCES_SEQ_ID AND LOG_TEACHING_LEVEL.ETARGET_TABLE_NAME='CRM_PERS_LOOKUP01'and LOG_TEACHING_LEVEL.STARGET_CLIENT_ENTITIES_SEQ_ID= 2690
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_TEACHING_LEVEL ON SRM_TEACHING_LEVEL.SEQ_ID=LOG_TEACHING_LEVEL.STARGET_CUS_ENTITY_DATA_SEQ_ID

			WHERE PERS.UCN=@Source_UCN
		
		OPEN Cur_records
	
	
		FETCH NEXT FROM Cur_records INTO @seq_id, @AGE, @bage1 , @bage2 , @bage3 , @bage4 , @Desg_letts , @ucn , @last_name , @first_name , @middle_name , @initials , @label_name , @tax_payer ,
										 @is_vip , @date_of_birth , @gad_given , @gad_refused , @sex , @sex_desc,
										 @title , @title_name , @contact_status , @contact_status_name , @branch1 , @branch1_name , @branch2 , @branch2_name , @branch3 , @branch3_name , @from_where_you_hear_about_us , @from_where_you_hear_about_us_name , @teaching_level , @teaching_level_name ,@LAST_PAYMENT_AMOUNT,  @LAST_PAYMENT_DATE , @LAST_SALE_AMOUNT , @LAST_SALE_DATE , @SALE_AMOUNT_LAST_YEARS , @SALE_AMOUNT_MONTH_TO_DATE,  @SALE_AMOUNT_YEAR_TO_DATE,@Salutation,@USERNAME,@PASSWORD,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy 
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
			SET @COUNTER = @COUNTER + 1
			
			---------------------------------------------AQ
			IF EXISTS (SELECT ATTRIBUTE_003 FROM [SRM-CUSTOMENTITIES].dbo.CUS_ENTITY_DATA  WHERE ATTRIBUTE_003 = @ucn AND CUS_ENTITY_DATA.SRM_CLIENT_ENTITIES_SEQ_ID = 2524)
			BEGIN
								
				EXEC [SRM-Framework_New].dbo.GET_PIVOT_NEXT_ID @UNIQUE_INDEX_ID = 1, @SRM_CLIENTS_SEQ_ID = 17, @PIVOT_NEXT_ID = @ucn OUTPUT  
			END
			---------------------------------------------AQ
			
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_012,ATTRIBUTE_098,ATTRIBUTE_099,ATTRIBUTE_100,ATTRIBUTE_101,ATTRIBUTE_009,ATTRIBUTE_003,ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_006,ATTRIBUTE_008,ATTRIBUTE_001,ATTRIBUTE_066,ATTRIBUTE_014,ATTRIBUTE_011,ATTRIBUTE_068,ATTRIBUTE_067,ATTRIBUTE_110,ATTRIBUTE_111,ATTRIBUTE_025,ATTRIBUTE_026,ATTRIBUTE_029,ATTRIBUTE_030,ATTRIBUTE_102,ATTRIBUTE_103,ATTRIBUTE_104,ATTRIBUTE_105,ATTRIBUTE_106,ATTRIBUTE_107,ATTRIBUTE_031,ATTRIBUTE_032,ATTRIBUTE_108,ATTRIBUTE_109,ATTRIBUTE_091,ATTRIBUTE_090,ATTRIBUTE_089,ATTRIBUTE_088,ATTRIBUTE_094,ATTRIBUTE_092,ATTRIBUTE_093,ATTRIBUTE_010,ATTRIBUTE_020,ATTRIBUTE_022,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY)	
			values(@srm_client_entities_seq_id, @AGE , @bage1,  @bage2 , @bage3 , @bage4 , @Desg_letts,  @ucn , @last_name,  @first_name,  @middle_name,  @initials , @label_name,  @tax_payer , @is_vip , @date_of_birth , @gad_given , @gad_refused , @sex ,@sex_desc, @title , @title_name , @contact_status , @contact_status_name,  @branch1 , @branch1_name,  @branch2 , @branch2_name , @branch3 , @branch3_name , @from_where_you_hear_about_us , @from_where_you_hear_about_us_name , @teaching_level , @teaching_level_name,@LAST_PAYMENT_AMOUNT,  @LAST_PAYMENT_DATE , @LAST_SALE_AMOUNT , @LAST_SALE_DATE , @SALE_AMOUNT_LAST_YEARS , @SALE_AMOUNT_MONTH_TO_DATE,  @SALE_AMOUNT_YEAR_TO_DATE,@Salutation,@USERNAME,@PASSWORD,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy )
		
			SELECT @SRM_CONTACT_SEQ_ID = SCOPE_IDENTITY()
			SET @new_seq_id=@SRM_CONTACT_SEQ_ID
			--IF @@ERROR <>0
			--		ROLLBACK TRANSACTION 
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--IF @@ERROR <>0
			--		ROLLBACK TRANSACTION 
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_PERSONS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

			-- PRINT 'before fetch next inner ' + cast(getdate() as nvarchar)
			FETCH NEXT FROM Cur_records INTO @seq_id, @AGE, @bage1 , @bage2 , @bage3 , @bage4 , @Desg_letts , @ucn , @last_name , @first_name , @middle_name , @initials , @label_name , @tax_payer ,
											 @is_vip , @date_of_birth , @gad_given , @gad_refused , @sex ,@sex_desc, 
											 @title , @title_name , @contact_status , @contact_status_name , @branch1 , @branch1_name , @branch2 , @branch2_name , @branch3 , @branch3_name , @from_where_you_hear_about_us , @from_where_you_hear_about_us_name , @teaching_level , @teaching_level_name ,@LAST_PAYMENT_AMOUNT,  @LAST_PAYMENT_DATE , @LAST_SALE_AMOUNT , @LAST_SALE_DATE , @SALE_AMOUNT_LAST_YEARS , @SALE_AMOUNT_MONTH_TO_DATE,  @SALE_AMOUNT_YEAR_TO_DATE,@Salutation,@USERNAME,@PASSWORD,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy 

		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
	
		---------------------------------------------------------------------------------------------------
		---------------------------------------------------------------------------------------------------
	print 'person inserted'
	---############################################ CONTACT_SPECIAL_REQUIREMENT ###########################################################





	declare @SPECIAL_REQUIREMENT nvarchar(200)
	declare @SPECIAL_REQUIREMENT_NAME nvarchar(200)
	declare @CONTACT nvarchar(200)
	declare @CONTACT_NAME nvarchar(200)



	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'CONTACT_SPECIAL_REQUIREMENT'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR 
		select SPEC_REQS.seq_id, remarks,
				SRM_spec_req_type.SEQ_ID SPECIAL_REQUIREMENT,SRM_spec_req_type.ATTRIBUTE_001 SPECIAL_REQUIREMENT_NAME,
				SRM_contact.SEQ_ID CONTACT,SRM_contact.ATTRIBUTE_001 AS CONTACT_NAME,
					 CONVERT(NVARCHAR, SPEC_REQS.DATE_CREATED, 121) DATE_CREATED,
					  SPEC_REQS.created_by,
					 CONVERT(NVARCHAR, SPEC_REQS.date_modified, 121) date_modified ,
					  SPEC_REQS.modified_by  

				from ETARGETDATA.DBO.CRM_PERS_SPECIAL_REQS SPEC_REQS
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_spec_req_type ON LOG_spec_req_type.ETARGET_SEQ_ID=SPEC_REQS.CRM_SPECIAL_REQS_TYPES_SEQ_ID AND LOG_spec_req_type.ETARGET_TABLE_NAME='CRM_SPECIAL_REQS_TYPES'and LOG_spec_req_type.STARGET_CLIENT_ENTITIES_SEQ_ID=2657
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_spec_req_type ON SRM_spec_req_type.SEQ_ID=LOG_spec_req_type.STARGET_CUS_ENTITY_DATA_SEQ_ID	
				inner JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_contact ON LOG_contact.ETARGET_SEQ_ID=SPEC_REQS.CRM_PERSONS_SEQ_ID AND LOG_contact.ETARGET_TABLE_NAME='CRM_PERSONS'and LOG_contact.STARGET_CLIENT_ENTITIES_SEQ_ID=2524
				inner JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_contact ON SRM_contact.SEQ_ID=LOG_contact.STARGET_CUS_ENTITY_DATA_SEQ_ID
				WHERE SPEC_REQS.CRM_PERSONS_SEQ_ID= @Source_PERSON_SEQ_ID
			
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id, @REMARKS ,@SPECIAL_REQUIREMENT , @SPECIAL_REQUIREMENT_NAME , @CONTACT , @CONTACT_NAME ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_001,ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_002,ATTRIBUTE_003,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id, @REMARKS ,@SPECIAL_REQUIREMENT , @SPECIAL_REQUIREMENT_NAME , @CONTACT , @CONTACT_NAME ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  )
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--IF @@ERROR <>0
			--		ROLLBACK TRANSACTION 
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--IF @@ERROR <>0
			--		ROLLBACK TRANSACTION 
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_PERS_SPECIAL_REQS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)
			--IF @@ERROR <>0
			--		ROLLBACK TRANSACTION 
		FETCH NEXT FROM Cur_records INTO @seq_id, @REMARKS ,@SPECIAL_REQUIREMENT , @SPECIAL_REQUIREMENT_NAME , @CONTACT , @CONTACT_NAME ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
	--###########################################################################################################################################

	--############################################ persons CRM_NOTES ###########################################################



	DECLARE @NOTE_DATE NVARCHAR(200)
	DECLARE @PARENT_SEQ_ID BIGINT


	DECLARE @NOTE_TYPE NVARCHAR(200)
	DECLARE @NOTE_TYPE_NAME NVARCHAR(200)



	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'NOTE'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR 
			SELECT PERS_REM.SEQ_ID,PERS_REM.REMARKS,
			 CONVERT(NVARCHAR, PERS_REM.DATE_CREATED, 121) aS NOTE_DATE,
			SRM_contact.SEQ_ID AS PARENT_SEQ_ID,
			SRM_NoteType.SEQ_ID note_type,
			SRM_NoteType.ATTRIBUTE_001 note_type_name,
					 CONVERT(NVARCHAR, PERS_REM.DATE_CREATED, 121) DATE_CREATED,
					  PERS_REM.created_by,
					 CONVERT(NVARCHAR, PERS_REM.date_modified, 121) date_modified ,
					  PERS_REM.modified_by 

			FROM ETARGETDATA.DBO.CRM_PERS_REMARKS PERS_REM
 				INNER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_contact ON LOG_contact.ETARGET_SEQ_ID=PERS_REM.CRM_PERSONS_SEQ_ID AND LOG_contact.ETARGET_TABLE_NAME='CRM_PERSONS' and LOG_contact.STARGET_CLIENT_ENTITIES_SEQ_ID=2524
				INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_contact ON SRM_contact.SEQ_ID=LOG_contact.STARGET_CUS_ENTITY_DATA_SEQ_ID 
	
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_NoteType ON LOG_NoteType.ETARGET_SEQ_ID=PERS_REM.CRM_REMARK_TYPES_SEQ_ID AND LOG_NoteType.ETARGET_TABLE_NAME='CRM_REMARK_TYPES' and LOG_NoteType.STARGET_CLIENT_ENTITIES_SEQ_ID=2684
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_NoteType ON SRM_NoteType.SEQ_ID=LOG_NoteType.STARGET_CUS_ENTITY_DATA_SEQ_ID 
			WHERE PERS_REM.CRM_PERSONS_SEQ_ID= @Source_PERSON_SEQ_ID
	
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@REMARKS ,@NOTE_DATE,@PARENT_SEQ_ID,@NOTE_TYPE,@NOTE_TYPE_NAME,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		WHILE @@FETCH_STATUS = 0
		BEGIN
		
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_499,ATTRIBUTE_003,ATTRIBUTE_004,ATTRIBUTE_002,ATTRIBUTE_001,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY)	
			values(@srm_client_entities_seq_id,@PARENT_SEQ_ID,@NOTE_TYPE,@NOTE_TYPE_NAME,@NOTE_DATE,@REMARKS,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  )
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--IF @@ERROR <>0
			--		ROLLBACK TRANSACTION 
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_PERS_REMARKS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,@REMARKS ,@NOTE_DATE,@PARENT_SEQ_ID,@NOTE_TYPE,@NOTE_TYPE_NAME,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
	--###########################################################################################################################################

	--############################################ Person Attributes ###########################################################



 
	set @client_seq_id=17


	DECLARE @PROFILE_DESCRIPTION NVARCHAR(200)
	DECLARE @PROFILE_Date NVARCHAR(200)
	declare @PROFILE_PICKLIST_SEQ_ID bigint


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'PROFILE'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR 
			
				SELECT  PERS_ATTR.SEQ_ID,
				SRM_SUB_ATTR.SEQ_ID AS CRM_PROFILE_PICKLIST_SEQ_ID,
				SRM_SUB_ATTR.ATTRIBUTE_001 AS PROFILE_DESCRIPTION
				,SRM_CONTACT.SEQ_ID AS PARENT_SEQ_ID,
				CONVERT(NVARCHAR, PERS_ATTR.EFFECTIVE_DATE, 121) AS PRFILE_DATE,
				PERS_ATTR.REMARKS,
				CONVERT(NVARCHAR, PERS_ATTR.DATE_CREATED, 121) DATE_CREATED ,
				PERS_ATTR.CREATED_BY,
				CONVERT(NVARCHAR, PERS_ATTR.DATE_MODIFIED, 121)PDATE_MODIFIED,
				PERS_ATTR.MODIFIED_BY 
				FROM ETARGETDATA.DBO.CRM_PERS_ATTRIBUTES PERS_ATTR
				INNER JOIN ETARGETDATA.DBO.CRM_PERS_SUB_ATTRIBS SUB_ATTR ON SUB_ATTR.SEQ_ID =PERS_ATTR.CRM_PERS_SUB_ATTRIBS_SEQ_ID 
				INNER JOIN ETARGETDATA.DBO.CRM_PERSONS PERS ON PERS.SEQ_ID=PERS_ATTR.CRM_PERSONS_SEQ_ID

				INNER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_SUB_ATTR ON LOG_SUB_ATTR.ETARGET_SEQ_ID=SUB_ATTR.SEQ_ID AND LOG_SUB_ATTR.ETARGET_TABLE_NAME='CRM_PERS_SUB_ATTRIBS'and LOG_SUB_ATTR.STARGET_CLIENT_ENTITIES_SEQ_ID=2554
				INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_SUB_ATTR ON SRM_SUB_ATTR.SEQ_ID=LOG_SUB_ATTR.STARGET_CUS_ENTITY_DATA_SEQ_ID 
				--INNER JOIN [SRM-SUNDRYDETAIL].DBO.CRM_PROFILE_PICKLIST SRM_SUB_ATTR ON SRM_SUB_ATTR.SEQ_ID=LOG_SUB_ATTR.STARGET_CUS_ENTITY_DATA_SEQ_ID 

				INNER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=PERS_ATTR.CRM_PERSONS_SEQ_ID AND LOG_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS' and LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID=2524
				INNER  JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID 
			
				WHERE PERS_ATTR.CRM_PERSONS_SEQ_ID= @Source_PERSON_SEQ_ID

	
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@PROFILE_PICKLIST_SEQ_ID,@PROFILE_DESCRIPTION,@PARENT_SEQ_ID,@PROFILE_Date,@REMARKS ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		WHILE @@FETCH_STATUS = 0
		BEGIN
		
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_499,ATTRIBUTE_002,ATTRIBUTE_001,ATTRIBUTE_003,ATTRIBUTE_004,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,@PARENT_SEQ_ID,@PROFILE_PICKLIST_SEQ_ID,@PROFILE_DESCRIPTION,@PROFILE_Date,@REMARKS,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  )
		
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_PERS_ATTRIBUTES',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,@PROFILE_PICKLIST_SEQ_ID,@PROFILE_DESCRIPTION,@PARENT_SEQ_ID,@PROFILE_Date,@REMARKS ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy    
	
			END

		CLOSE Cur_records
		DEALLOCATE Cur_records
	--###########################################################################################################################################


	alter table ETARGETDATA.DBO.CRM_PERS_ADDRESSES disable trigger all
	alter table ETARGETDATA.DBO.CRM_PERS_COMMS_ADDRESS disable trigger all

	update ETARGETDATA.DBO.CRM_PERS_ADDRESSES set SHOW_ON_CONTACT='N' WHERE CRM_PERSONS_SEQ_ID= @Source_PERSON_SEQ_ID

	update  PCA  set PCA.SHOW_ON_CONTACT='N' FROM  ETARGETDATA.DBO.CRM_PERS_COMMS_ADDRESS PCA
	INNER JOIN ETARGETDATA.DBO.CRM_PERS_ADDRESSES PA ON PA.SEQ_ID=PCA.CRM_PERS_ADDRESSES_SEQ_ID
	WHERE PA.CRM_PERSONS_SEQ_ID=@Source_PERSON_SEQ_ID


