		INNER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=PERS.SEQ_ID AND LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID= 2524
		INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_COUNTRY ON LOG_COUNTRY.ETARGET_SEQ_ID=PA.CRM_COUNTRIES_SEQ_ID and LOG_COUNTRY.STARGET_CLIENT_ENTITIES_SEQ_ID= 2549
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_COUNTRIES ON SRM_COUNTRIES.SEQ_ID=LOG_COUNTRY.STARGET_CUS_ENTITY_DATA_SEQ_ID
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_COUNTY ON LOG_COUNTY.ETARGET_SEQ_ID=PA.CRM_COUNTIES_SEQ_ID and LOG_COUNTY.STARGET_CLIENT_ENTITIES_SEQ_ID= 2550
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_COUNTIES ON SRM_COUNTIES.SEQ_ID=LOG_COUNTY.STARGET_CUS_ENTITY_DATA_SEQ_ID
	
		WHERE PERS.SEQ_ID=@Source_PERSON_SEQ_ID AND  PA.SEQ_ID IN (SELECT top 1 SEQ_ID FROM ETARGETDATA.dbo.CRM_PERS_ADDRESSES INNER_PA WHERE INNER_PA.CRM_PERSONS_SEQ_ID=PERS.SEQ_ID AND INNER_PA.CRM_ADDRESS_TYPES_SEQ_ID in (1) order by INNER_PA.main_address desc ) 
	
		OPEN Cur_records -------------AQ
		FETCH NEXT FROM Cur_records INTO @seq_id,@address_line1 , @address_line2 , @address_line3 , @postcode , @town , @org_name , @job_title, @Main_address, @country , @country_name , @county , @county_name , @contact , @contact_name
		WHILE @@FETCH_STATUS = 0
		BEGIN
			IF (@Main_address = 'Y')
			    BEGIN	
					UPDATE [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SET 
					ATTRIBUTE_035 = @address_line1 ,
					ATTRIBUTE_036 = @address_line2,
					ATTRIBUTE_037 = @address_line3,
					ATTRIBUTE_038 = @town,
					ATTRIBUTE_039 = @postcode,
					ATTRIBUTE_040 = @county,
					ATTRIBUTE_041 = @county_name,
					ATTRIBUTE_042 = @country,
					ATTRIBUTE_043 = @country_name,
					ATTRIBUTE_142 = @org_name,   -------------AQ
					ATTRIBUTE_143 = @job_title,   -------------AQ
					ATTRIBUTE_140 = 'Home',
					ATTRIBUTE_138 = 3076864,
					ATTRIBUTE_141 = 'Home',
					ATTRIBUTE_139 = 3076864
					WHERE SEQ_ID=@contact AND SRM_CLIENT_ENTITIES_SEQ_ID=2524
					set @rec_count=@rec_count+1
					ALTER TABLE ETARGETDATA.dbo.CRM_PERS_ADDRESSES DISABLE TRIGGER ALL
					UPDATE ETARGETDATA.dbo.CRM_PERS_ADDRESSES SET SHOW_ON_CONTACT='Y' WHERE SEQ_ID=@seq_id
					ALTER TABLE ETARGETDATA.dbo.CRM_PERS_ADDRESSES ENABLE TRIGGER ALL
				END
			ELSE
			BEGIN
				UPDATE [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SET 
				ATTRIBUTE_035 = @address_line1 ,
				ATTRIBUTE_036 = @address_line2,
				ATTRIBUTE_037 = @address_line3,
				ATTRIBUTE_038 = @town,
				ATTRIBUTE_039 = @postcode,
				ATTRIBUTE_040 = @county,
				ATTRIBUTE_041 = @county_name,
				ATTRIBUTE_042 = @country,
				ATTRIBUTE_043 = @country_name,
				ATTRIBUTE_142 = @org_name,   -------------AQ
				ATTRIBUTE_143 = @job_title   -------------AQ
				WHERE SEQ_ID=@contact AND SRM_CLIENT_ENTITIES_SEQ_ID=2524
				set @rec_count=@rec_count+1
				ALTER TABLE ETARGETDATA.dbo.CRM_PERS_ADDRESSES DISABLE TRIGGER ALL
				UPDATE ETARGETDATA.dbo.CRM_PERS_ADDRESSES SET SHOW_ON_CONTACT='Y' WHERE SEQ_ID=@seq_id
				ALTER TABLE ETARGETDATA.dbo.CRM_PERS_ADDRESSES ENABLE TRIGGER ALL
			END
			--IF @@ERROR <>0
			--		ROLLBACK TRANSACTION 
			print 'Record Processes : ' + cast(@rec_count as varchar)
		
		FETCH NEXT FROM Cur_records INTO @seq_id,@address_line1 , @address_line2 , @address_line3 , @postcode , @town , @org_name , @job_title, @Main_address , @country , @country_name , @county , @county_name, @contact , @contact_name
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
