					set @rec_count=@rec_count+1
					ALTER TABLE ETARGETDATA.dbo.CRM_PERS_ADDRESSES DISABLE TRIGGER ALL
					UPDATE ETARGETDATA.dbo.CRM_PERS_ADDRESSES SET SHOW_ON_CONTACT='Y' WHERE SEQ_ID=@seq_id
