	declare @description nvarchar(500)
	declare @active  char
	declare @ARCHIVE_STATUS nvarchar(20)
	declare @bank_name nvarchar(100)
	declare @bank_code nvarchar(100)
	declare @bank_address nvarchar(1000)
	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'MORE_ADDRESS'

	--declare @address_line1 nvarchar(200)
	--declare @address_line2 nvarchar(200)
	--declare @address_line3 nvarchar(200)
	--declare @job_title nvarchar(200)
	--declare @Main_address nvarchar(200)
	--declare @org_name nvarchar(200)
	--declare @postcode nvarchar(200)
	--declare @town nvarchar(200)
	--declare @department nvarchar(200)
	--declare @contact nvarchar(200)
	--declare @contact_name nvarchar(200)
	--declare @country nvarchar(200)
	--declare @country_name nvarchar(200)
	--declare @county nvarchar(200)
	--declare @county_name nvarchar(200)
	--declare @address_type nvarchar(200)
	--declare @address_type_name nvarchar(200)
	--DECLARE @DateModified datetime
	--DECLARE @ModifiedBy nvarchar(200)

		DECLARE Cur_records CURSOR  LOCAL STATIC  FOR
	 
		SELECT pa.SEQ_ID,pa.ADDR_LINE_1,pa.ADDR_LINE_2,pa.ADDR_LINE_3,pa.JOB_TITLE,pa.MAIN_ADDRESS,pa.ORG_NAME,pa.POSTCODE,pa.TOWN,pa.DEPARTMENT,
		SRM_CONTACT.SEQ_ID AS CONTACT,
		SRM_contact.ATTRIBUTE_001 AS CONTACT_NAME,
		SRM_COUNTRIES.SEQ_ID COUNTRY,
		SRM_COUNTRIES.ATTRIBUTE_001 COUNTRY_NAME,
		SRM_COUNTIES.SEQ_ID COUNTY,
		SRM_COUNTIES.ATTRIBUTE_001 COUNTY_NAME,
		SRM_ADDRESS_TYPE.SEQ_ID ADDRESS_TYPE,
		SRM_ADDRESS_TYPE.ATTRIBUTE_001 ADDRESS_TYPE_NAME,
		 CONVERT(NVARCHAR, PA.DATE_CREATED, 121) DATE_CREATED,
					  PA.created_by,
					 CONVERT(NVARCHAR, PA.date_modified, 121) date_modified ,
					  PA.modified_by 
		FROM ETARGETDATA.dbo.CRM_PERS_ADDRESSES PA
		 INNER JOIN  ETARGETDATA.dbo.CRM_PERSONS PERS ON PERS.SEQ_ID=PA.CRM_PERSONS_SEQ_ID
		INNER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=PERS.SEQ_ID AND  LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID= 2524
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_COUNTRY ON LOG_COUNTRY.ETARGET_SEQ_ID=PA.CRM_COUNTRIES_SEQ_ID  and LOG_COUNTRY.STARGET_CLIENT_ENTITIES_SEQ_ID= 2549
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_COUNTRIES ON SRM_COUNTRIES.SEQ_ID=LOG_COUNTRY.STARGET_CUS_ENTITY_DATA_SEQ_ID
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_COUNTY ON LOG_COUNTY.ETARGET_SEQ_ID=PA.CRM_COUNTIES_SEQ_ID and LOG_COUNTY.STARGET_CLIENT_ENTITIES_SEQ_ID= 2550
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_COUNTIES ON SRM_COUNTIES.SEQ_ID=LOG_COUNTY.STARGET_CUS_ENTITY_DATA_SEQ_ID
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_ADDRESS_TYPE ON LOG_ADDRESS_TYPE.ETARGET_SEQ_ID=PA.CRM_ADDRESS_TYPES_SEQ_ID and LOG_ADDRESS_TYPE.STARGET_CLIENT_ENTITIES_SEQ_ID= 2548
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_ADDRESS_TYPE ON SRM_ADDRESS_TYPE.SEQ_ID=LOG_ADDRESS_TYPE.STARGET_CUS_ENTITY_DATA_SEQ_ID
		WHERE PERS.SEQ_ID=@Source_PERSON_SEQ_ID AND ISNULL(SHOW_ON_CONTACT,'N') ='N'
	
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@address_line1 , @address_line2 , @address_line3 , @job_title , @Main_address , @org_name , @postcode , @town , @department , @contact , @contact_name , @country , @country_name , @county , @county_name , @address_type , @address_type_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy 
		WHILE @@FETCH_STATUS = 0
		BEGIN
