			values(@srm_client_entities_seq_id,@address_line1 , @address_line2 , @address_line3 , @job_title , @Main_address , @org_name , @postcode , @town , @department , @contact , @contact_name , @country , @country_name , @county , @county_name , @address_type , @address_type_name,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy )
		
