		--############################################ PERSONS ADDITIONAL COMMUNICATION addresses ###########################################################
	
	
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @ARCHIVE_STATUS nvarchar(20)
	--declare @bank_name nvarchar(100)
	--declare @bank_code nvarchar(100)
	--declare @bank_address nvarchar(1000)
	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'COMMUNICATION_DETAIL'

	declare @COMMS_DETAILS nvarchar(200)
	declare @EXTENSION nvarchar(200)
	declare @PREFERRED_METHOD nvarchar(200)
	declare @COMMUNICATION_MODE nvarchar(200)
	declare @COMMUNICATION_MODE_NAME nvarchar(200)
	--declare @contact nvarchar(200)
	--declare @contact_name nvarchar(200)
	--DECLARE @DateModified datetime
	--DECLARE @ModifiedBy nvarchar(200)


		DECLARE Cur_records CURSOR LOCAL STATIC FOR
	 
			select PCA.SEQ_ID,PCA.COMMS_ADDRESS COMMUNICATION_DETAIL,EXTENSION,PREFERRED_METHOD,
			SRM_COMMS_MODE.SEQ_ID COMMUNICATION_MODE,
			SRM_COMMS_MODE.ATTRIBUTE_001 COMMUNICATION_MODE_NAME,
			SRM_CONTACT.SEQ_ID AS CONTACT,
			SRM_contact.ATTRIBUTE_001 AS CONTACT_NAME,
		
				 CONVERT(NVARCHAR, PCA.DATE_CREATED, 121) DATE_CREATED,
					  PCA.created_by,
					 CONVERT(NVARCHAR, PCA.date_modified, 121) date_modified ,
					  PCA.modified_by


			FROM ETARGETDATA.dbo.CRM_PERS_COMMS_ADDRESS PCA
			INNER JOIN ETARGETDATA.dbo.CRM_PERS_ADDRESSES PA ON PA.SEQ_ID=PCA.CRM_PERS_ADDRESSES_SEQ_ID
			INNER JOIN ETARGETDATA.dbo.CRM_PERSONS PERS ON PERS.SEQ_ID= PA.CRM_PERSONS_SEQ_ID
			INNER JOIN ETARGETDATA.dbo.CRM_COMMS_MODES CM ON CM.SEQ_ID= PCA.CRM_COMMS_MODES_SEQ_ID
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=PERS.SEQ_ID AND LOG_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS' and LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID= 2524
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_COMMS_MODE ON LOG_COMMS_MODE.ETARGET_SEQ_ID=CM.SEQ_ID AND LOG_COMMS_MODE.ETARGET_TABLE_NAME='CRM_COMMS_MODES'and LOG_COMMS_MODE.STARGET_CLIENT_ENTITIES_SEQ_ID= 2551
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_COMMS_MODE ON SRM_COMMS_MODE.SEQ_ID=LOG_COMMS_MODE.STARGET_CUS_ENTITY_DATA_SEQ_ID
			WHERE  PERS.SEQ_ID=@Source_PERSON_SEQ_ID AND ISNULL(PCA.SHOW_ON_CONTACT,'N')<>'Y'
		
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@COMMS_DETAILS , @EXTENSION , @PREFERRED_METHOD , @COMMUNICATION_MODE , @COMMUNICATION_MODE_NAME , @contact , @contact_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy 
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_001, ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_007,ATTRIBUTE_008,ATTRIBUTE_011,ATTRIBUTE_012,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY)	
			values(@srm_client_entities_seq_id,@COMMS_DETAILS , @EXTENSION , @PREFERRED_METHOD , @COMMUNICATION_MODE , @COMMUNICATION_MODE_NAME , @contact , @contact_name,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy )
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_PERS_COMMS_ADDRESS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,@COMMS_DETAILS , @EXTENSION , @PREFERRED_METHOD , @COMMUNICATION_MODE , @COMMUNICATION_MODE_NAME , @contact , @contact_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy 
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
	--###########################################################################################################################################
	
	--############################################ PERSONS BANK ACCOUNTS ###########################################################

	
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @ARCHIVE_STATUS nvarchar(20)
	--declare @bank_name nvarchar(100)
	--declare @bank_code nvarchar(100)
	--declare @bank_address nvarchar(1000)
	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'ACCOUNT_CONTACT_BANK'

	declare @BANK_ACCOUNT_ID nvarchar(200)
	declare @BANK_ACCOUNT_NAME nvarchar(200)
	declare @SORT_CODE nvarchar(200)
	declare @BANK nvarchar(200)
	--declare @BANK_NAME nvarchar(200)
	--declare @CONTACT nvarchar(200)
	--declare @CONTACT_name nvarchar(200)

	--DECLARE @DateModified datetime
	--DECLARE @ModifiedBy nvarchar(200)



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR
	 
				select PBA.SEQ_ID,PBA.BANK_ACCOUNT_ID,PBA.BANK_ACCOUNT_NAME,PBA.BANK_CODE,
				SRM_BANK.SEQ_ID BANK,SRM_BANK.ATTRIBUTE_001 BANK_NAME,
				SRM_CONTACT.SEQ_ID AS CONTACT,	SRM_contact.ATTRIBUTE_001 AS CONTACT_NAME,
					 CONVERT(NVARCHAR, PBA.DATE_CREATED, 121) DATE_CREATED,
					  PBA.created_by,
					 CONVERT(NVARCHAR, PBA.date_modified, 121) date_modified ,
					  PBA.modified_by 


			FROM ETARGETDATA.dbo.CRM_PERS_BANK_ACCOUNTS PBA
			INNER JOIN ETARGETDATA.dbo.CRM_PERSONS PERS ON PERS.SEQ_ID= PBA.CRM_PERSONS_SEQ_ID
			INNER JOIN ETARGETDATA.dbo.CRM_BANKS BANK ON BANK.SEQ_ID= PBA.CRM_BANKS_SEQ_ID
		
			inner JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=PERS.SEQ_ID AND LOG_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS' and LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID=2524
		inner JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID
		
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BANK ON LOG_BANK.ETARGET_SEQ_ID=BANK.SEQ_ID AND LOG_BANK.ETARGET_TABLE_NAME='CRM_BANKS'and LOG_BANK.STARGET_CLIENT_ENTITIES_SEQ_ID=2575
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BANK ON SRM_BANK.SEQ_ID=LOG_BANK.STARGET_CUS_ENTITY_DATA_SEQ_ID
			WHERE  PERS.SEQ_ID=@Source_PERSON_SEQ_ID
		
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@BANK_ACCOUNT_ID , @BANK_ACCOUNT_NAME , @SORT_CODE , @BANK , @BANK_NAME , @CONTACT , @CONTACT_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  

		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_002,ATTRIBUTE_009,ATTRIBUTE_001,ATTRIBUTE_003,ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_006,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,@BANK_ACCOUNT_ID , @BANK_ACCOUNT_NAME , @SORT_CODE , @BANK , @BANK_NAME , @CONTACT , @CONTACT_name,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  )
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_PERS_BANK_ACCOUNTS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,@BANK_ACCOUNT_ID , @BANK_ACCOUNT_NAME , @SORT_CODE , @BANK , @BANK_NAME , @CONTACT , @CONTACT_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
