	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @ARCHIVE_STATUS nvarchar(20)
	--declare @bank_name nvarchar(100)
	--declare @bank_code nvarchar(100)
	--declare @bank_address nvarchar(1000)
	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'ACCOUNT_CONTACT_RELATIONSHIP'

	declare @EFFECTIVE_DATE nvarchar(200)
	declare @CEASED_DATE nvarchar(200)
	declare @MAIN_CONTACT nvarchar(200)
	declare @MAIN_ACCOUNT nvarchar(200)
	--declare @JOB_TITLE nvarchar(200)
	declare @ACCOUNT nvarchar(200)
	declare @ACCOUNT_name nvarchar(200)
	--declare @CONTACT nvarchar(200)
	--declare @CONTACT_name nvarchar(200)
	declare @JOB_FUNCTION nvarchar(200)
	declare @JOB_FUNCTION_name nvarchar(200)
	--DECLARE @DateModified datetime
	--DECLARE @ModifiedBy nvarchar(200)

		DECLARE Cur_records CURSOR LOCAL STATIC FOR
	 			
			SELECT OP.SEQ_ID,
			CONVERT(NVARCHAR, OP.EFFECTIVE_DATE, 121) EFFECTIVE_DATE,
			CONVERT(NVARCHAR, OP.CEASED_DATE, 121) CEASED_DATE,
			OP.MAIN_CONTACT MAIN_CONTACT,
			OP.MAIN_ORG MAIN_ACCOUNT,OP.JOB_TITLE,
			SRM_ACCOUNT.SEQ_ID AS ACCOUNT,
			SRM_ACCOUNT.ATTRIBUTE_001 AS ACCOUNT_NAME,
			SRM_CONTACT.SEQ_ID AS CONTACT,
			SRM_contact.ATTRIBUTE_001 AS CONTACT_NAME,
			SRM_FUNC.SEQ_ID AS JOB_FUNCTION,
			SRM_FUNC.ATTRIBUTE_001 JOB_FUNCTION_DESCRIPTION,
			CONVERT(NVARCHAR, OP.DATE_CREATED, 121) DATE_CREATED, 
			OP.CREATED_BY,
			CONVERT(NVARCHAR, OP.DATE_MODIFIED, 121) DATE_MODIFIED,OP.MODIFIED_BY


			FROM ETARGETDATA.dbo.CRM_ORG_PERSONS OP
			INNER JOIN ETARGETDATA.dbo.CRM_PERSONS PERS ON PERS.SEQ_ID =OP.CRM_PERSONS_SEQ_ID
			INNER JOIN ETARGETDATA.dbo.CRM_ORG_ADDRESSES OA ON OA.SEQ_ID=OP.CRM_ORG_ADDRESSES_SEQ_ID
			INNER JOIN ETARGETDATA.dbo.CRM_ORGANISATIONS ORG ON ORG.SEQ_ID=OA.CRM_ORGANISATIONS_SEQ_ID
			--LEFT OUTER JOIN ETARGETDATA.dbo.CRM_FUNCTIONS FUNC ON FUNC.SEQ_ID=OP.CRM_FUNCTIONS_SEQ_ID

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_ACCOUNT ON LOG_ACCOUNT.ETARGET_SEQ_ID=ORG.SEQ_ID AND LOG_ACCOUNT.ETARGET_TABLE_NAME='CRM_ORGANISATIONS' and LOG_ACCOUNT.STARGET_CLIENT_ENTITIES_SEQ_ID=2525
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_ACCOUNT ON SRM_ACCOUNT.SEQ_ID=LOG_ACCOUNT.STARGET_CUS_ENTITY_DATA_SEQ_ID

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=PERS.SEQ_ID AND LOG_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS'and LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID=2524
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_FUNC ON LOG_FUNC.ETARGET_SEQ_ID=OP.CRM_FUNCTIONS_SEQ_ID AND LOG_FUNC.ETARGET_TABLE_NAME='CRM_FUNCTIONS'and LOG_FUNC.STARGET_CLIENT_ENTITIES_SEQ_ID=2608
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_FUNC ON SRM_FUNC.SEQ_ID=LOG_FUNC.STARGET_CUS_ENTITY_DATA_SEQ_ID
			WHERE  PERS.SEQ_ID=@Source_PERSON_SEQ_ID


		
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id, @EFFECTIVE_DATE , @CEASED_DATE , @MAIN_CONTACT , @MAIN_ACCOUNT , @JOB_TITLE , @ACCOUNT , @ACCOUNT_name , @CONTACT , @CONTACT_name , @JOB_FUNCTION , @JOB_FUNCTION_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy 
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_008,ATTRIBUTE_009,ATTRIBUTE_011,ATTRIBUTE_012,ATTRIBUTE_010,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_006,ATTRIBUTE_007,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY)	
			values(@srm_client_entities_seq_id, @EFFECTIVE_DATE , @CEASED_DATE , @MAIN_CONTACT , @MAIN_ACCOUNT , @JOB_TITLE , @ACCOUNT , @ACCOUNT_name , @CONTACT , @CONTACT_name , @JOB_FUNCTION , @JOB_FUNCTION_name,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy )
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_ORG_PERSONS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id, @EFFECTIVE_DATE , @CEASED_DATE , @MAIN_CONTACT , @MAIN_ACCOUNT , @JOB_TITLE , @ACCOUNT , @ACCOUNT_name , @CONTACT , @CONTACT_name , @JOB_FUNCTION , @JOB_FUNCTION_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy 
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
