	--############################################## CRM_COMMUNICATION_LOGS ###################################################################

	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	----declare @description nvarchar(500)
	--declare @active  char
	--declare @ARCHIVE_STATUS nvarchar(20)
	--declare @bank_name nvarchar(100)
	--declare @bank_code nvarchar(100)
	--declare @bank_address nvarchar(1000)
	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	DECLARE @MODULE NVARCHAR(100)
	DECLARE @MODULE_NAME NVARCHAR(100)
	dECLARE @USER NVARCHAR(100)
	dECLARE @USER_NAME NVARCHAR(100)
	DECLARE @DATE_OF_COMMS  NVARCHAR(100)
	--DECLARE @DESCRIPTION NVARCHAR(MAX)
	--DECLARE @REMARKS NVARCHAR(MAX)
	DECLARE @TIME_TAKEN NVARCHAR(100)
	--DECLARE @CONTACT_SEQ_ID NVARCHAR(100)
	DECLARE @COMM_TYPE NVARCHAR(100)
	DECLARE @COMM_TYPE_NAME NVARCHAR(100)

	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)



	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'COMMUNICATION_LOG'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR 
				SELECT 
			
					PCL.SEQ_ID,
					SRM_MODULE.SEQ_ID MODULE,
					SRM_MODULE.ATTRIBUTE_001 MODUL_NAME,
					USERS.SEQ_ID AS USER_SEQ_ID,
					USERS.USER_NAME,
					DATE_OF_COMMS,
					DESCRIPTION,
					REMARKS,
					TIME_TAKEN,
					SRM_CONTACT.SEQ_ID,
					SRM_COMM_TYPE.SEQ_ID AS COMM_TYPE,
					SRM_COMM_TYPE.ATTRIBUTE_001 AS COMM_TYPE_NAME,
					 CONVERT(NVARCHAR, CL.DATE_CREATED, 121) DATE_CREATED,
					  CL.created_by,
					 CONVERT(NVARCHAR, CL.date_modified, 121) date_modified ,
					  CL.modified_by  				

			FROM ETARGETDATA.dbo.CRM_COMMS_LOGS CL
			INNER JOIN ETARGETDATA.dbo.CRM_PERS_COMMS_LOGS PCL ON CL.SEQ_ID=PCL.CRM_COMMS_LOGS_SEQ_ID
			LEFT OUTER JOIN ETARGETDATA.dbo.CRM_USERS USERS ON USERS.SEQ_ID=CL.CRM_USERS_SEQ_ID
		
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=PCL.CRM_PERSONS_SEQ_ID AND LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID=2524
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_MODULE ON LOG_MODULE.ETARGET_SEQ_ID=CL.CRM_MODULES_SEQ_ID AND LOG_MODULE.ETARGET_TABLE_NAME='CRM_MODULES'
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_MODULE ON SRM_MODULE.SEQ_ID=LOG_MODULE.STARGET_CUS_ENTITY_DATA_SEQ_ID

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_COMM_TYPE ON LOG_COMM_TYPE.ETARGET_SEQ_ID=CL.CRM_COMMS_MODES_SEQ_ID AND LOG_COMM_TYPE.STARGET_CLIENT_ENTITIES_SEQ_ID=2539
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_COMM_TYPE  ON SRM_COMM_TYPE.SEQ_ID=LOG_COMM_TYPE.STARGET_CUS_ENTITY_DATA_SEQ_ID
			WHERE  PCL.CRM_PERSONS_SEQ_ID=@Source_PERSON_SEQ_ID

			OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id, @MODULE , @MODULE_NAME ,@USER, @USER_NAME , @DATE_OF_COMMS  , @DESCRIPTION , @REMARKS , @TIME_TAKEN ,@CONTACT_SEQ_ID, @COMM_TYPE, @COMM_TYPE_NAME,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_498,ATTRIBUTE_002,ATTRIBUTE_005,ATTRIBUTE_007,ATTRIBUTE_001,ATTRIBUTE_008,ATTRIBUTE_006,ATTRIBUTE_499,ATTRIBUTE_010,ATTRIBUTE_011, SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY)	
			values(@srm_client_entities_seq_id, 2524, @MODULE_NAME , @USER_NAME , @DATE_OF_COMMS  , @DESCRIPTION , @REMARKS , @TIME_TAKEN , @CONTACT_SEQ_ID ,@COMM_TYPE,@COMM_TYPE_NAME,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_PERS_COMMS_LOGS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id, @MODULE , @MODULE_NAME ,@USER, @USER_NAME , @DATE_OF_COMMS  , @DESCRIPTION , @REMARKS , @TIME_TAKEN ,@CONTACT_SEQ_ID, @COMM_TYPE, @COMM_TYPE_NAME,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
