	---############################################ EVENT_REGISTRATION ###########################################################
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @ARCHIVE_STATUS nvarchar(20)
	--declare @bank_name nvarchar(100)
	--declare @bank_code nvarchar(100)
	--declare @bank_address nvarchar(1000)
	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	DECLARE @ATTENDED NVARCHAR(100)
	DECLARE @CANCELLATION_DATE NVARCHAR(100)
	DECLARE @CONF_LETTER_SENT NVARCHAR(100)
	DECLARE @CONFIRMATION_DATE NVARCHAR(100)
	DECLARE @MARKETING_CAMPAIGN NVARCHAR(100)
	DECLARE @MARKETING_CAMPAIGN_NAME NVARCHAR(100)
	--DECLARE @ACCOUNT NVARCHAR(100)
	--DECLARE @ACCOUNT_NAME NVARCHAR(100)
	DECLARE @BOOKER NVARCHAR(100)
	DECLARE @BOOKER_NAME NVARCHAR(100)
	DECLARE @BOOKING_SOURCE NVARCHAR(100)
	DECLARE @BOOKING_SOURCE_NAME NVARCHAR(100)
	DECLARE @DELEGATE_TYPE NVARCHAR(100)
	DECLARE @DELEGATE_TYPE_NAME NVARCHAR(100)
	DECLARE @EVENT_NAME NVARCHAR(100)
	DECLARE @REG_METHOD NVARCHAR(100)
	DECLARE @REG_METHOD_NAME NVARCHAR(100)
	DECLARE @REG_STATUS NVARCHAR(100)
	DECLARE @REG_STATUS_NAME NVARCHAR(100)
	DECLARE @INVOICE_TO_ORGANISATION NVARCHAR(100)
	DECLARE @NO_INVOICE NVARCHAR(100)
	DECLARE @REGISTRATION_DATE NVARCHAR(100)
	DECLARE @REGISTRATION_ID NVARCHAR(100)
	--DECLARE @REMARKS NVARCHAR(1000)
	DECLARE @SESSION_DATE NVARCHAR(100)
	DECLARE @SESSION_TIME NVARCHAR(100)
	--DECLARE @DateModified datetime
	--DECLARE @ModifiedBy nvarchar(200)
	DECLARE @default_event nvarchar(200)
	DECLARE @default_event_name nvarchar(500)


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'EVENT_REGISTRATION'



		DECLARE Cur_records CURSOR LOCAL STATIC  FOR  
	
			SELECT 
				ER.SEQ_ID,
				ATTENDED,
				CONVERT(NVARCHAR, er.CANCELLATION_DATE, 121) CANCELLATION_DATE,
				CONF_LETTER_SENT,
				CONVERT(NVARCHAR, er.CONFIRMATION_DATE, 121) CONFIRMATION_DATE,
				SRM_MARK_CAMP.SEQ_ID AS MARKETING_CAMPAIGN,
				SRM_MARK_CAMP.ATTRIBUTE_001 AS MARKETING_CAMPAIGN_NAME,
				SRM_ACCOUNT.SEQ_ID AS ACCOUNT,
				SRM_ACCOUNT.ATTRIBUTE_001 AS ACCOUNT_NAME,
				SRM_CONTACT.SEQ_ID AS BOOKER,
				SRM_CONTACT.ATTRIBUTE_001 AS BOOKER_NAME,
				SRM_BOOKING_SRC.SEQ_ID AS BOOKING_SOURCE,
				SRM_BOOKING_SRC.ATTRIBUTE_001 AS BOOKING_SOURCE_NAME,
				SRM_DEL_TYPE.SEQ_ID AS DELEGATE_TYPE,
				SRM_DEL_TYPE.ATTRIBUTE_001 AS DELEGATE_TYPE_NAME,
				SRM_EVENT.ATTRIBUTE_001 AS EVENT_NAME,
				SRM_REG_METHOD.SEQ_ID REG_METHOD,
				SRM_REG_METHOD.ATTRIBUTE_001 REG_METHOD_NAME,
				SRM_REG_STATUS.SEQ_ID AS REG_STATUS,
				SRM_REG_STATUS.ATTRIBUTE_001 AS REG_STATUS_NAME,
				INVOICE_TO_ORGANISATION,
				NO_INVOICE,
				CONVERT(NVARCHAR, er.REGISTRATION_DATE, 121) REGISTRATION_DATE,
				REGISTRATION_ID,
				REMARKS,
				CONVERT(NVARCHAR, er.SESSION_DATE, 121) SESSION_DATE,
				SESSION_TIME,
				SRM_EVENT.SEQ_ID AS DEFAULT_EVENT,
				SRM_EVENT.ATTRIBUTE_001 AS DEFAULT_EVENT_NAME,
				CONVERT(NVARCHAR, er.DATE_CREATED, 121) DATE_CREATED,
					  er.created_by,
					 CONVERT(NVARCHAR, er.date_modified, 121) date_modified ,
					  er.modified_by 
			
				FROM ETARGETDATA.DBO.EV_EVENT_REGISTRATIONS ER
					LEFT OUTER JOIN ETARGETDATA.DBO.EV_PARTICIPANTS PART ON ER.EV_PARTICIPANTS_SEQ_ID=PART.SEQ_ID
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_MARK_CAMP ON LOG_MARK_CAMP.ETARGET_SEQ_ID=ER.CRM_MARKETNG_CAMPAIGNS_SEQ_ID AND LOG_MARK_CAMP.ETARGET_TABLE_NAME='CRM_MARKETNG_CAMPAIGNS'and LOG_MARK_CAMP.STARGET_CLIENT_ENTITIES_SEQ_ID=2639
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_MARK_CAMP ON SRM_MARK_CAMP.SEQ_ID=LOG_MARK_CAMP.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_ACCOUNT ON LOG_ACCOUNT.ETARGET_SEQ_ID=ER.CRM_ORGANISATIONS_SEQ_ID AND LOG_ACCOUNT.ETARGET_TABLE_NAME='CRM_ORGANISATIONS'and LOG_ACCOUNT.STARGET_CLIENT_ENTITIES_SEQ_ID=2525
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_ACCOUNT ON SRM_ACCOUNT.SEQ_ID=LOG_ACCOUNT.STARGET_CUS_ENTITY_DATA_SEQ_ID
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=ER.CRM_PERSONS_SEQ_ID AND LOG_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS'and LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID=2524
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BOOKING_SRC ON LOG_BOOKING_SRC.ETARGET_SEQ_ID=ER.EV_BOOKING_SOURCES_SEQ_ID AND LOG_BOOKING_SRC.ETARGET_TABLE_NAME='EV_BOOKING_SOURCES'and LOG_BOOKING_SRC.STARGET_CLIENT_ENTITIES_SEQ_ID=2559
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BOOKING_SRC ON SRM_BOOKING_SRC.SEQ_ID=LOG_BOOKING_SRC.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_DEL_TYPE ON LOG_DEL_TYPE.ETARGET_SEQ_ID=ER.EV_DELEGATE_TYPES_SEQ_ID AND LOG_DEL_TYPE.ETARGET_TABLE_NAME='EV_DELEGATE_TYPES'and LOG_DEL_TYPE.STARGET_CLIENT_ENTITIES_SEQ_ID=2557
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_DEL_TYPE ON SRM_DEL_TYPE.SEQ_ID=LOG_DEL_TYPE.STARGET_CUS_ENTITY_DATA_SEQ_ID
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_EVENT ON LOG_EVENT.ETARGET_SEQ_ID=ER.EV_EVENTS_SEQ_ID AND LOG_EVENT.ETARGET_TABLE_NAME='EV_EVENTS'and LOG_EVENT.STARGET_CLIENT_ENTITIES_SEQ_ID=2556
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_EVENT  ON SRM_EVENT.SEQ_ID=LOG_EVENT.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_REG_METHOD ON LOG_REG_METHOD.ETARGET_SEQ_ID=ER.EV_REGISTRATION_METHODS_SEQ_ID AND LOG_REG_METHOD.ETARGET_TABLE_NAME='EV_REGISTRATION_METHODS'and LOG_REG_METHOD.STARGET_CLIENT_ENTITIES_SEQ_ID=2653
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_REG_METHOD ON SRM_REG_METHOD.SEQ_ID=LOG_REG_METHOD.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_REG_STATUS ON LOG_REG_STATUS.ETARGET_SEQ_ID=ER.EV_REGISTRATION_STATUS_SEQ_ID AND LOG_REG_STATUS.ETARGET_TABLE_NAME='EV_REGISTRATION_STATUS'and LOG_REG_STATUS.STARGET_CLIENT_ENTITIES_SEQ_ID=2558
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_REG_STATUS ON SRM_REG_STATUS.SEQ_ID=LOG_REG_STATUS.STARGET_CUS_ENTITY_DATA_SEQ_ID
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_PART_CONTACT ON LOG_PART_CONTACT.ETARGET_SEQ_ID=PART.CRM_PERSONS_SEQ_ID AND LOG_PART_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS'and LOG_PART_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID=2524
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_PART_CONTACT ON SRM_PART_CONTACT.SEQ_ID=LOG_PART_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID

				where ER.CRM_PERSONS_SEQ_ID=@Source_PERSON_SEQ_ID AND SRM_CONTACT.SEQ_ID is not null


		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@ATTENDED , @CANCELLATION_DATE , @CONF_LETTER_SENT , @CONFIRMATION_DATE , @MARKETING_CAMPAIGN , @MARKETING_CAMPAIGN_NAME , @ACCOUNT , @ACCOUNT_NAME , @BOOKER , @BOOKER_NAME , @BOOKING_SOURCE , @BOOKING_SOURCE_NAME , @DELEGATE_TYPE , @DELEGATE_TYPE_NAME , @EVENT_NAME , @REG_METHOD , @REG_METHOD_NAME , @REG_STATUS , @REG_STATUS_NAME , @INVOICE_TO_ORGANISATION , @NO_INVOICE , @REGISTRATION_DATE , @REGISTRATION_ID,  @REMARKS , @SESSION_DATE , @SESSION_TIME ,@default_event,@default_event_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_022,ATTRIBUTE_019,ATTRIBUTE_020,ATTRIBUTE_018,ATTRIBUTE_027,ATTRIBUTE_028,ATTRIBUTE_025,ATTRIBUTE_026,ATTRIBUTE_012,ATTRIBUTE_013,ATTRIBUTE_010,ATTRIBUTE_011,ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_009,ATTRIBUTE_014,ATTRIBUTE_015,ATTRIBUTE_006,ATTRIBUTE_007,ATTRIBUTE_024,ATTRIBUTE_021,ATTRIBUTE_017,ATTRIBUTE_016,ATTRIBUTE_023,ATTRIBUTE_029,ATTRIBUTE_030, ATTRIBUTE_032,ATTRIBUTE_033,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,@ATTENDED , @CANCELLATION_DATE , @CONF_LETTER_SENT , @CONFIRMATION_DATE , @MARKETING_CAMPAIGN , @MARKETING_CAMPAIGN_NAME , @ACCOUNT , @ACCOUNT_NAME , @BOOKER , @BOOKER_NAME , @BOOKING_SOURCE , @BOOKING_SOURCE_NAME , @DELEGATE_TYPE , @DELEGATE_TYPE_NAME , @EVENT_NAME , @REG_METHOD , @REG_METHOD_NAME , @REG_STATUS , @REG_STATUS_NAME , @INVOICE_TO_ORGANISATION , @NO_INVOICE , @REGISTRATION_DATE , @REGISTRATION_ID,  @REMARKS , @SESSION_DATE , @SESSION_TIME ,@default_event,@default_event_name,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  )
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--insert into log table
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('EV_EVENT_REGISTRATIONS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,@ATTENDED , @CANCELLATION_DATE , @CONF_LETTER_SENT , @CONFIRMATION_DATE , @MARKETING_CAMPAIGN , @MARKETING_CAMPAIGN_NAME , @ACCOUNT , @ACCOUNT_NAME , @BOOKER , @BOOKER_NAME , @BOOKING_SOURCE , @BOOKING_SOURCE_NAME , @DELEGATE_TYPE , @DELEGATE_TYPE_NAME , @EVENT_NAME , @REG_METHOD , @REG_METHOD_NAME , @REG_STATUS , @REG_STATUS_NAME , @INVOICE_TO_ORGANISATION , @NO_INVOICE , @REGISTRATION_DATE , @REGISTRATION_ID,  @REMARKS , @SESSION_DATE , @SESSION_TIME ,@default_event,@default_event_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
