	---############################################ EVENT_DELEGATE ###########################################################
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @ARCHIVE_STATUS nvarchar(20)
	--declare @bank_name nvarchar(100)
	--declare @bank_code nvarchar(100)
	--declare @bank_address nvarchar(1000)
	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	--DECLARE @ATTENDED NVARCHAR(100)
	DECLARE @BOOKING_REFERENCE NVARCHAR(100)
	DECLARE @CORRESPONDENCE_TO_DELEGATE NVARCHAR(100)
	DECLARE @DELEGATE_NO NVARCHAR(100)
	--DECLARE @BOOKING_SOURCE NVARCHAR(100)
	--DECLARE @BOOKING_SOURCE_NAME NVARCHAR(100)
	--DECLARE @DELEGATE_TYPE NVARCHAR(100)
	--DECLARE @DELEGATE_TYPE_NAME NVARCHAR(100)
	DECLARE @EVENT_REGISTRATION NVARCHAR(100)
	DECLARE @EVENT_REGISTRATION_NAME NVARCHAR(100)
	DECLARE @TBA NVARCHAR(100)

	--DECLARE @DateModified datetime
	--DECLARE @ModifiedBy nvarchar(200)

	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'EVENT_DELEGATE'



		DECLARE Cur_records CURSOR LOCAL STATIC  FOR  
	
			SELECT
				ED.SEQ_ID,
				ATTENDED,
				BOOKING_REFERENCE,
				CORRESPONDENCE_TO_DELEGATE,
				DELEGATE_NO,
				SRM_BOOKING_SRC.SEQ_ID AS BOOKING_SOURCE,
				SRM_BOOKING_SRC.ATTRIBUTE_001 AS BOOKING_SOURCE_NAME,
				SRM_DEL_TYPE.SEQ_ID AS DELEGATE_TYPE,
				SRM_DEL_TYPE.ATTRIBUTE_001 AS DELEGATE_TYPE_NAME,
				SRM_EV_REG.SEQ_ID EVENT_REGISTRATION,
				SRM_EV_REG.ATTRIBUTE_001 EVENT_REGISTRATION_NAME,
				TBA,
					 CONVERT(NVARCHAR, ed.DATE_CREATED, 121) DATE_CREATED,
					  ed.created_by,
					 CONVERT(NVARCHAR, ed.date_modified, 121) date_modified ,
					  ed.modified_by 

			FROM ETARGETDATA.DBO.EV_EVENT_DELEGATES ED

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BOOKING_SRC ON LOG_BOOKING_SRC.ETARGET_SEQ_ID=ED.EV_BOOKING_SOURCES_SEQ_ID AND LOG_BOOKING_SRC.ETARGET_TABLE_NAME='EV_BOOKING_SOURCES' and LOG_BOOKING_SRC.STARGET_CLIENT_ENTITIES_SEQ_ID=2559
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BOOKING_SRC ON SRM_BOOKING_SRC.SEQ_ID=LOG_BOOKING_SRC.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_DEL_TYPE ON LOG_DEL_TYPE.ETARGET_SEQ_ID=ED.EV_DELEGATE_TYPES_SEQ_ID AND LOG_DEL_TYPE.ETARGET_TABLE_NAME='EV_DELEGATE_TYPES'and LOG_DEL_TYPE.STARGET_CLIENT_ENTITIES_SEQ_ID=2557
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_DEL_TYPE ON SRM_DEL_TYPE.SEQ_ID=LOG_DEL_TYPE.STARGET_CUS_ENTITY_DATA_SEQ_ID
				inner JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_EV_REG ON LOG_EV_REG.ETARGET_SEQ_ID=ED.EV_EVENT_REGISTRATIONS_SEQ_ID AND LOG_EV_REG.ETARGET_TABLE_NAME='EV_EVENT_REGISTRATIONS' and LOG_EV_REG.STARGET_CLIENT_ENTITIES_SEQ_ID=2560
				inner JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_EV_REG ON SRM_EV_REG.SEQ_ID=LOG_EV_REG.STARGET_CUS_ENTITY_DATA_SEQ_ID
				WHERE SRM_EV_REG.ATTRIBUTE_012= CAST(@SRM_CONTACT_SEQ_ID AS VARCHAR)



		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@ATTENDED , @BOOKING_REFERENCE , @CORRESPONDENCE_TO_DELEGATE , @DELEGATE_NO , @BOOKING_SOURCE , @BOOKING_SOURCE_NAME , @DELEGATE_TYPE , @DELEGATE_TYPE_NAME , @EVENT_REGISTRATION , @EVENT_REGISTRATION_NAME , @TBA  ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_010,ATTRIBUTE_015,ATTRIBUTE_012,ATTRIBUTE_008,ATTRIBUTE_013,ATTRIBUTE_014,ATTRIBUTE_006,ATTRIBUTE_007,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_009,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,@ATTENDED , @BOOKING_REFERENCE , @CORRESPONDENCE_TO_DELEGATE , @DELEGATE_NO , @BOOKING_SOURCE , @BOOKING_SOURCE_NAME , @DELEGATE_TYPE , @DELEGATE_TYPE_NAME , @EVENT_REGISTRATION , @EVENT_REGISTRATION_NAME , @TBA   ,@client_seq_id ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  )
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('EV_EVENT_DELEGATES',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,@ATTENDED , @BOOKING_REFERENCE , @CORRESPONDENCE_TO_DELEGATE , @DELEGATE_NO , @BOOKING_SOURCE , @BOOKING_SOURCE_NAME , @DELEGATE_TYPE , @DELEGATE_TYPE_NAME , @EVENT_REGISTRATION , @EVENT_REGISTRATION_NAME , @TBA  ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
	
	
	--###########################################################################################################################################
	---############################################ EVENT_REGISTRATION_CHARGES ###########################################################
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @ARCHIVE_STATUS nvarchar(20)
	--declare @bank_name nvarchar(100)
	--declare @bank_code nvarchar(100)
	--declare @bank_address nvarchar(1000)
	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	DECLARE @CHARGE_DESC NVARCHAR(100)
	DECLARE @DISCOUNT_AMOUNT NVARCHAR(100)
	DECLARE @DISCOUNT_PERC NVARCHAR(100)
	DECLARE @ANALYSIS_HEAD NVARCHAR(100)
	DECLARE @ANALYSIS_HEAD_NAME NVARCHAR(100)
	--DECLARE @DELEGATE_TYPE NVARCHAR(100)
	--DECLARE @DELEGATE_TYPE_NAME NVARCHAR(100)
	DECLARE @EVENT_DELEGATE NVARCHAR(100)
	DECLARE @EVENT_DELEGATE_NAME NVARCHAR(100)
	--DECLARE @EVENT_REGISTRATION NVARCHAR(100)
	--DECLARE @EVENT_REGISTRATION_NAME NVARCHAR(100)
	DECLARE @RATE_TYPE NVARCHAR(100)
	DECLARE @RATE_TYPE_NAME NVARCHAR(100)
	DECLARE @GROSS_AMOUNT NVARCHAR(100)
	DECLARE @NET_AMOUNT NVARCHAR(100)
	DECLARE @QUANTITY NVARCHAR(100)
	DECLARE @RATE NVARCHAR(100)
	DECLARE @VAT_AMOUNT NVARCHAR(100)
	DECLARE @VAT_PERC NVARCHAR(100)

	--DECLARE @DateModified datetime
	--DECLARE @ModifiedBy nvarchar(200)


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'EVENT_REGISTRATION_CHARGES'



		DECLARE Cur_records CURSOR LOCAL STATIC  FOR  
	
			SELECT 
				ERC.SEQ_ID,
				CHARGE_DESC,
				DISCOUNT_AMOUNT,
				DISCOUNT_PERC,
				SRM_ANA_HEAD.SEQ_ID AS ANALYSIS_HEAD,
				SRM_ANA_HEAD.ATTRIBUTE_001 AS ANALYSIS_HEAD_NAME,
				SRM_DEL_TYPE.SEQ_ID AS DELEGATE_TYPE,
				SRM_DEL_TYPE.ATTRIBUTE_001 AS DELEGATE_TYPE_NAME,
				SRM_LOG_EV_EVENT_DELEGATES.SEQ_ID AS EVENT_DELEGATE,
				SRM_LOG_EV_EVENT_DELEGATES.ATTRIBUTE_008 AS EVENT_DELEGATE_NAME,
				SRM_EV_REG.SEQ_ID EVENT_REGISTRATION,
				SRM_EV_REG.ATTRIBUTE_001 EVENT_REGISTRATION_NAME,
				SRM_RATE_TYPE.SEQ_ID AS RATE_TYPE,
				SRM_RATE_TYPE.ATTRIBUTE_001 AS RATE_TYPE_NAME,
				GROSS_AMOUNT,
				NET_AMOUNT,
				QUANTITY,
				RATE,
				VAT_AMOUNT,
				VAT_PERC,
			 CONVERT(NVARCHAR, ERC.DATE_CREATED, 121) DATE_CREATED,
					  ERC.created_by,
					 CONVERT(NVARCHAR, ERC.date_modified, 121) date_modified ,
					  ERC.modified_by 
			FROM ETARGETDATA.DBO.EV_REGISTER_CHARGES ERC

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_DEL_TYPE ON LOG_DEL_TYPE.ETARGET_SEQ_ID=ERC.EV_DELEGATE_TYPES_SEQ_ID AND LOG_DEL_TYPE.ETARGET_TABLE_NAME='EV_DELEGATE_TYPES'and LOG_DEL_TYPE.STARGET_CLIENT_ENTITIES_SEQ_ID=2557
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_DEL_TYPE ON SRM_DEL_TYPE.SEQ_ID=LOG_DEL_TYPE.STARGET_CUS_ENTITY_DATA_SEQ_ID

				inner JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_EV_REG ON LOG_EV_REG.ETARGET_SEQ_ID=ERC.EV_EVENT_REGISTRATIONS_SEQ_ID AND LOG_EV_REG.ETARGET_TABLE_NAME='EV_EVENT_REGISTRATIONS'and LOG_EV_REG.STARGET_CLIENT_ENTITIES_SEQ_ID=2560
				inner  JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_EV_REG ON SRM_EV_REG.SEQ_ID=LOG_EV_REG.STARGET_CUS_ENTITY_DATA_SEQ_ID

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_RATE_TYPE ON LOG_RATE_TYPE.ETARGET_SEQ_ID=ERC.EV_RATE_TYPES_SEQ_ID AND LOG_RATE_TYPE.ETARGET_TABLE_NAME='EV_RATE_TYPES'and LOG_RATE_TYPE.STARGET_CLIENT_ENTITIES_SEQ_ID=2634
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_RATE_TYPE ON SRM_RATE_TYPE.SEQ_ID=LOG_RATE_TYPE.STARGET_CUS_ENTITY_DATA_SEQ_ID

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_ANA_HEAD ON LOG_ANA_HEAD.ETARGET_SEQ_ID=ERC.EV_ANALYSIS_HEADS_SEQ_ID AND LOG_ANA_HEAD.ETARGET_TABLE_NAME='EV_ANALYSIS_HEADS'and LOG_ANA_HEAD.STARGET_CLIENT_ENTITIES_SEQ_ID=2631
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_ANA_HEAD ON SRM_ANA_HEAD.SEQ_ID=LOG_ANA_HEAD.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_EV_EVENT_DELEGATES ON LOG_EV_EVENT_DELEGATES.ETARGET_SEQ_ID=ERC.EV_EVENT_DELEGATES_SEQ_ID AND LOG_EV_EVENT_DELEGATES.ETARGET_TABLE_NAME='EV_EVENT_DELEGATES'and LOG_EV_EVENT_DELEGATES.STARGET_CLIENT_ENTITIES_SEQ_ID=2656
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_LOG_EV_EVENT_DELEGATES ON SRM_LOG_EV_EVENT_DELEGATES.SEQ_ID=LOG_EV_EVENT_DELEGATES.STARGET_CUS_ENTITY_DATA_SEQ_ID
			
				WHERE SRM_EV_REG.ATTRIBUTE_012= CAST(@SRM_CONTACT_SEQ_ID AS VARCHAR) 





		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@CHARGE_DESC , @DISCOUNT_AMOUNT , @DISCOUNT_PERC , @ANALYSIS_HEAD , @ANALYSIS_HEAD_NAME , @DELEGATE_TYPE , @DELEGATE_TYPE_NAME , @EVENT_DELEGATE , @EVENT_DELEGATE_NAME , @EVENT_REGISTRATION , @EVENT_REGISTRATION_NAME , @RATE_TYPE , @RATE_TYPE_NAME , @GROSS_AMOUNT , @NET_AMOUNT , @QUANTITY , @RATE , @VAT_AMOUNT , @VAT_PERC ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_001,ATTRIBUTE_010,ATTRIBUTE_009,ATTRIBUTE_014,ATTRIBUTE_015,ATTRIBUTE_016,ATTRIBUTE_017,ATTRIBUTE_018,ATTRIBUTE_019,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_013,ATTRIBUTE_008,ATTRIBUTE_007,ATTRIBUTE_006,ATTRIBUTE_012,ATTRIBUTE_011,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,@CHARGE_DESC , @DISCOUNT_AMOUNT , @DISCOUNT_PERC , @ANALYSIS_HEAD , @ANALYSIS_HEAD_NAME , @DELEGATE_TYPE , @DELEGATE_TYPE_NAME , @EVENT_DELEGATE , @EVENT_DELEGATE_NAME , @EVENT_REGISTRATION , @EVENT_REGISTRATION_NAME , @RATE_TYPE , @RATE_TYPE_NAME , @GROSS_AMOUNT , @NET_AMOUNT , @QUANTITY , @RATE , @VAT_AMOUNT , @VAT_PERC   ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  )
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('EV_REGISTER_CHARGES',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,@CHARGE_DESC , @DISCOUNT_AMOUNT , @DISCOUNT_PERC , @ANALYSIS_HEAD , @ANALYSIS_HEAD_NAME , @DELEGATE_TYPE , @DELEGATE_TYPE_NAME , @EVENT_DELEGATE , @EVENT_DELEGATE_NAME , @EVENT_REGISTRATION , @EVENT_REGISTRATION_NAME , @RATE_TYPE , @RATE_TYPE_NAME , @GROSS_AMOUNT , @NET_AMOUNT , @QUANTITY , @RATE , @VAT_AMOUNT , @VAT_PERC ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
