	--############################################ EVENT_SESSION_REGISTRATION ###########################################################
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @ARCHIVE_STATUS nvarchar(20)
	--declare @bank_name nvarchar(100)
	--declare @bank_code nvarchar(100)
	--declare @bank_address nvarchar(1000)
	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	--DECLARE @ATTENDED NVARCHAR(100)
	--DECLARE @EVENT_DELEGATE NVARCHAR(100)
	--DECLARE @EVENT_DELEGATE_NAME NVARCHAR(100)
	--DECLARE @EVENT_REGISTRATION NVARCHAR(100)
	--DECLARE @EVENT_REGISTRATION_NAME NVARCHAR(100)
	DECLARE @EVENT_SESSION NVARCHAR(100)
	DECLARE @EVENT_SESSION_NAME NVARCHAR(100)
	--DECLARE @REG_STATUS NVARCHAR(100)
	--DECLARE @REG_STATUS_NAME NVARCHAR(100)
	DECLARE @NO_OF_SEATS_BOOKED NVARCHAR(100)

	--DECLARE @DateModified datetime
	--DECLARE @ModifiedBy nvarchar(200)

 
	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'EVENT_SESSION_REGISTRATION'



		DECLARE Cur_records CURSOR LOCAL STATIC  FOR  
	
			SELECT 
				ESR.SEQ_ID,
				ATTENDED,
				SRM_LOG_EV_EVENT_DELEGATES.SEQ_ID AS EVENT_DELEGATE,
				SRM_LOG_EV_EVENT_DELEGATES.ATTRIBUTE_008 AS EVENT_DELEGATE_NAME,
				SRM_EV_REG.SEQ_ID EVENT_REGISTRATION,
				SRM_EV_REG.ATTRIBUTE_001 EVENT_REGISTRATION_NAME,
				SRM_EV_SESSION.SEQ_ID EVENT_SESSION,
				SRM_EV_SESSION.ATTRIBUTE_001 EVENT_SESSION_NAME,
				SRM_REG_STATUS.SEQ_ID AS REG_STATUS,
				SRM_REG_STATUS.ATTRIBUTE_001 AS REG_STATUS_NAME,
				NO_OF_SEATS_BOOKED,
			 CONVERT(NVARCHAR, ESR.DATE_CREATED, 121) DATE_CREATED,
					  ESR.created_by,
					 CONVERT(NVARCHAR, ESR.date_modified, 121) date_modified ,
					  ESR.modified_by 


			FROM ETARGETDATA.DBO.EV_SESSN_REGISTRATIONS ESR

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_EV_EVENT_DELEGATES ON LOG_EV_EVENT_DELEGATES.ETARGET_SEQ_ID=ESR.EV_EVENT_DELEGATES_SEQ_ID AND LOG_EV_EVENT_DELEGATES.ETARGET_TABLE_NAME='EV_EVENT_DELEGATES'and LOG_EV_EVENT_DELEGATES.STARGET_CLIENT_ENTITIES_SEQ_ID=2656
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_LOG_EV_EVENT_DELEGATES ON SRM_LOG_EV_EVENT_DELEGATES.SEQ_ID=LOG_EV_EVENT_DELEGATES.STARGET_CUS_ENTITY_DATA_SEQ_ID
				INNER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_EV_REG ON LOG_EV_REG.ETARGET_SEQ_ID=ESR.EV_EVENT_REGISTRATIONS_SEQ_ID AND LOG_EV_REG.ETARGET_TABLE_NAME='EV_EVENT_REGISTRATIONS'and LOG_EV_REG.STARGET_CLIENT_ENTITIES_SEQ_ID=2560
				INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_EV_REG ON SRM_EV_REG.SEQ_ID=LOG_EV_REG.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_REG_STATUS ON LOG_REG_STATUS.ETARGET_SEQ_ID=ESR.EV_REGISTRATION_STATUS_SEQ_ID AND LOG_REG_STATUS.ETARGET_TABLE_NAME='EV_REGISTRATION_STATUS'and LOG_REG_STATUS.STARGET_CLIENT_ENTITIES_SEQ_ID=2558
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_REG_STATUS ON SRM_REG_STATUS.SEQ_ID=LOG_REG_STATUS.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_EV_SESSION ON LOG_EV_SESSION.ETARGET_SEQ_ID=ESR.EV_EVENT_SESSIONS_SEQ_ID AND LOG_EV_SESSION.ETARGET_TABLE_NAME='EV_EVENT_SESSIONS' and LOG_EV_SESSION.STARGET_CLIENT_ENTITIES_SEQ_ID=2646
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_EV_SESSION ON SRM_EV_SESSION.SEQ_ID=LOG_EV_SESSION.STARGET_CUS_ENTITY_DATA_SEQ_ID
			
				WHERE SRM_EV_REG.ATTRIBUTE_012= CAST(@SRM_CONTACT_SEQ_ID AS VARCHAR)




		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@ATTENDED , @EVENT_DELEGATE , @EVENT_DELEGATE_NAME , @EVENT_REGISTRATION , @EVENT_REGISTRATION_NAME , @EVENT_SESSION , @EVENT_SESSION_NAME , @REG_STATUS , @REG_STATUS_NAME , @NO_OF_SEATS_BOOKED  ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_013,ATTRIBUTE_016,ATTRIBUTE_017,ATTRIBUTE_006,ATTRIBUTE_007,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_008,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,@ATTENDED , @EVENT_DELEGATE , @EVENT_DELEGATE_NAME , @EVENT_REGISTRATION , @EVENT_REGISTRATION_NAME , @EVENT_SESSION , @EVENT_SESSION_NAME , @REG_STATUS , @REG_STATUS_NAME , @NO_OF_SEATS_BOOKED    ,@client_seq_id ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  )
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('EV_SESSN_REGISTRATIONS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,@ATTENDED , @EVENT_DELEGATE , @EVENT_DELEGATE_NAME , @EVENT_REGISTRATION , @EVENT_REGISTRATION_NAME , @EVENT_SESSION , @EVENT_SESSION_NAME , @REG_STATUS , @REG_STATUS_NAME , @NO_OF_SEATS_BOOKED  ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
	--###########################################################################################################################################

	--###########################################################################################################################################
	--###########################################################################################################################################
	--###########################################################################################################################################
	--###########################################################################################################################################
	--############################################ MEMBER ###########################################################

	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @ARCHIVE_STATUS nvarchar(20)
	--declare @bank_name nvarchar(100)
	--declare @bank_code nvarchar(100)
	--declare @bank_address nvarchar(1000)
	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	DECLARE @ARCHIVE NVARCHAR(200)
	--DECLARE @ACCOUNT NVARCHAR(200)
	--DECLARE @ACCOUNT_NAME NVARCHAR(200)
	DECLARE @PAID_BY NVARCHAR(200)
	DECLARE @PAID_BY_NAME NVARCHAR(200)
	DECLARE @PAYMENT_FREQUENCY NVARCHAR(200)
	DECLARE @PAYMENT_FREQUENCY_NAME NVARCHAR(200)
	DECLARE @PAYMENT_METHOD NVARCHAR(200)
	DECLARE @PAYMENT_METHOD_NAME NVARCHAR(200)
	--DECLARE @CONTACT NVARCHAR(200)
	--DECLARE @CONTACT_NAME NVARCHAR(200)
	DECLARE @DD_FLAG NVARCHAR(200)
	DECLARE @END_DATE NVARCHAR(200)
	DECLARE @INCLUDE_IN_NEXT_DD NVARCHAR(200)
	DECLARE @INSTALLMENTS_PAID NVARCHAR(200)
	DECLARE @JOIN_DATE NVARCHAR(200)
	DECLARE @RESIGN_REASON NVARCHAR(200)
	DECLARE @RESIGN_REASON_NAME NVARCHAR(200)
	DECLARE @MEMBER_ID NVARCHAR(200)
	DECLARE @NEXT_RENEWAL_DATE NVARCHAR(200)
	DECLARE @REINSTATED_DATE NVARCHAR(200)
	DECLARE @TOTAL_INSTALLMENTS NVARCHAR(200)
	DECLARE @TOTAL_OS NVARCHAR(200)
	DECLARE @STATUS NVARCHAR(200)
	DECLARE @STATUS_NAME NVARCHAR(200)
	DECLARE @STATUS_DATE NVARCHAR(200)
	DECLARE @MEMBER_CATEGORY NVARCHAR(200)
	DECLARE @MEMBER_CATEGORY_NAME NVARCHAR(200)
	DECLARE @CATEGORY_DATE NVARCHAR(200)
	--DECLARE @MARKETING_CAMPAIGN NVARCHAR(200)
	--DECLARE @MARKETING_CAMPAIGN_NAME NVARCHAR(200)
	DECLARE @PONO NVARCHAR(200)
	DECLARE @COURSE_END_DATE NVARCHAR(200)
	
	DECLARE @NEW_MEMBER_ID NVARCHAR(200) ------------------------------------AQ
	DECLARE @MEMBER_UNIQUE_ID SMALLINT  -------------------AQ
	
	

	--DECLARE @DateModified datetime
	--DECLARE @ModifiedBy nvarchar(200)

	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'MEMBER'

		DECLARE Cur_records  CURSOR LOCAL STATIC  FOR 
	
				select MEM.SEQ_ID,
				ARCHIVE,
				SRM_account.SEQ_ID ACCOUNT,
				SRM_account.ATTRIBUTE_001 ACCOUNT_NAME,
				SRM_PAID_BY.SEQ_ID PAID_BY,
				SRM_PAID_BY.ATTRIBUTE_001 PAID_BY_NAME,
				SRM_FREQUENCIES.SEQ_ID PAYMENT_FREQUENCY,
				SRM_FREQUENCIES.ATTRIBUTE_001 PAYMENT_FREQUENCY_NAME,
				SRM_PAYMENT_METHODS.SEQ_ID PAYMENT_METHOD,
				SRM_PAYMENT_METHODS.ATTRIBUTE_001 PAYMENT_METHOD_NAME,
				SRM_CONTACT.SEQ_ID CONTACT,
				SRM_CONTACT.ATTRIBUTE_001 CONTACT_NAME,
				DD_FLAG,
				CONVERT(NVARCHAR, mem.END_DATE, 121) END_DATE,
				INCLUDE_IN_NEXT_DD,
				INSTALLMENTS_PAID,
				CONVERT(NVARCHAR, mem.JOIN_DATE, 121) JOIN_DATE,
				SRM_RESIGN.SEQ_ID RESIGN_REASON,
				SRM_RESIGN.ATTRIBUTE_001 RESIGN_REASON_NAME,
				MEMBER_ID,
				CONVERT(NVARCHAR, mem.NEXT_RENEWAL_DATE, 121) NEXT_RENEWAL_DATE,
				CONVERT(NVARCHAR, mem.REINSTATED_DATE, 121)REINSTATED_DATE,
				TOTAL_INSTALLMENTS,
				TOTAL_OS,
				SRM_STATUS.SEQ_ID [STATUS],
				SRM_STATUS.ATTRIBUTE_001 STATUS_NAME,
				CONVERT(NVARCHAR, MMS.EFFECTIVE_DATE, 121) STATUS_DATE,
				SRM_CATEGORY.SEQ_ID MEMBER_CATEGORY,
				SRM_CATEGORY.ATTRIBUTE_001 MEMBER_CATEGORY_NAME,
				CONVERT(NVARCHAR, MMC.EFFECTIVE_DATE, 121) CATEGORY_DATE,
				SRM_MARK_CAMP.SEQ_ID AS MARKETING_CAMPAIGN,
				SRM_MARK_CAMP.SEQ_ID AS MARKETING_CAMPAIGN_NAME,
				TEXT_FIELD03  [P.O.No.],
				CONVERT(NVARCHAR, mem.DATE_FIELD01, 121) [Course End Date],
				CONVERT(NVARCHAR, mem.DATE_CREATED, 121) DATE_CREATED,
					  mem.created_by,
					 CONVERT(NVARCHAR, mem.date_modified, 121) date_modified ,
					  mem.modified_by 
					 from  ETARGETDATA.DBO.MEM_MEMBERS mem
					 inner join ETARGETDATA.DBO.mem_member_status mms on mms.mem_members_seq_id=mem.seq_id and (mms.ceased_date is null or mms.ceased_date>getdate())
					 inner join ETARGETDATA.DBO.mem_member_categories mmc on mmc.mem_members_seq_id=mem.seq_id and (mmc.ceased_date is null or mmc.ceased_date>getdate())
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_account ON LOG_account.ETARGET_SEQ_ID=mem.crm_organisations_SEQ_ID AND LOG_account.ETARGET_TABLE_NAME='CRM_ORGANISATIONS'and LOG_account.STARGET_CLIENT_ENTITIES_SEQ_ID=2525
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_account ON SRM_account.SEQ_ID=LOG_account.STARGET_CUS_ENTITY_DATA_SEQ_ID
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_PAID_BY ON LOG_PAID_BY.ETARGET_SEQ_ID=mem.crm_organisations_SEQ_ID4 AND LOG_PAID_BY.ETARGET_TABLE_NAME='CRM_ORGANISATIONS'and LOG_PAID_BY.STARGET_CLIENT_ENTITIES_SEQ_ID=2525
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_PAID_BY ON SRM_PAID_BY.SEQ_ID=LOG_PAID_BY.STARGET_CUS_ENTITY_DATA_SEQ_ID
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_FREQUENCIES ON LOG_FREQUENCIES.ETARGET_SEQ_ID=MEM.CRM_PAY_FREQUENCIES_SEQ_ID AND LOG_FREQUENCIES.ETARGET_TABLE_NAME='CRM_PAY_FREQUENCIES'and LOG_FREQUENCIES.STARGET_CLIENT_ENTITIES_SEQ_ID=2578
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_FREQUENCIES ON SRM_FREQUENCIES.SEQ_ID=LOG_FREQUENCIES.STARGET_CUS_ENTITY_DATA_SEQ_ID
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_PAYMENT_METHODS ON LOG_PAYMENT_METHODS.ETARGET_SEQ_ID=MEM.CRM_PAYMENT_METHODS_SEQ_ID AND LOG_PAYMENT_METHODS.ETARGET_TABLE_NAME='CRM_PAYMENT_METHODS'and LOG_PAYMENT_METHODS.STARGET_CLIENT_ENTITIES_SEQ_ID=2542
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_PAYMENT_METHODS  ON SRM_PAYMENT_METHODS.SEQ_ID=LOG_PAYMENT_METHODS.STARGET_CUS_ENTITY_DATA_SEQ_ID
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=mem.crm_PERSONS_SEQ_ID AND LOG_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS'and LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID=2524
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_RESIGN ON LOG_RESIGN.ETARGET_SEQ_ID=mem.MEM_RESIGN_REASONS_SEQ_ID AND LOG_RESIGN.ETARGET_TABLE_NAME='MEM_RESIGN_REASONS'and LOG_RESIGN.STARGET_CLIENT_ENTITIES_SEQ_ID=2543
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_RESIGN ON SRM_RESIGN.SEQ_ID=LOG_RESIGN.STARGET_CUS_ENTITY_DATA_SEQ_ID
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_STATUS ON LOG_STATUS.ETARGET_SEQ_ID=MMS.MEM_STATUS_SEQ_ID AND LOG_STATUS.ETARGET_TABLE_NAME='MEM_STATUS'and LOG_STATUS.STARGET_CLIENT_ENTITIES_SEQ_ID=2577
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_STATUS ON SRM_STATUS.SEQ_ID=LOG_STATUS.STARGET_CUS_ENTITY_DATA_SEQ_ID
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CATEGORY ON LOG_CATEGORY.ETARGET_SEQ_ID=MMC.MEM_CATEGORIES_SEQ_ID AND LOG_CATEGORY.ETARGET_TABLE_NAME='MEM_CATEGORIES'and LOG_CATEGORY.STARGET_CLIENT_ENTITIES_SEQ_ID=2544
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CATEGORY ON SRM_CATEGORY.SEQ_ID=LOG_CATEGORY.STARGET_CUS_ENTITY_DATA_SEQ_ID
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_MARK_CAMP ON LOG_MARK_CAMP.ETARGET_SEQ_ID=MEM.CRM_MARKETNG_CAMPAIGNS_SEQ_ID AND LOG_MARK_CAMP.ETARGET_TABLE_NAME='CRM_MARKETNG_CAMPAIGNS'and LOG_MARK_CAMP.STARGET_CLIENT_ENTITIES_SEQ_ID=2639
					 LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_MARK_CAMP ON SRM_MARK_CAMP.SEQ_ID=LOG_MARK_CAMP.STARGET_CUS_ENTITY_DATA_SEQ_ID
				
					where mem.CRM_PERSONS_SEQ_ID=@Source_PERSON_SEQ_ID AND (SRM_account.SEQ_ID is not  null or SRM_CONTACT.SEQ_ID is not null)

		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@ARCHIVE , @ACCOUNT , @ACCOUNT_NAME ,@PAID_BY , @PAID_BY_NAME , @PAYMENT_FREQUENCY , @PAYMENT_FREQUENCY_NAME , @PAYMENT_METHOD , @PAYMENT_METHOD_NAME , @CONTACT , @CONTACT_NAME , @DD_FLAG , @END_DATE , @INCLUDE_IN_NEXT_DD , @INSTALLMENTS_PAID , @JOIN_DATE , @RESIGN_REASON , @RESIGN_REASON_NAME , @MEMBER_ID , @NEXT_RENEWAL_DATE , @REINSTATED_DATE , @TOTAL_INSTALLMENTS , @TOTAL_OS , @STATUS , @STATUS_NAME , @STATUS_DATE , @MEMBER_CATEGORY , @MEMBER_CATEGORY_NAME , @CATEGORY_DATE , @MARKETING_CAMPAIGN, @MARKETING_CAMPAIGN_NAME, @PONO, @COURSE_END_DATE,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  

		WHILE @@FETCH_STATUS = 0
		BEGIN
			-----------------------------AQ
			IF EXISTS (SELECT ATTRIBUTE_001 FROM [SRM-CUSTOMENTITIES].dbo.CUS_ENTITY_DATA  WHERE ATTRIBUTE_001 = @MEMBER_ID AND CUS_ENTITY_DATA.SRM_CLIENT_ENTITIES_SEQ_ID = 2541)
			BEGIN
				SELECT @MEMBER_UNIQUE_ID = 4				
				EXEC [SRM-Framework_New].dbo.GET_PIVOT_NEXT_ID @UNIQUE_INDEX_ID = @MEMBER_UNIQUE_ID, @SRM_CLIENTS_SEQ_ID = 17, @PIVOT_NEXT_ID = @MEMBER_ID OUTPUT  
			END
			----------------------------AQ
			
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_031,ATTRIBUTE_015,ATTRIBUTE_016,ATTRIBUTE_029,ATTRIBUTE_030,ATTRIBUTE_025,ATTRIBUTE_026,ATTRIBUTE_009,ATTRIBUTE_010,ATTRIBUTE_017,ATTRIBUTE_018,ATTRIBUTE_027,ATTRIBUTE_003,ATTRIBUTE_008,ATTRIBUTE_007,ATTRIBUTE_002,ATTRIBUTE_011,ATTRIBUTE_012,ATTRIBUTE_001,ATTRIBUTE_005,ATTRIBUTE_004,ATTRIBUTE_006,ATTRIBUTE_028,ATTRIBUTE_022,ATTRIBUTE_023,ATTRIBUTE_024,ATTRIBUTE_013,ATTRIBUTE_014,ATTRIBUTE_021,ATTRIBUTE_038,ATTRIBUTE_039,ATTRIBUTE_040,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id, @ARCHIVE , @ACCOUNT , @ACCOUNT_NAME ,@PAID_BY , @PAID_BY_NAME , @PAYMENT_FREQUENCY , @PAYMENT_FREQUENCY_NAME , @PAYMENT_METHOD , @PAYMENT_METHOD_NAME , @CONTACT , @CONTACT_NAME , @DD_FLAG , @END_DATE , @INCLUDE_IN_NEXT_DD , @INSTALLMENTS_PAID , @JOIN_DATE , @RESIGN_REASON , @RESIGN_REASON_NAME , @MEMBER_ID , @NEXT_RENEWAL_DATE , @REINSTATED_DATE , @TOTAL_INSTALLMENTS , @TOTAL_OS , @STATUS , @STATUS_NAME , @STATUS_DATE , @MEMBER_CATEGORY , @MEMBER_CATEGORY_NAME , @CATEGORY_DATE ,  @MARKETING_CAMPAIGN_NAME, @PONO, @COURSE_END_DATE,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  )
		
			SELECT @SRM_MEMBER_SEQ_ID = SCOPE_IDENTITY()
			SET @new_seq_id=@SRM_MEMBER_SEQ_ID
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('MEM_MEMBERS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO  @seq_id,@ARCHIVE , @ACCOUNT , @ACCOUNT_NAME ,@PAID_BY , @PAID_BY_NAME , @PAYMENT_FREQUENCY , @PAYMENT_FREQUENCY_NAME , @PAYMENT_METHOD , @PAYMENT_METHOD_NAME , @CONTACT , @CONTACT_NAME , @DD_FLAG , @END_DATE , @INCLUDE_IN_NEXT_DD , @INSTALLMENTS_PAID , @JOIN_DATE , @RESIGN_REASON , @RESIGN_REASON_NAME , @MEMBER_ID , @NEXT_RENEWAL_DATE , @REINSTATED_DATE , @TOTAL_INSTALLMENTS , @TOTAL_OS , @STATUS , @STATUS_NAME , @STATUS_DATE , @MEMBER_CATEGORY , @MEMBER_CATEGORY_NAME , @CATEGORY_DATE , @MARKETING_CAMPAIGN, @MARKETING_CAMPAIGN_NAME, @PONO, @COURSE_END_DATE,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  

		END

