	--############################################ MEMBER_ASSIGNED_RATE ###########################################################
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)

	--declare @seq_id bigint
	declare @ACTUAL_RATE_AMOUNT nvarchar(100)
	declare @BALANCE nvarchar(200)
	--declare @PAYMENT_METHOD nvarchar(100)
	--declare @PAYMENT_METHOD_name nvarchar(100)
	declare @DISCOUNT nvarchar(100)
	declare @DO_NOT_RENEW nvarchar(100)
	declare @FISCAL_PERIOD nvarchar(100)
	declare @MEMBER nvarchar(100)
	declare @MEMBER_NAME nvarchar(100)
	--declare @RATE_TYPE nvarchar(100)
	--declare @RATE_TYPE_NAME nvarchar(100)
	--declare @QUANTITY nvarchar(100)
	declare @STANDARD_RATE_AMOUNT nvarchar(100)
	declare @SURCHARGE nvarchar(100)
	--declare @VAT_AMOUNT nvarchar(100)
	declare @VAT_RATE nvarchar(100)
	declare @VAT_RATE_NAME nvarchar(100)
	--declare @VAT_PERC nvarchar(100)
	declare @next_due_date nvarchar(100)

	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	--DECLARE @DateModified datetime
	--DECLARE @ModifiedBy nvarchar(200)


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'MEMBER_ASSIGNED_RATE'



		DECLARE Cur_records  CURSOR LOCAL STATIC  FOR 
	
			SELECT 
				MMR.SEQ_ID,
				ACTUAL_RATE_AMOUNT,
				BALANCE,
				SRM_PAYMENT_METHOD.SEQ_ID AS PAYMENT_METHOD,
				SRM_PAYMENT_METHOD.ATTRIBUTE_001 AS PAYMENT_METHOD_NAME,
				DISCOUNT,
				DO_NOT_RENEW,
				FISCAL_PERIOD,
				SRM_MEMBER.SEQ_ID AS MEMBER,
				SRM_MEMBER.ATTRIBUTE_001 AS MEMBER_ID,
				SRM_RATE_TYPE.SEQ_ID AS RATE_TYPE,
				SRM_RATE_TYPE.ATTRIBUTE_001 AS RATE_TYPE_NAME,
				QUANTITY,
				STANDARD_RATE_AMOUNT,
				SURCHARGE,
				VAT_AMOUNT,
				SRM_LOG_VAT_RATE.SEQ_ID AS VAT_RATE,
				SRM_LOG_VAT_RATE.ATTRIBUTE_001 AS VAT_RATE_NAME,
				VAT_PERC,
				CONVERT(NVARCHAR, MMR.NEXT_DUE_DATE, 121)NEXT_DUE_DATE,
				CONVERT(NVARCHAR, MMR.DATE_CREATED, 121) DATE_CREATED,
					  MMR.created_by,
					 CONVERT(NVARCHAR, MMR.date_modified, 121) date_modified ,
					  MMR.modified_by 

				FROM ETARGETDATA.DBO.MEM_MEMBER_RATES MMR
				LEFT OUTER JOIN ETARGETDATA.DBO.CRM_VAT_RATES ON CRM_VAT_RATES.VAT_RATE_ID =MMR.VAT_CODE

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_PAYMENT_METHOD ON LOG_PAYMENT_METHOD.ETARGET_SEQ_ID=Mmr.CRM_PAYMENT_METHODS_SEQ_ID AND LOG_PAYMENT_METHOD.ETARGET_TABLE_NAME='CRM_PAYMENT_METHODS' and LOG_PAYMENT_METHOD.STARGET_CLIENT_ENTITIES_SEQ_ID=2542
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_PAYMENT_METHOD ON SRM_PAYMENT_METHOD.SEQ_ID=LOG_PAYMENT_METHOD.STARGET_CUS_ENTITY_DATA_SEQ_ID

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_MEMBER ON LOG_MEMBER.ETARGET_SEQ_ID=Mmr.MEM_MEMBERS_SEQ_ID AND LOG_MEMBER.ETARGET_TABLE_NAME='MEM_MEMBERS'and LOG_MEMBER.STARGET_CLIENT_ENTITIES_SEQ_ID=2541
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_MEMBER ON SRM_MEMBER.SEQ_ID=LOG_MEMBER.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_RATE_TYPE ON LOG_RATE_TYPE.ETARGET_SEQ_ID=Mmr.MEM_RATE_TYPES_SEQ_ID AND LOG_RATE_TYPE.ETARGET_TABLE_NAME='MEM_RATE_TYPES'and LOG_RATE_TYPE.STARGET_CLIENT_ENTITIES_SEQ_ID=2546
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_RATE_TYPE ON SRM_RATE_TYPE.SEQ_ID=LOG_RATE_TYPE.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_VAT_RATE ON LOG_VAT_RATE.ETARGET_SEQ_ID=CRM_VAT_RATES.SEQ_ID AND LOG_VAT_RATE.ETARGET_TABLE_NAME='CRM_VAT_RATES'and LOG_VAT_RATE.STARGET_CLIENT_ENTITIES_SEQ_ID=2555
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_LOG_VAT_RATE ON SRM_LOG_VAT_RATE.SEQ_ID=LOG_VAT_RATE.STARGET_CUS_ENTITY_DATA_SEQ_ID
 				where SRM_MEMBER.SEQ_ID = @SRM_MEMBER_SEQ_ID
 
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,  @ACTUAL_RATE_AMOUNT, @BALANCE , @PAYMENT_METHOD, @PAYMENT_METHOD_name, @DISCOUNT, @DO_NOT_RENEW, @FISCAL_PERIOD, @MEMBER, @MEMBER_NAME, @RATE_TYPE, @RATE_TYPE_NAME, @QUANTITY, @STANDARD_RATE_AMOUNT, @SURCHARGE, @VAT_AMOUNT, @VAT_RATE, @VAT_RATE_NAME, @VAT_PERC,@next_due_date,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
 
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_016,ATTRIBUTE_010,ATTRIBUTE_018,ATTRIBUTE_019,ATTRIBUTE_012,ATTRIBUTE_020,ATTRIBUTE_004,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_008,ATTRIBUTE_009,ATTRIBUTE_014,ATTRIBUTE_011,ATTRIBUTE_013,ATTRIBUTE_006,ATTRIBUTE_021,ATTRIBUTE_022,ATTRIBUTE_015,ATTRIBUTE_017,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,  @ACTUAL_RATE_AMOUNT, @BALANCE , @PAYMENT_METHOD, @PAYMENT_METHOD_name, @DISCOUNT, @DO_NOT_RENEW, @FISCAL_PERIOD, @MEMBER, @MEMBER_NAME, @RATE_TYPE, @RATE_TYPE_NAME, @QUANTITY, @STANDARD_RATE_AMOUNT, @SURCHARGE, @VAT_AMOUNT, @VAT_RATE, @VAT_RATE_NAME, @VAT_PERC,@next_due_date,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  )
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
	
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('MEM_MEMBER_RATES',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,  @ACTUAL_RATE_AMOUNT, @BALANCE , @PAYMENT_METHOD, @PAYMENT_METHOD_name, @DISCOUNT, @DO_NOT_RENEW, @FISCAL_PERIOD, @MEMBER, @MEMBER_NAME, @RATE_TYPE, @RATE_TYPE_NAME, @QUANTITY, @STANDARD_RATE_AMOUNT, @SURCHARGE, @VAT_AMOUNT, @VAT_RATE, @VAT_RATE_NAME, @VAT_PERC,@next_due_date,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
