	--############################################ MEMBER_FINANCIAL_HISTORY/MEMBER_LEDGER ###########################################################
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)

	--declare @seq_id bigint

	declare @BATCH_ID_NAME nvarchar(100)
	declare @TRANSACTION_TYPE_NAME nvarchar(100)
	--declare @FISCAL_PERIOD nvarchar(100)
	--declare @MEMBER nvarchar(100)
	--declare @MEMBER_NAME nvarchar(100)
	--declare @RATE_TYPE_NAME nvarchar(100)
	--declare @REMARKS nvarchar(100)
	declare @DR_AMOUNT nvarchar(100)
	declare @CR_AMOUNT nvarchar(100)
	declare @TRANSACTION_DATE nvarchar(100)
	declare @TRANSACTION_METHOD nvarchar(100)


	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17


	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)

	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'MEMBER_LEDGER'



		DECLARE Cur_records  CURSOR LOCAL STATIC  FOR 
	
			SELECT 
				MFT.SEQ_ID,
				SRM_BATCH.ATTRIBUTE_001 AS BATCH_ID_NAME,
				case when MFT.CRM_TRANSACTION_TYPES_SEQ_ID=1 then 'Payment' when MFT.CRM_TRANSACTION_TYPES_SEQ_ID=4 then 'New'end TRANSACTION_TYPE_NAME,
				--SRM_TRAN_TYPE.ATTRIBUTE_001 AS TRANSACTION_TYPE_NAME,
				FISCAL_PERIOD,
				SRM_MEMBER.SEQ_ID MEMBER,
				SRM_MEMBER.ATTRIBUTE_001 MEMBER_NAME,
				SRM_RATE.ATTRIBUTE_001 AS RATE_TYPE_NAME,
				REMARKS,
				 CASE WHEN DR_CR ='DR' THEN TRANSACTION_AMOUNT ELSE 0 END AS DEBIT_AMOUNT,
				 CASE WHEN DR_CR ='CR' THEN TRANSACTION_AMOUNT ELSE 0 END AS CREDIT_AMOUNT,
				CONVERT(NVARCHAR, MFT.TRANSACTION_DATE, 121) TRANSACTION_DATE,
				TRANSACTION_METHOD,
				 CONVERT(NVARCHAR, MFT.DATE_CREATED, 121) DATE_CREATED,
					  MFT.created_by,
					 CONVERT(NVARCHAR, MFT.date_modified, 121) date_modified ,
					  MFT.modified_by 
				FROM 
				ETARGETDATA.DBO.MEM_FINANCIAL_TRANS MFT
				LEFT OUTER JOIN ETARGETDATA.DBO.MEM_RATE_TYPES MRT ON MRT.RATE_ID=MFT.RATE_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BATCH ON LOG_BATCH.ETARGET_SEQ_ID=MFT.CRM_PAY_BATCH_HEADERS_SEQ_ID AND LOG_BATCH.STARGET_CLIENT_ENTITIES_SEQ_ID=2580-- ETARGET_TABLE_NAME='CRM_PAY_BATCH_HEADERS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BATCH ON SRM_BATCH.SEQ_ID=LOG_BATCH.STARGET_CUS_ENTITY_DATA_SEQ_ID

				--LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_TRAN_TYPE ON LOG_TRAN_TYPE.ETARGET_SEQ_ID=MFT.CRM_PAY_BATCH_HEADERS_SEQ_ID AND LOG_TRAN_TYPE.STARGET_CLIENT_ENTITIES_SEQ_ID=2681-- ETARGET_TABLE_NAME='CRM_TRANSACTION_TYPES'
				--LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_TRAN_TYPE ON SRM_TRAN_TYPE.SEQ_ID=LOG_TRAN_TYPE.STARGET_CUS_ENTITY_DATA_SEQ_ID
			
				inner JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_MEMBER ON LOG_MEMBER.ETARGET_SEQ_ID=MFT.MEM_MEMBERS_SEQ_ID AND LOG_MEMBER.STARGET_CLIENT_ENTITIES_SEQ_ID=2541-- ETARGET_TABLE_NAME='MEM_MEMBERS'
				inner JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_MEMBER ON SRM_MEMBER.SEQ_ID=LOG_MEMBER.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_RATE ON LOG_RATE.ETARGET_SEQ_ID=MRT.SEQ_ID AND LOG_RATE.STARGET_CLIENT_ENTITIES_SEQ_ID=2546-- ETARGET_TABLE_NAME='MEM_RATE_TYPES'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_RATE ON SRM_RATE.SEQ_ID=LOG_RATE.STARGET_CUS_ENTITY_DATA_SEQ_ID
				where SRM_MEMBER.SEQ_ID = @SRM_MEMBER_SEQ_ID
			
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,  @BATCH_ID_NAME , @TRANSACTION_TYPE_NAME , @FISCAL_PERIOD , @MEMBER , @MEMBER_NAME , @RATE_TYPE_NAME, @REMARKS , @DR_AMOUNT , @CR_AMOUNT , @TRANSACTION_DATE , @TRANSACTION_METHOD ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy
 
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_009,ATTRIBUTE_002,ATTRIBUTE_004,ATTRIBUTE_010,ATTRIBUTE_011,ATTRIBUTE_003,ATTRIBUTE_001,ATTRIBUTE_007,ATTRIBUTE_008,ATTRIBUTE_005,ATTRIBUTE_006,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,  @BATCH_ID_NAME , @TRANSACTION_TYPE_NAME , @FISCAL_PERIOD , @MEMBER , @MEMBER_NAME , @RATE_TYPE_NAME, @REMARKS , @DR_AMOUNT , @CR_AMOUNT , @TRANSACTION_DATE , @TRANSACTION_METHOD   ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
	
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('MEM_FINANCIAL_TRANS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,  @BATCH_ID_NAME , @TRANSACTION_TYPE_NAME , @FISCAL_PERIOD , @MEMBER , @MEMBER_NAME , @RATE_TYPE_NAME, @REMARKS , @DR_AMOUNT , @CR_AMOUNT , @TRANSACTION_DATE , @TRANSACTION_METHOD,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy 
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
	--###########################################################################################################################################

	--############################################ MEMBER_RECEIPT ###########################################################
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)

	--declare @seq_id bigint
	--declare @BATCH_ID_NAME nvarchar(100)
	--declare @MEMBER nvarchar(100)
	--declare @MEMBER_NAME nvarchar(100)
	declare @PRINT_DATE nvarchar(200)
	declare @RECEIPT_AMOUNT nvarchar(100)
	declare @RECEIPT_DATE nvarchar(100)
	declare @RECEIPT_ID nvarchar(100)
	declare @RECEIPT_STATUS nvarchar(100)
	declare @RECEIPT_STATUS_DESCRIPTION nvarchar(100)
	declare @RECEIPT_TITLE nvarchar(100)
	--declare @REMARKS nvarchar(100)
	--declare @VAT_AMOUNT nvarchar(100)


	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)

	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'MEMBER_RECEIPT'



		DECLARE Cur_records  CURSOR LOCAL STATIC  FOR 
	
		
			SELECT 
				MR.SEQ_ID,
				SRM_BATCH.ATTRIBUTE_001 BATCH_ID,
				SRM_MEMBER.SEQ_ID MEMBER,
				SRM_MEMBER.ATTRIBUTE_001 MEMBER_NAME,
				PRINT_DATE,
				RECEIPT_AMOUNT,
				RECEIPT_DATE,
				RECEIPT_ID,
				SRM_RECE_STATUS.SEQ_ID RECEIPT_STATUS,
				SRM_RECE_STATUS.ATTRIBUTE_001 RECEIPT_STATUS_DESCRIPTION,
				RECEIPT_TITLE,
				REMARKS,
				VAT_AMOUNT,
				CONVERT(NVARCHAR, MR.DATE_CREATED, 121) DATE_CREATED,
					  MR.created_by,
					 CONVERT(NVARCHAR, MR.date_modified, 121) date_modified ,
					  MR.modified_by 
				FROM ETARGETDATA.DBO.MEM_RECEIPTS MR

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BATCH ON LOG_BATCH.ETARGET_SEQ_ID=MR.CRM_PAY_BATCH_HEADERS_SEQ_ID AND LOG_BATCH.STARGET_CLIENT_ENTITIES_SEQ_ID=2580-- ETARGET_TABLE_NAME='CRM_PAY_BATCH_HEADERS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BATCH ON SRM_BATCH.SEQ_ID=LOG_BATCH.STARGET_CUS_ENTITY_DATA_SEQ_ID

				inner JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_MEMBER ON LOG_MEMBER.ETARGET_SEQ_ID=MR.MEM_MEMBERS_SEQ_ID AND LOG_MEMBER.STARGET_CLIENT_ENTITIES_SEQ_ID=2541-- ETARGET_TABLE_NAME='MEM_MEMBERS'
				inner  JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_MEMBER ON SRM_MEMBER.SEQ_ID=LOG_MEMBER.STARGET_CUS_ENTITY_DATA_SEQ_ID

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_RECE_STATUS ON SRM_RECE_STATUS.ATTRIBUTE_001=MR.RECEIPT_STATUS collate SQL_Latin1_General_CP1_CI_AS
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_RECE_STATUS ON LOG_RECE_STATUS.STARGET_CUS_ENTITY_DATA_SEQ_ID=SRM_RECE_STATUS.SEQ_ID AND LOG_RECE_STATUS.STARGET_CLIENT_ENTITIES_SEQ_ID=2626-- ETARGET_TABLE_NAME='RECEIPT_STATUS'
			
				where SRM_MEMBER.SEQ_ID = @SRM_MEMBER_SEQ_ID

		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,    @BATCH_ID_NAME , @MEMBER , @MEMBER_NAME , @PRINT_DATE , @RECEIPT_AMOUNT,  @RECEIPT_DATE , @RECEIPT_ID , @RECEIPT_STATUS , @RECEIPT_STATUS_DESCRIPTION , @RECEIPT_TITLE , @REMARKS , @VAT_AMOUNT ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy
 
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,ATTRIBUTE_004,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_007,ATTRIBUTE_010,ATTRIBUTE_006,ATTRIBUTE_001,ATTRIBUTE_011,ATTRIBUTE_012,ATTRIBUTE_005,ATTRIBUTE_013,ATTRIBUTE_009,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,   @BATCH_ID_NAME , @MEMBER , @MEMBER_NAME , @PRINT_DATE , @RECEIPT_AMOUNT,  @RECEIPT_DATE , @RECEIPT_ID , @RECEIPT_STATUS , @RECEIPT_STATUS_DESCRIPTION , @RECEIPT_TITLE , @REMARKS , @VAT_AMOUNT   ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
	
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('MEM_RECEIPTS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,   @BATCH_ID_NAME , @MEMBER , @MEMBER_NAME , @PRINT_DATE , @RECEIPT_AMOUNT,  @RECEIPT_DATE , @RECEIPT_ID , @RECEIPT_STATUS , @RECEIPT_STATUS_DESCRIPTION , @RECEIPT_TITLE , @REMARKS , @VAT_AMOUNT ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
