	--############################################ MEMBER_RECEIPT_TRANSACTION ###########################################################
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)

	--declare @seq_id bigint
	--declare @FISCAL_PERIOD nvarchar(100)
	declare @MEMBER_RECEIPT nvarchar(100)
	declare @MEMBER_RECEIPT_NAME nvarchar(100)
	declare @RATE_AMOUNT nvarchar(100)
	--declare @RATE_TYPE nvarchar(200)
	--declare @VAT_AMOUNT nvarchar(100)


	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'MEMBER_RECEIPT_TRANSACTION'



		DECLARE Cur_records  CURSOR LOCAL STATIC  FOR 
	
		
			SELECT 
				MRT.SEQ_ID,
				FISCAL_PERIOD,
				SRM_RECEIPT.SEQ_ID MEMBER_RECEIPT,
				SRM_RECEIPT.ATTRIBUTE_001 MEMBER_RECEIPT_NAME,
				RATE_AMOUNT,
				SRM_RATE.ATTRIBUTE_001 AS RATE_TYPE,
				VAT_AMOUNT,
				CONVERT(NVARCHAR, MRT.DATE_CREATED, 121) DATE_CREATED,
					  MRT.created_by,
					 CONVERT(NVARCHAR, MRT.date_modified, 121) date_modified ,
					  MRT.modified_by 

			FROM ETARGETDATA.DBO.MEM_RECEIPT_TRANS MRT

				LEFT OUTER JOIN ETARGETDATA.DBO.MEM_RATE_TYPES MT ON MT.RATE_ID=MRT.RATE_ID 
				inner JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_RECEIPT ON LOG_RECEIPT.ETARGET_SEQ_ID=MRT.MEM_RECEIPTS_SEQ_ID AND LOG_RECEIPT.STARGET_CLIENT_ENTITIES_SEQ_ID=2625-- ETARGET_TABLE_NAME='MEM_RECEIPTS'
				inner JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_RECEIPT ON SRM_RECEIPT.SEQ_ID=LOG_RECEIPT.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_RATE ON LOG_RATE.ETARGET_SEQ_ID=MT.SEQ_ID AND LOG_RATE.STARGET_CLIENT_ENTITIES_SEQ_ID=2546-- .ETARGET_TABLE_NAME='MEM_RATE_TYPES'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_RATE ON SRM_RATE.SEQ_ID=LOG_RATE.STARGET_CUS_ENTITY_DATA_SEQ_ID

			WHERE SRM_RECEIPT.ATTRIBUTE_002= CAST(@SRM_MEMBER_SEQ_ID AS VARCHAR)

		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,    @FISCAL_PERIOD , @MEMBER_RECEIPT , @MEMBER_RECEIPT_NAME , @RATE_AMOUNT , @RATE_TYPE , @VAT_AMOUNT,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy
 
		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_005,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_008,ATTRIBUTE_004,ATTRIBUTE_007,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,  @FISCAL_PERIOD , @MEMBER_RECEIPT , @MEMBER_RECEIPT_NAME , @RATE_AMOUNT , @RATE_TYPE , @VAT_AMOUNT   ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
	
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('MEM_RECEIPT_TRANS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,    @FISCAL_PERIOD , @MEMBER_RECEIPT , @MEMBER_RECEIPT_NAME , @RATE_AMOUNT , @RATE_TYPE , @VAT_AMOUNT,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy
		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
