	--###########################################################################################################################################
	--###########################################################################################################################################
	--###########################################################################################################################################

	--############################################ FINANCE_TRANSACTION ###########################################################
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	declare @WEB  char

	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	declare @DEL_COUNTY nvarchar(200)
	declare @DEL_COUNTY_name nvarchar(200)
	declare @BIL_COUNTY nvarchar(200)
	declare @BIL_COUNTY_NAME nvarchar(200)
	declare @DEL_COUNTRY nvarchar(200)
	declare @DEL_COUNTRY_NAME nvarchar(200)
	declare @BIL_COUNTRY nvarchar(200)
	declare @BIL_COUNTRY_NAME nvarchar(200)
	declare @DELIVERY_ADD_LINE_1 nvarchar(200)
	declare @DELIVERY_ADD_LINE_2 nvarchar(200)
	declare @DELIVERY_ADD_LINE_3 nvarchar(200)
	declare @DELIVERY_JOB_TITLE nvarchar(200)
	declare @DELIVERY_NAME nvarchar(200)
	declare @DELIVERY_ORG_NAME nvarchar(200)
	declare @DELIVERY_POST_CODE  nvarchar(200)
	declare @DELIVERY_TOWN nvarchar(200)
	declare @INVOICE_ADD_LINE_1 nvarchar(200)
	declare @INVOICE_ADD_LINE_2 nvarchar(200)
	declare @INVOICE_ADD_LINE_3 nvarchar(200)
	declare @INVOICE_JOB_TITLE nvarchar(200)
	declare @INVOICE_NAME  nvarchar(200)
	declare @INVOICE_ORG_NAME  nvarchar(200)
	declare @INVOICE_POST_CODE nvarchar(200)
	declare @INVOICE_TOWN nvarchar(200)
	declare @BATCH_ID nvarchar(200)
	--declare @BATCH_ID_NAME nvarchar(200)
	--declare @REMARKS nvarchar(200)
	declare @TOTAL_CREDIT nvarchar(200)
	declare @TOTAL_DISCOUNT nvarchar(200)
	declare @TOTAL_INVOICE nvarchar(200)
	declare @TOTAL_RECEIPT nvarchar(200)
	declare @TOTAL_REFUND nvarchar(200)
	declare @TOTAL_VAT nvarchar(200)
	--declare @BALANCE nvarchar(200)
	declare @INVOICE_NO nvarchar(200)
	declare @PAYMENT_DUE_DATE nvarchar(200)
	declare @INVOICE_DATE nvarchar(200)
	--declare @ACCOUNT nvarchar(200)
	--declare @ACCOUNT_NAME nvarchar(200)
	--declare @CONTACT nvarchar(200)
	--declare @CONTACT_NAME nvarchar(200)
	DECLARE @DELIVERY_DEPARTMENT NVARCHAR(100)
	DECLARE @INVOICE_DEPARTMENT NVARCHAR(100)
	DECLARE @INVOICE_STATUS NVARCHAR(100)
	DECLARE @transaction_type NVARCHAR(100)
	--DECLARE @transaction_type_name NVARCHAR(100)

	-- DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)

	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'FINANCE_TRANSACTION'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR  
		SELECT 
			IIBD.SEQ_ID,
			SRM_DEL_COUNTY.SEQ_ID AS DEL_COUNTY,
			SRM_DEL_COUNTY.ATTRIBUTE_001 AS DEL_COUNTY_NAME,
			SRM_BIL_COUNTY.SEQ_ID AS BIL_COUNTY,
			SRM_BIL_COUNTY.ATTRIBUTE_001 AS BIL_COUNTY_NAME,
			SRM_DEL_COUNTRY.SEQ_ID AS DEL_COUNTRY,
			SRM_DEL_COUNTRY.ATTRIBUTE_001 AS DEL_COUNTRY_NAME,
			SRM_BIL_COUNTRY.SEQ_ID AS BIL_COUNTRY,
			SRM_BIL_COUNTRY.ATTRIBUTE_001 AS BIL_COUNTRY_NAME,
			DELIVERY_ADD_LINE_1,
			DELIVERY_ADD_LINE_2,
			DELIVERY_ADD_LINE_3,
			DELIVERY_JOB_TITLE,
			DELIVERY_NAME,
			DELIVERY_ORG_NAME,
			DELIVERY_POST_CODE,
			DELIVERY_TOWN,
			INVOICE_ADD_LINE_1,
			INVOICE_ADD_LINE_2,
			INVOICE_ADD_LINE_3,
			INVOICE_JOB_TITLE,
			INVOICE_NAME,
			INVOICE_ORG_NAME,
			INVOICE_POST_CODE,
			INVOICE_TOWN,
			SRM_BATCH.SEQ_ID AS BATCH_ID,
			SRM_BATCH.ATTRIBUTE_001 AS BATCH_ID_NAME,
			IIBD.REMARKS,
			TOTAL_CREDIT,
			TOTAL_DISCOUNT,
			TOTAL_INVOICE,
			TOTAL_RECEIPT,
			TOTAL_REFUND,
			TOTAL_VAT,
			BALANCE,
			INVOICE_NO,
			CONVERT(NVARCHAR, IIBD.PAYMENT_DUE_DATE, 121) PAYMENT_DUE_DATE,
			CONVERT(NVARCHAR, IIBD.INVOICE_DATE, 121)INVOICE_DATE,
			SRM_ACCOUNT.SEQ_ID AS ACCOUNT,
			SRM_ACCOUNT.ATTRIBUTE_001 AS ACCOUNT_NAME,
			SRM_CONTACT.SEQ_ID AS CONTACT,
			SRM_CONTACT.ATTRIBUTE_001 AS CONTACT_NAME,
			DELIVERY_DEPARTMENT,
			INVOICE_DEPARTMENT,
			INVOICE_STATUS,
			(SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_001='Invoice' and SRM_CLIENT_ENTITIES_SEQ_ID=( select top 1 C.SEQ_ID  
					FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
					WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
					AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
					AND C.SRM_CLIENTS_SEQ_ID = 17 AND C.ENTITY_DISPLAY_NAME like 'TRANSACTION_TYPE')) as Transaction_Type,
				'Invoice' as Transaction_Type_Name,
				 CONVERT(NVARCHAR, IIBD.DATE_CREATED, 121) DATE_CREATED,
					  IIBD.created_by,
					 CONVERT(NVARCHAR, IIBD.date_modified, 121) date_modified ,
					  IIBD.modified_by 




			FROM
			ETARGETDATA.dbo.ISC_INV_BATCH_DETAILS IIBD
			INNER JOIN ETARGETDATA.dbo.ISC_CUSTOMERS IC ON IC.SEQ_ID =IIBD.ISC_CUSTOMERS_SEQ_ID
		
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_ACCOUNT ON LOG_ACCOUNT.ETARGET_SEQ_ID=IC.CRM_ORGANISATIONS_SEQ_ID AND LOG_ACCOUNT.STARGET_CLIENT_ENTITIES_SEQ_ID=2525
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_ACCOUNT ON SRM_ACCOUNT.SEQ_ID=LOG_ACCOUNT.STARGET_CUS_ENTITY_DATA_SEQ_ID

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=IC.CRM_PERSONS_SEQ_ID AND LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID=2524
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_DEL_COUNTY ON LOG_DEL_COUNTY.ETARGET_SEQ_ID=IIBD.CRM_COUNTIES_SEQ_ID AND LOG_DEL_COUNTY.STARGET_CLIENT_ENTITIES_SEQ_ID=2550
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_DEL_COUNTY ON SRM_DEL_COUNTY.SEQ_ID=LOG_DEL_COUNTY.STARGET_CUS_ENTITY_DATA_SEQ_ID

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BIL_COUNTY ON LOG_BIL_COUNTY.ETARGET_SEQ_ID=IIBD.CRM_COUNTIES_SEQ_ID2 AND LOG_BIL_COUNTY.STARGET_CLIENT_ENTITIES_SEQ_ID=2550
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BIL_COUNTY ON SRM_BIL_COUNTY.SEQ_ID=LOG_BIL_COUNTY.STARGET_CUS_ENTITY_DATA_SEQ_ID

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_DEL_COUNTRY ON LOG_DEL_COUNTRY.ETARGET_SEQ_ID=IIBD.CRM_COUNTRIES_SEQ_ID AND LOG_DEL_COUNTRY.STARGET_CLIENT_ENTITIES_SEQ_ID=2549
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_DEL_COUNTRY ON SRM_DEL_COUNTRY.SEQ_ID=LOG_DEL_COUNTRY.STARGET_CUS_ENTITY_DATA_SEQ_ID


			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BIL_COUNTRY ON LOG_BIL_COUNTRY.ETARGET_SEQ_ID=IIBD.CRM_COUNTRIES_SEQ_ID2 AND LOG_BIL_COUNTRY.STARGET_CLIENT_ENTITIES_SEQ_ID=2549
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BIL_COUNTRY ON SRM_BIL_COUNTRY.SEQ_ID=LOG_BIL_COUNTRY.STARGET_CUS_ENTITY_DATA_SEQ_ID

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BATCH ON LOG_BATCH.ETARGET_SEQ_ID=IIBD.ISC_INV_BATCH_HEADERS_SEQ_ID AND LOG_BATCH.STARGET_CLIENT_ENTITIES_SEQ_ID=2666
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BATCH ON SRM_BATCH.SEQ_ID=LOG_BATCH.STARGET_CUS_ENTITY_DATA_SEQ_ID
			WHERE SRM_CONTACT.SEQ_ID=@SRM_CONTACT_SEQ_ID
		

		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@DEL_COUNTY ,@DEL_COUNTY_name ,@BIL_COUNTY ,@BIL_COUNTY_NAME ,@DEL_COUNTRY ,@DEL_COUNTRY_NAME ,@BIL_COUNTRY,@BIL_COUNTRY_NAME,@DELIVERY_ADD_LINE_1 ,@DELIVERY_ADD_LINE_2 ,@DELIVERY_ADD_LINE_3 ,@DELIVERY_JOB_TITLE, @DELIVERY_NAME ,@DELIVERY_ORG_NAME ,@DELIVERY_POST_CODE ,@DELIVERY_TOWN ,@INVOICE_ADD_LINE_1 ,@INVOICE_ADD_LINE_2 ,@INVOICE_ADD_LINE_3,@INVOICE_JOB_TITLE,@INVOICE_NAME  ,@INVOICE_ORG_NAME , @INVOICE_POST_CODE ,@INVOICE_TOWN,@BATCH_ID ,@BATCH_ID_NAME ,@REMARKS ,@TOTAL_CREDIT ,@TOTAL_DISCOUNT ,@TOTAL_INVOICE ,@TOTAL_RECEIPT ,@TOTAL_REFUND ,@TOTAL_VAT ,@BALANCE,@INVOICE_NO,@PAYMENT_DUE_DATE,@INVOICE_DATE,@ACCOUNT,@ACCOUNT_NAME, @CONTACT ,@CONTACT_NAME ,@DELIVERY_DEPARTMENT,@INVOICE_DEPARTMENT, @INVOICE_STATUS,@transaction_type,@transaction_type_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_021,ATTRIBUTE_022,ATTRIBUTE_033,ATTRIBUTE_034,ATTRIBUTE_023,ATTRIBUTE_024,ATTRIBUTE_035,ATTRIBUTE_036,ATTRIBUTE_016,ATTRIBUTE_017,ATTRIBUTE_018,ATTRIBUTE_014,ATTRIBUTE_013,ATTRIBUTE_015,ATTRIBUTE_020,ATTRIBUTE_019,ATTRIBUTE_028,ATTRIBUTE_029,ATTRIBUTE_030,ATTRIBUTE_026,ATTRIBUTE_025,ATTRIBUTE_027,ATTRIBUTE_032,ATTRIBUTE_031,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_051,ATTRIBUTE_048,ATTRIBUTE_038,ATTRIBUTE_046,ATTRIBUTE_047,ATTRIBUTE_049,ATTRIBUTE_040,ATTRIBUTE_050,ATTRIBUTE_001,ATTRIBUTE_011,ATTRIBUTE_010,ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_006,ATTRIBUTE_007,ATTRIBUTE_061,ATTRIBUTE_060,ATTRIBUTE_043,ATTRIBUTE_054,ATTRIBUTE_055,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,@DEL_COUNTY ,@DEL_COUNTY_name ,@BIL_COUNTY ,@BIL_COUNTY_NAME ,@DEL_COUNTRY ,@DEL_COUNTRY_NAME ,@BIL_COUNTRY,@BIL_COUNTRY_NAME,@DELIVERY_ADD_LINE_1 ,@DELIVERY_ADD_LINE_2 ,@DELIVERY_ADD_LINE_3 ,@DELIVERY_JOB_TITLE, @DELIVERY_NAME ,@DELIVERY_ORG_NAME ,@DELIVERY_POST_CODE ,@DELIVERY_TOWN ,@INVOICE_ADD_LINE_1 ,@INVOICE_ADD_LINE_2 ,@INVOICE_ADD_LINE_3,@INVOICE_JOB_TITLE,@INVOICE_NAME  ,@INVOICE_ORG_NAME , @INVOICE_POST_CODE ,@INVOICE_TOWN,@BATCH_ID ,@BATCH_ID_NAME ,@REMARKS ,@TOTAL_CREDIT ,@TOTAL_DISCOUNT ,@TOTAL_INVOICE ,@TOTAL_RECEIPT ,@TOTAL_REFUND ,@TOTAL_VAT ,@BALANCE,@INVOICE_NO,@PAYMENT_DUE_DATE,@INVOICE_DATE,@ACCOUNT,@ACCOUNT_NAME, @CONTACT ,@CONTACT_NAME ,@DELIVERY_DEPARTMENT,@INVOICE_DEPARTMENT, @INVOICE_STATUS,@transaction_type,@transaction_type_name ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
	
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('ISC_INV_BATCH_DETAILS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,@DEL_COUNTY ,@DEL_COUNTY_name ,@BIL_COUNTY ,@BIL_COUNTY_NAME ,@DEL_COUNTRY ,@DEL_COUNTRY_NAME ,@BIL_COUNTRY,@BIL_COUNTRY_NAME,@DELIVERY_ADD_LINE_1 ,@DELIVERY_ADD_LINE_2 ,@DELIVERY_ADD_LINE_3 ,@DELIVERY_JOB_TITLE, @DELIVERY_NAME ,@DELIVERY_ORG_NAME ,@DELIVERY_POST_CODE ,@DELIVERY_TOWN ,@INVOICE_ADD_LINE_1 ,@INVOICE_ADD_LINE_2 ,@INVOICE_ADD_LINE_3,@INVOICE_JOB_TITLE,@INVOICE_NAME  ,@INVOICE_ORG_NAME , @INVOICE_POST_CODE ,@INVOICE_TOWN,@BATCH_ID ,@BATCH_ID_NAME ,@REMARKS ,@TOTAL_CREDIT ,@TOTAL_DISCOUNT ,@TOTAL_INVOICE ,@TOTAL_RECEIPT ,@TOTAL_REFUND ,@TOTAL_VAT ,@BALANCE,@INVOICE_NO,@PAYMENT_DUE_DATE,@INVOICE_DATE,@ACCOUNT,@ACCOUNT_NAME, @CONTACT ,@CONTACT_NAME ,@DELIVERY_DEPARTMENT,@INVOICE_DEPARTMENT, @INVOICE_STATUS,@transaction_type,@transaction_type_name,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

		END

		CLOSE Cur_records
