	--############################################ FINANCE_TRANSACTION_DETAIL(ISC) ###########################################################

	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @WEB  char

	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	DECLARE @LEDGER_ACCOUNT NVARCHAR(100)
	DECLARE @LEDGER_ACCOUNT_NAME NVARCHAR(100)
	--DECLARE @VAT_RATE NVARCHAR(100)
	--DECLARE @VAT_RATE_NAME NVARCHAR(100)
	--DECLARE @DISCOUNT_AMOUNT NVARCHAR(100)
	--DECLARE @GROSS_AMOUNT NVARCHAR(100)
	DECLARE @FINANCE_TRANSACTION NVARCHAR(100)
	DECLARE @FINANCE_TRANSACTION_NAME NVARCHAR(100)
	DECLARE @PRODUCT NVARCHAR(100)
	DECLARE @PRODUCT_NAME NVARCHAR(100)
	--DECLARE @NET_AMOUNT NVARCHAR(100)
	--DECLARE @QUANTITY NVARCHAR(100)
	DECLARE @UNIT_PRICE NVARCHAR(100)
	--DECLARE @VAT_AMOUNT  NVARCHAR(100)
	DECLARE @VAT_RATE_PERC  NVARCHAR(100)

	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)

	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'FINANCE_TRANSACTION_DETAIL'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR  
			SELECT 
				IIBD.SEQ_ID,
				SRM_LEDGER_ACC.SEQ_ID AS LEDGER_ACCOUNT,
				SRM_LEDGER_ACC.ATTRIBUTE_001 AS LEDGER_ACCOUNT_NAME,
				SRM_VAT.SEQ_ID VAT_RATE,
				SRM_VAT.ATTRIBUTE_001 VAT_RATE_NAME,
				DISCOUNT_AMOUNT,
				GROSS_AMOUNT,
				SRM_BATCH_DETAILS.SEQ_ID AS FINANCE_TRANSACTION,
				SRM_BATCH_DETAILS.ATTRIBUTE_001 AS FINANCE_TRANSACTION_NAME,
				SRM_PROD.SEQ_ID PRODUCT,
				SRM_PROD.ATTRIBUTE_001 PRODUCT_NAME,
				NET_AMOUNT,
				QUANTITY,
				UNIT_PRICE,
				VAT_AMOUNT,
				VAT_RATE_PERC,
				 CONVERT(NVARCHAR, IIBD.DATE_CREATED, 121) DATE_CREATED,
					  IIBD.created_by,
					 CONVERT(NVARCHAR, IIBD.date_modified, 121) date_modified ,
					  IIBD.modified_by 
			
			FROM ETARGETDATA.dbo.ISC_INV_BATCH_TRANS IIBD


				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_LEDGER_ACC ON LOG_LEDGER_ACC.ETARGET_SEQ_ID=IIBD.CRM_LEDGER_ACCOUNTS_SEQ_ID AND LOG_LEDGER_ACC.STARGET_CLIENT_ENTITIES_SEQ_ID=2561
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_LEDGER_ACC ON SRM_LEDGER_ACC.SEQ_ID=LOG_LEDGER_ACC.STARGET_CUS_ENTITY_DATA_SEQ_ID


				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_VAT ON LOG_VAT.ETARGET_SEQ_ID=IIBD.CRM_VAT_RATES_SEQ_ID AND LOG_VAT.STARGET_CLIENT_ENTITIES_SEQ_ID=2555
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_VAT ON SRM_VAT.SEQ_ID=LOG_VAT.STARGET_CUS_ENTITY_DATA_SEQ_ID
			
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BATCH_DETAILS ON LOG_BATCH_DETAILS.ETARGET_SEQ_ID=IIBD.ISC_INV_BATCH_DETAILS_SEQ_ID AND LOG_BATCH_DETAILS.STARGET_CLIENT_ENTITIES_SEQ_ID=2667
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BATCH_DETAILS ON SRM_BATCH_DETAILS.SEQ_ID=LOG_BATCH_DETAILS.STARGET_CUS_ENTITY_DATA_SEQ_ID
			
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_PROD ON LOG_PROD.ETARGET_SEQ_ID=IIBD.ISC_PRODUCTS_SEQ_ID AND LOG_PROD.STARGET_CLIENT_ENTITIES_SEQ_ID=2568
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_PROD ON SRM_PROD.SEQ_ID=LOG_PROD.STARGET_CUS_ENTITY_DATA_SEQ_ID
			
				WHERE SRM_BATCH_DETAILS.ATTRIBUTE_006=CAST(@SRM_CONTACT_SEQ_ID AS VARCHAR)
	
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id, @LEDGER_ACCOUNT , @LEDGER_ACCOUNT_NAME , @VAT_RATE , @VAT_RATE_NAME , @DISCOUNT_AMOUNT , @GROSS_AMOUNT , @FINANCE_TRANSACTION , @FINANCE_TRANSACTION_NAME , @PRODUCT , @PRODUCT_NAME , @NET_AMOUNT , @QUANTITY , @UNIT_PRICE , @VAT_AMOUNT  , @VAT_RATE_PERC ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,  ATTRIBUTE_008,ATTRIBUTE_009,ATTRIBUTE_010,ATTRIBUTE_011,ATTRIBUTE_017,ATTRIBUTE_020,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_022,ATTRIBUTE_023,ATTRIBUTE_018,ATTRIBUTE_014,ATTRIBUTE_013,ATTRIBUTE_019,ATTRIBUTE_012,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY)	
			values(@srm_client_entities_seq_id, @LEDGER_ACCOUNT , @LEDGER_ACCOUNT_NAME , @VAT_RATE , @VAT_RATE_NAME , @DISCOUNT_AMOUNT , @GROSS_AMOUNT , @FINANCE_TRANSACTION , @FINANCE_TRANSACTION_NAME , @PRODUCT , @PRODUCT_NAME , @NET_AMOUNT , @QUANTITY , @UNIT_PRICE , @VAT_AMOUNT  , @VAT_RATE_PERC  ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('ISC_INV_BATCH_TRANS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id, @LEDGER_ACCOUNT , @LEDGER_ACCOUNT_NAME , @VAT_RATE , @VAT_RATE_NAME , @DISCOUNT_AMOUNT , @GROSS_AMOUNT , @FINANCE_TRANSACTION , @FINANCE_TRANSACTION_NAME , @PRODUCT , @PRODUCT_NAME , @NET_AMOUNT , @QUANTITY , @UNIT_PRICE , @VAT_AMOUNT  , @VAT_RATE_PERC ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
