			values(@srm_client_entities_seq_id,  @LEDGER_ACCOUNT , @LEDGER_ACCOUNT_NAME , @VAT_RATE , @VAT_RATE_NAME , @DISCOUNT_AMOUNT , @DISCOUNT_PERC , @PRODUCT , @PRODUCT_NAME , @GROSS_AMOUNT , @FINANCE_TRANSACTION , @FINANCE_TRANSACTION_NAME , @NET_AMOUNT , @QUANTITY , @UNIT_PRICE , @REMARKS , @TOTAL_AMOUNT , @VAT_AMOUNT,   @VAT_RATE_PERC    ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
