	--declare @BATCH_ID nvarchar(200)
	--declare @BATCH_ID_NAME nvarchar(200)
	declare @PAYMENT_REFERENCE nvarchar(200)
	--declare @REMARKS nvarchar(200)
	declare @TOTAL_PAYMENT_RCVD nvarchar(200)
	--declare @TRANSACTION_DATE nvarchar(200)
	declare @TRANSACTION_ID nvarchar(200)
	--declare @CONTACT nvarchar(200)
	--declare @CONTACT_NAME nvarchar(200)
	--declare @ACCOUNT nvarchar(200)
	--declare @ACCOUNT_NAME nvarchar(200)
	declare @TRAN_TYPE nvarchar(200)
	declare @TRAN_TYPE_NAME nvarchar(200)


	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)

	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'PAYMENT_BATCH_TRANSACTION'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR  
	

			SELECT 
				PT.SEQ_ID,
				SRM_BATCH.SEQ_ID AS BATCH_ID,
				SRM_BATCH.ATTRIBUTE_001 AS BATCH_ID_NAME,
				PAYMENT_REFERENCE,
				REMARKS,
				TOTAL_PAYMENT_RCVD,
				CONVERT(NVARCHAR, PT.TRANSACTION_DATE, 121) TRANSACTION_DATE,
				TRANSACTION_ID,
				SRM_CONTACT.SEQ_ID AS CONTACT,
				SRM_CONTACT.ATTRIBUTE_001 AS CONTACT_NAME,
				SRM_ACCOUNT.SEQ_ID AS ACCOUNT,
				SRM_ACCOUNT.ATTRIBUTE_001 AS ACCOUNT_NAME,
				3085508 AS TRAN_TYPE,
				'Payment' AS TRAN_TYPE_NAME,
				 CONVERT(NVARCHAR, PT.DATE_CREATED, 121) DATE_CREATED,
					  PT.created_by,
					 CONVERT(NVARCHAR, PT.date_modified, 121) date_modified ,
					  PT.modified_by
				 FROM 
				ETARGETDATA.dbo.CRM_PAY_TRANSACTIONS PT
				LEFT OUTER JOIN ETARGETDATA.dbo.CRM_PERSONS PERS ON PERS.UCN=PT.UCN
				LEFT OUTER JOIN ETARGETDATA.dbo.CRM_ORGANISATIONS ORG ON ORG.UCN=PT.UCN

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BATCH ON LOG_BATCH.ETARGET_SEQ_ID=PT.CRM_PAY_BATCH_HEADERS_SEQ_ID AND LOG_BATCH.STARGET_CLIENT_ENTITIES_SEQ_ID=2580-- ETARGET_TABLE_NAME='CRM_PAY_BATCH_HEADERS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BATCH ON SRM_BATCH.SEQ_ID=LOG_BATCH.STARGET_CUS_ENTITY_DATA_SEQ_ID

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=PERS.SEQ_ID AND LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID= 2524--  ETARGET_TABLE_NAME='CRM_PERSONS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_ACCOUNT ON LOG_ACCOUNT.ETARGET_SEQ_ID=ORG.SEQ_ID AND LOG_ACCOUNT.STARGET_CLIENT_ENTITIES_SEQ_ID= 2525--  ETARGET_TABLE_NAME='CRM_ORGANISATIONS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_ACCOUNT ON SRM_ACCOUNT.SEQ_ID=LOG_ACCOUNT.STARGET_CUS_ENTITY_DATA_SEQ_ID
					WHERE SRM_CONTACT.SEQ_ID=@SRM_CONTACT_SEQ_ID
	
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@BATCH_ID , @BATCH_ID_NAME , @PAYMENT_REFERENCE , @REMARKS , @TOTAL_PAYMENT_RCVD , @TRANSACTION_DATE , @TRANSACTION_ID , @CONTACT , @CONTACT_NAME , @ACCOUNT , @ACCOUNT_NAME,@TRAN_TYPE,@TRAN_TYPE_NAME,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  

		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_011,ATTRIBUTE_012,ATTRIBUTE_006,ATTRIBUTE_008,ATTRIBUTE_007,ATTRIBUTE_021,ATTRIBUTE_001,ATTRIBUTE_015,ATTRIBUTE_016,ATTRIBUTE_013,ATTRIBUTE_014 ,ATTRIBUTE_022,ATTRIBUTE_023 ,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id, @BATCH_ID , @BATCH_ID_NAME , @PAYMENT_REFERENCE , @REMARKS , @TOTAL_PAYMENT_RCVD , @TRANSACTION_DATE , @TRANSACTION_ID , @CONTACT , @CONTACT_NAME , @ACCOUNT , @ACCOUNT_NAME ,@TRAN_TYPE,@TRAN_TYPE_NAME ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
	
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_PAY_TRANSACTIONS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id, @BATCH_ID , @BATCH_ID_NAME , @PAYMENT_REFERENCE , @REMARKS , @TOTAL_PAYMENT_RCVD , @TRANSACTION_DATE , @TRANSACTION_ID , @CONTACT , @CONTACT_NAME , @ACCOUNT , @ACCOUNT_NAME ,@TRAN_TYPE,@TRAN_TYPE_NAME,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
	--###########################################################################################################################################

	--############################################ PAYMENT_TRANSACTION_DETAIL ###########################################################

	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @WEB  char

	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17


	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)

	--declare @MODULE nvarchar(200)
	--declare @MODULE_NAME nvarchar(200)
	declare @PAYMENT_TRANSACTION nvarchar(200)
	declare @PAYMENT_TRANSACTION_ID nvarchar(200)
	declare @EVENT nvarchar(200)
	--declare @EVENT_NAME nvarchar(200)
	declare @GAD_APPLICABLE nvarchar(200)
	--declare @GAD_GIVEN nvarchar(200)
	--declare @GAD_REFUSED nvarchar(200)
	--declare @RATE_TYPE nvarchar(200)
	--declare @RATE_TYPE_NAME nvarchar(200)
	declare @PAYMENT_RECEIVED nvarchar(200)
	--declare @REMARKS nvarchar(200)
	--declare @TAX_PAYER nvarchar(200)
	--declare @CONTACT nvarchar(200)
	--declare @CONTACT_NAME nvarchar(200)
	--declare @ACCOUNT nvarchar(200)
	--declare @ACCOUNT_NAME nvarchar(200)


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'PAYMENT_TRANSACTION_DETAIL'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR  
	

			SELECT 
			PD.SEQ_ID,
			SRM_MODULE.SEQ_ID AS MODULE,
			SRM_MODULE.ATTRIBUTE_001 AS MODULE_NAME,
			SRM_PAY_TRANS.SEQ_ID AS PAYMENT_TRANSACTION,
			SRM_PAY_TRANS.ATTRIBUTE_001 AS PAYMENT_TRANSACTION_ID,
			SRM_EVENT.SEQ_ID [EVENT],
			SRM_EVENT.ATTRIBUTE_001 EVENT_NAME,
			PD.GAD_APPLICABLE,
			PD.GAD_GIVEN,
			PD.GAD_REFUSED,
			SRM_RATE.SEQ_ID RATE_TYPE,
			SRM_RATE.ATTRIBUTE_001 RATE_TYPE_NAME,
			PAYMENT_RECEIVED,
			REMARKS,
			PD.TAX_PAYER,
			SRM_CONTACT.SEQ_ID AS CONTACT,
			SRM_CONTACT.ATTRIBUTE_001 AS CONTACT_NAME,
			SRM_ACCOUNT.SEQ_ID AS ACCOUNT,
			SRM_ACCOUNT.ATTRIBUTE_001 AS ACCOUNT_NAME,
			CONVERT(NVARCHAR, PD.DATE_CREATED, 121) DATE_CREATED,
					  PD.created_by,
					 CONVERT(NVARCHAR, PD.date_modified, 121) date_modified ,
					  PD.modified_by
			 FROM 
				ETARGETDATA.dbo.CRM_PAYMENT_DETAILS PD
				LEFT OUTER JOIN ETARGETDATA.dbo.CRM_PERSONS PERS ON PERS.UCN=PD.UCN
				LEFT OUTER JOIN ETARGETDATA.dbo.CRM_ORGANISATIONS ORG ON ORG.UCN=PD.UCN
				LEFT OUTER JOIN ETARGETDATA.dbo.MEM_RATE_TYPES MRT ON MRT.RATE_ID=PD.MEM_RATE_ID
			
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=PERS.SEQ_ID AND LOG_CONTACT.STARGET_CLIENT_ENTITIES_SEQ_ID=2524-- ETARGET_TABLE_NAME='CRM_PERSONS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_ACCOUNT ON LOG_ACCOUNT.ETARGET_SEQ_ID=ORG.SEQ_ID AND LOG_ACCOUNT.STARGET_CLIENT_ENTITIES_SEQ_ID=2524--ETARGET_TABLE_NAME='CRM_ORGANISATIONS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_ACCOUNT ON SRM_ACCOUNT.SEQ_ID=LOG_ACCOUNT.STARGET_CUS_ENTITY_DATA_SEQ_ID
			
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_MODULE ON LOG_MODULE.ETARGET_SEQ_ID=PD.CRM_MODULES_SEQ_ID AND LOG_MODULE.STARGET_CLIENT_ENTITIES_SEQ_ID=2584--.ETARGET_TABLE_NAME='CRM_MODULES'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_MODULE ON SRM_MODULE.SEQ_ID=LOG_MODULE.STARGET_CUS_ENTITY_DATA_SEQ_ID
		
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_PAY_TRANS ON LOG_PAY_TRANS.ETARGET_SEQ_ID=PD.CRM_PAY_TRANSACTIONS_SEQ_ID AND LOG_PAY_TRANS.STARGET_CLIENT_ENTITIES_SEQ_ID=2583--ETARGET_TABLE_NAME='CRM_PAY_TRANSACTIONS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_PAY_TRANS ON SRM_PAY_TRANS.SEQ_ID=LOG_PAY_TRANS.STARGET_CUS_ENTITY_DATA_SEQ_ID
			
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_EVENT ON LOG_EVENT.ETARGET_SEQ_ID=PD.EV_EVENTS_SEQ_ID AND LOG_EVENT.STARGET_CLIENT_ENTITIES_SEQ_ID=2556--.ETARGET_TABLE_NAME='EV_EVENTS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_EVENT ON SRM_EVENT.SEQ_ID=LOG_EVENT.STARGET_CUS_ENTITY_DATA_SEQ_ID
			
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_RATE ON LOG_RATE.ETARGET_SEQ_ID=MRT.SEQ_ID AND LOG_RATE.STARGET_CLIENT_ENTITIES_SEQ_ID=2546-- ETARGET_TABLE_NAME='MEM_RATE_TYPES'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_RATE ON SRM_RATE.SEQ_ID=LOG_RATE.STARGET_CUS_ENTITY_DATA_SEQ_ID
						WHERE SRM_CONTACT.SEQ_ID=@SRM_CONTACT_SEQ_ID	
	
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@MODULE , @MODULE_NAME , @PAYMENT_TRANSACTION , @PAYMENT_TRANSACTION_ID,  @EVENT , @EVENT_NAME , @GAD_APPLICABLE , @GAD_GIVEN , @GAD_REFUSED , @RATE_TYPE , @RATE_TYPE_NAME , @PAYMENT_RECEIVED , @REMARKS , @TAX_PAYER , @CONTACT , @CONTACT_NAME , @ACCOUNT , @ACCOUNT_NAME ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,  ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_025,ATTRIBUTE_026,ATTRIBUTE_028,ATTRIBUTE_030,ATTRIBUTE_029,ATTRIBUTE_011,ATTRIBUTE_012,ATTRIBUTE_010,ATTRIBUTE_024,ATTRIBUTE_027,ATTRIBUTE_040,ATTRIBUTE_041,ATTRIBUTE_038,ATTRIBUTE_039  ,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY)	
			values(@srm_client_entities_seq_id, @MODULE , @MODULE_NAME , @PAYMENT_TRANSACTION , @PAYMENT_TRANSACTION_ID,  @EVENT , @EVENT_NAME , @GAD_APPLICABLE , @GAD_GIVEN , @GAD_REFUSED , @RATE_TYPE , @RATE_TYPE_NAME , @PAYMENT_RECEIVED , @REMARKS , @TAX_PAYER , @CONTACT , @CONTACT_NAME , @ACCOUNT , @ACCOUNT_NAME   ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
	
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_PAYMENT_DETAILS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id, @MODULE , @MODULE_NAME , @PAYMENT_TRANSACTION , @PAYMENT_TRANSACTION_ID,  @EVENT , @EVENT_NAME , @GAD_APPLICABLE , @GAD_GIVEN , @GAD_REFUSED , @RATE_TYPE , @RATE_TYPE_NAME , @PAYMENT_RECEIVED , @REMARKS , @TAX_PAYER , @CONTACT , @CONTACT_NAME , @ACCOUNT , @ACCOUNT_NAME ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
	--###########################################################################################################################################

	--############################################ FINANCE_TRANSACTION (credit notes )###########################################################

	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @WEB  char

	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	--declare @INVOICE_DATE nvarchar(200)
	--declare @INVOICE_NO nvarchar(200)
	--declare @DEL_COUNTY nvarchar(200)
	--declare @DEL_COUNTY_name nvarchar(200)
	--declare @BIL_COUNTY nvarchar(200)
	--declare @BIL_COUNTY_NAME nvarchar(200)
	--declare @DEL_COUNTRY nvarchar(200)
	--declare @DEL_COUNTRY_NAME nvarchar(200)
	--declare @BIL_COUNTRY nvarchar(200)
	--declare @BIL_COUNTRY_NAME nvarchar(200)
	--declare @DELIVERY_ADD_LINE_1 nvarchar(200)
	--declare @DELIVERY_ADD_LINE_2 nvarchar(200)
	--declare @DELIVERY_ADD_LINE_3 nvarchar(200)
	--declare @DELIVERY_JOB_TITLE nvarchar(200)
	--declare @DELIVERY_NAME nvarchar(200)
	--declare @DELIVERY_ORG_NAME nvarchar(200)
	--declare @DELIVERY_POST_CODE  nvarchar(200)
	--declare @DELIVERY_TOWN nvarchar(200)
	--declare @INVOICE_ADD_LINE_1 nvarchar(200)
	--declare @INVOICE_ADD_LINE_2 nvarchar(200)
	--declare @INVOICE_ADD_LINE_3 nvarchar(200)
	--DECLARE @INVOICE_DEPARTMENT NVARCHAR(100)
	--declare @INVOICE_JOB_TITLE nvarchar(200)
	--declare @INVOICE_NAME  nvarchar(200)
	--declare @INVOICE_ORG_NAME  nvarchar(200)
	--declare @INVOICE_POST_CODE nvarchar(200)
	--declare @INVOICE_TOWN nvarchar(200)
	--declare @BATCH_ID nvarchar(200)
	--declare @BATCH_ID_NAME nvarchar(200)
	declare @PARENT_TRANSACTION nvarchar(200)
	declare @PARENT_TRANSACTION_NAME nvarchar(200)
	--declare @TOTAL_CREDIT nvarchar(200)
	--declare @ACCOUNT nvarchar(200)
	--declare @ACCOUNT_NAME nvarchar(200)
	--declare @CONTACT nvarchar(200)
	--declare @CONTACT_NAME nvarchar(200)
	--DECLARE @transaction_type NVARCHAR(100)
	--DECLARE @transaction_type_name NVARCHAR(100)

	-- DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)

	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'FINANCE_TRANSACTION'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR  
		SELECT 
			ICBD.SEQ_ID,
			 CONVERT(NVARCHAR, ICBD.CREDIT_NOTE_DATE, 121) CREDIT_NOTE_DATE,
			ICBD.CREDIT_NOTE_NO,
			SRM_DEL_COUNTY.SEQ_ID AS DEL_COUNTY,
			SRM_DEL_COUNTY.ATTRIBUTE_001 AS DEL_COUNTY_NAME,
			SRM_BIL_COUNTY.SEQ_ID AS BIL_COUNTY,
			SRM_BIL_COUNTY.ATTRIBUTE_001 AS BIL_COUNTY_NAME,
			SRM_DEL_COUNTRY.SEQ_ID AS DEL_COUNTRY,
			SRM_DEL_COUNTRY.ATTRIBUTE_001 AS DEL_COUNTRY_NAME,
			SRM_BIL_COUNTRY.SEQ_ID AS BIL_COUNTRY,
			SRM_BIL_COUNTRY.ATTRIBUTE_001 AS BIL_COUNTRY_NAME,
			ICBD.DELIVERY_ADD_LINE_1,
			ICBD.DELIVERY_ADD_LINE_2,
			ICBD.DELIVERY_ADD_LINE_3,
			ICBD.DELIVERY_JOB_TITLE,
			ICBD.DELIVERY_NAME,
			ICBD.DELIVERY_ORG_NAME,
			ICBD.DELIVERY_POST_CODE,
			ICBD.DELIVERY_TOWN,
			ICBD.INVOICE_ADD_LINE_1,
			ICBD.INVOICE_ADD_LINE_2,
			ICBD.INVOICE_ADD_LINE_3,
			ICBD.INVOICE_DEPARTMENT,
			ICBD.INVOICE_JOB_TITLE,
			ICBD.INVOICE_NAME,
			ICBD.INVOICE_ORG_NAME,
			ICBD.INVOICE_POST_CODE,
			ICBD.INVOICE_TOWN,
			SRM_BATCH.SEQ_ID AS BATCH_ID,
			SRM_BATCH.ATTRIBUTE_001 AS BATCH_ID_NAME,
			SRM_BATCH_DETAIL.SEQ_ID AS PARENT_TRANSACTION,
			SRM_BATCH_DETAIL.ATTRIBUTE_001 AS PARENT_TRANSACTION_NAME,
			ICBD.TOTAL_CREDIT,
			SRM_ACCOUNT.SEQ_ID AS ACCOUNT,
			SRM_ACCOUNT.ATTRIBUTE_001 AS ACCOUNT_NAME,
			SRM_CONTACT.SEQ_ID AS CONTACT,
			SRM_CONTACT.ATTRIBUTE_001 AS CONTACT_NAME,
			3085506 as TRANSACTION_TYPE,
			'Credit Note' as TRANSACTION_TYPE_NAME,
			 CONVERT(NVARCHAR, ICBD.DATE_CREATED, 121) DATE_CREATED,
			 ICBD.created_by,
			 CONVERT(NVARCHAR, ICBD.date_modified, 121) date_modified ,
			 ICBD.modified_by 



			FROM
			ETARGETDATA.dbo.ISC_CRD_BATCH_DETAILS ICBD
			INNER JOIN ETARGETDATA.dbo.ISC_INV_BATCH_DETAILS IIBD ON IIBD.SEQ_ID =ICBD.ISC_INV_BATCH_DETAILS_SEQ_ID
			INNER JOIN ETARGETDATA.dbo.ISC_CUSTOMERS IC ON IC.SEQ_ID =IIBD.ISC_CUSTOMERS_SEQ_ID
		
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_ACCOUNT ON LOG_ACCOUNT.ETARGET_SEQ_ID=IC.CRM_ORGANISATIONS_SEQ_ID AND LOG_ACCOUNT.ETARGET_TABLE_NAME='CRM_ORGANISATIONS'
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_ACCOUNT ON SRM_ACCOUNT.SEQ_ID=LOG_ACCOUNT.STARGET_CUS_ENTITY_DATA_SEQ_ID

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=IC.CRM_PERSONS_SEQ_ID AND LOG_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS'
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_DEL_COUNTY ON LOG_DEL_COUNTY.ETARGET_SEQ_ID=ICBD.CRM_COUNTIES_SEQ_ID AND LOG_DEL_COUNTY.ETARGET_TABLE_NAME='CRM_COUNTIES'
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_DEL_COUNTY ON SRM_DEL_COUNTY.SEQ_ID=LOG_DEL_COUNTY.STARGET_CUS_ENTITY_DATA_SEQ_ID

