	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)


		DECLARE Cur_records CURSOR  LOCAL STATIC FOR  
			SELECT 
					ICBT.SEQ_ID,
					SRM_LEDGER_ACC.SEQ_ID AS LEDGER_ACCOUNT,
					SRM_LEDGER_ACC.ATTRIBUTE_001 AS LEDGER_ACCOUNT_NAME,
					SRM_VAT.SEQ_ID VAT_RATE,
