					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_PROD ON SRM_PROD.SEQ_ID=LOG_PROD.STARGET_CUS_ENTITY_DATA_SEQ_ID

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_BATCH_DETAILS ON LOG_BATCH_DETAILS.ETARGET_SEQ_ID=ICBT.ISC_CRD_BATCH_DETAILS_SEQ_ID AND LOG_BATCH_DETAILS.ETARGET_TABLE_NAME='ISC_CRD_BATCH_DETAILS'
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_BATCH_DETAILS ON SRM_BATCH_DETAILS.SEQ_ID=LOG_BATCH_DETAILS.STARGET_CUS_ENTITY_DATA_SEQ_ID
				
					WHERE SRM_BATCH_DETAILS.ATTRIBUTE_006=CAST(@SRM_CONTACT_SEQ_ID AS VARCHAR)
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id, @LEDGER_ACCOUNT , @LEDGER_ACCOUNT_NAME , @VAT_RATE , @VAT_RATE_NAME , @GROSS_AMOUNT , @FINANCE_TRANSACTION,  @FINANCE_TRANSACTION_NAME , @PRODUCT , @PRODUCT_NAME , @NET_AMOUNT , @QUANTITY,  @UNIT_PRICE , @VAT_AMOUNT , @VAT_RATE_PERC  ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

