			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('ISC_CRD_BATCH_TRANS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id, @LEDGER_ACCOUNT , @LEDGER_ACCOUNT_NAME , @VAT_RATE , @VAT_RATE_NAME , @GROSS_AMOUNT , @FINANCE_TRANSACTION,  @FINANCE_TRANSACTION_NAME , @PRODUCT , @PRODUCT_NAME , @NET_AMOUNT , @QUANTITY,  @UNIT_PRICE , @VAT_AMOUNT , @VAT_RATE_PERC ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy 

		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
