	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	declare @Inv_No nvarchar(200)
	--declare @CONTACT nvarchar(200)
	--declare @CONTACT_NAME nvarchar(200)
	--declare @ACCOUNT nvarchar(200)
	--declare @ACCOUNT_NAME nvarchar(200)
	--declare @BATCH_ID nvarchar(200)
	--declare @BATCH_ID_NAME nvarchar(200)
	declare @REFUND_DATE nvarchar(200)
	declare @REFUND_NO nvarchar(200)
	--declare @REMARKS nvarchar(1000)
	--declare @TOTAL_REFUND nvarchar(200)
	--declare @TRAN_TYPE nvarchar(200)
	--declare @TRAN_TYPE_NAME nvarchar(200)

	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'PAYMENT_BATCH_TRANSACTION'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR  
		SELECT 
			IRBD.SEQ_ID,
			INVOICE_NO,
			SRM_CONTACT.SEQ_ID CONTACT,
			SRM_CONTACT.ATTRIBUTE_001 CONTACT_NAME,
			SRM_ACCOUNT.SEQ_ID ACCOUNT,
			SRM_ACCOUNT.ATTRIBUTE_001 ACCOUNT_NAME,
			SRM_REF_BATCH.SEQ_ID AS BATCH_ID,
			SRM_REF_BATCH.ATTRIBUTE_001 AS BATCH_ID_NAME,
			CONVERT(NVARCHAR, IRBD.REFUND_DATE, 121) REFUND_DATE,
			REFUND_NO,
			IRBD.REMARKS,
			TOTAL_REFUND,
			3085509 AS TRAN_TYPE,
			'Refund' AS TRAN_TYPE_NAME,
			CONVERT(NVARCHAR, IRBD.DATE_CREATED, 121) DATE_CREATED,
		  IRBD.created_by,
		 CONVERT(NVARCHAR, IRBD.date_modified, 121) date_modified ,
		  IRBD.modified_by 


		FROM ETARGETDATA.dbo.ISC_REF_BATCH_DETAILS IRBD
			INNER JOIN ETARGETDATA.dbo.ISC_CUSTOMERS IC ON IC.SEQ_ID =IRBD.ISC_CUSTOMERS_SEQ_ID
		
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=IC.CRM_PERSONS_SEQ_ID AND LOG_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS'
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID
			
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_ACCOUNT ON LOG_ACCOUNT.ETARGET_SEQ_ID=IC.CRM_ORGANISATIONS_SEQ_ID AND LOG_ACCOUNT.ETARGET_TABLE_NAME='CRM_ORGANISATIONS'
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_ACCOUNT ON SRM_ACCOUNT.SEQ_ID=LOG_ACCOUNT.STARGET_CUS_ENTITY_DATA_SEQ_ID
		
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_REF_BATCH ON LOG_REF_BATCH.ETARGET_SEQ_ID=IRBD.ISC_REF_BATCH_HEADERS_SEQ_ID AND LOG_REF_BATCH.ETARGET_TABLE_NAME='ISC_REF_BATCH_HEADERS'
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_REF_BATCH ON SRM_REF_BATCH.SEQ_ID=LOG_REF_BATCH.STARGET_CUS_ENTITY_DATA_SEQ_ID
		
		WHERE SRM_CONTACT.SEQ_ID=@SRM_CONTACT_SEQ_ID
		
	
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,@Inv_No,  @CONTACT,  @CONTACT_NAME,  @ACCOUNT , @ACCOUNT_NAME , @BATCH_ID , @BATCH_ID_NAME,  @REFUND_DATE , @REFUND_NO , @REMARKS , @TOTAL_REFUND , @TRAN_TYPE , @TRAN_TYPE_NAME ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,   ATTRIBUTE_006,ATTRIBUTE_015,ATTRIBUTE_016,ATTRIBUTE_013,ATTRIBUTE_014,ATTRIBUTE_011,ATTRIBUTE_012,ATTRIBUTE_021,ATTRIBUTE_001,ATTRIBUTE_008,ATTRIBUTE_007,ATTRIBUTE_022,ATTRIBUTE_023 ,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY)	
			values(@srm_client_entities_seq_id, @Inv_No,  @CONTACT,  @CONTACT_NAME,  @ACCOUNT , @ACCOUNT_NAME , @BATCH_ID , @BATCH_ID_NAME,  @REFUND_DATE , @REFUND_NO , @REMARKS , @TOTAL_REFUND , @TRAN_TYPE , @TRAN_TYPE_NAME     ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
	
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('ISC_REF_BATCH_DETAILS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id,@Inv_No,  @CONTACT,  @CONTACT_NAME,  @ACCOUNT , @ACCOUNT_NAME , @BATCH_ID , @BATCH_ID_NAME,  @REFUND_DATE , @REFUND_NO , @REMARKS , @TOTAL_REFUND , @TRAN_TYPE , @TRAN_TYPE_NAME ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy  

		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
