	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @WEB  char

	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17


	--declare @EVENT nvarchar(200)
	--declare @EVENT_NAME nvarchar(200)
	--declare @RATE nvarchar(200)
	declare @RATE_NAME nvarchar(200)
	--declare @PAYMENT_TRANSACTION nvarchar(200)
	--declare @PAYMENT_TRANSACTION_NAME nvarchar(200)
	--declare @REFUND_AMOUNT nvarchar(200)


	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'PAYMENT_TRANSACTION_DETAIL'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR  
		SELECT 
			IRBD.SEQ_ID,
			SRM_EVENT.SEQ_ID AS [EVENT],
			SRM_EVENT.ATTRIBUTE_001 AS [EVENT_NAME],
			SRM_RATE_TYPE.SEQ_ID AS RATE_TYPE,
			SRM_RATE_TYPE.ATTRIBUTE_001 AS RATE_TYPE_NAME,
			SRM_REF_DET.SEQ_ID AS PAYMENT_TRANSACTION,
			SRM_REF_DET.ATTRIBUTE_001 AS PAYMENT_TRANSACTION_NAME,
			REFUND_AMOUNT,
			 CONVERT(NVARCHAR, IRBD.DATE_CREATED, 121) DATE_CREATED,
					  IRBD.created_by,
					 CONVERT(NVARCHAR, IRBD.date_modified, 121) date_modified ,
					  IRBD.modified_by 

			FROM ETARGETDATA.dbo.EV_REF_BATCH_TRANS IRBD

			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_EVENT ON LOG_EVENT.ETARGET_SEQ_ID=IRBD.EV_EVENTS_SEQ_ID AND LOG_EVENT.ETARGET_TABLE_NAME='EV_EVENTS'
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_EVENT ON SRM_EVENT.SEQ_ID=LOG_EVENT.STARGET_CUS_ENTITY_DATA_SEQ_ID
		
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_REF_BATCH_DET ON LOG_REF_BATCH_DET.ETARGET_SEQ_ID=IRBD.ISC_REF_BATCH_DETAILS_SEQ_ID AND LOG_REF_BATCH_DET.ETARGET_TABLE_NAME='ISC_REF_BATCH_DETAILS'
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_REF_DET ON SRM_REF_DET.SEQ_ID=LOG_REF_BATCH_DET.STARGET_CUS_ENTITY_DATA_SEQ_ID
	
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_RATE_TYPE ON LOG_RATE_TYPE.ETARGET_SEQ_ID=IRBD.EV_RATE_TYPES_SEQ_ID AND LOG_RATE_TYPE.ETARGET_TABLE_NAME='EV_RATE_TYPES'
			LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_RATE_TYPE ON SRM_RATE_TYPE.SEQ_ID=LOG_RATE_TYPE.STARGET_CUS_ENTITY_DATA_SEQ_ID
	
			WHERE SRM_REF_DET.ATTRIBUTE_015=CAST(@SRM_CONTACT_SEQ_ID AS VARCHAR)
	
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,  @EVENT , @EVENT_NAME , @RATE , @RATE_NAME , @PAYMENT_TRANSACTION , @PAYMENT_TRANSACTION_NAME , @REFUND_AMOUNT,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

		WHILE @@FETCH_STATUS = 0
		BEGIN
			INSERT INTO [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID,   ATTRIBUTE_025,ATTRIBUTE_026,ATTRIBUTE_011,ATTRIBUTE_012,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_010 ,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DATE_MODIFIED,MODIFIED_BY )	
			values(@srm_client_entities_seq_id,   @EVENT , @EVENT_NAME , @RATE , @RATE_NAME , @PAYMENT_TRANSACTION , @PAYMENT_TRANSACTION_NAME , @REFUND_AMOUNT      ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
	
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('EV_REF_BATCH_TRANS',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id, @EVENT , @EVENT_NAME , @RATE , @RATE_NAME , @PAYMENT_TRANSACTION , @PAYMENT_TRANSACTION_NAME , @REFUND_AMOUNT   ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

		END

		CLOSE Cur_records
		DEALLOCATE Cur_records
