	--###########################################################################################################################################
	--############################################ SALES_LEDGER (CASH BOOKS)  ###########################################################
	--################## PAYMENTS AGAINST ACCOUNT/CONTACTC--credit
	--declare @client_seq_id bigint
	--declare @createdBy nvarchar(100)
	--declare @dateCreated datetime
	--declare @srm_client_entities_seq_id bigint
	--declare @new_seq_id bigint
	--DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	--declare @seq_id bigint
	--declare @description nvarchar(500)
	--declare @active  char
	--declare @WEB  char

	set @createdBy='CCSConv'
	set @dateCreated=GETDATE()
	set @client_seq_id=17

	--DECLARE @DateModified  nvarchar(200)
	--DECLARE @ModifiedBy nvarchar(200)


	--declare @ACCOUNT nvarchar(200)
	--declare @ACCOUNT_NAME nvarchar(200)
	declare @PAYMENT_TRANSACTION_DETAIL nvarchar(200)
	declare @PAYMENT_TRANSACTION_DETAIL_NAME nvarchar(200)
	--declare @CONTACT nvarchar(200)
	--declare @CONTACT_NAME nvarchar(200)
	--declare @EVENT nvarchar(200)
	--declare @EVENT_NAME nvarchar(200)
	--declare @GAD_APPLICABLE nvarchar(200)
	--declare @GAD_GIVEN nvarchar(200)
	--declare @GAD_REFUSED nvarchar(200)
	declare @GIFT_AID_AMOUNT nvarchar(200)
	declare @INVOICE_NUMBER nvarchar(200)
	--declare @LEDGER_ACCOUNT nvarchar(200)
	--declare @LEDGER_ACCOUNT_NAME nvarchar(200)
	--declare @REMARKS nvarchar(200)
	--declare @TRANSACTION_DATE nvarchar(200)
	--declare @TRANSACTION_TYPE nvarchar(200)
	--declare @TRANSACTION_TYPE_NAME nvarchar(200)
	declare @PAYMENT_RECEIVED_NET nvarchar(200)


	SELECT @srm_client_entities_seq_id= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ENTITIES A, [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES B,[SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES C, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @client_seq_id AND C.ENTITY_DISPLAY_NAME like 'SALES_LEDGER'



		DECLARE Cur_records CURSOR  LOCAL STATIC FOR  
			SELECT
				CB.SEQ_ID,
				SRM_ACCOUNT.SEQ_ID AS ACCOUNT,
				SRM_ACCOUNT.ATTRIBUTE_001 AS ACCOUNT_NAME,
				SRM_TRAN_DETAILS.SEQ_ID AS PAYMENT_TRANSACTION_DETAIL,
				SRM_TRAN_DETAILS.ATTRIBUTE_001 AS PAYMENT_TRANSACTION_DETAIL_NAME,
				SRM_CONTACT.SEQ_ID AS CONTACT ,
				SRM_CONTACT.ATTRIBUTE_001 AS CONTACT_NAME ,
				SRM_EVENT.SEQ_ID AS [EVENT],
				SRM_EVENT.ATTRIBUTE_001 AS [EVENT_NAME],
				GAD_APPLICABLE,
				GAD_GIVEN,
				GAD_REFUSED,
				GIFT_AID_AMOUNT,
				SRM_TRAN_DETAILS.ATTRIBUTE_006 INVOICE_NUMBER,
				SRM_LEDGER_ACCOUNT.SEQ_ID AS LEDGER_ACCOUNT,
				SRM_LEDGER_ACCOUNT.ATTRIBUTE_001 AS LEDGER_ACCOUNT_NAME,
				REMARKS,
				CONVERT(NVARCHAR, CB.TRANSACTION_DATE, 121) TRANSACTION_DATE,
				CASE WHEN PAYMENT_RECEIVED_NET <0 THEN 3085509 ELSE  3085508 END TRANSACTION_TYPE,
				CASE WHEN PAYMENT_RECEIVED_NET <0 THEN 'Refund' ELSE  'Payment' END TRANSACTION_TYPE_NAME,
				ISNULL(PAYMENT_RECEIVED_NET,0)+ISNULL(PAYMENT_RECEIVED_VAT,0) AMOUNT,
				 CONVERT(NVARCHAR, CB.DATE_CREATED, 121) DATE_CREATED,
				  CB.created_by,
				 CONVERT(NVARCHAR, CB.date_modified, 121) date_modified ,
				  CB.modified_by 
				FROM 
				ETARGETDATA.dbo.CRM_CASH_BOOKS CB

				LEFT OUTER JOIN ETARGETDATA.dbo.CRM_LEDGER_ACCOUNTS LA ON LA.LEDGER_ACCOUNT_ID=CB.LEDGER_ACCOUNT_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_LEDGER_ACCOUNT ON LOG_LEDGER_ACCOUNT.ETARGET_SEQ_ID=LA.SEQ_ID AND LOG_LEDGER_ACCOUNT.ETARGET_TABLE_NAME='CRM_LEDGER_ACCOUNTS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_LEDGER_ACCOUNT ON SRM_LEDGER_ACCOUNT.SEQ_ID=LOG_LEDGER_ACCOUNT.STARGET_CUS_ENTITY_DATA_SEQ_ID

				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_ACCOUNT ON LOG_ACCOUNT.ETARGET_SEQ_ID=CB.CRM_ORGANISATIONS_SEQ_ID AND LOG_ACCOUNT.ETARGET_TABLE_NAME='CRM_ORGANISATIONS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_ACCOUNT ON SRM_ACCOUNT.SEQ_ID=LOG_ACCOUNT.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=CB.CRM_PERSONS_SEQ_ID AND LOG_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_TRAN_DETAILS ON LOG_TRAN_DETAILS.ETARGET_SEQ_ID=CB.CRM_PAYMENT_DETAILS_SEQ_ID AND LOG_TRAN_DETAILS.ETARGET_TABLE_NAME='CRM_PAYMENT_DETAILS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_TRAN_DETAILS ON SRM_TRAN_DETAILS.SEQ_ID=LOG_TRAN_DETAILS.STARGET_CUS_ENTITY_DATA_SEQ_ID
