				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_CONTACT ON LOG_CONTACT.ETARGET_SEQ_ID=CB.CRM_PERSONS_SEQ_ID AND LOG_CONTACT.ETARGET_TABLE_NAME='CRM_PERSONS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_CONTACT ON SRM_CONTACT.SEQ_ID=LOG_CONTACT.STARGET_CUS_ENTITY_DATA_SEQ_ID
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_TRAN_DETAILS ON LOG_TRAN_DETAILS.ETARGET_SEQ_ID=CB.CRM_PAYMENT_DETAILS_SEQ_ID AND LOG_TRAN_DETAILS.ETARGET_TABLE_NAME='CRM_PAYMENT_DETAILS'
