				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG LOG_EVENT ON LOG_EVENT.ETARGET_SEQ_ID=CB.CRM_PAYMENT_DETAILS_SEQ_ID AND LOG_EVENT.ETARGET_TABLE_NAME='CRM_PAYMENT_DETAILS'
				LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SRM_EVENT ON SRM_EVENT.SEQ_ID=LOG_EVENT.STARGET_CUS_ENTITY_DATA_SEQ_ID
			WHERE PAYMENT_RECEIVED_NET<0 AND  SRM_CONTACT.SEQ_ID =@SRM_CONTACT_SEQ_ID
	
		OPEN Cur_records
		FETCH NEXT FROM Cur_records INTO @seq_id,  @ACCOUNT , @ACCOUNT_NAME , @PAYMENT_TRANSACTION_DETAIL , @PAYMENT_TRANSACTION_DETAIL_NAME , @CONTACT , @CONTACT_NAME , @EVENT ,@EVENT_NAME , @GAD_APPLICABLE , @GAD_GIVEN , @GAD_REFUSED , @GIFT_AID_AMOUNT , @INVOICE_NUMBER , @LEDGER_ACCOUNT , @LEDGER_ACCOUNT_NAME , @REMARKS , @TRANSACTION_DATE , @TRANSACTION_TYPE,  @TRANSACTION_TYPE_NAME , @PAYMENT_RECEIVED_NET ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

