			values(@srm_client_entities_seq_id,@ACCOUNT , @ACCOUNT_NAME , @PAYMENT_TRANSACTION_DETAIL , @PAYMENT_TRANSACTION_DETAIL_NAME , @CONTACT , @CONTACT_NAME , @EVENT ,@EVENT_NAME , @GAD_APPLICABLE , @GAD_GIVEN , @GAD_REFUSED , @GIFT_AID_AMOUNT , @INVOICE_NUMBER , @LEDGER_ACCOUNT , @LEDGER_ACCOUNT_NAME , @REMARKS , @TRANSACTION_DATE , @TRANSACTION_TYPE,  @TRANSACTION_TYPE_NAME , @PAYMENT_RECEIVED_NET  ,@client_seq_id,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy)
		
			SELECT @new_seq_id = SCOPE_IDENTITY()
			--POPULATING PIVOT 
			EXEC [SRM-Framework_New].DBO.GET_POPULATE_PIVOT_TABLE @srm_client_entities_seq_id,@new_seq_id, @client_seq_id,0,''
	
			--insert into log table 
			insert into [SRM-CUSTOMENTITIES].DBO.SRM_DATA_CONVERSION_LOG(ETARGET_TABLE_NAME,ETARGET_SEQ_ID,STARGET_ENTITY_NAME,STARGET_CLIENT_ENTITIES_SEQ_ID,STARGET_CUS_ENTITY_DATA_SEQ_ID,DATE_CREATED,CREATED_BY)
			values('CRM_CASH_BOOKS_REFUND_BANK_LEDGER',@seq_id,@SRM_ENTITY_NAME,@srm_client_entities_seq_id,@new_seq_id,@dateCreated,@createdBy)

		FETCH NEXT FROM Cur_records INTO @seq_id, @ACCOUNT , @ACCOUNT_NAME , @PAYMENT_TRANSACTION_DETAIL , @PAYMENT_TRANSACTION_DETAIL_NAME , @CONTACT , @CONTACT_NAME , @EVENT ,@EVENT_NAME , @GAD_APPLICABLE , @GAD_GIVEN , @GAD_REFUSED , @GIFT_AID_AMOUNT , @INVOICE_NUMBER , @LEDGER_ACCOUNT , @LEDGER_ACCOUNT_NAME , @REMARKS , @TRANSACTION_DATE , @TRANSACTION_TYPE,  @TRANSACTION_TYPE_NAME , @PAYMENT_RECEIVED_NET ,@DateCreated, @CreatedBy , @DateModified , @ModifiedBy

