CREATE PROCEDURE [dbo].[GET_CONVERT_PICKLIST_TO_CUSTOM_ENTITY]
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,	
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR_NO INT OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(250) OUTPUT
AS 
	DECLARE @PICK_LIST NVARCHAR(1)

	SELECT @PICK_LIST = PICK_LIST  FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

	PRINT 'SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS NVARCHAR)
	--RETURN

	IF ISNULL(@SRM_CLIENT_ENTITIES_SEQ_ID, 0) = 0 OR @PICK_LIST = 'N'
	BEGIN
		SET @ERROR_NO = -1
		SET @ERROR_DESCRIPTION = 'ENTITY DOES NOT EXIST OR NOT A PICKLIST.'
		RETURN
	END

	UPDATE SRM_CLIENT_ENTITIES SET PICK_LIST = 'N' WHERE SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

	UPDATE SRM_CLIENT_ENTITY_ATTRIBUTES SET SYSTEM_ATTRIBUTE = 'N' 
	WHERE 
	SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
	AND ATTRIBUTE_DISPLAY_NAME NOT IN
	('RECORD_ID',
	'DESCRIPTION',
	'CLIENT_ID',
	'SOURCE_OF_DATA',
	'SOURCE_FILE',
	'DATE_MODIFIED',
	'MODIFIED_BY',
	'DATE_CREATED',
	'CREATED_BY',
	'DELETED',
	'DATE_DELETED',
	'DELETED_BY')

	UPDATE SRM_CLIENT_ENTITY_ATTRIBUTES 
	SET SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = 19
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID2 = @SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = 11

	UPDATE SRM_CLIENT_ENTITY_ATTRIBUTES SET DISPLAY_ATTRIBUTE = 'N' WHERE ATTRIBUTE_DISPLAY_NAME = 'RECORD_ID' AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

	update SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS set DISPLAY_ONLY = 'N', DISPLAY_ONLY_ON_EDIT = 'N'   where DISPLAY_ONLY = 'Y' and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID in (select seq_id from SRM_CLIENT_ENTITY_ATTRIBUTES where SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID and ATTRIBUTE_DISPLAY_NAME = 'description')
	update SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS set DISPLAY_ONLY = 'N', DISPLAY_ONLY_ON_EDIT = 'N'   where DISPLAY_ONLY = 'Y' and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID in (select seq_id from SRM_CLIENT_ENTITY_ATTRIBUTES where SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID and ATTRIBUTE_DISPLAY_NAME = 'active')
	update SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS set DISPLAY_ONLY = 'N', DISPLAY_ONLY_ON_EDIT = 'N'   where DISPLAY_ONLY = 'Y' and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID in (select seq_id from SRM_CLIENT_ENTITY_ATTRIBUTES where SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID and ATTRIBUTE_DISPLAY_NAME = 'available_on_portal')

	SET @ERROR_NO = 0
	SET @ERROR_DESCRIPTION = 'Picklist successfully converted to entity.'

	




;






