-- Create date: <19/11/2013>
-- Description:	<Account Contact Bank>
-- =============================================
CREATE PROCEDURE [dbo].[GET_CREATE_ACCOUNT_CONTACT_BANK]
	-- Add the parameters for the stored procedure here
	@ACCOUNT BIGINT = NULL,
	@ACCOUNT_NAME NVARCHAR(100) = NULL,
	@CONTACT BIGINT = NULL,
	@CONTACT_NAME NVARCHAR(100) = NULL,
	@BRANCH_SORT_CODE NVARCHAR(50) = NULL,
	@BANK_BUILDING_SOCIETY_ACCOUNT_NUMBER NVARCHAR(50) = NULL,
	@NAME_OF_ACCOUNT_HOLDER NVARCHAR(100) = NULL,
	@I_AM_ACCOUNT_HOLDER NVARCHAR(10) = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@BANK BIGINT = NULL OUTPUT,
	@BANK_NAME NVARCHAR(200) = NULL OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[GET_CREATE_ACCOUNT_CONTACT_BANK]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_ACCOUNT_CONTACT_BANK]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @ENTITY_DISPLAY_NAME_ACCOUNT_CONTACT_BANK NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT_CONTACT_BANK BIGINT
	SET @ENTITY_DISPLAY_NAME_ACCOUNT_CONTACT_BANK = 'ACCOUNT_CONTACT_BANK'

	DECLARE @ENTITY_DISPLAY_NAME_BANK NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_BANK BIGINT
	SET @ENTITY_DISPLAY_NAME_BANK = 'BANK'


	DECLARE @TODATE DateTime
	SELECT @TODATE = GETDATE()

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT_CONTACT_BANK = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_ACCOUNT_CONTACT_BANK
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_BANK = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_BANK
	
	SELECT @BANK = SEQ_ID, @BANK_NAME = ATTRIBUTE_002 
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_BANK 
	--AND ATTRIBUTE_001 = @BRANCH_SORT_CODE
	AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_BANK AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52768 AND ISNULL(ATTRIBUTE_STRING,'')=@BRANCH_SORT_CODE)

	EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]	
		@ATTRIBUTE_001 = @BRANCH_SORT_CODE, --SORT_CODE
		@ATTRIBUTE_002 = @BANK_BUILDING_SOCIETY_ACCOUNT_NUMBER,
		@ATTRIBUTE_003 = @BANK,
		@ATTRIBUTE_004 = @BANK_NAME,
		@ATTRIBUTE_005 = @CONTACT,
		@ATTRIBUTE_006 = @CONTACT_NAME,
		@ATTRIBUTE_007 = @ACCOUNT,
		@ATTRIBUTE_008 = @ACCOUNT_NAME,
		@ATTRIBUTE_009 = @NAME_OF_ACCOUNT_HOLDER, -- @ACCOUNT_TITLE
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT_CONTACT_BANK,
		@DATE_CREATED = @TODATE,
		@CREATED_BY = @USER,
		@RETURN_SEQ_ID = @BANK OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

	SET @BANK_NAME = @BANK_BUILDING_SOCIETY_ACCOUNT_NUMBER

END







;






