		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT, @ATTRIBUTE_DISPLAY_NAME = 'RECORD_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @ORGANISATION_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @ACCOUNT OUTPUT, @DESCRIPTION = @ORGANISATION_NAME OUTPUT
		
		SET @REMARKS = @ORGANISATION_NAME + ' - ' + @CONTACT_NAME
	END
	ELSE IF ISNULL(@ORGANISATION_NAME, '') <> ''
