			@FAX = @ORGANISATION_FAX,
			@WEBSITE = NULL,
			@MAIN_CONTACT = @CONTACT,
			@MAIN_CONTACT_NAME = @CONTACT_NAME,
			@PREFERRED_MAILING_ADDRESS  = NULL,
			@PREFERRED_MAILING_ADDRESS_NAME = '0',
			@PREFERRED_BILLING_ADDRESS = NULL,
			@PREFERRED_BILLING_ADDRESS_NAME = '0',
			@USER = @USER,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ACCOUNT = @ACCOUNT OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		SET @REMARKS = @ORGANISATION_NAME + ' - ' + @CONTACT_NAME
	END
	
	IF ISNULL(@ACCOUNT, '0') <> '0'
	BEGIN
		EXEC [dbo].[GET_CREATE_ACCOUNT_CONTACT_RELATIONSHIP]
			@ACCOUNT = @ACCOUNT,
			@ACCOUNT_NAME = @ORGANISATION_NAME,
			@CONTACT = @CONTACT,
			@CONTACT_NAME = @CONTACT_NAME,
			@JOB_FUNCTION = NULL,
			@JOB_FUNCTION_DESCRIPTION = NULL,
			@EFFECTIVE_DATE = NULL,
			@CEASED_DATE = NULL,
			@JOB_TITLE = @JOB_TITLE,
			@MAIN_CONTACT = 'Y',
			@MAIN_ACCOUNT = 'Y', 
			@CEASED = 'N',
			@REMARKS = @REMARKS,
			@USER = @USER,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID = @ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

	END

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
	
END







;





  
