 EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM, @ATTRIBUTE_DISPLAY_NAME = 'SALE_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @EXTERNAL_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @WEB_SERVICE_PRODUCT_SALE_MASTER OUTPUT, @DESCRIPTION = @WEB_SERVICE_PRODUCT_SALE_MASTER_DESCRIPTION OUTPUT  
  
