   @MAILING_ADDRESS_LINE_1 = @MAILING_ADDRESS_LINE_1,  
   @MAILING_ADDRESS_LINE_2 = @MAILING_ADDRESS_LINE_2,  
   @MAILING_ADDRESS_LINE_3 = @MAILING_ADDRESS_LINE_3,  
   @MAILING_ADDRESS_LINE_4 = @MAILING_ADDRESS_LINE_4,  
