   @BILLING_ADDRESS_LINE_3 = @BILLING_ADDRESS_LINE_3,  
   @BILLING_ADDRESS_LINE_4 = @BILLING_ADDRESS_LINE_4,  
   @BILLING_ADDRESS_TOWN = @BILLING_ADDRESS_TOWN,  
   @BILLING_ADDRESS_COUNTY_DESCRIPTION = @BILLING_ADDRESS_COUNTY,  
   @BILLING_ADDRESS_COUNTRY_DESCRIPTION = @BILLING_ADDRESS_COUNTRY,  
   @BILLING_ADDRESS_POSTCODE = @BILLING_ADDRESS_POSTCODE,  
   -- Mailing & Billing Address Details - End  
   @USER = @USER,  
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
   @ACCOUNT = @ACCOUNT OUTPUT,  
   @ERROR = @ERROR OUTPUT,  
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
  
  SET @REMARKS = @ORGANISATION_NAME + ' - ' + @CONTACT_NAME  
  
  EXEC [dbo].[GET_CREATE_ACCOUNT_CONTACT_RELATIONSHIP]  
   @ACCOUNT = @ACCOUNT,  
   @ACCOUNT_NAME = @ORGANISATION_NAME,  
   @CONTACT = @CONTACT,  
   @CONTACT_NAME = @CONTACT_NAME,  
   @JOB_FUNCTION = NULL,  
   @JOB_FUNCTION_DESCRIPTION = NULL,  
   @EFFECTIVE_DATE = NULL,  
   @CEASED_DATE = NULL,  
   @JOB_TITLE = @JOB_TITLE,  
   @MAIN_CONTACT = 'Y',  
   @MAIN_ACCOUNT = 'Y',   
   @CEASED = 'N',  
   @REMARKS = @REMARKS,  
   @USER = @USER,  
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
   @ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID = @ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID OUTPUT,  
   @ERROR = @ERROR OUTPUT,  
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
  
 END  
  
 SET @ERROR = 0  
 SET @ERROR_DESCRIPTION = ''  
   
END  
  
  
  



