-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_CREATE_ACCOUNT_CONTACT_RELATIONSHIP]
	-- Add the parameters for the stored procedure here
	@ACCOUNT NVARCHAR(100) = NULL,
	@ACCOUNT_NAME NVARCHAR(100) = NULL,
	@CONTACT NVARCHAR(100) = NULL,
	@CONTACT_NAME NVARCHAR(100) = NULL,
	@JOB_FUNCTION NVARCHAR(100) = NULL,
	@JOB_FUNCTION_DESCRIPTION NVARCHAR(100) = NULL,
	@EFFECTIVE_DATE NVARCHAR(100) = NULL,
	@CEASED_DATE NVARCHAR(100) = 'N',
	@JOB_TITLE NVARCHAR(100) = NULL,
	@MAIN_CONTACT NVARCHAR(100) = NULL,
	@MAIN_ACCOUNT NVARCHAR(100) = NULL,
	@CEASED NVARCHAR(100) = NULL,
	@REMARKS NVARCHAR(100) = NULL,

	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID BIGINT OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[GET_CREATE_ACCOUNT_CONTACT_RELATIONSHIP]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_ACCOUNT_CONTACT_RELATIONSHIP]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	IF ISNULL(@ACCOUNT, 0) = 0 OR ISNULL(@CONTACT, 0) = 0
	BEGIN
		PRINT 'CAN NOT CREATE CONTACT ACCOUNT RELATIONSHIP'
		SET @ERROR = 0
		SET @ERROR_DESCRIPTION = ''
		RETURN
	END

	DECLARE @ENTITY_DISPLAY_NAME_ACR NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_ACR BIGINT
	SET @ENTITY_DISPLAY_NAME_ACR = 'ACCOUNT_CONTACT_RELATIONSHIP'
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_ACR = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_ACR

	DECLARE @ENTITY_DISPLAY_NAME_CONTACT NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT BIGINT
	SET @ENTITY_DISPLAY_NAME_CONTACT = 'CONTACT'
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_CONTACT 


	PRINT 'DATE....'
	PRINT @TODAY

	IF @EFFECTIVE_DATE IS NULL
		SET @EFFECTIVE_DATE = @TODAY

	IF ISNULL(@JOB_FUNCTION_DESCRIPTION, '') <> '' -- GET JOB_FUNCTION
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'JOB_FUNCTION', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @JOB_FUNCTION_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @JOB_FUNCTION OUTPUT, @DESCRIPTION = @JOB_FUNCTION_DESCRIPTION OUTPUT
	PRINT 'BEFORE INSERTING DATA FOR ACCOUNT_CONTACT_RELATIONSHIP ...'

	SET @ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID = NULL
	SELECT @ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID = SEQ_ID 
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACR 
	--AND ATTRIBUTE_002 = CAST(@ACCOUNT AS NVARCHAR(20)) 
	AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACR AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 53457 AND ISNULL(ATTRIBUTE_DECIMAL,0) = ISNULL(@ACCOUNT,0))
	--AND ATTRIBUTE_004 = CAST(@CONTACT AS NVARCHAR(20))
	AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACR AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 53459 AND ISNULL(ATTRIBUTE_DECIMAL,0) = ISNULL(@CONTACT,0))
	
	IF ISNULL(@ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID, 0) > 0
	BEGIN
		UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
		SET 
			ATTRIBUTE_006 = @JOB_FUNCTION,
			ATTRIBUTE_007 = @JOB_FUNCTION_DESCRIPTION,
			ATTRIBUTE_010 = @JOB_TITLE,
			ATTRIBUTE_012 = @MAIN_ACCOUNT,
			ATTRIBUTE_013 = @CEASED,
			DATE_MODIFIED = @TODAY,
			MODIFIED_BY = @USER
		WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACR AND SEQ_ID = @ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID

		EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACR,
			@CUS_ENTITY_DATA_SEQ_ID = @ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END
	ELSE
	BEGIN
		EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
			@ATTRIBUTE_001 = @REMARKS,
			@ATTRIBUTE_002 = @ACCOUNT,
			@ATTRIBUTE_003 = @ACCOUNT_NAME,
			@ATTRIBUTE_004 = @CONTACT,
			@ATTRIBUTE_005 = @CONTACT_NAME,
			@ATTRIBUTE_006 = @JOB_FUNCTION,
			@ATTRIBUTE_007 = @JOB_FUNCTION_DESCRIPTION,
			@ATTRIBUTE_008 = @EFFECTIVE_DATE,
			@ATTRIBUTE_009 = @CEASED_DATE,
			@ATTRIBUTE_010 = @JOB_TITLE,
			@ATTRIBUTE_011 = @MAIN_CONTACT,
			@ATTRIBUTE_012 = @MAIN_ACCOUNT,
			@ATTRIBUTE_013 = @CEASED,

			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACR,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@CREATED_BY = @USER,
			@RETURN_SEQ_ID = @ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END

	UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	SET ATTRIBUTE_058 = @ACCOUNT,		-- MAIN_ACCOUNT
		ATTRIBUTE_059 = @ACCOUNT_NAME,	-- MAIN_ACCOUNT_NAME
		DATE_MODIFIED = @TODAY,
		MODIFIED_BY = @USER
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT AND SEQ_ID = @CONTACT

	EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT,
		@CUS_ENTITY_DATA_SEQ_ID = @CONTACT,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
END



;





CREATE PROCEDURE [dbo].[GET_CREATE_API_FAILED_TRANSACTIONS_DnT]        
        
As        
      
      
Declare @WEB_SERVICE_EVENT_BOOKING_MASTER_Entity_SEQ_ID bigint        
Declare @WEB_SERVICE_PRODUCT_SALE_MASTER_Entity_SEQ_ID bigint        
Declare @WEB_SERVICE_MEMBERSHIP_Entity_SEQ_ID bigint    

Declare @LapsedDays Datetime
set @LapsedDays = dateadd(day, -10, getdate())

--select @LapsedDays

        
SET @WEB_SERVICE_EVENT_BOOKING_MASTER_Entity_SEQ_ID=2742        
SET @WEB_SERVICE_PRODUCT_SALE_MASTER_Entity_SEQ_ID=2725        
SET @WEB_SERVICE_MEMBERSHIP_Entity_SEQ_ID=2696        
        
DELETE FROM [SRM-ErrorHandler].dbo.SRM_API_DATA_IMPORT_EXCEPTIONS WHERE [CLIENT_ID] = 17      
      
--return      
      
;WITH TEMPREC (SOURCE,TRANSFERRED_TO_OOMI,SEQ_ID,DATE_CREATED,WHO)        
AS        
(        
        
select  'WEB_SERVICE_EVENT_BOOKING_MASTER' as SOURCE,ISNULL(ATTRIBUTE_066,'N') as TRANSFERRED_TO_OOMI,SEQ_ID,DATE_CREATED,'Booking ID : ' + ISNULL(ATTRIBUTE_035,'0') + ' , First Name: ' + ISNULL(ATTRIBUTE_003,'') + ' , Last Name : ' + ISNULL(ATTRIBUTE_004
,'') as WHO        
FROM [srm-CustomEntities].dbo.CUS_ENTITY_DATA   WITH(NOLOCK)     
Where SRM_CLIENT_ENTITIES_SEQ_ID=@WEB_SERVICE_EVENT_BOOKING_MASTER_Entity_SEQ_ID        
AND CREATED_BY='WEB'        
--AND ISNULL(ATTRIBUTE_066,'N')='N' --TRANSFERRED_TO_OOMI        
AND ISNULL(ATTRIBUTE_067,'N')='N' --REPORTED_TO_SUPPORT        
AND DATE_CREATED>@LapsedDays --'2014-06-04 10:00:00.000'        
AND DATEDIFF(minute, DATE_CREATED,GETDATE())>5        
AND isnull(ATTRIBUTE_035,0) not in(select isnull(ATTRIBUTE_062,0)      
         FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA  WITH(NOLOCK)  
         WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2667      
         AND created_by='WEB'      
         AND ATTRIBUTE_001 like 'EVE%'      
         )      
AND ATTRIBUTE_003 NOT LIKE '%SPIDER%' 
AND  ATTRIBUTE_004 NOT LIKE '%SPIDER%'       
UNION        
        
select  'WEB_SERVICE_PRODUCT_SALE_MASTER',ISNULL(ATTRIBUTE_068,'N') as TRANSFERRED_TO_OOMI,SEQ_ID,DATE_CREATED,'Sale ID : ' + ISNULL(ATTRIBUTE_001,'0') + ' , First Name: ' + ISNULL(ATTRIBUTE_004,'') + ' , Last Name : ' + ISNULL(ATTRIBUTE_005,'')  
FROM [srm-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)  
Where SRM_CLIENT_ENTITIES_SEQ_ID=@WEB_SERVICE_PRODUCT_SALE_MASTER_Entity_SEQ_ID        
AND CREATED_BY='WEB'        
--AND ISNULL(ATTRIBUTE_068,'N')='N' --TRANSFERRED_TO_OOMI        
--AND ISNULL(ATTRIBUTE_069,'N')='N' --REPORTED_TO_SUPPORT        
AND DATE_CREATED>@LapsedDays --'2014-06-04 10:00:00.000'        
AND DATEDIFF(minute, DATE_CREATED,GETDATE())>5       
and isnull(ATTRIBUTE_001,0) not in(select isnull(ATTRIBUTE_062,0)      
         from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA  WITH(NOLOCK)   
         where SRM_CLIENT_ENTITIES_SEQ_ID=2667      
         and created_by='WEB'      
         and ATTRIBUTE_001 like 'ISC%')   
            
AND ATTRIBUTE_004 NOT LIKE '%SPIDER%' 
AND  ATTRIBUTE_005 NOT LIKE '%SPIDER%'
    
UNION        
        
select  'WEB_SERVICE_MEMBERSHIP',ISNULL(ATTRIBUTE_078,'N') as TRANSFERRED_TO_OOMI,SEQ_ID,DATE_CREATED,'First Name: ' + ISNULL(ATTRIBUTE_003,'') + ' , Last Name : ' + ISNULL(ATTRIBUTE_001,'')        
FROM [srm-CustomEntities].dbo.CUS_ENTITY_DATA   WITH(NOLOCK)     
Where SRM_CLIENT_ENTITIES_SEQ_ID=@WEB_SERVICE_MEMBERSHIP_Entity_SEQ_ID        
AND CREATED_BY='WEB'        
--AND ISNULL(ATTRIBUTE_078,'N')='N' --TRANSFERRED_TO_OOMI        
AND ISNULL(ATTRIBUTE_079,'N')='N' --REPORTED_TO_SUPPORT        
AND DATE_CREATED>@LapsedDays --'2014-06-04 10:00:00.000'
AND DATEDIFF(minute, DATE_CREATED,GETDATE())>5        
and ISNULL(Deleted,'N')='N'      
and ATTRIBUTE_061 not in (select ISNULL(ATTRIBUTE_047,0) from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA   WITH(NOLOCK)    
        where SRM_CLIENT_ENTITIES_SEQ_ID=2541     
        AND CREATED_BY='WEB'     
        )      
AND ATTRIBUTE_003 NOT LIKE '%SPIDER%' 
AND  ATTRIBUTE_001 NOT LIKE '%SPIDER%'
)      
INSERT INTO [SRM-ErrorHandler].dbo.SRM_API_DATA_IMPORT_EXCEPTIONS      
([SOURCE], [CUS_ENTITY_DATA_SEQ_ID], [TRANSFERRED_TO_OOMI], [PARAMETERS], [DATE_CREATED], [CLIENT_ID], [LOG_DATE])      
Select [SOURCE], [SEQ_ID], [TRANSFERRED_TO_OOMI], [WHO], [DATE_CREATED], 17, GETDATE() from TEMPREC 



;








