-- =============================================
CREATE PROCEDURE [dbo].[GET_CREATE_EVENT_REGISTRATION]
	-- Add the parameters for the stored procedure here
	@EXTERNAL_ID NVARCHAR(100) = NULL,
	@BOOKING_REFERENCE NVARCHAR(100) = NULL, 
	@DELEGATE_NAME NVARCHAR(100) = NULL,
	@DELEGATE_TYPE BIGINT = NULL,
	@DELEGATE_TYPE_NAME NVARCHAR(100) = NULL,
	@REGISTRATION_STATUS BIGINT = NULL,
	@REGISTRATION_STATUS_NAME NVARCHAR(100) = NULL,
	@EVENT_NAME NVARCHAR(100) = NULL,
	@BOOKING_SOURCE BIGINT = NULL,
	@BOOKING_SOURCE_DESCRIPTION NVARCHAR(100) = NULL,
	@BOOKER BIGINT = NULL, 
	@BOOKER_NAME NVARCHAR(100) = NULL,
	@REGISTRATION_METHOD BIGINT = NULL,
	@REGISTRATION_METHOD_DESCRIPTION NVARCHAR(100) = NULL,
	@REGISTRATION_DATE NVARCHAR(100) = NULL,
	@CONFIRMATION_DATE NVARCHAR(100) = NULL,
	@CANCELLATION_DATE NVARCHAR(100) = NULL,
	@CONFIRMATION_LETTER_SENT NVARCHAR(100) = NULL,
	@REMARKS NVARCHAR(500) = NULL,
	@MARKETING_COMPAIGN BIGINT = NULL,
	@MARKETING_COMPAIGN_NAME NVARCHAR(100) = NULL, 
	@SESSION_DATE DateTime = NULL,
	@SESSION_TIME NVARCHAR(10) = NULL,
	@DEFAULT_EVENT BIGINT = NULL,
	@DEFAULT_EVENT_NAME NVARCHAR(100) = NULL,
	@MARKETING_SOURCE BIGINT = NULL,
	@MARKETING_SOURCE_DESCRIPTION NVARCHAR(100) = NULL,
	@SPECIAL_EDUCATION_NEEDS NVARCHAR(1) = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@EVENT_REGISTRATION_SEQ_ID BIGINT = NULL OUTPUT,
	@REGISTRATION_ID NVARCHAR(100) = NULL OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[GET_CREATE_EVENT_REGISTRATION]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_EVENT_REGISTRATION]'

	DECLARE @TODAY NVARCHAR(10)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @WEB_SERVICE_PRODUCT_SALE_MASTER BIGINT
	DECLARE @WEB_SERVICE_PRODUCT_SALE_MASTER_DESCRIPTION NVARCHAR(100)

	DECLARE @ENTITY_DISPLAY_NAME_EVENT_REGISTRATION NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION BIGINT
	SET @ENTITY_DISPLAY_NAME_EVENT_REGISTRATION = 'EVENT_REGISTRATION'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EVENT_REGISTRATION

	DECLARE @ENTITY_DISPLAY_NAME_EVENT NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT BIGINT
	SET @ENTITY_DISPLAY_NAME_EVENT = 'EVENT'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EVENT


	--EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'CONTACT', @ATTRIBUTE_DISPLAY_NAME = 'DEFAULT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @CONTACT_STATUS OUTPUT, @DESCRIPTION = @CONTACT_STATUS_NAME OUTPUT

	EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 8, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @REGISTRATION_ID OUTPUT

	SELECT @BOOKING_REFERENCE = ATTRIBUTE_002 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT AND SEQ_ID = @DEFAULT_EVENT

	EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
		@ATTRIBUTE_001 = @BOOKING_REFERENCE,
		@ATTRIBUTE_003 = @DELEGATE_NAME,
		@ATTRIBUTE_004 = @DELEGATE_TYPE,
		@ATTRIBUTE_005 = @DELEGATE_TYPE_NAME,
		@ATTRIBUTE_006 = @REGISTRATION_STATUS,
		@ATTRIBUTE_007 = @REGISTRATION_STATUS_NAME,
		@ATTRIBUTE_009 = @EVENT_NAME,
		@ATTRIBUTE_010 = @BOOKING_SOURCE,
		@ATTRIBUTE_011 = @BOOKING_SOURCE_DESCRIPTION,
		@ATTRIBUTE_012 = @BOOKER,
		@ATTRIBUTE_013 = @BOOKER_NAME,
		@ATTRIBUTE_014 = @REGISTRATION_METHOD,
		@ATTRIBUTE_015 = @REGISTRATION_METHOD_DESCRIPTION,
		@ATTRIBUTE_016 = @REGISTRATION_ID,
		@ATTRIBUTE_017 = @REGISTRATION_DATE,
		@ATTRIBUTE_018 = @CONFIRMATION_DATE,
		@ATTRIBUTE_019 = @CANCELLATION_DATE,
		@ATTRIBUTE_020 = @CONFIRMATION_LETTER_SENT,
		@ATTRIBUTE_023 = @REMARKS,
		@ATTRIBUTE_027 = @MARKETING_COMPAIGN,
		@ATTRIBUTE_028 = @MARKETING_COMPAIGN_NAME,
		@ATTRIBUTE_029 = @SESSION_DATE,
		@ATTRIBUTE_030 = @SESSION_TIME,
		@ATTRIBUTE_032 = @DEFAULT_EVENT,
		@ATTRIBUTE_033 = @DEFAULT_EVENT_NAME,
		@ATTRIBUTE_034 = @MARKETING_SOURCE,
		@ATTRIBUTE_035 = @MARKETING_SOURCE_DESCRIPTION,
		@ATTRIBUTE_031 = @SPECIAL_EDUCATION_NEEDS,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION,
		@DATE_CREATED = @TODAY,
		@CREATED_BY = @USER,
		@RETURN_SEQ_ID = @EVENT_REGISTRATION_SEQ_ID OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END







;






