-- Author:		<Adeel Hassan>
-- Create date: <03/09/2013>
-- Description:	<Create Event Registration Charges>
-- =============================================
CREATE PROCEDURE [dbo].[GET_CREATE_EVENT_REGISTRATION_CHARGES]
	-- Add the parameters for the stored procedure here
	@EXTERNAL_ID NVARCHAR(100) = NULL,
	@EVENT_REGISTRATION BIGINT = NULL,
	@EVENT_REGISTRATION_NAME NVARCHAR(100) = NULL,
	@EVENT_RATE_TYPE BIGINT = NULL,
	@EVENT_RATE_TYPE_NAME NVARCHAR(100) = NULL,
	@RATE MONEY = NULL,
	@QUANTITY BIGINT = NULL,
	@NET_AMOUNT MONEY = NULL,
	@DISCOUNT_PERCENTAGE MONEY = NULL,
	@DISCOUNT_AMOUNT MONEY = NULL,
	@VAT_PERCENTAGE MONEY = NULL,
	@VAT_AMOUNT MONEY = NULL,
	@GROSS_AMOUNT MONEY = NULL,
	@ANALYSIS_HEAD BIGINT = NULL,
	@ANALYSIS_HEAD_NAME NVARCHAR(100) = NULL,
	@DELEGATE_TYPE BIGINT = NULL,
	@DELEGATE_TYPE_NAME NVARCHAR(100) = NULL,
	@EVENT_DELEGATE BIGINT = NULL,
	@EVENT_DELEGATE_NAME NVARCHAR(100) = NULL,
	@EVENT BIGINT = NULL,
	@EVENT_NAME NVARCHAR(100) = NULL,
	@VAT_RATE BIGINT = NULL,
	@VAT_RATE_NAME NVARCHAR(100) = NULL,
	@TOTAL_AMOUNT MONEY = NULL,	
	@PO_NUMBER NVARCHAR(200) = NULL,
	@LEDGER_ACCOUNT BIGINT = NULL,
	@LEDGER_ACCOUNT_NAME NVARCHAR (200) = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[GET_CREATE_EVENT_REGISTRATION_CHARGES]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[EVENT_REGISTRATION_CHARGES]'

	DECLARE @TODAY NVARCHAR(10)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)
	DECLARE @EVENT_REGISTRATION_CHARGES BIGINT
	--DECLARE @EVENT_REGISTRATION_CHARGES_NAME NVARCHAR(100)
	
	DECLARE @ENTITY_DISPLAY_NAME_EVENT_REGISTRATION_CHARGES NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION_CHARGES BIGINT
	
	SET @ENTITY_DISPLAY_NAME_EVENT_REGISTRATION_CHARGES = 'EVENT_REGISTRATION_CHARGES'

	DECLARE @ENTITY_DISPLAY_NAME_INVOICE_TRANSACTION NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_INVOICE_TRANSACTION BIGINT
	SET @ENTITY_DISPLAY_NAME_INVOICE_TRANSACTION = 'INVOICE_TRANSACTION'

	DECLARE @MODULE BIGINT
	DECLARE @MODULE_DESCRIPTION NVARCHAR(100)
	DECLARE @TRANSACTION_STATUS BIGINT
	DECLARE @TRANSACTION_STATUS_DESCRIPTION NVARCHAR(100)
	
	-- GET MODULE
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MODULE', @ATTRIBUTE_DISPLAY_NAME = 'EVENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MODULE OUTPUT, @DESCRIPTION = @MODULE_DESCRIPTION OUTPUT
	-- GET Transaction Status
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'FINANCE_TRANSACTION_STATUS', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Current', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @TRANSACTION_STATUS OUTPUT, @DESCRIPTION = @TRANSACTION_STATUS_DESCRIPTION OUTPUT
	
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION_CHARGES = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EVENT_REGISTRATION_CHARGES
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_INVOICE_TRANSACTION = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_INVOICE_TRANSACTION
	
	PRINT 	'@EVENT_RATE_TYPE = ' + CAST(ISNULL(@EVENT_RATE_TYPE,0) AS VARCHAR(50))
	PRINT 	'@EVENT_RATE_TYPE_NAME = ' + CAST(ISNULL(@EVENT_RATE_TYPE_NAME,'') AS VARCHAR(50))



	-- EVENT REGISTRATION CHARGES
	EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]	
		@ATTRIBUTE_001 = @EVENT_RATE_TYPE_NAME,
		@ATTRIBUTE_002 = @EVENT_REGISTRATION,
		@ATTRIBUTE_003 = @EVENT_REGISTRATION_NAME,
		@ATTRIBUTE_004 = @EVENT_RATE_TYPE,
		@ATTRIBUTE_005 = @EVENT_RATE_TYPE_NAME,
		@ATTRIBUTE_006 = @RATE,
		@ATTRIBUTE_007 = @QUANTITY,
		@ATTRIBUTE_008 = @NET_AMOUNT ,
		@ATTRIBUTE_009 = @DISCOUNT_PERCENTAGE,
		@ATTRIBUTE_010 = @DISCOUNT_AMOUNT,
		@ATTRIBUTE_011 = @VAT_PERCENTAGE,
		@ATTRIBUTE_012 = @VAT_AMOUNT,
		@ATTRIBUTE_013 = @GROSS_AMOUNT,
		@ATTRIBUTE_014 = @ANALYSIS_HEAD,
		@ATTRIBUTE_015 = @ANALYSIS_HEAD_NAME,
		@ATTRIBUTE_016 = @DELEGATE_TYPE,
		@ATTRIBUTE_017 = @DELEGATE_TYPE_NAME,
		@ATTRIBUTE_018 = @EVENT_DELEGATE,
		@ATTRIBUTE_019 = @EVENT_DELEGATE_NAME,
		@ATTRIBUTE_020 = @EVENT,
		@ATTRIBUTE_021 = @EVENT_NAME,
		@ATTRIBUTE_022 = @VAT_RATE,
		@ATTRIBUTE_023 = @VAT_RATE_NAME,
		@ATTRIBUTE_024 = @TOTAL_AMOUNT,	
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION_CHARGES,
		@DATE_CREATED = @TODAY,
		@CREATED_BY = @USER,
		@RETURN_SEQ_ID = @EVENT_REGISTRATION_CHARGES OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		IF @EVENT_DELEGATE_NAME IS NOT NULL
			SET @EVENT_RATE_TYPE_NAME = @EVENT_RATE_TYPE_NAME + ' [' + @EVENT_DELEGATE_NAME + ']'
		--SELECT @EVENT_REGISTRATION_CHARGES_NAME = ATTRIBUTE_001 FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA
		--WHERE SEQ_ID = @EVENT_REGISTRATION_CHARGES 
		
		-- INVOICE TRANSACTION
		EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]	
			@ATTRIBUTE_001 = @EVENT_RATE_TYPE_NAME,
			@ATTRIBUTE_002 = @MODULE,
			@ATTRIBUTE_003 = @MODULE_DESCRIPTION,
			@ATTRIBUTE_004 = @EVENT_REGISTRATION_CHARGES,
			@ATTRIBUTE_008 = @EVENT_DELEGATE ,
			@ATTRIBUTE_009 = @EVENT_DELEGATE_NAME,
			@ATTRIBUTE_010 = @PO_NUMBER,
			@ATTRIBUTE_011 = @TODAY,
			@ATTRIBUTE_012 = @LEDGER_ACCOUNT,
			@ATTRIBUTE_013 = @LEDGER_ACCOUNT_NAME,
			@ATTRIBUTE_014 = @VAT_RATE,
			@ATTRIBUTE_015 = @VAT_RATE_NAME,
			@ATTRIBUTE_016 = @VAT_PERCENTAGE,
			@ATTRIBUTE_017 = @RATE,
			@ATTRIBUTE_018 = @QUANTITY,
			@ATTRIBUTE_019 = @TOTAL_AMOUNT,
			@ATTRIBUTE_020 = @DISCOUNT_PERCENTAGE,
			@ATTRIBUTE_021 = @DISCOUNT_AMOUNT,
			@ATTRIBUTE_022 = @NET_AMOUNT,
			@ATTRIBUTE_023 = @VAT_AMOUNT,
			@ATTRIBUTE_024 = @GROSS_AMOUNT,	
			@ATTRIBUTE_026 = @TRANSACTION_STATUS,
			@ATTRIBUTE_027 = @TRANSACTION_STATUS_DESCRIPTION,	
			@ATTRIBUTE_030 = @EXTERNAL_ID,
			@ATTRIBUTE_032 = @EVENT_REGISTRATION,
			@ATTRIBUTE_033 = @EVENT_REGISTRATION_NAME,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_INVOICE_TRANSACTION,
			@DATE_CREATED = @TODAY,
			@CREATED_BY = @USER,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	
END







;







-- =============================================
-- Author:		<Adeel Hassan>
-- Create date: <02/09/2013>
-- Description:	<Get Create Contact Account>
-- =============================================
CREATE PROCEDURE [dbo].[GET_CREATE_EVENT_REGISTRATION_IMPORT]
	-- Add the parameters for the stored procedure here
	@WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID BIGINT = NULL,
	@SRM_CLIENT_ENTITIES_SEQ_ID_EVENT BIGINT = NULL,
	@SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM BIGINT = NULL,
	@EXTERNAL_ID NVARCHAR(100) = NULL,
	@CONTACT_SEQ_ID BIGINT = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@EVENT_REGISTRATION_SEQ_ID BIGINT OUTPUT,
	@REGISTRATION_ID NVARCHAR(100) OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[GET_CREATE_EVENT_REGISTRATION_IMPORT]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_EVENT_REGISTRATION_IMPORT]'

	-- EVENT REGISTRATION DETAIL
	DECLARE @DELEGATE_TYPE NVARCHAR(100)
	DECLARE @EVENT_ID NVARCHAR(100)
	DECLARE @ATTENDING_IN_PERSON NVARCHAR(1)

	DECLARE @CONTACT_NAME NVARCHAR(100)
	DECLARE @REMARKS NVARCHAR(100)
	
	DECLARE @WEB_SERVICE_EVENT_BOOKING_MASTER BIGINT
	DECLARE @WEB_SERVICE_EVENT_BOOKING_MASTER_DESCRIPTION NVARCHAR(100)

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_RATE BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_EVENT_RATE NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION_STATUS BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_EVENT_REGISTRATION_STATUS NVARCHAR(100)
	DECLARE @MEMBER_SEQ_ID BIGINT
	DECLARE @MEMBER_ID NVARCHAR(100)
	DECLARE @EVENT_SEQ_ID BIGINT
	DECLARE @DELEGATE_TYPE_NAME NVARCHAR(200)
	DECLARE @EVENT_REGISTRATION_STATUS_SEQ_ID BIGINT
	DECLARE @EVENT_REGISTRATION_STATUS_DESCRIPTION NVARCHAR(100)

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_VAT_RATE NVARCHAR(100)

	DECLARE @EVENT_RATE_TYPE NVARCHAR(100)
	DECLARE @EVENT_RATE_TYPE_NAME NVARCHAR(200)
	DECLARE @PAYMENT_AMOUNT MONEY
	DECLARE @PAYMENT_AMOUNT_NET MONEY
	DECLARE @PAYMENT_AMOUNT_VAT MONEY
	DECLARE @VAT_PERCENTAGE MONEY
	DECLARE @VAT_RATE BIGINT
	DECLARE @VAT_RATE_NAME NVARCHAR(100)
	DECLARE @PO_NUMBER NVARCHAR(200)
	DECLARE @LEDGER_ACCOUNT BIGINT
	DECLARE @LEDGER_ACCOUNT_NAME NVARCHAR(200)

	DECLARE @DISCOUNT_CODE_SEQ_ID BIGINT
	DECLARE @DISCOUNT_PERC BIGINT
	DECLARE @DISCOUNT_CODE NVARCHAR(100)
	DECLARE @TOTAL_AMOUNT MONEY

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_DELEGATE_TYPE BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_DELEGATE_TYPE NVARCHAR(200)
	
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_DISCOUNT_CODE NVARCHAR(200)
	
	DECLARE @TODAY NVARCHAR(10)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)
	PRINT '@TODAY ' + @TODAY

	SELECT	@DELEGATE_TYPE = ATTRIBUTE_016, @EVENT_ID = ATTRIBUTE_018, @ATTENDING_IN_PERSON = ATTRIBUTE_034, @DISCOUNT_CODE = ATTRIBUTE_037,
			@PAYMENT_AMOUNT = ATTRIBUTE_017, @PAYMENT_AMOUNT_NET = ATTRIBUTE_038, @PAYMENT_AMOUNT_VAT = ATTRIBUTE_039, @PO_NUMBER = ATTRIBUTE_033
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM 
	AND SEQ_ID = @WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID

	-- Get CONFIRMED Status
	SET @ENTITY_DISPLAY_NAME_EVENT_REGISTRATION_STATUS = 'EVENT_REGISTRATION_STATUS'
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION_STATUS = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EVENT_REGISTRATION_STATUS
	
	SELECT @EVENT_REGISTRATION_STATUS_SEQ_ID = SEQ_ID, @EVENT_REGISTRATION_STATUS_DESCRIPTION = ATTRIBUTE_001 
	FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION_STATUS 
	--AND ATTRIBUTE_007 = 'Confirmed'
	AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION_STATUS AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52399 AND ISNULL(ATTRIBUTE_STRING,'')='Confirmed')
	
	PRINT '@EVENT_REGISTRATION_STATUS_SEQ_ID ' + CAST(@EVENT_REGISTRATION_STATUS_SEQ_ID AS NVARCHAR(100)) + ' @EVENT_REGISTRATION_STATUS_DESCRIPTION ' + @EVENT_REGISTRATION_STATUS_DESCRIPTION

	IF ISNULL(@EVENT_ID, '') <> ''  -- GET @DELEGATE_TYPE DESCRIPTION
	BEGIN
    
		DECLARE @EVENT_SEQ_ID_NEW BIGINT
		SELECT @EVENT_SEQ_ID_NEW =  CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52318 AND ISNULL(ATTRIBUTE_STRING,'')=@EVENT_ID

		IF ISNULL(@EVENT_SEQ_ID_NEW,0) = 0
		BEGIN
			SELECT @EVENT_SEQ_ID_NEW = SEQ_ID
			--@EVENT_SEQ_ID = SEQ_ID, @VAT_RATE = ATTRIBUTE_016, @VAT_RATE_NAME = ATTRIBUTE_017, @LEDGER_ACCOUNT = ATTRIBUTE_024, @LEDGER_ACCOUNT_NAME = ATTRIBUTE_025 
			FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH (NOLOCK)
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT 
			AND ATTRIBUTE_002 = @EVENT_ID
		END
        
		SELECT @EVENT_SEQ_ID = SEQ_ID, @VAT_RATE = ATTRIBUTE_016, @VAT_RATE_NAME = ATTRIBUTE_017, @LEDGER_ACCOUNT = ATTRIBUTE_024, @LEDGER_ACCOUNT_NAME = ATTRIBUTE_025 
		FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH (NOLOCK)
		WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT 
		--AND ATTRIBUTE_002 = @EVENT_ID
		AND CUS_ENTITY_DATA.SEQ_ID = @EVENT_SEQ_ID_NEW
		

		PRINT '@EVENT_SEQ_ID ' + CAST(@EVENT_SEQ_ID AS NVARCHAR(100))
	END

	IF ISNULL(@CONTACT_SEQ_ID, '') <> ''  -- GET @CONTACT_SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'CONTACT', @ATTRIBUTE_DISPLAY_NAME = 'RECORD_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @CONTACT_SEQ_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @CONTACT_SEQ_ID OUTPUT, @DESCRIPTION = @CONTACT_NAME OUTPUT
		PRINT '@CONTACT_NAME ' + CAST(@CONTACT_NAME AS NVARCHAR(100))
	END

	IF ISNULL(@DELEGATE_TYPE, '') = ''  -- GET @DELEGATE_TYPE DESCRIPTION
	BEGIN
		SET @ENTITY_DISPLAY_NAME_EVENT_RATE = 'EVENT_RATE'
		SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_RATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EVENT_RATE
	
		SET @ENTITY_DISPLAY_NAME_DELEGATE_TYPE = 'DELEGATE_TYPE'
		SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_DELEGATE_TYPE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_DELEGATE_TYPE
	
	
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MEMBER', @ATTRIBUTE_DISPLAY_NAME = 'CONTACT', @OPERATOR_ID = 3, @SEARCH_VALUE = @CONTACT_SEQ_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MEMBER_SEQ_ID OUTPUT, @DESCRIPTION = @MEMBER_ID OUTPUT
		
		IF ISNULL(@MEMBER_ID,'') = ''
		BEGIN
			--SELECT @EVENT_RATE_TYPE = ATTRIBUTE_004, @EVENT_RATE_TYPE_NAME = ATTRIBUTE_005, @DELEGATE_TYPE = ATTRIBUTE_006, @DELEGATE_TYPE_NAME = ATTRIBUTE_007 
			--FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_RATE 
			--AND ATTRIBUTE_002 = @EVENT_SEQ_ID
			--AND (ATTRIBUTE_005 LIKE '%Non Member%' OR ATTRIBUTE_005 LIKE '%Non-Member%')
			
			SELECT @EVENT_RATE_TYPE = EVNT_RATE.ATTRIBUTE_004, @EVENT_RATE_TYPE_NAME = EVNT_RATE.ATTRIBUTE_005,  @DELEGATE_TYPE = EVNT_RATE.ATTRIBUTE_006, @DELEGATE_TYPE_NAME = EVNT_RATE.ATTRIBUTE_007 
			FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVNT_RATE WITH(NOLOCK)
		    INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA DELEGATE_TYPE ON DELEGATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_DELEGATE_TYPE 
				--AND CAST(DELEGATE_TYPE.SEQ_ID AS VARCHAR)=EVNT_RATE.ATTRIBUTE_006 
				AND DELEGATE_TYPE.SEQ_ID IN(SELECT TEMP2.CUS_ENTITY_DATA_SEQ_ID 
											FROM (SELECT CUS_ENTITY_DATA_SEQ_ID 
													FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) 
													WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DELEGATE_TYPE 
													AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52362 
													AND CUS_ENTITY_DATA_SEQ_ID =EVNT_RATE.ATTRIBUTE_006
												  )TEMP1
											INNER JOIN [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH (NOLOCK) ON TEMP2.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DELEGATE_TYPE
											AND TEMP2.CUS_ENTITY_DATA_SEQ_ID=TEMP1.CUS_ENTITY_DATA_SEQ_ID 
											AND TEMP2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52381 --EVENT_DELEGATE_TYPE_DESCRIPTION
											AND ISNULL(TEMP2.ATTRIBUTE_STRING,'')='NON'  --AND DELEGATE_TYPE.ATTRIBUTE_009 = 'NON'
											)
				--AND DELEGATE_TYPE.ATTRIBUTE_009 = 'NON'
		    WHERE  EVNT_RATE.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		    AND EVNT_RATE.SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_RATE
		    --AND EVNT_RATE.ATTRIBUTE_002 = CAST(@EVENT_SEQ_ID AS VARCHAR )
		    AND EVNT_RATE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_RATE AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 54230 AND ISNULL(ATTRIBUTE_DECIMAL,0)=@EVENT_SEQ_ID)
			
			PRINT '@EVENT_RATE_TYPE_NAME ' + @EVENT_RATE_TYPE_NAME + ' @DELEGATE_TYPE_NAME ' + @DELEGATE_TYPE_NAME
			
		END	
		ELSE
		BEGIN
		
			SELECT @EVENT_RATE_TYPE = EVNT_RATE.ATTRIBUTE_004, @EVENT_RATE_TYPE_NAME = EVNT_RATE.ATTRIBUTE_005,  @DELEGATE_TYPE = EVNT_RATE.ATTRIBUTE_006, @DELEGATE_TYPE_NAME = EVNT_RATE.ATTRIBUTE_007 
			FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVNT_RATE WITH(NOLOCK)
		    INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA DELEGATE_TYPE ON DELEGATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_DELEGATE_TYPE 
		    --AND CAST(DELEGATE_TYPE.SEQ_ID AS VARCHAR)=EVNT_RATE.ATTRIBUTE_006 
		    AND DELEGATE_TYPE.SEQ_ID IN(SELECT TEMP2.CUS_ENTITY_DATA_SEQ_ID 
										FROM (SELECT CUS_ENTITY_DATA_SEQ_ID 
													FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) 
													WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DELEGATE_TYPE 
													AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52362 
													AND CUS_ENTITY_DATA_SEQ_ID =EVNT_RATE.ATTRIBUTE_006
												  )TEMP1
											INNER JOIN [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH (NOLOCK) ON TEMP2.SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DELEGATE_TYPE
											AND TEMP2.CUS_ENTITY_DATA_SEQ_ID=TEMP1.CUS_ENTITY_DATA_SEQ_ID 
											AND TEMP2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52381 --EVENT_DELEGATE_TYPE_DESCRIPTION
											AND ISNULL(TEMP2.ATTRIBUTE_STRING,'')='MEM'  --AND DELEGATE_TYPE.ATTRIBUTE_009 = 'MEM'
											)
		    --AND DELEGATE_TYPE.ATTRIBUTE_009 = 'MEM'
		    
		    WHERE EVNT_RATE.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		    AND EVNT_RATE.SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_RATE
		    --AND EVNT_RATE.ATTRIBUTE_002 = CAST(@EVENT_SEQ_ID AS VARCHAR )  
			AND EVNT_RATE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_RATE AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 54230 AND ISNULL(ATTRIBUTE_DECIMAL,0)=@EVENT_SEQ_ID)

			--FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA 
			--WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_RATE AND ATTRIBUTE_005 LIKE '%Member%' AND ATTRIBUTE_005 NOT LIKE '%Non Member%' AND ATTRIBUTE_005 Not LIKE '%Non-Member%'
			PRINT '@EVENT_RATE_TYPE_NAME ' + @EVENT_RATE_TYPE_NAME + ' @DELEGATE_TYPE_NAME ' + @DELEGATE_TYPE_NAME
		END	
	END
	
	SET @VAT_PERCENTAGE = 0.00
	IF ISNULL(@PAYMENT_AMOUNT_VAT,0) > 0 AND ISNULL(@VAT_RATE,0) > 0
	BEGIN
		SET @ENTITY_DISPLAY_NAME_VAT_RATE = 'VAT_RATE'
		SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_VAT_RATE
		
		SELECT @VAT_PERCENTAGE = ATTRIBUTE_006 
		FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)
		WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE 
		AND SEQ_ID = @VAT_RATE
		
		PRINT '@VAT_PERCENTAGE ' + CAST(@VAT_PERCENTAGE AS NVARCHAR(100))

	END

	EXEC [dbo].[GET_CREATE_EVENT_REGISTRATION]
		@EXTERNAL_ID = NULL,
		@BOOKING_REFERENCE = NULL, 
		@DELEGATE_NAME = NULL,
		@DELEGATE_TYPE  = @DELEGATE_TYPE,
		@DELEGATE_TYPE_NAME = @DELEGATE_TYPE_NAME,
		@REGISTRATION_STATUS  = @EVENT_REGISTRATION_STATUS_SEQ_ID,
		@REGISTRATION_STATUS_NAME = @EVENT_REGISTRATION_STATUS_DESCRIPTION,
		@EVENT_NAME = @EVENT_ID,
		@BOOKING_SOURCE  = NULL,
		@BOOKING_SOURCE_DESCRIPTION = NULL,
		@BOOKER  = @CONTACT_SEQ_ID, 
		@BOOKER_NAME = @CONTACT_NAME,
		@REGISTRATION_METHOD  = NULL,
		@REGISTRATION_METHOD_DESCRIPTION = NULL,
		@REGISTRATION_DATE = @TODAY,
		@CONFIRMATION_DATE = @TODAY,
		@CANCELLATION_DATE = NULL,
		@CONFIRMATION_LETTER_SENT = NULL,
		@REMARKS = NULL,
		@MARKETING_COMPAIGN  = NULL,
		@MARKETING_COMPAIGN_NAME = NULL, 
		@SESSION_DATE = NULL,
		@SESSION_TIME = NULL,
		@DEFAULT_EVENT  = @EVENT_SEQ_ID,
		@DEFAULT_EVENT_NAME = @EVENT_ID,
		@MARKETING_SOURCE  = NULL,
		@MARKETING_SOURCE_DESCRIPTION = NULL,
		@SPECIAL_EDUCATION_NEEDS = NULL,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@USER = @USER,
		@EVENT_REGISTRATION_SEQ_ID = @EVENT_REGISTRATION_SEQ_ID OUTPUT,
		@REGISTRATION_ID = @REGISTRATION_ID OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		SET @ERROR = 0
		SET @ERROR_DESCRIPTION = ''


		EXEC [dbo].[GET_CREATE_REGISTERED_EVENT]		
		@EVENT  = @EVENT_SEQ_ID,
		@EVENT_NAME = @EVENT_ID,
		@EVENT_REGISTRATION  = @EVENT_REGISTRATION_SEQ_ID,
		@EVENT_REGISTRATION_NAME = @REGISTRATION_ID,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@USER = @USER,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		SET @ERROR = 0
		SET @ERROR_DESCRIPTION = ''
	
		SET @ATTENDING_IN_PERSON = ''
		IF ISNULL(@ATTENDING_IN_PERSON,'') = 'Y'
		BEGIN
			DECLARE @EVENT_DELEGATE_SEQ_ID BIGINT
			DECLARE @EVENT_DELEGATE_NAME NVARCHAR(200)
			
			EXEC [dbo].[GET_CREATE_EVENT_DELEGATE]	
			@SRM_CLIENT_ENTITIES_SEQ_ID_EVENT = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT,	
			@EVENT  = @EVENT_SEQ_ID,
			@EVENT_NAME = @EVENT_ID,
			@EVENT_REGISTRATION  = @EVENT_REGISTRATION_SEQ_ID,
			@EVENT_REGISTRATION_NAME = @REGISTRATION_ID,
			@DELEGATE = @CONTACT_SEQ_ID,
			@DELEGATE_NAME = @CONTACT_NAME,
			@DELEGATE_TYPE = @DELEGATE_TYPE,
			@DELEGATE_TYPE_NAME = @DELEGATE_TYPE_NAME,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@USER = @USER,
			@EVENT_DELEGATE_SEQ_ID = @EVENT_DELEGATE_SEQ_ID OUTPUT,
			@EVENT_DELEGATE_NAME = @EVENT_DELEGATE_NAME OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

			SET @ERROR = 0
			SET @ERROR_DESCRIPTION = ''


			IF ISNULL(@DISCOUNT_CODE,'') <> ''
			BEGIN
				SET @DISCOUNT_PERC = 0
				SET @ENTITY_DISPLAY_NAME_DISCOUNT_CODE = 'DISCOUNT_CODE'
				SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_DISCOUNT_CODE
	
				SELECT @DISCOUNT_PERC = ATTRIBUTE_004 
				FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
				WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
				AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE 
				--AND ATTRIBUTE_001 = @DISCOUNT_CODE
				AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 55217 AND ISNULL(ATTRIBUTE_STRING,'')=@DISCOUNT_CODE)

				IF ISNULL(@DISCOUNT_PERC,0) > 0
				BEGIN
					PRINT '@DISCOUNT_PERC ' + CAST(@DISCOUNT_PERC AS NVARCHAR)
					SET @TOTAL_AMOUNT = @PAYMENT_AMOUNT_NET / (1.00 - ROUND(@DISCOUNT_PERC/100.00,2))			
										
					IF @PAYMENT_AMOUNT = @PAYMENT_AMOUNT_NET
					BEGIN
						PRINT '1st Case'
						SET @PAYMENT_AMOUNT_NET = @TOTAL_AMOUNT
						SET @PAYMENT_AMOUNT = @TOTAL_AMOUNT		
						IF @PAYMENT_AMOUNT_VAT > 0
							SET @PAYMENT_AMOUNT_VAT = ROUND(@TOTAL_AMOUNT * @VAT_PERCENTAGE / 100, 2)
					END
					ELSE IF @PAYMENT_AMOUNT = @PAYMENT_AMOUNT_NET + @PAYMENT_AMOUNT_VAT
					BEGIN
						PRINT '2nd Case'
						SET @PAYMENT_AMOUNT_NET = @TOTAL_AMOUNT
						IF @PAYMENT_AMOUNT_VAT > 0
							SET @PAYMENT_AMOUNT_VAT = ROUND(@TOTAL_AMOUNT * @VAT_PERCENTAGE / 100, 2)
						SET @PAYMENT_AMOUNT = @PAYMENT_AMOUNT_NET + @PAYMENT_AMOUNT_VAT
					END
					PRINT '@TOTAL_AMOUNT ' + CAST(@TOTAL_AMOUNT AS NVARCHAR(100))
					PRINT '@PAYMENT_AMOUNT_NET ' + CAST(@PAYMENT_AMOUNT_NET AS NVARCHAR(100))
					PRINT '@PAYMENT_AMOUNT_VAT ' + CAST(@PAYMENT_AMOUNT_VAT AS NVARCHAR(100))
					PRINT '@PAYMENT_AMOUNT ' + CAST(@PAYMENT_AMOUNT AS NVARCHAR(100))
				END
			END

			EXEC [dbo].[GET_CREATE_EVENT_REGISTRATION_CHARGES]		
			@EXTERNAL_ID = @EXTERNAL_ID,
			@EVENT_REGISTRATION = @EVENT_REGISTRATION_SEQ_ID,
			@EVENT_REGISTRATION_NAME = @REGISTRATION_ID,
			@EVENT_RATE_TYPE = @EVENT_RATE_TYPE,
			@EVENT_RATE_TYPE_NAME = @EVENT_RATE_TYPE_NAME,
			@RATE = @PAYMENT_AMOUNT,
			@QUANTITY = 1,
			@NET_AMOUNT = @PAYMENT_AMOUNT_NET ,
			@DISCOUNT_PERCENTAGE = 0.00,
			@DISCOUNT_AMOUNT = 0.00,
			@VAT_PERCENTAGE = @VAT_PERCENTAGE,
			@VAT_AMOUNT = @PAYMENT_AMOUNT_VAT,
			@GROSS_AMOUNT = @PAYMENT_AMOUNT,
			@ANALYSIS_HEAD = NULL,
			@ANALYSIS_HEAD_NAME = NULL,
			@DELEGATE_TYPE = @DELEGATE_TYPE,
			@DELEGATE_TYPE_NAME = @DELEGATE_TYPE_NAME,
			@EVENT_DELEGATE = @EVENT_DELEGATE_SEQ_ID,
			@EVENT_DELEGATE_NAME = @EVENT_DELEGATE_NAME,
			@EVENT = @EVENT_SEQ_ID,
			@EVENT_NAME = @EVENT_ID,
			@VAT_RATE = @VAT_RATE,
			@VAT_RATE_NAME = @VAT_RATE_NAME,
			@TOTAL_AMOUNT = @PAYMENT_AMOUNT,	
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@USER = @USER,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

			SET @ERROR = 0
			SET @ERROR_DESCRIPTION = ''
		END
END








;





-- =============================================    
-- Author:  <MQ>    
-- Create date: <09/12/2014>    
-- Description: <Create Event Session Registrations>    
-- =============================================    
CREATE PROCEDURE [dbo].[GET_CREATE_EVENT_SESSION_REGISTRATION]    
 -- Add the parameters for the stored procedure here    
 @BOOKING_ID NVARCHAR(100) = NULL,
 @DELEGATE_CONTACT_SEQ_ID BIGINT = NULL, 
 @DELEGATE_FIRST_NAME NVARCHAR(100) = NULL,
 @DELEGATE_LAST_NAME  NVARCHAR(100) = NULL,
 @EVENT_REGISTRATION_SEQ_ID BIGINT = NULL,
 @USER NVARCHAR(100) = NULL,    
 @SRM_CLIENTS_SEQ_ID BIGINT = NULL,    
 @ERROR SMALLINT = NULL OUTPUT,    
 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT    
AS    
BEGIN    
 DECLARE @EVENT_SESSION_REGISTRATION_SEQ_ID BIGINT  

DECLARE @REGISTRATION_STATUS_SEQ_ID BIGINT	
DECLARE @REGISTRATION_STATUS_NAME NVARCHAR(100)	
DECLARE @EVENT_SEQ_ID BIGINT	
DECLARE @EVENT_NAME NVARCHAR(100)	

DECLARE @LABEL_NAME NVARCHAR(100)
DECLARE @REGISTRATION_ID NVARCHAR(50)
DECLARE @WS_EVENT_SESSION_BOOKING_@EVENT_ID NVARCHAR(100)
DECLARE @WS_EVENT_SESSION_BOOKING_@SESSION_ID NVARCHAR(100)
DECLARE @OOMI_EVENT_SESSION_SEQ_ID BIGINT
DECLARE @SESSION_@FORMAL_TITLE NVARCHAR(500)

 -- SET NOCOUNT ON added to prevent extra result sets from    
 -- interfering with SELECT statements.    
 SET NOCOUNT ON;    
    
 PRINT 'I AM IN [dbo].[GET_CREATE_EVENT_SESSION_REGISTRATION]'    
    
 SET @ERROR = 1    
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_EVENT_SESSION_REGISTRATION]'    
    
 DECLARE @TODAY NVARCHAR(30)    
 SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)    
 
 DECLARE @ENTITY_DISPLAY_NAME_EVENT_DELEGATE NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_DELEGATE BIGINT    
 SET @ENTITY_DISPLAY_NAME_EVENT_DELEGATE = 'EVENT_DELEGATE'   
 
 DECLARE @ENTITY_DISPLAY_NAME_EVENT_SESSION_REGISTRATION NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_SESSION_REGISTRATION BIGINT    
 SET @ENTITY_DISPLAY_NAME_EVENT_SESSION_REGISTRATION = 'EVENT_SESSION_REGISTRATION'    
 
 DECLARE @ENTITY_DISPLAY_NAME_WS_EVENT_SESSION_BOOKING NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WS_EVENT_SESSION_BOOKING BIGINT    
 SET @ENTITY_DISPLAY_NAME_WS_EVENT_SESSION_BOOKING = 'WEB_SERVICE_EVENT_SESSION_BOOKING'
 
 DECLARE @ENTITY_DISPLAY_NAME_EVENT_SESSION NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_SESSION BIGINT    
 SET @ENTITY_DISPLAY_NAME_EVENT_SESSION = 'EVENT_SESSION'
 
 DECLARE @ENTITY_DISPLAY_NAME_WEB_SERVICE_EVENT_SESSIONS NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WEB_SERVICE_EVENT_SESSIONS BIGINT    
 SET @ENTITY_DISPLAY_NAME_WEB_SERVICE_EVENT_SESSIONS = 'WEB_SERVICE_EVENT_SESSIONS'
 
 DECLARE @ENTITY_DISPLAY_NAME_CONTACT NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT BIGINT    
 SET @ENTITY_DISPLAY_NAME_CONTACT = 'CONTACT'
 
 DECLARE @TODATE DateTime    
 SELECT @TODATE = GETDATE()  
 
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_CONTACT    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_DELEGATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EVENT_DELEGATE    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_SESSION_REGISTRATION = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EVENT_SESSION_REGISTRATION 
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_SESSION = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EVENT_SESSION    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WS_EVENT_SESSION_BOOKING = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WS_EVENT_SESSION_BOOKING    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WEB_SERVICE_EVENT_SESSIONS = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WEB_SERVICE_EVENT_SESSIONS    

 SELECT @LABEL_NAME=ISNULL(ATTRIBUTE_001,@DELEGATE_FIRST_NAME + ' ' + @DELEGATE_LAST_NAME)  FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA  WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT and SEQ_ID=@DELEGATE_CONTACT_SEQ_ID
 SELECT @REGISTRATION_STATUS_SEQ_ID=ATTRIBUTE_006,@REGISTRATION_STATUS_NAME=ATTRIBUTE_007,@EVENT_SEQ_ID=ATTRIBUTE_032,@EVENT_NAME=ATTRIBUTE_033,@REGISTRATION_ID=ATTRIBUTE_016	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA  WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID=@EVENT_REGISTRATION_SEQ_ID


 DECLARE CUR_WEB_SERVICE_EVENT_SESSION_BOOKING  CURSOR STATIC LOCAL FOR   
		 SELECT ATTRIBUTE_003,ATTRIBUTE_004
		 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
		 WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WS_EVENT_SESSION_BOOKING 
		 AND ATTRIBUTE_002 = @BOOKING_ID
		 AND ATTRIBUTE_005 = LTRIM(RTRIM(@DELEGATE_FIRST_NAME))
		 AND ATTRIBUTE_006 = LTRIM(RTRIM(@DELEGATE_LAST_NAME))
		 		
 OPEN CUR_WEB_SERVICE_EVENT_SESSION_BOOKING  
 FETCH NEXT FROM CUR_WEB_SERVICE_EVENT_SESSION_BOOKING INTO @WS_EVENT_SESSION_BOOKING_@EVENT_ID, @WS_EVENT_SESSION_BOOKING_@SESSION_ID
 
 DECLARE @WEB_SERVICE_EVENT_SESSION_SEQ_ID BIGINT
 
 WHILE @@FETCH_STATUS = 0  
 BEGIN  
 
 		SELECT @WEB_SERVICE_EVENT_SESSION_SEQ_ID=SEQ_ID , @EVENT_SEQ_ID=ATTRIBUTE_002,@EVENT_NAME=ATTRIBUTE_003,@OOMI_EVENT_SESSION_SEQ_ID=ATTRIBUTE_028,@SESSION_@FORMAL_TITLE=ATTRIBUTE_009
		FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA
		WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WEB_SERVICE_EVENT_SESSIONS
		AND ATTRIBUTE_027 = @WS_EVENT_SESSION_BOOKING_@EVENT_ID
		AND ATTRIBUTE_001=  @WS_EVENT_SESSION_BOOKING_@SESSION_ID
 
	  EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
	  @ATTRIBUTE_002 = @OOMI_EVENT_SESSION_SEQ_ID,
	  @ATTRIBUTE_003 = @SESSION_@FORMAL_TITLE,
	  @ATTRIBUTE_004 = @REGISTRATION_STATUS_SEQ_ID,
	  @ATTRIBUTE_005 = @REGISTRATION_STATUS_NAME,
	  @ATTRIBUTE_006 = @EVENT_REGISTRATION_SEQ_ID,
	  @ATTRIBUTE_007 = @REGISTRATION_ID,
	  @ATTRIBUTE_009 = @TODATE,    
	  @ATTRIBUTE_010 = @TODATE,    
	  @ATTRIBUTE_014 = @EVENT_SEQ_ID,
	  @ATTRIBUTE_015 = @EVENT_NAME,
	  @ATTRIBUTE_016 = @DELEGATE_CONTACT_SEQ_ID,
	  @ATTRIBUTE_017 = @LABEL_NAME,
	  @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
	  @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_SESSION_REGISTRATION,    
	  @DATE_CREATED = @TODATE,    
	  @CREATED_BY = @USER,    
	  @RETURN_SEQ_ID = @EVENT_SESSION_REGISTRATION_SEQ_ID OUTPUT,    
	  @ERROR = @ERROR OUTPUT,    
	  @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
  

 -- Increase / Descrease Total Bookings & Seats Available fields    
		 DECLARE @TOTAL_BOOKINGS INT    
		 DECLARE @SEATS_AVAILABLE INT    
		 DECLARE @MAXIMUM_SEATS INT   
		 DECLARE @TOTAL_DELEGATES INT --ATTRIBUTE_077  
		 DECLARE @TOTAL_CANCELLATION INT    
		    
		 SELECT @TOTAL_BOOKINGS = ATTRIBUTE_015, @SEATS_AVAILABLE = ATTRIBUTE_016 , @MAXIMUM_SEATS=ATTRIBUTE_014  
		 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
		 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_SESSION AND SEQ_ID = @OOMI_EVENT_SESSION_SEQ_ID
		   
		 SELECT @TOTAL_DELEGATES=ISNULL(Count(*),@TOTAL_BOOKINGS) FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA   
		 WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_SESSION_REGISTRATION  
		 AND ATTRIBUTE_002 = @OOMI_EVENT_SESSION_SEQ_ID  
		 and ATTRIBUTE_005='CONFIRMED'
		 and ISNULL(DELETED,'N')='N'
		   
		 SELECT @TOTAL_CANCELLATION=ISNULL(Count(*),0) FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA   
		 WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_SESSION_REGISTRATION  
		 AND ATTRIBUTE_016 = @OOMI_EVENT_SESSION_SEQ_ID  
		and ATTRIBUTE_019='CANCELLED'  
		and ISNULL(DELETED,'N')='N'
		   
		 SET @TOTAL_BOOKINGS = @TOTAL_BOOKINGS + 1    
		 SET @SEATS_AVAILABLE = @SEATS_AVAILABLE -1    
		   
		 SET @SEATS_AVAILABLE=@MAXIMUM_SEATS - @TOTAL_DELEGATES --+ @TOTAL_CANCELLATION  --ATTRIBUTE_077  
		   
		 UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
		 SET ATTRIBUTE_015 = @TOTAL_BOOKINGS, 
		  ATTRIBUTE_016 = @SEATS_AVAILABLE,  
		  DATE_MODIFIED = @TODAY,    
		  MODIFIED_BY = @USER    
		 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_SESSION AND SEQ_ID = @OOMI_EVENT_SESSION_SEQ_ID    
				    
		 EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
		  @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_SESSION,    
		  @CUS_ENTITY_DATA_SEQ_ID = @OOMI_EVENT_SESSION_SEQ_ID,    
		  @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
		  @ERROR = @ERROR OUTPUT,    
		  @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
		  
		 UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
		 SET ATTRIBUTE_015 = @TOTAL_BOOKINGS, 
		  ATTRIBUTE_016 = @SEATS_AVAILABLE,  
		  DATE_MODIFIED = @TODAY,    
		  MODIFIED_BY = @USER    
		 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WEB_SERVICE_EVENT_SESSIONS AND SEQ_ID = @WEB_SERVICE_EVENT_SESSION_SEQ_ID    
		  
		  
  FETCH NEXT FROM CUR_WEB_SERVICE_EVENT_SESSION_BOOKING INTO @WS_EVENT_SESSION_BOOKING_@EVENT_ID, @WS_EVENT_SESSION_BOOKING_@SESSION_ID
  
 END  
  
 CLOSE CUR_WEB_SERVICE_EVENT_SESSION_BOOKING  
 DEALLOCATE CUR_WEB_SERVICE_EVENT_SESSION_BOOKING  
END    
    
    



;





    
