  @ATTRIBUTE_051 = NULL, --REMARKS    
  @ATTRIBUTE_052 = NULL, --PARENT_TRANSACTION    
  @ATTRIBUTE_053 = NULL, --PARENT_TRANSACTION_NAME    
  @ATTRIBUTE_054 = @TRANSACTION_TYPE, --TRANSACTION_TYPE    
  @ATTRIBUTE_055 = @TRANSACTION_TYPE_DESCRIPTION, --TRANSACTION_TYPE_DESCRIPTION    
  @ATTRIBUTE_057 = @TOTAL_VOUCHER_AMOUNT, --TOTAL_VOUCHER_AMOUNT    
