 EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_IT, @ATTRIBUTE_DISPLAY_NAME = 'EXTERNAL_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @EXTERNAL_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT    
    
 DECLARE CUS_SALES CURSOR STATIC LOCAL FOR     
 SELECT     
  SEQ_ID,    
  ATTRIBUTE_001,  -- PRODUCT_NAME    
  ATTRIBUTE_002,  -- MODULE    
  ATTRIBUTE_003,  -- MODULE_DESCRIPTION    
  ATTRIBUTE_004,  -- PARENT_ID    
  ATTRIBUTE_005,  -- PRODUCT    
  ATTRIBUTE_008,  -- CONTACT    
  ATTRIBUTE_009,  -- CONTACT_NAME    
  ATTRIBUTE_011,  -- TODAY,    
  ATTRIBUTE_012,  -- LEDGER_ACCOUNT    
  ATTRIBUTE_013,  -- LEDGER_ACCOUNT_NAME    
  ATTRIBUTE_014,  -- VAT_RATE    
  ATTRIBUTE_015,  -- VAT_RATE_NAME    
  ATTRIBUTE_016,  -- VAT_PERCENTAGE    
  ATTRIBUTE_017,  -- UNIT_PRICE    
  ATTRIBUTE_018,  -- QUANTITY    
  ATTRIBUTE_019,  -- TOTAL_PRICE    
  ATTRIBUTE_020,  -- DISCOUNT_PERCENTAGE    
  ATTRIBUTE_021,  -- DISCOUNT_AMOUNT    
  ATTRIBUTE_022,  -- NET_AMOUNT    
  ATTRIBUTE_023,  -- VAT_AMOUNT    
  ATTRIBUTE_024,  -- GROSS_AMOUNT    
  ATTRIBUTE_030,  -- EXTERNAL_ID    
  ATTRIBUTE_031   -- SOLD_AGAINST_CURRICULUM_CREDITS    
 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA   WITH(NOLOCK)  
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID    
  AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_IT    
  AND SEQ_ID IN (SELECT DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ','))    
    
 OPEN CUS_SALES    
    
 FETCH NEXT FROM CUS_SALES INTO     
  @SEQ_ID,    
  @ATTRIBUTE_001,    
  @ATTRIBUTE_002,    
  @ATTRIBUTE_003,     
  @ATTRIBUTE_004,     
  @ATTRIBUTE_005,     
  @ATTRIBUTE_008,     
  @ATTRIBUTE_009,     
  @ATTRIBUTE_011,     
  @ATTRIBUTE_012,     
  @ATTRIBUTE_013,     
  @ATTRIBUTE_014,     
  @ATTRIBUTE_015,     
  @ATTRIBUTE_016,     
  @ATTRIBUTE_017,     
  @ATTRIBUTE_018,     
  @ATTRIBUTE_019,     
  @ATTRIBUTE_020,     
  @ATTRIBUTE_021,     
  @ATTRIBUTE_022,     
  @ATTRIBUTE_023,     
  @ATTRIBUTE_024,     
  @ATTRIBUTE_030,     
  @ATTRIBUTE_031    
    
 SET @DISCOUNT_AMOUNT = 0    
 SET @FINANCE_TRANSACTION_NET_AMOUNT = 0    
 SET @FINANCE_TRANSACTION_VAT_AMOUNT = 0    
 SET @FINANCE_TRANSACTION_GROSS_AMOUNT = 0    
    
 WHILE @@FETCH_STATUS = 0    
 BEGIN    
  EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 11, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @PIVOT_NEXT_ID OUTPUT    
    
  -- VAT RATE For given Product    
  SET @VAT_PERCENTAGE = 0    
    
  SELECT @VAT_RATE = ATTRIBUTE_005   
  FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH(NOLOCK)  
  WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT   
  AND SEQ_ID = @ATTRIBUTE_005    
    
  PRINT '@VAT_RATE ' + CAST(@VAT_RATE AS NVARCHAR(100))    
  IF ISNULL(@VAT_RATE, '') <> ''    
  BEGIN    
   SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_VAT_RATE    
     
   SELECT @VAT_PERCENTAGE = ATTRIBUTE_006   
   FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA   
   WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID   
   AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE   
   AND SEQ_ID = @VAT_RATE      
     
  END    
  PRINT '@VAT_PERCENTAGE ' + CAST(@VAT_PERCENTAGE AS NVARCHAR(100))    
    
  PRINT 'START ADD DATA IN FINANCE_TRANSACTION_DETAIL'    
    
  PRINT 'START CHECKING DISCOUNT CODE'    
  IF ISNULL(@DISCOUNT_CODE_DESCRIPTION,'') <> ''    
  BEGIN    
   SET @DISCOUNT_PERC = 0    
    
   PRINT 'QUERY DISCOUNT PERCENTAGE' 
    
   SELECT @DISCOUNT_PERC = CAST(CAST(ATTRIBUTE_004 AS MONEY) AS BIGINT)
   FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA   
   WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID     
   AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE   
   --AND ATTRIBUTE_001 = @DISCOUNT_CODE_DESCRIPTION    
   AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID   
         FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)  
         WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE  
         AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=55217  
         AND ISNULL(ATTRIBUTE_STRING,'')=@DISCOUNT_CODE_DESCRIPTION  
         )  
   
   PRINT 'END QUERY DISCOUNT PERCENTAGE' 
     
   IF ISNULL(@DISCOUNT_PERC,0) > 0    
   BEGIN    
    PRINT '@DISCOUNT_PERC ' + CAST(@DISCOUNT_PERC AS NVARCHAR)    
    
    SET @ATTRIBUTE_017 =  CAST(@ATTRIBUTE_022 AS MONEY)     
    SET @ATTRIBUTE_019 =  CAST(@ATTRIBUTE_022 AS MONEY)     
    SET @TOTAL_AMOUNT = CAST(@ATTRIBUTE_022 AS MONEY)       
    SET @ATTRIBUTE_020 = CAST(@DISCOUNT_PERC AS NVARCHAR)
    SET @ATTRIBUTE_021 = ROUND(@TOTAL_AMOUNT * @DISCOUNT_PERC / 100, 2)    
    
    IF CAST(@ATTRIBUTE_024 AS MONEY) = CAST(@ATTRIBUTE_022 AS MONEY)    
    BEGIN    
     PRINT '1st Case'    
     SET @ATTRIBUTE_022 = CAST(@TOTAL_AMOUNT AS MONEY) - CAST(@ATTRIBUTE_021 AS MONEY)    
     SET @ATTRIBUTE_024 = @ATTRIBUTE_022    
     IF CAST(ISNULL(@ATTRIBUTE_023,0) AS MONEY) > 0    
      SET @ATTRIBUTE_023 = ROUND(CAST(@ATTRIBUTE_022 AS MONEY) * @VAT_PERCENTAGE / 100, 2)    
    END    
    ELSE IF CAST(@ATTRIBUTE_024 AS MONEY) = CAST(@ATTRIBUTE_022 AS MONEY) + CAST(@ATTRIBUTE_023 AS MONEY)    
    BEGIN    
     PRINT '2nd Case'    
     SET @ATTRIBUTE_022 = CAST(@TOTAL_AMOUNT AS MONEY) - CAST(@ATTRIBUTE_021 AS MONEY)    
     PRINT '@ATTRIBUTE_023 ' + @ATTRIBUTE_023    
     IF CAST(ISNULL(@ATTRIBUTE_023,0) AS MONEY) > 0    
      SET @ATTRIBUTE_023 = ROUND(CAST(@ATTRIBUTE_022 AS MONEY) * @VAT_PERCENTAGE / 100, 2)    
     SET @ATTRIBUTE_024 = CAST(@ATTRIBUTE_022 AS MONEY) + CAST(@ATTRIBUTE_023 AS MONEY)    
    END    
    
    PRINT '@TOTAL_AMOUNT ' + CAST(@TOTAL_AMOUNT AS NVARCHAR(100))    
    PRINT '@DISCOUNT_AMOUNT ' + CAST(@ATTRIBUTE_021 AS NVARCHAR(100))    
    PRINT '@PAYMENT_AMOUNT_NET ' + @ATTRIBUTE_022    
    PRINT '@PAYMENT_AMOUNT_VAT ' + @ATTRIBUTE_023    
    PRINT '@PAYMENT_AMOUNT ' + @ATTRIBUTE_024    
   END    
  END    
  PRINT 'END CHECKING DISCOUNT CODE '    
    
  -- ADD DATA IN FINANCE_TRANSACTION_DETAIL    
  EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]    
   @ATTRIBUTE_001 = @PIVOT_NEXT_ID, --TRANSACTION_NUMBER    
   @ATTRIBUTE_002 = @FINANCE_TRANSACTION_SEQ_ID, --FINANCE_TRANSACTION    
   @ATTRIBUTE_003 = @TRANSACTION_ID, --FINANCE_TRANSACTION_NAME    
   @ATTRIBUTE_004 = @ATTRIBUTE_002, --MODULE    
   @ATTRIBUTE_005 = @ATTRIBUTE_003, --MODULE_DESCRIPTION    
   @ATTRIBUTE_008 = @ATTRIBUTE_012, --LEDGER_ACCOUNT    
   @ATTRIBUTE_009 = @ATTRIBUTE_013, --LEDGER_ACCOUNT_NAME    
   @ATTRIBUTE_010 = @ATTRIBUTE_014, --VAT_RATE    
   @ATTRIBUTE_011 = @ATTRIBUTE_015, --VAT_RATE_NAME    
   @ATTRIBUTE_012 = @ATTRIBUTE_016, --VAT_PERCENTAGE    
   @ATTRIBUTE_013 = @ATTRIBUTE_017, --UNIT_PRICE    
   @ATTRIBUTE_014 = @ATTRIBUTE_018, --QUANTITY    
   @ATTRIBUTE_015 = @ATTRIBUTE_019, --TOTAL_PRICE    
   @ATTRIBUTE_016 = @ATTRIBUTE_020, --DISCOUNT_PERCENTAGE    
   @ATTRIBUTE_017 = @ATTRIBUTE_021, --DISCOUNT_AMOUNT    
   @ATTRIBUTE_018 = @ATTRIBUTE_022, --NET_AMOUNT    
   @ATTRIBUTE_019 = @ATTRIBUTE_023, --VAT_AMOUNT    
   @ATTRIBUTE_020 = @ATTRIBUTE_024, --GROSS_AMOUNT    
   @ATTRIBUTE_021 = NULL, --REMARKS    
   @ATTRIBUTE_022 = @ATTRIBUTE_005, --PRODUCT    
   @ATTRIBUTE_023 = @ATTRIBUTE_001, --PRODUCT_NAME    
   @ATTRIBUTE_024 = NULL, --ORDER_NUMBER    
   @ATTRIBUTE_025 = NULL, --PRICE_TYPE    
   @ATTRIBUTE_026 = NULL, --PRICE_TYPE_DESCRIPTION    
   @ATTRIBUTE_027 = @ATTRIBUTE_031, --SOLD_AGAINST_CURRICULUM_CREDITS    
   @ATTRIBUTE_028 = @SEQ_ID, --INVOICE_TRANSACTION    
   @ATTRIBUTE_029 = @ATTRIBUTE_001, --INVOICE_TRANSACTION_NAME    
   @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_FTD,    
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
   @DATE_CREATED = @TODAY,    
   @CREATED_BY = @USER,    
   @RETURN_SEQ_ID = @FINANCE_TRANSACTION_DETAIL_SEQ_ID OUTPUT    
    
  SET @DISCOUNT_AMOUNT = @DISCOUNT_AMOUNT + ISNULL(@ATTRIBUTE_021, 0)    
    
  PRINT 'END START ADD DATA IN FINANCE_TRANSACTION_DETAIL'    
    
  UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
   SET ATTRIBUTE_026 = @TRANSACTION_STATUS_POSTED,    
    ATTRIBUTE_027 = @TRANSACTION_STATUS_POSTED_DESCRIPTION,    
    DATE_MODIFIED = @TODAY,    
    MODIFIED_BY = @USER    
   WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID   
   AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_IT   
   AND SEQ_ID = @SEQ_ID    
    
  EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
   @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_IT,    
   @CUS_ENTITY_DATA_SEQ_ID = @SEQ_ID,    
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
   @ERROR = @ERROR OUTPUT,    
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
    
    
  FETCH NEXT FROM CUS_SALES INTO     
   @SEQ_ID,    
   @ATTRIBUTE_001,    
   @ATTRIBUTE_002,    
   @ATTRIBUTE_003,     
   @ATTRIBUTE_004,     
   @ATTRIBUTE_005,     
   @ATTRIBUTE_008,     
   @ATTRIBUTE_009,     
   @ATTRIBUTE_011,     
   @ATTRIBUTE_012,     
   @ATTRIBUTE_013,     
   @ATTRIBUTE_014,     
   @ATTRIBUTE_015,     
   @ATTRIBUTE_016,     
   @ATTRIBUTE_017,     
   @ATTRIBUTE_018,     
   @ATTRIBUTE_019,     
   @ATTRIBUTE_020,     
   @ATTRIBUTE_021,     
   @ATTRIBUTE_022,     
   @ATTRIBUTE_023,     
   @ATTRIBUTE_024,     
   @ATTRIBUTE_030,     
   @ATTRIBUTE_031    
 END    
 CLOSE CUS_SALES    
 DEALLOCATE CUS_SALES    
    
 --UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
 --SET ATTRIBUTE_038 = @DISCOUNT_AMOUNT,    
 -- DATE_MODIFIED = @TODAY,    
 -- MODIFIED_BY = @USER    
 --WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM AND SEQ_ID = @WEB_SERVICE_PRODUCT_SALE_MASTER    
    
 --EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
 -- @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSPSM,    
 -- @CUS_ENTITY_DATA_SEQ_ID = @WEB_SERVICE_PRODUCT_SALE_MASTER,    
 -- @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
 -- @ERROR = @ERROR OUTPUT,    
 -- @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
    
 PRINT 'SET TOTALS IN INVOICE ...'    
 SELECT @DISCOUNT_AMOUNT =  ISNULL(SUM(CAST(ATTRIBUTE_017 AS MONEY)),0), @FINANCE_TRANSACTION_NET_AMOUNT =  ISNULL(SUM(CAST(ATTRIBUTE_018 AS MONEY)),0),     
 @FINANCE_TRANSACTION_VAT_AMOUNT =  ISNULL(SUM(CAST(ATTRIBUTE_019 AS MONEY)),0), @FINANCE_TRANSACTION_GROSS_AMOUNT =  ISNULL(SUM(CAST(ATTRIBUTE_020 AS MONEY)),0)    
 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA      
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID   
 AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_FTD   
 --AND ATTRIBUTE_002 = @FINANCE_TRANSACTION_SEQ_ID    
 AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID   
        FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)  
        WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_FTD  
        AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =54709  
        AND ISNULL(ATTRIBUTE_DECIMAL,0)=@FINANCE_TRANSACTION_SEQ_ID   
          )  
    
    
 UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA     
 SET ATTRIBUTE_038 = @DISCOUNT_AMOUNT,    
  ATTRIBUTE_037 = @FINANCE_TRANSACTION_GROSS_AMOUNT,    
  ATTRIBUTE_039 = @FINANCE_TRANSACTION_NET_AMOUNT,    
  ATTRIBUTE_040 = @FINANCE_TRANSACTION_VAT_AMOUNT,    
  ATTRIBUTE_041 = @FINANCE_TRANSACTION_GROSS_AMOUNT,    
  ATTRIBUTE_046 = @FINANCE_TRANSACTION_GROSS_AMOUNT,    
  ATTRIBUTE_050 = CAST(@FINANCE_TRANSACTION_GROSS_AMOUNT AS MONEY) - CAST(ISNULL(ATTRIBUTE_057, 0) AS MONEY) ,    
  DATE_MODIFIED = @TODAY,    
  MODIFIED_BY = @USER    
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID   
 AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_FT   
 AND SEQ_ID = @FINANCE_TRANSACTION_SEQ_ID    
    
 EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]    
  @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_FT,    
  @CUS_ENTITY_DATA_SEQ_ID = @FINANCE_TRANSACTION_SEQ_ID,    
  @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
  @ERROR = @ERROR OUTPUT,    
  @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
    
 SET @ERROR = 0    
 SET @ERROR_DESCRIPTION = ''    
    
 PRINT 'END OF SP [dbo].[GET_CREATE_FINANCE_BATCH]'    
    
END    
    



;








-- =============================================
-- Author:		<Adeel Hassan>
-- Create date: <03/09/2013>
