-- =============================================
CREATE PROCEDURE [dbo].[GET_CREATE_FINANCE_BATCH_EVENT]
	-- Add the parameters for the stored procedure here
	@EXTERNAL_ID NVARCHAR(100) = NULL,
	@ACCOUNT BIGINT = NULL,
	@ACCOUNT_NAME NVARCHAR(100) = NULL,
	@CONTACT BIGINT = NULL,
	@CONTACT_NAME NVARCHAR(100) = NULL,
	@EVENT_REGISTRATION BIGINT = NULL,
	@EVENT_REGISTRATION_NAME NVARCHAR(100) = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@FINANCE_TRANSACTION_SEQ_ID BIGINT = NULL OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_FINANCE_BATCH_EVENT]'

	DECLARE @TODAY NVARCHAR(10)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @TODAY_INCLUDING_TIME DATETIME 

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_IT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_FT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_FTD BIGINT
	
	DECLARE @ENTITY_DISPLAY_NAME_WSEBM NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_IT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_FT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_FTD NVARCHAR(100)

	DECLARE @TRANSACTION_AMOUNT MONEY
	DECLARE @DISCOUNT_AMOUNT MONEY
	DECLARE @FINANCE_TRANSACTION_NET_AMOUNT MONEY
	DECLARE @FINANCE_TRANSACTION_VAT_AMOUNT MONEY
	DECLARE @FINANCE_TRANSACTION_GROSS_AMOUNT MONEY

	DECLARE @NET_AMOUNT MONEY
	DECLARE @VAT_AMOUNT MONEY
	DECLARE @GROSS_AMOUNT MONEY

	DECLARE @MODULE BIGINT
	DECLARE @MODULE_DESCRIPTION NVARCHAR(100)

	DECLARE @TRANSACTION_STATUS BIGINT
	DECLARE @TRANSACTION_STATUS_DESCRIPTION NVARCHAR(100)
	
	DECLARE @TRANSACTION_STATUS_POSTED BIGINT
	DECLARE @TRANSACTION_STATUS_POSTED_DESCRIPTION NVARCHAR(100)

	DECLARE @TRANSACTION_TYPE BIGINT
	DECLARE @TRANSACTION_TYPE_DESCRIPTION NVARCHAR(100)

	DECLARE @WEB_SERVICE_EVENT_BOOKING_MASTER BIGINT
	DECLARE @WEB_SERVICE_PRODUCT_SALE_MASTER_DESCRIPTION NVARCHAR(100)

	DECLARE @PAYMENT_AMOUNT MONEY
	DECLARE @TOTAL_VOUCHER_AMOUNT MONEY
	DECLARE @CURRICULUM_CREDITS_USED CHAR(1)
	DECLARE @FINANCE_TRANSACTION_DETAIL_SEQ_ID BIGINT
	DECLARE @PIVOT_NEXT_ID BIGINT
	DECLARE @PIVOT_RETURN_VALUE NVARCHAR(MAX)
	DECLARE @SEQ_ID BIGINT
	DECLARE @TRANSACTION_ID NVARCHAR(30) 

	DECLARE @ORGANISATION_NAME  NVARCHAR(100)
	DECLARE @ADDRESS_LINE_1  NVARCHAR(100)
	DECLARE @ADDRESS_LINE_2  NVARCHAR(100)
	DECLARE @ADDRESS_LINE_3  NVARCHAR(100)
	DECLARE @ADDRESS_LINE_4  NVARCHAR(100)
	DECLARE @ADDRESS_LINE_5  NVARCHAR(100)
	DECLARE @ADDRESS_POSTCODE  NVARCHAR(100)
	DECLARE @ORG_ADDRESS_LINE_1  NVARCHAR(100)
	DECLARE @ORG_ADDRESS_LINE_2  NVARCHAR(100)
	DECLARE @ORG_ADDRESS_LINE_3  NVARCHAR(100)
	DECLARE @ORG_ADDRESS_LINE_4  NVARCHAR(100)
	DECLARE @ORG_ADDRESS_LINE_5  NVARCHAR(100)
	DECLARE @ORG_POSTCODE  NVARCHAR(100)
	DECLARE @PURCHASE_ORDER_NUMBER  NVARCHAR(100)
	DECLARE @DISCOUNT_CODE  BIGINT
	DECLARE @DISCOUNT_CODE_DESCRIPTION  NVARCHAR(100)
	DECLARE @ADDRESS_COUNTY  NVARCHAR(100)
	DECLARE @ADDRESS_COUNTRY  NVARCHAR(100)
	DECLARE @ORG_ADDRESS_COUNTY  NVARCHAR(100)
	DECLARE @ORG_ADDRESS_COUNTRY  NVARCHAR(100)
	DECLARE @PREFERRED_MAILING_ADDRESS  NVARCHAR(100)
	DECLARE @PREFERRED_BILLING_ADDRESS  NVARCHAR(100)
	DECLARE @JOB_TITLE  NVARCHAR(100)

	--
	DECLARE @MAILING_ACCOUNT_NAME NVARCHAR(100)
	DECLARE @MAILING_JOB_TITLE NVARCHAR(100)
	DECLARE @MAILING_ADDRESS_1 NVARCHAR(100)
	DECLARE @MAILING_ADDRESS_2 NVARCHAR(100)
	DECLARE @MAILING_ADDRESS_3 NVARCHAR(100)
	DECLARE @MAILING_ADDRESS_4 NVARCHAR(100)
	DECLARE @MAILING_ADDRESS_5 NVARCHAR(100)
	DECLARE @MAILING_POSTCODE NVARCHAR(100)
	DECLARE @MAILING_COUNTY BIGINT
	DECLARE @MAILING_COUNTY_DESCRIPTION NVARCHAR(100)
	DECLARE @MAILING_COUNTRY BIGINT
	DECLARE @MAILING_COUNTRY_DESCRIPTION NVARCHAR(100)

	DECLARE @BILLING_ACCOUNT_NAME NVARCHAR(100)
	DECLARE @BILLING_JOB_TITLE NVARCHAR(100)
	DECLARE @BILLING_ADDRESS_1 NVARCHAR(100)
	DECLARE @BILLING_ADDRESS_2 NVARCHAR(100)
	DECLARE @BILLING_ADDRESS_3 NVARCHAR(100)
	DECLARE @BILLING_ADDRESS_4 NVARCHAR(100)
	DECLARE @BILLING_ADDRESS_5 NVARCHAR(100)
	DECLARE @BILLING_POSTCODE NVARCHAR(100)
	DECLARE @BILLING_COUNTY BIGINT
	DECLARE @BILLING_COUNTY_DESCRIPTION NVARCHAR(100)
	DECLARE @BILLING_COUNTRY BIGINT
	DECLARE @BILLING_COUNTRY_DESCRIPTION NVARCHAR(100)
	--

	DECLARE @ATTRIBUTE_001  NVARCHAR(100)
	DECLARE @ATTRIBUTE_002  NVARCHAR(100)
	DECLARE @ATTRIBUTE_003  NVARCHAR(100)
	DECLARE @ATTRIBUTE_004  NVARCHAR(100)
	DECLARE @ATTRIBUTE_005  NVARCHAR(100)
	DECLARE @ATTRIBUTE_008  NVARCHAR(100)
	DECLARE @ATTRIBUTE_009  NVARCHAR(100)
	DECLARE @ATTRIBUTE_011  NVARCHAR(100)
	DECLARE @ATTRIBUTE_012  NVARCHAR(100)
	DECLARE @ATTRIBUTE_013  NVARCHAR(100)
	DECLARE @ATTRIBUTE_014  NVARCHAR(100)
	DECLARE @ATTRIBUTE_015  NVARCHAR(100)
	DECLARE @ATTRIBUTE_016  NVARCHAR(100)
	DECLARE @ATTRIBUTE_017  NVARCHAR(100)
	DECLARE @ATTRIBUTE_018  NVARCHAR(100)
	DECLARE @ATTRIBUTE_019  NVARCHAR(100)
	DECLARE @ATTRIBUTE_020  NVARCHAR(100)
	DECLARE @ATTRIBUTE_021  NVARCHAR(100)
	DECLARE @ATTRIBUTE_022  NVARCHAR(100)
	DECLARE @ATTRIBUTE_023  NVARCHAR(100)
	DECLARE @ATTRIBUTE_024  NVARCHAR(100)
	DECLARE @ATTRIBUTE_030  NVARCHAR(100)
	DECLARE @ATTRIBUTE_031  NVARCHAR(100)
--

	DECLARE @DISCOUNT_PERC BIGINT
	DECLARE @TOTAL_AMOUNT MONEY
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_DISCOUNT_CODE NVARCHAR(200)
	DECLARE @EVENT_ID NVARCHAR(100)
	DECLARE @VAT_RATE NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_EVENT NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_VAT_RATE NVARCHAR(100)
	DECLARE @VAT_PERCENTAGE MONEY
	DECLARE @PAY_BY_INVOICE NVARCHAR(1)
	DECLARE @EVENT BigInt
	DECLARE @EVENT_NAME NVarChar(100)

	SET @ENTITY_DISPLAY_NAME_WSEBM = 'WEB_SERVICE_EVENT_BOOKING_MASTER'
	SET @ENTITY_DISPLAY_NAME_IT = 'INVOICE_TRANSACTION'
	SET @ENTITY_DISPLAY_NAME_FT = 'FINANCE_TRANSACTION'
	SET @ENTITY_DISPLAY_NAME_FTD = 'FINANCE_TRANSACTION_DETAIL'
	SET @ENTITY_DISPLAY_NAME_EVENT = 'EVENT'
	SET @ENTITY_DISPLAY_NAME_VAT_RATE = 'VAT_RATE'
	SET @ENTITY_DISPLAY_NAME_DISCOUNT_CODE = 'DISCOUNT_CODE'
			
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSEBM
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_IT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_IT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_FT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_FT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_FTD = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_FTD
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EVENT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_VAT_RATE
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_DISCOUNT_CODE = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_DISCOUNT_CODE
	
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSEBM, @ATTRIBUTE_DISPLAY_NAME = 'BOOKING_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @EXTERNAL_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @WEB_SERVICE_EVENT_BOOKING_MASTER OUTPUT, @DESCRIPTION = @WEB_SERVICE_PRODUCT_SALE_MASTER_DESCRIPTION OUTPUT

	
	SELECT 
		@EVENT_ID = ATTRIBUTE_018,
		@PAYMENT_AMOUNT = ATTRIBUTE_017, 
		@TRANSACTION_AMOUNT = ATTRIBUTE_038,
		@NET_AMOUNT = ATTRIBUTE_038,
		@VAT_AMOUNT = ATTRIBUTE_039,
		@ORGANISATION_NAME = ATTRIBUTE_019,
		@ADDRESS_LINE_1 = ATTRIBUTE_007,
		@ADDRESS_LINE_2 = ATTRIBUTE_008,
		@ADDRESS_LINE_3 = ATTRIBUTE_009,
		@ADDRESS_LINE_4 = ATTRIBUTE_010,
		@ADDRESS_LINE_5 = ATTRIBUTE_011,
		@ADDRESS_POSTCODE = ATTRIBUTE_012,
		@ORG_ADDRESS_LINE_1 = ATTRIBUTE_022,
		@ORG_ADDRESS_LINE_2 = ATTRIBUTE_023,
		@ORG_ADDRESS_LINE_3 = ATTRIBUTE_024,
		@ORG_ADDRESS_LINE_4 = ATTRIBUTE_025,
		@ORG_ADDRESS_LINE_5 = ATTRIBUTE_026,
		@ORG_POSTCODE = ATTRIBUTE_027,
		@PURCHASE_ORDER_NUMBER = ATTRIBUTE_033,
		@DISCOUNT_CODE_DESCRIPTION = ATTRIBUTE_037,
		@ADDRESS_COUNTY = ATTRIBUTE_013,
		@ADDRESS_COUNTRY = ATTRIBUTE_036,
		@ORG_ADDRESS_COUNTY = ATTRIBUTE_028,
		@ORG_ADDRESS_COUNTRY = ATTRIBUTE_029,
		@PREFERRED_MAILING_ADDRESS = ATTRIBUTE_030,
		@PREFERRED_BILLING_ADDRESS = ATTRIBUTE_031,
		@JOB_TITLE = ATTRIBUTE_020,
		@PAY_BY_INVOICE = ATTRIBUTE_032,
		@MAILING_ACCOUNT_NAME = ATTRIBUTE_046,
		@MAILING_JOB_TITLE = ATTRIBUTE_047,
		@MAILING_ADDRESS_1 = ATTRIBUTE_048,
		@MAILING_ADDRESS_2 = ATTRIBUTE_049,
		@MAILING_ADDRESS_3 = ATTRIBUTE_050,
		@MAILING_ADDRESS_4 = ATTRIBUTE_051,
		@MAILING_ADDRESS_5 = ATTRIBUTE_052,
		@MAILING_COUNTY_DESCRIPTION = ATTRIBUTE_053,
		@MAILING_COUNTRY_DESCRIPTION = ATTRIBUTE_054,
		@BILLING_ACCOUNT_NAME = ATTRIBUTE_055,
		@BILLING_JOB_TITLE = ATTRIBUTE_056,
		@BILLING_ADDRESS_1 = ATTRIBUTE_057,
		@BILLING_ADDRESS_2 = ATTRIBUTE_058,
		@BILLING_ADDRESS_3 = ATTRIBUTE_059,
		@BILLING_ADDRESS_4 = ATTRIBUTE_060,
		@BILLING_ADDRESS_5 = ATTRIBUTE_061,
		@BILLING_COUNTY_DESCRIPTION = ATTRIBUTE_062,
		@BILLING_COUNTRY_DESCRIPTION = ATTRIBUTE_063,
		@BILLING_POSTCODE = ATTRIBUTE_064,
		@MAILING_POSTCODE = ATTRIBUTE_065
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	 AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSEBM 
	 AND SEQ_ID = @WEB_SERVICE_EVENT_BOOKING_MASTER

	SET @GROSS_AMOUNT = ISNULL(@NET_AMOUNT, 0) + ISNULL(@VAT_AMOUNT, 0)

	IF ISNULL(@MAILING_ADDRESS_1, '') = ''
	BEGIN
		IF (@PREFERRED_MAILING_ADDRESS = '0' OR @PREFERRED_MAILING_ADDRESS = 'HOME')
		BEGIN
			SET @MAILING_ADDRESS_1 = @ADDRESS_LINE_1
			SET @MAILING_ADDRESS_2 = @ADDRESS_LINE_2
			SET @MAILING_ADDRESS_3 = @ADDRESS_LINE_3
			SET @MAILING_ADDRESS_4 = @ADDRESS_LINE_4
			SET @MAILING_ADDRESS_5 = @ADDRESS_LINE_5
			SET @MAILING_POSTCODE = @ADDRESS_POSTCODE
			SET @MAILING_COUNTY_DESCRIPTION = @ADDRESS_COUNTY
			SET @MAILING_COUNTRY_DESCRIPTION = @ADDRESS_COUNTRY
		END
		ELSE
		BEGIN
			SET @MAILING_ACCOUNT_NAME = @ORGANISATION_NAME
			SET @MAILING_JOB_TITLE = @JOB_TITLE
			SET @MAILING_ADDRESS_1 = @ORG_ADDRESS_LINE_1
			SET @MAILING_ADDRESS_2 = @ORG_ADDRESS_LINE_2
			SET @MAILING_ADDRESS_3 = @ORG_ADDRESS_LINE_3
			SET @MAILING_ADDRESS_4 = @ORG_ADDRESS_LINE_4
			SET @MAILING_ADDRESS_5 = @ORG_ADDRESS_LINE_5
			SET @MAILING_POSTCODE = @ORG_POSTCODE
			SET @MAILING_COUNTY_DESCRIPTION = @ORG_ADDRESS_COUNTY
			SET @MAILING_COUNTRY_DESCRIPTION = @ORG_ADDRESS_COUNTRY
		END
	END

	IF ISNULL(@BILLING_ADDRESS_1, '') = ''
	BEGIN
		IF (@PREFERRED_BILLING_ADDRESS = '0' OR @PREFERRED_BILLING_ADDRESS = 'HOME')
		BEGIN
			SET @BILLING_ADDRESS_1 = @ADDRESS_LINE_1
			SET @BILLING_ADDRESS_2 = @ADDRESS_LINE_2
			SET @BILLING_ADDRESS_3 = @ADDRESS_LINE_3
			SET @BILLING_ADDRESS_4 = @ADDRESS_LINE_4
