	AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52318 AND ISNULL(ATTRIBUTE_STRING,'')=@EVENT_ID)
	
	IF ISNULL(@VAT_RATE, '') <> ''
