		WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_VAT_RATE 
