--			GOTO TRY_AGAIN
    
		DECLARE @UNIQUE_INDEX_ID_EVENT BIGINT = 22
		EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = @UNIQUE_INDEX_ID_EVENT, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @PIVOT_NEXT_ID OUTPUT , @ERROR = @ERROR OUTPUT, @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT    
