CREATE PROCEDURE [dbo].[GET_CREATE_MENU_CHILDREN]
	@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID BIGINT,
	@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 BIGINT,
	@FROM_SRM_CLIENTS_SEQ_ID BIGINT,
	@TO_SRM_CLIENTS_SEQ_ID BIGINT
AS
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT
	DECLARE @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2_OLD BIGINT

	--SELECT SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID FROM SRM_CLIENT_MENU_RELATIONSHIPS WHERE SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID 

	DECLARE CUR_MENU_CHILD CURSOR STATIC LOCAL FOR
	SELECT SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID FROM SRM_CLIENT_MENU_RELATIONSHIPS WHERE SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID 

	OPEN CUR_MENU_CHILD 

	FETCH NEXT FROM CUR_MENU_CHILD INTO @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT 'SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID = ' + CAST(@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID AS NVARCHAR)
		PRINT 'SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 = ' + CAST(@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 AS NVARCHAR)

		SET @SRM_CLIENT_ENTITIES_SEQ_ID2 = NULL

		IF ISNULL(@SRM_CLIENT_ENTITIES_SEQ_ID, 0) <> 0
		BEGIN
			SELECT @SRM_CLIENT_ENTITIES_SEQ_ID2 = SRM_CLIENT_COPY_LOG.SRM_CLIENT_ENTITIES_SEQ_ID_NEW 
			FROM [SRM-ClientCopyLog].DBO.SRM_CLIENT_COPY_LOG
			WHERE 
				SRM_CLIENT_COPY_LOG.SRM_CLIENTS_SEQ_ID_OLD = @FROM_SRM_CLIENTS_SEQ_ID
				AND SRM_CLIENT_COPY_LOG.SRM_CLIENTS_SEQ_ID_NEW = @TO_SRM_CLIENTS_SEQ_ID
				AND SRM_CLIENT_COPY_LOG.SRM_CLIENT_ENTITIES_SEQ_ID_OLD = @SRM_CLIENT_ENTITIES_SEQ_ID
		END

		INSERT INTO SRM_CLIENT_MENU_RELATIONSHIPS
		(
			DESCRIPTION,
			SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID,
			SRM_CLIENT_ENTITIES_SEQ_ID,
			MENU_URL,
			SETTINGS,
			VISIBLE,
			RANK,
			MENU_TYPE_ID,
			SRM_CLIENTS_SEQ_ID,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT 
			DESCRIPTION,
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2,
			@SRM_CLIENT_ENTITIES_SEQ_ID2,
			MENU_URL,
			SETTINGS,
			VISIBLE,
			RANK,
			MENU_TYPE_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			null,
			null,
			DATE_MODIFIED,
			'dbuser',
			DATE_CREATED,
			'dbuser',
			'N',
			DATE_DELETED,
			DELETED_BY
		FROM SRM_CLIENT_MENU_RELATIONSHIPS 
		WHERE SEQ_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID
		
		SET @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2_OLD = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2
		SET @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 = @@IDENTITY

		INSERT INTO [SRM-ClientCopyLog].DBO.SRM_CLIENT_COPY_LOG
		(
			LOG_TYPE_ID,
			LOG_TYPE_DESCRIPTION,
			SRM_CLIENTS_SEQ_ID_OLD,
			SRM_CLIENTS_SEQ_ID_NEW,
			ATTRIBUTE_01,
			ATTRIBUTE_02
		)
		SELECT
			4,
			'MENU RELATIONSHIP',
			@FROM_SRM_CLIENTS_SEQ_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID,
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2

		INSERT INTO SRM_CLIENT_LANGUAGE_ITEMS
		(
			SRM_LANGUAGES_SEQ_ID,
			SRM_CLIENTS_SEQ_ID,
			OBJECT_ID,
			OBJECT_TYPE,
			SRM_LANGUAGE_TOKENS_SEQ_ID,
			PHRASE,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT
			SRM_LANGUAGES_SEQ_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2,
			OBJECT_TYPE,
			SRM_LANGUAGE_TOKENS_SEQ_ID,
			PHRASE,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		FROM SRM_CLIENT_LANGUAGE_ITEMS 
		WHERE OBJECT_TYPE = 47
		AND OBJECT_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID

		EXEC DBO.GET_CREATE_MENU_CHILDREN 
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, 
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2, 
			@FROM_SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID, 
			@TO_SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID

		SET @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2_OLD

		FETCH NEXT FROM CUR_MENU_CHILD INTO @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID

	END
		
	CLOSE CUR_MENU_CHILD 
	DEALLOCATE CUR_MENU_CHILD 




;





