-- EXEC DBO.GET_CREATE_MENU_COPY @FROM_SRM_CLIENTS_SEQ_ID = 1, @TO_SRM_CLIENTS_SEQ_ID = 15



CREATE PROCEDURE [dbo].[GET_CREATE_MENU_COPY]
	@FROM_SRM_CLIENTS_SEQ_ID BIGINT,
	@TO_SRM_CLIENTS_SEQ_ID BIGINT
AS

	DECLARE @FROM_SRM_USERS_SEQ_ID BIGINT
	DECLARE @TO_SRM_USERS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT

	DELETE FROM SRM_CLIENT_MENU_RELATIONSHIPS WHERE SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID OR SRM_CLIENTS_SEQ_ID IS NULL
	DELETE FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID AND OBJECT_ID = 47

	DECLARE CUR_MENU CURSOR STATIC LOCAL FOR
		SELECT SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID FROM SRM_CLIENT_MENU_RELATIONSHIPS WHERE ISNULL(SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, 0) = 0 AND SRM_CLIENT_MENU_RELATIONSHIPS.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID 

	OPEN CUR_MENU 

	FETCH NEXT FROM CUR_MENU INTO @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @SRM_CLIENT_ENTITIES_SEQ_ID2 = NULL

		IF ISNULL(@SRM_CLIENT_ENTITIES_SEQ_ID, 0) <> 0
		BEGIN
			SELECT @SRM_CLIENT_ENTITIES_SEQ_ID2 = SRM_CLIENT_COPY_LOG.SRM_CLIENT_ENTITIES_SEQ_ID_NEW 
			FROM [SRM-ClientCopyLog].DBO.SRM_CLIENT_COPY_LOG
			WHERE 
				SRM_CLIENT_COPY_LOG.SRM_CLIENTS_SEQ_ID_OLD = @FROM_SRM_CLIENTS_SEQ_ID
				AND SRM_CLIENT_COPY_LOG.SRM_CLIENTS_SEQ_ID_NEW = @TO_SRM_CLIENTS_SEQ_ID
				AND SRM_CLIENT_COPY_LOG.SRM_CLIENT_ENTITIES_SEQ_ID_OLD = @SRM_CLIENT_ENTITIES_SEQ_ID
		END

		INSERT INTO SRM_CLIENT_MENU_RELATIONSHIPS
		(
			DESCRIPTION,
			SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID,
			SRM_CLIENT_ENTITIES_SEQ_ID,
			MENU_URL,
			SETTINGS,
			VISIBLE,
			RANK,
			MENU_TYPE_ID,
			SRM_CLIENTS_SEQ_ID,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY,
			SYSTEM_NAME,
			SYSTEM_MODULE,
			DISPLY_ON_MOBILE ,
			SHOW_ON_MOBILE ,
			ICON 
		)
		SELECT 
			DESCRIPTION,
			SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID,
			@SRM_CLIENT_ENTITIES_SEQ_ID2,
			MENU_URL,
			SETTINGS,
			VISIBLE,
			RANK,
			MENU_TYPE_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			null,
			null,
			DATE_MODIFIED,
			'dbuser',
			DATE_CREATED,
			'dbuser',
			'N',
			DATE_DELETED,
			DELETED_BY,
			SYSTEM_NAME,
			SYSTEM_MODULE,
			DISPLY_ON_MOBILE ,
			SHOW_ON_MOBILE ,
			ICON 
		FROM SRM_CLIENT_MENU_RELATIONSHIPS 
		WHERE SEQ_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID

		SET @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 = @@IDENTITY


		INSERT INTO [SRM-ClientCopyLog].DBO.SRM_CLIENT_COPY_LOG
		(
			LOG_TYPE_ID,
			LOG_TYPE_DESCRIPTION,
			SRM_CLIENTS_SEQ_ID_OLD,
			SRM_CLIENTS_SEQ_ID_NEW,
			ATTRIBUTE_01,
			ATTRIBUTE_02
		)
		SELECT
			4,
			'MENU RELATIONSHIP',
			@FROM_SRM_CLIENTS_SEQ_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID,
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2

		INSERT INTO SRM_CLIENT_LANGUAGE_ITEMS
		(
			SRM_LANGUAGES_SEQ_ID,
			SRM_CLIENTS_SEQ_ID,
			OBJECT_ID,
			OBJECT_TYPE,
			SRM_LANGUAGE_TOKENS_SEQ_ID,
			PHRASE,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT
			SRM_LANGUAGES_SEQ_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2,
			OBJECT_TYPE,
			SRM_LANGUAGE_TOKENS_SEQ_ID,
			PHRASE,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		FROM SRM_CLIENT_LANGUAGE_ITEMS 
		WHERE OBJECT_TYPE = 47
		AND OBJECT_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID

		EXEC DBO.GET_CREATE_MENU_CHILDREN 
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, 
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2, 
			@FROM_SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID, 
			@TO_SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID

		FETCH NEXT FROM CUR_MENU INTO @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID
	END

	CLOSE CUR_MENU 
	DEALLOCATE CUR_MENU 
	




;





-- AUTHOR : RAUF GILL
-- DATA : 30/07/2013

CREATE PROCEDURE [dbo].[GET_CREATE_MENU_COPY_ACCROSS_SERVER]
	@FROM_SRM_CLIENTS_SEQ_ID BIGINT=NULL,
	@TO_SRM_CLIENTS_SEQ_ID BIGINT=NULL
AS

	DECLARE @FROM_SRM_USERS_SEQ_ID BIGINT
	DECLARE @TO_SRM_USERS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID2 BIGINT

	DELETE FROM SRM_CLIENT_MENU_RELATIONSHIPS WHERE SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID OR SRM_CLIENTS_SEQ_ID IS NULL
	DELETE FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID AND OBJECT_ID = 47

	DECLARE CUR_MENU CURSOR STATIC LOCAL FOR
		SELECT SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID FROM [SRM-Framework_New_NI]..SRM_CLIENT_MENU_RELATIONSHIPS WHERE ISNULL(SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, 0) = 0 
		AND SRM_CLIENT_MENU_RELATIONSHIPS.SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID 

	OPEN CUR_MENU 

	FETCH NEXT FROM CUR_MENU INTO @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @SRM_CLIENT_ENTITIES_SEQ_ID2 = NULL

		IF ISNULL(@SRM_CLIENT_ENTITIES_SEQ_ID, 0) <> 0
		BEGIN
			SELECT @SRM_CLIENT_ENTITIES_SEQ_ID2 = SRM_CLIENT_COPY_LOG.SRM_CLIENT_ENTITIES_SEQ_ID_NEW 
			FROM [SRM-ClientCopyLog].DBO.SRM_CLIENT_COPY_LOG
			WHERE 
				SRM_CLIENT_COPY_LOG.SRM_CLIENTS_SEQ_ID_OLD = @FROM_SRM_CLIENTS_SEQ_ID
				AND SRM_CLIENT_COPY_LOG.SRM_CLIENTS_SEQ_ID_NEW = @TO_SRM_CLIENTS_SEQ_ID
				AND SRM_CLIENT_COPY_LOG.SRM_CLIENT_ENTITIES_SEQ_ID_OLD = @SRM_CLIENT_ENTITIES_SEQ_ID
		END

		INSERT INTO SRM_CLIENT_MENU_RELATIONSHIPS
		(
			DESCRIPTION,
			SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID,
			SRM_CLIENT_ENTITIES_SEQ_ID,
			MENU_URL,
			SETTINGS,
			VISIBLE,
			RANK,
			MENU_TYPE_ID,
			SRM_CLIENTS_SEQ_ID,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY,
			SYSTEM_MODULE
		)
		SELECT 
			DESCRIPTION,
			SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID,
			@SRM_CLIENT_ENTITIES_SEQ_ID2,
			MENU_URL,
			SETTINGS,
			VISIBLE,
			RANK,
			MENU_TYPE_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			null,
			null,
			DATE_MODIFIED,
			'dbuser',
			DATE_CREATED,
			'dbuser',
			'N',
			DATE_DELETED,
			DELETED_BY,
			SYSTEM_MODULE
		FROM [SRM-Framework_New_NI]..SRM_CLIENT_MENU_RELATIONSHIPS 
		WHERE SEQ_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID

		SET @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 = @@IDENTITY


		INSERT INTO [SRM-ClientCopyLog].DBO.SRM_CLIENT_COPY_LOG
		(
			LOG_TYPE_ID,
			LOG_TYPE_DESCRIPTION,
			SRM_CLIENTS_SEQ_ID_OLD,
			SRM_CLIENTS_SEQ_ID_NEW,
			ATTRIBUTE_01,
			ATTRIBUTE_02
		)
		SELECT
			4,
			'MENU RELATIONSHIP',
			@FROM_SRM_CLIENTS_SEQ_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID,
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2

		INSERT INTO SRM_CLIENT_LANGUAGE_ITEMS
		(
			SRM_LANGUAGES_SEQ_ID,
			SRM_CLIENTS_SEQ_ID,
			OBJECT_ID,
			OBJECT_TYPE,
			SRM_LANGUAGE_TOKENS_SEQ_ID,
			PHRASE,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		)
		SELECT
			SRM_LANGUAGES_SEQ_ID,
			@TO_SRM_CLIENTS_SEQ_ID,
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2,
			OBJECT_TYPE,
			SRM_LANGUAGE_TOKENS_SEQ_ID,
			PHRASE,
			SOURCE_OF_DATA,
			SOURCE_FILE,
			DATE_MODIFIED,
			MODIFIED_BY,
			DATE_CREATED,
			CREATED_BY,
			DELETED,
			DATE_DELETED,
			DELETED_BY
		FROM [SRM-Framework_New_NI]..SRM_CLIENT_LANGUAGE_ITEMS 
		WHERE OBJECT_TYPE = 47
		AND OBJECT_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID

		EXEC DBO.GET_CREATE_MENU_CHILDREN_ACCROSS_SERVER 
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, 
			@SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2 = @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID2, 
			@FROM_SRM_CLIENTS_SEQ_ID = @FROM_SRM_CLIENTS_SEQ_ID, 
			@TO_SRM_CLIENTS_SEQ_ID = @TO_SRM_CLIENTS_SEQ_ID

		FETCH NEXT FROM CUR_MENU INTO @SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID
	END

	CLOSE CUR_MENU 
	DEALLOCATE CUR_MENU 
	




;








