CREATE PROCEDURE [dbo].[GET_CREATE_RECEIPT_BATCH]
	-- Add the parameters for the stored procedure here
	@EXTERNAL_ID NVARCHAR(100) = NULL,
	@ACCOUNT BIGINT = NULL,
	@ACCOUNT_NAME NVARCHAR(100) = NULL,
	@CONTACT BIGINT = NULL,
	@CONTACT_NAME NVARCHAR(100) = NULL,
	@PAYMENT_AMOUNT MONEY = NULL,
	@FINANCE_TRANSACTION_SEQ_ID BIGINT = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@PAYMENT_BATCH_TRANSACTION_SEQ_ID BIGINT = NULL OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_RECEIPT_BATCH]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PBT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PTD BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_FT BIGINT
	
	DECLARE @ENTITY_DISPLAY_NAME_PBT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_PTD NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_FT NVARCHAR(100)

	DECLARE @TRANSACTION_ID BIGINT
	DECLARE @PAYMENT_BATCH_TRANSACTION_ID BIGINT
	DECLARE @PAYMENT_TRANSACTION_DETAIL_SEQ_ID BIGINT

	DECLARE @MODULE BIGINT
	DECLARE @MODULE_DESCRIPTION NVARCHAR(100)

	DECLARE @PIVOT_NEXT_ID BIGINT

	DECLARE @TRANSACTION_STATUS BIGINT
	DECLARE @TRANSACTION_STATUS_DESCRIPTION NVARCHAR(100)

	DECLARE @TRANSACTION_TYPE BIGINT
	DECLARE @TRANSACTION_TYPE_DESCRIPTION NVARCHAR(100)
	
	DECLARE @PAYMENT_METHOD BigInt
	DECLARE @PAYMENT_METHOD_NAME NVARCHAR(100)

	DECLARE @FINANCE_TRANSACTION_DESCRIPTION NVARCHAR(30)

	SET @ENTITY_DISPLAY_NAME_PBT = 'PAYMENT_BATCH_TRANSACTION'
	SET @ENTITY_DISPLAY_NAME_PTD = 'PAYMENT_TRANSACTION_DETAIL'
	SET @ENTITY_DISPLAY_NAME_FT = 'FINANCE_TRANSACTION'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PBT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PBT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PTD = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PTD
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_FT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_FT


	EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 5, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @PIVOT_NEXT_ID OUTPUT
	SET @PAYMENT_BATCH_TRANSACTION_ID = @PIVOT_NEXT_ID

	-- FINANCE TRANSACTION
	SELECT @FINANCE_TRANSACTION_DESCRIPTION = ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_FT AND SEQ_ID = @FINANCE_TRANSACTION_SEQ_ID

	-- GET MODULE
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MODULE', @ATTRIBUTE_DISPLAY_NAME = 'PRODUCT_SALE', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MODULE OUTPUT, @DESCRIPTION = @MODULE_DESCRIPTION OUTPUT

	-- GET FINANCE_TRANSACTION_STATUS
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'FINANCE_TRANSACTION_STATUS', @ATTRIBUTE_DISPLAY_NAME = 'CURRENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @TRANSACTION_STATUS OUTPUT, @DESCRIPTION = @TRANSACTION_STATUS_DESCRIPTION OUTPUT

	-- GET TRANSACTION_TYPE
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'TRANSACTION_TYPE', @ATTRIBUTE_DISPLAY_NAME = 'PAYMENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @TRANSACTION_TYPE OUTPUT, @DESCRIPTION = @TRANSACTION_TYPE_DESCRIPTION OUTPUT
	
	-- GET PAYMENT METHOD
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_METHOD', @ATTRIBUTE_DISPLAY_NAME = 'ONLINE', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_METHOD OUTPUT, @DESCRIPTION = @PAYMENT_METHOD_NAME OUTPUT


	-- ADD DATA IN PAYMENT_BATCH_TRANSACTION
	EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
		@ATTRIBUTE_001 = @PAYMENT_BATCH_TRANSACTION_ID, --TRANSACTION_ID
		@ATTRIBUTE_006 = NULL, --REFERENCE
		@ATTRIBUTE_007 = @PAYMENT_AMOUNT, --AMOUNT
		@ATTRIBUTE_008 = NULL, --REMARKS
		@ATTRIBUTE_010 = NULL, --MODULE_DESCRIPTION
		@ATTRIBUTE_011 = NULL, --BATCH_ID
		@ATTRIBUTE_012 = NULL, --BATCH_ID_NAME
		@ATTRIBUTE_013 = @ACCOUNT, --ACCOUNT
		@ATTRIBUTE_014 = @ACCOUNT_NAME, --ACCOUNT_NAME
		@ATTRIBUTE_015 = @CONTACT, --CONTACT
		@ATTRIBUTE_016 = @CONTACT_NAME, --CONTACT_NAME
		@ATTRIBUTE_017 = @MODULE, --MODULE
		@ATTRIBUTE_018 = @MODULE_DESCRIPTION, --MODULE_DESCRIPTION
		@ATTRIBUTE_019 = @TRANSACTION_STATUS, --FINANCE_TRANSACTION_STATUS
		@ATTRIBUTE_020 = @TRANSACTION_STATUS_DESCRIPTION, --FINANCE_TRANSACTION_STATUS_NAME
		@ATTRIBUTE_021 = @TODAY, --TRANSACTION_DATE
		@ATTRIBUTE_022 = @TRANSACTION_TYPE, --TRANSACTION_TYPE
		@ATTRIBUTE_023 = @TRANSACTION_TYPE_DESCRIPTION, --TRANSACTION_TYPE_NAME
		@ATTRIBUTE_024 = @PAYMENT_METHOD,
		@ATTRIBUTE_025 = @PAYMENT_METHOD_NAME,
		@ATTRIBUTE_026 = @EXTERNAL_ID,
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PBT,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@DATE_CREATED = NULL,
		@CREATED_BY = @USER,
		@RETURN_SEQ_ID = @PAYMENT_BATCH_TRANSACTION_SEQ_ID OUTPUT


	EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 12, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @PIVOT_NEXT_ID OUTPUT
	SET @TRANSACTION_ID = @PIVOT_NEXT_ID

		-- ADD DATA IN PAYMENT_TRANSACTION_DETAIL
	EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
		@ATTRIBUTE_001 = @TRANSACTION_ID, --TRANSACTION_ID
		@ATTRIBUTE_002 = @PAYMENT_BATCH_TRANSACTION_SEQ_ID, --PAYMENT_TRANSACTION
		@ATTRIBUTE_003 = @PAYMENT_BATCH_TRANSACTION_ID, --PAYMENT_TRANSACTION_NAME
		@ATTRIBUTE_004 = @MODULE, --MODULE
		@ATTRIBUTE_005 = @MODULE_DESCRIPTION, --MODULE_DESCRIPTION
		@ATTRIBUTE_006 = @FINANCE_TRANSACTION_SEQ_ID, --FINANCE_TRANSACTION
		@ATTRIBUTE_007 = @FINANCE_TRANSACTION_DESCRIPTION, --FINANCE_TRANSACTION_NAME
		@ATTRIBUTE_008 = NULL, --PRODUCT
		@ATTRIBUTE_009 = NULL, --PRODUCT_NAME
		@ATTRIBUTE_010 = @PAYMENT_AMOUNT, --AMOUNT
		@ATTRIBUTE_011 = NULL, --RATE_TYPE
		@ATTRIBUTE_012 = NULL, --RATE_TYPE_NAME
		@ATTRIBUTE_013 = NULL, --DONATION_TYPE
		@ATTRIBUTE_014 = NULL, --DONATION_TYPE_NAME
		@ATTRIBUTE_015 = NULL, --APPEAL
		@ATTRIBUTE_016 = NULL, --APPEAL_NAME
		@ATTRIBUTE_017 = NULL, --PROJECT
		@ATTRIBUTE_018 = NULL, --PROJECT_NAME
		@ATTRIBUTE_019 = NULL, --PLEDGE
		@ATTRIBUTE_020 = NULL, --PLEDGE_NAME
		@ATTRIBUTE_021 = NULL, --NAME_SUB
		@ATTRIBUTE_022 = NULL, --THANKYOU_LETTER
		@ATTRIBUTE_023 = NULL, --THANKYOU_LETTER_DESCRIPTION
		@ATTRIBUTE_024 = NULL, --REMARKS
		@ATTRIBUTE_025 = NULL, --EVENT
		@ATTRIBUTE_026 = null, --EVENT_NAME
		@ATTRIBUTE_027 = NULL, --TAX_PAYER
		@ATTRIBUTE_028 = NULL, --GIFT_AID_APPLICABLE
		@ATTRIBUTE_029 = NULL, --GIFT_AID_REFUSED
		@ATTRIBUTE_030 = NULL, --GIFT_AID_DECLARATION_GIVEN
		@ATTRIBUTE_031 = NULL, --GIFT_AID_DECLARATION_METHOD
		@ATTRIBUTE_032 = NULL, --GIFT_AID_DECLARATION_METHOD_DESCRIPTION
		@ATTRIBUTE_033 = NULL, --GIFT_AID_DECLARATION_VALID_FROM_DATE
		@ATTRIBUTE_034 = NULL, --GIFT_AID_DECLARATION_VALID_UNTIL_DATE
		@ATTRIBUTE_035 = NULL, --GIFT_AID_CONFIRMATION_LETTER_DATE
		@ATTRIBUTE_036 = NULL, --GIFT_AID_ORAL_CONFIRMATION_DATE
		@ATTRIBUTE_037 = NULL, --UPDATE_MAIN_RECORD
		@ATTRIBUTE_038 = @ACCOUNT, --ACCOUNT
		@ATTRIBUTE_039 = @ACCOUNT_NAME, --ACCOUNT_NAME
		@ATTRIBUTE_040 = @CONTACT, --CONTACT
		@ATTRIBUTE_041 = @CONTACT_NAME, --CONTACT_NAME
		@ATTRIBUTE_042 = NULL, --REGULAR_GIVING
		@ATTRIBUTE_043 = NULL, --REGULAR_GIVING_NAME
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PTD,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@DATE_CREATED = NULL,
		@CREATED_BY = @USER,
		@RETURN_SEQ_ID = @PAYMENT_TRANSACTION_DETAIL_SEQ_ID OUTPUT

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''

END






;





