-- Author:		<Adeel Hassan>
-- Create date: <04/09/2013,,>
-- Description:	<Receipt for Events>
-- =============================================
CREATE PROCEDURE [dbo].[GET_CREATE_RECEIPT_BATCH_EVENT]
	-- Add the parameters for the stored procedure here
	@EXTERNAL_ID NVARCHAR(100) = NULL,
	@ACCOUNT BIGINT = NULL,
	@ACCOUNT_NAME NVARCHAR(100) = NULL,
	@CONTACT BIGINT = NULL,
	@CONTACT_NAME NVARCHAR(100) = NULL,
	@FINANCE_TRANSACTION_SEQ_ID BIGINT = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@PAYMENT_BATCH_TRANSACTION_SEQ_ID BIGINT = NULL OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_RECEIPT_BATCH]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @PAYMENT_AMOUNT MONEY
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PBT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PTD BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_FT BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EBM BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_EBD BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_EBM_SEQ_ID BIGINT

	DECLARE @ENTITY_DISPLAY_NAME_PBT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_PTD NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_FT NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_EBM NVARCHAR(100)
	DECLARE @ENTITY_DISPLAY_NAME_EBD NVARCHAR(100)

	DECLARE @TRANSACTION_ID BIGINT
	DECLARE @PAYMENT_BATCH_TRANSACTION_ID BIGINT
	DECLARE @PAYMENT_TRANSACTION_DETAIL_SEQ_ID BIGINT

	DECLARE @MODULE BIGINT
	DECLARE @MODULE_DESCRIPTION NVARCHAR(100)

	DECLARE @PIVOT_NEXT_ID BIGINT

	DECLARE @TRANSACTION_STATUS BIGINT
	DECLARE @TRANSACTION_STATUS_DESCRIPTION NVARCHAR(100)

	DECLARE @TRANSACTION_TYPE BIGINT
	DECLARE @TRANSACTION_TYPE_DESCRIPTION NVARCHAR(100)

	DECLARE @PAYMENT_METHOD BigInt
	DECLARE @PAYMENT_METHOD_NAME NVARCHAR(100)
	
	DECLARE @FINANCE_TRANSACTION_ID NVARCHAR(30)

	SET @ENTITY_DISPLAY_NAME_PBT = 'PAYMENT_BATCH_TRANSACTION'
	SET @ENTITY_DISPLAY_NAME_PTD = 'PAYMENT_TRANSACTION_DETAIL'
	SET @ENTITY_DISPLAY_NAME_FT = 'FINANCE_TRANSACTION'
	SET @ENTITY_DISPLAY_NAME_EBM = 'WEB_SERVICE_EVENT_BOOKING_MASTER'
	SET @ENTITY_DISPLAY_NAME_EBD = 'WEB_SERVICE_EVENT_BOOKING_DETAIL'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PBT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PBT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PTD = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PTD
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_FT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_FT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EBM = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EBM
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_EBD = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_EBD


	EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 5, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @PIVOT_NEXT_ID OUTPUT
	SET @PAYMENT_BATCH_TRANSACTION_ID = @PIVOT_NEXT_ID

	-- FINANCE TRANSACTION
	SELECT @FINANCE_TRANSACTION_ID = ATTRIBUTE_001 
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_FT 
	AND SEQ_ID = @FINANCE_TRANSACTION_SEQ_ID

	-- Payment Amount
	SET @PAYMENT_AMOUNT = 0
	
	SELECT @SRM_CLIENT_ENTITIES_EBM_SEQ_ID = SEQ_ID 
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EBM 
	--AND ATTRIBUTE_035 = @EXTERNAL_ID
	AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EBM AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56279 AND ISNULL(ATTRIBUTE_STRING,'')=@EXTERNAL_ID)
	
	SELECT @PAYMENT_AMOUNT = @PAYMENT_AMOUNT + ISNULL(SUM(CAST(ATTRIBUTE_032 AS MONEY)),0) 
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EBD 
	--AND ATTRIBUTE_027 = @EXTERNAL_ID
	AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EBD AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56716 AND ISNULL(ATTRIBUTE_STRING,'')=@EXTERNAL_ID)

	PRINT '@PAYMENT_AMOUNT ' + CAST(@PAYMENT_AMOUNT AS NVARCHAR(100))

	-- GET MODULE
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MODULE', @ATTRIBUTE_DISPLAY_NAME = 'EVENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MODULE OUTPUT, @DESCRIPTION = @MODULE_DESCRIPTION OUTPUT

	-- GET FINANCE_TRANSACTION_STATUS
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'FINANCE_TRANSACTION_STATUS', @ATTRIBUTE_DISPLAY_NAME = 'CURRENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @TRANSACTION_STATUS OUTPUT, @DESCRIPTION = @TRANSACTION_STATUS_DESCRIPTION OUTPUT

	-- GET TRANSACTION_TYPE
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'TRANSACTION_TYPE', @ATTRIBUTE_DISPLAY_NAME = 'PAYMENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @TRANSACTION_TYPE OUTPUT, @DESCRIPTION = @TRANSACTION_TYPE_DESCRIPTION OUTPUT

	-- GET PAYMENT METHOD
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_METHOD', @ATTRIBUTE_DISPLAY_NAME = 'ONLINE', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_METHOD OUTPUT, @DESCRIPTION = @PAYMENT_METHOD_NAME OUTPUT

	-- ADD DATA IN PAYMENT_BATCH_TRANSACTION
	EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
		@ATTRIBUTE_001 = @PAYMENT_BATCH_TRANSACTION_ID, --TRANSACTION_ID
		@ATTRIBUTE_006 = NULL, --REFERENCE
		@ATTRIBUTE_007 = @PAYMENT_AMOUNT, --AMOUNT
		@ATTRIBUTE_008 = NULL, --REMARKS
		@ATTRIBUTE_010 = NULL, --MODULE_DESCRIPTION
		@ATTRIBUTE_011 = '4258535', --BATCH_ID
		@ATTRIBUTE_012 = '1', --BATCH_ID_NAME
		@ATTRIBUTE_013 = @ACCOUNT, --ACCOUNT
		@ATTRIBUTE_014 = @ACCOUNT_NAME, --ACCOUNT_NAME
		@ATTRIBUTE_015 = @CONTACT, --CONTACT
		@ATTRIBUTE_016 = @CONTACT_NAME, --CONTACT_NAME
		@ATTRIBUTE_017 = @MODULE, --MODULE
		@ATTRIBUTE_018 = @MODULE_DESCRIPTION, --MODULE_DESCRIPTION
		@ATTRIBUTE_019 = @TRANSACTION_STATUS, --FINANCE_TRANSACTION_STATUS
		@ATTRIBUTE_020 = @TRANSACTION_STATUS_DESCRIPTION, --FINANCE_TRANSACTION_STATUS_NAME
		@ATTRIBUTE_021 = @TODAY, --TRANSACTION_DATE
		@ATTRIBUTE_022 = @TRANSACTION_TYPE, --TRANSACTION_TYPE
		@ATTRIBUTE_023 = @TRANSACTION_TYPE_DESCRIPTION, --TRANSACTION_TYPE_NAME
		@ATTRIBUTE_024 = @PAYMENT_METHOD,
		@ATTRIBUTE_025 = @PAYMENT_METHOD_NAME,
		@ATTRIBUTE_026 = @SRM_CLIENT_ENTITIES_EBM_SEQ_ID, -- @SRM_CLIENT_ENTITIES_EBM_SEQ_ID AS EXTERNAL_ID
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PBT,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@DATE_CREATED = NULL,
		@CREATED_BY = @USER,
		@RETURN_SEQ_ID = @PAYMENT_BATCH_TRANSACTION_SEQ_ID OUTPUT


	EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 12, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @PIVOT_NEXT_ID OUTPUT
	SET @TRANSACTION_ID = @PIVOT_NEXT_ID

		-- ADD DATA IN PAYMENT_TRANSACTION_DETAIL
	EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
		@ATTRIBUTE_001 = @TRANSACTION_ID, --TRANSACTION_ID
		@ATTRIBUTE_002 = @PAYMENT_BATCH_TRANSACTION_SEQ_ID, --PAYMENT_TRANSACTION
		@ATTRIBUTE_003 = @PAYMENT_BATCH_TRANSACTION_ID, --PAYMENT_TRANSACTION_NAME
		@ATTRIBUTE_004 = @MODULE, --MODULE
		@ATTRIBUTE_005 = @MODULE_DESCRIPTION, --MODULE_DESCRIPTION
		@ATTRIBUTE_006 = @FINANCE_TRANSACTION_SEQ_ID, --FINANCE_TRANSACTION
		@ATTRIBUTE_007 = @FINANCE_TRANSACTION_ID, --FINANCE_TRANSACTION_ID
		@ATTRIBUTE_008 = NULL, --PRODUCT
		@ATTRIBUTE_009 = NULL, --PRODUCT_NAME
		@ATTRIBUTE_010 = @PAYMENT_AMOUNT, --AMOUNT
		@ATTRIBUTE_011 = NULL, --RATE_TYPE
		@ATTRIBUTE_012 = NULL, --RATE_TYPE_NAME
		@ATTRIBUTE_013 = NULL, --DONATION_TYPE
		@ATTRIBUTE_014 = NULL, --DONATION_TYPE_NAME
		@ATTRIBUTE_015 = NULL, --APPEAL
		@ATTRIBUTE_016 = NULL, --APPEAL_NAME
		@ATTRIBUTE_017 = NULL, --PROJECT
		@ATTRIBUTE_018 = NULL, --PROJECT_NAME
		@ATTRIBUTE_019 = NULL, --PLEDGE
		@ATTRIBUTE_020 = NULL, --PLEDGE_NAME
		@ATTRIBUTE_021 = NULL, --NAME_SUB
		@ATTRIBUTE_022 = NULL, --THANKYOU_LETTER
		@ATTRIBUTE_023 = NULL, --THANKYOU_LETTER_DESCRIPTION
		@ATTRIBUTE_024 = NULL, --REMARKS
		@ATTRIBUTE_025 = NULL, --EVENT
		@ATTRIBUTE_026 = NULL, --EVENT_NAME
		@ATTRIBUTE_027 = NULL, --TAX_PAYER
		@ATTRIBUTE_028 = NULL, --GIFT_AID_APPLICABLE
		@ATTRIBUTE_029 = NULL, --GIFT_AID_REFUSED
		@ATTRIBUTE_030 = NULL, --GIFT_AID_DECLARATION_GIVEN
		@ATTRIBUTE_031 = NULL, --GIFT_AID_DECLARATION_METHOD
		@ATTRIBUTE_032 = NULL, --GIFT_AID_DECLARATION_METHOD_DESCRIPTION
		@ATTRIBUTE_033 = NULL, --GIFT_AID_DECLARATION_VALID_FROM_DATE
		@ATTRIBUTE_034 = NULL, --GIFT_AID_DECLARATION_VALID_UNTIL_DATE
		@ATTRIBUTE_035 = NULL, --GIFT_AID_CONFIRMATION_LETTER_DATE
		@ATTRIBUTE_036 = NULL, --GIFT_AID_ORAL_CONFIRMATION_DATE
		@ATTRIBUTE_037 = NULL, --UPDATE_MAIN_RECORD
		@ATTRIBUTE_038 = @ACCOUNT, --ACCOUNT
		@ATTRIBUTE_039 = @ACCOUNT_NAME, --ACCOUNT_NAME
		@ATTRIBUTE_040 = @CONTACT, --CONTACT
		@ATTRIBUTE_041 = @CONTACT_NAME, --CONTACT_NAME
		@ATTRIBUTE_042 = NULL, --REGULAR_GIVING
		@ATTRIBUTE_043 = NULL, --REGULAR_GIVING_NAME
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PTD,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@DATE_CREATED = NULL,
		@CREATED_BY = @USER,
		@RETURN_SEQ_ID = @PAYMENT_TRANSACTION_DETAIL_SEQ_ID OUTPUT


	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''

END



;





-- =============================================
-- Author:  <Rauf Gill>    
-- Create date: <08/08/2013,,>    
-- Description: <Apply Product Sales Data to sTarget,,>    
-- =============================================    
    
CREATE PROCEDURE [dbo].[GET_CREATE_RECEIPT_BATCH_MEMBERSHIP]    
 -- Add the parameters for the stored procedure here    
 @EXTERNAL_RECORD_ID NVARCHAR(100) = NULL,    
 @MEMBER BIGINT = NULL,    
 @PAYMENT_AMOUNT MONEY = NULL,    
 @PAYMENT_METHOD BIGINT = NULL,    
 @PAYMENT_METHOD_NAME NVARCHAR(100) = NULL,    
 @USER NVARCHAR(100) = NULL,    
 @SRM_CLIENTS_SEQ_ID BIGINT = NULL,    
 @PAYMENT_BATCH_TRANSACTION_SEQ_ID BIGINT = NULL OUTPUT,    
 @ERROR SMALLINT = NULL OUTPUT,    
 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT    
AS    
BEGIN    
 -- SET NOCOUNT ON added to prevent extra result sets from    
 -- interfering with SELECT statements.    
 SET NOCOUNT ON;    
    
 SET @ERROR = 1    
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_RECEIPT_BATCH_MEMBERSHIP]'    
    
 DECLARE @TODAY NVARCHAR(30)    
 SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)    
    
 DECLARE @ACCOUNT BIGINT     
 DECLARE @ACCOUNT_NAME NVARCHAR(100)     
 DECLARE @CONTACT BIGINT     
 DECLARE @CONTACT_NAME NVARCHAR(100)    
    
    
    
 DECLARE @RATE_TYPE NVARCHAR(100)    
 DECLARE @RATE_TYPE_NAME NVARCHAR(100)    
 DECLARE @TOTAL_OUTSTANDING MONEY    
    
 DECLARE @TRANSACTION_ID BIGINT    
 DECLARE @PAYMENT_BATCH_TRANSACTION_ID BIGINT    
 DECLARE @PAYMENT_TRANSACTION_DETAIL_SEQ_ID BIGINT    
    
 DECLARE @MODULE BIGINT    
 DECLARE @MODULE_DESCRIPTION NVARCHAR(100)    
    
 DECLARE @PIVOT_NEXT_ID BIGINT    
    
 DECLARE @TRANSACTION_STATUS BIGINT    
 DECLARE @TRANSACTION_STATUS_DESCRIPTION NVARCHAR(100)    
    
 DECLARE @TRANSACTION_TYPE BIGINT    
 DECLARE @TRANSACTION_TYPE_DESCRIPTION NVARCHAR(100)    
    
 DECLARE @FINANCE_TRANSACTION_DESCRIPTION NVARCHAR(30)    
    
 DECLARE @ENTITY_DISPLAY_NAME_PBT NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PBT BIGINT    
 SET @ENTITY_DISPLAY_NAME_PBT = 'PAYMENT_BATCH_TRANSACTION'    
    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PTD BIGINT    
 DECLARE @ENTITY_DISPLAY_NAME_PTD NVARCHAR(100)    
 SET @ENTITY_DISPLAY_NAME_PTD = 'PAYMENT_TRANSACTION_DETAIL'    
    
 DECLARE @ENTITY_DISPLAY_NAME_MAR NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MAR BIGINT    
 SET @ENTITY_DISPLAY_NAME_MAR = 'MEMBER_ASSIGNED_RATE'    
    
 DECLARE @ENTITY_DISPLAY_NAME_MEMBER NVARCHAR(100)    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER BIGINT    
 SET @ENTITY_DISPLAY_NAME_MEMBER = 'MEMBER'    
    
 DECLARE @NEXT_RENEWAL_DATE NVARCHAR(100)    
 DECLARE @FISCAL_PERIOD NVARCHAR(10)    
    
 IF ISNULL(@PAYMENT_AMOUNT, 0) = 0    
 BEGIN    
  PRINT 'NO PAYMENT AMOUNT PRESENT'    
  SET @ERROR = 0    
  SET @ERROR_DESCRIPTION = ''    
  RETURN    
 END    
    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MEMBER    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MAR = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MAR    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PBT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PBT    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PTD = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PTD    
    
     
 SELECT @NEXT_RENEWAL_DATE = ATTRIBUTE_005 
 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
 AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
 AND SEQ_ID = @MEMBER    
 
 SET @FISCAL_PERIOD = CAST(MONTH(@NEXT_RENEWAL_DATE) AS NVARCHAR) + '/' + CAST((YEAR(@NEXT_RENEWAL_DATE) - 1) AS NVARCHAR)    
 PRINT '@FISCAL_PERIOD ' + ISNULL(@FISCAL_PERIOD,'NULL')    
    
    
 EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 5, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @PIVOT_NEXT_ID OUTPUT    
 SET @PAYMENT_BATCH_TRANSACTION_ID = @PIVOT_NEXT_ID    
    
 SELECT @ACCOUNT = ATTRIBUTE_015, @ACCOUNT_NAME = ATTRIBUTE_016, @CONTACT = ATTRIBUTE_017, @CONTACT_NAME = ATTRIBUTE_018 
 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
 AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
 AND SEQ_ID = @MEMBER    
     
 PRINT '@ACCOUNT = ' + ISNULL(CAST(@ACCOUNT AS NVARCHAR), '')    
 PRINT '@ACCOUNT_NAME = ' + ISNULL(@ACCOUNT_NAME, '')    
    
 PRINT '@CONTACT = ' + ISNULL(CAST(@CONTACT AS NVARCHAR), '')    
 PRINT '@CONTACT_NAME = ' + ISNULL(@CONTACT_NAME, '')    
    
    
 -- GET MODULE    
 EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MODULE', @ATTRIBUTE_DISPLAY_NAME = 'MEMBERSHIP', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MODULE OUTPUT, @DESCRIPTION = @MODULE_DESCRIPTION OUTPUT    
    
 -- GET FINANCE_TRANSACTION_STATUS    
 EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'FINANCE_TRANSACTION_STATUS', @ATTRIBUTE_DISPLAY_NAME = 'CURRENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @TRANSACTION_STATUS OUTPUT, @DESCRIPTION = @TRANSACTION_STATUS_DESCRIPTION OUTPUT    
    
 -- GET TRANSACTION_TYPE    
 EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'TRANSACTION_TYPE', @ATTRIBUTE_DISPLAY_NAME = 'PAYMENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @TRANSACTION_TYPE OUTPUT, @DESCRIPTION = @TRANSACTION_TYPE_DESCRIPTION OUTPUT    
    
 -- GET PAYMENT_METHOD    
 IF ISNULL(@PAYMENT_METHOD_NAME, '') = ''    
  EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'PAYMENT_METHOD', @ATTRIBUTE_DISPLAY_NAME = 'ONLINE', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PAYMENT_METHOD OUTPUT, @DESCRIPTION = @PAYMENT_METHOD_NAME OUTPUT    
    
 -- ADD DATA IN PAYMENT_BATCH_TRANSACTION    
 EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]    
  @ATTRIBUTE_001 = @PAYMENT_BATCH_TRANSACTION_ID, --TRANSACTION_ID    
  @ATTRIBUTE_006 = NULL, --REFERENCE    
  @ATTRIBUTE_007 = @PAYMENT_AMOUNT, --AMOUNT    
  @ATTRIBUTE_008 = NULL, --REMARKS    
  @ATTRIBUTE_010 = NULL, --MODULE_DESCRIPTION    
  @ATTRIBUTE_011 = '4258535', --BATCH_ID    
  @ATTRIBUTE_012 = '1', --BATCH_ID_NAME    
  @ATTRIBUTE_013 = @ACCOUNT, --ACCOUNT    
  @ATTRIBUTE_014 = @ACCOUNT_NAME, --ACCOUNT_NAME    
  @ATTRIBUTE_015 = @CONTACT, --CONTACT    
  @ATTRIBUTE_016 = @CONTACT_NAME, --CONTACT_NAME    
  @ATTRIBUTE_017 = @MODULE, --MODULE    
  @ATTRIBUTE_018 = @MODULE_DESCRIPTION, --MODULE_DESCRIPTION    
  @ATTRIBUTE_019 = @TRANSACTION_STATUS, --FINANCE_TRANSACTION_STATUS    
  @ATTRIBUTE_020 = @TRANSACTION_STATUS_DESCRIPTION, --FINANCE_TRANSACTION_STATUS_NAME    
  @ATTRIBUTE_021 = @TODAY, --TRANSACTION_DATE    
  @ATTRIBUTE_022 = @TRANSACTION_TYPE, --TRANSACTION_TYPE    
  @ATTRIBUTE_023 = @TRANSACTION_TYPE_DESCRIPTION, --TRANSACTION_TYPE_NAME    
  @ATTRIBUTE_024 = @PAYMENT_METHOD,    
  @ATTRIBUTE_025 = @PAYMENT_METHOD_NAME,    
  @ATTRIBUTE_026 = @EXTERNAL_RECORD_ID, -- EXTERNAL_ID    
  @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PBT,    
  @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
  @DATE_CREATED = NULL,    
  @CREATED_BY = @USER,    
  @RETURN_SEQ_ID = @PAYMENT_BATCH_TRANSACTION_SEQ_ID OUTPUT    
    
 DECLARE @MEMBER_ASSIGNED_RATE_SEQ_ID VARCHAR(50)

 DECLARE CUR_MR CURSOR LOCAL STATIC FOR     
 SELECT CAST(SEQ_ID AS VARCHAR(50)),ATTRIBUTE_008, ATTRIBUTE_009, ATTRIBUTE_010 , ATTRIBUTE_004
 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
 WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
 AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MAR 
 --AND ATTRIBUTE_002 = @MEMBER    
 AND SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID 
								 FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) 
								 WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MAR 
								 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =52152 
								 AND ISNULL(ATTRIBUTE_DECIMAL,0)=@MEMBER
								)
AND CAST(ATTRIBUTE_010 AS MONEY)>0
 
 OPEN CUR_MR     
    
 FETCH NEXT FROM CUR_MR INTO @MEMBER_ASSIGNED_RATE_SEQ_ID,@RATE_TYPE, @RATE_TYPE_NAME, @TOTAL_OUTSTANDING  , @FISCAL_PERIOD
    
 WHILE @@FETCH_STATUS = 0    
 BEGIN    
  IF ISNULL(@TOTAL_OUTSTANDING, 0) > 0    
  BEGIN    
   EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 12, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @PIVOT_NEXT_ID OUTPUT    
   SET @TRANSACTION_ID = @PIVOT_NEXT_ID    
    
    -- ADD DATA IN PAYMENT_TRANSACTION_DETAIL    
   EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]    
    @ATTRIBUTE_001 = @TRANSACTION_ID, --TRANSACTION_ID    
    @ATTRIBUTE_002 = @PAYMENT_BATCH_TRANSACTION_SEQ_ID, --PAYMENT_TRANSACTION    
    @ATTRIBUTE_003 = @PAYMENT_BATCH_TRANSACTION_ID, --PAYMENT_TRANSACTION_NAME    
    @ATTRIBUTE_004 = @MODULE, --MODULE    
    @ATTRIBUTE_005 = @MODULE_DESCRIPTION, --MODULE_DESCRIPTION    
    @ATTRIBUTE_006 = NULL, --FINANCE_TRANSACTION    
    @ATTRIBUTE_007 = NULL, --FINANCE_TRANSACTION_NAME    
    @ATTRIBUTE_008 = NULL, --PRODUCT    
    @ATTRIBUTE_009 = NULL, --PRODUCT_NAME    
    @ATTRIBUTE_010 = @TOTAL_OUTSTANDING, --AMOUNT    
    @ATTRIBUTE_011 = @RATE_TYPE, --RATE_TYPE    
    @ATTRIBUTE_012 = @RATE_TYPE_NAME, --RATE_TYPE_NAME    
    @ATTRIBUTE_013 = NULL, --DONATION_TYPE    
    @ATTRIBUTE_014 = NULL, --DONATION_TYPE_NAME    
    @ATTRIBUTE_015 = NULL, --APPEAL    
    @ATTRIBUTE_016 = NULL, --APPEAL_NAME    
    @ATTRIBUTE_017 = NULL, --PROJECT    
    @ATTRIBUTE_018 = NULL, --PROJECT_NAME    
    @ATTRIBUTE_019 = NULL, --PLEDGE    
    @ATTRIBUTE_020 = NULL, --PLEDGE_NAME    
    @ATTRIBUTE_021 = NULL, --NAME_SUB    
    @ATTRIBUTE_022 = NULL, --THANKYOU_LETTER    
    @ATTRIBUTE_023 = NULL, --THANKYOU_LETTER_DESCRIPTION    
    @ATTRIBUTE_024 = NULL, --REMARKS    
    @ATTRIBUTE_025 = NULL, --EVENT    
    @ATTRIBUTE_026 = NULL, --EVENT_NAME    
    @ATTRIBUTE_027 = NULL, --TAX_PAYER    
    @ATTRIBUTE_028 = NULL, --GIFT_AID_APPLICABLE    
    @ATTRIBUTE_029 = NULL, --GIFT_AID_REFUSED    
    @ATTRIBUTE_030 = NULL, --GIFT_AID_DECLARATION_GIVEN    
    @ATTRIBUTE_031 = NULL, --GIFT_AID_DECLARATION_METHOD    
    @ATTRIBUTE_032 = NULL, --GIFT_AID_DECLARATION_METHOD_DESCRIPTION    
    @ATTRIBUTE_033 = NULL, --GIFT_AID_DECLARATION_VALID_FROM_DATE    
    @ATTRIBUTE_034 = NULL, --GIFT_AID_DECLARATION_VALID_UNTIL_DATE    
    @ATTRIBUTE_035 = NULL, --GIFT_AID_CONFIRMATION_LETTER_DATE    
    @ATTRIBUTE_036 = NULL, --GIFT_AID_ORAL_CONFIRMATION_DATE    
    @ATTRIBUTE_037 = NULL, --UPDATE_MAIN_RECORD    
    @ATTRIBUTE_038 = @ACCOUNT, --ACCOUNT    
    @ATTRIBUTE_039 = @ACCOUNT_NAME, --ACCOUNT_NAME    
    @ATTRIBUTE_040 = @CONTACT, --CONTACT    
    @ATTRIBUTE_041 = @CONTACT_NAME, --CONTACT_NAME    
    @ATTRIBUTE_042 = NULL, --REGULAR_GIVING    
    @ATTRIBUTE_043 = NULL, --REGULAR_GIVING_NAME    
    @ATTRIBUTE_044 = @FISCAL_PERIOD,    
	@ATTRIBUTE_045 = @MEMBER_ASSIGNED_RATE_SEQ_ID,
	@ATTRIBUTE_046 = @RATE_TYPE_NAME,
    @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PTD,    
    @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,    
    @DATE_CREATED = NULL,    
    @CREATED_BY = @USER,    
    @RETURN_SEQ_ID = @PAYMENT_TRANSACTION_DETAIL_SEQ_ID OUTPUT    
  END    
  FETCH NEXT FROM CUR_MR INTO @MEMBER_ASSIGNED_RATE_SEQ_ID,@RATE_TYPE, @RATE_TYPE_NAME, @TOTAL_OUTSTANDING  , @FISCAL_PERIOD
 END    
 CLOSE CUR_MR     
 DEALLOCATE CUR_MR    
 SET @ERROR = 0    
 SET @ERROR_DESCRIPTION = ''    
    
END    
    
    



;






-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_CREATE_RECEIPT_BATCH_MEMBERSHIP_MEMBERSHIP]
	-- Add the parameters for the stored procedure here
	@EXTERNAL_RECORD_ID NVARCHAR(100) = NULL,
	@MEMBER BIGINT = NULL,
	@PAYMENT_AMOUNT MONEY = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@PAYMENT_BATCH_TRANSACTION_SEQ_ID BIGINT = NULL OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_RECEIPT_BATCH_MEMBERSHIP]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @ACCOUNT BIGINT 
	DECLARE @ACCOUNT_NAME NVARCHAR(100) 
	DECLARE @CONTACT BIGINT 
	DECLARE @CONTACT_NAME NVARCHAR(100)



	DECLARE @RATE_TYPE NVARCHAR(100)
	DECLARE @RATE_TYPE_NAME NVARCHAR(100)
	DECLARE @TOTAL_OUTSTANDING NVARCHAR(100)

	DECLARE @TRANSACTION_ID BIGINT
	DECLARE @PAYMENT_BATCH_TRANSACTION_ID BIGINT
	DECLARE @PAYMENT_TRANSACTION_DETAIL_SEQ_ID BIGINT

	DECLARE @MODULE BIGINT
	DECLARE @MODULE_DESCRIPTION NVARCHAR(100)

	DECLARE @PIVOT_NEXT_ID BIGINT

	DECLARE @TRANSACTION_STATUS BIGINT
	DECLARE @TRANSACTION_STATUS_DESCRIPTION NVARCHAR(100)

	DECLARE @TRANSACTION_TYPE BIGINT
	DECLARE @TRANSACTION_TYPE_DESCRIPTION NVARCHAR(100)

	DECLARE @FINANCE_TRANSACTION_DESCRIPTION NVARCHAR(30)

	DECLARE @ENTITY_DISPLAY_NAME_PBT NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PBT BIGINT
	SET @ENTITY_DISPLAY_NAME_PBT = 'PAYMENT_BATCH_TRANSACTION'

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PTD BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_PTD NVARCHAR(100)
	SET @ENTITY_DISPLAY_NAME_PTD = 'PAYMENT_TRANSACTION_DETAIL'

	DECLARE @ENTITY_DISPLAY_NAME_MAR NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MAR BIGINT
	SET @ENTITY_DISPLAY_NAME_MAR = 'MEMBER_ASSIGNED_RATE'

	DECLARE @ENTITY_DISPLAY_NAME_MEMBER NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER BIGINT
	SET @ENTITY_DISPLAY_NAME_MEMBER = 'MEMBER_master'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MEMBER
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MAR = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MAR
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PBT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PBT
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PTD = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PTD


	EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 5, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @PIVOT_NEXT_ID OUTPUT
	SET @PAYMENT_BATCH_TRANSACTION_ID = @PIVOT_NEXT_ID

	SELECT @ACCOUNT = ATTRIBUTE_015, @ACCOUNT_NAME = ATTRIBUTE_016, @CONTACT = ATTRIBUTE_017, @CONTACT_NAME = ATTRIBUTE_018 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER AND SEQ_ID = @MEMBER
	
	-- GET MODULE
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MODULE', @ATTRIBUTE_DISPLAY_NAME = 'MEMBERSHIP', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MODULE OUTPUT, @DESCRIPTION = @MODULE_DESCRIPTION OUTPUT

	-- GET FINANCE_TRANSACTION_STATUS
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'FINANCE_TRANSACTION_STATUS', @ATTRIBUTE_DISPLAY_NAME = 'CURRENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @TRANSACTION_STATUS OUTPUT, @DESCRIPTION = @TRANSACTION_STATUS_DESCRIPTION OUTPUT

	-- GET TRANSACTION_TYPE
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'TRANSACTION_TYPE', @ATTRIBUTE_DISPLAY_NAME = 'PAYMENT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @TRANSACTION_TYPE OUTPUT, @DESCRIPTION = @TRANSACTION_TYPE_DESCRIPTION OUTPUT


	-- ADD DATA IN PAYMENT_BATCH_TRANSACTION
	EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
		@ATTRIBUTE_001 = @PAYMENT_BATCH_TRANSACTION_ID, --TRANSACTION_ID
		@ATTRIBUTE_006 = NULL, --REFERENCE
		@ATTRIBUTE_007 = @PAYMENT_AMOUNT, --AMOUNT
		@ATTRIBUTE_008 = NULL, --REMARKS
		@ATTRIBUTE_010 = NULL, --MODULE_DESCRIPTION
		@ATTRIBUTE_011 = NULL, --BATCH_ID
		@ATTRIBUTE_012 = NULL, --BATCH_ID_NAME
		@ATTRIBUTE_013 = @ACCOUNT, --ACCOUNT
		@ATTRIBUTE_014 = @ACCOUNT_NAME, --ACCOUNT_NAME
		@ATTRIBUTE_015 = @CONTACT, --CONTACT
		@ATTRIBUTE_016 = @CONTACT_NAME, --CONTACT_NAME
		@ATTRIBUTE_017 = @MODULE, --MODULE
		@ATTRIBUTE_018 = @MODULE_DESCRIPTION, --MODULE_DESCRIPTION
		@ATTRIBUTE_019 = @TRANSACTION_STATUS, --FINANCE_TRANSACTION_STATUS
		@ATTRIBUTE_020 = @TRANSACTION_STATUS_DESCRIPTION, --FINANCE_TRANSACTION_STATUS_NAME
		@ATTRIBUTE_021 = @TODAY, --TRANSACTION_DATE
		@ATTRIBUTE_022 = @TRANSACTION_TYPE, --TRANSACTION_TYPE
		@ATTRIBUTE_023 = @TRANSACTION_TYPE_DESCRIPTION, --TRANSACTION_TYPE_NAME
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PBT,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@DATE_CREATED = NULL,
		@CREATED_BY = @USER,
		@RETURN_SEQ_ID = @PAYMENT_BATCH_TRANSACTION_SEQ_ID OUTPUT


	DECLARE CUR_MR CURSOR LOCAL STATIC FOR 
	SELECT ATTRIBUTE_008, ATTRIBUTE_009, ATTRIBUTE_010 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MAR AND ATTRIBUTE_002 = @MEMBER

	OPEN CUR_MR 

	FETCH NEXT FROM CUR_MR INTO @RATE_TYPE, @RATE_TYPE_NAME, @TOTAL_OUTSTANDING

	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF ISNULL(@TOTAL_OUTSTANDING, 0) > 0
		BEGIN
			EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 12, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @PIVOT_NEXT_ID OUTPUT
			SET @TRANSACTION_ID = @PIVOT_NEXT_ID

				-- ADD DATA IN PAYMENT_TRANSACTION_DETAIL
			EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_001 = @TRANSACTION_ID, --TRANSACTION_ID
				@ATTRIBUTE_002 = @PAYMENT_BATCH_TRANSACTION_SEQ_ID, --PAYMENT_TRANSACTION
				@ATTRIBUTE_003 = @PAYMENT_BATCH_TRANSACTION_ID, --PAYMENT_TRANSACTION_NAME
				@ATTRIBUTE_004 = @MODULE, --MODULE
				@ATTRIBUTE_005 = @MODULE_DESCRIPTION, --MODULE_DESCRIPTION
				@ATTRIBUTE_006 = NULL, --FINANCE_TRANSACTION
				@ATTRIBUTE_007 = NULL, --FINANCE_TRANSACTION_NAME
				@ATTRIBUTE_008 = NULL, --PRODUCT
				@ATTRIBUTE_009 = NULL, --PRODUCT_NAME
				@ATTRIBUTE_010 = @TOTAL_OUTSTANDING, --AMOUNT
				@ATTRIBUTE_011 = @RATE_TYPE, --RATE_TYPE
				@ATTRIBUTE_012 = @RATE_TYPE_NAME, --RATE_TYPE_NAME
				@ATTRIBUTE_013 = NULL, --DONATION_TYPE
				@ATTRIBUTE_014 = NULL, --DONATION_TYPE_NAME
				@ATTRIBUTE_015 = NULL, --APPEAL
				@ATTRIBUTE_016 = NULL, --APPEAL_NAME
				@ATTRIBUTE_017 = NULL, --PROJECT
				@ATTRIBUTE_018 = NULL, --PROJECT_NAME
				@ATTRIBUTE_019 = NULL, --PLEDGE
				@ATTRIBUTE_020 = NULL, --PLEDGE_NAME
				@ATTRIBUTE_021 = NULL, --NAME_SUB
				@ATTRIBUTE_022 = NULL, --THANKYOU_LETTER
				@ATTRIBUTE_023 = NULL, --THANKYOU_LETTER_DESCRIPTION
				@ATTRIBUTE_024 = NULL, --REMARKS
				@ATTRIBUTE_025 = NULL, --EVENT
				@ATTRIBUTE_026 = NULL, --EVENT_NAME
				@ATTRIBUTE_027 = NULL, --TAX_PAYER
				@ATTRIBUTE_028 = NULL, --GIFT_AID_APPLICABLE
				@ATTRIBUTE_029 = NULL, --GIFT_AID_REFUSED
				@ATTRIBUTE_030 = NULL, --GIFT_AID_DECLARATION_GIVEN
				@ATTRIBUTE_031 = NULL, --GIFT_AID_DECLARATION_METHOD
				@ATTRIBUTE_032 = NULL, --GIFT_AID_DECLARATION_METHOD_DESCRIPTION
				@ATTRIBUTE_033 = NULL, --GIFT_AID_DECLARATION_VALID_FROM_DATE
				@ATTRIBUTE_034 = NULL, --GIFT_AID_DECLARATION_VALID_UNTIL_DATE
				@ATTRIBUTE_035 = NULL, --GIFT_AID_CONFIRMATION_LETTER_DATE
				@ATTRIBUTE_036 = NULL, --GIFT_AID_ORAL_CONFIRMATION_DATE
				@ATTRIBUTE_037 = NULL, --UPDATE_MAIN_RECORD
				@ATTRIBUTE_038 = @ACCOUNT, --ACCOUNT
				@ATTRIBUTE_039 = @ACCOUNT_NAME, --ACCOUNT_NAME
				@ATTRIBUTE_040 = @CONTACT, --CONTACT
				@ATTRIBUTE_041 = @CONTACT_NAME, --CONTACT_NAME
				@ATTRIBUTE_042 = NULL, --REGULAR_GIVING
				@ATTRIBUTE_043 = NULL, --REGULAR_GIVING_NAME
				@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PTD,
				@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
				@DATE_CREATED = NULL,
				@CREATED_BY = @USER,
				@RETURN_SEQ_ID = @PAYMENT_TRANSACTION_DETAIL_SEQ_ID OUTPUT
		END
		FETCH NEXT FROM CUR_MR INTO @RATE_TYPE, @RATE_TYPE_NAME, @TOTAL_OUTSTANDING
	END
	CLOSE CUR_MR 
	DEALLOCATE CUR_MR
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''

END






;






-- =============================================
-- Author:		<Adeel Hassan>
-- Create date: <03/09/2013>
-- Description:	<Create Registered Events>
-- =============================================
CREATE PROCEDURE [dbo].[GET_CREATE_REGISTERED_EVENT]
	-- Add the parameters for the stored procedure here
	@EXTERNAL_ID NVARCHAR(100) = NULL,
	@EVENT BIGINT = NULL,
	@EVENT_NAME NVARCHAR(100) = NULL,
	@EVENT_REGISTRATION BIGINT = NULL,
	@EVENT_REGISTRATION_NAME NVARCHAR(100) = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[GET_CREATE_REGISTERED_EVENT]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_REGISTERED_EVENT]'

	DECLARE @TODAY NVARCHAR(10)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @ENTITY_DISPLAY_NAME_REGISTERED_EVENT NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_REGISTERED_EVENT BIGINT
	SET @ENTITY_DISPLAY_NAME_REGISTERED_EVENT = 'REGISTERED_EVENT'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_REGISTERED_EVENT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_REGISTERED_EVENT

	EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
		@ATTRIBUTE_002 = @EVENT,
		@ATTRIBUTE_003 = @EVENT_NAME,
		@ATTRIBUTE_004 = @EVENT_REGISTRATION,
		@ATTRIBUTE_005 = @EVENT_REGISTRATION_NAME,	
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_REGISTERED_EVENT,
		@DATE_CREATED = @TODAY,
		@CREATED_BY = @USER,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

END







;







-- DROP PROCEDURE [dbo].[GET_CREATE_UPDATE_ACCOUNT]

-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_CREATE_UPDATE_ACCOUNT]
	-- Add the parameters for the stored procedure here
	@ACCOUNT_NAME NVARCHAR(100) = NULL,
	@ACCOUNT_FULL_NAME NVARCHAR(100) = NULL,
	@BUSINESS_ADDRESS_LINE_1 NVARCHAR(100) = NULL,
	@BUSINESS_ADDRESS_LINE_2 NVARCHAR(100) = NULL,
	@BUSINESS_ADDRESS_LINE_3 NVARCHAR(100) = NULL,
	@BUSINESS_ADDRESS_LINE_4 NVARCHAR(100) = NULL,
	@BUSINESS_TOWN NVARCHAR(100) = NULL,
	@BUSINESS_POSTCODE NVARCHAR(100) = NULL,
	@BUSINESS_COUNTY NVARCHAR(100) = NULL,
	@BUSINESS_COUNTY_DESCRIPTION NVARCHAR(100) = NULL,
	@BUSINESS_COUNTRY NVARCHAR(100) = NULL,
	@BUSINESS_COUNTRY_DESCRIPTION NVARCHAR(100) = NULL,
	@TELEPHONE_1 NVARCHAR(100) = NULL,
	@TELEPHONE_2 NVARCHAR(100) = NULL,
	@EMAIL_ADDRESS NVARCHAR(100) = NULL,
	@FAX NVARCHAR(100) = NULL,
	@WEBSITE NVARCHAR(100) = NULL,
	@MAIN_CONTACT NVARCHAR(100) = NULL,
	@MAIN_CONTACT_NAME NVARCHAR(100) = NULL,
	@PREFERRED_MAILING_ADDRESS NVARCHAR(100) = NULL,
	@PREFERRED_MAILING_ADDRESS_NAME NVARCHAR(100) = NULL, -- 0 for BUSINESS, 1 for ALTERNATE_BUSINESS
	@PREFERRED_BILLING_ADDRESS NVARCHAR(100) = NULL,
	@PREFERRED_BILLING_ADDRESS_NAME NVARCHAR(100) = NULL, -- 0 for BUSINESS, 1 for ALTERNATE_BUSINESS
	@ACCOUNT_STATUS NVARCHAR(100) = NULL,
	@ACCOUNT_STATUS_NAME NVARCHAR(100) = NULL, 
	@ORGANISATION_ID NVARCHAR(100) = NULL, 
	-- Mailing & Billing Address Details - Start
	@MAILING_ADDRESS_CONTACT_NAME NVARCHAR(100) = NULL,
	@MAILING_ADDRESS_JOB_TITLE NVARCHAR(100) = NULL,
	@MAILING_ADDRESS_LINE_1 NVARCHAR(50) = NULL,
	@MAILING_ADDRESS_LINE_2 NVARCHAR(50) = NULL,
	@MAILING_ADDRESS_LINE_3 NVARCHAR(50) = NULL,
	@MAILING_ADDRESS_LINE_4 NVARCHAR(50) = NULL,
	@MAILING_ADDRESS_TOWN NVARCHAR(50) = NULL,
	@MAILING_ADDRESS_POSTCODE NVARCHAR(30) = NULL,
	@MAILING_ADDRESS_COUNTY  BIGINT = NULL,
	@MAILING_ADDRESS_COUNTY_DESCRIPTION NVARCHAR(100) = NULL,
	@MAILING_ADDRESS_COUNTRY  BIGINT = NULL,
	@MAILING_ADDRESS_COUNTRY_DESCRIPTION NVARCHAR(100) = NULL,
	@BILLING_ADDRESS_CONTACT_NAME NVARCHAR(100) = NULL,
	@BILLING_ADDRESS_JOB_TITLE NVARCHAR(100) = NULL,
	@BILLING_ADDRESS_LINE_1 NVARCHAR(50) = NULL,
	@BILLING_ADDRESS_LINE_2 NVARCHAR(50) = NULL,
	@BILLING_ADDRESS_LINE_3 NVARCHAR(50) = NULL,
	@BILLING_ADDRESS_LINE_4 NVARCHAR(50) = NULL,
	@BILLING_ADDRESS_TOWN NVARCHAR(50) = NULL,
	@BILLING_ADDRESS_POSTCODE NVARCHAR(30) = NULL,
	@BILLING_ADDRESS_COUNTY  BIGINT = NULL,
	@BILLING_ADDRESS_COUNTY_DESCRIPTION NVARCHAR(100) = NULL,
	@BILLING_ADDRESS_COUNTRY  BIGINT = NULL,
	@BILLING_ADDRESS_COUNTRY_DESCRIPTION NVARCHAR(100) = NULL,
	-- Mailing & Billing Address Details - End
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ACCOUNT BIGINT OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[GET_CREATE_UPDATE_ACCOUNT]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_UPDATE_ACCOUNT]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @UCN BIGINT

	DECLARE @ENTITY_DISPLAY_NAME_ACCOUNT NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT BIGINT
	SET @ENTITY_DISPLAY_NAME_ACCOUNT = 'ACCOUNT'

	DECLARE @ENTITY_DISPLAY_NAME_WSO NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSO BIGINT
	SET @ENTITY_DISPLAY_NAME_WSO = 'WEB_SERVICE_ORGANISATION'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSO = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSO
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_ACCOUNT

	IF ISNULL(@ORGANISATION_ID, '0') <> '0'
	BEGIN	
		SET @ACCOUNT = CAST(@ORGANISATION_ID AS BIGINT)
		-- SELECT @ACCOUNT = CAST(ATTRIBUTE_010 AS BIGINT) FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SEQ_ID = @ORGANISATION_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSO
		IF ISNULL(@ACCOUNT, 0) <> 0 -- ORGANISATION ALREADY EXIST
		BEGIN
			PRINT 'ACCOUNT ALREADY EXIST. ACCOUNT ID = ' + CAST(@ACCOUNT AS NVARCHAR(20))
			SET @ERROR = 0
			SET @ERROR_DESCRIPTION = ''
			RETURN
		END
	END
	

	IF ISNULL(@BUSINESS_COUNTY_DESCRIPTION, '') <> '' -- GET COUNTY
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @BUSINESS_COUNTY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @BUSINESS_COUNTY OUTPUT, @DESCRIPTION = @BUSINESS_COUNTY_DESCRIPTION OUTPUT
	
	IF ISNULL(@BUSINESS_COUNTRY_DESCRIPTION, '') <> '' -- GET COUNTRY
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTRY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @BUSINESS_COUNTRY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @BUSINESS_COUNTRY OUTPUT, @DESCRIPTION = @BUSINESS_COUNTRY_DESCRIPTION OUTPUT
	
	-- Mailing & Billing Address Details - Start
	IF ISNULL(@MAILING_ADDRESS_COUNTY_DESCRIPTION, '') <> '' -- GET @MAILING_ADDRESS_COUNTY_DESCRIPTION
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @MAILING_ADDRESS_COUNTY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MAILING_ADDRESS_COUNTY OUTPUT, @DESCRIPTION = @MAILING_ADDRESS_COUNTY_DESCRIPTION OUTPUT
	
	IF ISNULL(@MAILING_ADDRESS_COUNTRY_DESCRIPTION, '') <> '' -- GET @MAILING_ADDRESS_COUNTRY_DESCRIPTION
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTRY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @MAILING_ADDRESS_COUNTRY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MAILING_ADDRESS_COUNTRY OUTPUT, @DESCRIPTION = @MAILING_ADDRESS_COUNTRY_DESCRIPTION OUTPUT

	IF ISNULL(@BILLING_ADDRESS_COUNTY_DESCRIPTION, '') <> '' -- GET @BILLING_ADDRESS_COUNTY_DESCRIPTION
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @BILLING_ADDRESS_COUNTY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @BILLING_ADDRESS_COUNTY OUTPUT, @DESCRIPTION = @BILLING_ADDRESS_COUNTY_DESCRIPTION OUTPUT
	
	IF ISNULL(@BILLING_ADDRESS_COUNTRY_DESCRIPTION, '') <> '' -- GET @BILLING_ADDRESS_COUNTRY_DESCRIPTION
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTRY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @BILLING_ADDRESS_COUNTRY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @BILLING_ADDRESS_COUNTRY OUTPUT, @DESCRIPTION = @BILLING_ADDRESS_COUNTRY_DESCRIPTION OUTPUT
	-- Mailing & Billing Address Details - End

	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'ADDRESS_PREFERENCE', @ATTRIBUTE_DISPLAY_NAME = 'BUSINESS', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PREFERRED_MAILING_ADDRESS OUTPUT, @DESCRIPTION = @PREFERRED_MAILING_ADDRESS_NAME OUTPUT
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'ADDRESS_PREFERENCE', @ATTRIBUTE_DISPLAY_NAME = 'BUSINESS', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PREFERRED_BILLING_ADDRESS OUTPUT, @DESCRIPTION = @PREFERRED_BILLING_ADDRESS_NAME OUTPUT

	IF ISNULL(@ACCOUNT_FULL_NAME, '') = ''
		SET @ACCOUNT_FULL_NAME = @ACCOUNT_NAME

	IF ISNULL(@MAILING_ADDRESS_LINE_1, '') = '' AND ISNULL(@BUSINESS_ADDRESS_LINE_1, '') <> ''
	BEGIN
		SET @MAILING_ADDRESS_LINE_1 = @BUSINESS_ADDRESS_LINE_1
		SET @MAILING_ADDRESS_LINE_2 = @BUSINESS_ADDRESS_LINE_2
		SET @MAILING_ADDRESS_LINE_3 = @BUSINESS_ADDRESS_LINE_3
		SET @MAILING_ADDRESS_LINE_4 = @BUSINESS_ADDRESS_LINE_4
		SET @MAILING_ADDRESS_TOWN = @BUSINESS_TOWN
		SET @MAILING_ADDRESS_POSTCODE = @BUSINESS_POSTCODE
		SET @MAILING_ADDRESS_COUNTY = @BUSINESS_COUNTY
		SET @MAILING_ADDRESS_COUNTY_DESCRIPTION = @BUSINESS_COUNTY_DESCRIPTION
		SET @MAILING_ADDRESS_COUNTRY = @BUSINESS_COUNTRY
		SET @MAILING_ADDRESS_COUNTRY_DESCRIPTION = @BUSINESS_COUNTRY_DESCRIPTION
	END

	IF ISNULL(@BILLING_ADDRESS_LINE_1, '') = '' AND ISNULL(@BUSINESS_ADDRESS_LINE_1, '') <> ''
	BEGIN
		SET @BILLING_ADDRESS_LINE_1 = @BUSINESS_ADDRESS_LINE_1
		SET @BILLING_ADDRESS_LINE_2 = @BUSINESS_ADDRESS_LINE_2
		SET @BILLING_ADDRESS_LINE_3 = @BUSINESS_ADDRESS_LINE_3
		SET @BILLING_ADDRESS_LINE_4 = @BUSINESS_ADDRESS_LINE_4
		SET @BILLING_ADDRESS_TOWN = @BUSINESS_TOWN
		SET @BILLING_ADDRESS_POSTCODE = @BUSINESS_POSTCODE
		SET @BILLING_ADDRESS_COUNTY = @BUSINESS_COUNTY
		SET @BILLING_ADDRESS_COUNTY_DESCRIPTION = @BUSINESS_COUNTY_DESCRIPTION
		SET @BILLING_ADDRESS_COUNTRY = @BUSINESS_COUNTRY
		SET @BILLING_ADDRESS_COUNTRY_DESCRIPTION = @BUSINESS_COUNTRY_DESCRIPTION
	END

	IF ISNULL(@ACCOUNT, 0) = 0 -- ADD A NEW ACCOUNT
	BEGIN
		PRINT 'NEW ACCOUNT'
		-- GET ACCOUNT STATUS
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'ACCOUNT_CONTACT_STATUS', @ATTRIBUTE_DISPLAY_NAME = 'DEFAULT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @ACCOUNT_STATUS OUTPUT, @DESCRIPTION = @ACCOUNT_STATUS_NAME OUTPUT

		EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 1, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @UCN OUTPUT

		EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
			@ATTRIBUTE_001 = @ACCOUNT_NAME,
			@ATTRIBUTE_003 = @UCN,
			@ATTRIBUTE_009 = @ACCOUNT_FULL_NAME,
			@ATTRIBUTE_020 = @ACCOUNT_STATUS,
			@ATTRIBUTE_021 = @ACCOUNT_STATUS_NAME,
			@ATTRIBUTE_024 = @BUSINESS_ADDRESS_LINE_1,
			@ATTRIBUTE_025 = @BUSINESS_ADDRESS_LINE_2,
			@ATTRIBUTE_026 = @BUSINESS_ADDRESS_LINE_3,
			@ATTRIBUTE_105 = @BUSINESS_ADDRESS_LINE_4,
			@ATTRIBUTE_027 = @BUSINESS_TOWN,
			@ATTRIBUTE_028 = @BUSINESS_POSTCODE,
			@ATTRIBUTE_029 = @BUSINESS_COUNTY,
			@ATTRIBUTE_030 = @BUSINESS_COUNTY_DESCRIPTION,
			@ATTRIBUTE_031 = @BUSINESS_COUNTRY,
			@ATTRIBUTE_032 = @BUSINESS_COUNTRY_DESCRIPTION,
			@ATTRIBUTE_043 = @TELEPHONE_1,
			@ATTRIBUTE_044 = @TELEPHONE_2,
			@ATTRIBUTE_045 = @EMAIL_ADDRESS,
			@ATTRIBUTE_046 = @FAX,
			@ATTRIBUTE_047 = @WEBSITE,
			@ATTRIBUTE_055 = @MAIN_CONTACT,
			@ATTRIBUTE_056 = @MAIN_CONTACT_NAME,
			-- Mailing & Billing Address Details - Start
			@ATTRIBUTE_112 = @MAILING_ADDRESS_CONTACT_NAME,
			@ATTRIBUTE_113 = @MAILING_ADDRESS_JOB_TITLE,
			@ATTRIBUTE_114 = @MAILING_ADDRESS_LINE_1,
			@ATTRIBUTE_115 = @MAILING_ADDRESS_LINE_2,
			@ATTRIBUTE_116 = @MAILING_ADDRESS_LINE_3,
			@ATTRIBUTE_117 = @MAILING_ADDRESS_LINE_4,
			@ATTRIBUTE_118 = @MAILING_ADDRESS_TOWN,
			@ATTRIBUTE_119 = @MAILING_ADDRESS_POSTCODE,
			@ATTRIBUTE_120 = @MAILING_ADDRESS_COUNTY,
			@ATTRIBUTE_121 = @MAILING_ADDRESS_COUNTY_DESCRIPTION,
			@ATTRIBUTE_122 = @MAILING_ADDRESS_COUNTRY,
			@ATTRIBUTE_123 = @MAILING_ADDRESS_COUNTRY_DESCRIPTION,
			@ATTRIBUTE_124 = @BILLING_ADDRESS_CONTACT_NAME,
			@ATTRIBUTE_125 = @BILLING_ADDRESS_JOB_TITLE,
			@ATTRIBUTE_126 = @BILLING_ADDRESS_LINE_1,
			@ATTRIBUTE_127 = @BILLING_ADDRESS_LINE_2,
			@ATTRIBUTE_128 = @BILLING_ADDRESS_LINE_3,
			@ATTRIBUTE_129 = @BILLING_ADDRESS_LINE_4,
			@ATTRIBUTE_130 = @BILLING_ADDRESS_TOWN,
			@ATTRIBUTE_131 = @BILLING_ADDRESS_POSTCODE,
			@ATTRIBUTE_132 = @BILLING_ADDRESS_COUNTY,
			@ATTRIBUTE_133 = @BILLING_ADDRESS_COUNTY_DESCRIPTION,
			@ATTRIBUTE_134 = @BILLING_ADDRESS_COUNTRY,
			@ATTRIBUTE_135 = @BILLING_ADDRESS_COUNTRY_DESCRIPTION,
			-- Mailing & Billing Address Details - End
			@ATTRIBUTE_106 = @PREFERRED_MAILING_ADDRESS, --	PREFERRED_MAILING_ADDRESS
			@ATTRIBUTE_107 = @PREFERRED_BILLING_ADDRESS, --	PREFERRED_BILLING_ADDRESS
			@ATTRIBUTE_108 = @PREFERRED_MAILING_ADDRESS_NAME, --	PREFERRED_MAILING_ADDRESS_NAME
			@ATTRIBUTE_109 = @PREFERRED_BILLING_ADDRESS_NAME, --	PREFERRED_BILLING_ADDRESS_NAME
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@DATE_CREATED = NULL,
			@CREATED_BY = @USER,
			@RETURN_SEQ_ID = @ACCOUNT OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END
	ELSE
	BEGIN -- UPDATE EXISTING ACCOUNT
		PRINT 'UPDATE ACCOUNT'
		UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
		SET ATTRIBUTE_001 = @ACCOUNT_NAME,
			--ATTRIBUTE_003 = @UCN,
			ATTRIBUTE_009 = @ACCOUNT_FULL_NAME,
			ATTRIBUTE_020 = @ACCOUNT_STATUS,
			ATTRIBUTE_021 = @ACCOUNT_STATUS_NAME,
			ATTRIBUTE_024 = @BUSINESS_ADDRESS_LINE_1,
			ATTRIBUTE_025 = @BUSINESS_ADDRESS_LINE_2,
			ATTRIBUTE_026 = @BUSINESS_ADDRESS_LINE_3,
			ATTRIBUTE_105 = @BUSINESS_ADDRESS_LINE_4,
			ATTRIBUTE_027 = @BUSINESS_TOWN,
			ATTRIBUTE_028 = @BUSINESS_POSTCODE,
			ATTRIBUTE_029 = @BUSINESS_COUNTY,
			ATTRIBUTE_030 = @BUSINESS_COUNTY_DESCRIPTION,
			ATTRIBUTE_031 = @BUSINESS_COUNTRY,
			ATTRIBUTE_032 = @BUSINESS_COUNTRY_DESCRIPTION,
			ATTRIBUTE_043 = @TELEPHONE_1,
			ATTRIBUTE_044 = @TELEPHONE_2,
			ATTRIBUTE_045 = @EMAIL_ADDRESS,
			ATTRIBUTE_046 = @FAX,
			ATTRIBUTE_047 = @WEBSITE,
			ATTRIBUTE_055 = @MAIN_CONTACT,
			ATTRIBUTE_056 = @MAIN_CONTACT_NAME,
			-- Mailing & Billing Address Details - Start
			ATTRIBUTE_112 = @MAILING_ADDRESS_CONTACT_NAME,
			ATTRIBUTE_113 = @MAILING_ADDRESS_JOB_TITLE,
			ATTRIBUTE_114 = @MAILING_ADDRESS_LINE_1,
			ATTRIBUTE_115 = @MAILING_ADDRESS_LINE_2,
			ATTRIBUTE_116 = @MAILING_ADDRESS_LINE_3,
			ATTRIBUTE_117 = @MAILING_ADDRESS_LINE_4,
			ATTRIBUTE_118 = @MAILING_ADDRESS_TOWN,
			ATTRIBUTE_119 = @MAILING_ADDRESS_POSTCODE,
			ATTRIBUTE_120 = @MAILING_ADDRESS_COUNTY,
			ATTRIBUTE_121 = @MAILING_ADDRESS_COUNTY_DESCRIPTION,
			ATTRIBUTE_122 = @MAILING_ADDRESS_COUNTRY,
			ATTRIBUTE_123 = @MAILING_ADDRESS_COUNTRY_DESCRIPTION,
			ATTRIBUTE_124 = @BILLING_ADDRESS_CONTACT_NAME,
			ATTRIBUTE_125 = @BILLING_ADDRESS_JOB_TITLE,
			ATTRIBUTE_126 = @BILLING_ADDRESS_LINE_1,
			ATTRIBUTE_127 = @BILLING_ADDRESS_LINE_2,
			ATTRIBUTE_128 = @BILLING_ADDRESS_LINE_3,
			ATTRIBUTE_129 = @BILLING_ADDRESS_LINE_4,
			ATTRIBUTE_130 = @BILLING_ADDRESS_TOWN,
			ATTRIBUTE_131 = @BILLING_ADDRESS_POSTCODE,
			ATTRIBUTE_132 = @BILLING_ADDRESS_COUNTY,
			ATTRIBUTE_133 = @BILLING_ADDRESS_COUNTY_DESCRIPTION,
			ATTRIBUTE_134 = @BILLING_ADDRESS_COUNTRY,
			ATTRIBUTE_135 = @BILLING_ADDRESS_COUNTRY_DESCRIPTION,
			-- Mailing & Billing Address Details - End
			DATE_MODIFIED = @TODAY,
			MODIFIED_BY = @USER
		WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT AND SEQ_ID = @ACCOUNT

		EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT,
			@CUS_ENTITY_DATA_SEQ_ID = @ACCOUNT,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

	END

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END







;







