		@ORG_ADDRESS_LINE_4 = ATTRIBUTE_030,
		@ORG_ADDRESS_LINE_5 = ATTRIBUTE_031,
		@ORG_TOWN = ATTRIBUTE_065,
		@ORGANISATION_TYPE = ATTRIBUTE_032,
		@PASSWORD = ATTRIBUTE_033,
		@PREFERRED_MAILING_ADDRESS = ATTRIBUTE_034,
		@PREFERRED_INVOICE_ADDRESS = ATTRIBUTE_035,
		@SUPPLEMENTARY_PUBLICATIONS = ATTRIBUTE_036,
		@THE_JOURNAL_SUPPLEMENT = ATTRIBUTE_037,
		@ORG_ADDRESS_POSTCODE = ATTRIBUTE_038,
		@ORG_ADDRESS_COUNTY = ATTRIBUTE_039,
		@ORG_ADDRESS_COUNTRY = ATTRIBUTE_040,
		@USER_NAME = ATTRIBUTE_041,
		@CATEGORY_OF_MEMBERSHIP = ATTRIBUTE_042,
		@PACKAGE = ATTRIBUTE_043,
		@PAYMENT_AMOUNT = ATTRIBUTE_044,
		@MEMBER_ID = ATTRIBUTE_045,
		@DEPARTMENTAL_MEMBER_ID = ATTRIBUTE_046,
		@AREA_OF_FOCUS = ATTRIBUTE_047,
		@ORGANISATION_TEL = ATTRIBUTE_048,
		@ORGANISATION_FAX = ATTRIBUTE_049,
		@ORGANISATION_EMAIL = ATTRIBUTE_050,
		@CURRICULUM_CREDITS_AVAILABLE = ATTRIBUTE_051,
