		@TS_CS_AGREEMENT_DATE = ATTRIBUTE_083
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBERSHIP AND SEQ_ID = @EXTERNAL_RECORD_ID

	IF ISNULL(@USER_NAME, '') <> '' 
	BEGIN
		-- CHECK IF USER NAME EXISTS FOR CONTACT
		SET @PIVOT_RETURN_VALUE = NULL

		EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT, @ATTRIBUTE_DISPLAY_NAME = 'LOGIN_USER_NAME', @OPERATOR_ID = 3, @SEARCH_VALUE = @USER_NAME, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT

		IF ISNULL(@PIVOT_RETURN_VALUE, '') <> ''
		BEGIN
			SELECT @CONTACT = DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ',')
		END
		IF ISNULL(@CONTACT, 0) = 0
		BEGIN
			SET @PIVOT_RETURN_VALUE = NULL

			EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT, @ATTRIBUTE_DISPLAY_NAME = 'LOGIN_USER_NAME', @OPERATOR_ID = 3, @SEARCH_VALUE = @USER_NAME, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT

			IF ISNULL(@PIVOT_RETURN_VALUE, '') <> ''
