			@HOME_COUNTY_DESCRIPTION = @COUNTY,
			@HOME_COUNTRY = NULL,
			@HOME_COUNTRY_DESCRIPTION = @COUNTRY,
			@BUSINESS_ADDRESS_LINE_1 = @ORG_ADDRESS_LINE_1,
			@BUSINESS_ADDRESS_LINE_2 = @ORG_ADDRESS_LINE_2,
			@BUSINESS_ADDRESS_LINE_3 = @ORG_ADDRESS_LINE_3,
			@BUSINESS_ADDRESS_LINE_4 = @ORG_ADDRESS_LINE_4,
			@BUSINESS_TOWN = @ORG_TOWN,
			@BUSINESS_POSTCODE = @ORG_ADDRESS_POSTCODE,
			@BUSINESS_COUNTY = NULL,
			@BUSINESS_COUNTY_DESCRIPTION = @ORG_ADDRESS_COUNTY,
			@BUSINESS_COUNTRY = NULL,
			@BUSINESS_COUNTRY_DESCRIPTION = @ORG_ADDRESS_COUNTRY,
			@HOME_TELEPHONE = @TEL_NUMBER,
			@BUSINESS_TELEPHONE = @ORGANISATION_TEL,
			@MOBILE = @MOBILE,
			@EMAIL_1 = @EMAIL,
			@EMAIL_2 = NULL,
			@BADGE_1 = NULL,
			@BADGE_2 = NULL,
			@BADGE_3 = NULL,
			@BADGE_4 = NULL,
			@AREA_OF_FOCUS = NULL,
			@AREA_OF_FOCUS_DESCRIPTION = @AREA_OF_FOCUS,
			@CONTACT_TYPE = NULL,
			@CONTACT_TYPE_DESCRIPTION = NULL,
			@PREFERRED_MAILING_ADDRESS = NULL,
			@PREFERRED_MAILING_ADDRESS_NAME = @PREFERRED_MAILING_ADDRESS, -- 0 for home, 1 for business
			@PREFERRED_BILLING_ADDRESS = NULL,
			@PREFERRED_BILLING_ADDRESS_NAME = @PREFERRED_INVOICE_ADDRESS, -- 0 for home, 1 for business
			@BUSINESS_ADDRESS_ACCOUNT_NAME = @ORGANISATION_NAME,
			@BUSINESS_ADDRESS_JOB_TITLE = @JOB_TITLE,
			@DATA_PROTECTION = @DATA_PROTECTION,
			@PRIVACY_POLICY_AGREEMENT = @PRIVACY_POLICY_AGREEMENT,
			@PRIVACY_POLICY_AGREEMENT_DATE = @PRIVACY_POLICY_AGREEMENT_DATE,
			@TS_CS_AGREEMENT = @TS_CS_AGREEMENT,
			@TS_CS_AGREEMENT_DATE = @TS_CS_AGREEMENT_DATE,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@USER = @USER,
			@CONTACT = @CONTACT OUTPUT,
			@CONTACT_NAME = @CONTACT_NAME OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	--END

	IF ISNULL(@ACCOUNT, 0) = 0 AND ISNULL(@ORGANISATION_NAME, '') <> ''
	BEGIN
		EXEC [dbo].[GET_CREATE_UPDATE_ACCOUNT]
			@ACCOUNT_NAME = @ORGANISATION_NAME,
			@ACCOUNT_FULL_NAME = @ORGANISATION_NAME,
			@BUSINESS_ADDRESS_LINE_1 = @ORG_ADDRESS_LINE_1,
			@BUSINESS_ADDRESS_LINE_2 = @ORG_ADDRESS_LINE_2,
			@BUSINESS_ADDRESS_LINE_3 = @ORG_ADDRESS_LINE_3,
			@BUSINESS_ADDRESS_LINE_4 = @ORG_ADDRESS_LINE_4,
			@BUSINESS_TOWN = @ORG_TOWN,
			@BUSINESS_POSTCODE = @ORG_ADDRESS_POSTCODE,
			@BUSINESS_COUNTY = NULL,
			@BUSINESS_COUNTY_DESCRIPTION = @ORG_ADDRESS_COUNTY,
			@BUSINESS_COUNTRY = NULL,
			@BUSINESS_COUNTRY_DESCRIPTION = @ORG_ADDRESS_COUNTRY,
			@TELEPHONE_1 = @ORGANISATION_TEL,
			@TELEPHONE_2 = NULL,
			@EMAIL_ADDRESS = @ORGANISATION_EMAIL,
			@FAX = @ORGANISATION_FAX,
			@WEBSITE = NULL,
			@MAIN_CONTACT = @CONTACT,
			@MAIN_CONTACT_NAME = @CONTACT_NAME,
			@PREFERRED_MAILING_ADDRESS  = NULL,
			@PREFERRED_MAILING_ADDRESS_NAME = '0',
			@PREFERRED_BILLING_ADDRESS = NULL,
			@PREFERRED_BILLING_ADDRESS_NAME = '0',
			@ORGANISATION_ID = @ORGANISATION_ID,
			@USER = @USER,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ACCOUNT = @ACCOUNT OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		SET @REMARKS = @ORGANISATION_NAME + ' - ' + @CONTACT_NAME
	END

	EXEC [dbo].[GET_CREATE_ACCOUNT_CONTACT_RELATIONSHIP]
		@ACCOUNT = @ACCOUNT,
		@ACCOUNT_NAME = @ORGANISATION_NAME,
		@CONTACT = @CONTACT,
		@CONTACT_NAME = @CONTACT_NAME,
		@JOB_FUNCTION = NULL,
		@JOB_FUNCTION_DESCRIPTION = @JOB_CATEGORY,
		@EFFECTIVE_DATE = NULL,
		@CEASED_DATE = NULL,
		@JOB_TITLE = @JOB_TITLE,
		@MAIN_CONTACT = 'Y',
		@MAIN_ACCOUNT = 'Y', 
		@CEASED = 'N',
		@REMARKS = @REMARKS,
		@USER = @USER,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID = @ACCOUNT_CONTACT_RELATIONSHIP_SEQ_ID OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
	
END








;







