	@BADGE_4 NVARCHAR(100) = NULL,
	@AREA_OF_FOCUS NVARCHAR(100) = NULL,
	@AREA_OF_FOCUS_DESCRIPTION NVARCHAR(100) = NULL,
	@CONTACT_TYPE NVARCHAR(100) = NULL,
	@CONTACT_TYPE_DESCRIPTION NVARCHAR(100) = NULL,
	@PREFERRED_MAILING_ADDRESS NVARCHAR(100) = NULL,
	@PREFERRED_MAILING_ADDRESS_NAME NVARCHAR(100) = NULL, -- 0 for home, 1 for business
	@PREFERRED_BILLING_ADDRESS NVARCHAR(100) = NULL,
