	@DATA_PROTECTION NVARCHAR(100) = NULL,
	-- Mailing & Billing Address Details - Start
	@MAILING_ADDRESS_ACCOUNT_NAME NVARCHAR(100) = NULL,
	@MAILING_ADDRESS_JOB_TITLE NVARCHAR(100) = NULL,
	@MAILING_ADDRESS_LINE_1 NVARCHAR(50) = NULL,
	@MAILING_ADDRESS_LINE_2 NVARCHAR(50) = NULL,
	@MAILING_ADDRESS_LINE_3 NVARCHAR(50) = NULL,
	@MAILING_ADDRESS_LINE_4 NVARCHAR(50) = NULL,
	@MAILING_ADDRESS_TOWN NVARCHAR(50) = NULL,
	@MAILING_ADDRESS_POSTCODE NVARCHAR(30) = NULL,
	@MAILING_ADDRESS_COUNTY BIGINT = NULL,
	@MAILING_ADDRESS_COUNTY_DESCRIPTION NVARCHAR(100) = NULL,
	@MAILING_ADDRESS_COUNTRY BIGINT = NULL,
	@MAILING_ADDRESS_COUNTRY_DESCRIPTION NVARCHAR(100) = NULL,
	@BILLING_ADDRESS_ACCOUNT_NAME NVARCHAR(100) = NULL,
	@BILLING_ADDRESS_JOB_TITLE NVARCHAR(100) = NULL,
	@BILLING_ADDRESS_LINE_1 NVARCHAR(50) = NULL,
	@BILLING_ADDRESS_LINE_2 NVARCHAR(50) = NULL,
	@BILLING_ADDRESS_LINE_3 NVARCHAR(50) = NULL,
	@BILLING_ADDRESS_LINE_4 NVARCHAR(50) = NULL,
	@BILLING_ADDRESS_TOWN NVARCHAR(50) = NULL,
	@BILLING_ADDRESS_POSTCODE NVARCHAR(30) = NULL,
	@BILLING_ADDRESS_COUNTY BIGINT = NULL,
	@BILLING_ADDRESS_COUNTY_DESCRIPTION NVARCHAR(100) = NULL,
	@BILLING_ADDRESS_COUNTRY BIGINT = NULL,
	@BILLING_ADDRESS_COUNTRY_DESCRIPTION NVARCHAR(100) = NULL,
	-- Mailing & Billing Address Details - End
	@PRIVACY_POLICY_AGREEMENT CHAR(1) = NULL,
	@PRIVACY_POLICY_AGREEMENT_DATE NVARCHAR(30) = NULL,
	@TS_CS_AGREEMENT CHAR(1) = NULL,
	@TS_CS_AGREEMENT_DATE NVARCHAR(30) = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@CONTACT BIGINT = NULL OUTPUT,
	@CONTACT_NAME NVARCHAR(100) = NULL OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[GET_CREATE_UPDATE_CONTACT]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_UPDATE_CONTACT]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @WEB_SERVICE_PRODUCT_SALE_MASTER BIGINT
	DECLARE @WEB_SERVICE_PRODUCT_SALE_MASTER_DESCRIPTION NVARCHAR(100)

	DECLARE @ENTITY_DISPLAY_NAME_CONTACT NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT BIGINT
	SET @ENTITY_DISPLAY_NAME_CONTACT = 'CONTACT'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_CONTACT

	IF ISNULL(@AREA_OF_FOCUS_DESCRIPTION, '') <> '' -- GET AREA_OF_FOCUS DESCRIPTION
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'AREA_OF_FOCUS', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @AREA_OF_FOCUS_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @AREA_OF_FOCUS OUTPUT, @DESCRIPTION = @AREA_OF_FOCUS_DESCRIPTION OUTPUT

	IF ISNULL(@HOME_COUNTY_DESCRIPTION, '') <> '' -- GET HOME COUNTY
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @HOME_COUNTY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @HOME_COUNTY OUTPUT, @DESCRIPTION = @HOME_COUNTY_DESCRIPTION OUTPUT
	
	IF ISNULL(@HOME_COUNTRY_DESCRIPTION, '') <> '' -- GET HOME COUNTRY
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTRY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @HOME_COUNTRY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @HOME_COUNTRY OUTPUT, @DESCRIPTION = @HOME_COUNTRY_DESCRIPTION OUTPUT

	IF ISNULL(@BUSINESS_COUNTY_DESCRIPTION, '') <> '' -- GET ORG COUNTY
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @BUSINESS_COUNTY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @BUSINESS_COUNTY OUTPUT, @DESCRIPTION = @BUSINESS_COUNTY_DESCRIPTION OUTPUT
	
	IF ISNULL(@BUSINESS_COUNTRY_DESCRIPTION, '') <> '' -- GET ORG COUNTRY
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTRY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @BUSINESS_COUNTRY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @BUSINESS_COUNTRY OUTPUT, @DESCRIPTION = @BUSINESS_COUNTRY_DESCRIPTION OUTPUT

	IF ISNULL(@TITLE_DESCRIPTION, '') <> '' -- GET TITLE
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'TITLE', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @TITLE_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @TITLE OUTPUT, @DESCRIPTION = @TITLE_DESCRIPTION OUTPUT

	IF ISNULL(@WHERE_YOU_HEAR_ABOUT_US_DESCRIPTION, '') <> '' -- GET MARKETING SOURCE
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MARKETING_SOURCE', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @WHERE_YOU_HEAR_ABOUT_US_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @WHERE_YOU_HEAR_ABOUT_US OUTPUT, @DESCRIPTION = @WHERE_YOU_HEAR_ABOUT_US_DESCRIPTION OUTPUT

	IF @PREFERRED_MAILING_ADDRESS_NAME = '1' OR @PREFERRED_MAILING_ADDRESS_NAME = 'HOME'
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'ADDRESS_PREFERENCE', @ATTRIBUTE_DISPLAY_NAME = 'HOME', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PREFERRED_MAILING_ADDRESS OUTPUT, @DESCRIPTION = @PREFERRED_MAILING_ADDRESS_NAME OUTPUT
		IF ISNULL(@MAILING_ADDRESS_LINE_1, '') = '' AND ISNULL(@HOME_ADDRESS_LINE_1, '') <> ''
		BEGIN
			SET @MAILING_ADDRESS_LINE_1 = @HOME_ADDRESS_LINE_1
			SET @MAILING_ADDRESS_LINE_2 = @HOME_ADDRESS_LINE_2
			SET @MAILING_ADDRESS_LINE_3 = @HOME_ADDRESS_LINE_3
			SET @MAILING_ADDRESS_LINE_4 = @HOME_ADDRESS_LINE_4
			SET @MAILING_ADDRESS_TOWN = @HOME_TOWN
			SET @MAILING_ADDRESS_POSTCODE = @HOME_POSTCODE
			SET @MAILING_ADDRESS_COUNTY = @HOME_COUNTY
			SET @MAILING_ADDRESS_COUNTY_DESCRIPTION = @HOME_COUNTY_DESCRIPTION
			SET @MAILING_ADDRESS_COUNTRY = @HOME_COUNTRY
			SET @MAILING_ADDRESS_COUNTRY_DESCRIPTION = @HOME_COUNTRY_DESCRIPTION
		END
	END
	ELSE IF @PREFERRED_MAILING_ADDRESS_NAME = '2' OR @PREFERRED_MAILING_ADDRESS_NAME = 'ORGANISATION'
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'ADDRESS_PREFERENCE', @ATTRIBUTE_DISPLAY_NAME = 'BUSINESS', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PREFERRED_MAILING_ADDRESS OUTPUT, @DESCRIPTION = @PREFERRED_MAILING_ADDRESS_NAME OUTPUT
		IF ISNULL(@MAILING_ADDRESS_LINE_1, '') = '' AND ISNULL(@BUSINESS_ADDRESS_LINE_1, '') <> ''
		BEGIN
			SET @MAILING_ADDRESS_ACCOUNT_NAME = @BUSINESS_ADDRESS_ACCOUNT_NAME
			SET @MAILING_ADDRESS_JOB_TITLE = @BUSINESS_ADDRESS_JOB_TITLE
			SET @MAILING_ADDRESS_LINE_1 = @BUSINESS_ADDRESS_LINE_1
			SET @MAILING_ADDRESS_LINE_2 = @BUSINESS_ADDRESS_LINE_2
			SET @MAILING_ADDRESS_LINE_3 = @BUSINESS_ADDRESS_LINE_3
			SET @MAILING_ADDRESS_LINE_4 = @BUSINESS_ADDRESS_LINE_4
			SET @MAILING_ADDRESS_TOWN = @BUSINESS_TOWN
			SET @MAILING_ADDRESS_POSTCODE = @BUSINESS_POSTCODE
			SET @MAILING_ADDRESS_COUNTY = @BUSINESS_COUNTY
			SET @MAILING_ADDRESS_COUNTY_DESCRIPTION = @BUSINESS_COUNTY_DESCRIPTION
			SET @MAILING_ADDRESS_COUNTRY = @BUSINESS_COUNTRY
			SET @MAILING_ADDRESS_COUNTRY_DESCRIPTION = @BUSINESS_COUNTRY_DESCRIPTION
		END
	END

	IF @PREFERRED_BILLING_ADDRESS_NAME = '1' OR @PREFERRED_BILLING_ADDRESS_NAME = 'HOME'
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'ADDRESS_PREFERENCE', @ATTRIBUTE_DISPLAY_NAME = 'HOME', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PREFERRED_BILLING_ADDRESS OUTPUT, @DESCRIPTION = @PREFERRED_BILLING_ADDRESS_NAME OUTPUT
		IF ISNULL(@BILLING_ADDRESS_LINE_1, '') = '' AND ISNULL(@HOME_ADDRESS_LINE_1, '') <> ''
		BEGIN
			SET @BILLING_ADDRESS_LINE_1 = @HOME_ADDRESS_LINE_1
			SET @BILLING_ADDRESS_LINE_2 = @HOME_ADDRESS_LINE_2
			SET @BILLING_ADDRESS_LINE_3 = @HOME_ADDRESS_LINE_3
			SET @BILLING_ADDRESS_LINE_4 = @HOME_ADDRESS_LINE_4
			SET @BILLING_ADDRESS_TOWN = @HOME_TOWN
			SET @BILLING_ADDRESS_POSTCODE = @HOME_POSTCODE
			SET @BILLING_ADDRESS_COUNTY = @HOME_COUNTY
			SET @BILLING_ADDRESS_COUNTY_DESCRIPTION = @HOME_COUNTY_DESCRIPTION
			SET @BILLING_ADDRESS_COUNTRY = @HOME_COUNTRY
			SET @BILLING_ADDRESS_COUNTRY_DESCRIPTION = @HOME_COUNTRY_DESCRIPTION
		END
	END
	ELSE IF @PREFERRED_BILLING_ADDRESS_NAME = '2' OR @PREFERRED_BILLING_ADDRESS_NAME = 'ORGANISATION'
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'ADDRESS_PREFERENCE', @ATTRIBUTE_DISPLAY_NAME = 'BUSINESS', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @PREFERRED_BILLING_ADDRESS OUTPUT, @DESCRIPTION = @PREFERRED_BILLING_ADDRESS_NAME OUTPUT
		IF ISNULL(@BILLING_ADDRESS_LINE_1, '') = '' AND ISNULL(@BUSINESS_ADDRESS_LINE_1, '') <> ''
		BEGIN
			SET @BILLING_ADDRESS_ACCOUNT_NAME = @BUSINESS_ADDRESS_ACCOUNT_NAME
			SET @BILLING_ADDRESS_JOB_TITLE = @BUSINESS_ADDRESS_JOB_TITLE
			SET @BILLING_ADDRESS_LINE_1 = @BUSINESS_ADDRESS_LINE_1
			SET @BILLING_ADDRESS_LINE_2 = @BUSINESS_ADDRESS_LINE_2
			SET @BILLING_ADDRESS_LINE_3 = @BUSINESS_ADDRESS_LINE_3
			SET @BILLING_ADDRESS_LINE_4 = @BUSINESS_ADDRESS_LINE_4
			SET @BILLING_ADDRESS_TOWN = @BUSINESS_TOWN
			SET @BILLING_ADDRESS_POSTCODE = @BUSINESS_POSTCODE
			SET @BILLING_ADDRESS_COUNTY = @BUSINESS_COUNTY
			SET @BILLING_ADDRESS_COUNTY_DESCRIPTION = @BUSINESS_COUNTY_DESCRIPTION
			SET @BILLING_ADDRESS_COUNTRY = @BUSINESS_COUNTRY
			SET @BILLING_ADDRESS_COUNTRY_DESCRIPTION = @BUSINESS_COUNTRY_DESCRIPTION
		END
	END

	-- Mailing & Billing Address Details - Start
	IF ISNULL(@MAILING_ADDRESS_COUNTY_DESCRIPTION, '') <> '' -- GET @MAILING_ADDRESS_COUNTY_DESCRIPTION
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @MAILING_ADDRESS_COUNTY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MAILING_ADDRESS_COUNTY OUTPUT, @DESCRIPTION = @MAILING_ADDRESS_COUNTY_DESCRIPTION OUTPUT
	
	IF ISNULL(@MAILING_ADDRESS_COUNTRY_DESCRIPTION, '') <> '' -- GET @MAILING_ADDRESS_COUNTRY_DESCRIPTION
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTRY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @MAILING_ADDRESS_COUNTRY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @MAILING_ADDRESS_COUNTRY OUTPUT, @DESCRIPTION = @MAILING_ADDRESS_COUNTRY_DESCRIPTION OUTPUT

	IF ISNULL(@BILLING_ADDRESS_COUNTY_DESCRIPTION, '') <> '' -- GET @BILLING_ADDRESS_COUNTY_DESCRIPTION
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @BILLING_ADDRESS_COUNTY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @BILLING_ADDRESS_COUNTY OUTPUT, @DESCRIPTION = @BILLING_ADDRESS_COUNTY_DESCRIPTION OUTPUT
	
	IF ISNULL(@BILLING_ADDRESS_COUNTRY_DESCRIPTION, '') <> '' -- GET @MAILING_ADDRESS_COUNTRY_DESCRIPTION
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'COUNTRY', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @BILLING_ADDRESS_COUNTRY_DESCRIPTION, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @BILLING_ADDRESS_COUNTRY OUTPUT, @DESCRIPTION = @BILLING_ADDRESS_COUNTRY_DESCRIPTION OUTPUT
	-- Mailing & Billing Address Details - End

	IF ISDATE(@DATE_OF_BIRTH)=0
		SET @DATE_OF_BIRTH = NULL

	IF ISNULL(@AGE, 0) = 0 AND ISNULL(@DATE_OF_BIRTH, '') <> ''
		SET @AGE = [dbo].fn_CalculateAge(@DATE_OF_BIRTH)

	IF ISNULL(@LABEL_NAME, '') = '' -- CALC LABLE_NAME
		SET @LABEL_NAME = LTRIM(RTRIM(ISNULL(@TITLE_DESCRIPTION, ''))) + ' ' + LTRIM(RTRIM(ISNULL(@FIRST_NAME, ''))) + ' ' + LTRIM(RTRIM(ISNULL(@LAST_NAME, '')))

	SET @CONTACT_NAME = @LABEL_NAME
	
	IF ISNULL(@INITIALS, '') = '' -- CALC INITIALS
		SET @INITIALS = [dbo].[fn_CalculateInitials](@FIRST_NAME, @MIDDLE_NAME)

	IF ISNULL(@SALUTATION, '') = '' -- CALC SALUTATION
	BEGIN
		IF LTRIM(RTRIM(ISNULL(@TITLE_DESCRIPTION, ''))) = ''
			SET @SALUTATION = LTRIM(RTRIM(ISNULL(@FIRST_NAME, '')))
		ELSE
			SET @SALUTATION = LTRIM(RTRIM(ISNULL(@TITLE_DESCRIPTION, '') + ' ' + ISNULL(@LAST_NAME, '')))
	END
	IF LTRIM(RTRIM(ISNULL(@BADGE_1, ''))) = '' -- BADGE_1
		SET @BADGE_1 = @LABEL_NAME


	IF ISNULL(@CONTACT, 0) = 0 -- ADD A NEW CONTACT
	BEGIN
		-- GET CONTACT STATUS
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'ACCOUNT_CONTACT_STATUS', @ATTRIBUTE_DISPLAY_NAME = 'DEFAULT', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @CONTACT_STATUS OUTPUT, @DESCRIPTION = @CONTACT_STATUS_NAME OUTPUT

		EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 1, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @UCN OUTPUT
		PRINT 'I am in new contact 1'
		EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
			@ATTRIBUTE_001 = @LABEL_NAME,
			@ATTRIBUTE_003 = @UCN,
			@ATTRIBUTE_004 = @LAST_NAME,
			@ATTRIBUTE_005 = @FIRST_NAME,
			@ATTRIBUTE_006 = @MIDDLE_NAME,
			@ATTRIBUTE_008 = @INITIALS,
			@ATTRIBUTE_010 = @SALUTATION,
			@ATTRIBUTE_011 = @DATE_OF_BIRTH,
			@ATTRIBUTE_012 = @AGE,
			@ATTRIBUTE_015 = @AVAILABLE_ON_PORTAL,
			@ATTRIBUTE_020 = @LOGIN_USER_NAME,
			@ATTRIBUTE_021 = @LOGIN_EMAIL_ADDRESS,
			@ATTRIBUTE_022 = @LOGIN_PASSWORD,
			@ATTRIBUTE_025 = @TITLE,
			@ATTRIBUTE_026 = @TITLE_DESCRIPTION,
			@ATTRIBUTE_029 = @CONTACT_STATUS,
			@ATTRIBUTE_030 = @CONTACT_STATUS_NAME,
			@ATTRIBUTE_031 = @WHERE_YOU_HEAR_ABOUT_US,
			@ATTRIBUTE_032 = @WHERE_YOU_HEAR_ABOUT_US_DESCRIPTION,
			@ATTRIBUTE_035 = @HOME_ADDRESS_LINE_1,
			@ATTRIBUTE_036 = @HOME_ADDRESS_LINE_2,
			@ATTRIBUTE_037 = @HOME_ADDRESS_LINE_3,
