			ATTRIBUTE_149 = @MAILING_ADDRESS_LINE_1,
			ATTRIBUTE_150 = @MAILING_ADDRESS_LINE_2,
			ATTRIBUTE_151 = @MAILING_ADDRESS_LINE_3,
			ATTRIBUTE_152 = @MAILING_ADDRESS_LINE_4,
