CREATE PROCEDURE [dbo].[GET_CREATE_UPDATE_MEMBER_RATES]
	-- Add the parameters for the stored procedure here
	@EXTERNAL_RECORD_ID BIGINT = NULL,
	@MEMBER BIGINT = NULL,
	@USER NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[GET_CREATE_UPDATE_MEMBER_RATES]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_CREATE_UPDATE_MEMBER_RATES]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @MEMBER_ID NVARCHAR(100)
	DECLARE @RATE_NAME NVARCHAR(100)
	DECLARE @RATE_TYPE NVARCHAR(100)
	DECLARE @RATE_TYPE_NAME NVARCHAR(100)
	DECLARE @MEMBER_CATEGORY NVARCHAR(100)
	DECLARE @RATE_AMOUNT NVARCHAR(100)
	DECLARE @LEDGER_ACCOUNT NVARCHAR(100)
	DECLARE @LEDGER_ACCOUNT_DESCRIPTION NVARCHAR(100)
	DECLARE @QUANTITY NVARCHAR(100)
	DECLARE @FISCAL_PERIOD NVARCHAR(10)

	DECLARE @MEMBER_ASSIGNED_RATE BIGINT
	DECLARE @MEMBER_LEDGER BIGINT
	DECLARE @EXTERNAL_ID NVARCHAR(100)

	DECLARE @PAYMENT_AMOUNT_NET MONEY
	DECLARE @PAYMENT_AMOUNT_VAT MONEY
	DECLARE @GROSS_AMOUNT MONEY

	DECLARE @TMP_PAYMENT_AMOUNT_NET MONEY
	DECLARE @TMP_PAYMENT_AMOUNT_VAT MONEY
	DECLARE @TMP_GROSS_AMOUNT MONEY
	
	DECLARE @MSUB_RATE NVARCHAR(1)
	DECLARE @CREDIT_RATE NVARCHAR(1)
	DECLARE @LOGIN_RATE NVARCHAR(1)
	
	DECLARE @ADDITIONAL_PAYMENT_AMOUNT_NET MONEY
	DECLARE @ADDITIONAL_PAYMENT_AMOUNT_VAT MONEY

	DECLARE @ENTITY_DISPLAY_NAME_MR NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MR BIGINT
	SET @ENTITY_DISPLAY_NAME_MR = 'MEMBER_RATE'

	DECLARE @ENTITY_DISPLAY_NAME_MEMBER NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER BIGINT
	SET @ENTITY_DISPLAY_NAME_MEMBER = 'MEMBER'

	DECLARE @ENTITY_DISPLAY_NAME_MAR NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MAR BIGINT
	SET @ENTITY_DISPLAY_NAME_MAR = 'MEMBER_ASSIGNED_RATE'

	DECLARE @ENTITY_DISPLAY_NAME_WSM NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSM BIGINT
	SET @ENTITY_DISPLAY_NAME_WSM = 'WEB_SERVICE_MEMBERSHIP'

	DECLARE @ENTITY_DISPLAY_NAME_MRT NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MRT BIGINT
	SET @ENTITY_DISPLAY_NAME_MRT = 'MEMBER_RATE_TYPE'

	DECLARE @ENTITY_DISPLAY_NAME_WSMAR NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR BIGINT
	SET @ENTITY_DISPLAY_NAME_WSMAR = 'WEB_SERVICE_MEMBERSHIP_ADDITIONAL_RATE'

	DECLARE @ENTITY_DISPLAY_NAME_ML NVARCHAR(100)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_ML BIGINT
	SET @ENTITY_DISPLAY_NAME_ML = 'MEMBER_LEDGER'

	DECLARE @NEXT_RENEWAL_DATE NVARCHAR(100)

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MRT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MRT 
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSMAR
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_WSM = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_WSM 
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MAR = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MAR
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MEMBER
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MR = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_MR
	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_ML = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_ML

	SELECT @MEMBER_ID = ATTRIBUTE_001, @MEMBER_CATEGORY = ATTRIBUTE_013, @NEXT_RENEWAL_DATE = ATTRIBUTE_005 
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER 
	AND SEQ_ID = @MEMBER
	
	
	SET @FISCAL_PERIOD = CAST(MONTH(@NEXT_RENEWAL_DATE) AS NVARCHAR) + '/' + CAST((YEAR(@NEXT_RENEWAL_DATE) - 1) AS NVARCHAR)
	
	PRINT '@FISCAL_PERIOD ' + ISNULL(@FISCAL_PERIOD,'NULL')

	SELECT 
		@PAYMENT_AMOUNT_NET = ATTRIBUTE_056,
		@PAYMENT_AMOUNT_VAT = ATTRIBUTE_057,
		@EXTERNAL_ID = ATTRIBUTE_061
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSM 
	AND SEQ_ID = @EXTERNAL_RECORD_ID

	SET @PAYMENT_AMOUNT_NET = ISNULL(@PAYMENT_AMOUNT_NET, 0)
	SET @PAYMENT_AMOUNT_VAT = ISNULL(@PAYMENT_AMOUNT_VAT, 0)

		-- Additional Rate
	SET @ADDITIONAL_PAYMENT_AMOUNT_NET = 0
	SET @ADDITIONAL_PAYMENT_AMOUNT_VAT = 0


	SELECT @ADDITIONAL_PAYMENT_AMOUNT_NET = ISNULL(SUM(CAST(ATTRIBUTE_003 AS MONEY)), 0), @ADDITIONAL_PAYMENT_AMOUNT_VAT = ISNULL(SUM(CAST(ATTRIBUTE_004 AS MONEY)),0)
	FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH (NOLOCK)
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
	AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR 
	--AND ATTRIBUTE_002 = @EXTERNAL_ID
	AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57036 AND ISNULL(ATTRIBUTE_STRING,'')=@EXTERNAL_ID)
	
	
	IF @ADDITIONAL_PAYMENT_AMOUNT_NET > 0
	BEGIN
		SET @PAYMENT_AMOUNT_NET = @PAYMENT_AMOUNT_NET - @ADDITIONAL_PAYMENT_AMOUNT_NET
		SET @PAYMENT_AMOUNT_VAT = @PAYMENT_AMOUNT_VAT - @ADDITIONAL_PAYMENT_AMOUNT_VAT
	END

	SET @GROSS_AMOUNT = @PAYMENT_AMOUNT_NET + @PAYMENT_AMOUNT_VAT

	DECLARE CUR_MR CURSOR STATIC LOCAL FOR
		SELECT ATTRIBUTE_001, ATTRIBUTE_002, ATTRIBUTE_003, ATTRIBUTE_004, ATTRIBUTE_007, ATTRIBUTE_008, ATTRIBUTE_009, ATTRIBUTE_017 
		FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH (NOLOCK)
		WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MR 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		--AND ATTRIBUTE_004 = @MEMBER_CATEGORY
		AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MR AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52103 AND ISNULL(ATTRIBUTE_DECIMAL,0)=@MEMBER_CATEGORY)
		AND ISNULL(DELETED,'N') = 'N' 

	OPEN CUR_MR

	FETCH NEXT FROM CUR_MR INTO @RATE_NAME, @RATE_TYPE, @RATE_TYPE_NAME, @MEMBER_CATEGORY, @RATE_AMOUNT, @LEDGER_ACCOUNT, @LEDGER_ACCOUNT_DESCRIPTION, @QUANTITY

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SELECT @MSUB_RATE = ATTRIBUTE_008, @CREDIT_RATE = ATTRIBUTE_009, @LOGIN_RATE = ATTRIBUTE_014 
		FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
		WHERE ISNULL(DELETED,'N') = 'N' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MRT 
		AND SEQ_ID = @RATE_TYPE 

		IF ISNULL(@MSUB_RATE, 'N') = 'N'
		BEGIN
			SET @TMP_PAYMENT_AMOUNT_NET = 0
			SET @TMP_PAYMENT_AMOUNT_VAT = 0
			SET @TMP_GROSS_AMOUNT = 0
		END
		ELSE
		BEGIN
			SET @TMP_PAYMENT_AMOUNT_NET = @PAYMENT_AMOUNT_NET
			SET @TMP_PAYMENT_AMOUNT_VAT = @PAYMENT_AMOUNT_VAT
			SET @TMP_GROSS_AMOUNT = @GROSS_AMOUNT
		END
		
		IF ISNULL(@CREDIT_RATE, 'N') = 'N' AND ISNULL(@LOGIN_RATE, 'N') = 'N'
		
		IF ISNULL(@QUANTITY,0)=0
			SET @QUANTITY = 1 
			
		BEGIN
			EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_001 = @RATE_NAME,
				@ATTRIBUTE_002 = @MEMBER,
				@ATTRIBUTE_003 = @MEMBER_ID,
				@ATTRIBUTE_004 = @FISCAL_PERIOD,
				@ATTRIBUTE_005 = @TMP_PAYMENT_AMOUNT_NET,
				@ATTRIBUTE_006 = @TMP_PAYMENT_AMOUNT_VAT,
				@ATTRIBUTE_007 = @TMP_GROSS_AMOUNT,
				@ATTRIBUTE_008 = @RATE_TYPE,
				@ATTRIBUTE_009 = @RATE_TYPE_NAME,
				@ATTRIBUTE_010 = @TMP_GROSS_AMOUNT,
				@ATTRIBUTE_011 = @TMP_GROSS_AMOUNT, --RATE_AMOUNT
				@ATTRIBUTE_012 = 0, --DISCOUNT,
				@ATTRIBUTE_013 = 0, --SURCHARGE,
				@ATTRIBUTE_014 = @QUANTITY, --1 it was hard coded 1 before 1/4/2015 16:44
				@ATTRIBUTE_015 = 0, --VAT_PERCENTAGE,
				@ATTRIBUTE_016 = @TMP_GROSS_AMOUNT, --ACTUAL_RATE_AMOUNT,
				@ATTRIBUTE_017 = NULL, --NEXT_RENEWAL_DATE,
				@ATTRIBUTE_018 = NULL, --PAYMENT_METHOD,
				@ATTRIBUTE_019 = NULL, --PAYMENT_METHOD_DESCRIPTION,
				@ATTRIBUTE_020 = 'N', --DO_NOT_RENEW,
				@ATTRIBUTE_021 = 0, --VAT_RATE,
				@ATTRIBUTE_022 = NULL, --VAT_RATE_NAME,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MAR,
				@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
				@CREATED_BY = @USER,
				@RETURN_SEQ_ID = @MEMBER_ASSIGNED_RATE OUTPUT,
				@ERROR = @ERROR OUTPUT,
				@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

				-- record data in member ledger
				IF @TMP_GROSS_AMOUNT > 0
				BEGIN
					EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
					@ATTRIBUTE_001 = @RATE_NAME,
					@ATTRIBUTE_002 = 'New',
					@ATTRIBUTE_003 = @RATE_TYPE_NAME,
					@ATTRIBUTE_004 = @FISCAL_PERIOD,
					@ATTRIBUTE_005 = @TODAY,
					@ATTRIBUTE_006 = NULL,
					@ATTRIBUTE_007 = @TMP_GROSS_AMOUNT,
					@ATTRIBUTE_008 = NULL,
					@ATTRIBUTE_009 = NULL,
					@ATTRIBUTE_010 = @MEMBER,
					@ATTRIBUTE_011 = @MEMBER_ID, 
					@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ML,
					@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
					@CREATED_BY = @USER,
					@RETURN_SEQ_ID = @MEMBER_LEDGER OUTPUT,
					@ERROR = @ERROR OUTPUT,
					@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
				END
		END

		FETCH NEXT FROM CUR_MR INTO @RATE_NAME, @RATE_TYPE, @RATE_TYPE_NAME, @MEMBER_CATEGORY, @RATE_AMOUNT, @LEDGER_ACCOUNT, @LEDGER_ACCOUNT_DESCRIPTION, @QUANTITY
	END
	CLOSE CUR_MR
	DEALLOCATE CUR_MR

	-- additional rates

	DECLARE CUR_MR CURSOR STATIC LOCAL FOR
		SELECT ATTRIBUTE_001, ATTRIBUTE_003, ATTRIBUTE_004, ATTRIBUTE_005 
		FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
		WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR 
		--AND ATTRIBUTE_002 = @EXTERNAL_ID
		AND CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_WSMAR AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57036 AND ISNULL(ATTRIBUTE_STRING,'')= @EXTERNAL_ID)
		
	OPEN CUR_MR

	FETCH NEXT FROM CUR_MR INTO @RATE_TYPE_NAME, @PAYMENT_AMOUNT_NET, @PAYMENT_AMOUNT_VAT, @GROSS_AMOUNT

	WHILE @@FETCH_STATUS = 0
	BEGIN
		-- GET RATE TYPE
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MRT, @ATTRIBUTE_DISPLAY_NAME = 'RATE_TYPE', @OPERATOR_ID = 3, @SEARCH_VALUE = @RATE_TYPE_NAME, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @RATE_TYPE OUTPUT, @DESCRIPTION = @RATE_TYPE_NAME OUTPUT

		EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
			@ATTRIBUTE_001 = @RATE_TYPE_NAME,
			@ATTRIBUTE_002 = @MEMBER,
			@ATTRIBUTE_003 = @MEMBER_ID,
			@ATTRIBUTE_004 = @FISCAL_PERIOD,
			@ATTRIBUTE_005 = @PAYMENT_AMOUNT_NET,
			@ATTRIBUTE_006 = @PAYMENT_AMOUNT_VAT,
			@ATTRIBUTE_007 = @GROSS_AMOUNT,
			@ATTRIBUTE_008 = @RATE_TYPE,
			@ATTRIBUTE_009 = @RATE_TYPE_NAME,
			@ATTRIBUTE_010 = @GROSS_AMOUNT,
			@ATTRIBUTE_011 = @GROSS_AMOUNT, --RATE_AMOUNT
			@ATTRIBUTE_012 = 0, --DISCOUNT,
			@ATTRIBUTE_013 = 0, --SURCHARGE,
			@ATTRIBUTE_014 = 1, --QUANTITY
			@ATTRIBUTE_015 = 0, --VAT_PERCENTAGE,
			@ATTRIBUTE_016 = @GROSS_AMOUNT, --ACTUAL_RATE_AMOUNT,
			@ATTRIBUTE_017 = NULL, --NEXT_RENEWAL_DATE,
			@ATTRIBUTE_018 = NULL, --PAYMENT_METHOD,
			@ATTRIBUTE_019 = NULL, --PAYMENT_METHOD_DESCRIPTION,
			@ATTRIBUTE_020 = 'N', --DO_NOT_RENEW,
			@ATTRIBUTE_021 = 0, --VAT_RATE,
			@ATTRIBUTE_022 = NULL, --VAT_RATE_NAME,
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MAR,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@CREATED_BY = @USER,
			@RETURN_SEQ_ID = @MEMBER_ASSIGNED_RATE OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

			-- record data in member ledger
			IF @GROSS_AMOUNT > 0
			BEGIN
				EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
					@ATTRIBUTE_001 = @RATE_NAME,
					@ATTRIBUTE_002 = 'New',
					@ATTRIBUTE_003 = @RATE_TYPE_NAME,
					@ATTRIBUTE_004 = @FISCAL_PERIOD,
					@ATTRIBUTE_005 = @TODAY,
					@ATTRIBUTE_006 = NULL,
					@ATTRIBUTE_007 = @GROSS_AMOUNT,
					@ATTRIBUTE_008 = NULL,
					@ATTRIBUTE_009 = NULL,
					@ATTRIBUTE_010 = @MEMBER,
					@ATTRIBUTE_011 = @MEMBER_ID, 
					@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_ML,
					@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
					@CREATED_BY = @USER,
					@RETURN_SEQ_ID = @MEMBER_LEDGER OUTPUT,
					@ERROR = @ERROR OUTPUT,
					@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
			END

		FETCH NEXT FROM CUR_MR INTO @RATE_TYPE_NAME, @PAYMENT_AMOUNT_NET, @PAYMENT_AMOUNT_VAT, @GROSS_AMOUNT
	END
	CLOSE CUR_MR
	DEALLOCATE CUR_MR

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END







;


-- *****************************************************************************************************************
-- Created By: Adeel Hassan
-- Date Created: 25/02/2025
-- Summary: A process to return total number of delegates booked for a given event programme / delegate type
--******************************************************************************************************************
CREATE PROCEDURE [dbo].[GET_DELEGATES_COUNT]
	@p_RECORD_ID BIGINT,					-- SEQ_ID OF EVENT PROGRAMME
	@p_GUID NVARCHAR(100),					-- GUID of relevant API Temp Event Registration
	@p_DELEGATE_TYPE BIGINT,			    -- DELEGATE TYPE
	@p_BOOKING_FORMAT NVARCHAR(100),		-- BOOKING FORMAT
	@p_USER_EMAIL NVARCHAR(200),			-- EMAIL OF oomi USER
	@p_DELEGATES_COUNT NVARCHAR(10) OUTPUT  -- DELEGATES Count
AS
BEGIN
	
	DECLARE @p_CLIENT_ID BIGINT
	DECLARE @API_TEMP_DELEGATE_ENTITY_ID BIGINT = 112966
	DECLARE @PROGRAMME_IDS_ATTRIBUTE_SEQ_ID BIGINT = 3066796
	DECLARE @GUID_ATTRIBUTE_SEQ_ID BIGINT = 3067146
	DECLARE @DELEGATE_TYPE_ATTRIBUTE_SEQ_ID BIGINT = 3067035
	DECLARE @BOOKING_FORMAT_ATTRIBUTE_SEQ_ID BIGINT = 3066795
	DECLARE @DUPLICATE_BOOKING_ATTRIBUTE_SEQ_ID BIGINT = 3067074

	IF (ISNULL(@p_USER_EMAIL, '') = '') OR ISNULL(@p_RECORD_ID, 0) = 0
	BEGIN
		PRINT 'MISSING REQUIRED PARAMETER'
		RETURN
	END
	ELSE
	BEGIN
		DECLARE @SELECT_STATEMENT NVARCHAR(MAX)

		-- GET CLIENT BASED ON USER
		SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USER_EMAIL

		IF (ISNULL(@p_CLIENT_ID, 0) != 0) 
		BEGIN
			SET @SELECT_STATEMENT = 'SELECT @p_DELEGATES_COUNT = COUNT(API_DELEGATE.SEQ_ID) ' + 
									'FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + ']..CUS_ENTITY_DATA API_DELEGATE
									 INNER JOIN [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + ']..CUS_PIVOT_NON_UNIQUE_INDEXES PIV_GUID ON PIV_GUID.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @GUID_ATTRIBUTE_SEQ_ID
									 AND PIV_GUID.CUS_ENTITY_DATA_SEQ_ID = API_DELEGATE.SEQ_ID AND PIV_GUID.ATTRIBUTE_STRING = @p_GUID

									 INNER JOIN [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + ']..CUS_PIVOT_NON_UNIQUE_INDEXES PIV_DUPID ON PIV_DUPID.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @DUPLICATE_BOOKING_ATTRIBUTE_SEQ_ID
									 AND PIV_DUPID.CUS_ENTITY_DATA_SEQ_ID = API_DELEGATE.SEQ_ID AND ISNULL(PIV_DUPID.ATTRIBUTE_BOOLEAN, ''N'') != ''Y''

									 INNER JOIN [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + ']..CUS_PIVOT_NON_UNIQUE_INDEXES PIV_PID ON PIV_PID.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @PROGRAMME_IDS_ATTRIBUTE_SEQ_ID
									 AND PIV_PID.CUS_ENTITY_DATA_SEQ_ID = API_DELEGATE.SEQ_ID AND PIV_PID.ATTRIBUTE_STRING LIKE ''%'' + CAST(@p_RECORD_ID AS NVARCHAR(50)) + ''%''
									  ' 
			IF(ISNULL(@p_DELEGATE_TYPE,0)!= 0)
			BEGIN
				SET @SELECT_STATEMENT = @SELECT_STATEMENT + ' INNER JOIN [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + ']..CUS_PIVOT_NON_UNIQUE_INDEXES PIV_DT 
				ON PIV_DT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @DELEGATE_TYPE_ATTRIBUTE_SEQ_ID  AND PIV_DT.CUS_ENTITY_DATA_SEQ_ID = API_DELEGATE.SEQ_ID 
				AND PIV_DT.ATTRIBUTE_DECIMAL = @p_DELEGATE_TYPE '
			END
			IF(ISNULL(@p_BOOKING_FORMAT, '') != '')
			BEGIN
				SET @SELECT_STATEMENT = @SELECT_STATEMENT +' INNER JOIN [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + ']..CUS_PIVOT_NON_UNIQUE_INDEXES PIV_BF 
				ON PIV_BF.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @BOOKING_FORMAT_ATTRIBUTE_SEQ_ID AND PIV_BF.CUS_ENTITY_DATA_SEQ_ID = API_DELEGATE.SEQ_ID 
				AND PIV_BF.ATTRIBUTE_STRING = @p_BOOKING_FORMAT'
			END
			
			SET @SELECT_STATEMENT = @SELECT_STATEMENT + ' WHERE API_DELEGATE.SRM_CLIENT_ENTITIES_SEQ_ID = @API_TEMP_DELEGATE_ENTITY_ID ' + 'AND ISNULL(API_DELEGATE.DELETED, ''N'') = ''N'''
			-- Executing dynamic query with OUTPUT parameter
			PRINT @SELECT_STATEMENT

			EXEC sp_executesql @SELECT_STATEMENT, 
				N'@p_DELEGATES_COUNT INT OUTPUT, @p_GUID NVARCHAR(100), @p_RECORD_ID BIGINT, @API_TEMP_DELEGATE_ENTITY_ID BIGINT, @GUID_ATTRIBUTE_SEQ_ID BIGINT, @PROGRAMME_IDS_ATTRIBUTE_SEQ_ID BIGINT,@BOOKING_FORMAT_ATTRIBUTE_SEQ_ID BIGINT,@DELEGATE_TYPE_ATTRIBUTE_SEQ_ID BIGINT,@p_DELEGATE_TYPE BIGINT, @DUPLICATE_BOOKING_ATTRIBUTE_SEQ_ID BIGINT, @p_BOOKING_FORMAT NVARCHAR(100)', 
				@p_DELEGATES_COUNT = @p_DELEGATES_COUNT OUTPUT, 
				@p_GUID = @p_GUID, 
				@p_RECORD_ID = @p_RECORD_ID, 
				@API_TEMP_DELEGATE_ENTITY_ID = @API_TEMP_DELEGATE_ENTITY_ID,
				@PROGRAMME_IDS_ATTRIBUTE_SEQ_ID = @PROGRAMME_IDS_ATTRIBUTE_SEQ_ID,
				@GUID_ATTRIBUTE_SEQ_ID = @GUID_ATTRIBUTE_SEQ_ID,
				@DELEGATE_TYPE_ATTRIBUTE_SEQ_ID = @DELEGATE_TYPE_ATTRIBUTE_SEQ_ID,
				@BOOKING_FORMAT_ATTRIBUTE_SEQ_ID = @BOOKING_FORMAT_ATTRIBUTE_SEQ_ID,
				@p_DELEGATE_TYPE = @p_DELEGATE_TYPE,
				@DUPLICATE_BOOKING_ATTRIBUTE_SEQ_ID = @DUPLICATE_BOOKING_ATTRIBUTE_SEQ_ID,
				@p_BOOKING_FORMAT = @p_BOOKING_FORMAT;

			-- Final output
			SELECT @p_DELEGATES_COUNT
		END
	END
END
;






-- EXEC DBO.GET_DELETE_COMPLETE_CLIENT @SRM_CLIENTS_SEQ_ID = 146

-- Author: Rauf Gill
CREATE PROCEDURE [dbo].[GET_DELETE_COMPLETE_CLIENT]
	@SRM_CLIENTS_SEQ_ID BigInt
AS
	DECLARE @SRM_ENTITIES_SEQ_ID BIGINT
	DECLARE @WFL_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_FILTER_VIEWS_SEQ_ID BIGINT
	DECLARE @CLIENT_NAME NVARCHAR(200)
	DECLARE @IS_LIVE NVARCHAR(200)
	DECLARE @DELETED NVARCHAR(200)

	SET @IS_LIVE = 'Y'
	SET @DELETED = 'N'

	IF @SRM_CLIENTS_SEQ_ID = 0 OR @SRM_CLIENTS_SEQ_ID IS NULL OR NOT EXISTS(SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW]..SRM_CLIENTS WHERE SEQ_ID = @SRM_CLIENTS_SEQ_ID)
	BEGIN
		PRINT 'PLEASE PROVIDE A VALID CLIENT ID. PROCESS TERMINATED !!!'
		RETURN
	END

	SELECT @CLIENT_NAME = CLIENT_NAME, @DELETED = DELETED FROM [SRM-FRAMEWORK_NEW]..SRM_CLIENTS WHERE SEQ_ID = @SRM_CLIENTS_SEQ_ID
	IF @CLIENT_NAME NOT LIKE '%DELETE%' OR @DELETED <> 'Y'
	BEGIN
		PRINT 'THIS CLIENT CANNOT BE DELETED. CLIENT NAME IN [SRM_CLIENTS] TABLE MUST INCLUDE WORD ''DELETE'' ALSO SHOULD BE MARKED AS DELETED IN THE TABLE.'
		RETURN
	END

	SELECT @IS_LIVE = IS_LIVE FROM [SRM-FRAMEWORK_NEW]..SRM_CLIENTS WHERE SEQ_ID = @SRM_CLIENTS_SEQ_ID
	IF @IS_LIVE = 'Y'
	BEGIN
		PRINT 'LIVE CLIENT CANNOT BE DELETED'
		RETURN
	END

	--RETURN

	DELETE FROM QRY_OUTPUT_RESULTS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM QRY_OUTPUTS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM QRY_QUERIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM QRY_REPORTS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM QRY_RESULTS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM QRY_TEMPLATES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SEC_GROUPS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SEC_OPTIONS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SEC_SETTINGS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_APPLICATION_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_BULK_UPDATE WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_BULK_UPDATE_AREA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_BULK_UPDATE_BUTTON_OPTIONS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_BULK_UPDATE_CLIENT_RULES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_BULK_UPDATE_RULES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_BULK_UPDATE_RULES_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_BULK_UPDATE_SUBAREA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_COMPONENTS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_LANGUAGES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_MENU_ITEMS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_MENU_RELATIONSHIPS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_PAGE_SECTIONS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_REPORTING_SETTINGS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_SETTINGS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_SYSTEM_MODULES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_DASHBOARDS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_DEPARTMENTS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_MODULE_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_MODULE_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_MODULE_CLIENT_ENTITY_BUTTONS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_MODULE_FEATURES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_MODULE_WORKFLOWS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_RECENT_ITEMS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_REPLICATION_RECEIVERS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_REPLICATION_SENDERS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_SCHEDULES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_SYSTEM_EMAIL_TEMPLATES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_USERS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_ENTITY_DETAILS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_MAILCHIMP_SCHEDULE WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_ENTITY_RULES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENT_FILTER_VIEW_DEFAULT WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

	-- DELETE FILTERVIEWS
	DECLARE CUR_FILTER_VIEWS CURSOR FOR 
	SELECT DISTINCT SEQ_ID FROM SRM_CLIENT_FILTER_VIEWS WHERE SRM_CLIENT_ENTITIES_SEQ_ID IN (SELECT SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)
	UNION 
	SELECT DISTINCT SEQ_ID FROM SRM_CLIENT_FILTER_VIEWS WHERE SRM_CLIENT_ENTITIES_SEQ_ID2 IN (SELECT SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)

	OPEN CUR_FILTER_VIEWS
	FETCH NEXT FROM CUR_FILTER_VIEWS INTO @SRM_CLIENT_FILTER_VIEWS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		EXECUTE DBO.GET_DELETE_FILTER_VIEW
			@SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID

		FETCH NEXT FROM CUR_FILTER_VIEWS INTO @SRM_CLIENT_FILTER_VIEWS_SEQ_ID
	END
	CLOSE CUR_FILTER_VIEWS 
	DEALLOCATE CUR_FILTER_VIEWS 


	-- DELETE ENTITIES
	DECLARE CUR_ENTITIES CURSOR FOR 
	SELECT SRM_ENTITIES_SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

	OPEN CUR_ENTITIES
	FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		EXECUTE DBO.GET_DELETE_ENTITY
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID ,
			@SRM_ENTITIES_SEQ_ID = @SRM_ENTITIES_SEQ_ID 

		FETCH NEXT FROM CUR_ENTITIES INTO @SRM_ENTITIES_SEQ_ID
	END
	CLOSE CUR_ENTITIES 
	DEALLOCATE CUR_ENTITIES 

	-- DELETE WORKFLOWS
	DECLARE CUR_WORKFLOWS CURSOR FOR 
	SELECT SEQ_ID FROM [SRM-WORKFLOW].DBO.WFL_WORKFLOWS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

	OPEN CUR_WORKFLOWS
	FETCH NEXT FROM CUR_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		EXECUTE DBO.GET_DELETE_WORKFLOW_INCLUDING_DESIGN
			@WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

		FETCH NEXT FROM CUR_WORKFLOWS INTO @WFL_WORKFLOWS_SEQ_ID
	END
	CLOSE CUR_WORKFLOWS 
	DEALLOCATE CUR_WORKFLOWS 

	DELETE FROM SRM_USERS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	DELETE FROM SRM_CLIENTS WHERE SEQ_ID = @SRM_CLIENTS_SEQ_ID


;







-- Author: Rauf Gill
CREATE PROCEDURE [dbo].[GET_DELETE_ENTITY]
	@SRM_CLIENTS_SEQ_ID BIGINT,
	@SRM_ENTITIES_SEQ_ID BIGINT

AS
	IF ISNULL(@SRM_CLIENTS_SEQ_ID, 0) = 0 OR ISNULL(@SRM_ENTITIES_SEQ_ID, 0) = 0
	BEGIN
		PRINT 'CLIENT OR ENTIITY SEQ ID MISSING'
		RETURN
	END

	DECLARE @SRM_CLIENT_ENTITY_SEQ_ID BIGINT
	DECLARE @SYSTEM_ENTITY CHAR(1)

	SET @SYSTEM_ENTITY = 'N'

	DECLARE CUR_ENTITY CURSOR FOR 
	SELECT SEQ_ID FROM SRM_ENTITIES WHERE SEQ_ID = @SRM_ENTITIES_SEQ_ID

	OPEN CUR_ENTITY

	FETCH NEXT FROM CUR_ENTITY INTO @SRM_ENTITIES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SELECT @SRM_CLIENT_ENTITY_SEQ_ID = SEQ_ID, @SYSTEM_ENTITY = SYSTEM_ENTITY FROM SRM_CLIENT_ENTITIES WHERE SRM_ENTITIES_SEQ_ID = @SRM_ENTITIES_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		DELETE FROM SRM_CLIENT_ENTITY_RULES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID 
		DELETE FROM SRM_CLIENT_ENTITY_RULES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IN (SELECT SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID)
		DELETE FROM SRM_CLIENT_ENTITY_LOOKUP_FILTERS WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IN (SELECT SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID)
		DELETE FROM SRM_CLIENT_MENU_RELATIONSHIPS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID 
		DELETE FROM SRM_CLIENT_FILTER_VIEW_DEFAULT WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID 
		EXECUTE DBO.SYS_DELETE_ENTITY_METADATA @ENTITY_SEQ_ID = @SRM_ENTITIES_SEQ_ID, @CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		UPDATE SRM_CLIENT_ENTITY_ATTRIBUTES SET SRM_CLIENT_ENTITIES_SEQ_ID2 = NULL WHERE SRM_CLIENT_ENTITIES_SEQ_ID2 = @SRM_CLIENT_ENTITY_SEQ_ID 
		DELETE FROM SRM_CLIENT_ENTITY_RELATED_LIST_USER_DEFAULT WHERE (SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID OR SRM_CLIENT_ENTITIES_SEQ_ID2 = @SRM_CLIENT_ENTITY_SEQ_ID)
		DELETE FROM SRM_CLIENT_ENTITY_SUB_RELATED_LISTS WHERE (SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID OR SRM_CLIENT_ENTITIES_SEQ_ID2 = @SRM_CLIENT_ENTITY_SEQ_ID)
		DELETE FROM SRM_CLIENT_ENTITY_RELATED_LISTS WHERE (SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID OR SRM_CLIENT_ENTITIES_SEQ_ID2 = @SRM_CLIENT_ENTITY_SEQ_ID)
		DELETE FROM SRM_CLIENT_PAGE_COMPONENTS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID 
		
		
		
		DELETE FROM SRM_CLIENT_ENTITIES WHERE SRM_ENTITIES_SEQ_ID = @SRM_ENTITIES_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		IF @SYSTEM_ENTITY = 'N'
		BEGIN
			DELETE FROM SRM_ENTITIES WHERE SEQ_ID = @SRM_ENTITIES_SEQ_ID
		END

		FETCH NEXT FROM CUR_ENTITY INTO @SRM_ENTITIES_SEQ_ID
	END

	CLOSE CUR_ENTITY
	DEALLOCATE CUR_ENTITY

/*
SEC_GROUP_RIGHTS
SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS
SRM_CLIENT_ENTITY_ATTRIBUTES
SRM_CLIENT_ENTITY_BUTTONS
SRM_CLIENT_ENTITY_BUTTONS_RM
SRM_CLIENT_ENTITY_LOOKUP_FILTERS

SRM_CLIENT_PAGE_COMPONENTS
SRM_DELETED_DATA_QUERY
*/


;







-- Author: Rauf Gill
CREATE PROCEDURE [dbo].[GET_DELETE_FILTER_VIEW]
	@SRM_CLIENT_FILTER_VIEWS_SEQ_ID BIGINT
AS
	DECLARE CUR_VIEWS CURSOR FOR 
		SELECT SEQ_ID FROM SRM_CLIENT_FILTER_VIEWS 
		WHERE SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID

	OPEN CUR_VIEWS

	FETCH NEXT FROM CUR_VIEWS INTO @SRM_CLIENT_FILTER_VIEWS_SEQ_ID
	WHILE @@FETCH_STATUS = 0
	BEGIN
		DELETE FROM SRM_CLIENT_FILTER_VIEW_BUTTONS WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID 
		DELETE FROM SRM_CLIENT_FILTER_VIEW_CRITERIA WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID 
		DELETE FROM SRM_CLIENT_FILTER_VIEW_DEFAULT WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID 
		DELETE FROM SRM_CLIENT_FILTER_VIEW_ATTRIBUTES WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID 
		DELETE FROM SRM_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 35 AND OBJECT_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID
		DELETE FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 35 AND OBJECT_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID
		DELETE FROM SRM_CLIENT_FILTER_VIEWS WHERE SEQ_ID = @SRM_CLIENT_FILTER_VIEWS_SEQ_ID

		FETCH NEXT FROM CUR_VIEWS INTO @SRM_CLIENT_FILTER_VIEWS_SEQ_ID
	END
	CLOSE CUR_VIEWS
	DEALLOCATE CUR_VIEWS


;







-- Author: Rauf Gill
CREATE PROCEDURE [dbo].[GET_DELETE_WORKFLOW_INCLUDING_DESIGN]
	@WFL_WORKFLOWS_SEQ_ID BigInt,
	@SRM_CLIENTS_SEq_ID BigInt
AS

	IF ISNULL(@SRM_CLIENTS_SEQ_ID, 0) = 0 OR ISNULL(@WFL_WORKFLOWS_SEQ_ID, 0) = 0
	BEGIN
		PRINT 'CLIENT OR WORKFLOW SEQ ID MISSING'
		RETURN
	END


	DECLARE @DELETE_WORKFLOW_HEADER CHAR(1)

	SET @DELETE_WORKFLOW_HEADER = 'Y'

	IF NOT EXISTS(SELECT SEQ_ID FROM [SRM-WORKFLOW].DBO.WFL_WORKFLOWS WHERE SEQ_ID = @WFL_WORKFLOWS_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)
	BEGIN
		PRINT 'THIS WORKFLOW DOES NOT MATCH WITH GIVEN CLIENT'
		RETURN
	END

	IF @DELETE_WORKFLOW_HEADER = 'Y'
	BEGIN
		DELETE FROM [SRM-WORKFLOW].DBO.WFL_WORKFLOW_STARTING_OPTIONS WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID
	END

	DELETE FROM [SRM-WORKFLOW].DBO.WFL_TASK_DETAILS
	WHERE WFL_TASKS_SEQ_ID IN (select seq_id FROM [SRM-WORKFLOW].DBO.WFL_TASKS
	WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID) --AND ISNULL(DELETED, 'N') = 'Y'

	DELETE FROM [SRM-WORKFLOW].DBO.WFL_TASK_DETAILS
	WHERE WFL_TASK_CONDITIONS_SEQ_ID IN (select seq_id FROM [SRM-WORKFLOW].DBO.WFL_TASK_CONDITIONS where WFL_TASKS_SEQ_ID2 in (select seq_id FROM [SRM-WORKFLOW].DBO.WFL_TASKS
	WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID))

	delete from [SRM-WORKFLOW].DBO.WFL_TASK_CONDITIONS
	where WFL_TASKS_SEQ_ID in (select seq_id FROM [SRM-WORKFLOW].DBO.WFL_TASKS
	WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID) --AND ISNULL(DELETED, 'N') = 'Y'

	delete from [SRM-WORKFLOW].DBO.WFL_TASK_CONDITIONS
	where WFL_TASKS_SEQ_ID2 in (select seq_id FROM [SRM-WORKFLOW].DBO.WFL_TASKS
	WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID)

	DELETE FROM [SRM-WORKFLOW].DBO.WFL_VARIABLES
	WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID --AND ISNULL(DELETED, 'N') = 'Y'

	DELETE FROM [SRM-WORKFLOW].DBO.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID --AND ISNULL(DELETED, 'N') = 'Y'

	IF @DELETE_WORKFLOW_HEADER = 'Y'
	BEGIN
		DELETE FROM [SRM-WORKFLOW].DBO.WFL_WORKFLOWS WHERE SEQ_ID = @WFL_WORKFLOWS_SEQ_ID
	END
	-- DELETE DESIGN
	DELETE FROM [SRM-WORKFLOW].DBO.WFL_DESIGNER_TASK_DETAILS WHERE WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID
	DELETE FROM [SRM-WORKFLOW].DBO.WFL_DESIGNER_VARIABLES WHERE WFL_WORKFLOW_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID
	DELETE FROM [SRM-WORKFLOW].DBO.WFL_DESIGNER_CONNECTIONS WHERE WFL_WORKFLOW_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID



;

