-- =============================================
-- Author:		Rauf Gill
-- Create date: 24/11/2017
-- Description:	Do not change its frequency, it should run only once a day
-- =============================================
CREATE PROCEDURE [dbo].[GET_FIX_DATA_ISSUES_RUN_ONCE_A_DAY]
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	--SET NOCOUNT ON;

	-- Start Update LCVP Stakeholder
	UPDATE CONTACT 
	SET 	
		CONTACT.ATTRIBUTE_204 = MEMBER.ATTRIBUTE_068, --	STAKEHOLDER
		CONTACT.ATTRIBUTE_205 = MEMBER.ATTRIBUTE_069,  --	STAKEHOLDER_NAME
		DATE_MODIFIED = GETDATE(),
		MODIFIED_BY = 'LCVP'
	FROM [SRM-CustomEntities_41]..CUS_ENTITY_DATA CONTACT WITH (NOLOCK) 
	INNER JOIN [SRM-CustomEntities_41]..CUS_ENTITY_DATA MEMBER ON CONTACT.ATTRIBUTE_058 = MEMBER.ATTRIBUTE_015 AND MEMBER.SRM_CLIENT_ENTITIES_SEQ_ID = 10268 AND (MEMBER.DELETED = 'N' OR MEMBER.DELETED IS NULL)
	WHERE CONTACT.SRM_CLIENT_ENTITIES_SEQ_ID = 10254
		AND (CONTACT.DELETED = 'N' OR CONTACT.DELETED IS NULL)
		AND ISNULL(CONTACT.ATTRIBUTE_058, 0) <> 0
		AND ISNULL(CONTACT.ATTRIBUTE_204, '') <> ISNULL(MEMBER.ATTRIBUTE_068, '')

	EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE
		@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 278315

	EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE
		@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 278316

	-- End Update LCVP Stakeholder
END


;





-- AUTHOR: RAUF GILL
-- DATED: 12/01/2016
CREATE PROCEDURE [dbo].[GET_GENERATE_EXCEL_WITH_COLUMNS]
(
    @db_name varchar(100),
    @table_name varchar(100),   
    @file_name  varchar(100)
)
as
	declare @columns varchar(8000), @sql varchar(8000), @data_file varchar(100)
	DECLARE @COLUMN_NAME VARCHAR(200)
	DECLARE @DATA_TYPE VARCHAR(200)
	DECLARE @sqlColumns varchar(8000)
	DECLARE @QUERY NVARCHAR(MAX)
	
	SET @sqlColumns = ''
	SET @QUERY = 'USE ' + @db_name  +';'
	EXEC ( @QUERY)
	
	DECLARE CUR_COLUMNS CURSOR FOR
	
	SELECT COLUMN_NAME, DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @table_name ORDER BY ORDINAL_POSITION
	 
	
	OPEN CUR_COLUMNS 
	
	FETCH NEXT FROM CUR_COLUMNS INTO @COLUMN_NAME, @DATA_TYPE
	
	PRINT @COLUMN_NAME + ' ' + @DATA_TYPE;
	
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF @COLUMN_NAME = 'SEQ_ID'
		BEGIN
			PRINT 'IGNORE THIS AND ADD AT THE END'
		END
		ELSE IF @DATA_TYPE = 'DATETIME'
		BEGIN
			IF @sqlColumns = ''
				SET @sqlColumns = 'convert(varchar(10), [' + @COLUMN_NAME + '], 121)'
			ELSE
				SET @sqlColumns = @sqlColumns + ', convert(varchar(10), [' + @COLUMN_NAME + '], 121)'
		END
		ELSE
		BEGIN
			IF @sqlColumns = ''
				SET @sqlColumns = '[' + @COLUMN_NAME + ']'
			ELSE
				SET @sqlColumns = @sqlColumns + ', [' + @COLUMN_NAME + ']'
			SET @sql = 'UPDATE ' + @table_name + ' SET [' + @COLUMN_NAME + '] = [dbo].[ReplaceSpecialCharaters]([' + @COLUMN_NAME + '])'
		END
		
		PRINT @sql
		EXECUTE (@sql) 
		
		FETCH NEXT FROM CUR_COLUMNS INTO @COLUMN_NAME, @DATA_TYPE
	END
	CLOSE CUR_COLUMNS 
	DEALLOCATE CUR_COLUMNS 
	
	SET @sqlColumns = @sqlColumns + ', [SEQ_ID]'
	
	--Generate column names as a recordset
	select 
		@columns=coalesce(@columns+',','')+column_name+' as ['+column_name + ']'
	from 
		information_schema.columns
	where 
		table_name=@table_name
		and column_name <> 'SEQ_ID'
	ORDER BY ORDINAL_POSITION
	
	select @columns=''''''+replace(replace(@columns,' as ',''''' as '),',',',''''')
	set @columns = @columns + ',''''SEQ_ID'''' AS [SEQ_ID]'

	--Create a dummy file to have actual data
	select @data_file=substring(@file_name,1,len(@file_name)-charindex('\',reverse(@file_name)))+'\data_file.xls'
	print @data_file

	--Generate column names in the passed EXCEL file
	set @sql='exec master..xp_cmdshell ''bcp " select * from (select '+@columns+') as t" queryout "'+@file_name+'" -c -T -C 1252'''
	print @sql
	exec(@sql)

	--Generate data in the dummy file
	set @sql='exec master..xp_cmdshell ''bcp "select ' + @sqlColumns + ' from ' + @db_name + '.dbo.'+@table_name+' ORDER BY SEQ_ID" queryout "'+@data_file+'" -c -T -C 1252'''
	print @sql
	exec(@sql)
	
	--Copy dummy file to passed EXCEL file
	set @sql= 'exec master..xp_cmdshell ''type '+@data_file+' >> "'+@file_name+'"'''
	print @sql
	exec(@sql)

	--Delete dummy file 
	set @sql= 'exec master..xp_cmdshell ''del '+@data_file+''''
	exec(@sql) 


;





CREATE PROCEDURE [dbo].[GET_HIDE_MODULE]
@CLIENT_ID BIGINT = 0,
@MODULE NVARCHAR(20) = ''

AS

BEGIN
	DECLARE @SQL NVARCHAR(2000)

	IF @CLIENT_ID > 0 AND @MODULE != ''
	BEGIN 

		--MENU
		
		UPDATE dbo.SRM_CLIENT_MENU_RELATIONSHIPS SET VISIBLE = 'N' WHERE SEQ_ID IN (
		SELECT SEQ_ID FROM dbo.SRM_CLIENT_MENU_RELATIONSHIPS AS SCMR WHERE SRM_CLIENTS_SEQ_ID=@CLIENT_ID AND SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID = 0 AND VISIBLE='Y'
		AND SYSTEM_MODULE  = @MODULE)

		IF (@@ROWCOUNT > 0)
			PRINT 'Menu is hidden.'
		ELSE
			PRINT 'Menu is already hidden.'
		

		--RELATED_LISTS
		
		UPDATE dbo.SRM_CLIENT_ENTITY_RELATED_LISTS SET VISIBLE = 'N' WHERE SEQ_ID IN (
		SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_RELATED_LISTS AS SCERL WHERE SRM_CLIENT_ENTITIES_SEQ_ID2 IN (SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITIES AS SCE 
		WHERE SRM_CLIENTS_SEQ_ID=@CLIENT_ID AND SYSTEM_MODULE = @MODULE) AND RANK > 0 AND SCERL.VISIBLE = 'Y')

		IF (@@ROWCOUNT > 0)
			PRINT 'Related lists are hidden.'
		ELSE
			PRINT 'Related lists are already hidden.'
		

		
		--ATTRIBUTES
		UPDATE dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS SET DELETED='Y', DELETED_BY='Hide_Module', DATE_DELETED=GETDATE() WHERE SEQ_ID IN (
		SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS AS SCEAGD WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IN (
		SELECT SCEA.SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA 
		INNER JOIN dbo.SRM_CLIENT_ENTITIES SCE ON SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = SCE.SEQ_ID AND SRM_CLIENTS_SEQ_ID = @CLIENT_ID
		WHERE SCEA.SYSTEM_MODULE= @MODULE AND SCEA.DISPLAY_ATTRIBUTE ='Y' ) AND ISNULL(SCEAGD.DELETED, 'N') != 'Y')

		IF (@@ROWCOUNT > 0)
			PRINT 'Attributes are hidden.'
		ELSE
			PRINT 'Attributes are already hidden.'

		


		--Remove module lookup value
		
		SET @SQL = 'UPDATE [SRM-CustomEntities].dbo.CUS_ENTITY_DATA SET DELETED=''Y'', DELETED_BY=''Hide_Module'', DATE_DELETED=GETDATE() WHERE SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IN (
		SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA WHERE SYSTEM_MODULE=''' + @MODULE + ''' AND SRM_CLIENT_ENTITIES_SEQ_ID IN (
		SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=' + CAST(@CLIENT_ID AS NVARCHAR(10)) + ' AND ENTITY_DISPLAY_NAME=''MODULE'')) 
		AND ATTRIBUTE_BOOLEAN=''Y'')
		AND SRM_CLIENTS_SEQ_ID=' + CAST(@CLIENT_ID AS NVARCHAR(10)) + '
		AND DELETED=''N'' '

		SET @SQL = REPLACE(@SQL,'[SRM-DataPivot]', '[SRM-DataPivot_'+CAST(@CLIENT_ID AS NVARCHAR(10)) + ']')
		EXEC (@SQL)

		IF (@@ROWCOUNT > 0)
			PRINT 'Module Lookup record is deleted.'
		ELSE
			PRINT 'Module Lookup record is already deleted.'
		

		--QUERY_BUILDER
		
		UPDATE dbo.SRM_CLIENT_ENTITIES SET SHOW_IN_QUERYBUILDER = 'N' WHERE SRM_CLIENTS_SEQ_ID=@CLIENT_ID AND system_module=@MODULE AND SHOW_IN_QUERYBUILDER='Y'
		
		IF (@@ROWCOUNT > 0)
			PRINT 'Module is hidden from Query builder.'
		ELSE
			PRINT 'Module is already hidden from Query builder.'
		

	END
	ELSE
		PRINT 'Please provide client id and module to hide module details.'  
END


;




CREATE PROCEDURE [dbo].[GET_HOUSE_KEEPING_DELETE_QUERY_RESULTS]
AS
BEGIN
	SELECT * INTO [SRM-OOMITEMP]..TMP_QRY_RESULTS FROM [SRM-FRAMEWORK_NEW]..QRY_RESULTS WITH (NOLOCK)
	WHERE QRY_QUERIES_SEQ_ID IN (SELECT (SEQ_ID) FROM [SRM-FRAMEWORK_NEW]..QRY_QUERIES WITH (NOLOCK) WHERE ISNULL(IS_RECORD_LEVEL_SECURITY_QUERY, 'N') = 'Y')

	TRUNCATE TABLE [SRM-FRAMEWORK_NEW]..QRY_RESULTS 
	INSERT INTO  [SRM-FRAMEWORK_NEW]..QRY_RESULTS
	(
		QRY_QUERIES_SEQ_ID,
		PARENT_SEQ_ID,
		SRM_CLIENTS_SEQ_ID,
		SOURCE_OF_DATA,
		SOURCE_FILE,
		DATE_MODIFIED,
		MODIFIED_BY,
		DATE_CREATED,
		CREATED_BY,
		DELETED,
		DATE_DELETED,
		DELETED_BY,
		SELECTED
	)
	SELECT 
		QRY_QUERIES_SEQ_ID,
		PARENT_SEQ_ID,
		SRM_CLIENTS_SEQ_ID,
		SOURCE_OF_DATA,
		SOURCE_FILE,
		DATE_MODIFIED,
		MODIFIED_BY,
		DATE_CREATED,
		CREATED_BY,
		DELETED,
		DATE_DELETED,
		DELETED_BY,
		SELECTED
	FROM [SRM-OOMITEMP]..TMP_QRY_RESULTS

	DROP TABLE [SRM-OOMITEMP]..TMP_QRY_RESULTS
END


;




CREATE PROCEDURE [dbo].[GET_HOUSE_KEEPING_DELETE_WORKFLOW_JOBS]
AS
BEGIN

	DECLARE @MAX_WFL_OUTPUT_SEQ_ID BIGINT
	DECLARE @PREVIOUS_YEAR INT

	SET @PREVIOUS_YEAR = YEAR(GETDATE()) - 1

	SELECT TOP 1 @MAX_WFL_OUTPUT_SEQ_ID=SEQ_ID FROM [SRM-Workflow]..WFL_OUTPUT WITH (NOLOCK) ORDER BY SEQ_ID DESC

	SET @MAX_WFL_OUTPUT_SEQ_ID = @MAX_WFL_OUTPUT_SEQ_ID - 3000

	--WFL_OUTPUT WITH BLANK WFL_JOBS_SEQ_ID
	DELETE FROM [SRM-Workflow]..WFL_OUTPUT WHERE SEQ_ID IN (
	SELECT SEQ_ID FROM [SRM-Workflow]..WFL_OUTPUT WITH (NOLOCK) WHERE SEQ_ID < @MAX_WFL_OUTPUT_SEQ_ID AND WFL_JOBS_SEQ_ID IS NULL)


	--WFL_OUTPUT WITH WFL_JOBS_SEQ_ID AND SHOW_IN_JOB ON WFL_WORKFLOW IS 'N'
	DELETE FROM [SRM-Workflow]..WFL_OUTPUT WHERE SEQ_ID IN (
	SELECT SEQ_ID FROM [SRM-Workflow]..WFL_OUTPUT WITH (NOLOCK) WHERE WFL_JOBS_SEQ_ID IS NOT NULL AND WFL_JOBS_SEQ_ID NOT IN (SELECT 
		[Extent1].SEQ_ID
		FROM  [SRM-Workflow].[dbo].[WFL_JOBS] AS [Extent1] with (nolock)
		INNER JOIN [SRM-Workflow].[dbo].[WFL_WORKFLOWS] AS [Extent2] with (nolock) ON [Extent1].[WFL_WORKFLOWS_SEQ_ID] = [Extent2].[SEQ_ID]
		WHERE ('Y' = [Extent2].[SHOW_IN_JOBS] OR YEAR([Extent1].START_DATE) > @PREVIOUS_YEAR)))

	--WFL_JOBS OF EXCLUDING CURRENT YEAR AND SHOW_IN_JOB ON WFL_WORKFLOW IS 'N'
	DELETE FROM [SRM-Workflow]..[WFL_JOBS] WHERE SEQ_ID NOT IN 
	(SELECT 
		[Extent1].SEQ_ID
		FROM  [SRM-Workflow].[dbo].[WFL_JOBS] AS [Extent1] with (nolock)
		INNER JOIN [SRM-Workflow].[dbo].[WFL_WORKFLOWS] AS [Extent2] with (nolock) ON [Extent1].[WFL_WORKFLOWS_SEQ_ID] = [Extent2].[SEQ_ID]
		WHERE ('Y' = [Extent2].[SHOW_IN_JOBS] OR YEAR([Extent1].START_DATE) > @PREVIOUS_YEAR))
END


;




CREATE PROCEDURE [dbo].[GET_HOUSE_KEEPING_MASTER]
AS
BEGIN
	EXEC [SRM-FRAMEWORK_NEW].DBO.GET_HOUSE_KEEPING_DELETE_QUERY_RESULTS
	EXEC [SRM-FRAMEWORK_NEW].DBO.GET_HOUSE_KEEPING_DELETE_WORKFLOW_JOBS
END


;






