CREATE PROCEDURE [dbo].[GET_LOOKUP_DATA_NI]

	@m_LOOKUP_NAME NVarChar(30)  = NULL,

	@m_USER_ID NVarChar(30) = NULL,

	@m_COMPANY_ID NVarChar(10) = NULL,          

	@m_PARM_1 NVarChar(100) = NULL,

	@m_PARM_2 NVarChar(100) = NULL,

	@m_PARM_3 NVarChar(100) = NULL,

	@m_ERROR_ID INT OUTPUT,

	@m_ERROR_DESC NVarChar(100) OUTPUT

AS

	DECLARE @STR_SQL NVARCHAR(4000)
	DECLARE @NATIONALITY_CLIENT_ENTITY_SEQ_ID NVARCHAR(5) = 9858
	DECLARE @COUNTRY_CLIENT_ENTITY_SEQ_ID NVARCHAR(5) = 9877
	DECLARE @SRM_CLIENTS_SEQ_ID NVARCHAR(5) = 40

	SET @m_ERROR_ID = 0

	SET @m_ERROR_DESC = ''	

	SET @STR_SQL = ''

	

	IF ISNULL(@m_USER_ID, '') = ''

		SET @m_USER_ID = 'Videotel'	

	

	IF UPPER(RTRIM(LTRIM(@m_LOOKUP_NAME))) = 'N' 

		SET @STR_SQL = 'SELECT SEQ_ID AS CRM_NATIONALITIES_SEQ_ID,'''' AS NATIONALITY_ID, ATTRIBUTE_001 AS NATIONALITY_DESC FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = '+@SRM_CLIENTS_SEQ_ID+' AND SRM_CLIENT_ENTITIES_SEQ_ID = '+@NATIONALITY_CLIENT_ENTITY_SEQ_ID+' AND DELETED != ''Y''  ORDER BY NATIONALITY_DESC '

	ELSE IF UPPER(RTRIM(LTRIM(@m_LOOKUP_NAME))) = 'C' 

		SET @STR_SQL = 'SELECT SEQ_ID AS CRM_COUNTRIES_SEQ_ID,'''' AS COUNTRY_ID,ATTRIBUTE_001 AS COUNTRY_DESC FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = '+@SRM_CLIENTS_SEQ_ID+' AND SRM_CLIENT_ENTITIES_SEQ_ID = '+@COUNTRY_CLIENT_ENTITY_SEQ_ID+' AND DELETED != ''Y'' ORDER BY COUNTRY_DESC' 

	IF LEN(@STR_SQL) > 0

	BEGIN 

		PRINT (@STR_SQL)	

		EXECUTE(@STR_SQL)

	END

	IF @@Rowcount = 0

	BEGIN

		SET @m_ERROR_ID = -1

		IF UPPER(RTRIM(LTRIM(@m_LOOKUP_NAME))) = 'N' OR UPPER(RTRIM(LTRIM(@m_LOOKUP_NAME))) = 'C' 

			SET @m_ERROR_DESC = 'No Record Found.'

		ELSE

			SET @m_ERROR_DESC = 'Invalid value passed in the Lookup_Name parameter.'	

	END



;


