CREATE PROCEDURE [dbo].[GET_MERGE_RECORDS]   
	 @USER_EMAIL NVARCHAR(100),
	 @CLIENT_ENTITY_SEQ_ID BIGINT,  
	 @MAIN_RECORD_SEQ_ID BIGINT, -- THIS RECORD WON'T BE DELETED  
	 @MAIN_RECORD_DESCRIPTION NVARCHAR(500), -- THIS RECORD WON'T BE DELETED  
	 @SUB_RECORD_SEQ_ID BIGINT, -- THIS RECORD WILL BE DELETED. ITS LINKED RECORDS WILL BE UPDATED WITH @MAIN_RECORD_SEQ_ID  
	 @SUB_RECORD_DESCRIPTION NVARCHAR(500), -- THIS RECORD WILL BE DELETED. ITS LINKED RECORDS WILL BE UPDATED WITH @MAIN_RECORD_SEQ_ID  
	 @CREATED_BY NVARCHAR(500),  
	 @COUNTER BIGINT = 0 ,
	 @OUT_STATUS NVARCHAR(100) OUTPUT  
AS  
	
	 --DECLARE @CHECK_TABLE TABLE  
		--(SEQ_ID BIGINT NULL)  
  
  IF @COUNTER = 0
  BEGIN
		CREATE  TABLE #CHECK_TABLE
			(
				SEQ_ID		BIGINT
			)

	 DECLARE @SUB_CLIENT_ENTITY_SEQ_ID BIGINT  
	 DECLARE @SUB_CLIENT_ENTITY_DISPLAY_NAME NVARCHAR(200)  
  
	 DECLARE @ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID BIGINT  
	 DECLARE @ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME NVARCHAR(200)  
	 DECLARE @DESC_FIELD_CLIENT_ATTRIBUTE_SEQ_ID BIGINT  
	 DECLARE @DESC_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME NVARCHAR(200)  
	 DECLARE @DESC_FIELD_ATTRIBUTE_DATA_TYPE_SEQ_ID BIGINT
	 DECLARE @CUSTOM_ENTITIES_SEQ_ID BIGINT  
	 DECLARE @sqlCommand nvarchar(1000)

	 DECLARE @MAIN_RECORD_CUSTOMER_NUMBER BIGINT = 0
	 DECLARE @SUB_RECORD_CUSTOMER_NUMBER BIGINT = 0
	 DECLARE @REMARKS NVARCHAR(100) = 'MERGE'
  
	 DECLARE @EN_MERGING_SNAPSHOT_SEQ_ID BIGINT  
	 DECLARE @EN_MERGING_DETAIL_SEQ_ID BIGINT  
	 DECLARE @SRM_CLIENTS_SEQ_ID BIGINT  
	 DECLARE @MERGING_SNAPSHOT_INDENTITY BIGINT  
	 DECLARE @sSQL NVARCHAR(4000)
 
	 DECLARE @TODATE NVARCHAR(100)
	 SELECT @TODATE = GETDATE()
	 PRINT '@TODATE ' + CAST(@TODATE AS NVARCHAR(100))

	 IF @MAIN_RECORD_SEQ_ID = @SUB_RECORD_SEQ_ID
		RETURN
 
	SET @MAIN_RECORD_DESCRIPTION = REPLACE (@MAIN_RECORD_DESCRIPTION, '''', '''''')
	SET @SUB_RECORD_DESCRIPTION = REPLACE (@SUB_RECORD_DESCRIPTION, '''', '''''')
	PRINT @MAIN_RECORD_DESCRIPTION
	PRINT @SUB_RECORD_DESCRIPTION

	SELECT @SRM_CLIENTS_SEQ_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].dbO.SRM_USERS WHERE LOGIN_EMAIL = @USER_EMAIL
		SET @EN_MERGING_SNAPSHOT_SEQ_ID = 112906 /*EN_MERGING_SNAPSHOT*/
		SET @EN_MERGING_DETAIL_SEQ_ID = 112907 /*EN_MERGING_DETAIL*/	
	 
		 IF ISNULL(@SRM_CLIENTS_SEQ_ID,0)=0
		 BEGIN
			 PRINT 'INVALID USER ID'
			 RETURN
		 END 
 
	 PRINT '@CLIENT_ENTITY_SEQ_ID ' + CAST(@CLIENT_ENTITY_SEQ_ID AS NVARCHAR(100))  
	 PRINT '@MAIN_RECORD_SEQ_ID ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100))  
	 PRINT '@MAIN_RECORD_DESCRIPTION ' + CAST(@MAIN_RECORD_DESCRIPTION AS NVARCHAR(200))  
	 PRINT '@SUB_RECORD_SEQ_ID 211 ' + CAST(@SUB_RECORD_SEQ_ID AS NVARCHAR(100))  
	

	/*PICK BOTH MEBERSHIP RECORD AND MERGE AT THE END START*/
	DECLARE @MAIN_MEMBER_SEQ_ID   BIGINT 
	DECLARE @MAIN_MEMBER_ID NVARCHAR(200)
	DECLARE @MAIN_MEMBER_TYPE_SEQ_ID BIGINT
	DECLARE @SUB_MEMBER_SEQ_ID BIGINT 
	DECLARE @SUB_MEMBER_ID NVARCHAR(200)
	DECLARE @SUB_MEMBER_TYPE_SEQ_ID BIGINT


	SET @sSQL = '
		SELECT 
			@SUB_MEMBER_SEQ_ID_OUT = SEQ_ID, 
			@SUB_MEMBER_ID_OUT = ATTRIBUTE_001,
			@SUB_MEMBER_TYPE_SEQ_ID_OUT = ATTRIBUTE_008 
			
		FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA MEM
		WHERE 
			MEM.SRM_CLIENT_ENTITIES_SEQ_ID = 112782 
			 AND (MEM.ATTRIBUTE_002 = '+ CAST(@SUB_RECORD_SEQ_ID AS NVARCHAR(100))  +' 
			OR  MEM.ATTRIBUTE_004  = '+ CAST(@SUB_RECORD_SEQ_ID AS NVARCHAR(100)) +')'+'
			AND ISNULL(MEM.DELETED, ''N'') = ''N''
		'
		print '00 MEM'
		print @sSQL
		EXEC sp_executesql @sSQL,  N'@SUB_MEMBER_SEQ_ID_OUT BIGINT OUTPUT, @SUB_MEMBER_ID_OUT NVARCHAR(200) OUTPUT,  @SUB_MEMBER_TYPE_SEQ_ID_OUT BIGINT OUTPUT'  ,
									@SUB_MEMBER_SEQ_ID OUTPUT,@SUB_MEMBER_ID OUTPUT, @SUB_MEMBER_TYPE_SEQ_ID OUTPUT
   
		PRINT 'SUB_MEMBER_SEQ_ID: ' + CAST(@SUB_MEMBER_SEQ_ID AS NVARCHAR)
		PRINT 'SUB_MEMBER_ID: ' + CAST(@SUB_MEMBER_ID AS NVARCHAR)
		PRINT 'SUB_MEMBER_TYPE_SEQ_ID: ' + CAST(@SUB_MEMBER_TYPE_SEQ_ID AS NVARCHAR)

		SET @sSQL = '
		SELECT 
			@MAIN_MEMBER_SEQ_ID_OUT = SEQ_ID, 
			@MAIN_MEMBER_ID_OUT = ATTRIBUTE_001,
			@MAIN_MEMBER_TYPE_SEQ_ID_OUT = ATTRIBUTE_008  
		FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA MEM
		WHERE 
			MEM.SRM_CLIENT_ENTITIES_SEQ_ID = 112782 
			 AND (MEM.ATTRIBUTE_002 = '+ CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100))  +' 
			OR  MEM.ATTRIBUTE_004  = '+ CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) +')'+'
			AND ISNULL(MEM.DELETED, ''N'') = ''N''
		'
		print '01 MEM'
		print @sSQL
		EXEC sp_executesql @sSQL,  N'@MAIN_MEMBER_SEQ_ID_OUT BIGINT OUTPUT, @MAIN_MEMBER_ID_OUT NVARCHAR(200) OUTPUT, @MAIN_MEMBER_TYPE_SEQ_ID_OUT BIGINT OUTPUT',   
								@MAIN_MEMBER_SEQ_ID OUTPUT,@MAIN_MEMBER_ID OUTPUT , @MAIN_MEMBER_TYPE_SEQ_ID OUTPUT

		PRINT 'MAIN_MEMBER_SEQ_ID: ' + CAST(@MAIN_MEMBER_SEQ_ID AS NVARCHAR)
		PRINT 'MAIN_MEMBER_ID: ' + CAST(@MAIN_MEMBER_ID AS NVARCHAR)
		PRINT 'MAIN_MEMBER_TYPE_SEQ_ID: ' + CAST(@MAIN_MEMBER_TYPE_SEQ_ID AS NVARCHAR)
		/*PICK BOTH MEBERSHIP RECORD AND MERGE AT THE END END*/

		/*FETCH MAIN ACCOUNT EXISTING MAIN CONTACT ACR SEQ_ID START*/
		IF @CLIENT_ENTITY_SEQ_ID = 112715 --Account entity
			BEGIN
				DECLARE @MAIN_ACR_MAIN_CONTACT_SEQ_ID BIGINT = 0
				
				SET @sSQL = '
				    SELECT TOP 1 @MAIN_ACR_MAIN_CONTACT_SEQ_ID_OUT = ACR.SEQ_ID
				    FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
				    WHERE ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
				        AND ACR.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
				        AND ACR.ATTRIBUTE_008 = ''Y''
				        AND ISNULL(ACR.ATTRIBUTE_012, ''N'') = ''N''
				        AND ISNULL(ACR.DELETED, ''N'') = ''N''
				    ORDER BY ACR.SEQ_ID ASC'
				
				EXEC SP_EXECUTESQL @sSQL,
				    N'@MAIN_ACR_MAIN_CONTACT_SEQ_ID_OUT BIGINT OUTPUT',
				    @MAIN_ACR_MAIN_CONTACT_SEQ_ID OUTPUT
				
				PRINT '@MAIN_ACR_MAIN_CONTACT_SEQ_ID: ' + CAST(@MAIN_ACR_MAIN_CONTACT_SEQ_ID AS NVARCHAR(100))
			END
		/*FETCH MAIN ACCOUNT EXISTING MAIN CONTACT ACR SEQ_ID END*/

	 --**************************************************************************************************************************************************************  
	 -- Populate data in Merging Snapshot entity  
	 --**************************************************************************************************************************************************************   
		

