		@CUS_ENTITY_DATA_SEQ_ID = '  +  CAST ( @MERGING_SNAPSHOT_INDENTITY as nvarchar)+ ','  + '
		@SRM_CLIENTS_SEQ_ID			= ' +  cast(@SRM_CLIENTS_SEQ_ID as nvarchar)
		
