	 --**************************************************************************************************************************************************************  
	 -- Main Cursor to pick up list of ALL entities linked with the given entity e.g. Contact, Account etc  
	 --**************************************************************************************************************************************************************   
	 DECLARE CUR_LINKED_ENTITIES CURSOR STATIC LOCAL FOR  
	 SELECT SEQ_ID, ENTITY_DISPLAY_NAME 
	 FROM [SRM-Framework_New].[dbo].SRM_CLIENT_ENTITIES 
	 WHERE SEQ_ID IN ( SELECT SRM_CLIENT_ENTITIES_SEQ_ID 
					   FROM  [SRM-Framework_New].[dbo].SRM_CLIENT_ENTITY_ATTRIBUTES 
					   WHERE SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID AND DELETED = 'N'
					   )   
			AND SEQ_ID ! = 112963 /*SSO_PORTAL_LOGIN*/
	 ORDER BY SEQ_ID  
  
	 OPEN CUR_LINKED_ENTITIES  
	 FETCH NEXT FROM CUR_LINKED_ENTITIES INTO @SUB_CLIENT_ENTITY_SEQ_ID, @SUB_CLIENT_ENTITY_DISPLAY_NAME  
  
	 WHILE (@@FETCH_STATUS = 0)  
	 BEGIN  
		  PRINT '@SUB_CLIENT_ENTITY_SEQ_ID ' + CAST(@SUB_CLIENT_ENTITY_SEQ_ID AS NVARCHAR(100))  
		  PRINT '@SUB_CLIENT_ENTITY_DISPLAY_NAME ' + CAST(@SUB_CLIENT_ENTITY_DISPLAY_NAME AS NVARCHAR(100))  

		  --**************************************************************************************************************************************************************  
		  -- Cursor to pick up list of ALL attributes of the entity selected in above loop  
		  --**************************************************************************************************************************************************************   
		  DECLARE CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE CURSOR STATIC LOCAL FOR  
		  SELECT CEA.SEQ_ID, EA.SYSTEM_NAME, CEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
		  FROM [SRM-Framework_New].[dbo].SRM_CLIENT_ENTITY_ATTRIBUTES CEA, [SRM-Framework_New].[dbo].SRM_ENTITY_ATTRIBUTES EA   
		  WHERE CEA.SRM_CLIENT_ENTITIES_SEQ_ID =  @SUB_CLIENT_ENTITY_SEQ_ID 
		  AND SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID 
		  AND SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = 19  
		  AND CEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = EA.SEQ_ID   
  
  
		  OPEN CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE  
		  FETCH NEXT FROM CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE INTO @ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID, @ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME, @DESC_FIELD_CLIENT_ATTRIBUTE_SEQ_ID
  
		  WHILE (@@FETCH_STATUS = 0)  
		  BEGIN  
			   SET @DESC_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME = NULL

			   SELECT @DESC_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME = SRM_ENTITY_ATTRIBUTES.SYSTEM_NAME, @DESC_FIELD_ATTRIBUTE_DATA_TYPE_SEQ_ID = SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID
			   FROM SRM_CLIENT_ENTITY_ATTRIBUTES, SRM_ENTITY_ATTRIBUTES 
			   WHERE SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SRM_ENTITY_ATTRIBUTES.SEQ_ID  
			   AND SRM_CLIENT_ENTITY_ATTRIBUTES.SEQ_ID = @DESC_FIELD_CLIENT_ATTRIBUTE_SEQ_ID
  
  			   PRINT '@DESC_FIELD_CLIENT_ATTRIBUTE_SEQ_ID ' + CAST(@DESC_FIELD_CLIENT_ATTRIBUTE_SEQ_ID AS NVARCHAR(100))  
			   PRINT '@DESC_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME ' + @DESC_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME  

			   --**************************************************************************************************************************************************************  
			   -- Cursor to pick up list of ALL records from Custom Entities which match with the value of @MAIN_RECORD_SEQ_ID   
			   --**************************************************************************************************************************************************************   
			  SET @sqlCommand =' INSERT INTO #CHECK_TABLE (SEQ_ID)  
				   SELECT CPNUI.CUS_ENTITY_DATA_SEQ_ID FROM [SRM-CustomEntities_'+ CAST (@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50) )+']' + '.[dbo].CUS_PIVOT_NON_UNIQUE_INDEXES CPNUI   
				   WHERE CPNUI.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = '+ CAST( @ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID AS NVARCHAR(50)) +
				   'AND ATTRIBUTE_DECIMAL =' + CAST( @SUB_RECORD_SEQ_ID  AS NVARCHAR(50))
			 EXEC (@sqlCommand)
			  print '5'
			 PRINT @sqlCommand

			   DECLARE CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES CURSOR STATIC LOCAL FOR  
			   SELECT SEQ_ID FROM #CHECK_TABLE  
  
			   OPEN CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES  
			   FETCH NEXT FROM CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES INTO @CUSTOM_ENTITIES_SEQ_ID  
  
			   WHILE (@@FETCH_STATUS = 0)  
			   BEGIN  
					PRINT '@CUSTOM_ENTITIES_SEQ_ID ' + CAST(@CUSTOM_ENTITIES_SEQ_ID AS NVARCHAR(100))  
  
					IF (@DESC_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME <> '' AND @DESC_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME IS NOT NULL)
					BEGIN
						SET @sSQL = 'UPDATE [SRM-CustomEntities_'+ CAST (@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50) )+']' + '.[dbo].CUS_ENTITY_DATA SET DATE_MODIFIED =  ''' + @TODATE + ''', MODIFIED_BY = ''Merge Process'','
						+ @ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME + ' = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(20)) + ','
