						PRINT @sSQL
					IF (@DESC_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME <> '' AND @DESC_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME IS NOT NULL)
					BEGIN
						IF @DESC_FIELD_ATTRIBUTE_DATA_TYPE_SEQ_ID = 13
						BEGIN
					
							SET @sSQL = 'UPDATE [SRM-CustomEntities_'+ CAST (@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50) )+']' + '.dbo.CUS_PIVOT_NON_UNIQUE_INDEXES
							 SET ATTRIBUTE_STRING = ''' + CAST ( @MAIN_RECORD_DESCRIPTION AS nvarchar(500))+'''' + '
							WHERE CUS_ENTITY_DATA_SEQ_ID = '+ CAST ( @CUSTOM_ENTITIES_SEQ_ID AS NVARCHAR(50)) + '
