								SET ATTRIBUTE_DECIMAL = ' + CAST ( @MAIN_RECORD_DESCRIPTION  AS NVARCHAR(50)) + '
								WHERE CUS_ENTITY_DATA_SEQ_ID = ' + CAST (  @CUSTOM_ENTITIES_SEQ_ID AS NVARCHAR(50)) + '
								AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST ( @DESC_FIELD_CLIENT_ATTRIBUTE_SEQ_ID AS NVARCHAR(50))
								EXECUTE (@sSQL)
							  print '9'
							PRINT @sSQL
						END
					END
  
					--*******************************************************************************************************************************************  
					-- Populate data in Merging Detail entity  
					--*******************************************************************************************************************************************  
				
					SET @sSQL = 'INSERT INTO [SRM-CustomEntities_'+ CAST (@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50) )+']' + '.[dbo].CUS_ENTITY_DATA 
						(SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENTS_SEQ_ID, ATTRIBUTE_001, ATTRIBUTE_002, ATTRIBUTE_003, ATTRIBUTE_004,  
						ATTRIBUTE_005, ATTRIBUTE_006, DATE_CREATED, CREATED_BY, DELETED)  
						SELECT ' + CAST (@EN_MERGING_DETAIL_SEQ_ID AS NVARCHAR(50)) +',' +
						CAST( @SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + ',' + 
						'''MERGING DETAIL''' +','+
						CAST (@MERGING_SNAPSHOT_INDENTITY AS NVARCHAR(50)) +',' + 
						CAST ( @SUB_CLIENT_ENTITY_SEQ_ID AS NVARCHAR(50)) +','+
						CAST (@ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID AS NVARCHAR(50)) +', ' + '''' +
						CAST (@ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME AS NVARCHAR(50)) +''','+
						CAST (@CUSTOM_ENTITIES_SEQ_ID AS NVARCHAR(50))+', '+
						'''' + CAST (GETDATE() AS NVARCHAR(100))+'''' +',' + 
						'''' +CAST (@CREATED_BY AS NVARCHAR(100)) + '''' + +',''N'''
				
						PRINT ' @EN_MERGING_DETAIL_SEQ_ID 10'
						PRINT @SSQL
						EXECUTE (@SSQL)
						PRINT ' @EN_MERGING_DETAIL_SEQ_ID 10.0'
					FETCH NEXT FROM CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES INTO @CUSTOM_ENTITIES_SEQ_ID  
			   END  
			   CLOSE CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES  
			   DEALLOCATE CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES  
  
			   DELETE FROM #CHECK_TABLE  
			   FETCH NEXT FROM CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE INTO @ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID, @ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME, @DESC_FIELD_CLIENT_ATTRIBUTE_SEQ_ID 
		  END  
		  CLOSE CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE  
		  DEALLOCATE CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE    

		
		   	SET @sSQL = 'UPDATE [SRM-CustomEntities_'+ CAST (@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50) )+']' + '.[dbo].CUS_ENTITY_DATA 
				   SET DELETED = ' + '''Y''' +', ' + 
				   ' DELETED_BY= ' +''''+ CAST (ISNULL(@CREATED_BY,'') AS NVARCHAR(50))  + ''''' (Merge Process)''' +', ' + 
				   ' DATE_DELETED = ''' + CAST (GETDATE() AS NVARCHAR(50)) +'''' + 
				   ' WHERE SEQ_ID = ' + CAST (@SUB_RECORD_SEQ_ID AS NVARCHAR(50)) + 
