				 ACC.ATTRIBUTE_126 = MEM.ATTRIBUTE_014, --SUBSBAND
				 ACC.ATTRIBUTE_127 = MEM.ATTRIBUTE_016, --STATUS
				 ACC.ATTRIBUTE_128 = MEM.ATTRIBUTE_017, --STATUS
				 ACC.ATTRIBUTE_131 = MEM.ATTRIBUTE_072, --TYPE ICON
				 ACC.ATTRIBUTE_133 = MEM.ATTRIBUTE_075, --STATUS ICON
				 ACC.ATTRIBUTE_134 = MEM.ATTRIBUTE_073, --CATEGORY ICON
                 ACC.MODIFIED_BY = ''Merge Process'',
                 ACC.DATE_MODIFIED = GETDATE()
             FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACC
             INNER JOIN [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA MEM
                 ON MEM.SEQ_ID = ' + CAST(@SUB_MEMBER_SEQ_ID AS NVARCHAR(100)) + '
                 AND MEM.SRM_CLIENT_ENTITIES_SEQ_ID = 112782
                 AND ISNULL(MEM.DELETED, ''N'') = ''N''
             WHERE ACC.SEQ_ID = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
                 AND ACC.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@CLIENT_ENTITY_SEQ_ID AS NVARCHAR(100))
         PRINT 'Change 1 - Update Main Account Member Lookup'
         PRINT @sSQL
         EXECUTE (@sSQL)

