	            SELECT COUNT(DISTINCT ACR.ATTRIBUTE_002)
	            FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
	            WHERE ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
