     /*UPDATE CONTACTS MEMBERSHIP FIELDS START*/

    DECLARE @EFFECTIVE_MEMBER_SEQ_ID BIGINT
	SET @EFFECTIVE_MEMBER_SEQ_ID = CASE 
    WHEN ISNULL(@MAIN_MEMBER_SEQ_ID, 0) > 0 THEN @MAIN_MEMBER_SEQ_ID  -- Scenario B
    WHEN ISNULL(@SUB_MEMBER_SEQ_ID, 0) > 0 THEN @SUB_MEMBER_SEQ_ID    -- Scenario A
    ELSE NULL 
    END

	IF ISNULL(@EFFECTIVE_MEMBER_SEQ_ID, 0) > 0
     BEGIN
