             UPDATE CON
             SET
                 CON.ATTRIBUTE_155 = MEM.SEQ_ID,
                 CON.ATTRIBUTE_156 = MEM.ATTRIBUTE_001,
                 CON.ATTRIBUTE_157 = MEM.ATTRIBUTE_010,      --CATEGORY
                 CON.ATTRIBUTE_158 = MEM.ATTRIBUTE_011, --CATEGORY
                 CON.ATTRIBUTE_159 = MEM.ATTRIBUTE_013, -- SUBSCRIPTION_BAND_ID   
                 CON.ATTRIBUTE_160 = MEM.ATTRIBUTE_014, -- SUBSCRIPTION_BAND_NAME 
                 CON.ATTRIBUTE_161 = MEM.ATTRIBUTE_016,  -- STATUS_ID   
                 CON.ATTRIBUTE_162 = MEM.ATTRIBUTE_017, -- STATUS_NAME
				 CON.ATTRIBUTE_163 = MEM.ATTRIBUTE_072,  -- TYPE ICON   
                 CON.ATTRIBUTE_164 = MEM.ATTRIBUTE_074, --BAND ICON
				 CON.ATTRIBUTE_165 = MEM.ATTRIBUTE_075,  -- STATUS ICON
                 CON.ATTRIBUTE_166 = MEM.ATTRIBUTE_073, --CATEGORY ICON
                 CON.MODIFIED_BY = ''Merge Process'',
                 CON.DATE_MODIFIED = GETDATE()
             FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA CON
             INNER JOIN [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA MEM
                 ON MEM.SEQ_ID = ' + CAST(@EFFECTIVE_MEMBER_SEQ_ID AS NVARCHAR(100)) + '
                 AND MEM.SRM_CLIENT_ENTITIES_SEQ_ID = 112782
                 AND ISNULL(MEM.DELETED, ''N'') = ''N''
             WHERE CON.SRM_CLIENT_ENTITIES_SEQ_ID = 112718 -- CONTACT entity 
                 AND CON.ATTRIBUTE_016 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
                 AND ISNULL(CON.DELETED, ''N'') = ''N'''

         PRINT 'Change 2 - Update Contacts Membership Fields'
