	 DECLARE @CUS_ENTITY_DATA_SEQ_ID_1 BIGINT
     DECLARE CUR_CONTACT_PIVOT CURSOR STATIC LOCAL FOR
     SELECT SEQ_ID FROM #TEMP_PIV_ID
 
     OPEN CUR_CONTACT_PIVOT
     FETCH NEXT FROM CUR_CONTACT_PIVOT INTO @CUS_ENTITY_DATA_SEQ_ID_1
 
     WHILE (@@FETCH_STATUS = 0)
     BEGIN
         PRINT 'Change 2 - Pivot Update Contact SEQ_ID: ' + CAST(@CUS_ENTITY_DATA_SEQ_ID_1 AS NVARCHAR(100))
 
         SET @sqlCommand = '
             EXEC [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
             @SRM_CLIENT_ENTITIES_SEQ_ID = 112718,
             @CUS_ENTITY_DATA_SEQ_ID = ' + CAST(@CUS_ENTITY_DATA_SEQ_ID_1 AS NVARCHAR(100)) + ',
             @SRM_CLIENTS_SEQ_ID = ' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(100))
         EXEC (@sqlCommand)
 
         FETCH NEXT FROM CUR_CONTACT_PIVOT INTO @CUS_ENTITY_DATA_SEQ_ID_1
     END
 
     CLOSE CUR_CONTACT_PIVOT
     DEALLOCATE CUR_CONTACT_PIVOT
 
     /*STEP 4 - DROP TEMP PIVOT TABLE*/
     DROP TABLE #TEMP_PIV_ID
   END  
