   /*CREATE COMBINED ACR PIVOT TEMP TABLE*/
   CREATE TABLE #TEMP_PIV_ACR (SEQ_ID BIGINT)
   /*
   /*CHANGE 4A - DELETE DUPLICATE SAME CONTACT MAIN CONTACT RECORD ON ACR AFTER MERGE START*/
   SET @sSQL = '
       WITH DuplicatesCTE AS (
           SELECT *,
               ROW_NUMBER() OVER (
                   PARTITION BY ATTRIBUTE_002, ATTRIBUTE_004
                   ORDER BY SEQ_ID ASC
               ) AS rn
           FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA
           WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 112723
               AND ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
               AND ATTRIBUTE_008 = ''Y''
               AND ISNULL(DELETED, ''N'') = ''N''
       )
       UPDATE DuplicatesCTE
       SET
           DELETED = ''Y'',
           DELETED_BY = ''Merge Process'',
           DATE_DELETED = GETDATE(),
           MODIFIED_BY = ''Merge Process'',
           DATE_MODIFIED = GETDATE()
       WHERE rn > 1'
   
   PRINT 'Change 4A - Delete Duplicate Same Main Contact ACR Records'
   PRINT @sSQL
   EXECUTE (@sSQL)
   /*CHANGE 4A - DELETE DUPLICATE SAME CONTACT MAIN CONTACT RECORD ON ACR AFTER MERGE END*/
