	DECLARE @MAIN_HAS_MAIN_CONTACT INT = 0
	
	SET @sSQL = '
	    SELECT @MAIN_HAS_MAIN_CONTACT_OUT = COUNT(*)
	    FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
	    WHERE ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
	        AND ACR.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
	        AND ACR.ATTRIBUTE_008 = ''Y''
	        AND ISNULL(ACR.DELETED, ''N'') = ''N'''
	
	EXEC SP_EXECUTESQL @sSQL,
	    N'@MAIN_HAS_MAIN_CONTACT_OUT INT OUTPUT',
	    @MAIN_HAS_MAIN_CONTACT OUTPUT
	
	PRINT 'Change 4B - Main Contact Count on Main Account: ' + CAST(@MAIN_HAS_MAIN_CONTACT AS NVARCHAR(10))
	
	IF @MAIN_HAS_MAIN_CONTACT > 1
	BEGIN
	    IF ISNULL(@MAIN_ACR_MAIN_CONTACT_SEQ_ID, 0) > 0
	    BEGIN
	        /*MAIN ACCOUNT HAD A PRE-EXISTING MAIN CONTACT - USE CAPTURED SEQ_ID TO KEEP IT STRICTLY*/
	        SET @sSQL = '
	            UPDATE ACR
	            SET
	                ACR.ATTRIBUTE_008 = ''N'',
	                ACR.SOURCE_OF_DATA = ''Post merge wrong main contact unticked'',
	                ACR.MODIFIED_BY = ''Merge Process'',
	                ACR.DATE_MODIFIED = GETDATE()
	            FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
	            WHERE ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
	                AND ACR.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
	                AND ACR.ATTRIBUTE_008 = ''Y''
	                AND ISNULL(ACR.DELETED, ''N'') = ''N''
	                AND ACR.SEQ_ID != ' + CAST(@MAIN_ACR_MAIN_CONTACT_SEQ_ID AS NVARCHAR(100))
	
	        PRINT 'Change 4B - Untick Using Captured Main Account Main Contact SEQ_ID'
	        PRINT @sSQL
	        EXECUTE (@sSQL)
	    END
	    ELSE
	    BEGIN
	        /*MAIN ACCOUNT HAD NO PRE-EXISTING MAIN CONTACT - FALLBACK TO SEQ_ID ORDER*/
	        SET @sSQL = '
	            UPDATE ACR
	            SET
	                ACR.ATTRIBUTE_008 = ''N'',
	                ACR.SOURCE_OF_DATA = ''Post merge wrong main contact unticked'',
	                ACR.MODIFIED_BY = ''Merge Process'',
	                ACR.DATE_MODIFIED = GETDATE()
	            FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
	            WHERE ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
	                AND ACR.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
	                AND ACR.ATTRIBUTE_008 = ''Y''
	                AND ISNULL(ACR.DELETED, ''N'') = ''N''
	                AND ACR.SEQ_ID != (
	                    SELECT TOP 1 SEQ_ID
	                    FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA
	                    WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 112723
	                        AND ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
	                        AND ATTRIBUTE_008 = ''Y''
	                        AND ISNULL(DELETED, ''N'') = ''N''
	                    ORDER BY SEQ_ID ASC
	                )'
	
	        PRINT 'Change 4B - Untick Fallback Using SEQ_ID Order'
	        PRINT @sSQL
	        EXECUTE (@sSQL)
	    END
	
	    /*COLLECT UNTICKED ACR SEQ_IDs FOR COMBINED PIVOT*/
	    /*SET @sqlCommand = '
	        INSERT INTO #TEMP_PIV_ACR (SEQ_ID)
	        SELECT ACR.SEQ_ID
	        FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
	        WHERE ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
	            AND ACR.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
	            AND ACR.ATTRIBUTE_008 = ''N''
	            AND ISNULL(ACR.DELETED, ''N'') = ''N''
	            AND ACR.SOURCE_OF_DATA = ''Post merge wrong main contact unticked'''
	    EXEC (@sqlCommand)*/
	END
	/*CHANGE 4B - UNTICK DIFFERENT CONTACTS BOTH FLAGGED AS MAIN CONTACT END*/
   
   /*CHANGE 5 - UPDATE ACR DESCRIPTION START*/
   SET @sSQL = '
       UPDATE ACR
       SET
           ACR.ATTRIBUTE_001 = ACR.ATTRIBUTE_005 + '' '' + ACR.ATTRIBUTE_003,
           ACR.MODIFIED_BY = ''Merge Process'',
           ACR.DATE_MODIFIED = GETDATE()
       FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
       WHERE ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
           AND ACR.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
           AND ISNULL(ACR.ATTRIBUTE_001, '''') != ISNULL(ACR.ATTRIBUTE_005 + '' '' + ACR.ATTRIBUTE_003, ''[]'')'
   
   PRINT 'Change 5 - Update ACR Description'
   PRINT @sSQL
   EXECUTE (@sSQL)
   

   /*CHANGE 5 - UPDATE ACR DESCRIPTION END*/
    /*CHECK IF MAIN ACCOUNT TICK NEEDS TO BE CARRIED OVER START*/

	DECLARE @ACR_TO_TICK_MAIN_ACCOUNT BIGINT = 0
	
	SET @sSQL = '
	    SELECT TOP 1 @ACR_TO_TICK_MAIN_ACCOUNT_OUT = KEEPER.SEQ_ID
	    FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA KEEPER
	    INNER JOIN [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA DUPLICATE
	        ON DUPLICATE.ATTRIBUTE_002 = KEEPER.ATTRIBUTE_002
	        AND DUPLICATE.ATTRIBUTE_004 = KEEPER.ATTRIBUTE_004
	        AND DUPLICATE.SEQ_ID != KEEPER.SEQ_ID
	        AND DUPLICATE.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
	        AND ISNULL(DUPLICATE.DELETED, ''N'') = ''N''
	        AND ISNULL(DUPLICATE.ATTRIBUTE_011, '''') = ''''
			AND ISNULL(DUPLICATE.ATTRIBUTE_008, ''N'') = ''N''
	        AND ISNULL(DUPLICATE.ATTRIBUTE_009, ''N'') = ''Y''
	    WHERE KEEPER.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
	        AND KEEPER.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
	        AND ISNULL(KEEPER.DELETED, ''N'') = ''N''
	        AND ISNULL(KEEPER.ATTRIBUTE_011, '''') = ''''
	        AND ISNULL(KEEPER.ATTRIBUTE_008, ''N'') = ''Y''
	        AND ISNULL(KEEPER.ATTRIBUTE_009, ''N'') = ''N'''
	
	EXEC SP_EXECUTESQL @sSQL,
	    N'@ACR_TO_TICK_MAIN_ACCOUNT_OUT BIGINT OUTPUT',
	    @ACR_TO_TICK_MAIN_ACCOUNT OUTPUT
	
	PRINT 'ACR SEQ_ID To Tick Main Account: ' + CAST(@ACR_TO_TICK_MAIN_ACCOUNT AS NVARCHAR(100))

	/*CHECK IF MAIN ACCOUNT TICK NEEDS TO BE CARRIED OVER END*/

   /*MANAN'S ACR DUPLICATE TEST CASE HANDLING SCRIPT START*/

	SET @sSQL = 'WITH DuplicatesCTE AS (
	    SELECT 
	        *,
	        ROW_NUMBER() OVER (
	            PARTITION BY ATTRIBUTE_002, ATTRIBUTE_004
	            ORDER BY 
	                CASE WHEN ISNULL(ATTRIBUTE_008, ''N'') = ''Y'' THEN 0 ELSE 1 END ASC,
	                CASE WHEN ISNULL(ATTRIBUTE_009, ''N'') = ''Y'' THEN 0 ELSE 1 END ASC,
	                SEQ_ID ASC
	        ) AS rn
	    FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA
	    WHERE 
	        SRM_CLIENT_ENTITIES_SEQ_ID = 112723
	        AND ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
	        AND DELETED = ''N''
	        AND ISNULL(ATTRIBUTE_011, '''') = ''''
	)
     UPDATE DuplicatesCTE
     SET DELETED_BY = ''' + CAST(ISNULL(@CREATED_BY, '') AS NVARCHAR(50)) + ' (Merge Process)'','  +
         ' ATTRIBUTE_011 = ''' + CAST(GETDATE() AS NVARCHAR(50)) + ''','  +
         ' ATTRIBUTE_012 = ''Y'',' +
         ' DATE_DELETED = ''' + CAST(GETDATE() AS NVARCHAR(50)) + ''','  +
		 ' DELETED = ''Y'',' + 
         ' SOURCE_OF_DATA = ''DUP_ACR_CEASED''' +
     ' WHERE rn > 1;'
	
	PRINT '23.1'
	PRINT @sSQL
	EXECUTE (@sSQL)

		
	/*MANAN'S ACR DUPLICATE TEST CASE HANDLING SCRIPT END*/

	/*TICK MAIN ACCOUNT ON KEPT RECORD IF NEEDED START*/
	IF ISNULL(@ACR_TO_TICK_MAIN_ACCOUNT, 0) > 0
	BEGIN
		SET @sSQL = '
		    UPDATE ACR
		    SET
		        ACR.ATTRIBUTE_009 = ''Y'',
		        ACR.MODIFIED_BY = ''Merge Process'',
		        ACR.DATE_MODIFIED = GETDATE()
		    FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
		    WHERE ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
		        AND ACR.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
		        AND ACR.ATTRIBUTE_008 = ''Y''
		        AND ACR.ATTRIBUTE_009 != ''Y''
		        AND ISNULL(ACR.ATTRIBUTE_011, '''') = ''''
		        AND ISNULL(ACR.DELETED, ''N'') = ''N'''

		PRINT 'Tick Main Account On Kept ACR Record'
		PRINT @sSQL
		EXECUTE (@sSQL)
	
	END
	/*TICK MAIN ACCOUNT ON KEPT RECORD IF NEEDED END*/
   
   /*COMBINED ACR PIVOT START*/

      SET @sqlCommand = '
       INSERT INTO #TEMP_PIV_ACR (SEQ_ID)
       SELECT ACR.SEQ_ID
       FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
       WHERE ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
           AND ACR.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
           AND ISNULL(ACR.DELETED, ''N'') = ''N'''
   EXEC (@sqlCommand)

   DECLARE @ACR_SEQ_ID BIGINT
   DECLARE CUR_ACR_PIVOT CURSOR STATIC LOCAL FOR
   SELECT DISTINCT SEQ_ID FROM #TEMP_PIV_ACR
   
   OPEN CUR_ACR_PIVOT
   FETCH NEXT FROM CUR_ACR_PIVOT INTO @ACR_SEQ_ID
   
   WHILE (@@FETCH_STATUS = 0)
   BEGIN
       PRINT 'ACR Pivot Update SEQ_ID: ' + CAST(@ACR_SEQ_ID AS NVARCHAR(100))
   
       SET @sqlCommand = '
           EXEC [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
           @SRM_CLIENT_ENTITIES_SEQ_ID = 112723,
           @CUS_ENTITY_DATA_SEQ_ID = ' + CAST(@ACR_SEQ_ID AS NVARCHAR(100)) + ',
           @SRM_CLIENTS_SEQ_ID = ' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(100))
       EXEC (@sqlCommand)
   
       FETCH NEXT FROM CUR_ACR_PIVOT INTO @ACR_SEQ_ID
   END
   
   CLOSE CUR_ACR_PIVOT
   DEALLOCATE CUR_ACR_PIVOT
   
   DROP TABLE #TEMP_PIV_ACR
   /*COMBINED ACR PIVOT END*/
   
   /*ACR CHANGES END*/
   /*CHANGE 4C - UPDATE MAIN ACCOUNT MAIN CONTACT FIELDS WHEN EMPTY START*/
   DECLARE @ACCOUNT_HAS_MAIN_CONTACT INT = 0
   DECLARE @ACR_MAIN_CONTACT_EXISTS INT = 0

   SET @sSQL = '
    SELECT @ACCOUNT_HAS_MAIN_CONTACT_OUT = COUNT(*)
    FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA
    WHERE SEQ_ID = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
        AND SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@CLIENT_ENTITY_SEQ_ID AS NVARCHAR(100)) + '
        AND ISNULL(ATTRIBUTE_016, 0) != 0
        AND ISNULL(DELETED, ''N'') = ''N'''

   EXEC SP_EXECUTESQL @sSQL,
       N'@ACCOUNT_HAS_MAIN_CONTACT_OUT INT OUTPUT',
       @ACCOUNT_HAS_MAIN_CONTACT OUTPUT
   
   PRINT 'Change 4C - Main Account Has Main Contact: ' + CAST(@ACCOUNT_HAS_MAIN_CONTACT AS NVARCHAR(10))
   IF @ACCOUNT_HAS_MAIN_CONTACT = 0
	BEGIN
		-- Check 2: a main contact ACR record exists to pull from
		SET @sSQL = '
		    SELECT @ACR_MAIN_CONTACT_EXISTS_OUT = COUNT(*)
		    FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
		    WHERE ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
		        AND ACR.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
		        AND ACR.ATTRIBUTE_008 = ''Y''
		        AND ISNULL(ACR.DELETED, ''N'') = ''N'''

		EXEC SP_EXECUTESQL @sSQL,
		    N'@ACR_MAIN_CONTACT_EXISTS_OUT INT OUTPUT',
		    @ACR_MAIN_CONTACT_EXISTS OUTPUT

		PRINT 'Change 4C - ACR Main Contact Exists: ' + CAST(@ACR_MAIN_CONTACT_EXISTS AS NVARCHAR(10))
		    IF @ACR_MAIN_CONTACT_EXISTS > 0
				BEGIN
								SET @sSQL = '
				    UPDATE ACC
				    SET
				        ACC.ATTRIBUTE_016 = CON.SEQ_ID,
				        ACC.ATTRIBUTE_017 = CON.ATTRIBUTE_001,
				        ACC.ATTRIBUTE_018 = CON.ATTRIBUTE_018, -- DEPARTMENT 
				        ACC.ATTRIBUTE_019 = CON.ATTRIBUTE_019, -- JOB TITLE 
						ACC.ATTRIBUTE_024 = CON.ATTRIBUTE_024, --REGION
						ACC.ATTRIBUTE_025 = CON.ATTRIBUTE_025, --REGION NAME
				        ACC.MODIFIED_BY = ''Merge Process'',
				        ACC.DATE_MODIFIED = GETDATE()
				    FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACC
				    INNER JOIN [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA ACR
				        ON ACR.SRM_CLIENT_ENTITIES_SEQ_ID = 112723
				        AND ACR.ATTRIBUTE_004 = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
				        AND ACR.ATTRIBUTE_008 = ''Y''
				        AND ISNULL(ACR.DELETED, ''N'') = ''N''
				    INNER JOIN [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].CUS_ENTITY_DATA CON
				        ON CON.SEQ_ID = ACR.ATTRIBUTE_002
				        AND CON.SRM_CLIENT_ENTITIES_SEQ_ID = 112718
				        AND ISNULL(CON.DELETED, ''N'') = ''N''
				    WHERE ACC.SEQ_ID = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + '
				        AND ACC.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@CLIENT_ENTITY_SEQ_ID AS NVARCHAR(100)) + '
				        AND ISNULL(ACC.ATTRIBUTE_016, 0) = 0'
				
				PRINT 'Change 4C - Update Main Account Main Contact Fields'
				PRINT @sSQL
				EXECUTE (@sSQL)
				
				/*PIVOT UPDATE FOR MAIN ACCOUNT*/
				SET @sqlCommand = '
				    EXEC [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50)) + '].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
				    @SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@CLIENT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ',
				    @CUS_ENTITY_DATA_SEQ_ID = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(100)) + ',
				    @SRM_CLIENTS_SEQ_ID = ' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(100))
				PRINT 'Change 4C - Pivot Update Main Account Main Contact Fields'
				PRINT @sqlCommand
				EXEC (@sqlCommand)
		END
	END
	/*CHANGE 4C - UPDATE MAIN ACCOUNT MAIN CONTACT FIELDS WHEN EMPTY END*/
 END
