	 DECLARE CUR_LINKED_ENTITIES2 CURSOR STATIC LOCAL FOR  
	 SELECT SEQ_ID, ENTITY_DISPLAY_NAME FROM [SRM-Framework_New].[dbo].SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME IN (  
	 'DIARY_ACTION', 'COMMUNICATION_LOG', 'NOTE', 'ATTACHMENT', 'PROFILE', 'COMMUNICATION_HISTORY')   
	 ORDER BY SEQ_ID  
  
	 OPEN CUR_LINKED_ENTITIES2  
	 FETCH NEXT FROM CUR_LINKED_ENTITIES2 INTO @SUB_CLIENT_ENTITY_SEQ_ID, @SUB_CLIENT_ENTITY_DISPLAY_NAME  
  
	 WHILE (@@FETCH_STATUS = 0)  
	 BEGIN  
		  PRINT '@SUB_CLIENT_ENTITY_SEQ_ID ' + CAST(@SUB_CLIENT_ENTITY_SEQ_ID AS NVARCHAR(100))  
		  PRINT '@SUB_CLIENT_ENTITY_DISPLAY_NAME ' + CAST(@SUB_CLIENT_ENTITY_DISPLAY_NAME AS NVARCHAR(100))  
  
		  --**************************************************************************************************************************************************************  
		  -- Cursor to pick up list of ALL attributes of the entity selected in above loop  
		  --**************************************************************************************************************************************************************   
		  DECLARE CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE2 CURSOR STATIC LOCAL FOR  
		  SELECT CEA.SEQ_ID, EA.SYSTEM_NAME FROM [SRM-Framework_New].[dbo].SRM_CLIENT_ENTITY_ATTRIBUTES CEA, [SRM-Framework_New].[dbo].SRM_ENTITY_ATTRIBUTES EA   
		  WHERE CEA.SRM_CLIENT_ENTITIES_SEQ_ID =  @SUB_CLIENT_ENTITY_SEQ_ID AND SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = 19  
		  AND CEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = EA.SEQ_ID AND CEA.ATTRIBUTE_DISPLAY_NAME = 'PARENT_SEQ_ID'
  
		  OPEN CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE2  
		  FETCH NEXT FROM CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE2 INTO @ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID, @ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME  
  
		  WHILE (@@FETCH_STATUS = 0)  
		  BEGIN  
			   PRINT '@ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID ' + CAST(@ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID AS NVARCHAR(100))  
			   PRINT '@ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME ' + @ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME  
  
			   --**************************************************************************************************************************************************************  
			   -- Cursor to pick up list of ALL records from Custom Entities which match with the value of @MAIN_RECORD_SEQ_ID   
			
			 SET @sqlCommand =' INSERT INTO #CHECK_TABLE (SEQ_ID)  
				   SELECT CPNUI.CUS_ENTITY_DATA_SEQ_ID FROM [SRM-CustomEntities_'+ CAST (@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50) )+']' + '.[dbo].CUS_PIVOT_NON_UNIQUE_INDEXES CPNUI   
				   WHERE CPNUI.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = '+ CAST( @ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID AS NVARCHAR(50)) +
				   'AND ATTRIBUTE_DECIMAL =' + CAST( @SUB_RECORD_SEQ_ID  AS NVARCHAR(50))
			 EXEC (@sqlCommand)
			  print '12'
			PRINT @sSQL
			   DECLARE CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES CURSOR STATIC LOCAL FOR  
			   SELECT SEQ_ID FROM #CHECK_TABLE  
  
			   OPEN CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES  
			   FETCH NEXT FROM CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES INTO @CUSTOM_ENTITIES_SEQ_ID  
  
			   WHILE (@@FETCH_STATUS = 0)  
			   BEGIN  
					PRINT '@CUSTOM_ENTITIES_SEQ_ID ' + CAST(@CUSTOM_ENTITIES_SEQ_ID AS NVARCHAR(100))  
				
					SET @sSQL = 'UPDATE [SRM-CustomEntities_'+ CAST (@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50) )+']' + '.[dbo].CUS_ENTITY_DATA SET DATE_MODIFIED =  ''' + @TODATE + ''', MODIFIED_BY = ''Merge Process'','
					+ @ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME + ' = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(20)) +
					' WHERE SEQ_ID =  ' + CAST(@CUSTOM_ENTITIES_SEQ_ID AS NVARCHAR(20))

					EXECUTE (@sSQL)  
					 print '13'
					PRINT @sSQL
				
					
					SET @sSQL = 'UPDATE [SRM-CustomEntities_'+ CAST (@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50) )+']' + '.[dbo].CUS_PIVOT_NON_UNIQUE_INDEXES
					SET ATTRIBUTE_DECIMAL =  ' + cast(@MAIN_RECORD_SEQ_ID as nvarchar(20))  +
					/*+ ' , '+
					 @ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME + ' = ' + CAST(@MAIN_RECORD_SEQ_ID AS NVARCHAR(20))  +*/
					' WHERE CUS_ENTITY_DATA_SEQ_ID =  ' + cast(@CUSTOM_ENTITIES_SEQ_ID as nvarchar(50)) + 
					' AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + cast(@ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID as nvarchar(50)) +  
					' AND SRM_CLIENT_ENTITIES_SEQ_ID = ' + cast(@SUB_CLIENT_ENTITY_SEQ_ID as nvarchar(50))
					
					print '14'
					PRINT @sSQL
					EXECUTE (@sSQL)  
					

					--*******************************************************************************************************************************************  
