					--*******************************************************************************************************************************************  
				

					SET @sSQL = 'INSERT INTO [SRM-CustomEntities_'+ CAST (@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50) )+']' + '.[dbo].CUS_ENTITY_DATA 
						(SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENTS_SEQ_ID, ATTRIBUTE_001, ATTRIBUTE_002, ATTRIBUTE_003, ATTRIBUTE_004,  
						ATTRIBUTE_005, ATTRIBUTE_006, DATE_CREATED, CREATED_BY, DELETED)  
						SELECT ' + CAST (@EN_MERGING_DETAIL_SEQ_ID AS NVARCHAR(50)) +',' +
