						CAST (@MERGING_SNAPSHOT_INDENTITY AS NVARCHAR(50)) +',' + 
						CAST ( @SUB_CLIENT_ENTITY_SEQ_ID AS NVARCHAR(50)) +','+
						CAST (@ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID AS NVARCHAR(50)) +', ''' +
						CAST (@ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME AS NVARCHAR(50)) +''','+
						CAST (@CUSTOM_ENTITIES_SEQ_ID AS NVARCHAR(50))+', '+
						'''' + CAST (GETDATE() AS NVARCHAR(100))+'''' +',' + 
						'''' +CAST (@CREATED_BY AS NVARCHAR(100)) + '''' + +',''N'''
						
						PRINT ' @EN_MERGING_DETAIL_SEQ_ID 15'
						PRINT @SSQL
						EXECUTE (@SSQL)


					FETCH NEXT FROM CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES INTO @CUSTOM_ENTITIES_SEQ_ID  
			   END  
			   CLOSE CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES  
			   DEALLOCATE CUR_LINKED_ID_FIELD_CUSTOM_ENTITIES  
  
			   DELETE FROM #CHECK_TABLE  
			   FETCH NEXT FROM CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE2 INTO @ID_FIELD_CLIENT_ATTRIBUTE_SEQ_ID, @ID_FIELD_CLIENT_ATTRIBUTE_SYSTEM_NAME  
		  END  
		  CLOSE CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE2  
		  DEALLOCATE CUR_LINKED_ID_FIELD_CLIENT_ATTRIBUTE2    
		  
	

		  SET @sSQL = 'UPDATE [SRM-CustomEntities_'+ CAST (@SRM_CLIENTS_SEQ_ID AS NVARCHAR(50) )+']' + '.[dbo].CUS_ENTITY_DATA 
