-- =============================================
-- Author:		<Nimra Azeem>
-- Create date: <27/02/2026>
-- Description:	<Get Paid Member Assigned Rate>
-- =============================================
CREATE PROCEDURE [dbo].[GET_PAID_RATE]
	-- Add the parameters for the stored procedure here
	@p_MEMBER BIGINT,					-- MEMBER
	@p_FISCAL_PERIOD BIGINT,			-- FISCAL PERIOD
	@p_USER_EMAIL NVARCHAR(100),          --LOGIN USER EMAIL
	@p_MEMBER_ASSIGNED_RATE BIGINT OUTPUT				-- OUTPUT PARAMETER RETURNS 1/0
AS
BEGIN
	IF (ISNULL(@p_USER_EMAIL, '') = '') OR ISNULL(@p_MEMBER, 0) = 0 OR ISNULL(@p_FISCAL_PERIOD, 0) = 0
		BEGIN
			PRINT 'MISSING REQUIRED PARAMETER'
			RETURN
		END
		ELSE
		BEGIN
			DECLARE @p_CLIENT_ID BIGINT
			DECLARE @strSQL NVARCHAR(max)
			DECLARE @EN_MEMBER_ASSIGNED_RATE BIGINT = 112788
			DECLARE @ASSIGNED_RATE_ATT_MEMBER BIGINT = 3061726
			DECLARE @ASSIGNED_RATE_ATT_FISCAL_PERIOD BIGINT = 3061730
			DECLARE @ASSIGNED_RATE_ATT_GROSS_AMOUNT BIGINT = 3061742
			DECLARE @ASSIGNED_RATE_ATT_TOTAL_OUTSTANDING BIGINT = 3061749

			SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USER_EMAIL
			IF (ISNULL(@p_CLIENT_ID, 0) != 0) 
			BEGIN
				SET @strSQL = 'SELECT @p_MEMBER_ASSIGNED_RATE = A.SEQ_ID
				FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A WITH (NOLOCK)
				INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES PIV_MEM ON PIV_MEM.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@ASSIGNED_RATE_ATT_MEMBER AS NVARCHAR(100)) +' AND PIV_MEM.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND PIV_MEM.ATTRIBUTE_DECIMAL = ' + CAST(@p_MEMBER  AS NVARCHAR(100)) +' 
				INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES PIV_FP ON PIV_FP.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@ASSIGNED_RATE_ATT_FISCAL_PERIOD AS NVARCHAR(100)) +'  AND PIV_FP.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND PIV_FP.ATTRIBUTE_DECIMAL = ' + CAST(@p_FISCAL_PERIOD  AS NVARCHAR(100)) +' 
				INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES PIV_GA ON PIV_GA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@ASSIGNED_RATE_ATT_GROSS_AMOUNT AS NVARCHAR(100)) +'  AND PIV_GA.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID 
				INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES PIV_TO ON PIV_TO.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@ASSIGNED_RATE_ATT_TOTAL_OUTSTANDING AS NVARCHAR(100)) +'  AND PIV_TO.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID 
				WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID = '+ CAST(@EN_MEMBER_ASSIGNED_RATE AS NVARCHAR(100)) +'  AND ISNULL(A.DELETED, ''N'') != ''Y'' AND PIV_TO.ATTRIBUTE_DECIMAL < PIV_GA.ATTRIBUTE_DECIMAL'
				PRINT @strSQL
				EXEC sp_executesql @strSQL, N'@p_MEMBER_ASSIGNED_RATE BIGINT OUTPUT', @p_MEMBER_ASSIGNED_RATE OUTPUT
				SELECT @p_MEMBER_ASSIGNED_RATE
			END
		END
END
;






-- ASAD


CREATE PROCEDURE [dbo].[GET_PERSON_ADD_EDIT_DETAILS_NI]
	@m_UCN BIGINT = NULL,
	@m_TITLE_DESC NVARCHAR(50) = NULL,
	@m_LAST_NAME NVARCHAR(50) = NULL,
	@m_FIRST_NAME NVARCHAR(50) = NULL,
	@m_SEX NVARCHAR(1) = NULL,
	@m_DATE_OF_BIRTH DATETIME = NULL,
	@m_NATIONALITY_DESC NVARCHAR(50) = NULL,
	@m_CRM_PERS_ADDRESSES_SEQ_ID BIGINT = NULL,
	@m_ADDRESS_TYPE NVARCHAR(1) = NULL,
	@m_ORG_NAME NVARCHAR(50) = NULL,
	@m_JOB_TITLE NVARCHAR(60) = NULL,
	@m_ADDR_LINE_1 NVARCHAR(50) = NULL,
	@m_ADDR_LINE_2 NVARCHAR(50) = NULL,
	@m_ADDR_LINE_3 NVARCHAR(50) = NULL,
	@m_TOWN NVARCHAR(50) = NULL,
	@m_POSTCODE NVARCHAR(30) = NULL,
	@m_COUNTY_DESC NVARCHAR(50) = NULL,
	@m_COUNTRY_DESC NVARCHAR(50) = NULL,
	@m_EMAIL_ADDRESS NVARCHAR(100) = NULL,
	@m_EMAIL_CRM_PERS_COMMS_ADDRESS_SEQ_ID BIGINT = NULL,
	@m_TELEPHONE_ADDRESS NVARCHAR(100) = NULL,
	@m_TELEPHONE_CRM_PERS_COMMS_ADDRESS_SEQ_ID BIGINT = NULL,
	@m_TYPE NVARCHAR(10) = NULL,
	@m_USER_ID NVarChar(30) = NULL,
	@m_COMPANY_ID NVarChar(10) = NULL,       
	@m_PARM_1 NVarChar(100) = NULL,
	@m_PARM_2 NVarChar(100) = NULL,
	@m_PARM_3 NVarChar(100) = NULL,
	--@m_SCHEME_TYPE_ID NVARCHAR(10) = NULL,
	--@m_LOGBOOK_TYPE  NVARCHAR(10) = NULL,
	@m_ERROR_ID INT OUTPUT,
	@m_ERROR_DESC NVarChar(100) OUTPUT
AS

	DECLARE @CRM_TITLES_SEQ_ID BIGINT
	DECLARE @CRM_NATIONALITIES_SEQ_ID BIGINT
	DECLARE @CRM_COUNTIES_SEQ_ID BIGINT
	DECLARE @CRM_COUNTRIES_SEQ_ID BIGINT
	DECLARE @CRM_COMMS_MODES_SEQ_ID BIGINT
	DECLARE @SOURCE_OF_DATA NVARCHAR(10)
	DECLARE @SOURCE_FILE NVARCHAR(10)
	DECLARE @CRM_ADDRESS_TYPES_SEQ_ID BIGINT
	DECLARE @CRM_PERSONS_SEQ_ID BIGINT
	DECLARE @CLIENT_ID NVARCHAR(20)
	DECLARE @CONTACT_CLIENT_ENTITY_SEQ_ID BIGINT = 9855
	DECLARE @TITLE_CLIENT_ENTITY BIGINT = 9860
	DECLARE @NATIONALITY_CLIENT_ENTITY BIGINT = 9858
	DECLARE @CONTACT_CLIENT_ENTITY BIGINT = 9855
	DECLARE @GENDER_CLIENT_ENTITY BIGINT = 10005
	DECLARE @GENDER_SEQ_ID BIGINT
	DECLARE @GENDER_DESCRIOTION NVARCHAR(20) 

	DECLARE @OLD_LOGBOOK_NO NVARCHAR(100)
	DECLARE @ACCOUNT_CLIENT_ENTITY_SEQ_ID BIGINT = 9856
	DECLARE @ORG_NAME_SEQ_ID BIGINT
	DECLARE @UCN BIGINT

	DECLARE @TODAY DATETIME
	DECLARE @CONTACT_LABEL_NAME NVARCHAR(100)
	DECLARE @DP_LOG_BOOKS_SEQ_ID BIGINT
	DECLARE @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID NVARCHAR(5) = 13026
	DECLARE @LOG_BOOK_NUMBER NVARCHAR(100) = ''

	SET @SOURCE_OF_DATA = 'SYS'
	SET @SOURCE_FILE = 'SYS'
	SET @TODAY = GETDATE()

	SELECT @CRM_PERSONS_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
		WHERE SRM_CLIENTS_SEQ_ID = 40
			  AND SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY_SEQ_ID 
			  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 212519 
			  AND ATTRIBUTE_STRING = @m_UCN AND DELETED != 'Y'


	SET @m_ERROR_ID = 0
	SET @m_ERROR_DESC = ''

	IF dbo.GetStringDate(@m_DATE_OF_BIRTH) = dbo.GetStringDate('1/1/1753') 
		SET @m_DATE_OF_BIRTH = NULL

	IF ISNULL(@m_USER_ID, '') = ''
		SET @m_USER_ID = 'Videotel'

	IF ISNULL(@m_TITLE_DESC, '') = ''
		SET @CRM_TITLES_SEQ_ID = NULL
	ELSE
	BEGIN
		SET @CRM_TITLES_SEQ_ID = NULL
		SELECT @CRM_TITLES_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
		WHERE SRM_CLIENTS_SEQ_ID = 40
			  AND SRM_CLIENT_ENTITIES_SEQ_ID = @TITLE_CLIENT_ENTITY 
			  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 212935 
			  AND ATTRIBUTE_STRING = @m_TITLE_DESC AND DELETED != 'Y'

		IF @CRM_TITLES_SEQ_ID IS NULL -- ADD A NEW TITLE
		BEGIN
			EXEC [dbo].[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_001 = @m_TITLE_DESC,
				@ATTRIBUTE_002 = 'Y',
				@DATE_CREATED = @TODAY,
				@CREATED_BY = @m_USER_ID,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @TITLE_CLIENT_ENTITY,
				@SRM_CLIENTS_SEQ_ID = 40,
				@RETURN_SEQ_ID = @CRM_TITLES_SEQ_ID OUTPUT,
				@ERROR = @m_ERROR_ID OUTPUT
		END
	END

	IF ISNULL(@m_NATIONALITY_DESC, '') = ''
		SET @CRM_NATIONALITIES_SEQ_ID = NULL
	ELSE
	BEGIN
		SET @CRM_NATIONALITIES_SEQ_ID = NULL
		SELECT @CRM_NATIONALITIES_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
		WHERE SRM_CLIENTS_SEQ_ID = 40
			  AND SRM_CLIENT_ENTITIES_SEQ_ID = @NATIONALITY_CLIENT_ENTITY 
			  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 212899 
			  AND ATTRIBUTE_STRING = @m_NATIONALITY_DESC AND DELETED != 'Y'

		IF @CRM_NATIONALITIES_SEQ_ID IS NULL -- ADD A NEW NATIONALITY
		BEGIN
			EXEC [dbo].[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_001 = @m_NATIONALITY_DESC,
				@ATTRIBUTE_002 = 'Y',
				@DATE_CREATED = @TODAY,
				@CREATED_BY = @m_USER_ID,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @NATIONALITY_CLIENT_ENTITY,
				@SRM_CLIENTS_SEQ_ID = 40,
				@RETURN_SEQ_ID = @CRM_NATIONALITIES_SEQ_ID OUTPUT,
				@ERROR = @m_ERROR_ID OUTPUT
		END
	END

	IF ISNULL(@m_COUNTY_DESC, '') = ''
		SET @CRM_COUNTIES_SEQ_ID = NULL
	ELSE
	BEGIN
		DECLARE @COUNTY_CLIENT_ENTITY BIGINT = 9878
		SET @CRM_COUNTIES_SEQ_ID = NULL

		SELECT @CRM_COUNTIES_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
		WHERE SRM_CLIENTS_SEQ_ID = 40
			  AND SRM_CLIENT_ENTITIES_SEQ_ID = @COUNTY_CLIENT_ENTITY 
			  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 213346 
			  AND ATTRIBUTE_STRING = @m_COUNTY_DESC AND DELETED != 'Y'

		IF @CRM_COUNTIES_SEQ_ID IS NULL -- ADD A NEW COUNTY
		BEGIN
			EXEC [dbo].[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_001 = @m_COUNTY_DESC,
				@ATTRIBUTE_002 = 'Y',
				@DATE_CREATED = @TODAY,
				@CREATED_BY = @m_USER_ID,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @COUNTY_CLIENT_ENTITY,
				@SRM_CLIENTS_SEQ_ID = 40,
				@RETURN_SEQ_ID = @CRM_COUNTIES_SEQ_ID OUTPUT,
				@ERROR = @m_ERROR_ID OUTPUT
		END
	END

	DECLARE @COUNTRY_CLIENT_ENTITY BIGINT = 9877

	IF ISNULL(@m_COUNTRY_DESC, '') = ''
	BEGIN		
		SELECT @CRM_COUNTRIES_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
		WHERE SRM_CLIENTS_SEQ_ID = 40
			  AND SRM_CLIENT_ENTITIES_SEQ_ID = @COUNTRY_CLIENT_ENTITY 
			  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 213344 
			  AND ATTRIBUTE_BOOLEAN = 'Y' AND DELETED != 'Y'

		SELECT @m_COUNTRY_DESC = ATTRIBUTE_001 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE SEQ_ID = @CRM_COUNTRIES_SEQ_ID
	END
	ELSE
	BEGIN
		SET @CRM_COUNTRIES_SEQ_ID = NULL

		SELECT @CRM_COUNTRIES_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
		WHERE SRM_CLIENTS_SEQ_ID = 40
			  AND SRM_CLIENT_ENTITIES_SEQ_ID = @COUNTRY_CLIENT_ENTITY 
			  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 213329 
			  AND ATTRIBUTE_STRING = @m_COUNTRY_DESC AND DELETED != 'Y'

		IF @CRM_COUNTRIES_SEQ_ID IS NULL -- ADD A NEW COUNTRY
		BEGIN
			PRINT 'ADDING A NEW COUNTRY'
			EXEC [dbo].[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_001 = @m_COUNTRY_DESC,
				@ATTRIBUTE_002 = 'Y',
				@DATE_CREATED = @TODAY,
				@CREATED_BY = @m_USER_ID,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @COUNTRY_CLIENT_ENTITY,
				@SRM_CLIENTS_SEQ_ID = 40,
				@RETURN_SEQ_ID = @CRM_COUNTRIES_SEQ_ID OUTPUT,
				@ERROR = @m_ERROR_ID OUTPUT
		END
	END

	IF ISNULL(@m_SEX , '') = 'F'
	BEGIN
		SELECT @GENDER_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID , @GENDER_DESCRIOTION = ATTRIBUTE_STRING FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
		WHERE SRM_CLIENTS_SEQ_ID = 40
			  AND SRM_CLIENT_ENTITIES_SEQ_ID = @GENDER_CLIENT_ENTITY 
			  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 216176 
			  AND ATTRIBUTE_STRING = 'Female' AND DELETED != 'Y'
	END
	ELSE IF ISNULL(@m_SEX , '') = 'M'
	BEGIN
		SELECT @GENDER_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID , @GENDER_DESCRIOTION = ATTRIBUTE_STRING FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
		WHERE SRM_CLIENTS_SEQ_ID = 40
			  AND SRM_CLIENT_ENTITIES_SEQ_ID = @GENDER_CLIENT_ENTITY 
			  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 216176 
			  AND ATTRIBUTE_STRING = 'Male' AND DELETED != 'Y'
	END
	-- UPDATE MAIN DETAILS			
	DECLARE @DOB date
	IF (@m_DATE_OF_BIRTH != NULL OR @m_DATE_OF_BIRTH != '')
		SET @DOB = cast(@m_DATE_OF_BIRTH as date)  --CONVERT(DATETIME, @m_DATE_OF_BIRTH, 121)

	DECLARE @Contact_Number NVARCHAR(100)
	
	IF ISNULL(@m_UCN, 0) = 0
	BEGIN
		EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 1, @SRM_CLIENTS_SEQ_ID = 40, @PIVOT_NEXT_ID = @Contact_Number OUTPUT

		SET @CONTACT_LABEL_NAME = LTRIM(RTRIM(ISNULL(@m_TITLE_DESC,'') +' '+ ISNULL(@m_FIRST_NAME,'') + ' ' +ISNULL(@m_LAST_NAME,'')))
		EXEC [dbo].[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_003 = @Contact_Number,
				@ATTRIBUTE_025 = @CRM_TITLES_SEQ_ID,
				@ATTRIBUTE_026 = @m_TITLE_DESC,
				@ATTRIBUTE_184 = @CRM_COUNTRIES_SEQ_ID,
				@ATTRIBUTE_185 = @m_COUNTRY_DESC,
				@ATTRIBUTE_004 = @m_LAST_NAME,
				@ATTRIBUTE_005 = @m_FIRST_NAME,
				@ATTRIBUTE_011 = @DOB,
				@ATTRIBUTE_110 = @GENDER_SEQ_ID,
				@ATTRIBUTE_111 = @GENDER_DESCRIOTION,
				@ATTRIBUTE_023 = @CRM_NATIONALITIES_SEQ_ID,
				@ATTRIBUTE_024 = @m_NATIONALITY_DESC,
				@ATTRIBUTE_056 = @m_EMAIL_ADDRESS,
				@ATTRIBUTE_053 = @m_TELEPHONE_ADDRESS,
				@ATTRIBUTE_001 = @CONTACT_LABEL_NAME,
				@ATTRIBUTE_186 = @m_PARM_1,
				@DATE_CREATED = @TODAY,
				@CREATED_BY = @m_USER_ID,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY,
				@SRM_CLIENTS_SEQ_ID = 40,
				@RETURN_SEQ_ID = @CRM_PERSONS_SEQ_ID OUTPUT,
				@ERROR = @m_ERROR_ID OUTPUT

	END
	ELSE
	BEGIN		
		SELECT @CRM_PERSONS_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
		WHERE SRM_CLIENTS_SEQ_ID = 40
			  AND SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY_SEQ_ID 
			  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 212519 
			  AND ATTRIBUTE_STRING = @m_UCN AND DELETED != 'Y'

		IF @CRM_PERSONS_SEQ_ID > 0
		BEGIN
			SELECT @OLD_LOGBOOK_NO = ATTRIBUTE_STRING FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
			WHERE SRM_CLIENTS_SEQ_ID = 40
			AND SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY_SEQ_ID 
			AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 287380 
			AND CUS_ENTITY_DATA_SEQ_ID = @CRM_PERSONS_SEQ_ID AND DELETED != 'Y'

			SET @ORG_NAME_SEQ_ID = 0
			SET @m_ORG_NAME = RTRIM(LTRIM(ISNULL(@m_ORG_NAME,'')))
			IF RTRIM(LTRIM(ISNULL(@m_ORG_NAME,''))) != ''
			BEGIN
				SELECT @ORG_NAME_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
				WHERE SRM_CLIENTS_SEQ_ID = 40
				AND SRM_CLIENT_ENTITIES_SEQ_ID = @ACCOUNT_CLIENT_ENTITY_SEQ_ID 
				AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 212707 
				AND ATTRIBUTE_STRING = @m_ORG_NAME AND DELETED != 'Y'

				IF @ORG_NAME_SEQ_ID = 0
				BEGIN
					PRINT 'ADDING A NEW ACCOUNT'
					EXEC [dbo].[GET_PIVOT_NEXT_ID]
						@UNIQUE_INDEX_ID = 1,
						@SRM_CLIENTS_SEQ_ID = 40,
						@PIVOT_NEXT_ID = @UCN OUTPUT,
						@ERROR = @m_ERROR_ID OUTPUT,
						@ERROR_DESCRIPTION = @m_ERROR_DESC OUTPUT

					EXEC [dbo].[GET_INSERT_CUS_ENTITY_DATA]
						@ATTRIBUTE_003 = @UCN,
						@ATTRIBUTE_001 = @m_ORG_NAME,
						@ATTRIBUTE_009 = @m_ORG_NAME,
						@DATE_CREATED = @TODAY,
						@CREATED_BY = @m_USER_ID,
						@SRM_CLIENT_ENTITIES_SEQ_ID = @ACCOUNT_CLIENT_ENTITY_SEQ_ID,
						@SRM_CLIENTS_SEQ_ID = 40,
						@RETURN_SEQ_ID = @ORG_NAME_SEQ_ID OUTPUT,
						@ERROR = @m_ERROR_ID OUTPUT

						
						EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
						@SRM_CLIENT_ENTITIES_SEQ_ID = @ACCOUNT_CLIENT_ENTITY_SEQ_ID,
						@CUS_ENTITY_DATA_SEQ_ID = @ORG_NAME_SEQ_ID,
						@SRM_CLIENTS_SEQ_ID = 40,
						@ERROR = @m_ERROR_ID OUTPUT,
						@ERROR_DESCRIPTION = @m_ERROR_DESC OUTPUT

						EXEC [dbo].[TRIGGER_NEW_ACCOUNT_REPLICATE_TO_NI] 
						@RECORD_ID = @ORG_NAME_SEQ_ID,
						@ERROR = @m_ERROR_ID OUTPUT
				END
				PRINT '@ORG_NAME_SEQ_ID ' + CAST(@ORG_NAME_SEQ_ID AS NVARCHAR(100))
			END

			UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA
			SET ATTRIBUTE_025 = @CRM_TITLES_SEQ_ID,
				ATTRIBUTE_026 = @m_TITLE_DESC,
				ATTRIBUTE_184 = @CRM_COUNTRIES_SEQ_ID,
				ATTRIBUTE_185 = @m_COUNTRY_DESC,
				ATTRIBUTE_004 = @m_LAST_NAME,
				ATTRIBUTE_005 = @m_FIRST_NAME,
				ATTRIBUTE_110 = @GENDER_SEQ_ID,
				ATTRIBUTE_111 = @GENDER_DESCRIOTION,
				ATTRIBUTE_011 = @DOB,
				ATTRIBUTE_023 = @CRM_NATIONALITIES_SEQ_ID,
				ATTRIBUTE_024 = @m_NATIONALITY_DESC,
				ATTRIBUTE_056 = @m_EMAIL_ADDRESS,
				ATTRIBUTE_053 = @m_TELEPHONE_ADDRESS,
				ATTRIBUTE_001 = LTRIM(RTRIM(ISNULL(@m_TITLE_DESC,'') +' '+ ISNULL(@m_FIRST_NAME,'') + ' ' +ISNULL(@m_LAST_NAME,''))),
				ATTRIBUTE_186 =  RTRIM(LTRIM(ISNULL(@m_PARM_1,''))),
				ATTRIBUTE_058 = @ORG_NAME_SEQ_ID,
				ATTRIBUTE_059 = @m_ORG_NAME,
				MODIFIED_BY   = @m_USER_ID,
				DATE_MODIFIED = @TODAY
			WHERE SEQ_ID = @CRM_PERSONS_SEQ_ID AND ATTRIBUTE_003 = @m_UCN AND SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY_SEQ_ID AND SRM_CLIENTS_SEQ_ID = 40

			EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
			@SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CRM_PERSONS_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = 40,
			@ERROR = @m_ERROR_ID OUTPUT,
			@ERROR_DESCRIPTION = @m_ERROR_DESC OUTPUT

		END
	END

	SELECT @m_UCN = ATTRIBUTE_003, @CONTACT_LABEL_NAME = ATTRIBUTE_001  FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE SEQ_ID = @CRM_PERSONS_SEQ_ID 

	IF RTRIM(LTRIM(ISNULL(@m_PARM_1,''))) <> ''
	BEGIN
	
		SET @LOG_BOOK_NUMBER = RTRIM(LTRIM(@m_PARM_1))
		Print '@OLD_LOGBOOK_NO ' + @OLD_LOGBOOK_NO

		SELECT @DP_LOG_BOOKS_SEQ_ID = SEQ_ID FROM  [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA
				WHERE SEQ_ID IN (select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID AND srm_client_entity_Attributes_seq_id = 287021
					AND ATTRIBUTE_STRING = @LOG_BOOK_NUMBER AND DELETED != 'Y'
					INTERSECT
					select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID AND srm_client_entity_Attributes_seq_id = 287032
					and CAST(ATTRIBUTE_DECIMAL AS BIGINT) = @CRM_PERSONS_SEQ_ID AND DELETED != 'Y')

		--SELECT @DP_LOG_BOOKS_SEQ_ID = SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID AND ATTRIBUTE_001 = @LOG_BOOK_NUMBER AND ATTRIBUTE_002 = @CRM_PERSONS_SEQ_ID AND SRM_CLIENTS_SEQ_ID = 40 AND DELETED != 'Y'			
		print '@DP_LOG_BOOKS_SEQ_ID ' + cast(@DP_LOG_BOOKS_SEQ_ID as nvarchar(100))

		IF ISNULL(@DP_LOG_BOOKS_SEQ_ID, 0) = 0
		BEGIN
			EXEC [dbo].[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_001 = @LOG_BOOK_NUMBER,
				@ATTRIBUTE_002 = @CRM_PERSONS_SEQ_ID,
				@ATTRIBUTE_003 = @CONTACT_LABEL_NAME,
				@DATE_CREATED = @TODAY,
				@CREATED_BY = @m_USER_ID,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID,
				@SRM_CLIENTS_SEQ_ID = 40,
				@RETURN_SEQ_ID = @DP_LOG_BOOKS_SEQ_ID OUTPUT,
				@ERROR = @m_ERROR_ID OUTPUT

			UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA
			SET ATTRIBUTE_186 = @LOG_BOOK_NUMBER,
				MODIFIED_BY   = @m_USER_ID,
				DATE_MODIFIED = @TODAY
			WHERE SEQ_ID = @CRM_PERSONS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY_SEQ_ID AND SRM_CLIENTS_SEQ_ID = 40

			EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
			@SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CRM_PERSONS_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = 40,
			@ERROR = @m_ERROR_ID OUTPUT,
			@ERROR_DESCRIPTION = @m_ERROR_DESC OUTPUT

		END
		ELSE
		BEGIN
			UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA
			SET ATTRIBUTE_186 = @LOG_BOOK_NUMBER,
				MODIFIED_BY   = @m_USER_ID,
				DATE_MODIFIED = @TODAY
			WHERE SEQ_ID = @CRM_PERSONS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY_SEQ_ID AND SRM_CLIENTS_SEQ_ID = 40

			EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
			@SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CRM_PERSONS_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = 40,
			@ERROR = @m_ERROR_ID OUTPUT,
			@ERROR_DESCRIPTION = @m_ERROR_DESC OUTPUT
		END
	END


	EXEC [dbo].[GET_PERSON_DETAILS_NI]
		@m_UCN = @m_UCN,
		@m_USER_ID = @m_USER_ID,
		@m_COMPANY_ID = @m_COMPANY_ID,
		@m_PARM_1 = NULL,
		@m_PARM_2 = NULL,
		@m_PARM_3 = NULL,
		@m_ERROR_ID = @m_ERROR_ID OUTPUT,
		@m_ERROR_DESC = @m_ERROR_DESC OUTPUT




;






CREATE PROCEDURE [dbo].[GET_PERSON_DETAILS_NI]

	@m_UCN BIGINT = NULL,

	@m_USER_ID NVarChar(30) = NULL,

	@m_COMPANY_ID NVarChar(10) = NULL,          

	@m_PARM_1 NVarChar(100) = NULL,

	@m_PARM_2 NVarChar(max) = NULL,

	@m_PARM_3 NVarChar(100) = NULL,

	@m_ERROR_ID INT OUTPUT,

	@m_ERROR_DESC NVarChar(100) OUTPUT

	

AS

	DECLARE @STR_SQL NVARCHAR(max)

	
		DECLARE	@CONTACT_CLIENT_ENTITY_SEQ_ID NVARCHAR(5) = 9855
		DECLARE @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID NVARCHAR(5) = 13026


	SET @m_ERROR_ID = 0

	SET @m_ERROR_DESC = ''	


	IF ISNULL(@m_USER_ID, '') = ''

		SET @m_USER_ID = 'Videotel'


		SET @STR_SQL = 'SELECT DISTINCT CONTACTS.ATTRIBUTE_003 AS UCN, CONTACTS.ATTRIBUTE_026 AS TITLE_DESC, CONTACTS.ATTRIBUTE_004 AS LAST_NAME, CONTACTS.ATTRIBUTE_005 AS FIRST_NAME, CONTACTS.ATTRIBUTE_111 AS SEX, CONTACTS.ATTRIBUTE_011 AS DATE_OF_BIRTH, ISNULL(CONTACTS.ATTRIBUTE_059,'''') AS ORG_NAME,CONTACTS.ATTRIBUTE_023 AS CRM_NATIONALITIES_SEQ_ID,CONTACTS.ATTRIBUTE_184 AS CRM_COUNTRIES_SEQ_ID, CONTACTS.ATTRIBUTE_056 AS EMAIL_ADDRESS, 
		CONTACTS.ATTRIBUTE_186 AS LOGBOOK_NUMBER, 0 AS CRM_PERS_ADDRESSES_SEQ_ID, DATE_CREATED 
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA AS CONTACTS 
		WHERE CONTACTS.SRM_CLIENTS_SEQ_ID = 40 AND CONTACTS.SRM_CLIENT_ENTITIES_SEQ_ID = '+@CONTACT_CLIENT_ENTITY_SEQ_ID+' AND CONTACTS.DELETED != ''Y'''

	IF @m_PARM_1 = 'MULTIPLE_UCN'

		SET @STR_SQL = @STR_SQL + ' AND CONTACTS.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES where SRM_CLIENT_ENTITIES_SEQ_ID = 9855 and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 212519 AND ATTRIBUTE_STRING IN (' + @m_PARM_2 + '))'

	
	ELSE IF ISNULL(@m_UCN, 0) <> 0

		SET @STR_SQL = @STR_SQL + ' AND CONTACTS.SEQ_ID = (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES where SRM_CLIENT_ENTITIES_SEQ_ID = 9855 and SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 212519 AND ATTRIBUTE_STRING IN (' + CAST(@m_UCN AS NVARCHAR)+'))'

	PRINT (@STR_SQL)	

	EXECUTE(@STR_SQL)



	IF @@Rowcount = 0

	BEGIN

		SET @m_ERROR_ID = -1

		SET @m_ERROR_DESC = 'No Record Found.'

	END



;







CREATE PROCEDURE [dbo].[GET_PERSON_DUPLICATE_CHECK_NI]

	@m_FIRST_NAME NVarChar(50) = NULL,

	@m_LAST_NAME NVarChar(50) = NULL,

	@m_DATE_OF_BIRTH DATETIME = NULL,

	@m_USER_ID NVarChar(30) = NULL,

	@m_COMPANY_ID NVarChar(10) = NULL,          

	@m_PARM_1 NVarChar(100) = NULL,

	@m_PARM_2 NVarChar(100) = NULL,

	@m_PARM_3 NVarChar(100) = NULL,

	@m_ERROR_ID INT OUTPUT,

	@m_ERROR_DESC NVarChar(100) OUTPUT

	

AS

	DECLARE @UCNs NVARCHAR(max)
	DECLARE @CONTACT_CLIENT_ENTITY_SEQ_ID BIGINT = 9855
	SET @UCNs = NULL



	SET @m_ERROR_ID = 0

	SET @m_ERROR_DESC = ''

	

	IF dbo.GetStringDate(@m_DATE_OF_BIRTH) = dbo.GetStringDate('1/1/1753') 

		SET @m_DATE_OF_BIRTH = NULL

		
	IF ISNULL(@m_USER_ID, '') = ''

		SET @m_USER_ID = 'Videotel'

	
	DECLARE @TEMP_CUS_ENTITY_TABLE TABLE
	(
		CUS_SEQ_ID BIGINT
	)

	SET @m_FIRST_NAME = RTRIM(LTRIM(ISNULL(@m_FIRST_NAME,'')))
	SET @m_LAST_NAME = RTRIM(LTRIM(ISNULL(@m_LAST_NAME,'')))


	IF ISNULL(@m_FIRST_NAME,'') != '' AND ISNULL(@m_LAST_NAME,'') != '' AND ISNULL(@m_DATE_OF_BIRTH,'') != ''
	BEGIN
		
		INSERT INTO @TEMP_CUS_ENTITY_TABLE (CUS_SEQ_ID)
		SELECT SEQ_ID FROM  [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA

				WHERE SEQ_ID IN (select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212520
					and attribute_string like '%' + @m_LAST_name + '%'
					INTERSECT
					select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212521
					and attribute_string like '%' + @m_FIRST_name + '%'
					INTERSECT 
					select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212528
					and attribute_datetime = @m_DATE_OF_BIRTH)

	END
	ELSE IF ISNULL(@m_FIRST_NAME,'') != '' AND ISNULL(@m_LAST_NAME,'') != '' AND ISNULL(@m_DATE_OF_BIRTH,'') = ''
	BEGIN
		
		INSERT INTO @TEMP_CUS_ENTITY_TABLE (CUS_SEQ_ID)
		SELECT SEQ_ID FROM  [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA

				WHERE SEQ_ID IN (select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212520
					and attribute_string like '%' + @m_LAST_name + '%'
					INTERSECT
					select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212521
					and attribute_string like '%' + @m_FIRST_name + '%')

	END
	ELSE IF ISNULL(@m_FIRST_NAME,'') != '' AND ISNULL(@m_DATE_OF_BIRTH,'') != ''
	BEGIN

		INSERT INTO @TEMP_CUS_ENTITY_TABLE (CUS_SEQ_ID)
		SELECT SEQ_ID FROM  [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA

				WHERE SEQ_ID IN (
					select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212521
					and attribute_string like '%' + @m_FIRST_name + '%'
					INTERSECT 
					select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212528
					and attribute_datetime = @m_DATE_OF_BIRTH)

	END
	ELSE IF ISNULL(@m_LAST_name,'') != '' AND ISNULL(@m_DATE_OF_BIRTH,'') != ''
	BEGIN

		INSERT INTO @TEMP_CUS_ENTITY_TABLE (CUS_SEQ_ID)
		SELECT SEQ_ID FROM  [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA

				WHERE SEQ_ID IN (select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212520
					and attribute_string like '%' + @m_LAST_name + '%'
					INTERSECT
					select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212528
					and attribute_datetime = @m_DATE_OF_BIRTH)

	END
	ELSE IF ISNULL(@m_FIRST_NAME,'') != '' AND ISNULL(@m_DATE_OF_BIRTH,'') = ''
	BEGIN

		INSERT INTO @TEMP_CUS_ENTITY_TABLE (CUS_SEQ_ID)
		SELECT SEQ_ID FROM  [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA

				WHERE SEQ_ID IN (select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212521
					and attribute_string like '%' + @m_FIRST_name + '%')

	END
	ELSE IF ISNULL(@m_LAST_name,'') != '' AND ISNULL(@m_DATE_OF_BIRTH,'') = ''
	BEGIN

		INSERT INTO @TEMP_CUS_ENTITY_TABLE (CUS_SEQ_ID)
		SELECT SEQ_ID FROM  [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA

				WHERE SEQ_ID IN (select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212520
					and attribute_string like '%' + @m_LAST_name + '%')		
		
	END
	ELSE IF ISNULL(@m_DATE_OF_BIRTH,'') != ''
	BEGIN

		INSERT INTO @TEMP_CUS_ENTITY_TABLE (CUS_SEQ_ID)
		SELECT SEQ_ID FROM  [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA

				WHERE SEQ_ID IN (select distinct cus_entity_data_seq_id from [srm-datapivot].dbo.cus_pivot_non_unique_indexes where srm_client_entities_seq_id = 9855 AND srm_client_entity_Attributes_seq_id = 212528
					and attribute_datetime = @m_DATE_OF_BIRTH)

	END




	IF EXISTS (SELECT SEQ_ID FROM  [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA

				WHERE SEQ_ID IN (SELECT CUS_SEQ_ID FROM  @TEMP_CUS_ENTITY_TABLE))


	BEGIN

	
		SELECT @UCNs = COALESCE(@UCNs + ',', '') + cast(ATTRIBUTE_003 as Varchar) 

		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA

		WHERE SEQ_ID IN (SELECT CUS_SEQ_ID FROM  @TEMP_CUS_ENTITY_TABLE) 


			

		EXEC [dbo].[GET_PERSON_DETAILS_NI]

			@m_UCN = NULL,

			@m_USER_ID = @m_USER_ID,

			@m_COMPANY_ID = @m_COMPANY_ID,

			@m_PARM_1 = 'MULTIPLE_UCN',

			@m_PARM_2 = @UCNs,

			@m_PARM_3 = NULL,

			@m_ERROR_ID = @m_ERROR_ID OUTPUT,

			@m_ERROR_DESC = @m_ERROR_DESC OUTPUT

			

		SET @m_ERROR_ID = 0

		SET @m_ERROR_DESC = ''

	END

	ELSE

	BEGIN

		EXEC [dbo].[GET_PERSON_DETAILS_NI]

			@m_UCN = -1,

			@m_USER_ID = @m_USER_ID,

			@m_COMPANY_ID = @m_COMPANY_ID,

			@m_PARM_1 = NULL,

			@m_PARM_2 = NULL,

			@m_PARM_3 = NULL,

			@m_ERROR_ID = @m_ERROR_ID OUTPUT,

			@m_ERROR_DESC = @m_ERROR_DESC OUTPUT

		

		SET @m_ERROR_ID = -1

		SET @m_ERROR_DESC = 'No Record Found.'	

	END



;





CREATE PROCEDURE [dbo].[GET_PIVOT_NEXT_ID]
	-- Add the parameters for the stored procedure here
	@UNIQUE_INDEX_ID SMALLINT= NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@PIVOT_NEXT_ID BIGINT OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.

	-- Need to make this SP Dynamic also transaction should be implemented

	SET NOCOUNT ON;
	DECLARE @SQL NVARCHAR(MAX)
	DECLARE @RETRY_COUNT INT
	
	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_PIVOT_NEXT_ID]'
	SET @RETRY_COUNT = 1


BEGIN Tran 
	GET_NEXT_ID:


		SET @SQL = 'SELECT @PIVOT_NEXT_ID_DYN = MAX(ATTRIBUTE_DECIMAL) + 1  FROM [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS VARCHAR) + '].dbo.CUS_PIVOT_UNIQUE_INDEXES WHERE UNIQUE_INDEX_ID = @UNIQUE_INDEX_ID_DYN AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID_DYN'
		EXEC sp_executesql
		@sql,
		N'@UNIQUE_INDEX_ID_DYN SMALLINT, @SRM_CLIENTS_SEQ_ID_DYN BIGINT, @PIVOT_NEXT_ID_DYN BIGINT OUTPUT',
		@SRM_CLIENTS_SEQ_ID_DYN = @SRM_CLIENTS_SEQ_ID,
		@UNIQUE_INDEX_ID_DYN = @UNIQUE_INDEX_ID,
		@PIVOT_NEXT_ID_DYN = @PIVOT_NEXT_ID OUTPUT;
	

		IF ISNULL(@PIVOT_NEXT_ID, 0) = 0
			SET @PIVOT_NEXT_ID = 1
	
		BEGIN TRY
			SET @SQL = 'INSERT INTO [SRM-CustomEntities_' + CAST(@SRM_CLIENTS_SEQ_ID AS VARCHAR) + '].dbo.CUS_PIVOT_UNIQUE_INDEXES 
	    			(
	    				ATTRIBUTE_DECIMAL,
	    				UNIQUE_INDEX_ID,
	    				SRM_CLIENTS_SEQ_ID
	    			)
	    			VALUES
	    			(
	    				@PIVOT_NEXT_ID_DYN,
	    				@UNIQUE_INDEX_ID_DYN,
	    				@SRM_CLIENTS_SEQ_ID_DYN
	    			)
	    
	    			SET @ERROR_DYN = 0
	    			SET @ERROR_DESCRIPTION_DYN = '''''
			EXEC sp_executesql
			@sql,
			N'@PIVOT_NEXT_ID_DYN BIGINT,
			@UNIQUE_INDEX_ID_DYN SMALLINT,
			@SRM_CLIENTS_SEQ_ID_DYN BIGINT,
			@ERROR_DYN SMALLINT OUTPUT,
			@ERROR_DESCRIPTION_DYN VARCHAR(200) OUTPUT',

			@SRM_CLIENTS_SEQ_ID_DYN = @SRM_CLIENTS_SEQ_ID,
			@UNIQUE_INDEX_ID_DYN = @UNIQUE_INDEX_ID,
			@ERROR_DYN = @ERROR OUTPUT,
			@ERROR_DESCRIPTION_DYN = @ERROR_DESCRIPTION OUTPUT,
			@PIVOT_NEXT_ID_DYN = @PIVOT_NEXT_ID;

		END TRY

		BEGIN CATCH
			IF @RETRY_COUNT > 5
			BEGIN
				SET @ERROR = -1
				SET @ERROR_DESCRIPTION = 'Error in incrementing the ID'
				Rollback Tran
			END
			ELSE
			BEGIN
				SET @RETRY_COUNT = @RETRY_COUNT + 1
				GOTO GET_NEXT_ID
			END
		END CATCH	
	

IF @@TRANCOUNT > 0 Commit Tran 

END
;



