CREATE PROCEDURE [dbo].[GET_POPULATE_COURSES_BOOKED_AND_ATTENDED]   
  @m_CLIENT_SEQ_ID BIGINT,  
  @m_MEMBER_CUS_ENTITY_DATA_SEQ_ID BIGINT,  
  @ERROR SMALLINT = NULL OUTPUT,  
  @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT  
 AS   
 BEGIN  
    
 SET NOCOUNT ON;  
   
 DECLARE @ACCOUNT_CONTACT_SEQ_ID BIGINT  
 DECLARE @EVE_REG_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
 DECLARE @EVE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
 DECLARE @CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
   
 DECLARE @MEM_TYPE CHAR--A(ACCOUNT) OR C(CONTACT)  
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
 DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
 DECLARE @NEW_SEQ_ID BIGINT  
 DECLARE @SRM_ENTITY_NAME NVARCHAR(200)  
 DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)  
   
 DECLARE @USERNAME NVARCHAR(100)  
 DECLARE @EVENT_ID NVARCHAR(100)  
 DECLARE @EVENT_NAME NVARCHAR(100)  
 DECLARE @EVENT_START_DATE NVARCHAR(100)  
 DECLARE @ATTENDED NVARCHAR(100)  
 DECLARE @BOOKER NVARCHAR(100)  
   
    
 DECLARE @DATEMODIFIED DATETIME  
 DECLARE @MODIFIEDBY NVARCHAR(200)  
 DECLARE @DATECREATED DATETIME  
 DECLARE @CREATEDBY NVARCHAR(200)  
  
 SET @ERROR = 1  
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_COURSES_BOOKED_AND_ATTENDED]'  
  
 SELECT @ACCOUNT_CONTACT_SEQ_ID = CASE WHEN ISNULL(ATTRIBUTE_015,'')='' THEN ATTRIBUTE_017 ELSE ATTRIBUTE_015 END,  
   @MEM_TYPE=CASE WHEN ISNULL(ATTRIBUTE_015,'')='' THEN 'C' ELSE 'A' END  
   FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM WHERE SEQ_ID=@m_MEMBER_CUS_ENTITY_DATA_SEQ_ID  
  
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME   
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D  
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID  
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID  
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_COURSES_BOOKED_AND_ATTENDED'  
  
 SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME   
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D  
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID  
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID  
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT_DELEGATE'  
  
 SELECT @EVE_REG_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME   
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D  
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID  
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID  
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT_REGISTRATION'  
   
 SELECT @EVE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME   
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D  
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID  
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID  
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT'  
   
 SELECT @CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME   
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D  
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID  
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID  
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'CONTACT'  

 DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR   
      
   SELECT   
   CONTACT.ATTRIBUTE_020 AS USERNAME,  
   EVE.ATTRIBUTE_002 AS EVENT_ID,  
   EVE.ATTRIBUTE_001 AS EVENT_NAME,  
   EVE.ATTRIBUTE_004 AS EVENT_START_DATE,  
   EVE_REG.ATTRIBUTE_022 AS ATTENDED,  
   CASE WHEN EVE_DELEGATE.ATTRIBUTE_004=EVE_REG.ATTRIBUTE_012 THEN 'Y'ELSE 'N' END AS BOOKER,  
   EVE_DELEGATE.DATE_CREATED,  
   EVE_DELEGATE.CREATED_BY,  
   EVE_DELEGATE.DATE_MODIFIED,  
   EVE_DELEGATE.MODIFIED_BY  
     
   FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVE_DELEGATE WITH(NOLOCK)
   LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVE_REG WITH(NOLOCK) ON  EVE_REG.SRM_CLIENT_ENTITIES_SEQ_ID=@EVE_REG_SRM_CLIENT_ENTITIES_SEQ_ID AND EVE_REG.SEQ_ID IN(SELECT ATTRIBUTE_DECIMAL FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =54366 AND CUS_ENTITY_DATA_SEQ_ID =EVE_DELEGATE.SEQ_ID ) --EVE_DELEGATE.ATTRIBUTE_002 
   LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVE     WITH(NOLOCK) ON  EVE.SRM_CLIENT_ENTITIES_SEQ_ID=@EVE_SRM_CLIENT_ENTITIES_SEQ_ID		    AND EVE.SEQ_ID IN(SELECT ATTRIBUTE_DECIMAL FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =54380 AND CUS_ENTITY_DATA_SEQ_ID =EVE_DELEGATE.SEQ_ID)--EVE_DELEGATE.ATTRIBUTE_016  
   LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA CONTACT WITH(NOLOCK) ON  CONTACT.SRM_CLIENT_ENTITIES_SEQ_ID=@CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID AND CONTACT.SEQ_ID IN(SELECT ATTRIBUTE_DECIMAL FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =54368 AND CUS_ENTITY_DATA_SEQ_ID =EVE_DELEGATE.SEQ_ID)--EVE_DELEGATE.ATTRIBUTE_004  
     
   WHERE EVE_DELEGATE.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID  
   AND EVE_DELEGATE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =54368 AND ATTRIBUTE_DECIMAL=@ACCOUNT_CONTACT_SEQ_ID ) 
   AND EVE_DELEGATE.DELETED <>'Y'  
    
     
 OPEN CUR_RECORDS  

 FETCH NEXT FROM CUR_RECORDS INTO  @USERNAME,@EVENT_ID,@EVENT_NAME,@EVENT_START_DATE,@ATTENDED,@BOOKER,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY   

   --DELETE IF ALREADY EXITS   
 IF (EXISTS(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56172 AND ATTRIBUTE_STRING = @USERNAME))  
 BEGIN  
	DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56172 AND ATTRIBUTE_STRING = @USERNAME)
	DELETE FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56172 AND ATTRIBUTE_STRING = @USERNAME
 END  

 WHILE @@FETCH_STATUS = 0  
 BEGIN  

	  EXEC  [DBO].[GET_INSERT_CUS_ENTITY_DATA]  
		   @SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID,  
		   @ATTRIBUTE_001=@USERNAME,  
		   @ATTRIBUTE_002=@EVENT_ID,  
		   @ATTRIBUTE_003=@EVENT_NAME,  
		   @ATTRIBUTE_004=@EVENT_START_DATE,  
		   @ATTRIBUTE_005=@ATTENDED,  
		   @ATTRIBUTE_006=@BOOKER,  
		   @SRM_CLIENTS_SEQ_ID=@M_CLIENT_SEQ_ID,  
		   @DATE_CREATED=@DATECREATED,  
		   @CREATED_BY=@CREATEDBY,  
		   @DATE_MODIFIED=@DATEMODIFIED,  
		   @MODIFIED_BY=@MODIFIEDBY,  
		   @RETURN_SEQ_ID=@NEW_SEQ_ID OUTPUT,  
		   @ERROR=@ERROR OUTPUT,  
		   @ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT  
  
	 FETCH NEXT FROM CUR_RECORDS INTO  @USERNAME,@EVENT_ID,@EVENT_NAME,@EVENT_START_DATE,@ATTENDED,@BOOKER,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY   
 END  
  
 CLOSE CUR_RECORDS  
 DEALLOCATE CUR_RECORDS  
   
 SET @ERROR = 0  
 SET @ERROR_DESCRIPTION = ''  
END



;





CREATE PROCEDURE [dbo].[GET_POPULATE_DEFAULT_VIEWS_FOR_GLOBAL_SEARCH]
	@SRM_CLIENTS_SEQ_ID bigint = NULL 
as

	DECLARE @SRM_USERS_SEQ_ID bigint

	IF @SRM_CLIENTS_SEQ_ID IS NULL
	BEGIN
		DECLARE CUR_USERS CURSOR LOCAL STATIC FOR
		SELECT SEQ_ID, SRM_CLIENTS_SEQ_ID FROM SRM_USERS WHERE ACTIVE = 'Y' ORDER BY SRM_USERS.SEQ_ID
	END 
	ELSE 
	BEGIN
		DECLARE CUR_USERS CURSOR LOCAL STATIC FOR
		SELECT SEQ_ID, SRM_CLIENTS_SEQ_ID FROM SRM_USERS WHERE ACTIVE = 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID ORDER BY SRM_USERS.SEQ_ID, SRM_USERS.SRM_CLIENTS_SEQ_ID
	END 

	OPEN CUR_USERS

	FETCH NEXT FROM CUR_USERS INTO @SRM_USERS_SEQ_ID, @SRM_CLIENTS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT 'PROCESSING FOR CLIENT: ' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR) + ' AND USER: ' + CAST(@SRM_USERS_SEQ_ID AS NVARCHAR)
		EXEC [dbo].[GET_POPULATE_DEFAULT_VIEWS_FOR_GLOBAL_SEARCH_SINGLE_USER]
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@SRM_USERS_SEQ_ID = @SRM_USERS_SEQ_ID

		FETCH NEXT FROM CUR_USERS INTO @SRM_USERS_SEQ_ID, @SRM_CLIENTS_SEQ_ID
	END

	CLOSE CUR_USERS
	DEALLOCATE CUR_USERS

/*
	INSERT INTO SRM_CLIENT_FILTER_VIEW_DEFAULT
	(
		SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
		SRM_CLIENT_ENTITIES_SEQ_ID,
		SRM_CLIENTS_SEQ_ID,
		SRM_USERS_SEQ_ID,
		DATE_CREATED,
		CREATED_BY,
		DELETED
	)
	select SRM_CLIENT_FILTER_VIEWS_seq_id, SRM_CLIENt_entities_seq_id, srm_clients_seq_id, SRM_USERS_SEQ_ID, Date_Created, login_user_name, Deleted
	from
	(SELECT
		distinct SRM_CLIENT_FILTER_VIEWS.seq_id SRM_CLIENT_FILTER_VIEWS_seq_id,
		SRM_CLIENt_entities_seq_id,
		SRM_USERS.srm_clients_seq_id,
		SRM_USERS.SEQ_ID SRM_USERS_SEQ_ID,
		GETDATE() Date_Created,
		'System' login_user_name,
		'N' Deleted
	FROM SRM_CLIENT_FILTER_VIEWS with (nolock)
	inner join SRM_USERS  with (nolock) on (SRM_USERS.deleted = 'N' or SRM_USERS.deleted is null) and SRM_USERS.srm_clients_seq_id = @srm_clients_seq_id
	inner join SRM_CLIENt_entities  with (nolock) on SRM_CLIENt_entities.seq_id = SRM_CLIENT_FILTER_VIEWS.SRM_CLIENt_entities_seq_id AND ISNULL(SRM_CLIENt_entities.DO_NOT_SHOW_IN_GLOBAL_SEARCH,'N')!='Y'
	WHERE SRM_CLIENt_entities.srm_clients_seq_id = @srm_clients_seq_id and isnull(SRM_CLIENT_FILTER_VIEWS.deleted, 'N') = 'N' and FILTER_VIEW_TYPE_ID = 4 and SRM_CLIENT_FILTER_VIEWS.seq_id in
	(select min(SRM_CLIENT_FILTER_VIEWS.seq_id) from SRM_CLIENT_FILTER_VIEWS with (nolock)
	inner join SRM_CLIENt_entities  with (nolock) on SRM_CLIENt_entities.seq_id = SRM_CLIENT_FILTER_VIEWS.SRM_CLIENt_entities_seq_id
	WHERE FILTER_VIEW_TYPE_ID = 4 and SRM_CLIENt_entities.srm_clients_seq_id = @srm_clients_seq_id and isnull(SRM_CLIENT_FILTER_VIEWS.deleted, 'N') = 'N'
	group by SRM_CLIENt_entities_seq_id)) a
	where  convert(nvarchar(20), SRM_USERS_seq_id) + '|' +  convert(nvarchar(20), SRM_CLIENt_entities_seq_id)
	not in (select convert(nvarchar(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_USERS_seq_id) + '|' +  convert(nvarchar(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_CLIENt_entities_seq_id)
	from SRM_CLIENT_FILTER_VIEW_DEFAULT with (nolock) where isnull(SRM_CLIENT_FILTER_VIEW_DEFAULT.deleted, 'N') = 'N' and SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_CLIENTS_SEQ_ID = @srm_clients_seq_id
	and convert(nvarchar(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_USERS_seq_id) + '|' +  convert(nvarchar(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_CLIENt_entities_seq_id) is not null)

*/


;





-- EXEC DBO.GET_POPULATE_DEFAULT_VIEWS_FOR_GLOBAL_SEARCH_FOR_ALL_CLIENTS

CREATE PROCEDURE [dbo].[GET_POPULATE_DEFAULT_VIEWS_FOR_GLOBAL_SEARCH_FOR_ALL_CLIENTS]
as

	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT

	DECLARE CUR_CLIENTS CURSOR LOCAL STATIC 
	FOR
		SELECT SEQ_ID FROM SRM_CLIENTS WHERE CLIENT_NAME NOT LIKE '%DELETE%' ORDER BY SEQ_ID
		--AND (SEQ_ID IN (SELECT SRM_CLIENTS_SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE DATEDIFF(hh, DATE_CREATED, GETDATE()) < 24)
		--OR SEQ_ID IN (SELECT SRM_CLIENTS_SEQ_ID FROM SRM_USERS WHERE DATEDIFF(hh, DATE_CREATED, GETDATE()) < 24))

	OPEN CUR_CLIENTS
	FETCH NEXT FROM CUR_CLIENTS INTO @SRM_CLIENTS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT 'PROCESSING FOR CLIENT ' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR)
		EXEC DBO.GET_POPULATE_DEFAULT_VIEWS_FOR_GLOBAL_SEARCH 
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

		FETCH NEXT FROM CUR_CLIENTS INTO @SRM_CLIENTS_SEQ_ID
	END

	CLOSE CUR_CLIENTS
	DEALLOCATE CUR_CLIENTS


;





CREATE PROCEDURE [dbo].[GET_POPULATE_DEFAULT_VIEWS_FOR_GLOBAL_SEARCH_SINGLE_USER]
	@SRM_CLIENTS_SEQ_ID bigint,
	@SRM_USERS_SEQ_ID bigint

as

	INSERT INTO SRM_CLIENT_FILTER_VIEW_DEFAULT
	(
		SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
		SRM_CLIENT_ENTITIES_SEQ_ID,
		SRM_CLIENTS_SEQ_ID,
		SRM_USERS_SEQ_ID,
		DATE_CREATED,
		CREATED_BY,
		DELETED
	)
	select SRM_CLIENT_FILTER_VIEWS_seq_id, SRM_CLIENt_entities_seq_id, srm_clients_seq_id, SRM_USERS_SEQ_ID, Date_Created, login_user_name, Deleted
	from
	(SELECT
		distinct SRM_CLIENT_FILTER_VIEWS.seq_id SRM_CLIENT_FILTER_VIEWS_seq_id,
		SRM_CLIENt_entities_seq_id,
		SRM_USERS.srm_clients_seq_id,
		SRM_USERS.SEQ_ID SRM_USERS_SEQ_ID,
		GETDATE() Date_Created,
		'System' login_user_name,
		'N' Deleted
	FROM SRM_CLIENT_FILTER_VIEWS with (nolock)
	inner join SRM_USERS  with (nolock) on (SRM_USERS.deleted = 'N' or SRM_USERS.deleted is null) and SRM_USERS.srm_clients_seq_id = @srm_clients_seq_id AND SRM_USERS.SEQ_ID = @SRM_USERS_seq_id
	inner join SRM_CLIENt_entities  with (nolock) on SRM_CLIENt_entities.seq_id = SRM_CLIENT_FILTER_VIEWS.SRM_CLIENt_entities_seq_id AND ISNULL(SRM_CLIENt_entities.DO_NOT_SHOW_IN_GLOBAL_SEARCH,'N')!='Y'
	WHERE (SRM_CLIENt_entities.srm_clients_seq_id = 500 or SRM_CLIENt_entities.srm_clients_seq_id = @srm_clients_seq_id) and isnull(SRM_CLIENT_FILTER_VIEWS.deleted, 'N') = 'N' and FILTER_VIEW_TYPE_ID = 4 and SRM_CLIENT_FILTER_VIEWS.seq_id in
	(select min(SRM_CLIENT_FILTER_VIEWS.seq_id) from SRM_CLIENT_FILTER_VIEWS with (nolock)
	inner join SRM_CLIENt_entities  with (nolock) on SRM_CLIENt_entities.seq_id = SRM_CLIENT_FILTER_VIEWS.SRM_CLIENt_entities_seq_id
	WHERE FILTER_VIEW_TYPE_ID = 4 and (SRM_CLIENt_entities.srm_clients_seq_id = 500 or SRM_CLIENt_entities.srm_clients_seq_id = @srm_clients_seq_id) and isnull(SRM_CLIENT_FILTER_VIEWS.deleted, 'N') = 'N'
	group by SRM_CLIENt_entities_seq_id)) a
	where  convert(nvarchar(20), SRM_USERS_seq_id) + '|' +  convert(nvarchar(20), SRM_CLIENt_entities_seq_id)
	not in (select convert(nvarchar(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_USERS_seq_id) + '|' +  convert(nvarchar(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_CLIENt_entities_seq_id)
	from SRM_CLIENT_FILTER_VIEW_DEFAULT with (nolock) where SRM_USERS_seq_id = @SRM_USERS_SEQ_ID AND isnull(SRM_CLIENT_FILTER_VIEW_DEFAULT.deleted, 'N') = 'N' and SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_CLIENTS_SEQ_ID = @srm_clients_seq_id
	and convert(nvarchar(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_USERS_seq_id) + '|' +  convert(nvarchar(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_CLIENt_entities_seq_id) is not null)


;





    
    
