                 AND ISNULL(ATTRIBUTE_BOOLEAN,'N') = 'Y' --[SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_003 = 'Y' --AVAILABLE ON PORTAL  
