-- =============================================
-- Author:  <Mazhar>
-- Create date: <14/08/2013,,>
-- Description: <Apply Area of Focus Data to Web service Area of Focus>
-- =============================================
CREATE PROCEDURE  [dbo].[GET_POPULATE_MEMBERSHIP] 
	 @CLIENT_SEQ_ID BIGINT,
	 @CUS_ENTITY_DATA_SEQ_ID BIGINT,
	 @ERROR SMALLINT = 0 OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
 AS 
 BEGIN
  
	SET NOCOUNT ON;
	--START (THIS PATCH OF CODE IS WRITTEN TO PICK THE LIVE MEMBER IF GIVEN SEQ_ID IS OF ARCHIVED MEMBER)
	DECLARE @CONTACT BIGINT
	DECLARE @ACCOUNT BIGINT
	DECLARE @CUS_ENTITY_DATA_SEQ_ID2 BIGINT

	DECLARE @COUNTER INT
	SET @COUNTER = 0

	IF NOT EXISTS(select SEQ_ID from [srm-customentities].dbo.cus_entity_data where seq_id=@CUS_ENTITY_DATA_SEQ_ID AND DELETED='N' AND ATTRIBUTE_022 IN (
	SELECT SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2577 AND DELETED='N' AND ISNULL(ATTRIBUTE_006, 'N') = 'Y'))
	BEGIN
		select @ACCOUNT=ATTRIBUTE_015,@CONTACT=ATTRIBUTE_017 from [srm-customentities].dbo.cus_entity_data where seq_id=@CUS_ENTITY_DATA_SEQ_ID 
	
		SELECT @CUS_ENTITY_DATA_SEQ_ID2=SEQ_ID FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2541 AND DELETED='N' 
		AND ISNULL(ATTRIBUTE_015,0)=ISNULL(@ACCOUNT,0) AND ISNULL(ATTRIBUTE_017,0)=ISNULL(@CONTACT,0)
		AND ATTRIBUTE_022 IN (
		SELECT SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2577 AND DELETED='N' AND ISNULL(ATTRIBUTE_006, 'N') = 'Y')

		IF ISNULL(@CUS_ENTITY_DATA_SEQ_ID2,0) != 0
			SET @CUS_ENTITY_DATA_SEQ_ID=@CUS_ENTITY_DATA_SEQ_ID2
	
	END




	--END
	-- populate member and also all of other members paid by this.
	DECLARE @PAY_BY BIGINT , @ACCOUNT2 BIGINT
    SELECT @PAY_BY=ISNULL(ATTRIBUTE_029,0) , @ACCOUNT2=ISNULL(ATTRIBUTE_015,0) FROM [SRM-CustomEntities]..CUS_ENTITY_DATA WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2541 AND SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID

			DECLARE CUR_MEMBERSHIP_PAID_BY CURSOR LOCAL STATIC FOR
			SELECT DISTINCT MEM.SEQ_ID
			FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA  MEM WITH(NOLOCK) 
			WHERE MEM.SRM_CLIENT_ENTITIES_SEQ_ID = 2541 
			AND MEM.SEQ_ID IN (
							  SELECT @CUS_ENTITY_DATA_SEQ_ID 
							  UNION
							  SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2541 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52025 AND ATTRIBUTE_DECIMAL= @PAY_BY AND @PAY_BY>0
							  UNION
							  SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2541 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52011 AND ATTRIBUTE_DECIMAL=@PAY_BY AND @PAY_BY>0 
							  UNION
							  SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=2541 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52025 AND ATTRIBUTE_DECIMAL= @ACCOUNT2 AND @ACCOUNT2>0
							)


	OPEN CUR_MEMBERSHIP_PAID_BY

	FETCH NEXT FROM CUR_MEMBERSHIP_PAID_BY INTO @CUS_ENTITY_DATA_SEQ_ID
	WHILE @@FETCH_STATUS = 0
	BEGIN
		DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
		DECLARE @CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
		DECLARE @ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
		DECLARE @ACCOUNT_CON_REL_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
		DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
		DECLARE @NEW_SEQ_ID BIGINT
		DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
		DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)
		DECLARE @WEB_PAY_HIST_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
		DECLARE @MEM_LEDGER_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
		
		DECLARE @SURNAME NVARCHAR(200)
		DECLARE @FIRST_NAME NVARCHAR(100)
		DECLARE @MIDDLE_NAME NVARCHAR(100)
		DECLARE @DOB NVARCHAR(100)
		DECLARE @HOW_DID_YOU_HEAR_ABOUT_THE_ASSOCIATION NVARCHAR(100)
		
		DECLARE @ADDRESS_LINE_1 NVARCHAR(100)
		DECLARE @ADDRESS_LINE_2 NVARCHAR(100)
		DECLARE @ADDRESS_LINE_3 NVARCHAR(100)
		DECLARE @ADDRESS_LINE_4 NVARCHAR(100)
		
		DECLARE @TOWN NVARCHAR(100)
		DECLARE @POSTCODE NVARCHAR(100)
		DECLARE @COUNTY NVARCHAR(100)
		DECLARE @COUNTRY NVARCHAR(100)
		DECLARE @TEL_NUMBER NVARCHAR(100)
		DECLARE @MOBILE NVARCHAR(100)
		DECLARE @EMAIL NVARCHAR(100)
		DECLARE @FAX NVARCHAR(100)
		DECLARE @ORGANISATION_ID NVARCHAR(100)
		DECLARE @ORGANISATION_NAME NVARCHAR(200)
		DECLARE @JOB_TITLE NVARCHAR(200)
		DECLARE @JOB_CATEGORY NVARCHAR(200)
		
		DECLARE @ORG_ADDRESS_LINE_1 NVARCHAR(200)
		DECLARE @ORG_ADDRESS_LINE_2 NVARCHAR(200)
		DECLARE @ORG_ADDRESS_LINE_3 NVARCHAR(200)
		DECLARE @ORG_ADDRESS_LINE_4 NVARCHAR(200)
		
		DECLARE @ORGANISATION_TYPE NVARCHAR(200)
		DECLARE @PASSWORD NVARCHAR(200)
		DECLARE @ORG_ADDRESS_POSTCODE NVARCHAR(200)
		DECLARE @ORG_ADDRESS_COUNTY NVARCHAR(200)
		DECLARE @ORG_ADDRESS_COUNTRY NVARCHAR(200)
		DECLARE @USER_NAME NVARCHAR(200)
		DECLARE @CATEGORY_OF_MEMBERSHIP NVARCHAR(200)
		DECLARE @MEMBER_ID NVARCHAR(200)
		DECLARE @DEPARTMENTAL_MEMBER_ID NVARCHAR(200)
		DECLARE @AREA_OF_FOCUS NVARCHAR(200)
		DECLARE @ORGANISATION_TEL NVARCHAR(200)
		DECLARE @ORGANISATION_FAX NVARCHAR(200)
		DECLARE @ORGANISATION_EMAIL NVARCHAR(200)
		DECLARE @CURRICULUM_CREDITS_AVAILABLE NVARCHAR(200)
		DECLARE @TRANSACTION_TYPE NVARCHAR(200)
		DECLARE @TITLE NVARCHAR(200)
		DECLARE @PREFERRED_MAILING_ADDRESS_NAME NVARCHAR(100)
		DECLARE @PREFERRED_BILLING_ADDRESS_NAME NVARCHAR(100)
		DECLARE @PAYMENT_DATE NVARCHAR(200)
		DECLARE @PAYMENT_METHOD NVARCHAR(200)
		DECLARE @PAYMENT_AMOUNT NVARCHAR(200)
		DECLARE @HIS_USER_NAME NVARCHAR(200)
		DECLARE @HIST_DATEMODIFIED DATETIME
		DECLARE @HIST_MODIFIEDBY NVARCHAR(200)
		DECLARE @HIST_DATECREATED DATETIME
		DECLARE @HIST_CREATEDBY NVARCHAR(200)
		
		DECLARE @DATEMODIFIED DATETIME
		DECLARE @MODIFIEDBY NVARCHAR(200)
		DECLARE @DATECREATED DATETIME
		DECLARE @CREATEDBY NVARCHAR(200)

		DECLARE @SALE_ID NVARCHAR(100)
		DECLARE @PAY_BY_INVOICE NVARCHAR(100)
		DECLARE @PAY_BY_DIRECT_DEBIT NVARCHAR(100)
		DECLARE @NEXT_RENEWAL_DATE NVARCHAR(100)
		DECLARE @TOTAL_OUTSTANDING NVARCHAR(100)
		DECLARE @MEMBERSHIP_STATUS NVARCHAR(100)
		DECLARE @HAS_MEMBERSHIP_TAGS CHAR(1)
		DECLARE @MEMBERSHIP_TAGS NVARCHAR(2000)
	
		SET @ERROR = 1
		SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_MEMBERSHIP]'

		SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
		FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH (NOLOCK),[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH (NOLOCK)
		WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
		AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
		AND C.SRM_CLIENTS_SEQ_ID = @CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_MEMBERSHIP'

		SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
		FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH (NOLOCK),[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH (NOLOCK)
		WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
		AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
		AND C.SRM_CLIENTS_SEQ_ID = @CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'MEMBER'

		SELECT @CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID 
		FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH (NOLOCK),[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH (NOLOCK)
		WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
		AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
		AND C.SRM_CLIENTS_SEQ_ID = @CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'CONTACT'
		
		SELECT @ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID 
		FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH (NOLOCK),[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH (NOLOCK)
		WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
		AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
		AND C.SRM_CLIENTS_SEQ_ID = @CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'ACCOUNT'

		SELECT @ACCOUNT_CON_REL_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID 
		FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH (NOLOCK),[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH (NOLOCK)
		WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
		AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
		AND C.SRM_CLIENTS_SEQ_ID = @CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'ACCOUNT_CONTACT_RELATIONSHIP'


		SELECT @WEB_PAY_HIST_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
		FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH (NOLOCK),[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH (NOLOCK)
		WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
		AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
		AND C.SRM_CLIENTS_SEQ_ID = @CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_MEMBER_PAYMENT_HISTORY'

		SELECT @MEM_LEDGER_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
		FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH (NOLOCK),[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH (NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH (NOLOCK)
		WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
		AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
		AND C.SRM_CLIENTS_SEQ_ID = @CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'MEMBER_LEDGER'



		--DELETE IF ALREADY EXITS MEMBER DATA
		SELECT @MEMBER_ID = MEM.ATTRIBUTE_001 FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM WITH (NOLOCK) WHERE MEM.SEQ_ID=@CUS_ENTITY_DATA_SEQ_ID AND MEM.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID 
		--IF (EXISTS(SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH (NOLOCK) WHERE ATTRIBUTE_045=@MEMBER_ID AND SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID))

		IF (EXISTS(SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=55327 AND ATTRIBUTE_STRING = @MEMBER_ID))
		BEGIN
			DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=55327 AND ATTRIBUTE_STRING = @MEMBER_ID)
			DELETE FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=55327 AND ATTRIBUTE_STRING = @MEMBER_ID
			
			IF (SELECT ISNULL(MEM.DELETED,'N')  
				FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM WITH (NOLOCK) 
				WHERE MEM.SEQ_ID=@CUS_ENTITY_DATA_SEQ_ID
				AND MEM.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID)='Y'
				CONTINUE
		END

		DECLARE @MEM_TABLE TABLE 
			(SEQ_ID BIGINT)

		INSERT INTO @MEM_TABLE SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH (NOLOCK) 
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@ACCOUNT_CON_REL_SRM_CLIENT_ENTITIES_SEQ_ID 
				  AND SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 53459 AND ATTRIBUTE_DECIMAL = @CONTACT)

		-----------
		DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR 
				SELECT TOP 1
					CONTACT.ATTRIBUTE_004 AS SURNAME,
					CONTACT.ATTRIBUTE_005 AS FIRST_NAME,
					CONTACT.ATTRIBUTE_006 AS MIDDLE_NAME,
					CONTACT.ATTRIBUTE_011 AS DOB,
					CONTACT.ATTRIBUTE_032 AS HOW_DID_YOU_HEAR_ABOUT_THE_ASSOCIATION,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_035 ELSE ACCOUNT.ATTRIBUTE_024 END AS ADDRESS_LINE_1,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_036 ELSE ACCOUNT.ATTRIBUTE_025 END AS ADDRESS_LINE_2,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_037 ELSE ACCOUNT.ATTRIBUTE_026 END AS ADDRESS_LINE_3,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_136 ELSE ACCOUNT.ATTRIBUTE_105 END AS ADDRESS_LINE_4,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_038 ELSE ACCOUNT.ATTRIBUTE_027 END AS TOWN,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_039 ELSE ACCOUNT.ATTRIBUTE_028 END AS POSTCODE,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_041 ELSE ACCOUNT.ATTRIBUTE_030 END AS COUNTY,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_043 ELSE ACCOUNT.ATTRIBUTE_032 END AS COUNTRY,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_053 ELSE ACCOUNT.ATTRIBUTE_043 END AS TEL_NUMBER,
					CONTACT.ATTRIBUTE_055 AS MOBILE,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_056 ELSE ACCOUNT.ATTRIBUTE_045 END AS EMAIL,
					ACCOUNT.ATTRIBUTE_046 AS FAX,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN LINK_ACCOUNT.SEQ_ID ELSE ACCOUNT.SEQ_ID END AS ORGANISATION_ID,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN LINK_ACCOUNT.ATTRIBUTE_001 ELSE ACCOUNT.ATTRIBUTE_001 END AS ORGANISATION_NAME,
					CONTACT.ATTRIBUTE_143 AS JOB_TITLE,
					ACCOUNT_CONTACT_LINK.ATTRIBUTE_007 AS JOB_CATEGORY,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_044 ELSE ACCOUNT.ATTRIBUTE_033 END AS ORG_ADDRESS_LINE_1,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_045 ELSE ACCOUNT.ATTRIBUTE_034 END AS ORG_ADDRESS_LINE_2,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_046 ELSE ACCOUNT.ATTRIBUTE_035 END AS ORG_ADDRESS_LINE_3,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN  CONTACT.ATTRIBUTE_137 ELSE ACCOUNT.ATTRIBUTE_104 END AS ORG_ADDRESS_LINE_4,
					
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN LINK_ACCOUNT.ATTRIBUTE_015 ELSE ACCOUNT.ATTRIBUTE_015 END AS  ORGANISATION_TYPE,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN CONTACT.ATTRIBUTE_022 ELSE ACCOUNT.ATTRIBUTE_013 END AS  [PASSWORD],
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN CONTACT.ATTRIBUTE_048 ELSE ACCOUNT.ATTRIBUTE_038 END AS  ORG_ADDRESS_POSTCODE,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN CONTACT.ATTRIBUTE_050 ELSE ACCOUNT.ATTRIBUTE_040 END AS  ORG_ADDRESS_COUNTY,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN CONTACT.ATTRIBUTE_052 ELSE ACCOUNT.ATTRIBUTE_042 END AS  ORG_ADDRESS_COUNTRY,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN CONTACT.ATTRIBUTE_020 ELSE ACCOUNT.ATTRIBUTE_011 END AS  [USER_NAME],
					
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN CONTACT.ATTRIBUTE_140 ELSE ACCOUNT.ATTRIBUTE_108 END AS  PREFERRED_MAILING_ADDRESS_NAME,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_015,'')='' THEN CONTACT.ATTRIBUTE_141 ELSE ACCOUNT.ATTRIBUTE_109 END AS  PREFERRED_BILLING_ADDRESS_NAME,
					
					MEM.ATTRIBUTE_014 AS CATEGORY_OF_MEMBERSHIP,
					MEM.ATTRIBUTE_001 AS MEMBER_ID,
					PAID_BY_MEMBERSHIP.ATTRIBUTE_001 AS DEPARTMENTAL_MEMBER_ID,
					CONTACT.ATTRIBUTE_133 AS AREA_OF_FOCUS,
					LINK_ACCOUNT.ATTRIBUTE_043 ORGANISATION_TEL,
					LINK_ACCOUNT.ATTRIBUTE_046 ORGANISATION_FAX,
					LINK_ACCOUNT.ATTRIBUTE_045 ORGANISATION_EMAIL,
					CASE WHEN cast(MEM.ATTRIBUTE_029 as bigint)>0 THEN PAID_BY_MEMBERSHIP.ATTRIBUTE_035 ELSE MEM.ATTRIBUTE_035 END AS CURRICULUM_CREDITS_AVAILABLE,
					-- NOT USED MEM.ATTRIBUTE_035 AS CURRICULUM_CREDITS_AVAILABLE,
					CASE WHEN ISNULL(MEM.ATTRIBUTE_029,'')<>'' THEN '1' ELSE '2' END AS  TRANSACTION_TYPE,
					CONTACT.ATTRIBUTE_026 AS TITLE,
					MEM.DATE_CREATED,
					MEM.CREATED_BY,
					MEM.DATE_MODIFIED,
					MEM.MODIFIED_BY,
					-- added Sale ID, Pay By Invoice and Pay by DD fields - Start
					MEM.ATTRIBUTE_047 AS SALE_ID,
					MEM.ATTRIBUTE_048 AS PAY_BY_INVOICE,
					MEM.ATTRIBUTE_049 AS PAY_BY_DIRECT_DEBIT,
					MEM.ATTRIBUTE_005 AS NEXT_RENEWAL_DATE,
					MEM.ATTRIBUTE_028 AS TOTAL_OUTSTANDING,
					MEM.ATTRIBUTE_023 AS MEMBERSHIP_STATUS, 
					MEM.ATTRIBUTE_053 AS HAS_MEMBERSHIP_TAGS,
					MEM.ATTRIBUTE_057 AS MEMBERSHIP_TAGS
					-- added Sale ID, Pay By Invoice and Pay by DD fields - End
					FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM WITH (NOLOCK)
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA CONTACT WITH (NOLOCK) ON CONTACT.SRM_CLIENT_ENTITIES_SEQ_ID=@CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID AND CONTACT.SEQ_ID IN (SELECT ATTRIBUTE_DECIMAL FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE CUS_ENTITY_DATA_SEQ_ID = MEM.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52013)
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA ACCOUNT WITH (NOLOCK) ON ACCOUNT.SRM_CLIENT_ENTITIES_SEQ_ID=@ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID AND ACCOUNT.SEQ_ID IN (SELECT ATTRIBUTE_DECIMAL FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE CUS_ENTITY_DATA_SEQ_ID = MEM.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52011)

					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA ACCOUNT_CONTACT_LINK WITH (NOLOCK) ON ACCOUNT_CONTACT_LINK.SRM_CLIENT_ENTITIES_SEQ_ID=@ACCOUNT_CON_REL_SRM_CLIENT_ENTITIES_SEQ_ID 
						 AND ACCOUNT_CONTACT_LINK.SEQ_ID IN (
							SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES Q1, @MEM_TABLE MT WHERE Q1.CUS_ENTITY_DATA_SEQ_ID = MT.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 53459 AND ATTRIBUTE_DECIMAL = CONTACT.SEQ_ID
							INTERSECT SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES Q2, @MEM_TABLE MT WHERE Q2.CUS_ENTITY_DATA_SEQ_ID = MT.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 53467 AND ATTRIBUTE_BOOLEAN = 'Y'
							INTERSECT SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES Q3, @MEM_TABLE MT WHERE Q3.CUS_ENTITY_DATA_SEQ_ID = MT.SEQ_ID AND  SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 53468 AND ATTRIBUTE_BOOLEAN = 'N')

					--	AND ACCOUNT_CONTACT_LINK.SEQ_ID IN (
						
					--	SELECT T4.CUS_ENTITY_DATA_SEQ_ID FROM (
					--	SELECT T2.CUS_ENTITY_DATA_SEQ_ID FROM (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES 
					--										    WHERE ATTRIBUTE_DECIMAL = CONTACT.SEQ_ID
					--											AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 53459
					--										  ) T1
					--	INNER JOIN [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES T2 ON T2.CUS_ENTITY_DATA_SEQ_ID = T1.CUS_ENTITY_DATA_SEQ_ID
					--	WHERE T2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 53467 AND T2.ATTRIBUTE_BOOLEAN = 'Y'
					--	) T3 INNER JOIN [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES T4 ON T4.CUS_ENTITY_DATA_SEQ_ID=T3.CUS_ENTITY_DATA_SEQ_ID
					--	WHERE T4.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 53468 AND T4.ATTRIBUTE_BOOLEAN = 'N'
					--	)


					
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA LINK_ACCOUNT WITH (NOLOCK) ON LINK_ACCOUNT.SRM_CLIENT_ENTITIES_SEQ_ID=@ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID AND LINK_ACCOUNT.DELETED='N'
					AND LINK_ACCOUNT.SEQ_ID IN (SELECT ATTRIBUTE_DECIMAL FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE CUS_ENTITY_DATA_SEQ_ID = ACCOUNT_CONTACT_LINK.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 53457) 
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA PAID_BY WITH (NOLOCK) ON PAID_BY.SRM_CLIENT_ENTITIES_SEQ_ID=@ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID AND PAID_BY.DELETED='N' AND PAID_BY.SEQ_ID IN (SELECT ATTRIBUTE_DECIMAL FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE CUS_ENTITY_DATA_SEQ_ID = MEM.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52025)
					LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA PAID_BY_MEMBERSHIP WITH (NOLOCK) ON PAID_BY_MEMBERSHIP.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND PAID_BY_MEMBERSHIP.DELETED='N' AND PAID_BY_MEMBERSHIP.SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE ATTRIBUTE_DECIMAL = PAID_BY.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52011)
					
					WHERE MEM.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID 
					AND MEM.SEQ_ID=@CUS_ENTITY_DATA_SEQ_ID 
						AND MEM.SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) 
						WHERE CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID
						AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52027
						AND ATTRIBUTE_BOOLEAN <> 'Y'
						)
				
		OPEN CUR_RECORDS
		
		FETCH NEXT FROM CUR_RECORDS INTO   @SURNAME, @FIRST_NAME,@MIDDLE_NAME,@DOB,@HOW_DID_YOU_HEAR_ABOUT_THE_ASSOCIATION,
										    @ADDRESS_LINE_1,@ADDRESS_LINE_2,@ADDRESS_LINE_3, @ADDRESS_LINE_4, 
											@TOWN,@POSTCODE,@COUNTY,@COUNTRY,@TEL_NUMBER,@MOBILE,@EMAIL,@FAX,
											@ORGANISATION_ID,@ORGANISATION_NAME, @JOB_TITLE,@JOB_CATEGORY,
											@ORG_ADDRESS_LINE_1,@ORG_ADDRESS_LINE_2,@ORG_ADDRESS_LINE_3,@ORG_ADDRESS_LINE_4,
											@ORGANISATION_TYPE,@PASSWORD,@ORG_ADDRESS_POSTCODE,@ORG_ADDRESS_COUNTY,
											@ORG_ADDRESS_COUNTRY,@USER_NAME,@PREFERRED_MAILING_ADDRESS_NAME,@PREFERRED_BILLING_ADDRESS_NAME, @CATEGORY_OF_MEMBERSHIP,@MEMBER_ID,@DEPARTMENTAL_MEMBER_ID,
											@AREA_OF_FOCUS, @ORGANISATION_TEL,@ORGANISATION_FAX,@ORGANISATION_EMAIL,@CURRICULUM_CREDITS_AVAILABLE, @TRANSACTION_TYPE,	 @TITLE,@DATECREATED, @CREATEDBY , 
											@DATEMODIFIED , @MODIFIEDBY, @SALE_ID, @PAY_BY_INVOICE, @PAY_BY_DIRECT_DEBIT, @NEXT_RENEWAL_DATE, @TOTAL_OUTSTANDING, @MEMBERSHIP_STATUS, @HAS_MEMBERSHIP_TAGS, @MEMBERSHIP_TAGS
											
		WHILE @@FETCH_STATUS = 0
		BEGIN
			SET @COUNTER = @COUNTER + 1
			IF @PREFERRED_MAILING_ADDRESS_NAME = 'HOME'
				SET @PREFERRED_MAILING_ADDRESS_NAME = 'Home'
			ELSE
				SET @PREFERRED_MAILING_ADDRESS_NAME = 'Organisation'

			IF @PREFERRED_BILLING_ADDRESS_NAME = 'HOME'
				SET @PREFERRED_BILLING_ADDRESS_NAME = 'Home'
			ELSE
				SET @PREFERRED_BILLING_ADDRESS_NAME = 'Organisation'

			--SYNCH MEMBERSHIP RECORD
			EXEC  [DBO].[GET_INSERT_CUS_ENTITY_DATA]
				@SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID,
				@ATTRIBUTE_001=@SURNAME,
				@ATTRIBUTE_003=@FIRST_NAME,
				@ATTRIBUTE_004=@MIDDLE_NAME,
				@ATTRIBUTE_006=@DOB,
				@ATTRIBUTE_007=@HOW_DID_YOU_HEAR_ABOUT_THE_ASSOCIATION,
				@ATTRIBUTE_011=@ADDRESS_LINE_1,
				@ATTRIBUTE_012=@ADDRESS_LINE_2,
				@ATTRIBUTE_013=@ADDRESS_LINE_3,
				@ATTRIBUTE_014=@ADDRESS_LINE_4,
				@ATTRIBUTE_016=@TOWN,
				@ATTRIBUTE_017=@POSTCODE,
				@ATTRIBUTE_018=@COUNTY,
				@ATTRIBUTE_019=@COUNTRY,
				@ATTRIBUTE_020=@TEL_NUMBER,
				@ATTRIBUTE_021=@MOBILE,
				@ATTRIBUTE_022=@EMAIL,
				@ATTRIBUTE_023=@FAX,
				@ATTRIBUTE_058=@ORGANISATION_ID,
				@ATTRIBUTE_024=@ORGANISATION_NAME,
				@ATTRIBUTE_025=@JOB_TITLE,
				@ATTRIBUTE_026=@JOB_CATEGORY,
				@ATTRIBUTE_027=@ORG_ADDRESS_LINE_1,
				@ATTRIBUTE_028=@ORG_ADDRESS_LINE_2,
				@ATTRIBUTE_029=@ORG_ADDRESS_LINE_3,
				@ATTRIBUTE_030=@ORG_ADDRESS_LINE_4,
				@ATTRIBUTE_032=@ORGANISATION_TYPE,
				@ATTRIBUTE_033=@PASSWORD,
				@ATTRIBUTE_038=@ORG_ADDRESS_POSTCODE,
				@ATTRIBUTE_039=@ORG_ADDRESS_COUNTY,
				@ATTRIBUTE_040=@ORG_ADDRESS_COUNTRY,
				@ATTRIBUTE_041=@USER_NAME,
				@ATTRIBUTE_042=@CATEGORY_OF_MEMBERSHIP,
				@ATTRIBUTE_045=@MEMBER_ID,
				@ATTRIBUTE_046=@DEPARTMENTAL_MEMBER_ID,
				@ATTRIBUTE_047=@AREA_OF_FOCUS,
				@ATTRIBUTE_048=@ORGANISATION_TEL,
				@ATTRIBUTE_049=@ORGANISATION_FAX,
				@ATTRIBUTE_050=@ORGANISATION_EMAIL,
				@ATTRIBUTE_051=@CURRICULUM_CREDITS_AVAILABLE,
				@ATTRIBUTE_053=@TRANSACTION_TYPE,
				@ATTRIBUTE_062=@TITLE,
				@ATTRIBUTE_034=@PREFERRED_MAILING_ADDRESS_NAME,
				@ATTRIBUTE_035=@PREFERRED_BILLING_ADDRESS_NAME,
				-- added Sale ID, Pay By Invoice and Pay by DD fields - Start
				@ATTRIBUTE_061 = @SALE_ID,
				@ATTRIBUTE_009 = @PAY_BY_INVOICE,
				@ATTRIBUTE_064 = @PAY_BY_DIRECT_DEBIT,
				@ATTRIBUTE_066 = @NEXT_RENEWAL_DATE,
				@ATTRIBUTE_067 = @TOTAL_OUTSTANDING,
				@ATTRIBUTE_068 = @MEMBERSHIP_STATUS,
				@ATTRIBUTE_077 = @HAS_MEMBERSHIP_TAGS,
				@ATTRIBUTE_075 = @MEMBERSHIP_TAGS,
				-- added Sale ID, Pay By Invoice and Pay by DD fields - Start
				@SRM_CLIENTS_SEQ_ID=@CLIENT_SEQ_ID,
				@DATE_CREATED=@DATECREATED,
				@CREATED_BY=@CREATEDBY,
				@DATE_MODIFIED=@DATEMODIFIED,
				@MODIFIED_BY=@MODIFIEDBY,
				@RETURN_SEQ_ID=@NEW_SEQ_ID OUTPUT,
				@ERROR=@ERROR OUTPUT,
				@ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT
			
			--SYNCH PAYMENT HISTORY

				DECLARE CUR_INNER_HIST_RECORDS CURSOR LOCAL STATIC  FOR 
					
					SELECT 
					MEMBER_LEDGER.ATTRIBUTE_005 AS PAYMENT_DATE,
					MEMBER_LEDGER.ATTRIBUTE_006 AS PAYMENT_METHOD,
					SUM(CAST(MEMBER_LEDGER.ATTRIBUTE_008 AS MONEY)) AS PAYMENT_AMOUNT,
					@USER_NAME AS [USER_NAME],
					MEMBER_LEDGER.DATE_CREATED,
					MEMBER_LEDGER.CREATED_BY,
					MEMBER_LEDGER.DATE_MODIFIED,
					MEMBER_LEDGER.MODIFIED_BY
				
					FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEMBER_LEDGER WITH (NOLOCK)
					INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEMBER_LEDGER2 WITH (NOLOCK) on MEMBER_LEDGER2.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_LEDGER_SRM_CLIENT_ENTITIES_SEQ_ID AND MEMBER_LEDGER2.seq_id = MEMBER_LEDGER.seq_id  AND MEMBER_LEDGER.SEQ_ID  IN  (SELECT CUS_ENTITY_DATA_SEQ_ID
								FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK)
								WHERE CUS_ENTITY_DATA_SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) 
														      WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_LEDGER_SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52855 AND ATTRIBUTE_DECIMAL = @CUS_ENTITY_DATA_SEQ_ID)
								AND CUS_ENTITY_DATA_SEQ_ID =MEMBER_LEDGER2.seq_id 
								AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52847
							    AND ATTRIBUTE_STRING = 'Payment'
							   ) 
					WHERE MEMBER_LEDGER.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_LEDGER_SRM_CLIENT_ENTITIES_SEQ_ID 
					AND MEMBER_LEDGER.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID
							FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK)
							WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52855
							AND ATTRIBUTE_DECIMAL = @CUS_ENTITY_DATA_SEQ_ID)
							AND MEMBER_LEDGER.DELETED <>'Y'
					GROUP BY MEMBER_LEDGER.ATTRIBUTE_005,MEMBER_LEDGER.ATTRIBUTE_006,MEMBER_LEDGER.DATE_CREATED,MEMBER_LEDGER.CREATED_BY,MEMBER_LEDGER.DATE_MODIFIED,MEMBER_LEDGER.MODIFIED_BY
						
				OPEN CUR_INNER_HIST_RECORDS
				FETCH NEXT FROM CUR_INNER_HIST_RECORDS INTO @PAYMENT_DATE, @PAYMENT_METHOD,@PAYMENT_AMOUNT, @HIS_USER_NAME, @HIST_DATECREATED, @HIST_CREATEDBY,@HIST_DATEMODIFIED, @HIST_MODIFIEDBY

				--DELETE IF ALREADY EXITS MEMBER PAYMENT HISTORY DATA
				IF (EXISTS(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56138 AND ATTRIBUTE_STRING = @HIS_USER_NAME))
				BEGIN
					DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56138 AND ATTRIBUTE_STRING = @HIS_USER_NAME)
					DELETE FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56138 AND ATTRIBUTE_STRING = @HIS_USER_NAME
				END
				
				WHILE @@FETCH_STATUS = 0
				BEGIN			
					SET @COUNTER = @COUNTER + 1
					EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
								@SRM_CLIENT_ENTITIES_SEQ_ID = @WEB_PAY_HIST_SRM_CLIENT_ENTITIES_SEQ_ID,
								@ATTRIBUTE_002=@PAYMENT_DATE,
								@ATTRIBUTE_003=@PAYMENT_METHOD,
								@ATTRIBUTE_004=@PAYMENT_AMOUNT,
								@ATTRIBUTE_006=@HIS_USER_NAME,
								@SRM_CLIENTS_SEQ_ID=@CLIENT_SEQ_ID,
								@DATE_CREATED=@HIST_DATECREATED,
								@CREATED_BY=@HIST_CREATEDBY,
								@DATE_MODIFIED=@HIST_DATEMODIFIED,
								@MODIFIED_BY=@HIST_MODIFIEDBY,
								@RETURN_SEQ_ID=@NEW_SEQ_ID OUTPUT,
								@ERROR=@ERROR OUTPUT,
								@ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT
				
				FETCH NEXT FROM CUR_INNER_HIST_RECORDS INTO @PAYMENT_DATE, @PAYMENT_METHOD,@PAYMENT_AMOUNT, @HIS_USER_NAME, @HIST_DATECREATED, @HIST_CREATEDBY,@HIST_DATEMODIFIED, @HIST_MODIFIEDBY
				END

				CLOSE CUR_INNER_HIST_RECORDS
				DEALLOCATE CUR_INNER_HIST_RECORDS
				
					
		FETCH NEXT FROM CUR_RECORDS INTO   @SURNAME, @FIRST_NAME,@MIDDLE_NAME,@DOB,@HOW_DID_YOU_HEAR_ABOUT_THE_ASSOCIATION,
										    @ADDRESS_LINE_1,@ADDRESS_LINE_2,@ADDRESS_LINE_3, @ADDRESS_LINE_4, 
											@TOWN,@POSTCODE,@COUNTY,@COUNTRY,@TEL_NUMBER,@MOBILE,@EMAIL,@FAX,
											@ORGANISATION_ID,@ORGANISATION_NAME, @JOB_TITLE,@JOB_CATEGORY,
											@ORG_ADDRESS_LINE_1,@ORG_ADDRESS_LINE_2,@ORG_ADDRESS_LINE_3,@ORG_ADDRESS_LINE_4,
											@ORGANISATION_TYPE,@PASSWORD,@ORG_ADDRESS_POSTCODE,@ORG_ADDRESS_COUNTY,
											@ORG_ADDRESS_COUNTRY,@USER_NAME,@PREFERRED_MAILING_ADDRESS_NAME,@PREFERRED_BILLING_ADDRESS_NAME, @CATEGORY_OF_MEMBERSHIP,@MEMBER_ID,@DEPARTMENTAL_MEMBER_ID,
											@AREA_OF_FOCUS, @ORGANISATION_TEL,@ORGANISATION_FAX,@ORGANISATION_EMAIL,@CURRICULUM_CREDITS_AVAILABLE, @TRANSACTION_TYPE,	 @TITLE,@DATECREATED, @CREATEDBY , 
											@DATEMODIFIED , @MODIFIEDBY, @SALE_ID, @PAY_BY_INVOICE, @PAY_BY_DIRECT_DEBIT, @NEXT_RENEWAL_DATE, @TOTAL_OUTSTANDING, @MEMBERSHIP_STATUS, @HAS_MEMBERSHIP_TAGS, @MEMBERSHIP_TAGS

		END

		CLOSE CUR_RECORDS
		DEALLOCATE CUR_RECORDS

		EXEC [DBO].[GET_POPULATE_PURCHASE_HISTORY]
			@m_CLIENT_SEQ_ID = @CLIENT_SEQ_ID,
			@m_MEMBER_CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		EXEC [DBO].[GET_POPULATE_COURSES_BOOKED_AND_ATTENDED]
			@m_CLIENT_SEQ_ID = @CLIENT_SEQ_ID,
			@m_MEMBER_CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		
	FETCH NEXT FROM CUR_MEMBERSHIP_PAID_BY INTO @CUS_ENTITY_DATA_SEQ_ID
	END

	CLOSE CUR_MEMBERSHIP_PAID_BY
	DEALLOCATE CUR_MEMBERSHIP_PAID_BY
	
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END





;





      
      
-- exec  [dbo].[GET_POPULATE_MEMBERSHIP_CATEGORY] @m_CLIENT_SEQ_ID = 17      
      
-- =============================================      
-- Author:  <Mazhar>      
-- Create date: <14/08/2013,,>      
-- Description: <Apply Area of Focus Data to Web service Area of Focus>      
-- =============================================      
CREATE PROCEDURE  [dbo].[GET_POPULATE_MEMBERSHIP_CATEGORY]       
  @m_CLIENT_SEQ_ID BIGINT,      
  @ERROR SMALLINT = NULL OUTPUT,      
  @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT      
 AS       
 BEGIN      
   
   
 SET NOCOUNT ON;      
       
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
 DECLARE @MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
 DECLARE @MEM_MASTER_CATE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
 DECLARE @MEM_RATE_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
 DECLARE @VAT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
 DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
 DECLARE @NEW_SEQ_ID BIGINT      
 DECLARE @SRM_ENTITY_NAME NVARCHAR(200)      
 DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)      
 DECLARE @CATEGORY NVARCHAR(100)      
 DECLARE @CURRICULUM_CREDIT NVARCHAR(100)      
 DECLARE @NUMBER_OF_MEMBERS_ALLOWED NVARCHAR(100)      
 DECLARE @RATE_TYPE_NAME NVARCHAR(100)      
 DECLARE @MASTER_CATEGORY_NAME NVARCHAR(100)      
 DECLARE @NET_AMOUNT NVARCHAR(100)      
 DECLARE @VAT_AMOUNT NVARCHAR(100)      
 DECLARE @GROSS_AMOUNT NVARCHAR(100)      
 DECLARE @DATEMODIFIED DATETIME      
 DECLARE @MODIFIEDBY NVARCHAR(200)      
 DECLARE @DATECREATED DATETIME      
 DECLARE @CREATEDBY NVARCHAR(200)      
 DECLARE @VAT_PERS MONEY      
 DECLARE @VAT_RATE NVARCHAR(200)      
 DECLARE @RANK NVARCHAR(200)      
 DECLARE @LONG_DESCRIPTION NVARCHAR(1000)      
 DECLARE @MEM_RATE_TYPE_SEQ_ID BigInt      
 DECLARE @DEPARTMENTAL_MEMBERSHIP NVARCHAR(1)      
 DECLARE @CATEGORY_ID NVARCHAR(100)      
      
 SET @ERROR = 1      
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_MEMBERSHIP_CATEGORY]'      
      
 SET @VAT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID = 2555      
      
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_MEMBERSHIP_CATEGORY'      
      
 SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'MEMBER_RATE'      
      
 SELECT @MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'MEMBER_CATEGORY'      
       
 SELECT @MEM_MASTER_CATE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'MEMBERSHIP_MASTER_CATEGORY'      
      
 SELECT @MEM_RATE_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'MEMBER_RATE_TYPE'      
      
 --DELETING EXISTING DATA      
 DELETE FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID      
 DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENTS_SEQ_ID=@m_CLIENT_SEQ_ID      
      
 DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR       
  SELECT DISTINCT      
   MEM_CATEGORY.ATTRIBUTE_001 CATEGORY,      
   MEM_CATEGORY.ATTRIBUTE_011 CATEGORY_ID,   
     
   (SELECT top 1 CURRI.ATTRIBUTE_017   
	FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA CURRI WITH(NOLOCK)  
    INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA RATE_TYPE WITH(NOLOCK) ON RATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_RATE_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID   
    --AND  CAST(RATE_TYPE.SEQ_ID AS NVARCHAR(50))= CURRI.ATTRIBUTE_002   
    --AND RATE_TYPE.SEQ_ID RATE_TYPE.ATTRIBUTE_009='Y'    
    AND   RATE_TYPE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID  
							 FROM [SRM-DataPivot_17].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)  
							 where SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_RATE_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID   
							 AND CUS_ENTITY_DATA_SEQ_ID=CURRI.ATTRIBUTE_002  
							 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52135  
							 AND ISNULL(ATTRIBUTE_BOOLEAN,'N')='Y'  
							)  
           
    WHERE CURRI.deleted = 'N' and CURRI.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID   
    AND CURRI.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) where SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52103 AND ISNULL(ATTRIBUTE_DECIMAL,0)=MEM_RATE.ATTRIBUTE_004)   --CURRI.ATTRIBUTE_004 = MEM_RATE.ATTRIBUTE_004   
    ) AS CURRICULUM_CREDIT_QUANTITY,   
   
   (SELECT top 1 CURRI.ATTRIBUTE_017   
    FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA CURRI WITH(NOLOCK)     
    INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA RATE_TYPE WITH(NOLOCK) ON RATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_RATE_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID   
    --AND CAST(RATE_TYPE.SEQ_ID AS NVARCHAR(50))= CURRI.ATTRIBUTE_002   
    --AND RATE_TYPE.ATTRIBUTE_014='Y'     
         AND   RATE_TYPE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID  
									 FROM [SRM-DataPivot_17].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)  
									 where SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_RATE_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID   
									 AND CUS_ENTITY_DATA_SEQ_ID=CURRI.ATTRIBUTE_002  
									 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57689  
									 AND ISNULL(ATTRIBUTE_BOOLEAN,'N')='Y'  
									)  
    WHERE CURRI.deleted = 'N' and CURRI.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID   
    AND CURRI.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) where SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52103 AND ISNULL(ATTRIBUTE_DECIMAL,0)=MEM_RATE.ATTRIBUTE_004)   --CURRI.ATTRIBUTE_004 = MEM_RATE.ATTRIBUTE_004   
    ) AS LOGINS,  
      
   '' RATE_TYPE_NAME,    
       
   MEM_MASTER_CATEGORY.ATTRIBUTE_001 AS MASTER_CATEGORY,     
   MEM_RATE.ATTRIBUTE_007 NET_AMOUNT,      
   0 VAT_AMOUNT,      
   MEM_RATE.ATTRIBUTE_007 GROSS_AMOUNT,      
   MEM_RATE.DATE_CREATED,      
   MEM_RATE.CREATED_BY,      
   MEM_RATE.DATE_MODIFIED,      
   MEM_RATE.MODIFIED_BY,      
   MEM_RATE_TYPE.ATTRIBUTE_003,      
   MEM_CATEGORY.ATTRIBUTE_009,      
   MEM_CATEGORY.ATTRIBUTE_010,      
   MEM_RATE_TYPE.SEQ_ID MEM_RATE_TYPE_SEQ_ID      
   FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM_RATE WITH(NOLOCK)  
   LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM_CATEGORY WITH(NOLOCK) ON MEM_CATEGORY.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID  
   AND MEM_CATEGORY.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID  
								 FROM [SRM-DataPivot_17].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)  
								 where SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID   
								 AND CUS_ENTITY_DATA_SEQ_ID=MEM_RATE.ATTRIBUTE_004  
								 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52086  ---ATTRIBUTE_004	WEB
								 AND ISNULL(ATTRIBUTE_BOOLEAN,'N')='Y'  
								) --MEM_RATE.ATTRIBUTE_004 AND  MEM_CATEGORY.ATTRIBUTE_004 = 'Y'      
   LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM_MASTER_CATEGORY WITH(NOLOCK)ON MEM_MASTER_CATEGORY.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_MASTER_CATE_SRM_CLIENT_ENTITIES_SEQ_ID AND MEM_MASTER_CATEGORY.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0) FROM [SRM-DataPivot_17].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID AND CUS_ENTITY_DATA_SEQ_ID=MEM_CATEGORY.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52087)  --MEM_CATEGORY.ATTRIBUTE_005  
   LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM_RATE_TYPE  WITH(NOLOCK)ON MEM_RATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_RATE_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID    AND MEM_RATE_TYPE.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0) FROM [SRM-DataPivot_17].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND CUS_ENTITY_DATA_SEQ_ID=MEM_RATE.SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52101) --MEM_RATE.ATTRIBUTE_002  
     
   WHERE MEM_RATE.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID 
   
   --ATTRIBUTE_004	MEMBER_CATEGORY SEQ_ID >0  
   AND MEM_RATE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) where SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52103 AND ISNULL(ATTRIBUTE_DECIMAL,0)<>0 ) --ISNULL(MEM_RATE.ATTRIBUTE_004,'0')<>'0'   
   
   AND ISNULL(MEM_RATE.DELETED,'N')<>'Y'  
   
   --ATTRIBUTE_008	MEMBERSHIP_SUBSCRIPTION='Y'
   AND MEM_RATE_TYPE.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) where SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_RATE_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =52134 AND ISNULL(ATTRIBUTE_BOOLEAN,'N')='Y' ) --ATTRIBUTE_008='Y'    
   
   --ATTRIBUTE_001	DESCRIPTION<>''
   AND MEM_CATEGORY.SEQ_ID  IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) where SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID      AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =52073 AND ISNULL(ATTRIBUTE_STRING,'')<>'') --ISNULL(MEM_CATEGORY.ATTRIBUTE_001, '') <> ''  
     
   UNION      
         
   SELECT DISTINCT      
   '' CATEGORY,      
   '' CATEGORY_ID,      
   0 AS CURRICULUM_CREDIT_QUANTITY,      
   0 AS LOGINS,      
      
   MEM_RATE.ATTRIBUTE_003  RATE_TYPE_NAME,      
   MEM_MASTER_CATEGORY.ATTRIBUTE_001 AS MASTER_CATEGORY,      
   MEM_RATE.ATTRIBUTE_007 NET_AMOUNT,      
   0 VAT_AMOUNT,      
   MEM_RATE.ATTRIBUTE_007 GROSS_AMOUNT,      
   MEM_RATE.DATE_CREATED,      
   MEM_RATE.CREATED_BY,      
   MEM_RATE.DATE_MODIFIED,      
   MEM_RATE.MODIFIED_BY,      
   NULL,      
   MEM_CATEGORY.ATTRIBUTE_009,      
   MEM_CATEGORY.ATTRIBUTE_010,      
   MEM_RATE_TYPE.SEQ_ID MEM_RATE_TYPE_SEQ_ID      
   FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM_RATE      
   LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM_CATEGORY  ON MEM_CATEGORY.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID     AND MEM_CATEGORY.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0)   FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID   AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52103 AND CUS_ENTITY_DATA_SEQ_ID =MEM_RATE.SEQ_ID) --= MEM_RATE.ATTRIBUTE_004       
   LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM_MASTER_CATEGORY ON MEM_MASTER_CATEGORY.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_MASTER_CATE_SRM_CLIENT_ENTITIES_SEQ_ID AND MEM_MASTER_CATEGORY.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0) FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52087 AND CUS_ENTITY_DATA_SEQ_ID =MEM_CATEGORY.SEQ_ID) --= MEM_CATEGORY.ATTRIBUTE_005   
 
   LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM_RATE_TYPE  ON MEM_RATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_RATE_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID   AND MEM_RATE_TYPE.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0)   FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID   AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52101 AND CUS_ENTITY_DATA_SEQ_ID =MEM_RATE.SEQ_ID) --= MEM_RATE.ATTRIBUTE_002    
   WHERE MEM_RATE.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID   
   AND ISNULL(MEM_RATE.DELETED,'N')<>'Y'
   AND MEM_RATE.SEQ_ID IN(SELECT TEMP4.CUS_ENTITY_DATA_SEQ_ID
						  FROM (SELECT TEMP2.CUS_ENTITY_DATA_SEQ_ID
								FROM (SELECT CUS_ENTITY_DATA_SEQ_ID
									  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)
									  WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID  
									  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=58053 --WEB FLAG IS TICKED  
								      AND ISNULL(ATTRIBUTE_BOOLEAN,'N')='Y'
								      )TEMP1  
							   INNER JOIN [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH(NOLOCK) ON SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID  
							   AND TEMP2.CUS_ENTITY_DATA_SEQ_ID = TEMP1.CUS_ENTITY_DATA_SEQ_ID  
							   AND TEMP2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52103 --MEMBER CATEGORY = 0   
							   AND ISNULL(ATTRIBUTE_DECIMAL,0)=0  
							)TEMP3  
						INNER JOIN [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES TEMP4 WITH(NOLOCK) ON SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID  
						AND TEMP4.CUS_ENTITY_DATA_SEQ_ID = TEMP3.CUS_ENTITY_DATA_SEQ_ID --RATE_TYPE_NAME<>''  
						AND TEMP4.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=52102  
						AND ISNULL(ATTRIBUTE_STRING,'')<>''  
					   )  
   --MEM_RATE.ATTRIBUTE_018 = 'Y'   
   --AND ISNULL(MEM_RATE.ATTRIBUTE_004,'0')='0'   
   --AND ISNULL(MEM_RATE.ATTRIBUTE_003, '') <> ''      
      
 OPEN CUR_RECORDS      
 FETCH NEXT FROM CUR_RECORDS INTO  @CATEGORY, @CATEGORY_ID, @CURRICULUM_CREDIT, @NUMBER_OF_MEMBERS_ALLOWED, @RATE_TYPE_NAME, @MASTER_CATEGORY_NAME,@NET_AMOUNT,@VAT_AMOUNT, @GROSS_AMOUNT,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY, @VAT_RATE, @RANK, @LONG_DESCRIPTION, @MEM_RATE_TYPE_SEQ_ID      
 WHILE @@FETCH_STATUS = 0      
 BEGIN      
  IF CAST(ISNULL(@NUMBER_OF_MEMBERS_ALLOWED, '0') AS BIGINT) > 1      
  BEGIN      
   SET @DEPARTMENTAL_MEMBERSHIP = 'Y'      
  END      
  ELSE      
  BEGIN      
   SET @DEPARTMENTAL_MEMBERSHIP = 'N'      
  END      
      
  --Get VAT amount from Breakdown      
  EXEC GET_VAT_AMOUNT_USING_BREAKDOWN      
   @m_MEMBER_RATE_TYPE_SEQ_ID = @MEM_RATE_TYPE_SEQ_ID,      
   @m_AMOUNT = @NET_AMOUNT,      
   @m_CLIENT_SEQ_ID = @m_CLIENT_SEQ_ID,      
   @m_VAT_AMOUNT = @VAT_AMOUNT OUTPUT,      
   @m_NET_AMOUNT = @NET_AMOUNT OUTPUT,      
   @ERROR = @ERROR OUTPUT,      
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT      
         
  SET @GROSS_AMOUNT = CAST(@VAT_AMOUNT AS MONEY) + CAST(@NET_AMOUNT AS MONEY)      
        
  PRINT @GROSS_AMOUNT       
  PRINT @VAT_AMOUNT       
  PRINT @NET_AMOUNT      
        
  --IF @VAT_RATE IS NOT NULL      
  --BEGIN      
  -- SELECT @VAT_PERS = CAST(ATTRIBUTE_006 AS MONEY) FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SEQ_ID = @VAT_RATE AND SRM_CLIENT_ENTITIES_SEQ_ID = @VAT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID      
  -- SET @VAT_AMOUNT = CAST(@NET_AMOUNT AS MONEY) * @VAT_PERS/100.00      
  -- SET @GROSS_AMOUNT = CAST(@VAT_AMOUNT AS MONEY) + CAST(@NET_AMOUNT AS MONEY)       
  --END      
  --ELSE      
  --BEGIN      
  -- SET @VAT_AMOUNT = '0.00'      
  --END      
      
  EXEC  [DBO].[GET_INSERT_CUS_ENTITY_DATA]      
   @SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID,      
   @ATTRIBUTE_001=@CATEGORY,      
   @ATTRIBUTE_002=@CURRICULUM_CREDIT,      
   @ATTRIBUTE_003=@NET_AMOUNT,      
   @ATTRIBUTE_004=@VAT_AMOUNT,      
   @ATTRIBUTE_005=@GROSS_AMOUNT,      
   @ATTRIBUTE_006=@DEPARTMENTAL_MEMBERSHIP,      
   @ATTRIBUTE_007=@NUMBER_OF_MEMBERS_ALLOWED,      
   @ATTRIBUTE_008=@MASTER_CATEGORY_NAME,      
   @ATTRIBUTE_009=@RATE_TYPE_NAME,      
   @ATTRIBUTE_010=@RANK,      
   @ATTRIBUTE_011=@LONG_DESCRIPTION,      
   @ATTRIBUTE_012 = @CATEGORY_ID,      
   @SRM_CLIENTS_SEQ_ID=@M_CLIENT_SEQ_ID,      
   @DATE_CREATED=@DATECREATED,      
   @CREATED_BY=@CREATEDBY,      
   @DATE_MODIFIED=@DATEMODIFIED,      
   @MODIFIED_BY=@MODIFIEDBY,      
   @RETURN_SEQ_ID=@NEW_SEQ_ID OUTPUT,      
   @ERROR=@ERROR OUTPUT,      
   @ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT      
          
 FETCH NEXT FROM CUR_RECORDS INTO  @CATEGORY, @CATEGORY_ID, @CURRICULUM_CREDIT, @NUMBER_OF_MEMBERS_ALLOWED, @RATE_TYPE_NAME, @MASTER_CATEGORY_NAME,@NET_AMOUNT,@VAT_AMOUNT, @GROSS_AMOUNT,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY, @VAT_RATE, @RANK, @LONG_DESCRIPTION, @MEM_RATE_TYPE_SEQ_ID      
 END      
      
 CLOSE CUR_RECORDS      
 DEALLOCATE CUR_RECORDS      
       
 SET @ERROR = 0      
 SET @ERROR_DESCRIPTION = ''      
END      



;





--EXEC [dbo].[GET_POPULATE_MEMBERSHIP_CATEGORY_DETAIL] @m_CLIENT_SEQ_ID = 17      
      
-- =============================================      
-- Author:  <Mazhar>      
-- Create date: <14/08/2013,,>      
-- Description: <Apply Area of Focus Data to Web service Area of Focus>      
-- =============================================      
CREATE PROCEDURE  [dbo].[GET_POPULATE_MEMBERSHIP_CATEGORY_DETAIL]       
  @m_CLIENT_SEQ_ID BIGINT,      
  @ERROR SMALLINT = NULL OUTPUT,      
  @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT      
 AS       
 BEGIN      
          
      
 SET NOCOUNT ON;      
       
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
 DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
 DECLARE @MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT      
 DECLARE @NEW_SEQ_ID BIGINT      
 DECLARE @SRM_ENTITY_NAME NVARCHAR(200)      
 DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)      
 DECLARE @DESCRIPTION NVARCHAR(500)      
 DECLARE @RATE_TYPE_NAME NVARCHAR(500)      
 DECLARE @DATEMODIFIED DATETIME      
 DECLARE @MODIFIEDBY NVARCHAR(200)      
 DECLARE @DATECREATED DATETIME      
 DECLARE @CREATEDBY NVARCHAR(200)      
 DECLARE @RANK NVARCHAR(200)      
 DECLARE @LONG_DESCRIPTION NVARCHAR(1000)      
      
      
 SET @ERROR = 1      
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_MEMBERSHIP_CATEGORY_DETAIL]'      
      
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_MEMBERSHIP_CATEGORY_DETAIL'      
      
 SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'MEMBER_RATE'      
      
 SELECT @MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID       
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D      
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID      
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID      
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'MEMBER_CATEGORY'      
      
 --DELETING EXISTING DATA      
 DELETE FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID      
 DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENTS_SEQ_ID=@m_CLIENT_SEQ_ID      
      
 DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR       
   SELECT DISTINCT      
   MEM_CATEGORY.ATTRIBUTE_001 CATEGORY,      
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_001 RATE_TYPE_NAME,      
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DATE_CREATED,      
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.CREATED_BY,      
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DATE_MODIFIED,      
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.MODIFIED_BY,      
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_019,      
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_020      
FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH(NOLOCK)  
LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM_CATEGORY WITH(NOLOCK) ON  MEM_CATEGORY.SRM_CLIENT_ENTITIES_SEQ_ID=@MEM_CATE_SRM_CLIENT_ENTITIES_SEQ_ID    
AND MEM_CATEGORY.SEQ_ID IN(SELECT ISNULL(ATTRIBUTE_DECIMAL,0) FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52103 AND CUS_ENTITY_DATA_SEQ_ID =CUS_ENTITY_DATA.SEQ_ID) --=CUS_ENTITY_DATA.ATTRIBUTE_004    
WHERE [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID   
AND ISNULL([SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DELETED,'N')<>'Y'  
AND [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.SEQ_ID IN (SELECT TEMP2.CUS_ENTITY_DATA_SEQ_ID   
														  FROM (SELECT CUS_ENTITY_DATA_SEQ_ID   
															FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)   
															WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID   
															AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 52103   
															AND ISNULL(ATTRIBUTE_DECIMAL,0)<>0 --.ATTRIBUTE_004,'0')<>'0'   
															 )TEMP1  
														   INNER JOIN [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH(NOLOCK)   
														   ON TEMP2.SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID  
															 AND TEMP2.CUS_ENTITY_DATA_SEQ_ID=TEMP1.CUS_ENTITY_DATA_SEQ_ID  
															 AND TEMP2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 58053   
															 AND ISNULL(TEMP2.ATTRIBUTE_BOOLEAN,'N')='Y' --AND ATTRIBUTE_018 = 'Y'  
														  )    
                    
ORDER BY MEM_CATEGORY.ATTRIBUTE_001,CUS_ENTITY_DATA.ATTRIBUTE_001  
         
 OPEN CUR_RECORDS      
 FETCH NEXT FROM CUR_RECORDS INTO @DESCRIPTION ,@RATE_TYPE_NAME,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY, @RANK, @LONG_DESCRIPTION      
 WHILE @@FETCH_STATUS = 0      
 BEGIN      
  EXEC  [DBO].[GET_INSERT_CUS_ENTITY_DATA]      
  @SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID,      
  @ATTRIBUTE_001=@DESCRIPTION,      
  @ATTRIBUTE_005=@RATE_TYPE_NAME,      
  @ATTRIBUTE_006=@RANK,      
  @ATTRIBUTE_007=@LONG_DESCRIPTION,      
  @SRM_CLIENTS_SEQ_ID=@M_CLIENT_SEQ_ID,      
  @DATE_CREATED=@DATECREATED,      
  @CREATED_BY=@CREATEDBY,      
  @DATE_MODIFIED=@DATEMODIFIED,      
  @MODIFIED_BY=@MODIFIEDBY,      
  @RETURN_SEQ_ID=@NEW_SEQ_ID OUTPUT,      
  @ERROR=@ERROR OUTPUT,      
  @ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT      
          
 FETCH NEXT FROM CUR_RECORDS INTO @DESCRIPTION,@RATE_TYPE_NAME,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY, @RANK, @LONG_DESCRIPTION      
 END      
      
 CLOSE CUR_RECORDS      
 DEALLOCATE CUR_RECORDS      
       
 SET @ERROR = 0      
 SET @ERROR_DESCRIPTION = ''      
END      



;





    -- =============================================    
-- Author:  <Mazhar>    
-- Create date: <14/08/2013,,>    
-- Description: <Apply Area of Focus Data to Web service Area of Focus>    
-- =============================================    
CREATE PROCEDURE  [dbo].[GET_POPULATE_MEMBERSHIP_MASTER_CATEGORY]     
  @m_CLIENT_SEQ_ID BIGINT,    
  @ERROR SMALLINT = NULL OUTPUT,    
  @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT    
 AS     
 BEGIN    
      
 SET NOCOUNT ON;    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT    
 DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT    
 DECLARE @NEW_SEQ_ID BIGINT    
 DECLARE @SRM_ENTITY_NAME NVARCHAR(200)    
 DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)    
 DECLARE @DESCRIPTION NVARCHAR(500)    
 DECLARE @DATEMODIFIED DATETIME    
 DECLARE @MODIFIEDBY NVARCHAR(200)    
 DECLARE @DATECREATED DATETIME    
 DECLARE @CREATEDBY NVARCHAR(200)    
    
 SET @ERROR = 1    
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_MEMBERSHIP_MASTER_CATEGORY]'    
    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME     
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D    
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID    
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID    
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_MEMBERSHIP_MASTER_CATEGORY'    
    
 SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME     
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D    
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID    
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID    
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'MEMBERSHIP_MASTER_CATEGORY'    
    
 --DELETING EXISTING DATA    
 DELETE FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID    
 DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENTS_SEQ_ID=@m_CLIENT_SEQ_ID    
    
    
 DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR     
   SELECT DISTINCT    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_001 DISCRIPTION,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DATE_CREATED,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.CREATED_BY,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DATE_MODIFIED,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.MODIFIED_BY    
   FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA     
   WHERE [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID 
   AND ISNULL([SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DELETED,'N')<>'Y'    
   AND [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56994 AND ISNULL(ATTRIBUTE_BOOLEAN,'N')='Y')  --ATTRIBUTE_002 = 'Y'
   AND [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56995 AND ISNULL(ATTRIBUTE_BOOLEAN,'N')='Y')  --ATTRIBUTE_003 = 'Y'
   
 OPEN CUR_RECORDS    
 FETCH NEXT FROM CUR_RECORDS INTO @DESCRIPTION ,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY     
 WHILE @@FETCH_STATUS = 0    
 BEGIN    
  EXEC  [dbo].[GET_INSERT_CUS_ENTITY_DATA]    
  @SRM_CLIENT_ENTITIES_SEQ_ID=@srm_client_entities_seq_id,    
  @ATTRIBUTE_001=@description,    
  @SRM_CLIENTS_SEQ_ID=@m_CLIENT_SEQ_ID,    
  @DATE_CREATED=@DATECREATED,    
  @CREATED_BY=@CREATEDBY,    
  @DATE_MODIFIED=@DateModified,    
  @MODIFIED_BY=@ModifiedBy,    
  @RETURN_SEQ_ID=@new_seq_id output,    
  @ERROR=@ERROR OUTPUT,    
  @ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT    
        
 FETCH NEXT FROM CUR_RECORDS INTO @DESCRIPTION,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY     
 END    
    
 CLOSE CUR_RECORDS    
 DEALLOCATE CUR_RECORDS    
     
 SET @ERROR = 0    
 SET @ERROR_DESCRIPTION = ''    
END    



;






-- =============================================
-- Author:  <Mazhar>
-- Create date: <14/08/2013,,>
-- Description: <Apply Area of Focus Data to Web service Area of Focus>
-- =============================================
CREATE PROCEDURE [dbo].[GET_POPULATE_ORGANISATION] 
	 @m_CLIENT_SEQ_ID BIGINT,
	 @m_CUS_ENTITY_DATA_SEQ_ID BIGINT,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
 AS 
 BEGIN
  
	SET NOCOUNT ON;
	
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @NEW_SEQ_ID BIGINT
	DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)
	
	DECLARE @ACCOUNT_NAME NVARCHAR(100)
	DECLARE @ADDRESS_LINE_1 NVARCHAR(100)
	DECLARE @ADDRESS_LINE_2 NVARCHAR(100)
	DECLARE @ADDRESS_LINE_3 NVARCHAR(100)
	DECLARE @POSTCODE NVARCHAR(100)
	DECLARE @COUNTY NVARCHAR(100)
	DECLARE @COUNTRY NVARCHAR(100)
	 
	DECLARE @DATEMODIFIED DATETIME
	DECLARE @MODIFIEDBY NVARCHAR(200)
	DECLARE @DATECREATED DATETIME
	DECLARE @CREATEDBY NVARCHAR(200)

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_ORGANISATION]'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_ORGANISATION'

	SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'ACCOUNT'

	
	
	DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR 
				
			SELECT 
			ACCOUNT.ATTRIBUTE_001 AS ACCOUNT_NAME,
			ACCOUNT.ATTRIBUTE_024 AS ADDRESS_LINE_1,
			ACCOUNT.ATTRIBUTE_025 AS ADDRESS_LINE_2,
			ACCOUNT.ATTRIBUTE_026 AS ADDRESS_LINE_3,
			ACCOUNT.ATTRIBUTE_028 AS POSTCODE,
			ACCOUNT.ATTRIBUTE_030 AS COUNTY,
			ACCOUNT.ATTRIBUTE_032 AS COUNTRY,
			ACCOUNT.DATE_CREATED,
			ACCOUNT.CREATED_BY,
			ACCOUNT.DATE_MODIFIED,
			ACCOUNT.MODIFIED_BY
			
			FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA ACCOUNT
			
			WHERE ACCOUNT.SEQ_ID=@m_CUS_ENTITY_DATA_SEQ_ID AND ACCOUNT.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID AND ISNULL(ACCOUNT.DELETED,'N')<>'Y'
		
			
	OPEN CUR_RECORDS
	
	FETCH NEXT FROM CUR_RECORDS INTO  	 @ACCOUNT_NAME,@ADDRESS_LINE_1,@ADDRESS_LINE_2,@ADDRESS_LINE_3,@POSTCODE,@COUNTY,@COUNTRY,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY 
	WHILE @@FETCH_STATUS = 0
	BEGIN
	
	--DELETE IF ALREADY EXITS 
		IF (EXISTS(SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_001=@ACCOUNT_NAME AND SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID))
		BEGIN
			DELETE FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE CUS_ENTITY_DATA_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_001=@ACCOUNT_NAME  AND SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID)
			DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_001=@ACCOUNT_NAME  AND SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID
		END
		
		EXEC  [DBO].[GET_INSERT_CUS_ENTITY_DATA]
		@SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID,
		@ATTRIBUTE_001=@ACCOUNT_NAME,
		@ATTRIBUTE_002=@ADDRESS_LINE_1,
		@ATTRIBUTE_003=@ADDRESS_LINE_2,
		@ATTRIBUTE_004=@ADDRESS_LINE_3,
		@ATTRIBUTE_007=@POSTCODE,
		@ATTRIBUTE_008=@COUNTY,
		@ATTRIBUTE_009=@COUNTRY,
		@SRM_CLIENTS_SEQ_ID=@M_CLIENT_SEQ_ID,
		@DATE_CREATED=@DATECREATED,
		@CREATED_BY=@CREATEDBY,
		@DATE_MODIFIED=@DATEMODIFIED,
		@MODIFIED_BY=@MODIFIEDBY,
		@RETURN_SEQ_ID=@NEW_SEQ_ID OUTPUT,
		@ERROR=@ERROR OUTPUT,
		@ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT
				
	FETCH NEXT FROM CUR_RECORDS INTO  	 @ACCOUNT_NAME,@ADDRESS_LINE_1,@ADDRESS_LINE_2,@ADDRESS_LINE_3,@POSTCODE,@COUNTY,@COUNTRY,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY 
	END

	CLOSE CUR_RECORDS
	DEALLOCATE CUR_RECORDS
	
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END



;





-- =============================================    
-- Author:  <Mazhar>    
-- Create date: <14/08/2013,,>    
-- Description: <Apply Area of Focus Data to Web service Area of Focus>    
-- =============================================    
CREATE PROCEDURE [dbo].[GET_POPULATE_ORGANISATION_TYPE]     
  @m_CLIENT_SEQ_ID BIGINT,    
  @ERROR SMALLINT = NULL OUTPUT,    
  @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT    
 AS     
 BEGIN    
      
 SET NOCOUNT ON;    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT    
 DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT    
 DECLARE @NEW_SEQ_ID BIGINT    
 DECLARE @SRM_ENTITY_NAME NVARCHAR(200)    
 DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)    
 DECLARE @DESCRIPTION NVARCHAR(500)    
 DECLARE @DATEMODIFIED DATETIME    
 DECLARE @MODIFIEDBY NVARCHAR(200)    
 DECLARE @DATECREATED DATETIME    
 DECLARE @CREATEDBY NVARCHAR(200)    
    
 SET @ERROR = 1    
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_ORGANISATION_TYPE]'    
    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME     
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D    
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID    
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID    
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_ORGANISATION_TYPE'    
    
 SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME     
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D    
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID    
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID    
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'ACCOUNT_TYPE'    
    
    
 --DELETING EXISTING DATA    
 DELETE FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID    
 DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENTS_SEQ_ID=@m_CLIENT_SEQ_ID    
    
 


 DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR     
   SELECT DISTINCT    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_001 DISCRIPTION,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DATE_CREATED,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.CREATED_BY,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DATE_MODIFIED,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.MODIFIED_BY    
   FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
   WHERE [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID 
   AND ISNULL([SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DELETED,'N')<>'Y'   
   AND [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.SEQ_ID IN(SELECT TEMP2.CUS_ENTITY_DATA_SEQ_ID   
                FROM (SELECT CUS_ENTITY_DATA_SEQ_ID   
                  FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)   
                  WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID   
                  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 51890   
                  AND ISNULL(ATTRIBUTE_BOOLEAN,'N') = 'Y' --[SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_002 = 'Y' --ACTIVE   
                 ) TEMP1  
                 INNER JOIN [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH(NOLOCK)  
                 ON TEMP2.CUS_ENTITY_DATA_SEQ_ID = TEMP1.CUS_ENTITY_DATA_SEQ_ID  
                 WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID  
                 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 51891   
                 AND ISNULL(ATTRIBUTE_BOOLEAN,'N') = 'Y' --[SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_003 = 'Y' --AVAILABLE ON PORTAL  
               ) 
   --AND [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_002 = 'Y'    
   --AND [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_003 = 'Y'    
     
     
 OPEN CUR_RECORDS    
 FETCH NEXT FROM CUR_RECORDS INTO @DESCRIPTION ,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY     
 WHILE @@FETCH_STATUS = 0    
 BEGIN    
  EXEC  [DBO].[GET_INSERT_CUS_ENTITY_DATA]    
   @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,    
   @ATTRIBUTE_001    = @DESCRIPTION,    
   @SRM_CLIENTS_SEQ_ID   = @M_CLIENT_SEQ_ID,    
   @DATE_CREATED    = @DATECREATED,    
   @CREATED_BY     = @CREATEDBY,    
   @DATE_MODIFIED    = @DATEMODIFIED,    
   @MODIFIED_BY    = @MODIFIEDBY,    
   @RETURN_SEQ_ID    = @NEW_SEQ_ID OUTPUT,    
   @ERROR      = @ERROR OUTPUT,    
   @ERROR_DESCRIPTION   = @ERROR_DESCRIPTION OUTPUT    
    
 FETCH NEXT FROM CUR_RECORDS INTO @DESCRIPTION,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY    
 END    
    
 CLOSE CUR_RECORDS    
 DEALLOCATE CUR_RECORDS    
     
 SET @ERROR = 0    
 SET @ERROR_DESCRIPTION = ''    
END 



;






