-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <15/03/2015,,>
-- Description:	<Delete Data from Pivot Single Entity>
-- =============================================
CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_DELETE_DATA_FROM_PIVOT_SINGLE_ENTITY]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_PIVOT_TABLE_DELETE_DATA_FROM_PIVOT_SINGLE_ENTITY]'
	
		
	WHILE EXISTS(SELECT TOP 1 SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE DELETED <> 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID)
	BEGIN
		UPDATE [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES
			SET DELETED = 'Y'
		WHERE SEQ_ID IN (SELECT TOP 10000 SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES 
					WHERE DELETED <> 'Y' 
					AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
					AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID)
	END
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''

	EXEC [dbo].[GET_POPULATE_PIVOT_TABLE_DELETE_MARKED_RECORDS_FROM_PIVOT]
	-- Add the parameters for the stored procedure here
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

END


;




