-- =============================================
-- Author:		<Rauf Gill>
-- ALTER date: <25/03/2016,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_DELETE_MARKED_RECORDS]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@CUS_ENTITY_DATA_SEQ_ID BIGINT = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [SRM-CustomEntities_162].[dbo].[GET_POPULATE_PIVOT_TABLE_DELETE_MARKED_RECORDS]'
	DECLARE @CUS_PIVOT_NON_UNIQUE_INDEXES_SEQ_ID BIGINT
	DECLARE @COUNTER BIGINT
	DECLARE @TOTAL_RECORDS BIGINT
	DECLARE @FIRST_TIME CHAR(1)

	SET @FIRST_TIME = 'Y'

	IF  @SRM_CLIENTS_SEQ_ID IS NULL AND @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL 
	BEGIN
		PRINT 'CLIENT ID OR ENTITY ID IS MISSING. CANNOT PROCEED.'
		RETURN
	END
	
	IF @CUS_ENTITY_DATA_SEQ_ID IS NOT NULL -- SINGLE RECORD
	BEGIN
		SELECT @TOTAL_RECORDS = COUNT(*) FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE DELETED = 'Y' AND CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID
		PRINT 'Total Records for Deletion : ' + cast(@TOTAL_RECORDS as nvarchar(20))
		WHILE (@FIRST_TIME = 'Y' OR @@ROWCOUNT > 0)
		BEGIN
			SET @FIRST_TIME = 'N'
			DELETE FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES
			WHERE SEQ_ID IN (SELECT TOP 10000 SEQ_ID FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES  WITH (NOLOCK)
						WHERE DELETED = 'Y' 
						AND CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID)
		END
		RETURN
	END
	ELSE IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL -- COMPLETE CLIENT
	BEGIN
		SELECT @TOTAL_RECORDS = COUNT(*) FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE DELETED = 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		PRINT 'Total Records for Deletion : ' + cast(@TOTAL_RECORDS as nvarchar(20))
		WHILE (@FIRST_TIME = 'Y' OR @@ROWCOUNT > 0)
		BEGIN
			SET @FIRST_TIME = 'N'
			DELETE FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES
			WHERE SEQ_ID IN (SELECT TOP 10000 SEQ_ID FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES  WITH (NOLOCK)
						WHERE DELETED = 'Y' 
						AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)
		END
		RETURN
	END
	ELSE -- SINGLE ENTITY
	BEGIN
		SELECT @TOTAL_RECORDS = COUNT(*) FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE DELETED = 'Y' AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
		PRINT 'Total Records for Deletion : ' + cast(@TOTAL_RECORDS as nvarchar(20))
		WHILE (@FIRST_TIME = 'Y' OR @@ROWCOUNT > 0)
		BEGIN
			SET @FIRST_TIME = 'N'
			DELETE FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES
			WHERE SEQ_ID IN (SELECT TOP 10000 SEQ_ID FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES  WITH (NOLOCK)
						WHERE DELETED = 'Y' 
						AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID)
		END
		RETURN
	END
	
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END








;




CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_DELETE_MARKED_RECORDS_FROM_PIVOT]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@CUS_ENTITY_DATA_SEQ_ID BIGINT = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_PIVOT_TABLE_DELETE_MARKED_RECORDS_FROM_PIVOT]'
	DECLARE @CUS_PIVOT_NON_UNIQUE_INDEXES_SEQ_ID BIGINT
	DECLARE @COUNTER BIGINT
	DECLARE @TOTAL_RECORDS BIGINT
	DECLARE @FIRST_TIME CHAR(1)

	SET @FIRST_TIME = 'Y'

	IF  @SRM_CLIENTS_SEQ_ID IS NULL AND @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL 
	BEGIN
		PRINT 'CLIENT ID OR ENTITY ID IS MISSING. CANNOT PROCEED.'
		RETURN
	END
	
	IF @CUS_ENTITY_DATA_SEQ_ID IS NOT NULL
		SELECT @TOTAL_RECORDS = COUNT(*) FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE DELETED = 'Y' AND CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID
	ELSE IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL
	BEGIN
		--WHILE EXISTS(SELECT TOP 1 SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES  WITH (NOLOCK) WHERE DELETED = 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)
		WHILE (@FIRST_TIME = 'Y' OR @@ROWCOUNT > 0)
		BEGIN
			SET @FIRST_TIME = 'N'
			DELETE FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES
			WHERE SEQ_ID IN (SELECT TOP 10000 SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES  WITH (NOLOCK)
						WHERE DELETED = 'Y' 
						AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)
		END
		--SELECT @TOTAL_RECORDS = COUNT(*) FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE DELETED = 'Y' AND SRM_CLIENTS_SEQ_ID  = @SRM_CLIENTS_SEQ_ID		
		RETURN
	END
	ELSE
	BEGIN
		--WHILE EXISTS(SELECT TOP 1 SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES  WITH (NOLOCK) WHERE DELETED = 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID)
		WHILE (@FIRST_TIME = 'Y' OR @@ROWCOUNT > 0)
		BEGIN
			SET @FIRST_TIME = 'N'
			DELETE FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES
			WHERE SEQ_ID IN (SELECT TOP 10000 SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES  WITH (NOLOCK)
						WHERE DELETED = 'Y' 
						AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
						AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID)
		END
		--SELECT @TOTAL_RECORDS = COUNT(*) FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE DELETED = 'Y' AND SRM_CLIENTS_SEQ_ID  = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
		RETURN
	END

	IF @CUS_ENTITY_DATA_SEQ_ID IS NOT NULL
		DECLARE CUR_DATA_PIVOT CURSOR LOCAL STATIC FOR
			SELECT SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE DELETED = 'Y' AND CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID
	ELSE IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL
		DECLARE CUR_DATA_PIVOT CURSOR LOCAL STATIC FOR
			SELECT SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE DELETED = 'Y' AND SRM_CLIENTS_SEQ_ID  = @SRM_CLIENTS_SEQ_ID
	ELSE
		DECLARE CUR_DATA_PIVOT CURSOR LOCAL STATIC FOR
			SELECT SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE DELETED = 'Y' AND SRM_CLIENTS_SEQ_ID  = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID


	OPEN CUR_DATA_PIVOT 

	FETCH NEXT FROM CUR_DATA_PIVOT INTO @CUS_PIVOT_NON_UNIQUE_INDEXES_SEQ_ID

	SET @COUNTER = 0
	PRINT 'Total Records for Processing : ' + cast(@TOTAL_RECORDS as nvarchar(20))
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @COUNTER = @COUNTER + 1
		DELETE FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SEQ_ID = @CUS_PIVOT_NON_UNIQUE_INDEXES_SEQ_ID
		FETCH NEXT FROM CUR_DATA_PIVOT INTO @CUS_PIVOT_NON_UNIQUE_INDEXES_SEQ_ID

		IF @COUNTER % 1000 = 0 
			PRINT 'Deleting Records from Pivot. Processing ' +  cast(@COUNTER as nvarchar(20)) + ' of total ' + cast(@TOTAL_RECORDS as nvarchar(20))
	END

	CLOSE CUR_DATA_PIVOT 
	DEALLOCATE CUR_DATA_PIVOT

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END


;






