-- =============================================
-- Author:		<Rauf Gill>
-- ALTER date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_DO_NOT_DELETE_EXISTING_RECORDS]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@CUS_ENTITY_DATA_SEQ_ID BIGINT = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_PIVOT_TABLE]'

	SET ANSI_NULLS ON
	SET QUOTED_IDENTIFIER ON

	DECLARE @DATA_TYPE_ID smallint
	DECLARE @DATA_VALUE NVARCHAR(MAX)
	DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT
	DECLARE @ATTRIBUTE_SYSTEM_NAME NVARCHAR(100)

	DECLARE @STRSQL NVARCHAR(4000)
	DECLARE @sql NVARCHAR(MAX)

	DECLARE @DATA_TABLE TABLE
	(
		SEQ_ID BIGINT,
		DATA_VALUE NVARCHAR(MAX)
	)

	IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL
	BEGIN
		SELECT @SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID
	END

	DECLARE CUR_ATTRIBUTES CURSOR LOCAL STATIC
	FOR 
		SELECT SRM_CLIENT_ENTITIES.SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES.SEQ_ID, SRM_ENTITY_ATTRIBUTES.SYSTEM_NAME, SRM_ATTRIBUTE_DATA_TYPES.DATA_TYPE_ID
		FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITIES WITH (NOLOCK)
		INNER JOIN [SRM-Framework_New].DBO.SRM_ENTITIES WITH (NOLOCK) ON SRM_CLIENT_ENTITIES.SRM_ENTITIES_SEQ_ID = SRM_ENTITIES.SEQ_ID
		INNER JOIN [SRM-Framework_New].DBO.SRM_ENTITY_ATTRIBUTES WITH (NOLOCK) ON SRM_ENTITIES.SEQ_ID = SRM_ENTITY_ATTRIBUTES.SRM_ENTITIES_SEQ_ID
		INNER JOIN [SRM-Framework_New].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES WITH (NOLOCK) ON SRM_ENTITY_ATTRIBUTES.SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_ENTITY_ATTRIBUTES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES.SEQ_ID AND ISNULL(SRM_CLIENT_ENTITY_ATTRIBUTES.DELETED,'N')='N'
		INNER JOIN [SRM-Framework_New].DBO.SRM_ATTRIBUTE_DATA_TYPES WITH (NOLOCK) ON SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = SRM_ATTRIBUTE_DATA_TYPES.SEQ_ID 
		WHERE SRM_ENTITIES.DATABASE_SYSTEM_NAME like 'SRM-CustomEntities%'
		AND ISNULL(SRM_CLIENT_ENTITY_ATTRIBUTES.MAX_LENGTH, 0) <= 255
		AND SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		and SRM_CLIENT_ENTITIES.SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
		ORDER BY SRM_ENTITIES.SEQ_ID, SRM_ENTITY_ATTRIBUTES.SYSTEM_NAME

	OPEN CUR_ATTRIBUTES

	FETCH NEXT FROM CUR_ATTRIBUTES INTO @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @ATTRIBUTE_SYSTEM_NAME, @DATA_TYPE_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT @ATTRIBUTE_SYSTEM_NAME  
		DELETE FROM @DATA_TABLE

		IF @CUS_ENTITY_DATA_SEQ_ID IS NOT NULL
			SET @STRSQL = 'SELECT SEQ_ID, ' + @ATTRIBUTE_SYSTEM_NAME + ' AS DATA_VALUE FROM [SRM-CUSTOMENTITIES].DBO.[CUS_ENTITY_DATA] WITH (NOLOCK) WHERE SRM_CLIENTS_SEQ_ID = ' + CAST(@SRM_CLIENTS_SEQ_ID AS nvarchar) + ' AND SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS nvarchar) + ' AND SEQ_ID = ' + CAST(@CUS_ENTITY_DATA_SEQ_ID AS nvarchar)
		ELSE
			SET @STRSQL = 'SELECT SEQ_ID, ' + @ATTRIBUTE_SYSTEM_NAME + ' AS DATA_VALUE FROM [SRM-CUSTOMENTITIES].DBO.[CUS_ENTITY_DATA] WITH (NOLOCK) WHERE SRM_CLIENTS_SEQ_ID = ' + CAST(@SRM_CLIENTS_SEQ_ID AS nvarchar) + ' AND SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS nvarchar)

		INSERT INTO @DATA_TABLE EXEC(@STRSQL)



		IF @DATA_TYPE_ID IN (1, 3) -- NUMERIC
		BEGIN 
			UPDATE @DATA_TABLE SET DATA_VALUE = 0 WHERE DATA_VALUE IS NULL
			INSERT INTO [SRM-DataPivot].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] 
					(SRM_CLIENT_ENTITIES_SEQ_ID, 
											CUS_ENTITY_DATA_SEQ_ID, 
											SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, 
											ATTRIBUTE_DATETIME, 
											ATTRIBUTE_DECIMAL, 
											ATTRIBUTE_STRING, 
											ATTRIBUTE_BOOLEAN, 
											SRM_CLIENTS_SEQ_ID)
				SELECT @SRM_CLIENT_ENTITIES_SEQ_ID,SEQ_ID,@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, NULL, DATA_VALUE,NULL,NULL,@SRM_CLIENTS_SEQ_ID FROM @DATA_TABLE
		END
		ELSE IF @DATA_TYPE_ID IN (2) --BOOLEAN
		BEGIN 
			UPDATE @DATA_TABLE SET DATA_VALUE = 'N' WHERE DATA_VALUE = 'FALSE'
			UPDATE @DATA_TABLE SET DATA_VALUE = 'Y' WHERE DATA_VALUE = 'TRUE'
			UPDATE @DATA_TABLE SET DATA_VALUE = 'N' WHERE DATA_VALUE IS NULL
			INSERT INTO [SRM-DataPivot].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] 
				(SRM_CLIENT_ENTITIES_SEQ_ID, 
										CUS_ENTITY_DATA_SEQ_ID, 
										SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, 
										ATTRIBUTE_DATETIME, 
										ATTRIBUTE_DECIMAL, 
										ATTRIBUTE_STRING, 
										ATTRIBUTE_BOOLEAN, 
										SRM_CLIENTS_SEQ_ID)
			SELECT @SRM_CLIENT_ENTITIES_SEQ_ID,SEQ_ID,@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, NULL,NULL,NULL, DATA_VALUE, @SRM_CLIENTS_SEQ_ID FROM @DATA_TABLE
		END
		ELSE IF @DATA_TYPE_ID IN (4, 5 ) --DATETIME
		BEGIN
			SELECT @DATA_VALUE = SEQ_ID FROM @DATA_TABLE
			INSERT INTO [SRM-DataPivot].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] 
				(SRM_CLIENT_ENTITIES_SEQ_ID, 
										CUS_ENTITY_DATA_SEQ_ID, 
										SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, 
										ATTRIBUTE_DATETIME, 
										ATTRIBUTE_DECIMAL, 
										ATTRIBUTE_STRING, 
										ATTRIBUTE_BOOLEAN, 
										SRM_CLIENTS_SEQ_ID)
			SELECT @SRM_CLIENT_ENTITIES_SEQ_ID,SEQ_ID,@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,DATA_VALUE,NULL,NULL,NULL,@SRM_CLIENTS_SEQ_ID FROM @DATA_TABLE
		END
		ELSE IF @DATA_TYPE_ID IN (6, 7, 8) --STRING
		BEGIN
			INSERT INTO [SRM-DataPivot].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] 
				(SRM_CLIENT_ENTITIES_SEQ_ID, 
										CUS_ENTITY_DATA_SEQ_ID, 
										SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, 
										ATTRIBUTE_DATETIME, 
										ATTRIBUTE_DECIMAL, 
										ATTRIBUTE_STRING, 
										ATTRIBUTE_BOOLEAN, 
										SRM_CLIENTS_SEQ_ID)
			SELECT @SRM_CLIENT_ENTITIES_SEQ_ID,SEQ_ID,@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID,NULL,NULL, DATA_VALUE ,NULL,@SRM_CLIENTS_SEQ_ID FROM @DATA_TABLE
		END
		
		FETCH NEXT FROM CUR_ATTRIBUTES INTO @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @ATTRIBUTE_SYSTEM_NAME, @DATA_TYPE_ID
	END

	CLOSE CUR_ATTRIBUTES 
	DEALLOCATE CUR_ATTRIBUTES 

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''

	--PRINT 'END POPULATE PIVOT _____________________________'
END






;



