		DECLARE CUR_ENTITIES CURSOR LOCAL STATIC FOR 
			SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES WITH (NOLOCK) WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID >= @SRM_CLIENT_ENTITIES_SEQ_ID_STARTING_ENTITY ORDER BY SEQ_ID 
