-- =============================================
CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_FOR_USING_SEPARATE_PIVOT_DB_BY_CLIENT]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@CUS_ENTITY_DATA_SEQ_ID BIGINT = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	IF @SRM_CLIENTS_SEQ_ID IS NULL OR @SRM_CLIENTS_SEQ_ID = 0
	BEGIN
		PRINT '@SRM_CLIENTS_SEQ_ID IS MISSING'
		RETURN
	END
	
	SET @ERROR = NULL
	SET @ERROR_DESCRIPTION = ''

	DECLARE @STRSQL NVARCHAR(1000)
	DECLARE @PIVOT_DB_NAME NVARCHAR(100)
	SET @PIVOT_DB_NAME = [dbo].[GetClientPivotdatabase](@SRM_CLIENTS_SEQ_ID)

		SET @STRSQL = 'EXEC ' + @PIVOT_DB_NAME + '.[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN] '
	SET @STRSQL = @STRSQL + '@SRM_CLIENT_ENTITIES_SEQ_ID = ' +  ISNULL(CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS NVARCHAR(100)), 'NULL') + ', '
	SET @STRSQL = @STRSQL + '@CUS_ENTITY_DATA_SEQ_ID = ' +  ISNULL(CAST(@CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR(100)), 'NULL') + ', '
	SET @STRSQL = @STRSQL + '@SRM_CLIENTS_SEQ_ID = ' + ISNULL(CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(100)), 'NULL') 
	PRINT @STRSQL 
	EXECUTE (@STRSQL)

	RETURN
END


;




/*
EXEC [SRM-FRAMEWORK_NEW].[dbo].[GET_POPULATE_PIVOT_TABLE_INSERT_DATA_FOR_SINGLE_ATTRIBUTE]
	@SRM_CLIENTS_SEQ_ID = 500,
	@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1041832

*/

CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_INSERT_DATA_FOR_SINGLE_ATTRIBUTE]
	@SRM_CLIENTS_SEQ_ID bigint = 500,
	@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT = 0,
	@PRINT_MESSAGES CHAR(1) = 'Y',
	@DO_NOT_UPDATE_EXISTING_RECORD CHAR(1) = 'N'
AS
	DECLARE @sInsert NVARCHAR(MAX)
	DECLARE @sCheck NVARCHAR(MAX)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID NVARCHAR(100) -- CLIENT ENTITY ID
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID2 NVARCHAR(100) -- INCASE OF LOOKUP FIELD
	DECLARE @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID NVARCHAR(100) -- ATTRIBUTE_DATA_TYPE
	DECLARE @SRM_ENTITY_ATTRIBUTES_SEQ_ID NVARCHAR(100)
	DECLARE @SYSTEM_NAME NVARCHAR(100)
	DECLARE @PIVOT_ATTRIBUTE_NAME NVARCHAR(100)
	DECLARE @PIVOT_DB_NAME NVARCHAR(100)
	DECLARE @CUSTOMEENTITY_DB_NAME NVARCHAR(100)
	DECLARE @ISNULL_VALUE NVARCHAR(10)
	--SET @SRM_CLIENTS_SEQ_ID = 88

	IF @PRINT_MESSAGES = 'Y'
		PRINT 'POPULATING PIVOT FOR ' + CAST(@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS NVARCHAR(100))

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID2 = SRM_CLIENT_ENTITIES_SEQ_ID2 
	,@SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID, @SRM_ENTITY_ATTRIBUTES_SEQ_ID = SRM_ENTITY_ATTRIBUTES_SEQ_ID
	FROM SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID


	SELECT @SYSTEM_NAME = SYSTEM_NAME FROM SRM_ENTITY_ATTRIBUTES WHERE SEQ_ID=@SRM_ENTITY_ATTRIBUTES_SEQ_ID
	SET @PIVOT_ATTRIBUTE_NAME = CASE WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (3) THEN 'ATTRIBUTE_BOOLEAN' WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (13,23) THEN 'ATTRIBUTE_STRING' WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (4,8,19) THEN 'ATTRIBUTE_DECIMAL' WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (5,6) THEN 'ATTRIBUTE_DATETIME' END
	SET @ISNULL_VALUE = CASE WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID  IN (13, 23,5) THEN '''''' WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (4, 8, 11 , 19) THEN '0' WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (3) THEN '''N''' ELSE '''''' END
	SET @PIVOT_DB_NAME = [dbo].[GetClientPivotdatabase](@SRM_CLIENTS_SEQ_ID)
	SET @CUSTOMEENTITY_DB_NAME =  [dbo].[GetClientCustomEntitiesdatabase](@SRM_CLIENTS_SEQ_ID)


	SET @sInsert = '
	DECLARE @PRIMARY_KEYS TABLE (SEQ_ID BIGINT)
	INSERT INTO @PRIMARY_KEYS( SEQ_ID )
	SELECT CED.SEQ_ID FROM  '+@CUSTOMEENTITY_DB_NAME+'.dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK)
	WHERE ced.SRM_CLIENT_ENTITIES_SEQ_ID=' + CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS NVARCHAR(100)) + CHAR(13) + ' 
	Except
	select CUS_ENTITY_DATA_seq_id from ' + @PIVOT_DB_NAME + '.dbo.CUS_PIVOT_NON_UNIQUE_INDEXES with (nolock) 
	where SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS NVARCHAR(100)) + '

	WHILE EXISTS (SELECT SEQ_ID FROM @PRIMARY_KEYS)
	BEGIN '

	SET @sInsert = @sInsert + CHAR(13) + 'INSERT INTO ' + @PIVOT_DB_NAME + '.DBO.CUS_PIVOT_NON_UNIQUE_INDEXES (SRM_CLIENT_ENTITIES_SEQ_ID, CUS_ENTITY_DATA_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, '
	+ @PIVOT_ATTRIBUTE_NAME + ', SRM_CLIENTS_SEQ_ID, DATE_CREATED, DELETED) '

	SET	@sInsert = @sInsert + CHAR(13) + ' SELECT SRM_CLIENT_ENTITIES_SEQ_ID, SEQ_ID, ' + CAST(@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS NVARCHAR(100))+ ', ' + 
	'ISNULL('+ @SYSTEM_NAME + ',' + @ISNULL_VALUE + '), SRM_CLIENTS_SEQ_ID, DATE_CREATED, ''N'' FROM ' +
	@CUSTOMEENTITY_DB_NAME + '.DBO.CUS_ENTITY_DATA CUS_ENTITY WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS NVARCHAR(100))
	+ ' AND SEQ_ID IN (SELECT TOP 50000 SEQ_ID FROM @PRIMARY_KEYS)' + CHAR(13)+ CHAR(13) + '	

	 DELETE TOP (50000) FROM @PRIMARY_KEYS

	END '

	IF @PRINT_MESSAGES = 'Y'
		PRINT @sInsert
	EXEC (@sInsert)

	IF @DO_NOT_UPDATE_EXISTING_RECORD = 'N'
	BEGIN
		EXEC [SRM-FRAMEWORK_NEW].[DBO].GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE
			@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, @PRINT_MESSAGES = @PRINT_MESSAGES, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	END

;

grant execute, view definition on GET_POPULATE_PIVOT_TABLE_INSERT_DATA_FOR_SINGLE_ATTRIBUTE to usr_conversion;







