CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@CUS_ENTITY_DATA_SEQ_ID BIGINT = NULL,
	@DELETE_EXISTING_RECORDS CHAR(1) = 'Y',
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [SRM-CustomEntities_162].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]'

	SET ANSI_NULLS ON
	SET QUOTED_IDENTIFIER ON
	--SET NOCOUNT ON;

	PRINT 'START OF PROCESS................................' + CAST(GETDATE()  AS NVARCHAR(100))

	IF (@SRM_CLIENT_ENTITIES_SEQ_ID IS NULL OR @SRM_CLIENTS_SEQ_ID IS NULL) AND @CUS_ENTITY_DATA_SEQ_ID IS NOT NULL
	BEGIN
		SELECT @SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENTS_SEQ_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-CustomEntities_162].DBO.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID
	END
	
	IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NOT NULL AND @SRM_CLIENTS_SEQ_ID IS NULL
	BEGIN
		SELECT @SRM_CLIENTS_SEQ_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITIES WITH (NOLOCK) WHERE SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
	END
	
	IF  (@SRM_CLIENT_ENTITIES_SEQ_ID IS NULL AND @CUS_ENTITY_DATA_SEQ_ID IS NULL) OR @SRM_CLIENTS_SEQ_ID IS NULL
	BEGIN
		PRINT 'CLIENT ID OR CLIENT ENTITY OR CUS ENTITY DATA SEQ ID IS MISSING. CANNOT PROCEED.'
		RETURN
	END
	
	IF @DELETE_EXISTING_RECORDS = 'Y'
	BEGIN
		EXEC [SRM-CustomEntities_162].[dbo].[GET_POPULATE_PIVOT_TABLE_MARK_RECORDS_FOR_DELETION]
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END
	PRINT 'END OF MARK DELETED PROCESS.....................: ' + CAST(GETDATE()  AS NVARCHAR(100))
	EXEC [SRM-CustomEntities_162].DBO.GET_POPULATE_PIVOT_TABLE_POPULATE_DATA
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
		@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

	PRINT 'END OF POPULATE PIVOT PROCESS...................: ' + CAST(GETDATE()  AS NVARCHAR(100))
	IF @DELETE_EXISTING_RECORDS = 'Y'
	BEGIN
		EXEC [SRM-CustomEntities_162].[dbo].[GET_POPULATE_PIVOT_TABLE_DELETE_MARKED_RECORDS]
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END

	PRINT 'END OF RECORD DELETE PROCESS................DONE: ' + CAST(GETDATE()  AS NVARCHAR(100))

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END












;





