-- =============================================
CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_MARK_RECORDS_FOR_DELETION]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@CUS_ENTITY_DATA_SEQ_ID BIGINT = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [SRM-CustomEntities_162].[dbo].[GET_POPULATE_PIVOT_TABLE_MARK_RECORDS_FOR_DELETION]'
	DECLARE @CUS_PIVOT_NON_UNIQUE_INDEXES_SEQ_ID BIGINT
	DECLARE @COUNTER BIGINT
	DECLARE @TOTAL_RECORDS BIGINT
	DECLARE @FIRST_TIME CHAR(1)

	SET @FIRST_TIME = 'Y'

	IF  @SRM_CLIENTS_SEQ_ID IS NULL AND @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL AND @CUS_ENTITY_DATA_SEQ_ID IS NULL
	BEGIN
		PRINT 'CLIENT ID AND ENTITY ID AND CUS_ENTITY SEQ ID IS MISSING. CANNOT PROCEED.'
		RETURN
	END
	
	IF @CUS_ENTITY_DATA_SEQ_ID IS NOT NULL -- SINGLE RECORD
	BEGIN
		SELECT @TOTAL_RECORDS = COUNT(*) FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE (DELETED = 'N' OR DELETED IS NULL) AND CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID
		PRINT 'Total Records for Mark Deletion : ' + cast(@TOTAL_RECORDS as nvarchar(20))
		WHILE (@FIRST_TIME = 'Y' OR @@ROWCOUNT > 0)
		BEGIN
			SET @FIRST_TIME = 'N'
			UPDATE [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES SET DELETED = 'Y'
			WHERE SEQ_ID IN (SELECT TOP 10000 SEQ_ID FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES  WITH (NOLOCK)
						WHERE (DELETED = 'N' OR DELETED IS NULL)
						AND CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID)
		END
		RETURN
	END
	ELSE IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL -- COMPLETE CLIENT
	BEGIN
		SELECT @TOTAL_RECORDS = COUNT(*) FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE (DELETED = 'N' OR DELETED IS NULL) AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		PRINT 'Total Records for Mark Deletion : ' + cast(@TOTAL_RECORDS as nvarchar(20))
		WHILE (@FIRST_TIME = 'Y' OR @@ROWCOUNT > 0)
		BEGIN
			SET @FIRST_TIME = 'N'
			UPDATE [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES SET DELETED = 'Y'
			WHERE SEQ_ID IN (SELECT TOP 10000 SEQ_ID FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES  WITH (NOLOCK)
						WHERE (DELETED = 'N' OR DELETED IS NULL)
						AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)
		END
		RETURN
	END
	ELSE -- SINGLE ENTITY
	BEGIN
		SELECT @TOTAL_RECORDS = COUNT(*) FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE (DELETED = 'N' OR DELETED IS NULL) AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
		PRINT 'Total Records for Mark Deletion : ' + cast(@TOTAL_RECORDS as nvarchar(20))
		WHILE (@FIRST_TIME = 'Y' OR @@ROWCOUNT > 0)
		BEGIN
			SET @FIRST_TIME = 'N'
			UPDATE [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES SET DELETED = 'Y'
			WHERE SEQ_ID IN (SELECT TOP 10000 SEQ_ID FROM [SRM-CustomEntities_162].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES  WITH (NOLOCK)
						WHERE (DELETED = 'N' OR DELETED IS NULL) 
						AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID)
		END
		RETURN
	END
	
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END








;





