-- =============================================
-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_MISSING_ATTRIBUTES_MAIN]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@SRM_CLIENT_ENTITIES_SEQ_ID_STARING_ENTITY BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT
	DECLARE @Query NVARCHAR(4000) 
	DECLARE @Database VARCHAR(4000)
	SET @Database = 'SRM-DataPivot'
	DECLARE @LogFile NVARCHAR(4000)
	DECLARE @ParmDefinition NVARCHAR(500)
	DECLARE @TOTAL_RECORDS BIGINT
	DECLARE @CURRENT_RECORD BIGINT

	IF ISNULL(@SRM_CLIENTS_SEQ_ID, 0) = 0
	BEGIN
		SET @ERROR = -1
		SET @ERROR_DESCRIPTION = 'NO CLIENT SPECIFIED'
		PRINT '............NO CLIENT SPECIFIED...............'
		RETURN
	END

	-- truncate transaction log
	SET @Query = 'USE [' + @Database + '] SELECT @LogFile = name FROM [' + @Database + '].dbo.sysfiles WHERE filename LIKE ''%.ldf'''
	SET @ParmDefinition = '@LogFile VARCHAR(4000) OUTPUT'
	EXECUTE sp_executesql @Query, @ParmDefinition, @LogFile = @LogFile OUTPUT 
	SET @Query = 'ALTER DATABASE [' + @Database + '] SET RECOVERY SIMPLE'
	EXEC(@Query) 
	SET @Query = 'USE [' + @Database + '] DBCC SHRINKFILE ([' + @LogFile + '], 0)'
	EXEC(@Query)

	IF ISNULL(@SRM_CLIENT_ENTITIES_SEQ_ID_STARING_ENTITY, 0) > 0
	BEGIN
		DECLARE CUR_ENTITIES CURSOR FOR 
			SELECT SEQ_ID FROM SRM_CLIENT_ENTITIES WITH (NOLOCK) WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID >= @SRM_CLIENT_ENTITIES_SEQ_ID_STARING_ENTITY ORDER BY SEQ_ID
	END
	ELSE IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL
	BEGIN
		DECLARE CUR_ENTITIES CURSOR FOR 
			SELECT SEQ_ID FROM SRM_CLIENT_ENTITIES WITH (NOLOCK) WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID ORDER BY SEQ_ID
	END
	ELSE
	BEGIN
		DECLARE CUR_ENTITIES CURSOR FOR 
			SELECT SEQ_ID FROM SRM_CLIENT_ENTITIES WITH (NOLOCK) WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID ORDER BY SEQ_ID
	END

	OPEN CUR_ENTITIES

	FETCH NEXT FROM CUR_ENTITIES INTO @SRM_CLIENT_ENTITIES_SEQ_ID
	WHILE @@FETCH_STATUS = 0
	BEGIN
		DECLARE CUR_RECORDS CURSOR FOR 
			SELECT SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID 

		SELECT @TOTAL_RECORDS = COUNT(*) FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID 
		SET @CURRENT_RECORD = 1

		OPEN CUR_RECORDS

		FETCH NEXT FROM CUR_RECORDS INTO @CUS_ENTITY_DATA_SEQ_ID
		WHILE @@FETCH_STATUS = 0
		BEGIN
			PRINT 'PROCESSING CLIENT ENTITY ' + CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS NVARCHAR(20)) + '. RECORD ID ' + CAST(@CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR(20)) + '. RECORD ' + CAST(@CURRENT_RECORD AS NVARCHAR(20)) + ' OF ' + CAST(@TOTAL_RECORDS AS NVARCHAR(20)) + '.'

			SET @CURRENT_RECORD = @CURRENT_RECORD + 1

			EXEC [dbo].[GET_POPULATE_PIVOT_TABLE_MISSING_ATTRIBUTES]
				@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
				@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
				@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID	

			FETCH NEXT FROM CUR_RECORDS INTO @CUS_ENTITY_DATA_SEQ_ID
		END
		CLOSE CUR_RECORDS
		DEALLOCATE CUR_RECORDS

		FETCH NEXT FROM CUR_ENTITIES INTO @SRM_CLIENT_ENTITIES_SEQ_ID
	END

	CLOSE CUR_ENTITIES
	DEALLOCATE CUR_ENTITIES
	
	-- truncate transaction log
	SET @Query = 'USE [' + @Database + '] SELECT @LogFile = name FROM [' + @Database + '].dbo.sysfiles WHERE filename LIKE ''%.ldf'''
	SET @ParmDefinition = '@LogFile VARCHAR(4000) OUTPUT'
	EXECUTE sp_executesql @Query, @ParmDefinition, @LogFile = @LogFile OUTPUT 
	SET @Query = 'ALTER DATABASE [' + @Database + '] SET RECOVERY SIMPLE'
	EXEC(@Query) 
	SET @Query = 'USE [' + @Database + '] DBCC SHRINKFILE ([' + @LogFile + '], 0)'
	EXEC(@Query)
END


;







