CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_SINGLE_ENTITY]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT,
	@SHOW_RECORD_COUNTER NVARCHAR(1) = 'Y',
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT
	DECLARE @TOTAL_COUNT BIGINT
	DECLARE @CURRENT_COUNT BIGINT

	IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL OR @SRM_CLIENTS_SEQ_ID IS NULL
	BEGIN
		PRINT 'NO @SRM_CLIENT_ENTITIES_SEQ_ID OR @SRM_CLIENTS_SEQ_ID SPECIFIED'
		RETURN
	END

	SELECT @TOTAL_COUNT = COUNT(SEQ_ID) FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	SET @CURRENT_COUNT = 1

	DECLARE CUR_RECORDS CURSOR LOCAL STATIC FOR
		SELECT SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID ORDER BY CUS_ENTITY_DATA.SEQ_ID

	OPEN CUR_RECORDS

	FETCH NEXT FROM CUR_RECORDS INTO @CUS_ENTITY_DATA_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF @SHOW_RECORD_COUNTER = 'Y'
			PRINT 'PROCESSING RECORD ' + CAST(@CURRENT_COUNT AS NVARCHAR) + ' OF ' + CAST(@TOTAL_COUNT AS NVARCHAR) + '. RECORD_ID = ' + CAST(@CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR(20)) + ' ENTITY_ID = ' + CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS NVARCHAR(20)) + ' CLIENT_ID = ' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(20))

		EXEC [SRM-Framework_New].[dbo].[GET_POPULATE_PIVOT_TABLE]
			-- Add the parameters for the stored procedure here
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

		SET @CURRENT_COUNT = @CURRENT_COUNT + 1

		FETCH NEXT FROM CUR_RECORDS INTO @CUS_ENTITY_DATA_SEQ_ID
	END

	CLOSE CUR_RECORDS
	DEALLOCATE CUR_RECORDS

END
	 --exec [dbo].[GET_APPLY_PS_DATA_TO_API]


;






-- Stored Procedure

-- =============================================
-- Author:		<Rauf Gill>
-- ALTER date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_SINGLE_ENTITY_USING_DO_NOT_DELETE_EXISTING_RECORDS]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@CUS_ENTITY_DATA_SEQ_ID BIGINT = NULL,
	@DELETE_EXISTING_RECORDS CHAR(1) = 'Y',
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_PIVOT_TABLE_SINGLE_ENTITY_USING_DO_NOT_DELETE_EXISTING_RECORDS]'

	SET ANSI_NULLS ON
	SET QUOTED_IDENTIFIER ON
	--SET NOCOUNT ON;

	PRINT 'START OF PROCESS................................' + CAST(GETDATE()  AS NVARCHAR(100))

	IF  @SRM_CLIENTS_SEQ_ID IS NULL OR (@SRM_CLIENT_ENTITIES_SEQ_ID IS NULL AND @CUS_ENTITY_DATA_SEQ_ID IS NULL)
	BEGIN
		PRINT 'CLIENT ID OR ENTITY ID IS MISSING. CANNOT PROCEED.'
		RETURN
	END
	IF @CUS_ENTITY_DATA_SEQ_ID IS NOT NULL
	BEGIN
		UPDATE [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES
			SET DELETED = 'Y'
		WHERE 
			CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID
	END
	ELSE
	BEGIN
		WHILE EXISTS(SELECT TOP 1 SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE DELETED <> 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID)
		BEGIN
			UPDATE [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES
				SET DELETED = 'Y'
			WHERE SEQ_ID IN (SELECT TOP 10000 SEQ_ID FROM [SRM-DataPivot].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) 
						WHERE (DELETED IS NULL OR DELETED <> 'Y') 
						AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
						AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID)
		END
	END
	PRINT 'END OF MARK DELETED PROCESS.....................' + CAST(GETDATE()  AS NVARCHAR(100))

	EXEC DBO.GET_POPULATE_PIVOT_TABLE_DO_NOT_DELETE_EXISTING_RECORDS
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
		@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

	PRINT 'END OF POPULATE PIVOT PROCESS...................' + CAST(GETDATE()  AS NVARCHAR(100))

	IF @DELETE_EXISTING_RECORDS = 'Y'
	BEGIN
		EXEC [dbo].[GET_POPULATE_PIVOT_TABLE_DELETE_MARKED_RECORDS_FROM_PIVOT]
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END

	PRINT 'END OF PROCESS..................................' + CAST(GETDATE()  AS NVARCHAR(100))

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END






;




