	(SRM_CLIENT_ENTITIES_SEQ_ID, CUS_ENTITY_DATA_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, ATTRIBUTE_DATETIME, ATTRIBUTE_DECIMAL, ATTRIBUTE_STRING, ATTRIBUTE_BOOLEAN,
	SRM_CLIENTS_SEQ_ID, DATE_CREATED, DELETED)
	SELECT SRM_CLIENT_ENTITIES_SEQ_ID, SEQ_ID, 547086, NULL, NULL, ATTRIBUTE_169, NULL,66, GETDATE(),'N'
	FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=18511
	*/



