CREATE PROCEDURE [dbo].[GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE_95]
	@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT
AS
	DECLARE @sSelect NVARCHAR(MAX)
	DECLARE @sUpdate NVARCHAR(MAX)
	DECLARE @SRM_CLIENTS_SEQ_ID NVARCHAR(100)
	-- This is the only value need to be provided by User
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID NVARCHAR(100) -- CLIENT ENTITY ID
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID2 NVARCHAR(100) -- INCASE OF LOOKUP FIELD
	DECLARE @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID NVARCHAR(100) -- ATTRIBUTE_DATA_TYPE
	DECLARE @SRM_ENTITY_ATTRIBUTES_SEQ_ID NVARCHAR(100)
	DECLARE @SYSTEM_NAME NVARCHAR(100)
	DECLARE @PIVOT_ATTRIBUTE_NAME NVARCHAR(100)
	DECLARE @PIVOT_DB_NAME NVARCHAR(100)
	DECLARE @CUSTOMEENTITY_DB_NAME NVARCHAR(100)
	DECLARE @ISNULL_VALUE NVARCHAR(10)

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID2 = SRM_CLIENT_ENTITIES_SEQ_ID2 
	,@SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID, @SRM_ENTITY_ATTRIBUTES_SEQ_ID = SRM_ENTITY_ATTRIBUTES_SEQ_ID
	FROM SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

	SELECT @SRM_CLIENTS_SEQ_ID = SRM_CLIENTS_SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID

	SELECT @SYSTEM_NAME = SYSTEM_NAME FROM SRM_ENTITY_ATTRIBUTES WHERE SEQ_ID=@SRM_ENTITY_ATTRIBUTES_SEQ_ID
	SET @PIVOT_ATTRIBUTE_NAME = CASE WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (3) THEN 'ATTRIBUTE_BOOLEAN' WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (13,23) THEN 'ATTRIBUTE_STRING' WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (4,8,11,19) THEN 'ATTRIBUTE_DECIMAL' WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (5,6) THEN 'ATTRIBUTE_DATETIME' END
	IF @PIVOT_ATTRIBUTE_NAME IS NULL 
		SET @PIVOT_ATTRIBUTE_NAME = 'ATTRIBUTE_STRING'
	SET @ISNULL_VALUE = CASE WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID  IN (3) THEN '''N''' WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID  IN (13, 23,5) THEN '''''' WHEN @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID IN (4, 8, 11, 19) THEN '0' ELSE '''''' END
	--SET @PIVOT_DB_NAME = CASE WHEN @SRM_CLIENTS_SEQ_ID IN (21,48,63,65,66,67,68,69,72,73,74,75)  THEN '[SRM-DataPivot_'+@SRM_CLIENTS_SEQ_ID+']' ELSE '[SRM-DataPivot]' END
	SET @PIVOT_DB_NAME = [dbo].[GetClientPivotdatabase](@SRM_CLIENTS_SEQ_ID)
	SET @CUSTOMEENTITY_DB_NAME = [dbo].[GetClientCustomEntitiesdatabase](@SRM_CLIENTS_SEQ_ID)

	--PRINT @SRM_CLIENTS_SEQ_ID
	--PRINT @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
	--PRINT @SRM_CLIENT_ENTITIES_SEQ_ID 
	--PRINT @SRM_CLIENT_ENTITIES_SEQ_ID2
	--PRINT @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID 
	--PRINT @SRM_ENTITY_ATTRIBUTES_SEQ_ID
	--PRINT @SYSTEM_NAME
	--PRINT @PIVOT_ATTRIBUTE_NAME
	--PRINT @PIVOT_DB_NAME
	--SELECT * FROM SRM_ATTRIBUTE_DATA_TYPES

	SET @sSelect = 'SELECT CUS_ENTITY.'+ @SYSTEM_NAME + ',  DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + '
	FROM ' + @CUSTOMEENTITY_DB_NAME + '.DBO.CUS_ENTITY_DATA CUS_ENTITY
	INNER JOIN ' + @PIVOT_DB_NAME + '.DBO.CUS_PIVOT_NON_UNIQUE_INDEXES DATAPIVOT ON CUS_ENTITY.SEQ_ID = DATAPIVOT.CUS_ENTITY_DATA_SEQ_ID AND DATAPIVOT.SRM_CLIENT_ENTITIES_SEQ_ID = ' + @SRM_CLIENT_ENTITIES_SEQ_ID + ' AND 
	DATAPIVOT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS NVARCHAR(20)) + '
	WHERE CUS_ENTITY.SRM_CLIENT_ENTITIES_SEQ_ID = ' + @SRM_CLIENT_ENTITIES_SEQ_ID + 
	' AND ISNULL(CUS_ENTITY.'+ @SYSTEM_NAME + ',' + @ISNULL_VALUE + ') != ISNULL(DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + ', ' + @ISNULL_VALUE + ') '


	IF @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = 5
	BEGIN
	
		SET @sUpdate = 'UPDATE DATAPIVOT SET DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + ' = ' + @SYSTEM_NAME + ' 
		FROM ' + @CUSTOMEENTITY_DB_NAME + '.DBO.CUS_ENTITY_DATA CUS_ENTITY WITH (NOLOCK)
		INNER JOIN ' + @PIVOT_DB_NAME + '.DBO.CUS_PIVOT_NON_UNIQUE_INDEXES DATAPIVOT ON CUS_ENTITY.SEQ_ID = DATAPIVOT.CUS_ENTITY_DATA_SEQ_ID AND DATAPIVOT.SRM_CLIENT_ENTITIES_SEQ_ID = ' + @SRM_CLIENT_ENTITIES_SEQ_ID + ' 
		AND DATAPIVOT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS NVARCHAR(20)) + '
		WHERE '
		SET @sUpdate = @sUpdate + ' (ISNULL(CUS_ENTITY.' + @SYSTEM_NAME + ', ''1753-01-01'')  != ISNULL(' + @PIVOT_ATTRIBUTE_NAME + ', ''1753-01-01''))'	

		--SET @sUpdate = @sUpdate + ' AND ((CUS_ENTITY.' + @SYSTEM_NAME + '  IS NOT NULL AND ' + @PIVOT_ATTRIBUTE_NAME + ' IS NULL ) OR '
		--SET @sUpdate = @sUpdate + '(CUS_ENTITY.' + @SYSTEM_NAME + '  != ' + @PIVOT_ATTRIBUTE_NAME + '))'
	END
	ELSE if @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = 3
	BEGIN
		SET @sUpdate = 'UPDATE DATAPIVOT SET DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + ' = ISNULL(CUS_ENTITY.'+ @SYSTEM_NAME + ', ' + @ISNULL_VALUE + ') 
		FROM ' + @CUSTOMEENTITY_DB_NAME + '.DBO.CUS_ENTITY_DATA CUS_ENTITY WITH (NOLOCK)
		INNER JOIN ' + @PIVOT_DB_NAME + '.DBO.CUS_PIVOT_NON_UNIQUE_INDEXES DATAPIVOT ON CUS_ENTITY.SEQ_ID = DATAPIVOT.CUS_ENTITY_DATA_SEQ_ID AND DATAPIVOT.SRM_CLIENT_ENTITIES_SEQ_ID = ' + @SRM_CLIENT_ENTITIES_SEQ_ID + ' 
		AND DATAPIVOT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS NVARCHAR(20)) + '
		WHERE '
		SET @sUpdate = @sUpdate + ' ISNULL(CUS_ENTITY.'+ @SYSTEM_NAME + ', '''') COLLATE Latin1_General_CI_AS != ISNULL(DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + ', ' + @ISNULL_VALUE + ') '
	END
	ELSE 
	BEGIN
		print 'here in else'

		SET @sUpdate = 'UPDATE DATAPIVOT SET DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + ' = ISNULL(CUS_ENTITY.'+ @SYSTEM_NAME + ', ' + @ISNULL_VALUE + ') 
		FROM ' + @CUSTOMEENTITY_DB_NAME + '.DBO.CUS_ENTITY_DATA CUS_ENTITY WITH (NOLOCK)
		INNER JOIN ' + @PIVOT_DB_NAME + '.DBO.CUS_PIVOT_NON_UNIQUE_INDEXES DATAPIVOT ON CUS_ENTITY.SEQ_ID = DATAPIVOT.CUS_ENTITY_DATA_SEQ_ID AND DATAPIVOT.SRM_CLIENT_ENTITIES_SEQ_ID = ' + @SRM_CLIENT_ENTITIES_SEQ_ID + ' 
		AND DATAPIVOT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS NVARCHAR(20)) + '
		WHERE '
		IF @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID NOT IN (4, 8, 9, 11)
			SET @sUpdate = @sUpdate + ' ISNULL(CUS_ENTITY.'+ @SYSTEM_NAME + ',' + @ISNULL_VALUE + ') COLLATE Latin1_General_CI_AS != ISNULL(DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + ', ' + @ISNULL_VALUE + ') '
		ELSE
			SET @sUpdate = @sUpdate + ' ISNULL(CUS_ENTITY.'+ @SYSTEM_NAME + ',' + @ISNULL_VALUE + ') != ' + @PIVOT_ATTRIBUTE_NAME 
	END

	--ELSE
	--	BEGIN
	--	SET @sUpdate = 'UPDATE DATAPIVOT SET DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + ' = ISNULL(CUS_ENTITY.'+ @SYSTEM_NAME + ', ' + @ISNULL_VALUE + ')
	--	FROM ' + @CUSTOMEENTITY_DB_NAME + '.DBO.CUS_ENTITY_DATA CUS_ENTITY WITH (NOLOCK)
	--	INNER JOIN ' + @PIVOT_DB_NAME + '.DBO.CUS_PIVOT_NON_UNIQUE_INDEXES DATAPIVOT ON CUS_ENTITY.SEQ_ID = DATAPIVOT.CUS_ENTITY_DATA_SEQ_ID AND DATAPIVOT.SRM_CLIENT_ENTITIES_SEQ_ID = ' + @SRM_CLIENT_ENTITIES_SEQ_ID + ' 
	--	AND DATAPIVOT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID AS NVARCHAR(20)) + '
	--	WHERE CUS_ENTITY.SRM_CLIENT_ENTITIES_SEQ_ID = ' + @SRM_CLIENT_ENTITIES_SEQ_ID 
	--	IF @SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID NOT IN (4, 5, 6, 8, 9)
	--		SET @sUpdate = @sUpdate + ' AND ISNULL(CUS_ENTITY.'+ @SYSTEM_NAME + ',' + @ISNULL_VALUE + ') COLLATE Latin1_General_CI_AS != ISNULL(DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + ', ' + @ISNULL_VALUE + ') '
	--	ELSE
	--		SET @sUpdate = @sUpdate + ' AND ISNULL(CUS_ENTITY.'+ @SYSTEM_NAME + ',' + @ISNULL_VALUE + ') != ISNULL(DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + ', ' + @ISNULL_VALUE + ') '
	--END
	-- ISNULL(CUS_ENTITY.'+ @SYSTEM_NAME + ',' + @ISNULL_VALUE + ') collate Latin1_General_100_CI_AS != ISNULL(DATAPIVOT.' + @PIVOT_ATTRIBUTE_NAME + ', ' + @ISNULL_VALUE + ') '

	--PRINT @sSelect
	--PRINT CHAR(10) + CHAR(13)
	PRINT @sUpdate

	EXEC (@sUpdate)

	--COLLATE Latin1_General_CI_AS 

	/*
	INSERT INTO [SRM-DataPivot_66].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES
	(SRM_CLIENT_ENTITIES_SEQ_ID, CUS_ENTITY_DATA_SEQ_ID, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, ATTRIBUTE_DATETIME, ATTRIBUTE_DECIMAL, ATTRIBUTE_STRING, ATTRIBUTE_BOOLEAN,
	SRM_CLIENTS_SEQ_ID, DATE_CREATED, DELETED)
	SELECT SRM_CLIENT_ENTITIES_SEQ_ID, SEQ_ID, 547086, NULL, NULL, ATTRIBUTE_169, NULL,66, GETDATE(),'N'
	FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA AS CED WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=18511
	*/



;





  
