CREATE PROCEDURE [dbo].[GET_POPULATE_PURCHASE_HISTORY]   
  @m_CLIENT_SEQ_ID BIGINT,  
  @m_MEMBER_CUS_ENTITY_DATA_SEQ_ID BIGINT,  
  @ERROR SMALLINT = NULL OUTPUT,  
  @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT  
 AS   
 BEGIN  

 --return -- RG_2022-02-22 Temp to ease out server load
    
 SET NOCOUNT ON;  
   
 DECLARE @ACCOUNT_CONTACT_SEQ_ID BIGINT  
 DECLARE @ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
 DECLARE @CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
 DECLARE @PRODUCT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
 DECLARE @LOGIN_USER_NAME NVARCHAR(200)  
   
 DECLARE @MEM_TYPE CHAR--A(ACCOUNT) OR C(CONTACT)  
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
 DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  
 DECLARE @NEW_SEQ_ID BIGINT  
 DECLARE @SRM_ENTITY_NAME NVARCHAR(200)  
 DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)  
   
 DECLARE @USERNAME NVARCHAR(100)  
 DECLARE @TRANSACTION_DATE NVARCHAR(100)  
 DECLARE @PRODUCT_TITLE NVARCHAR(100)  
 DECLARE @QUANTITY NVARCHAR(100)  
 DECLARE @NET_AMOUNT NVARCHAR(100)  
 DECLARE @VAT_AMOUNT NVARCHAR(100)  
 DECLARE @GROSS_AMOUNT NVARCHAR(100)  
 DECLARE @PRODUCT_ID NVARCHAR(100)  
    
 DECLARE @DATEMODIFIED DATETIME  
 DECLARE @MODIFIEDBY NVARCHAR(200)  
 DECLARE @DATECREATED DATETIME  
 DECLARE @CREATEDBY NVARCHAR(200)  

  
 SET @ERROR = 1  
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_PURCHASE_HISTORY]'  
  
 SELECT @ACCOUNT_CONTACT_SEQ_ID = CASE WHEN ISNULL(ATTRIBUTE_015,'')='' THEN ATTRIBUTE_017 ELSE ATTRIBUTE_015 END,  
   @MEM_TYPE=CASE WHEN ISNULL(ATTRIBUTE_015,'')='' THEN 'C' ELSE 'A' END  
   FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA MEM WITH(NOLOCK) WHERE SEQ_ID=@m_MEMBER_CUS_ENTITY_DATA_SEQ_ID  
  
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME   
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH(NOLOCK)  
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID  
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID  
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_PURCHASE_HISTORY'  
  
 SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME   
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH(NOLOCK),[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH(NOLOCK) 
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID  
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID  
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'PRODUCT_SALE'  
  
 SELECT @ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME   
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH(NOLOCK) 
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID  
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID  
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'ACCOUNT'  
   
 SELECT @CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME   
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH(NOLOCK) 
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID  
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID  
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'CONTACT'  
   
 SELECT @PRODUCT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME   
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C WITH(NOLOCK), [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D WITH(NOLOCK)  
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID  
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID  
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'PRODUCT'  
  
    
 
 IF @MEM_TYPE='C' 
 BEGIN
	SELECT @LOGIN_USER_NAME = ATTRIBUTE_020 FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID AND SEQ_ID = @ACCOUNT_CONTACT_SEQ_ID
	-- FOR CONTACT
	DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR
	SELECT   
		@LOGIN_USER_NAME USERNAME,  
		PRODUCT_SALE.ATTRIBUTE_008 AS TRANSACTION_DATE,  
		PRODUCT_SALE.ATTRIBUTE_007 AS PRODUCT_TITLE,  
		PRODUCT_SALE.ATTRIBUTE_020 AS QUANTITY,  
		PRODUCT_SALE.ATTRIBUTE_017 AS NET_AMOUNT,  
		PRODUCT_SALE.ATTRIBUTE_018 AS VAT_AMOUNT,  
		PRODUCT_SALE.ATTRIBUTE_019 AS GROSS_AMOUNR,  
		PRODUCT.ATTRIBUTE_001 AS PRODUCT_ID,  
		PRODUCT_SALE.DATE_CREATED,  
		PRODUCT_SALE.CREATED_BY,  
		PRODUCT_SALE.DATE_MODIFIED,  
		PRODUCT_SALE.MODIFIED_BY  
     
	FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA PRODUCT_SALE  WITH(NOLOCK)
		INNER JOIN [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES PRODUCT_SALE_PIVOT WITH(NOLOCK) ON PRODUCT_SALE.SEQ_ID = PRODUCT_SALE_PIVOT.CUS_ENTITY_DATA_SEQ_ID AND PRODUCT_SALE_PIVOT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 54528 AND PRODUCT_SALE_PIVOT.ATTRIBUTE_DECIMAL = @ACCOUNT_CONTACT_SEQ_ID
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA PRODUCT WITH(NOLOCK) ON PRODUCT.SRM_CLIENT_ENTITIES_SEQ_ID=@PRODUCT_SRM_CLIENT_ENTITIES_SEQ_ID AND PRODUCT.SEQ_ID IN(SELECT ATTRIBUTE_DECIMAL FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=54530 AND CUS_ENTITY_DATA_SEQ_ID =PRODUCT_SALE.SEQ_ID) --PRODUCT_SALE.ATTRIBUTE_006
	WHERE PRODUCT_SALE.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID  
		AND PRODUCT_SALE.DELETED <> 'Y'  

 END
 ELSE
 BEGIN
	SELECT @LOGIN_USER_NAME = ATTRIBUTE_011 FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID AND SEQ_ID = @ACCOUNT_CONTACT_SEQ_ID
	-- FOR ACCOUNT
	DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR
	SELECT   
		@LOGIN_USER_NAME USERNAME,  
		PRODUCT_SALE.ATTRIBUTE_008 AS TRANSACTION_DATE,  
		PRODUCT_SALE.ATTRIBUTE_007 AS PRODUCT_TITLE,  
		PRODUCT_SALE.ATTRIBUTE_020 AS QUANTITY,  
		PRODUCT_SALE.ATTRIBUTE_017 AS NET_AMOUNT,  
		PRODUCT_SALE.ATTRIBUTE_018 AS VAT_AMOUNT,  
		PRODUCT_SALE.ATTRIBUTE_019 AS GROSS_AMOUNR,  
		PRODUCT.ATTRIBUTE_001 AS PRODUCT_ID,  
		PRODUCT_SALE.DATE_CREATED,  
		PRODUCT_SALE.CREATED_BY,  
		PRODUCT_SALE.DATE_MODIFIED,  
		PRODUCT_SALE.MODIFIED_BY  
     
	FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA PRODUCT_SALE  WITH(NOLOCK)
		INNER JOIN [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES PRODUCT_SALE_PIVOT WITH(NOLOCK) ON PRODUCT_SALE.SEQ_ID = PRODUCT_SALE_PIVOT.CUS_ENTITY_DATA_SEQ_ID AND PRODUCT_SALE_PIVOT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 54526 AND PRODUCT_SALE_PIVOT.ATTRIBUTE_DECIMAL = @ACCOUNT_CONTACT_SEQ_ID
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA PRODUCT WITH(NOLOCK) ON PRODUCT.SRM_CLIENT_ENTITIES_SEQ_ID=@PRODUCT_SRM_CLIENT_ENTITIES_SEQ_ID AND PRODUCT.SEQ_ID IN(SELECT ATTRIBUTE_DECIMAL FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=54530 AND CUS_ENTITY_DATA_SEQ_ID =PRODUCT_SALE.SEQ_ID) --PRODUCT_SALE.ATTRIBUTE_006
	WHERE PRODUCT_SALE.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID  
		AND PRODUCT_SALE.DELETED <> 'Y'  
 END
     
 OPEN CUR_RECORDS  
   
 FETCH NEXT FROM CUR_RECORDS INTO     @USERNAME,  @TRANSACTION_DATE,  @PRODUCT_TITLE,  @QUANTITY,  @NET_AMOUNT,  @VAT_AMOUNT,  @GROSS_AMOUNT,  @PRODUCT_ID,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY   
  
 --DELETE IF ALREADY EXITS   
 IF (EXISTS(SELECT SEQ_ID FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WITH (NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56153 AND ATTRIBUTE_STRING = @USERNAME))  
 BEGIN  
	DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56153 AND ATTRIBUTE_STRING = @USERNAME)
	DELETE FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE SEQ_ID IN (SELECT SEQ_ID FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WITH (NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 56153 AND ATTRIBUTE_STRING = @USERNAME)
 END  
  
 WHILE @@FETCH_STATUS = 0  
 BEGIN  
   
	  EXEC  [DBO].[GET_INSERT_CUS_ENTITY_DATA]  
		  @SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID,  
		  @ATTRIBUTE_001=@USERNAME,  
		  @ATTRIBUTE_003=@TRANSACTION_DATE,  
		  @ATTRIBUTE_004=@PRODUCT_TITLE,  
		  @ATTRIBUTE_005=@QUANTITY,  
		  @ATTRIBUTE_006=@NET_AMOUNT,  
		  @ATTRIBUTE_008=@GROSS_AMOUNT,  
		  @ATTRIBUTE_009=@PRODUCT_ID,  
		  @SRM_CLIENTS_SEQ_ID=@M_CLIENT_SEQ_ID,  
		  @DATE_CREATED=@DATECREATED,  
		  @CREATED_BY=@CREATEDBY,  
		  @DATE_MODIFIED=@DATEMODIFIED,  
		  @MODIFIED_BY=@MODIFIEDBY,  
		  @RETURN_SEQ_ID=@NEW_SEQ_ID OUTPUT,  
		  @ERROR=@ERROR OUTPUT,  
		  @ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT  
      
	 FETCH NEXT FROM CUR_RECORDS INTO    @USERNAME,  @TRANSACTION_DATE,  @PRODUCT_TITLE,  @QUANTITY,  @NET_AMOUNT,  @VAT_AMOUNT,  @GROSS_AMOUNT,  @PRODUCT_ID,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY   
 END  
  
 CLOSE CUR_RECORDS  
 DEALLOCATE CUR_RECORDS  
   
 SET @ERROR = 0  
 SET @ERROR_DESCRIPTION = ''  
END



;






-- =============================================    
-- Author:  <Mazhar>    
-- Create date: <14/08/2013,,>    
-- Description: <Apply Area of Focus Data to Web service Area of Focus>    
-- =============================================    
CREATE PROCEDURE [dbo].[GET_POPULATE_TITLE]     
  @m_CLIENT_SEQ_ID BIGINT,    
  @ERROR SMALLINT = NULL OUTPUT,    
  @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT    
 AS     
 BEGIN    
      
 SET NOCOUNT ON;    
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT    
 DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT    
 DECLARE @NEW_SEQ_ID BIGINT    
 DECLARE @SRM_ENTITY_NAME NVARCHAR(200)    
 DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)    
 DECLARE @DESCRIPTION NVARCHAR(500)    
 DECLARE @DATEMODIFIED DATETIME    
 DECLARE @MODIFIEDBY NVARCHAR(200)    
 DECLARE @DATECREATED DATETIME    
 DECLARE @CREATEDBY NVARCHAR(200)    
    
 SET @ERROR = 1    
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_TITLE]'
    
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME     
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D    
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID    
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID    
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_TITLE'    
    
 SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME     
 FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D    
 WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID    
 AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID    
 AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'TITLE'    
    
 --DELETING EXISTING DATA    
 DELETE FROM [SRM-DataPivot_17].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID    
 DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_CLIENTS_SEQ_ID=@m_CLIENT_SEQ_ID    
 
 DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR     
   SELECT DISTINCT    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_001 DISCRIPTION,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DATE_CREATED,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.CREATED_BY,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DATE_MODIFIED,    
   [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.MODIFIED_BY    
   FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA     
   WHERE [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID     
   AND ISNULL([SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.DELETED,'N')<>'Y'  
   AND [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.SEQ_ID IN(SELECT TEMP2.CUS_ENTITY_DATA_SEQ_ID   
                FROM (SELECT CUS_ENTITY_DATA_SEQ_ID   
                  FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK)   
                  WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID   
                  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 51783   
                  AND ISNULL(ATTRIBUTE_BOOLEAN,'N') = 'Y' --[SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_002 = 'Y' --ACTIVE   
                 ) TEMP1  
                 INNER JOIN [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES TEMP2 WITH(NOLOCK)  
                 ON TEMP2.CUS_ENTITY_DATA_SEQ_ID = TEMP1.CUS_ENTITY_DATA_SEQ_ID  
                 WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID  
                 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 51784   
                 AND ISNULL(ATTRIBUTE_BOOLEAN,'N') = 'Y' --[SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_003 = 'Y' --AVAILABLE ON PORTAL  
               )  
   --AND [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_002 = 'Y'    
   --AND [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA.ATTRIBUTE_003 = 'Y'    
     
 OPEN CUR_RECORDS    
 FETCH NEXT FROM CUR_RECORDS INTO @DESCRIPTION ,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY     
 WHILE @@FETCH_STATUS = 0    
 BEGIN    
  EXEC  [dbo].[GET_INSERT_CUS_ENTITY_DATA]    
   @SRM_CLIENT_ENTITIES_SEQ_ID=@srm_client_entities_seq_id,    
   @ATTRIBUTE_001=@description,    
   @SRM_CLIENTS_SEQ_ID=@m_CLIENT_SEQ_ID,    
   @DATE_CREATED=@DATECREATED,    
   @CREATED_BY=@CREATEDBY,    
   @DATE_MODIFIED=@DateModified,    
   @MODIFIED_BY=@ModifiedBy,    
   @RETURN_SEQ_ID=@new_seq_id output,    
   @ERROR=@ERROR OUTPUT,    
   @ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT    
    
 FETCH NEXT FROM CUR_RECORDS INTO @DESCRIPTION,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY     
 END    
    
 CLOSE CUR_RECORDS    
 DEALLOCATE CUR_RECORDS    
     
 SET @ERROR = 0    
 SET @ERROR_DESCRIPTION = ''    
END 



;






CREATE PROCEDURE [dbo].[GET_PRINT]

@strSQL NVarChar(MAX) 

AS
     
	DECLARE @strTempSQL NVarChar(4000)
	DECLARE @iIndex Int

	SET @iIndex = 0

	WHILE(@iIndex * 4000 < LEN(@strSQL))
	BEGIN
		SET @strTempSQL = SUBSTRING(@strSQL, @iIndex * 4000, 4000)	

		IF RIGHT(@strTempSQL, LEN(@strTempSQL) - (LEN(@strTempSQL) - 1)) = CHAR(13)		
			SET @strTempSQL = LEFT(@strTempSQL, (LEN(@strTempSQL) - 1))	
		
		SET @iIndex = @iIndex + 1			
		PRINT @strTempSQL
		PRINT '#'
	END





;

/*
select * from srm_users where srm_clients_Seq_id  = 5002

declare	@ERROR_NO INT 
declare	@ERROR_DESCRIPTION NVARCHAR(250) 
exec [GET_REPLICATE_FORM_DESIGNER_CHANGES_FOR_ALL_USERS] @SRM_CLIENT_ENTITIES_SEQ_ID = 112718, @SRM_USERS_SEQ_ID = 9990, @SRM_CLIENTS_SEQ_ID = 5002, @ERROR_NO = @ERROR_NO output, @ERROR_DESCRIPTION = @ERROR_DESCRIPTION output
*/
CREATE PROCEDURE [dbo].[GET_REPLICATE_FORM_DESIGNER_CHANGES_FOR_ALL_USERS] 
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT,
	@SRM_USERS_SEQ_ID BIGINT,
	@SRM_CLIENTS_SEQ_ID BIGINT,
	@ERROR_NO INT OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(250) OUTPUT

AS
	DECLARE @CHECK NVARCHAR(5)

	IF ISNULL(@SRM_USERS_SEQ_ID, 0) = 0 OR ISNULL(@SRM_CLIENTS_SEQ_ID, 0) = 0
	BEGIN
		SET @ERROR_NO = -1
		SET @ERROR_DESCRIPTION = 'CLIENT ID OR USER ID IS MISSING.'
		RETURN
	END

	SELECT @CHECK = SUPER_ADMIN FROM SRM_USERS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @SRM_USERS_SEQ_ID

	PRINT @CHECK 
	IF @CHECK IS NULL OR @CHECK <> 'Y'
	BEGIN
		SET @ERROR_NO = -1
		SET @ERROR_DESCRIPTION = 'This user does not have sufficient rights to perform this action.'
		RETURN
	END

	IF ISNULL(@SRM_CLIENT_ENTITIES_SEQ_ID, 0) = 0
	BEGIN
		DECLARE CUR_ENTITIES CURSOR
		FOR
		SELECT SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = 500		
		ORDER BY SEQ_ID
	END
	ELSE 
	BEGIN
		DECLARE CUR_ENTITIES CURSOR
		FOR
		SELECT SEQ_ID FROM SRM_CLIENT_ENTITIES WHERE (SRM_CLIENTS_SEQ_ID = 500 OR SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)
		AND SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID		
		ORDER BY SEQ_ID
	END
	OPEN CUR_ENTITIES 

	FETCH NEXT FROM CUR_ENTITIES INTO @SRM_CLIENT_ENTITIES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF EXISTS(SELECT SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_USERS_SEQ_ID = @SRM_USERS_SEQ_ID)
		BEGIN
			DELETE FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS WHERE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID IN (SELECT SEQ_ID FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_USERS_SEQ_ID IS NULL)-- ISNULL(SRM_USERS_SEQ_ID, 0) <>  @SRM_USERS_SEQ_ID)
			DELETE FROM SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE  SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_USERS_SEQ_ID IS NULL

			UPDATE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS SET SRM_USERS_SEQ_ID = NULL WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND SRM_USERS_SEQ_ID = @SRM_USERS_SEQ_ID
		END

		-- REPLICATE RELATED LISTS
		DELETE FROM SRM_CLIENT_ENTITY_RELATED_LISTS WHERE SEQ_ID IN
		(SELECT SRM_CLIENT_ENTITY_RELATED_LISTS.SEQ_ID 
		FROM SRM_CLIENT_ENTITY_RELATED_LISTS
		INNER JOIN SRM_CLIENT_ENTITIES ON SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES.SEQ_ID
		WHERE 
			SRM_CLIENT_ENTITIES.SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
			AND (SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = 500 OR SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID) AND SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_USERS_SEQ_ID IS NULL
			AND SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)

		INSERT INTO SRM_CLIENT_ENTITY_RELATED_LISTS (SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID2, SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, VISIBLE, RANK, LINK_SUB_RELATED_LISTS, EXPANDABLE_VIEW, SRM_CLIENTS_SEQ_ID)
		SELECT SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID2, SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, SRM_CLIENT_ENTITY_RELATED_LISTS.VISIBLE, RANK, LINK_SUB_RELATED_LISTS, EXPANDABLE_VIEW, @SRM_CLIENTS_SEQ_ID 
		FROM SRM_CLIENT_ENTITY_RELATED_LISTS
		INNER JOIN SRM_CLIENT_ENTITIES ON SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES.SEQ_ID
		WHERE 
			SRM_CLIENT_ENTITIES.SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
			AND (SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = 500 OR SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID) AND SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_USERS_SEQ_ID = @srm_users_seq_id
			AND SRM_CLIENT_ENTITY_RELATED_LISTS.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

		-- REMOVE DUPLICATE RELATED LISTS
		DELETE FROM SRM_CLIENT_ENTITY_RELATED_LISTS  WHERE SEQ_ID IN
		(SELECT MAX(SEQ_ID)
		FROM SRM_CLIENT_ENTITY_RELATED_LISTS 
		WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
			AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
		GROUP BY SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID2, SRM_CLIENTS_SEQ_ID, SRM_USERS_SEQ_ID, isnull(SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, 0), VISIBLE 
		HAVING COUNT(*) > 1)

		FETCH NEXT FROM CUR_ENTITIES INTO @SRM_CLIENT_ENTITIES_SEQ_ID
	END
	CLOSE CUR_ENTITIES 
	DEALLOCATE CUR_ENTITIES 

	UPDATE SRM_CLIENT_PAGE_COMPONENTS SET SRM_USERS_SEQ_ID = NULL WHERE SRM_USERS_SEQ_ID = @SRM_USERS_SEQ_ID AND SRM_CLIENT_PAGE_SECTIONS_SEQ_ID NOT IN (SELECT SRM_CLIENT_PAGE_SECTIONS_SEQ_ID FROM SRM_CLIENT_PAGE_COMPONENTS WHERE SRM_USERS_SEQ_ID IS NULL)
	AND SRM_CLIENT_PAGE_SECTIONS_SEQ_ID IN (SELECT SEQ_ID FROM SRM_CLIENT_PAGE_SECTIONS WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID)

	SET @ERROR_NO = 0
	SET @ERROR_DESCRIPTION = ''




;




CREATE PROCEDURE [dbo].[GET_RETURN_LONGEST_VALUE] 
@INPUT_NAME NVARCHAR(500) = NULL  
,@WFL_OUTPUT_SEQ_ID BIGINT = 0
--,@ERROR NVARCHAR(500) OUTPUT  
AS

DECLARE @LONGEST_NAME NVARCHAR(500) = '' 

IF @WFL_OUTPUT_SEQ_ID > 0
BEGIN  
 SELECT TOP 1 @LONGEST_NAME = case when value is null or value ='' then ' ' else value end FROM dbo.fn_Split(REPLACE(@INPUT_NAME,' ','|'),'|')  
 where value not in (
 'hardware',
 'limited',
 'services',
 'cookshop',
 'the',
 'ltd',
 'associates'
 )
 ORDER BY LEN(value) DESC,idx  
 
 
 UPDATE [SRM-Workflow].dbo.WFL_OUTPUT SET ATTRIBUTE_002=@LONGEST_NAME WHERE SEQ_ID=@WFL_OUTPUT_SEQ_ID
 --SET @OUTPUT_VALUE = @LONGEST_NAME
 
 
END  




;






