-- Author:		<Rauf Gill>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_SEARCH_PIVOT]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT = NULL,
	@ENTITY_DISPLAY_NAME NVARCHAR(100) = NULL,
	@ATTRIBUTE_DISPLAY_NAME NVARCHAR(100) = NULL,
	@OPERATOR_ID SMALLINT = NULL,
	@SEARCH_VALUE NVARCHAR(500) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@RETURN_VALUE NVARCHAR(MAX) OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_SEARCH_PIVOT]'

	DECLARE @DATA_TYPE_ID SMALLINT
	DECLARE @PIVOT_DATA TABLE(CUS_ENTITY_DATA_SEQ_ID BIGINT NOT NULL)

	SET @RETURN_VALUE = ''



	IF ISNULL(@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID, 0) = 0
	BEGIN
		IF ISNULL(@SRM_CLIENT_ENTITIES_SEQ_ID, 0) = 0
		BEGIN
			SELECT @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SEQ_ID 
			FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES 
			WHERE 
				SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
				AND SRM_CLIENT_ENTITIES.SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_CLIENT_ENTITIES_SEQ_ID 
				AND SRM_CLIENT_ENTITIES.ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME 
				AND SRM_CLIENT_ENTITY_ATTRIBUTES.ATTRIBUTE_DISPLAY_NAME = @ATTRIBUTE_DISPLAY_NAME
		END
		ELSE
		BEGIN
			SELECT @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SEQ_ID 
			FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES 
			WHERE 
				SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
				AND SRM_CLIENT_ENTITIES.SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_CLIENT_ENTITIES_SEQ_ID 
				AND SRM_CLIENT_ENTITIES.SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID 
				AND SRM_CLIENT_ENTITY_ATTRIBUTES.ATTRIBUTE_DISPLAY_NAME = @ATTRIBUTE_DISPLAY_NAME
		END
	END

	SELECT @DATA_TYPE_ID = DATA_TYPE_ID FROM [SRM-Framework_New].dbo.SRM_ATTRIBUTE_DATA_TYPES, [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_ATTRIBUTE_DATA_TYPES.SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES.SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID AND SRM_CLIENT_ENTITY_ATTRIBUTES.SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 

	IF @SRM_CLIENTS_SEQ_ID = 17
	BEGIN
		IF @DATA_TYPE_ID IN (1, 3)  -- NUMERIC
		BEGIN
			IF ISNULL(@SEARCH_VALUE, '') = ''
				SET @SEARCH_VALUE = 0
		END
		ELSE IF @DATA_TYPE_ID IN (6, 7, 8) --STRING
		BEGIN
			IF ISNULL(@SEARCH_VALUE, '') = ''
				SET @SEARCH_VALUE = ''
		END
		ELSE IF @DATA_TYPE_ID IN (2) --BOOLEAN
		BEGIN
			IF ISNULL(@SEARCH_VALUE, '') = ''
				SET @SEARCH_VALUE = 'N'
		END

		IF @DATA_TYPE_ID IN (1, 3)  -- NUMERIC
		BEGIN
			IF @OPERATOR_ID = 3 -- EQUALS
			BEGIN
				INSERT INTO @PIVOT_DATA
				(CUS_ENTITY_DATA_SEQ_ID)
				SELECT 
					DISTINCT CUS_ENTITY_DATA_SEQ_ID
					FROM [SRM-DATAPIVOT_17].[dbo].CUS_PIVOT_NON_UNIQUE_INDEXES
					WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
					AND ATTRIBUTE_DECIMAL = @SEARCH_VALUE
			END
		END

		IF @DATA_TYPE_ID IN (6, 7, 8) --STRING
		BEGIN
			IF @OPERATOR_ID = 3 -- EQUALS
			BEGIN
				INSERT INTO @PIVOT_DATA
				(CUS_ENTITY_DATA_SEQ_ID)
				SELECT 
					DISTINCT CUS_ENTITY_DATA_SEQ_ID
					FROM [SRM-DATAPIVOT_17].[dbo].CUS_PIVOT_NON_UNIQUE_INDEXES
					WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
					AND ATTRIBUTE_STRING = @SEARCH_VALUE
			END
		END

		IF @DATA_TYPE_ID IN (2) -- CHECKBOX
		BEGIN
			IF @OPERATOR_ID = 3 -- EQUALS
			BEGIN
				INSERT INTO @PIVOT_DATA
				(CUS_ENTITY_DATA_SEQ_ID)
				SELECT 
					DISTINCT CUS_ENTITY_DATA_SEQ_ID
					FROM [SRM-DATAPIVOT_17].[dbo].CUS_PIVOT_NON_UNIQUE_INDEXES
					WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
					AND ATTRIBUTE_BOOLEAN = @SEARCH_VALUE
			END
		END
	
	END
	ELSE
	BEGIN

		IF @DATA_TYPE_ID IN (1, 3)  -- NUMERIC
		BEGIN
			IF ISNULL(@SEARCH_VALUE, '') = ''
				SET @SEARCH_VALUE = 0
		END
		ELSE IF @DATA_TYPE_ID IN (6, 7, 8) --STRING
		BEGIN
			IF ISNULL(@SEARCH_VALUE, '') = ''
				SET @SEARCH_VALUE = ''
		END
		ELSE IF @DATA_TYPE_ID IN (2) --BOOLEAN
		BEGIN
			IF ISNULL(@SEARCH_VALUE, '') = ''
				SET @SEARCH_VALUE = 'N'
		END

		IF @DATA_TYPE_ID IN (1, 3)  -- NUMERIC
		BEGIN
			IF @OPERATOR_ID = 3 -- EQUALS
			BEGIN
				INSERT INTO @PIVOT_DATA
				(CUS_ENTITY_DATA_SEQ_ID)
				SELECT 
					DISTINCT CUS_ENTITY_DATA_SEQ_ID
					FROM [SRM-DataPivot].[dbo].CUS_PIVOT_NON_UNIQUE_INDEXES
					WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
					AND ATTRIBUTE_DECIMAL = @SEARCH_VALUE
			END
		END

		IF @DATA_TYPE_ID IN (6, 7, 8) --STRING
		BEGIN
			IF @OPERATOR_ID = 3 -- EQUALS
			BEGIN
				INSERT INTO @PIVOT_DATA
				(CUS_ENTITY_DATA_SEQ_ID)
				SELECT 
					DISTINCT CUS_ENTITY_DATA_SEQ_ID
					FROM [SRM-DataPivot].[dbo].CUS_PIVOT_NON_UNIQUE_INDEXES
					WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
					AND ATTRIBUTE_STRING = @SEARCH_VALUE
			END
		END

		IF @DATA_TYPE_ID IN (2) -- CHECKBOX
		BEGIN
			IF @OPERATOR_ID = 3 -- EQUALS
			BEGIN
				INSERT INTO @PIVOT_DATA
				(CUS_ENTITY_DATA_SEQ_ID)
				SELECT 
					DISTINCT CUS_ENTITY_DATA_SEQ_ID
					FROM [SRM-DataPivot].[dbo].CUS_PIVOT_NON_UNIQUE_INDEXES
					WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
					AND ATTRIBUTE_BOOLEAN = @SEARCH_VALUE
			END
		END
	
	END
	
	SELECT @RETURN_VALUE = COALESCE(@RETURN_VALUE + ',', '') + CAST(CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR(20)) FROM @PIVOT_DATA
		INNER JOIN [SRM-CustomEntities].dbo.CUS_ENTITY_DATA ON CUS_ENTITY_DATA_SEQ_ID = CUS_ENTITY_DATA.SEQ_ID AND ISNULL(CUS_ENTITY_DATA.DELETED, 'N') = 'N'
	
	IF @RETURN_VALUE <> '' AND @RETURN_VALUE LIKE '%,%'
		SET @RETURN_VALUE = RIGHT(@RETURN_VALUE, LEN(@RETURN_VALUE) - 1)

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END





;





CREATE PROCEDURE [dbo].[GET_SET_DEFAULT_VIEWS_FOR_GLOBAL_SEARCH]
	@SRM_CLIENTS_SEQ_ID BIGINT
AS
BEGIN
	INSERT INTO SRM_CLIENT_FILTER_VIEW_DEFAULT
		(SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
		SRM_CLIENT_ENTITIES_SEQ_ID,
		SRM_CLIENTS_SEQ_ID,
		SRM_USERS_SEQ_ID,
		DATE_CREATED,
		CREATED_BY,
		DELETED
		)
		SELECT SRM_CLIENT_FILTER_VIEWS_SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENTS_SEQ_ID, SRM_USERS_SEQ_ID, DATE_CREATED, LOGIN_USER_NAME, DELETED
		FROM
		(SELECT
			DISTINCT SRM_CLIENT_FILTER_VIEWS.SEQ_ID SRM_CLIENT_FILTER_VIEWS_SEQ_ID,
			SRM_CLIENT_ENTITIES_SEQ_ID,
			SRM_USERS.SRM_CLIENTS_SEQ_ID,
			SRM_USERS.SEQ_ID SRM_USERS_SEQ_ID,
			GETDATE() DATE_CREATED,
			'SYSTEM' LOGIN_USER_NAME,
			'N' DELETED
		FROM SRM_CLIENT_FILTER_VIEWS 
		INNER JOIN SRM_USERS ON (SRM_USERS.DELETED = 'N' OR SRM_USERS.DELETED IS NULL) AND SRM_USERS.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		INNER JOIN SRM_CLIENT_ENTITIES ON SRM_CLIENT_ENTITIES.SEQ_ID = SRM_CLIENT_FILTER_VIEWS.SRM_CLIENT_ENTITIES_SEQ_ID
		WHERE SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND FILTER_VIEW_TYPE_ID = 4 AND SRM_CLIENT_FILTER_VIEWS.SEQ_ID IN
		(SELECT MIN(SRM_CLIENT_FILTER_VIEWS.SEQ_ID) FROM SRM_CLIENT_FILTER_VIEWS 
		INNER JOIN SRM_CLIENT_ENTITIES ON SRM_CLIENT_ENTITIES.SEQ_ID = SRM_CLIENT_FILTER_VIEWS.SRM_CLIENT_ENTITIES_SEQ_ID
		WHERE FILTER_VIEW_TYPE_ID = 4 AND SRM_CLIENT_ENTITIES.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		GROUP BY SRM_CLIENT_ENTITIES_SEQ_ID)) A
		WHERE  CONVERT(NVARCHAR(20), SRM_USERS_SEQ_ID) + '|' +  CONVERT(NVARCHAR(20), SRM_CLIENT_ENTITIES_SEQ_ID)
		NOT IN (SELECT CONVERT(NVARCHAR(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_USERS_SEQ_ID) + '|' +  CONVERT(NVARCHAR(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_CLIENT_ENTITIES_SEQ_ID)
		FROM SRM_CLIENT_FILTER_VIEW_DEFAULT WHERE SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
		AND CONVERT(NVARCHAR(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_USERS_SEQ_ID) + '|' +  CONVERT(NVARCHAR(20), SRM_CLIENT_FILTER_VIEW_DEFAULT.SRM_CLIENT_ENTITIES_SEQ_ID) IS NOT NULL)
END



;





CREATE PROCEDURE [dbo].[GET_SHOW_MODULE]
@CLIENT_ID BIGINT = 0,
@MODULE NVARCHAR(20) = ''

AS

BEGIN

	DECLARE @SQL NVARCHAR(2000)

	IF @CLIENT_ID > 0 AND @MODULE != ''
	BEGIN 

		--MENU
		UPDATE dbo.SRM_CLIENT_MENU_RELATIONSHIPS SET VISIBLE = 'Y' WHERE SEQ_ID IN (
		SELECT SEQ_ID FROM dbo.SRM_CLIENT_MENU_RELATIONSHIPS AS SCMR WHERE SRM_CLIENTS_SEQ_ID=@CLIENT_ID AND SRM_CLIENT_MENU_RELATIONSHIPS_SEQ_ID = 0 AND VISIBLE='N'
		AND SYSTEM_MODULE  = @MODULE)

		IF (@@ROWCOUNT > 0)
			PRINT 'Menu is shown.'
		ELSE
			PRINT 'Menu is already shown.'

		--RELATED_LISTS
		UPDATE dbo.SRM_CLIENT_ENTITY_RELATED_LISTS SET VISIBLE = 'Y' WHERE SEQ_ID IN (
		SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_RELATED_LISTS AS SCERL WHERE SRM_CLIENT_ENTITIES_SEQ_ID2 IN (SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITIES AS SCE 
		WHERE SRM_CLIENTS_SEQ_ID=@CLIENT_ID AND SYSTEM_MODULE = @MODULE) AND RANK > 0 AND SCERL.VISIBLE = 'N')

		IF (@@ROWCOUNT > 0)
			PRINT 'Related lists are shown.'
		ELSE
			PRINT 'Related lists are already shown.'

		--ATTRIBUTES
		UPDATE dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS SET DELETED='N', DELETED_BY=NULL, DATE_DELETED=NULL WHERE SEQ_ID IN (
		SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS AS SCEAGD WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IN (
		SELECT SCEA.SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA 
		INNER JOIN dbo.SRM_CLIENT_ENTITIES SCE ON SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = SCE.SEQ_ID AND SRM_CLIENTS_SEQ_ID = @CLIENT_ID
		WHERE SCEA.SYSTEM_MODULE= @MODULE AND SCEA.DISPLAY_ATTRIBUTE ='Y' ) AND ISNULL(SCEAGD.DELETED, 'N') = 'Y')

		IF (@@ROWCOUNT > 0)
			PRINT 'Attributes are shown.'
		ELSE
			PRINT 'Attributes are already shown.'

		--Recover module lookup value
		SET @SQL = 'UPDATE [SRM-CustomEntities].dbo.CUS_ENTITY_DATA SET DELETED=''N'', DELETED_BY=NULL, DATE_DELETED=NULL WHERE SEQ_ID IN (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IN (
		SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA WHERE SYSTEM_MODULE=''' + @MODULE + ''' AND SRM_CLIENT_ENTITIES_SEQ_ID IN (
		SELECT SEQ_ID FROM dbo.SRM_CLIENT_ENTITIES AS SCE WHERE SRM_CLIENTS_SEQ_ID=' + CAST(@CLIENT_ID AS NVARCHAR(10)) + ' AND ENTITY_DISPLAY_NAME=''MODULE'')) 
		AND ATTRIBUTE_BOOLEAN=''Y'')
		AND SRM_CLIENTS_SEQ_ID=' + CAST(@CLIENT_ID AS NVARCHAR(10)) + '
		AND DELETED=''Y'' '

		SET @SQL = REPLACE(@SQL,'[SRM-DataPivot]', '[SRM-DataPivot_GO]')
		EXEC (@SQL)

		IF (@@ROWCOUNT > 0)
			PRINT 'Module Lookup record is recovered.'
		ELSE
			PRINT 'Module Lookup record is already recovered.'

		--QUERY_BUILDER
		UPDATE dbo.SRM_CLIENT_ENTITIES SET SHOW_IN_QUERYBUILDER = 'Y' WHERE SRM_CLIENTS_SEQ_ID=@CLIENT_ID AND system_module=@MODULE AND SHOW_IN_QUERYBUILDER='N'
		
		IF (@@ROWCOUNT > 0)
			PRINT 'Module is shown in Query builder.'
		ELSE
			PRINT 'Module is already shown in Query builder.'

	END
	ELSE
		PRINT 'Please provide client id and module to show module details.'  
END


;







