CREATE PROCEDURE [dbo].[GET_SINGLE_ID_DESCRIPTION]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT = NULL,
	@ENTITY_DISPLAY_NAME NVARCHAR(100) = NULL,
	@ATTRIBUTE_DISPLAY_NAME NVARCHAR(100) = NULL,
	@OPERATOR_ID SMALLINT = NULL,
	@SEARCH_VALUE NVARCHAR(100) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT,
	@ID BIGINT = NULL OUTPUT,
	@DESCRIPTION NVARCHAR(100) = NULL OUTPUT,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_SINGLE_ID_DESCRIPTION]'

	DECLARE @PIVOT_RETURN_VALUE NVARCHAR(100)
	

	IF @SRM_CLIENT_ENTITIES_SEQ_ID IS NULL
		SELECT @SRM_CLIENT_ENTITIES_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME

	PRINT 'CALLED FOR ENTITY = ' + ISNULL(@ENTITY_DISPLAY_NAME, '') + ' - ' + CAST(ISNULL(@SRM_CLIENT_ENTITIES_SEQ_ID, 0) AS NVARCHAR) + ': ATTRIBUTE = ' + @ATTRIBUTE_DISPLAY_NAME + ' SEARCH VALUE = ' + @SEARCH_VALUE

	EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID, @ATTRIBUTE_DISPLAY_NAME = @ATTRIBUTE_DISPLAY_NAME, @OPERATOR_ID = @OPERATOR_ID, @SEARCH_VALUE = @SEARCH_VALUE, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT 

	--SELECT @SRM_CLIENT_ENTITIES_SEQ_ID, @ATTRIBUTE_DISPLAY_NAME, DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ',')

	SELECT @ID = DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ',')
	SELECT @DESCRIPTION = ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID AND SEQ_ID = @ID

	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END






;


CREATE FUNCTION [dbo].[GET_SRM_Client_ENTITY_ATTRIBUTES_SEQ_ID](@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT, @ATTRIBUTE_DISPLAY_NAME NVARCHAR(200))
RETURNS BIGINT
AS

BEGIN
DECLARE @SRM_ATTRIBUTES_SEQ_ID BIGINT

SELECT @SRM_ATTRIBUTES_SEQ_ID = SCEA.SEQ_ID 
FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA 
WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID 
AND ATTRIBUTE_DISPLAY_NAME = @ATTRIBUTE_DISPLAY_NAME

RETURN @SRM_ATTRIBUTES_SEQ_ID

END
;


CREATE FUNCTION [dbo].[GET_SRM_ENTITY_ATTRIBUTES_SEQ_ID](@SRM_CLIENT_ENTITIES_SEQ_ID BIGINT, @ATTRIBUTE_DISPLAY_NAME NVARCHAR(200))
RETURNS BIGINT
AS

BEGIN
DECLARE @SRM_ENTITY_ATTRIBUTES_SEQ_ID BIGINT

SELECT @SRM_ENTITY_ATTRIBUTES_SEQ_ID = SRM_ENTITY_ATTRIBUTES_SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA 
WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID AND ATTRIBUTE_DISPLAY_NAME = @ATTRIBUTE_DISPLAY_NAME

RETURN @SRM_ENTITY_ATTRIBUTES_SEQ_ID

END
;







