			SET @Mem_Price = '0.00'

		IF ISNUMERIC(@NON_Mem_Price) = 0 OR @NON_Mem_Price IS NULL
			SET @NON_Mem_Price = '0.00'

		IF ISNUMERIC(@MEMBER_VAT_AMOUNT) = 0 OR @MEMBER_VAT_AMOUNT IS NULL
			SET @MEMBER_VAT_AMOUNT = '0.00'

		IF ISNUMERIC(@NON_MEMBER_VAT_AMOUNT) = 0 OR @NON_MEMBER_VAT_AMOUNT IS NULL
