-- =============================================
CREATE PROCEDURE [dbo].[GET_SYNC_USER_ENTITY]
	-- Add the parameters for the stored procedure here
	@USER_ID BIGINT = NULL,
	@USER_DISPLAY_NAME NVARCHAR(100) = NULL,
	@USER_EMAIL NVARCHAR(512) = NULL,
	@USER_PASSWORD NVARCHAR(512) = NULL,
	@ACTIVE NVARCHAR(1) = NULL,
	@DELETED NVARCHAR(1) = NULL,
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL
	
AS
BEGIN

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @ENTITY_USER_SEQ_ID BIGINT
	DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT
	DECLARE @PIVOT_DB_NAME NVARCHAR(100)
	DECLARE @CUSTOMEENTITY_DB_NAME NVARCHAR(100)
	

	DECLARE @TODATE DateTime
	DECLARE @LIVE_CLIENT CHAR(1)
	SELECT @TODATE = GETDATE()

	DECLARE @ERROR SMALLINT
	DECLARE @ERROR_DESCRIPTION NVARCHAR(200)

	SELECT @LIVE_CLIENT = IS_LIVE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENTS WHERE SEQ_ID = @SRM_CLIENTS_SEQ_ID

	IF ISNULL(@LIVE_CLIENT, 'N') = 'N'
	BEGIN
		RETURN
	END

	SET @PIVOT_DB_NAME = [dbo].[GetClientPivotdatabase](@SRM_CLIENTS_SEQ_ID)
	SET @CUSTOMEENTITY_DB_NAME =  [dbo].[GetClientCustomEntitiesdatabase](@SRM_CLIENTS_SEQ_ID)

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE		
	SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = 'USER'

	-- SET DEFAULT VIEWS FOR GLOBAL SEARCH
	EXEC [dbo].[GET_POPULATE_DEFAULT_VIEWS_FOR_GLOBAL_SEARCH_SINGLE_USER]
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@SRM_USERS_SEQ_ID = @USER_ID
	
	PRINT 'HERE 20180717'
	print @PIVOT_DB_NAME
	print @CUSTOMEENTITY_DB_NAME
	

	If @SRM_CLIENT_ENTITIES_SEQ_ID > 0
	Begin
		PRINT 'HERE 20180717_2'
		SET @CUS_ENTITY_DATA_SEQ_ID = 0
		IF @PIVOT_DB_NAME = '[SRM-DataPivot]' AND @CUSTOMEENTITY_DB_NAME = '[SRM-CustomEntities]'
		BEGIN
			PRINT 'HERE 20180717_3'
			SELECT @CUS_ENTITY_DATA_SEQ_ID = SEQ_ID FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA 
			WHERE 
				SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
				AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
				AND ATTRIBUTE_004 = @USER_ID
		
			IF ISNULL(@CUS_ENTITY_DATA_SEQ_ID, 0) > 0
			BEGIN			
				UPDATE [SRM-CustomEntities].dbo.CUS_ENTITY_DATA SET
				ATTRIBUTE_001 = @USER_DISPLAY_NAME,
				ATTRIBUTE_002 = @USER_EMAIL,
				ATTRIBUTE_003 = @USER_PASSWORD,
				ATTRIBUTE_008 =	@ACTIVE,
				DELETED = @DELETED
				WHERE 
					SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID

				EXEC [SRM-Framework_New].[dbo].[GET_POPULATE_PIVOT_TABLE]
					-- Add the parameters for the stored procedure here
					@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
					@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
					@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
			END
			ELSE
			BEGIN		
				EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]		
					@ATTRIBUTE_001 = @USER_DISPLAY_NAME,
					@ATTRIBUTE_002 = @USER_EMAIL,
					@ATTRIBUTE_003 = @USER_PASSWORD,			
					@ATTRIBUTE_004 = @USER_ID,
					@ATTRIBUTE_008 = @ACTIVE,
			
					@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
					@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
			
					@CREATED_BY = 'web',
					@RETURN_SEQ_ID = @ENTITY_USER_SEQ_ID OUTPUT,
					@ERROR = @ERROR OUTPUT,
					@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

				--EXEC [dbo].[GET_SET_DEFAULT_VIEWS_FOR_GLOBAL_SEARCH]
				--	@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

			End
		END
		ELSE IF @SRM_CLIENTS_SEQ_ID = 66
		BEGIN
			SELECT @CUS_ENTITY_DATA_SEQ_ID = SEQ_ID FROM [SRM-CustomEntities_66].dbo.CUS_ENTITY_DATA 
			WHERE 
				SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID
				AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
				AND ATTRIBUTE_004 = @USER_ID
		
