				ATTRIBUTE_008 =	@ACTIVE,
				DELETED = @DELETED
				WHERE 
					SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID

				EXEC [dbo].[GET_POPULATE_PIVOT_TABLE_FOR_USING_SEPARATE_PIVOT_DB_BY_CLIENT]
					@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
					@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
