					@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
			
					@CREATED_BY = 'web',
					@RETURN_SEQ_ID = @ENTITY_USER_SEQ_ID OUTPUT,
					@ERROR = @ERROR OUTPUT,
					@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

				--EXEC [dbo].[GET_SET_DEFAULT_VIEWS_FOR_GLOBAL_SEARCH]
				--	@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID

			End
		END
		ELSE IF @SRM_CLIENTS_SEQ_ID = 36
		BEGIN
			SELECT @CUS_ENTITY_DATA_SEQ_ID = SEQ_ID FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA 
			WHERE 
