CREATE PROCEDURE [dbo].[GET_UPDATE_DONATION_SUMMARY_FIELDS_ACCOUNT]    
AS    
BEGIN    
	SET NOCOUNT ON;

	DECLARE @SEQ_ID BIGINT
	DECLARE @SEQ_IDs NVARCHAR(4000) 
	DECLARE @LAST_DONATION_DATE NVARCHAR(100)
	DECLARE @LAST_DONATION_AMOUNT NVARCHAR(100)
	DECLARE @DONATION_TO_DATE NVARCHAR(100)
	DECLARE @DONATION_THIS_YEAR NVARCHAR(100)
	DECLARE @SMALLEST_DONATION NVARCHAR(100)
	DECLARE @LARGEST_DONATION NVARCHAR(100)
	DECLARE @AVERAGE_DONATION NVARCHAR(100)
	DECLARE @TOTAL_NUMBER_OF_DONATION NVARCHAR(100)
	DECLARE @MODIFIED_BY NVARCHAR(100)
	DECLARE @DATE_MODIFIED DATETIME

	DECLARE @TODAY_DATE DATE
	DECLARE @YEAR INT
	SET @TODAY_DATE=GETDATE()
	SET @YEAR = YEAR(@TODAY_DATE)
	

	DECLARE CUR_ACCOUNT_CONTACT CURSOR LOCAL STATIC FOR    
	SELECT DISTINCT ATTRIBUTE_010 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
	   WHERE SRM_CLIENTS_SEQ_ID = 48
	   AND SRM_CLIENT_ENTITIES_SEQ_ID=13083 AND SEQ_ID IN (
	   SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_48].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITIES_SEQ_ID=13083 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=288201
	   AND CAST(ATTRIBUTE_DATETIME AS DATE) = @TODAY_DATE UNION
	   SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_48].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITIES_SEQ_ID=13083 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=288199
	   AND CAST(ATTRIBUTE_DATETIME AS DATE) = @TODAY_DATE UNION
	   SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_48].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITIES_SEQ_ID=13083 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=288204
	   AND CAST(ATTRIBUTE_DATETIME AS DATE) = @TODAY_DATE)
	   AND ATTRIBUTE_010 IS NOT NULL --AND ATTRIBUTE_010=67174997	   
   
	  OPEN CUR_ACCOUNT_CONTACT    
    
	  FETCH NEXT FROM CUR_ACCOUNT_CONTACT INTO @SEQ_ID    
    
	  WHILE @@FETCH_STATUS = 0    
	  BEGIN
		SET @SEQ_IDs=''
		--GETTING RECORD_IDS FROM PIVOT
		SELECT @SEQ_IDs = COALESCE(@SEQ_IDs  + ',' ,'') + CAST(W.CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR(100)) FROM  (
		SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT_48].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITIES_SEQ_ID=13083 AND 
		SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=288258 AND
		ATTRIBUTE_DECIMAL = @SEQ_ID) W
		--PRINT @SEQ_IDs
		--GET MODIFIED_BY AND DATE_MODIFIED FROM THE LAST DONATION
		SET @MODIFIED_BY=NULL
		SET @DATE_MODIFIED=NULL

		SELECT TOP 1 
		@MODIFIED_BY = CASE WHEN MODIFIED_BY IS NOT NULL THEN MODIFIED_BY ELSE CREATED_BY END,
		@DATE_MODIFIED = CASE WHEN DATE_MODIFIED IS NOT NULL THEN DATE_MODIFIED ELSE DATE_CREATED END
		FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
		WHERE SRM_CLIENTS_SEQ_ID = 48
		AND SRM_CLIENT_ENTITIES_SEQ_ID=13083 
		AND DELETED='N' 
		AND SEQ_ID IN (SELECT VALUE FROM DBO.FN_SPLIT(@SEQ_IDs, ','))
		ORDER BY SEQ_ID DESC
		
		--LAST DONATION_DATE
		SET @LAST_DONATION_DATE = NULL

		SELECT @LAST_DONATION_DATE = MAX(CAST(ATTRIBUTE_035 AS DATE)) FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
		WHERE SRM_CLIENTS_SEQ_ID = 48
		AND SRM_CLIENT_ENTITIES_SEQ_ID=13083 
		AND DELETED='N' 
		AND SEQ_ID IN (SELECT VALUE FROM DBO.FN_SPLIT(@SEQ_IDs, ','))
	   
	   --LAST_DONATION_AMOUNT
	   SET @LAST_DONATION_AMOUNT = '0.00'

	   SELECT TOP 1 @LAST_DONATION_AMOUNT = ATTRIBUTE_026 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
		WHERE SRM_CLIENTS_SEQ_ID = 48
		AND SRM_CLIENT_ENTITIES_SEQ_ID=13083 
		AND DELETED='N' 
		AND SEQ_ID IN (SELECT VALUE FROM DBO.FN_SPLIT(@SEQ_IDs, ','))
		AND CAST(ATTRIBUTE_035 AS DATE) = @LAST_DONATION_DATE
		ORDER BY SEQ_ID DESC

		--DONATION_THIS_YEAR
		SET @DONATION_THIS_YEAR = '0.00'

		SELECT @DONATION_THIS_YEAR = SUM(CAST(ATTRIBUTE_026 AS MONEY)) FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
		WHERE SRM_CLIENTS_SEQ_ID = 48
		AND SRM_CLIENT_ENTITIES_SEQ_ID=13083 
		AND DELETED='N' 
		AND SEQ_ID IN (SELECT VALUE FROM DBO.FN_SPLIT(@SEQ_IDs, ','))
		AND YEAR(CAST(ATTRIBUTE_035 AS DATE)) = @YEAR

		--DONATION_TO_DATE, SMALLEST_DONATION, LARGEST_DONATION, AVERAGE_DONATION, TOTAL_NUMBER_OF_DONATION
		SET @DONATION_TO_DATE = '0.00'
		SET @SMALLEST_DONATION = '0.00'
		SET @LARGEST_DONATION = '0.00'
		SET @AVERAGE_DONATION = '0.00'
		SET @TOTAL_NUMBER_OF_DONATION = '0'

		SELECT 
		@DONATION_TO_DATE = SUM(CAST(ATTRIBUTE_026 AS MONEY)), 
		@SMALLEST_DONATION = MIN(CAST(ATTRIBUTE_026 AS MONEY)), 
		@LARGEST_DONATION = MAX(CAST(ATTRIBUTE_026 AS MONEY)),
		@AVERAGE_DONATION = AVG(CAST(ATTRIBUTE_026 AS MONEY)),
		@TOTAL_NUMBER_OF_DONATION = COUNT(SEQ_ID)
		FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
		WHERE SRM_CLIENTS_SEQ_ID = 48
		AND SRM_CLIENT_ENTITIES_SEQ_ID=13083 
		AND DELETED='N' 
		AND SEQ_ID IN (SELECT VALUE FROM DBO.FN_SPLIT(@SEQ_IDs, ','))

		UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA SET
		ATTRIBUTE_110=@LAST_DONATION_DATE 
		,ATTRIBUTE_111=@LAST_DONATION_AMOUNT 
		,ATTRIBUTE_112=@DONATION_TO_DATE 
		,ATTRIBUTE_113=@DONATION_THIS_YEAR 
		,ATTRIBUTE_114=@SMALLEST_DONATION 
		,ATTRIBUTE_115=@LARGEST_DONATION 
		,ATTRIBUTE_116=@AVERAGE_DONATION 
		,ATTRIBUTE_117=@TOTAL_NUMBER_OF_DONATION 
		,DATE_MODIFIED = @DATE_MODIFIED
		,MODIFIED_BY = @MODIFIED_BY
		WHERE SEQ_ID = @SEQ_ID AND
		SRM_CLIENT_ENTITIES_SEQ_ID = 12975 AND
		SRM_CLIENTS_SEQ_ID = 48

		--exec [srm-framework_new].dbo.GET_POPULATE_PIVOT_TABLE
		--@SRM_CLIENT_ENTITIES_SEQ_ID = 12975,
		--@CUS_ENTITY_DATA_SEQ_ID = @SEQ_ID,
		--@SRM_CLIENTS_SEQ_ID = 48

		EXEC [SRM-DataPivot_48].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
		-- Add the parameters for the stored procedure here
		@SRM_CLIENT_ENTITIES_SEQ_ID = 12975,
		@CUS_ENTITY_DATA_SEQ_ID = @SEQ_ID,
		@SRM_CLIENTS_SEQ_ID = 48

    
	   FETCH NEXT FROM CUR_ACCOUNT_CONTACT INTO @SEQ_ID    
	  END    
    
	  CLOSE CUR_ACCOUNT_CONTACT    
	  DEALLOCATE CUR_ACCOUNT_CONTACT 
END


;





CREATE PROCEDURE [dbo].[GET_UPDATE_DP_RESULT_NI]
	@m_UCN BIGINT = NULL,
	@m_BASIC_PASSED NVarChar(1) = NULL,
	@m_USER_ID NVarChar(30) = NULL,
	@m_COMPANY_ID NVarChar(10) = NULL,  
	@m_PARM_1 NVarChar(100) = NULL,
	@m_PARM_2 NVarChar(100) = NULL,
	@m_PARM_3 NVarChar(100) = NULL,
	@m_SIMULATOR_PRACTICAL_PASSED NVarChar(1) = NULL,
	@m_COURSE_FLAG NVarChar(1) = NULL,
	@m_ERROR_ID INT OUTPUT,
	@m_ERROR_DESC NVarChar(100) OUTPUT
AS
	DECLARE @ERROR INT
	DECLARE @ERROR_DESCRIPTION NVARCHAR(100)
	DECLARE @STR_SQL NVARCHAR(4000)

	DECLARE @DP_LOG_BOOKS_SEQ_ID BIGINT
	DECLARE @TEMP_DP_LOG_BOOKS_SEQ_ID BIGINT

	DECLARE @CRM_PERSONS_SEQ_ID BIGINT

	DECLARE @TODAY DATETIME

	DECLARE @CONTACT_CLIENT_ENTITY_SEQ_ID BIGINT = 9855
	DECLARE @TITLE_CLIENT_ENTITY BIGINT = 9860
	DECLARE @NATIONALITY_CLIENT_ENTITY BIGINT = 9858
	DECLARE @CONTACT_CLIENT_ENTITY BIGINT = 9855
	DECLARE @GENDER_CLIENT_ENTITY BIGINT = 10005
	DECLARE @GENDER_SEQ_ID BIGINT
	DECLARE @GENDER_DESCRIOTION NVARCHAR(20) 
	DECLARE @CONTACT_LABEL_NAME NVARCHAR(100)
	DECLARE @TEMP_DATE_COMPLETED DATETIME
	DECLARE @TEMP_LOG_BOOK_ID NVARCHAR(100)
	DECLARE @m_DATE_OF_BIRTH DATETIME = NULL
	DECLARE @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID NVARCHAR(5) = 13026
	DECLARE @DP_LOG_BOOK_NO NVARCHAR(100)

	DECLARE @TEMP_CONTACT_SEQ_ID DECIMAL(18,4) = 0

	SET @TODAY = GETDATE()
	SET @m_ERROR_ID = 0
	SET @m_ERROR_DESC = ''	

	IF ISNULL(@m_USER_ID, '') = ''
		SET @m_USER_ID = 'Videotel'


	IF ISNULL(@m_COURSE_FLAG, '') NOT IN ('B', 'S')
	BEGIN
		SET @m_ERROR_ID = -1
		SET @m_ERROR_DESC = 'Invalid Result.'
		SET @m_UCN = -1
	END


	SELECT @CRM_PERSONS_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
		WHERE SRM_CLIENTS_SEQ_ID = 40
			  AND SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_CLIENT_ENTITY 
			  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 212519 
			  AND ATTRIBUTE_STRING = @m_UCN AND DELETED != 'Y'


	SELECT  @CONTACT_LABEL_NAME = LTRIM(RTRIM(ISNULL(ATTRIBUTE_026,'') +' '+ ISNULL(ATTRIBUTE_005,'') + ' ' +ISNULL(ATTRIBUTE_004,''))), 
	@m_DATE_OF_BIRTH = ATTRIBUTE_011, @DP_LOG_BOOK_NO = ISNULL(ATTRIBUTE_186, '0')
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SEQ_ID = @CRM_PERSONS_SEQ_ID

	IF ISNULL(@CRM_PERSONS_SEQ_ID,0) <> 0
	BEGIN 	
		SET @TEMP_CONTACT_SEQ_ID = @CRM_PERSONS_SEQ_ID

		SELECT @DP_LOG_BOOKS_SEQ_ID = CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES 
			WHERE SRM_CLIENTS_SEQ_ID = 40
				  AND SRM_CLIENT_ENTITIES_SEQ_ID = @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID 
				  AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 287021 
				  AND ATTRIBUTE_STRING = @DP_LOG_BOOK_NO AND DELETED != 'Y'
	
		IF ISNULL(@DP_LOG_BOOKS_SEQ_ID, 0) = 0
		BEGIN	
			EXEC [dbo].[GET_INSERT_CUS_ENTITY_DATA]
					@ATTRIBUTE_002 = @CRM_PERSONS_SEQ_ID,
					@ATTRIBUTE_003 = @CONTACT_LABEL_NAME,
					@DATE_CREATED = @TODAY,
					@CREATED_BY = @m_USER_ID,
					@SRM_CLIENT_ENTITIES_SEQ_ID = @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID,
					@SRM_CLIENTS_SEQ_ID = 40,
					@RETURN_SEQ_ID = @DP_LOG_BOOKS_SEQ_ID OUTPUT,
					@ERROR = @m_ERROR_ID OUTPUT
		END

		IF ISNULL(@DP_LOG_BOOKS_SEQ_ID, 0) <> 0
		BEGIN
			IF ISNULL(@m_COURSE_FLAG, '') = 'B'
			BEGIN		
				IF ISNULL(@m_BASIC_PASSED, 'N') NOT IN ('N', 'Y')
				BEGIN
					SET @m_ERROR_ID = -1
					SET @m_ERROR_DESC = 'Invalid Result.'
					SET @m_UCN = -1
				END
				ELSE
				BEGIN
					-- This part is written in place of Part B
					UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA
					SET ATTRIBUTE_006 = @m_BASIC_PASSED,
						MODIFIED_BY   = @m_USER_ID,
						DATE_MODIFIED = @TODAY
					WHERE SEQ_ID = @DP_LOG_BOOKS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID AND SRM_CLIENTS_SEQ_ID = 40

					EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
					@SRM_CLIENT_ENTITIES_SEQ_ID = @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID,
					@CUS_ENTITY_DATA_SEQ_ID = @DP_LOG_BOOKS_SEQ_ID,
					@SRM_CLIENTS_SEQ_ID = 40,
					@ERROR = @m_ERROR_ID OUTPUT,
					@ERROR_DESCRIPTION = @m_ERROR_DESC OUTPUT

				END
			END

	  		IF ISNULL(@m_COURSE_FLAG, '') = 'S'
			BEGIN
				IF ISNULL(@m_SIMULATOR_PRACTICAL_PASSED, 'N') NOT IN ('N', 'Y')
				BEGIN
					SET @m_ERROR_ID = -1
					SET @m_ERROR_DESC = 'Invalid Result.'
					SET @m_UCN = -1
				END
			ELSE
			BEGIN
				-- This Part is written to place Part D
				UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA
				SET ATTRIBUTE_007 = @m_SIMULATOR_PRACTICAL_PASSED,
					MODIFIED_BY   = @m_USER_ID,
					DATE_MODIFIED = @TODAY
				WHERE SEQ_ID = @DP_LOG_BOOKS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID AND SRM_CLIENTS_SEQ_ID = 40

				EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
				@SRM_CLIENT_ENTITIES_SEQ_ID = @CENTRE_LOG_BOOK_CLIENT_ENTITY_SEQ_ID,
				@CUS_ENTITY_DATA_SEQ_ID = @DP_LOG_BOOKS_SEQ_ID,
				@SRM_CLIENTS_SEQ_ID = 40,
				@ERROR = @m_ERROR_ID OUTPUT,
				@ERROR_DESCRIPTION = @m_ERROR_DESC OUTPUT

			END
		END
	END
	ELSE
	BEGIN
		SET @m_ERROR_ID = -1
		SET @m_ERROR_DESC = 'NO RECORD FOUND IN DP_LOG_BOOKS'
	END

	END
	
	EXEC [dbo].[GET_PERSON_DETAILS_NI]
		@m_UCN = @m_UCN,
		@m_USER_ID = @m_USER_ID,
		@m_COMPANY_ID = @m_COMPANY_ID,
		@m_PARM_1 = NULL,
		@m_PARM_2 = NULL,
		@m_PARM_3 = NULL,
		@m_ERROR_ID = @m_ERROR_ID OUTPUT,
		@m_ERROR_DESC = @m_ERROR_DESC OUTPUT



;





CREATE PROCEDURE [dbo].[GET_UPDATE_PRODUCT_QUANTITY_IN_HAND]    
    
@m_CLIENT_SEQ_ID BIGINT,    
@m_PRODUCT_SEQ_ID BIGINT    
    
AS    
    
--EXEC GET_UPDATE_PRODUCT_QUANTITY_IN_HAND    
--@m_CLIENT_SEQ_ID = 17,    
--@m_PRODUCT_SEQ_ID  = 55123119    
    
DECLARE @PRODUCT_SEQ_ID BIGINT    
DECLARE @PRODUCT_ID NVARCHAR(100)    
DECLARE @QUANTITY_IN_HAND_OOMI BIGINT    
    
DECLARE @NEXT_SEQ_ID BIGINT     
DECLARE @MAX_SEQ_ID BIGINT     
    
DECLARE @PIVOT_RETURN_VALUE NVARCHAR(MAX)    
    
    
DECLARE @WEB_SERVICE_PRODUCT_SEQ_ID BIGINT    


SELECT IDENTITY(BIGINT,1,1) AS ROW_ID , cast(cast(PRODUCT.SEQ_ID as varchar(100)) as bigint) AS PRODUCT_SEQ_ID , PRODUCT.ATTRIBUTE_001 AS PRODUCT_ID , PRODUCT.ATTRIBUTE_009 AS QUANTITY_IN_HAND    
INTO #TEMP_PRODUCT    
FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA PRODUCT WITH(NOLOCK)    
WHERE PRODUCT.SRM_CLIENT_ENTITIES_SEQ_ID=2568    
AND PRODUCT.SEQ_ID=@m_PRODUCT_SEQ_ID --IN(SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_17].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID =2568 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID= 52591 AND ATTRIBUTE_STRING=@m_PRODUCT_ID)     
AND ISNULL(PRODUCT.DELETED,'N')='N'    
AND ISNULL(PRODUCT.ATTRIBUTE_039,'N')='Y'     
ORDER BY PRODUCT.SEQ_ID    
    
SET @NEXT_SEQ_ID = 1    
SELECT @MAX_SEQ_ID=MAX(ROW_ID) FROM #TEMP_PRODUCT    
    
print @MAX_SEQ_ID     
    
WHILE @NEXT_SEQ_ID <=@MAX_SEQ_ID    
BEGIN    
     
     
 SELECT @PRODUCT_SEQ_ID = PRODUCT_SEQ_ID , @PRODUCT_ID = PRODUCT_ID ,  @QUANTITY_IN_HAND_OOMI =QUANTITY_IN_HAND     
 FROM #TEMP_PRODUCT WHERE ROW_ID = @NEXT_SEQ_ID    
     
 SET @PIVOT_RETURN_VALUE = NULL    
    
 EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = 2724, @ATTRIBUTE_DISPLAY_NAME = 'PRODUCT_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @PRODUCT_ID, @SRM_CLIENTS_SEQ_ID = 17, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT    
    
 IF ISNULL(@PIVOT_RETURN_VALUE, '') <> ''    
 BEGIN    
  SELECT @WEB_SERVICE_PRODUCT_SEQ_ID = DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ',')    
      
  IF ISNULL(@WEB_SERVICE_PRODUCT_SEQ_ID,0)>0    
  BEGIN    
   UPDATE WEB_SERVICE_PRODUCT    
   SET ATTRIBUTE_015 = @QUANTITY_IN_HAND_OOMI    
   FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA WEB_SERVICE_PRODUCT WITH(NOLOCK)    
   WHERE SEQ_ID = @WEB_SERVICE_PRODUCT_SEQ_ID AND WEB_SERVICE_PRODUCT.SRM_CLIENT_ENTITIES_SEQ_ID=2724    
  END     
      
  PRINT 'WEB_SERVICE_PRODUCT_SEQ_ID  UPDATED = ' + CAST(@WEB_SERVICE_PRODUCT_SEQ_ID AS VARCHAR(500))    
      
 END    
     
     
 SET @NEXT_SEQ_ID = @NEXT_SEQ_ID + 1    
END    
    
DROP TABLE #TEMP_PRODUCT



;





-- =============================================  
-- Author:  <Rauf Gill>  
-- Create date: <08/08/2013,,>  
-- Description: <Apply Product Sales Data to sTarget,,>  
-- =============================================  
CREATE PROCEDURE [dbo].[GET_UPDATE_QUANTITY_IN_HAND_PS]  
 -- Add the parameters for the stored procedure here  
 @PRODUCT_SEQ_ID BIGINT = NULL,  
 @QUANTITY_SOLD BIGINT = NULL,  
 @SRM_CLIENTS_SEQ_ID BIGINT = NULL,  
 @USER NVARCHAR(100) = NULL,  
 @ERROR SMALLINT = NULL OUTPUT,  
 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT  
AS  
BEGIN  
 -- SET NOCOUNT ON added to prevent extra result sets from  
 -- interfering with SELECT statements.  
 SET NOCOUNT ON;  
  
 SET @ERROR = 1  
 SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_UPDATE_QUANTITY_IN_HAND_PS]'  
  
 DECLARE @TODAY NVARCHAR(30)  
 SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)  
  
 DECLARE @PRODUCT_GROUP NVARCHAR(1)  
 DECLARE @PIVOT_RETURN_VALUE NVARCHAR(MAX)  
 DECLARE @PRODUCT_GROUP_QUANTITY BIGINT  
 DECLARE @PRODUCT_ID NVARCHAR(100)  
   
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT BIGINT  
 DECLARE @ENTITY_DISPLAY_NAME_PRODUCT NVARCHAR(100)  
 SET @ENTITY_DISPLAY_NAME_PRODUCT = 'PRODUCT'  
  
 DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_PS BIGINT  
 DECLARE @ENTITY_DISPLAY_NAME_PS NVARCHAR(100)  
 SET @ENTITY_DISPLAY_NAME_PS = 'PRODUCT_SET'  
  
 PRINT '-----H1 ' +  convert(varchar, getdate(), 113)   
 PRINT @PRODUCT_SEQ_ID  
 PRINT @QUANTITY_SOLD  
  
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PRODUCT  
 SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_PS = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_PS  
  
 SELECT @PRODUCT_GROUP = ATTRIBUTE_036, @PRODUCT_ID = ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT AND SEQ_ID = @PRODUCT_SEQ_ID  
  
 IF ISNULL(@PRODUCT_GROUP, 'N') = 'N'  
 BEGIN  
  
  PRINT '-----H2 ' +  convert(varchar, getdate(), 113)   
    
  PRINT @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT  
  PRINT @PRODUCT_SEQ_ID  
  PRINT @SRM_CLIENTS_SEQ_ID  
  
  UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA   
  SET ATTRIBUTE_009 = CAST(CAST(ATTRIBUTE_009 AS MONEY) AS BIGINT) - @QUANTITY_SOLD,  
  DATE_MODIFIED = @TODAY,  
  MODIFIED_BY = @USER  
  WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
  AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT 
  AND SEQ_ID = @PRODUCT_SEQ_ID  
    
  PRINT '-----H3 ' +  convert(varchar, getdate(), 113)   
  
  EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]  
   @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT,  
   @CUS_ENTITY_DATA_SEQ_ID = @PRODUCT_SEQ_ID,  
   @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
   @ERROR = @ERROR OUTPUT,  
   @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
    
  PRINT '-----H4 ' +  convert(varchar, getdate(), 113)   
  --EXEC [dbo].[GET_SYNCH_PRODUCTS]  
  -- @m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
  -- @m_PRODUCT_ID = @PRODUCT_ID  
    
  PRINT '-----H5 ' +  convert(varchar, getdate(), 113)   
    
 END  
 ELSE  
 BEGIN  
  EXEC [dbo].[GET_SEARCH_PIVOT] @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PS, @ATTRIBUTE_DISPLAY_NAME = 'PRODUCT_GROUP', @OPERATOR_ID = 3, @SEARCH_VALUE = @PRODUCT_SEQ_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @RETURN_VALUE = @PIVOT_RETURN_VALUE OUTPUT  
    
  PRINT '-----H6 ' +  convert(varchar, getdate(), 113)   
  DECLARE CUS_PRODUCT_SET CURSOR LOCAL STATIC FOR   
   SELECT ATTRIBUTE_004, ATTRIBUTE_006 
   FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
   WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
   AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PS 
   AND SEQ_ID IN (SELECT DATA FROM [dbo].[fn_StringToTable](@PIVOT_RETURN_VALUE, ','))  
  
  OPEN CUS_PRODUCT_SET  
  
  FETCH NEXT FROM CUS_PRODUCT_SET INTO @PRODUCT_SEQ_ID, @PRODUCT_GROUP_QUANTITY  
    
  PRINT '-----H7 ' +  convert(varchar, getdate(), 113)   
  WHILE @@FETCH_STATUS = 0  
  BEGIN  
   SET @QUANTITY_SOLD = @QUANTITY_SOLD * ISNULL(@PRODUCT_GROUP_QUANTITY, 0)  
  
   UPDATE [SRM-CustomEntities].DBO.CUS_ENTITY_DATA   
    SET ATTRIBUTE_009 = ATTRIBUTE_009 - @QUANTITY_SOLD,  
    DATE_MODIFIED = @TODAY,  
    MODIFIED_BY = @USER  
    WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
    AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT 
    AND SEQ_ID = @PRODUCT_SEQ_ID  
      
   PRINT '-----H8 ' +  convert(varchar, getdate(), 113)   
     
   EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]  
    @SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT,  
    @CUS_ENTITY_DATA_SEQ_ID = @PRODUCT_SEQ_ID,  
    @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
    @ERROR = @ERROR OUTPUT,  
    @ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT  
  
  
   SELECT @PRODUCT_ID = ATTRIBUTE_001 FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA 
   WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
   AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_PRODUCT 
   AND SEQ_ID = @PRODUCT_SEQ_ID  
     
   PRINT '-----H9 ' +  convert(varchar, getdate(), 113)   
     
   --EXEC [dbo].[GET_SYNCH_PRODUCTS]  
   -- @m_CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,  
   -- @m_PRODUCT_ID = @PRODUCT_ID  
      
   PRINT '-----H10 ' +  convert(varchar, getdate(), 113)   
     
   FETCH NEXT FROM CUS_PRODUCT_SET INTO @PRODUCT_SEQ_ID, @PRODUCT_GROUP_QUANTITY  
  END  
  CLOSE CUS_PRODUCT_SET  
  DEALLOCATE CUS_PRODUCT_SET  
 END  
  
 SET @ERROR = 0  
 SET @ERROR_DESCRIPTION = ''  
END  
  
  
  



;





