-- =============================================
CREATE PROCEDURE [dbo].[GET_UPDATE_SRM_CLIENT_REPORTING_SETTINGS]
	-- Add the parameters for the stored procedure here
	@new_client_id BIGINT = 0,
	@TEST BIT = 0
AS

BEGIN

	IF @new_client_id = 0
		RETURN

	DECLARE @SRM_CLIENT_REPORTING_SETTINGS_SEQ_ID bigint

	DECLARE @settings XML
	DECLARE @settings_new NVARCHAR(max)
	DECLARE @client_key NVARCHAR(200)
	DECLARE @Report_Path NVARCHAR(200)
	DECLARE @User_Name NVARCHAR(200)
	DECLARE @Password NVARCHAR(200)
	DECLARE @Report_Path_new NVARCHAR(200)
	DECLARE @User_Name_new NVARCHAR(200)
	DECLARE @Password_new NVARCHAR(200)

	SELECT @SRM_CLIENT_REPORTING_SETTINGS_SEQ_ID = SEQ_ID, @settings = setting from dbo.SRM_CLIENT_REPORTING_SETTINGS WHERE srm_clients_seq_id=@new_client_id
	SELECT @client_key = CLIENT_KEY FROM dbo.SRM_CLIENTS AS SC WHERE SEQ_ID = @new_client_id

	SET @Report_Path_new = '/' + CAST(@new_client_id AS NVARCHAR(10)) + '_' + @client_key
	SELECT @User_Name_new = VALUE FROM [SRM-Framework_New].dbo.fn_Split(@client_key,'-') WHERE idx=0
	SELECT @Password_new = RIGHT(VALUE,8) + '@' FROM [SRM-Framework_New].dbo.fn_Split(@client_key,'-') WHERE idx=4 

	IF @settings IS NOT NULL
	BEGIN
		SELECT @Report_Path = RTRIM(LTRIM(REPLACE(REPLACE((@settings.value('((//Reports/Settings)/node())[8]', 'NVARCHAR(MAX)')), CHAR(10), ''), CHAR(13), '')))
		SELECT @User_Name = RTRIM(LTRIM(REPLACE(REPLACE((@settings.value('((//Reports/Settings)/node())[10]', 'NVARCHAR(MAX)')), CHAR(10), ''), CHAR(13), '')))
		SELECT @Password = RTRIM(LTRIM(REPLACE(REPLACE((@settings.value('((//Reports/Settings)/node())[12]', 'NVARCHAR(MAX)')), CHAR(10), ''), CHAR(13), '')))		


		SELECT @settings_new = REPLACE(REPLACE(REPLACE(SETTING,@Report_Path, @Report_Path_new),@user_name, @User_Name_new), @Password, @Password_new) FROM 
		SRM_CLIENT_REPORTING_SETTINGS WHERE SEQ_ID=@SRM_CLIENT_REPORTING_SETTINGS_SEQ_ID

		IF @TEST = 1
		BEGIN
			PRINT 'OLD SETTING: ' + CAST(@settings AS NVARCHAR(MAX))
			PRINT 'NEW SETTING: ' + @settings_new 
		END
		ELSE IF @TEST = 0 AND @settings_new IS NOT NULL
			UPDATE SRM_CLIENT_REPORTING_SETTINGS SET SETTING = @settings_new WHERE SEQ_ID = @SRM_CLIENT_REPORTING_SETTINGS_SEQ_ID
	END
END



;





