-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[GET_UPDATE_SRM_DASHBOARD_COLUMNS]
	-- Add the parameters for the stored procedure here
	@new_client_id BIGINT = 0,
	@TEST BIT = 0
AS

BEGIN

	IF @new_client_id = 0
		RETURN

	DECLARE @SRM_DASHBOARD_COLUMNS_SEQ_ID bigint

	DECLARE @settings XML
	DECLARE @settings_new NVARCHAR(max)
	DECLARE @client_key NVARCHAR(200)
	DECLARE @Report_Path NVARCHAR(200)
	DECLARE @User_Name NVARCHAR(200)
	DECLARE @Password NVARCHAR(200)
	DECLARE @Report_Path_new NVARCHAR(200)
	DECLARE @User_Name_new NVARCHAR(200)
	DECLARE @Password_new NVARCHAR(200)	


	SELECT @client_key = CLIENT_KEY FROM dbo.SRM_CLIENTS AS SC WHERE SEQ_ID = @new_client_id

	SET @Report_Path_new = '/' + CAST(@new_client_id AS NVARCHAR(10)) + '_' + @client_key
	SELECT @User_Name_new = VALUE FROM [SRM-Framework_New].dbo.fn_Split(@client_key,'-') WHERE idx=0
	SELECT @Password_new = RIGHT(VALUE,8) + '@' FROM [SRM-Framework_New].dbo.fn_Split(@client_key,'-') WHERE idx=4 

  
  
  
	DECLARE curGeneral CURSOR LOCAL STATIC FOR 
	SELECT SEQ_ID, SETTINGS FROM dbo.SRM_DASHBOARD_COLUMNS AS SDC WHERE SRM_DASHBOARD_ROWS_SEQ_ID IN 
	(SELECT SEQ_ID FROM dbo.SRM_DASHBOARD_ROWS AS SDR WHERE SRM_DASHBOARDS_SEQ_ID IN 
	(SELECT SEQ_ID FROM dbo.SRM_DASHBOARDS AS SD WHERE SRM_CLIENTS_SEQ_ID=@new_client_id)) AND SETTINGS IS NOT NULL
   
	OPEN curGeneral                                                             
	FETCH NEXT FROM curGeneral INTO @SRM_DASHBOARD_COLUMNS_SEQ_ID,  @settings

	WHILE (@@Fetch_Status = 0)       
	BEGIN        

		IF @settings IS NOT NULL
		BEGIN
			SELECT @Report_Path = RTRIM(LTRIM(REPLACE(REPLACE((@settings.value('((//Reports/Settings/Setting_Value)/node())[2]', 'NVARCHAR(MAX)')), CHAR(10), ''), CHAR(13), '')))
			SELECT @User_Name = RTRIM(LTRIM(REPLACE(REPLACE((@settings.value('((//Reports/Settings/Setting_Value)/node())[3]', 'NVARCHAR(MAX)')), CHAR(10), ''), CHAR(13), '')))
			SELECT @Password = RTRIM(LTRIM(REPLACE(REPLACE((@settings.value('((//Reports/Settings/Setting_Value)/node())[4]', 'NVARCHAR(MAX)')), CHAR(10), ''), CHAR(13), '')))	
			--remove report name from the path
			SELECT @Report_Path = '/'+VALUE FROM [SRM-Framework_New].dbo.fn_Split(@Report_Path,'/') AS FS WHERE idx=1
			
			SELECT @settings_new = REPLACE(REPLACE(REPLACE(CAST(SETTINGS AS NVARCHAR(MAX)),@Report_Path, @Report_Path_new),@user_name, @User_Name_new), @Password, @Password_new) FROM 
			SRM_DASHBOARD_COLUMNS WHERE SEQ_ID=@SRM_DASHBOARD_COLUMNS_SEQ_ID			

			IF @TEST = 1
			BEGIN
				PRINT '----------------------------'
				PRINT CAST(@settings AS NVARCHAR(MAX))
				PRINT '----------------------------'
				PRINT @settings_new
			END
			ELSE IF @TEST = 0 AND @settings_new IS NOT NULL
				UPDATE SRM_DASHBOARD_COLUMNS SET SETTINGs = @settings_new WHERE SEQ_ID = @SRM_DASHBOARD_COLUMNS_SEQ_ID
		END

		FETCH NEXT FROM curGeneral INTO @SRM_DASHBOARD_COLUMNS_SEQ_ID,  @settings
	END    
   
	CLOSE curGeneral                           
	DEALLOCATE curGeneral    

END



;




-- =============================================
-- Author:		<Abdul Rauf Gill>
-- Create date: <18/06/2019>
-- Description:	<Update Total Outstanding on Member screen from Member Assigned Rates>
-- =============================================
CREATE PROCEDURE [dbo].[GET_UPDATE_TOTAL_OUTSTANDING_ON_MEMBER_FROM_MAR_CLIENTS_WITH_STANDARD_CUSTOM_ENTITY]
	@SRM_CLIENTS_SEQ_ID bigint
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @Member BIGINT 
	DECLARE @Balance MONEY
	DECLARE @Mem_Balance MONEY
	DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT

	DECLARE @EN_MEMBER_ASSIGNED_RATE BIGINT = [SRM-DataConversion].[DBO].[GET_SRM_CLIENT_ENTITIES_SEQ_ID]('MEMBER_ASSIGNED_RATE', @SRM_CLIENTS_SEQ_ID)
	DECLARE @EN_MEMBER BIGINT = [SRM-DataConversion].[DBO].[GET_SRM_CLIENT_ENTITIES_SEQ_ID]('MEMBER', @SRM_CLIENTS_SEQ_ID)

	DECLARE CurGeneral CURSOR LOCAL STATIC FOR
	SELECT MAR.ATTRIBUTE_002,SUM(CAST(MAR.ATTRIBUTE_019 AS MONEY)) FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA AS MEM
	INNER JOIN [SRM-CustomEntities].dbo.CUS_ENTITY_DATA AS MAR ON MAR.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_MEMBER_ASSIGNED_RATE AND MAR.ATTRIBUTE_002 = Mem.SEQ_ID AND mar.DELETED != 'Y'
	WHERE MEM.SRM_CLIENT_ENTITIES_SEQ_ID = @EN_MEMBER AND MEM.DELETED != 'Y' --AND CAST(MAR.ATTRIBUTE_019 AS MONEY) > 0
	GROUP BY MAR.ATTRIBUTE_002

	OPEN CurGeneral
	FETCH NEXT FROM CurGeneral INTO @Member,@Balance
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SELECT @Mem_Balance = ATTRIBUTE_044 FROM [SRM-CustomEntities].dbo.CUS_ENTITY_DATA AS ced WHERE SEQ_ID = @Member
		IF ISNULL(@Balance, 0) != ISNULL(@Mem_Balance, 0)
		BEGIN
			UPDATE [SRM-CustomEntities].dbo.CUS_ENTITY_DATA SET ATTRIBUTE_044 = @Balance WHERE SEQ_ID = @Member
		END 
		SET @Mem_Balance = 0 
		SET @Balance = 0

		FETCH NEXT FROM CurGeneral INTO @Member,@Balance
	END
	CLOSE CurGeneral
	DEALLOCATE CurGeneral

	SELECT @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SEQ_ID FROM [SRM-Framework_New]..SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @EN_MEMBER AND ATTRIBUTE_DISPLAY_NAME = 'TOTAL_OUTSTANDING'

	EXEC [SRM-Framework_New].dbo.GET_POPULATE_PIVOT_TABLE_UPDATE_DATA_FOR_SINGLE_ATTRIBUTE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
END



;





CREATE PROCEDURE [dbo].[GET_VAT_AMOUNT_USING_BREAKDOWN]      
  @m_MEMBER_RATE_TYPE_SEQ_ID BigInt,      
  @m_AMOUNT Money,      
  @m_CLIENT_SEQ_ID BIGINT,      
  @m_VAT_AMOUNT Money OUTPUT,      
  @m_NET_AMOUNT Money OUTPUT,      
  @ERROR SMALLINT = NULL OUTPUT,      
  @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT      
AS      
 DECLARE @VAT_APPLICABLE CHAR(1)      
 DECLARE @VAT_INCLUDED CHAR(1)      
 DECLARE @AMOUNT_PERCENTAGE Money      
 DECLARE @TAXABLE_AMOUNT Money      
 DECLARE @VAT_PERCENTAGE Money      
       
 SET @m_VAT_AMOUNT = 0      
       
       
 SELECT @VAT_APPLICABLE = ISNULL(ATTRIBUTE_002, 'N'), @VAT_INCLUDED = ISNULL(ATTRIBUTE_005, 'N')     
 FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA VAT_RATE WITH(NOLOCK)    
 WHERE VAT_RATE.SRM_CLIENT_ENTITIES_SEQ_ID = 2546     
 AND SEQ_ID =  @m_MEMBER_RATE_TYPE_SEQ_ID      
       
 IF @VAT_APPLICABLE = 'Y'  
 BEGIN      
       
 DECLARE curBreakdown CURSOR FOR      
 SELECT VAT_BREAKDOWN.ATTRIBUTE_003 AMOUNT_PERCENTAGE, VAT_RATE.ATTRIBUTE_006 VAT_PERCENTAGE      
 FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA VAT_BREAKDOWN  WITH(NOLOCK)    
 INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA VAT_RATE WITH(NOLOCK) ON VAT_RATE.SRM_CLIENT_ENTITIES_SEQ_ID = 2555   
 AND VAT_BREAKDOWN.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2784 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 57055 AND ATTRIBUTE_DECIMAL = VAT_RATE.SEQ_ID) --ATTRIBUTE_005 = VAT_RATE.SEQ_ID       
 WHERE VAT_BREAKDOWN.SRM_CLIENT_ENTITIES_SEQ_ID = 2784   
 AND VAT_BREAKDOWN.SEQ_ID IN(SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_17]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2784 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 58268 AND ATTRIBUTE_DECIMAL = @m_MEMBER_RATE_TYPE_SEQ_ID)--ATTRIBUTE_007  @m_MEMBER_RATE_TYPE_SEQ_ID   
 AND ISNULL(VAT_BREAKDOWN.DELETED,'N')<>'Y'   
        
  OPEN curBreakdown      
        
  FETCH NEXT FROM curBreakdown INTO @AMOUNT_PERCENTAGE, @VAT_PERCENTAGE      
        
  WHILE (@@FETCH_STATUS = 0)      
  BEGIN      
        
   SET @TAXABLE_AMOUNT = ROUND(@m_AMOUNT * @AMOUNT_PERCENTAGE / 100, 2)      
         
   IF @VAT_INCLUDED = 'Y'      
         
    SET @m_VAT_AMOUNT = @m_VAT_AMOUNT + ROUND(CAST((@TAXABLE_AMOUNT * @VAT_PERCENTAGE) / (@VAT_PERCENTAGE + 100) AS Money), 2)      
         
   ELSE      
    SET @m_VAT_AMOUNT = @m_VAT_AMOUNT + ROUND(CAST(@TAXABLE_AMOUNT * @VAT_PERCENTAGE / 100 AS Money), 2)      
        
   FETCH NEXT FROM curBreakdown INTO @AMOUNT_PERCENTAGE, @VAT_PERCENTAGE      
  END      
  CLOSE curBreakdown      
  DEALLOCATE curBreakdown      
        
  IF @VAT_INCLUDED = 'Y'      
   SET @m_NET_AMOUNT = @m_AMOUNT - @m_VAT_AMOUNT      
  ELSE      
   SET @m_NET_AMOUNT = @m_AMOUNT      
 END 



;






CREATE PROCEDURE [dbo].[GET_WORKFLOW_DETAILS]
@SRM_CLIENT_ENTITY_SEQ_ID BIGINT = 0,  
@WFL_WORKFLOWS_SEQ_ID BIGINT = 0,   
@TYPE NVARCHAR(50) = ''

AS

--EXEC [dbo].[GET_WORKFLOW_DETAILS] @SRM_CLIENT_ENTITY_SEQ_ID=9855,@WFL_WORKFLOWS_SEQ_ID=0,@TYPE='WORKFLOW_BY_ENTITY'
--EXEC [dbo].[GET_WORKFLOW_DETAILS] @SRM_CLIENT_ENTITY_SEQ_ID=0,@WFL_WORKFLOWS_SEQ_ID=9626,@TYPE='PARENT_WORKFLOW'
--EXEC [dbo].[GET_WORKFLOW_DETAILS] @SRM_CLIENT_ENTITY_SEQ_ID=0,@WFL_WORKFLOWS_SEQ_ID=9232,@TYPE='CHILD_WORKFLOW'

BEGIN
--WORKFLOW OF GIVEN ENTITY
	IF @SRM_CLIENT_ENTITY_SEQ_ID > 0
	BEGIN
		SELECT * FROM (
		SELECT 
		1 RETURN_TYPE_ID
		,ISNULL(SCE.SEQ_ID,0) SRM_CLIENT_ENTITIES_SEQ_ID
		,ISNULL(SCE.ENTITY_DISPLAY_NAME,'') ENTITY_DISPLAY_NAME
		,WW.SEQ_ID WFL_WORKFLOW_SEQ_ID
		,ISNULL(WW.DESCRIPTION,'') [WORKFLOW_DESCRIPTION]
		,CASE WHEN WWSOA.SEQ_ID > 0 THEN 'Y' ELSE 'N' END [ADD]
		,CASE WHEN WWSOE.SEQ_ID > 0 THEN 'Y' ELSE 'N' END [EDIT]
		,CASE WHEN WWSOD.SEQ_ID > 0 THEN 'Y' ELSE 'N' END [DELETE]
		,ISNULL(WW.ALWAYS_TRIGGER, 'N') ALWAYS_TRIGGER
		,ISNULL(WW.AVAILABLE_FOR_TEMPLATES, 'N') AVAILABLE_FOR_TEMPLATES
		,ISNULL(WW.IS_ASYNC, 'Y') IS_ASYNC
		,ISNULL(WW.SHOW_IN_JOBS, 'N') SHOW_IN_JOBS
		,ISNULL(WW.SHOW_ON_QUERYBUILDER, 'N') SHOW_ON_QUERYBUILDER
		,CASE WHEN EXISTS (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS HP WHERE HP.TASK_TYPE_ID = 1 AND HP.WFL_WORKFLOWS_SEQ_ID2 = WW.SEQ_ID ) THEN 'Y' ELSE 'N' END HAS_PARENT_WORKFLOW
		,CASE WHEN EXISTS (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS HC WHERE HC.TASK_TYPE_ID = 1 AND HC.WFL_WORKFLOWS_SEQ_ID = WW.SEQ_ID AND HC.WFL_WORKFLOWS_SEQ_ID2 IS NOT NULL) THEN 'Y' ELSE 'N' END HAS_CHILD_WORKFLOW
		FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE
		INNER JOIN [SRM-Workflow].dbo.WFL_WORKFLOWS AS WW ON SCE.SEQ_ID = ww.SRM_CLIENT_ENTITY_SEQ_ID
		LEFT OUTER JOIN [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS AS WWSOA ON WW.SEQ_ID = WWSOA.WFL_WORKFLOWS_SEQ_ID AND WWSOA.START_WHEN_ID = 3
		LEFT OUTER JOIN [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS AS WWSOE ON ww.SEQ_ID = WWSOE.WFL_WORKFLOWS_SEQ_ID AND WWSOE.START_WHEN_ID = 4
		LEFT OUTER JOIN [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS AS WWSOD ON ww.SEQ_ID = WWSOD.WFL_WORKFLOWS_SEQ_ID AND WWSOD.START_WHEN_ID = 5
		WHERE SCE.SEQ_ID = @SRM_CLIENT_ENTITY_SEQ_ID) AS WORKFLOWS_BY_ENTITY
		UNION
		--BLANK ROW FOR PARENTWORKFLOW
		SELECT * FROM (
		SELECT 2 RETURN_TYPE_ID, 0 SRM_CLIENT_ENTITIES_SEQ_ID ,'' ENTITY_DISPLAY_NAME ,0 WFL_WORKFLOW_SEQ_ID, ''  [WORKFLOW_DESCRIPTION],'N' [ADD]
		,'N' [EDIT],'N' [DELETE],'N' ALWAYS_TRIGGER,'N' AVAILABLE_FOR_TEMPLATES,'Y' IS_ASYNC,'N' SHOW_IN_JOBS,'N' SHOW_ON_QUERYBUILDER
		,'N' HAS_PARENT_WORKFLOW,'N' HAS_CHILD_WORKFLOW WHERE 1=2) PARENTWORKFLOW
		UNION
		--BLANK ROW FOR CHILDWORKFLOW
		SELECT * FROM (
		SELECT 3 RETURN_TYPE_ID, 0 SRM_CLIENT_ENTITIES_SEQ_ID ,'' ENTITY_DISPLAY_NAME ,0 WFL_WORKFLOW_SEQ_ID, ''  [WORKFLOW_DESCRIPTION],'N' [ADD]
		,'N' [EDIT],'N' [DELETE],'N' ALWAYS_TRIGGER,'N' AVAILABLE_FOR_TEMPLATES,'Y' IS_ASYNC,'N' SHOW_IN_JOBS,'N' SHOW_ON_QUERYBUILDER
		,'N' HAS_PARENT_WORKFLOW,'N' HAS_CHILD_WORKFLOW WHERE 1=2) CHILDWORKFLOW

		
	END
		--PARENT WORKFLOWS OF GIVEN WORKFLOW
	ELSE IF @WFL_WORKFLOWS_SEQ_ID > 0
	BEGIN
		--BLANK ROW FOR ENTITY
		SELECT * FROM (
		SELECT 1 RETURN_TYPE_ID, 0 SRM_CLIENT_ENTITIES_SEQ_ID ,'' ENTITY_DISPLAY_NAME ,0 WFL_WORKFLOW_SEQ_ID, ''  [WORKFLOW_DESCRIPTION],'N' [ADD]
		,'N' [EDIT],'N' [DELETE],'N' ALWAYS_TRIGGER,'N' AVAILABLE_FOR_TEMPLATES,'Y' IS_ASYNC,'N' SHOW_IN_JOBS,'N' SHOW_ON_QUERYBUILDER
		,'N' HAS_PARENT_WORKFLOW,'N' HAS_CHILD_WORKFLOW WHERE 1=2) AS WORKFLOWS_BY_ENTITY
		UNION
		SELECT * FROM (
		SELECT 
		2 RETURN_TYPE_ID
		,ISNULL(SCE.SEQ_ID,0) SRM_CLIENT_ENTITIES_SEQ_ID
		,ISNULL(SCE.ENTITY_DISPLAY_NAME,'') ENTITY_DISPLAY_NAME
		,WW.SEQ_ID WFL_WORKFLOW_SEQ_ID
		,ISNULL(WW.DESCRIPTION,'') [WORKFLOW_DESCRIPTION]
		,CASE WHEN WWSOA.SEQ_ID > 0 THEN 'Y' ELSE 'N' END [ADD]
		,CASE WHEN WWSOE.SEQ_ID > 0 THEN 'Y' ELSE 'N' END [EDIT]
		,CASE WHEN WWSOD.SEQ_ID > 0 THEN 'Y' ELSE 'N' END [DELETE]
		,ISNULL(WW.ALWAYS_TRIGGER, 'N') ALWAYS_TRIGGER
		,ISNULL(WW.AVAILABLE_FOR_TEMPLATES, 'N') AVAILABLE_FOR_TEMPLATES
		,ISNULL(WW.IS_ASYNC, 'Y') IS_ASYNC
		,ISNULL(WW.SHOW_IN_JOBS, 'N') SHOW_IN_JOBS
		,ISNULL(WW.SHOW_ON_QUERYBUILDER, 'N') SHOW_ON_QUERYBUILDER
		,CASE WHEN EXISTS (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS HP WHERE HP.TASK_TYPE_ID = 1 AND HP.WFL_WORKFLOWS_SEQ_ID2 = WW.SEQ_ID ) THEN 'Y' ELSE 'N' END HAS_PARENT_WORKFLOW
		,CASE WHEN EXISTS (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS HC WHERE HC.TASK_TYPE_ID = 1 AND HC.WFL_WORKFLOWS_SEQ_ID = WW.SEQ_ID AND HC.WFL_WORKFLOWS_SEQ_ID2 IS NOT NULL) THEN 'Y' ELSE 'N' END HAS_CHILD_WORKFLOW
		FROM [SRM-Workflow].dbo.WFL_WORKFLOWS AS WW 
		LEFT OUTER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE ON ww.SRM_CLIENT_ENTITY_SEQ_ID = SCE.SEQ_ID 
		LEFT OUTER JOIN [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS AS WWSOA ON WW.SEQ_ID = WWSOA.WFL_WORKFLOWS_SEQ_ID AND WWSOA.START_WHEN_ID = 3
		LEFT OUTER JOIN [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS AS WWSOE ON ww.SEQ_ID = WWSOE.WFL_WORKFLOWS_SEQ_ID AND WWSOE.START_WHEN_ID = 4
		LEFT OUTER JOIN [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS AS WWSOD ON ww.SEQ_ID = WWSOD.WFL_WORKFLOWS_SEQ_ID AND WWSOD.START_WHEN_ID = 5
		WHERE WW.SEQ_ID IN (SELECT WFL_WORKFLOWS_SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE TASK_TYPE_ID = 1 AND WFL_WORKFLOWS_SEQ_ID2 = @WFL_WORKFLOWS_SEQ_ID 
		AND WFL_WORKFLOWS_SEQ_ID IS NOT NULL)) PARENTWORKFLOW
		UNION		
		SELECT * FROM (
		SELECT 
		3 RETURN_TYPE_ID
		,ISNULL(SCE.SEQ_ID,0) SRM_CLIENT_ENTITIES_SEQ_ID
		,ISNULL(SCE.ENTITY_DISPLAY_NAME,'') ENTITY_DISPLAY_NAME 
		,WW.SEQ_ID WFL_WORKFLOW_SEQ_ID
		,ISNULL(WW.DESCRIPTION,'') [WORKFLOW_DESCRIPTION]
		,CASE WHEN WWSOA.SEQ_ID > 0 THEN 'Y' ELSE 'N' END [ADD]
		,CASE WHEN WWSOE.SEQ_ID > 0 THEN 'Y' ELSE 'N' END [EDIT]
		,CASE WHEN WWSOD.SEQ_ID > 0 THEN 'Y' ELSE 'N' END [DELETE]
		,ISNULL(WW.ALWAYS_TRIGGER, 'N') ALWAYS_TRIGGER
		,ISNULL(WW.AVAILABLE_FOR_TEMPLATES, 'N') AVAILABLE_FOR_TEMPLATES
		,ISNULL(WW.IS_ASYNC, 'Y') IS_ASYNC
		,ISNULL(WW.SHOW_IN_JOBS, 'N') SHOW_IN_JOBS
		,ISNULL(WW.SHOW_ON_QUERYBUILDER, 'N') SHOW_ON_QUERYBUILDER
		,CASE WHEN EXISTS (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS HP WHERE HP.TASK_TYPE_ID = 1 AND HP.WFL_WORKFLOWS_SEQ_ID2 = WW.SEQ_ID ) THEN 'Y' ELSE 'N' END HAS_PARENT_WORKFLOW
		,CASE WHEN EXISTS (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS HC WHERE HC.TASK_TYPE_ID = 1 AND HC.WFL_WORKFLOWS_SEQ_ID = WW.SEQ_ID AND HC.WFL_WORKFLOWS_SEQ_ID2 IS NOT NULL) THEN 'Y' ELSE 'N' END HAS_CHILD_WORKFLOW
		FROM [SRM-Workflow].dbo.WFL_WORKFLOWS AS WW 
		LEFT OUTER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE ON ww.SRM_CLIENT_ENTITY_SEQ_ID = SCE.SEQ_ID 
		LEFT OUTER JOIN [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS AS WWSOA ON WW.SEQ_ID = WWSOA.WFL_WORKFLOWS_SEQ_ID AND WWSOA.START_WHEN_ID = 3
		LEFT OUTER JOIN [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS AS WWSOE ON ww.SEQ_ID = WWSOE.WFL_WORKFLOWS_SEQ_ID AND WWSOE.START_WHEN_ID = 4
		LEFT OUTER JOIN [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS AS WWSOD ON ww.SEQ_ID = WWSOD.WFL_WORKFLOWS_SEQ_ID AND WWSOD.START_WHEN_ID = 5
		WHERE WW.SEQ_ID IN (SELECT WFL_WORKFLOWS_SEQ_ID2 FROM [SRM-Workflow].dbo.WFL_TASKS WHERE TASK_TYPE_ID = 1 AND WFL_WORKFLOWS_SEQ_ID = @WFL_WORKFLOWS_SEQ_ID 
		AND WFL_WORKFLOWS_SEQ_ID2 IS NOT NULL)) CHILDWORKFLOW
	END 
	ELSE
	BEGIN
		--BLANK ROW FOR ENTITY  
		--SELECT * FROM (
		SELECT 1 RETURN_TYPE_ID, 0 SRM_CLIENT_ENTITIES_SEQ_ID ,'' ENTITY_DISPLAY_NAME ,0 WFL_WORKFLOW_SEQ_ID, ''  [WORKFLOW_DESCRIPTION],'N' [ADD]
		,'N' [EDIT],'N' [DELETE],'N' ALWAYS_TRIGGER,'N' AVAILABLE_FOR_TEMPLATES,'Y' IS_ASYNC,'N' SHOW_IN_JOBS,'N' SHOW_ON_QUERYBUILDER
		,'N' HAS_PARENT_WORKFLOW,'N' HAS_CHILD_WORKFLOW WHERE 1=2--) AS WORKFLOWS_BY_ENTITY

		----BLANK ROW FOR PARENTWORKFLOW
		--SELECT * FROM (
		--SELECT 2 RETURN_TYPE_ID, 0 SRM_CLIENT_ENTITIES_SEQ_ID ,'' ENTITY_DISPLAY_NAME ,0 WFL_WORKFLOW_SEQ_ID, ''  [WORKFLOW_DESCRIPTION],'N' [ADD]
		--,'N' [EDIT],'N' [DELETE],'N' ALWAYS_TRIGGER,'N' AVAILABLE_FOR_TEMPLATES,'Y' IS_ASYNC,'N' SHOW_IN_JOBS,'N' SHOW_ON_QUERYBUILDER
		--,'N' HAS_PARENT_WORKFLOW,'N' HAS_CHILD_WORKFLOW WHERE 1=2) PARENTWORKFLOW

		----BLANK ROW FOR CHILDWORKFLOW
		--SELECT * FROM (
		--SELECT 3 RETURN_TYPE_ID, 0 SRM_CLIENT_ENTITIES_SEQ_ID ,'' ENTITY_DISPLAY_NAME ,0 WFL_WORKFLOW_SEQ_ID, ''  [WORKFLOW_DESCRIPTION],'N' [ADD]
		--,'N' [EDIT],'N' [DELETE],'N' ALWAYS_TRIGGER,'N' AVAILABLE_FOR_TEMPLATES,'Y' IS_ASYNC,'N' SHOW_IN_JOBS,'N' SHOW_ON_QUERYBUILDER
		--,'N' HAS_PARENT_WORKFLOW,'N' HAS_CHILD_WORKFLOW WHERE 1=2) CHILDWORKFLOW
	END  
		  
END



;

CREATE FUNCTION [dbo].[GET_WhereClause](@WHERE NVARCHAR(4000), @ParamName NVARCHAR(50), @ParamVal NVARCHAR(200), @Op NVARCHAR(10))  
  
RETURNS NVARCHAR(4000)  
  
AS  
BEGIN  
  
IF @WHERE IS NULL  
 SET @WHERE = ''  
  
IF @Op = 'LIKE'  
 SET @ParamVal = '%'+@ParamVal+'%'  
  
IF CHARINDEX('WHERE' , @WHERE) > 0  
 BEGIN   
  SET @WHERE = @WHERE  + ' AND ' + @ParamName +' '+ @Op +' '''+ dbo.CheckSingleQuote(@ParamVal) + ''''  
 END   
ELSE  
 BEGIN   
  SET @WHERE = @WHERE  + ' WHERE ' + @ParamName +' '+ @Op +' '''+ dbo.CheckSingleQuote(@ParamVal) + ''''  
 END   
  
RETURN @WHERE  
  
END;




