CREATE PROCEDURE [dbo].[GM_AMEND_CC_MAPPINGS]
	@RECORD_ID BIGINT = 0, 
	@RECORD_ID2 BIGINT = 0 

AS

DECLARE @KEEP BIGINT
DECLARE @DELETED BIGINT

SET @KEEP = 0
SET @DELETED = 0

IF @RECORD_ID > 0 AND @RECORD_ID2=0 -- CALLED FROM WORKFLOW ON DELETE CONTACT
BEGIN
	DELETE FROM [SRM-ThirdPartyIntegration].DBO.SRM_THIRD_PARTY_APPLICATION_MAPPINGS WHERE 
	SEQ_ID IN (SELECT TOP 1 SEQ_ID FROM [SRM-ThirdPartyIntegration].DBO.SRM_THIRD_PARTY_APPLICATION_MAPPINGS WHERE SRM_CLIENTS_SEQ_ID=16 AND MAPPING_TYPE_ID=1 AND STARGET_ID=@RECORD_ID)
END
ELSE IF @RECORD_ID > 0 AND @RECORD_ID2 > 0 -- CALLED FROM MERGE SP
BEGIN
	SELECT @KEEP = SEQ_ID FROM [SRM-ThirdPartyIntegration].DBO.SRM_THIRD_PARTY_APPLICATION_MAPPINGS WHERE SRM_CLIENTS_SEQ_ID=16 AND MAPPING_TYPE_ID=1 AND STARGET_ID=@RECORD_ID
	SELECT @DELETED = SEQ_ID FROM [SRM-ThirdPartyIntegration].DBO.SRM_THIRD_PARTY_APPLICATION_MAPPINGS WHERE SRM_CLIENTS_SEQ_ID=16 AND MAPPING_TYPE_ID=1 AND STARGET_ID=@RECORD_ID2

	IF @KEEP > 0 AND @DELETED > 0 -- BOTH CONTACTS HAVE ENTRY IN SRM_THIRD_PARTY_APPLICATION_MAPPINGS 
		DELETE FROM [SRM-ThirdPartyIntegration].DBO.SRM_THIRD_PARTY_APPLICATION_MAPPINGS WHERE SEQ_ID=@DELETED

	ELSE IF @KEEP = 0 AND @DELETED > 0 -- DELETED CONTACT HAS ENTRY BUT KEEP HAS NOT ENTRY IN SRM_THIRD_PARTY_APPLICATION_MAPPINGS 
		UPDATE [SRM-ThirdPartyIntegration].DBO.SRM_THIRD_PARTY_APPLICATION_MAPPINGS SET STARGET_ID=@RECORD_ID WHERE SEQ_ID=@DELETED
END




;


CREATE function [dbo].[GetAttributeSystemName](@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT)
returns varchar(100)
as
begin
	DECLARE @DESCRIPTION_ATTRIBUTE NVARCHAR(100) = ''
	
	SELECT @DESCRIPTION_ATTRIBUTE = sea.SYSTEM_NAME FROM [SRM-Framework_New].dbo.SRM_ENTITY_ATTRIBUTES AS sea
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS scea ON sea.SEQ_ID = scea.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	WHERE scea.SEQ_ID = @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 

   return rtrim(ltrim(@DESCRIPTION_ATTRIBUTE))
end
;

grant alter, execute on GetAttributeSystemName to usr_conversion;







create FUNCTION [dbo].[GetCalculateAge] (@DATE_OF_BIRTH DATETIME)
RETURNS INT
AS
BEGIN
	DECLARE @RETURN_ID AS INT
	DECLARE @iYearOfBirth AS INT
	DECLARE @iCurrentYear AS INT
			
	IF (@DATE_OF_BIRTH IS NULL OR @DATE_OF_BIRTH = '')
		BEGIN 
			SET @RETURN_ID = 0
		END
	ELSE
		BEGIN
			SET @iYearOfBirth = YEAR(@DATE_OF_BIRTH)
			SET @iCurrentYear = YEAR(GETDATE())

			IF (@iCurrentYear <> @iYearOfBirth)
				BEGIN
					IF (MONTH(@DATE_OF_BIRTH) > MONTH(GETDATE()))
							SET @RETURN_ID =  @iCurrentYear - (@iYearOfBirth + 1)
					ELSE IF (MONTH(@DATE_OF_BIRTH) < MONTH(GETDATE()))
							SET @RETURN_ID = @iCurrentYear - @iYearOfBirth;
					ELSE
							BEGIN
							IF (DAY(@DATE_OF_BIRTH) > DAY(GETDATE()))
									SET @RETURN_ID = @iCurrentYear - (@iYearOfBirth + 1)
							ELSE
									SET @RETURN_ID = @iCurrentYear - @iYearOfBirth
							END
				END
			ELSE
					SET @RETURN_ID = 0
		END

		RETURN RTRIM(LTRIM(@RETURN_ID))
END

;


CREATE function [dbo].[GetClientCustomEntitiesdatabase](@ClientId NVARCHAR(10))
returns varchar(100)
as
begin
   DECLARE @PIVOT_DATABASENAME NVARCHAR(100)
	
	select @PIVOT_DATABASENAME=SC.INITIAL_CATALOG_CUSTOM_ENTITIES from SRM_CLIENTS SC WITH (NOLOCK) WHERE SC.SEQ_ID=@ClientId

	if db_id(@PIVOT_DATABASENAME) IS NULL
		SET @PIVOT_DATABASENAME = 'SRM-CustomEntities'
		
	SET @PIVOT_DATABASENAME = '[' + @PIVOT_DATABASENAME + ']'

   return rtrim(ltrim(@PIVOT_DATABASENAME))
end
;

grant alter, execute on GetClientCustomEntitiesdatabase to usr_conversion;


CREATE function [dbo].[GetClientPivotdatabase](@ClientId NVARCHAR(10))
returns varchar(100)
as
