CREATE PROCEDURE [dbo].[GetREGISTER_COURSE_MASTER_DETAILData] 
@m_SEARCH_STUDENT_SEQ_ID BigInt = NULL, 
@m_SEARCH_STUDENT_NAME NVarChar(200) = NULL, 
@m_ED_REGISTER_COURSES_MASTER_SEQ_ID BigInt = NULL, 
@m_ED_REGISTER_COURSES_SEQ_ID BigInt = NULL, 
@m_ED_COURSES_SEQ_ID BigInt = NULL, 
@m_THEORY_ED_MODULES_SEQ_ID BigInt = NULL, 
@m_THEORY_EXAM_CENTRE_SEQ_ID BigInt = NULL, 
@m_THEORY_EXAM_CENTRE_NAME NVarChar(200) = NULL, 
@m_THEORY_GRADE_SEQ_ID BigInt = NULL, 
@m_THEORY_MARKS Float = NULL, 
@m_THEORY_ABSENT NVarChar(1) = NULL, 
@m_THEORY_EXAMINER_SEQ_ID BigInt = NULL, 
@m_THEORY_EXAMINER_NAME NVarChar(200) = NULL, 
@m_THEORY_TUTOR_SEQ_ID BigInt = NULL, 
@m_THEORY_TUTOR_NAME NVarChar(200) = NULL, 
@m_PRACTICAL_GRADE_SEQ_ID BigInt = NULL, 
@m_PRACTICAL_ABSENT NVarChar(1) = NULL, 
@m_EXAM_DATE_FOR NVarChar(20) = NULL,  
@m_EXAM_DATE_FROM DateTime = NULL, 
@m_EXAM_DATE_TO DateTime = NULL,
@m_THEORY_RESIT_ATTEMPTS_AVAILED CHAR(1) = 'N',
@m_PRACTICAL_RESIT_ATTEMPTS_AVAILED CHAR(1) = 'N',
@m_THEORY_RESIT_ATTEMPTS INT = 0,
@m_PRACTICAL_RESIT_ATTEMPTS INT = 0

AS 

Declare @strSQL nvarchar(max) 
Declare @strSQL1 nvarchar(max) 
Declare @strWHERE nvarchar(max) 
DECLARE @ErrorNo int 
Declare @CreatedBy nvarchar(30)

SET @strWHERE = '' 


SET NOCOUNT ON 
SET @ErrorNo = -1 



SELECT @CreatedBy = CREATED_BY FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA where SRM_CLIENT_ENTITIES_SEQ_ID = 12677 and seq_id = @m_SEARCH_STUDENT_SEQ_ID


UPDATE [SRM-CustomEntities_36].DBO.CUS_ENTITY_DATA 
SET 
DELETED = 'Y'
, DATE_DELETED = GETDATE()
, DELETED_BY = @CREATEDBY 
WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 12678 AND DELETED = 'N'
AND SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-CustomEntities_36].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI 
WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=279266 AND ATTRIBUTE_DECIMAL=@m_SEARCH_STUDENT_SEQ_ID)




--IF Len(@m_THEORY_EXAM_CENTRE_NAME) > 0 
--BEGIN 
--SET @m_THEORY_EXAM_CENTRE_NAME = @m_THEORY_EXAM_CENTRE_NAME + '%' 
--END 

IF ISNULL(@m_THEORY_EXAM_CENTRE_NAME, '') ='' -- Change made by AS to restirct blank exam centre
	SET @m_THEORY_EXAM_CENTRE_NAME = 'Both' 

IF ISNULL(@m_THEORY_ABSENT, '') != 'Y' 
BEGIN 
SET @m_THEORY_ABSENT = 'N' 
END 

IF Len(@m_THEORY_EXAMINER_NAME) > 0 
BEGIN 
SET @m_THEORY_EXAMINER_NAME = @m_THEORY_EXAMINER_NAME + '%' 
END 

IF Len(@m_THEORY_TUTOR_NAME) > 0 
BEGIN 
SET @m_THEORY_TUTOR_NAME = @m_THEORY_TUTOR_NAME + '%' 
END 

IF ISNULL(@m_PRACTICAL_ABSENT, '') != 'Y' 
BEGIN 
SET @m_PRACTICAL_ABSENT = 'N' 
END 

--new start

IF dbo.GetStringDate(@m_EXAM_DATE_FROM) = dbo.GetStringDate('1/1/1753') OR ISNULL(@m_EXAM_DATE_FROM, '') = ''
BEGIN 
SET @m_EXAM_DATE_FROM = NULL 
END 
IF dbo.GetStringDate(@m_EXAM_DATE_TO) = dbo.GetStringDate('1/1/1753')  OR ISNULL(@m_EXAM_DATE_TO, '') = ''
BEGIN 
SET @m_EXAM_DATE_TO = NULL 
END 
--new end



BEGIN

SET @STRSQL = ''

SET @STRSQL = 'INSERT INTO [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA(SRM_CLIENT_ENTITIES_SEQ_ID, SRM_CLIENTS_SEQ_ID, DATE_CREATED, CREATED_BY, DELETED,
ATTRIBUTE_001,ATTRIBUTE_002,ATTRIBUTE_003,ATTRIBUTE_004,ATTRIBUTE_005,ATTRIBUTE_006,ATTRIBUTE_007,ATTRIBUTE_008,ATTRIBUTE_009,
ATTRIBUTE_011,ATTRIBUTE_012,ATTRIBUTE_013,ATTRIBUTE_015,ATTRIBUTE_017,ATTRIBUTE_018,ATTRIBUTE_019,ATTRIBUTE_020) '

SET @STRSQL = @STRSQL + '
SELECT DISTINCT 12678, 36, GETDATE(), ''' + @CreatedBy + ''', ''N'', ''' + @m_SEARCH_STUDENT_NAME + '''
,STUDENT.ATTRIBUTE_004, STUDENT.ATTRIBUTE_003 
,REGISTER_COURSE_MASTER.ATTRIBUTE_019, REGISTER_COURSE_MASTER.ATTRIBUTE_020
,TGRADE.ATTRIBUTE_001, PGRADE.ATTRIBUTE_001
,REGISTER_COURSE_MASTER.ATTRIBUTE_021
,RESULT_TYPE.ATTRIBUTE_001 
, ' + CAST(@m_SEARCH_STUDENT_SEQ_ID AS NVARCHAR(100)) + ',''' + @m_SEARCH_STUDENT_NAME + '''
,REGISTER_COURSE_MASTER.SEQ_ID 
,REGISTER_COURSE_MASTER_DETAIL.SEQ_ID REGISTER_COURSE_MASTER_DETAIL_SEQ_ID 
,STUDENT.ATTRIBUTE_002, STUDENT.ATTRIBUTE_003
,REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_006 REGISTER_COURSE_MASTER_DETAIL_ATTRIBUTE_006, REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_007 REGISTER_COURSE_MASTER_DETAIL_ATTRIBUTE_007
FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA REGISTER_COURSE_MASTER with (NOLOCK) 
INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA STUDENT with (NOLOCK) ON STUDENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10168 AND STUDENT.DELETED = ''N'' AND REGISTER_COURSE_MASTER.ATTRIBUTE_002 = STUDENT.SEQ_ID
LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA TGRADE with (NOLOCK) ON TGRADE.SRM_CLIENT_ENTITIES_SEQ_ID = 9774 AND TGRADE.DELETED = ''N'' AND TGRADE.SEQ_ID = REGISTER_COURSE_MASTER.ATTRIBUTE_006
LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA PGRADE with (NOLOCK) ON PGRADE.SRM_CLIENT_ENTITIES_SEQ_ID = 9774 AND PGRADE.DELETED = ''N'' AND PGRADE.SEQ_ID = REGISTER_COURSE_MASTER.ATTRIBUTE_008
LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA RESULT_TYPE with (NOLOCK) ON RESULT_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = 9773 AND RESULT_TYPE.DELETED = ''N'' AND RESULT_TYPE.SEQ_ID = REGISTER_COURSE_MASTER.ATTRIBUTE_012
INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA REGISTER_COURSE_MASTER_DETAIL with (NOLOCK) ON REGISTER_COURSE_MASTER_DETAIL.SRM_CLIENT_ENTITIES_SEQ_ID = 10237 AND REGISTER_COURSE_MASTER_DETAIL.DELETED = ''N'' AND REGISTER_COURSE_MASTER.SEQ_ID = REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_002 '



--IF @m_EXAM_DATE_FROM IS NOT NULL AND @m_EXAM_DATE_TO IS NOT NULL -- Commented by AS to restirct blank exam centre
