					LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_MODULE with (NOLOCK) ON COURSE_REGISTRATION_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 10228 AND COURSE_REGISTRATION_MODULE.DELETED = ''N'' AND COURSE_REGISTRATION_MODULE.ATTRIBUTE_016=COURSE_REGISTRATION.SEQ_ID
					LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_ELEMENT with (NOLOCK) ON COURSE_REGISTRATION_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10229 AND COURSE_REGISTRATION_ELEMENT.DELETED = ''N'' AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_004 = COURSE_REGISTRATION_MODULE.SEQ_ID '
	END
	ELSE IF @m_THEORY_EXAM_CENTRE_NAME='Theory' --@m_EXAM_DATE_FOR LIKE '%Theory%' -- Change made by AS to restirct blank exam centre
	BEGIN
		SET @STRSQL = @STRSQL + ' LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_MODULE with (NOLOCK) ON COURSE_REGISTRATION_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 10228 AND COURSE_REGISTRATION_MODULE.DELETED = ''N'' AND REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_036=COURSE_REGISTRATION_MODULE.SEQ_ID
								  LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_ELEMENT with (NOLOCK) ON COURSE_REGISTRATION_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10229 AND COURSE_REGISTRATION_ELEMENT.DELETED = ''N'' AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_004 = COURSE_REGISTRATION_MODULE.SEQ_ID '
	END
	ELSE IF @m_THEORY_EXAM_CENTRE_NAME='Practical' --@m_EXAM_DATE_FOR LIKE '%Practical%' -- Change made by AS to restirct blank exam centre
	BEGIN
