								  LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_ELEMENT with (NOLOCK) ON COURSE_REGISTRATION_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10229 AND COURSE_REGISTRATION_ELEMENT.DELETED = ''N'' AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_004 = COURSE_REGISTRATION_MODULE.SEQ_ID '
	END
END

SET @STRSQL = @STRSQL + '  WHERE REGISTER_COURSE_MASTER.SRM_CLIENT_ENTITIES_SEQ_ID = 10236 AND REGISTER_COURSE_MASTER.DELETED = ''N'' AND REGISTER_COURSE_MASTER.ATTRIBUTE_022 = ' + CAST(@m_ED_REGISTER_COURSES_MASTER_SEQ_ID  AS NVARCHAR(10) )+ ''

IF (len(@m_ED_COURSES_SEQ_ID)> 0 AND @m_ED_COURSES_SEQ_ID > 0)
	SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_006 =' + cast(@m_ED_COURSES_SEQ_ID as nvarchar(10)) + ''

IF ( @m_THEORY_EXAMINER_SEQ_ID > 0 )
BEGIN
	IF @m_THEORY_EXAMINER_NAME LIKE '%Both%'
	BEGIN
		SET @STRSQL = @STRSQL + ' AND (REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_020 =  '+ CAST(@m_THEORY_EXAMINER_SEQ_ID AS NVARCHAR(10)) + ''
		SET @STRSQL = @STRSQL + ' OR REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_032 =  '+ CAST(@m_THEORY_EXAMINER_SEQ_ID AS NVARCHAR(10)) + '' + ')'
	END

	IF @m_THEORY_EXAMINER_NAME LIKE '%Theory%'
		SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_020 = '+ CAST(@m_THEORY_EXAMINER_SEQ_ID AS NVARCHAR(10)) + '' 
	IF @m_THEORY_EXAMINER_NAME LIKE '%Practical%'
		SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_032 =' + CAST(@m_THEORY_EXAMINER_SEQ_ID AS NVARCHAR(10)) + '' 

END

IF ( @m_THEORY_TUTOR_SEQ_ID > 0 )
BEGIN
