		SET @STRSQL = @STRSQL + ' OR REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_034 = '  + CAST(@m_THEORY_TUTOR_SEQ_ID AS NVARCHAR(10) ) + '' + ')'
	END
	IF @m_THEORY_TUTOR_NAME LIKE '%Theory%'
	SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_022 = '+ CAST(@m_THEORY_TUTOR_SEQ_ID AS NVARCHAR(10) )+ '' 
	IF @m_THEORY_TUTOR_NAME LIKE '%Practical%'
	SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_034 = ' + CAST(@m_THEORY_TUTOR_SEQ_ID AS NVARCHAR(10)) + '' 
END


IF ( @m_THEORY_EXAM_CENTRE_SEQ_ID > 0 )
BEGIN
	IF @m_THEORY_EXAM_CENTRE_NAME LIKE '%Both%'
