--
IF ( @m_THEORY_ED_MODULES_SEQ_ID > 0 ) -- FOR OVER ALL RESULT
SET @STRSQL = @STRSQL + ' AND  REGISTER_COURSE_MASTER.ATTRIBUTE_012 = ' + CAST( @m_THEORY_ED_MODULES_SEQ_ID AS NVARCHAR(10)) + ''
--
IF ( @m_THEORY_GRADE_SEQ_ID > 0 )
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_006 = ' + CAST( @m_THEORY_GRADE_SEQ_ID AS NVARCHAR(10)) + ''
--
IF ( @m_PRACTICAL_GRADE_SEQ_ID > 0 )
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_008 = ' + CAST( @m_PRACTICAL_GRADE_SEQ_ID AS NVARCHAR(10)) + ''

--IF ( @m_THEORY_ABSENT = 'Y' ) 
