--IF ( @m_PRACTICAL_ABSENT ='Y' ) 
SET @STRSQL = @STRSQL + ' AND ISNULL(REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_031, ''N'') = ''' + @m_PRACTICAL_ABSENT + ''' '

----------Change made by AS Starts to pick specfic progress statuses only
SET @STRSQL = @STRSQL + ' AND
REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_004 IN 
(SELECT SEQ_ID FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=10225 AND DELETED=''N'' AND ATTRIBUTE_009 IN (
SELECT SEQ_ID FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID=9776 AND DELETED=''N'' AND ATTRIBUTE_003 =''Y'' )) '

SET @STRSQL = @STRSQL + ' AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028 IS NOT NULL '
----------Change made by AS End

--
IF @m_THEORY_RESIT_ATTEMPTS_AVAILED like 'Y%'
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_017 =''Y'''

IF @m_PRACTICAL_RESIT_ATTEMPTS_AVAILED like 'Y%'
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_018 =''Y'''

IF @m_THEORY_RESIT_ATTEMPTS <> 0 
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_015 = ''' +  CAST(@m_THEORY_RESIT_ATTEMPTS AS NVARCHAR(10)) + ''' '

IF @m_PRACTICAL_RESIT_ATTEMPTS <> 0
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_016 = ''' +  CAST(@m_PRACTICAL_RESIT_ATTEMPTS AS NVARCHAR(10)) + ''' '

--NEW START
IF @m_EXAM_DATE_FROM IS NOT NULL AND @m_EXAM_DATE_TO IS NOT NULL	
BEGIN
	SET @STRSQL = @STRSQL + ' AND   CAST(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_018 AS DATE) >= ''' + dbo.GetStringDate(@m_EXAM_DATE_FROM) + ''' '	
	SET @STRSQL = @STRSQL + ' AND   CAST(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_018 AS DATE) <= ''' + dbo.GetStringDate(@m_EXAM_DATE_TO) + ''' '
END	
--NEW END

EXEC GET_PRINT @strSQL
EXECUTE (@strSQL) 



DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT


DECLARE curGeneral CURSOR STATIC LOCAL FOR 
SELECT SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID FROM  [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA D 
WHERE D.SRM_CLIENT_ENTITIES_SEQ_ID = 12678 AND D.ATTRIBUTE_011 = @m_SEARCH_STUDENT_SEQ_ID AND D.DELETED = 'N'
   
OPEN curGeneral                                                             
FETCH NEXT FROM curGeneral INTO @CUS_ENTITY_DATA_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID    

WHILE (@@Fetch_Status = 0)       
BEGIN        

	exec [DBO].[GET_POPULATE_PIVOT_TABLE]
	@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID,
	@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
	@SRM_CLIENTS_SEQ_ID = 36


	FETCH NEXT FROM curGeneral INTO @CUS_ENTITY_DATA_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID
END    
   
CLOSE curGeneral                           
DEALLOCATE curGeneral  




END




;








