		SET @STRSQL = @STRSQL + ' OR REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_032 =  '+ CAST(@m_THEORY_EXAMINER_SEQ_ID AS NVARCHAR(10)) + '' + ')'
