	BEGIN
		SET @STRSQL = @STRSQL + ' AND (REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_022 = ' + CAST(@m_THEORY_TUTOR_SEQ_ID AS NVARCHAR(10) ) + ''
		SET @STRSQL = @STRSQL + ' OR REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_034 = '  + CAST(@m_THEORY_TUTOR_SEQ_ID AS NVARCHAR(10) ) + '' + ')'
	END
	IF @m_THEORY_TUTOR_NAME LIKE '%Theory%'
	SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_022 = '+ CAST(@m_THEORY_TUTOR_SEQ_ID AS NVARCHAR(10) )+ '' 
	IF @m_THEORY_TUTOR_NAME LIKE '%Practical%'
	SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_034 = ' + CAST(@m_THEORY_TUTOR_SEQ_ID AS NVARCHAR(10)) + '' 
END


IF ( @m_THEORY_EXAM_CENTRE_SEQ_ID > 0 )
BEGIN
	IF @m_THEORY_EXAM_CENTRE_NAME LIKE '%Both%'
	BEGIN
		SET @STRSQL = @STRSQL + ' AND (REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_014 = ' + CAST(@m_THEORY_EXAM_CENTRE_SEQ_ID AS NVARCHAR(10) ) + ''
		SET @STRSQL = @STRSQL + ' OR REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_026 = '  + CAST(@m_THEORY_EXAM_CENTRE_SEQ_ID AS NVARCHAR(10) ) + '' + ')'
	END
	IF @m_THEORY_EXAM_CENTRE_NAME LIKE '%Theory%'
		SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_014 = '+ CAST(@m_THEORY_EXAM_CENTRE_SEQ_ID AS NVARCHAR(10) )+ '' 
	IF @m_THEORY_EXAM_CENTRE_NAME LIKE '%Practical%'
		SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_026 = ' + CAST(@m_THEORY_EXAM_CENTRE_SEQ_ID AS NVARCHAR(10)) + '' 
END

--
IF ( @m_ED_REGISTER_COURSES_SEQ_ID > 0 ) -- FOR STUDENT NUMBER
SET @STRSQL = @STRSQL + ' AND STUDENT.SEQ_ID = ' + CAST(@m_ED_REGISTER_COURSES_SEQ_ID AS NVARCHAR(10)) + ''
--
IF ( @m_THEORY_ED_MODULES_SEQ_ID > 0 ) -- FOR OVER ALL RESULT
SET @STRSQL = @STRSQL + ' AND  REGISTER_COURSE_MASTER.ATTRIBUTE_012 = ' + CAST( @m_THEORY_ED_MODULES_SEQ_ID AS NVARCHAR(10)) + ''
--
IF ( @m_THEORY_GRADE_SEQ_ID > 0 )
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_006 = ' + CAST( @m_THEORY_GRADE_SEQ_ID AS NVARCHAR(10)) + ''
--
IF ( @m_PRACTICAL_GRADE_SEQ_ID > 0 )
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_008 = ' + CAST( @m_PRACTICAL_GRADE_SEQ_ID AS NVARCHAR(10)) + ''

IF ( @m_THEORY_ABSENT = 'Y' ) 
SET @STRSQL = @STRSQL + ' AND ISNULL(REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_019, ''N'') = ''Y'''
IF ( @m_PRACTICAL_ABSENT ='Y' ) 
SET @STRSQL = @STRSQL + ' AND ISNULL(REGISTER_COURSE_MASTER_DETAIL.ATTRIBUTE_031, ''N'') = ''Y'''

--
IF @m_THEORY_RESIT_ATTEMPTS_AVAILED like 'Y%'
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_017 =''Y'''

IF @m_PRACTICAL_RESIT_ATTEMPTS_AVAILED like 'Y%'
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_018 =''Y'''

IF @m_THEORY_RESIT_ATTEMPTS <> 0 
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_015 = ''' +  CAST(@m_THEORY_RESIT_ATTEMPTS AS NVARCHAR(10)) + ''' '

IF @m_PRACTICAL_RESIT_ATTEMPTS <> 0
SET @STRSQL = @STRSQL + ' AND REGISTER_COURSE_MASTER.ATTRIBUTE_016 = ''' +  CAST(@m_PRACTICAL_RESIT_ATTEMPTS AS NVARCHAR(10)) + ''' '

--NEW START
IF @m_EXAM_DATE_FROM IS NOT NULL AND @m_EXAM_DATE_TO IS NOT NULL	
BEGIN
	SET @STRSQL = @STRSQL + ' AND   CAST(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_018 AS DATE) >= ''' + dbo.GetStringDate(@m_EXAM_DATE_FROM) + ''' '	
	SET @STRSQL = @STRSQL + ' AND   CAST(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_018 AS DATE) <= ''' + dbo.GetStringDate(@m_EXAM_DATE_TO) + ''' '
END	
--NEW END

PRINT @strSQL
EXECUTE (@strSQL) 






END




;

CREATE FUNCTION [dbo].[GetSingleLineFilterViewAttributes] (@SRM_CLIENT_FILTER_VIEWS_SEQ_ID BIGINT)      

RETURNS NVARCHAR (2000)        

AS      

  

BEGIN      

	DECLARE @ATTRIBUTES NVARCHAR(2000)
	
	SELECT @ATTRIBUTES = COALESCE(@ATTRIBUTES  + ', ' ,'') + SCEA.SYSTEM_NAME  FROM 
	(	
		SELECT SYSTEM_NAME FROM dbo.SRM_CLIENT_FILTER_VIEW_ATTRIBUTES AS SCFVA 
		INNER JOIN dbo.SRM_CLIENT_ENTITY_ATTRIBUTES AS SCEA2 ON SCFVA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SCEA2.SEQ_ID
		INNER JOIN dbo.SRM_ENTITY_ATTRIBUTES AS SEA ON SCEA2.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
		WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID=@SRM_CLIENT_FILTER_VIEWS_SEQ_ID
	) AS SCEA
	
 

 
RETURN @ATTRIBUTES        

END;

CREATE FUNCTION [dbo].[GetStringDate]  (@DATE datetime)

RETURNS nVarChar(10)

AS

BEGIN

   DECLARE @Year int

   DECLARE @Month int

   DECLARE @Day int

   DECLARE @retDate nVarChar(10)



   SET @Year = DATEPART(yyyy,@DATE)

   SET @Month = DATEPART(mm,@DATE)

   SET @Day = DATEPART(dd,@DATE)



   SET @retDate = cast(@Year as char(4)) + '/' + cast(@Month as char(2)) + '/' + cast(@Day as char(2))



   RETURN(@retDate)

END;

CREATE FUNCTION [dbo].[GetStringDateUK]  (@DATE datetime)

RETURNS nVarChar(10)

AS

BEGIN

   DECLARE @Year int

   DECLARE @Month int

   DECLARE @Day int

   DECLARE @retDate nVarChar(10)



   SET @Year = DATEPART(yyyy,@DATE)

   SET @Month = DATEPART(mm,@DATE)

   SET @Day = DATEPART(dd,@DATE)



   SET @retDate = Right('0' + cast(@Day as varchar(2)), 2) + '/' + Right('0' + cast(@Month as varchar(2)), 2) + '/' + cast(@Year as char(4)) 



   RETURN(@retDate)

END;






