	--@DesignatoryLetter=ATTRIBUTE_009  MQ removed this as Attribute_009 is Dietary_Req already used above
	from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA 
	where SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_EVT_BOOKING and  seq_id = @WEB_SERVICE_EVENT_BOOKING_MASTER_SEQ_ID
	
	
	SET @CONTACT_BOOKER_SEQ_ID = 0
	SET @Email = LTRIM(RTRIM(@Email))
	SET @Email = REPLACE(@Email, ' ','')

	SELECT @CONTACT_BOOKER_SEQ_ID=SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE SEQ_ID IN (
	SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DATAPIVOT].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=45797 AND ATTRIBUTE_STRING=@Email) AND
	DELETED='N' ORDER BY SEQ_ID
 
	IF @CONTACT_BOOKER_SEQ_ID = 0
	BEGIN
		--Get Title Value
		set @TitleId= null 
		set @TitleName=null
	
		select @TitleId=SEQ_ID,@TitleName=ATTRIBUTE_001
		from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA 
		where SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_TITLE and LTRIM(rtrim(ATTRIBUTE_001)) = LTRIM(rtrim(@Title))


		set @LabelName = ltrim(rtrim(isnull(@TitleName, ''))) + ' ' + ltrim(rtrim(isnull(@FirstName, ''))) +  ' ' +ltrim(rtrim(isnull(@LastName, '')))  --+ ' ' + ltrim(rtrim(isnull(@DesignatoryLetter, '')))
		set @Salutation = ltrim(rtrim(isnull(@TitleName, ''))) + ' ' + ltrim(rtrim(isnull(@LastName, ''))) 
		set @Family_Sal = ltrim(rtrim(isnull(@TitleName, ''))) + ' ' + ltrim(rtrim(isnull(@FirstName, ''))) +  ' ' +ltrim(rtrim(isnull(@LastName, ''))) 
	
		--Get County Value
		set @AddressCountyId= null 
		set @AddressCountyName=null
	
		select @AddressCountyId=SEQ_ID,@AddressCountyName=ATTRIBUTE_001
		from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA 
		where SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_COUNTY and LTRIM(rtrim(ATTRIBUTE_001)) = LTRIM(rtrim(@AddressCounty))
	
		--Get Country Value
		set @AddressCountryId= null 
		set @AddressCountryName=null
	
		select @AddressCountryId=SEQ_ID,@AddressCountryName=ATTRIBUTE_001
		from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA 
		where SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_COUNTY and LTRIM(rtrim(ATTRIBUTE_001)) = LTRIM(rtrim(@AddressCountry))
	
		--Get London_Borough Value
		set @BoroughId= null 
		set @BoroughName=null
	
		select @BoroughId=SEQ_ID,@BoroughName=ATTRIBUTE_001
		from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA 
		where SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_LONDON_BOROUGH and LTRIM(rtrim(ATTRIBUTE_001)) = LTRIM(rtrim(@London_Borough))
	
	
		--Get Address Type Value
		set @AddressTypeId= null 
		set @AddressTypeName=null
	
		select @AddressTypeId=SEQ_ID,@AddressTypeName=ATTRIBUTE_001
		from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA 
		where SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_ADDRESS_TYPE and LTRIM(rtrim(ATTRIBUTE_001)) = LTRIM(rtrim(@AddressType))
	
		declare @Contact_Number nvarchar(100)
	
		-- Insert Booker in Contact
	
		if(@FirstName is not null or @LastName is not null)
		Begin
			SET @Department = 'Learning & Engagement'
			SET @RelationshipManager = 'Rebecca Honeycombe'
			SET @ContactStatus='Current'

			SELECT @DepartmentSeqId =SEQ_ID, @Department = ATTRIBUTE_001
			FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA 
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_DEPARTMENT AND LTRIM(RTRIM(ATTRIBUTE_001)) = @Department

			SELECT @RelationshipManagerSeqId =SEQ_ID, @RelationshipManager = ATTRIBUTE_001
			FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA 
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_RELATIONSHIP_MANAGER AND LTRIM(RTRIM(ATTRIBUTE_001)) = @RelationshipManager
		
			SELECT @ContactStatusSeqId=SEQ_ID
			FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA 
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT_ACCOUNT_STATUS AND DELETED='N' AND LTRIM(RTRIM(ATTRIBUTE_001)) = @ContactStatus

			-- Get Next Contact Number
			EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 1, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @Contact_Number OUTPUT
	
				EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_001=@LabelName,
				@ATTRIBUTE_005= @FirstName,
				@ATTRIBUTE_004= @LastName,
				@ATTRIBUTE_010 = @Salutation,
				@ATTRIBUTE_056 =@Email,
				@ATTRIBUTE_053=@Telephone,
				@ATTRIBUTE_025=@TitleId,
				@ATTRIBUTE_026=@TitleName,
				@ATTRIBUTE_163=@AddressTypeId,
				@ATTRIBUTE_164=@AddressTypeName,
				@ATTRIBUTE_167=@AddressAccountName,
				@ATTRIBUTE_169=@AddressJobTitle,
				@ATTRIBUTE_035=@Address_1,
				@ATTRIBUTE_036=@Address_2,
				@ATTRIBUTE_037=@Address_3,
				@ATTRIBUTE_042=@AddressCountryId,
				@ATTRIBUTE_043=@AddressCountryName,
				@ATTRIBUTE_040=@AddressCountyId,
				@ATTRIBUTE_041=@AddressCountyName,
				@ATTRIBUTE_038=@AddressTown,
				@ATTRIBUTE_137=@Booking_Id,
				@ATTRIBUTE_138=@BoroughName,
				@ATTRIBUTE_191=@AddressCity,
				@ATTRIBUTE_192=@AddressState,
				@ATTRIBUTE_003=@Contact_Number,
				@ATTRIBUTE_200=@MarketingOptIn,
				@ATTRIBUTE_201=@ContactOptIn,
				@ATTRIBUTE_039=@PostCode,
				@ATTRIBUTE_007 = @LabelName,
				@ATTRIBUTE_199=@Family_Sal,
				@ATTRIBUTE_149=@DepartmentSeqId,
				@ATTRIBUTE_150=@Department,
				@ATTRIBUTE_152=@RelationshipManagerSeqId,
				@ATTRIBUTE_153=@RelationshipManager,
				@ATTRIBUTE_205=@ContactStatusSeqId,
				@ATTRIBUTE_206=@ContactStatus,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT,
				@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
				@DATE_CREATED = @TODAY,
				@CREATED_BY = @USER,
				@RETURN_SEQ_ID = @CONTACT_BOOKER_SEQ_ID OUTPUT,
				@ERROR = @ERROR OUTPUT,
				@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	
		end

	END
	
	Declare @BookerName nvarchar(100)
	
	IF ISNULL(@CONTACT_BOOKER_SEQ_ID, '') <> ''  -- GET Booker @CONTACT_SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'CONTACT', @ATTRIBUTE_DISPLAY_NAME = 'RECORD_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @CONTACT_BOOKER_SEQ_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @CONTACT_BOOKER_SEQ_ID OUTPUT, @DESCRIPTION = @BookerName OUTPUT
		PRINT '@CONTACT_NAME ' + CAST(@BookerName AS NVARCHAR(100))
	END
	
	Declare @EventName nvarchar(100), @EventId bigint 
	
	IF ISNULL(@Event_Id, '') <> ''  -- GET Event @SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'EVENT', @ATTRIBUTE_DISPLAY_NAME = 'EVENT_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @Event_Id, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @EventId OUTPUT, @DESCRIPTION = @EventName OUTPUT
		PRINT '@EVENT_NAME ' + CAST(@EventName AS NVARCHAR(100))
	END
	
	
	Declare @Reg_Status nvarchar(100), @Reg_Status_Id bigint , @Status nvarchar(100)
	set @Status = 'Confirmed'
	
	IF ISNULL(@Status, '') <> ''  -- GET Registration Status @SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'EVENT_REGISTRATION_STATUS', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @Status, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @Reg_Status_Id OUTPUT, @DESCRIPTION = @Reg_Status OUTPUT
		PRINT '@Reg_Status ' + CAST(@Reg_Status AS NVARCHAR(100))
	END
	
	Declare @AttendeeType nvarchar(100), @AttendeeType_Id bigint , @Type nvarchar(100)
	set @Type = case when isnull(@Attendee,'') = 'N' then 'Online Booker' else 'Attendee' end
	
	IF (ISNULL(@Status, '') <> '' and isnull(@Attendee,'') <> 'N')  -- GET Registration Status @SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'DELEGATE_TYPE', @ATTRIBUTE_DISPLAY_NAME = 'ONLINE_ATTENDEE', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @AttendeeType_Id OUTPUT, @DESCRIPTION = @AttendeeType OUTPUT
		PRINT '@Delegate_Type ' + CAST(@Reg_Status AS NVARCHAR(100))
	END
	else IF (ISNULL(@Status, '') <> '' and isnull(@Attendee,'') = 'N')  -- GET Registration Status @SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'DELEGATE_TYPE', @ATTRIBUTE_DISPLAY_NAME = 'ONLINE_BOOKER', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Y', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @AttendeeType_Id OUTPUT, @DESCRIPTION = @AttendeeType OUTPUT
		PRINT '@Delegate_Type ' + CAST(@Reg_Status AS NVARCHAR(100))
	END

	
	--Declare @AttendeeType nvarchar(100), @AttendeeType_Id bigint , @Type nvarchar(100)
	--set @Type = 'Attendee'
	
	IF ISNULL(@Marketing_Source, '') <> ''  -- GET Registration Status @SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MARKETING_SOURCE', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @Marketing_Source, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID =@MarketingId OUTPUT, @DESCRIPTION = @MarketingName OUTPUT
		PRINT '@Marketing_Source ' + CAST(@Reg_Status AS NVARCHAR(100))
	END
	
	
	-- Insert Event Registration and Booker
	
	Declare @Event_Reg_Seq_Id bigint,@REGISTRATION_ID nvarchar(100)
	
	if(ISNULL(@EventName, '') <> '')
	Begin
	
	-- Get Next Registration ID
		EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 8, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @REGISTRATION_ID OUTPUT
	
	set @Reg_Date=CONVERT(NVARCHAR, @Reg_Date, 121)
	
		EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
		@ATTRIBUTE_032=@EventId,
		@ATTRIBUTE_033=@Event_Id,
		@ATTRIBUTE_012= @CONTACT_BOOKER_SEQ_ID,
		@ATTRIBUTE_013=@BookerName,
		@ATTRIBUTE_017= @Reg_Date,--CONVERT(NVARCHAR, @Reg_Date, 121),
		@ATTRIBUTE_006=@Reg_Status_Id,
		@ATTRIBUTE_007=@Reg_Status,
		@ATTRIBUTE_004=@AttendeeType_Id,
		@ATTRIBUTE_005=@AttendeeType,
		@ATTRIBUTE_034=@MarketingId,
		@ATTRIBUTE_035=@MarketingName,
		@ATTRIBUTE_043 = @Total_Amount,
		@ATTRIBUTE_016=@REGISTRATION_ID,	
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVT_REG,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@DATE_CREATED = @TODAY,
		@CREATED_BY = @USER,
		@RETURN_SEQ_ID = @Event_Reg_Seq_Id OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
				
	
	set @EVENT_REGISTRATION_SEQ_ID = @Event_Reg_Seq_Id
	
	end
	
	
	
	Declare @Reg_Id nvarchar(100)
	
	IF ISNULL(@Event_Reg_Seq_Id, 0) <> 0  -- GET Event Registration @SEQ_ID Reg ID
	BEGIN
		select @Reg_Id=ATTRIBUTE_016 from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA where SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		and SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVT_REG and seq_id=@Event_Reg_Seq_Id
	END
	
	-- Insert Event Registration and Booker
	
	Declare @Event_Delegate_Id bigint
	Declare @Delegate_Id bigint, @DelegateName nvarchar(100)
	
	if(ISNULL(@Event_Reg_Seq_Id, 0) <> 0)
	Begin
	
		declare @Attended bigint,@OnlineDes nvarchar(100)
		set @Attended = case when ISNULL(@ChildAttendee,0) > 0 then @ChildAttendee else @Total_Seats end
		set @OnlineDes = case when isnull(@Attendee,'') = 'N' then @AttendeeType +' ' +@Event_Id  else @BookerName end
	
				EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
				@ATTRIBUTE_002=@Event_Reg_Seq_Id,
				@ATTRIBUTE_003=@Reg_Id,
				@ATTRIBUTE_016= @EventId,
				@ATTRIBUTE_017= @Event_Id,
				@ATTRIBUTE_006=@AttendeeType_Id,
				@ATTRIBUTE_007=@AttendeeType,
				@ATTRIBUTE_020=@Total_Seats,
				@ATTRIBUTE_022=@ChildAttendee,
				@ATTRIBUTE_021=@Attended,
				@ATTRIBUTE_001=@OnlineDes,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVT_DELEGATE,
				@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
				@DATE_CREATED = @TODAY,
				@CREATED_BY = @USER,
				@RETURN_SEQ_ID = @Event_Delegate_Id OUTPUT,
				@ERROR = @ERROR OUTPUT,
				@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
				
		IF ISNULL(@Event_Delegate_Id, '') <> ''  -- GET Booker @CONTACT_SEQ_ID NAME
		BEGIN
			EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'Event_Delegate', @ATTRIBUTE_DISPLAY_NAME = 'RECORD_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @Event_Delegate_Id, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @Delegate_Id OUTPUT, @DESCRIPTION = @DelegateName OUTPUT
			PRINT '@Event_Delegate ' + CAST(@BookerName AS NVARCHAR(100))
		END
	
		if(ISNULL(@DelegateName, '') <> '' and isnull(@Attendee,'') <> 'N')
		Begin
		EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
			@ATTRIBUTE_002=@CONTACT_BOOKER_SEQ_ID,
			@ATTRIBUTE_003=@BookerName,
			@ATTRIBUTE_004=@Delegate_Id,
			@ATTRIBUTE_005=@DelegateName,
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DELEGATE_NAMES,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@DATE_CREATED = @TODAY,
			@CREATED_BY = @USER,
			--@RETURN_SEQ_ID = @AttendeeNamesId OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
		end
	
	end
	
	-- Insert Booker Dietary Requirement
	Declare @SpecialReqId Bigint, @SpecialReq nvarchar(100)
	
	
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'SPECIAL_REQUIREMENT', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Dietary Requirement', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @SpecialReqId OUTPUT, @DESCRIPTION = @SpecialReq OUTPUT
		PRINT '@Special Req ' + CAST(@BookerName AS NVARCHAR(100))

	
	if(ISNULL(@Dietary_Req, '') <> '')
	Begin

		EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
		@ATTRIBUTE_001=@Dietary_Req,
		@ATTRIBUTE_005=@Reg_Id,
		@ATTRIBUTE_004= @Event_Reg_Seq_Id,
		@ATTRIBUTE_002=@SpecialReqId,
		@ATTRIBUTE_003= @SpecialReq,
		@ATTRIBUTE_008=@CONTACT_BOOKER_SEQ_ID,
		@ATTRIBUTE_009=@BookerName,
		@ATTRIBUTE_006= @EventId,
		@ATTRIBUTE_007= @EventName,
		@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVT_REG_SPECIAL_REQUIREMENT,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@DATE_CREATED = @TODAY,
		@CREATED_BY = @USER,
		--@RETURN_SEQ_ID = @EVENT_RATE_SEQ_ID OUTPUT,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	
	end
	
	
	-- Insert Event Registration Charges
	
	Declare @R_Description nvarchar(100),@R_RATE_AMOUNT money,@R_QUANTITY int, @R_TOTAL_AMOUNT money, @R_VAT_RATE int, @R_VAT_RATE_name Nvarchar(200), @R_VAT_AMOUNT money, @R_VAT_PERCENTAGE int, @R_GROSS_AMOUNT money,@R_ATTENDEE_TYPE nvarchar(100)

	declare @EVENT_RATE_SEQ_ID Bigint, @ContactId bigint, @Contact nvarchar(100), @T_Status_Id bigint, @T_Status nvarchar(100), @Invoice_TransactionId bigint
	Declare @ModuleId bigint, @Module nvarchar(100)
	
	-- Get Module
	
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'MODULE', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Events', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @ModuleId OUTPUT, @DESCRIPTION = @Module OUTPUT
	PRINT '@Module ' + CAST(@Reg_Status AS NVARCHAR(100))
	
	-- Get Transaction Status	
	EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'FINANCE_TRANSACTION_STATUS', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = 'Current', @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @T_Status_Id OUTPUT, @DESCRIPTION = @T_Status OUTPUT
	PRINT '@T_Status ' + CAST(@Reg_Status AS NVARCHAR(100))

	declare @VAT_RATE_ID BigInt
	declare @VAT_RATE_NAME NVarchar(200)
	declare @VAT_PERC numeric(8,2)
	declare @Net_Amount money

	select @VAT_RATE_ID = ATTRIBUTE_016, @VAT_RATE_NAME = ATTRIBUTE_017
	 from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA where SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT and SEQ_ID = @EventId

	SET @VAT_PERC = 0
	select @VAT_PERC = ATTRIBUTE_010
	 from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA where SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVT and ATTRIBUTE_014 = @EventId
	

	DECLARE Cur_records  CURSOR LOCAL STATIC 
	FOR

select ltrim(rtrim(Attribute_001)),Attribute_003,Attribute_004,Attribute_005,Attribute_006,Attribute_007,Attribute_008,Attribute_009,ltrim(rtrim(Attribute_010))
 from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA where SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVT_BOOKING_RATE and ATTRIBUTE_002 = @BOOKING_ID

 
OPEN Cur_records -- open the cursor

FETCH NEXT FROM Cur_records INTO @R_Description,@R_RATE_AMOUNT,@R_QUANTITY,@R_TOTAL_AMOUNT,@R_VAT_RATE,@R_VAT_AMOUNT,@R_VAT_PERCENTAGE,@R_GROSS_AMOUNT,@R_ATTENDEE_TYPE
 
   
WHILE @@FETCH_STATUS = 0
BEGIN
	set @AttendeeType_Id=null
	set @AttendeeType = null

	SET @R_GROSS_AMOUNT = @R_TOTAL_AMOUNT
	IF (@VAT_PERC > 0)
	BEGIN
		SET @R_VAT_RATE = @VAT_RATE_ID
		SET @R_VAT_RATE_name = @VAT_RATE_NAME	
	END
	ELSE
	BEGIN
		SET @R_VAT_RATE = 0
		SET @R_VAT_RATE_name = NULL
	END
	SET @R_VAT_PERCENTAGE = @VAT_PERC
	SET @Net_Amount = Round((100 * @R_GROSS_AMOUNT)/(100 + @VAT_PERC),2)
	SET @R_TOTAL_AMOUNT = @Net_Amount
	SET @R_RATE_AMOUNT = @Net_Amount / @R_QUANTITY
	SET @R_VAT_AMOUNT = @R_GROSS_AMOUNT - @Net_Amount

-- Get Delegate Type
	IF ISNULL(@R_ATTENDEE_TYPE, '') <> ''  -- GET Registration Status @SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'DELEGATE_TYPE', @ATTRIBUTE_DISPLAY_NAME = 'DESCRIPTION', @OPERATOR_ID = 3, @SEARCH_VALUE = @R_ATTENDEE_TYPE, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @AttendeeType_Id OUTPUT, @DESCRIPTION = @AttendeeType OUTPUT
		PRINT '@Delegate_Type ' + CAST(@Reg_Status AS NVARCHAR(100))
	END

		EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
			@ATTRIBUTE_002=@Event_Reg_Seq_Id,
			@ATTRIBUTE_003=@Reg_Id,
			@ATTRIBUTE_020= @EventId,
			@ATTRIBUTE_021= @EventName,
			@ATTRIBUTE_016=@AttendeeType_Id,
			@ATTRIBUTE_017=@AttendeeType,
			@ATTRIBUTE_001=@R_Description,
			@ATTRIBUTE_006=@R_RATE_AMOUNT,
			@ATTRIBUTE_007=@R_QUANTITY,
			@ATTRIBUTE_008=@Net_Amount,
			@ATTRIBUTE_024=@R_TOTAL_AMOUNT,
			@ATTRIBUTE_022=@R_VAT_RATE,
			@ATTRIBUTE_023=@R_VAT_RATE_name,
			@ATTRIBUTE_012=@R_VAT_AMOUNT,
			@ATTRIBUTE_011=@R_VAT_PERCENTAGE,
			@ATTRIBUTE_013=@R_GROSS_AMOUNT,
			@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVENT_REGISTRATION_CHARGES,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@DATE_CREATED = @TODAY,
			@CREATED_BY = @USER,
			@RETURN_SEQ_ID = @EVENT_RATE_SEQ_ID OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
				
				
				
	-- INVOICE TRANSACTION
	
	
	-- Get Booker 
	IF ISNULL(@CONTACT_BOOKER_SEQ_ID, '') <> ''  -- GET Registration Status @SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'CONTACT', @ATTRIBUTE_DISPLAY_NAME = 'RECORD_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @CONTACT_BOOKER_SEQ_ID, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @ContactId OUTPUT, @DESCRIPTION = @Contact OUTPUT
		PRINT '@Booker ' + CAST(@Reg_Status AS NVARCHAR(100))
	END
	
		EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]	
			--@ATTRIBUTE_001 = @EVENT_RATE_TYPE_NAME,
			@ATTRIBUTE_002 = @ModuleId,
			@ATTRIBUTE_003 = @Module,
			@ATTRIBUTE_004 = @EVENT_RATE_SEQ_ID,
			@ATTRIBUTE_008 = @ContactId ,
			@ATTRIBUTE_009 = @Contact,
			--@ATTRIBUTE_010 = @PO_NUMBER,
			@ATTRIBUTE_011 = @TODAY,
			--@ATTRIBUTE_012 = @LEDGER_ACCOUNT,
			--@ATTRIBUTE_013 = @LEDGER_ACCOUNT_NAME,
			--@ATTRIBUTE_014 = @VAT_RATE,
			--@ATTRIBUTE_015 = @VAT_RATE_NAME,
			@ATTRIBUTE_016 = @R_VAT_PERCENTAGE,
			@ATTRIBUTE_017 = @R_RATE_AMOUNT,
			@ATTRIBUTE_018 = @R_QUANTITY,
			@ATTRIBUTE_019 = @R_TOTAL_AMOUNT,
			--@ATTRIBUTE_020 = @DISCOUNT_PERCENTAGE,
			--@ATTRIBUTE_021 = @DISCOUNT_AMOUNT,
			@ATTRIBUTE_022 = @R_TOTAL_AMOUNT,
			@ATTRIBUTE_023 = @R_VAT_AMOUNT,
			@ATTRIBUTE_024 = @R_GROSS_AMOUNT,	
			
			@ATTRIBUTE_026 = @T_Status_Id,
