-- Insert Event Attendees
	
Declare @A_LabelName nvarchar(100), @A_FirstName nvarchar(100), @A_LastName nvarchar(100), @A_Email nvarchar(100), @A_Dietary_Req nvarchar(100), @A_Telephone nvarchar(100)
Declare @Contant_Attendee_Seq_Id bigint, @Attendee_Seq_Id bigint, @AttendeeName nvarchar(100), @AttendeeNamesId bigint
declare @BId bigint, @BName nvarchar(200), @A_Title nvarchar(100), @A_Salutation nvarchar(100), @data_source_id bigint, @data_source_desc nvarchar(100)

select @data_source_id = seq_id, @data_source_desc = attribute_001 from  [srm-customentities].dbo.cus_entity_data 
where deleted = 'N' and srm_client_entities_seq_id = @SRM_CLIENT_ENTITIES_SEQ_ID_ACCOUNT_CONTACT_SOURCE and attribute_001 like '%web%'

DECLARE Cur_records  CURSOR LOCAL STATIC For

select ltrim(rtrim(Attribute_001)),ltrim(rtrim(Attribute_003)),ltrim(rtrim(Attribute_004)),ltrim(rtrim(Attribute_005)),ltrim(rtrim(Attribute_006)),ltrim(rtrim(Attribute_007)),ltrim(rtrim(Attribute_002))
 from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA where SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVT_BOOKING_ATTENDEE and ATTRIBUTE_009 = @BOOKING_ID
 
OPEN Cur_records -- open the cursor

FETCH NEXT FROM Cur_records INTO @A_LabelName,@A_FirstName,@A_LastName,@A_Email,@A_Dietary_Req,@A_Telephone,@A_Title
   
WHILE @@FETCH_STATUS = 0
 
BEGIN

set @TitleId= null
set @TitleName = null

select @TitleId=SEQ_ID,@TitleName=ATTRIBUTE_001
	from [SRM-CustomEntities].dbo.CUS_ENTITY_DATA 
	where SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID_TITLE and LTRIM(rtrim(ATTRIBUTE_001)) = LTRIM(rtrim(@A_Title))

set @A_LabelName = ltrim(rtrim(isnull(@A_Title, ''))) + ' ' + ltrim(rtrim(isnull(@A_FirstName, '')))  +  ' ' +ltrim(rtrim(isnull(@A_LastName, ''))) 
set @Salutation = ltrim(rtrim(isnull(@A_Title, ''))) + ' ' + ltrim(rtrim(isnull(@A_LastName, ''))) 


-- Get Next Contact Number
		EXEC [dbo].[GET_PIVOT_NEXT_ID] @UNIQUE_INDEX_ID = 1, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @PIVOT_NEXT_ID = @Contact_Number OUTPUT
		
EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
	@ATTRIBUTE_001=@A_LabelName,
	@ATTRIBUTE_005= @A_FirstName,
	@ATTRIBUTE_004= @A_LastName,
	@ATTRIBUTE_010= @Salutation,
	@ATTRIBUTE_056 =@A_Email,
	@ATTRIBUTE_053=@A_Telephone,
	@ATTRIBUTE_003=@Contact_Number,
	@ATTRIBUTE_025=@TitleId,
	@ATTRIBUTE_026=@TitleName,
	@ATTRIBUTE_186 = @data_source_id,
	@ATTRIBUTE_187 = @data_source_desc,
	@ATTRIBUTE_007 = @A_LabelName,
	@ATTRIBUTE_199=@A_LabelName,
	@ATTRIBUTE_149=@DepartmentSeqId,
	@ATTRIBUTE_150=@Department,
	@ATTRIBUTE_152=@RelationshipManagerSeqId,
	@ATTRIBUTE_153=@RelationshipManager,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_CONTACT,
				@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
				@DATE_CREATED = @TODAY,
				@CREATED_BY = @USER,
				@RETURN_SEQ_ID = @Contant_Attendee_Seq_Id OUTPUT,
				@ERROR = @ERROR OUTPUT,
				@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

set @AttendeeName =null

IF ISNULL(@Contant_Attendee_Seq_Id, '') <> ''  -- GET Booker @CONTACT_SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'CONTACT', @ATTRIBUTE_DISPLAY_NAME = 'RECORD_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @Attendee_Seq_Id, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @Contant_Attendee_Seq_Id OUTPUT, @DESCRIPTION = @AttendeeName OUTPUT
		PRINT '@CONTACT_NAME ' + CAST(@BookerName AS NVARCHAR(100))
	END
	
	IF ISNULL(@Event_Delegate_Id, '') <> ''  -- GET Booker @CONTACT_SEQ_ID NAME
	BEGIN
		EXEC [dbo].[GET_SINGLE_ID_DESCRIPTION] @ENTITY_DISPLAY_NAME = 'Event_Delegate', @ATTRIBUTE_DISPLAY_NAME = 'RECORD_ID', @OPERATOR_ID = 3, @SEARCH_VALUE = @Event_Delegate_Id, @SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID, @ID = @BId OUTPUT, @DESCRIPTION = @BName OUTPUT
		PRINT '@Event_Delegate ' + CAST(@BookerName AS NVARCHAR(100))
	END
	

EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
	@ATTRIBUTE_002=@Contant_Attendee_Seq_Id,
	@ATTRIBUTE_003=@AttendeeName,
	@ATTRIBUTE_004=@BId,
	@ATTRIBUTE_005=@BName,
				@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_DELEGATE_NAMES,
				@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
				@DATE_CREATED = @TODAY,
				@CREATED_BY = @USER,
				@RETURN_SEQ_ID = @AttendeeNamesId OUTPUT,
				@ERROR = @ERROR OUTPUT,
				@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
				
				
			IF ISNULL(@A_Dietary_Req, '') <> ''
		begin
				EXEC [DBO].[GET_INSERT_CUS_ENTITY_DATA]
			@ATTRIBUTE_001=@A_Dietary_Req,
			@ATTRIBUTE_005=@Reg_Id,
			@ATTRIBUTE_004= @Event_Reg_Seq_Id,
			@ATTRIBUTE_002=@SpecialReqId,
			@ATTRIBUTE_003= @SpecialReq,
			@ATTRIBUTE_008=@Contant_Attendee_Seq_Id,
			@ATTRIBUTE_009=@AttendeeName,
			@ATTRIBUTE_006= @EventId,
			@ATTRIBUTE_007= @EventName,
						@SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_EVT_REG_SPECIAL_REQUIREMENT,
						@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
						@DATE_CREATED = @TODAY,
						@CREATED_BY = @USER,
						--@RETURN_SEQ_ID = @EVENT_RATE_SEQ_ID OUTPUT,
						@ERROR = @ERROR OUTPUT,
						@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
					
		end
	 

FETCH NEXT FROM Cur_records INTO @A_LabelName,@A_FirstName,@A_LastName,@A_Email,@A_Dietary_Req,@A_Telephone,@A_Title
END
 
CLOSE Cur_records -- close the cursor

DEALLOCATE Cur_records


	 
	
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = 'Process completed successfully'
  
	SELECT @ERROR AS Error, @ERROR_DESCRIPTION AS ErrorDescription, @EVENT_REGISTRATION_SEQ_ID as EVENT_REGISTRATION_SEQ_ID
	
	
END








;




