CREATE PROCEDURE [dbo].[INSERT_JAM_EMAIL]
	-- Add the parameters for the stored procedure here
	@FromAddress VARCHAR(200) = NULL,
	@ToAddress VARCHAR(200) = NULL,
	@EmailBody VARCHAR(4000) = NULL,
	@EmailSubject VARCHAR(500) = NULL,
	@SendingPriority INT = NULL,
	@JamEmailStatusTypeId VARCHAR(200) = NULL
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	INSERT INTO [SRM-Emails].[dbo].[JAM_EMAILS]
           ([FROM_ADDRESS]
           ,[TO_ADDRESS]          
           ,[EMAIL_BODY]
           ,[EMAIL_SUBJECT]
           ,[SENDING_PRIORITY]
           ,[JAM_EMAIL_STATUS_TYPE_ID]
		   ,[NO_OF_SENDING_RETRY]
		   ,[EMAIL_SENDING_PRIORITY]
		   ,[IS_SENT])
     VALUES
           (@FromAddress
           ,@ToAddress          
           ,@EmailBody
           ,@EmailSubject
           ,@SendingPriority
           ,@JamEmailStatusTypeId
		   ,0
		   ,0
		   ,0)


END


;


---- *****************************************************************************************************************
---- Created By: Nimra Azeem
---- Date Created: 20/10/2025
---- Summary: A process to insert Tasks for Events from Task Template
----******************************************************************************************************************

CREATE PROCEDURE [dbo].[INSERT_TASKS_FROM_TASK_TEMPLATE]
	@p_EVENT_RECORD_ID BIGINT,					-- SEQ_ID OF EVENT
	@p_TASK_TEMPLATE_RECORD_ID BIGINT,			-- SEQ_ID OF TASK TEMPLATE
	@p_USERS_EMAIL NVARCHAR(200)				-- EMAIL OF oomi USER
AS
BEGIN

--DECLARE @p_EVENT_RECORD_ID BIGINT = 44733				-- SEQ_ID OF EVENT
--DECLARE @p_TASK_TEMPLATE_RECORD_ID BIGINT = 43907		-- SEQ_ID OF TASK TEMPLATE
--DECLARE @p_USERS_EMAIL NVARCHAR(200) = 'smart@oomi.co.uk'


	DECLARE @p_CLIENT_ID BIGINT
	DECLARE @LOGGED_IN_USER NVARCHAR(200)

	DECLARE @EVENT_ENTITY_SEQ_ID BIGINT
	DECLARE @TASK_TEMPLATE_DETAIL_ENTITY_SEQ_ID BIGINT
	DECLARE @EVENT_FIELD_ENTITY_SEQ_ID BIGINT
	DECLARE @TASK_PRIORITY_ENTITY_SEQ_ID BIGINT
	DECLARE @TASK_STATUS_ENTITY_SEQ_ID BIGINT
	DECLARE @TASK_ENTITY_SEQ_ID BIGINT

	DECLARE @TTD_TASK_TEMPLATE_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @TTD_EVENT_FIELD_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @EVENT_FIELD_SYSTEM_NAME_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @TASK_STATUS_DEFAULT_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @TASK_PRIORITY_DEFAULT_ATTRIBUTE_SEQ_ID BIGINT
	
	SET @EVENT_ENTITY_SEQ_ID = 112809
	SET @TASK_TEMPLATE_DETAIL_ENTITY_SEQ_ID = 113036
	SET @EVENT_FIELD_ENTITY_SEQ_ID = 113034
	SET @TASK_PRIORITY_ENTITY_SEQ_ID = 112912
	SET @TASK_STATUS_ENTITY_SEQ_ID = 112911
	SET @TASK_ENTITY_SEQ_ID = 112762

	SET @TTD_EVENT_FIELD_ATTRIBUTE_SEQ_ID = 3068922
	SET @EVENT_FIELD_SYSTEM_NAME_ATTRIBUTE_SEQ_ID = 3068944
	SET @TTD_TASK_TEMPLATE_ATTRIBUTE_SEQ_ID = 3068920
	SET @TASK_STATUS_DEFAULT_ATTRIBUTE_SEQ_ID = 3065255
	SET @TASK_PRIORITY_DEFAULT_ATTRIBUTE_SEQ_ID = 3065272

	-- Get Client ID on the basis of User Email
	SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USERS_EMAIL
	SELECT @LOGGED_IN_USER = LOGIN_USER_NAME FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USERS_EMAIL

	DECLARE @EVENT_ID NVARCHAR(200)
	DECLARE @strSQL NVARCHAR(max)
	DECLARE @paramStr NVARCHAR(max)
	DECLARE @EVENT_FIELD_RECORD_ID BIGINT
	DECLARE @EVENT_FIELD_DESCRIPTION NVARCHAR(200)
	DECLARE @EVENT_FIELD_SYSTEM_NAME NVARCHAR(200)
	DECLARE @TASK_TEMPLATE_DETAIL_RECORD_ID BIGINT
	DECLARE @TASK_TEMPLATE_DETAIL_DESCRIPTION NVARCHAR(500)
	DECLARE @TASK_TEMPLATE_RECORD_ID BIGINT
	DECLARE @TASK_TEMPLATE_DESCRIPTION NVARCHAR(200)
	DECLARE @TASK_REMINDER NVARCHAR(200)
	DECLARE @TASK_DAYS BIGINT
	DECLARE @TASK_OWNER BIGINT
	DECLARE @TASK_OWNER_NAME NVARCHAR(200)
	DECLARE @ASSIGNED_TO_TEAM BIGINT
	DECLARE @ASSIGNED_TO_TEAM_NAME NVARCHAR(200)
	DECLARE @ASSIGNED_TO_USER BIGINT
	DECLARE @ASSIGNED_TO_USER_NAME NVARCHAR(200)
	DECLARE @TASK_DATE DATE
	DECLARE @TASK_STATUS_RECORD_ID BIGINT
	DECLARE @TASK_STATUS_DESCRIPTION NVARCHAR(200)
	DECLARE @TASK_PRIORITY_RECORD_ID BIGINT
	DECLARE @TASK_PRIORITY_DESCRIPTION NVARCHAR(200)
	DECLARE @TASK_PRIORITY_SET_REMINDER NVARCHAR(200)
	DECLARE @TASK_PRIORITY_DEFAULT_REMINDER_TIME NVARCHAR(200)
	DECLARE @TASK_PRIORITY_INCREASE_DAYS_FOR_DUE_DATE BIGINT
	DECLARE @TASK_PRIORITY_REMINDER_DAYS_BEFORE_DUE_DATE BIGINT
	DECLARE @DUE_DATE NVARCHAR(200)
	DECLARE @REMINDER_DATE NVARCHAR(200)
	DECLARE @NEW_TASK_RECORD BIGINT
	

	BEGIN TRAN oomiTran
	-----GETTING EVENT ID AND STORING IT IN VARIABLE
	SET @strSQL = 'SELECT @EVENT_ID = ATTRIBUTE_001 FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + ']..CUS_ENTITY_DATA WITH (NOLOCK)
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @EVENT_ENTITY_SEQ_ID AND SEQ_ID = @p_EVENT_RECORD_ID'

	SET @paramStr = N'@EVENT_ID NVARCHAR(200) OUTPUT, 
	@EVENT_ENTITY_SEQ_ID BIGINT, 
	@p_EVENT_RECORD_ID BIGINT'

	EXEC sp_executesql 
	@strSQL, 
	@paramStr,
	@EVENT_ID = @EVENT_ID OUTPUT,
	@EVENT_ENTITY_SEQ_ID = @EVENT_ENTITY_SEQ_ID,
	@p_EVENT_RECORD_ID = @p_EVENT_RECORD_ID

	PRINT @EVENT_ID
	
	--GETTING DEFAULT TASK STATUS
	SET @strSQL = 'SELECT @TASK_STATUS_RECORD_ID = TS.SEQ_ID, @TASK_STATUS_DESCRIPTION = TS.ATTRIBUTE_001  
	FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + ']..CUS_ENTITY_DATA TS WITH (NOLOCK) 
	,[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I  
	WHERE TS.DELETED != ''Y'' AND I.DELETED != ''Y'' AND TS.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@TASK_STATUS_ENTITY_SEQ_ID AS NVARCHAR(100)) +
	' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@TASK_STATUS_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
	CAST(@TASK_STATUS_DEFAULT_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_BOOLEAN = ''Y'' AND I.CUS_ENTITY_DATA_SEQ_ID = TS.SEQ_ID '

	SET @paramStr = N'@TASK_STATUS_RECORD_ID BIGINT OUTPUT,
	@TASK_STATUS_DESCRIPTION NVARCHAR(200) OUTPUT,
	@TASK_STATUS_ENTITY_SEQ_ID BIGINT, 
	@TASK_STATUS_DEFAULT_ATTRIBUTE_SEQ_ID BIGINT'
						  
	EXEC sp_executesql 
	@strSQL, 
	@paramStr,
	@TASK_STATUS_RECORD_ID = @TASK_STATUS_RECORD_ID OUTPUT,
	@TASK_STATUS_DESCRIPTION = @TASK_STATUS_DESCRIPTION OUTPUT,
	@TASK_STATUS_ENTITY_SEQ_ID =  @TASK_STATUS_ENTITY_SEQ_ID,
	@TASK_STATUS_DEFAULT_ATTRIBUTE_SEQ_ID = @TASK_STATUS_DEFAULT_ATTRIBUTE_SEQ_ID
	PRINT @TASK_STATUS_RECORD_ID
	PRINT @TASK_STATUS_DESCRIPTION
	
	--GETTING DEFAULT TASK PRIORITY
	SET @strSQL = 'SELECT @TASK_PRIORITY_RECORD_ID = TP.SEQ_ID, @TASK_PRIORITY_DESCRIPTION = TP.ATTRIBUTE_001
	, @TASK_PRIORITY_SET_REMINDER = TP.ATTRIBUTE_005, @TASK_PRIORITY_DEFAULT_REMINDER_TIME = TP.ATTRIBUTE_006
	, @TASK_PRIORITY_INCREASE_DAYS_FOR_DUE_DATE = TP.ATTRIBUTE_007, @TASK_PRIORITY_REMINDER_DAYS_BEFORE_DUE_DATE = TP.ATTRIBUTE_008
	FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + ']..CUS_ENTITY_DATA TP WITH (NOLOCK) 
	,[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I  
	WHERE TP.DELETED != ''Y'' AND I.DELETED != ''Y'' AND TP.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@TASK_PRIORITY_ENTITY_SEQ_ID AS NVARCHAR(100)) +
	' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@TASK_PRIORITY_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
	CAST(@TASK_PRIORITY_DEFAULT_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_BOOLEAN = ''Y'' AND I.CUS_ENTITY_DATA_SEQ_ID = TP.SEQ_ID '

	SET @paramStr = N'@TASK_PRIORITY_RECORD_ID BIGINT OUTPUT,
	@TASK_PRIORITY_DESCRIPTION NVARCHAR(200) OUTPUT,
	@TASK_PRIORITY_SET_REMINDER NVARCHAR(200) OUTPUT,
	@TASK_PRIORITY_DEFAULT_REMINDER_TIME NVARCHAR(200) OUTPUT,
	@TASK_PRIORITY_INCREASE_DAYS_FOR_DUE_DATE BIGINT OUTPUT,
	@TASK_PRIORITY_REMINDER_DAYS_BEFORE_DUE_DATE BIGINT OUTPUT,
	@TASK_PRIORITY_ENTITY_SEQ_ID BIGINT, 
	@TASK_PRIORITY_DEFAULT_ATTRIBUTE_SEQ_ID BIGINT'

	EXEC sp_executesql 
	@strSQL, 
	@paramStr,
	@TASK_PRIORITY_RECORD_ID = @TASK_PRIORITY_RECORD_ID OUTPUT,
	@TASK_PRIORITY_DESCRIPTION = @TASK_PRIORITY_DESCRIPTION OUTPUT,
	@TASK_PRIORITY_SET_REMINDER = @TASK_PRIORITY_SET_REMINDER OUTPUT,
	@TASK_PRIORITY_DEFAULT_REMINDER_TIME = @TASK_PRIORITY_DEFAULT_REMINDER_TIME OUTPUT,
	@TASK_PRIORITY_INCREASE_DAYS_FOR_DUE_DATE  = @TASK_PRIORITY_INCREASE_DAYS_FOR_DUE_DATE  OUTPUT,
	@TASK_PRIORITY_REMINDER_DAYS_BEFORE_DUE_DATE = @TASK_PRIORITY_REMINDER_DAYS_BEFORE_DUE_DATE OUTPUT,
	@TASK_PRIORITY_ENTITY_SEQ_ID =  @TASK_PRIORITY_ENTITY_SEQ_ID,
	@TASK_PRIORITY_DEFAULT_ATTRIBUTE_SEQ_ID = @TASK_PRIORITY_DEFAULT_ATTRIBUTE_SEQ_ID
		
	--SET PRIORITY TIME IF REMINDER EXISTS
	SET @TASK_PRIORITY_DEFAULT_REMINDER_TIME = CASE WHEN ISNULL(@TASK_PRIORITY_SET_REMINDER,'N') = 'Y' THEN ISNULL(@TASK_PRIORITY_DEFAULT_REMINDER_TIME, '00:00') ELSE NULL END;
			

	-- Temporary Table to hold data of distinct fields
	CREATE TABLE #TEMP_EVENT_FIELDS
	(EVENT_FIELD_RECORD_ID BIGINT,
	EVENT_FIELD_DESCRIPTION NVARCHAR(200),
	EVENT_FIELD_SYSTEM_NAME NVARCHAR(200));

	--CREATING TABLE TO STORE TEMPLATE DETAILS DATA W.R.T. EVENT FIELD
	CREATE TABLE #TEMP_TASK_TEMPLATE_DETAIL
	(TASK_TEMPLATE_DETAIL_RECORD_ID BIGINT,
	TASK_TEMPLATE_DETAIL_DESCRIPTION NVARCHAR(500),
	TASK_TEMPLATE_RECORD_ID BIGINT,
	TASK_TEMPLATE_DESCRIPTION NVARCHAR(200),
	TASK_REMINDER NVARCHAR(200),
	TASK_DATE DATE,
	DUE_DATE DATE,
	REMINDER_DATE DATE,
	TASK_DAYS BIGINT,
	TASK_OWNER BIGINT,
	TASK_OWNER_NAME NVARCHAR(200),
	ASSIGNED_TO_TEAM BIGINT,
	ASSIGNED_TO_TEAM_NAME NVARCHAR(200),
	ASSIGNED_TO_USER BIGINT,
	ASSIGNED_TO_USER_NAME NVARCHAR(200));
	
	--Inserting data in Temp table for distinct fields
	SET @strSQL = 'INSERT INTO #TEMP_EVENT_FIELDS (EVENT_FIELD_RECORD_ID, EVENT_FIELD_DESCRIPTION,EVENT_FIELD_SYSTEM_NAME) 
	SELECT DISTINCT TTD.ATTRIBUTE_004,  TTD.ATTRIBUTE_005, I3.ATTRIBUTE_STRING
	FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA TTD, 
	[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I  
	,[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I2
	,[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I3
	WHERE TTD.DELETED != ''Y'' AND I.DELETED != ''Y'' AND TTD.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@TASK_TEMPLATE_DETAIL_ENTITY_SEQ_ID AS NVARCHAR(100)) +
	' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@TASK_TEMPLATE_DETAIL_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
	CAST(@TTD_TASK_TEMPLATE_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = '+CAST(@p_TASK_TEMPLATE_RECORD_ID AS NVARCHAR(100)) + ' AND TTD.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID 
	AND I2.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@TASK_TEMPLATE_DETAIL_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
	CAST(@TTD_EVENT_FIELD_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I2.CUS_ENTITY_DATA_SEQ_ID =  TTD.SEQ_ID AND I2.DELETED != ''Y'' 
	AND I3.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_FIELD_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I3.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
	CAST(@EVENT_FIELD_SYSTEM_NAME_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I3.CUS_ENTITY_DATA_SEQ_ID = I2.ATTRIBUTE_DECIMAL AND I3.DELETED != ''Y'' 
	ORDER BY TTD.ATTRIBUTE_004'
	PRINT @strSQL
	EXECUTE (@strSQL)

	DECLARE curField CURSOR FOR			---Cursor to loop through each distinct field
	SELECT EVENT_FIELD_RECORD_ID, EVENT_FIELD_DESCRIPTION, EVENT_FIELD_SYSTEM_NAME FROM #TEMP_EVENT_FIELDS
	WHERE EVENT_FIELD_RECORD_ID IS NOT NULL
	ORDER BY EVENT_FIELD_RECORD_ID

	OPEN curField
	FETCH curField INTO @EVENT_FIELD_RECORD_ID,@EVENT_FIELD_DESCRIPTION,@EVENT_FIELD_SYSTEM_NAME
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		--GETTING EVENT DATE BASED ON ATTRIBUTE SYSTEM NAME FROM TASK TEMPLATE
		SET @strSQL = 'SELECT @TASK_DATE = ' + CAST(@EVENT_FIELD_SYSTEM_NAME AS NVARCHAR(100)) + '  FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + ']..CUS_ENTITY_DATA WITH (NOLOCK)
		WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @EVENT_ENTITY_SEQ_ID AND SEQ_ID = @p_EVENT_RECORD_ID'

		SET @paramStr = N'@TASK_DATE DATE OUTPUT, 
		@EVENT_ENTITY_SEQ_ID BIGINT, 
		@p_EVENT_RECORD_ID BIGINT'

		EXEC sp_executesql 
		@strSQL, 
		@paramStr,
		@TASK_DATE = @TASK_DATE OUTPUT,
		@EVENT_ENTITY_SEQ_ID = @EVENT_ENTITY_SEQ_ID,
		@p_EVENT_RECORD_ID = @p_EVENT_RECORD_ID
			
		
		--Inserting Data of Task Template Detail in Temp Table
		SET @strSQL = 'INSERT INTO #TEMP_TASK_TEMPLATE_DETAIL (TASK_DATE, DUE_DATE,REMINDER_DATE, TASK_TEMPLATE_DETAIL_RECORD_ID, TASK_TEMPLATE_DETAIL_DESCRIPTION,TASK_TEMPLATE_RECORD_ID,TASK_TEMPLATE_DESCRIPTION,
		TASK_REMINDER, TASK_DAYS,TASK_OWNER, TASK_OWNER_NAME,ASSIGNED_TO_TEAM, ASSIGNED_TO_TEAM_NAME, ASSIGNED_TO_USER,ASSIGNED_TO_USER_NAME)  

		SELECT '''+ CAST(CAST(ISNULL(@TASK_DATE, '') AS DATE) AS NVARCHAR(100))+ ''', ''' + CAST(CAST(ISNULL(@DUE_DATE, '') AS DATE) AS NVARCHAR(100))+ ''', ''' + CAST(CAST(ISNULL(@REMINDER_DATE, '') AS DATE) AS NVARCHAR(100)) +''',' + 'TTD.SEQ_ID, TTD.ATTRIBUTE_001, TTD.ATTRIBUTE_002, TTD.ATTRIBUTE_003, 
		TTD.ATTRIBUTE_006, TTD.ATTRIBUTE_008, TTD.ATTRIBUTE_009, TTD.ATTRIBUTE_010, TTD.ATTRIBUTE_011, TTD.ATTRIBUTE_012, TTD.ATTRIBUTE_013, TTD.ATTRIBUTE_014
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA TTD, 
		[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I  
		,[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I2 
		WHERE TTD.DELETED != ''Y'' AND I.DELETED != ''Y'' AND TTD.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@TASK_TEMPLATE_DETAIL_ENTITY_SEQ_ID AS NVARCHAR(100)) +
		' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@TASK_TEMPLATE_DETAIL_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@TTD_TASK_TEMPLATE_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = '+CAST(@p_TASK_TEMPLATE_RECORD_ID AS NVARCHAR(100)) + ' AND TTD.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID
		AND I2.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@TASK_TEMPLATE_DETAIL_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@TTD_EVENT_FIELD_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I2.CUS_ENTITY_DATA_SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID AND I2.ATTRIBUTE_DECIMAL = ' + CAST(@EVENT_FIELD_RECORD_ID AS NVARCHAR(100)) +' AND I2.DELETED != ''Y'''
		PRINT @strSQL
		
		EXECUTE (@strSQL)
		
		FETCH curField INTO @EVENT_FIELD_RECORD_ID, @EVENT_FIELD_DESCRIPTION, @EVENT_FIELD_SYSTEM_NAME
	END
	
	CLOSE curField
	DEALLOCATE curField
		
	----Sub Cursor to insert task for each row
	DECLARE SubcurField CURSOR FOR	
	SELECT * FROM #TEMP_TASK_TEMPLATE_DETAIL

	OPEN SubcurField
	FETCH SubcurField INTO @TASK_TEMPLATE_DETAIL_RECORD_ID, @TASK_TEMPLATE_DETAIL_DESCRIPTION,@TASK_TEMPLATE_RECORD_ID,@TASK_TEMPLATE_DESCRIPTION,
	@TASK_REMINDER,@TASK_DATE,@DUE_DATE,@REMINDER_DATE,@TASK_DAYS,@TASK_OWNER, @TASK_OWNER_NAME,@ASSIGNED_TO_TEAM, @ASSIGNED_TO_TEAM_NAME, @ASSIGNED_TO_USER,@ASSIGNED_TO_USER_NAME
		
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		IF ISNULL(@TASK_DATE, '')!= ''
		BEGIN
			SET @TASK_DATE = CASE WHEN ISNULL(@TASK_REMINDER, '') = 'Before' THEN [SRM-Framework_New].dbo.AddWorkingDays(@TASK_DATE, (0-ISNULL(@TASK_DAYS,0)))
			WHEN ISNULL(@TASK_REMINDER, '') = 'After' THEN [SRM-Framework_New].dbo.AddWorkingDays(@TASK_DATE, @TASK_DAYS) ELSE @TASK_DATE END
			
			SET @DUE_DATE = @TASK_DATE
			--SET @DUE_DATE = CASE WHEN ISNULL(@TASK_PRIORITY_INCREASE_DAYS_FOR_DUE_DATE, 0) > 0 THEN DATEADD(DAY, @TASK_PRIORITY_INCREASE_DAYS_FOR_DUE_DATE, @TASK_DATE) ELSE @TASK_DATE END;
					
			--------CALCULATING REMINDER_DATES AS PER PRIORITY
			SET @REMINDER_DATE = CASE WHEN ISNULL(@TASK_PRIORITY_SET_REMINDER,'N') = 'Y' THEN [SRM-Framework_New].dbo.AddWorkingDays(@DUE_DATE, (0-ISNULL(@TASK_PRIORITY_REMINDER_DAYS_BEFORE_DUE_DATE,0))) ELSE NULL END;
			
			PRINT 'Due Date: '+ CAST(@DUE_DATE AS NVARCHAR(100))
			PRINT 'Reminder Date: '+ CAST(@REMINDER_DATE AS NVARCHAR(100))
			
			-- Construct dynamic SQL
			SET @strSQL = N'
			INSERT INTO [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10)) + N'].dbo.CUS_ENTITY_DATA
			(
			SRM_CLIENTS_SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_001, ATTRIBUTE_002, ATTRIBUTE_003,
			ATTRIBUTE_005, ATTRIBUTE_006, ATTRIBUTE_007, ATTRIBUTE_008, ATTRIBUTE_009, ATTRIBUTE_010, ATTRIBUTE_011,
			ATTRIBUTE_012, ATTRIBUTE_013, ATTRIBUTE_014, ATTRIBUTE_017, ATTRIBUTE_018, ATTRIBUTE_019, ATTRIBUTE_026,
			ATTRIBUTE_027, ATTRIBUTE_046, ATTRIBUTE_047, ATTRIBUTE_048, ATTRIBUTE_049,
			DELETED, DATE_CREATED, CREATED_BY
			)
			VALUES
			(
			@p_CLIENT_ID,
			@TASK_ENTITY_SEQ_ID,
			@TASK_TEMPLATE_DETAIL_DESCRIPTION,
			@TASK_TEMPLATE_DETAIL_DESCRIPTION,
			CONVERT(NVARCHAR(100), @DUE_DATE, 23),
			@TASK_OWNER,
			@TASK_OWNER_NAME,
			@ASSIGNED_TO_USER,
			@ASSIGNED_TO_USER_NAME,
			@ASSIGNED_TO_TEAM,
			@ASSIGNED_TO_TEAM_NAME,
			@TASK_PRIORITY_RECORD_ID,
			@TASK_PRIORITY_DESCRIPTION,
			@TASK_STATUS_RECORD_ID,
			@TASK_STATUS_DESCRIPTION,
			@TASK_PRIORITY_SET_REMINDER,
			CONVERT(NVARCHAR(100), @REMINDER_DATE, 23),
			@TASK_PRIORITY_DEFAULT_REMINDER_TIME,
			@p_EVENT_RECORD_ID,
			@EVENT_ID,
			@TASK_TEMPLATE_RECORD_ID,
			@TASK_TEMPLATE_DESCRIPTION,
			@TASK_TEMPLATE_DETAIL_RECORD_ID,
			@TASK_TEMPLATE_DETAIL_DESCRIPTION,
			''N'', GETDATE(), @LOGGED_IN_USER
			);

			SET @NEW_TASK_RECORD = SCOPE_IDENTITY();
			';

			-- Execute dynamic SQL safely with parameter mapping
			EXEC sp_executesql
			@strSQL,
			N'
			@p_CLIENT_ID INT,
			@TASK_ENTITY_SEQ_ID INT,
			@TASK_TEMPLATE_DETAIL_DESCRIPTION NVARCHAR(200),
			@DUE_DATE DATE,
			@TASK_OWNER INT,
			@TASK_OWNER_NAME NVARCHAR(200),
			@ASSIGNED_TO_USER INT,
			@ASSIGNED_TO_USER_NAME NVARCHAR(200),
			@ASSIGNED_TO_TEAM INT,
			@ASSIGNED_TO_TEAM_NAME NVARCHAR(100),
			@TASK_PRIORITY_RECORD_ID INT,
			@TASK_PRIORITY_DESCRIPTION NVARCHAR(100),
			@TASK_STATUS_RECORD_ID INT,
			@TASK_STATUS_DESCRIPTION NVARCHAR(100),
			@TASK_PRIORITY_SET_REMINDER NVARCHAR(100),
			@REMINDER_DATE DATE,
			@TASK_PRIORITY_DEFAULT_REMINDER_TIME NVARCHAR(10),
			@p_EVENT_RECORD_ID INT,
			@EVENT_ID NVARCHAR(100),
			@TASK_TEMPLATE_RECORD_ID INT,
			@TASK_TEMPLATE_DESCRIPTION NVARCHAR(100),
			@TASK_TEMPLATE_DETAIL_RECORD_ID INT,
			@LOGGED_IN_USER NVARCHAR(200),
			@NEW_TASK_RECORD INT OUTPUT
			',
			@p_CLIENT_ID = @p_CLIENT_ID,
			@TASK_ENTITY_SEQ_ID = @TASK_ENTITY_SEQ_ID,
			@TASK_TEMPLATE_DETAIL_DESCRIPTION = @TASK_TEMPLATE_DETAIL_DESCRIPTION,
			@DUE_DATE = @DUE_DATE,
			@TASK_OWNER = @TASK_OWNER,
			@TASK_OWNER_NAME = @TASK_OWNER_NAME,
			@ASSIGNED_TO_USER = @ASSIGNED_TO_USER,
			@ASSIGNED_TO_USER_NAME = @ASSIGNED_TO_USER_NAME,
			@ASSIGNED_TO_TEAM = @ASSIGNED_TO_TEAM,
			@ASSIGNED_TO_TEAM_NAME = @ASSIGNED_TO_TEAM_NAME,
			@TASK_PRIORITY_RECORD_ID = @TASK_PRIORITY_RECORD_ID,
			@TASK_PRIORITY_DESCRIPTION = @TASK_PRIORITY_DESCRIPTION,
			@TASK_STATUS_RECORD_ID = @TASK_STATUS_RECORD_ID,
			@TASK_STATUS_DESCRIPTION = @TASK_STATUS_DESCRIPTION,
			@TASK_PRIORITY_SET_REMINDER = @TASK_PRIORITY_SET_REMINDER,
			@REMINDER_DATE = @REMINDER_DATE,
			@TASK_PRIORITY_DEFAULT_REMINDER_TIME = @TASK_PRIORITY_DEFAULT_REMINDER_TIME,
			@p_EVENT_RECORD_ID = @p_EVENT_RECORD_ID,
			@EVENT_ID = @EVENT_ID,
			@TASK_TEMPLATE_RECORD_ID = @TASK_TEMPLATE_RECORD_ID,
			@TASK_TEMPLATE_DESCRIPTION = @TASK_TEMPLATE_DESCRIPTION,
			@TASK_TEMPLATE_DETAIL_RECORD_ID = @TASK_TEMPLATE_DETAIL_RECORD_ID,
			@LOGGED_IN_USER = @LOGGED_IN_USER,
			@NEW_TASK_RECORD = @NEW_TASK_RECORD OUTPUT;

			-- Assign the new identity value to your variable

			PRINT '@NEW_TASK_RECORD ' + CAST(ISNULL(@NEW_TASK_RECORD, 0) AS NVARCHAR(20))

			--EXECUTING PIVOT
			SET @strSQL = 'EXEC [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..[GET_POPULATE_PIVOT_TABLE_MAIN]  
							@SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(ISNULL(@TASK_ENTITY_SEQ_ID, 0) AS NVARCHAR(10))+ ',
							@CUS_ENTITY_DATA_SEQ_ID  = ' + CAST(ISNULL(@NEW_TASK_RECORD, 0) AS NVARCHAR(10))+ ',
							@SRM_CLIENTS_SEQ_ID = ' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))
			PRINT @strSQL
			EXECUTE (@strSQL)	
			
		END

		SELECT @TASK_TEMPLATE_DETAIL_RECORD_ID, @TASK_TEMPLATE_DETAIL_DESCRIPTION,@TASK_TEMPLATE_RECORD_ID,@TASK_TEMPLATE_DESCRIPTION,
		@TASK_REMINDER,@TASK_DATE,@DUE_DATE,@REMINDER_DATE,@TASK_DAYS,@TASK_OWNER, @TASK_OWNER_NAME,@ASSIGNED_TO_TEAM, @ASSIGNED_TO_TEAM_NAME, @ASSIGNED_TO_USER,@ASSIGNED_TO_USER_NAME
	
		FETCH SubcurField INTO @TASK_TEMPLATE_DETAIL_RECORD_ID, @TASK_TEMPLATE_DETAIL_DESCRIPTION,@TASK_TEMPLATE_RECORD_ID,@TASK_TEMPLATE_DESCRIPTION,
		@TASK_REMINDER,@TASK_DATE,@DUE_DATE,@REMINDER_DATE,@TASK_DAYS,@TASK_OWNER, @TASK_OWNER_NAME,@ASSIGNED_TO_TEAM, @ASSIGNED_TO_TEAM_NAME, @ASSIGNED_TO_USER,@ASSIGNED_TO_USER_NAME
	END
	
	CLOSE SubcurField
	DEALLOCATE SubcurField
	
	DROP TABLE #TEMP_TASK_TEMPLATE_DETAIL
	DROP TABLE #TEMP_EVENT_FIELDS

	IF @@ERROR <> 0 
		ROLLBACK TRAN oomiTran
	ELSE
		COMMIT TRAN oomiTran

END;





CREATE PROCEDURE [dbo].[IOG_PRINT_CREDIT_NOTE]
-- Add the parameters for the stored procedure here
@OUTPUt_SEQ_ID bigint,
@CREDIT_NOTE_SEQ_ID bigint
AS
BEGIN
-- SET NOCOUNT ON added to prevent extra result sets from
-- interfering with SELECT statements.
SET NOCOUNT ON;

PRINT 'start'

Declare @TotalRecords int
Declare @Account_SRM_Client_Entity_SEQ_ID bigint
DECLARE @STR_SQL NVARCHAR(4000)
DECLARE @Counter int
DECLARE @Quantity NVARCHAR(15)
DECLARE @Short_Description NVARCHAR(100)
DECLARE @Unit_Price MONEY
DECLARE @Discount_Amount MONEY 
DECLARE @Net_Amount MONEY 
DECLARE @Vat_Amount MONEY 
DECLARE @Gross_Amount MONEY 

Select @TotalRecords = COUNT(SEQ_ID) FROM [SRM-CustomEntities_132]..CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=47836
AND ATTRIBUTE_002=@CREDIT_NOTE_SEQ_ID AND ISNULL(DELETED,'N')='N'


DECLARE CurMain CURSOR LOCAL STATIC FOR

SELECT ATTRIBUTE_026	QUANTITY, 
ATTRIBUTE_059	SHORT_DESCRIPTION,
ATTRIBUTE_025	UNIT_PRICE,
ATTRIBUTE_029	DISCOUNT_AMOUNT,
ATTRIBUTE_030	NET_AMOUNT,
ATTRIBUTE_031	VAT_AMOUNT,
ATTRIBUTE_032	GROSS_AMOUNT

FROM [SRM-CustomEntities_132]..CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=47836
AND ATTRIBUTE_002=@CREDIT_NOTE_SEQ_ID AND ISNULL(DELETED,'N')='N'

OPEN CurMain
FETCH NEXT FROM CurMain INTO @Quantity, @Short_Description, @Unit_Price,@Discount_Amount,@Net_Amount,@Vat_Amount,@Gross_Amount

Set @Counter = 1

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT @Short_Description
		SET @STR_SQL = 'UPDATE [SRM-Workflow].dbo.WFL_OUTPUT SET'
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((9 + @Counter) * 10) + 1 as nvarchar))) + Cast(((9 + @Counter) * 10) + 1 as nvarchar) + ' = ''' + @Quantity + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((9 + @Counter) * 10) + 2 as nvarchar))) + Cast(((9 + @Counter) * 10) + 2 as nvarchar) + '=''' + REPLACE(@Short_Description,CHAR(39),CHAR(39)+CHAR(39)) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((9 + @Counter) * 10) + 3 as nvarchar))) + Cast(((9 + @Counter) * 10) + 3 as nvarchar) + '=''' + REPLACE(@Unit_Price,CHAR(39),CHAR(39)+CHAR(39)) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((9 + @Counter) * 10) + 4 as nvarchar))) + Cast(((9 + @Counter) * 10) + 4 as nvarchar) + '=''' + CAST(ISNULL(@Discount_Amount,0.00) AS NVARCHAR) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((9 + @Counter) * 10) + 5 as nvarchar))) + Cast(((9 + @Counter) * 10) + 5 as nvarchar) + '=''' + CAST(ISNULL(@Net_Amount,0.00) AS NVARCHAR) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((9 + @Counter) * 10) + 6 as nvarchar))) + Cast(((9 + @Counter) * 10) + 6 as nvarchar) + '=''' + CAST(ISNULL(@Vat_Amount,0.00) AS NVARCHAR) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((9 + @Counter) * 10) + 7 as nvarchar))) + Cast(((9 + @Counter) * 10) + 7 as nvarchar) + ' = ''' + CAST(ISNULL(@Gross_Amount,0.00) AS NVARCHAR) + ''''
		SET @STR_SQL = @STR_SQL + ' WHERE seq_id = ' + CAST(@OUTPUt_SEQ_ID AS NVARCHAR(20))
	


PRINT @STR_SQL

EXEC (@STR_SQL)

Set @Counter = @Counter + 1

FETCH NEXT FROM CurMain INTO @Quantity, @Short_Description, @Unit_Price,@Discount_Amount,@Net_Amount,@Vat_Amount,@Gross_Amount

END
CLOSE CurMain
DEALLOCATE CurMain

END


;





