		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 5 as nvarchar))) + Cast(((79 + @Counter) * 5) + 5 as nvarchar) + ' = ''' + CAST(ISNULL(@Gross_Amount,0.00) AS NVARCHAR) + ''''
