CREATE PROCEDURE [dbo].[IOG_PRINT_INVOICE_UPDATED]
-- Add the parameters for the stored procedure here
@OUTPUt_SEQ_ID bigint,
@INVOICE_SEQ_ID bigint
AS
BEGIN
-- SET NOCOUNT ON added to prevent extra result sets from
-- interfering with SELECT statements.
SET NOCOUNT ON;

PRINT 'start'

Declare @TotalRecords int
Declare @Account_SRM_Client_Entity_SEQ_ID bigint
DECLARE @STR_SQL NVARCHAR(4000)
DECLARE @Counter int
DECLARE @Quantity NVARCHAR(15)
DECLARE @Short_Description NVARCHAR(100)
DECLARE @Unit_Price MONEY
DECLARE @Discount_Amount MONEY 
DECLARE @Net_Amount MONEY 
DECLARE @Vat_Amount MONEY 
DECLARE @Gross_Amount MONEY 
DECLARE @Module NVARCHAR(100)

--Select @TotalRecords = COUNT(SEQ_ID) FROM [SRM-CustomEntities_132]..CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=47836
--AND ATTRIBUTE_002=@INVOICE_SEQ_ID AND ISNULL(DELETED,'N')='N'

SELECT
@Module = ATTRIBUTE_007	--MODULE_NAME
FROM [SRM-CustomEntities_132]..CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=47824	--INVOICE
AND SEQ_ID=@INVOICE_SEQ_ID AND ISNULL(DELETED,'N')='N'

IF(@Module = 'Membership')
BEGIN
DECLARE CurMain CURSOR LOCAL STATIC FOR
	SELECT 
				SUM(CAST (InvTran.ATTRIBUTE_026 AS INT) )	QUANTITY,
				InvTran.ATTRIBUTE_079	SHORT_DESCRIPTION,
				--Product.ATTRIBUTE_017   SHORT_DESCRIPTION,
				SUM(CAST (InvTran.ATTRIBUTE_025 AS money))/COUNT(*)	UNIT_PRICE,
				SUM(CAST (InvTran.ATTRIBUTE_031 AS money))	VAT_AMOUNT,
				SUM(CAST (InvTran.ATTRIBUTE_027 AS money))	GROSS_AMOUNT

			FROM [SRM-CustomEntities_132]..CUS_ENTITY_DATA InvTran
			INNER JOIN [SRM-CustomEntities_132]..CUS_ENTITY_DATA Mem
			ON InvTran.ATTRIBUTE_012 = Mem.SEQ_ID
			WHERE InvTran.SRM_CLIENT_ENTITIES_SEQ_ID=47831	--InvTran
			AND Mem.SRM_CLIENT_ENTITIES_SEQ_ID=47724	--MEMBER
			AND InvTran.ATTRIBUTE_002=@INVOICE_SEQ_ID
			AND ISNULL(InvTran.DELETED,'N')='N'
			GROUP BY --Product.ATTRIBUTE_017,
			InvTran.ATTRIBUTE_079,cast(InvTran.ATTRIBUTE_025 as money)
END
ELSE
BEGIN
DECLARE CurMain CURSOR LOCAL STATIC FOR
	 SELECT 
				SUM(CAST (InvTran.ATTRIBUTE_026 AS INT) )	QUANTITY,
				InvTran.ATTRIBUTE_079	SHORT_DESCRIPTION,
				--Product.ATTRIBUTE_017   SHORT_DESCRIPTION,
				SUM(CAST (InvTran.ATTRIBUTE_025 AS money))/COUNT(*)	UNIT_PRICE,
				SUM(CAST (InvTran.ATTRIBUTE_031 AS money))	VAT_AMOUNT,
				SUM(CAST (InvTran.ATTRIBUTE_027 AS money))	GROSS_AMOUNT

			FROM [SRM-CustomEntities_132]..CUS_ENTITY_DATA InvTran
			INNER JOIN [SRM-CustomEntities_132]..CUS_ENTITY_DATA Product
			ON InvTran.ATTRIBUTE_077 = Product.SEQ_ID
			WHERE InvTran.SRM_CLIENT_ENTITIES_SEQ_ID=47831
			AND Product.SRM_CLIENT_ENTITIES_SEQ_ID=47975
			AND InvTran.ATTRIBUTE_002=@INVOICE_SEQ_ID
			AND ISNULL(InvTran.DELETED,'N')='N'
			GROUP BY --Product.ATTRIBUTE_017,
			InvTran.ATTRIBUTE_079,cast(InvTran.ATTRIBUTE_025 as money)
END

OPEN CurMain
FETCH NEXT FROM CurMain INTO @Quantity, @Short_Description, @Unit_Price,@Vat_Amount,@Gross_Amount

Set @Counter = 1

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT @Short_Description
		SET @STR_SQL = 'UPDATE [SRM-Workflow].dbo.WFL_OUTPUT SET'
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 1 as nvarchar))) + Cast(((79 + @Counter) * 5) + 1 as nvarchar) + ' = ''' + @Quantity + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 2 as nvarchar))) + Cast(((79 + @Counter) * 5) + 2 as nvarchar) + '=''' + REPLACE(@Short_Description,CHAR(39),CHAR(39)+CHAR(39)) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 3 as nvarchar))) + Cast(((79 + @Counter) * 5) + 3 as nvarchar) + '=''' + REPLACE(@Unit_Price,CHAR(39),CHAR(39)+CHAR(39)) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 4 as nvarchar))) + Cast(((79 + @Counter) * 5) + 4 as nvarchar) + '=''' + CAST(ISNULL(@Vat_Amount,0.00) AS NVARCHAR) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 5 as nvarchar))) + Cast(((79 + @Counter) * 5) + 5 as nvarchar) + ' = ''' + CAST(ISNULL(@Gross_Amount,0.00) AS NVARCHAR) + ''''
		SET @STR_SQL = @STR_SQL + ' WHERE seq_id = ' + CAST(@OUTPUt_SEQ_ID AS NVARCHAR(20))
	


PRINT @STR_SQL

EXEC (@STR_SQL)

Set @Counter = @Counter + 1

FETCH NEXT FROM CurMain INTO @Quantity, @Short_Description, @Unit_Price,@Vat_Amount,@Gross_Amount

END
CLOSE CurMain
DEALLOCATE CurMain

END


;





CREATE PROCEDURE [dbo].[IOG_TEST_PRINT_INVOICE_UPDATED] 
-- Add the parameters for the stored procedure here
@OUTPUt_SEQ_ID bigint,
@INVOICE_SEQ_ID bigint
AS
BEGIN
-- SET NOCOUNT ON added to prevent extra result sets from
-- interfering with SELECT statements.
SET NOCOUNT ON;

PRINT 'start'

Declare @TotalRecords int
Declare @Account_SRM_Client_Entity_SEQ_ID bigint
DECLARE @STR_SQL NVARCHAR(4000)
DECLARE @Counter int
DECLARE @Quantity NVARCHAR(15)
DECLARE @Short_Description NVARCHAR(100)
DECLARE @Unit_Price MONEY
DECLARE @Discount_Amount MONEY 
DECLARE @Net_Amount MONEY 
DECLARE @Vat_Amount MONEY 
DECLARE @Gross_Amount MONEY 

Select @TotalRecords = COUNT(SEQ_ID) FROM [SRM-CustomEntities_150]..CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID=56895
AND ATTRIBUTE_002=@INVOICE_SEQ_ID AND ISNULL(DELETED,'N')='N'


DECLARE CurMain CURSOR LOCAL STATIC FOR

--SELECT 
--ATTRIBUTE_026	QUANTITY, 
--ATTRIBUTE_079	SHORT_DESCRIPTION,
--ATTRIBUTE_025	UNIT_PRICE,
--ATTRIBUTE_031	VAT_AMOUNT,
--ATTRIBUTE_032	GROSS_AMOUNT

--FROM [SRM-CustomEntities_150]..CUS_ENTITY_DATA 
--WHERE SRM_CLIENT_ENTITIES_SEQ_ID=56895
--AND ATTRIBUTE_002=@INVOICE_SEQ_ID 
--AND ISNULL(DELETED,'N')='N'

-- MQ 

SELECT 
SUM(CAST (InvTran.ATTRIBUTE_026 AS INT) )	QUANTITY,
--Product.ATTRIBUTE_017   SHORT_DESCRIPTION,
InvTran.ATTRIBUTE_079	SHORT_DESCRIPTION,
SUM(CAST (InvTran.ATTRIBUTE_025 AS money))/COUNT(*)	UNIT_PRICE,
SUM(CAST (InvTran.ATTRIBUTE_031 AS money))	VAT_AMOUNT,
SUM(CAST (InvTran.ATTRIBUTE_032 AS money))	GROSS_AMOUNT

FROM [SRM-CustomEntities_150]..CUS_ENTITY_DATA InvTran WITH(NOLOCK)
INNER JOIN [SRM-CustomEntities_150]..CUS_ENTITY_DATA Product WITH(NOLOCK) ON Product.SRM_CLIENT_ENTITIES_SEQ_ID=57039 AND Product.SEQ_ID = InvTran.ATTRIBUTE_077
WHERE InvTran.SRM_CLIENT_ENTITIES_SEQ_ID=56895
AND InvTran.ATTRIBUTE_002=@INVOICE_SEQ_ID 
AND ISNULL(InvTran.DELETED,'N')='N'
GROUP BY --Product.ATTRIBUTE_017
InvTran.ATTRIBUTE_079,cast(InvTran.ATTRIBUTE_025 as money)
ORDER BY GROSS_AMOUNT DESC


OPEN CurMain
FETCH NEXT FROM CurMain INTO @Quantity, @Short_Description, @Unit_Price,@Vat_Amount,@Gross_Amount

Set @Counter = 1

	WHILE @@FETCH_STATUS = 0
	BEGIN
		PRINT @Short_Description
		SET @STR_SQL = 'UPDATE [SRM-Workflow].dbo.WFL_OUTPUT SET'
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 1 as nvarchar))) + Cast(((79 + @Counter) * 5) + 1 as nvarchar) + ' = ''' + @Quantity + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 2 as nvarchar))) + Cast(((79 + @Counter) * 5) + 2 as nvarchar) + '=''' + REPLACE(@Short_Description,CHAR(39),CHAR(39)+CHAR(39)) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 3 as nvarchar))) + Cast(((79 + @Counter) * 5) + 3 as nvarchar) + '=''' + REPLACE(@Unit_Price,CHAR(39),CHAR(39)+CHAR(39)) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 4 as nvarchar))) + Cast(((79 + @Counter) * 5) + 4 as nvarchar) + '=''' + CAST(ISNULL(@Vat_Amount,0.00) AS NVARCHAR) + ''','
		SET @STR_SQL = @STR_SQL + ' ATTRIBUTE_' + REPLICATE('0', 3 - LEN(Cast(((79 + @Counter) * 5) + 5 as nvarchar))) + Cast(((79 + @Counter) * 5) + 5 as nvarchar) + ' = ''' + CAST(ISNULL(@Gross_Amount,0.00) AS NVARCHAR) + ''''
		SET @STR_SQL = @STR_SQL + ' WHERE seq_id = ' + CAST(@OUTPUt_SEQ_ID AS NVARCHAR(20))
	


PRINT @STR_SQL

EXEC (@STR_SQL)

Set @Counter = @Counter + 1

FETCH NEXT FROM CurMain INTO @Quantity, @Short_Description, @Unit_Price,@Vat_Amount,@Gross_Amount

END
CLOSE CurMain
DEALLOCATE CurMain

END


;

CREATE FUNCTION [dbo].[JSONEscaped] ( /* this is a simple utility function that takes a SQL String with all its clobber and outputs it as a sting with all the JSON escape sequences in it.*/

  @Unescaped NVARCHAR(MAX) --a string with maybe characters that will break json

  )

RETURNS NVARCHAR(MAX)

AS

BEGIN

  SELECT  @Unescaped = REPLACE(@Unescaped, FROMString, TOString)

  FROM    (SELECT

            '\"' AS FromString, '"' AS ToString

           UNION ALL SELECT '\', '\\'

           UNION ALL SELECT '/', '\/'

           UNION ALL SELECT  CHAR(08),'\b'

           UNION ALL SELECT  CHAR(12),'\f'

           UNION ALL SELECT  CHAR(10),'\n'

           UNION ALL SELECT  CHAR(13),'\r'

           UNION ALL SELECT  CHAR(09),'\t'

          ) substitutions

RETURN @Unescaped

END;

CREATE PROCEDURE  [dbo].[MEMBERSHIP_OUTSTANDING_TASK](
@URL NVARCHAR(250),
@CATEGORY_NAME NVARCHAR(150),
@REMARKS NVARCHAR(350) OUTPUT)
AS 
BEGIN	

	SET @REMARKS = 'Your ' + @CATEGORY_NAME + ' membership has an outstanding amount please <a href="'+ @URL + '"> click here to review and pay</a>'

END;





