CREATE PROCEDURE [dbo].[NI_CANCEL_PAYPAL_PROFILE]
      @MEMBER_SEQ_ID BIGINT
	 ,@PROFILE_ID NVARCHAR(100)
	 ,@MODE NVARCHAR(20) = 'TEST'
	 ,@ERROR VARCHAR(MAX) = NULL OUTPUT
AS
DECLARE @NI_PAYPAL_LOG_SEQ_ID BIGINT
DECLARE @USE_RDS VARCHAR(1)='N'

SELECT @USE_RDS =   ISNULL(Attribute_033,'N')
FROM [SRM-CustomEntities_40]..CUS_ENTITY_DATA WITH(NOLOCK)
WHERE SEQ_ID = 192599179 
AND SRM_CLIENT_ENTITIES_SEQ_ID = 9987


PRINT 'CALLING THE WEB SERVICE WITH PARAMS'



INSERT INTO [SRM-CustomEntities_40]..NI_PAYPAL_LOG (API_CALL , PAYPAL_PROFILE_ID , RESPONSE , DATE_CREATE , DATE_MODIFIED, MEMBER_SEQ_ID,AMOUNT)
SELECT 'CANCEL_PAYPAL_PROFILE',@PROFILE_ID,null,getdate(),null,@MEMBER_SEQ_ID,NULL

SET @NI_PAYPAL_LOG_SEQ_ID = SCOPE_IDENTITY()


IF ISNULL(@USE_RDS , 'N')='Y'
BEGIN

		SET @ERROR = CAST(@NI_PAYPAL_LOG_SEQ_ID AS VARCHAR(100))
END
ELSE
BEGIN

					DECLARE @OBJ INT, @VALUE INT,@hr2 INT, @len INT, @SURL VARCHAR(max),@vStatusText varchar(8000), @status varchar(8000),@response varchar(8000),@hr INT,@src varchar(255),@desc varchar(255)
					--IF ( @@SERVERNAME = 'DSVR021112')

					IF @MODE='TEST'
						set @sURL = 'http://146.101.155.95/NISSOTest/etarget.aspx/CANCELRECURRING?PROFILEID=' + @PROFILE_ID
					ELSE
						set @sURL = 'https://membership.nautinst.org/etarget.aspx/CANCELRECURRING?PROFILEID=' + @PROFILE_ID



					print '------------@sURL'
					print @sURL
					EXEC sp_OACreate 'MSXML2.ServerXMLHTTP', @obj OUT
					--select @obj
					EXEC @hr2 =sp_OAMethod @obj, 'Open',Null, 'GET',@sURL, false
					--SELECT @hr2
					exec @hr2 = sp_OAMethod @obj, 'setRequestHeader', NULL, 'Content-Type','application/x-www-form-urlencoded'
					--SELECT @hr2
					EXEC @hr2 =sp_OAMethod @obj, 'send', NULL, ''
					--SELECT @hr2
					exec @hr2 = sp_OAGetProperty @obj, 'status', @status OUT
					--SELECT @hr2 --set @len = len(@sUrl) --SELECT @LEN
					exec @hr2 = sp_OAMethod @obj, 'setRequestHeader', NULL, 'Content-Length', 200
					--SELECT @hr2
					EXEC sp_OAMethod @obj, 'StatusText', @vStatusText OUTPUT
					--select @vStatusText
					SET @response = @response
					exec @hr2 = sp_OAGetProperty @obj, 'responseText', @response OUT  

					UPDATE [SRM-CustomEntities_40]..NI_PAYPAL_LOG SET RESPONSE = @response , DATE_MODIFIED =GETDATE() WHERE SEQ_ID=@NI_PAYPAL_LOG_SEQ_ID

					PRINT @response
					SET @response = REPLACE(@response,' query=''''','')
					PRINT @response
					DECLARE @response2 xml 
					SET @response2 = CAST(@response AS XML)
					SELECT @ERROR = @response2.value('(/etarget_response//Result/node())[1]', 'varchar(max)')
					PRINT @ERROR

					UPDATE [SRM-CustomEntities_40]..CUS_ENTITY_DATA SET ATTRIBUTE_112 = @ERROR WHERE SRM_CLIENT_ENTITIES_SEQ_ID=9869 AND SEQ_ID=@MEMBER_SEQ_ID
END



;





CREATE PROCEDURE [dbo].[NI_Check_Invalid_Date_Format] 
AS

RETURN

Begin

	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SYSTEM_NAME NVARCHAR(100), @ENTITY_DISPLAY_NAME NVARCHAR(200), @ATTRIBUTE_DISPLAY_NAME NVARCHAR(200)
	DECLARE @STRSQL NVARCHAR(MAX)
	DECLARE @STRSQL2 NVARCHAR(MAX)
	DECLARE @EN_ENTITY_SEQ_ID BIGINT, @SCEA_ATTRIBUTE_SEQ_ID BIGINT, @SEQ_ID NVARCHAR(20), @VALUE NVARCHAR(50)
	
	--CREATE TABLE TMP_DATA_FOR_ALERT(SEQ_ID BIGINT, SRM_CLIENTS_SEQ_ID BIGINT, SRM_CLIENT_ENTITIES_SEQ_ID BIGINT, VALUE NVARCHAR(50), ENTITY_DISPLAY_NAME NVARCHAR(200), ATTRIBUTE_DISPLAY_NAME NVARCHAR(200), SYSTEM_NAME NVARCHAR(200))
	
	PRINT 'Check if there is any date with invalid format'
	TRUNCATE TABLE TMP_DATA_FOR_ALERT

	DECLARE CUR_DATETIME_FIELDS CURSOR LOCAL STATIC FOR
	SELECT DISTINCT SYSTEM_NAME,SCE.SEQ_ID SRM_CLIENT_ENTITIES_SEQ_ID,SA.SRM_CLIENTS_SEQ_ID,SA.ENTITY_DISPLAY_NAME,ATTRIBUTE_DISPLAY_NAME 
	FROM [SRM-Framework_New].dbo.SRM_ALERTS AS SA
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES AS SCE ON SA.SRM_CLIENTS_SEQ_ID=SCE.SRM_CLIENTS_SEQ_ID AND SA.ENTITY_DISPLAY_NAME=SCE.ENTITY_DISPLAY_NAME

	OPEN CUR_DATETIME_FIELDS
			
	FETCH NEXT FROM CUR_DATETIME_FIELDS INTO @SYSTEM_NAME, @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENTS_SEQ_ID, @ENTITY_DISPLAY_NAME, @ATTRIBUTE_DISPLAY_NAME
			
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @EN_ENTITY_SEQ_ID = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID(@ENTITY_DISPLAY_NAME,@SRM_CLIENTS_SEQ_ID)
		SET @SCEA_ATTRIBUTE_SEQ_ID = [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID(@EN_ENTITY_SEQ_ID,'RECORD_ID')

		SET @STRSQL = 'INSERT INTO TMP_DATA_FOR_ALERT (SEQ_ID,SRM_CLIENT_ENTITIES_SEQ_ID,SRM_CLIENTS_SEQ_ID,VALUE,ENTITY_DISPLAY_NAME,ATTRIBUTE_DISPLAY_NAME,SYSTEM_NAME) '
		SET @STRSQL = @STRSQL + 'SELECT DISTINCT SEQ_ID,SRM_CLIENT_ENTITIES_SEQ_ID,SRM_CLIENTS_SEQ_ID, ' + @SYSTEM_NAME + ', ''' + @ENTITY_DISPLAY_NAME + ''',  ''' + @ATTRIBUTE_DISPLAY_NAME + ''',  ''' + @SYSTEM_NAME + ''' FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WITH (NOLOCK)'
		SET @STRSQL = @STRSQL + ' WHERE  SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS nvarchar) 
		SET @STRSQL = @STRSQL + ' AND SEQ_ID IN (SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=' + CAST(@SCEA_ATTRIBUTE_SEQ_ID AS NVARCHAR(200)) + ' AND ATTRIBUTE_DECIMAL > 0)'
		SET @STRSQL = @STRSQL + ' AND ' + @SYSTEM_NAME + ' IS NOT NULL'
		SET @STRSQL = @STRSQL + ' AND ISDATE(' + @SYSTEM_NAME + ') = 0'

		PRINT @STRSQL
		EXECUTE (@STRSQL)

		FETCH NEXT FROM CUR_DATETIME_FIELDS INTO @SYSTEM_NAME, @SRM_CLIENT_ENTITIES_SEQ_ID, @SRM_CLIENTS_SEQ_ID, @ENTITY_DISPLAY_NAME, @ATTRIBUTE_DISPLAY_NAME
	END
	
	CLOSE CUR_DATETIME_FIELDS 
	DEALLOCATE CUR_DATETIME_FIELDS 

	
	
	IF EXISTS(SELECT * FROM TMP_DATA_FOR_ALERT)
	BEGIN		
		PRINT 'send email'
			
		SET @STRSQL2 = '<table border="1">
		<tr>
			<td>SEQ_ID</td>
			<td>SRM_CLIENTS_SEQ_ID</td>
			<td>SRM_CLIENT_ENTITIES_SEQ_ID</td>
			<td>VALUE</td>
			<td>ENTITY_DISPLAY_NAME</td>
			<td>ATTRIBUTE_DISPLAY_NAME</td>
			<td>SYSTEM_NAME</td>
		</tr>'	

		DECLARE cur_Html CURSOR LOCAL STATIC FOR
		SELECT SEQ_ID, SRM_CLIENTS_SEQ_ID, SRM_CLIENT_ENTITIES_SEQ_ID, VALUE, ENTITY_DISPLAY_NAME, ATTRIBUTE_DISPLAY_NAME, SYSTEM_NAME FROM TMP_DATA_FOR_ALERT

		OPEN cur_Html
			
		FETCH NEXT FROM cur_Html INTO @SEQ_ID,@SRM_CLIENTS_SEQ_ID,@SRM_CLIENT_ENTITIES_SEQ_ID,@VALUE,@ENTITY_DISPLAY_NAME,@ATTRIBUTE_DISPLAY_NAME,@SYSTEM_NAME
			
		WHILE @@FETCH_STATUS = 0
		BEGIN
		
			SET @STRSQL2 = @STRSQL2 + '<tr>
			<td>' + CAST(@SEQ_ID AS NVARCHAR(20)) + '</td>
			<td>' + CAST(@SRM_CLIENTS_SEQ_ID AS NVARCHAR(20)) + '</td>
			<td>' + CAST(@SRM_CLIENT_ENTITIES_SEQ_ID AS NVARCHAR(20)) + '</td>
			<td>' + @VALUE + '</td>
			<td>' + @ENTITY_DISPLAY_NAME + '</td>
			<td>' + @ATTRIBUTE_DISPLAY_NAME + '</td>
			<td>' + @SYSTEM_NAME + '</td>
			</tr>'	

			FETCH NEXT FROM cur_Html INTO @SEQ_ID,@SRM_CLIENTS_SEQ_ID,@SRM_CLIENT_ENTITIES_SEQ_ID,@VALUE,@ENTITY_DISPLAY_NAME,@ATTRIBUTE_DISPLAY_NAME,@SYSTEM_NAME
		END
	
		CLOSE cur_Html 
		DEALLOCATE cur_Html 

		SET @STRSQL2 = @STRSQL2 + '</table>'

		declare @Body nvarchar(max)

		set @Body = 'NI - There is issue in Date format of following entities. See exceptions in [Srm-Framework_New].dbo.TMP_DATA_FOR_ALERT table' +  char(9) + char(13) +  char(9) + char(13)

		set @Body = @Body + @STRSQL2 +  char(9) + char(13) +  char(9) + char(13)

		set @Body = @Body + 'This is an automated email.' +  char(9) + char(13) +  char(9) + char(13)
		set @Body = @Body + 'Kind Regards' +  char(9) + char(13)
		set @Body = @Body + 'oomi SupportDesk' 

		EXEC msdb.dbo.sp_send_dbmail
			@profile_name = 'oomi_DB',
			@recipients = 'support-alerts@target.com.pk',
			@subject = 'NI - Issue found in the date format',
			@Body = @Body
	END
    
END




;




CREATE PROC [dbo].[NI_TENTH_APPLICATION]
(
@RECORD_ID BIGINT
,@CATEGORY BIGINT --= 9465930 -- REVALIDATE
,@CSV varchar(MAX) OUTPUT
)
AS
DECLARE 
@Date_Modified DATETIME = GETDATE()
,@STATUS BIGINT = 16725510 --SUBMITTED PAID
,@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT = 1763069
,@MAX_DATE_OF_APPLICAITON DATETIME

UPDATE X SET 
 DATE_MODIFIED = @Date_Modified 
, MODIFIED_BY='Nautical Institute DP'
, ATTRIBUTE_324 = @Date_Modified
, ATTRIBUTE_325 = RIGHT('0' + CAST(DATEPART(HOUR,@Date_Modified) AS VARCHAR(50)),2)+ ':' + RIGHT('0' + CAST(DATEPART(MINUTE,@Date_Modified) AS VARCHAR(50)),2)
FROM [SRM-CustomEntities_40]..CUS_ENTITY_DATA X WITH(NOLOCK)
WHERE SEQ_ID = @RECORD_ID

		EXEC [SRM-DataPivot_40].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN]
		@SRM_CLIENT_ENTITIES_SEQ_ID = 10156,
		@CUS_ENTITY_DATA_SEQ_ID = @RECORD_ID,
		@SRM_CLIENTS_SEQ_ID = 40


DECLARE  @Temp_RecordIds_With_Catg_And_Status		TABLE(SEQ_ID BIGINT)
DECLARE  @Temp_RecordIds_With_TenthApplicationFlag  TABLE(SEQ_ID BIGINT)


INSERT INTO @Temp_RecordIds_With_Catg_And_Status
SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_40]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 219119 AND ATTRIBUTE_DECIMAL=@CATEGORY --CERTIFICATION_CATEGORY
INTERSECT
SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_40]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 219117 AND ATTRIBUTE_DECIMAL=@STATUS  --CERTIFICATION_STATUS




INSERT INTO @Temp_RecordIds_With_TenthApplicationFlag
SELECT SEQ_ID FROM @Temp_RecordIds_With_Catg_And_Status
INTERSECT
SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_40]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1726855 AND ATTRIBUTE_BOOLEAN IS NOT NULL AND ATTRIBUTE_BOOLEAN!='N'  --TENTH_APPLICATION


SELECT @MAX_DATE_OF_APPLICAITON = MAX(CAST(ATTRIBUTE_324 AS DATETIME))
From [SRM-CustomEntities_40]..Cus_Entity_Data X with(Nolock)
Where SRM_Client_Entities_SEQ_ID =10156
and ISNULL(Deleted,'N')='N'
AND SEQ_ID IN(SELECT SEQ_ID FROM @Temp_RecordIds_With_TenthApplicationFlag)


DECLARE  @Temp_RecordIds_GreaterThan_Max_DateOfApplication  TABLE(SEQ_ID BIGINT)
INSERT INTO @Temp_RecordIds_GreaterThan_Max_DateOfApplication
SELECT SEQ_ID FROM @Temp_RecordIds_With_Catg_And_Status
INTERSECT
SELECT CUS_ENTITY_DATA_SEQ_ID  FROM [SRM-DataPivot_40]..CUS_PIVOT_NON_UNIQUE_INDEXES WITH(NOLOCK) WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 1763069 AND ATTRIBUTE_DATETIME>@MAX_DATE_OF_APPLICAITON --DATE_OF_APPLICATION_WITH_TIME


DECLARE  @Temp_Final TABLE(SEQ_ID BIGINT , DATE_OF_APPLICAITON DATETIME)

INSERT INTO @Temp_Final
SELECT SEQ_ID , CAST(ATTRIBUTE_324 AS DATETIME)
From [SRM-CustomEntities_40]..Cus_Entity_Data X with(Nolock)
Where SRM_Client_Entities_SEQ_ID =10156
and ISNULL(Deleted,'N')='N'
AND SEQ_ID IN(SELECT SEQ_ID FROM @Temp_RecordIds_GreaterThan_Max_DateOfApplication)


SELECT @CSV = COALESCE(@CSV + ',', '') + CAST(SEQ_ID AS VARCHAR)
From @Temp_Final
ORDER BY DATE_OF_APPLICAITON

INSERT INTO [SRM-oomiTemp].dbo.NI_TENTH_APPLICATION (RECORD_ID,COMMA_SEPARATED_RECORDIDs,DATE_CREATED) VALUES (@RECORD_ID,@CSV,GETDATE())



;






