CREATE FUNCTION [dbo].[PadString] (@m_STRING_TO_PAD NVARCHAR(500), @m_PAD_CHARACTER NVARCHAR(1), @m_MAX_LENGHT INT)
RETURNS NVARCHAR(500)
AS
BEGIN
	DECLARE @RETURN_VALUE NVARCHAR(500)

	IF LEN(@m_STRING_TO_PAD) < @m_MAX_LENGHT
	BEGIN
		SET @RETURN_VALUE = REPLICATE(@m_PAD_CHARACTER, @m_MAX_LENGHT - LEN(@m_STRING_TO_PAD)) + @m_STRING_TO_PAD
	END
	ELSE
	BEGIN
		SET @RETURN_VALUE = @m_STRING_TO_PAD
	END

	RETURN @RETURN_VALUE 
END




;


CREATE function [dbo].[Phrase](@Text as varchar(8000), @RemoveS char(1))
returns varchar(8000)
as
begin
   declare @Reset bit;
   declare @Ret varchar(8000);
   declare @i int;
   declare @c char(1);

   select @Reset = 1, @i=1, @Ret = '';
   
   SET @Text = REPLACE(REPLACE(REPLACE(@Text, '_', ' '), 'SRM', ''), 'CRM', '')

   while (@i <= len(@Text))
    select @c= substring(@Text,@i,1),
               @Ret = @Ret + case when @Reset=1 then UPPER(@c) else LOWER(@c) end,
               @Reset = case when @c like '[a-zA-Z]' then 0 else 1 end,
               @i = @i +1
               
   if @RemoveS = 'Y'
		if RIGHT(@Ret, 1) = 's'
			set @Ret = SUBSTRING(@Ret, 1, len(@Ret) -1)
		
   return rtrim(ltrim(@Ret))
end
;

create function ProperCase(@Text as varchar(8000))
returns varchar(8000)
as
begin
   declare @Reset bit;
   declare @Ret varchar(8000);
   declare @i int;
   declare @c char(1);

   select @Reset = 1, @i=1, @Ret = '';

   while (@i <= len(@Text))
    select @c= substring(@Text,@i,1),
               @Ret = @Ret + case when @Reset=1 then UPPER(@c) else LOWER(@c) end,
               @Reset = case when @c like '[a-zA-Z]' then 0 else 1 end,
               @i = @i +1
   return @Ret
end;





