,@CONTACT_2_SEQ_ID =NULL
,@APPLICATION_SEQ_ID =1
,@TRANSACTION_DATE =@TRAN_DATE
,@ERROR = @ERR OUTPUT
SELECT @ERR
*/



;





CREATE PROCEDURE [dbo].[REPLACE_WORKFLOW_COPY_FOR_DIFFERENT_CLIENT_NI_eTarget]
	-- Add the parameters for the stored procedure here
	@FROM_SRM_CLIENTS_SEQ_ID BIGINT = 82,
	@TO_SRM_CLIENTS_SEQ_ID BIGINT = 92,
	@FROM_SRM_USERS_SEQ_ID BIGINT = 0,	
	@FROM_WORKFLOW_SEQ_ID BIGINT = 0,
	@TO_WORKFLOW_SEQ_ID BIGINT = 0
AS

SET NOCOUNT ON;

	DECLARE @TO_SRM_USERS_SEQ_ID BIGINT 
	DECLARE @CREATED_BY NVARCHAR(100) = 'Copy-User'
	DECLARE @DATE_CREATED DATETIME = GETDATE()
	
	SELECT TOP 1 @TO_SRM_USERS_SEQ_ID = SEQ_ID, @CREATED_BY = LOGIN_USER_NAME  FROM dbo.SRM_USERS WHERE SRM_CLIENTS_SEQ_ID=@TO_SRM_CLIENTS_SEQ_ID AND SUPER_ADMIN='Y'

	

	DECLARE @WFL_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @NEW_WORKFLOWS_SEQ_ID BIGINT 
	
	DECLARE @SOURCE_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @DESTINATION_WORKFLOWS_SEQ_ID BIGINT 
	
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
  	DECLARE @NEW_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  

	DECLARE @WFL_TASKS_SEQ_ID BIGINT  
	DECLARE @NEW_WFL_TASKS_SEQ_ID BIGINT
	DECLARE @WFL_NEXT_TASK_SEQ_ID BIGINT
	DECLARE @NEW_WFL_NEXT_TASK_SEQ_ID BIGINT  
	DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT 
	DECLARE @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT  

	DECLARE @WFL_VARIABLES_SEQ_ID BIGINT
	DECLARE @WFL_TASK_DETAILS_SEQ_ID BIGINT  
  
	DECLARE @WFL_TASK_CONDITIONS_SEQ_ID BIGINT  
	DECLARE @NEW_WFL_TASK_CONDITIONS_SEQ_ID BIGINT  
	
	DECLARE @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID BIGINT
	DECLARE @WFL_MAPPINGS_SEQ_ID BIGINT
	DECLARE @WFL_SCHEDULES_SEQ_ID BIGINT
	DECLARE @WFL_MAILMERGE_TEMPLATES_SEQ_ID BIGINT  
	
	DECLARE @TASK_EXPRESSION XML  



	--BEGIN TRAN A


	DECLARE @TEMP_WFL_TASK_CONDITIONS_TABLE TABLE
	(
		WFL_TASK_CONDITIONS_SEQ_ID BIGINT,
		WFL_TASK_CONDITIONS_SEQ_ID2 BIGINT
	)  

	DECLARE @TEMP_WFL_TASKS_TABLE TABLE
	(
		WFL_TASKS_SEQ_ID BIGINT,
		WFL_TASKS_SEQ_ID2 BIGINT
	)
	

	IF EXISTS(SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOWS AS ww WHERE SEQ_ID = @TO_WORKFLOW_SEQ_ID)
	BEGIN
		DELETE FROM [SRM-Workflow].dbo.WFL_MAPPINGS WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID
		DELETE FROM [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID
		DELETE FROM [SRM-Workflow].dbo.WFL_TASK_DETAILS WHERE WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE wt.WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID)
		DELETE FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS WHERE WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE wt.WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID)
		DELETE FROM [SRM-Workflow].dbo.WFL_VARIABLES WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID			
		DELETE FROM [SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID	
		DELETE FROM [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID
		DELETE FROM [SRM-Workflow].dbo.WFL_SCHEDULES WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID		
	END


  
	IF EXISTS (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOWS WHERE SEQ_ID = @TO_WORKFLOW_SEQ_ID)
	BEGIN
		UPDATE wf_to
		SET 
		wf_to.DESCRIPTION =					wf_from.DESCRIPTION ,
		wf_to.SRM_CLIENT_ENTITY_SEQ_ID =	(SELECT TOP 1 SRM_CLIENT_ENTITIES_SEQ_ID_92 FROM [SRM-DataConversion].dbo.SRM_CLIENT_ENTITIES_ATTRIBUTES_LOG_82_92 WHERE SRM_CLIENT_ENTITIES_SEQ_ID_82=wf_from.SRM_CLIENT_ENTITY_SEQ_ID) ,
		wf_to.EXPRESSION =					wf_from.EXPRESSION ,
		wf_to.REMARKS =						wf_from.REMARKS ,
		wf_to.SOURCE_OF_DATA =				wf_from.SOURCE_OF_DATA ,
		wf_to.SOURCE_FILE =					wf_from.SOURCE_FILE ,
		wf_to.DATE_MODIFIED =				wf_from.DATE_MODIFIED ,
		wf_to.MODIFIED_BY =					wf_from.MODIFIED_BY ,
		wf_to.DATE_CREATED =				wf_from.DATE_CREATED ,
		wf_to.CREATED_BY =					wf_from.CREATED_BY ,
		wf_to.DELETED =						wf_from.DELETED ,
		wf_to.DATE_DELETED =				wf_from.DATE_DELETED ,
		wf_to.DELETED_BY	=				wf_from.DELETED_BY ,
		wf_to.SHOW_IN_JOBS	=				wf_from.SHOW_IN_JOBS , 
		wf_to.OUTPUT_FILENAME	=			wf_from.OUTPUT_FILENAME ,
		wf_to.IS_ASYNC		=				wf_from.IS_ASYNC ,
		wf_to.ALWAYS_TRIGGER	=			wf_from.ALWAYS_TRIGGER ,
		wf_to.AVAILABLE_FOR_TEMPLATES =		wf_from.AVAILABLE_FOR_TEMPLATES ,
		wf_to.REQUIRE_MANUAL_INPUT		=	wf_from.REQUIRE_MANUAL_INPUT
		FROM [SRM-Workflow].dbo.WFL_WORKFLOWS wf_to
		INNER JOIN  [SRM-Workflow].dbo.WFL_WORKFLOWS wf_from ON wf_to.SEQ_ID = @TO_WORKFLOW_SEQ_ID AND wf_from.SEQ_ID = @FROM_WORKFLOW_SEQ_ID
		
		SET @NEW_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID
	END
	


	-- WFL_WORKFLOW_STARTING_OPTIONS
	DECLARE CUR_WFL_WORKFLOW_STARTING_OPTIONS CURSOR STATIC FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID
	
	OPEN CUR_WFL_WORKFLOW_STARTING_OPTIONS 

	FETCH NEXT FROM CUR_WFL_WORKFLOW_STARTING_OPTIONS INTO @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS
				( WFL_WORKFLOWS_SEQ_ID ,
				  START_WHEN_ID ,
				  REMARKS ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID ,
				START_WHEN_ID ,
				REMARKS ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				NULL ,
				NULL 
		FROM [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS WHERE SEQ_ID = @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_WORKFLOW_STARTING_OPTIONS INTO @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID
	END

	CLOSE CUR_WFL_WORKFLOW_STARTING_OPTIONS 
	DEALLOCATE CUR_WFL_WORKFLOW_STARTING_OPTIONS 


	-- WFL_TASKS
	DECLARE CUR_WFL_TASKS CURSOR STATIC FOR
	SELECT SEQ_ID, SRM_CLIENT_ENTITY_SEQ_ID, WFL_TASKS_SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE 
	wt.WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASKS 

	FETCH NEXT FROM CUR_WFL_TASKS INTO @WFL_TASKS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--Get new client entity ID        
		IF ISNULL(@SRM_CLIENT_ENTITIES_SEQ_ID, 0) != 0
		BEGIN
			SELECT TOP 1 @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID_92 FROM 
			[SRM-DataConversion].dbo.SRM_CLIENT_ENTITIES_ATTRIBUTES_LOG_82_92 WHERE SRM_CLIENT_ENTITIES_SEQ_ID_82=@SRM_CLIENT_ENTITIES_SEQ_ID			
		END 
		ELSE
			SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = NULL 
		
		--Get new sub-workflow ID
		IF (SELECT TASK_TYPE_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE SEQ_ID = @WFL_TASKS_SEQ_ID) = 1
		BEGIN
			SET @DESTINATION_WORKFLOWS_SEQ_ID = 0
			SELECT @SOURCE_WORKFLOWS_SEQ_ID = WFL_WORKFLOWS_SEQ_ID2 FROM [SRM-Workflow].dbo.WFL_TASKS WHERE SEQ_ID = @WFL_TASKS_SEQ_ID
			
			SELECT @DESTINATION_WORKFLOWS_SEQ_ID=Workflow_Id_92_Live FROM [SRM-DataConversion].dbo.NIDC_WORKFLOW_MAPPINGS 
				WHERE Workflow_Id_82 = @SOURCE_WORKFLOWS_SEQ_ID AND Action_Taken='Add'

			IF @DESTINATION_WORKFLOWS_SEQ_ID =0
				SELECT @DESTINATION_WORKFLOWS_SEQ_ID=WFL_WORKFLOWS_SEQ_ID_NEW FROM [SRM-ClientCopyLog].dbo.SRM_CLIENT_WORKFLOW_COPY_LOG_40_92 WHERE WFL_WORKFLOWS_SEQ_ID_OLD IN (
				SELECT WFL_WORKFLOWS_SEQ_ID_OLD FROM [SRM-ClientCopyLog].dbo.SRM_CLIENT_WORKFLOW_COPY_LOG_40_82 WHERE WFL_WORKFLOWS_SEQ_ID_NEW= @SOURCE_WORKFLOWS_SEQ_ID)

			IF @DESTINATION_WORKFLOWS_SEQ_ID = 0
				SET @DESTINATION_WORKFLOWS_SEQ_ID = 99999

		END
		ELSE
		BEGIN
			SET @DESTINATION_WORKFLOWS_SEQ_ID = NULL
			SET @SOURCE_WORKFLOWS_SEQ_ID = NULL
		END

		INSERT INTO [SRM-Workflow].dbo.WFL_TASKS
				( WFL_WORKFLOWS_SEQ_ID ,
				  TASK_TYPE_ID ,
				  SRM_CLIENT_ENTITY_SEQ_ID ,
				  WFL_WORKFLOWS_SEQ_ID2 ,
				  WFL_TASKS_SEQ_ID ,
				  STARTING_TASK ,
				  ENDING_TASK ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT @NEW_WORKFLOWS_SEQ_ID,
				TASK_TYPE_ID ,
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID ,
				@DESTINATION_WORKFLOWS_SEQ_ID ,--WFL_WORKFLOWS_SEQ_ID2 
				NULL, --WFL_TASKS_SEQ_ID,
				STARTING_TASK ,
				ENDING_TASK ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				WFL_TASKS_SEQ_ID ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_TASKS wt
		WHERE SEQ_ID = @WFL_TASKS_SEQ_ID
		
		SELECT @NEW_WFL_TASKS_SEQ_ID = MAX(SEQ_ID) FROM [SRM-Workflow].dbo.WFL_TASKS

		INSERT INTO @TEMP_WFL_TASKS_TABLE
		(WFL_TASKS_SEQ_ID, WFL_TASKS_SEQ_ID2)
		VALUES 
		(@WFL_TASKS_SEQ_ID, @NEW_WFL_TASKS_SEQ_ID)

		FETCH NEXT FROM CUR_WFL_TASKS INTO @WFL_TASKS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID
	END

	CLOSE CUR_WFL_TASKS 
	DEALLOCATE CUR_WFL_TASKS 
	
	--SELECT * FROM @TEMP_WFL_TASKS_TABLE
	-- TASK UPDATER
	DECLARE CUR_WFL_TASKS_UPDATER CURSOR STATIC FOR
	SELECT SEQ_ID, SOURCE_OF_DATA FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE 
	wt.WFL_WORKFLOWS_SEQ_ID = @NEW_WORKFLOWS_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASKS_UPDATER 

	FETCH NEXT FROM CUR_WFL_TASKS_UPDATER INTO @WFL_TASKS_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF @WFL_NEXT_TASK_SEQ_ID IS NOT NULL
			SET @NEW_WFL_NEXT_TASK_SEQ_ID = (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = @WFL_NEXT_TASK_SEQ_ID)
		ELSE
			SET @NEW_WFL_NEXT_TASK_SEQ_ID = NULL 

		UPDATE [SRM-Workflow].dbo.WFL_TASKS
		SET WFL_TASKS_SEQ_ID = @NEW_WFL_NEXT_TASK_SEQ_ID
		WHERE SEQ_ID = @WFL_TASKS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_TASKS_UPDATER INTO @WFL_TASKS_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID
	END

	CLOSE CUR_WFL_TASKS_UPDATER 
	DEALLOCATE CUR_WFL_TASKS_UPDATER 



	-- WFL_VARIABLES
	DECLARE CUR_WFL_VARIABLES CURSOR STATIC FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_VARIABLES AS wv 
	WHERE wv.WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_VARIABLES 

	FETCH NEXT FROM CUR_WFL_VARIABLES INTO @WFL_VARIABLES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_VARIABLES
				( WFL_WORKFLOWS_SEQ_ID ,
				  VARIABLE_NAME ,
				  VARIABLE_TYPE_ID ,
				  EXPRESSION ,
				  REMARKS ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID,
				VARIABLE_NAME ,
				VARIABLE_TYPE_ID ,
				EXPRESSION ,
				REMARKS ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_VARIABLES AS wv
		WHERE SEQ_ID = @WFL_VARIABLES_SEQ_ID

		FETCH NEXT FROM CUR_WFL_VARIABLES INTO @WFL_VARIABLES_SEQ_ID
	END

	CLOSE CUR_WFL_VARIABLES 
	DEALLOCATE CUR_WFL_VARIABLES


	--WFL_TASK_CONDITIONS
	DECLARE CUR_WFL_TASK_CONDITIONS CURSOR STATIC FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS WHERE 
	WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID) ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASK_CONDITIONS 

	FETCH NEXT FROM CUR_WFL_TASK_CONDITIONS INTO @WFL_TASK_CONDITIONS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_TASK_CONDITIONS
				( WFL_TASKS_SEQ_ID ,
				  WFL_TASKS_SEQ_ID2 ,
				  RANK ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtc.WFL_TASKS_SEQ_ID) ,
				(SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtc.WFL_TASKS_SEQ_ID2) ,
				RANK ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS wtc
		WHERE SEQ_ID = @WFL_TASK_CONDITIONS_SEQ_ID

		SELECT @NEW_WFL_TASK_CONDITIONS_SEQ_ID = MAX(SEQ_ID) FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS


		INSERT INTO @TEMP_WFL_TASK_CONDITIONS_TABLE
		(WFL_TASK_CONDITIONS_SEQ_ID, WFL_TASK_CONDITIONS_SEQ_ID2)
		VALUES
		(@WFL_TASK_CONDITIONS_SEQ_ID, @NEW_WFL_TASK_CONDITIONS_SEQ_ID)  

		FETCH NEXT FROM CUR_WFL_TASK_CONDITIONS INTO @WFL_TASK_CONDITIONS_SEQ_ID
	END

	CLOSE CUR_WFL_TASK_CONDITIONS 
	DEALLOCATE CUR_WFL_TASK_CONDITIONS


	-- WFL_TASK_DETAILS
	DECLARE @Node BIGINT
	DECLARE @ATTRIB_COUNTER BIGINT

	DECLARE CUR_WFL_TASK_DETAILS CURSOR STATIC FOR
	SELECT wtd.SEQ_ID, EXPRESSION, wt.SRM_CLIENT_ENTITY_SEQ_ID 
	FROM [SRM-Workflow].dbo.WFL_TASK_DETAILS AS wtd 
	INNER JOIN [SRM-Workflow].dbo.WFL_TASKS wt ON wtd.WFL_TASKS_SEQ_ID = wt.SEQ_ID
	WHERE wtd.WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID) ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASK_DETAILS 

	FETCH NEXT FROM CUR_WFL_TASK_DETAILS INTO @WFL_TASK_DETAILS_SEQ_ID, @TASK_EXPRESSION, @SRM_CLIENT_ENTITIES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Node = 1
		SET @ATTRIB_COUNTER = (SELECT COUNT(attrib.value('(SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID)[1]', 'bigint')) FROM @TASK_EXPRESSION.nodes('/QUERY/CRITERIA_ATTRIBUTES') as EMP(attrib))

		WHILE @Node <= @ATTRIB_COUNTER
		BEGIN
			SET @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0
			SET @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = (SELECT @TASK_EXPRESSION.value('(//QUERY/CRITERIA_ATTRIBUTES[sql:variable("@Node")]/SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID/node())[1]', 'varchar(max)')) 

			SET @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0
			SELECT TOP 1 @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID_92 FROM 
			[SRM-DataConversion].dbo.SRM_CLIENT_ENTITIES_ATTRIBUTES_LOG_82_92 WHERE SRM_CLIENT_ENTITy_attributes_SEQ_ID_82=@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

			
			IF(@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID != '' AND @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID > 0)
			BEGIN
				SET @TASK_EXPRESSION.modify('replace value of (//QUERY/CRITERIA_ATTRIBUTES[sql:variable("@Node")]/SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID/text())[1] with sql:variable("@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID")') 
			END

			SET @Node = @Node + 1
		END

		INSERT INTO [SRM-Workflow].dbo.WFL_TASK_DETAILS
				( WFL_TASKS_SEQ_ID ,
				  WFL_TASK_CONDITIONS_SEQ_ID ,
				  DETAILS_TYPE_ID ,
				  EXPRESSION ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtd.WFL_TASKS_SEQ_ID) ,
				(SELECT WFL_TASK_CONDITIONS_SEQ_ID2 FROM @TEMP_WFL_TASK_CONDITIONS_TABLE WHERE WFL_TASK_CONDITIONS_SEQ_ID = wtd.WFL_TASK_CONDITIONS_SEQ_ID) ,
				DETAILS_TYPE_ID ,
				CONVERT(NVARCHAR(max), @TASK_EXPRESSION) ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_TASK_DETAILS wtd
		WHERE wtd.SEQ_ID = @WFL_TASK_DETAILS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_TASK_DETAILS INTO @WFL_TASK_DETAILS_SEQ_ID, @TASK_EXPRESSION, @SRM_CLIENT_ENTITIES_SEQ_ID
	END

	CLOSE CUR_WFL_TASK_DETAILS 
	DEALLOCATE CUR_WFL_TASK_DETAILS 


	-- WFL_MAILMERGE_TEMPLATES
	DECLARE CUR_WFL_MAILMERGE_TEMPLATES CURSOR STATIC FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES AS wmt 
	WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_MAILMERGE_TEMPLATES 

	FETCH NEXT FROM CUR_WFL_MAILMERGE_TEMPLATES INTO @WFL_MAILMERGE_TEMPLATES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES
				( WFL_WORKFLOWS_SEQ_ID ,
				  TEMPLATE_TITLE ,
				  ATTACHMENT_URL ,
				  REMARKS ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID,
				TEMPLATE_TITLE ,
				ATTACHMENT_URL ,
				REMARKS ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES wmt
		WHERE SEQ_ID = @WFL_MAILMERGE_TEMPLATES_SEQ_ID

		FETCH NEXT FROM CUR_WFL_MAILMERGE_TEMPLATES INTO @WFL_MAILMERGE_TEMPLATES_SEQ_ID
	END

	CLOSE CUR_WFL_MAILMERGE_TEMPLATES 
	DEALLOCATE CUR_WFL_MAILMERGE_TEMPLATES


	-- WFL_MAPPINGS
	DECLARE CUR_WFL_MAPPINGS CURSOR STATIC FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_MAPPINGS AS wm WHERE 
	WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_MAPPINGS 

	FETCH NEXT FROM CUR_WFL_MAPPINGS INTO @WFL_MAPPINGS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_MAPPINGS
				( WFL_WORKFLOWS_SEQ_ID ,
				  ATTRIBUTE_SYSTEM_NAME ,
				  ATTRIBUTE_DESCRIPTION ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID,
				ATTRIBUTE_SYSTEM_NAME ,
				ATTRIBUTE_DESCRIPTION ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_MAPPINGS AS wm
		WHERE SEQ_ID = @WFL_MAPPINGS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_MAPPINGS INTO @WFL_MAPPINGS_SEQ_ID
	END

	CLOSE CUR_WFL_MAPPINGS 
	DEALLOCATE CUR_WFL_MAPPINGS 


	



;





CREATE PROCEDURE [dbo].[REPLACE_WORKFLOW_COPY_FOR_DIFFERENT_CLIENT_NI_eTargetLive]
	-- Add the parameters for the stored procedure here
	@FROM_SRM_CLIENTS_SEQ_ID BIGINT = 82,
	@TO_SRM_CLIENTS_SEQ_ID BIGINT = 40,
	@FROM_SRM_USERS_SEQ_ID BIGINT = 0,	
	@FROM_WORKFLOW_SEQ_ID BIGINT = 0,
	@TO_WORKFLOW_SEQ_ID BIGINT = 0
AS

SET NOCOUNT ON;

	DECLARE @TO_SRM_USERS_SEQ_ID BIGINT 
	DECLARE @CREATED_BY NVARCHAR(100) = 'Copy-User'
	DECLARE @DATE_CREATED DATETIME = GETDATE()
	
	SELECT TOP 1 @TO_SRM_USERS_SEQ_ID = SEQ_ID, @CREATED_BY = LOGIN_USER_NAME  FROM dbo.SRM_USERS WHERE SRM_CLIENTS_SEQ_ID=@TO_SRM_CLIENTS_SEQ_ID AND SUPER_ADMIN='Y'

	

	DECLARE @WFL_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @NEW_WORKFLOWS_SEQ_ID BIGINT 
	
	DECLARE @SOURCE_WORKFLOWS_SEQ_ID BIGINT
	DECLARE @DESTINATION_WORKFLOWS_SEQ_ID BIGINT 
	
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
  	DECLARE @NEW_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT  

	DECLARE @WFL_TASKS_SEQ_ID BIGINT  
	DECLARE @NEW_WFL_TASKS_SEQ_ID BIGINT
	DECLARE @WFL_NEXT_TASK_SEQ_ID BIGINT
	DECLARE @NEW_WFL_NEXT_TASK_SEQ_ID BIGINT  
	DECLARE @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT 
	DECLARE @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID BIGINT  

	DECLARE @WFL_VARIABLES_SEQ_ID BIGINT
	DECLARE @WFL_TASK_DETAILS_SEQ_ID BIGINT  
  
	DECLARE @WFL_TASK_CONDITIONS_SEQ_ID BIGINT  
	DECLARE @NEW_WFL_TASK_CONDITIONS_SEQ_ID BIGINT  
	
	DECLARE @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID BIGINT
	DECLARE @WFL_MAPPINGS_SEQ_ID BIGINT
	DECLARE @WFL_SCHEDULES_SEQ_ID BIGINT
	DECLARE @WFL_MAILMERGE_TEMPLATES_SEQ_ID BIGINT  
	
	DECLARE @TASK_EXPRESSION XML  



	--BEGIN TRAN A


	DECLARE @TEMP_WFL_TASK_CONDITIONS_TABLE TABLE
	(
		WFL_TASK_CONDITIONS_SEQ_ID BIGINT,
		WFL_TASK_CONDITIONS_SEQ_ID2 BIGINT
	)  

	DECLARE @TEMP_WFL_TASKS_TABLE TABLE
	(
		WFL_TASKS_SEQ_ID BIGINT,
		WFL_TASKS_SEQ_ID2 BIGINT
	)
	

	IF EXISTS(SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOWS AS ww WHERE SEQ_ID = @TO_WORKFLOW_SEQ_ID)
	BEGIN
		DELETE FROM [SRM-Workflow].dbo.WFL_MAPPINGS WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID
		DELETE FROM [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID
		DELETE FROM [SRM-Workflow].dbo.WFL_TASK_DETAILS WHERE WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE wt.WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID)
		DELETE FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS WHERE WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE wt.WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID)
		DELETE FROM [SRM-Workflow].dbo.WFL_VARIABLES WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID			
		DELETE FROM [SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID	
		DELETE FROM [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID
		DELETE FROM [SRM-Workflow].dbo.WFL_SCHEDULES WHERE WFL_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID		
	END


  
	IF EXISTS (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOWS WHERE SEQ_ID = @TO_WORKFLOW_SEQ_ID)
	BEGIN
		UPDATE wf_to
		SET 
		wf_to.DESCRIPTION =					wf_from.DESCRIPTION ,
		wf_to.SRM_CLIENT_ENTITY_SEQ_ID =	(SELECT TOP 1 SRM_CLIENT_ENTITIES_SEQ_ID_40 FROM [SRM-DataConversion].dbo.SRM_CLIENT_ENTITIES_ATTRIBUTES_LOG_82_40 WHERE SRM_CLIENT_ENTITIES_SEQ_ID_82=wf_from.SRM_CLIENT_ENTITY_SEQ_ID) ,
		wf_to.EXPRESSION =					wf_from.EXPRESSION ,
		wf_to.REMARKS =						wf_from.REMARKS ,
		wf_to.SOURCE_OF_DATA =				wf_from.SOURCE_OF_DATA ,
		wf_to.SOURCE_FILE =					wf_from.SOURCE_FILE ,
		wf_to.DATE_MODIFIED =				wf_from.DATE_MODIFIED ,
		wf_to.MODIFIED_BY =					wf_from.MODIFIED_BY ,
		wf_to.DATE_CREATED =				wf_from.DATE_CREATED ,
		wf_to.CREATED_BY =					wf_from.CREATED_BY ,
		wf_to.DELETED =						wf_from.DELETED ,
		wf_to.DATE_DELETED =				wf_from.DATE_DELETED ,
		wf_to.DELETED_BY	=				wf_from.DELETED_BY ,
		wf_to.SHOW_IN_JOBS	=				wf_from.SHOW_IN_JOBS , 
		wf_to.OUTPUT_FILENAME	=			wf_from.OUTPUT_FILENAME ,
		wf_to.IS_ASYNC		=				wf_from.IS_ASYNC ,
		wf_to.ALWAYS_TRIGGER	=			wf_from.ALWAYS_TRIGGER ,
		wf_to.AVAILABLE_FOR_TEMPLATES =		wf_from.AVAILABLE_FOR_TEMPLATES ,
		wf_to.REQUIRE_MANUAL_INPUT		=	wf_from.REQUIRE_MANUAL_INPUT
		FROM [SRM-Workflow].dbo.WFL_WORKFLOWS wf_to
		INNER JOIN  [SRM-Workflow].dbo.WFL_WORKFLOWS wf_from ON wf_to.SEQ_ID = @TO_WORKFLOW_SEQ_ID AND wf_from.SEQ_ID = @FROM_WORKFLOW_SEQ_ID
		
		SET @NEW_WORKFLOWS_SEQ_ID = @TO_WORKFLOW_SEQ_ID
	END
	


	-- WFL_WORKFLOW_STARTING_OPTIONS
	DECLARE CUR_WFL_WORKFLOW_STARTING_OPTIONS CURSOR STATIC FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID
	
	OPEN CUR_WFL_WORKFLOW_STARTING_OPTIONS 

	FETCH NEXT FROM CUR_WFL_WORKFLOW_STARTING_OPTIONS INTO @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS
				( WFL_WORKFLOWS_SEQ_ID ,
				  START_WHEN_ID ,
				  REMARKS ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID ,
				START_WHEN_ID ,
				REMARKS ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				NULL ,
				NULL 
		FROM [SRM-Workflow].dbo.WFL_WORKFLOW_STARTING_OPTIONS WHERE SEQ_ID = @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_WORKFLOW_STARTING_OPTIONS INTO @WFL_WORKFLOW_STARTING_OPTIONS_SEQ_ID
	END

	CLOSE CUR_WFL_WORKFLOW_STARTING_OPTIONS 
	DEALLOCATE CUR_WFL_WORKFLOW_STARTING_OPTIONS 


	-- WFL_TASKS
	DECLARE CUR_WFL_TASKS CURSOR STATIC FOR
	SELECT SEQ_ID, SRM_CLIENT_ENTITY_SEQ_ID, WFL_TASKS_SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE 
	wt.WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASKS 

	FETCH NEXT FROM CUR_WFL_TASKS INTO @WFL_TASKS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--Get new client entity ID        
		IF ISNULL(@SRM_CLIENT_ENTITIES_SEQ_ID, 0) != 0
		BEGIN
			SELECT TOP 1 @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID_40 FROM 
			[SRM-DataConversion].dbo.SRM_CLIENT_ENTITIES_ATTRIBUTES_LOG_82_40 WHERE SRM_CLIENT_ENTITIES_SEQ_ID_82=@SRM_CLIENT_ENTITIES_SEQ_ID			
		END 
		ELSE
			SET @NEW_SRM_CLIENT_ENTITIES_SEQ_ID = NULL 
		
		--Get new sub-workflow ID
		IF (SELECT TASK_TYPE_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE SEQ_ID = @WFL_TASKS_SEQ_ID) = 1
		BEGIN
			SET @DESTINATION_WORKFLOWS_SEQ_ID = 0
			SELECT @SOURCE_WORKFLOWS_SEQ_ID = WFL_WORKFLOWS_SEQ_ID2 FROM [SRM-Workflow].dbo.WFL_TASKS WHERE SEQ_ID = @WFL_TASKS_SEQ_ID
			
			SELECT @DESTINATION_WORKFLOWS_SEQ_ID=Workflow_Id_40_Live FROM [SRM-DataConversion].dbo.NIDC_WORKFLOW_MAPPINGS 
				WHERE Workflow_Id_82 = @SOURCE_WORKFLOWS_SEQ_ID AND Action_Taken='Add' AND DUPLICATE='N'

			IF @DESTINATION_WORKFLOWS_SEQ_ID =0
				SELECT @DESTINATION_WORKFLOWS_SEQ_ID=WFL_WORKFLOWS_SEQ_ID_OLD FROM [SRM-ClientCopyLog].dbo.SRM_CLIENT_WORKFLOW_COPY_LOG_40_82 
				WHERE WFL_WORKFLOWS_SEQ_ID_NEW= @SOURCE_WORKFLOWS_SEQ_ID

			IF @DESTINATION_WORKFLOWS_SEQ_ID = 0
				SET @DESTINATION_WORKFLOWS_SEQ_ID = 99999

		END
		ELSE
		BEGIN
			SET @DESTINATION_WORKFLOWS_SEQ_ID = NULL
			SET @SOURCE_WORKFLOWS_SEQ_ID = NULL
		END

		INSERT INTO [SRM-Workflow].dbo.WFL_TASKS
				( WFL_WORKFLOWS_SEQ_ID ,
				  TASK_TYPE_ID ,
				  SRM_CLIENT_ENTITY_SEQ_ID ,
				  WFL_WORKFLOWS_SEQ_ID2 ,
				  WFL_TASKS_SEQ_ID ,
				  STARTING_TASK ,
				  ENDING_TASK ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT @NEW_WORKFLOWS_SEQ_ID,
				TASK_TYPE_ID ,
				@NEW_SRM_CLIENT_ENTITIES_SEQ_ID ,
				@DESTINATION_WORKFLOWS_SEQ_ID ,--WFL_WORKFLOWS_SEQ_ID2 
				NULL, --WFL_TASKS_SEQ_ID,
				STARTING_TASK ,
				ENDING_TASK ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				WFL_TASKS_SEQ_ID ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_TASKS wt
		WHERE SEQ_ID = @WFL_TASKS_SEQ_ID
		
		SELECT @NEW_WFL_TASKS_SEQ_ID = MAX(SEQ_ID) FROM [SRM-Workflow].dbo.WFL_TASKS

		INSERT INTO @TEMP_WFL_TASKS_TABLE
		(WFL_TASKS_SEQ_ID, WFL_TASKS_SEQ_ID2)
		VALUES 
		(@WFL_TASKS_SEQ_ID, @NEW_WFL_TASKS_SEQ_ID)

		FETCH NEXT FROM CUR_WFL_TASKS INTO @WFL_TASKS_SEQ_ID, @SRM_CLIENT_ENTITIES_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID
	END

	CLOSE CUR_WFL_TASKS 
	DEALLOCATE CUR_WFL_TASKS 
	
	--SELECT * FROM @TEMP_WFL_TASKS_TABLE
	-- TASK UPDATER
	DECLARE CUR_WFL_TASKS_UPDATER CURSOR STATIC FOR
	SELECT SEQ_ID, SOURCE_OF_DATA FROM [SRM-Workflow].dbo.WFL_TASKS AS wt WHERE 
	wt.WFL_WORKFLOWS_SEQ_ID = @NEW_WORKFLOWS_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASKS_UPDATER 

	FETCH NEXT FROM CUR_WFL_TASKS_UPDATER INTO @WFL_TASKS_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF @WFL_NEXT_TASK_SEQ_ID IS NOT NULL
			SET @NEW_WFL_NEXT_TASK_SEQ_ID = (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = @WFL_NEXT_TASK_SEQ_ID)
		ELSE
			SET @NEW_WFL_NEXT_TASK_SEQ_ID = NULL 

		UPDATE [SRM-Workflow].dbo.WFL_TASKS
		SET WFL_TASKS_SEQ_ID = @NEW_WFL_NEXT_TASK_SEQ_ID
		WHERE SEQ_ID = @WFL_TASKS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_TASKS_UPDATER INTO @WFL_TASKS_SEQ_ID, @WFL_NEXT_TASK_SEQ_ID
	END

	CLOSE CUR_WFL_TASKS_UPDATER 
	DEALLOCATE CUR_WFL_TASKS_UPDATER 



	-- WFL_VARIABLES
	DECLARE CUR_WFL_VARIABLES CURSOR STATIC FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_VARIABLES AS wv 
	WHERE wv.WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_VARIABLES 

	FETCH NEXT FROM CUR_WFL_VARIABLES INTO @WFL_VARIABLES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_VARIABLES
				( WFL_WORKFLOWS_SEQ_ID ,
				  VARIABLE_NAME ,
				  VARIABLE_TYPE_ID ,
				  EXPRESSION ,
				  REMARKS ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID,
				VARIABLE_NAME ,
				VARIABLE_TYPE_ID ,
				EXPRESSION ,
				REMARKS ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_VARIABLES AS wv
		WHERE SEQ_ID = @WFL_VARIABLES_SEQ_ID

		FETCH NEXT FROM CUR_WFL_VARIABLES INTO @WFL_VARIABLES_SEQ_ID
	END

	CLOSE CUR_WFL_VARIABLES 
	DEALLOCATE CUR_WFL_VARIABLES


	--WFL_TASK_CONDITIONS
	DECLARE CUR_WFL_TASK_CONDITIONS CURSOR STATIC FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS WHERE 
	WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID) ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASK_CONDITIONS 

	FETCH NEXT FROM CUR_WFL_TASK_CONDITIONS INTO @WFL_TASK_CONDITIONS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_TASK_CONDITIONS
				( WFL_TASKS_SEQ_ID ,
				  WFL_TASKS_SEQ_ID2 ,
				  RANK ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtc.WFL_TASKS_SEQ_ID) ,
				(SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtc.WFL_TASKS_SEQ_ID2) ,
				RANK ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS wtc
		WHERE SEQ_ID = @WFL_TASK_CONDITIONS_SEQ_ID

		SELECT @NEW_WFL_TASK_CONDITIONS_SEQ_ID = MAX(SEQ_ID) FROM [SRM-Workflow].dbo.WFL_TASK_CONDITIONS


		INSERT INTO @TEMP_WFL_TASK_CONDITIONS_TABLE
		(WFL_TASK_CONDITIONS_SEQ_ID, WFL_TASK_CONDITIONS_SEQ_ID2)
		VALUES
		(@WFL_TASK_CONDITIONS_SEQ_ID, @NEW_WFL_TASK_CONDITIONS_SEQ_ID)  

		FETCH NEXT FROM CUR_WFL_TASK_CONDITIONS INTO @WFL_TASK_CONDITIONS_SEQ_ID
	END

	CLOSE CUR_WFL_TASK_CONDITIONS 
	DEALLOCATE CUR_WFL_TASK_CONDITIONS


	-- WFL_TASK_DETAILS
	DECLARE @Node BIGINT
	DECLARE @ATTRIB_COUNTER BIGINT

	DECLARE CUR_WFL_TASK_DETAILS CURSOR STATIC FOR
	SELECT wtd.SEQ_ID, EXPRESSION, wt.SRM_CLIENT_ENTITY_SEQ_ID 
	FROM [SRM-Workflow].dbo.WFL_TASK_DETAILS AS wtd 
	INNER JOIN [SRM-Workflow].dbo.WFL_TASKS wt ON wtd.WFL_TASKS_SEQ_ID = wt.SEQ_ID
	WHERE wtd.WFL_TASKS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_TASKS WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID) ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_TASK_DETAILS 

	FETCH NEXT FROM CUR_WFL_TASK_DETAILS INTO @WFL_TASK_DETAILS_SEQ_ID, @TASK_EXPRESSION, @SRM_CLIENT_ENTITIES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Node = 1
		SET @ATTRIB_COUNTER = (SELECT COUNT(attrib.value('(SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID)[1]', 'bigint')) FROM @TASK_EXPRESSION.nodes('/QUERY/CRITERIA_ATTRIBUTES') as EMP(attrib))

		WHILE @Node <= @ATTRIB_COUNTER
		BEGIN
			SET @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0
			SET @SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = (SELECT @TASK_EXPRESSION.value('(//QUERY/CRITERIA_ATTRIBUTES[sql:variable("@Node")]/SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID/node())[1]', 'varchar(max)')) 

			SET @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 0
			SELECT TOP 1 @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID_40 FROM 
			[SRM-DataConversion].dbo.SRM_CLIENT_ENTITIES_ATTRIBUTES_LOG_82_40 WHERE SRM_CLIENT_ENTITy_attributes_SEQ_ID_82=@SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID

			
			IF(@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID != '' AND @NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID > 0)
			BEGIN
				SET @TASK_EXPRESSION.modify('replace value of (//QUERY/CRITERIA_ATTRIBUTES[sql:variable("@Node")]/SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID/text())[1] with sql:variable("@NEW_SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID")') 
			END

			SET @Node = @Node + 1
		END

		INSERT INTO [SRM-Workflow].dbo.WFL_TASK_DETAILS
				( WFL_TASKS_SEQ_ID ,
				  WFL_TASK_CONDITIONS_SEQ_ID ,
				  DETAILS_TYPE_ID ,
				  EXPRESSION ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  (SELECT WFL_TASKS_SEQ_ID2 FROM @TEMP_WFL_TASKS_TABLE WHERE WFL_TASKS_SEQ_ID = wtd.WFL_TASKS_SEQ_ID) ,
				(SELECT WFL_TASK_CONDITIONS_SEQ_ID2 FROM @TEMP_WFL_TASK_CONDITIONS_TABLE WHERE WFL_TASK_CONDITIONS_SEQ_ID = wtd.WFL_TASK_CONDITIONS_SEQ_ID) ,
				DETAILS_TYPE_ID ,
				CONVERT(NVARCHAR(max), @TASK_EXPRESSION) ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_TASK_DETAILS wtd
		WHERE wtd.SEQ_ID = @WFL_TASK_DETAILS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_TASK_DETAILS INTO @WFL_TASK_DETAILS_SEQ_ID, @TASK_EXPRESSION, @SRM_CLIENT_ENTITIES_SEQ_ID
	END

	CLOSE CUR_WFL_TASK_DETAILS 
	DEALLOCATE CUR_WFL_TASK_DETAILS 


	-- WFL_MAILMERGE_TEMPLATES
	DECLARE CUR_WFL_MAILMERGE_TEMPLATES CURSOR STATIC FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES AS wmt 
	WHERE WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_MAILMERGE_TEMPLATES 

	FETCH NEXT FROM CUR_WFL_MAILMERGE_TEMPLATES INTO @WFL_MAILMERGE_TEMPLATES_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES
				( WFL_WORKFLOWS_SEQ_ID ,
				  TEMPLATE_TITLE ,
				  ATTACHMENT_URL ,
				  REMARKS ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID,
				TEMPLATE_TITLE ,
				ATTACHMENT_URL ,
				REMARKS ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_MAILMERGE_TEMPLATES wmt
		WHERE SEQ_ID = @WFL_MAILMERGE_TEMPLATES_SEQ_ID

		FETCH NEXT FROM CUR_WFL_MAILMERGE_TEMPLATES INTO @WFL_MAILMERGE_TEMPLATES_SEQ_ID
	END

	CLOSE CUR_WFL_MAILMERGE_TEMPLATES 
	DEALLOCATE CUR_WFL_MAILMERGE_TEMPLATES


	-- WFL_MAPPINGS
	DECLARE CUR_WFL_MAPPINGS CURSOR STATIC FOR
	SELECT SEQ_ID FROM [SRM-Workflow].dbo.WFL_MAPPINGS AS wm WHERE 
	WFL_WORKFLOWS_SEQ_ID = @FROM_WORKFLOW_SEQ_ID ORDER BY SEQ_ID ASC

	OPEN CUR_WFL_MAPPINGS 

	FETCH NEXT FROM CUR_WFL_MAPPINGS INTO @WFL_MAPPINGS_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		INSERT INTO [SRM-Workflow].dbo.WFL_MAPPINGS
				( WFL_WORKFLOWS_SEQ_ID ,
				  ATTRIBUTE_SYSTEM_NAME ,
				  ATTRIBUTE_DESCRIPTION ,
				  SRM_CLIENTS_SEQ_ID ,
				  SOURCE_OF_DATA ,
				  SOURCE_FILE ,
				  DATE_MODIFIED ,
				  MODIFIED_BY ,
				  DATE_CREATED ,
				  CREATED_BY ,
				  DELETED ,
				  DATE_DELETED ,
				  DELETED_BY
				)
		SELECT  @NEW_WORKFLOWS_SEQ_ID,
				ATTRIBUTE_SYSTEM_NAME ,
				ATTRIBUTE_DESCRIPTION ,
				@TO_SRM_CLIENTS_SEQ_ID ,
				SOURCE_OF_DATA ,
				SOURCE_FILE ,
				DATE_MODIFIED ,
				MODIFIED_BY ,
				@DATE_CREATED ,
				@CREATED_BY ,
				DELETED ,
				DATE_DELETED ,
				DELETED_BY 
		FROM [SRM-Workflow].dbo.WFL_MAPPINGS AS wm
		WHERE SEQ_ID = @WFL_MAPPINGS_SEQ_ID

		FETCH NEXT FROM CUR_WFL_MAPPINGS INTO @WFL_MAPPINGS_SEQ_ID
	END

	CLOSE CUR_WFL_MAPPINGS 
	DEALLOCATE CUR_WFL_MAPPINGS 


	



;

-- =============================================
-- Author:		<Nimra Azeem>
-- Create date: <29/01/2025>
-- Description:	<Return Client and Entity ID>
-- =============================================
CREATE PROCEDURE [dbo].[RETURN_CLIENT_AND_ENTITY_ID] 
	-- Add the parameters for the stored procedure here
	@p_RECORD_ID BIGINT,					-- SEQ_ID OF RECORD
	@p_USER_EMAIL NVARCHAR(200),			-- EMAIL OF USER
	@p_SRM_CLIENTS_SEQ_ID BIGINT OUTPUT,
	@p_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT OUTPUT
AS
BEGIN
	IF (ISNULL(@p_USER_EMAIL, '') = '') OR ISNULL(@p_RECORD_ID, 0) = 0
	BEGIN
		PRINT 'MISSING REQUIRED PARAMETER'
		RETURN
	END
	ELSE
	BEGIN
		DECLARE @SELECT_STATEMENT NVARCHAR(MAX)
		-- GET CLIENT BASED ON USER
		SELECT @p_SRM_CLIENTS_SEQ_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USER_EMAIL
		IF (ISNULL(@p_SRM_CLIENTS_SEQ_ID, 0) != 0) 
		BEGIN
			SELECT @SELECT_STATEMENT = 'SELECT @p_SRM_CLIENT_ENTITIES_SEQ_ID = SRM_CLIENT_ENTITIES_SEQ_ID FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_SRM_CLIENTS_SEQ_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA WHERE SEQ_ID = ' + CAST(ISNULL(@p_RECORD_ID, 0) AS NVARCHAR(50))
			PRINT @SELECT_STATEMENT
			EXEC sp_executesql @SELECT_STATEMENT, N'@p_SRM_CLIENT_ENTITIES_SEQ_ID INT OUTPUT', @p_SRM_CLIENT_ENTITIES_SEQ_ID = @p_SRM_CLIENT_ENTITIES_SEQ_ID OUTPUT;
			SELECT @p_SRM_CLIENT_ENTITIES_SEQ_ID, @p_SRM_CLIENTS_SEQ_ID
		END
	END
END;

