	@p_ELEMENT_1_ID NVARCHAR(100) OUTPUT,
	@p_ELEMENT_2_ID NVARCHAR(100) OUTPUT
AS
BEGIN
	DECLARE @ELEMENT_1_ATTRIBUTE_SEQ_ID BIGINT = 3049980
	DECLARE @ELEMENT_2_ATTRIBUTE_SEQ_ID BIGINT = 3049981
	
	DECLARE @strSQL NVARCHAR(MAX)
	DECLARE @strSQL2 NVARCHAR(MAX)
