;

-- =============================================
-- Author:		<Nimra Azeem>
-- Create date: <10/04/2026>
-- Description:	<Return Padded Financial ID>
-- =============================================
CREATE PROCEDURE [dbo].[RETURN_PADDED_FINANCIAL_ID]
	-- Add the parameters for the stored procedure here
	@ID NVARCHAR(MAX),					-- VALUE TO BE VALIDATED
	@p_USER_EMAIL NVARCHAR(200),			-- DATA TYPE TO BE VALIDATED
	@p_CONFIGURATION_VALUE NVARCHAR(10),			-- OUTPUT PARAMETER RETURNS 1/0
	@p_RESULT NVARCHAR(MAX) OUTPUT				-- OUTPUT PARAMETER RETURNS 1/0
AS
BEGIN
	IF (ISNULL(@ID , '') = '' OR ISNULL(@p_USER_EMAIL, '') = '' OR ISNULL(@p_CONFIGURATION_VALUE, '') = '')
	BEGIN  
	  PRINT 'MISSING REQUIRED PARAMETER'  
	  RETURN  
	END  

	IF ISNULL(@p_CONFIGURATION_VALUE, 0)  <= LEN(@ID) SET @p_RESULT = @ID
	ELSE SELECT @p_RESULT = LTRIM(RTRIM(STUFF(REPLICATE('0', @p_CONFIGURATION_VALUE), @p_CONFIGURATION_VALUE - LEN(@ID) + 1, LEN(@ID),CAST(@ID AS VARCHAR))))
	
END;

CREATE FUNCTION RHA_GET_HEAD_OFFICE_MEMBERSHIP_NO(@MEMBERSHIP_ID VARCHAR(200) )
RETURNS VARCHAR(200)
AS
BEGIN
DECLARE @HO_MEMBERSHIP_ID VARCHAR(200)

IF (CHARINDEX('-',@MEMBERSHIP_ID) > 0)  
	SET @MEMBERSHIP_ID = LEFT(@MEMBERSHIP_ID, CHARINDEX('-',@MEMBERSHIP_ID) - 1)   
SET @HO_MEMBERSHIP_ID = @MEMBERSHIP_ID + '-000'
  
RETURN @HO_MEMBERSHIP_ID
END;


Create Function [RemoveNonAlphaCharacters](@Temp VarChar(1000))
Returns VarChar(1000)
AS
Begin

    Declare @KeepValues as varchar(50)
    Set @KeepValues = '%[^a-z]%'
    While PatIndex(@KeepValues, @Temp) > 0
        Set @Temp = Stuff(@Temp, PatIndex(@KeepValues, @Temp), 1, '')

    Return @Temp
End;


create function dbo.RemoveSpecialChars (@s varchar(256)) returns varchar(256)
   with schemabinding
begin
   if @s is null
      return null
   declare @s2 varchar(256)
   set @s2 = ''
   declare @l int
   set @l = len(@s)
   declare @p int
   set @p = 1
   while @p <= @l begin
      declare @c int
      set @c = ascii(substring(@s, @p, 1))
      if @c between 48 and 57 or @c between 65 and 90 or @c between 97 and 122
         set @s2 = @s2 + char(@c)
      set @p = @p + 1
      end
   if len(@s2) = 0
      return null
   return @s2
   end;


CREATE FUNCTION [dbo].[ReplaceASCII](@inputString NVARCHAR(4000))
RETURNS VARCHAR(250)
AS
     BEGIN
         DECLARE @badStrings VARCHAR(100);
         DECLARE @increment INT= 1;
         WHILE @increment <= DATALENGTH(@inputString)
             BEGIN
                 IF(ASCII(SUBSTRING(@inputString, @increment, 1)) < 33)
                     BEGIN
                         SET @badStrings = CHAR(ASCII(SUBSTRING(@inputString, @increment, 1)));
                         SET @inputString = REPLACE(@inputString, @badStrings, '');
                 END;
                 SET @increment = @increment + 1;
             END;
         RETURN @inputString;
     END;

CREATE FUNCTION
[dbo].[ReplaceSpecialCharacterforAccountDedup](
@String NVARCHAR(500))
RETURNS
	NVARCHAR(500)
BEGIN

	RETURN 
	LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(
	@String,' Limited',''),' Limted',''),' Ltd.',''),' Ltd',''),' PLC',''),' UK',''),' (UK)',''),' Co.',''),' Company',''),' --',''),' -',''),' /',''))) 

END
;

CREATE FUNCTION
ReplaceWholeWord(
@String NVARCHAR(500),
@Word NVARCHAR(100),
@Replace NVARCHAR(100))
RETURNS
	NVARCHAR(500)
BEGIN
	DECLARE @Pos SmallInt

	SET @Pos = CHARINDEX(' ' + @Word + ' ', ' ' + ISNULL(@String, '') + ' ')
	RETURN CASE WHEN @Pos > 0 THEN STUFF(@String, @Pos, LEN(@Word), @Replace) ELSE @String END
END
;






