-- =============================================
-- Author:		<Asif Shehzad>
-- Create date: <25/08/2014>
-- Description:	<Export Marks Sheet>
-- =============================================
CREATE PROCEDURE [dbo].[SP_EXPORT_MARKS_SHEET] 
	@Param1 BigInt = 0, 
	--<@Param2, sysname, @p2> <Datatype_For_Param2, , int> = <Default_Value_For_Param2, , 0>
	@XMLDATA NVARCHAR(MAX) OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @COURSE_MASTER BIGINT
	DECLARE @MODULE_COUNT INT
	DECLARE @QUESTION_COUNT INT
	DECLARE @QUESTION_SUM INT
	DECLARE @MODULE_TYPE_COUNT INT
	DECLARE @CREATECOLUMNSSTRING NVARCHAR(4000)
	DECLARE @TYPE NVARCHAR(50)
	DECLARE @MODE NVARCHAR(50)
	DECLARE @DATE_FROM DATE
	DECLARE @DATE_TO DATE
	DECLARE @EXAMINER BIGINT
	DECLARE @CENTRE BIGINT
	DECLARE @CENTRE_COLUMN NVARCHAR(30)
	DECLARE @INSERTSTUDENTSTATEMENT NVARCHAR(4000)

	SELECT @COURSE_MASTER = ATTRIBUTE_004, @TYPE = ATTRIBUTE_003 
	, @DATE_FROM = ATTRIBUTE_006, @DATE_TO = ATTRIBUTE_007, @EXAMINER = ATTRIBUTE_008, @CENTRE = ATTRIBUTE_010
	FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 11596 AND DELETED = 'N' AND SEQ_ID = @Param1 -- 10338988

	declare @table_name nvarchar(100)
	declare @timestring nvarchar(12)
	declare @datestring nvarchar(10)

	set @timestring = convert(varchar(12), getdate(), 114)
	set @datestring = convert(varchar(10), getdate(), 103)

	set @table_name = 'EXPORT_MARKS_SHEET_DATA_' + replace(@datestring, '/', '') + replace(@timestring, ':','')
	print @table_name

	declare @CreateTable nvarchar(1000)
	set @CreateTable = 'CREATE TABLE ' + @table_name + '(BLANK NVARCHAR(50)); '
	exec sp_executesql @CreateTable

	IF @TYPE = 'PAPER'
	BEGIN

		print 'here 1'

		BEGIN -- GET COUNTS
			--COURSE_MASTER_MODULE
			SELECT @MODULE_COUNT = COUNT(*) FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND DELETED = 'N' AND ATTRIBUTE_002 = @COURSE_MASTER --9755403
	
			--COURSE_MASTER_ELEMENT	Total Questions
			SELECT @QUESTION_SUM = SUM(CAST(ISNULL(COURSE_MASTER_ELEMENT.ATTRIBUTE_009,0) AS BIGINT)) 
			FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_ELEMENT 
			INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_MODULE ON (COURSE_MASTER_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MASTER_MODULE.DELETED = 'N' AND COURSE_MASTER_ELEMENT.ATTRIBUTE_002 = COURSE_MASTER_MODULE.SEQ_ID)
			WHERE COURSE_MASTER_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 9784 AND COURSE_MASTER_ELEMENT.DELETED = 'N' AND COURSE_MASTER_MODULE.ATTRIBUTE_002 = @COURSE_MASTER --9755403	

			--COURSE_MASTER_ELEMENT Number of questions
			SELECT @QUESTION_COUNT = COUNT(*) 
			FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_ELEMENT 
			INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_MODULE ON (COURSE_MASTER_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MASTER_MODULE.DELETED = 'N' AND COURSE_MASTER_ELEMENT.ATTRIBUTE_002 = COURSE_MASTER_MODULE.SEQ_ID)
			WHERE COURSE_MASTER_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 9784 AND COURSE_MASTER_ELEMENT.DELETED = 'N' AND COURSE_MASTER_MODULE.ATTRIBUTE_002 = @COURSE_MASTER --9755403
	
			--COURSE_MASTER_MODULE	
			SELECT @MODULE_TYPE_COUNT = COUNT(*) FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MAST_MODULE
			INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA MODULE_TYPE ON (MODULE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = 9770 AND MODULE_TYPE.DELETED = 'N' AND COURSE_MAST_MODULE.ATTRIBUTE_004 = MODULE_TYPE.SEQ_ID)
			WHERE COURSE_MAST_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MAST_MODULE.DELETED = 'N' AND COURSE_MAST_MODULE.ATTRIBUTE_002 = @COURSE_MASTER --9755403

		END

		BEGIN -- ADDING COLUMN TO TEMP TABLE

		DECLARE @COLUMN_COUNT INT
		DECLARE @INSERT_COLUMN_COUNT INT
		SET @COLUMN_COUNT = 1 -- EXAM_NUMBER
		SET @COLUMN_COUNT = @COLUMN_COUNT + @MODULE_COUNT -- MODULE
		SET @COLUMN_COUNT = @COLUMN_COUNT + 1 --NOTES
		SET @INSERT_COLUMN_COUNT = @COLUMN_COUNT + 1
		SET @COLUMN_COUNT = @COLUMN_COUNT + @QUESTION_COUNT + @QUESTION_SUM -- NO OF QUESTION + SUM OF QUESTION
		SET @COLUMN_COUNT = @COLUMN_COUNT + 2 --FINAL TOTAL + CENTRE
		SET @COLUMN_COUNT = @COLUMN_COUNT + @MODULE_TYPE_COUNT -- MODULE TYPE COUNT
		SET @COLUMN_COUNT = @COLUMN_COUNT + 2 --DPFR + WRONG STONE

		PRINT @COLUMN_COUNT

	
		DECLARE @I INT
		SET @I = 1

		WHILE (@I <= @COLUMN_COUNT)
		BEGIN
			
			SET @CREATECOLUMNSSTRING = 'ALTER TABLE ' + @table_name + ' ADD F' + CAST(@I AS NVARCHAR(2)) + ' NVARCHAR(500) '
		
			EXEC SP_EXECUTESQL @CREATECOLUMNSSTRING
		
			SET @I = @I + 1
		END

		END

		BEGIN -- POPULATING FIRST TWO ROWS

		DECLARE @ELEMENT_NAME NVARCHAR(500)
		DECLARE @NO_OF_QUESTION INT
		DECLARE @INS_SECOND_COLUMN NVARCHAR(4000)

		DECLARE @INS_BLANK_ROW NVARCHAR(4000)
		SET @INS_BLANK_ROW = CHAR(10) + CHAR(13) + 'SELECT '' '', '' '','

		DECLARE @INS_FIRST_VALUES NVARCHAR(4000)
		SET @INS_FIRST_VALUES = CHAR(10) + CHAR(13) + 'UNION SELECT '' '', '' '','

		DECLARE @INS_SECOND_VALUES NVARCHAR(4000)
		SET @INS_SECOND_VALUES = CHAR(10) + CHAR(13) +  'UNION SELECT '' '', ''EXAM NO'','

		SET @INSERT_COLUMN_COUNT = 2

		DECLARE curModule CURSOR STATIC FOR 
		SELECT ATTRIBUTE_001 FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND DELETED = 'N' AND ATTRIBUTE_002 = @COURSE_MASTER -- 9361545
   
		OPEN curModule                                                             
		FETCH NEXT FROM curModule INTO @ELEMENT_NAME

		WHILE (@@Fetch_Status = 0)       
		BEGIN       

			 SET @INS_SECOND_COLUMN = @INS_SECOND_COLUMN + ' F' + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(2)) + ','
	 
			 SET @INS_BLANK_ROW = @INS_BLANK_ROW + ''' '','
			 SET @INS_FIRST_VALUES = @INS_FIRST_VALUES + ''' '','
			 SET @INS_SECOND_VALUES = @INS_SECOND_VALUES + '''' + @ELEMENT_NAME+ ''','

			 SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1

			FETCH NEXT FROM curModule INTO @ELEMENT_NAME
		END    
   
		CLOSE curModule                           
		DEALLOCATE curModule

		DECLARE @INSERT_SECOND_ROW_STATEMENT NVARCHAR(4000)
		SET @INSERT_SECOND_ROW_STATEMENT = 'INSERT INTO ' + @table_name 

		SET @INS_SECOND_COLUMN = @INS_SECOND_COLUMN + ' F' + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(2)) + ','
		
		SET @INS_BLANK_ROW = @INS_BLANK_ROW + ''' '','
		SET @INS_FIRST_VALUES = @INS_FIRST_VALUES + ''' '','
		SET @INS_SECOND_VALUES = @INS_SECOND_VALUES + ' ''NOTES'','

		SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1


		DECLARE @MODULE NVARCHAR(50)
		DECLARE @ELEMENT NVARCHAR(50)
		DECLARE @QUESTION_NUMBER NVARCHAR(50)
		DECLARE @TOTAL_QUESTIONS NVARCHAR(50)

		DECLARE curGeneral CURSOR STATIC FOR 
		SELECT COURSE_MASTER_MODULE.ATTRIBUTE_001, COURSE_MASTER_ELEMENT.ATTRIBUTE_004, COURSE_MASTER_ELEMENT_QUESTION.ATTRIBUTE_004, COURSE_MASTER_ELEMENT.ATTRIBUTE_009
		FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_ELEMENT_QUESTION 
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_ELEMENT ON COURSE_MASTER_ELEMENT_QUESTION.ATTRIBUTE_002 = COURSE_MASTER_ELEMENT.SEQ_ID AND COURSE_MASTER_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 9784 AND COURSE_MASTER_ELEMENT.DELETED = 'N'
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_MODULE ON (COURSE_MASTER_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MASTER_MODULE.DELETED = 'N' AND COURSE_MASTER_ELEMENT.ATTRIBUTE_002 = COURSE_MASTER_MODULE.SEQ_ID)
		WHERE COURSE_MASTER_ELEMENT_QUESTION.SRM_CLIENT_ENTITIES_SEQ_ID = 9785 AND COURSE_MASTER_ELEMENT_QUESTION.DELETED = 'N'  AND COURSE_MASTER_MODULE.ATTRIBUTE_002 = @COURSE_MASTER -- 9361545
		ORDER BY COURSE_MASTER_MODULE.ATTRIBUTE_001, COURSE_MASTER_ELEMENT.ATTRIBUTE_004,COURSE_MASTER_ELEMENT_QUESTION.ATTRIBUTE_004
   
		OPEN curGeneral                                                             
		FETCH NEXT FROM curGeneral INTO @MODULE, @ELEMENT, @QUESTION_NUMBER, @TOTAL_QUESTIONS

		WHILE (@@Fetch_Status = 0)       
		BEGIN

			 SET @INS_BLANK_ROW = @INS_BLANK_ROW + ''' '','
			 SET @INS_SECOND_COLUMN = @INS_SECOND_COLUMN + ' F' + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(2)) + ','


			 IF @QUESTION_NUMBER = 1
				SET @INS_FIRST_VALUES = @INS_FIRST_VALUES + '''Paper : ' + @MODULE + ' - ' + @ELEMENT + ''','
			 ELSE
				SET @INS_FIRST_VALUES = @INS_FIRST_VALUES + ''' '','

			 SET @INS_SECOND_VALUES = @INS_SECOND_VALUES + '''' + @QUESTION_NUMBER + ''','

			 SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1

			 IF @QUESTION_NUMBER = @TOTAL_QUESTIONS
			 BEGIN
				SET @INS_SECOND_COLUMN = @INS_SECOND_COLUMN + ' F' + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(2)) + ','
		
				SET @INS_BLANK_ROW = @INS_BLANK_ROW + ''' '','
				SET @INS_FIRST_VALUES = @INS_FIRST_VALUES + ''' '','
				SET @INS_SECOND_VALUES = @INS_SECOND_VALUES + ' ''Sub Total'','

				SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1
			 END

			FETCH NEXT FROM curGeneral INTO @MODULE, @ELEMENT, @QUESTION_NUMBER, @TOTAL_QUESTIONS
		END    
   
		CLOSE curGeneral                           
		DEALLOCATE curGeneral  

		SET @INS_SECOND_COLUMN = @INS_SECOND_COLUMN + ' F' + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(2)) + ','
		
		SET @INS_BLANK_ROW = @INS_BLANK_ROW + ''' '','
		SET @INS_FIRST_VALUES = @INS_FIRST_VALUES + ''' '','
		SET @INS_SECOND_VALUES = @INS_SECOND_VALUES + ' ''Final TOTAL'','

		SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1


		SET @INS_SECOND_COLUMN = @INS_SECOND_COLUMN + ' F' + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(2)) + ','
	
		PRINT ISNULL(@INSERT_COLUMN_COUNT, 0)
		SET @CENTRE_COLUMN = 'F'
		SET @CENTRE_COLUMN = @CENTRE_COLUMN + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(20))
		PRINT @CENTRE_COLUMN

		SET @INS_BLANK_ROW = @INS_BLANK_ROW + ''' '','
		SET @INS_FIRST_VALUES = @INS_FIRST_VALUES + ''' '','
		SET @INS_SECOND_VALUES = @INS_SECOND_VALUES + ' ''CENTRE'','

		SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1

		DECLARE @MODULE_TYPE NVARCHAR(10)

		DECLARE curModuleType CURSOR STATIC FOR 
		SELECT CASE MODULE_TYPE.ATTRIBUTE_002 WHEN 'Theory' THEN 'TH' WHEN 'Practical' THEN 'PR' END MODULE_TYPE_NAME 
		FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MAST_MODULE
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA MODULE_TYPE ON (MODULE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = 9770 AND MODULE_TYPE.DELETED = 'N' AND COURSE_MAST_MODULE.ATTRIBUTE_004 = MODULE_TYPE.SEQ_ID)
		WHERE COURSE_MAST_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MAST_MODULE.DELETED = 'N' AND COURSE_MAST_MODULE.ATTRIBUTE_002 = @COURSE_MASTER -- 9361545 --9755403

   
		OPEN curModuleType                                                             
		FETCH NEXT FROM curModuleType INTO @MODULE_TYPE

		WHILE (@@Fetch_Status = 0)       
		BEGIN       

			 SET @INS_SECOND_COLUMN = @INS_SECOND_COLUMN + ' F' + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(2)) + ','
	 
			 SET @INS_BLANK_ROW = @INS_BLANK_ROW + ''' '','
			 SET @INS_FIRST_VALUES = @INS_FIRST_VALUES + ''' '','
			 SET @INS_SECOND_VALUES = @INS_SECOND_VALUES + '''' + @MODULE_TYPE+ ''','

			 SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1

			FETCH NEXT FROM curModuleType INTO @MODULE_TYPE
		END    
   
		CLOSE curModuleType                           
		DEALLOCATE curModuleType

		SET @INS_SECOND_COLUMN = @INS_SECOND_COLUMN + ' F' + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(2)) + ','
		
		SET @INS_BLANK_ROW = @INS_BLANK_ROW + ''' '','
		SET @INS_FIRST_VALUES = @INS_FIRST_VALUES + ''' '','
		SET @INS_SECOND_VALUES = @INS_SECOND_VALUES + ' ''D P F R'','

		SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1

		SET @INS_SECOND_COLUMN = @INS_SECOND_COLUMN + ' F' + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(2)) + ','
		
		SET @INS_BLANK_ROW = @INS_BLANK_ROW + 'NULL'
		SET @INS_FIRST_VALUES = @INS_FIRST_VALUES + 'NULL'
		SET @INS_SECOND_VALUES = @INS_SECOND_VALUES + ' ''Wrong Stone'''

		SET @INSERT_SECOND_ROW_STATEMENT = @INSERT_SECOND_ROW_STATEMENT + @INS_BLANK_ROW + @INS_FIRST_VALUES + @INS_SECOND_VALUES
	
		PRINT @INSERT_SECOND_ROW_STATEMENT

		EXEC SP_EXECUTESQL @INSERT_SECOND_ROW_STATEMENT

	END

		BEGIN -- POPULATING STUDENT ROWS
			 SELECT DISTINCT CAST(STUDENT.ATTRIBUTE_004 AS BIGINT) STUDENT_NUMBER, COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_029 CENTRE_NAME
			 INTO #TEMP_GET_MARK_SHEET_STUDENTS_AND_CENTRES
			 FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_ELEMENT
			 INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION ON COURSE_REGISTRATION.SRM_CLIENT_ENTITIES_SEQ_ID = 10225 AND COURSE_REGISTRATION.DELETED = 'N' AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_002 = COURSE_REGISTRATION.SEQ_ID
			 INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA STUDENT ON STUDENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10168 AND STUDENT.DELETED = 'N' AND COURSE_REGISTRATION.ATTRIBUTE_004 = STUDENT.SEQ_ID
			 INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE ON COURSE.SRM_CLIENT_ENTITIES_SEQ_ID = 9810 AND COURSE.DELETED = 'N' AND COURSE_REGISTRATION.ATTRIBUTE_002 = COURSE.SEQ_ID
			 INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER ON COURSE_MASTER.SRM_CLIENT_ENTITIES_SEQ_ID = 9780 AND COURSE_MASTER.DELETED = 'N' AND COURSE.ATTRIBUTE_002 = COURSE_MASTER.SEQ_ID
			 WHERE COURSE_REGISTRATION_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10229 AND COURSE_REGISTRATION_ELEMENT.DELETED = 'N'
			 AND COURSE_MASTER.SEQ_ID = @COURSE_MASTER AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_018 BETWEEN @DATE_FROM AND @DATE_TO
			 AND ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028, 0) != 0
			 AND ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_010, 0) = CASE ISNULL(@EXAMINER, 0) WHEN 0 THEN ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_010, 0) ELSE @EXAMINER END
			 AND ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028, 0) = CASE ISNULL(@CENTRE, 0) WHEN 0 THEN ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028, 0) ELSE @CENTRE END
			 ORDER BY CAST(STUDENT.ATTRIBUTE_004 AS BIGINT), COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_029


			SET @INSERTSTUDENTSTATEMENT = 'INSERT INTO ' + @table_name + '(F1,' + @CENTRE_COLUMN + ')
			SELECT STUDENT_NUMBER,substring((select isnull(CENTRE_NAME,'''') + ''/'' from #TEMP_GET_MARK_SHEET_STUDENTS_AND_CENTRES b  
			WHERE B.STUDENT_NUMBER = A.STUDENT_NUMBER FOR XML PATH('''')),0,LEN((SELECT ISNULL(CENTRE_NAME,'''') + ''/'' FROM #TEMP_GET_MARK_SHEET_STUDENTS_AND_CENTRES B  
			WHERE B.STUDENT_NUMBER = A.STUDENT_NUMBER FOR XML PATH('''')))-1) AS ''CENTRE_NAME''  
			FROM #TEMP_GET_MARK_SHEET_STUDENTS_AND_CENTRES A  
			GROUP BY STUDENT_NUMBER  '

			PRINT @INSERTSTUDENTSTATEMENT

			EXEC SP_EXECUTESQL @INSERTSTUDENTSTATEMENT

			drop table #TEMP_GET_MARK_SHEET_STUDENTS_AND_CENTRES 

		END

	END
	ELSE IF @TYPE = 'Assignment'
	BEGIN
		
		

		BEGIN -- GET COUNTS

		DECLARE @COLUMNS_COUNT INT
		DECLARE @COURSEWORK_COUNT INT

		SET @COLUMNS_COUNT = 2 --EXAM + NOTES

		SELECT @COURSEWORK_COUNT = COUNT(*) 
		FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_COURSEWORK 
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_MODULE ON (COURSE_MASTER_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MASTER_MODULE.DELETED = 'N' AND COURSE_MASTER_COURSEWORK.ATTRIBUTE_002 = COURSE_MASTER_MODULE.SEQ_ID)
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSEWORK_TYPE ON (COURSEWORK_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = 9771 AND COURSEWORK_TYPE.DELETED = 'N' AND COURSE_MASTER_COURSEWORK.ATTRIBUTE_005 = COURSEWORK_TYPE.SEQ_ID)
		WHERE COURSE_MASTER_COURSEWORK.SRM_CLIENT_ENTITIES_SEQ_ID = 9786 AND COURSE_MASTER_COURSEWORK.DELETED = 'N' AND 
		COURSEWORK_TYPE.ATTRIBUTE_002 = 'Assignment' AND COURSE_MASTER_MODULE.ATTRIBUTE_002 = @COURSE_MASTER --9755403	
	
		SET @COLUMNS_COUNT = @COLUMNS_COUNT + @COURSEWORK_COUNT -- COURSEWORK COUNT

		SET @COLUMNS_COUNT = @COLUMNS_COUNT + 1 -- TOTAL COUNT

		PRINT @COLUMNS_COUNT
		END

		BEGIN -- CREATING COLUMNS
			DECLARE @J INT
			SET @J = 1

			WHILE (@J <= @COLUMNS_COUNT)
			BEGIN
			
				SET @CREATECOLUMNSSTRING = 'ALTER TABLE ' + @table_name + ' ADD F' + CAST(@J AS NVARCHAR(2)) + ' NVARCHAR(500) '
		
				EXEC SP_EXECUTESQL @CREATECOLUMNSSTRING
		
				SET @J = @J + 1
			END
		END

		--DECLARE @SELECT NVARCHAR(500)
		--SET @SELECT = 'SELECT * FROM ' + @table_name
		--EXEC SP_EXECUTESQL @SELECT

		BEGIN -- POPULATING FIRST TWO ROWS

		DECLARE @INSERT_SECOND_ROW_STATEMENT2 NVARCHAR(4000)
		SET @INSERT_SECOND_ROW_STATEMENT2 = 'INSERT INTO ' + @table_name 

		DECLARE @INS_FIRST_VALUES2 NVARCHAR(4000)
		SET @INS_FIRST_VALUES2 = CHAR(10) + CHAR(13) + 'SELECT '' '', '' '','

		DECLARE @INS_SECOND_VALUES2 NVARCHAR(4000)
		SET @INS_SECOND_VALUES2 = CHAR(10) + CHAR(13) +  'UNION SELECT '' '', ''EXAM NO'','

		SET @INSERT_COLUMN_COUNT = 2

		SET @INS_SECOND_COLUMN = @INS_SECOND_COLUMN + ' F' + CAST(@INSERT_COLUMN_COUNT AS NVARCHAR(2)) + ','
	
		SET @INS_FIRST_VALUES2 = @INS_FIRST_VALUES2 + ''' '','
		SET @INS_SECOND_VALUES2 = @INS_SECOND_VALUES2 + ' ''NOTES'','

		SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1


		DECLARE @COURSE_WORK NVARCHAR(100)
		DECLARE @QUESTION_NUMBER1 INT
		SET @QUESTION_NUMBER1 = 1



		DECLARE curGeneral CURSOR STATIC FOR 
		SELECT COURSE_MASTER_COURSEWORK.ATTRIBUTE_001
		FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_COURSEWORK 
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_MODULE ON (COURSE_MASTER_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MASTER_MODULE.DELETED = 'N' AND COURSE_MASTER_COURSEWORK.ATTRIBUTE_002 = COURSE_MASTER_MODULE.SEQ_ID)
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSEWORK_TYPE ON (COURSEWORK_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = 9771 AND COURSEWORK_TYPE.DELETED = 'N' AND COURSE_MASTER_COURSEWORK.ATTRIBUTE_005 = COURSEWORK_TYPE.SEQ_ID)
		WHERE COURSE_MASTER_COURSEWORK.SRM_CLIENT_ENTITIES_SEQ_ID = 9786 AND COURSE_MASTER_COURSEWORK.DELETED = 'N' AND 
		COURSEWORK_TYPE.ATTRIBUTE_002 = 'Assignment' AND COURSE_MASTER_MODULE.ATTRIBUTE_002 = @COURSE_MASTER-- 9361545	
		ORDER BY COURSE_MASTER_COURSEWORK.ATTRIBUTE_001
   
		OPEN curGeneral                                                             
		FETCH NEXT FROM curGeneral INTO @COURSE_WORK

		WHILE (@@Fetch_Status = 0)       
		BEGIN			 

			 IF @QUESTION_NUMBER1 = 1
				SET @INS_FIRST_VALUES2 = @INS_FIRST_VALUES2 + '''Assignments'','
			 ELSE
				SET @INS_FIRST_VALUES2 = @INS_FIRST_VALUES2 + ''' '','

			 SET @QUESTION_NUMBER1 = @QUESTION_NUMBER1 + 1

			 SET @INS_SECOND_VALUES2 = @INS_SECOND_VALUES2 + '''' + @COURSE_WORK + ''','

			 SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1


			FETCH NEXT FROM curGeneral INTO @COURSE_WORK
		END    
   
		CLOSE curGeneral                           
		DEALLOCATE curGeneral  

		SET @INS_FIRST_VALUES2 = @INS_FIRST_VALUES2 + 'NULL'
		SET @INS_SECOND_VALUES2 = @INS_SECOND_VALUES2 + ' ''TOTAL'''

		SET @INSERT_COLUMN_COUNT = @INSERT_COLUMN_COUNT + 1

		SET @INSERT_SECOND_ROW_STATEMENT2 = @INSERT_SECOND_ROW_STATEMENT2 + @INS_FIRST_VALUES2 + @INS_SECOND_VALUES2

		--PRINT @INSERT_SECOND_ROW_STATEMENT2
		EXEC SP_EXECUTESQL @INSERT_SECOND_ROW_STATEMENT2

	
		END

		BEGIN -- POPULATING STUDENT ROWS

			
			 SELECT DISTINCT CAST(STUDENT.ATTRIBUTE_004 AS BIGINT) STUDENT_NUMBER
			 INTO #TEMP_GET_MARK_SHEET_STUDENTS
			 FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_ELEMENT
			 INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION ON COURSE_REGISTRATION.SRM_CLIENT_ENTITIES_SEQ_ID = 10225 AND COURSE_REGISTRATION.DELETED = 'N' AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_002 = COURSE_REGISTRATION.SEQ_ID
			 INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA STUDENT ON STUDENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10168 AND STUDENT.DELETED = 'N' AND COURSE_REGISTRATION.ATTRIBUTE_004 = STUDENT.SEQ_ID
			 INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE ON COURSE.SRM_CLIENT_ENTITIES_SEQ_ID = 9810 AND COURSE.DELETED = 'N' AND COURSE_REGISTRATION.ATTRIBUTE_002 = COURSE.SEQ_ID
			 INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER ON COURSE_MASTER.SRM_CLIENT_ENTITIES_SEQ_ID = 9780 AND COURSE_MASTER.DELETED = 'N' AND COURSE.ATTRIBUTE_002 = COURSE_MASTER.SEQ_ID
			 WHERE COURSE_REGISTRATION_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10229 AND COURSE_REGISTRATION_ELEMENT.DELETED = 'N'
			 AND COURSE_MASTER.SEQ_ID = @COURSE_MASTER AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_018 BETWEEN @DATE_FROM AND @DATE_TO
			 AND ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028, 0) != 0
			 AND ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_010, 0) = CASE ISNULL(@EXAMINER, 0) WHEN 0 THEN ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_010, 0) ELSE @EXAMINER END
			 AND ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028, 0) = CASE ISNULL(@CENTRE, 0) WHEN 0 THEN ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028, 0) ELSE @CENTRE END
			 ORDER BY CAST(STUDENT.ATTRIBUTE_004 AS BIGINT)


			 SET @INSERTSTUDENTSTATEMENT = 'INSERT INTO ' + @table_name + '(F1)
			 SELECT STUDENT_NUMBER FROM #TEMP_GET_MARK_SHEET_STUDENTS '

			 EXEC SP_EXECUTESQL @INSERTSTUDENTSTATEMENT

			drop table #TEMP_GET_MARK_SHEET_STUDENTS 

		END

	END

	
	--ALTER TABLE EXPORT_MARKS_SHEET_DATA DROP COLUMN BLANK
	DECLARE @DROPCOLUMN NVARCHAR(500)
	SET @DROPCOLUMN = 'ALTER TABLE ' + @table_name + ' DROP COLUMN BLANK'
	EXEC SP_EXECUTESQL @DROPCOLUMN
	

	BEGIN -- CONVERT DATA INTO XML
	
    DECLARE @TableData XML--,@TableSchema XML
	

	--SELECT @TableSchema = (
	--	select  column_name,
	--			data_type,
	--			case(is_nullable)
	--				when 'YES' then 'true'
	--				else 'false'    
	--			end as is_nullable,
	--			CHARACTER_MAXIMUM_LENGTH as Charlen
	--	from information_schema.columns [column]
	--	where table_name = 'EXPORT_MARKS_SHEET_DATA'
	--	for XML  PATH,root('Table') 
	--	)

	DECLARE @CONVERTXML NVARCHAR(1000)

	SET @CONVERTXML = 'SELECT @MyTableData = (
	SELECT * 
	FROM ' + @table_name + ' row
	FOR XML PATH, BINARY BASE64,root(''NewDataSet'') 
	) '


	DECLARE @params nvarchar(100)
	SET @params = '@MyTableData xml output'
	EXEC sp_executesql @CONVERTXML, @params, @MyTableData = @TableData output

	

	SET @XMLDATA = REPLACE(REPLACE(CONVERT(VARCHAR(MAX),@TableData), '<row>', '<Table>'), '</row>', '</Table>')
	
	END

	BEGIN -- DROP TABLE
		DECLARE @DROPTABLE NVARCHAR(500)
		SET @DROPTABLE = 'DROP TABLE ' + @table_name

		EXEC SP_EXECUTESQL @DROPTABLE

	END
END





;





