-- =============================================
CREATE PROCEDURE [dbo].[SP_EXPORT_RESULTS_TEST] 
	-- Add the parameters for the stored procedure here
	--<@Param1, sysname, @p1> <Datatype_For_Param1, , int> = <Default_Value_For_Param1, , 0>, 
	--<@Param2, sysname, @p2> <Datatype_For_Param2, , int> = <Default_Value_For_Param2, , 0>
	@XML_DATA NVARCHAR(MAX) OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    DECLARE @TableData XML,@TableSchema XML

SELECT @TableSchema = (
    select  column_name,
            data_type,
            case(is_nullable)
                when 'YES' then 'true'
                else 'false'    
            end as is_nullable,
			CHARACTER_MAXIMUM_LENGTH as Charlen
    from information_schema.columns [column]
    where table_name = 'EXPORT_MARKS_SHEET_DATA' 
    for XML  PATH,root('Table') 
	)

SELECT @TableData = (
SELECT * 
FROM EXPORT_MARKS_SHEET_DATA row
FOR XML PATH, BINARY BASE64,root('NewDataSet') 
)

SET @XML_DATA = REPLACE(REPLACE(CONVERT(VARCHAR(MAX),@TableData), '<row>', '<Table>'), '</row>', '</Table>')
END




;




