-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_IMPORT_MARKS_SHEET] 
	-- Add the parameters for the stored procedure here
	@XML_DATA NVARCHAR(MAX) = NULL, 
	@COLUMNS_COUNT INT = 0,
	@COURSE_MASTER BIGINT = 0
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    declare @xml xml
	DECLARE @TYPE NVARCHAR(50)
	DECLARE @WFL_JOBS_SEQ_ID BIGINT
	SET @WFL_JOBS_SEQ_ID = 0

	DECLARE @xmlHandle int
	DECLARE @SEQIDS NVARCHAR(MAX)

	set @xml = @XML_DATA

	--Creating job for output
	BEGIN
		DECLARE @JOB_ID BIGINT

		INSERT INTO [SRM-WORKFLOW].DBO.WFL_JOBS (JOB_ID,WORKFLOW_DESCRIPTION,START_DATE,STATUS_ID,SRM_CLIENTS_SEQ_ID,DATE_CREATED,CREATED_BY,DELETED)
		SELECT MAX(JOB_ID)+1, 'FOR MARKSHEET IMPORT', GETDATE(), 2, 36, GETDATE(), 'MARKSHEET IMPORT PROCESS','N' FROM [SRM-WORKFLOW].DBO.WFL_JOBS  

		SET @WFL_JOBS_SEQ_ID = SCOPE_IDENTITY()
	END

	PRINT 'INSERTED WFL_JOBS:' + CAST(@WFL_JOBS_SEQ_ID AS NVARCHAR(100))

	declare @i int
	declare @j nvarchar(5)

	set @i = 1
	declare @columns nvarchar(1000)
	declare @SheetcolumnsWOType nvarchar(1000)
	declare @columnsWOTYPE nvarchar(1000)

	set @columns = ''
	SET @columnsWOTYPE = ''
	SET @SheetcolumnsWOType = ''
	while(@i <= @COLUMNS_COUNT)
	begin

		set @j = @i
		set @columns = @columns + 'F' + cast(@i as nvarchar(2)) + ' NVARCHAR(100),'
		set @SheetcolumnsWOType = @SheetcolumnsWOType + 'F' + cast(@i as nvarchar(2)) + ','
		SET @columnsWOTYPE = @columnsWOTYPE + 'ATTRIBUTE_' + REPLICATE('0', 3 - LEN(@j)) + @j  + ','
		set @i = @i + 1 
	end

	if len(@columns) > 1
		set @columns = substring(@columns, 1, len(@columns)-1)

	if len(@SheetcolumnsWOType) > 1
		set @SheetcolumnsWOType = substring(@SheetcolumnsWOType, 1, len(@SheetcolumnsWOType)-1)

	if len(@columnsWOTYPE) > 1
		set @columnsWOTYPE = substring(@columnsWOTYPE, 1, len(@columnsWOTYPE)-1)
	

	EXEC sp_xml_preparedocument @xmlHandle output, @xml 

	declare @importstatement nvarchar(4000)

	set @importstatement = ' SELECT * INTO #IMPORT_MARKS_SHEET_DATA
    FROM OPENXML (@MyxmlHandle, ''/NewDataSet/Table'',2) 
    WITH (' + @columns + ') '

	set @importstatement = @importstatement + CHAR(10) + CHAR(13) + ';with C(XmlCol) as
	(
	  select
		(select T.*
		 for xml path(''row''), type)
	  from #IMPORT_MARKS_SHEET_DATA as T
	)
	delete from C
	where C.XmlCol.exist(''row/*[. != ""]'') = 0 '

	set @importstatement = @importstatement + CHAR(10) + CHAR(13) + 'INSERT INTO [SRM-WORKFLOW].DBO.WFL_OUTPUT(WFL_JOBS_SEQ_ID,' + @columnsWOTYPE + ') '
	set @importstatement = @importstatement + 'SELECT ' + CAST(@WFL_JOBS_SEQ_ID  AS NVARCHAR(100)) +',' + @SheetcolumnsWOType + ' FROM #IMPORT_MARKS_SHEET_DATA '

	
	--PRINT @importstatement

	DECLARE @params nvarchar(100)
	SET @params = '@MyxmlHandle int'
	EXEC sp_executesql @importstatement,  @params, @MyxmlHandle = @xmlHandle



	SELECT TOP 1 @SEQIDS = SEQ_ID FROM [SRM-WORKFLOW].DBO.WFL_OUTPUT WHERE WFL_JOBS_SEQ_ID = @WFL_JOBS_SEQ_ID
	SELECT @SEQIDS = COALESCE(@SEQIDS  + ', ' ,'') + CAST(SEQ_ID AS NVARCHAR(100)) FROM [SRM-WORKFLOW].DBO.WFL_OUTPUT WHERE WFL_JOBS_SEQ_ID = @WFL_JOBS_SEQ_ID AND SEQ_ID != @SEQIDS

	print @SEQIDS
	
	SELECT @TYPE = ATTRIBUTE_003 
	FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 11596 AND DELETED = 'N' AND SEQ_ID = @COURSE_MASTER -- 10338988
	print @TYPE
	if @TYPE = 'Paper'
	BEGIN		
		EXEC [dbo].[SP_UPDATE_REGISTERED_ELEMENT_RESULT_DETAIL] 
		@COLUMNS_COUNT = @COLUMNS_COUNT,
		@MARKS_SHEET = @COURSE_MASTER,
		@WFL_JOBS_SEQ_ID = @WFL_JOBS_SEQ_ID,
		@SEQIDS = @SEQIDS
	END
	ELSE if @TYPE = 'Assignment'
	BEGIN
		EXEC [dbo].[SP_UPDATE_REGISTERED_COURSEWORK] 
		@COLUMNS_COUNT = @COLUMNS_COUNT,
		@MARKS_SHEET = @COURSE_MASTER,
		@WFL_JOBS_SEQ_ID = @WFL_JOBS_SEQ_ID,
		@SEQIDS = @SEQIDS
	END


END


;





