 --=============================================20791704
-- Author:		Mudassar Rafiq
-- Create date: 29-01-2016 
-- Description:	Move Contact detail to EI api
-- =============================================
CREATE PROCEDURE [dbo].[SP_POST_DATA_TO_API_EI]
	@CONTACT_RECORD_ID BIGINT
  , @USE_RDS VARCHAR(1)='Y'
  , @ERROR VARCHAR(200) OUTPUT
  

AS

----------------------------------------------------------------------------------------------------
--											SP CALL AND LOG
----------------------------------------------------------------------------------------------------
--DECLARE @ERROR VARCHAR(MAX)
--EXEC SP_POST_DATA_TO_API_EI @CONTACT_RECORD_ID=190484162 , @ERROR=@ERROR OUTPUT
--SELECT * FROM POST_DATA_TO_API_EI_LOG
----------------------------------------------------------------------------------------------------


PRINT 'CALLING THE WEB SERVICE ''SP_POST_DATA_TO_API_EI'' WITH PARAMS'

--SELECT * FROM POST_DATA_TO_API_EI_LOG


--CREATE TABLE POST_DATA_TO_API_EI_LOG(
--SEQ_ID BIGINT IDENTITY(1,1),
--CONTACT_RECORD_ID BIGINT,
--PRIMARY_EMAIL NVARCHAR(100),
--LOGIN_USER_NAME NVARCHAR(100),
--URL NVARCHAR(100),
--RESPONSE VARCHAR(MAX),
--DATE_CREATED DATETIME,
--DATE_MODIFIED DATETIME
--)

DECLARE 
@INSERT_CONTACT_SP_START_TIME DATETIME
,@INSERT_CONTACT_SP_END_TIME  DATETIME
,@RECORD_COUNT BIGINT = 0

SELECT @RECORD_COUNT=COUNT(*) FROM [SRM-CustomEntities_77]..EI_GDPR_data_TEMP WHERE PARENT_SEQ_ID = @CONTACT_RECORD_ID
IF(@RECORD_COUNT > 0)
BEGIN
	--No need to call API as no data is modified
	PRINT 'No Sync Run'
	RETURN
END

DECLARE @SP_Response INT = 0
--below sp will check if any data of contact detail, committee,mailing preference and profile is modified then it retun 1 else it returns 0

SET @INSERT_CONTACT_SP_START_TIME = GETDATE()

EXEC [SRM-DataPivot_77].dbo.INSERT_UPDATE_CONTACT_IN_API @ContactSeqId = @CONTACT_RECORD_ID, -- bigint
    @RESPONSE = @SP_Response OUTPUT -- int

SET @INSERT_CONTACT_SP_END_TIME = GETDATE()

print '@SP_Response.......' + cast(@SP_Response as varchar(100))


IF(@SP_Response = 0)
BEGIN
	--No need to call API as no data is modified
	RETURN
END


DECLARE 
 @OOMI_SEQ_ID BIGINT
,@UCN VARCHAR(50)
,@FIRSTNAME VARCHAR(200)
,@LASTNAME VARCHAR(200)
,@PRIMARY_EMAIL VARCHAR(200)
,@LOGIN_USER_NAME VARCHAR(200)
,@DELETED VARCHAR(1)

SELECT	TOP 1
  @UCN				=	ISNULL(ATTRIBUTE_002,'')
, @FIRSTNAME		=	ISNULL(ATTRIBUTE_006,'')	
, @LASTNAME			=	ISNULL(ATTRIBUTE_008,'')
, @PRIMARY_EMAIL	=	ISNULL(ATTRIBUTE_069,'')
, @LOGIN_USER_NAME	=	ISNULL(ATTRIBUTE_111,'')
, @DELETED			=	ISNULL(DELETED,'N')
FROM [SRM-CustomEntities_77].DBO.CUS_ENTITY_DATA WITH(NOLOCK)
WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 22675 
AND SEQ_ID = @CONTACT_RECORD_ID


--check for the duplicate call

--IF ( (SELECT TOP 1 LOGIN_USER_NAME from POST_DATA_TO_API_EI_LOG WHERE CONTACT_RECORD_ID=@CONTACT_RECORD_ID ORDER BY SEQ_ID DESC) =  @LOGIN_USER_NAME)
--BEGIN
--	PRINT 'Duplicate call'
--	RETURN
--END

DECLARE 
 @ENDPOINT VARCHAR(MAX)
,@HIT_TEST_OR_LIVE_FLAG VARCHAR(10)
,@PRESET_KEY VARCHAR(MAX)

SET @HIT_TEST_OR_LIVE_FLAG='LIVE'
SET @PRESET_KEY  ='98LqZnpj4scwILTU8ooztqPP'

IF @HIT_TEST_OR_LIVE_FLAG='TEST'
BEGIN
		SET @ENDPOINT='https://TESTei-api.ladoo.com.au/oomiendpoint/updateuser?key=' + @PRESET_KEY
END 
ELSE
BEGIN
		IF ISNULL(@DELETED,'N')='N'    
			SET @ENDPOINT='https://ei-api.ladoo.com.au/foroomi/updateuser?key=' + @PRESET_KEY
		ELSE
		    SET @ENDPOINT='https://ei-api.ladoo.com.au/foroomi/deleteuser?key=' + @PRESET_KEY


END


DECLARE @OBJ INT, @VALUE INT,@hr2 INT, @len INT, @SURL VARCHAR(max),@vStatusText varchar(8000), @status varchar(8000),@response varchar(8000),@hr INT,@src varchar(255),@desc varchar(255), @DateCreated datetime

SET @SURL=@ENDPOINT

SET @sURL = @sURL  + '&email='+ CONVERT(VARCHAR(MAX),@LOGIN_USER_NAME)

--Mudassar
print '------------@sURL'
print @sURL

DECLARE @LOG_SEQ_ID BIGINT

INSERT INTO POST_DATA_TO_API_EI_LOG (CONTACT_RECORD_ID,PRIMARY_EMAIL,LOGIN_USER_NAME,URL,RESPONSE,DATE_CREATED , INSERT_CONTACT_SP_START_TIME,INSERT_CONTACT_SP_END_TIME,IS_CONTACT_DELETED)
VALUES(@CONTACT_RECORD_ID ,@PRIMARY_EMAIL , @LOGIN_USER_NAME , @SURL, NULL , GETDATE(), @INSERT_CONTACT_SP_START_TIME,@INSERT_CONTACT_SP_END_TIME,@DELETED)

SET @LOG_SEQ_ID = SCOPE_IDENTITY()

Print '@USE_RDS.....' + @USE_RDS


--DECLARE @Response2 NVARCHAR(3000) =N''
--EXEC [10.0.0.100].[SRM-Framework_new].dbo.SP_POST_DATA_TO_API_EI_NEW_RDS @LOG_SEQ_ID , @LOGIN_USER_NAME , @DELETED ,@Response2 OUTPUT
--SELECT @Response2

        DECLARE @STRSQL NVARCHAR(1000)
		SET @STRSQL = 'EXEC [SRM-Framework_new].[dbo].[SP_POST_DATA_TO_API_EI_NEW_RDS] @RECORD_ID = ' + cast(@LOG_SEQ_ID as nvarchar(20)) + ''
		SET @STRSQL = 'EXEC (''' + @STRSQL + ''') AT [db_server]'
		EXEC (@STRSQL)

		SELECT @response = response, @DateCreated = DATE_CREATED FROM [db_server].[SRM-Framework_new].dbo.POST_DATA_TO_API_EI_LOG WHERE SEQ_ID = @LOG_SEQ_ID
		UPDATE POST_DATA_TO_API_EI_LOG
			SET response = @response,
			DATE_MODIFIED = @DateCreated
		WHERE
			SEQ_ID = @LOG_SEQ_ID
RETURN

IF ISNULL(@USE_RDS,'N')='Y'
BEGIN
		--INSERT INTO POST_DATA_TO_API_EI_LOG_logSTATUS (POST_DATA_TO_API_EI_LOG_SEQ_ID,LOG_STATUS) VALUES(@LOG_SEQ_ID,'PEN')
		EXEC [10.0.0.100].[SRM-Framework_new].dbo.SP_POST_DATA_TO_API_EI_NEW_RDS @LOG_SEQ_ID
END
ELSE
BEGIN
				EXEC sp_OACreate 'MSXML2.ServerXMLHTTP', @obj OUT
				--select @obj
				EXEC @hr2 =sp_OAMethod @obj, 'Open',Null, 'GET',@sURL, false
				--SELECT @hr2
				exec @hr2 = sp_OAMethod @obj, 'setRequestHeader', NULL, 'Content-Type','application/x-www-form-urlencoded'
				--SELECT @hr2
				EXEC @hr2 =sp_OAMethod @obj, 'send', NULL, ''
				--SELECT @hr2
				exec @hr2 = sp_OAGetProperty @obj, 'status', @status OUT
				--SELECT @hr2 --set @len = len(@sUrl) --SELECT @LEN
				exec @hr2 = sp_OAMethod @obj, 'setRequestHeader', NULL, 'Content-Length', 200
				--SELECT @hr2
				EXEC sp_OAMethod @obj, 'StatusText', @vStatusText OUTPUT
				--select @vStatusText
				SET @response = @response
				exec @hr2 = sp_OAGetProperty @obj, 'responseText', @response OUT  

				print '@response: ' + isnull(@response, '')

				IF @response != ''
				BEGIN

					IF ISNULL(@LOG_SEQ_ID,0) >0
					BEGIN
						UPDATE POST_DATA_TO_API_EI_LOG SET RESPONSE = @response, DATE_MODIFIED=GETDATE() WHERE SEQ_ID=@LOG_SEQ_ID
					END
				END
END


--SELECT CONTACT_RECORD_ID c, COUNT(*) FROM POST_DATA_TO_API_EI_LOG WHERE CAST(DATE_MODIFIED AS DATE)='2018-02-05' GROUP BY CONTACT_RECORD_ID HAVING count(*)>3 ORDER BY count(*) desc
