	--ATTRIBUTE_131,ATTRIBUTE_132,ATTRIBUTE_133,ATTRIBUTE_134,ATTRIBUTE_135,ATTRIBUTE_136,ATTRIBUTE_137,ATTRIBUTE_138,ATTRIBUTE_139,ATTRIBUTE_140,
	--ATTRIBUTE_141,ATTRIBUTE_142,ATTRIBUTE_143,ATTRIBUTE_144,ATTRIBUTE_145,ATTRIBUTE_146,ATTRIBUTE_147,ATTRIBUTE_148,ATTRIBUTE_149,ATTRIBUTE_150
	FROM [SRM-WORKFLOW].DBO.WFL_OUTPUT WHERE WFL_JOBS_SEQ_ID = @WFL_JOBS_SEQ_ID AND SEQ_ID IN (SELECT VALUE FROM [SRM-FRAMEWORK_NEW].DBO.fn_Split(@SEQIDS,',')) 
	UNION 
