	--ATTRIBUTE_141,ATTRIBUTE_142,ATTRIBUTE_143,ATTRIBUTE_144,ATTRIBUTE_145,ATTRIBUTE_146,ATTRIBUTE_147,ATTRIBUTE_148,ATTRIBUTE_149,ATTRIBUTE_150
	FROM [SRM-WORKFLOW].DBO.WFL_OUTPUT WHERE WFL_JOBS_SEQ_ID = @WFL_JOBS_SEQ_ID AND ATTRIBUTE_001 IN (@STUDENT_NUMBER) )A
	
	select @Pivotcols = STUFF((SELECT ',' + QUOTENAME(SEQ_ID) 
						from #TMP_IMPORT_MARKS_SHEET_DATA
						group by SEQ_ID
						order by SEQ_ID
				FOR XML PATH(''), TYPE
				).value('.', 'NVARCHAR(MAX)') ,1,1,'')


	DECLARE curGeneral CURSOR STATIC FOR 
	--SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = '##TMP_IMPORT_MARKS_SHEET_DATA' AND COLUMN_NAME != 'ID'
	SELECT COLUMN_NAME FROM TEMPDB.INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME IN (
	SELECT TABLE_NAME FROM TEMPDB.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE '%#TMP_IMPORT_MARKS_SHEET_DATA%') AND COLUMN_NAME !='SEQ_ID'
   
	OPEN curGeneral                                                             
	FETCH NEXT FROM curGeneral INTO @COLUMNAME    

	WHILE (@@Fetch_Status = 0)       
	BEGIN        


	set @query = N'SELECT ' + @Pivotcols + N' from 
				 (
					select ' + @COLUMNAME + ',SEQ_ID
					from #TMP_IMPORT_MARKS_SHEET_DATA
				) x
				pivot 
				(
					max(' + @COLUMNAME + ' )
					for SEQ_ID in (' + @Pivotcols + N')
				) p '


		INSERT INTO #TMP_IMPORT_PIVOT 
		exec sp_executesql @query;

		FETCH NEXT FROM curGeneral INTO @COLUMNAME    
	END    
   
	CLOSE curGeneral                           
	DEALLOCATE curGeneral  
    
END







;





