CREATE PROCEDURE [dbo].[SP_UPDATE_REGISTERED_COURSEWORK] 
	-- Add the parameters for the stored procedure here	
	@COLUMNS_COUNT INT = 0,
	@MARKS_SHEET BIGINT = 0,
	@WFL_JOBS_SEQ_ID BIGINT = 0,
	@SEQIDS NVARCHAR(MAX) 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @COURSE_MASTER BIGINT
	DECLARE @TYPE NVARCHAR(50)
	DECLARE @MODE NVARCHAR(50)
	DECLARE @DATE_FROM DATE
	DECLARE @DATE_TO DATE
	DECLARE @EXAMINER BIGINT
	DECLARE @CENTRE BIGINT

	DECLARE @MODULE_COUNT INT
	DECLARE @QUESTION_COUNT INT
	DECLARE @QUESTION_SUM INT
	DECLARE @MODULE_TYPE_COUNT INT
	DECLARE @PAPER_COLUMN_COUNT INT

	SELECT @COURSE_MASTER = ATTRIBUTE_004, @TYPE = ATTRIBUTE_003 
	, @DATE_FROM = ATTRIBUTE_006, @DATE_TO = ATTRIBUTE_007, @EXAMINER = ATTRIBUTE_008, @CENTRE = ATTRIBUTE_010
	FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 11596 AND DELETED = 'N' AND SEQ_ID = @MARKS_SHEET -- 10338988

	IF @TYPE = 'Assignment'
	BEGIN
		DECLARE @ASSIGNMENT_COLUMN_COUNT INT
		DECLARE @COURSEWORK_COUNT INT

		SET @ASSIGNMENT_COLUMN_COUNT = 2 --EXAM + NOTES

		SELECT @COURSEWORK_COUNT = COUNT(*) 
		FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_COURSEWORK WITH (NOLOCK) 
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_MODULE WITH (NOLOCK) ON (COURSE_MASTER_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MASTER_MODULE.DELETED = 'N' AND COURSE_MASTER_COURSEWORK.ATTRIBUTE_002 = COURSE_MASTER_MODULE.SEQ_ID)
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSEWORK_TYPE WITH (NOLOCK) ON (COURSEWORK_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = 9771 AND COURSEWORK_TYPE.DELETED = 'N' AND COURSE_MASTER_COURSEWORK.ATTRIBUTE_005 = COURSEWORK_TYPE.SEQ_ID)
		WHERE COURSE_MASTER_COURSEWORK.SRM_CLIENT_ENTITIES_SEQ_ID = 9786 AND COURSE_MASTER_COURSEWORK.DELETED = 'N' AND 
		COURSEWORK_TYPE.ATTRIBUTE_002 = 'Assignment' AND COURSE_MASTER_MODULE.ATTRIBUTE_002 = @COURSE_MASTER --9755403	
	
		SET @ASSIGNMENT_COLUMN_COUNT = @ASSIGNMENT_COLUMN_COUNT + @COURSEWORK_COUNT -- COURSEWORK COUNT

		SET @ASSIGNMENT_COLUMN_COUNT = @ASSIGNMENT_COLUMN_COUNT + 1 -- TOTAL COUNT
	
	
		IF @PAPER_COLUMN_COUNT != @COLUMNS_COUNT
		BEGIN
			Print 'Assignment: Columns number mismatched.'
			RETURN
		END
	
	END

	BEGIN -- Populate student for same criteria

		
		SELECT DISTINCT CAST(STUDENT.ATTRIBUTE_004 AS BIGINT) STUDENT_NUMBER
		, COURSE_REGISTRATION_COURSEWORK.ATTRIBUTE_005 COURSEWORK_NAME
		, COURSE_REGISTRATION_COURSEWORK.SEQ_ID COURSE_REGISTRATION_COURSEWORK_SEQ_ID
		, COURSE_MASTER.SEQ_ID COURSE_MASTER_SEQ_ID, COURSE_MASTER.ATTRIBUTE_001 COURSE_MASTER_NAME
		, COURSE_REGISTRATION_MODULE.ATTRIBUTE_002 COURSE_MODULES_SEQ_ID, COURSE_REGISTRATION_MODULE.ATTRIBUTE_003 COURSE_MODULE_NAME
		INTO #STUDENT_LIST_ON_CRITERIA
		FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_COURSEWORK WITH (NOLOCK) 
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_MODULE WITH (NOLOCK) ON COURSE_REGISTRATION_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 10228 AND COURSE_REGISTRATION_MODULE.DELETED = 'N' AND COURSE_REGISTRATION_COURSEWORK.ATTRIBUTE_002 = COURSE_REGISTRATION_MODULE.SEQ_ID
		LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_ELEMENT WITH (NOLOCK) ON COURSE_REGISTRATION_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10229 AND COURSE_REGISTRATION_ELEMENT.DELETED = 'N' AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_004 = COURSE_REGISTRATION_MODULE.SEQ_ID
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION WITH (NOLOCK) ON COURSE_REGISTRATION.SRM_CLIENT_ENTITIES_SEQ_ID = 10225 AND COURSE_REGISTRATION.DELETED = 'N' AND COURSE_REGISTRATION_MODULE.ATTRIBUTE_016 = COURSE_REGISTRATION.SEQ_ID
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA STUDENT WITH (NOLOCK) ON STUDENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10168 AND STUDENT.DELETED = 'N' AND COURSE_REGISTRATION.ATTRIBUTE_004 = STUDENT.SEQ_ID
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE WITH (NOLOCK) ON COURSE.SRM_CLIENT_ENTITIES_SEQ_ID = 9810 AND COURSE.DELETED = 'N' AND COURSE_REGISTRATION.ATTRIBUTE_002 = COURSE.SEQ_ID
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER WITH (NOLOCK) ON COURSE_MASTER.SRM_CLIENT_ENTITIES_SEQ_ID = 9780 AND COURSE_MASTER.DELETED = 'N' AND COURSE.ATTRIBUTE_002 = COURSE_MASTER.SEQ_ID
		LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_COURSEWORK WITH (NOLOCK) ON COURSE_COURSEWORK.SRM_CLIENT_ENTITIES_SEQ_ID = 9823 AND COURSE_COURSEWORK.DELETED = 'N' AND COURSE_REGISTRATION_COURSEWORK.ATTRIBUTE_004 = COURSE_COURSEWORK.SEQ_ID
		LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSEWORK_TYPE WITH (NOLOCK) ON COURSEWORK_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = 9771 AND COURSEWORK_TYPE.DELETED = 'N' AND COURSE_COURSEWORK.ATTRIBUTE_005 = COURSEWORK_TYPE.SEQ_ID
		WHERE COURSE_REGISTRATION_COURSEWORK.SRM_CLIENT_ENTITIES_SEQ_ID = 10230 AND COURSE_REGISTRATION_COURSEWORK.DELETED = 'N' AND COURSEWORK_TYPE.ATTRIBUTE_002 = 'Assignment'
		AND COURSE_MASTER.SEQ_ID = @COURSE_MASTER AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_018 BETWEEN @DATE_FROM AND @DATE_TO
		AND ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_010, 0) = CASE ISNULL(@EXAMINER, 0) WHEN 0 THEN ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_010, 0) ELSE @EXAMINER END
		AND ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028, 0) = CASE ISNULL(@CENTRE, 0) WHEN 0 THEN ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028, 0) ELSE @CENTRE END
		ORDER BY CAST(STUDENT.ATTRIBUTE_004 AS BIGINT)

	END

	
	BEGIN -- CREATE NEW TABLE FOR REGISTERED_ELEMENT_RESULT_DETAIL
		
		DECLARE @STUDENT_NUMBER BIGINT
		DECLARE @COL1 NVARCHAR(100),@COL2 NVARCHAR(100),@COL3 NVARCHAR(100)
		DECLARE @FOUND CHAR(1)
		DECLARE @CourseWork NVARCHAR(100)
		DECLARE @QUESTION_MARKS MONEY
		DECLARE @COURSE_REGISTRATION_COURSEWORK_SEQ_ID BIGINT
		DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT

		SET @FOUND = 'N'

		--DELETED EXISTING DATA FROM CALCULATE_RESULT_ON_IMPORT_DATA ENTITY
		UPDATE [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA SET DELETED = 'Y', DATE_DELETED = GETDATE(), DELETED_BY = 'Import Process' WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 11619
		AND ATTRIBUTE_002 = 'Assignment' AND ISNULL(DELETED, 'N') != 'Y'

		PRINT 'CREATE TABLE START'
		CREATE TABLE #TMP_IMPORT_PIVOT (COL1 NVARCHAR(500),COL2 NVARCHAR(500),COL3 NVARCHAR(500))
		
		PRINT 'CREATE TABLE END'

		DECLARE curUpdateCOURSE_REGISTRATION_COURSEWORK CURSOR STATIC FOR 
		SELECT DISTINCT SLC.STUDENT_NUMBER FROM #STUDENT_LIST_ON_CRITERIA SLC-- WE NEED TO CHECK FOR THOSE STUDENTS WHICH ARE NOT AVAILABLE IN IMPORT_MARKS_SHEET_DATA
		INNER JOIN [SRM-WORKFLOW].DBO.WFL_OUTPUT IMSD WITH (NOLOCK) ON IMSD.WFL_JOBS_SEQ_ID = @WFL_JOBS_SEQ_ID AND (ISNUMERIC(IMSD.ATTRIBUTE_001) = 1 AND SLC.STUDENT_NUMBER = IMSD.ATTRIBUTE_001)
		--WHERE CAST(SLC.STUDENT_NUMBER AS NVARCHAR(100)) = '144'
   
		OPEN curUpdateCOURSE_REGISTRATION_COURSEWORK                                                             
		FETCH NEXT FROM curUpdateCOURSE_REGISTRATION_COURSEWORK INTO @STUDENT_NUMBER    

		WHILE (@@Fetch_Status = 0)       
		BEGIN   
		
			--Populating CALCULATE_RESULT_ON_IMPORT_DATA for result calculation
		
			DECLARE @m_REGISTERED_COURSEWORKS_SEQ_ID BIGINT 
			DECLARE @m_COURSE_MASTER_SEQ_ID BIGINT 
			DECLARE @m_COURSE_MASTER_NAME NVARCHAR(100) 
			DECLARE @m_COURSE_MODULES_SEQ_ID BIGINT 
			DECLARE @m_COURSE_MODULE_NAME NVARCHAR(100)
			DECLARE @m_STUDENT_NUMBER NVARCHAR(100)
			DECLARE @m_ASSIGNMENT_MARKS MONEY


			DECLARE curPopulateDataforResutlCalculation CURSOR STATIC FOR 
			SELECT MAX(COURSE_REGISTRATION_COURSEWORK_SEQ_ID), STUDENT_NUMBER
			, COURSE_MASTER_SEQ_ID, COURSE_MASTER_NAME, COURSE_MODULES_SEQ_ID, COURSE_MODULE_NAME
			FROM #STUDENT_LIST_ON_CRITERIA
			WHERE STUDENT_NUMBER = @STUDENT_NUMBER
			GROUP BY STUDENT_NUMBER, COURSE_MASTER_SEQ_ID, COURSE_MASTER_NAME, COURSE_MODULES_SEQ_ID, COURSE_MODULE_NAME
   
			OPEN curPopulateDataforResutlCalculation                                                             
			FETCH NEXT FROM curPopulateDataforResutlCalculation INTO @m_REGISTERED_COURSEWORKS_SEQ_ID, @m_STUDENT_NUMBER, @m_COURSE_MASTER_SEQ_ID, @m_COURSE_MASTER_NAME
			,@m_COURSE_MODULES_SEQ_ID ,@m_COURSE_MODULE_NAME

			WHILE (@@Fetch_Status = 0)       
			BEGIN        

				INSERT INTO [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA
				(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_001, ATTRIBUTE_002, ATTRIBUTE_003, ATTRIBUTE_004
				, ATTRIBUTE_005, ATTRIBUTE_006, ATTRIBUTE_007, ATTRIBUTE_008, ATTRIBUTE_009
				, SRM_CLIENTS_SEQ_ID, DELETED, DATE_CREATED, CREATED_BY) 
				SELECT 11619, 'Added by Import Process', 'Assignment', @m_REGISTERED_COURSEWORKS_SEQ_ID, @STUDENT_NUMBER
				 ,@m_COURSE_MASTER_SEQ_ID, @m_COURSE_MASTER_NAME, @m_COURSE_MODULES_SEQ_ID ,@m_COURSE_MODULE_NAME, @WFL_JOBS_SEQ_ID
				, 36, 'N', getdate(), 'Import Process'
	
				SET @CUS_ENTITY_DATA_SEQ_ID = SCOPE_IDENTITY() 

				exec [DBO].GET_POPULATE_PIVOT_TABLE
				@SRM_CLIENT_ENTITIES_SEQ_ID = 11619,
				@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
				@SRM_CLIENTS_SEQ_ID = 36		


				FETCH NEXT FROM curPopulateDataforResutlCalculation INTO @m_REGISTERED_COURSEWORKS_SEQ_ID, @m_STUDENT_NUMBER, @m_COURSE_MASTER_SEQ_ID, @m_COURSE_MASTER_NAME
			,@m_COURSE_MODULES_SEQ_ID ,@m_COURSE_MODULE_NAME    
			END    
   
			CLOSE curPopulateDataforResutlCalculation                           
			DEALLOCATE curPopulateDataforResutlCalculation  
		
			
			exec [dbo].[SP_TransposeRowstoColumn]  @STUDENT_NUMBER, @WFL_JOBS_SEQ_ID, @SEQIDS


			DECLARE curPivot CURSOR STATIC FOR 
			SELECT COL1, COL2, COL3 FROM #TMP_IMPORT_PIVOT WHERE COL2 != 'TOTAL'
   
			OPEN curPivot                                                             
			FETCH NEXT FROM curPivot INTO @COL1,@COL2,@COL3    

			WHILE (@@Fetch_Status = 0)       
			BEGIN        
	
				IF ISNULL(@COL1, '')  != '' OR @FOUND = 'Y'
				BEGIN		
					
					SET @FOUND = 'Y'

					SET @CourseWork = @COL2
					SET @QUESTION_MARKS = @COL3

					IF ISNULL(@QUESTION_MARKS, '') = ''
						SET @QUESTION_MARKS = 0


					IF ISNULL(@COL1, '') = '' AND @COL2 = 'Total'
						SET @FOUND = 'N'
			

					IF ISNULL(@CourseWork, '') != ''
					BEGIN
						SET @COURSE_REGISTRATION_COURSEWORK_SEQ_ID = 0
						SELECT @COURSE_REGISTRATION_COURSEWORK_SEQ_ID = COURSE_REGISTRATION_COURSEWORK_SEQ_ID FROM #STUDENT_LIST_ON_CRITERIA WHERE STUDENT_NUMBER = @STUDENT_NUMBER AND 
						COURSEWORK_NAME = @CourseWork 

						IF ISNULL(@COURSE_REGISTRATION_COURSEWORK_SEQ_ID, 0) > 0 --and isnull(@QUESTION_MARKS,0) > 0
						BEGIN
							SELECT @m_ASSIGNMENT_MARKS = CAST(ATTRIBUTE_006 AS MONEY) FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 10230 AND SEQ_ID = @COURSE_REGISTRATION_COURSEWORK_SEQ_ID

							PRINT '@m_ASSIGNMENT_MARKS: ' + CAST(@m_ASSIGNMENT_MARKS AS NVARCHAR(100))
							IF @m_ASSIGNMENT_MARKS = 0
							BEGIN
								PRINT '@m_ASSIGNMENT_MARKS = 0'
								UPDATE [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA SET ATTRIBUTE_010 = '0.00',
								ATTRIBUTE_009 = '0.00', 
								DATE_MODIFIED = GETDATE(), MODIFIED_BY = 'Import Process'
								WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 10230 AND SEQ_ID = @COURSE_REGISTRATION_COURSEWORK_SEQ_ID
							END
							ELSE
							BEGIN
								PRINT '@m_ASSIGNMENT_MARKS != 0'
								PRINT @COURSE_REGISTRATION_COURSEWORK_SEQ_ID
								UPDATE [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA SET ATTRIBUTE_010 = @QUESTION_MARKS,
								ATTRIBUTE_009 = cast(cast(ATTRIBUTE_008 as money)*(@QUESTION_MARKS/cast(ATTRIBUTE_006 as money)) as numeric(9,2)), 
								DATE_MODIFIED = GETDATE(), MODIFIED_BY = 'Import Process'
								WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 10230 AND SEQ_ID = @COURSE_REGISTRATION_COURSEWORK_SEQ_ID
							END

							exec [DBO].GET_POPULATE_PIVOT_TABLE
							@SRM_CLIENT_ENTITIES_SEQ_ID = 10230,
							@CUS_ENTITY_DATA_SEQ_ID = @COURSE_REGISTRATION_COURSEWORK_SEQ_ID,
							@SRM_CLIENTS_SEQ_ID = 36
						END
					END
				END

				FETCH NEXT FROM curPivot INTO @COL1,@COL2,@COL3
			END    
   
			CLOSE curPivot                           
			DEALLOCATE curPivot  


			FETCH NEXT FROM curUpdateCOURSE_REGISTRATION_COURSEWORK INTO @STUDENT_NUMBER    
		END    
   
		CLOSE curUpdateCOURSE_REGISTRATION_COURSEWORK                           
		DEALLOCATE curUpdateCOURSE_REGISTRATION_COURSEWORK  
		

	END	

END



;





-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_UPDATE_REGISTERED_ELEMENT_RESULT_DETAIL] 
	-- Add the parameters for the stored procedure here	
	@COLUMNS_COUNT INT = 0,
	@MARKS_SHEET BIGINT = 0,
	@WFL_JOBS_SEQ_ID BIGINT = 0,
	@SEQIDS NVARCHAR(MAX)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	print @COLUMNS_COUNT
	print @MARKS_SHEET
	print @WFL_JOBS_SEQ_ID
	print @SEQIDS

	DECLARE @COURSE_MASTER BIGINT
	DECLARE @TYPE NVARCHAR(50)
	DECLARE @MODE NVARCHAR(50)
	DECLARE @DATE_FROM DATE
	DECLARE @DATE_TO DATE
	DECLARE @EXAMINER BIGINT
	DECLARE @CENTRE BIGINT

	DECLARE @MODULE_COUNT INT
	DECLARE @QUESTION_COUNT INT
	DECLARE @QUESTION_SUM INT
	DECLARE @MODULE_TYPE_COUNT INT

		
	SELECT @COURSE_MASTER = ATTRIBUTE_004, @TYPE = ATTRIBUTE_003 
	, @DATE_FROM = ATTRIBUTE_006, @DATE_TO = ATTRIBUTE_007, @EXAMINER = ATTRIBUTE_008, @CENTRE = ATTRIBUTE_010
	FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 11596 AND DELETED = 'N' AND SEQ_ID = @MARKS_SHEET -- 10338988

	IF @TYPE = 'PAPER'
	BEGIN -- GET COUNT FROM DB
		--COURSE_MASTER_MODULE
		SELECT @MODULE_COUNT = COUNT(*) FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA WITH (NOLOCK) WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND DELETED = 'N' AND ATTRIBUTE_002 = @COURSE_MASTER --9755403
	
		--COURSE_MASTER_ELEMENT	Total Questions
		SELECT @QUESTION_SUM = SUM(CAST(ISNULL(COURSE_MASTER_ELEMENT.ATTRIBUTE_009,0) AS BIGINT)) 
		FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_ELEMENT WITH (NOLOCK) 
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_MODULE WITH (NOLOCK) ON (COURSE_MASTER_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MASTER_MODULE.DELETED = 'N' AND COURSE_MASTER_ELEMENT.ATTRIBUTE_002 = COURSE_MASTER_MODULE.SEQ_ID)
		WHERE COURSE_MASTER_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 9784 AND COURSE_MASTER_ELEMENT.DELETED = 'N' AND COURSE_MASTER_MODULE.ATTRIBUTE_002 = @COURSE_MASTER --9755403	

		--COURSE_MASTER_ELEMENT Number of questions
		SELECT @QUESTION_COUNT = COUNT(*) 
		FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_ELEMENT WITH (NOLOCK) 
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER_MODULE WITH (NOLOCK) ON (COURSE_MASTER_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MASTER_MODULE.DELETED = 'N' AND COURSE_MASTER_ELEMENT.ATTRIBUTE_002 = COURSE_MASTER_MODULE.SEQ_ID)
		WHERE COURSE_MASTER_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 9784 AND COURSE_MASTER_ELEMENT.DELETED = 'N' AND COURSE_MASTER_MODULE.ATTRIBUTE_002 = @COURSE_MASTER --9755403
	
		--COURSE_MASTER_MODULE	
		SELECT @MODULE_TYPE_COUNT = COUNT(*) FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MAST_MODULE WITH (NOLOCK) 
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA MODULE_TYPE WITH (NOLOCK) ON (MODULE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID = 9770 AND MODULE_TYPE.DELETED = 'N' AND COURSE_MAST_MODULE.ATTRIBUTE_004 = MODULE_TYPE.SEQ_ID)
		WHERE COURSE_MAST_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 9783 AND COURSE_MAST_MODULE.DELETED = 'N' AND COURSE_MAST_MODULE.ATTRIBUTE_002 = @COURSE_MASTER --9755403
		
	
		BEGIN -- ADDING COLUMN TO TEMP TABLE

			DECLARE @PAPER_COLUMN_COUNT INT
			DECLARE @INSERT_COLUMN_COUNT INT
			SET @PAPER_COLUMN_COUNT = 1 -- EXAM_NUMBER
			SET @PAPER_COLUMN_COUNT = @PAPER_COLUMN_COUNT + @MODULE_COUNT -- MODULE
			SET @PAPER_COLUMN_COUNT = @PAPER_COLUMN_COUNT + 1 --NOTES
			SET @INSERT_COLUMN_COUNT = @PAPER_COLUMN_COUNT + 1
			SET @PAPER_COLUMN_COUNT = @PAPER_COLUMN_COUNT + @QUESTION_COUNT + @QUESTION_SUM -- NO OF QUESTION + SUM OF QUESTION
			SET @PAPER_COLUMN_COUNT = @PAPER_COLUMN_COUNT + 2 --FINAL TOTAL + CENTRE
			SET @PAPER_COLUMN_COUNT = @PAPER_COLUMN_COUNT + @MODULE_TYPE_COUNT -- MODULE TYPE COUNT
			SET @PAPER_COLUMN_COUNT = @PAPER_COLUMN_COUNT + 2 --DPFR + WRONG STONE
	
		END
		print @PAPER_COLUMN_COUNT
		IF @PAPER_COLUMN_COUNT != @COLUMNS_COUNT
		BEGIN
			Print 'Paper: Columns number mismatched.'
			RETURN
		END
	END

	BEGIN -- Populate student for same criteria

		
		SELECT DISTINCT CAST(STUDENT.ATTRIBUTE_004 AS BIGINT) STUDENT_NUMBER
		, REGISTERED_ELEMENT_RESULT_DETAIL.SEQ_ID REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID
		, REGISTERED_ELEMENT_RESULT.SEQ_ID REGISTERED_ELEMENT_RESULT_SEQ_ID
		, REGISTERED_ELEMENT_RESULT_DETAIL.ATTRIBUTE_008 QUESTION_NUMBER
		, ELEMENT.ATTRIBUTE_004 ELEMENT_ID
		, COURSE_MASTER.SEQ_ID COURSE_MASTER_SEQ_ID, COURSE_MASTER.ATTRIBUTE_001 COURSE_MASTER_NAME
		, COURSE_REGISTRATION_MODULE.ATTRIBUTE_002 COURSE_MODULES_SEQ_ID, COURSE_REGISTRATION_MODULE.ATTRIBUTE_003 COURSE_MODULE_NAME
		, COURSE_REGISTRATION_ELEMENT.SEQ_ID COURSE_REGISTRATION_ELEMENT_SEQ_ID
		INTO #STUDENT_LIST_ON_CRITERIA
		FROM [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_ELEMENT WITH (NOLOCK)
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION_MODULE WITH (NOLOCK) ON COURSE_REGISTRATION_MODULE.SRM_CLIENT_ENTITIES_SEQ_ID = 10228 AND COURSE_REGISTRATION_MODULE.DELETED = 'N' AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_004 = COURSE_REGISTRATION_MODULE.SEQ_ID
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_REGISTRATION WITH (NOLOCK) ON COURSE_REGISTRATION.SRM_CLIENT_ENTITIES_SEQ_ID = 10225 AND COURSE_REGISTRATION.DELETED = 'N' AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_002 = COURSE_REGISTRATION.SEQ_ID
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA STUDENT WITH (NOLOCK) ON STUDENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10168 AND STUDENT.DELETED = 'N' AND COURSE_REGISTRATION.ATTRIBUTE_004 = STUDENT.SEQ_ID
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE WITH (NOLOCK) ON COURSE.SRM_CLIENT_ENTITIES_SEQ_ID = 9810 AND COURSE.DELETED = 'N' AND COURSE_REGISTRATION.ATTRIBUTE_002 = COURSE.SEQ_ID
		INNER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA COURSE_MASTER WITH (NOLOCK) ON COURSE_MASTER.SRM_CLIENT_ENTITIES_SEQ_ID = 9780 AND COURSE_MASTER.DELETED = 'N' AND COURSE.ATTRIBUTE_002 = COURSE_MASTER.SEQ_ID
		LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA REGISTERED_ELEMENT_RESULT WITH (NOLOCK) ON REGISTERED_ELEMENT_RESULT.SRM_CLIENT_ENTITIES_SEQ_ID = 10233 AND REGISTERED_ELEMENT_RESULT.DELETED = 'N' AND COURSE_REGISTRATION_ELEMENT.SEQ_ID = REGISTERED_ELEMENT_RESULT.ATTRIBUTE_004
		LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA REGISTERED_ELEMENT_RESULT_DETAIL WITH (NOLOCK) ON REGISTERED_ELEMENT_RESULT_DETAIL.SRM_CLIENT_ENTITIES_SEQ_ID = 10234 AND REGISTERED_ELEMENT_RESULT_DETAIL.DELETED = 'N' AND 
		COURSE_REGISTRATION_ELEMENT.SEQ_ID = REGISTERED_ELEMENT_RESULT_DETAIL.ATTRIBUTE_004 AND REGISTERED_ELEMENT_RESULT.SEQ_ID = REGISTERED_ELEMENT_RESULT_DETAIL.ATTRIBUTE_002
		LEFT OUTER JOIN [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA ELEMENT WITH (NOLOCK) ON ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 9821 AND ELEMENT.DELETED = 'N' AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_006 = ELEMENT.SEQ_ID
		WHERE COURSE_REGISTRATION_ELEMENT.SRM_CLIENT_ENTITIES_SEQ_ID = 10229 AND COURSE_REGISTRATION_ELEMENT.DELETED = 'N'
		AND COURSE_MASTER.SEQ_ID = @COURSE_MASTER AND COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_018 BETWEEN @DATE_FROM AND @DATE_TO
		AND ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_010, 0) = CASE ISNULL(@EXAMINER, 0) WHEN 0 THEN ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_010, 0) ELSE @EXAMINER END
		AND ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028, 0) = CASE ISNULL(@CENTRE, 0) WHEN 0 THEN ISNULL(COURSE_REGISTRATION_ELEMENT.ATTRIBUTE_028, 0) ELSE @CENTRE END
		ORDER BY CAST(STUDENT.ATTRIBUTE_004 AS BIGINT)
	END

	--SELECT * FROM #STUDENT_LIST_ON_CRITERIA
	--ALTER TABLE ##IMPORT_MARKS_SHEET_DATA ADD ID BIGINT IDENTITY (1,1)
	--SELECT * FROM ##IMPORT_MARKS_SHEET_DATA
	
	BEGIN -- CREATE NEW TABLE FOR REGISTERED_ELEMENT_RESULT_DETAIL
		
		DECLARE @STUDENT_NUMBER BIGINT
		DECLARE @COL1 NVARCHAR(100),@COL2 NVARCHAR(100),@COL3 NVARCHAR(100),@MODULE NVARCHAR(100),@ELEMENT NVARCHAR(100)
		DECLARE @FOUND CHAR(1)
		DECLARE @QUESTION_NUMBER NVARCHAR(10)
		DECLARE @QUESTION_MARKS MONEY
		DECLARE @REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID BIGINT
		DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT
		DECLARE @NUMBER_OF_WRONG_STONES INT
		DECLARE @COURSE_MODULES_SEQ_ID BIGINT

		SET @FOUND = 'N'

		--DELETED EXISTING DATA FROM CALCULATE_RESULT_ON_IMPORT_DATA ENTITY
		UPDATE [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA SET DELETED = 'Y', DATE_DELETED = GETDATE(), DELETED_BY = 'Import Process' WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 11619
		AND ATTRIBUTE_002 = 'Paper' AND ISNULL(DELETED, 'N') != 'Y'
	
		PRINT 'CREATE TABLE START'
		CREATE TABLE #TMP_IMPORT_PIVOT (COL1 NVARCHAR(500),COL2 NVARCHAR(500),COL3 NVARCHAR(500))
		
		PRINT 'CREATE TABLE END'
		
		DECLARE curUpdateREGISTERED_ELEMENT_RESULT_DETAIL CURSOR STATIC FOR 
		SELECT DISTINCT SLC.STUDENT_NUMBER FROM #STUDENT_LIST_ON_CRITERIA SLC-- WE NEED TO CHECK FOR THOSE STUDENTS WHICH ARE NOT AVAILABLE IN IMPORT_MARKS_SHEET_DATA
		INNER JOIN [SRM-WORKFLOW].DBO.WFL_OUTPUT IMSD WITH (NOLOCK) ON IMSD.WFL_JOBS_SEQ_ID = @WFL_JOBS_SEQ_ID AND (ISNUMERIC(IMSD.ATTRIBUTE_001) = 1 AND SLC.STUDENT_NUMBER = IMSD.ATTRIBUTE_001)
		--WHERE CAST(SLC.STUDENT_NUMBER AS NVARCHAR(100)) = '144'
   
		OPEN curUpdateREGISTERED_ELEMENT_RESULT_DETAIL                                                             
		FETCH NEXT FROM curUpdateREGISTERED_ELEMENT_RESULT_DETAIL INTO @STUDENT_NUMBER    

		WHILE (@@Fetch_Status = 0)       
		BEGIN        
			PRINT 'IN curUpdateREGISTERED_ELEMENT_RESULT_DETAIL CUROSOR'
			--Populating CALCULATE_RESULT_ON_IMPORT_DATA for result calculation
		
			DECLARE @m_REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID BIGINT 
			DECLARE @m_COURSE_MASTER_SEQ_ID BIGINT 
			DECLARE @m_COURSE_MASTER_NAME NVARCHAR(100) 
			DECLARE @m_COURSE_MODULES_SEQ_ID BIGINT 
			DECLARE @m_COURSE_MODULE_NAME NVARCHAR(100)
			DECLARE @m_STUDENT_NUMBER NVARCHAR(100)
			DECLARE @m_ELEMENT_ID NVARCHAR(100)


			DECLARE curPopulateDataforResutlCalculation CURSOR STATIC FOR 
			SELECT MAX(REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID), ELEMENT_ID, STUDENT_NUMBER
			, COURSE_MASTER_SEQ_ID, COURSE_MASTER_NAME, COURSE_MODULES_SEQ_ID, COURSE_MODULE_NAME
			FROM #STUDENT_LIST_ON_CRITERIA
			WHERE STUDENT_NUMBER = @STUDENT_NUMBER
			GROUP BY ELEMENT_ID, STUDENT_NUMBER, COURSE_MASTER_SEQ_ID, COURSE_MASTER_NAME, COURSE_MODULES_SEQ_ID, COURSE_MODULE_NAME
   
			OPEN curPopulateDataforResutlCalculation                                                             
			FETCH NEXT FROM curPopulateDataforResutlCalculation INTO @m_REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID, @m_ELEMENT_ID, @m_STUDENT_NUMBER, @m_COURSE_MASTER_SEQ_ID, @m_COURSE_MASTER_NAME
			,@m_COURSE_MODULES_SEQ_ID ,@m_COURSE_MODULE_NAME

			WHILE (@@Fetch_Status = 0)       
			BEGIN        

				INSERT INTO [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA
				(SRM_CLIENT_ENTITIES_SEQ_ID, ATTRIBUTE_001, ATTRIBUTE_002, ATTRIBUTE_003, ATTRIBUTE_004
				, ATTRIBUTE_005, ATTRIBUTE_006, ATTRIBUTE_007, ATTRIBUTE_008
				, SRM_CLIENTS_SEQ_ID, DELETED, DATE_CREATED, CREATED_BY) 
				SELECT 11619, 'Added by Import Process', 'Paper', @m_REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID, @STUDENT_NUMBER
				 ,@m_COURSE_MASTER_SEQ_ID, @m_COURSE_MASTER_NAME, @m_COURSE_MODULES_SEQ_ID ,@m_COURSE_MODULE_NAME
				, 36, 'N', getdate(), 'Import Process'
	
				SET @CUS_ENTITY_DATA_SEQ_ID = SCOPE_IDENTITY() 

				IF @CUS_ENTITY_DATA_SEQ_ID > 0
				BEGIN
					exec [DBO].GET_POPULATE_PIVOT_TABLE
					@SRM_CLIENT_ENTITIES_SEQ_ID = 11619,
					@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
					@SRM_CLIENTS_SEQ_ID = 36		
				END

				FETCH NEXT FROM curPopulateDataforResutlCalculation INTO @m_REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID, @m_ELEMENT_ID, @m_STUDENT_NUMBER, @m_COURSE_MASTER_SEQ_ID, @m_COURSE_MASTER_NAME
			,@m_COURSE_MODULES_SEQ_ID ,@m_COURSE_MODULE_NAME    
			END    
   
			CLOSE curPopulateDataforResutlCalculation                           
			DEALLOCATE curPopulateDataforResutlCalculation  

			exec [dbo].[SP_TransposeRowstoColumn]  @STUDENT_NUMBER, @WFL_JOBS_SEQ_ID, @SEQIDS

			DECLARE curPivot CURSOR STATIC FOR 
			SELECT COL1, COL2, COL3 FROM #TMP_IMPORT_PIVOT
   
			OPEN curPivot                                                             
			FETCH NEXT FROM curPivot INTO @COL1,@COL2,@COL3    

			WHILE (@@Fetch_Status = 0)       
			BEGIN        
	
				--PRINT '@COL1:' + ISNULL(@COL1, '') 
				--PRINT '@COL2:' + ISNULL(@COL2, '') 
				--PRINT '@COL3:' + ISNULL(@COL3, '') 

				IF ISNULL(@COL1, '') = '' AND ISNULL(@COL2, '') = '' AND ISNULL(@COL3, '') = ''
				BREAK

				IF ISNULL(@COL1, '')  != '' OR @FOUND = 'Y'
				BEGIN
		
					IF @FOUND = 'N'
					BEGIN
						SET @MODULE = SUBSTRING(REPLACE(@COL1, 'Paper : ',''), 1, PATINDEX('% - %',REPLACE(@COL1, 'Paper : ','')))
						SET @ELEMENT = SUBSTRING(@COL1, PATINDEX('% - %',@COL1) + 3, LEN(@COL1))
					END

					SET @FOUND = 'Y'

					SET @QUESTION_NUMBER = @COL2
					SET @QUESTION_MARKS = @COL3

					IF ISNULL(@QUESTION_MARKS, '') = ''
						SET @QUESTION_MARKS = 0

					--PRINT @STUDENT_NUMBER
					--PRINT @QUESTION_NUMBER
					--PRINT @QUESTION_MARKS

					IF ISNULL(@COL1, '') = '' AND @COL2 = 'Sub Total'
						SET @FOUND = 'N'
			

					--print @MODULE
					--PRINT @ELEMENT 
		
					IF ISNUMERIC(@QUESTION_NUMBER) = 1
					BEGIN
						SELECT @REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID = REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID 
						, @COURSE_MODULES_SEQ_ID = COURSE_MODULES_SEQ_ID
						FROM #STUDENT_LIST_ON_CRITERIA WHERE STUDENT_NUMBER = @STUDENT_NUMBER AND 
						QUESTION_NUMBER = @QUESTION_NUMBER AND ELEMENT_ID = @ELEMENT

						--PRINT '@REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID ' + CAST(@REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID AS NVARCHAR(200))

						IF @REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID > 0 --AND @QUESTION_MARKS > 0
						BEGIN
							UPDATE [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA SET ATTRIBUTE_010 = @QUESTION_MARKS, DATE_MODIFIED = GETDATE(), MODIFIED_BY = 'Import Process'
							WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 10234 AND SEQ_ID = @REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID

							exec [DBO].GET_POPULATE_PIVOT_TABLE
							@SRM_CLIENT_ENTITIES_SEQ_ID = 10234,
							@CUS_ENTITY_DATA_SEQ_ID = @REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID,
							@SRM_CLIENTS_SEQ_ID = 36

							SET @REGISTERED_ELEMENT_RESULT_DETAIL_SEQ_ID = 0
						END
					END
				END

				IF ISNULL(@COL2,'') = 'Wrong Stone'
				BEGIN
					SET @NUMBER_OF_WRONG_STONES = @COL3
					
					UPDATE [SRM-CustomEntities_36].dbo.CUS_ENTITY_DATA SET ATTRIBUTE_023 = @NUMBER_OF_WRONG_STONES, DATE_MODIFIED = GETDATE(), MODIFIED_BY = 'Import Process'
					WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 10229 AND SEQ_ID IN (  
					SELECT DISTINCT COURSE_REGISTRATION_ELEMENT_SEQ_ID FROM #STUDENT_LIST_ON_CRITERIA 
					WHERE STUDENT_NUMBER = @STUDENT_NUMBER AND COURSE_MODULE_NAME LIKE '%Practical%')
				END

				FETCH NEXT FROM curPivot INTO @COL1,@COL2,@COL3
			END    
   
			CLOSE curPivot                           
			DEALLOCATE curPivot  

			




			FETCH NEXT FROM curUpdateREGISTERED_ELEMENT_RESULT_DETAIL INTO @STUDENT_NUMBER    
		END    
   
		CLOSE curUpdateREGISTERED_ELEMENT_RESULT_DETAIL                           
		DEALLOCATE curUpdateREGISTERED_ELEMENT_RESULT_DETAIL  
		

	END	

END



;






CREATE PROCEDURE [dbo].[SYS_DELETE_ENTITY_METADATA] 
	@ENTITY_SEQ_ID BIGINT,
	@CLIENT_SEQ_ID BIGINT
AS
BEGIN
	SET NOCOUNT ON

	DECLARE @CLIENT_ENTITY_SEQ_ID BIGINT

	DECLARE CUR_ENTITIES CURSOR 
	FOR SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES WHERE SEQ_ID = @ENTITY_SEQ_ID

	OPEN CUR_ENTITIES

	FETCH NEXT FROM CUR_ENTITIES INTO @ENTITY_SEQ_ID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF ISNULL(@CLIENT_SEQ_ID, 0) = 0
			DECLARE CUR_CLIENT_ENTITIES CURSOR 
			FOR SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES WHERE SRM_ENTITIES_SEQ_ID = @ENTITY_SEQ_ID
		ELSE
			DECLARE CUR_CLIENT_ENTITIES CURSOR 
			FOR SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES WHERE SRM_ENTITIES_SEQ_ID = @ENTITY_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @CLIENT_SEQ_ID
		
		OPEN CUR_CLIENT_ENTITIES

		FETCH NEXT FROM CUR_CLIENT_ENTITIES INTO @CLIENT_ENTITY_SEQ_ID

		WHILE @@FETCH_STATUS = 0
		BEGIN
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_LANGUAGE_ITEMS 
			WHERE SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 11 AND OBJECT_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID))
			OR SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 35 AND OBJECT_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEWS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID OR SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID))

			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS WHERE SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID)
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUP_DETAILS WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID)
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTE_GROUPS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEW_ATTRIBUTES WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEWS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID OR SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID)
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEW_ATTRIBUTES WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID)
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEW_BUTTONS WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEWS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID OR SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID)
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEW_BUTTONS WHERE SRM_CLIENT_ENTITY_BUTTONS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_BUTTONS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID)
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEW_DEFAULT WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEWS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID OR SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID)
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEW_CRITERIA WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEWS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID OR SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID)
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_FILTER_VIEWS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID OR SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID 
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_BUTTONS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_RELATED_LISTS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID OR SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID 
			DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_PAGE_COMPONENTS WHERE SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID 

			UPDATE SRM_CLIENT_ENTITY_ATTRIBUTES SET SRM_CLIENT_ENTITIES_SEQ_ID2 = NULL WHERE SRM_CLIENT_ENTITIES_SEQ_ID2 = @CLIENT_ENTITY_SEQ_ID

			-- CLIENT ENTITY
			--UPDATE [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES SET SRM_CLIENT_ENTITIES_SEQ_ID
			--DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES WHERE SEQ_ID = @CLIENT_ENTITY_SEQ_ID

			FETCH NEXT FROM CUR_CLIENT_ENTITIES INTO @CLIENT_ENTITY_SEQ_ID
		END
		CLOSE CUR_CLIENT_ENTITIES
		DEALLOCATE CUR_CLIENT_ENTITIES
		
		DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_LANGUAGE_ITEMS 
		WHERE SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 25 AND OBJECT_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES WHERE SEQ_ID = @ENTITY_SEQ_ID))
		OR SEQ_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_LANGUAGE_ITEMS WHERE OBJECT_TYPE = 3 AND OBJECT_ID IN (SELECT SEQ_ID FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES WHERE SRM_ENTITIES_SEQ_ID = @ENTITY_SEQ_ID))

		-- ENTITY
		DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_COMPONENTS WHERE SRM_ENTITIES_SEQ_ID = @ENTITY_SEQ_ID
		
		DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES WHERE SRM_ENTITIES_SEQ_ID = @ENTITY_SEQ_ID
		
		-- MENU
		DELETE FROM SRM_CLIENT_MODULE_MENU_ITEMS WHERE SRM_CLIENT_MENU_ITEMS_SEQ_ID IN (SELECT SEQ_ID FROM SRM_CLIENT_MENU_ITEMS WHERE SRM_MENU_ITEMS_SEQ_ID IN (SELECT SEQ_ID FROM SRM_MENU_ITEMS WHERE SRM_ENTITIES_SEQ_ID = @ENTITY_SEQ_ID))
		DELETE FROM SRM_CLIENT_MENU_ITEMS WHERE SRM_MENU_ITEMS_SEQ_ID IN (SELECT SEQ_ID FROM SRM_MENU_ITEMS WHERE SRM_ENTITIES_SEQ_ID = @ENTITY_SEQ_ID)		
		DELETE FROM SRM_MODULE_MENU_ITEMS WHERE SRM_MENU_ITEMS_SEQ_ID IN (SELECT SEQ_ID FROM SRM_MENU_ITEMS WHERE SRM_ENTITIES_SEQ_ID = @ENTITY_SEQ_ID)
		DELETE FROM SRM_MENU_ITEMS WHERE SRM_ENTITIES_SEQ_ID = @ENTITY_SEQ_ID

		--DELETE FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES WHERE SEQ_ID = @ENTITY_SEQ_ID

		FETCH NEXT FROM CUR_ENTITIES INTO @ENTITY_SEQ_ID
	END

	CLOSE CUR_ENTITIES
	DEALLOCATE CUR_ENTITIES
END



;

-- User Defined Function

CREATE function [dbo].[SpecifyLength](@DataType as varchar(100))
returns CHAR(1)
as
begin
	declare @Ret char(1);

	set @Ret= 'N'

	if @DataType = 'bigint' or @DataType = 'datetime' or @DataType = 'date' or @DataType = 'datetime' or @DataType = 'smallint' or @DataType = 'varbinary' or @DataType = 'decimal'
		set @Ret= 'N'
	else 
		set @Ret= 'Y'

   return @Ret
end

;







CREATE FUNCTION [dbo].[Split](@sText varchar(MAX), @sDelim varchar(20) = ' ')
RETURNS @retArray TABLE (idx smallint Primary Key, value nvarchar(4000))
AS
BEGIN
DECLARE @idx smallint,
	@value nvarchar(4000),
	@bcontinue bit,
	@iStrike smallint,
	@iDelimlength tinyint

IF @sDelim = 'Space'
	BEGIN
	SET @sDelim = ' '
	END

SET @idx = 0
SET @sText = LTrim(RTrim(@sText))
SET @iDelimlength = LEN(@sDelim)
SET @bcontinue = 1

IF NOT ((@iDelimlength = 0) or (@sDelim = 'Empty'))
	BEGIN
	WHILE @bcontinue = 1
		BEGIN

--If you can find the delimiter in the text, retrieve the first element and
--insert it with its index into the return table.
 
		IF CHARINDEX(@sDelim, @sText)>0
			BEGIN
			SET @value = SUBSTRING(@sText,1, CHARINDEX(@sDelim,@sText)-1)
				BEGIN
				INSERT @retArray (idx, value)
				VALUES (@idx, @value)
				END
			
--Trim the element and its delimiter from the front of the string.
			--Increment the index and loop.
SET @iStrike = LEN(@value) + @iDelimlength
			SET @idx = @idx + 1
			SET @sText = LTrim(Right(@sText,LEN(@sText) - @iStrike))
		
			END
		ELSE
			BEGIN
--If you can’t find the delimiter in the text, @sText is the last value in
--@retArray.
 SET @value = @sText
				BEGIN
				INSERT @retArray (idx, value)
				VALUES (@idx, @value)
				END
			--Exit the WHILE loop.
SET @bcontinue = 0
			END
		END
	END
ELSE
	BEGIN
	WHILE @bcontinue=1
		BEGIN
		--If the delimiter is an empty string, check for remaining text
		--instead of a delimiter. Insert the first character into the
		--retArray table. Trim the character from the front of the string.
--Increment the index and loop.
		IF LEN(@sText)>1
			BEGIN
			SET @value = SUBSTRING(@sText,1,1)
				BEGIN
				INSERT @retArray (idx, value)
				VALUES (@idx, @value)
				END
			SET @idx = @idx+1
			SET @sText = SUBSTRING(@sText,2,LEN(@sText)-1)
			
			END
		ELSE
			BEGIN
			--One character remains.
			--Insert the character, and exit the WHILE loop.
			INSERT @retArray (idx, value)
			VALUES (@idx, @sText)
			SET @bcontinue = 0	
			END
	END

END

RETURN
END








;




