CREATE PROCEDURE [dbo].[TRIGGER_MOVE_TO_FULL_INVOICE]
	 @RECORD_ID BIGINT,
	 @ERROR VARCHAR(MAX) = NULL OUTPUT

AS
--IF ( @@SERVERNAME = 'DSVR021112')
--	RETURN;

PRINT 'CALLING THE WEB SERVICE WITH PARAMS FOR INVOICE CREDIT'
----------------------------------------------------------------------------------------------------------------------------

DECLARE @DETAIL_RECORD_ID BIGINT, @OOMI_SEQ_ID VARCHAR(MAX),@ACCOUNT_NAME VARCHAR(MAX),@ACCOUNT VARCHAR(MAX),@CONTACT VARCHAR(MAX),@CONTACT_NAME VARCHAR(MAX),@DATE_CREATED VARCHAR(MAX),@CREATED_BY VARCHAR(MAX),
@TRANSACTION_ID VARCHAR(MAX),@REMARKS VARCHAR(MAX),@BATCH_TOTAL_AMOUNT VARCHAR(MAX), @COUNTRY VARCHAR(MAX) , @COUNTRY_NAME VARCHAR(MAX) ,
@COUNTY VARCHAR(MAX) ,	 @COUNTY_NAME VARCHAR(MAX) , @VAT_AREA VARCHAR(MAX)  ,	 @BILLING_COUNTRY VARCHAR(MAX) , @BILLING_COUNTRY_NAME VARCHAR(MAX) , @BILLING_COUNTY VARCHAR(MAX) ,
@BILLING_COUNTY_NAME VARCHAR(MAX) , @BILLING_VAT_AREA VARCHAR(MAX),@TRANSACTION_DATE VARCHAR(MAX),@TRANSACTION_DUE_DATE VARCHAR(MAX),@CUSTOMER_ORDER_NO  VARCHAR(MAX) = null,
@DELIVERY_NAME  VARCHAR(MAX) ,	 @DELIVERY_JOB_TITLE  VARCHAR(MAX) ,	 @DELIVERY_ORG_NAME  VARCHAR(MAX) ,	 @DELIVERY_DEPARTMENT  VARCHAR(MAX) ,	 @DELIVERY_ADD_LINE_1  VARCHAR(MAX) ,
@DELIVERY_ADD_LINE_2  VARCHAR(MAX),@DELIVERY_ADD_LINE_3  VARCHAR(MAX),@DELIVERY_ADD_LINE_4 VARCHAR(MAX),@DELIVERY_TOWN VARCHAR(MAX),@DELIVERY_POST_CODE VARCHAR(MAX) ,
@BILLING_NAME  VARCHAR(MAX), @BILLING_JOB_TITLE  VARCHAR(MAX),@BILLING_ORG_NAME  VARCHAR(MAX),@BILLING_DEPARTMENT  VARCHAR(MAX),@BILLING_ADD_LINE_1  VARCHAR(MAX),
@BILLING_ADD_LINE_2  VARCHAR(MAX),@BILLING_ADD_LINE_3  VARCHAR(MAX),@BILLING_ADD_LINE_4  VARCHAR(MAX),@BILLING_TOWN  VARCHAR(MAX), @BILLING_POST_CODE  VARCHAR(MAX),  	
