@BALANCE  VARCHAR(MAX) = null, @INVOICE_STATUS  VARCHAR(MAX) = null, @TRANSACTION_TYPE VARCHAR(MAX),@TRANSACTION_TYPE_NAME VARCHAR(MAX),
