CREATE PROCEDURE [dbo].[TRIGGER_NEW_ACCOUNT_REPLICATE_TO_UMBRACO]
	 @RECORD_ID BIGINT,
	 @ERROR VARCHAR(MAX) = NULL OUTPUT
AS

PRINT 'CALLING THE WEB SERVICE WITH PARAMS'

DECLARE 
 @LOGIN_USER_NAME	VARCHAR(MAX)
,@DELETED			VARCHAR(1)
,@MODE				VARCHAR(4)
,@USE_RDS VARCHAR(1)='N'


SELECT @USE_RDS =   ISNULL(Attribute_033,'N')
FROM [SRM-CustomEntities]..CUS_ENTITY_DATA WITH(NOLOCK)
WHERE SEQ_ID = 192599179 
AND SRM_CLIENT_ENTITIES_SEQ_ID = 9987

IF ISNULL(@USE_RDS,'N')='Y'
BEGIN
		RETURN
END
ELSE
BEGIN

				SET @MODE = 'Live'

				SELECT @LOGIN_USER_NAME = ISNULL(ATTRIBUTE_011,'') , @DELETED = ISNULL(DELETED,'N') FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WITH(NOLOCK) WHERE SEQ_ID = @RECORD_ID

				IF ISNULL(@DELETED,'N')='N'
					SET @LOGIN_USER_NAME = ''

				DECLARE @OBJ INT, @VALUE INT,@hr2 INT, @len INT, @SURL VARCHAR(max),@vStatusText varchar(8000), @status varchar(8000),@response varchar(8000),@hr INT,@src varchar(255),@desc varchar(255)
				--IF ( @@SERVERNAME = 'DSVR021112')

				IF @MODE='TEST'
					set @sURL = 'http://test-dp.nialexisplatform.org/Home/UpdateMember?ID=' + Convert(varchar(50),@RECORD_ID)
				ELSE
					set @sURL = 'http://dp.nialexisplatform.org/Home/UpdateMember?ID=' + Convert(varchar(50),@RECORD_ID)


				set @sURL = @sURL  + '&Email='+ Convert(VARCHAR(MAX),@LOGIN_USER_NAME)


				print '------------@sURL'
				print @sURL
				EXEC sp_OACreate 'MSXML2.ServerXMLHTTP', @obj OUT
				--select @obj
				EXEC @hr2 =sp_OAMethod @obj, 'Open',Null, 'GET',@sURL, false
				--SELECT @hr2
				exec @hr2 = sp_OAMethod @obj, 'setRequestHeader', NULL, 'Content-Type','application/x-www-form-urlencoded'
				--SELECT @hr2
				EXEC @hr2 =sp_OAMethod @obj, 'send', NULL, ''
				--SELECT @hr2
				exec @hr2 = sp_OAGetProperty @obj, 'status', @status OUT
				--SELECT @hr2 --set @len = len(@sUrl) --SELECT @LEN
				exec @hr2 = sp_OAMethod @obj, 'setRequestHeader', NULL, 'Content-Length', 200
				--SELECT @hr2
				EXEC sp_OAMethod @obj, 'StatusText', @vStatusText OUTPUT
				--select @vStatusText
				SET @response = @response
				exec @hr2 = sp_OAGetProperty @obj, 'responseText', @response OUT  

END


--IF  @RECORD_ID = 0 
--BEGIN
--	SET @ERROR = 'RECORD NOT FOUND'
