	set @sURL = 'http://3.9.25.160/eTargetNIIntegrationForTestReach.WebServices/eTargetNIIntegration.asmx/PushTrainingCenterONTestReach?Record_id=' + Convert(varchar(50),@ACCOUNT_SEQ_ID)

set @sURL = @sURL  + '&ptraining_centre_id='+ Convert(varchar(MAX),@ACCOUNT_UCN)
set @sURL = @sURL  + '&ptraining_centre_name='+ Convert(varchar(MAX),@ACCOUNT_NAME)
set @sURL = @sURL  + '&pstatus='+ Convert(varchar(MAX),@ACCOUNT_STATUS)
