set @sURL = @sURL  + '&pfirstname='+ Convert(varCHAR(MAX),@TRAINING_CENTRE_MANAGER_FIRSTNAME)
set @sURL = @sURL  + '&plastname='+ Convert(varchAR(MAX),@TRAINING_CENTRE_MANAGER_LASTNAME)
