set @sURL = @sURL  + '&porganization='+ Convert(varchar(MAX),@ORGANIZATION)
set @sURL = @sURL  + '&pemail='+ Convert(varCHAR(MAX),@TRAINING_CENTRE_MANAGER_EMAIL)
set @sURL = @sURL  + '&psend_email='+ Convert(varchaR(MAX),@SEND_EMAIL)
set @sURL = @sURL  + '&prole='+ @ROLE



print '------------@sURL'
print @sURL


EXEC sp_OACreate 'MSXML2.ServerXMLHTTP', @obj OUT
--select @obj
EXEC @hr2 =sp_OAMethod @obj, 'Open',Null, 'GET',@sURL, false
--SELECT @hr2
exec @hr2 = sp_OAMethod @obj, 'setRequestHeader', NULL, 'Content-Type','application/x-www-form-urlencoded'
--SELECT @hr2
EXEC @hr2 =sp_OAMethod @obj, 'send', NULL, ''
--SELECT @hr2
exec @hr2 = sp_OAGetProperty @obj, 'status', @status OUT
--SELECT @hr2 --set @len = len(@sUrl) --SELECT @LEN
exec @hr2 = sp_OAMethod @obj, 'setRequestHeader', NULL, 'Content-Length', 200
--SELECT @hr2
EXEC sp_OAMethod @obj, 'StatusText', @vStatusText OUTPUT
--select @vStatusText
SET @response = @response
exec @hr2 = sp_OAGetProperty @obj, 'responseText', @response OUT  

print '@response: ' + isnull(@response, '')

IF @response != ''
BEGIN

  SET @CLIENT_ENTITY_DISPLAY_NAME = 'TESTREACH_CENTER_LOG'
  SELECT @CLIENT_ENTITY_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @CLIENT_ENTITY_DISPLAY_NAME


	SET @TESTREACH_CENTRE_LOG_SEQ_ID = 0
	print @ACCOUNT_UCN

	SELECT TOP 1 @TESTREACH_CENTRE_LOG_SEQ_ID = SEQ_ID 
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SEQ_ID IN (
						SELECT CUS_ENTITY_DATA_SEQ_ID 
						FROM [SRM-DATAPIVOT_40].DBO.CUS_PIVOT_NON_UNIQUE_INDEXES 
						WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=(SELECT SEQ_ID FROM [SRM-Framework_New].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID =@CLIENT_ENTITY_SEQ_ID AND ATTRIBUTE_DISPLAY_NAME='ACCOUNT_UCN' ) 
						AND ATTRIBUTE_DECIMAL=@ACCOUNT_UCN
					)
	AND DELETED='N' 
	ORDER BY SEQ_ID DESC

	print @TESTREACH_CENTRE_LOG_SEQ_ID

	IF @TESTREACH_CENTRE_LOG_SEQ_ID != 0
	BEGIN
		UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA SET ATTRIBUTE_011 = @response, MODIFIED_BY='TESTREACH_API', DATE_MODIFIED=GETDATE() WHERE SEQ_ID=@TESTREACH_CENTRE_LOG_SEQ_ID

		exec [srm-framework_new].dbo.GET_POPULATE_PIVOT_TABLE
		@SRM_CLIENT_ENTITIES_SEQ_ID = @CLIENT_ENTITY_SEQ_ID,
		@CUS_ENTITY_DATA_SEQ_ID = @TESTREACH_CENTRE_LOG_SEQ_ID,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID
	END
END





