CREATE FUNCTION [dbo].[ToJSON]

(

      @Hierarchy JSONHierarchy READONLY

)

RETURNS NVARCHAR(MAX)--JSON documents are always unicode.

AS

BEGIN

  DECLARE

    @JSON NVARCHAR(MAX),

    @NewJSON NVARCHAR(MAX),

    @Where INT,

    @ANumber INT,

    @notNumber INT,

    @indent INT,

    @CrLf CHAR(2)--just a simple utility to save typing!

     

  --firstly get the root token into place

  SELECT @CrLf=CHAR(13)+CHAR(10),--just CHAR(10) in UNIX

         @JSON = CASE ValueType WHEN 'array' THEN '[' ELSE '{' END

            +@CrLf+ '@Object'+CONVERT(VARCHAR(5),OBJECT_ID)

            +@CrLf+CASE ValueType WHEN 'array' THEN ']' ELSE '}' END

  FROM @Hierarchy

    WHERE parent_id IS NULL AND valueType IN ('object','array') --get the root element

/* now we simply iterate from the root token growing each branch and leaf in each iteration. This won't be enormously quick, but it is simple to do. All values, or name/value pairs withing a structure can be created in one SQL Statement*/

  WHILE 1=1

    begin

    SELECT @where= PATINDEX('%[^[a-zA-Z0-9]@Object%',@json)--find NEXT token

    if @where=0 BREAK

    /* this is slightly painful. we get the indent of the object we've found by looking backwards up the string */

    SET @indent=CHARINDEX(char(10)+char(13),Reverse(LEFT(@json,@where))+char(10)+char(13))-1

    SET @NotNumber= PATINDEX('%[^0-9]%', RIGHT(@json,LEN(@JSON+'|')-@Where-8)+' ')--find NEXT token

    SET @NewJSON=NULL --this contains the structure in its JSON form

    SELECT @NewJSON=COALESCE(@NewJSON+','+@CrLf+SPACE(@indent),'')

      +COALESCE('"'+NAME+'" : ','')

      +CASE valuetype

        WHEN 'array' THEN '  ['+@CrLf+SPACE(@indent+2)

           +'@Object'+CONVERT(VARCHAR(5),OBJECT_ID)+@CrLf+SPACE(@indent+2)+']'

        WHEN 'object' then '  {'+@CrLf+SPACE(@indent+2)

           +'@Object'+CONVERT(VARCHAR(5),OBJECT_ID)+@CrLf+SPACE(@indent+2)+'}'

        WHEN 'string' THEN '"'+dbo.JSONEscaped(StringValue)+'"'

        ELSE StringValue

       END

     FROM @Hierarchy WHERE parent_id= SUBSTRING(@JSON,@where+8, @Notnumber-1)

     /* basically, we just lookup the structure based on the ID that is appended to the @Object token. Simple eh? */

    --now we replace the token with the structure, maybe with more tokens in it.

    Select @JSON=STUFF (@JSON, @where+1, 8+@NotNumber-1, @NewJSON)

    end

  return @JSON

end;

CREATE FUNCTION [dbo].[ToXML]

(

/*this function converts a JSONhierarchy table into an XML document. This uses the same technique as the toJSON function, and uses the 'entities' form of XML syntax to give a compact rendering of the structure */

      @Hierarchy JSONHierarchy READONLY

)

RETURNS NVARCHAR(MAX)--use unicode.

AS

BEGIN

  DECLARE

    @XMLAsString NVARCHAR(MAX),

    @NewXML NVARCHAR(MAX),

    @Entities NVARCHAR(MAX),

    @Objects NVARCHAR(MAX),

    @Name NVARCHAR(200),

    @Where INT,

    @ANumber INT,

    @notNumber INT,

    @indent INT,

    @CrLf CHAR(2)--just a simple utility to save typing!

     

  --firstly get the root token into place

  --firstly get the root token into place

  SELECT @CrLf=CHAR(13)+CHAR(10),--just CHAR(10) in UNIX

         @XMLasString ='<?xml version="1.0" ?>

@Object'+CONVERT(VARCHAR(5),OBJECT_ID)+'

'

    FROM @hierarchy

    WHERE parent_id IS NULL AND valueType IN ('object','array') --get the root element

/* now we simply iterate from the root token growing each branch and leaf in each iteration. This won't be enormously quick, but it is simple to do. All values, or name/value pairs within a structure can be created in one SQL Statement*/

  WHILE 1=1

    begin

    SELECT @where= PATINDEX('%[^a-zA-Z0-9]@Object%',@XMLAsString)--find NEXT token

    if @where=0 BREAK

    /* this is slightly painful. we get the indent of the object we've found by looking backwards up the string */

    SET @indent=CHARINDEX(char(10)+char(13),Reverse(LEFT(@XMLasString,@where))+char(10)+char(13))-1

    SET @NotNumber= PATINDEX('%[^0-9]%', RIGHT(@XMLasString,LEN(@XMLAsString+'|')-@Where-8)+' ')--find NEXT token

    SET @Entities=NULL --this contains the structure in its XML form

    SELECT @Entities=COALESCE(@Entities+' ',' ')+NAME+'="'

     +REPLACE(REPLACE(REPLACE(StringValue, '<', '&lt;'), '&', '&amp;'),'>', '&gt;')

     + '"' 

       FROM @hierarchy

       WHERE parent_id= SUBSTRING(@XMLasString,@where+8, @Notnumber-1)

          AND ValueType NOT IN ('array', 'object')

    SELECT @Entities=COALESCE(@entities,''),@Objects='',@name=CASE WHEN Name='-' THEN 'root' ELSE NAME end

      FROM @hierarchy

      WHERE [Object_id]= SUBSTRING(@XMLasString,@where+8, @Notnumber-1)

   

    SELECT  @Objects=@Objects+@CrLf+SPACE(@indent+2)

           +'@Object'+CONVERT(VARCHAR(5),OBJECT_ID)

           --+@CrLf+SPACE(@indent+2)+''

      FROM @hierarchy

      WHERE parent_id= SUBSTRING(@XMLasString,@where+8, @Notnumber-1)

      AND ValueType IN ('array', 'object')

    IF @Objects='' --if it is a lef, we can do a more compact rendering

         SELECT @NewXML='<'+COALESCE(@name,'item')+@entities+' />'

    ELSE

        SELECT @NewXML='<'+COALESCE(@name,'item')+@entities+'>'

            +@Objects+@CrLf++SPACE(@indent)+'</'+COALESCE(@name,'item')+'>'

     /* basically, we just lookup the structure based on the ID that is appended to the @Object token. Simple eh? */

    --now we replace the token with the structure, maybe with more tokens in it.

    Select @XMLasString=STUFF (@XMLasString, @where+1, 8+@NotNumber-1, @NewXML)

    end

  return @XMLasString

  end;






-- =============================================
-- Author:		<ASAD>
-- Create date: <11/11/2014>
-- Description:	<UPDATE CRETIFICATE TRACKING>
-- =============================================
CREATE PROCEDURE [dbo].[UPDATE CRETIFICATE TRACKING]
	 @APPLICATION_SEQ_ID BIGINT,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[UPDATE CRETIFICATE TRACKING]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[UPDATE CRETIFICATE TRACKING]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE
	--BLUE BOOK ENTITIES
	@BLUE_BOOK_PHASE_B_CLIENT_ENTITY BIGINT = 10164,
	@BLUE_BOOK_TASK_BOOK_CLIENT_ENTITY BIGINT = 10170,
	@BLUE_BOOK_PHASE_D_CLIENT_ENTITY BIGINT = 11231,
	@BLUE_BOOK_STR_CLIENT_ENTITY BIGINT = 11545,
	@BLUE_BOOK_SIGN_OFF_CLIENT_ENTITY BIGINT = 10167,

	--BLACK BOOK ENTITIES
	@BLACK_BOOK_PHASE_B_CLIENT_ENTITY BIGINT = 10177,
	@BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY BIGINT = 10185,
	@BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY BIGINT = 10179,
	@BLACK_BOOK_PHASE_D_CLIENT_ENTITY BIGINT = 10177,
	@BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY BIGINT = 11234,
	@BLACK_BOOK_STR_CLIENT_ENTITY BIGINT =11544,
	@BLACK_BOOK_SIGN_OFF_CLIENT_ENTITY BIGINT = 10178,

	--CERTIFICATE TRACKING FIELDS
	@TOTAL_PHASE_B_DAYS BIGINT = 0,
	@PHASE_B_SEA_TIME_DATE_VALID NVARCHAR(3) = 'Y',
	@TASK_DATE_WITHIN_B NVARCHAR(3) = 'N',
	@NEW_TASK_DATE_WITHIN_D NVARCHAR(3) = 'N',
	@TOTAL_PHASE_D_DAYS BIGINT = 0,
	@PHASE_D_SEA_TIME_DATE_VALID NVARCHAR(3) = 'Y',
	@DP1_CLASS NVARCHAR(3) = 'N',
	@DP1_CLASS_DAYS BIGINT = 0,
	@DP2_CLASS NVARCHAR(3) = 'N',
	@DP2_CLASS_DAYS BIGINT = 0,
	@SIGNED_OFF_LAST_VESSEL NVARCHAR(3) = 'N',
	--UPGRADE
	@NEW_PHASE_D_DATA NVARCHAR(3) = 'N',
	@NEW_PHASE_D_SEA_TIME_VALID NVARCHAR(3) = 'Y',
	@TOTAL_DAYS_FOR_NEW_DP2 BIGINT = 0,
	@STR NVARCHAR(3) = 'N',
	@STR_DAYS BIGINT = 0,
	@NEW_SIGNED_OFF_LAST_VESSEL NVARCHAR(3) = 'N',

	@SRM_CLIENTS_SEQ_ID BIGINT = 40
	
	DECLARE @CERTIFICATION_CATEGORY_SEQ_ID BIGINT
	DECLARE @CATEGORY NVARCHAR(20)
	DECLARE @TEMP_BLUE_PHASE_B_DAYS BIGINT
	DECLARE @TEMP_BLACK_PHASE_B_DAYS BIGINT
	DECLARE @TEMP_BLUE_PHASE_D_DAYS BIGINT
	DECLARE @TEMP_BLACK_PHASE_D_DAYS BIGINT
	DECLARE @TEMP_BLUE_DP1_DAYS BIGINT = 0
	DECLARE @TEMP_BLACK_DP1_DAYS BIGINT = 0
	DECLARE @TEMP_BLUE_DP2_DAYS BIGINT = 0
	DECLARE @TEMP_BLACK_DP2_DAYS BIGINT = 0
	DECLARE @TEMP_BLUE_STR_DAYS BIGINT =0
	DECLARE @TEMP_BLACK_STR_DAYS BIGINT = 0

	DECLARE @BLACK_BOOK_TASK_BOOK_SEQ_ID BIGINT
	DECLARE @BLACK_BOOK_DATE NVARCHAR(50)

	DECLARE @BLACK_TASK_BOOK_SEQ BIGINT = 0
	DECLARE @BLUE_BOOK_TASK_BOOK_SEQ_ID BIGINT
	DECLARE @BLUE_BOOK_DATE NVARCHAR(50)

	DECLARE @BLACK_BOOK_PHASE_D_SEQ_ID BIGINT
	DECLARE @BLACK_BOOK_PHASE_D_FROM_DATE NVARCHAR(50)
	DECLARE @BLACK_BOOK_PHASE_D_TO_DATE NVARCHAR(50)



	SELECT @CERTIFICATION_CATEGORY_SEQ_ID = ATTRIBUTE_007
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @APPLICATION_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID =10156

	SELECT @CATEGORY = ATTRIBUTE_006
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @CERTIFICATION_CATEGORY_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 10154

	IF (@CATEGORY = 'New' AND @APPLICATION_SEQ_ID > 0)
	BEGIN
	
		SELECT @TEMP_BLUE_PHASE_B_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_010,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_018 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_B_CLIENT_ENTITY

		SELECT @TEMP_BLACK_PHASE_B_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_010,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_015,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY

		SET @TOTAL_PHASE_B_DAYS = SUM(@TEMP_BLUE_PHASE_B_DAYS + @TEMP_BLACK_PHASE_B_DAYS) --CERTIFICATE TRACKING


	DECLARE @BLACK_BOOK_PHASE_B_SEQ_ID BIGINT
	DECLARE @BLACK_BOOK_PHASE_B_FROM_DATE NVARCHAR(50)
	DECLARE @BLACK_BOOK_PHASE_B_TO_DATE NVARCHAR(50)

	IF(EXISTS(SELECT  SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_015 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_024,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_CLIENT_ENTITY))
	BEGIN
    DECLARE CUR_BLACK_BOOK_PHASE_B CURSOR STATIC FOR

	SELECT  SEQ_ID,ATTRIBUTE_004,ATTRIBUTE_005 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_015 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_024,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_CLIENT_ENTITY

	OPEN CUR_BLACK_BOOK_PHASE_B 
	FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_B INTO @BLACK_BOOK_PHASE_B_SEQ_ID,@BLACK_BOOK_PHASE_B_FROM_DATE,@BLACK_BOOK_PHASE_B_TO_DATE
	WHILE @@FETCH_STATUS = 0
	BEGIN
		--IF DETAIL NOT EXIST THEN WHAT TO DO......
		IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_015,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND ATTRIBUTE_006 = @BLACK_BOOK_PHASE_B_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY
		AND (CAST(ISNULL(ATTRIBUTE_008,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_B_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_B_TO_DATE,'1947-01-01') AS DATE) 
		OR CAST(ISNULL(ATTRIBUTE_009,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_B_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_B_TO_DATE,'1947-01-01') AS DATE))))
	BEGIN
		SET @PHASE_B_SEA_TIME_DATE_VALID = 'N'
	END
	ELSE
		SET @PHASE_B_SEA_TIME_DATE_VALID = 'Y'

	FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_B INTO @BLACK_BOOK_PHASE_B_SEQ_ID,@BLACK_BOOK_PHASE_B_FROM_DATE,@BLACK_BOOK_PHASE_B_TO_DATE
	END

	CLOSE CUR_BLACK_BOOK_PHASE_B 
	DEALLOCATE CUR_BLACK_BOOK_PHASE_B
	END

	SELECT  @BLACK_TASK_BOOK_SEQ = SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_006 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY AND ATTRIBUTE_010 IS NOT NULL

	IF @BLACK_TASK_BOOK_SEQ > 0
	BEGIN
		DECLARE CUR_BLACK_TASK_BOOK_NEW CURSOR STATIC FOR
		SELECT  SEQ_ID,ATTRIBUTE_010 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_006 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY

		OPEN CUR_BLACK_TASK_BOOK_NEW 
		FETCH NEXT FROM CUR_BLACK_TASK_BOOK_NEW 
		INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID, @BLACK_BOOK_DATE
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
		--IF DETAIL NOT EXIST THEN WHAT TO DO......
	
			IF EXISTS (SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_015 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_024,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_004,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_005,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE))
		BEGIN
			SET @TASK_DATE_WITHIN_B = 'Y'
		END
		ELSE
		BEGIN
			IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_018 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_B_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_008,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_009,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE)))
		BEGIN	
			SET @TASK_DATE_WITHIN_B = 'Y'
		END
		ELSE
			SET @TASK_DATE_WITHIN_B = 'N'
		END
		FETCH NEXT FROM CUR_BLACK_TASK_BOOK_NEW INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID,@BLACK_BOOK_DATE
		END

		CLOSE CUR_BLACK_TASK_BOOK_NEW 
		DEALLOCATE CUR_BLACK_TASK_BOOK_NEW
	END
	ELSE
	BEGIN

		DECLARE CUR_BLUE_TASK_BOOK_NEW CURSOR STATIC FOR
		SELECT  SEQ_ID,ATTRIBUTE_014 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_023,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_TASK_BOOK_CLIENT_ENTITY

		OPEN CUR_BLUE_TASK_BOOK_NEW 
		FETCH NEXT FROM CUR_BLUE_TASK_BOOK_NEW 
		INTO @BLUE_BOOK_TASK_BOOK_SEQ_ID, @BLUE_BOOK_DATE
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
		--IF DETAIL NOT EXIST THEN WHAT TO DO......
	
			IF EXISTS (SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_015 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_024,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_004,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_005,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE))
		BEGIN
			SET @TASK_DATE_WITHIN_B = 'Y'
		END
		ELSE
		BEGIN
			IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_018 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_B_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_008,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_009,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE)))
		BEGIN	
			SET @TASK_DATE_WITHIN_B = 'Y'
		END
		ELSE
			SET @TASK_DATE_WITHIN_B = 'N'
		END
		FETCH NEXT FROM CUR_BLUE_TASK_BOOK_NEW INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID,@BLACK_BOOK_DATE
		END

		CLOSE CUR_BLUE_TASK_BOOK_NEW 
		DEALLOCATE CUR_BLUE_TASK_BOOK_NEW

	END



	SELECT @TEMP_BLUE_PHASE_D_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

	SELECT @TEMP_BLACK_PHASE_D_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

	SET @TOTAL_PHASE_D_DAYS = SUM(@TEMP_BLUE_PHASE_D_DAYS + @TEMP_BLACK_PHASE_D_DAYS)

	--CHECK CLASS DP1 AND DP2
	IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_020 LIKE '%1'
    AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY))
	BEGIN
		SET @DP1_CLASS = 'Y'
	END
	ELSE
	BEGIN
		IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_009 LIKE '%1'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY))
	BEGIN
		SET @DP1_CLASS = 'Y'

	END
	ELSE
		SET @DP1_CLASS = 'N'
	END

	IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_020 LIKE '%2'
    AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY))
	BEGIN
		SET @DP2_CLASS = 'Y'
	END
	ELSE
	BEGIN
		IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_009 LIKE '%2'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY))
	BEGIN
		SET @DP2_CLASS = 'Y'
	END
	ELSE
		SET @DP2_CLASS = 'N'
	END

	IF @DP1_CLASS = 'Y'
	BEGIN
		SELECT @TEMP_BLACK_DP1_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_020 LIKE '%1'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

		SELECT @TEMP_BLUE_DP1_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_009 LIKE '%1'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

		SET @DP1_CLASS_DAYS = SUM(@TEMP_BLACK_DP1_DAYS + @TEMP_BLUE_DP1_DAYS)
	END
	IF (@DP2_CLASS = 'Y')
	BEGIN
		SELECT @TEMP_BLACK_DP2_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_020 LIKE '%2'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

		SELECT @TEMP_BLUE_DP2_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_009 LIKE '%2'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

		SET @DP2_CLASS_DAYS = SUM(@TEMP_BLACK_DP2_DAYS + @TEMP_BLUE_DP2_DAYS)
	END

	

	IF(EXISTS(SELECT  SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY))
	BEGIN
    DECLARE CUR_BLACK_BOOK_PHASE_D CURSOR STATIC FOR

	SELECT  SEQ_ID,ATTRIBUTE_013,ATTRIBUTE_014 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY

	OPEN CUR_BLACK_BOOK_PHASE_D 
	FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_D INTO @BLACK_BOOK_PHASE_D_SEQ_ID,@BLACK_BOOK_PHASE_D_FROM_DATE,@BLACK_BOOK_PHASE_D_TO_DATE
	WHILE @@FETCH_STATUS = 0
	BEGIN
		--IF DETAIL NOT EXIST THEN WHAT TO DO......
		IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND ATTRIBUTE_011 = @BLACK_BOOK_PHASE_D_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY
		AND (CAST(ISNULL(ATTRIBUTE_006,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_D_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_D_TO_DATE,'1947-01-01') AS DATE) 
		OR CAST(ISNULL(ATTRIBUTE_007,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_D_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_D_TO_DATE,'1947-01-01') AS DATE))))
	BEGIN
		SET @PHASE_D_SEA_TIME_DATE_VALID = 'N'
	END
	ELSE
		SET @PHASE_D_SEA_TIME_DATE_VALID = 'Y'

	FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_D INTO @BLACK_BOOK_PHASE_D_SEQ_ID,@BLACK_BOOK_PHASE_D_FROM_DATE,@BLACK_BOOK_PHASE_D_TO_DATE
	END

	CLOSE CUR_BLACK_BOOK_PHASE_D 
	DEALLOCATE CUR_BLACK_BOOK_PHASE_D
	END

	IF(EXISTS(SELECT  SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_STR_CLIENT_ENTITY))
	BEGIN
	 SET @STR = 'Y'
	END
	ELSE
	BEGIN
		IF(EXISTS(SELECT  SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_STR_CLIENT_ENTITY))
	BEGIN
		SET @STR = 'N'
	END
	ELSE
		SET @STR = 'N'
	END
	
	IF (@STR = 'Y')
	BEGIN	
		SELECT @TEMP_BLUE_STR_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_022,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_STR_CLIENT_ENTITY

		SELECT @TEMP_BLACK_STR_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_019,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_STR_CLIENT_ENTITY

		SET @STR_DAYS = SUM(@TEMP_BLUE_STR_DAYS + @TEMP_BLACK_STR_DAYS)
	END


	END
	ELSE IF (@CATEGORY = 'Upgrade' AND @APPLICATION_SEQ_ID > 0)
	BEGIN
	
	SELECT  @BLACK_TASK_BOOK_SEQ = SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_006 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY AND ATTRIBUTE_010 IS NOT NULL

	IF @BLACK_TASK_BOOK_SEQ > 0
	BEGIN
		DECLARE CUR_BLACK_TASK_BOOK_UPGRADE CURSOR STATIC FOR
		SELECT  SEQ_ID,ATTRIBUTE_010 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_006 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY

		OPEN CUR_BLACK_TASK_BOOK_UPGRADE 
		FETCH NEXT FROM CUR_BLACK_TASK_BOOK_UPGRADE 
		INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID, @BLACK_BOOK_DATE
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
		--IF DETAIL NOT EXIST THEN WHAT TO DO......
	
			IF EXISTS (SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_013,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_014,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE))
		BEGIN
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
		BEGIN
			IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_010,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_011,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE)))
		BEGIN	
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
			SET @NEW_TASK_DATE_WITHIN_D = 'N'
		END
		FETCH NEXT FROM CUR_BLACK_TASK_BOOK_UPGRADE INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID,@BLACK_BOOK_DATE
		END

		CLOSE CUR_BLACK_TASK_BOOK_UPGRADE 
		DEALLOCATE CUR_BLACK_TASK_BOOK_UPGRADE
	END
	ELSE
	BEGIN
		
		DECLARE CUR_BLUE_TASK_BOOK_UPGRADE CURSOR STATIC FOR
		SELECT  SEQ_ID,ATTRIBUTE_014 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_023,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_TASK_BOOK_CLIENT_ENTITY

		OPEN CUR_BLUE_TASK_BOOK_UPGRADE 
		FETCH NEXT FROM CUR_BLUE_TASK_BOOK_UPGRADE 
		INTO @BLUE_BOOK_TASK_BOOK_SEQ_ID, @BLUE_BOOK_DATE
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
		--IF DETAIL NOT EXIST THEN WHAT TO DO......
	
			IF EXISTS (SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_013,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_014,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE))
		BEGIN
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
		BEGIN
			IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_010,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_011,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE)))
		BEGIN	
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
			SET @NEW_TASK_DATE_WITHIN_D = 'N'
		END
		FETCH NEXT FROM CUR_BLUE_TASK_BOOK_UPGRADE INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID,@BLACK_BOOK_DATE
		END

		CLOSE CUR_BLUE_TASK_BOOK_UPGRADE 
		DEALLOCATE CUR_BLUE_TASK_BOOK_UPGRADE

	END

		SELECT @TEMP_BLUE_PHASE_D_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_009 LIKE '%2'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

		SELECT @TEMP_BLACK_PHASE_D_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_020 LIKE '%2'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

		SET @TOTAL_DAYS_FOR_NEW_DP2 = SUM(@TEMP_BLUE_PHASE_D_DAYS + @TEMP_BLACK_PHASE_D_DAYS)

		IF (@TOTAL_DAYS_FOR_NEW_DP2  > 0)
		BEGIN
			SET @NEW_PHASE_D_DATA = 'Y'

			IF(EXISTS(SELECT  SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY))
			BEGIN
				DECLARE CUR_BLACK_BOOK_PHASE_D CURSOR STATIC FOR

				SELECT  SEQ_ID,ATTRIBUTE_013,ATTRIBUTE_014 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
				WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
				AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY

				OPEN CUR_BLACK_BOOK_PHASE_D 
				FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_D INTO @BLACK_BOOK_PHASE_D_SEQ_ID,@BLACK_BOOK_PHASE_D_FROM_DATE,@BLACK_BOOK_PHASE_D_TO_DATE
				WHILE @@FETCH_STATUS = 0
				BEGIN
					--IF DETAIL NOT EXIST THEN WHAT TO DO......
					IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
					WHERE ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
					AND ATTRIBUTE_011 = @BLACK_BOOK_PHASE_D_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
					AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY
					AND (CAST(ISNULL(ATTRIBUTE_006,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_D_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_D_TO_DATE,'1947-01-01') AS DATE) 
					OR CAST(ISNULL(ATTRIBUTE_007,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_D_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_D_TO_DATE,'1947-01-01') AS DATE))))
				BEGIN
					SET @PHASE_D_SEA_TIME_DATE_VALID = 'N'
				END
				ELSE
					SET @PHASE_D_SEA_TIME_DATE_VALID = 'Y'

				FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_D INTO @BLACK_BOOK_PHASE_D_SEQ_ID,@BLACK_BOOK_PHASE_D_FROM_DATE,@BLACK_BOOK_PHASE_D_TO_DATE
				END

				CLOSE CUR_BLACK_BOOK_PHASE_D 
				DEALLOCATE CUR_BLACK_BOOK_PHASE_D
			END
		END
		ELSE
			SET @NEW_PHASE_D_SEA_TIME_VALID = 'N'
END

	DECLARE @TEMP_BLUE_LEFT_DATE DATE
	DECLARE @TEMP_BLACK_LEFT_DATE DATE
	DECLARE @BLUE_D_SEQ_ID BIGINT = 0
	DECLARE @BLUE_SHIP BIGINT = 0
	DECLARE @BLACK_D_SEQ_ID BIGINT = 0
	DECLARE @BLACK_SHIP BIGINT = 0
	DECLARE @BLUE_SIGN_OFF_SEQ_ID BIGINT =0
	DECLARE @BLUE_SIGN_OFF_SHIP BIGINT = 0
	DECLARE @BLACK_SIGN_OFF_SEQ_ID BIGINT = 0
	DECLARE @BLACK_SIGN_OFF_SHIP BIGINT = 0
	DECLARE @TEMP_SIGN_OFF_FLAG NVARCHAR(3) = 'N'


	SELECT @TEMP_BLUE_LEFT_DATE = MAX(CAST(ISNULL(ATTRIBUTE_011,'0001-01-01') AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY


	SELECT @TEMP_BLACK_LEFT_DATE = MAX(CAST(ISNULL(ATTRIBUTE_014,'0001-01-01') AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY

	IF (@TEMP_BLUE_LEFT_DATE != CAST('0001-01-01' AS DATE) AND @TEMP_BLUE_LEFT_DATE > @TEMP_BLACK_LEFT_DATE)
	BEGIN

		SELECT @BLUE_D_SEQ_ID = SEQ_ID ,@BLUE_SHIP = ISNULL(ATTRIBUTE_006,0)
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY
		AND CAST(ISNULL(ATTRIBUTE_011,'0002-01-01') AS DATE) = @TEMP_BLUE_LEFT_DATE

	END
	ELSE IF (@TEMP_BLACK_LEFT_DATE != CAST('0001-01-01' AS DATE) AND @TEMP_BLACK_LEFT_DATE >= @TEMP_BLUE_LEFT_DATE)
	BEGIN

		SELECT @BLACK_D_SEQ_ID = SEQ_ID ,@BLACK_SHIP = ISNULL(ATTRIBUTE_006,0)
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
		AND CAST(ISNULL(ATTRIBUTE_014,'0002-01-01') AS DATE) = @TEMP_BLACK_LEFT_DATE
	END
	ELSE
	BEGIN
	SET @TEMP_SIGN_OFF_FLAG = 'N'
	END

		SELECT @BLUE_SIGN_OFF_SEQ_ID = SEQ_ID ,@BLUE_SIGN_OFF_SHIP = ISNULL(ATTRIBUTE_014,0)
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_SIGN_OFF_CLIENT_ENTITY

	IF (@BLUE_D_SEQ_ID > 0 AND @BLUE_SIGN_OFF_SEQ_ID > 0 AND @BLUE_SHIP > 0 AND @BLUE_SHIP = @BLUE_SIGN_OFF_SHIP)
	BEGIN
		SET @TEMP_SIGN_OFF_FLAG = 'Y'
	END
	ELSE IF(@BLACK_D_SEQ_ID > 0 AND @BLUE_SIGN_OFF_SEQ_ID > 0 AND @BLACK_SHIP > 0 AND @BLACK_SHIP = @BLUE_SIGN_OFF_SHIP)
	BEGIN
		SET @TEMP_SIGN_OFF_FLAG = 'Y'
	END
	ELSE
	BEGIN
		SELECT @BLACK_SIGN_OFF_SEQ_ID = SEQ_ID ,@BLACK_SIGN_OFF_SHIP = ISNULL(ATTRIBUTE_027,0)
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_020,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_SIGN_OFF_CLIENT_ENTITY

		IF (@BLUE_D_SEQ_ID > 0 AND @BLACK_SIGN_OFF_SEQ_ID > 0 AND @BLUE_SHIP > 0 AND @BLUE_SHIP = @BLACK_SIGN_OFF_SHIP)
		BEGIN
			SET @TEMP_SIGN_OFF_FLAG = 'Y'
		END
		ELSE IF(@BLACK_D_SEQ_ID > 0 AND @BLACK_SIGN_OFF_SEQ_ID > 0 AND @BLACK_SHIP > 0 AND @BLACK_SHIP = @BLACK_SIGN_OFF_SHIP)
		BEGIN
			SET @TEMP_SIGN_OFF_FLAG = 'Y'
		END
		ELSE
			SET @TEMP_SIGN_OFF_FLAG = 'N'
	END
	IF (@CATEGORY = 'New' AND @APPLICATION_SEQ_ID > 0)
		SET @SIGNED_OFF_LAST_VESSEL = @TEMP_SIGN_OFF_FLAG
	IF (@CATEGORY = 'Upgrade' AND @APPLICATION_SEQ_ID > 0)
		SET @SIGNED_OFF_LAST_VESSEL = @TEMP_SIGN_OFF_FLAG
	
	DECLARE @TRACKING_SEQ_ID BIGINT  = 0
	SELECT @TRACKING_SEQ_ID = SEQ_ID 
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID  AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 11604

	IF (@TRACKING_SEQ_ID > 0)
	BEGIN
		UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		SET
				ATTRIBUTE_011 = @PHASE_B_SEA_TIME_DATE_VALID,   
				ATTRIBUTE_036 = @TOTAL_PHASE_B_DAYS, 
				ATTRIBUTE_015 = @TASK_DATE_WITHIN_B,
				ATTRIBUTE_029 = @NEW_TASK_DATE_WITHIN_D,
				ATTRIBUTE_037 = @TOTAL_PHASE_D_DAYS,
				ATTRIBUTE_012 = @PHASE_D_SEA_TIME_DATE_VALID,
				ATTRIBUTE_019 = @DP1_CLASS,
				ATTRIBUTE_025 = @DP1_CLASS_DAYS,
				ATTRIBUTE_020 = @DP2_CLASS,
				ATTRIBUTE_022 = @DP2_CLASS_DAYS,
				ATTRIBUTE_026 = @NEW_PHASE_D_DATA,
				ATTRIBUTE_031 = @NEW_PHASE_D_SEA_TIME_VALID,
				ATTRIBUTE_027 = @TOTAL_DAYS_FOR_NEW_DP2,
				ATTRIBUTE_038 = @STR,
				ATTRIBUTE_039 = @STR_DAYS,
				ATTRIBUTE_041 = @NEW_SIGNED_OFF_LAST_VESSEL,
				ATTRIBUTE_040 = @SIGNED_OFF_LAST_VESSEL			
		WHERE  SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID= 11604

		EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
			@SRM_CLIENT_ENTITIES_SEQ_ID = 11604,
			@CUS_ENTITY_DATA_SEQ_ID = @TRACKING_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END
END






;


-- *****************************************************************************************************************
-- Created By: Adeel Hassan
-- Date Created: 22/09/2025
-- Summary: A process to update an existing Account Contact Relationship record from Contact or ACCOUNT API for selected Sections' fields only
--******************************************************************************************************************

CREATE PROCEDURE [dbo].[UPDATE_ACCOUNT_CONTACT_RELATIONSHIP_FROM_API]
	@p_CONTACT_RECORD_ID BIGINT,		-- SEQ_ID OF API_CONTACT
	@p_ACCOUNT_RECORD_ID BIGINT,		-- SEQ_ID OF API_ACCOUNT
	@p_MEMBER_RECORD_ID BIGINT,			-- SEQ_ID of API_ADD_MEMBER
	@p_ACCOUNT_CONTACT_RELATIONSHIP_RECORD_ID BIGINT, -- SEQ_ID of ACR
	@p_USER_EMAIL NVARCHAR(200)			-- EMAIL OF oomi USER
AS
BEGIN


	DECLARE @p_CLIENT_ID BIGINT
	DECLARE @API_CONTACT_SEQ_ID BIGINT
	DECLARE @API_ACCOUNT_SEQ_ID BIGINT
	DECLARE @API_ADD_MEMBER_SEQ_ID BIGINT
		
	
	IF @p_CONTACT_RECORD_ID > 0 
		SET @API_CONTACT_SEQ_ID = @p_CONTACT_RECORD_ID
	ELSE IF @p_ACCOUNT_RECORD_ID > 0
		SET @API_ACCOUNT_SEQ_ID = @p_ACCOUNT_RECORD_ID
	ELSE IF @p_MEMBER_RECORD_ID > 0
		SET @API_ADD_MEMBER_SEQ_ID = @p_MEMBER_RECORD_ID

	DECLARE @API_CONTACT_ENTITY_SEQ_ID BIGINT
	DECLARE @CONTACT_ENTITY_SEQ_ID BIGINT	
	DECLARE @API_ACCOUNT_ENTITY_SEQ_ID BIGINT
	DECLARE @ACCOUNT_ENTITY_SEQ_ID BIGINT
	DECLARE @ACCOUNT_CONTACT_RELATIONSHIP_ENTITY_SEQ_ID BIGINT
	DECLARE @API_ADD_MEMBER_ENTITY_SEQ_ID BIGINT
	
	DECLARE @WEB_SECTION_ENTITY_SEQ_ID BIGINT
	DECLARE @WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID BIGINT
	DECLARE @WEB_SECTION_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @WEB_SECTION_ATTRIBUTE_SEQ_ID2 BIGINT
	DECLARE @WEB_API_FIELDS_CAPTION NVARCHAR(4000)

	DECLARE @strSections NVARCHAR(4000)
	DECLARE @strSQL NVARCHAR(max)
	DECLARE @strSOURCE_ATTRIBUTE_SYSTEM_NAME NVARCHAR(100)
	DECLARE @strDESTINATION_ATTRIBUTE_SYSTEM_NAME NVARCHAR(100)

	SET @API_CONTACT_ENTITY_SEQ_ID = 112942
	SET @CONTACT_ENTITY_SEQ_ID = 112718
	SET @API_ACCOUNT_ENTITY_SEQ_ID = 112943
	SET @ACCOUNT_ENTITY_SEQ_ID = 112715
	SET @API_ADD_MEMBER_ENTITY_SEQ_ID = 112953
	SET @ACCOUNT_CONTACT_RELATIONSHIP_ENTITY_SEQ_ID = 112723
	SET @WEB_SECTION_ENTITY_SEQ_ID = 112922
	SET @WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID = 112934
	SET @WEB_SECTION_ATTRIBUTE_SEQ_ID = 3065767
	SET @WEB_SECTION_ATTRIBUTE_SEQ_ID2 = 3065824


	-- Temporary Table to hold data from CustomEntities of relevant Client - to be used in the Dynamic Statement
	CREATE TABLE #TEMP_QRY
	(SECTIONS NVARCHAR(4000),
	WEB_API_FIELDS_CAPTION NVARCHAR(4000));

	-- Table Variable to hold Web Section ID and Web Section Name
	CREATE TABLE #Temp_SECTIONS  
	(SECTION_ID INT,
	SECTION_NAME NVARCHAR(250) 
	);

	-- Table Variable to hold Section Name, API Caption along with Source and Destination ATTRIBUTES Number
	CREATE TABLE #Temp_SECTION_FIELDS 
	(SECTION_ID INT, 
	SECTION_NAME NVARCHAR(250) , 
	API_CAPTION NVARCHAR(250) ,
	SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT,
	SOURCE_ATTRIBUTE_SYSTEM_NAME NVARCHAR(250) ,
	DESTINATION_ATTRIBUTE_SYSTEM_NAME NVARCHAR(250) 
	);
	
	-- Get Client ID on the basis of User Email
	SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USER_EMAIL
	
	IF @p_CONTACT_RECORD_ID > 0 
	BEGIN
		-- Get All Sections (from Section Name field) and Contact SEQ ID from the API CONTACT entity & Add them into Temp Table
		SET @strSQL = 'INSERT INTO #TEMP_QRY (SECTIONS, WEB_API_FIELDS_CAPTION) SELECT ATTRIBUTE_003, ATTRIBUTE_117 FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA WITH (NOLOCK) 
		WHERE SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SEQ_ID = ' + CAST(@API_CONTACT_SEQ_ID AS NVARCHAR(100))
		PRINT @strSQL
		EXECUTE (@strSQL)

		-- Assign Sections and Contact SEQ ID to the relevant variables for further processing
		SELECT @strSections = SECTIONS, @WEB_API_FIELDS_CAPTION = WEB_API_FIELDS_CAPTION FROM #TEMP_QRY

	END
	ELSE IF @p_ACCOUNT_RECORD_ID > 0
	BEGIN
		-- Get All Sections (from Section Name field) and Account SEQ ID from the API ACCOUNT entity & Add them into Temp Table
		SET @strSQL = 'INSERT INTO #TEMP_QRY (SECTIONS, WEB_API_FIELDS_CAPTION) SELECT ATTRIBUTE_003, ATTRIBUTE_068 FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA WITH (NOLOCK) 
		WHERE SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SEQ_ID = ' + CAST(@API_ACCOUNT_SEQ_ID AS NVARCHAR(100))
		PRINT @strSQL
		EXECUTE (@strSQL)

		-- Assign Sections and Account SEQ ID to the relevant variables for further processing
		SELECT @strSections = SECTIONS, @WEB_API_FIELDS_CAPTION = WEB_API_FIELDS_CAPTION FROM #TEMP_QRY
	END
	ELSE IF @p_MEMBER_RECORD_ID > 0
	BEGIN
		-- Get All Sections (from Section Name field) and Account SEQ ID from the API ACCOUNT entity & Add them into Temp Table
		SET @strSQL = 'INSERT INTO #TEMP_QRY (SECTIONS, WEB_API_FIELDS_CAPTION) SELECT ATTRIBUTE_135, ATTRIBUTE_150 FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA WITH (NOLOCK) 
		WHERE SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_ADD_MEMBER_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SEQ_ID = ' + CAST(@API_ADD_MEMBER_SEQ_ID AS NVARCHAR(100))
		PRINT @strSQL
		EXECUTE (@strSQL)

		-- Assign Sections and Account SEQ ID to the relevant variables for further processing
		SELECT @strSections = SECTIONS, @WEB_API_FIELDS_CAPTION = WEB_API_FIELDS_CAPTION FROM #TEMP_QRY
	END

	PRINT  @strSections
	SELECT * FROM #TEMP_QRY

	IF(ISNULL(@WEB_API_FIELDS_CAPTION, '') != '')
		BEGIN	
		
			INSERT INTO #Temp_SECTION_FIELDS (API_CAPTION)
			SELECT LTRIM(RTRIM(VALUE)) FROM [SRM-FRAMEWORK_NEW].dbo.fn_split (@WEB_API_FIELDS_CAPTION, '|') WHERE LTRIM(RTRIM(value)) <> ''
			AND LTRIM(RTRIM(value)) NOT IN ('MainAccount','MainContact');
		
			SELECT * FROM #Temp_SECTION_FIELDS ORDER BY API_CAPTION
		END
	ELSE
		BEGIN

			-- Split the Sections variable on the basis of | sign and add the data into @temp_sections table variable
			INSERT INTO #Temp_SECTIONS (SECTION_NAME)
			SELECT VALUE FROM [SRM-FRAMEWORK_NEW].dbo.fn_split (@strSections, '|')

			-- Update Section ID 
			SET @strSQL = 'UPDATE #Temp_SECTIONS SET SECTION_ID = SEQ_ID FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA 
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@WEB_SECTION_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND LTRIM(RTRIM(ATTRIBUTE_001)) COLLATE SQL_Latin1_General_CP1_CI_AS = LTRIM(RTRIM(SECTION_NAME))'
			PRINT @strSQL
			EXECUTE (@strSQL)
	
			--SELECT * FROM #Temp_SECTIONS

			-- Add Section Name and API Caption in Temp Setion Fields table from CustomEntities of relevant database
			SET @strSQL = 'INSERT INTO #Temp_SECTION_FIELDS (SECTION_ID, SECTION_NAME, API_CAPTION)
			SELECT DISTINCT T.SECTION_ID, T.SECTION_NAME, C.ATTRIBUTE_066 FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C, 
			[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I,  #Temp_SECTIONS T,
			[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I2
			WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID AS NVARCHAR(100)) +
			' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
			CAST(@WEB_SECTION_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = T.SECTION_ID AND C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID 
			AND I2.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
			CAST(@WEB_SECTION_ATTRIBUTE_SEQ_ID2 AS NVARCHAR(100)) + ' AND I2.ATTRIBUTE_STRING = ''ACCOUNT_CONTACT_RELATIONSHIP'' AND C.SEQ_ID = I2.CUS_ENTITY_DATA_SEQ_ID '
			PRINT @strSQL
			EXECUTE (@strSQL)

			SELECT * FROM #Temp_SECTION_FIELDS
		END

	IF EXISTS (SELECT * FROM #Temp_SECTION_FIELDS)
	BEGIN
		IF @p_CONTACT_RECORD_ID > 0 
		BEGIN
			-- Update Attribute Number of Source field from API Contact in the Temp Setion Fields table
			UPDATE T 
			SET T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
			FROM #Temp_SECTION_FIELDS T
			INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
			INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
			WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @API_CONTACT_ENTITY_SEQ_ID
		END
		ELSE IF @p_ACCOUNT_RECORD_ID > 0 
		BEGIN
			-- Update Attribute Number of Source field fromn API Account in the Temp Setion Fields table
			UPDATE T 
			SET T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
			FROM #Temp_SECTION_FIELDS T
			INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
			INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
			WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @API_ACCOUNT_ENTITY_SEQ_ID
		END
		ELSE IF @p_MEMBER_RECORD_ID > 0 
		BEGIN
			-- Update Attribute Number of Source field fromn API Add Member in the Temp Setion Fields table
			UPDATE T 
			SET T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
			FROM #Temp_SECTION_FIELDS T
			INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
			INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
			WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @API_ADD_MEMBER_ENTITY_SEQ_ID
		END

		-- Insert API Caption of the Description Field of all relevant Lookups 
		INSERT INTO #Temp_SECTION_FIELDS (SECTION_ID, SECTION_NAME, API_CAPTION)
		SELECT T.SECTION_ID, T.SECTION_NAME, SCEA.ATTRIBUTE_API_CAPTION
		FROM #Temp_SECTION_FIELDS T 
		INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SEQ_ID
		WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 IS NOT NULL

		IF @p_CONTACT_RECORD_ID > 0 
		BEGIN
			-- Update Attribute Number of Source field from API Contact in the Temp Setion Fields table
			UPDATE T 
			SET T.SOURCE_ATTRIBUTE_SYSTEM_NAME = SEA.SYSTEM_NAME, T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
			FROM #Temp_SECTION_FIELDS T
			INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
			INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
			WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @API_CONTACT_ENTITY_SEQ_ID

			-- Update Attribute Number of Destination field in the Temp Setion Fields table
			UPDATE T 
			SET T.DESTINATION_ATTRIBUTE_SYSTEM_NAME = SEA.SYSTEM_NAME 
			FROM #Temp_SECTION_FIELDS T 
			INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
			INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
			WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @ACCOUNT_CONTACT_RELATIONSHIP_ENTITY_SEQ_ID
		END
		ELSE IF @p_ACCOUNT_RECORD_ID > 0 
		BEGIN
			-- Update Attribute Number of Source field from API Account in the Temp Setion Fields table
			UPDATE T 
			SET T.SOURCE_ATTRIBUTE_SYSTEM_NAME = SEA.SYSTEM_NAME, T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
			FROM #Temp_SECTION_FIELDS T
			INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
			INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
			WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @API_ACCOUNT_ENTITY_SEQ_ID

			-- Update Attribute Number of Destination field in the Temp Setion Fields table
			UPDATE T 
			SET T.DESTINATION_ATTRIBUTE_SYSTEM_NAME = SEA.SYSTEM_NAME 
			FROM #Temp_SECTION_FIELDS T 
			INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
			INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
			WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @ACCOUNT_CONTACT_RELATIONSHIP_ENTITY_SEQ_ID
		END
		ELSE IF @p_MEMBER_RECORD_ID > 0 
		BEGIN
			-- Update Attribute Number of Source field from API Account in the Temp Setion Fields table
			UPDATE T 
			SET T.SOURCE_ATTRIBUTE_SYSTEM_NAME = SEA.SYSTEM_NAME, T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
			FROM #Temp_SECTION_FIELDS T
			INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
			INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
			WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @API_ADD_MEMBER_ENTITY_SEQ_ID

			-- Update Attribute Number of Destination field in the Temp Setion Fields table
			UPDATE T 
			SET T.DESTINATION_ATTRIBUTE_SYSTEM_NAME = SEA.SYSTEM_NAME 
			FROM #Temp_SECTION_FIELDS T 
			INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
			INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
			WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @ACCOUNT_CONTACT_RELATIONSHIP_ENTITY_SEQ_ID
		END

		-- Following statement is used just to show the data in this temp table
		SELECT * FROM #Temp_SECTION_FIELDS ORDER BY SOURCE_ATTRIBUTE_SYSTEM_NAME

		-- Create Dynamic Update Statement to update all fields of relevant Sections from Source Custom Entity (i.e API_Contact) to Destination Custom Entity (i.e. Contact)
		SET @strSQL = 'UPDATE DEST SET '
		DECLARE curField CURSOR FOR
		SELECT SOURCE_ATTRIBUTE_SYSTEM_NAME, DESTINATION_ATTRIBUTE_SYSTEM_NAME FROM #Temp_SECTION_FIELDS
		WHERE DESTINATION_ATTRIBUTE_SYSTEM_NAME IS NOT NULL AND SOURCE_ATTRIBUTE_SYSTEM_NAME != 'SEQ_ID'
		ORDER BY SOURCE_ATTRIBUTE_SYSTEM_NAME

		OPEN curField
		FETCH curField INTO @strSOURCE_ATTRIBUTE_SYSTEM_NAME, @strDESTINATION_ATTRIBUTE_SYSTEM_NAME

		WHILE (@@FETCH_STATUS = 0)
		BEGIN
			IF @strSQL != 'UPDATE DEST SET ' 
				SET @strSQL = @strSQL + ', '

			SET @strSQL = @strSQL + 'DEST.' + @strDESTINATION_ATTRIBUTE_SYSTEM_NAME + ' = SOURCE.'+ @strSOURCE_ATTRIBUTE_SYSTEM_NAME

			FETCH curField INTO @strSOURCE_ATTRIBUTE_SYSTEM_NAME, @strDESTINATION_ATTRIBUTE_SYSTEM_NAME
		END
	
		CLOSE curField
		DEALLOCATE curField

		SET @strSQL = @strSQL + ' FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA DEST, [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA SOURCE '
		SET @strSQL = @strSQL + ' WHERE DEST.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@ACCOUNT_CONTACT_RELATIONSHIP_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND DEST.SEQ_ID = ' + CAST(@p_ACCOUNT_CONTACT_RELATIONSHIP_RECORD_ID AS NVARCHAR(100))
		IF @p_CONTACT_RECORD_ID > 0 		
			SET @strSQL = @strSQL + ' AND SOURCE.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SOURCE.SEQ_ID = ' + CAST(@API_CONTACT_SEQ_ID AS NVARCHAR(100))
		ELSE IF @p_ACCOUNT_RECORD_ID > 0 
			SET @strSQL = @strSQL + ' AND SOURCE.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SOURCE.SEQ_ID = ' + CAST(@API_ACCOUNT_SEQ_ID AS NVARCHAR(100))
		ELSE IF @p_MEMBER_RECORD_ID > 0 
			SET @strSQL = @strSQL + ' AND SOURCE.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_ADD_MEMBER_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SOURCE.SEQ_ID = ' + CAST(@API_ADD_MEMBER_SEQ_ID AS NVARCHAR(100))
	
		-- execute the dynamic statement fo update the details of the Contact record
		PRINT @strSQL
		EXEC (@strSQL)


		-- Create Dynamic Update Statement to update data in the Pivot table
		SET @strSQL = 'EXEC [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+'].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN] '
		SET @strSQL = @strSQL + ' @SRM_CLIENTS_SEQ_ID = ' +  CAST(@p_CLIENT_ID AS NVARCHAR(100))
		SET @strSQL = @strSQL + ', @SRM_CLIENT_ENTITIES_SEQ_ID = ' +  CAST(@ACCOUNT_CONTACT_RELATIONSHIP_ENTITY_SEQ_ID AS NVARCHAR(100))		
		SET @strSQL = @strSQL + ', @CUS_ENTITY_DATA_SEQ_ID = ' +  CAST(@p_ACCOUNT_CONTACT_RELATIONSHIP_RECORD_ID AS NVARCHAR(100))

		-- execute the dynamic statement for update the details of the Account Contact Relationship record in the Pivot table
		PRINT @strSQL
		EXEC (@strSQL)
	END
END

;


-- *****************************************************************************************************************
-- Created By: Adeel Hassan
-- Date Created: 23/01/2025
-- Summary: A process to update an existing Account record from Account API for selected Sections' fields only
--******************************************************************************************************************

CREATE PROCEDURE [dbo].[UPDATE_ACCOUNT_FROM_API]
	@p_RECORD_ID BIGINT,					-- SEQ_ID OF ACCOUNT
	@p_USERS_EMAIL NVARCHAR(200)			-- EMAIL OF oomi USER
AS
BEGIN

	DECLARE @p_CLIENT_ID BIGINT
	DECLARE @API_ACCOUNT_SEQ_ID BIGINT
	DECLARE @ACCOUNT_SEQ_ID BIGINT
	SET @API_ACCOUNT_SEQ_ID = @p_RECORD_ID

	DECLARE @API_ACCOUNT_ENTITY_SEQ_ID BIGINT
	DECLARE @ACCOUNT_ENTITY_SEQ_ID BIGINT
	DECLARE @WEB_SECTION_ENTITY_SEQ_ID BIGINT
	DECLARE @WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID BIGINT
	DECLARE @WEB_SECTION_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @WEB_SECTION_ATTRIBUTE_SEQ_ID2 BIGINT
	DECLARE @WEB_API_FIELDS_CAPTION NVARCHAR(4000)

	DECLARE @strSections NVARCHAR(4000)
	DECLARE @strSQL NVARCHAR(max)
	DECLARE @strSOURCE_ATTRIBUTE_SYSTEM_NAME NVARCHAR(100)
	DECLARE @strDESTINATION_ATTRIBUTE_SYSTEM_NAME NVARCHAR(100)

	SET @API_ACCOUNT_ENTITY_SEQ_ID = 112943
	SET @ACCOUNT_ENTITY_SEQ_ID = 112715
	SET @WEB_SECTION_ENTITY_SEQ_ID = 112922
	SET @WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID = 112934
	SET @WEB_SECTION_ATTRIBUTE_SEQ_ID = 3065767
	SET @WEB_SECTION_ATTRIBUTE_SEQ_ID2 = 3065824

	-- Temporary Table to hold data from CustomEntities of relevant Client - to be used in the Dynamic Statement
	CREATE TABLE #TEMP_QRY
	(SECTIONS NVARCHAR(4000),
	ACCOUNT_SEQ_ID BIGINT,
	WEB_API_FIELDS_CAPTION NVARCHAR(4000));

	-- Table Variable to hold Web Section ID and Web Section Name
	CREATE TABLE #Temp_SECTIONS  
	(SECTION_ID INT,
	SECTION_NAME NVARCHAR(250) 
	);

	-- Table Variable to hold Section Name, API Caption along with Source and Destination ATTRIBUTES Number
	CREATE TABLE #Temp_SECTION_FIELDS 
	(SECTION_ID INT, 
	SECTION_NAME NVARCHAR(250) , 
	API_CAPTION NVARCHAR(250) ,
	SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT,
	SOURCE_ATTRIBUTE_SYSTEM_NAME NVARCHAR(250) ,
	DESTINATION_ATTRIBUTE_SYSTEM_NAME NVARCHAR(250) 
	);

	-- Get Client ID on the basis of User Email
	SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USERS_EMAIL

	-- Get All Sections (from Section Name field) and Account SEQ ID from the API Account entity & Add them into Temp Table
	SET @strSQL = 'INSERT INTO #TEMP_QRY (SECTIONS, ACCOUNT_SEQ_ID, WEB_API_FIELDS_CAPTION) SELECT ATTRIBUTE_003, ATTRIBUTE_004, ATTRIBUTE_068 FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA WITH (NOLOCK) 
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SEQ_ID = ' + CAST(@API_ACCOUNT_SEQ_ID AS NVARCHAR(100))
	EXECUTE (@strSQL)

	SELECT * FROM #TEMP_QRY

	-- Assign Sections and Account SEQ ID to the relevant variables for further processing
	SELECT @strSections = SECTIONS, @ACCOUNT_SEQ_ID = ACCOUNT_SEQ_ID, @WEB_API_FIELDS_CAPTION = WEB_API_FIELDS_CAPTION FROM #TEMP_QRY

	PRINT  @strSections
	PRINT @ACCOUNT_SEQ_ID

	IF(ISNULL(@WEB_API_FIELDS_CAPTION, '') != '')
		BEGIN
			INSERT INTO #Temp_SECTION_FIELDS (API_CAPTION)
			SELECT LTRIM(RTRIM(VALUE)) FROM [SRM-FRAMEWORK_NEW].dbo.fn_split (@WEB_API_FIELDS_CAPTION, '|') WHERE LTRIM(RTRIM(value)) <> '';
		
			SELECT * FROM #Temp_SECTION_FIELDS ORDER BY API_CAPTION
		END

	ELSE
		BEGIN
		-- Split the Sections variable on the basis of | sign and add the data into @temp_sections table variable
			INSERT INTO #Temp_SECTIONS (SECTION_NAME)
			SELECT VALUE FROM [SRM-FRAMEWORK_NEW].dbo.fn_split (@strSections, '|')

	

		-- Update Section ID 
			SET @strSQL = 'UPDATE #Temp_SECTIONS SET SECTION_ID = SEQ_ID FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA 
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@WEB_SECTION_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND LTRIM(RTRIM(ATTRIBUTE_001)) COLLATE SQL_Latin1_General_CP1_CI_AS = LTRIM(RTRIM(SECTION_NAME))'
			PRINT @strSQL
			EXECUTE (@strSQL)
	
		--SELECT * FROM #Temp_SECTIONS
		-- Add Section Name and API Caption in Temp Setion Fields table from CustomEntities of relevant database
			SET @strSQL = 'INSERT INTO #Temp_SECTION_FIELDS (SECTION_ID, SECTION_NAME, API_CAPTION)
			SELECT DISTINCT T.SECTION_ID, T.SECTION_NAME, C.ATTRIBUTE_066 FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C, 
			[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I,  #Temp_SECTIONS T, 
			[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I2 
			WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID AS NVARCHAR(100)) +
			' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
			CAST(@WEB_SECTION_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = T.SECTION_ID AND C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID 
			  AND I2.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
			CAST(@WEB_SECTION_ATTRIBUTE_SEQ_ID2 AS NVARCHAR(100)) + ' AND I2.ATTRIBUTE_STRING = ''ACCOUNT'' AND C.SEQ_ID = I2.CUS_ENTITY_DATA_SEQ_ID '
			PRINT @strSQL
			EXECUTE (@strSQL)

		END

	-- Update Attribute Number of Source field in the Temp Setion Fields table
	UPDATE T 
	SET T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
	FROM #Temp_SECTION_FIELDS T
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
	INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
	WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @API_ACCOUNT_ENTITY_SEQ_ID

	-- Insert API Caption of the Description Field of all relevant Lookups 
	INSERT INTO #Temp_SECTION_FIELDS (SECTION_ID, SECTION_NAME, API_CAPTION)
	SELECT T.SECTION_ID, T.SECTION_NAME, SCEA.ATTRIBUTE_API_CAPTION
	FROM #Temp_SECTION_FIELDS T 
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SEQ_ID
	WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 IS NOT NULL

		-- Update Attribute Number of Source field in the Temp Setion Fields table 
	UPDATE T 
	SET T.SOURCE_ATTRIBUTE_SYSTEM_NAME = SEA.SYSTEM_NAME, T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
	FROM #Temp_SECTION_FIELDS T
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
	INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
	WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @API_ACCOUNT_ENTITY_SEQ_ID

	-- Update Attribute Number of Destination field in the Temp Setion Fields table
	UPDATE T 
	SET T.DESTINATION_ATTRIBUTE_SYSTEM_NAME = SEA.SYSTEM_NAME 
	FROM #Temp_SECTION_FIELDS T 
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
	INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
	WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @ACCOUNT_ENTITY_SEQ_ID

	-- Following statement is used just to show the data in this temp table
	 SELECT * FROM #Temp_SECTION_FIELDS ORDER BY SOURCE_ATTRIBUTE_SYSTEM_NAME

	-- Create Dynamic Update Statement to update all fields of relevant Sections from Source Custom Entity (i.e API_Account) to Destination Custom Entity (i.e. Account)
	SET @strSQL = 'UPDATE DEST SET '

	DECLARE curField CURSOR FOR
	SELECT SOURCE_ATTRIBUTE_SYSTEM_NAME, DESTINATION_ATTRIBUTE_SYSTEM_NAME FROM #Temp_SECTION_FIELDS
	WHERE DESTINATION_ATTRIBUTE_SYSTEM_NAME IS NOT NULL AND SOURCE_ATTRIBUTE_SYSTEM_NAME IS NOT NULL
	ORDER BY SOURCE_ATTRIBUTE_SYSTEM_NAME

	OPEN curField
	FETCH curField INTO @strSOURCE_ATTRIBUTE_SYSTEM_NAME, @strDESTINATION_ATTRIBUTE_SYSTEM_NAME

	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		IF @strSQL != 'UPDATE DEST SET ' 
			SET @strSQL = @strSQL + ', '

		SET @strSQL = @strSQL + 'DEST.' + @strDESTINATION_ATTRIBUTE_SYSTEM_NAME + ' = SOURCE.'+ @strSOURCE_ATTRIBUTE_SYSTEM_NAME

		FETCH curField INTO @strSOURCE_ATTRIBUTE_SYSTEM_NAME, @strDESTINATION_ATTRIBUTE_SYSTEM_NAME
	END
	
	CLOSE curField
	DEALLOCATE curField

	SET @strSQL = @strSQL + ' FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA DEST, [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA SOURCE '
	SET @strSQL = @strSQL + ' WHERE DEST.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND DEST.SEQ_ID = ' + CAST(@ACCOUNT_SEQ_ID AS NVARCHAR(100))
	SET @strSQL = @strSQL + ' AND SOURCE.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SOURCE.SEQ_ID = ' + CAST(@API_ACCOUNT_SEQ_ID AS NVARCHAR(100))

	-- execute the dynamic statement fo update the details of the Account record
	PRINT @strSQL
	EXEC (@strSQL)


	-- Create Dynamic Update Statement to update data in the Pivot table
	SET @strSQL = '[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+'].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN] '
	SET @strSQL = @strSQL + '@SRM_CLIENT_ENTITIES_SEQ_ID = ' +  CAST(@ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100))
	SET @strSQL = @strSQL + ', @SRM_CLIENTS_SEQ_ID = ' +  CAST(@p_CLIENT_ID AS NVARCHAR(100))
	SET @strSQL = @strSQL + ', @CUS_ENTITY_DATA_SEQ_ID = ' +  CAST(@ACCOUNT_SEQ_ID AS NVARCHAR(100))

	-- execute the dynamic statement fo update the details of the Account record in the Pivot table
	PRINT @strSQL
	EXEC (@strSQL)

	
	-- Create dynamic statement to update Populate Main Account flag in the API Account
	IF EXISTS (SELECT API_CAPTION, SOURCE_ATTRIBUTE_SYSTEM_NAME FROM #Temp_SECTION_FIELDS WHERE API_CAPTION IN ('PrimaryEmail', 'MainContact'))
	BEGIN
		SET @strSQL = 'UPDATE [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA SET ATTRIBUTE_037 = ''Y'''	
		SET @strSQL = @strSQL + ' WHERE SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SEQ_ID = ' + CAST(@API_ACCOUNT_SEQ_ID AS NVARCHAR(100))
		
		PRINT @strSQL
		EXEC (@strSQL)

		-- Create Dynamic Update Statement to update data in the Pivot table
		SET @strSQL = '[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+'].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN] '
		SET @strSQL = @strSQL + '@SRM_CLIENT_ENTITIES_SEQ_ID = ' +  CAST(@API_ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100))
		SET @strSQL = @strSQL + ', @SRM_CLIENTS_SEQ_ID = ' +  CAST(@p_CLIENT_ID AS NVARCHAR(100))
		SET @strSQL = @strSQL + ', @CUS_ENTITY_DATA_SEQ_ID = ' +  CAST(@API_ACCOUNT_SEQ_ID AS NVARCHAR(100))
		
		EXEC (@strSQL)
	END
END;




-- ********************************************************************************************************************************
-- Created By: Nimra Azeem
-- Date Created: 13/05/2025
-- Summary: A dynamic process to update COMBINED__PROGRAMME_SETUP reference in EVENT_PROGRAMME_REGISTRATION or API_TEMP_DELEGATE
--*********************************************************************************************************************************

CREATE PROCEDURE [dbo].[UPDATE_COMBINED_PROGRAMME_REGISTRATION]
	@p_EVENT BIGINT,
	@p_EVENT_DELEGATE BIGINT,
	@p_API_TEMP_EVENT_DELEGATE BIGINT,
	@REGISTRATION_STATUS BIGINT,
	@p_USER_EMAIL NVARCHAR(200)
AS
BEGIN
	--DECLARE @p_EVENT BIGINT = 29886
	--DECLARE @p_EVENT_DELEGATE BIGINT = 0
	--DECLARE @p_API_TEMP_EVENT_DELEGATE BIGINT = 30731
	--DECLARE @REGISTRATION_STATUS BIGINT = 25170
	--DECLARE @p_USER_EMAIL NVARCHAR(200) = 'smart@oomi.co.uk'
	
	--DROP TABLE #Temp_DELEGATE_PROGRAMMES 
	--DROP TABLE #Temp_COMBINED_PROGRAMME_RATES 

	DECLARE @CLIENT_ID BIGINT
    DECLARE @strSQL NVARCHAR(1000)
    DECLARE @TEMP_PROGRAMMES NVARCHAR(1000)
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT

	DECLARE @COMBINED_PROGRAMME_SETUP BIGINT
	DECLARE @EVENT_PROGRAMME BIGINT
	
	DECLARE @EVENT_DELEGATE_ENTITY_SEQ_ID BIGINT
	DECLARE @API_TEMP_DELEGATE_ENTITY_SEQ_ID BIGINT
	DECLARE @COMBINED_PROGRAMME_RATE_ENTITY_SEQ_ID BIGINT
	DECLARE @COMBINED_PROGRAMME_SETUP_ENTITY_SEQ_ID BIGINT
	DECLARE @EVENT_PROGRAMME_REGISTRATION_SEQ_ID BIGINT

	DECLARE @EVENT_DELEGATE_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @REGISTRATION_STATUS_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @EVENT_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @REGISTRATION_COMBINED_PROGRAMME_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @REGISTRATION_COMBINED_PROGRAMME_NAME_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @TEMP_PROGRAMMES_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @TEMP_COMBINED_PROGRAMMES_ATTRIBUTE_SEQ_ID BIGINT

	SET @EVENT_DELEGATE_ENTITY_SEQ_ID = 112837
	SET @API_TEMP_DELEGATE_ENTITY_SEQ_ID = 112966
	SET @COMBINED_PROGRAMME_RATE_ENTITY_SEQ_ID = 112823
	SET @COMBINED_PROGRAMME_SETUP_ENTITY_SEQ_ID = 112822
	SET @EVENT_PROGRAMME_REGISTRATION_SEQ_ID = 112845
	SET @TEMP_PROGRAMMES_ATTRIBUTE_SEQ_ID = 3067569
	SET @TEMP_COMBINED_PROGRAMMES_ATTRIBUTE_SEQ_ID = 3067568

	SET @EVENT_DELEGATE_ATTRIBUTE_SEQ_ID = 3063391
	SET @REGISTRATION_STATUS_ATTRIBUTE_SEQ_ID = 3063388
	SET @REGISTRATION_COMBINED_PROGRAMME_ATTRIBUTE_SEQ_ID = 3067536
	SET @REGISTRATION_COMBINED_PROGRAMME_NAME_ATTRIBUTE_SEQ_ID = 3067537
	SET @EVENT_ATTRIBUTE_SEQ_ID = 3062646

	-- Table Variable to hold Event Programme from Event Programme Registration
	CREATE TABLE #Temp_DELEGATE_PROGRAMMES  
	(EVENT_PROGRAMME_REGISTRATION BIGINT,
	EVENT_PROGRAMME BIGINT,
	COMBINED_PROGRAMME_SETUP BIGINT,
	COMBINED_PROGRAMME_SETUP_NAME NVARCHAR(100)
	);

	-- Table Variable to hold Combined Programme Setup and Event Programme from Combined Programme Rate
	CREATE TABLE #Temp_COMBINED_PROGRAMME_RATES  
	(COMBINED_PROGRAMME_SETUP BIGINT,
	COMBINED_PROGRAMME_SETUP_NAME NVARCHAR(100),
	EVENT_PROGRAMME BIGINT
	);

	-- Get Client ID on the basis of User Email
	SELECT @CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USER_EMAIL
	
	-- Reset Combined Programme field in Event Registration Programmes for given delegate
	IF ISNULL(@p_API_TEMP_EVENT_DELEGATE,0) = 0 AND ISNULL(@p_EVENT_DELEGATE,0) > 0
	BEGIN
		SET @strSQL = 'UPDATE C 
		SET C.ATTRIBUTE_018 = 0 , C.ATTRIBUTE_019 = ''''
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C, 
		[SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I
		WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) +
		' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@EVENT_DELEGATE_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = ' + CAST(@p_EVENT_DELEGATE AS NVARCHAR(100)) + ' AND C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID'
	
		PRINT @strSQL
		EXECUTE (@strSQL)
		
		---Reset Pivot
				SET @strSQL = 'UPDATE P
		SET P.ATTRIBUTE_DECIMAL = 0.00
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C, 
		[SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I, 
		[SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES P
		WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' AND P.DELETED != ''Y''  AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) +
		' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@EVENT_DELEGATE_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = ' + CAST(@p_EVENT_DELEGATE AS NVARCHAR(100)) + ' AND C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID
		AND P.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) + ' AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@REGISTRATION_COMBINED_PROGRAMME_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND C.SEQ_ID = P.CUS_ENTITY_DATA_SEQ_ID'
	
	
		PRINT @strSQL
		EXECUTE (@strSQL)

		SET @strSQL = 'UPDATE P
		SET P.ATTRIBUTE_STRING = ''''
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C, 
		[SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I, 
		[SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES P
		WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' AND P.DELETED != ''Y''  AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) +
		' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@EVENT_DELEGATE_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = ' + CAST(@p_EVENT_DELEGATE AS NVARCHAR(100)) + ' AND C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID
		AND P.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) + ' AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@REGISTRATION_COMBINED_PROGRAMME_NAME_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND C.SEQ_ID = P.CUS_ENTITY_DATA_SEQ_ID'
	
		PRINT @strSQL
		EXECUTE (@strSQL)
	END
	
	-- Get All Programmes booked by the Delegate & add them into relevant Temp Table
	IF ISNULL(@p_API_TEMP_EVENT_DELEGATE,0) = 0 AND ISNULL(@p_EVENT_DELEGATE,0) > 0
	BEGIN
		SET @strSQL = 'INSERT INTO #Temp_DELEGATE_PROGRAMMES (EVENT_PROGRAMME_REGISTRATION, EVENT_PROGRAMME) 
		SELECT C.SEQ_ID, C.ATTRIBUTE_006 
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C, 
		[SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I
		WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) +
		' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@EVENT_DELEGATE_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = ' + CAST(@p_EVENT_DELEGATE AS NVARCHAR(100)) + ' AND C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID'
	
		SET @strSQL = @strSQL + ' INTERSECT 
		 SELECT C.SEQ_ID, C.ATTRIBUTE_006 
		 FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C, 
		 [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I
		 WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) +
		 ' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		 CAST(@REGISTRATION_STATUS_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = ' + CAST(@REGISTRATION_STATUS AS NVARCHAR(100)) + ' AND C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID'
	
		PRINT @strSQL
		EXECUTE (@strSQL)
	END

	IF ISNULL(@p_API_TEMP_EVENT_DELEGATE,0) > 0 AND ISNULL(@p_EVENT_DELEGATE,0) = 0
	BEGIN
		SET @strSQL = 'SELECT @OUT_TEMP_PROGRAMMES  = C.ATTRIBUTE_010
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C
		WHERE C.DELETED != ''Y'' AND C.SEQ_ID = ' + CAST(@p_API_TEMP_EVENT_DELEGATE AS NVARCHAR(100))
		PRINT @strSQL
		EXEC sp_executesql @strSQL, N'@OUT_TEMP_PROGRAMMES NVARCHAR(1000) OUTPUT', @OUT_TEMP_PROGRAMMES = @TEMP_PROGRAMMES OUTPUT;

		SET @TEMP_PROGRAMMES = LTRIM(RTRIM(LEFT(@TEMP_PROGRAMMES, LEN(@TEMP_PROGRAMMES) - 1)))
		PRINT '@TEMP_PROGRAMMES ' + @TEMP_PROGRAMMES

		SET @strSQL = 'INSERT INTO #Temp_DELEGATE_PROGRAMMES (EVENT_PROGRAMME) 
		SELECT VALUE FROM [SRM-FRAMEWORK_NEW].dbo.fn_split (@TEMP_PROGRAMMES, '','')'
		PRINT @strSQL
		EXEC sp_executesql @strSQL, N'@TEMP_PROGRAMMES NVARCHAR(1000)', @TEMP_PROGRAMMES = @TEMP_PROGRAMMES;
	END

	-- Get All Combined Programme Rates & add them into relevant Temp Table
	SET @strSQL = 'INSERT INTO #Temp_COMBINED_PROGRAMME_RATES (COMBINED_PROGRAMME_SETUP,COMBINED_PROGRAMME_SETUP_NAME, EVENT_PROGRAMME) 
	SELECT ATTRIBUTE_004, ATTRIBUTE_005,ATTRIBUTE_006 
	FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C, 
	[SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I
	WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@COMBINED_PROGRAMME_RATE_ENTITY_SEQ_ID AS NVARCHAR(100)) +
	' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@COMBINED_PROGRAMME_RATE_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
	CAST(@EVENT_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = ' + CAST(@p_EVENT AS NVARCHAR(100)) + ' AND C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID'
	
	PRINT @strSQL
	EXECUTE (@strSQL)
	
	-- Declare Cursor on Distinct COMBINED_PROGRAMME_SETUP from #Temp_COMBINED_PROGRAMME_RATES Order by Max(EVENT_PROGRAMME) Desc
	DECLARE curUpdateCombinedProgramme CURSOR LOCAL STATIC FOR
	SELECT COMBINED_PROGRAMME_SETUP
	FROM #Temp_COMBINED_PROGRAMME_RATES 
	GROUP BY COMBINED_PROGRAMME_SETUP
	ORDER BY COUNT(EVENT_PROGRAMME) DESC

	OPEN curUpdateCombinedProgramme;
	FETCH NEXT FROM curUpdateCombinedProgramme INTO @COMBINED_PROGRAMME_SETUP

	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		UPDATE B
		SET 
			B.COMBINED_PROGRAMME_SETUP = A.COMBINED_PROGRAMME_SETUP,
			B.COMBINED_PROGRAMME_SETUP_NAME = A.COMBINED_PROGRAMME_SETUP_NAME
		FROM #Temp_DELEGATE_PROGRAMMES B 
		INNER JOIN #Temp_COMBINED_PROGRAMME_RATES A ON A.EVENT_PROGRAMME = B.EVENT_PROGRAMME
		WHERE A.COMBINED_PROGRAMME_SETUP = @COMBINED_PROGRAMME_SETUP AND ISNULL(B.COMBINED_PROGRAMME_SETUP, 0)= 0
		AND NOT EXISTS (SELECT 1
			FROM #Temp_COMBINED_PROGRAMME_RATES A2
			WHERE A2.COMBINED_PROGRAMME_SETUP = @COMBINED_PROGRAMME_SETUP
			AND NOT EXISTS (SELECT 1
				FROM #Temp_DELEGATE_PROGRAMMES B2
				WHERE B2.EVENT_PROGRAMME = A2.EVENT_PROGRAMME)
						)
				
		FETCH NEXT FROM curUpdateCombinedProgramme INTO @COMBINED_PROGRAMME_SETUP
	END
	CLOSE curUpdateCombinedProgramme
	DEALLOCATE curUpdateCombinedProgramme

	--Update Combined Programme Setup in Event Programme Registrations
	IF ISNULL(@p_API_TEMP_EVENT_DELEGATE,0) = 0 AND ISNULL(@p_EVENT_DELEGATE,0) > 0
	BEGIN
		SET @strSQL = 'UPDATE C 
		SET C.ATTRIBUTE_018 = B.COMBINED_PROGRAMME_SETUP , C.ATTRIBUTE_019 = B.COMBINED_PROGRAMME_SETUP_NAME
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C
		INNER JOIN #Temp_DELEGATE_PROGRAMMES B ON B.EVENT_PROGRAMME_REGISTRATION = C.SEQ_ID
		AND ISNULL(B.COMBINED_PROGRAMME_SETUP, 0) > 0'

		PRINT @strSQL
		EXECUTE (@strSQL)

		-- Update Pivot
		SET @strSQL = 'UPDATE I
		SET I.ATTRIBUTE_DECIMAL = ISNULL(B.COMBINED_PROGRAMME_SETUP, 0)
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I
		INNER JOIN #Temp_DELEGATE_PROGRAMMES B ON B.EVENT_PROGRAMME_REGISTRATION = I.CUS_ENTITY_DATA_SEQ_ID
		WHERE I.DELETED != ''Y'' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@REGISTRATION_COMBINED_PROGRAMME_ATTRIBUTE_SEQ_ID AS NVARCHAR(100))  + ''
	
		PRINT @strSQL
		EXECUTE (@strSQL)

		SET @strSQL = 'UPDATE I
		SET I.ATTRIBUTE_STRING = ISNULL(B.COMBINED_PROGRAMME_SETUP_NAME,'''')
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I
		INNER JOIN #Temp_DELEGATE_PROGRAMMES B ON B.EVENT_PROGRAMME_REGISTRATION = I.CUS_ENTITY_DATA_SEQ_ID
		WHERE I.DELETED != ''Y'' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@EVENT_PROGRAMME_REGISTRATION_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@REGISTRATION_COMBINED_PROGRAMME_NAME_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ''
	
		PRINT @strSQL
		EXECUTE (@strSQL)
	END
	
	IF ISNULL(@p_API_TEMP_EVENT_DELEGATE,0) > 0 AND ISNULL(@p_EVENT_DELEGATE,0) = 0
	BEGIN
		SET @strSQL = 'UPDATE C SET 
		C.ATTRIBUTE_038 = (SELECT STRING_AGG(EVENT_PROGRAMME, '', '') FROM #Temp_DELEGATE_PROGRAMMES WHERE ISNULL(COMBINED_PROGRAMME_SETUP, 0) = 0),
        C.ATTRIBUTE_037 = (SELECT STRING_AGG(COMBINED_PROGRAMME_SETUP, '', '') FROM #Temp_DELEGATE_PROGRAMMES WHERE ISNULL(COMBINED_PROGRAMME_SETUP, 0) != 0 )
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C
		WHERE C.DELETED != ''Y'' AND C.SEQ_ID = ' + CAST(@p_API_TEMP_EVENT_DELEGATE AS NVARCHAR(100))
	
		PRINT @strSQL
		EXECUTE (@strSQL)

		-- Update Pivot
		SET @strSQL = 'UPDATE I
		SET I.ATTRIBUTE_STRING = ISNULL((SELECT STRING_AGG(EVENT_PROGRAMME, '', '') FROM #Temp_DELEGATE_PROGRAMMES WHERE ISNULL(COMBINED_PROGRAMME_SETUP, 0) = 0), '''')
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I
		WHERE I.CUS_ENTITY_DATA_SEQ_ID = ' + CAST(@p_API_TEMP_EVENT_DELEGATE AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@TEMP_PROGRAMMES_ATTRIBUTE_SEQ_ID AS NVARCHAR(100))  + ' '
	
		PRINT @strSQL
		EXECUTE (@strSQL)

		SET @strSQL = 'UPDATE I
		SET I.ATTRIBUTE_STRING = ISNULL((SELECT STRING_AGG(COMBINED_PROGRAMME_SETUP, '', '') FROM #Temp_DELEGATE_PROGRAMMES WHERE ISNULL(COMBINED_PROGRAMME_SETUP, 0) != 0), '''')
		FROM [SRM-CustomEntities_' + CAST(ISNULL(@CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I
		WHERE I.CUS_ENTITY_DATA_SEQ_ID = ' + CAST(@p_API_TEMP_EVENT_DELEGATE AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
		CAST(@TEMP_COMBINED_PROGRAMMES_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) 
		PRINT @strSQL
		EXECUTE (@strSQL)
	END

	SELECT * FROM #Temp_DELEGATE_PROGRAMMES-- WHERE ISNULL(COMBINED_PROGRAMME_SETUP,0) != 0

END
;





-- =============================================
-- Author:		
-- Create date: <26/09/2014>
-- Description:	
-- ============================================= EXEC UPDATE_CONTACT_AGE 1,NULL,NULL
CREATE PROCEDURE [dbo].[UPDATE_CONTACT_AGE]
	-- Add the parameters for the stored procedure here

	 @YELLOW_BOOK_OFFSHORE_NEW BIGINT,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN


DECLARE @AGE BIGINT = 0
DECLARE @CONTACT_SEQ_ID BIGINT = 0
DECLARE @DOB DATETIME = NULL


DECLARE CUR_SET_AGE CURSOR STATIC FOR

SELECT  SEQ_ID , Attribute_011  FROM  [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA 
WHERE  SRM_CLIENT_ENTITIES_SEQ_ID = 9855 AND DAY(ISNULL(CAST(Attribute_011 AS DATETIME) , '2014-01-20')) >=1 
AND DAY(ISNULL(CAST(Attribute_011 AS DATETIME) , '2014-01-20')) <=7 
AND MONTH(ISNULL(CAST(Attribute_011 AS DATETIME) , '2014-05-20')) =1 
--AND MONTH(ISNULL(CAST(Attribute_011 AS DATETIME) , '2014-05-20')) =1

OPEN CUR_SET_AGE 
FETCH NEXT FROM CUR_SET_AGE INTO @CONTACT_SEQ_ID , @DOB
	
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @AGE =  DATEDIFF(YY, @DOB, GETDATE())

	UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	SET
			ATTRIBUTE_012 =	@AGE   
	WHERE  SEQ_ID = @CONTACT_SEQ_ID AND SRM_CLIENTS_SEQ_ID = 40 
    AND SRM_CLIENT_ENTITIES_SEQ_ID = 9855

	UPDATE [srm-datapivot].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES
	SET ATTRIBUTE_DECIMAL = CAST(ISNULL(@AGE,0) AS DECIMAL(18,4))
	  WHERE CUS_ENTITY_DATA_SEQ_ID = @CONTACT_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 9855 AND SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = 212529

FETCH NEXT FROM CUR_SET_AGE INTO @CONTACT_SEQ_ID , @DOB
END

CLOSE CUR_SET_AGE 
DEALLOCATE CUR_SET_AGE


END




;


-- *****************************************************************************************************************
-- Created By: Adeel Hassan
-- Date Created: 23/01/2025
-- Summary: A process to update an existing Contact record from Contact API for selected Sections' fields only
--******************************************************************************************************************

CREATE PROCEDURE [dbo].[UPDATE_CONTACT_FROM_API]
	@p_RECORD_ID BIGINT,				-- SEQ_ID OF API_CONTACT
	@p_USER_EMAIL NVARCHAR(200)			-- EMAIL OF oomi USER
AS
BEGIN


	DECLARE @p_CLIENT_ID BIGINT
	DECLARE @API_CONTACT_SEQ_ID BIGINT
	DECLARE @CONTACT_SEQ_ID BIGINT
	SET @API_CONTACT_SEQ_ID = @p_RECORD_ID

	DECLARE @API_CONTACT_ENTITY_SEQ_ID BIGINT
	DECLARE @CONTACT_ENTITY_SEQ_ID BIGINT
	DECLARE @WEB_SECTION_ENTITY_SEQ_ID BIGINT
	DECLARE @WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID BIGINT
	DECLARE @WEB_SECTION_ATTRIBUTE_SEQ_ID BIGINT
	DECLARE @WEB_SECTION_ATTRIBUTE_SEQ_ID2 BIGINT
	DECLARE @WEB_API_FIELDS_CAPTION NVARCHAR(4000)
	DECLARE @WEB_FIELD_ENTITY_SEQ_ID BIGINT

	DECLARE @strSections NVARCHAR(4000)
	DECLARE @strSQL NVARCHAR(max)
	DECLARE @strSOURCE_ATTRIBUTE_SYSTEM_NAME NVARCHAR(100)
	DECLARE @strDESTINATION_ATTRIBUTE_SYSTEM_NAME NVARCHAR(100)

	SET @API_CONTACT_ENTITY_SEQ_ID = 112942
	SET @CONTACT_ENTITY_SEQ_ID = 112718
	SET @WEB_SECTION_ENTITY_SEQ_ID = 112922
	SET @WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID = 112934
	SET @WEB_SECTION_ATTRIBUTE_SEQ_ID = 3065767
	SET @WEB_SECTION_ATTRIBUTE_SEQ_ID2 = 3065824
	SET @WEB_FIELD_ENTITY_SEQ_ID = 112923 



	-- Temporary Table to hold data from CustomEntities of relevant Client - to be used in the Dynamic Statement
	CREATE TABLE #TEMP_QRY
	(SECTIONS NVARCHAR(4000),
	CONTACT_SEQ_ID BIGINT,
	WEB_API_FIELDS_CAPTION NVARCHAR(4000),
	);

	-- Table Variable to hold Web Section ID and Web Section Name
	CREATE TABLE #Temp_SECTIONS  
	(SECTION_ID INT,
	SECTION_NAME NVARCHAR(250) 
	);

	-- Table Variable to hold Section Name, API Caption along with Source and Destination ATTRIBUTES Number
	CREATE TABLE #Temp_SECTION_FIELDS 
	(SECTION_ID INT, 
	SECTION_NAME NVARCHAR(250) , 
	API_CAPTION NVARCHAR(250) ,
	SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 BIGINT,
	SOURCE_ATTRIBUTE_SYSTEM_NAME NVARCHAR(250) ,
	DESTINATION_ATTRIBUTE_SYSTEM_NAME NVARCHAR(250) 
	);


	
	-- Get Client ID on the basis of User Email
	SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USER_EMAIL
	
	
	-- Get All Sections (from Section Name field) and Contact SEQ ID from the API CONTACT entity & Add them into Temp Table
	SET @strSQL = 'INSERT INTO #TEMP_QRY (SECTIONS, CONTACT_SEQ_ID,WEB_API_FIELDS_CAPTION) SELECT ATTRIBUTE_003, ATTRIBUTE_004,ATTRIBUTE_117 FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA WITH (NOLOCK) 
	WHERE SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SEQ_ID = ' + CAST(@API_CONTACT_SEQ_ID AS NVARCHAR(100))
	PRINT @strSQL
	EXECUTE (@strSQL)
	SELECT * FROM #TEMP_QRY 
	
	-- Assign Sections and Contact SEQ ID to the relevant variables for further processing
	SELECT @strSections = SECTIONS, @CONTACT_SEQ_ID = CONTACT_SEQ_ID, @WEB_API_FIELDS_CAPTION = WEB_API_FIELDS_CAPTION FROM #TEMP_QRY

	PRINT  @strSections
	PRINT @CONTACT_SEQ_ID


	IF(ISNULL(@WEB_API_FIELDS_CAPTION, '') != '')
		BEGIN	
		
			INSERT INTO #Temp_SECTION_FIELDS (API_CAPTION)
			SELECT LTRIM(RTRIM(VALUE)) FROM [SRM-FRAMEWORK_NEW].dbo.fn_split (@WEB_API_FIELDS_CAPTION, '|') WHERE LTRIM(RTRIM(value)) <> '';
		
			SELECT * FROM #Temp_SECTION_FIELDS ORDER BY API_CAPTION
		END

	ELSE
		BEGIN
			-- Split the Sections variable on the basis of | sign and add the data into @temp_sections table variable
			INSERT INTO #Temp_SECTIONS (SECTION_NAME)
			SELECT VALUE FROM [SRM-FRAMEWORK_NEW].dbo.fn_split (@strSections, '|') 

			-- Update Section ID 
			SET @strSQL = 'UPDATE #Temp_SECTIONS SET SECTION_ID = SEQ_ID FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA 
			WHERE SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@WEB_SECTION_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND LTRIM(RTRIM(ATTRIBUTE_001)) COLLATE SQL_Latin1_General_CP1_CI_AS = LTRIM(RTRIM(SECTION_NAME))'
			PRINT @strSQL
			EXECUTE (@strSQL)

			-- Add Section Name and API Caption in Temp Setion Fields table from CustomEntities of relevant database
			SET @strSQL = 'INSERT INTO #Temp_SECTION_FIELDS (SECTION_ID, SECTION_NAME, API_CAPTION)
			SELECT DISTINCT T.SECTION_ID, T.SECTION_NAME, C.ATTRIBUTE_066 FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA C, 
			[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I,  #Temp_SECTIONS T, 
			[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES I2 
			WHERE C.DELETED != ''Y'' AND I.DELETED != ''Y'' AND C.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID AS NVARCHAR(100)) +
			' AND I.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
			CAST(@WEB_SECTION_ATTRIBUTE_SEQ_ID AS NVARCHAR(100)) + ' AND I.ATTRIBUTE_DECIMAL = T.SECTION_ID AND C.SEQ_ID = I.CUS_ENTITY_DATA_SEQ_ID 
			 AND I2.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@WEB_FORM_SECTION_FIELD_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND I2.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + 
			CAST(@WEB_SECTION_ATTRIBUTE_SEQ_ID2 AS NVARCHAR(100)) + ' AND I2.ATTRIBUTE_STRING = ''CONTACT'' AND C.SEQ_ID = I2.CUS_ENTITY_DATA_SEQ_ID'
			PRINT @strSQL
			EXECUTE (@strSQL)

			SELECT * FROM #Temp_SECTION_FIELDS ORDER BY API_CAPTION
		END

	-- Update Attribute Number of Source field in the Temp Setion Fields table

	UPDATE T 
	SET T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
	FROM #Temp_SECTION_FIELDS T
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
	INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
	WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @API_CONTACT_ENTITY_SEQ_ID

	-- Insert API Caption of the Description Field of all relevant Lookups 
	INSERT INTO #Temp_SECTION_FIELDS (SECTION_ID, SECTION_NAME, API_CAPTION)
	SELECT T.SECTION_ID, T.SECTION_NAME, SCEA.ATTRIBUTE_API_CAPTION
	FROM #Temp_SECTION_FIELDS T 
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SEQ_ID
	WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 IS NOT NULL

		-- Update Attribute Number of Source field in the Temp Setion Fields table
	UPDATE T 
	SET T.SOURCE_ATTRIBUTE_SYSTEM_NAME = SEA.SYSTEM_NAME, T.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID2 = SCEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID 
	FROM #Temp_SECTION_FIELDS T
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
	INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
	WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @API_CONTACT_ENTITY_SEQ_ID

	-- Update Attribute Number of Destination field in the Temp Setion Fields table
	UPDATE T 
	SET T.DESTINATION_ATTRIBUTE_SYSTEM_NAME = SEA.SYSTEM_NAME 
	FROM #Temp_SECTION_FIELDS T 
	INNER JOIN [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES SCEA ON T.API_CAPTION COLLATE Latin1_General_100_CI_AS = SCEA.ATTRIBUTE_API_CAPTION COLLATE Latin1_General_100_CI_AS
	INNER JOIN [SRM-Framework_New].dbo.srm_entity_attributes SEA ON SCEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SEA.SEQ_ID
	WHERE  SCEA.SRM_CLIENT_ENTITIES_SEQ_ID = @CONTACT_ENTITY_SEQ_ID

	-- Following statement is used just to show the data in this temp table
	SELECT * FROM #Temp_SECTION_FIELDS ORDER BY SOURCE_ATTRIBUTE_SYSTEM_NAME

	-- Create Dynamic Update Statement to update all fields of relevant Sections from Source Custom Entity (i.e API_Contact) to Destination Custom Entity (i.e. Contact)
	SET @strSQL = 'UPDATE DEST SET '
	DECLARE curField CURSOR FOR
	SELECT SOURCE_ATTRIBUTE_SYSTEM_NAME, DESTINATION_ATTRIBUTE_SYSTEM_NAME FROM #Temp_SECTION_FIELDS
	WHERE DESTINATION_ATTRIBUTE_SYSTEM_NAME IS NOT NULL AND SOURCE_ATTRIBUTE_SYSTEM_NAME != 'SEQ_ID' AND SOURCE_ATTRIBUTE_SYSTEM_NAME IS NOT NULL
	ORDER BY SOURCE_ATTRIBUTE_SYSTEM_NAME

	OPEN curField
	FETCH curField INTO @strSOURCE_ATTRIBUTE_SYSTEM_NAME, @strDESTINATION_ATTRIBUTE_SYSTEM_NAME
	
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		IF @strSQL != 'UPDATE DEST SET ' 
			SET @strSQL = @strSQL + ', '

		SET @strSQL = @strSQL + 'DEST.' + @strDESTINATION_ATTRIBUTE_SYSTEM_NAME + ' = SOURCE.'+ @strSOURCE_ATTRIBUTE_SYSTEM_NAME

		FETCH curField INTO @strSOURCE_ATTRIBUTE_SYSTEM_NAME, @strDESTINATION_ATTRIBUTE_SYSTEM_NAME
	END
	
	CLOSE curField
	DEALLOCATE curField

	SET @strSQL = @strSQL + ' FROM [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA DEST, [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA SOURCE '
	SET @strSQL = @strSQL + ' WHERE DEST.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND DEST.SEQ_ID = ' + CAST(@CONTACT_SEQ_ID AS NVARCHAR(100))
	SET @strSQL = @strSQL + ' AND SOURCE.SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SOURCE.SEQ_ID = ' + CAST(@API_CONTACT_SEQ_ID AS NVARCHAR(100))

	-- execute the dynamic statement fo update the details of the Contact record
	PRINT @strSQL
	EXEC (@strSQL)


	-- Create Dynamic Update Statement to update data in the Pivot table
	SET @strSQL = '[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+'].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN] '
	SET @strSQL = @strSQL + '@SRM_CLIENT_ENTITIES_SEQ_ID = ' +  CAST(@CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100))
	SET @strSQL = @strSQL + ', @SRM_CLIENTS_SEQ_ID = ' +  CAST(@p_CLIENT_ID AS NVARCHAR(100))
	SET @strSQL = @strSQL + ', @CUS_ENTITY_DATA_SEQ_ID = ' +  CAST(@CONTACT_SEQ_ID AS NVARCHAR(100))

	-- execute the dynamic statement fo update the details of the Contact record in the Pivot table
	PRINT @strSQL
	EXEC (@strSQL)

	
	-- Create dynamic statement to update certain flags in the API Contact
	SET @strSQL = 'UPDATE [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA SET '
	PRINT @strSQL

	IF EXISTS (SELECT API_CAPTION, SOURCE_ATTRIBUTE_SYSTEM_NAME FROM #Temp_SECTION_FIELDS WHERE API_CAPTION IN ('MainAccount', 'MainAccountName'))
		SET @strSQL = @strSQL + 'ATTRIBUTE_078 = ''Y'''		

	IF EXISTS (SELECT API_CAPTION, SOURCE_ATTRIBUTE_SYSTEM_NAME FROM #Temp_SECTION_FIELDS WHERE API_CAPTION IN ('DisabilitiesRecordIds', 'OtherDisabilities'))
		IF @strSQL = 'UPDATE [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA SET '
			SET @strSQL = @strSQL + 'ATTRIBUTE_079 = ''Y'''		
		ELSE
			SET @strSQL = @strSQL + ', ATTRIBUTE_079 = ''Y'''		
	
	IF EXISTS (SELECT API_CAPTION, SOURCE_ATTRIBUTE_SYSTEM_NAME FROM #Temp_SECTION_FIELDS WHERE API_CAPTION IN ('WorkingPatternsRecordIds', 'OtherWorkingPattern'))
		IF @strSQL = 'UPDATE [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA SET ' 
			SET @strSQL = @strSQL + 'ATTRIBUTE_080 = ''Y'''
		ELSE
			SET @strSQL = @strSQL + ', ATTRIBUTE_080 = ''Y'''

	IF EXISTS (SELECT API_CAPTION, SOURCE_ATTRIBUTE_SYSTEM_NAME FROM #Temp_SECTION_FIELDS WHERE API_CAPTION IN ('CaringResponsibilitiesRecordIds'))
		IF @strSQL = 'UPDATE [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA SET ' 
			SET @strSQL = @strSQL + 'ATTRIBUTE_081 = ''Y'''
		ELSE
			SET @strSQL = @strSQL + ', ATTRIBUTE_081 = ''Y'''

	IF @strSQL != 'UPDATE [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA SET '
	BEGIN
		SET @strSQL = @strSQL + ' WHERE SRM_CLIENT_ENTITIES_SEQ_ID = ' + CAST(@API_CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100)) + ' AND SEQ_ID = ' + CAST(@API_CONTACT_SEQ_ID AS NVARCHAR(100))

		PRINT @strSQL
		EXEC (@strSQL)

		-- Create Dynamic Update Statement to update data in the Pivot table
		SET @strSQL = '[SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+'].[dbo].[GET_POPULATE_PIVOT_TABLE_MAIN] '
		SET @strSQL = @strSQL + '@SRM_CLIENT_ENTITIES_SEQ_ID = ' +  CAST(@API_CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100))
		SET @strSQL = @strSQL + ', @SRM_CLIENTS_SEQ_ID = ' +  CAST(@p_CLIENT_ID AS NVARCHAR(100))
		SET @strSQL = @strSQL + ', @CUS_ENTITY_DATA_SEQ_ID = ' +  CAST(@API_CONTACT_SEQ_ID AS NVARCHAR(100))

		PRINT @strSQL
		EXEC (@strSQL)
	END

END

;





 --=============================================
-- Author:		<ASAD>
-- Create date: <11/11/2014>
-- Modified By: <Musawar>
-- Modified Date: <26/11/2014>
-- Description:	<UPDATE CRETIFICATE TRACKING>
-- =============================================
CREATE PROCEDURE [dbo].[UPDATE_CRETIFICATE_TRACKING]
	 @APPLICATION_SEQ_ID BIGINT,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[UPDATE CRETIFICATE TRACKING]...'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[UPDATE CRETIFICATE TRACKING]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE
	--BLUE BOOK ENTITIES
	@BLUE_BOOK_PHASE_B_CLIENT_ENTITY BIGINT = 10164,
	@BLUE_BOOK_TASK_BOOK_CLIENT_ENTITY BIGINT = 10170,
	@BLUE_BOOK_PHASE_D_CLIENT_ENTITY BIGINT = 11231,
	@BLUE_BOOK_STR_CLIENT_ENTITY BIGINT = 11545,
	@BLUE_BOOK_SIGN_OFF_CLIENT_ENTITY BIGINT = 10167,

	--BLACK BOOK ENTITIES
	@BLACK_BOOK_PHASE_B_CLIENT_ENTITY BIGINT = 10176,
	@BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY BIGINT = 10185,
	@BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY BIGINT = 10179,
	@BLACK_BOOK_PHASE_D_CLIENT_ENTITY BIGINT = 10177,
	@BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY BIGINT = 11234,
	@BLACK_BOOK_STR_CLIENT_ENTITY BIGINT =11544,
	@BLACK_BOOK_SIGN_OFF_CLIENT_ENTITY BIGINT = 10178,

	--CERTIFICATE TRACKING FIELDS
	@TOTAL_PHASE_B_DAYS BIGINT = 0,
	@PHASE_B_SEA_TIME_DATE_VALID NVARCHAR(3) = 'Y',
	@TASK_DATE_WITHIN_B NVARCHAR(3) = 'N',
	@NEW_TASK_DATE_WITHIN_D NVARCHAR(3) = 'N',
	@TOTAL_PHASE_D_DAYS BIGINT = 0,
	@PHASE_D_SEA_TIME_DATE_VALID NVARCHAR(3) = 'Y',
	@DP1_CLASS NVARCHAR(3) = 'N',
