		AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY
		AND (CAST(ISNULL(ATTRIBUTE_006,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_D_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_D_TO_DATE,'1947-01-01') AS DATE) 
		OR CAST(ISNULL(ATTRIBUTE_007,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_D_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_D_TO_DATE,'1947-01-01') AS DATE))))
	BEGIN
		SET @PHASE_D_SEA_TIME_DATE_VALID = 'N'
	END
	ELSE
		SET @PHASE_D_SEA_TIME_DATE_VALID = 'Y'

	FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_D INTO @BLACK_BOOK_PHASE_D_SEQ_ID,@BLACK_BOOK_PHASE_D_FROM_DATE,@BLACK_BOOK_PHASE_D_TO_DATE
	END

	CLOSE CUR_BLACK_BOOK_PHASE_D 
	DEALLOCATE CUR_BLACK_BOOK_PHASE_D
	END

	IF(EXISTS(SELECT  SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_STR_CLIENT_ENTITY))
	BEGIN
	 SET @STR = 'Y'
	END
	ELSE
	BEGIN
		IF(EXISTS(SELECT  SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_STR_CLIENT_ENTITY))
	BEGIN
		SET @STR = 'Y'
	END
	ELSE
		SET @STR = 'N'
	END
	
	IF (@STR = 'Y')
	BEGIN
		PRINT 'PHASE STR'	
		SELECT @TEMP_BLUE_STR_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_022,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_STR_CLIENT_ENTITY

		SELECT @TEMP_BLACK_STR_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_019,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_STR_CLIENT_ENTITY

		SET @STR_DAYS = SUM(ISNULL(@TEMP_BLUE_STR_DAYS,0) + ISNULL(@TEMP_BLACK_STR_DAYS,0))
	END


	END
	ELSE IF (@CATEGORY = 'Upgrade' AND @APPLICATION_SEQ_ID > 0)
	BEGIN
	
	SELECT  @BLACK_TASK_BOOK_SEQ = SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_006 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY AND ATTRIBUTE_010 IS NOT NULL

	IF @BLACK_TASK_BOOK_SEQ > 0
	BEGIN
		DECLARE CUR_BLACK_TASK_BOOK_UPGRADE CURSOR STATIC FOR
		SELECT  SEQ_ID,ATTRIBUTE_010 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_006 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY

		OPEN CUR_BLACK_TASK_BOOK_UPGRADE 
		FETCH NEXT FROM CUR_BLACK_TASK_BOOK_UPGRADE 
		INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID, @BLACK_BOOK_DATE
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
		--IF DETAIL NOT EXIST THEN WHAT TO DO......
	
			IF EXISTS (SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_013,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_014,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE))
		BEGIN
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
		BEGIN
			IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_010,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_011,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE)))
		BEGIN	
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
			SET @NEW_TASK_DATE_WITHIN_D = 'N'
		END
		FETCH NEXT FROM CUR_BLACK_TASK_BOOK_UPGRADE INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID,@BLACK_BOOK_DATE
		END

		CLOSE CUR_BLACK_TASK_BOOK_UPGRADE 
		DEALLOCATE CUR_BLACK_TASK_BOOK_UPGRADE
	END
	ELSE
	BEGIN
		
		DECLARE CUR_BLUE_TASK_BOOK_UPGRADE CURSOR STATIC FOR
		SELECT  SEQ_ID,ATTRIBUTE_014 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_023,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_TASK_BOOK_CLIENT_ENTITY

		OPEN CUR_BLUE_TASK_BOOK_UPGRADE 
		FETCH NEXT FROM CUR_BLUE_TASK_BOOK_UPGRADE 
		INTO @BLUE_BOOK_TASK_BOOK_SEQ_ID, @BLUE_BOOK_DATE
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
		--IF DETAIL NOT EXIST THEN WHAT TO DO......
	
			IF EXISTS (SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_013,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_014,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE))
		BEGIN
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
		BEGIN
			IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_010,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_011,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE)))
		BEGIN	
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
			SET @NEW_TASK_DATE_WITHIN_D = 'N'
		END
		FETCH NEXT FROM CUR_BLUE_TASK_BOOK_UPGRADE INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID,@BLACK_BOOK_DATE
		END

		CLOSE CUR_BLUE_TASK_BOOK_UPGRADE 
		DEALLOCATE CUR_BLUE_TASK_BOOK_UPGRADE

	END

		SELECT @TEMP_BLUE_PHASE_D_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ( ATTRIBUTE_009 LIKE '%2' OR ATTRIBUTE_009 LIKE '%3')
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

		SELECT @TEMP_BLACK_PHASE_D_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ( ATTRIBUTE_020 LIKE '%2' OR ATTRIBUTE_020 LIKE '%3')
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY


		
		SET @TOTAL_DAYS_FOR_NEW_DP2 = SUM(@TEMP_BLUE_PHASE_D_DAYS + @TEMP_BLACK_PHASE_D_DAYS)

		IF (@TOTAL_DAYS_FOR_NEW_DP2  > 0)
		BEGIN
			SET @NEW_PHASE_D_DATA = 'Y'

			IF(EXISTS(SELECT  SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY))
			BEGIN
				DECLARE CUR_BLACK_BOOK_PHASE_D CURSOR STATIC FOR

				SELECT  SEQ_ID,ATTRIBUTE_013,ATTRIBUTE_014 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
				WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
				AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY

				OPEN CUR_BLACK_BOOK_PHASE_D 
				FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_D INTO @BLACK_BOOK_PHASE_D_SEQ_ID,@BLACK_BOOK_PHASE_D_FROM_DATE,@BLACK_BOOK_PHASE_D_TO_DATE
				WHILE @@FETCH_STATUS = 0
				BEGIN
					--IF DETAIL NOT EXIST THEN WHAT TO DO......
					IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
					WHERE ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
					AND ATTRIBUTE_011 = @BLACK_BOOK_PHASE_D_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
					AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY
					AND (CAST(ISNULL(ATTRIBUTE_006,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_D_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_D_TO_DATE,'1947-01-01') AS DATE) 
					OR CAST(ISNULL(ATTRIBUTE_007,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_D_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_D_TO_DATE,'1947-01-01') AS DATE))))
				BEGIN
					SET @PHASE_D_SEA_TIME_DATE_VALID = 'N'
				END
				ELSE
					SET @PHASE_D_SEA_TIME_DATE_VALID = 'Y'

				FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_D INTO @BLACK_BOOK_PHASE_D_SEQ_ID,@BLACK_BOOK_PHASE_D_FROM_DATE,@BLACK_BOOK_PHASE_D_TO_DATE
				END

				CLOSE CUR_BLACK_BOOK_PHASE_D 
				DEALLOCATE CUR_BLACK_BOOK_PHASE_D
			END
		END
		ELSE
			SET @NEW_PHASE_D_SEA_TIME_VALID = 'N'
END

	DECLARE @TEMP_BLUE_LEFT_DATE DATE
	DECLARE @TEMP_BLACK_LEFT_DATE DATE
	DECLARE @BLUE_D_SEQ_ID BIGINT = 0
	DECLARE @BLUE_SHIP BIGINT = 0
	DECLARE @BLACK_D_SEQ_ID BIGINT = 0
	DECLARE @BLACK_SHIP BIGINT = 0
	DECLARE @BLUE_SIGN_OFF_SEQ_ID BIGINT =0
	DECLARE @BLUE_SIGN_OFF_SHIP BIGINT = 0
	DECLARE @BLACK_SIGN_OFF_SEQ_ID BIGINT = 0
	DECLARE @BLACK_SIGN_OFF_SHIP BIGINT = 0
	DECLARE @TEMP_SIGN_OFF_FLAG NVARCHAR(3) = 'N'


	SELECT @TEMP_BLUE_LEFT_DATE = MAX(CAST(ISNULL(ATTRIBUTE_011,'0001-01-01') AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

	PRINT 'BLUE @TEMP_BLUE_LEFT_DATE'
	PRINT @TEMP_BLUE_LEFT_DATE
	
	SELECT @TEMP_BLACK_LEFT_DATE = MAX(CAST(ISNULL(ATTRIBUTE_014,'0001-01-01') AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
	PRINT @TEMP_BLACK_LEFT_DATE
	IF (@TEMP_BLUE_LEFT_DATE != CAST('0001-01-01' AS DATE) AND CAST(ISNULL(@TEMP_BLUE_LEFT_DATE,'0001-01-01') AS DATE) > CAST(ISNULL(@TEMP_BLACK_LEFT_DATE,'0001-01-01') AS DATE))
	BEGIN
		PRINT 'SIGN OFF 1'
		SELECT @BLUE_D_SEQ_ID = SEQ_ID ,@BLUE_SHIP = ISNULL(ATTRIBUTE_006,0)
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY
		AND CAST(ISNULL(ATTRIBUTE_011,'0002-01-01') AS DATE) = CAST(ISNULL(@TEMP_BLUE_LEFT_DATE,'0002-01-01')AS DATE)

	END
	ELSE IF (@TEMP_BLACK_LEFT_DATE != CAST('0001-01-01' AS DATE) AND  CAST(ISNULL(@TEMP_BLACK_LEFT_DATE,'0002-01-01')AS DATE) >= CAST(ISNULL(@TEMP_BLUE_LEFT_DATE,'0002-01-01')AS DATE))
	BEGIN
		PRINT 'SIGN OFF 2'
		SELECT @BLACK_D_SEQ_ID = SEQ_ID ,@BLACK_SHIP = ISNULL(ATTRIBUTE_006,0)
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
		AND CAST(ISNULL(ATTRIBUTE_014,'0002-01-01') AS DATE) = CAST(ISNULL(@TEMP_BLACK_LEFT_DATE,'0002-01-01')AS DATE)
	END
	ELSE
	BEGIN
		PRINT 'SIGN OFF ELSE TO N'
		SET @TEMP_SIGN_OFF_FLAG = 'N'
	END

		SELECT @BLUE_SIGN_OFF_SEQ_ID = SEQ_ID ,@BLUE_SIGN_OFF_SHIP = ISNULL(ATTRIBUTE_014,0)--22052795	18148614
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_SIGN_OFF_CLIENT_ENTITY

	IF (@BLUE_D_SEQ_ID > 0 AND @BLUE_SIGN_OFF_SEQ_ID > 0 AND @BLUE_SHIP > 0 AND @BLUE_SHIP = @BLUE_SIGN_OFF_SHIP)
	BEGIN
		PRINT '@TEMP_SIGN_OFF_FLAG'
		SET @TEMP_SIGN_OFF_FLAG = 'Y'
	END
	ELSE IF(@BLACK_D_SEQ_ID > 0 AND @BLUE_SIGN_OFF_SEQ_ID > 0 AND @BLACK_SHIP > 0 AND @BLACK_SHIP = @BLUE_SIGN_OFF_SHIP)
	BEGIN
		PRINT '@TEMP_SIGN_OFF_FLAG1'
		SET @TEMP_SIGN_OFF_FLAG = 'Y'
	END
	ELSE
	BEGIN
		PRINT '@TEMP_SIGN_OFF_FLAG ELSE'
		SELECT @BLACK_SIGN_OFF_SEQ_ID = SEQ_ID ,@BLACK_SIGN_OFF_SHIP = ISNULL(ATTRIBUTE_027,0)
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_020,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_SIGN_OFF_CLIENT_ENTITY

		IF (@BLUE_D_SEQ_ID > 0 AND @BLACK_SIGN_OFF_SEQ_ID > 0 AND @BLUE_SHIP > 0 AND @BLUE_SHIP = @BLACK_SIGN_OFF_SHIP)
		BEGIN
			SET @TEMP_SIGN_OFF_FLAG = 'Y'
		END
		ELSE IF(@BLACK_D_SEQ_ID > 0 AND @BLACK_SIGN_OFF_SEQ_ID > 0 AND @BLACK_SHIP > 0 AND @BLACK_SHIP = @BLACK_SIGN_OFF_SHIP)
		BEGIN
			SET @TEMP_SIGN_OFF_FLAG = 'Y'
		END
		ELSE
			SET @TEMP_SIGN_OFF_FLAG = 'N'
	END
	PRINT '@TEMP_SIGN_OFF_FLAG IS ' + @TEMP_SIGN_OFF_FLAG
	IF (@CATEGORY = 'New' AND @APPLICATION_SEQ_ID > 0)
		SET @SIGNED_OFF_LAST_VESSEL = @TEMP_SIGN_OFF_FLAG
	IF (@CATEGORY = 'Upgrade' AND @APPLICATION_SEQ_ID > 0)
		SET @SIGNED_OFF_LAST_VESSEL = @TEMP_SIGN_OFF_FLAG
	
	DECLARE @TRACKING_SEQ_ID BIGINT  = 0
	SELECT @TRACKING_SEQ_ID = SEQ_ID 
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID  AND ISNULL(DELETED ,'N') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 11604
	print @TOTAL_PHASE_B_DAYS
	
	IF (@TRACKING_SEQ_ID > 0)
	BEGIN
		UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		SET
				ATTRIBUTE_011 = @PHASE_B_SEA_TIME_DATE_VALID,   
				ATTRIBUTE_036 = @TOTAL_PHASE_B_DAYS, 
				ATTRIBUTE_015 = @TASK_DATE_WITHIN_B,
				ATTRIBUTE_029 = @NEW_TASK_DATE_WITHIN_D,
				ATTRIBUTE_037 = @TOTAL_PHASE_D_DAYS,
				ATTRIBUTE_012 = @PHASE_D_SEA_TIME_DATE_VALID,
				ATTRIBUTE_019 = @DP1_CLASS,
				ATTRIBUTE_025 = @DP1_CLASS_DAYS,
				ATTRIBUTE_020 = @DP2_CLASS,
				ATTRIBUTE_022 = @DP2_CLASS_DAYS,
				ATTRIBUTE_021 = @DP3_CLASS,
				ATTRIBUTE_023 = @DP3_CLASS_DAYS,
				ATTRIBUTE_024 = 0,--TOTAL ACTIVE_DAYS
				ATTRIBUTE_026 = @NEW_PHASE_D_DATA,
				ATTRIBUTE_031 = @NEW_PHASE_D_SEA_TIME_VALID,
				ATTRIBUTE_027 = @TOTAL_DAYS_FOR_NEW_DP2,
				ATTRIBUTE_038 = @STR,
				ATTRIBUTE_039 = @STR_DAYS,
				ATTRIBUTE_041 = @NEW_SIGNED_OFF_LAST_VESSEL,
				ATTRIBUTE_040 = @SIGNED_OFF_LAST_VESSEL			
		WHERE  SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID= 11604 and seq_id =@TRACKING_SEQ_ID

		EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
			@SRM_CLIENT_ENTITIES_SEQ_ID = 11604,
			@CUS_ENTITY_DATA_SEQ_ID = @TRACKING_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT


			EXEC [dbo].[UPDATE_CRETIFICATE_TRACKING_BLUE_BLACK_SP]
			@APPLICATION_SEQ_ID = @APPLICATION_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT



	END
END






;





 --=============================================
-- Author:		<ASAD>
-- Create date: <11/12/2014>
-- Description:	<UPDATE CRETIFICATE TRACKING>
-- =============================================
CREATE PROCEDURE [dbo].[UPDATE_CRETIFICATE_TRACKING_BLUE_BLACK_SP]
	 @APPLICATION_SEQ_ID BIGINT,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[UPDATE_CRETIFICATE_TRACKING_BLUE_BLACK_SP]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[UPDATE_CRETIFICATE_TRACKING_BLUE_BLACK_SP]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE
	--BLUE BOOK ENTITIES
	@BLUE_BOOK_BASIC_COURSE_CLIENT_ENTITY BIGINT = 10162,
	@BLUE_BOOK_ADVANCE_COURSE_CLIENT_ENTITY BIGINT = 10165,
	@BLUE_BOOK_PHASE_B_CLIENT_ENTITY BIGINT = 10164,
	@BLUE_BOOK_TASK_BOOK_CLIENT_ENTITY BIGINT = 10170,
	@BLUE_BOOK_PHASE_D_CLIENT_ENTITY BIGINT = 11231,
	@BLUE_BOOK_STR_CLIENT_ENTITY BIGINT = 11545,

	--@BLUE_BOOK_SIGN_OFF_CLIENT_ENTITY BIGINT = 10167,

	--BLACK BOOK ENTITIES
	@BLACK_BOOK_BASIC_COURSE_CLIENT_ENTITY BIGINT = 10174,
	@BLACK_BOOK_ADVANCE_COURSE_CLIENT_ENTITY BIGINT = 10175,
	@BLACK_BOOK_PHASE_B_CLIENT_ENTITY BIGINT = 10176,
	@BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY BIGINT = 10185,
	@BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY BIGINT = 10179,
	@BLACK_BOOK_PHASE_D_CLIENT_ENTITY BIGINT = 10177,
	@BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY BIGINT = 11234,
	@BLACK_BOOK_STR_CLIENT_ENTITY BIGINT =11544,
	--@BLACK_BOOK_SIGN_OFF_CLIENT_ENTITY BIGINT = 10178,


	--CERTIFICATE TRACKING FIELDS
	
	@BASIC_COURSE_DATE DATE = NULL,
	@BASIC_COURSE_CENTRE_SEQ_ID BIGINT = NULL,
	@BASIC_COURSE_CENTRE_NAME NVARCHAR(100) = NULL,
	@BASIC_COURSE_EXAM_PASSED NVARCHAR(3) = 'N',
	@ADVANCE_COURSE_DATE DATE = NULL,
	@ADVANCE_COURSE_CENTRE_SEQ_ID BIGINT = NULL,
	@ADVANCE_COURSE_CENTRE_NAME NVARCHAR(100) = NULL,
	@ADVANCE_COURSE_EXAM_PASSED NVARCHAR(3) = 'N',

	@PHASE_B_DATE DATE,
	@PHASE_B_NOT_MORE_THAN_150_DAYS NVARCHAR(3) = 'N',
	@SECTION_C_MANDATORY_TASK_COMPLETED NVARCHAR(3) = 'N',
	@50_PERCENT_MANDATORY_TASK_COMPLETED NVARCHAR(3) = 'N',
	@PHASE_D_DAYS_AFTER_ADVANCE BIGINT = 0,
	@PHASE_D_DAYS_AFTER_STR BIGINT = 0,
	@PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR BIGINT = 0,
	@PHASE_D_DATE DATE,
	@PHASE_D_DAYS_NOT_MORE_THAN_150 NVARCHAR(3) = 'N',

	@TEMP_MAX_BLUE_BASIC_COURSE_DATE DATE,
	@TEMP_MAX_BLACK_BASIC_COURSE_DATE DATE,
	@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE DATE,
	@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE DATE,

	@TEMP_MAX_BLUE_STR_DATE DATE,
	@TEMP_MAX_BLACK_STR_DATE DATE,

	@TEMP_MIN_BLUE_PHASE_B_DATE DATE,
	@TEMP_MIN_BLACK_PHASE_B_DATE DATE,
	@TEMP_MIN_BLUE_PHASE_D_DATE DATE,
	@TEMP_MIN_BLACK_PHASE_D_DATE DATE,
	@TEMP_BLUE_PHASE_D_DAYS_AFTER_STR BIGINT,
	@TEMP_BLACK_PHASE_D_DAYS_AFTER_STR BIGINT,
	@TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE BIGINT,
	@TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE BIGINT,
	@TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR BIGINT,
	@TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR BIGINT,


	@TEMP_ADVANCE_LATEST_DATE DATE,
	@TEMP_STR_LATEST_DATE DATE,

	@TEMP_BASIC_LATEST_DATE DATE,
	@TEMP_ADV_DAYS_LASTEST_DATE DATE,

	@SRM_CLIENTS_SEQ_ID BIGINT = 40
	
	DECLARE @CERTIFICATION_CATEGORY_SEQ_ID BIGINT
	DECLARE @CATEGORY NVARCHAR(20)

	DECLARE @STR_DATE DATE
  DECLARE @PHASE_B_DAYS_AFTER_BASIC_BEFORE_ADVANCE BIGINT = 0
  DECLARE @TEMP_BLACK_STR_MIN_DATE DATE
  DECLARE @TEMP_BLUE_STR_MIN_DATE DATE
  DECLARE @TEMP_BLACK_PHASE_B_DAYS BIGINT
  DECLARE @TEMP_BLUE_PHASE_B_DAYS BIGINT
  DECLARE @STATUS NVARCHAR(50)


	SELECT @CERTIFICATION_CATEGORY_SEQ_ID = ATTRIBUTE_007
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @APPLICATION_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID =10156

	SELECT @CATEGORY = ATTRIBUTE_006
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @CERTIFICATION_CATEGORY_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 10154


	SELECT @STATUS = ATTRIBUTE_006
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @APPLICATION_SEQ_ID

	IF (@CATEGORY = 'New' AND @APPLICATION_SEQ_ID > 0 AND @STATUS = 'In Progress' )
	BEGIN
		print 'new..'
		-- MAX BASIC COURSE DATE
		SELECT @TEMP_MAX_BLUE_BASIC_COURSE_DATE = MAX(CAST(ATTRIBUTE_004 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_010 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_017,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_BASIC_COURSE_CLIENT_ENTITY

		SELECT @TEMP_MAX_BLACK_BASIC_COURSE_DATE = MAX(CAST(ATTRIBUTE_004 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_008 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_015,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_BASIC_COURSE_CLIENT_ENTITY

		IF ISNULL(@TEMP_MAX_BLUE_BASIC_COURSE_DATE,'0001-01-01') != '0001-01-01' 
			AND ISNULL(@TEMP_MAX_BLUE_BASIC_COURSE_DATE,'0001-01-01') >= ISNULL(@TEMP_MAX_BLACK_BASIC_COURSE_DATE,'0002-01-01')
		BEGIN
			SELECT @BASIC_COURSE_DATE = CAST(ATTRIBUTE_004 AS DATE) ,
				   @BASIC_COURSE_CENTRE_SEQ_ID = ATTRIBUTE_002 ,
				   @BASIC_COURSE_CENTRE_NAME = ATTRIBUTE_003,
				   @BASIC_COURSE_EXAM_PASSED = ATTRIBUTE_007
			FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_010 = @APPLICATION_SEQ_ID AND ATTRIBUTE_004 = @TEMP_MAX_BLUE_BASIC_COURSE_DATE AND ISNULL(ATTRIBUTE_017,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_BASIC_COURSE_CLIENT_ENTITY

			SET @TEMP_BASIC_LATEST_DATE = @TEMP_MAX_BLUE_BASIC_COURSE_DATE
		END
		ELSE IF ISNULL(@TEMP_MAX_BLACK_BASIC_COURSE_DATE,'0001-01-01') != '0001-01-01' 
						AND ISNULL(@TEMP_MAX_BLACK_BASIC_COURSE_DATE,'0001-01-01') >= ISNULL(@TEMP_MAX_BLUE_BASIC_COURSE_DATE,'0002-01-01')
		BEGIN
			SELECT @BASIC_COURSE_DATE = CAST(ATTRIBUTE_004 AS DATE) ,
				   @BASIC_COURSE_CENTRE_SEQ_ID = ATTRIBUTE_002 ,
				   @BASIC_COURSE_CENTRE_NAME = ATTRIBUTE_003,
				   @BASIC_COURSE_EXAM_PASSED = ATTRIBUTE_007
			FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_008 = @APPLICATION_SEQ_ID AND ATTRIBUTE_004 = @TEMP_MAX_BLACK_BASIC_COURSE_DATE AND ISNULL(ATTRIBUTE_015,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_BASIC_COURSE_CLIENT_ENTITY

			SET @TEMP_BASIC_LATEST_DATE = @TEMP_MAX_BLACK_BASIC_COURSE_DATE
		END


		--MAX ADVANCE COURSE
		SELECT @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE = MAX(CAST(ATTRIBUTE_006 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_012 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_014,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

		SELECT @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE = MAX(CAST(ATTRIBUTE_012 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_015,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

		IF ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE,'0001-01-01') != '0001-01-01' 
			AND ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE,'0001-01-01') >= ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE,'0002-01-01')
		BEGIN
			SELECT @ADVANCE_COURSE_DATE = CAST(ATTRIBUTE_006 AS DATE) ,
				   @ADVANCE_COURSE_CENTRE_SEQ_ID = ATTRIBUTE_004 ,
				   @ADVANCE_COURSE_CENTRE_NAME = ATTRIBUTE_005,
				   @ADVANCE_COURSE_EXAM_PASSED = ATTRIBUTE_009
			FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_012 = @APPLICATION_SEQ_ID AND ATTRIBUTE_006 = @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE AND ISNULL(ATTRIBUTE_014,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

			SET @TEMP_ADV_DAYS_LASTEST_DATE = @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE

		END
		ELSE IF ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE,'0001-01-01') != '0001-01-01' 
						AND ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE,'0001-01-01') >= ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE,'0002-01-01')
		BEGIN
			SELECT @ADVANCE_COURSE_DATE = CAST(ATTRIBUTE_012 AS DATE) ,
				   @ADVANCE_COURSE_CENTRE_SEQ_ID = ATTRIBUTE_006 ,
				   @ADVANCE_COURSE_CENTRE_NAME = ATTRIBUTE_007,
				   @ADVANCE_COURSE_EXAM_PASSED = ATTRIBUTE_011
			FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ATTRIBUTE_012 = @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE AND ISNULL(ATTRIBUTE_015,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

			SET @TEMP_ADV_DAYS_LASTEST_DATE = @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE

		END

		--PHASE B DATE
		SELECT @TEMP_MIN_BLUE_PHASE_B_DATE = MIN(CAST(ATTRIBUTE_008 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_018 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_B_CLIENT_ENTITY

		SELECT @TEMP_MIN_BLACK_PHASE_B_DATE = MIN(CAST(ATTRIBUTE_004 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_015 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_024,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_CLIENT_ENTITY


		IF ISNULL(@TEMP_MIN_BLUE_PHASE_B_DATE,'2099-01-01') != '2099-01-01' 
			AND ISNULL(@TEMP_MIN_BLUE_PHASE_B_DATE,'2099-01-01') <= ISNULL(@TEMP_MIN_BLACK_PHASE_B_DATE,'2098-01-01')

		BEGIN
			SET @PHASE_B_DATE = @TEMP_MIN_BLUE_PHASE_B_DATE
		END
		ELSE IF ISNULL(@TEMP_MIN_BLACK_PHASE_B_DATE,'2099-01-01') != '2099-01-01' 
			AND ISNULL(@TEMP_MIN_BLACK_PHASE_B_DATE,'2099-01-01') <= ISNULL(@TEMP_MIN_BLUE_PHASE_B_DATE,'2098-01-01')

		BEGIN
			SET @PHASE_B_DATE = @TEMP_MIN_BLACK_PHASE_B_DATE
		END

		DECLARE @TEMP_BLUE_PHASE_B_SEQ_ID BIGINT
		DECLARE @TEMP_BLACK_PHASE_B_DETAIL_SEQ_ID BIGINT


		SELECT @TEMP_BLUE_PHASE_B_SEQ_ID = SEQ_ID
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_018 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND CAST(ISNULL(ATTRIBUTE_010, 0) AS INT) > 150
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_B_CLIENT_ENTITY

		SELECT @TEMP_BLACK_PHASE_B_DETAIL_SEQ_ID = SEQ_ID
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_015,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND CAST(ISNULL(ATTRIBUTE_010, 0) AS INT) > 150
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY

		IF ISNULL(@TEMP_BLUE_PHASE_B_SEQ_ID, 0) = 0 AND ISNULL(@TEMP_BLACK_PHASE_B_DETAIL_SEQ_ID,0) = 0
		SET @PHASE_B_NOT_MORE_THAN_150_DAYS = 'Y'


		IF ISNULL(@TEMP_BASIC_LATEST_DATE, '0001-01-01') != '0001-01-01' AND ISNULL(@TEMP_ADV_DAYS_LASTEST_DATE, '0001-01-01') != '0001-01-01'
		BEGIN

		SELECT @TEMP_BLACK_PHASE_B_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_010,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_015,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_008 > @TEMP_BASIC_LATEST_DATE AND ATTRIBUTE_009 < @TEMP_ADV_DAYS_LASTEST_DATE
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY

		SELECT @TEMP_BLUE_PHASE_B_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_010,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_018 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_008 > @TEMP_BASIC_LATEST_DATE AND ATTRIBUTE_009 < @TEMP_ADV_DAYS_LASTEST_DATE
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_B_CLIENT_ENTITY

		SET @PHASE_B_DAYS_AFTER_BASIC_BEFORE_ADVANCE = ISNULL(@TEMP_BLACK_PHASE_B_DAYS,0) + ISNULL(@TEMP_BLUE_PHASE_B_DAYS,0)

		END

		--PHASE D DATE
		SELECT @TEMP_MIN_BLUE_PHASE_D_DATE = MIN(CAST(ATTRIBUTE_010 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

		SELECT @TEMP_MIN_BLACK_PHASE_D_DATE = MIN(CAST(ATTRIBUTE_013 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_022,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY


		IF ISNULL(@TEMP_MIN_BLUE_PHASE_D_DATE,'2099-01-01') != '2099-01-01' 
			AND ISNULL(@TEMP_MIN_BLUE_PHASE_D_DATE,'2099-01-01') <= ISNULL(@TEMP_MIN_BLACK_PHASE_D_DATE,'2098-01-01')

		BEGIN
			SET @PHASE_D_DATE = @TEMP_MIN_BLUE_PHASE_D_DATE
		END
		ELSE IF ISNULL(@TEMP_MIN_BLACK_PHASE_D_DATE,'2099-01-01') != '2099-01-01' 
			AND ISNULL(@TEMP_MIN_BLACK_PHASE_D_DATE,'2099-01-01') <= ISNULL(@TEMP_MIN_BLUE_PHASE_D_DATE,'2098-01-01')

		BEGIN
			SET @PHASE_D_DATE = @TEMP_MIN_BLUE_PHASE_D_DATE
		END

		DECLARE @TEMP_BLUE_PHASE_D_SEQ_ID BIGINT
		DECLARE @TEMP_BLACK_PHASE_D_DETAIL_SEQ_ID BIGINT


		SELECT @TEMP_BLUE_PHASE_D_SEQ_ID = SEQ_ID
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND CAST(ISNULL(ATTRIBUTE_030, 0) AS INT) > 150
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

		SELECT @TEMP_BLACK_PHASE_D_DETAIL_SEQ_ID = SEQ_ID
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND CAST(ISNULL(ATTRIBUTE_008, 0) AS INT) > 150
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

		IF ISNULL(@TEMP_BLUE_PHASE_D_SEQ_ID, 0) = 0 AND ISNULL(@TEMP_BLACK_PHASE_D_DETAIL_SEQ_ID,0) = 0
		SET @PHASE_D_DAYS_NOT_MORE_THAN_150 = 'Y'

		--PHASE_D_DAYS_AFTER_ADVANCE

	SELECT @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE = MAX(ATTRIBUTE_006)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_012 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_014,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

	SELECT @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE = MAX(ATTRIBUTE_012)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_015,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

	IF ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE,'2099-12-01') != '2099-12-01' OR ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE, '2099-12-01') != '2099-12-01'
	BEGIN
		
	SELECT @TEMP_MAX_BLUE_STR_DATE = MAX(ATTRIBUTE_008)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_STR_CLIENT_ENTITY

	SELECT @TEMP_MAX_BLACK_STR_DATE = MAX(ATTRIBUTE_006)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_STR_CLIENT_ENTITY


	IF ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE , '0001-01-01') != '0001-01-01' AND ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE , '0001-01-01') >= ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE, '0001-01-01')
	BEGIN 
		SET @TEMP_ADVANCE_LATEST_DATE = @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE
	
	END
	ELSE IF ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE , '0001-01-01') != '0001-01-01' AND ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE , '0001-01-01') >= ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE, '0001-01-01')
	BEGIN
		SET @TEMP_ADVANCE_LATEST_DATE = @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE
	END

	SELECT @TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_006 > @TEMP_ADVANCE_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

	SELECT @TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_010 > @TEMP_ADVANCE_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

	SET @PHASE_D_DAYS_AFTER_ADVANCE = ISNULL(@TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE,0) + ISNULL(@TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE,0)


	IF ISNULL(@TEMP_MAX_BLACK_STR_DATE , '0001-01-01') != '0001-01-01' AND ISNULL(@TEMP_MAX_BLACK_STR_DATE , '0001-01-01') >= ISNULL(@TEMP_MAX_BLUE_STR_DATE, '0001-01-01')
	BEGIN 
		SET @TEMP_STR_LATEST_DATE = @TEMP_MAX_BLACK_STR_DATE
	
	END
	ELSE IF ISNULL(@TEMP_MAX_BLUE_STR_DATE , '0001-01-01') != '0001-01-01' AND ISNULL(@TEMP_MAX_BLUE_STR_DATE , '0001-01-01') >= ISNULL(@TEMP_MAX_BLACK_STR_DATE, '0001-01-01')
	BEGIN
		SET @TEMP_STR_LATEST_DATE = @TEMP_MAX_BLUE_STR_DATE
	END

	IF ISNULL(@TEMP_STR_LATEST_DATE, '0001-01-01') != '0001-01-01'
	BEGIN
	SELECT @TEMP_BLACK_PHASE_D_DAYS_AFTER_STR = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_006 > @TEMP_STR_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

	SELECT @TEMP_BLUE_PHASE_D_DAYS_AFTER_STR = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_010 > @TEMP_STR_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

	SET @PHASE_D_DAYS_AFTER_STR = ISNULL(@TEMP_BLUE_PHASE_D_DAYS_AFTER_STR,0) + ISNULL(@TEMP_BLACK_PHASE_D_DAYS_AFTER_STR,0)


	SELECT @TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_006 > @TEMP_ADVANCE_LATEST_DATE AND ATTRIBUTE_007 < @TEMP_STR_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

	SELECT @TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_021,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_010 > @TEMP_ADVANCE_LATEST_DATE AND ATTRIBUTE_011 < @TEMP_STR_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

	SET @PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR = ISNULL(@TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR,0) + ISNULL(@TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR , 0)

	END

  END




  	SELECT @TEMP_BLUE_STR_MIN_DATE = MIN(ATTRIBUTE_008)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_STR_CLIENT_ENTITY

	SELECT @TEMP_BLACK_STR_MIN_DATE = MIN(ATTRIBUTE_006)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_013,'') !='Y' AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_STR_CLIENT_ENTITY


	IF ISNULL(@TEMP_BLUE_STR_MIN_DATE , '2099-02-02') != '2099-02-02' AND ISNULL(@TEMP_BLUE_STR_MIN_DATE , '2099-02-02') <= ISNULL(@TEMP_BLACK_STR_MIN_DATE, '2099-01-01')
	BEGIN 
		SET @STR_DATE = @TEMP_BLUE_STR_MIN_DATE
	
	END
	ELSE IF ISNULL(@TEMP_BLACK_STR_MIN_DATE , '2099-02-02') != '2099-02-02' AND ISNULL(@TEMP_BLACK_STR_MIN_DATE , '2099-02-02') <= ISNULL(@TEMP_BLUE_STR_MIN_DATE, '2099-01-01')
	BEGIN
		SET @STR_DATE = @TEMP_BLACK_STR_MIN_DATE
	END


		



		SELECT @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE = MAX(CAST(ATTRIBUTE_006 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_012 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_014,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

		SELECT @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE = MAX(CAST(ATTRIBUTE_012 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(ATTRIBUTE_015,'') !='Y' AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_ADVANCE_COURSE_CLIENT_ENTITY



	
  	DECLARE @TRACKING_SEQ_ID BIGINT  = 0
	SELECT @TRACKING_SEQ_ID = SEQ_ID 
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID  AND ISNULL(DELETED ,'N') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 11604
	--print @TOTAL_PHASE_B_DAYS
	
	IF (@TRACKING_SEQ_ID > 0)
	BEGIN
		UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		SET
				ATTRIBUTE_094 = @BASIC_COURSE_DATE,   
				ATTRIBUTE_095 = @BASIC_COURSE_CENTRE_SEQ_ID, 
				ATTRIBUTE_096 = @BASIC_COURSE_CENTRE_NAME,
				ATTRIBUTE_097 = @BASIC_COURSE_EXAM_PASSED,
				ATTRIBUTE_101 = @ADVANCE_COURSE_DATE,
				ATTRIBUTE_102 = @ADVANCE_COURSE_CENTRE_SEQ_ID,
				ATTRIBUTE_103 = @ADVANCE_COURSE_CENTRE_NAME,
				ATTRIBUTE_104 = @ADVANCE_COURSE_EXAM_PASSED,
				ATTRIBUTE_110 = @PHASE_B_DATE,
				ATTRIBUTE_098 = @PHASE_B_NOT_MORE_THAN_150_DAYS,
				ATTRIBUTE_099 = @SECTION_C_MANDATORY_TASK_COMPLETED,
				ATTRIBUTE_100 = @50_PERCENT_MANDATORY_TASK_COMPLETED,
				ATTRIBUTE_112 = @PHASE_D_DAYS_AFTER_ADVANCE,
				ATTRIBUTE_106 = @PHASE_D_DAYS_AFTER_STR,
				ATTRIBUTE_105 = @PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR,
				ATTRIBUTE_107 = @PHASE_D_DATE,
				ATTRIBUTE_108 = @PHASE_D_DAYS_NOT_MORE_THAN_150,
				ATTRIBUTE_117 = @STR_DATE,
				ATTRIBUTE_118 = @PHASE_B_DAYS_AFTER_BASIC_BEFORE_ADVANCE

		WHERE  SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID= 11604 and seq_id =@TRACKING_SEQ_ID

		EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
			@SRM_CLIENT_ENTITIES_SEQ_ID = 11604,
			@CUS_ENTITY_DATA_SEQ_ID = @TRACKING_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END

END

END






;





 --=============================================
-- Author:		<ASAD>
-- Create date: <11/12/2014>
-- Description:	<UPDATE CRETIFICATE TRACKING>
-- =============================================
CREATE PROCEDURE [dbo].[UPDATE_CRETIFICATE_TRACKING_BLUE_BLACK_SP_WITHOUT_LOCKED]
	 @APPLICATION_SEQ_ID BIGINT,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[UPDATE CRETIFICATE TRACKING] no lick'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[UPDATE CRETIFICATE TRACKING]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE
	--BLUE BOOK ENTITIES
	@BLUE_BOOK_BASIC_COURSE_CLIENT_ENTITY BIGINT = 10162,
	@BLUE_BOOK_ADVANCE_COURSE_CLIENT_ENTITY BIGINT = 10165,
	@BLUE_BOOK_PHASE_B_CLIENT_ENTITY BIGINT = 10164,
	@BLUE_BOOK_TASK_BOOK_CLIENT_ENTITY BIGINT = 10170,
	@BLUE_BOOK_PHASE_D_CLIENT_ENTITY BIGINT = 11231,
	@BLUE_BOOK_STR_CLIENT_ENTITY BIGINT = 11545,

	--@BLUE_BOOK_SIGN_OFF_CLIENT_ENTITY BIGINT = 10167,

	--BLACK BOOK ENTITIES
	@BLACK_BOOK_BASIC_COURSE_CLIENT_ENTITY BIGINT = 10174,
	@BLACK_BOOK_ADVANCE_COURSE_CLIENT_ENTITY BIGINT = 10175,
	@BLACK_BOOK_PHASE_B_CLIENT_ENTITY BIGINT = 10176,
	@BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY BIGINT = 10185,
	@BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY BIGINT = 10179,
	@BLACK_BOOK_PHASE_D_CLIENT_ENTITY BIGINT = 10177,
	@BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY BIGINT = 11234,
	@BLACK_BOOK_STR_CLIENT_ENTITY BIGINT =11544,
	--@BLACK_BOOK_SIGN_OFF_CLIENT_ENTITY BIGINT = 10178,


	--CERTIFICATE TRACKING FIELDS
	
	@BASIC_COURSE_DATE DATE = NULL,
	@BASIC_COURSE_CENTRE_SEQ_ID BIGINT = NULL,
	@BASIC_COURSE_CENTRE_NAME NVARCHAR(100) = NULL,
	@BASIC_COURSE_EXAM_PASSED NVARCHAR(3) = 'N',
	@ADVANCE_COURSE_DATE DATE = NULL,
	@ADVANCE_COURSE_CENTRE_SEQ_ID BIGINT = NULL,
	@ADVANCE_COURSE_CENTRE_NAME NVARCHAR(100) = NULL,
	@ADVANCE_COURSE_EXAM_PASSED NVARCHAR(3) = 'N',

	@PHASE_B_DATE DATE,
	@PHASE_B_NOT_MORE_THAN_150_DAYS NVARCHAR(3) = 'N',
	@SECTION_C_MANDATORY_TASK_COMPLETED NVARCHAR(3) = 'N',
	@50_PERCENT_MANDATORY_TASK_COMPLETED NVARCHAR(3) = 'N',
	@PHASE_D_DAYS_AFTER_ADVANCE BIGINT = 0,
	@PHASE_D_DAYS_AFTER_STR BIGINT = 0,
	@PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR BIGINT = 0,
	@PHASE_D_DATE DATE,
	@PHASE_D_DAYS_NOT_MORE_THAN_150 NVARCHAR(3) = 'N',

	@TEMP_MAX_BLUE_BASIC_COURSE_DATE DATE,
	@TEMP_MAX_BLACK_BASIC_COURSE_DATE DATE,
	@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE DATE,
	@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE DATE,

	@TEMP_MAX_BLUE_STR_DATE DATE,
	@TEMP_MAX_BLACK_STR_DATE DATE,

	@TEMP_MIN_BLUE_PHASE_B_DATE DATE,
	@TEMP_MIN_BLACK_PHASE_B_DATE DATE,
	@TEMP_MIN_BLUE_PHASE_D_DATE DATE,
	@TEMP_MIN_BLACK_PHASE_D_DATE DATE,
	@TEMP_BLUE_PHASE_D_DAYS_AFTER_STR BIGINT,
	@TEMP_BLACK_PHASE_D_DAYS_AFTER_STR BIGINT,
	@TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE BIGINT,
	@TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE BIGINT,
	@TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR BIGINT,
	@TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR BIGINT,


	@TEMP_ADVANCE_LATEST_DATE DATE,
	@TEMP_STR_LATEST_DATE DATE,

	@TEMP_BASIC_LATEST_DATE DATE,
	@TEMP_ADV_DAYS_LASTEST_DATE DATE,

	@SRM_CLIENTS_SEQ_ID BIGINT = 40
	
	DECLARE @CERTIFICATION_CATEGORY_SEQ_ID BIGINT
	DECLARE @CATEGORY NVARCHAR(20)

	DECLARE @STR_DATE DATE
  DECLARE @PHASE_B_DAYS_AFTER_BASIC_BEFORE_ADVANCE BIGINT = 0
  DECLARE @TEMP_BLACK_STR_MIN_DATE DATE
  DECLARE @TEMP_BLUE_STR_MIN_DATE DATE
  DECLARE @TEMP_BLACK_PHASE_B_DAYS BIGINT
  DECLARE @TEMP_BLUE_PHASE_B_DAYS BIGINT
  DECLARE @STATUS NVARCHAR(50)


	SELECT @CERTIFICATION_CATEGORY_SEQ_ID = ATTRIBUTE_007
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @APPLICATION_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID =10156

	SELECT @CATEGORY = ATTRIBUTE_006
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @CERTIFICATION_CATEGORY_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 10154


	SELECT @STATUS = ATTRIBUTE_006
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @APPLICATION_SEQ_ID

	IF (@CATEGORY = 'New' AND @APPLICATION_SEQ_ID > 0 )--AND (@STATUS = 'In Progress' Or @STATUS = 'Not Eligible' ))
	BEGIN
		print 'new..'
		-- MAX BASIC COURSE DATE
		SELECT @TEMP_MAX_BLUE_BASIC_COURSE_DATE = MAX(CAST(ATTRIBUTE_004 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_010 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_BASIC_COURSE_CLIENT_ENTITY

		SELECT @TEMP_MAX_BLACK_BASIC_COURSE_DATE = MAX(CAST(ATTRIBUTE_004 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_008 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_BASIC_COURSE_CLIENT_ENTITY

		IF ISNULL(@TEMP_MAX_BLUE_BASIC_COURSE_DATE,'0001-01-01') != '0001-01-01' 
			AND ISNULL(@TEMP_MAX_BLUE_BASIC_COURSE_DATE,'0001-01-01') >= ISNULL(@TEMP_MAX_BLACK_BASIC_COURSE_DATE,'0002-01-01')
		BEGIN
			SELECT @BASIC_COURSE_DATE = CAST(ATTRIBUTE_004 AS DATE) ,
				   @BASIC_COURSE_CENTRE_SEQ_ID = ATTRIBUTE_002 ,
				   @BASIC_COURSE_CENTRE_NAME = ATTRIBUTE_003,
				   @BASIC_COURSE_EXAM_PASSED = ATTRIBUTE_007
			FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_010 = @APPLICATION_SEQ_ID AND ATTRIBUTE_004 = @TEMP_MAX_BLUE_BASIC_COURSE_DATE AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_BASIC_COURSE_CLIENT_ENTITY

			SET @TEMP_BASIC_LATEST_DATE = @TEMP_MAX_BLUE_BASIC_COURSE_DATE
		END
		ELSE IF ISNULL(@TEMP_MAX_BLACK_BASIC_COURSE_DATE,'0001-01-01') != '0001-01-01' 
						AND ISNULL(@TEMP_MAX_BLACK_BASIC_COURSE_DATE,'0001-01-01') >= ISNULL(@TEMP_MAX_BLUE_BASIC_COURSE_DATE,'0002-01-01')
		BEGIN
			SELECT @BASIC_COURSE_DATE = CAST(ATTRIBUTE_004 AS DATE) ,
				   @BASIC_COURSE_CENTRE_SEQ_ID = ATTRIBUTE_002 ,
				   @BASIC_COURSE_CENTRE_NAME = ATTRIBUTE_003,
				   @BASIC_COURSE_EXAM_PASSED = ATTRIBUTE_007
			FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_008 = @APPLICATION_SEQ_ID AND ATTRIBUTE_004 = @TEMP_MAX_BLACK_BASIC_COURSE_DATE AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_BASIC_COURSE_CLIENT_ENTITY

			SET @TEMP_BASIC_LATEST_DATE = @TEMP_MAX_BLACK_BASIC_COURSE_DATE
		END


		--MAX ADVANCE COURSE
		SELECT @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE = MAX(CAST(ATTRIBUTE_006 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_012 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

		SELECT @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE = MAX(CAST(ATTRIBUTE_012 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

		IF ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE,'0001-01-01') != '0001-01-01' 
			AND ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE,'0001-01-01') >= ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE,'0002-01-01')
		BEGIN
			SELECT @ADVANCE_COURSE_DATE = CAST(ATTRIBUTE_006 AS DATE) ,
				   @ADVANCE_COURSE_CENTRE_SEQ_ID = ATTRIBUTE_004 ,
				   @ADVANCE_COURSE_CENTRE_NAME = ATTRIBUTE_005,
				   @ADVANCE_COURSE_EXAM_PASSED = ATTRIBUTE_009
			FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_012 = @APPLICATION_SEQ_ID AND ATTRIBUTE_006 = @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

			SET @TEMP_ADV_DAYS_LASTEST_DATE = @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE

		END
		ELSE IF ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE,'0001-01-01') != '0001-01-01' 
						AND ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE,'0001-01-01') >= ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE,'0002-01-01')
		BEGIN
			SELECT @ADVANCE_COURSE_DATE = CAST(ATTRIBUTE_012 AS DATE) ,
				   @ADVANCE_COURSE_CENTRE_SEQ_ID = ATTRIBUTE_006 ,
				   @ADVANCE_COURSE_CENTRE_NAME = ATTRIBUTE_007,
				   @ADVANCE_COURSE_EXAM_PASSED = ATTRIBUTE_011
			FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ATTRIBUTE_012 = @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

			SET @TEMP_ADV_DAYS_LASTEST_DATE = @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE

		END

		--PHASE B DATE
		SELECT @TEMP_MIN_BLUE_PHASE_B_DATE = MIN(CAST(ATTRIBUTE_008 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_018 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_B_CLIENT_ENTITY

		SELECT @TEMP_MIN_BLACK_PHASE_B_DATE = MIN(CAST(ATTRIBUTE_004 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_015 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_CLIENT_ENTITY


		IF ISNULL(@TEMP_MIN_BLUE_PHASE_B_DATE,'2099-01-01') != '2099-01-01' 
			AND ISNULL(@TEMP_MIN_BLUE_PHASE_B_DATE,'2099-01-01') <= ISNULL(@TEMP_MIN_BLACK_PHASE_B_DATE,'2098-01-01')

		BEGIN
			SET @PHASE_B_DATE = @TEMP_MIN_BLUE_PHASE_B_DATE
		END
		ELSE IF ISNULL(@TEMP_MIN_BLACK_PHASE_B_DATE,'2099-01-01') != '2099-01-01' 
			AND ISNULL(@TEMP_MIN_BLACK_PHASE_B_DATE,'2099-01-01') <= ISNULL(@TEMP_MIN_BLUE_PHASE_B_DATE,'2098-01-01')

		BEGIN
			SET @PHASE_B_DATE = @TEMP_MIN_BLACK_PHASE_B_DATE
		END

		DECLARE @TEMP_BLUE_PHASE_B_SEQ_ID BIGINT
		DECLARE @TEMP_BLACK_PHASE_B_DETAIL_SEQ_ID BIGINT


		SELECT @TEMP_BLUE_PHASE_B_SEQ_ID = SEQ_ID
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_018 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND CAST(ISNULL(ATTRIBUTE_010, 0) AS INT) > 150
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_B_CLIENT_ENTITY

		SELECT @TEMP_BLACK_PHASE_B_DETAIL_SEQ_ID = SEQ_ID
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND CAST(ISNULL(ATTRIBUTE_010, 0) AS INT) > 150
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY

		IF ISNULL(@TEMP_BLUE_PHASE_B_SEQ_ID, 0) = 0 AND ISNULL(@TEMP_BLACK_PHASE_B_DETAIL_SEQ_ID,0) = 0
		SET @PHASE_B_NOT_MORE_THAN_150_DAYS = 'Y'


		IF ISNULL(@TEMP_BASIC_LATEST_DATE, '0001-01-01') != '0001-01-01' AND ISNULL(@TEMP_ADV_DAYS_LASTEST_DATE, '0001-01-01') != '0001-01-01'
		BEGIN

		SELECT @TEMP_BLACK_PHASE_B_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_010,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_008 > @TEMP_BASIC_LATEST_DATE AND ATTRIBUTE_009 < @TEMP_ADV_DAYS_LASTEST_DATE
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY

		SELECT @TEMP_BLUE_PHASE_B_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_010,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_018 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_008 > @TEMP_BASIC_LATEST_DATE AND ATTRIBUTE_009 < @TEMP_ADV_DAYS_LASTEST_DATE
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_B_CLIENT_ENTITY

		SET @PHASE_B_DAYS_AFTER_BASIC_BEFORE_ADVANCE = ISNULL(@TEMP_BLACK_PHASE_B_DAYS,0) + ISNULL(@TEMP_BLUE_PHASE_B_DAYS,0)

		END

		--PHASE D DATE
		SELECT @TEMP_MIN_BLUE_PHASE_D_DATE = MIN(CAST(ATTRIBUTE_010 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

		SELECT @TEMP_MIN_BLACK_PHASE_D_DATE = MIN(CAST(ATTRIBUTE_013 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY


		IF ISNULL(@TEMP_MIN_BLUE_PHASE_D_DATE,'2099-01-01') != '2099-01-01' 
			AND ISNULL(@TEMP_MIN_BLUE_PHASE_D_DATE,'2099-01-01') <= ISNULL(@TEMP_MIN_BLACK_PHASE_D_DATE,'2098-01-01')

		BEGIN
			SET @PHASE_D_DATE = @TEMP_MIN_BLUE_PHASE_D_DATE
		END
		ELSE IF ISNULL(@TEMP_MIN_BLACK_PHASE_D_DATE,'2099-01-01') != '2099-01-01' 
			AND ISNULL(@TEMP_MIN_BLACK_PHASE_D_DATE,'2099-01-01') <= ISNULL(@TEMP_MIN_BLUE_PHASE_D_DATE,'2098-01-01')

		BEGIN
			SET @PHASE_D_DATE = @TEMP_MIN_BLUE_PHASE_D_DATE
		END

		DECLARE @TEMP_BLUE_PHASE_D_SEQ_ID BIGINT
		DECLARE @TEMP_BLACK_PHASE_D_DETAIL_SEQ_ID BIGINT


		SELECT @TEMP_BLUE_PHASE_D_SEQ_ID = SEQ_ID
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND CAST(ISNULL(ATTRIBUTE_030, 0) AS INT) > 150
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

		SELECT @TEMP_BLACK_PHASE_D_DETAIL_SEQ_ID = SEQ_ID
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND CAST(ISNULL(ATTRIBUTE_008, 0) AS INT) > 150
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

		IF ISNULL(@TEMP_BLUE_PHASE_D_SEQ_ID, 0) = 0 AND ISNULL(@TEMP_BLACK_PHASE_D_DETAIL_SEQ_ID,0) = 0
		SET @PHASE_D_DAYS_NOT_MORE_THAN_150 = 'Y'

		--PHASE_D_DAYS_AFTER_ADVANCE

	SELECT @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE = MAX(ATTRIBUTE_006)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_012 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

	SELECT @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE = MAX(ATTRIBUTE_012)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

	IF ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE,'2099-12-01') != '2099-12-01' OR ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE, '2099-12-01') != '2099-12-01'
	BEGIN
		
	SELECT @TEMP_MAX_BLUE_STR_DATE = MAX(ATTRIBUTE_008)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_STR_CLIENT_ENTITY

	SELECT @TEMP_MAX_BLACK_STR_DATE = MAX(ATTRIBUTE_006)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_STR_CLIENT_ENTITY


	IF ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE , '0001-01-01') != '0001-01-01' AND ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE , '0001-01-01') >= ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE, '0001-01-01')
	BEGIN 
		SET @TEMP_ADVANCE_LATEST_DATE = @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE
	
	END
	ELSE IF ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE , '0001-01-01') != '0001-01-01' AND ISNULL(@TEMP_MAX_BLUE_ADVANCE_COURSE_DATE , '0001-01-01') >= ISNULL(@TEMP_MAX_BLACK_ADVANCE_COURSE_DATE, '0001-01-01')
	BEGIN
		SET @TEMP_ADVANCE_LATEST_DATE = @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE
	END

	SELECT @TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_006 > @TEMP_ADVANCE_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

	SELECT @TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_010 > @TEMP_ADVANCE_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

	SET @PHASE_D_DAYS_AFTER_ADVANCE = ISNULL(@TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE,0) + ISNULL(@TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE,0)


	IF ISNULL(@TEMP_MAX_BLACK_STR_DATE , '0001-01-01') != '0001-01-01' AND ISNULL(@TEMP_MAX_BLACK_STR_DATE , '0001-01-01') >= ISNULL(@TEMP_MAX_BLUE_STR_DATE, '0001-01-01')
	BEGIN 
		SET @TEMP_STR_LATEST_DATE = @TEMP_MAX_BLACK_STR_DATE
	
	END
	ELSE IF ISNULL(@TEMP_MAX_BLUE_STR_DATE , '0001-01-01') != '0001-01-01' AND ISNULL(@TEMP_MAX_BLUE_STR_DATE , '0001-01-01') >= ISNULL(@TEMP_MAX_BLACK_STR_DATE, '0001-01-01')
	BEGIN
		SET @TEMP_STR_LATEST_DATE = @TEMP_MAX_BLUE_STR_DATE
	END

	IF ISNULL(@TEMP_STR_LATEST_DATE, '0001-01-01') != '0001-01-01'
	BEGIN
	SELECT @TEMP_BLACK_PHASE_D_DAYS_AFTER_STR = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_006 > @TEMP_STR_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

	SELECT @TEMP_BLUE_PHASE_D_DAYS_AFTER_STR = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_010 > @TEMP_STR_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

	SET @PHASE_D_DAYS_AFTER_STR = ISNULL(@TEMP_BLUE_PHASE_D_DAYS_AFTER_STR,0) + ISNULL(@TEMP_BLACK_PHASE_D_DAYS_AFTER_STR,0)


	SELECT @TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_006 > @TEMP_ADVANCE_LATEST_DATE AND ATTRIBUTE_007 < @TEMP_STR_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY

	SELECT @TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND ATTRIBUTE_010 > @TEMP_ADVANCE_LATEST_DATE AND ATTRIBUTE_011 < @TEMP_STR_LATEST_DATE
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

	SET @PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR = ISNULL(@TEMP_BLACK_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR,0) + ISNULL(@TEMP_BLUE_PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR , 0)

	END

  END




  	SELECT @TEMP_BLUE_STR_MIN_DATE = MIN(ATTRIBUTE_008)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_STR_CLIENT_ENTITY

	SELECT @TEMP_BLACK_STR_MIN_DATE = MIN(ATTRIBUTE_006)
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
	AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_STR_CLIENT_ENTITY


	IF ISNULL(@TEMP_BLUE_STR_MIN_DATE , '2099-02-02') != '2099-02-02' AND ISNULL(@TEMP_BLUE_STR_MIN_DATE , '2099-02-02') <= ISNULL(@TEMP_BLACK_STR_MIN_DATE, '2099-01-01')
	BEGIN 
		SET @STR_DATE = @TEMP_BLUE_STR_MIN_DATE
	
	END
	ELSE IF ISNULL(@TEMP_BLACK_STR_MIN_DATE , '2099-02-02') != '2099-02-02' AND ISNULL(@TEMP_BLACK_STR_MIN_DATE , '2099-02-02') <= ISNULL(@TEMP_BLUE_STR_MIN_DATE, '2099-01-01')
	BEGIN
		SET @STR_DATE = @TEMP_BLACK_STR_MIN_DATE
	END


		



		SELECT @TEMP_MAX_BLUE_ADVANCE_COURSE_DATE = MAX(CAST(ATTRIBUTE_006 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_012 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_ADVANCE_COURSE_CLIENT_ENTITY

		SELECT @TEMP_MAX_BLACK_ADVANCE_COURSE_DATE = MAX(CAST(ATTRIBUTE_012 AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_ADVANCE_COURSE_CLIENT_ENTITY



	
  	DECLARE @TRACKING_SEQ_ID BIGINT  = 0
	SELECT @TRACKING_SEQ_ID = SEQ_ID 
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID  AND ISNULL(DELETED ,'N') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 11604
	--print @TOTAL_PHASE_B_DAYS
	
	IF (@TRACKING_SEQ_ID > 0)
	BEGIN
		UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		SET
				ATTRIBUTE_094 = @BASIC_COURSE_DATE,   
				ATTRIBUTE_095 = @BASIC_COURSE_CENTRE_SEQ_ID, 
				ATTRIBUTE_096 = @BASIC_COURSE_CENTRE_NAME,
				ATTRIBUTE_097 = @BASIC_COURSE_EXAM_PASSED,
				ATTRIBUTE_101 = @ADVANCE_COURSE_DATE,
				ATTRIBUTE_102 = @ADVANCE_COURSE_CENTRE_SEQ_ID,
				ATTRIBUTE_103 = @ADVANCE_COURSE_CENTRE_NAME,
				ATTRIBUTE_104 = @ADVANCE_COURSE_EXAM_PASSED,
				ATTRIBUTE_110 = @PHASE_B_DATE,
				ATTRIBUTE_098 = @PHASE_B_NOT_MORE_THAN_150_DAYS,
				ATTRIBUTE_112 = @PHASE_D_DAYS_AFTER_ADVANCE,
				ATTRIBUTE_106 = @PHASE_D_DAYS_AFTER_STR,
				ATTRIBUTE_105 = @PHASE_D_DAYS_AFTER_ADVANCE_BEFORE_STR,
				ATTRIBUTE_107 = @PHASE_D_DATE,
				ATTRIBUTE_108 = @PHASE_D_DAYS_NOT_MORE_THAN_150,
				ATTRIBUTE_117 = @STR_DATE,
				ATTRIBUTE_118 = @PHASE_B_DAYS_AFTER_BASIC_BEFORE_ADVANCE

		WHERE  SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID= 11604 and seq_id =@TRACKING_SEQ_ID
		
		IF ISNULL(@SECTION_C_MANDATORY_TASK_COMPLETED,'') = 'Y'
			UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			SET 	ATTRIBUTE_099 = @SECTION_C_MANDATORY_TASK_COMPLETED
			WHERE  SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID= 11604 and seq_id =@TRACKING_SEQ_ID
		
		IF ISNULL(@50_PERCENT_MANDATORY_TASK_COMPLETED,'') = 'Y'
			UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			SET		ATTRIBUTE_100 = @50_PERCENT_MANDATORY_TASK_COMPLETED
			WHERE  SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID= 11604 and seq_id =@TRACKING_SEQ_ID
		
		
		EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
			@SRM_CLIENT_ENTITIES_SEQ_ID = 11604,
			@CUS_ENTITY_DATA_SEQ_ID = @TRACKING_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
	END

END

END



;





 --=============================================
-- Author:		<ASAD>
-- Create date: <11/11/2014>
-- Modified By: <Musawar>
-- Modified Date: <26/11/2014>
-- Description:	<UPDATE CRETIFICATE TRACKING>
-- =============================================
CREATE PROCEDURE [dbo].[UPDATE_CRETIFICATE_TRACKING_NO_LOCK]
	 @APPLICATION_SEQ_ID BIGINT,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[UPDATE CRETIFICATE TRACKING_nolock]...'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[UPDATE CRETIFICATE TRACKING]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE
	--BLUE BOOK ENTITIES
	@BLUE_BOOK_PHASE_B_CLIENT_ENTITY BIGINT = 10164,
	@BLUE_BOOK_TASK_BOOK_CLIENT_ENTITY BIGINT = 10170,
	@BLUE_BOOK_PHASE_D_CLIENT_ENTITY BIGINT = 11231,
	@BLUE_BOOK_STR_CLIENT_ENTITY BIGINT = 11545,
	@BLUE_BOOK_SIGN_OFF_CLIENT_ENTITY BIGINT = 10167,

	--BLACK BOOK ENTITIES
	@BLACK_BOOK_PHASE_B_CLIENT_ENTITY BIGINT = 10176,
	@BLACK_BOOK_PHASE_B_DETAIL_CLIENT_ENTITY BIGINT = 10185,
	@BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY BIGINT = 10179,
	@BLACK_BOOK_PHASE_D_CLIENT_ENTITY BIGINT = 10177,
	@BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY BIGINT = 11234,
	@BLACK_BOOK_STR_CLIENT_ENTITY BIGINT =11544,
	@BLACK_BOOK_SIGN_OFF_CLIENT_ENTITY BIGINT = 10178,

	--CERTIFICATE TRACKING FIELDS
	@TOTAL_PHASE_B_DAYS BIGINT = 0,
	@PHASE_B_SEA_TIME_DATE_VALID NVARCHAR(3) = 'Y',
	@TASK_DATE_WITHIN_B NVARCHAR(3) = 'N',
	@NEW_TASK_DATE_WITHIN_D NVARCHAR(3) = 'N',
	@TOTAL_PHASE_D_DAYS BIGINT = 0,
	@PHASE_D_SEA_TIME_DATE_VALID NVARCHAR(3) = 'Y',
	@DP1_CLASS NVARCHAR(3) = 'N',
	@DP1_CLASS_DAYS BIGINT = 0,
	@DP2_CLASS NVARCHAR(3) = 'N',
	@DP3_CLASS NVARCHAR(3) = 'N',
	@DP2_CLASS_DAYS BIGINT = 0,
	@DP3_CLASS_DAYS BIGINT = 0,
	@SIGNED_OFF_LAST_VESSEL NVARCHAR(3) = 'N',
	--UPGRADE
	@NEW_PHASE_D_DATA NVARCHAR(3) = 'N',
	@NEW_PHASE_D_SEA_TIME_VALID NVARCHAR(3) = 'Y',
	@TOTAL_DAYS_FOR_NEW_DP2 BIGINT = 0,
	@STR NVARCHAR(3) = 'N',
	@STR_DAYS BIGINT = 0,
	@NEW_SIGNED_OFF_LAST_VESSEL NVARCHAR(3) = 'N',

	@SRM_CLIENTS_SEQ_ID BIGINT = 40
	
	DECLARE @CERTIFICATION_CATEGORY_SEQ_ID BIGINT
	DECLARE @CATEGORY NVARCHAR(20)
	DECLARE @TEMP_BLUE_PHASE_B_DAYS BIGINT
	DECLARE @TEMP_BLACK_PHASE_B_DAYS BIGINT
	DECLARE @TEMP_BLUE_PHASE_D_DAYS BIGINT
	DECLARE @TEMP_BLACK_PHASE_D_DAYS BIGINT
	DECLARE @TEMP_BLUE_DP1_DAYS BIGINT = 0
	DECLARE @TEMP_BLACK_DP1_DAYS BIGINT = 0
	DECLARE @TEMP_BLUE_DP2_DAYS BIGINT = 0
	DECLARE @TEMP_BLUE_DP3_DAYS BIGINT = 0
	DECLARE @TEMP_BLACK_DP2_DAYS BIGINT = 0
	DECLARE @TEMP_BLACK_DP3_DAYS BIGINT = 0
	DECLARE @TEMP_BLUE_STR_DAYS BIGINT =0
	DECLARE @TEMP_BLACK_STR_DAYS BIGINT = 0

	DECLARE @BLACK_BOOK_TASK_BOOK_SEQ_ID BIGINT
	DECLARE @BLACK_BOOK_DATE NVARCHAR(50)

	DECLARE @BLACK_TASK_BOOK_SEQ BIGINT = 0
	DECLARE @BLUE_BOOK_TASK_BOOK_SEQ_ID BIGINT
	DECLARE @BLUE_BOOK_DATE NVARCHAR(50)

	DECLARE @BLACK_BOOK_PHASE_D_SEQ_ID BIGINT
	DECLARE @BLACK_BOOK_PHASE_D_FROM_DATE NVARCHAR(50)
	DECLARE @BLACK_BOOK_PHASE_D_TO_DATE NVARCHAR(50)



	SELECT @CERTIFICATION_CATEGORY_SEQ_ID = ATTRIBUTE_007
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @APPLICATION_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID =10156

	SELECT @CATEGORY = ATTRIBUTE_006
	FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
