		SELECT  SEQ_ID,ATTRIBUTE_010 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_006 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_TASK_BOOK_CLIENT_ENTITY

		OPEN CUR_BLACK_TASK_BOOK_UPGRADE 
		FETCH NEXT FROM CUR_BLACK_TASK_BOOK_UPGRADE 
		INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID, @BLACK_BOOK_DATE
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
		--IF DETAIL NOT EXIST THEN WHAT TO DO......
	
			IF EXISTS (SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_013,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_014,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE))
		BEGIN
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
		BEGIN
			IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_010,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_011,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLACK_BOOK_DATE,'1947-01-01') AS DATE)))
		BEGIN	
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
			SET @NEW_TASK_DATE_WITHIN_D = 'N'
		END
		FETCH NEXT FROM CUR_BLACK_TASK_BOOK_UPGRADE INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID,@BLACK_BOOK_DATE
		END

		CLOSE CUR_BLACK_TASK_BOOK_UPGRADE 
		DEALLOCATE CUR_BLACK_TASK_BOOK_UPGRADE
	END
	ELSE
	BEGIN
		
		DECLARE CUR_BLUE_TASK_BOOK_UPGRADE CURSOR STATIC FOR
		SELECT  SEQ_ID,ATTRIBUTE_014 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_TASK_BOOK_CLIENT_ENTITY

		OPEN CUR_BLUE_TASK_BOOK_UPGRADE 
		FETCH NEXT FROM CUR_BLUE_TASK_BOOK_UPGRADE 
		INTO @BLUE_BOOK_TASK_BOOK_SEQ_ID, @BLUE_BOOK_DATE
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
		--IF DETAIL NOT EXIST THEN WHAT TO DO......
	
			IF EXISTS (SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID  AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_013,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_014,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE))
		BEGIN
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
		BEGIN
			IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
			WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID  AND ISNULL(DELETED ,'') != 'Y' 
			AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY
			AND CAST(ISNULL(ATTRIBUTE_010,'2050-01-01') AS DATE) <=  CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(ATTRIBUTE_011,'2050-01-01') AS DATE) >=CAST(ISNULL(@BLUE_BOOK_DATE,'1947-01-01') AS DATE)))
		BEGIN	
			SET @NEW_TASK_DATE_WITHIN_D = 'Y'
		END
		ELSE
			SET @NEW_TASK_DATE_WITHIN_D = 'N'
		END
		FETCH NEXT FROM CUR_BLUE_TASK_BOOK_UPGRADE INTO @BLACK_BOOK_TASK_BOOK_SEQ_ID,@BLACK_BOOK_DATE
		END

		CLOSE CUR_BLUE_TASK_BOOK_UPGRADE 
		DEALLOCATE CUR_BLUE_TASK_BOOK_UPGRADE

	END

		SELECT @TEMP_BLUE_PHASE_D_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_030,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID  AND ISNULL(DELETED ,'') != 'Y' AND ( ATTRIBUTE_009 LIKE '%2' OR ATTRIBUTE_009 LIKE '%3')
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

		SELECT @TEMP_BLACK_PHASE_D_DAYS = SUM(CAST(ISNULL(ATTRIBUTE_008,0) AS BIGINT))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID  AND ISNULL(DELETED ,'') != 'Y' AND ( ATTRIBUTE_020 LIKE '%2' OR ATTRIBUTE_020 LIKE '%3')
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY


		
		SET @TOTAL_DAYS_FOR_NEW_DP2 = SUM(@TEMP_BLUE_PHASE_D_DAYS + @TEMP_BLACK_PHASE_D_DAYS)

		IF (@TOTAL_DAYS_FOR_NEW_DP2  > 0)
		BEGIN
			SET @NEW_PHASE_D_DATA = 'Y'

			IF(EXISTS(SELECT  SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY))
			BEGIN
				DECLARE CUR_BLACK_BOOK_PHASE_D CURSOR STATIC FOR

				SELECT  SEQ_ID,ATTRIBUTE_013,ATTRIBUTE_014 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
				WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y' 
				AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY

				OPEN CUR_BLACK_BOOK_PHASE_D 
				FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_D INTO @BLACK_BOOK_PHASE_D_SEQ_ID,@BLACK_BOOK_PHASE_D_FROM_DATE,@BLACK_BOOK_PHASE_D_TO_DATE
				WHILE @@FETCH_STATUS = 0
				BEGIN
					--IF DETAIL NOT EXIST THEN WHAT TO DO......
					IF(EXISTS(SELECT SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
					WHERE ISNULL(DELETED ,'') != 'Y' 
					AND ATTRIBUTE_011 = @BLACK_BOOK_PHASE_D_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
					AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_DETAIL_CLIENT_ENTITY
					AND (CAST(ISNULL(ATTRIBUTE_006,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_D_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_D_TO_DATE,'1947-01-01') AS DATE) 
					OR CAST(ISNULL(ATTRIBUTE_007,'2050-01-01') AS DATE) NOT BETWEEN CAST(ISNULL(@BLACK_BOOK_PHASE_D_FROM_DATE,'1947-01-01') AS DATE) AND CAST(ISNULL(@BLACK_BOOK_PHASE_D_TO_DATE,'1947-01-01') AS DATE))))
				BEGIN
					SET @PHASE_D_SEA_TIME_DATE_VALID = 'N'
				END
				ELSE
					SET @PHASE_D_SEA_TIME_DATE_VALID = 'Y'

				FETCH NEXT FROM CUR_BLACK_BOOK_PHASE_D INTO @BLACK_BOOK_PHASE_D_SEQ_ID,@BLACK_BOOK_PHASE_D_FROM_DATE,@BLACK_BOOK_PHASE_D_TO_DATE
				END

				CLOSE CUR_BLACK_BOOK_PHASE_D 
				DEALLOCATE CUR_BLACK_BOOK_PHASE_D
			END
		END
		ELSE
			SET @NEW_PHASE_D_SEA_TIME_VALID = 'N'
END

	DECLARE @TEMP_BLUE_LEFT_DATE DATE
	DECLARE @TEMP_BLACK_LEFT_DATE DATE
	DECLARE @BLUE_D_SEQ_ID BIGINT = 0
	DECLARE @BLUE_SHIP BIGINT = 0
	DECLARE @BLACK_D_SEQ_ID BIGINT = 0
	DECLARE @BLACK_SHIP BIGINT = 0
	DECLARE @BLUE_SIGN_OFF_SEQ_ID BIGINT =0
	DECLARE @BLUE_SIGN_OFF_SHIP BIGINT = 0
	DECLARE @BLACK_SIGN_OFF_SEQ_ID BIGINT = 0
	DECLARE @BLACK_SIGN_OFF_SHIP BIGINT = 0
	DECLARE @TEMP_SIGN_OFF_FLAG NVARCHAR(3) = 'N'


	SELECT @TEMP_BLUE_LEFT_DATE = MAX(CAST(ISNULL(ATTRIBUTE_011,'0001-01-01') AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY

	PRINT 'BLUE @TEMP_BLUE_LEFT_DATE'
	PRINT @TEMP_BLUE_LEFT_DATE
	
	SELECT @TEMP_BLACK_LEFT_DATE = MAX(CAST(ISNULL(ATTRIBUTE_014,'0001-01-01') AS DATE))
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
	PRINT @TEMP_BLACK_LEFT_DATE
	IF (@TEMP_BLUE_LEFT_DATE != CAST('0001-01-01' AS DATE) AND CAST(ISNULL(@TEMP_BLUE_LEFT_DATE,'0001-01-01') AS DATE) > CAST(ISNULL(@TEMP_BLACK_LEFT_DATE,'0001-01-01') AS DATE))
	BEGIN
		PRINT 'SIGN OFF 1'
		SELECT @BLUE_D_SEQ_ID = SEQ_ID ,@BLUE_SHIP = ISNULL(ATTRIBUTE_006,0)
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_PHASE_D_CLIENT_ENTITY
		AND CAST(ISNULL(ATTRIBUTE_011,'0002-01-01') AS DATE) = CAST(ISNULL(@TEMP_BLUE_LEFT_DATE,'0002-01-01')AS DATE)

	END
	ELSE IF (@TEMP_BLACK_LEFT_DATE != CAST('0001-01-01' AS DATE) AND  CAST(ISNULL(@TEMP_BLACK_LEFT_DATE,'0002-01-01')AS DATE) >= CAST(ISNULL(@TEMP_BLUE_LEFT_DATE,'0002-01-01')AS DATE))
	BEGIN
		PRINT 'SIGN OFF 2'
		SELECT @BLACK_D_SEQ_ID = SEQ_ID ,@BLACK_SHIP = ISNULL(ATTRIBUTE_006,0)
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_PHASE_D_CLIENT_ENTITY
		AND CAST(ISNULL(ATTRIBUTE_014,'0002-01-01') AS DATE) = CAST(ISNULL(@TEMP_BLACK_LEFT_DATE,'0002-01-01')AS DATE)
	END
	ELSE
	BEGIN
		PRINT 'SIGN OFF ELSE TO N'
		SET @TEMP_SIGN_OFF_FLAG = 'N'
	END

		SELECT @BLUE_SIGN_OFF_SEQ_ID = SEQ_ID ,@BLUE_SIGN_OFF_SHIP = ISNULL(ATTRIBUTE_014,0)--22052795	18148614
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLUE_BOOK_SIGN_OFF_CLIENT_ENTITY

	IF (@BLUE_D_SEQ_ID > 0 AND @BLUE_SIGN_OFF_SEQ_ID > 0 AND @BLUE_SHIP > 0 AND @BLUE_SHIP = @BLUE_SIGN_OFF_SHIP)
	BEGIN
		PRINT '@TEMP_SIGN_OFF_FLAG'
		SET @TEMP_SIGN_OFF_FLAG = 'Y'
	END
	ELSE IF(@BLACK_D_SEQ_ID > 0 AND @BLUE_SIGN_OFF_SEQ_ID > 0 AND @BLACK_SHIP > 0 AND @BLACK_SHIP = @BLUE_SIGN_OFF_SHIP)
	BEGIN
		PRINT '@TEMP_SIGN_OFF_FLAG1'
		SET @TEMP_SIGN_OFF_FLAG = 'Y'
	END
	ELSE
	BEGIN
		PRINT '@TEMP_SIGN_OFF_FLAG ELSE'
		SELECT @BLACK_SIGN_OFF_SEQ_ID = SEQ_ID ,@BLACK_SIGN_OFF_SHIP = ISNULL(ATTRIBUTE_027,0)
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID AND ISNULL(DELETED ,'') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @BLACK_BOOK_SIGN_OFF_CLIENT_ENTITY

		IF (@BLUE_D_SEQ_ID > 0 AND @BLACK_SIGN_OFF_SEQ_ID > 0 AND @BLUE_SHIP > 0 AND @BLUE_SHIP = @BLACK_SIGN_OFF_SHIP)
		BEGIN
			SET @TEMP_SIGN_OFF_FLAG = 'Y'
		END
		ELSE IF(@BLACK_D_SEQ_ID > 0 AND @BLACK_SIGN_OFF_SEQ_ID > 0 AND @BLACK_SHIP > 0 AND @BLACK_SHIP = @BLACK_SIGN_OFF_SHIP)
		BEGIN
			SET @TEMP_SIGN_OFF_FLAG = 'Y'
		END
		ELSE
			SET @TEMP_SIGN_OFF_FLAG = 'N'
	END
	PRINT '@TEMP_SIGN_OFF_FLAG IS ' + @TEMP_SIGN_OFF_FLAG
	IF (@CATEGORY = 'New' AND @APPLICATION_SEQ_ID > 0)
		SET @SIGNED_OFF_LAST_VESSEL = @TEMP_SIGN_OFF_FLAG
	IF (@CATEGORY = 'Upgrade' AND @APPLICATION_SEQ_ID > 0)
		SET @SIGNED_OFF_LAST_VESSEL = @TEMP_SIGN_OFF_FLAG
	
	DECLARE @TRACKING_SEQ_ID BIGINT  = 0
	SELECT @TRACKING_SEQ_ID = SEQ_ID 
		FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		WHERE ATTRIBUTE_002 = @APPLICATION_SEQ_ID  AND ISNULL(DELETED ,'N') != 'Y'
		AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = 11604
	print @TOTAL_PHASE_B_DAYS
	
	IF (@TRACKING_SEQ_ID > 0)
	BEGIN
		UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		SET
				ATTRIBUTE_011 = @PHASE_B_SEA_TIME_DATE_VALID,   
				ATTRIBUTE_036 = @TOTAL_PHASE_B_DAYS, 
				ATTRIBUTE_015 = @TASK_DATE_WITHIN_B,
				ATTRIBUTE_029 = @NEW_TASK_DATE_WITHIN_D,
				ATTRIBUTE_037 = @TOTAL_PHASE_D_DAYS,
				ATTRIBUTE_012 = @PHASE_D_SEA_TIME_DATE_VALID,
				ATTRIBUTE_019 = @DP1_CLASS,
				ATTRIBUTE_025 = @DP1_CLASS_DAYS,
				ATTRIBUTE_020 = @DP2_CLASS,
				ATTRIBUTE_022 = @DP2_CLASS_DAYS,
				ATTRIBUTE_021 = @DP3_CLASS,
				ATTRIBUTE_023 = @DP3_CLASS_DAYS,
				ATTRIBUTE_024 = 0,--TOTAL ACTIVE_DAYS
				ATTRIBUTE_026 = @NEW_PHASE_D_DATA,
				ATTRIBUTE_031 = @NEW_PHASE_D_SEA_TIME_VALID,
				ATTRIBUTE_027 = @TOTAL_DAYS_FOR_NEW_DP2,
				ATTRIBUTE_038 = @STR,
				ATTRIBUTE_039 = @STR_DAYS,
				ATTRIBUTE_041 = @NEW_SIGNED_OFF_LAST_VESSEL,
				ATTRIBUTE_040 = @SIGNED_OFF_LAST_VESSEL			
		WHERE  SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID= 11604 and seq_id =@TRACKING_SEQ_ID

		EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
			@SRM_CLIENT_ENTITIES_SEQ_ID = 11604,
			@CUS_ENTITY_DATA_SEQ_ID = @TRACKING_SEQ_ID,
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT


			EXEC [dbo].[UPDATE_CRETIFICATE_TRACKING_BLUE_BLACK_SP_WITHOUT_LOCKED] @APPLICATION_SEQ_ID,null,null



	END
END






;



-- *****************************************************************************************************************
-- Created By: Nimra Azeem
-- Date Created: 13/01/2026
-- Summary: A process to update Icons and Banner Colors on CRM from Membership lookups
--******************************************************************************************************************

CREATE PROCEDURE [dbo].[UPDATE_CRM_ICONS_AND_COLORS]
	@p_CATEGORY_RECORD_ID BIGINT,						-- SEQ_ID OF MEMBER_CATEGORY
	@p_SUBS_BAND_RECORD_ID BIGINT,						-- SEQ_ID OF SUBSCRIPTION_BAND
	@p_MEMBER_STATUS_RECORD_ID BIGINT,					-- SEQ_ID OF MEMBER_STATUS
	@p_MEMBER_TYPE_RECORD_ID BIGINT,					-- SEQ_ID OF MEMBER_TYPE
	@p_ICON NVARCHAR(MAX),								-- ICON OF LOOKUP
	@p_COLOR NVARCHAR(200),								-- COLOR OF LOOKUP

	@p_USERS_EMAIL NVARCHAR(200)						-- EMAIL OF oomi USER
AS
BEGIN
	DECLARE @p_CLIENT_ID BIGINT

	DECLARE @ACCOUNT_ENTITY_SEQ_ID BIGINT = 112715
	DECLARE @CONTACT_ENTITY_SEQ_ID BIGINT = 112718
	
	DECLARE @CONTACT_CATEGORY_ATTRIBUTE_SEQ_ID BIGINT = 3061831
	DECLARE @CONTACT_MEMBER_STATUS_ATTRIBUTE_SEQ_ID BIGINT = 3061835
	DECLARE @CONTACT_BAND_ATTRIBUTE_SEQ_ID BIGINT = 3061833
	DECLARE @ACCOUNT_CATEGORY_ATTRIBUTE_SEQ_ID BIGINT = 3062502
	DECLARE @ACCOUNT_MEMBER_STATUS_ATTRIBUTE_SEQ_ID BIGINT = 3062506
	DECLARE @ACCOUNT_BAND_ATTRIBUTE_SEQ_ID BIGINT = 3062504
	DECLARE @CONTACT_MEMBER_ATTRIBUTE_SEQ_ID BIGINT = 3061829
	DECLARE @ACCOUNT_MEMBER_ATTRIBUTE_SEQ_ID BIGINT = 3062500
	DECLARE @MEMBER_MEMBER_TYPE_ATTRIBUTE_SEQ_ID BIGINT = 3061542

	DECLARE @strSQL NVARCHAR(MAX)

	-- Get Client ID on the basis of User Email
	SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USERS_EMAIL
	
	--If Category Icon
	IF(ISNULL(@p_CATEGORY_RECORD_ID, 0) != 0)
	BEGIN
		--Updating CATEGORY ICONS ON CONTACT
		SET @strSQL = 'UPDATE A SET A.ATTRIBUTE_166 = ''' + CAST(ISNULL(@p_ICON, '') AS NVARCHAR(MAX))+ ''' FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
		INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES P WITH (NOLOCK) ON P.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL(@CONTACT_CATEGORY_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND P.ATTRIBUTE_DECIMAL = ' + CAST(ISNULL(@p_CATEGORY_RECORD_ID, 0) AS NVARCHAR(10))+ '
		WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y'''
		PRINT @strSQL
		EXEC sp_executesql @strSQL, N'@p_CATEGORY_RECORD_ID BIGINT', @p_CATEGORY_RECORD_ID

		--Updating CATEGORY ICONS ON ACCOUNT
		SET @strSQL = 'UPDATE A SET A.ATTRIBUTE_134 = ''' + CAST(ISNULL(@p_ICON, '') AS NVARCHAR(MAX))+ ''' FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
		INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES P WITH (NOLOCK) ON P.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL(@ACCOUNT_CATEGORY_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND P.ATTRIBUTE_DECIMAL = ' + CAST(ISNULL(@p_CATEGORY_RECORD_ID, 0) AS NVARCHAR(10))+ '
		WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y'''
		PRINT @strSQL
		EXEC sp_executesql @strSQL, N'@p_CATEGORY_RECORD_ID BIGINT', @p_CATEGORY_RECORD_ID

	END

	--If Subs. Band Icon
	IF(ISNULL(@p_SUBS_BAND_RECORD_ID, 0) != 0)
	BEGIN
		--Updating BAND ICONS ON CONTACT
		SET @strSQL = 'UPDATE A SET A.ATTRIBUTE_164 = ''' + CAST(ISNULL(@p_ICON, '') AS NVARCHAR(MAX))+ ''' FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
		INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES P WITH (NOLOCK) ON P.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL(@CONTACT_BAND_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND P.ATTRIBUTE_DECIMAL = ' + CAST(ISNULL(@p_SUBS_BAND_RECORD_ID, 0) AS NVARCHAR(10))+ '
		WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y'''
		PRINT @strSQL
		EXEC sp_executesql @strSQL, N'@p_SUBS_BAND_RECORD_ID BIGINT', @p_SUBS_BAND_RECORD_ID

		--Updating BAND ICONS ON ACCOUNT
		SET @strSQL = 'UPDATE A SET A.ATTRIBUTE_132 = ''' + CAST(ISNULL(@p_ICON, '') AS NVARCHAR(MAX))+ ''' FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
		INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES P WITH (NOLOCK) ON P.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL(@ACCOUNT_BAND_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND P.ATTRIBUTE_DECIMAL = ' + CAST(ISNULL(@p_SUBS_BAND_RECORD_ID, 0) AS NVARCHAR(10))+ '
		WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y'''
		PRINT @strSQL
		EXEC sp_executesql @strSQL, N'@p_SUBS_BAND_RECORD_ID BIGINT', @p_SUBS_BAND_RECORD_ID
	END

	IF(ISNULL(@p_MEMBER_STATUS_RECORD_ID, 0) != 0)
	BEGIN
			--Updating STATUS ICONS ON CONTACT
			SET @strSQL = 'UPDATE A SET A.ATTRIBUTE_165 = ''' + CAST(ISNULL(@p_ICON, '') AS NVARCHAR(MAX))+ ''' FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
			INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES P WITH (NOLOCK) ON P.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL(@CONTACT_MEMBER_STATUS_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND P.ATTRIBUTE_DECIMAL = ' + CAST(ISNULL(@p_MEMBER_STATUS_RECORD_ID, 0) AS NVARCHAR(10))+ '
			WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y'''
			PRINT @strSQL
			EXEC sp_executesql @strSQL, N'@p_MEMBER_STATUS_RECORD_ID BIGINT', @p_MEMBER_STATUS_RECORD_ID

			--Updating STATUS ICONS ON ACCOUNT
			SET @strSQL = 'UPDATE A SET A.ATTRIBUTE_133 = ''' + CAST(ISNULL(@p_ICON, '') AS NVARCHAR(MAX))+ ''' FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
			INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES P WITH (NOLOCK) ON P.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL(@ACCOUNT_MEMBER_STATUS_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND P.ATTRIBUTE_DECIMAL = ' + CAST(ISNULL(@p_MEMBER_STATUS_RECORD_ID, 0) AS NVARCHAR(10))+ '
			WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y'''
			PRINT @strSQL
			EXEC sp_executesql @strSQL, N'@p_MEMBER_STATUS_RECORD_ID BIGINT', @p_MEMBER_STATUS_RECORD_ID
		
			--Updating STATUS COLOR ON CONTACT
			SET @strSQL = 'UPDATE A SET A.COLOR = ''' + CAST(ISNULL(@p_COLOR, '') AS NVARCHAR(MAX))+ ''' , A.ATTRIBUTE_230 =  ''' + CAST(ISNULL(@p_COLOR, '') AS NVARCHAR(MAX))+ ''' FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
			INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES P WITH (NOLOCK) ON P.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL(@CONTACT_MEMBER_STATUS_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND P.ATTRIBUTE_DECIMAL = ' + CAST(ISNULL(@p_MEMBER_STATUS_RECORD_ID, 0) AS NVARCHAR(10))+ '
			WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y'''
			PRINT @strSQL
			EXEC sp_executesql @strSQL, N'@p_MEMBER_STATUS_RECORD_ID BIGINT', @p_MEMBER_STATUS_RECORD_ID
			
			--Updating STATUS COLOR ON ACCOUNT
			SET @strSQL = 'UPDATE A SET  A.COLOR = ''' + CAST(ISNULL(@p_COLOR, '') AS NVARCHAR(MAX))+ ''' , A.ATTRIBUTE_154 =  ''' + CAST(ISNULL(@p_COLOR, '') AS NVARCHAR(MAX))+ ''' FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
			INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES P WITH (NOLOCK) ON P.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL(@ACCOUNT_MEMBER_STATUS_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND P.ATTRIBUTE_DECIMAL = ' + CAST(ISNULL(@p_MEMBER_STATUS_RECORD_ID, 0) AS NVARCHAR(10))+ '
			WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y'''
			PRINT @strSQL
			EXEC sp_executesql @strSQL, N'@p_MEMBER_STATUS_RECORD_ID BIGINT', @p_MEMBER_STATUS_RECORD_ID
	END

	IF(ISNULL(@p_MEMBER_TYPE_RECORD_ID, 0) != 0)
	BEGIN
				--Updating CATEGORY ICONS ON CONTACT
				SET @strSQL = 'UPDATE A SET A.ATTRIBUTE_163 = ''' + CAST(ISNULL(@p_ICON, '') AS NVARCHAR(MAX))+ ''' FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
				INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES MEM ON MEM.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =' + CAST(ISNULL( @CONTACT_MEMBER_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND MEM.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND ISNULL(MEM.ATTRIBUTE_DECIMAL, 0.00)!= 0.00
				INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES MT ON MT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL( @MEMBER_MEMBER_TYPE_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ '  AND MT.CUS_ENTITY_DATA_SEQ_ID = MEM.ATTRIBUTE_DECIMAL AND ISNULL(MT.ATTRIBUTE_DECIMAL, 0.00) = @p_MEMBER_TYPE_RECORD_ID
				WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@CONTACT_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y'''
				PRINT @strSQL
				EXEC sp_executesql @strSQL, N'@p_MEMBER_TYPE_RECORD_ID BIGINT', @p_MEMBER_TYPE_RECORD_ID
		

				--Updating CATEGORY ICONS ON ACCOUNT
				SET @strSQL = 'UPDATE A SET A.ATTRIBUTE_131 = ''' + CAST(ISNULL(@p_ICON, '') AS NVARCHAR(MAX))+ ''' FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
				INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES MEM ON MEM.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID =' + CAST(ISNULL( @ACCOUNT_MEMBER_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND MEM.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND ISNULL(MEM.ATTRIBUTE_DECIMAL, 0.00)!= 0.00
				INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES MT ON MT.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL( @MEMBER_MEMBER_TYPE_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ '  AND MT.CUS_ENTITY_DATA_SEQ_ID = MEM.ATTRIBUTE_DECIMAL AND ISNULL(MT.ATTRIBUTE_DECIMAL, 0.00) = @p_MEMBER_TYPE_RECORD_ID
				WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@ACCOUNT_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y'''
				PRINT @strSQL
				EXEC sp_executesql @strSQL, N'@p_MEMBER_TYPE_RECORD_ID BIGINT', @p_MEMBER_TYPE_RECORD_ID
	END

END
;





CREATE PROC [dbo].[UPDATE_EMPTY_ACCOUNT_NAME_FOR_MAILING_DISK]
@m_JOB_ID BigInt
AS
UPDATE X 
SET
ATTRIBUTE_016 = NULL
FROM [SRM-CustomEntities]..CUS_ENTITY_DATA X
WHERE SRM_CLIENT_ENTITIES_SEQ_ID = 2541
AND ISNULL(ATTRIBUTE_017,0) > 0 --CONTACT
AND ISNULL(ATTRIBUTE_015,0) = 0 --ACCOUNT
AND ATTRIBUTE_016 IS NOT NULL
AND ISNULL(DELETED,'N') = 'N'


;



---- *****************************************************************************************************************
---- Created By: Nimra Azeem
---- Date Created: 25/02/2026
---- Summary: A process to update WFL Output dynamically for Print Delivery Note
----******************************************************************************************************************

CREATE PROCEDURE [dbo].[UPDATE_OUTPUT_FOR_PRINT_DELIVERY_NOTE]
	@p_SALES_ORDER_RECORD_ID BIGINT,					-- SEQ_ID OF SALES_ORDER
	@p_USERS_EMAIL NVARCHAR(200),						-- EMAIL OF oomi USER
	@WFL_OUTPUT_SEQ_ID BIGINT							-- WFL OUTPUT SEQ ID
AS
BEGIN
	--DECLARE @p_SALES_ORDER_RECORD_ID BIGINT = 75540
	--DECLARE @p_USERS_EMAIL NVARCHAR(200) = 'smart@oomi.co.uk'
	--DECLARE @WFL_OUTPUT_SEQ_ID BIGINT = 12424123

	DECLARE @p_CLIENT_ID BIGINT 
	DECLARE @strSQL NVARCHAR(MAX)
	DECLARE @SALES_ORDER_ENTITY_SEQ_ID BIGINT = 113057
	DECLARE @SALES_ORDER_DETAIL_ENTITY_SEQ_ID BIGINT = 113058
	
	DECLARE @SALES_ORDER_DETAIL_SALES_ORDER_ATTRIBUTE_SEQ_ID BIGINT = 3069627
	
	DECLARE @SALES_ORDER_DETAIL_NAME NVARCHAR(100)
	DECLARE @PRODUCT_NAME NVARCHAR(100)
	DECLARE @PRICE_TYPE_NAME NVARCHAR(100)
	DECLARE @UNIT_PRICE MONEY
	DECLARE @QUANTITY INT
	DECLARE @TOTAL_AMOUNT MONEY
	DECLARE @DISCOUNT_AMOUNT MONEY
	DECLARE @NET_AMOUNT MONEY
	DECLARE @VAT_AMOUNT MONEY
	DECLARE @VAT_RATE_NAME NVARCHAR(100)
	DECLARE @VAT_PERCENTAGE DECIMAL(8,2)
	DECLARE @GROSS_AMOUNT MONEY
	DECLARE @WEIGHT__GRAMS_  DECIMAL(8,2)
	DECLARE @COUNTER BIGINT = 1
	DECLARE @STARTING_POINT INT = 51
	

	-- Get Client ID on the basis of User Email
	SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USERS_EMAIL
	
	IF(ISNULL(@p_SALES_ORDER_RECORD_ID, 0) != 0)
	BEGIN
		SET @strSQL = 'SELECT A.ATTRIBUTE_001, ATTRIBUTE_005,ATTRIBUTE_007, ATTRIBUTE_008,ATTRIBUTE_009,ATTRIBUTE_010,ATTRIBUTE_011,ATTRIBUTE_012,
		ATTRIBUTE_014,ATTRIBUTE_015,ATTRIBUTE_016,ATTRIBUTE_017,ATTRIBUTE_024 FROM [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ '].dbo.CUS_ENTITY_DATA A
		INNER JOIN [SRM-CustomEntities_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+ ']..CUS_PIVOT_NON_UNIQUE_INDEXES P WITH (NOLOCK) ON P.CUS_ENTITY_DATA_SEQ_ID = A.SEQ_ID AND P.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = ' + CAST(ISNULL(@SALES_ORDER_DETAIL_SALES_ORDER_ATTRIBUTE_SEQ_ID, 0) AS NVARCHAR(10))+ ' AND P.ATTRIBUTE_DECIMAL = ' + CAST(ISNULL(@p_SALES_ORDER_RECORD_ID, 0) AS NVARCHAR(10))+ '
		WHERE A.SRM_CLIENT_ENTITIES_SEQ_ID =' + CAST(@SALES_ORDER_DETAIL_ENTITY_SEQ_ID AS NVARCHAR(100))  + ' AND ISNULL(A.DELETED, ''N'')!= ''Y''
		ORDER BY ISNULL(A.ATTRIBUTE_029,0)'

		CREATE TABLE #TempSalesOrderDetails
		(
			SALES_ORDER_DETAIL_NAME NVARCHAR(100),
			PRODUCT_NAME NVARCHAR(100), 
			PRICE_TYPE_NAME NVARCHAR(100),
			UNIT_PRICE MONEY,
			QUANTITY INT,
			TOTAL_AMOUNT MONEY,
			DISCOUNT_AMOUNT MONEY,
			NET_AMOUNT MONEY,
			VAT_RATE_NAME NVARCHAR(100),
			VAT_PERCENTAGE DECIMAL(8,2),
			VAT_AMOUNT MONEY,
			GROSS_AMOUNT MONEY,
			WEIGHT__GRAMS_  DECIMAL(8,2)
		)

		INSERT INTO #TempSalesOrderDetails
		EXEC sp_executesql @strSQL, N'@p_SALES_ORDER_RECORD_ID BIGINT', @p_SALES_ORDER_RECORD_ID

		DECLARE curGeneral CURSOR LOCAL STATIC FOR 
		SELECT *
		FROM #TempSalesOrderDetails
		ORDER BY PRODUCT_NAME
		
		OPEN curGeneral                                                             
		FETCH NEXT FROM curGeneral INTO @SALES_ORDER_DETAIL_NAME,@PRODUCT_NAME, @PRICE_TYPE_NAME,@UNIT_PRICE,@QUANTITY,@TOTAL_AMOUNT,@DISCOUNT_AMOUNT,@NET_AMOUNT,@VAT_RATE_NAME,@VAT_PERCENTAGE,@VAT_AMOUNT,@GROSS_AMOUNT,@WEIGHT__GRAMS_

		WHILE (@@Fetch_Status = 0)       
		BEGIN    
			SET @COUNTER = @COUNTER + 1
			SELECT @SALES_ORDER_DETAIL_NAME,@PRODUCT_NAME, @PRICE_TYPE_NAME,@UNIT_PRICE,@QUANTITY,@TOTAL_AMOUNT,@DISCOUNT_AMOUNT,@NET_AMOUNT,@VAT_RATE_NAME,@VAT_PERCENTAGE,@VAT_AMOUNT,@GROSS_AMOUNT,@WEIGHT__GRAMS_

			SET @strSQL = 'UPDATE WFL_OUTPUT
			SET ATTRIBUTE_0'+ CAST(@STARTING_POINT AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@PRODUCT_NAME AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+1 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@PRICE_TYPE_NAME AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+2 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@UNIT_PRICE AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+3 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@QUANTITY AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+4 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@TOTAL_AMOUNT AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+5 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@DISCOUNT_AMOUNT AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+6 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@NET_AMOUNT AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+7 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@VAT_RATE_NAME AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+8 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@VAT_PERCENTAGE AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+9 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@VAT_AMOUNT AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+10 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@GROSS_AMOUNT AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+11 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@WEIGHT__GRAMS_ AS nvarchar(100)), '') + ''',
			ATTRIBUTE_0'+ CAST(@STARTING_POINT+12 AS nvarchar(100)) + ' = ''' + ISNULL(CAST(@SALES_ORDER_DETAIL_NAME AS nvarchar(100)), '') + '''
			FROM [SRM-Workflow].dbo.[WFL_OUTPUT] WFL_OUTPUT
			WHERE SEQ_ID = '+ CAST(@WFL_OUTPUT_SEQ_ID AS NVARCHAR(100)) +''

			PRINT @strSQL
			EXEC sp_executesql @strSQL, N'@PRODUCT_NAME NVARCHAR(100),
										  @PRICE_TYPE_NAME NVARCHAR(100),
										  @UNIT_PRICE DECIMAL(18,2),
										  @QUANTITY DECIMAL(18,2),
										  @TOTAL_AMOUNT DECIMAL(18,2),
										  @DISCOUNT_AMOUNT DECIMAL(18,2),
										  @NET_AMOUNT DECIMAL(18,2),
										  @VAT_RATE_NAME NVARCHAR(100),
										  @VAT_PERCENTAGE DECIMAL(18,2),
										  @VAT_AMOUNT DECIMAL(18,2),
										  @GROSS_AMOUNT DECIMAL(18,2),
										  @WEIGHT__GRAMS_ DECIMAL(18,2),
										  @SALES_ORDER_DETAIL_NAME NVARCHAR(100),
										  @WFL_OUTPUT_SEQ_ID INT',
      
										  @PRODUCT_NAME,
										  @PRICE_TYPE_NAME,
										  @UNIT_PRICE,
										  @QUANTITY,
										  @TOTAL_AMOUNT,
										  @DISCOUNT_AMOUNT,
										  @NET_AMOUNT,
										  @VAT_RATE_NAME,
										  @VAT_PERCENTAGE,
										  @VAT_AMOUNT,
										  @GROSS_AMOUNT,
										  @WEIGHT__GRAMS_,
										  @SALES_ORDER_DETAIL_NAME,
										  @WFL_OUTPUT_SEQ_ID
			
			SET @STARTING_POINT = @STARTING_POINT + 15  
			                                                        
			FETCH NEXT FROM curGeneral INTO @SALES_ORDER_DETAIL_NAME,@PRODUCT_NAME, @PRICE_TYPE_NAME,@UNIT_PRICE,@QUANTITY,@TOTAL_AMOUNT,@DISCOUNT_AMOUNT,@NET_AMOUNT,@VAT_RATE_NAME,@VAT_PERCENTAGE,@VAT_AMOUNT,@GROSS_AMOUNT,@WEIGHT__GRAMS_
		END    
		
		CLOSE curGeneral                           
		DEALLOCATE curGeneral
	END
	
END;

-- =============================================
-- Author:		<Sikandar Hayat>
-- Create date: <29/11/2024>
-- Description:	<Updates Color Field>
-- =============================================
CREATE PROCEDURE [dbo].[UPDATE_RECORD_COLOR]
	-- Add the parameters for the stored procedure here
	@COLOR NVARCHAR(100),					-- COLOR TO BE UPDATED
	@p_RECORD_ID BIGINT,					-- SEQ_ID OF RECORD
	@p_USERS_EMAIL NVARCHAR(200)			-- EMAIL OF USER
AS
BEGIN
	IF (ISNULL(@p_USERS_EMAIL, '') = '') OR ISNULL(@p_RECORD_ID, 0) = 0
	BEGIN
		PRINT 'MISSING REQUIRED PARAMETER'
		RETURN
	END
	ELSE
	BEGIN
		DECLARE @p_CLIENT_ID BIGINT
		SET @COLOR = ISNULL(@COLOR, '')
		DECLARE @UPDATE_STATEMENT NVARCHAR(MAX)
		-- GET CLIENT BASED ON USER
		SELECT @p_CLIENT_ID = SRM_CLIENTS_SEQ_ID FROM [SRM-Framework_New].. srm_users WHERE LOGIN_EMAIL = @p_USERS_EMAIL
		IF (ISNULL(@p_CLIENT_ID, 0) != 0) 
		BEGIN
			SELECT @UPDATE_STATEMENT = 'UPDATE [SRM-CUSTOMENTITIES_' + CAST(ISNULL(@p_CLIENT_ID, 0) AS NVARCHAR(10))+']..CUS_ENTITY_DATA  SET COLOR = '+CHAR(39)+ @COLOR +CHAR(39)+' WHERE SEQ_ID = ' + CAST(ISNULL(@p_RECORD_ID, 0) AS NVARCHAR(50))
			PRINT @UPDATE_STATEMENT
			EXEC (@UPDATE_STATEMENT)
		END
	END
END;

