-- =============================================
-- Author:		<Nimra Azeem>
-- Create date: <27/02/2026>
-- Description:	<Validate Data Type>
-- =============================================
CREATE PROCEDURE [dbo].[VALIDATE_DATA_TYPE]
	-- Add the parameters for the stored procedure here
	@VALUE NVARCHAR(MAX),					-- VALUE TO BE VALIDATED
	@p_DATA_TYPE NVARCHAR(200),			-- DATA TYPE TO BE VALIDATED
	@p_RESULT INT OUTPUT				-- OUTPUT PARAMETER RETURNS 1/0
AS
BEGIN
	IF ISNULL(@p_DATA_TYPE, '')  = 'NUMERIC'
	BEGIN
		IF EXISTS (SELECT * WHERE @value NOT LIKE '%[^0-9]%')
		SET @p_RESULT = 1
		else set @p_RESULT = 0
	END
	ELSE IF ISNULL(@p_DATA_TYPE, '')  = 'DATE'
	BEGIN
		if ISDATE(@VALUE) = 1 set @p_RESULT = 1 ELSE set @p_RESULT = 0
	END
	ELSE set @p_RESULT = 0
END;






