CREATE PROCEDURE [dbo].[YBON PHASE UPGRADE]
	-- Add the parameters for the stored procedure here

	 @YELLOW_BOOK_OFFSHORE_NEW BIGINT,
	 @SHIP BIGINT,
	 @SHIP_NAME NVARCHAR(100),
	 @DP_EQUIP__CLASS BIGINT,
	 @DP_EQUIP__CLASS_NAME  NVARCHAR(100),
	 @PHASE_B_SEQ_ID BIGINT=NULL,
	 @PHASE_B_DATE_JOINED DATE=NULL,
	 @PHASE_B_DATE_LEFT DATE=NULL,
	 @PHASE_D_SEQ_ID BIGINT=NULL,
	 @PHASE_D_DATE_JOINED DATE=NULL,
	 @PHASE_D_DATE_LEFT DATE=NULL,
	 @PAHSE_B_DTAIL_IS_REQUIRED VARCHAR(1)=NULL,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[YBON Phases]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[YBON Phases]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_YBON_PHASE_B NVARCHAR(100)
	DECLARE @YBON_PHASE_B_CLIENT_ENTITY_SEQ_ID BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_YBON_PHASE_B_DETAIL NVARCHAR(100)
	DECLARE @YBON_PHASE_B_DETAIL_CLIENT_ENTITY_SEQ_ID BIGINT

	DECLARE @ENTITY_DISPLAY_NAME_YBON_PHASE_D NVARCHAR(100)
	DECLARE @YBON_PHASE_D_CLIENT_ENTITY_SEQ_ID BIGINT
	DECLARE @ENTITY_DISPLAY_NAME_YBON_PHASE_D_DETAIL NVARCHAR(100)
	DECLARE @YBON_PHASE_D_DETAIL_CLIENT_ENTITY_SEQ_ID BIGINT

	DECLARE @ENTITY_DISPLAY_NAME_YBON_TASK_BOOK NVARCHAR(100)
	DECLARE @YBON_TASK_BOOK_CLIENT_ENTITY_SEQ_ID BIGINT

	DECLARE @YBON_NAME NVARCHAR(100)
	DECLARE @APPLICATION BIGINT
	DECLARE @APPLICATION_NAME NVARCHAR(100)
	DECLARE @CONTACT BIGINT 
	DECLARE @CONTACT_NAME NVARCHAR(100)
	DECLARE @LOG_BOOK_TYPE BIGINT 
	DECLARE @LOG_BOOK_TYPE_NAME NVARCHAR(100)
	
	DECLARE @NUMBER_OF_DASYS_PHASE_B BIGINT
	DECLARE @NUMBER_OF_DASYS_PHASE_D BIGINT

	SET @ENTITY_DISPLAY_NAME_YBON_PHASE_B = 'YBON_PHASE_B_60_DAYS_DP_SEA_TIME'
	SET @ENTITY_DISPLAY_NAME_YBON_PHASE_B_DETAIL = 'YBON_PHASE_B_DETAIL'

	SET @ENTITY_DISPLAY_NAME_YBON_PHASE_D = 'YBON_PHASE_D_60_DAYS_DP_SEA_TIME'
	SET @ENTITY_DISPLAY_NAME_YBON_PHASE_D_DETAIL = 'YBON_PHASE_D_DETAIL'
	SET @ENTITY_DISPLAY_NAME_YBON_TASK_BOOK = 'YBON_TASK_BOOK'

	SET @SRM_CLIENTS_SEQ_ID = 40
	
	SELECT @NUMBER_OF_DASYS_PHASE_B =  DATEDIFF(day,@PHASE_B_DATE_JOINED,@PHASE_B_DATE_LEFT)
	SELECT @NUMBER_OF_DASYS_PHASE_D =  DATEDIFF(day,@PHASE_D_DATE_JOINED,@PHASE_D_DATE_LEFT)

	DECLARE @TODATE DateTime
	SELECT @TODATE = GETDATE()

	SELECT @YBON_NAME		    = ATTRIBUTE_015,
		   @APPLICATION         = ATTRIBUTE_002,
		   @APPLICATION_NAME    = ATTRIBUTE_003,
		   @CONTACT				= ATTRIBUTE_013,
		   @CONTACT_NAME		= ATTRIBUTE_014,
		   @LOG_BOOK_TYPE		= ATTRIBUTE_016,
		   @LOG_BOOK_TYPE_NAME	= ATTRIBUTE_017
	 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SEQ_ID = @YELLOW_BOOK_OFFSHORE_NEW

	 SELECT @YBON_PHASE_B_CLIENT_ENTITY_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_YBON_PHASE_B
	 SELECT @YBON_PHASE_B_DETAIL_CLIENT_ENTITY_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_YBON_PHASE_B_DETAIL
	
	 SELECT @YBON_PHASE_D_CLIENT_ENTITY_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_YBON_PHASE_D
	 SELECT @YBON_PHASE_D_DETAIL_CLIENT_ENTITY_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_YBON_PHASE_D_DETAIL
	 SELECT @YBON_TASK_BOOK_CLIENT_ENTITY_SEQ_ID = SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITIES WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME = @ENTITY_DISPLAY_NAME_YBON_TASK_BOOK
	

	 DECLARE @B_DATE NVARCHAR(100)
	 DECLARE @D_DATE NVARCHAR(100)
	 DECLARE @PHASE_B_F NVARCHAR(100)
	 DECLARE @PHASE_B_L NVARCHAR(100)
	 DECLARE @PHASE_D_F NVARCHAR(100)
	 DECLARE @PHASE_D_L NVARCHAR(100)

	 SET @PHASE_B_F = CONVERT(NVARCHAR, @PHASE_B_DATE_JOINED, 121)
	 SET @PHASE_B_L = CONVERT(NVARCHAR, @PHASE_B_DATE_LEFT, 121) 
	 SET @PHASE_D_F = CONVERT(NVARCHAR, @PHASE_D_DATE_JOINED, 121)
	 SET @PHASE_D_L = CONVERT(NVARCHAR, @PHASE_D_DATE_LEFT, 121)
	
	 --SET @B_DATE = @SHIP_NAME +' ' + CONVERT(NVARCHAR(10), @PHASE_B_DATE_JOINED , 121) + ' - ' +  CONVERT(NVARCHAR(10), @PHASE_B_DATE_LEFT , 121)
	 SET @D_DATE = CONVERT(NVARCHAR(10), @PHASE_D_DATE_JOINED , 121) + ' - ' + CONVERT(NVARCHAR(10), @PHASE_D_DATE_LEFT , 121) 


		DECLARE @NEXT_DP_SEA_DATE NVARCHAR(100)
		DECLARE @REMARKS NVARCHAR(100)
		DECLARE @PHASE_B_DETAIL_SEQ_ID BIGINT
		DECLARE @B_COUNT INT
		SET @B_COUNT = 1;
		
		IF ISNULL(@PAHSE_B_DTAIL_IS_REQUIRED,'N')='Y'
		BEGIN
				WHILE @B_COUNT < @NUMBER_OF_DASYS_PHASE_B
				BEGIN
					SET @NEXT_DP_SEA_DATE = CONVERT(NVARCHAR, DATEADD(DAY, @B_COUNT, @PHASE_B_DATE_JOINED), 121);
					SET @REMARKS = CONVERT(NVARCHAR(10), DATEADD(DAY, @B_COUNT, @PHASE_B_DATE_JOINED), 121)

					EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]	
					@ATTRIBUTE_001 = @REMARKS , 
					@ATTRIBUTE_002 = @PHASE_B_SEQ_ID,
					@ATTRIBUTE_003 = @B_DATE,
					@ATTRIBUTE_004 = @NEXT_DP_SEA_DATE,
					@ATTRIBUTE_006 = '9464976',
					@ATTRIBUTE_007 = 'Active',
					@ATTRIBUTE_011 = @APPLICATION,
					@ATTRIBUTE_012 = @APPLICATION_NAME,
					@ATTRIBUTE_013 = @YELLOW_BOOK_OFFSHORE_NEW,
					@ATTRIBUTE_014 = @YBON_NAME,
					@ATTRIBUTE_015 = @CONTACT,
					@ATTRIBUTE_016 = @CONTACT_NAME,
					@ATTRIBUTE_017 = @LOG_BOOK_TYPE,
					@ATTRIBUTE_018 = @LOG_BOOK_TYPE_NAME, 
					@ATTRIBUTE_019 = @YBON_NAME, 
					@ATTRIBUTE_020 = 'N',
					@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
					@SRM_CLIENT_ENTITIES_SEQ_ID = @YBON_PHASE_B_DETAIL_CLIENT_ENTITY_SEQ_ID,
					@DATE_CREATED = @TODATE,
					@CREATED_BY = 'NIDP',
					@RETURN_SEQ_ID = @PHASE_B_DETAIL_SEQ_ID OUTPUT,
					@ERROR = @ERROR OUTPUT,
					@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

				   SET @B_COUNT = @B_COUNT + 1;
				END;
			END;

		DECLARE @NEXT_DP_SEA_DATE_D NVARCHAR(100)
		DECLARE @REMARKS_D NVARCHAR(100)
		DECLARE @PHASE_D_DETAIL_SEQ_ID BIGINT
		DECLARE @D_COUNT INT
		SET @D_COUNT = 1;

		WHILE @D_COUNT < @NUMBER_OF_DASYS_PHASE_D
		BEGIN
		    SET @NEXT_DP_SEA_DATE_D =  CONVERT(NVARCHAR, DATEADD(DAY, @D_COUNT, @PHASE_D_DATE_JOINED), 121);
			SET @REMARKS_D = CONVERT(NVARCHAR(10), DATEADD(DAY, @D_COUNT, @PHASE_D_DATE_JOINED), 121);
			EXEC DBO.[GET_INSERT_CUS_ENTITY_DATA]
			@ATTRIBUTE_015 = @CONTACT,
			@ATTRIBUTE_016 = @CONTACT_NAME,
			@ATTRIBUTE_011 = @APPLICATION,
			@ATTRIBUTE_012 = @APPLICATION_NAME,
			@ATTRIBUTE_013 = @YELLOW_BOOK_OFFSHORE_NEW,
			@ATTRIBUTE_014 = @YBON_NAME,
			@ATTRIBUTE_017 = @LOG_BOOK_TYPE,
			@ATTRIBUTE_018 = @LOG_BOOK_TYPE_NAME, 
			@ATTRIBUTE_019 = @YBON_NAME, 
			@ATTRIBUTE_002 = @PHASE_D_SEQ_ID,
			@ATTRIBUTE_003 = @D_DATE,
			@ATTRIBUTE_001 = @REMARKS_D, 			
			@ATTRIBUTE_004 = @NEXT_DP_SEA_DATE_D,
			@ATTRIBUTE_006 = '9464976',
			@ATTRIBUTE_007 = 'Active',		
			@ATTRIBUTE_010 = 'Y',		
			@ATTRIBUTE_020 = 'N',
			@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@SRM_CLIENT_ENTITIES_SEQ_ID = @YBON_PHASE_D_DETAIL_CLIENT_ENTITY_SEQ_ID,
			@DATE_CREATED = @TODATE,
			@CREATED_BY = 'NIDP',
			@RETURN_SEQ_ID = @PHASE_D_DETAIL_SEQ_ID OUTPUT,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		   SET @D_COUNT = @D_COUNT + 1;
		END;


	DECLARE @TASK_BOOK_SEQ_ID BIGINT
	DECLARE @TASK_BOOK_DATE DATETIME
	DECLARE @TASK_COUNT BIGINT
	SET @TASK_COUNT = 1
    DECLARE CUR_PHASE_B CURSOR STATIC FOR

	SELECT  SEQ_ID FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ATTRIBUTE_006 = @YELLOW_BOOK_OFFSHORE_NEW  AND SRM_CLIENT_ENTITIES_SEQ_ID= @YBON_TASK_BOOK_CLIENT_ENTITY_SEQ_ID AND ISNULL(ATTRIBUTE_037 , 'N') != 'Y'

	OPEN CUR_PHASE_B 
	FETCH NEXT FROM CUR_PHASE_B INTO @TASK_BOOK_SEQ_ID
	
	WHILE @@FETCH_STATUS = 0
	BEGIN

	IF @TASK_COUNT > 60
	BEGIN
		SET @TASK_COUNT = 1
		SET @TASK_BOOK_DATE = DATEADD(DAY, @TASK_COUNT, @PHASE_D_DATE_JOINED);
	END
	ELSE
	SET @TASK_BOOK_DATE = DATEADD(DAY, @TASK_COUNT, @PHASE_D_DATE_JOINED);
	   	
	SET @TASK_COUNT = @TASK_COUNT + 1;
	FETCH NEXT FROM CUR_PHASE_B INTO @TASK_BOOK_SEQ_ID
	END

	CLOSE CUR_PHASE_B 
	DEALLOCATE CUR_PHASE_B


END



;






