CREATE PROCEDURE [dbo].[YBON TASK BOOK]
	-- Add the parameters for the stored procedure here
	 @YELLOW_BOOK_OFFSHORE_NEW BIGINT,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	PRINT 'I AM IN [dbo].[YBON Phases]'

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[YBON Phases]'

	DECLARE @TODAY NVARCHAR(30)
	SELECT @TODAY = CONVERT(NVARCHAR, GETDATE(), 121)

	DECLARE @SRM_CLIENTS_SEQ_ID BIGINT


	DECLARE @ENTITY_DISPLAY_NAME_YBON_TASK_BOOK NVARCHAR(100)

	SET @ENTITY_DISPLAY_NAME_YBON_TASK_BOOK = 'SHUTTLE_TANKER_TASK_BOOKS'

	SET @SRM_CLIENTS_SEQ_ID = 40
	
	DECLARE @TASK_BOOK_SEQ_ID BIGINT
	DECLARE @TASK_BOOK_DATE DATETIME
	DECLARE @ATTRIBUTE_025 NVARCHAR(2)
	--DECLARE @TASK_COUNT BIGINT
	DECLARE @MODE NVARCHAR(50)
	--SET @TASK_COUNT = 1
	SET @TASK_BOOK_DATE  = '2012-01-01'
    DECLARE CUR_PHASE_B CURSOR STATIC FOR

	SELECT  SEQ_ID, ATTRIBUTE_025 FROM [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA WHERE 
	SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ATTRIBUTE_006 = @YELLOW_BOOK_OFFSHORE_NEW  AND SRM_CLIENT_ENTITIES_SEQ_ID= 10223

	OPEN CUR_PHASE_B 
	FETCH NEXT FROM CUR_PHASE_B INTO @TASK_BOOK_SEQ_ID, @ATTRIBUTE_025 
	
	WHILE @@FETCH_STATUS = 0
	BEGIN

	IF @ATTRIBUTE_025 = '9' OR @ATTRIBUTE_025 = '10'
	BEGIN
		SET @TASK_BOOK_DATE = '2012-01-01'

		UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		SET
				ATTRIBUTE_016 = CONVERT(NVARCHAR, @TASK_BOOK_DATE, 121), 
				ATTRIBUTE_013 ='Y'   
		WHERE  SEQ_ID = @TASK_BOOK_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		AND ATTRIBUTE_006 = @YELLOW_BOOK_OFFSHORE_NEW  AND SRM_CLIENT_ENTITIES_SEQ_ID= 10223
	END
	ELSE
		UPDATE [SRM-CustomEntities_40].DBO.CUS_ENTITY_DATA 
		SET
				ATTRIBUTE_016 = CONVERT(NVARCHAR, @TASK_BOOK_DATE, 121), 
				ATTRIBUTE_013 ='Y'   
		WHERE  SEQ_ID = @TASK_BOOK_SEQ_ID AND SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID 
		AND ATTRIBUTE_006 = @YELLOW_BOOK_OFFSHORE_NEW  AND SRM_CLIENT_ENTITIES_SEQ_ID= 10223

	EXEC [dbo].[GET_POPULATE_PIVOT_TABLE]
		@SRM_CLIENT_ENTITIES_SEQ_ID = 10223,
		@CUS_ENTITY_DATA_SEQ_ID = @TASK_BOOK_SEQ_ID,
		@SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
		@ERROR = @ERROR OUTPUT,
		@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT

		
	SET @TASK_BOOK_DATE = DATEADD(day, 1, @TASK_BOOK_DATE)

	IF @TASK_BOOK_DATE > '2012-01-24'
		SET @TASK_BOOK_DATE = '2012-01-01'
	FETCH NEXT FROM CUR_PHASE_B INTO @TASK_BOOK_SEQ_ID, @ATTRIBUTE_025
	END

	CLOSE CUR_PHASE_B 
	DEALLOCATE CUR_PHASE_B


END



;

CREATE FUNCTION dbo.fnFormatDate (@Datetime DATETIME, @FormatMask VARCHAR(32))
RETURNS VARCHAR(32)
AS
BEGIN
    DECLARE @StringDate VARCHAR(32)
    SET @StringDate = @FormatMask
    IF (CHARINDEX ('YYYY',@StringDate) > 0)
       SET @StringDate = REPLACE(@StringDate, 'YYYY',
                         DATENAME(YY, @Datetime))
    IF (CHARINDEX ('YY',@StringDate) > 0)
       SET @StringDate = REPLACE(@StringDate, 'YY',
                         RIGHT(DATENAME(YY, @Datetime),2))
    IF (CHARINDEX ('Month',@StringDate) > 0)
       SET @StringDate = REPLACE(@StringDate, 'Month',
                         DATENAME(MM, @Datetime))
    IF (CHARINDEX ('MON',@StringDate COLLATE SQL_Latin1_General_CP1_CS_AS)>0)
       SET @StringDate = REPLACE(@StringDate, 'MON',
                         LEFT(UPPER(DATENAME(MM, @Datetime)),3))
    IF (CHARINDEX ('Mon',@StringDate) > 0)
       SET @StringDate = REPLACE(@StringDate, 'Mon',
                                     LEFT(DATENAME(MM, @Datetime),3))
    IF (CHARINDEX ('MM',@StringDate) > 0)
       SET @StringDate = REPLACE(@StringDate, 'MM',
                  RIGHT('0'+CONVERT(VARCHAR,DATEPART(MM, @Datetime)),2))
    IF (CHARINDEX ('M',@StringDate) > 0)
       SET @StringDate = REPLACE(@StringDate, 'M',
                         CONVERT(VARCHAR,DATEPART(MM, @Datetime)))
    IF (CHARINDEX ('DD',@StringDate) > 0)
       SET @StringDate = REPLACE(@StringDate, 'DD',
                         RIGHT('0'+DATENAME(DD, @Datetime),2))
    IF (CHARINDEX ('D',@StringDate) > 0)
       SET @StringDate = REPLACE(@StringDate, 'D',
                                     DATENAME(DD, @Datetime))   
RETURN @StringDate
END
;







create FUNCTION [dbo].[fn_CalculateAge] (@DATE_OF_BIRTH DATETIME)
RETURNS INT
AS
BEGIN
	DECLARE @RETURN_ID AS INT
	DECLARE @iYearOfBirth AS INT
	DECLARE @iCurrentYear AS INT
			
	IF (@DATE_OF_BIRTH IS NULL OR @DATE_OF_BIRTH = '')
		BEGIN 
			SET @RETURN_ID = 0
		END
	ELSE
		BEGIN
			SET @iYearOfBirth = YEAR(@DATE_OF_BIRTH)
			SET @iCurrentYear = YEAR(GETDATE())

			IF (@iCurrentYear <> @iYearOfBirth)
				BEGIN
					IF (MONTH(@DATE_OF_BIRTH) > MONTH(GETDATE()))
							SET @RETURN_ID =  @iCurrentYear - (@iYearOfBirth + 1)
					ELSE IF (MONTH(@DATE_OF_BIRTH) < MONTH(GETDATE()))
							SET @RETURN_ID = @iCurrentYear - @iYearOfBirth;
					ELSE
							BEGIN
							IF (DAY(@DATE_OF_BIRTH) > DAY(GETDATE()))
									SET @RETURN_ID = @iCurrentYear - (@iYearOfBirth + 1)
							ELSE
									SET @RETURN_ID = @iCurrentYear - @iYearOfBirth
							END
				END
			ELSE
					SET @RETURN_ID = 0
		END

		RETURN RTRIM(LTRIM(@RETURN_ID))
END

;


CREATE FUNCTION [dbo].[fn_CalculateInitials]  (@firstname nvarchar(60),@middlenames nvarchar(60))
RETURNS NVARCHAR(20)
AS
BEGIN
    DECLARE @iLastPosition int
    DECLARE @sInitials nvarchar(20)
    DECLARE @sForenames nvarchar(121)
	DECLARE @sLoopFirstTime nchar(1)

	set @firstname = isnull(@firstname, '')
	set @middlenames = isnull(@middlenames, '')

	SET @sInitials = ''
	SET @sForenames = ''
    SET @sForenames = LTRIM(RTRIM(@firstname)) + ' ' + LTRIM(RTRIM(@middlenames))
	SET @sForenames = LTRIM(RTRIM(@sForenames))
	SET @sLoopFirstTime = 'Y'

    IF LEN(@sForenames) > 0
	BEGIN
		WHILE @iLastPosition <> 0 OR @sLoopFirstTime = 'Y'
		BEGIN
			IF LEN(@sInitials) > 0
				SET @sInitials = LTRIM(RTRIM(@sInitials)) + ' ' + SUBSTRING(@sForenames,1,1)				
			ELSE IF LEN(@sInitials) = 0
				SET @sInitials = SUBSTRING(@sForenames,1,1)

			SET @iLastPosition = PATINDEX('% %',@sForenames)
			IF @iLastPosition <> 0 
			BEGIN
				SET @sForenames = SUBSTRING(@sForenames,@iLastPosition + 1,LEN(@sForenames))
				SET @sForenames = LTRIM(RTRIM(@sForenames))
			END
			SET @sLoopFirstTime = 'N'
		END
	END
	ELSE
	BEGIN
		SET @sInitials = ''
	END

	SET @sInitials = UPPER(@sInitials)
    RETURN(@sInitials)
END





;

CREATE Function [dbo].[fn_CalculateLabelName](@Title nvarchar(50), @FirstName nvarchar(50) , @LastName nvarchar(50) , @DesignatoryLetters nvarchar(50))
RETURNS NVARCHAR(200)
AS
BEGIN
	DECLARE @lABEL_NAME nvarchar(100)

	set @Title = ltrim(rtrim(@Title))
	set @FirstName = ltrim(rtrim(@FirstName))
	set @LastName = ltrim(rtrim(@LastName))
	set @DesignatoryLetters = ltrim(rtrim(@DesignatoryLetters))

    SET @lABEL_NAME = ISNULL(@Title,'') + ISNULL(' ' + @FirstName,'') + ISNULL(' ' + @LastName,'') + ISNULL(' ' + @DesignatoryLetters,'')

	SET @lABEL_NAME = LTRIM(RTRIM(@lABEL_NAME))

	RETURN @lABEL_NAME
END
;

grant alter, control, execute, references, take ownership, view definition on fn_CalculateLabelName to usr_conversion;







CREATE FUNCTION [dbo].[fn_CalculateTime] (@Time NVarchar(10))
RETURNS NVarchar(10)
AS
BEGIN
		DECLARE @RETURN_ID NVARCHAR(10)
		DECLARE @FIELD01 NVARCHAR(100)

		SET @RETURN_ID = ''

		DECLARE curGeneral CURSOR STATIC LOCAL FOR 
		SELECT VALUE FROM [SRM-FRAMEWORK_NEW].DBO.FN_SPLIT(@Time, ':') WHERE IDX < 2
   
		OPEN curGeneral                                                             
		FETCH NEXT FROM curGeneral INTO @FIELD01    

		WHILE (@@Fetch_Status = 0)       
		BEGIN        
			
			IF CAST(@FIELD01 AS INT) < 10 AND LEN(@FIELD01) = 1
				SET @RETURN_ID = @RETURN_ID + '0' + 	@FIELD01 + ':'
			ELSE 
				SET @RETURN_ID = @RETURN_ID + @FIELD01 + ':'

			FETCH NEXT FROM curGeneral INTO @FIELD01    
		END    
   
		CLOSE curGeneral                           
		DEALLOCATE curGeneral  

		IF LEN(@RETURN_ID) > 1
			SET @RETURN_ID = SUBSTRING(@RETURN_ID, 1, LEN(@RETURN_ID)-1)
		
		RETURN RTRIM(LTRIM(@RETURN_ID))
END

;


