CREATE FUNCTION [dbo].[fn_Calculate_Application_ID]  (@RecordId bigint)
RETURNS NVARCHAR(50)
AS
BEGIN

	DECLARE @App_ID nvarchar(20)
	DECLARE @Application_SRM_CLIENTS_SEQ_ID int,@Scheme_SRM_CLIENTS_SEQ_ID int
	set @Application_SRM_CLIENTS_SEQ_ID = 10156
	set @Scheme_SRM_CLIENTS_SEQ_ID = 10147

	DECLARE @SCHEME_TYPE bigint, @SCHEME_TYPE_ID nvarchar(20), @TOTAL_APP_COUNT_YEAR bigint, @CURRENT_YEAR int, @APP_COUNT_YEAR nvarchar(20)
	set @CURRENT_YEAR = YEAR(GETDATE())

	-- Declare the return variable here
	
	select @SCHEME_TYPE=ATTRIBUTE_009 from [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA where SRM_CLIENT_ENTITIES_SEQ_ID = @Application_SRM_CLIENTS_SEQ_ID and SEQ_ID = @RecordId and DELETED <> 'Y'

	select @SCHEME_TYPE_ID=ATTRIBUTE_006 from [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA where SRM_CLIENT_ENTITIES_SEQ_ID = @Scheme_SRM_CLIENTS_SEQ_ID and SEQ_ID = @SCHEME_TYPE and DELETED <> 'Y'

	select @TOTAL_APP_COUNT_YEAR = COUNT(SEQ_ID) from [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA where SRM_CLIENT_ENTITIES_SEQ_ID = @Application_SRM_CLIENTS_SEQ_ID --and DELETED <> 'Y'
	and ATTRIBUTE_020 = @CURRENT_YEAR

	

	set @TOTAL_APP_COUNT_YEAR = @TOTAL_APP_COUNT_YEAR + 1

	
	set @APP_COUNT_YEAR = cast(@TOTAL_APP_COUNT_YEAR as nvarchar(8))

	set @App_ID = @SCHEME_TYPE_ID + '-' + RIGHT(REPLICATE('0', 5) + @APP_COUNT_YEAR, 5) + '/' + cast(@CURRENT_YEAR as nvarchar(8))

	RETURN @App_ID

END

;







CREATE FUNCTION [dbo].[fn_ExtractNumbericValuefromString] (@StringValue NVARCHAR(500))
RETURNS INT
AS
BEGIN
	

	WHILE PATINDEX('%[^0-9]%',@StringValue) <> 0.
		SET @StringValue = STUFF(@StringValue,PATINDEX('%[^0-9]%',@StringValue),1,'')
	
	
	RETURN RTRIM(LTRIM(@StringValue))
END

;



CREATE FUNCTION [dbo].[fn_ExtractPostcodeAlphaPrefixfromPostcode] (@postcode NVARCHAR(500))
RETURNS NVARCHAR(200)
AS
BEGIN
	
	DECLARE @postcode2 NVARCHAR(100) = @postcode, @NumericValue NVARCHAR(100), @newvalue NVARCHAR(20)
	
	WHILE PATINDEX('%[^0-9]%',@postcode2) <> 0.
		SET @postcode2 = STUFF(@postcode2,PATINDEX('%[^0-9]%',@postcode2),1,'')

	IF ISNULL(@postcode2 , '') != ''
	BEGIN

		SET @NumericValue = LEFT(@postcode2,1)
	
		SET @newvalue = SUBSTRING(@postcode,1, CHARINDEX(@NumericValue,@postcode)-1 )	
	END
	RETURN RTRIM(LTRIM(@newvalue))
END

;


CREATE FUNCTION [dbo].[fn_GetFirstRegularInstalment]  (@Amount MONEY, @Installment INT, @FIrst_Regular CHAR(1),@Total_Instalments INT)
RETURNS MONEY
AS
BEGIN
   DECLARE @ReturnValue MONEY
	  
	  IF(@Installment = 0)
	  BEGIN
  		SET @Installment = @Total_Instalments
	  END 

    DECLARE @X MONEY = @Amount/@Installment -- 8.33
	SET @X = ROUND(@X,2)

	DECLARE @Y MONEY = @X * ((@Installment - 1)) -- 91.63
	DECLARE @Z MONEY = @Amount - @Y


	IF @FIrst_Regular = 'F'
		SET @ReturnValue=@Z
	ELSE
		SET @ReturnValue=@X

    RETURN(@ReturnValue)
END





;

grant alter, execute on fn_GetFirstRegularInstalment to usr_conversion;


