CREATE FUNCTION [dbo].[fn_GetInvoiceDepartment_40]  (@invoice BIGINT)
RETURNS NVARCHAR(200)
AS
BEGIN
	DECLARE @srm_clients_seq_id BIGINT=40 	
	DECLARE @Dept_ID nvarchar(200)
	DECLARE @PRODUCT BIGINT = 0, @PRODUCT_DEPARTMENT BIGINT = 0
	
	DECLARE @EN_INVOICE_TRANSACTION BIGINT = (SELECT [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID('FINANCE_TRANSACTION_DETAIL',@srm_clients_seq_id))
	DECLARE @EN_PRODUCT BIGINT = (SELECT [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID('PRODUCT',@srm_clients_seq_id))
	DECLARE @EN_PRODUCT_TYPE BIGINT = (SELECT [SRM-DataConversion].dbo.GET_SRM_CLIENT_ENTITIES_SEQ_ID('PRODUCT_TYPE',@srm_clients_seq_id))
	DECLARE @SCEA_INVOICE BIGINT = (SELECT SEQ_ID FROM [SRM-Framework_New].dbo.SRM_CLIENT_ENTITY_ATTRIBUTES WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_INVOICE_TRANSACTION
	AND ATTRIBUTE_DISPLAY_NAME='FINANCE_TRANSACTION')

	SELECT TOP 1 @PRODUCT = ATTRIBUTE_022 FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CED WHERE SEQ_ID IN (
	SELECT CUS_ENTITY_DATA_SEQ_ID FROM [SRM-DataPivot_40].dbo.CUS_PIVOT_NON_UNIQUE_INDEXES AS CPNUI WHERE SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID=@SCEA_INVOICE
	AND ATTRIBUTE_DECIMAL = @invoice) AND CED.DELETED='N' AND CED.SEQ_ID NOT IN (
	SELECT SEQ_ID FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CED2 WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_PRODUCT AND DELETED='N' AND ATTRIBUTE_003 IN (
	SELECT SEQ_ID FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CED3 WHERE SRM_CLIENT_ENTITIES_SEQ_ID=@EN_PRODUCT_TYPE AND DELETED='N' AND ATTRIBUTE_109='Y' ))
	ORDER BY CED.SEQ_ID
		
	IF @PRODUCT > 0
	BEGIN
		SELECT @PRODUCT_DEPARTMENT = ATTRIBUTE_124 FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CED WHERE SEQ_ID=@PRODUCT
		
		IF @PRODUCT_DEPARTMENT > 0
			SELECT @Dept_ID = ATTRIBUTE_006 FROM [SRM-CustomEntities_40].dbo.CUS_ENTITY_DATA AS CED WHERE SEQ_ID=@PRODUCT_DEPARTMENT
		ELSE
			SET @Dept_ID='No department is Linked with the product'        
	END
	ELSE
		SET @Dept_ID='No Product is Linked with the invoice'  
		  
	RETURN @Dept_ID

END

;


