CREATE FUNCTION [dbo].[fn_Split](@sText varchar(MAX), @sDelim varchar(20) = ' ')
RETURNS @retArray TABLE (idx smallint Primary Key, value nvarchar(4000))
AS
BEGIN
DECLARE @idx smallint,
	@value nvarchar(4000),
	@bcontinue bit,
	@iStrike smallint,
	@iDelimlength tinyint

IF @sDelim = 'Space'
	BEGIN
	SET @sDelim = ' '
	END

SET @idx = 0
SET @sText = LTrim(RTrim(@sText))
SET @iDelimlength = LEN(@sDelim)
SET @bcontinue = 1

IF NOT ((@iDelimlength = 0) or (@sDelim = 'Empty'))
	BEGIN
	WHILE @bcontinue = 1
		BEGIN

--If you can find the delimiter in the text, retrieve the first element and
--insert it with its index into the return table.
 
		IF CHARINDEX(@sDelim, @sText)>0
			BEGIN
			SET @value = SUBSTRING(@sText,1, CHARINDEX(@sDelim,@sText)-1)
				BEGIN
				INSERT @retArray (idx, value)
				VALUES (@idx, @value)
				END
			
--Trim the element and its delimiter from the front of the string.
			--Increment the index and loop.
SET @iStrike = LEN(@value) + @iDelimlength
			SET @idx = @idx + 1
			SET @sText = LTrim(Right(@sText,LEN(@sText) - @iStrike))
		
			END
		ELSE
			BEGIN
--If you can’t find the delimiter in the text, @sText is the last value in
--@retArray.
 SET @value = @sText
				BEGIN
				INSERT @retArray (idx, value)
				VALUES (@idx, @value)
				END
			--Exit the WHILE loop.
SET @bcontinue = 0
			END
		END
	END
ELSE
	BEGIN
	WHILE @bcontinue=1
		BEGIN
		--If the delimiter is an empty string, check for remaining text
		--instead of a delimiter. Insert the first character into the
		--retArray table. Trim the character from the front of the string.
--Increment the index and loop.
		IF LEN(@sText)>1
			BEGIN
			SET @value = SUBSTRING(@sText,1,1)
				BEGIN
				INSERT @retArray (idx, value)
				VALUES (@idx, @value)
				END
			SET @idx = @idx+1
			SET @sText = SUBSTRING(@sText,2,LEN(@sText)-1)
			
			END
		ELSE
			BEGIN
			--One character remains.
			--Insert the character, and exit the WHILE loop.
			INSERT @retArray (idx, value)
			VALUES (@idx, @sText)
			SET @bcontinue = 0	
			END
	END

END

RETURN
END








;







CREATE FUNCTION [dbo].[fn_SplitPrimarySecondaryOther](@sText varchar(MAX))
RETURNS @COMMS_DETAIL TABLE (PRIMARY_DETAIL NVARCHAR(200),SECONDARY_DETAIL NVARCHAR(200),OTHER_DETAIL NVARCHAR(200))
AS
BEGIN

		DECLARE @P_TELEPHONE NVARCHAR(100)
		DECLARE @S_TELEPHONE NVARCHAR(100)
		DECLARE @REMARKS NVARCHAR(100)

		DECLARE @VALUE NVARCHAR(100)

		DECLARE @TELEPHONE NVARCHAR(500)
		SET @TELEPHONE = @sText

		SET @P_TELEPHONE = ''
		SET @S_TELEPHONE = ''
		SET @REMARKS = ''
		
		DECLARE curGeneral CURSOR LOCAL STATIC FOR 
		SELECT DISTINCT VALUE FROM (
		SELECT VALUE FROM [SRM-Framework_New].dbo.fn_Split(@TELEPHONE,',') WHERE idx=0 UNION
		SELECT VALUE FROM [SRM-Framework_New].dbo.fn_Split(@TELEPHONE,',') WHERE idx=1 UNION
		SELECT VALUE FROM [SRM-Framework_New].dbo.fn_Split(@TELEPHONE,',') WHERE idx=2 UNION
		SELECT VALUE FROM [SRM-Framework_New].dbo.fn_Split(@TELEPHONE,',') WHERE idx=3 UNION
		SELECT VALUE FROM [SRM-Framework_New].dbo.fn_Split(@TELEPHONE,',') WHERE idx=4) A
		WHERE VALUE != ''
   
		OPEN curGeneral                                                             
		FETCH NEXT FROM curGeneral INTO @VALUE    

		WHILE (@@Fetch_Status = 0)       
		BEGIN      

			IF @P_TELEPHONE = ''
				SET @P_TELEPHONE = @VALUE
			ELSE IF @P_TELEPHONE != '' AND @S_TELEPHONE = ''
				SET @S_TELEPHONE = @VALUE
			ELSE IF @P_TELEPHONE != '' AND @S_TELEPHONE != '' AND @REMARKS = ''
				SET @REMARKS = @VALUE
			ELSE IF @P_TELEPHONE != '' AND @S_TELEPHONE != '' AND @REMARKS != ''
				SET @REMARKS = @REMARKS + ',' + @VALUE

			FETCH NEXT FROM curGeneral INTO @VALUE    
		END    
   
		CLOSE curGeneral                           
		DEALLOCATE curGeneral  


		
		INSERT INTO @COMMS_DETAIL
		SELECT @P_TELEPHONE PRIMARY_DETAIL, @S_TELEPHONE SECONDARY_DETAIL, @REMARKS OTHER_DETAIL
		RETURN
END;



CREATE FUNCTION [dbo].[fn_StringToTable]
(
    @string VARCHAR(MAX),
    @delimiter CHAR(1)
)
RETURNS @output TABLE(
    data nvarchar(100)
)
BEGIN

    DECLARE @start INT, @end INT
    SELECT @start = 1, @end = CHARINDEX(@delimiter, @string)

    WHILE @start < LEN(@string) + 1 BEGIN
        IF @end = 0 
            SET @end = LEN(@string) + 1

        INSERT INTO @output (data) 
        VALUES(SUBSTRING(@string, @start, @end - @start))
        SET @start = @end + 1
        SET @end = CHARINDEX(@delimiter, @string, @start)
    END

    RETURN

END




;


	CREATE FUNCTION dbo.fn_diagramobjects() 
	RETURNS int
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		declare @id_upgraddiagrams		int
		declare @id_sysdiagrams			int
		declare @id_helpdiagrams		int
		declare @id_helpdiagramdefinition	int
		declare @id_creatediagram	int
		declare @id_renamediagram	int
		declare @id_alterdiagram 	int 
		declare @id_dropdiagram		int
		declare @InstalledObjects	int

		select @InstalledObjects = 0

		select 	@id_upgraddiagrams = object_id(N'dbo.sp_upgraddiagrams'),
			@id_sysdiagrams = object_id(N'dbo.sysdiagrams'),
			@id_helpdiagrams = object_id(N'dbo.sp_helpdiagrams'),
			@id_helpdiagramdefinition = object_id(N'dbo.sp_helpdiagramdefinition'),
			@id_creatediagram = object_id(N'dbo.sp_creatediagram'),
			@id_renamediagram = object_id(N'dbo.sp_renamediagram'),
			@id_alterdiagram = object_id(N'dbo.sp_alterdiagram'), 
			@id_dropdiagram = object_id(N'dbo.sp_dropdiagram')

		if @id_upgraddiagrams is not null
			select @InstalledObjects = @InstalledObjects + 1
		if @id_sysdiagrams is not null
			select @InstalledObjects = @InstalledObjects + 2
		if @id_helpdiagrams is not null
			select @InstalledObjects = @InstalledObjects + 4
		if @id_helpdiagramdefinition is not null
			select @InstalledObjects = @InstalledObjects + 8
		if @id_creatediagram is not null
			select @InstalledObjects = @InstalledObjects + 16
		if @id_renamediagram is not null
			select @InstalledObjects = @InstalledObjects + 32
		if @id_alterdiagram  is not null
			select @InstalledObjects = @InstalledObjects + 64
		if @id_dropdiagram is not null
			select @InstalledObjects = @InstalledObjects + 128
		
		return @InstalledObjects 
	END
;

exec sp_addextendedproperty 'microsoft_database_tools_support', 1, 'SCHEMA', 'dbo', 'FUNCTION', 'fn_diagramobjects';

deny execute on fn_diagramobjects to guest;

grant execute on fn_diagramobjects to [public];

CREATE FUNCTION [dbo].[fn_eliminatespecialchars](@string nvarchar(250))
RETURNS nvarchar(250)
AS
BEGIN
       declare @i int
   
        set @i = PATINDEX('%[^abcdefghijklmnopqrstuvwxyz0123456789 ]%',@string collate Latin1_General_CI_AS_KS) 
       while (@i > 0)
       begin
            SELECT @string = STUFF(@string,@i,1,' ')
            set @i = PATINDEX('%[^abcdefghijklmnopqrstuvwxyz0123456789 ]%',@string collate Latin1_General_CI_AS_KS)
       end
       RETURN(@string);
END;

create FUNCTION [dbo].[fn_leanUtil_PostCodePart]
    (
      @PostCode VARCHAR(15) ,
      @Part TINYINT
    )
	
RETURNS VARCHAR(5)
AS 
    BEGIN

	
		
        DECLARE @codepart VARCHAR(5) 
            -- Insert space if missing from postcode
          
            IF LEN(@PostCode) > 4
		BEGIN

        IF CHARINDEX(' ', @postcode) = 0
			SELECT  @postcode = SUBSTRING(@postcode, 0, LEN(@postcode) - 2) + ' '
                + SUBSTRING(@postcode, LEN(@postcode) - 2, LEN(@postcode))
                
                
        IF @Part = 1 
            SELECT  @codepart = LTRIM(SUBSTRING(@postcode, 1,
                                                CHARINDEX(' ', @postcode))) 
        ELSE 
            SELECT  @codepart = LTRIM(SUBSTRING(@postcode, CHARINDEX(' ', @postcode), 4)) 
		END
        RETURN  @codepart
    
    END;




