CREATE PROCEDURE [dbo].[sp_SelectEntityDto] --'3553755275','befc321996bb2d85c5486063e4feceab','COUNTRY'
	-- Add the parameters for the stored procedure here
 @AccessId AS varchar(250) = NULL,
 @SecretKey AS VARCHAR(250) = NULL,
 @EntityName AS VARCHAR(250) = NULL

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
--SET @SecretKey = '94f4df144c60a7c074187ca615b1b902'
    -- Insert statements for procedure here
SELECT ENTITY_DISPLAY_NAME AS EntityName, 
(SELECT 'This entity contains information about ' + PHRASE
FROM
SRM_CLIENT_LANGUAGE_ITEMS l,
dbo.SRM_ENTITIES AS SE
WHERE  SE.SEQ_ID = l.OBJECT_ID
AND SE.SEQ_ID = E.SRM_ENTITIES_SEQ_ID
AND l.OBJECT_TYPE = 25
AND l.SRM_LANGUAGE_TOKENS_SEQ_ID = 1
AND l.SRM_CLIENTS_SEQ_ID = C.SEQ_ID ) [Description],
--'This entity contains information about ' + dbo.ProperCase( ENTITY_DISPLAY_NAME) as [Description],
ISNULL(DO_NOT_AVAILABLE_FOR_INSERT, 'N') DoNotAvailableForInsert, 
ISNULL(DO_NOT_AVAILABLE_FOR_SELECT, 'N') DoNotAvailableForSelect , 
ISNULL(DO_NOT_AVAILABLE_FOR_UPDATE, 'N') DoNotAvailableForUpdate 
FROM [SRM-Framework_New]..SRM_CLIENT_ENTITIES E
INNER JOIN [SRM-Framework_New]..SRM_CLIENTS C ON C.SEQ_ID = E.SRM_CLIENTS_SEQ_ID
INNER JOIN [SRM-ApiTool]..SRM_APITOOL T ON E.SRM_CLIENTS_SEQ_ID = T.SRM_CLIENT_SEQ_ID

WHERE T.SRM_ACCESS_ID = @AccessId AND 
T.SRM_CLIENT_SECRET_KEY = @SecretKey 
AND ENTITY_DISPLAY_NAME LIKE @EntityName 
AND ISNULL(DO_NOT_EXPOSE_IN_SWAGGER, 'N') = 'N' AND ISNULL(ENTITY_DISPLAY_NAME,'') != ''
ORDER BY ENTITY_DISPLAY_NAME


END





;




