-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
--select * from [SRM-ApiTool]..SRM_APITOOL
--[dbo].[sp_SelectFieldDescriptionDto] '1133557799','d1a85f741772ae215f06893b53b627e6','COUNTRY'
-- =============================================
CREATE PROCEDURE [dbo].[sp_SelectFieldDescriptionDto]
	-- Add the parameters for the stored procedure here
 @AccessId AS varchar(250) = NULL,
 @SecretKey AS VARCHAR(250) = NULL,
 @EntityName AS VARCHAR(250) = NULL

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
 --SET @SecretKey = '94f4df144c60a7c074187ca615b1b902'
	SELECT ROW_NUMBER() OVER(ORDER BY a.SrNo ASC) AS SrNo, [oomiField], [APIMetaname], [MaxLength], [Remarks], [Type], [LookupEntity], Helptext from
	(
	--select '' as SrNo,'*' 'oomiField','*' 'APIMetaname','' 'MaxLength',''Remarks,'' Type,'' 'LookupEntity', 'It will select all fields' as 'Helptext'
	--union
	select '' as SrNo,'Record ID' 'oomiField','RecordId' 'APIMetaname', 15 'MaxLength','' Remarks,'Number' Type,'' 'LookupEntity', 'Unique Identifier' as 'Helptext'
	union
	SELECT ROW_NUMBER() OVER(ORDER BY d.ATTRIBUTE_API_CAPTION ASC) AS SrNo,
	(SELECT TOP 1 PHRASE FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE D.SRM_ENTITY_ATTRIBUTES_SEQ_ID = SRM_CLIENT_LANGUAGE_ITEMS.OBJECT_ID AND SRM_CLIENT_LANGUAGE_ITEMS.OBJECT_TYPE = 3 AND SRM_CLIENT_LANGUAGE_ITEMS.SRM_LANGUAGE_TOKENS_SEQ_ID = 1) 'oomiField',
	ATTRIBUTE_API_CAPTION 'APIMetaname',
	case when d.SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID in (19,11, 5) then 15 else isnull(D.MAX_LENGTH,'1') end 'MaxLength',
	CASE F.SYSTEM_NAME WHEN 'LookupRelationship' THEN 'RecordId' WHEN 'Checkbox' THEN 'Y/N' ELSE '' END Remarks,
	CASE F.SYSTEM_NAME WHEN 'TEXT' THEN 'String' WHEN 'Checkbox' THEN 'String' WHEN 'LookupRelationship' THEN 'Number' ELSE F.SYSTEM_NAME END TYPE,
	isnull((SELECT ENTITY_DISPLAY_NAME FROM SRM_CLIENT_ENTITIES C2 WHERE C2.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID2), '') 'LookupEntity',
	(SELECT TOP 1 PHRASE FROM SRM_CLIENT_LANGUAGE_ITEMS WHERE B.SEQ_ID = SRM_CLIENT_LANGUAGE_ITEMS.OBJECT_ID AND SRM_CLIENT_LANGUAGE_ITEMS.OBJECT_TYPE = 3 AND SRM_CLIENT_LANGUAGE_ITEMS.SRM_LANGUAGE_TOKENS_SEQ_ID = 3) Helptext
	FROM 
		[SRM-Framework_New]..SRM_ENTITIES A, 
		[SRM-Framework_New]..SRM_ENTITY_ATTRIBUTES B, 
		[SRM-Framework_New]..SRM_CLIENT_ENTITIES C, 
		[SRM-Framework_New]..SRM_CLIENT_ENTITY_ATTRIBUTES D, 
		[SRM-Framework_New]..SRM_ATTRIBUTE_DATA_TYPES F, 
		[SRM-ApiTool]..SRM_APITOOL G
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID 
		AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID 
		AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID 
		AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID 
		AND D.SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = F.SEQ_ID
		AND (ISNULL(D.DO_NOT_EXPOSE_IN_API,'N') = 'N' or D.DO_NOT_EXPOSE_IN_API = '') 
		AND (ISNULL(C.DO_NOT_EXPOSE_IN_SWAGGER,'N') = 'N' or C.DO_NOT_EXPOSE_IN_SWAGGER = '')
		AND (C.SRM_CLIENTS_SEQ_ID = G.SRM_CLIENT_SEQ_ID OR C.SRM_CLIENTS_SEQ_ID = 500)
		--AND C.SRM_CLIENTS_SEQ_ID = 126
		AND G.SRM_ACCESS_ID = @AccessId AND G.SRM_CLIENT_SECRET_KEY = @SecretKey
		AND C.ENTITY_DISPLAY_NAME  = @EntityName
  
		AND D.ATTRIBUTE_DISPLAY_NAME NOT IN (
		'RECORD_ID',
		'CLIENT_ID',
		'SOURCE_OF_DATA',
		'SOURCE_FILE',
		'DATE_MODIFIED',
		'MODIFIED_BY',
		'DATE_CREATED_ON',
		'DATE_CREATED',
		'CREATED_BY',
		'DELETED',
		'DATE_DELETED',
		'DELETED_BY',
		'COLOR',
		'GraphColor',
		'Rank',
		'GRAPH_COLOR')
	) a order by SrNo
END







;




