	SET NOCOUNT ON;

    -- Insert statements for procedure here
 --SET @SecretKey = '94f4df144c60a7c074187ca615b1b902'
SELECT  A.ATTRIBUTE_API_CAPTION AS oomiField, A.MAX_LENGTH AS MaximumLength, D.SQL_DATA_TYPE DataType,
