INNER JOIN SRM_ATTRIBUTE_DATA_TYPES D ON  D.SEQ_ID = A.SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID
INNER JOIN [SRM-Framework_New]..SRM_CLIENTS C ON C.SEQ_ID = E.SRM_CLIENTS_SEQ_ID
INNER JOIN [SRM-ApiTool]..SRM_APITOOL T ON E.SRM_CLIENTS_SEQ_ID = T.SRM_CLIENT_SEQ_ID

WHERE T.SRM_ACCESS_ID = @AccessId AND T.SRM_CLIENT_SECRET_KEY = @SecretKey AND ISNULL(E.DO_NOT_EXPOSE_IN_SWAGGER, 'N') = 'N' 
AND ISNULL(A.DO_NOT_EXPOSE_IN_API, 'N') = 'N'AND ISNULL(E.ENTITY_DISPLAY_NAME,'') = @EntityName
AND A.ATTRIBUTE_API_CAPTION NOT IN ('ClientId','SourceOfData','SourceFile','Deleted','DateDeleted','DeletedBy','Default','Nationality','ShortCode','UkOrIreland')
ORDER BY A.ATTRIBUTE_API_CAPTION




END



;




