-- =============================================
CREATE PROCEDURE [dbo].[sp_SelectFilterViewDto] 
	-- Add the parameters for the stored procedure here
 @FilterViewId AS BIGINT = NULL,
 @ClientEntityId AS BIGINT = NULL

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


SELECT FV.SEQ_ID, FV.SYSTEM_NAME FilterViewName, FILTER_LOGIC FilterLogic, 
SCE.SEQ_ID  ClientEntityId, SRM_ENTITIES_SEQ_ID EntityId,
ENTITY_DISPLAY_NAME EntityDisplayName
FROM [dbo].[SRM_CLIENT_FILTER_VIEWS] FV  WITH(NOLOCK)
LEFT OUTER JOIN [dbo].[SRM_CLIENT_ENTITIES] SCE  WITH(NOLOCK)
ON FV.SRM_CLIENT_ENTITIES_SEQ_ID = SCE.SEQ_ID
WHERE FV.SEQ_ID = @FilterViewId 
AND SCE.SEQ_ID = @ClientEntityId


SELECT  
FVA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID ClientEntityAttributeId, 
--CASE WHEN CEA.SRM_CLIENT_ENTITIES_SEQ_ID2  IS NOT NULL THEN 
--(SELECT SYSTEM_NAME FROM [dbo].[SRM_ENTITY_ATTRIBUTES] WITH(NOLOCK) WHERE SEQ_ID = CEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID)
--ELSE SEA.SYSTEM_NAME END AS SystemName,
SEA.SYSTEM_NAME AS SystemName,
ATTRIBUTE_API_CAPTION AttributeApiCaption,
Rank, CEA.SRM_CLIENT_ENTITIES_SEQ_ID2 ClientEntitiesId
,CASE WHEN CEA.SRM_CLIENT_ENTITIES_SEQ_ID2  IS NOT NULL THEN CEA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID
ELSE FVA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID END AS ClientEntityAttributeId
,ADT.SQL_DATA_TYPE DataType

FROM [dbo].[SRM_CLIENT_FILTER_VIEW_ATTRIBUTES] FVA WITH(NOLOCK)
INNER JOIN [dbo].[SRM_CLIENT_ENTITY_ATTRIBUTES] CEA  WITH(NOLOCK) ON FVA.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = CEA.SEQ_ID  
INNER JOIN [dbo].[SRM_ENTITY_ATTRIBUTES] SEA WITH(NOLOCK) ON  SEA.SEQ_ID = CEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID
INNER JOIN [dbo].[SRM_ATTRIBUTE_DATA_TYPES] ADT WITH(NOLOCK) ON  CEA.SRM_ATTRIBUTE_DATA_TYPES_SEQ_ID = ADT.SEQ_ID
WHERE FVA.SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @FilterViewId

SELECT FVC.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID  ClientEntityAttributeId,
SYSTEM_NAME SystemName, Rank, 
OPERATOR_ID OperatorId, CRITERIA_VALUE CriteriaValue, CEA.ATTRIBUTE_API_CAPTION ApiCaption
FROM [dbo].[SRM_CLIENT_FILTER_VIEW_CRITERIA] FVC WITH(NOLOCK)
INNER JOIN [dbo].[SRM_CLIENT_ENTITY_ATTRIBUTES] CEA  WITH(NOLOCK) ON FVC.SRM_CLIENT_ENTITY_ATTRIBUTES_SEQ_ID = CEA.SEQ_ID  
INNER JOIN [dbo].[SRM_ENTITY_ATTRIBUTES] SEA WITH(NOLOCK) ON  SEA.SEQ_ID = CEA.SRM_ENTITY_ATTRIBUTES_SEQ_ID
WHERE SRM_CLIENT_FILTER_VIEWS_SEQ_ID = @FilterViewId


SELECT  ATTRIBUTE_API_CAPTION ApiCaption,
B.SYSTEM_NAME SystemName
FROM SRM_ENTITIES A, SRM_ENTITY_ATTRIBUTES B, SRM_CLIENT_ENTITIES C, SRM_CLIENT_ENTITY_ATTRIBUTES D
WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID 
AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
AND SRM_CLIENT_ENTITIES_SEQ_ID = @ClientEntityId AND B.SYSTEM_NAME LIKE 'ATTRIBUTE_%'

END






;


	CREATE PROCEDURE dbo.sp_alterdiagram
	(
		@diagramname 	sysname,
		@owner_id	int	= null,
		@version 	int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId 			int
		declare @retval 		int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @ShouldChangeUID	int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid ARG', 16, 1)
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();	 
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		revert;
	
		select @ShouldChangeUID = 0
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		
		if(@DiagId IS NULL or (@IsDbo = 0 and @theId <> @UIDFound))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end
	
		if(@IsDbo <> 0)
		begin
			if(@UIDFound is null or USER_NAME(@UIDFound) is null) -- invalid principal_id
			begin
				select @ShouldChangeUID = 1 ;
			end
		end

		-- update dds data			
		update dbo.sysdiagrams set definition = @definition where diagram_id = @DiagId ;

		-- change owner
		if(@ShouldChangeUID = 1)
			update dbo.sysdiagrams set principal_id = @theId where diagram_id = @DiagId ;

		-- update dds version
		if(@version is not null)
			update dbo.sysdiagrams set version = @version where diagram_id = @DiagId ;

		return 0
	END
;

exec sp_addextendedproperty 'microsoft_database_tools_support', 1, 'SCHEMA', 'dbo', 'PROCEDURE', 'sp_alterdiagram';

deny execute on sp_alterdiagram to guest;

grant execute on sp_alterdiagram to [public];


	CREATE PROCEDURE dbo.sp_creatediagram
	(
		@diagramname 	sysname,
		@owner_id		int	= null, 	
		@version 		int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId int
		declare @retval int
		declare @IsDbo	int
		declare @userName sysname
		if(@version is null or @diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID(); 
		select @IsDbo = IS_MEMBER(N'db_owner');
		revert; 
		
		if @owner_id is null
		begin
			select @owner_id = @theId;
		end
		else
		begin
			if @theId <> @owner_id
			begin
				if @IsDbo = 0
				begin
					RAISERROR (N'E_INVALIDARG', 16, 1);
					return -1
				end
				select @theId = @owner_id
			end
		end
		-- next 2 line only for test, will be removed after define name unique
		if EXISTS(select diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @diagramname)
		begin
			RAISERROR ('The name is already used.', 16, 1);
			return -2
		end
	
		insert into dbo.sysdiagrams(name, principal_id , version, definition)
				VALUES(@diagramname, @theId, @version, @definition) ;
		
		select @retval = @@IDENTITY 
		return @retval
	END
;

exec sp_addextendedproperty 'microsoft_database_tools_support', 1, 'SCHEMA', 'dbo', 'PROCEDURE', 'sp_creatediagram';

deny execute on sp_creatediagram to guest;

grant execute on sp_creatediagram to [public];


	CREATE PROCEDURE dbo.sp_dropdiagram
	(
		@diagramname 	sysname,
		@owner_id	int	= null
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
		declare @theId 			int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid value', 16, 1);
			return -1
		end
	
		EXECUTE AS CALLER;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		REVERT; 
		
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
			return -3
		end
	
		delete from dbo.sysdiagrams where diagram_id = @DiagId;
	
		return 0;
	END
;

exec sp_addextendedproperty 'microsoft_database_tools_support', 1, 'SCHEMA', 'dbo', 'PROCEDURE', 'sp_dropdiagram';

deny execute on sp_dropdiagram to guest;

grant execute on sp_dropdiagram to [public];


	CREATE PROCEDURE dbo.sp_helpdiagramdefinition
	(
		@diagramname 	sysname,
		@owner_id	int	= null 		
	)
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		set nocount on

		declare @theId 		int
		declare @IsDbo 		int
		declare @DiagId		int
		declare @UIDFound	int
	
		if(@diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner');
		if(@owner_id is null)
			select @owner_id = @theId;
		revert; 
	
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname;
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId ))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end

		select version, definition FROM dbo.sysdiagrams where diagram_id = @DiagId ; 
		return 0
	END
;

exec sp_addextendedproperty 'microsoft_database_tools_support', 1, 'SCHEMA', 'dbo', 'PROCEDURE', 'sp_helpdiagramdefinition';

deny execute on sp_helpdiagramdefinition to guest;

grant execute on sp_helpdiagramdefinition to [public];


	CREATE PROCEDURE dbo.sp_helpdiagrams
	(
		@diagramname sysname = NULL,
		@owner_id int = NULL
	)
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		DECLARE @user sysname
		DECLARE @dboLogin bit
		EXECUTE AS CALLER;
			SET @user = USER_NAME();
			SET @dboLogin = CONVERT(bit,IS_MEMBER('db_owner'));
		REVERT;
		SELECT
			[Database] = DB_NAME(),
			[Name] = name,
			[ID] = diagram_id,
			[Owner] = USER_NAME(principal_id),
			[OwnerID] = principal_id
		FROM
			sysdiagrams
		WHERE
			(@dboLogin = 1 OR USER_NAME(principal_id) = @user) AND
			(@diagramname IS NULL OR name = @diagramname) AND
			(@owner_id IS NULL OR principal_id = @owner_id)
		ORDER BY
			4, 5, 1
	END
;

exec sp_addextendedproperty 'microsoft_database_tools_support', 1, 'SCHEMA', 'dbo', 'PROCEDURE', 'sp_helpdiagrams';

deny execute on sp_helpdiagrams to guest;

grant execute on sp_helpdiagrams to [public];


	CREATE PROCEDURE dbo.sp_renamediagram
	(
		@diagramname 		sysname,
		@owner_id		int	= null,
		@new_diagramname	sysname
	
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
		declare @theId 			int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @DiagIdTarg		int
		declare @u_name			sysname
		if((@diagramname is null) or (@new_diagramname is null))
		begin
			RAISERROR ('Invalid value', 16, 1);
			return -1
		end
	
		EXECUTE AS CALLER;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		REVERT;
	
		select @u_name = USER_NAME(@owner_id)
	
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
			return -3
		end
	
		-- if((@u_name is not null) and (@new_diagramname = @diagramname))	-- nothing will change
		--	return 0;
	
		if(@u_name is null)
			select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @new_diagramname
		else
			select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @owner_id and name = @new_diagramname
	
		if((@DiagIdTarg is not null) and  @DiagId <> @DiagIdTarg)
		begin
			RAISERROR ('The name is already used.', 16, 1);
			return -2
		end		
	
		if(@u_name is null)
			update dbo.sysdiagrams set [name] = @new_diagramname, principal_id = @theId where diagram_id = @DiagId
		else
			update dbo.sysdiagrams set [name] = @new_diagramname where diagram_id = @DiagId
		return 0
	END
;

exec sp_addextendedproperty 'microsoft_database_tools_support', 1, 'SCHEMA', 'dbo', 'PROCEDURE', 'sp_renamediagram';

deny execute on sp_renamediagram to guest;

grant execute on sp_renamediagram to [public];


	CREATE PROCEDURE dbo.sp_upgraddiagrams
	AS
	BEGIN
		IF OBJECT_ID(N'dbo.sysdiagrams') IS NOT NULL
			return 0;
	
		CREATE TABLE dbo.sysdiagrams
		(
			name sysname NOT NULL,
			principal_id int NOT NULL,	-- we may change it to varbinary(85)
			diagram_id int PRIMARY KEY IDENTITY,
			version int,
	
			definition varbinary(max)
			CONSTRAINT UK_principal_name UNIQUE
			(
				principal_id,
				name
			)
		);


		/* Add this if we need to have some form of extended properties for diagrams */
		/*
		IF OBJECT_ID(N'dbo.sysdiagram_properties') IS NULL
		BEGIN
			CREATE TABLE dbo.sysdiagram_properties
			(
				diagram_id int,
				name sysname,
				value varbinary(max) NOT NULL
			)
		END
		*/

		IF OBJECT_ID(N'dbo.dtproperties') IS NOT NULL
		begin
			insert into dbo.sysdiagrams
			(
				[name],
				[principal_id],
				[version],
				[definition]
			)
			select	 
				convert(sysname, dgnm.[uvalue]),
				DATABASE_PRINCIPAL_ID(N'dbo'),			-- will change to the sid of sa
				0,							-- zero for old format, dgdef.[version],
				dgdef.[lvalue]
			from dbo.[dtproperties] dgnm
				inner join dbo.[dtproperties] dggd on dggd.[property] = 'DtgSchemaGUID' and dggd.[objectid] = dgnm.[objectid]	
				inner join dbo.[dtproperties] dgdef on dgdef.[property] = 'DtgSchemaDATA' and dgdef.[objectid] = dgnm.[objectid]
				
			where dgnm.[property] = 'DtgSchemaNAME' and dggd.[uvalue] like N'_EA3E6268-D998-11CE-9454-00AA00A3F36E_' 
			return 2;
		end
		return 1;
	END
;

exec sp_addextendedproperty 'microsoft_database_tools_support', 1, 'SCHEMA', 'dbo', 'PROCEDURE', 'sp_upgraddiagrams';





