CREATE PROCEDURE [dbo].[xGET_POPULATE_EVENT_LISTING] 
	 @m_CLIENT_SEQ_ID BIGINT,
	 @m_CUS_ENTITY_DATA_SEQ_ID BIGINT,
	 @ERROR SMALLINT = NULL OUTPUT,
	 @ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
 AS 
 BEGIN
  
	SET NOCOUNT ON;
	
	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @DEL_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @NEW_SEQ_ID BIGINT
	DECLARE @SRM_ENTITY_NAME NVARCHAR(200)
	DECLARE @SOURCE_SRM_ENTITY_NAME NVARCHAR(200)
	DECLARE @EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @MEM_LEDGER_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @ATTACHMENT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	DECLARE @SIMILAR_EVENT_SRM_CLIENT_ENTITIES_SEQ_ID BIGINT
	
	DECLARE @EVENT_NAME NVARCHAR(200)
	DECLARE @INTRODUCTION NVARCHAR(100)
	DECLARE @VENUE_ADDRESS_1 NVARCHAR(100)
	DECLARE @VENUE_ADDRESS_2 NVARCHAR(100)
	DECLARE @VENUE_ADDRESS_3 NVARCHAR(100)
	DECLARE @VENUE_ADDRESS_4 NVARCHAR(100)
	DECLARE @VENUE_POSTCODE NVARCHAR(100)
	DECLARE @VENUE_COUNTY NVARCHAR(100)
	DECLARE @VENUE_COUNTRY NVARCHAR(100)
	DECLARE @START_TIME NVARCHAR(100)
	DECLARE @END_TIME NVARCHAR(100)
	DECLARE @INFORMATION_ABOUT_THE_EVENT NVARCHAR(100)
	DECLARE @CONTACT_EMAIL NVARCHAR(100)
	DECLARE @CONTACT_TELEPHONE NVARCHAR(100)
	DECLARE @START_DATE NVARCHAR(100)
	DECLARE @TOTAL_SPACE NVARCHAR(100)
	DECLARE @AVAILABLE_SPACE NVARCHAR(100)
	DECLARE @EVENT_ID NVARCHAR(100)
	DECLARE @MEM_RATE NVARCHAR(100)
	DECLARE @NON_MEM_RATE NVARCHAR(100)
	DECLARE @PRIMARY NVARCHAR(200)
	DECLARE @SECONDARY NVARCHAR(200)
	DECLARE @SEN NVARCHAR(200)
	DECLARE @LOCAL_BRANCHES NVARCHAR(200)
	DECLARE @WORK_GROUP NVARCHAR(200)
	DECLARE @EVENTS NVARCHAR(200)
	DECLARE @CONSUTANTS NVARCHAR(200)
	DECLARE @CURRICULUM NVARCHAR(200)
	DECLARE @SEARCH NVARCHAR(200)
	DECLARE @HEALTHSAFETY NVARCHAR(200)
	DECLARE @REGISTRATION_TIME NVARCHAR(200)
	DECLARE @PRE_READINGS NVARCHAR(500)
	DECLARE @ASSOCITED_PRODUCTS NVARCHAR(500)
	DECLARE @ACCREDITION_POINTS NVARCHAR(500)
	DECLARE @BOOKING_DEADLINE NVARCHAR(500)
	DECLARE @PRESENTER_INFO NVARCHAR(500)
	DECLARE @PRESENTER_NAME NVARCHAR(500)
	DECLARE @SIMILAR_EVENT_IDS NVARCHAR(500)
	
	
	DECLARE @IMAGE_URL NVARCHAR(200)
	DECLARE @MEM_NET_AMOUNT NVARCHAR(200)
	DECLARE @MEM_VAT_AMOUNT NVARCHAR(200)
	DECLARE @MEM_GROSS_AMOUNT NVARCHAR(200)
	DECLARE @NON_MEM_NET_AMOUNT NVARCHAR(200)
	DECLARE @NON_MEM_VAT_AMOUNT NVARCHAR(200)
	DECLARE @NON_MEM_GROSS_AMOUNT NVARCHAR(200)
	DECLARE @MEM_VAT_INCLUSIVE NVARCHAR(200)
	DECLARE @NON_VAT_INCLUSIVE NVARCHAR(200)
	
	DECLARE @MEM_VAT_RATE NVARCHAR(200)
	DECLARE @NON_VAT_RATE NVARCHAR(200)
	DECLARE @DATEMODIFIED DATETIME
	DECLARE @MODIFIEDBY NVARCHAR(200)
	DECLARE @DATECREATED DATETIME
	DECLARE @CREATEDBY NVARCHAR(200)

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_POPULATE_EVENT_LISTING]'

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'WEB_SERVICE_EVENT_LISTING'

	SELECT @SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SOURCE_SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT'

	SELECT @CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'CONTACT'
	
	SELECT @ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'ACCOUNT'

	SELECT @DEL_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'DELEGATE_TYPE'


	SELECT @EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT_RATE'

	SELECT @ATTACHMENT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'ATTACHMENT'
	
	SELECT @PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'EVENT_ASSOCIATED_PRODUCT'

	SELECT @SIMILAR_EVENT_SRM_CLIENT_ENTITIES_SEQ_ID= C.SEQ_ID ,@SRM_ENTITY_NAME=C.ENTITY_DISPLAY_NAME 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITIES A, [SRM-FRAMEWORK_NEW].DBO.SRM_ENTITY_ATTRIBUTES B,[SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES C, [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITY_ATTRIBUTES D
	WHERE A.SEQ_ID = B.SRM_ENTITIES_SEQ_ID AND A.SEQ_ID = C.SRM_ENTITIES_SEQ_ID AND C.SEQ_ID = D.SRM_CLIENT_ENTITIES_SEQ_ID
	AND B.SEQ_ID = D.SRM_ENTITY_ATTRIBUTES_SEQ_ID
	AND C.SRM_CLIENTS_SEQ_ID = @M_CLIENT_SEQ_ID AND C.ENTITY_DISPLAY_NAME LIKE 'SIMILAR_EVENT'



	DECLARE CUR_RECORDS CURSOR LOCAL STATIC  FOR 
		SELECT  
			EVE.ATTRIBUTE_001 AS EVENT_NAME,
			EVE.ATTRIBUTE_048 AS INTRODUCTION,
			VENUE.ATTRIBUTE_024 AS VENUE_ADDRESS_1,
			VENUE.ATTRIBUTE_025 AS VENUE_ADDRESS_2,
			VENUE.ATTRIBUTE_026 AS VENUE_ADDRESS_3,
			VENUE.ATTRIBUTE_105 AS VENUE_ADDRESS_4,
			VENUE.ATTRIBUTE_028 AS VENUE_POSTCODE,
			VENUE.ATTRIBUTE_030 AS VENUE_COUNTY,
			VENUE.ATTRIBUTE_032 AS VENUE_COUNTRY,
			EVE.ATTRIBUTE_028 AS [START_TIME],
			EVE.ATTRIBUTE_029 AS [END_TIME],
			EVE.ATTRIBUTE_052 AS INFORMATION_ABOUT_THE_EVENT,
			EVE_CONTACT.ATTRIBUTE_056 AS CONTACT_EMAIL,
			EVE_CONTACT.ATTRIBUTE_054 AS CONTACT_TELEPHONE,
			CONVERT(NVARCHAR, EVE.ATTRIBUTE_004,121)  AS [START_DATE],
			EVE.ATTRIBUTE_030 AS TOTAL_SPACE,
			EVE.ATTRIBUTE_034 AS AVAILABLE_SPACE,
			--EVE.ATTRIBUTE_034 AS AVAILABLE_SPACE,
			EVE.ATTRIBUTE_002 AS EVENT_ID,
			EVE.ATTRIBUTE_054 AS [PRIMARY],
			EVE.ATTRIBUTE_055 AS SECONDARY,
			EVE.ATTRIBUTE_056 AS SEN,
			EVE.ATTRIBUTE_057 AS LOCAL_BRANCHES,
			EVE.ATTRIBUTE_058 AS WORK_GROUP,
			EVE.ATTRIBUTE_059 AS [EVENTS],
			EVE.ATTRIBUTE_060 AS CONSUTANTS,
			EVE.ATTRIBUTE_061 AS CURRICULUM ,
			EVE.ATTRIBUTE_062 AS SEARCH ,
			EVE.ATTRIBUTE_063 AS HEALTH_AND_SAFETY,
			EVE.ATTRIBUTE_064 AS REGISTRATION_TIME,
			EVE.ATTRIBUTE_069 AS ACCREDITION,
			EVE.ATTRIBUTE_068 AS BOOKING_DEADLINE,
			EVE.ATTRIBUTE_067 AS PRESENTER_INFO,
			EVE.ATTRIBUTE_065 AS PRESENTER_NAME,
			EVE.DATE_CREATED,EVE.CREATED_BY,EVE.DATE_MODIFIED,EVE.MODIFIED_BY


		FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVE
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA VENUE ON CAST(VENUE.SEQ_ID AS VARCHAR)=EVE.ATTRIBUTE_020 AND VENUE.SRM_CLIENT_ENTITIES_SEQ_ID=@ACCOUNT_SRM_CLIENT_ENTITIES_SEQ_ID--ACCOUNT
		LEFT OUTER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVE_CONTACT ON CAST(EVE_CONTACT.SEQ_ID AS VARCHAR)=EVE.ATTRIBUTE_042 AND EVE_CONTACT.SRM_CLIENT_ENTITIES_SEQ_ID=@CONTACT_SRM_CLIENT_ENTITIES_SEQ_ID--CONTACT
		WHERE 
		EVE.SEQ_ID=@m_CUS_ENTITY_DATA_SEQ_ID AND 
		 EVE.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID	
		OPEN CUR_RECORDS
	FETCH NEXT FROM CUR_RECORDS INTO   @EVENT_NAME,@INTRODUCTION,@VENUE_ADDRESS_1,@VENUE_ADDRESS_2,@VENUE_ADDRESS_3,@VENUE_ADDRESS_4,@VENUE_POSTCODE,
										@VENUE_COUNTY,@VENUE_COUNTRY,@START_TIME,@END_TIME,@INFORMATION_ABOUT_THE_EVENT,@CONTACT_EMAIL,@CONTACT_TELEPHONE,
										@START_DATE,@TOTAL_SPACE,@AVAILABLE_SPACE,@EVENT_ID,@PRIMARY,@SECONDARY,@SEN,@LOCAL_BRANCHES,
										@WORK_GROUP,@EVENTS,@CONSUTANTS,@CURRICULUM,@SEARCH,@HEALTHSAFETY,@REGISTRATION_TIME,@ACCREDITION_POINTS,@BOOKING_DEADLINE,@PRESENTER_INFO,@PRESENTER_NAME,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY 
	WHILE @@FETCH_STATUS = 0
	BEGIN
	
		
		--GETING SIMILAR EVENTS
		SET @SIMILAR_EVENT_IDS =(SELECT TOP 1 STUFF((SELECT ',' + E.ATTRIBUTE_002 FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA SIM_EVE INNER JOIN  [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA E ON CAST(E.SEQ_ID AS VARCHAR)=SIM_EVE.ATTRIBUTE_004 AND E.SRM_CLIENT_ENTITIES_SEQ_ID=@SOURCE_SRM_CLIENT_ENTITIES_SEQ_ID  WHERE ISNULL(SIM_EVE.DELETED,'N')='N'  AND   SIM_EVE.SRM_CLIENT_ENTITIES_SEQ_ID=@SIMILAR_EVENT_SRM_CLIENT_ENTITIES_SEQ_ID AND SIM_EVE.ATTRIBUTE_002=CAST(@m_CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR )FOR XML PATH('')),1,1,''))
		--GET PRE READINGS AND ASSOCIATED PRODUCTS 
		SET @PRE_READINGS = (SELECT TOP 1 STUFF((SELECT ',' + PRE_READINGS.ATTRIBUTE_003 FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA PRE_READINGS WHERE ISNULL(PRE_READINGS.DELETED,'N')='N' AND PRE_READINGS.ATTRIBUTE_005='Y' AND   PRE_READINGS.SRM_CLIENT_ENTITIES_SEQ_ID=@PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID AND PRE_READINGS.ATTRIBUTE_006=CAST(@m_CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR )FOR XML PATH('')),1,1,''))
		SET @ASSOCITED_PRODUCTS = (SELECT TOP 1 STUFF((SELECT ',' + PRE_READINGS.ATTRIBUTE_003 FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA PRE_READINGS WHERE ISNULL(PRE_READINGS.DELETED,'N')='N' AND PRE_READINGS.ATTRIBUTE_004='Y' AND   PRE_READINGS.SRM_CLIENT_ENTITIES_SEQ_ID=@PRE_READINGS_SRM_CLIENT_ENTITIES_SEQ_ID AND PRE_READINGS.ATTRIBUTE_006=CAST(@m_CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR )FOR XML PATH('')),1,1,''))
		
		--GET ATTACHMENT
		SELECT TOP 1  @IMAGE_URL=ATTRIBUTE_002 from [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA ATTACHMENT where ISNULL(ATTACHMENT.DELETED,'N')='N' AND ATTACHMENT.SRM_CLIENT_ENTITIES_SEQ_ID=@ATTACHMENT_SRM_CLIENT_ENTITIES_SEQ_ID and ATTACHMENT.ATTRIBUTE_499=CAST(@m_CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR)
		
		--GETTING MEM RATE
		SELECT TOP 1 @MEM_RATE = ISNULL(EVNT_RATE.ATTRIBUTE_008,'0'),@MEM_VAT_RATE=ISNULL(EVNT_RATE.ATTRIBUTE_015,'0'),@MEM_VAT_INCLUSIVE=EVNT_RATE.ATTRIBUTE_010  FROM
		[SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVNT_RATE 
		INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA DELEGATE_TYPE ON CAST(DELEGATE_TYPE.SEQ_ID AS VARCHAR)=EVNT_RATE.ATTRIBUTE_006 AND DELEGATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID=@DEL_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID AND DELEGATE_TYPE.ATTRIBUTE_009='MEM'
		WHERE EVNT_RATE.ATTRIBUTE_002 = CAST(@m_CUS_ENTITY_DATA_SEQ_ID AS VARCHAR )  AND EVNT_RATE.SRM_CLIENT_ENTITIES_SEQ_ID=@EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID
		
		IF(@MEM_VAT_INCLUSIVE='Y')
		BEGIN
			--Net=(Gross*100)/(100+vat rate)
			SET @MEM_NET_AMOUNT = (CAST(@MEM_RATE AS MONEY)*100.00)/(100.00+ CAST(@MEM_VAT_RATE AS MONEY))
			SET @MEM_GROSS_AMOUNT = @MEM_RATE
			SET @MEM_VAT_AMOUNT = CAST(@MEM_GROSS_AMOUNT AS MONEY)-CAST(@MEM_NET_AMOUNT AS MONEY)
		END
		ELSE
		BEGIN
			SET @MEM_NET_AMOUNT = @MEM_RATE
			--gross=net((100+vat rate)/100)
			SET @MEM_GROSS_AMOUNT = CAST(@MEM_NET_AMOUNT AS MONEY)*((100 + CAST(@MEM_VAT_RATE AS MONEY))/100.00)
			SET @MEM_VAT_AMOUNT = CAST(@MEM_GROSS_AMOUNT AS MONEY)-CAST(@MEM_NET_AMOUNT AS MONEY)
		END

		--GETTING NON MEM RATE
		SELECT TOP 1 @NON_MEM_RATE = ISNULL(EVNT_RATE.ATTRIBUTE_008,'0'),@NON_VAT_RATE=ISNULL(EVNT_RATE.ATTRIBUTE_015,'0') ,@NON_VAT_INCLUSIVE=EVNT_RATE.ATTRIBUTE_010 FROM
		[SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA EVNT_RATE 
		INNER JOIN [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA DELEGATE_TYPE ON CAST(DELEGATE_TYPE.SEQ_ID AS VARCHAR)=EVNT_RATE.ATTRIBUTE_006 AND DELEGATE_TYPE.SRM_CLIENT_ENTITIES_SEQ_ID=@DEL_TYPE_SRM_CLIENT_ENTITIES_SEQ_ID AND DELEGATE_TYPE.ATTRIBUTE_009='NON'
		WHERE EVNT_RATE.ATTRIBUTE_002 = CAST(@m_CUS_ENTITY_DATA_SEQ_ID AS VARCHAR )  AND EVNT_RATE.SRM_CLIENT_ENTITIES_SEQ_ID=@EVENT_RATE_SRM_CLIENT_ENTITIES_SEQ_ID
		
		IF(@NON_VAT_INCLUSIVE='Y')
		BEGIN
			--Net=(Gross*100)/(100+vat rate)
			SET @NON_MEM_NET_AMOUNT = (CAST(@NON_MEM_RATE AS MONEY)*100.00)/(100.00+ CAST(@NON_VAT_RATE AS MONEY))
			SET @NON_MEM_GROSS_AMOUNT = @NON_MEM_RATE
			SET @NON_MEM_VAT_AMOUNT = CAST(@NON_MEM_GROSS_AMOUNT AS MONEY)-CAST(@NON_MEM_NET_AMOUNT AS MONEY)
		END
		ELSE
		BEGIN
			SET @NON_MEM_NET_AMOUNT = @NON_MEM_RATE
			--gross=net((100+vat rate)/100)
			SET @NON_MEM_GROSS_AMOUNT = CAST(@NON_MEM_NET_AMOUNT AS MONEY)*((100 + CAST(@NON_VAT_RATE AS MONEY))/100.00)
			SET @NON_MEM_VAT_AMOUNT = CAST(@NON_MEM_GROSS_AMOUNT AS MONEY)-CAST(@NON_MEM_NET_AMOUNT AS MONEY)
		END


		--DELETE IF ALREADY EXITS MEMBER DATA
		IF (EXISTS(SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_001=@EVENT_NAME AND SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID))
		BEGIN
			DELETE FROM [SRM-DataPivot].DBO.[CUS_PIVOT_NON_UNIQUE_INDEXES] WHERE CUS_ENTITY_DATA_SEQ_ID IN (SELECT SEQ_ID FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_001=@EVENT_NAME  AND SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID)
			DELETE FROM [SRM-CUSTOMENTITIES].DBO.CUS_ENTITY_DATA WHERE ATTRIBUTE_001=@EVENT_NAME  AND SRM_CLIENT_ENTITIES_SEQ_ID= @SRM_CLIENT_ENTITIES_SEQ_ID
		END
		--SYNCH MEMBERSHIP RECORD
		EXEC  [DBO].[GET_INSERT_CUS_ENTITY_DATA]
		@SRM_CLIENT_ENTITIES_SEQ_ID=@SRM_CLIENT_ENTITIES_SEQ_ID,
		@ATTRIBUTE_001=@EVENT_NAME,
		@ATTRIBUTE_002=@INTRODUCTION,
		@ATTRIBUTE_003=@VENUE_ADDRESS_1,
		@ATTRIBUTE_004=@VENUE_ADDRESS_2,
		@ATTRIBUTE_005=@VENUE_ADDRESS_3,
		@ATTRIBUTE_006=@VENUE_ADDRESS_4,
		@ATTRIBUTE_008=@VENUE_POSTCODE,
		@ATTRIBUTE_009=@VENUE_COUNTY,
		@ATTRIBUTE_011=@START_TIME,
		@ATTRIBUTE_012=@END_TIME,
		@ATTRIBUTE_013=@INFORMATION_ABOUT_THE_EVENT,
		@ATTRIBUTE_015=@CONTACT_EMAIL,
		@ATTRIBUTE_016=@CONTACT_TELEPHONE,
		@ATTRIBUTE_020=@START_DATE,
		@ATTRIBUTE_022=@TOTAL_SPACE,
		@ATTRIBUTE_023=@AVAILABLE_SPACE,
		@ATTRIBUTE_028=@EVENT_ID,
		@ATTRIBUTE_031=@MEM_NET_AMOUNT,
		@ATTRIBUTE_032=@MEM_VAT_AMOUNT,
		@ATTRIBUTE_029=@MEM_GROSS_AMOUNT,
		@ATTRIBUTE_033=@NON_MEM_NET_AMOUNT,
		@ATTRIBUTE_034=@NON_MEM_VAT_AMOUNT,
		@ATTRIBUTE_030=@NON_MEM_GROSS_AMOUNT,
		@ATTRIBUTE_037=@PRIMARY,
		@ATTRIBUTE_038=@SECONDARY,
		@ATTRIBUTE_039=@SEN,
		@ATTRIBUTE_040=@LOCAL_BRANCHES,
		@ATTRIBUTE_041=@WORK_GROUP,
		@ATTRIBUTE_042=@EVENTS,
		@ATTRIBUTE_043=@CONSUTANTS,
		@ATTRIBUTE_044=@CURRICULUM,
		@ATTRIBUTE_045=@SEARCH,
		@ATTRIBUTE_046=@HEALTHSAFETY,
		@ATTRIBUTE_010=@REGISTRATION_TIME,
		@ATTRIBUTE_035=@IMAGE_URL,
		@ATTRIBUTE_017=@PRE_READINGS,
		@ATTRIBUTE_036=@ASSOCITED_PRODUCTS,
		@ATTRIBUTE_026=@ACCREDITION_POINTS,
		@ATTRIBUTE_021=@BOOKING_DEADLINE,
		@ATTRIBUTE_018=@PRESENTER_INFO,
		@ATTRIBUTE_019=@PRESENTER_NAME,
		@ATTRIBUTE_027=@SIMILAR_EVENT_IDS,
		@SRM_CLIENTS_SEQ_ID=@M_CLIENT_SEQ_ID,
		@DATE_CREATED=@DATECREATED,
		@CREATED_BY=@CREATEDBY,
		@DATE_MODIFIED=@DATEMODIFIED,
		@MODIFIED_BY=@MODIFIEDBY,
		@RETURN_SEQ_ID=@NEW_SEQ_ID OUTPUT,
		@ERROR=@ERROR OUTPUT,
		@ERROR_DESCRIPTION=@ERROR_DESCRIPTION OUTPUT
					
	FETCH NEXT FROM CUR_RECORDS INTO    @EVENT_NAME,@INTRODUCTION,@VENUE_ADDRESS_1,@VENUE_ADDRESS_2,@VENUE_ADDRESS_3,@VENUE_ADDRESS_4,@VENUE_POSTCODE,
										@VENUE_COUNTY,@VENUE_COUNTRY,@START_TIME,@END_TIME,@INFORMATION_ABOUT_THE_EVENT,@CONTACT_EMAIL,@CONTACT_TELEPHONE,
										@START_DATE,@TOTAL_SPACE,@AVAILABLE_SPACE,@EVENT_ID,@PRIMARY,@SECONDARY,@SEN,@LOCAL_BRANCHES,
										@WORK_GROUP,@EVENTS,@CONSUTANTS,@CURRICULUM,@SEARCH,@HEALTHSAFETY,@REGISTRATION_TIME,@ACCREDITION_POINTS,@BOOKING_DEADLINE,@PRESENTER_INFO,@PRESENTER_NAME,@DATECREATED, @CREATEDBY , @DATEMODIFIED , @MODIFIEDBY 
	
	END

	CLOSE CUR_RECORDS
	DEALLOCATE CUR_RECORDS
	
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END


;





-- =============================================
-- Author:		<Rauf Gill>
-- Modifications By:		<Sohail Raza>
-- Create date: <08/08/2013,,>
-- Description:	<Apply Product Sales Data to sTarget,,>
-- =============================================
CREATE PROCEDURE [dbo].[x_GET_APPLY_MEMBERSHIP_MEMBERS_DATA_TO_API]
	-- Add the parameters for the stored procedure here
	@SRM_CLIENTS_SEQ_ID BIGINT = NULL,
	@ERROR SMALLINT = NULL OUTPUT,
	@ERROR_DESCRIPTION NVARCHAR(200) = NULL OUTPUT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SET @ERROR = 1
	SET @ERROR_DESCRIPTION = 'ERROR IN [dbo].[GET_APPLY_MEMBERSHIP_MEMBERS_DATA_TO_API]'

	DECLARE @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER  BIGINT
	DECLARE @CUS_ENTITY_DATA_SEQ_ID BIGINT

	SELECT @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER = SEQ_ID 
	FROM [SRM-FRAMEWORK_NEW].DBO.SRM_CLIENT_ENTITIES
	WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND ENTITY_DISPLAY_NAME LIKE 'MEMBER'

	DECLARE CUR_MEMBERS CURSOR LOCAL STATIC FOR
		SELECT SEQ_ID FROM [SRM-CustomEntities].DBO.CUS_ENTITY_DATA WHERE SRM_CLIENTS_SEQ_ID = @SRM_CLIENTS_SEQ_ID AND SRM_CLIENT_ENTITIES_SEQ_ID = @SRM_CLIENT_ENTITIES_SEQ_ID_MEMBER -- AND ISNULL(ATTRIBUTE_031, 'N')  ='N'
		AND DATE_MODIFIED BETWEEN '2014-02-03' AND '2014-02-07' AND SEQ_ID >= 4156036
	-- Only get those where 'Membership Pay By' is null. case handled in [GET_POPULATE_MEMBERSHIP]	
	-- RG_2013102 Commented following line as system does not sync. data if record if pay by member is saved.
	 --AND ATTRIBUTE_029 IS NULL

	OPEN CUR_MEMBERS
	FETCH NEXT FROM CUR_MEMBERS INTO @CUS_ENTITY_DATA_SEQ_ID
	WHILE @@FETCH_STATUS = 0 
	BEGIN
		PRINT 'PROCESSING MEMBER CUS_ENTITY_DATA_SEQ_ID = ' +  CAST(@CUS_ENTITY_DATA_SEQ_ID AS NVARCHAR(20))

		
		EXEC [dbo].[GET_POPULATE_MEMBERSHIP] 
			@CLIENT_SEQ_ID = @SRM_CLIENTS_SEQ_ID,
			@CUS_ENTITY_DATA_SEQ_ID = @CUS_ENTITY_DATA_SEQ_ID,
			@ERROR = @ERROR OUTPUT,
			@ERROR_DESCRIPTION = @ERROR_DESCRIPTION OUTPUT
		
		FETCH NEXT FROM CUR_MEMBERS INTO @CUS_ENTITY_DATA_SEQ_ID
	END
	CLOSE CUR_MEMBERS
	DEALLOCATE CUR_MEMBERS


					
	SET @ERROR = 0
	SET @ERROR_DESCRIPTION = ''
END





;



/****** Object:  Rule [dbo].[R_SYSTEM_MODULE]    Script Date: 01/12/2016 15:43:27 ******/
CREATE RULE [dbo].[R_SYSTEM_MODULE] 
AS
@column is null or ( @column in ('MEM','CRM','EV','PS','FR','COMMON') )

;

